import { type CSSProperties, type ReactNode, useEffect, useRef } from "react";

export type AgentActivity = {
  id: string;
  /** Wall-clock timestamp; component formats it. */
  at: number;
  /** "tool" for MCP tool invocations, "message" for chat, "info" for status. */
  kind: "tool" | "message" | "info" | "error";
  /** Short label, e.g. "whiteboard_add_sticky" or "Agent". */
  source: string;
  /** Body text. */
  text: string;
  /** Optional structured payload, rendered as collapsed JSON. */
  detail?: unknown;

  // ── Tool-call fields. Present when `kind === "tool"`; ignored otherwise. ──
  /**
   * The call's arguments. Rendered inline next to the tool name so the feed
   * reads as `tool(args) → result` — the point being that the agent's
   * reasoning is legible AS IT HAPPENS, not reconstructable afterwards from a
   * details pane nobody opens.
   */
  args?: unknown;
  /** What the call returned. */
  result?: unknown;
  /** Round-trip time in ms. Rendered as `· 142ms`. */
  durationMs?: number;
  /**
   * Lifecycle. A row can appear as `pending` the moment a call starts and be
   * replaced by the settled row, which is what makes this a STREAM rather than
   * a log. Defaults to `ok`, or `error` when `kind === "error"`.
   */
  status?: "pending" | "ok" | "error";
};

export type AgentPanelProps = {
  /** The agent's identity (name + color appears in the header). */
  agent?: { name?: string; color?: string };
  /** Activity stream. Most recent at the end. */
  activity: AgentActivity[];
  /** Optional chat composer — pass an onSubmit to enable. */
  onSubmit?: (message: string) => void;
  /** Disabled while a request is in flight. */
  busy?: boolean;
  /** Right-rail header actions. */
  actions?: ReactNode;
  className?: string;
  style?: CSSProperties;
};

/**
 * AgentPanel — sidebar showing the agent's identity, a tool-and-chat log,
 * and an optional input composer. Pure presentational: hosts feed it the
 * activity stream from their own state (typically the MCP transport log).
 */
export function AgentPanel({ agent, activity, onSubmit, busy, actions, className, style }: AgentPanelProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    el.scrollTop = el.scrollHeight;
  }, [activity.length]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const value = inputRef.current?.value.trim();
    if (!value || !onSubmit) return;
    onSubmit(value);
    if (inputRef.current) inputRef.current.value = "";
  };

  const color = agent?.color ?? "#a855f7";
  const name = agent?.name ?? "Agent";

  return (
    <div className={["fai-panel", className ?? ""].filter(Boolean).join(" ")} style={style}>
      <header className="fai-panel__header">
        <div
          className="fai-panel__avatar"
          style={{ background: color }}
          aria-hidden
        >
          {name.slice(0, 1)}
        </div>
        <div className="fai-panel__title">
          <strong>{name}</strong>
          <span className="fai-panel__subtitle">
            {busy ? "Working…" : `${activity.length} event${activity.length === 1 ? "" : "s"}`}
          </span>
        </div>
        {actions && <div className="fai-panel__actions">{actions}</div>}
      </header>

      <div ref={scrollRef} className="fai-panel__stream">
        {activity.length === 0 ? (
          <p className="fai-panel__empty">No activity yet.</p>
        ) : (
          activity.map((a) => <ActivityRow key={a.id} item={a} />)
        )}
      </div>

      {onSubmit && (
        <form className="fai-panel__composer" onSubmit={handleSubmit}>
          <textarea
            ref={inputRef}
            className="fai-panel__input"
            placeholder={busy ? "Working…" : "Ask the agent…"}
            disabled={busy}
            rows={2}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                handleSubmit(e as unknown as React.FormEvent);
              }
            }}
          />
          <button type="submit" className="fai-panel__send" disabled={busy}>
            Send
          </button>
        </form>
      )}
    </div>
  );
}

function ActivityRow({ item }: { item: AgentActivity }) {
  const time = formatTime(item.at);
  const status = item.status ?? (item.kind === "error" ? "error" : "ok");
  const isCall = item.kind === "tool" && (item.args !== undefined || item.result !== undefined || item.durationMs !== undefined);

  return (
    <div
      className={`fai-row fai-row--${item.kind}${isCall ? ` fai-row--${status}` : ""}`}
      data-fai-row=""
      data-kind={item.kind}
      data-status={isCall ? status : undefined}
    >
      <div className="fai-row__meta">
        <span className="fai-row__source">{item.source}</span>
        {isCall && item.args !== undefined && (
          <span className="fai-row__args" data-fai-args="">
            ({inline(item.args)})
          </span>
        )}
        {isCall && item.durationMs !== undefined && (
          <span className="fai-row__latency" data-fai-latency="">
            · {item.durationMs}ms
          </span>
        )}
        <span className="fai-row__time">{time}</span>
      </div>
      {isCall && item.result !== undefined && (
        <div className="fai-row__result" data-fai-result="">
          → {inline(item.result)}
        </div>
      )}
      <div className="fai-row__text">{item.text}</div>
      {item.detail !== undefined && (
        <details className="fai-row__detail">
          <summary>details</summary>
          <pre>{safeJson(item.detail)}</pre>
        </details>
      )}
    </div>
  );
}

/**
 * One-line rendering of a call's args or result.
 *
 * Truncated hard, because a feed is scanned rather than read: an untruncated
 * result payload pushes every subsequent row off the screen, which costs more
 * than the detail is worth. The full value stays available via `detail`.
 */
function inline(v: unknown, max = 80): string {
  if (typeof v === "string") return v.length > max ? `${v.slice(0, max)}…` : v;
  const json = safeJson(v).replace(/\s+/g, " ");
  return json.length > max ? `${json.slice(0, max)}…` : json;
}

function formatTime(at: number): string {
  const d = new Date(at);
  const hh = d.getHours().toString().padStart(2, "0");
  const mm = d.getMinutes().toString().padStart(2, "0");
  const ss = d.getSeconds().toString().padStart(2, "0");
  return `${hh}:${mm}:${ss}`;
}

function safeJson(v: unknown): string {
  try {
    return JSON.stringify(v, null, 2);
  } catch {
    return String(v);
  }
}

import { Button, Input, Select } from "@particle-academy/react-fancy";
import type { AgentEntry, AgentsModel } from "../lib/model";
import { validateAgents } from "../lib/validate";
import { IssueList, Section } from "./internal";

export interface AgentsEditorProps {
  value: AgentsModel;
  onChange: (next: AgentsModel) => void;
  hideIssues?: boolean;
  className?: string;
}

/** Controlled /AGENTS register editor: per-agent allow/deny policy. */
export function AgentsEditor({
  value,
  onChange,
  hideIssues,
  className,
}: AgentsEditorProps) {
  const issues = validateAgents(value);
  const patch = (next: Partial<AgentsModel>) => onChange({ ...value, ...next });

  const updateAgent = (index: number, next: Partial<AgentEntry>) =>
    patch({
      agents: value.agents.map((a, i) =>
        i === index ? { ...a, ...next } : a,
      ),
    });

  const addAgent = () =>
    patch({ agents: [...value.agents, { id: "", policy: "allow" }] });

  const removeAgent = (index: number) =>
    patch({ agents: value.agents.filter((_, i) => i !== index) });

  return (
    <div className={className} data-x-editor="agents">
      <Section title="Policy contact" handle="agents-contact">
        <Input
          value={value.contact ?? ""}
          onValueChange={(v) => patch({ contact: v || undefined })}
          placeholder="mailto:agents@example.com"
          data-x-input="agents-contact"
        />
      </Section>

      <Section
        title="Agents"
        handle="agents-list"
        action={
          <Button
            type="button"
            variant="ghost"
            onClick={addAgent}
            data-x-add="agents-agent"
          >
            Add agent
          </Button>
        }
      >
        {value.agents.map((agent, i) => (
          <div
            key={i}
            data-x-agent={i}
            style={{
              border: "1px solid var(--rf-border, #e5e7eb)",
              borderRadius: "0.5rem",
              padding: "0.6rem",
              display: "flex",
              flexDirection: "column",
              gap: "0.4rem",
            }}
          >
            <div
              style={{
                display: "flex",
                gap: "0.4rem",
                alignItems: "end",
                flexWrap: "wrap",
              }}
            >
              <div style={{ flex: "1 1 8rem" }}>
                <Input
                  label="id"
                  value={agent.id}
                  onValueChange={(id) => updateAgent(i, { id })}
                  placeholder="gptbot"
                  data-x-input={`agents-id:${i}`}
                />
              </div>
              <div style={{ flex: "1 1 8rem" }}>
                <Input
                  label="name"
                  value={agent.name ?? ""}
                  onValueChange={(v) => updateAgent(i, { name: v || undefined })}
                  placeholder="GPTBot"
                  data-x-input={`agents-name:${i}`}
                />
              </div>
              <div style={{ flex: "0 1 7rem" }}>
                <Select
                  label="policy"
                  value={agent.policy}
                  list={["allow", "deny"]}
                  onValueChange={(v) =>
                    updateAgent(i, { policy: v as AgentEntry["policy"] })
                  }
                  data-x-input={`agents-policy:${i}`}
                />
              </div>
              <Button
                type="button"
                variant="ghost"
                color="red"
                onClick={() => removeAgent(i)}
                data-x-remove={`agents-agent:${i}`}
              >
                ×
              </Button>
            </div>
            <div style={{ display: "flex", gap: "0.4rem", flexWrap: "wrap" }}>
              <div style={{ flex: "1 1 9rem" }}>
                <Input
                  label="url"
                  value={agent.url ?? ""}
                  onValueChange={(v) => updateAgent(i, { url: v || undefined })}
                  placeholder="https://example.com/bot"
                  data-x-input={`agents-url:${i}`}
                />
              </div>
              <div style={{ flex: "2 1 12rem" }}>
                <Input
                  label="scope"
                  value={agent.scope ?? ""}
                  onValueChange={(v) =>
                    updateAgent(i, { scope: v || undefined })
                  }
                  placeholder="read-only crawl of /docs"
                  data-x-input={`agents-scope:${i}`}
                />
              </div>
            </div>
          </div>
        ))}
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="agents" />}
    </div>
  );
}

import { useState } from "react";
import { Badge, Button, Callout, Input } from "@particle-academy/react-fancy";

/**
 * Shared internal building blocks for the editors. Not exported from the
 * package root — these are implementation details of the editors.
 */

/** Surface a list of validation issues as a soft warning callout. */
export function IssueList({
  issues,
  testid,
}: {
  issues: string[];
  testid?: string;
}) {
  if (!issues.length) return null;
  return (
    <Callout color="amber" data-x-issues={testid ?? ""}>
      <ul style={{ margin: 0, paddingLeft: "1.1rem" }}>
        {issues.map((issue, i) => (
          <li key={i} data-x-issue>
            {issue}
          </li>
        ))}
      </ul>
    </Callout>
  );
}

/**
 * Controlled add/remove list of plain strings rendered as chips with an
 * inline "add a row" input. `disallowedValues` are rejected on add and, if
 * already present, flagged — used by RobotsEditor to keep protected paths out
 * of an Allow list.
 */
export function StringList({
  label,
  values,
  onChange,
  placeholder,
  handle,
  disallowedValues,
  disallowedReason,
}: {
  label?: string;
  values: string[];
  onChange: (next: string[]) => void;
  placeholder?: string;
  /** data-* handle base, e.g. "robots-allow". */
  handle: string;
  disallowedValues?: string[];
  disallowedReason?: (value: string) => string;
}) {
  const [draft, setDraft] = useState("");
  const blocked = new Set(disallowedValues ?? []);

  const add = () => {
    const v = draft.trim();
    if (!v || values.includes(v)) {
      setDraft("");
      return;
    }
    onChange([...values, v]);
    setDraft("");
  };

  const remove = (value: string) =>
    onChange(values.filter((v) => v !== value));

  return (
    <div data-x-list={handle}>
      {label ? (
        <div
          style={{ fontSize: "0.8rem", fontWeight: 600, marginBottom: "0.25rem" }}
        >
          {label}
        </div>
      ) : null}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "0.35rem",
          marginBottom: values.length ? "0.4rem" : 0,
        }}
      >
        {values.map((value) => {
          const isBlocked = blocked.has(value);
          return (
            <Badge
              key={value}
              color={isBlocked ? "red" : "slate"}
              variant={isBlocked ? "soft" : "outline"}
              data-x-chip={`${handle}:${value}`}
              title={
                isBlocked && disallowedReason
                  ? disallowedReason(value)
                  : undefined
              }
            >
              {value}
              <button
                type="button"
                onClick={() => remove(value)}
                aria-label={`Remove ${value}`}
                data-x-remove={`${handle}:${value}`}
                style={{
                  marginLeft: "0.35rem",
                  border: "none",
                  background: "transparent",
                  cursor: "pointer",
                  fontWeight: 700,
                }}
              >
                ×
              </button>
            </Badge>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: "0.4rem" }}>
        <Input
          value={draft}
          onValueChange={setDraft}
          placeholder={placeholder}
          data-x-input={`${handle}-draft`}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              add();
            }
          }}
        />
        <Button
          type="button"
          variant="ghost"
          onClick={add}
          data-x-add={handle}
        >
          Add
        </Button>
      </div>
    </div>
  );
}

/** A labelled section wrapper used to group fields inside an editor. */
export function Section({
  title,
  action,
  children,
  handle,
}: {
  title: string;
  action?: React.ReactNode;
  children: React.ReactNode;
  handle?: string;
}) {
  return (
    <section
      data-x-section={handle}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "0.5rem",
        marginBottom: "1rem",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <h4 style={{ margin: 0, fontSize: "0.9rem", fontWeight: 700 }}>
          {title}
        </h4>
        {action}
      </div>
      {children}
    </section>
  );
}

/**
 * TS model types for the well-known files modeled by `fancy-x-files`.
 *
 * These are intentionally small, standalone shapes (this package does NOT
 * import the PHP/JS port) so the editor builds + ships independently. They
 * mirror the canonical shapes emitted by the `fancy-x-files` packages.
 *
 * Every model is plain JSON: arrays of objects + primitives. That makes the
 * whole surface agent-emittable — an embedded agent can read the current
 * model, propose a new one, and hand it back through the same `onChange`
 * channel a human uses (Human+ UX contract).
 */

/** The well-known files this suite can edit + preview. */
export type XFileKind =
  | "robots"
  | "securityTxt"
  | "llmsTxt"
  | "humansTxt"
  | "sitemap"
  | "agents";

/** robots.txt — grouped crawl rules, sitemaps, host, protected paths. */
export interface RobotsGroup {
  /** `User-agent` lines for this group. `["*"]` for all. */
  userAgents: string[];
  /** `Allow:` paths. */
  allow: string[];
  /** `Disallow:` paths. */
  disallow: string[];
  /** Optional `Crawl-delay:` seconds. */
  crawlDelay?: number;
}

export interface RobotsModel {
  groups: RobotsGroup[];
  /** Absolute `Sitemap:` URLs. */
  sitemaps: string[];
  /**
   * Paths that must be Disallowed for every user-agent and may NEVER be
   * Allowed — mirrors the PHP `protect()` safety rail. The renderer pins
   * these as Disallow on every group; the editor refuses to Allow them.
   */
  protectedPaths: string[];
  /** Optional `Host:` directive. */
  host?: string;
}

/** security.txt (RFC 9116). */
export interface SecurityTxtModel {
  /** `Contact:` — one or more mailto:/https: URIs. At least one required. */
  contact: string[];
  /** `Expires:` — ISO 8601 timestamp; MUST be in the future. */
  expires: string;
  /** `Encryption:` URI. */
  encryption?: string;
  /** `Acknowledgments:` URI. */
  acknowledgments?: string;
  /** `Preferred-Languages:` comma-separated tags. */
  preferredLanguages?: string;
  /** `Canonical:` URI. */
  canonical?: string;
  /** `Policy:` URI. */
  policy?: string;
  /** `Hiring:` URI. */
  hiring?: string;
}

/** llms.txt — Markdown index of resources for LLMs. */
export interface LlmsLink {
  title: string;
  url: string;
  notes?: string;
}

export interface LlmsSection {
  name: string;
  links: LlmsLink[];
}

export interface LlmsTxtModel {
  title: string;
  /** The blockquote summary directly under the H1. */
  summary?: string;
  /** Free-form Markdown paragraph(s) of detail. */
  details?: string;
  sections: LlmsSection[];
}

/** humans.txt — credits + site colophon. */
export interface HumansTxtEntry {
  /** e.g. "Developer", "Designer". */
  role: string;
  name: string;
  /** Optional contact / handle / site. */
  contact?: string;
}

export interface HumansTxtModel {
  team: HumansTxtEntry[];
  /** "Site" section free-text (Standards, Components, Software, …). */
  site?: string;
  thanks?: string[];
}

/** sitemap.xml — a flat URL set. */
export type SitemapChangeFreq =
  | "always"
  | "hourly"
  | "daily"
  | "weekly"
  | "monthly"
  | "yearly"
  | "never";

export interface SitemapUrl {
  loc: string;
  /** ISO 8601 date. */
  lastmod?: string;
  changefreq?: SitemapChangeFreq;
  /** 0.0 – 1.0. */
  priority?: number;
}

export interface SitemapModel {
  urls: SitemapUrl[];
}

/**
 * /AGENTS — a machine-readable register of the agents allowed (or denied) to
 * act on the site, mirroring the robots-style "agent policy" idea.
 */
export interface AgentEntry {
  /** Stable identifier / handle for the agent. */
  id: string;
  /** Human label. */
  name?: string;
  /** Policy for this agent. */
  policy: "allow" | "deny";
  /** Optional homepage / contact URL. */
  url?: string;
  /** Optional one-line description of permitted scope. */
  scope?: string;
}

export interface AgentsModel {
  agents: AgentEntry[];
  /** Optional contact for policy questions. */
  contact?: string;
}

/** The aggregate value held by `XFilesManager`. */
export interface XFilesModel {
  robots?: RobotsModel;
  securityTxt?: SecurityTxtModel;
  llmsTxt?: LlmsTxtModel;
  humansTxt?: HumansTxtModel;
  sitemap?: SitemapModel;
  agents?: AgentsModel;
}

/** Map a file kind to its model type. */
export interface XFileModelMap {
  robots: RobotsModel;
  securityTxt: SecurityTxtModel;
  llmsTxt: LlmsTxtModel;
  humansTxt: HumansTxtModel;
  sitemap: SitemapModel;
  agents: AgentsModel;
}

/** Empty-but-valid starting models, handy for "add this file" affordances. */
export const emptyRobots = (): RobotsModel => ({
  groups: [{ userAgents: ["*"], allow: [], disallow: [] }],
  sitemaps: [],
  protectedPaths: [],
});

export const emptySecurityTxt = (): SecurityTxtModel => ({
  contact: [],
  expires: "",
});

export const emptyLlmsTxt = (): LlmsTxtModel => ({
  title: "",
  sections: [],
});

export const emptyHumansTxt = (): HumansTxtModel => ({ team: [] });

export const emptySitemap = (): SitemapModel => ({ urls: [] });

export const emptyAgents = (): AgentsModel => ({ agents: [] });

/** Human-readable label + on-disk filename for each kind. */
export const X_FILE_META: Record<
  XFileKind,
  { label: string; filename: string }
> = {
  robots: { label: "robots.txt", filename: "robots.txt" },
  securityTxt: { label: "security.txt", filename: ".well-known/security.txt" },
  llmsTxt: { label: "llms.txt", filename: "llms.txt" },
  humansTxt: { label: "humans.txt", filename: "humans.txt" },
  sitemap: { label: "sitemap.xml", filename: "sitemap.xml" },
  agents: { label: "AGENTS", filename: ".well-known/agents.json" },
};

/**
 * Validation helpers. Each `validate*` returns a flat `string[]` of
 * human-readable issues (empty array == valid). The editors surface these
 * inline, and an embedded agent can call them to check a proposal before
 * handing it back.
 */
import type {
  AgentsModel,
  HumansTxtModel,
  LlmsTxtModel,
  RobotsModel,
  SecurityTxtModel,
  SitemapModel,
  XFileKind,
} from "./model";

const looksLikeUrl = (s: string): boolean =>
  /^https?:\/\/\S+$/i.test(s.trim());

export function validateRobots(model: RobotsModel): string[] {
  const issues: string[] = [];
  if (!model.groups.length) {
    issues.push("At least one user-agent group is required.");
  }
  model.groups.forEach((group, i) => {
    const where = `Group ${i + 1}`;
    if (!group.userAgents.length) {
      issues.push(`${where}: needs at least one User-agent (use "*" for all).`);
    }
    // Protected paths must never be Allowed — mirrors PHP protect() safety.
    for (const path of group.allow) {
      if (model.protectedPaths.includes(path)) {
        issues.push(
          `${where}: "${path}" is a protected path and cannot be Allowed. Remove it from Allow or unprotect it.`,
        );
      }
    }
    if (group.crawlDelay != null && group.crawlDelay < 0) {
      issues.push(`${where}: Crawl-delay must be ≥ 0.`);
    }
  });
  for (const sm of model.sitemaps) {
    if (!looksLikeUrl(sm)) {
      issues.push(`Sitemap "${sm}" should be an absolute http(s) URL.`);
    }
  }
  return issues;
}

export function validateSecurityTxt(model: SecurityTxtModel): string[] {
  const issues: string[] = [];
  if (!model.contact.length || model.contact.every((c) => !c.trim())) {
    issues.push("At least one Contact is required (mailto: or https: URI).");
  }
  if (!model.expires) {
    issues.push("Expires is required.");
  } else {
    const when = new Date(model.expires);
    if (Number.isNaN(when.getTime())) {
      issues.push("Expires must be a valid date/time.");
    } else if (when.getTime() <= Date.now()) {
      issues.push("Expires must be a date in the future.");
    }
  }
  return issues;
}

export function validateLlmsTxt(model: LlmsTxtModel): string[] {
  const issues: string[] = [];
  if (!model.title.trim()) issues.push("Title is required.");
  model.sections.forEach((section, i) => {
    if (!section.name.trim()) {
      issues.push(`Section ${i + 1}: needs a name.`);
    }
    section.links.forEach((link, j) => {
      const where = `Section ${i + 1} · link ${j + 1}`;
      if (!link.title.trim()) issues.push(`${where}: needs a title.`);
      if (!looksLikeUrl(link.url)) {
        issues.push(`${where}: URL should be an absolute http(s) URL.`);
      }
    });
  });
  return issues;
}

export function validateHumansTxt(model: HumansTxtModel): string[] {
  const issues: string[] = [];
  model.team.forEach((m, i) => {
    if (!m.role.trim()) issues.push(`Team member ${i + 1}: needs a role.`);
    if (!m.name.trim()) issues.push(`Team member ${i + 1}: needs a name.`);
  });
  return issues;
}

export function validateSitemap(model: SitemapModel): string[] {
  const issues: string[] = [];
  if (!model.urls.length) issues.push("Add at least one URL.");
  model.urls.forEach((u, i) => {
    if (!looksLikeUrl(u.loc)) {
      issues.push(`URL ${i + 1}: <loc> should be an absolute http(s) URL.`);
    }
    if (u.priority != null && (u.priority < 0 || u.priority > 1)) {
      issues.push(`URL ${i + 1}: priority must be between 0.0 and 1.0.`);
    }
  });
  return issues;
}

export function validateAgents(model: AgentsModel): string[] {
  const issues: string[] = [];
  const seen = new Set<string>();
  model.agents.forEach((a, i) => {
    if (!a.id.trim()) {
      issues.push(`Agent ${i + 1}: needs an id.`);
    } else if (seen.has(a.id)) {
      issues.push(`Agent ${i + 1}: duplicate id "${a.id}".`);
    } else {
      seen.add(a.id);
    }
    if (a.url && !looksLikeUrl(a.url)) {
      issues.push(`Agent ${i + 1}: url should be an absolute http(s) URL.`);
    }
  });
  return issues;
}

/** Dispatch validation by file kind. */
export function validateModel(kind: XFileKind, model: unknown): string[] {
  switch (kind) {
    case "robots":
      return validateRobots(model as RobotsModel);
    case "securityTxt":
      return validateSecurityTxt(model as SecurityTxtModel);
    case "llmsTxt":
      return validateLlmsTxt(model as LlmsTxtModel);
    case "humansTxt":
      return validateHumansTxt(model as HumansTxtModel);
    case "sitemap":
      return validateSitemap(model as SitemapModel);
    case "agents":
      return validateAgents(model as AgentsModel);
  }
}

import { Badge, Button, Card, Heading, Select, Text } from '@particle-academy/react-fancy';
import type { ReactNode } from 'react';
import { APPLICATION_STATUS_OPTIONS, applicationStatusColor, formatPosted } from '../lib/format';
import type { ApplicationStatus, JobApplication } from '../lib/types';

export interface ApplicationListProps {
    applications: JobApplication[];
    /** Employer moving a candidate along. Omit for a read-only list. */
    onStatusChange?: (application: JobApplication, status: ApplicationStatus) => void;
    /** Candidate withdrawing their own application. */
    onWithdraw?: (application: JobApplication) => void;
    /** Show which posting each application is for. Off within one posting. */
    showPosting?: boolean;
    /** Show candidate identity. Off on the candidate's own list. */
    showCandidate?: boolean;
    busyId?: number | null;
    /**
     * The host's OWN control for a row, rendered beside the built-in actions.
     *
     * A FUNCTION rather than children, because a list needs the row to decide
     * what to render — a resume download link needs the id of the application it
     * is on, and children could only ever render the same thing on every row.
     *
     * Generic rather than a `resume` prop, for the reason `ApplyForm`'s slot is:
     * this component cannot know how a host serves a file, and the next
     * host-specific control should not need another release. Return `null` for a
     * row that has nothing — no wrapper is rendered for it.
     *
     * The first consumer could not show a resume link on EITHER side, employer or
     * candidate, because the prop set was closed. That is the gap.
     */
    rowActions?: (application: JobApplication) => ReactNode;
    emptyMessage?: string;
    className?: string;
}

/**
 * A list of applications, used from both sides: the employer reviewing
 * candidates, and the candidate tracking their own submissions.
 */
export function ApplicationList({
    applications,
    onStatusChange,
    onWithdraw,
    showPosting = true,
    showCandidate = true,
    busyId = null,
    rowActions,
    emptyMessage = 'No applications yet.',
    className,
}: ApplicationListProps) {
    if (applications.length === 0) {
        return (
            <Card
                variant="outlined"
                padding="lg"
                className={`!rounded-xl !border-secondary-200 text-center ${className ?? ''}`}
            >
                <Text color="muted">{emptyMessage}</Text>
            </Card>
        );
    }

    return (
        <div className={`grid gap-3 ${className ?? ''}`}>
            {applications.map((application) => {
                const busy = busyId === application.id;
                const submitted = formatPosted(application.submitted_at)?.replace('Posted', 'Applied');

                return (
                    <Card
                        key={application.id}
                        variant="outlined"
                        padding="lg"
                        className="!rounded-xl !border-secondary-200 !shadow-sm"
                    >
                        <div className="flex flex-wrap items-start justify-between gap-4">
                            <div className="min-w-0">
                                <Badge
                                    color={applicationStatusColor(application.status)}
                                    variant="soft"
                                    size="sm"
                                >
                                    {application.status_label}
                                </Badge>

                                {showCandidate && application.candidate && (
                                    <Heading
                                        as="h3"
                                        size="lg"
                                        weight="bold"
                                        className="!mt-2 !text-secondary-900"
                                    >
                                        {application.candidate.name ?? 'Candidate'}
                                    </Heading>
                                )}

                                {showPosting && application.job_posting && (
                                    <Text
                                        size={showCandidate ? 'sm' : 'lg'}
                                        weight={showCandidate ? undefined : 'bold'}
                                        className="!mt-1 !text-secondary-900"
                                    >
                                        {application.job_posting.title}
                                    </Text>
                                )}

                                <Text size="sm" color="muted" className="!mt-1">
                                    {[
                                        showCandidate ? application.candidate?.email : null,
                                        application.contact_phone,
                                        submitted,
                                    ]
                                        .filter(Boolean)
                                        .join(' · ')}
                                </Text>
                            </div>

                            <div className="flex items-center gap-2">
                                {/*
                                    The host's control, FIRST in the action row.
                                    A resume download is a read, and reads belong
                                    left of the controls that change something —
                                    putting it after a status Select would make the
                                    destructive-ish action the easier target.
                                    Called per row with that row's application, and
                                    rendered only when it returns something, so a
                                    host showing a link on some rows and not others
                                    gets no empty box on the rest.
                                */}
                                {rowActions
                                    ? (() => {
                                          const actions = rowActions(application);
                                          return actions ? (
                                              <div
                                                  data-job-board-application-actions=""
                                                  className="flex items-center gap-2"
                                              >
                                                  {actions}
                                              </div>
                                          ) : null;
                                      })()
                                    : null}

                                {onStatusChange && (
                                    <Select
                                        list={[...APPLICATION_STATUS_OPTIONS]}
                                        value={application.status}
                                        disabled={busy}
                                        onValueChange={(status) =>
                                            onStatusChange(application, status as ApplicationStatus)
                                        }
                                        className="!min-w-40"
                                    />
                                )}

                                {onWithdraw && !application.is_terminal && (
                                    <Button
                                        type="button"
                                        variant="ghost"
                                        loading={busy}
                                        disabled={busy}
                                        onClick={() => onWithdraw(application)}
                                        className="!text-secondary-700 hover:!text-brand"
                                    >
                                        Withdraw
                                    </Button>
                                )}
                            </div>
                        </div>

                        {application.cover_letter && (
                            <Text
                                size="sm"
                                className="!mt-4 !text-secondary-700 whitespace-pre-line border-t border-secondary-200 pt-4"
                            >
                                {application.cover_letter}
                            </Text>
                        )}

                        {application.employer_notes && (
                            <Text size="xs" color="muted" className="!mt-3">
                                Notes: {application.employer_notes}
                            </Text>
                        )}
                    </Card>
                );
            })}
        </div>
    );
}

import type { ApplicationStatus, JobPosting, JobPostingStatus } from './types';

const PAY_UNIT_SUFFIX: Record<string, string> = {
    hour: '/hr',
    day: '/day',
    week: '/wk',
    month: '/mo',
    year: '/yr',
};

/**
 * "$20–$30/hr", "From $45,000/yr", "Up to $25/hr", or null when the posting
 * gives no pay information — callers should omit the line entirely rather than
 * print an empty range.
 */
export function formatPay(posting: Pick<JobPosting, 'pay_min' | 'pay_max' | 'pay_unit' | 'currency'>): string | null {
    const { pay_min, pay_max, pay_unit, currency } = posting;

    if (pay_min == null && pay_max == null) {
        return null;
    }

    const money = (n: number) =>
        new Intl.NumberFormat(undefined, {
            style: 'currency',
            currency: currency || 'USD',
            maximumFractionDigits: n % 1 === 0 ? 0 : 2,
        }).format(n);

    const suffix = pay_unit ? (PAY_UNIT_SUFFIX[pay_unit] ?? `/${pay_unit}`) : '';

    if (pay_min != null && pay_max != null) {
        return pay_min === pay_max
            ? `${money(pay_min)}${suffix}`
            : `${money(pay_min)}–${money(pay_max)}${suffix}`;
    }

    return pay_min != null
        ? `From ${money(pay_min)}${suffix}`
        : `Up to ${money(pay_max as number)}${suffix}`;
}

/** "Torrance, CA", "Remote", or "Remote · Torrance, CA" when it is both. */
export function formatLocation(posting: Pick<JobPosting, 'location' | 'is_remote'>): string | null {
    if (posting.is_remote && posting.location) {
        return `Remote · ${posting.location}`;
    }
    if (posting.is_remote) {
        return 'Remote';
    }
    return posting.location || null;
}

/** Coarse "posted" line. Deliberately vague — exact times add nothing here. */
export function formatPosted(iso?: string | null): string | null {
    if (!iso) return null;

    const then = new Date(iso).getTime();
    if (Number.isNaN(then)) return null;

    const days = Math.floor((Date.now() - then) / 86_400_000);

    if (days <= 0) return 'Posted today';
    if (days === 1) return 'Posted yesterday';
    if (days < 7) return `Posted ${days} days ago`;
    if (days < 14) return 'Posted last week';
    if (days < 60) return `Posted ${Math.floor(days / 7)} weeks ago`;
    return `Posted ${Math.floor(days / 30)} months ago`;
}

/** Fancy Badge colours, chosen so status reads at a glance. */
export function postingStatusColor(status: JobPostingStatus): 'green' | 'zinc' | 'red' {
    switch (status) {
        case 'published':
            return 'green';
        case 'closed':
            return 'red';
        default:
            return 'zinc';
    }
}

export function applicationStatusColor(status: ApplicationStatus): 'green' | 'zinc' | 'red' | 'blue' {
    switch (status) {
        case 'hired':
            return 'green';
        case 'shortlisted':
            return 'blue';
        case 'rejected':
        case 'withdrawn':
            return 'red';
        default:
            return 'zinc';
    }
}

