import { type ReactNode } from "react";
import type { ArtPieceContent } from "../lib/types";

export type ArtPieceProps = {
  /** Stable handle — agents/selectors target this without guessing the DOM. */
  id: string;
  label?: string;
  width?: number;
  height?: number;
  /**
   * Content source. Omit to render `children` as a `kind:"node"` piece
   * (JSX authoring sugar), or pass an explicit image/html/node descriptor.
   */
  content?: ArtPieceContent;
  /** Proposed (agent-staged) piece — renders with a trust-but-verify affordance. */
  pending?: boolean;
  /** JSX content when authoring inline (compiled to a `kind:"node"` piece). */
  children?: ReactNode;
};

/**
 * Authoring marker for a single design frame. Renders nothing itself — the
 * parent `<ArtBoard>` walks `<ArtPiece>` children to compile the
 * `ArtBoardValue` and a content registry (for `kind:"node"` JSX). The frame
 * chrome + content host is rendered by `PieceFrame`.
 */
export function ArtPiece(_props: ArtPieceProps): null {
  return null;
}
ArtPiece.displayName = "ArtPiece";

import { useRef, useState, type CSSProperties } from "react";
import { Button, Dropdown, Tooltip } from "@particle-academy/react-fancy";
import type { ArtPieceData, ArtSectionData } from "../lib/types";
import { useArtBoard } from "../artboard/context";
import { InlineEditor } from "../lib/components/InlineEditor";
import { exportPiece, exportName, type ExportKind } from "../lib/lib/export";
import { cx } from "../lib/lib/cx";
import { PolicyHtml } from "../lib/html/PolicyHtml";

const DEFAULT_W = 260;
const DEFAULT_H = 480;

type PieceFrameProps = {
  sectionId: string;
  piece: ArtPieceData;
  /** Ordered piece ids in the section — for live drag-reorder. */
  order: string[];
};

export function PieceFrame({ sectionId, piece, order }: PieceFrameProps) {
  const board = useArtBoard();
  const slotRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  // Two-click delete confirm — persists across menu re-opens.
  const [confirming, setConfirming] = useState(false);
  const width = piece.width ?? DEFAULT_W;
  const height = piece.height ?? DEFAULT_H;
  const id = piece.id;
  const label = piece.label ?? id;

  const renameLabel = (next: string) => {
    board.setSections((sections) =>
      sections.map((s) =>
        s.id === sectionId
          ? { ...s, pieces: s.pieces.map((p) => (p.id === id ? { ...p, label: next } : p)) }
          : s,
      ),
    );
  };

  const reorder = (nextOrder: string[]) => {
    board.setSections((sections) =>
      sections.map((s) => {
        if (s.id !== sectionId) return s;
        const byId = new Map(s.pieces.map((p) => [p.id, p]));
        return { ...s, pieces: nextOrder.map((k) => byId.get(k)!).filter(Boolean) };
      }),
    );
  };

  const remove = () => {
    board.setSections((sections) =>
      sections.map((s) =>
        s.id === sectionId ? { ...s, pieces: s.pieces.filter((p) => p.id !== id) } : s,
      ),
    );
  };

  const doExport = (kind: ExportKind) => {
    board.onExport?.(id, kind);
    if (!cardRef.current) return;
    exportPiece(cardRef.current, width, height, exportName(piece.label, id), kind).catch((e) =>
      // eslint-disable-next-line no-console
      console.error("[fancy-artboard] export failed:", e),
    );
  };

  const focus = () => board.setFocus(id);

  // Live drag-reorder: dragged card sticks to the cursor; siblings slide into
  // their would-be slots via transforms; DOM order commits only on drop.
  const onGripDown = (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const me = slotRef.current;
    if (!me) return;
    // translateX is in local (pre-scale) space but pointer deltas + rect.left
    // are screen-space — divide by the live zoom so it tracks the cursor.
    const scale = me.getBoundingClientRect().width / me.offsetWidth || 1;
    const peers = Array.from(
      document.querySelectorAll<HTMLElement>(
        `[data-fa-section="${CSS.escape(sectionId)}"] [data-fa-piece]`,
      ),
    );
    const homes = peers.map((el) => ({
      el,
      id: el.dataset.faPiece as string,
      x: el.getBoundingClientRect().left,
    }));
    const slotXs = homes.map((h) => h.x);
    const startIdx = order.indexOf(id);
    const startX = e.clientX;
    let liveOrder = order.slice();
    me.classList.add("fa-dragging");

    const layout = () => {
      for (const h of homes) {
        if (h.id === id) continue;
        const slot = liveOrder.indexOf(h.id);
        h.el.style.transform = `translateX(${(slotXs[slot] - h.x) / scale}px)`;
      }
    };

    const move = (ev: PointerEvent) => {
      const dx = ev.clientX - startX;
      me.style.transform = `translateX(${dx / scale}px)`;
      const cur = homes[startIdx].x + dx;
      let nearest = 0;
      let best = Infinity;
      for (let i = 0; i < slotXs.length; i++) {
        const d = Math.abs(slotXs[i] - cur);
        if (d < best) {
          best = d;
          nearest = i;
        }
      }
      if (liveOrder.indexOf(id) !== nearest) {
        liveOrder = order.filter((k) => k !== id);
        liveOrder.splice(nearest, 0, id);
        layout();
      }
    };

    const up = () => {
      document.removeEventListener("pointermove", move);
      document.removeEventListener("pointerup", up);
      const finalSlot = liveOrder.indexOf(id);
      me.classList.remove("fa-dragging");
      me.style.transform = `translateX(${(slotXs[finalSlot] - homes[startIdx].x) / scale}px)`;
      // After the settle transition, kill transitions + clear transforms +
      // commit in the same frame so there's no snap-back flash.
      setTimeout(() => {
        for (const h of homes) {
          h.el.style.transition = "none";
          h.el.style.transform = "";
        }
        if (liveOrder.join("|") !== order.join("|")) reorder(liveOrder);
        requestAnimationFrame(() =>
          requestAnimationFrame(() => {
            for (const h of homes) h.el.style.transition = "";
          }),
        );
      }, 180);
    };

    document.addEventListener("pointermove", move);
    document.addEventListener("pointerup", up);
  };

  const cardStyle: CSSProperties = {
    width,
    height,
  };

  return (
    <div ref={slotRef} className="fa-slot" data-fa-piece={id}>
      <div
        className="fa-header"
        data-fa-chrome=""
        onPointerDown={(e) => e.stopPropagation()}
      >
        <div className="fa-labelrow">
          <span
            className="fa-grip"
            onPointerDown={onGripDown}
            title="Drag to reorder"
            aria-label="Drag to reorder"
          >
            <svg width="9" height="13" viewBox="0 0 9 13" fill="currentColor" aria-hidden>
              <circle cx="2" cy="2" r="1.1" />
              <circle cx="7" cy="2" r="1.1" />
              <circle cx="2" cy="6.5" r="1.1" />
              <circle cx="7" cy="6.5" r="1.1" />
              <circle cx="2" cy="11" r="1.1" />
              <circle cx="7" cy="11" r="1.1" />
            </svg>
          </span>
          <span className="fa-labeltext" onClick={focus} title="Click to focus">
            <InlineEditor
              value={label}
              onChange={renameLabel}
              onClick={(e) => e.stopPropagation()}
              style={{ fontSize: 15, fontWeight: 500, lineHeight: 1 }}
            />
          </span>
        </div>
        <div className="fa-btns">
          <Dropdown placement="bottom-start">
            <Dropdown.Trigger>
              <Tooltip content="More">
                <Button variant="ghost" size="sm" icon="more-horizontal" aria-label="More" />
              </Tooltip>
            </Dropdown.Trigger>
            <Dropdown.Items className="fa-menu">
              <Dropdown.Item
                onClick={() => {
                  setConfirming(false);
                  doExport("png");
                }}
              >
                Download PNG
              </Dropdown.Item>
              <Dropdown.Item
                onClick={() => {
                  setConfirming(false);
                  doExport("html");
                }}
              >
                Download HTML
              </Dropdown.Item>
              <Dropdown.Separator />
              <Dropdown.Item
                danger
                onClick={() => {
                  if (confirming) {
                    setConfirming(false);
                    remove();
                  } else {
                    setConfirming(true);
                  }
                }}
              >
                {confirming ? "Click again to delete" : "Delete"}
              </Dropdown.Item>
            </Dropdown.Items>
          </Dropdown>
          <Tooltip content="Focus">
            <Button variant="ghost" size="sm" icon="maximize" onClick={focus} aria-label="Focus" />
          </Tooltip>
        </div>
      </div>
      <div
        ref={cardRef}
        className={cx("fa-card", piece.pending && "fa-pending")}
        style={cardStyle}
      >
        <PieceContent piece={piece} sectionId={sectionId} />
        {piece.pending && <span className="fa-pending-badge">proposed</span>}
      </div>
    </div>
  );
}

/** Renders the piece content inline so it scales crisply under the world transform. */
function PieceContent({ piece, sectionId }: { piece: ArtPieceData; sectionId: string }) {
  const board = useArtBoard();
  const c = piece.content;
  if (c.kind === "image") {
    return (
      <img
        src={c.src}
        alt={c.alt ?? piece.label ?? piece.id}
        style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
      />
    );
  }
  if (c.kind === "html") {
    return (
      <PolicyHtml
        html={c.html}
        policy={board.htmlPolicy}
        context={{
          pieceId: piece.id,
          sectionId,
          origin: piece.origin ?? "agent",
          reviewState: piece.pending ? "pending" : "accepted",
        }}
      />
    );
  }
  // kind: "node" — the JSX child the human authored.
  const node = board.nodes.get(piece.id);
  return <>{node ?? null}</>;
}

import type { HtmlOrigin } from "./html/policy";

export type Viewport = { x: number; y: number; zoom: number };
export type ArtPieceContent =
  | { kind: "image"; src: string; alt?: string }
  | { kind: "html"; html: string }
  | { kind: "node" };
export type ArtPieceData = {
  id: string; label?: string; width?: number; height?: number;
  content: ArtPieceContent; pending?: boolean;
  /**
   * Who authored this piece. Drives the HTML trust policy together with
   * `pending`. Absent is treated as `"agent"` — the conservative assumption on
   * an open-world board, so unlabelled HTML is sanitised/sandboxed rather than
   * trusted.
   */
  origin?: HtmlOrigin;
};
export type ArtSectionData = { id: string; title: string; subtitle?: string; pieces: ArtPieceData[] };

/**
 * A free-floating note, as DATA.
 *
 * Notes existed only as React children, and `NoteProps` carried no id — so an
 * agent driving the board read every piece and was blind to every note: it
 * could not enumerate them, resolve one, or author one without emitting JSX.
 * That broke both halves of the component contract at once ("stable handles"
 * and "avoid forcing React children for things the agent must populate"), in a
 * package whose entire subject is a shared human+agent canvas.
 *
 * Mirrors {@link NoteProps} so a note round-trips between the two forms.
 */
export type ArtNoteData = {
  /** Stable handle. Rendered as `data-fa-note-id` so an agent never guesses DOM. */
  id: string;
  /** Note text. Named `text` rather than `value` because this is data, not a control. */
  text?: string;
  top?: number | string;
  left?: number | string;
  right?: number | string;
  bottom?: number | string;
  rotate?: number;
  width?: number | string;
  /** Paper colour — a react-fancy StickyNote preset or any CSS colour. */
  color?: string;
  /** Trust-but-verify: an agent-proposed note awaiting a human. */
  pending?: boolean;
};

export type ArtBoardValue = {
  sections: ArtSectionData[];
  /**
   * Optional so this is additive: a board written before notes were data still
   * type-checks, and the JSX-children form keeps working alongside it.
   */
  notes?: ArtNoteData[];
};

import { type CSSProperties, type ElementType } from "react";
import { cx } from "../lib/cx";

export type InlineEditorProps = {
  value: string;
  onChange?: (value: string) => void;
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  onClick?: (e: React.MouseEvent) => void;
  title?: string;
};

/**
 * Tiny contentEditable inline editor — crisp under counter-scale. Commits on
 * blur or Enter; Escape reverts. Stops pointerdown so it doesn't initiate a
 * viewport pan or a grip drag.
 */
export function InlineEditor({
  value,
  onChange,
  as,
  className,
  style,
  onClick,
  title,
}: InlineEditorProps) {
  const Tag = (as || "span") as ElementType;
  return (
    <Tag
      className={cx("fa-editable", className)}
      contentEditable
      suppressContentEditableWarning
      spellCheck={false}
      title={title}
      onClick={onClick}
      onPointerDown={(e: React.PointerEvent) => e.stopPropagation()}
      onBlur={(e: React.FocusEvent<HTMLElement>) =>
        onChange?.(e.currentTarget.textContent ?? "")
      }
      onKeyDown={(e: React.KeyboardEvent<HTMLElement>) => {
        if (e.key === "Enter") {
          e.preventDefault();
          e.currentTarget.blur();
        } else if (e.key === "Escape") {
          e.preventDefault();
          e.currentTarget.textContent = value;
          e.currentTarget.blur();
        }
      }}
      style={style}
    >
      {value}
    </Tag>
  );
}

// Self-contained per-piece export. Clones the live DOM node with computed
// styles baked in, inlines @font-face / <img> / inline-style background-image
// urls as data URIs, then emits either a PNG (foreignObject -> canvas at 3x)
// or a standalone HTML document. Independent of viewport zoom.
//
// Rebuilt clean from the dirty reference's `dcExport` — no host coupling.

export type ExportKind = "png" | "html";

const toDataURL = (url: string): Promise<string> =>
  fetch(url)
    .then((r) => r.blob())
    .then(
      (b) =>
        new Promise<string>((res) => {
          const fr = new FileReader();
          fr.onload = () => res(String(fr.result));
          fr.onerror = () => res(url);
          fr.readAsDataURL(b);
        }),
    )
    .catch(() => url);

// Collect @font-face rules across all stylesheets. Cross-origin sheets throw
// SecurityError on .cssRules — fall back to fetching the CSS text directly and
// regex-extracting the blocks. @import / nested groups are walked.
async function collectFontCss(): Promise<string> {
  const fontRules: Array<{ css: string; base: string }> = [];
  const pending: Array<Promise<void>> = [];
  const seen = new Set<string>();

  const scrapeCss = (href: string) => {
    if (seen.has(href)) return;
    seen.add(href);
    pending.push(
      fetch(href)
        .then((r) => r.text())
        .then((css) => {
          for (const m of css.match(/@font-face\s*{[^}]*}/g) || [])
            fontRules.push({ css: m, base: href });
          for (const m of css.matchAll(/@import\s+(?:url\()?['"]?([^'")\s;]+)/g))
            scrapeCss(new URL(m[1], href).href);
        })
        .catch(() => {}),
    );
  };

  const walk = (rules: CSSRuleList, base: string) => {
    for (const r of Array.from(rules)) {
      if (r.type === CSSRule.FONT_FACE_RULE) {
        fontRules.push({ css: r.cssText, base });
      } else if (r.type === CSSRule.IMPORT_RULE && (r as CSSImportRule).styleSheet) {
        const sheet = (r as CSSImportRule).styleSheet as CSSStyleSheet;
        const ibase = sheet.href || base;
        try {
          walk(sheet.cssRules, ibase);
        } catch {
          scrapeCss(ibase);
        }
      } else if ((r as CSSGroupingRule).cssRules) {
        walk((r as CSSGroupingRule).cssRules, base);
      }
    }
  };

  for (const ss of Array.from(document.styleSheets)) {
    const base = ss.href || location.href;
    try {
      walk(ss.cssRules, base);
    } catch {
      if (ss.href) scrapeCss(ss.href);
    }
  }
  while (pending.length) await pending.shift();

  return (
    await Promise.all(
      fontRules.map(async (rule) => {
        let out = rule.css;
        const re = /url\((['"]?)([^'")]+)\1\)/g;
        let m: RegExpExecArray | null;
        while ((m = re.exec(rule.css))) {
          if (m[2].indexOf("data:") === 0) continue;
          let abs: string;
          try {
            abs = new URL(m[2], rule.base).href;
          } catch {
            continue;
          }
          out = out.split(m[0]).join('url("' + (await toDataURL(abs)) + '")');
        }
        return out;
      }),
    )
  ).join("\n");
}

// Deep clone with every computed style baked into an inline style attribute,
// canvases rasterized to <img>, scripts/comments dropped.
function cloneStyled(src: Node): Node {
  if (src.nodeType === 8 || (src.nodeType === 1 && (src as Element).tagName === "SCRIPT"))
    return document.createTextNode("");
  const dst = src.cloneNode(false);
  if (src.nodeType === 1) {
    const el = src as Element;
    const cs = getComputedStyle(el);
    let txt = "";
    for (let i = 0; i < cs.length; i++) txt += cs[i] + ":" + cs.getPropertyValue(cs[i]) + ";";
    (dst as Element).setAttribute("style", txt + "animation:none;transition:none;");
    if (el.tagName === "CANVAS") {
      try {
        const im = document.createElement("img");
        im.src = (el as HTMLCanvasElement).toDataURL();
        im.setAttribute("style", txt);
        return im;
      } catch {
        /* tainted canvas — fall through to the styled clone */
      }
    }
  }
  for (let c = src.firstChild; c; c = c.nextSibling) dst.appendChild(cloneStyled(c));
  return dst;
}

const triggerDownload = (blob: Blob | null, name: string, ext: string) => {
  if (!blob) return;
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = name + "." + ext;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
};

/**
 * Export a piece's content DOM node as a PNG or standalone HTML file.
 * @param node  the live element to capture (the piece content host)
 * @param w     natural width in px (artboard width)
 * @param h     natural height in px (artboard height)
 * @param name  download filename (sans extension)
 * @param kind  "png" | "html"
 */
export async function exportPiece(
  node: HTMLElement,
  w: number,
  h: number,
  name: string,
  kind: ExportKind,
): Promise<void> {
  try {
    await document.fonts.ready;
  } catch {
    /* fonts API may be unavailable */
  }
  const fontCss = await collectFontCss();

  const clone = cloneStyled(node) as HTMLElement;
  clone.setAttribute("xmlns", "http://www.w3.org/1999/xhtml");
  // Flush w x h rect — drop the frame's own shadow/radius.
  clone.style.boxShadow = "none";
  clone.style.borderRadius = "0";

  const jobs: Array<Promise<void>> = [];
  clone.querySelectorAll("img").forEach((el) => {
    const s = el.getAttribute("src");
    if (s && s.indexOf("data:") !== 0)
      jobs.push(toDataURL((el as HTMLImageElement).src).then((d) => el.setAttribute("src", d)));
  });
  [clone, ...Array.from(clone.querySelectorAll<HTMLElement>("*"))].forEach((el) => {
    const bg = el.style.backgroundImage;
    if (!bg) return;
    const re = /url\(["']?([^"')]+)["']?\)/g;
    let m: RegExpExecArray | null;
    while ((m = re.exec(bg))) {
      const tok = m[0];
      const url = m[1];
      if (url.indexOf("data:") === 0) continue;
      jobs.push(
        toDataURL(url).then((d) => {
          el.style.backgroundImage = el.style.backgroundImage.split(tok).join('url("' + d + '")');
        }),
      );
    }
  });
  await Promise.all(jobs);

  const xml = new XMLSerializer().serializeToString(clone);

  if (kind === "html") {
    const html =
      '<!doctype html><html><head><meta charset="utf-8"><title>' +
      name +
      "</title>" +
      (fontCss ? "<style>" + fontCss + "</style>" : "") +
      '</head><body style="margin:0">' +
      xml +
      "</body></html>";
    triggerDownload(new Blob([html], { type: "text/html" }), name, "html");
    return;
  }

  // PNG — the SVG's own width/height is the output resolution; viewBox maps the
  // w x h foreignObject onto the px*w x px*h canvas so the browser renders the
  // HTML at full resolution (not an upscaled 1x bitmap).
  const px = 3;
  const svg =
    '<svg xmlns="http://www.w3.org/2000/svg" width="' +
    w * px +
    '" height="' +
    h * px +
    '" viewBox="0 0 ' +
    w +
    " " +
    h +
    '"><foreignObject width="' +
    w +
    '" height="' +
    h +
    '">' +
    (fontCss ? "<style><![CDATA[" + fontCss + "]]></style>" : "") +
    xml +
    "</foreignObject></svg>";
  const img = new Image();
  await new Promise<void>((res, rej) => {
    img.onload = () => res();
    img.onerror = () => rej(new Error("svg load failed"));
    img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
  });
  const cv = document.createElement("canvas");
  cv.width = w * px;
  cv.height = h * px;
  cv.getContext("2d")?.drawImage(img, 0, 0);
  await new Promise<void>((res) => {
    cv.toBlob((blob) => {
      triggerDownload(blob, name, "png");
      res();
    }, "image/png");
  });
}

/** Sanitize a label/id into a safe download filename stem. */
export function exportName(label: string | undefined, id: string): string {
  return String(label || id || "artpiece").replace(/[^\w\s.-]+/g, "_");
}

// Tiny classnames join — no third-party deps (no clsx).
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

import { useMemo, type CSSProperties } from "react";
import {
  checkLimits,
  resolveHtmlMode,
  sanitizeHtmlWithReport,
  type HtmlPolicy,
  type HtmlPolicyContext,
} from "./policy";

/**
 * The one place agent-authored HTML is rendered.
 *
 * `PieceFrame` and `FocusOverlay` both used their own `dangerouslySetInnerHTML`
 * call, which is how the same hole existed twice. Both now render through this
 * component, so a policy change lands everywhere and neither surface can drift
 * back to raw output.
 */
export type PolicyHtmlProps = {
  html: string;
  policy?: HtmlPolicy;
  context: HtmlPolicyContext;
  style?: CSSProperties;
  className?: string;
};

const FILL: CSSProperties = { width: "100%", height: "100%" };

export function PolicyHtml({ html, policy, context, style, className }: PolicyHtmlProps) {
  const mode = resolveHtmlMode(policy, context);

  const resolved = useMemo(() => {
    if (mode === "blocked") return { html: "", removed: [], blocked: true as const };

    const limits = checkLimits(html, policy?.limits);
    if (!limits.ok) {
      policy?.onViolation?.({ context, kind: limits.violation!.kind, detail: limits.violation!.detail });
      return { html: "", removed: [limits.violation!], blocked: true as const };
    }

    if (mode === "trusted") return { html, removed: [], blocked: false as const };
    if (mode === "sandbox") return { html, removed: [], blocked: false as const };

    const result = policy?.sanitizer ? policy.sanitizer(html, context) : sanitizeHtmlWithReport(html);
    for (const item of result.removed) {
      policy?.onViolation?.({ context, kind: item.kind, detail: item.detail });
    }
    return { ...result, blocked: false as const };
    // `policy` identity churn would re-sanitize every render; the fields that
    // actually affect the output are the deps.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [html, mode, policy?.sanitizer, policy?.limits, context.pieceId, context.reviewState, context.origin]);

  const base = { ...FILL, ...style };

  if (resolved.blocked) {
    return (
      <div
        className={className}
        style={base}
        data-artboard-html-mode="blocked"
        data-artboard-html-blocked=""
      />
    );
  }

  if (mode === "sandbox") {
    // No allow-scripts and no allow-same-origin: the document is inert and
    // cannot reach this origin. This is what makes "pending" an actual boundary
    // rather than a label — unreviewed markup renders visually without ever
    // executing.
    return (
      <iframe
        className={className}
        style={{ ...base, border: 0, background: "transparent" }}
        sandbox=""
        srcDoc={resolved.html}
        title={`artboard-piece-${context.pieceId}`}
        data-artboard-html-mode="sandbox"
      />
    );
  }

  return (
    <div
      className={className}
      style={base}
      data-artboard-html-mode={mode}
      data-artboard-html-removed={resolved.removed.length || undefined}
      dangerouslySetInnerHTML={{ __html: resolved.html }}
    />
  );
}

/**
 * Host-owned trust policy for agent-authored HTML.
 *
 * ArtBoard is open-world: an agent can propose a piece whose content is raw
 * HTML. That HTML used to reach `dangerouslySetInnerHTML` untouched, and a live
 * probe confirmed script execution from an `<img onerror>` handler **while the
 * piece was still PROPOSED** — so "pending review" was visual state, not a
 * security boundary.
 *
 * The fix is not to close the world but to make trust an explicit decision the
 * HOST owns and content can never elevate:
 *
 *     effective mode = most restrictive of (host policy × origin × review state)
 *
 * Nothing in a payload selects its own mode.
 */

/** How a piece's HTML is allowed to render. Ordered least → most restrictive. */
export type HtmlRenderMode = "trusted" | "sanitize" | "sandbox" | "blocked";

/** Restrictiveness rank — higher wins when combining decisions. */
const RANK: Record<HtmlRenderMode, number> = {
  trusted: 0,
  sanitize: 1,
  sandbox: 2,
  blocked: 3,
};

/** Return whichever mode is more restrictive. */
export function mostRestrictive(a: HtmlRenderMode, b: HtmlRenderMode): HtmlRenderMode {
  return RANK[a] >= RANK[b] ? a : b;
}

export type HtmlOrigin = "host" | "human" | "agent" | "external";
export type HtmlReviewState = "pending" | "accepted";

export type HtmlPolicyContext = {
  pieceId: string;
  sectionId: string;
  origin: HtmlOrigin;
  reviewState: HtmlReviewState;
};

export type SanitizedHtmlResult = {
  html: string;
  /** What was stripped, so a human can see why the render differs. */
  removed: Array<{ kind: string; detail: string }>;
};

export type HtmlPolicyViolation = {
  context: HtmlPolicyContext;
  /** What tripped: a removed construct, or a limit that was exceeded. */
  kind: string;
  detail: string;
};

export type HtmlPolicyLimits = {
  maxBytes?: number;
  maxDepth?: number;
  maxNodes?: number;
};

export type HtmlPolicy = {
  /** Mode for content that a human has accepted. Default `sanitize`. */
  accepted?: HtmlRenderMode;
  /**
   * Mode for content still awaiting review. Default `sandbox`.
   * `trusted` is deliberately not assignable — unreviewed content can never
   * run with full privileges.
   */
  pending?: Exclude<HtmlRenderMode, "trusted">;
  /** Final say. Its result is still floored by the origin/review baseline. */
  resolve?: (context: HtmlPolicyContext) => HtmlRenderMode;
  /** Replace the built-in sanitizer. */
  sanitizer?: (html: string, context: HtmlPolicyContext) => SanitizedHtmlResult;
  onViolation?: (event: HtmlPolicyViolation) => void;
  limits?: HtmlPolicyLimits;
};

export const DEFAULT_LIMITS: Required<HtmlPolicyLimits> = {
  maxBytes: 512_000,
  maxDepth: 64,
  maxNodes: 5_000,
};

/**
 * The floor for a given origin + review state, before the host's policy applies.
 *
 * Host-authored content is the only thing that may be trusted outright, and
 * only once it is not pending. Unknown provenance is blocked rather than
 * guessed at.
 */
function baseline(context: HtmlPolicyContext): HtmlRenderMode {
  if (context.reviewState === "pending") return "sandbox";
  switch (context.origin) {
    case "host":
      return "trusted";
    case "human":
    case "agent":
      return "sanitize";
    case "external":
      return "sanitize";
    default:
      return "blocked";
  }
}

/**
 * Resolve the effective render mode.
 *
 * Every input can only tighten: the host's `resolve`/`accepted`/`pending`
 * choice is combined with the origin baseline via `mostRestrictive`, so a host
 * may harden its own content but a policy can never loosen what the origin
 * and review state already require.
 */
export function resolveHtmlMode(
  policy: HtmlPolicy | undefined,
  context: HtmlPolicyContext,
): HtmlRenderMode {
  const floor = baseline(context);

  const configured =
    context.reviewState === "pending"
      ? (policy?.pending ?? "sandbox")
      : (policy?.accepted ?? "sanitize");

  let mode = mostRestrictive(floor, configured);

  if (policy?.resolve) {
    // A resolver may tighten further, never loosen below the baseline.
    mode = mostRestrictive(mode, policy.resolve(context));
  }

  return mode;
}

const EVENT_ATTR = /^on/i;
const UNSAFE_URL = /^(javascript|vbscript|data):/i;
/**
 * Unsafe schemes anywhere in a CSS value — `background:url(javascript:…)` puts
 * the scheme mid-string, so this one is deliberately unanchored. `data:` is
 * left alone except for text/html, since data-URI images are ordinary in CSS.
 */
const UNSAFE_CSS = /(javascript|vbscript)\s*:|data\s*:\s*text\/html/i;

/**
 * Normalize a URL attribute before testing its scheme.
 *
 * Browsers ignore whitespace and control characters inside a scheme, so
 * `java\tscript:` and `java\nscript:` both execute. Strip them first, or the
 * anchored test above is trivially bypassed.
 */
function normalizeUrl(value: string): string {
  // Drop spaces, control characters and NBSP by code point. Written as a filter
  // rather than a regex character class so the literal control bytes never end
  // up in this source file.
  return Array.from(value)
    .filter((ch) => {
      const code = ch.charCodeAt(0);
      return code > 32 && code !== 127 && code !== 160;
    })
    .join("");
}
const BLOCKED_TAGS = new Set([
  "SCRIPT",
  "IFRAME",
  "OBJECT",
  "EMBED",
  "APPLET",
  "FORM",
  "BASE",
  "META",
  "LINK",
  "STYLE",
  "FOREIGNOBJECT",
]);
const URL_ATTRS = ["href", "src", "action", "formaction", "xlink:href", "poster", "background"];

/**
 * Built-in sanitizer: strips active content and reports what it removed.
 *
 * Deliberately implemented here rather than delegating to react-fancy's
 * `sanitizeHtml`, for two reasons — it must return a removal REPORT, and that
 * helper returns its input unchanged when `DOMParser` is unavailable, which
 * would silently pass raw agent HTML through during SSR. This one fails closed
 * instead (see `sanitizeHtmlWithReport`).
 */
export function sanitizeHtmlWithReport(html: string): SanitizedHtmlResult {
  const removed: SanitizedHtmlResult["removed"] = [];

  if (typeof DOMParser === "undefined") {
    // No parser (SSR / non-DOM runtime) means no way to make this safe. Emit
    // nothing rather than the raw string — failing closed is the whole point.
    return {
      html: "",
      removed: [{ kind: "unavailable", detail: "No DOMParser available; HTML withheld." }],
    };
  }

  // CodeQL flags this line as `js/html-constructed-from-input` (medium). It is a
  // FALSE POSITIVE, dismissed on the alert — recorded here because a dismissal in
  // GitHub's UI is invisible to anyone reading the code, and the next person to
  // see the warning deserves the reasoning rather than a rediscovery.
  //
  // `parseFromString(..., "text/html")` builds an INERT document: no script
  // executes, no resource is fetched, no side effect occurs. That is precisely
  // why it is the standard way to sanitize untrusted HTML, and it is the parse
  // step of the sanitizer — the walk below is what makes the output safe, and the
  // only consumer (`PolicyHtml`) passes the SANITIZED result to
  // `dangerouslySetInnerHTML`, never this input.
  //
  // CodeQL traces "library input -> HTML string -> parser" without modelling
  // either of those facts. If this ever stops being a sanitizer — if the parsed
  // document or the raw `html` reaches the DOM without the walk — the warning
  // becomes real and this comment is wrong.
  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");
  const body = doc.body;
  if (!body) return { html: "", removed: [{ kind: "unparsable", detail: "HTML could not be parsed." }] };

  const walk = (el: Element) => {
    for (const child of Array.from(el.children)) walk(child);

    if (BLOCKED_TAGS.has(el.tagName)) {
      removed.push({ kind: "element", detail: `<${el.tagName.toLowerCase()}>` });
      el.remove();
      return;
    }

    for (const attr of Array.from(el.attributes)) {
      const name = attr.name.toLowerCase();

      if (EVENT_ATTR.test(name)) {
        removed.push({ kind: "event-handler", detail: `${el.tagName.toLowerCase()}[${name}]` });
        el.removeAttribute(attr.name);
        continue;
      }

      if (URL_ATTRS.includes(name) && UNSAFE_URL.test(normalizeUrl(attr.value))) {
        removed.push({ kind: "unsafe-url", detail: `${name}="${attr.value.slice(0, 40)}"` });
        el.removeAttribute(attr.name);
        continue;
      }

      // url(javascript:…) and friends inside inline styles.
      if (name === "style" && UNSAFE_CSS.test(attr.value)) {
        removed.push({ kind: "unsafe-css", detail: "style contains an unsafe url()" });
        el.removeAttribute(attr.name);
      }
    }
  };

  for (const child of Array.from(body.children)) walk(child);

  return { html: body.innerHTML, removed };
}

/** Measure a document fragment against the configured limits. */
export function checkLimits(
  html: string,
  limits: HtmlPolicyLimits | undefined,
): { ok: boolean; violation?: { kind: string; detail: string } } {
  const merged = { ...DEFAULT_LIMITS, ...limits };

  const bytes = html.length;
  if (bytes > merged.maxBytes) {
    return { ok: false, violation: { kind: "limit", detail: `${bytes} bytes exceeds maxBytes ${merged.maxBytes}` } };
  }

  if (typeof DOMParser === "undefined") return { ok: true };

  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");
  const body = doc.body;
  if (!body) return { ok: true };

  let nodes = 0;
  let deepest = 0;
  const measure = (el: Element, depth: number) => {
    nodes++;
    if (depth > deepest) deepest = depth;
    for (const child of Array.from(el.children)) measure(child, depth + 1);
  };
  for (const child of Array.from(body.children)) measure(child, 1);

  if (nodes > merged.maxNodes) {
    return { ok: false, violation: { kind: "limit", detail: `${nodes} nodes exceeds maxNodes ${merged.maxNodes}` } };
  }
  if (deepest > merged.maxDepth) {
    return { ok: false, violation: { kind: "limit", detail: `depth ${deepest} exceeds maxDepth ${merged.maxDepth}` } };
  }
  return { ok: true };
}

import {
  Children,
  Fragment,
  isValidElement,
  useCallback,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactElement,
  type ReactNode,
} from "react";
import type {
  ArtBoardValue,
  ArtPieceData,
  ArtSectionData,
  Viewport,
} from "../lib/types";
import { ArtBoardContext, type ArtBoardCtx } from "./context";
import { ViewportEngine } from "./Viewport";
import { Section, SectionView, type SectionProps } from "./Section";
import { ArtPiece, type ArtPieceProps } from "../art-piece/ArtPiece";
import { Note } from "../lib/components/Note/Note";
import { FocusOverlay } from "../lib/components/FocusOverlay/FocusOverlay";
import type { HtmlPolicy } from "../lib/html/policy";

const DEFAULT_VIEWPORT: Viewport = { x: 0, y: 0, zoom: 1 };

export type ArtBoardProps = {
  value?: ArtBoardValue;
  defaultValue?: ArtBoardValue;
  onChange?: (v: ArtBoardValue) => void;
  viewport?: Viewport;
  defaultViewport?: Viewport;
  onViewportChange?: (v: Viewport) => void;
  focus?: string | null;
  onFocusChange?: (pieceId: string | null) => void;
  minZoom?: number;
  maxZoom?: number;
  onExport?: (pieceId: string, kind: "png" | "html") => void;
  /**
   * Trust policy for `kind:"html"` pieces. The HOST owns this — an agent's
   * payload can never select or elevate its own render mode. Defaults to
   * sandboxing pending content and sanitising accepted content.
   */
  htmlPolicy?: HtmlPolicy;
  /** `<ArtBoard.Section>` / `<ArtPiece>` authoring sugar. */
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
};

// Recursively unwrap fragments so <>...</> grouping doesn't hide children.
function flatten(children: ReactNode): ReactNode[] {
  const out: ReactNode[] = [];
  Children.forEach(children, (c) => {
    if (isValidElement(c) && c.type === Fragment) {
      out.push(...flatten((c.props as { children?: ReactNode }).children));
    } else {
      out.push(c);
    }
  });
  return out;
}

type Compiled = { value: ArtBoardValue; nodes: Map<string, ReactNode> };

/** Walk Section/ArtPiece children into an ArtBoardValue + JSX node registry. */
function compileChildren(children: ReactNode): Compiled {
  const sections: ArtSectionData[] = [];
  const nodes = new Map<string, ReactNode>();

  flatten(children).forEach((sec) => {
    if (!isValidElement(sec) || sec.type !== Section) return;
    const sp = sec.props as SectionProps;
    const sid = sp.id ?? sp.title;
    if (!sid) return;
    const pieces: ArtPieceData[] = [];
    flatten(sp.children).forEach((pc) => {
      if (!isValidElement(pc) || pc.type !== ArtPiece) return;
      const pp = (pc as ReactElement).props as ArtPieceProps;
      if (!pp.id) return;
      const content = pp.content ?? { kind: "node" as const };
      if (content.kind === "node") nodes.set(pp.id, pp.children);
      pieces.push({
        id: pp.id,
        label: pp.label,
        width: pp.width,
        height: pp.height,
        content,
        pending: pp.pending,
      });
    });
    sections.push({ id: sid, title: sp.title, subtitle: sp.subtitle, pieces });
  });

  return { value: { sections }, nodes };
}

/**
 * Figma-style design canvas. Controlled (or uncontrolled) pan/zoom board of
 * `ArtPiece`s grouped into `ArtBoard.Section`s. Composes react-fancy chrome and
 * emits no agent events itself — a bridge layer owns presence/undo.
 */
function ArtBoardRoot({
  value,
  defaultValue,
  onChange,
  viewport,
  defaultViewport,
  onViewportChange,
  focus,
  onFocusChange,
  minZoom = 0.1,
  maxZoom = 8,
  onExport,
  htmlPolicy,
  children,
  className,
  style,
}: ArtBoardProps) {
  // children -> value + node registry (one source of truth). Recomputed each
  // render so authored JSX stays live, but only used to seed uncontrolled state.
  const compiled = useMemo(() => compileChildren(children), [children]);

  // value: controlled if `value` defined, else internal seeded from
  // defaultValue ?? compiled-from-children.
  const [internalValue, setInternalValue] = useState<ArtBoardValue>(
    () => defaultValue ?? compiled.value,
  );
  const resolvedValue = value ?? internalValue;

  const setValue = useCallback(
    (next: ArtBoardValue) => {
      if (value === undefined) setInternalValue(next);
      onChange?.(next);
    },
    [value, onChange],
  );

  const setSections = useCallback(
    (fn: (sections: ArtSectionData[]) => ArtSectionData[]) => {
      const cur = value ?? internalValueRef.current;
      setValue({ sections: fn(cur.sections) });
    },
    // setValue depends on value/onChange; cur is read via ref to stay fresh.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [setValue, value],
  );
  // Keep latest internal value reachable from the stable setSections closure.
  const internalValueRef = useRef(internalValue);
  internalValueRef.current = internalValue;

  // viewport: controlled or internal.
  const [internalVp, setInternalVp] = useState<Viewport>(
    () => defaultViewport ?? DEFAULT_VIEWPORT,
  );
  const resolvedVp = viewport ?? internalVp;
  const setVp = useCallback(
    (next: Viewport) => {
      if (viewport === undefined) setInternalVp(next);
      onViewportChange?.(next);
    },
    [viewport, onViewportChange],
  );

  // focus: controlled or internal.
  const [internalFocus, setInternalFocus] = useState<string | null>(null);
  const resolvedFocus = focus !== undefined ? focus : internalFocus;
  const setFocus = useCallback(
    (next: string | null) => {
      if (focus === undefined) setInternalFocus(next);
      onFocusChange?.(next);
    },
    [focus, onFocusChange],
  );

  // The node registry: when controlled by `value`, JSX nodes still come from
  // children (the value JSON can't carry React nodes). Merge children-derived
  // nodes regardless of the value source.
  const ctx: ArtBoardCtx = useMemo(
    () => ({
      value: resolvedValue,
      nodes: compiled.nodes,
      patchValue: setValue,
      setSections,
      focus: resolvedFocus,
      setFocus,
      onExport,
      htmlPolicy,
    }),
    [resolvedValue, compiled.nodes, setValue, setSections, resolvedFocus, setFocus, onExport, htmlPolicy],
  );

  return (
    <ArtBoardContext.Provider value={ctx}>
      <ViewportEngine
        viewport={resolvedVp}
        onViewportChange={setVp}
        minZoom={minZoom}
        maxZoom={maxZoom}
        className={className}
        style={style}
      >
        {resolvedValue.sections.map((section) => (
          <SectionView key={section.id} section={section} />
        ))}
        {/* Notes as DATA — what an agent can enumerate, resolve and author.
            Rendered before the children form so a JSX note declared later wins
            the paint order, matching how authors expect their own markup to
            behave. */}
        {resolvedValue.notes?.map((n) => (
          <Note
            key={n.id}
            id={n.id}
            value={n.text}
            top={n.top}
            left={n.left}
            right={n.right}
            bottom={n.bottom}
            rotate={n.rotate}
            width={n.width}
            color={n.color}
          />
        ))}
        {/* Free-floating notes authored as direct children (outside sections).
            Kept: this is how every existing consumer writes a note, and notes
            as data must ADD a way in rather than replace one. */}
        {flatten(children).filter((c) => isValidElement(c) && c.type === Note)}
      </ViewportEngine>
      {resolvedFocus != null && <FocusOverlay />}
    </ArtBoardContext.Provider>
  );
}

export const ArtBoard = Object.assign(ArtBoardRoot, {
  Section,
  Note,
});

import { type ReactNode } from "react";
import type { ArtSectionData } from "../lib/types";
import { useArtBoard } from "./context";
import { InlineEditor } from "../lib/components/InlineEditor";
import { PieceFrame } from "../art-piece/PieceFrame";

export type SectionProps = {
  /** Stable handle. */
  id: string;
  title: string;
  subtitle?: string;
  /** `<ArtPiece>` children (authoring sugar). Ignored when `value` drives the board. */
  children?: ReactNode;
};

/**
 * Authoring marker for a section. Renders nothing on its own — `<ArtBoard>`
 * compiles `<ArtBoard.Section>` + `<ArtPiece>` children into the value. The
 * live section (titled head + horizontal piece row) is rendered by
 * `SectionView` from the controlled value.
 */
export function Section(_props: SectionProps): null {
  return null;
}
Section.displayName = "ArtBoard.Section";

/** The rendered section — head + horizontal row of piece frames in order. */
export function SectionView({ section }: { section: ArtSectionData }) {
  const board = useArtBoard();
  const order = section.pieces.map((p) => p.id);

  const patchTitle = (next: string) => {
    board.setSections((sections) =>
      sections.map((s) => (s.id === section.id ? { ...s, title: next } : s)),
    );
  };

  return (
    <div className="fa-section" data-fa-section={section.id}>
      <div className="fa-sectionhead-wrap">
        <div className="fa-sectionhead" data-fa-chrome="">
          <InlineEditor
            as="div"
            value={section.title}
            onChange={patchTitle}
            className="fa-sectiontitle"
          />
          {section.subtitle && <div className="fa-sectionsub">{section.subtitle}</div>}
        </div>
      </div>
      <div className="fa-row">
        {section.pieces.map((piece) => (
          <PieceFrame key={piece.id} sectionId={section.id} piece={piece} order={order} />
        ))}
      </div>
    </div>
  );
}

import {
  useCallback,
  useEffect,
  useRef,
  type CSSProperties,
  type ReactNode,
} from "react";
import type { Viewport } from "../lib/types";

type ViewportEngineProps = {
  viewport: Viewport;
  onViewportChange: (v: Viewport) => void;
  minZoom: number;
  maxZoom: number;
  children: ReactNode;
  className?: string;
  style?: CSSProperties;
};

const GRID_COLOR = "rgba(0,0,0,0.06)";
const gridSvg = `url("data:image/svg+xml,%3Csvg width='120' height='120' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M120 0H0v120' fill='none' stroke='${encodeURIComponent(
  GRID_COLOR,
)}' stroke-width='1'/%3E%3C/svg%3E")`;

/**
 * Transform-based pan/zoom engine (internal). Writes `translate3d(x,y,0)
 * scale(zoom)` straight to a DOM ref so wheel ticks bypass React; the
 * controlled `viewport` prop is the source of truth and `onViewportChange`
 * fires after each gesture frame.
 *
 * Input mapping (Figma-style):
 *   - trackpad pinch (ctrlKey wheel, non-integer delta) -> zoom
 *   - notched mouse wheel (integer |deltaY|>=40 or deltaMode!==0) -> stepped zoom
 *   - two-finger scroll -> pan
 *   - middle-drag / primary-drag on empty background -> pan
 *   - Safari gesturestart/change/end -> zoom
 *
 * Cursor-anchored zoom keeps the world point under the cursor fixed, then
 * cancels the vertical drift introduced by `--fa-inv-zoom`-driven reflow of
 * the section heads (CSS `zoom`) by re-pinning the DOM element under the
 * cursor.
 */
export function ViewportEngine({
  viewport,
  onViewportChange,
  minZoom,
  maxZoom,
  children,
  className,
  style,
}: ViewportEngineProps) {
  const vpRef = useRef<HTMLDivElement>(null);
  const worldRef = useRef<HTMLDivElement>(null);
  // Live transform state lives in a ref so high-frequency wheel/pointer events
  // don't round-trip through React. We mirror the controlled prop into it.
  const tf = useRef<Viewport>(viewport);
  const onChangeRef = useRef(onViewportChange);
  onChangeRef.current = onViewportChange;
  const limits = useRef({ minZoom, maxZoom });
  limits.current = { minZoom, maxZoom };

  // Write the live transform to the DOM + expose --fa-inv-zoom for chrome.
  const apply = useCallback(() => {
    const el = worldRef.current;
    if (!el) return;
    const { x, y, zoom } = tf.current;
    el.style.transform = `translate3d(${x}px, ${y}px, 0) scale(${zoom})`;
    el.style.setProperty("--fa-inv-zoom", String(1 / zoom));
  }, []);

  // Sync external (controlled) changes into the ref + DOM. Skip if the value
  // already matches what we wrote (our own gesture echo).
  useEffect(() => {
    const cur = tf.current;
    if (cur.x !== viewport.x || cur.y !== viewport.y || cur.zoom !== viewport.zoom) {
      tf.current = viewport;
      apply();
    }
  }, [viewport, apply]);

  // Initial paint.
  useEffect(() => {
    apply();
  }, [apply]);

  const commit = useCallback(() => {
    onChangeRef.current({ ...tf.current });
  }, []);

  useEffect(() => {
    const vp = vpRef.current;
    if (!vp) return;

    const zoomAt = (cx: number, cy: number, factor: number) => {
      const r = vp.getBoundingClientRect();
      const px = cx - r.left;
      const py = cy - r.top;
      const t = tf.current;
      const next = Math.min(limits.current.maxZoom, Math.max(limits.current.minZoom, t.zoom * factor));
      const k = next / t.zoom;

      // The `--fa-inv-zoom`-driven section heads (CSS `zoom`) reflow on every
      // scale change, shifting world layout vertically. Anchor the DOM element
      // under the cursor: record its screen-Y, apply, then cancel the drift.
      let marker: Element | null = null;
      let markerY0 = 0;
      if (k !== 1) {
        const hit = document.elementFromPoint(cx, cy);
        marker = hit ? hit.closest("[data-fa-piece],[data-fa-section]") : null;
        if (marker) markerY0 = marker.getBoundingClientRect().top;
      }

      // Keep the world point under the cursor fixed.
      t.x = px - (px - t.x) * k;
      t.y = py - (py - t.y) * k;
      t.zoom = next;
      apply();

      if (marker) {
        const drift = marker.getBoundingClientRect().top - (cy + (markerY0 - cy) * k);
        if (Math.abs(drift) > 0.1) {
          t.y -= drift;
          apply();
        }
      }
    };

    // Physical wheel vs trackpad-scroll heuristic.
    const isMouseWheel = (e: WheelEvent) =>
      e.deltaMode !== 0 ||
      (e.deltaX === 0 && Number.isInteger(e.deltaY) && Math.abs(e.deltaY) >= 40);

    let isGesturing = false;

    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      if (isGesturing) return; // Safari gesture* owns the pinch
      if ((e.ctrlKey || e.metaKey) && !isMouseWheel(e)) {
        zoomAt(e.clientX, e.clientY, Math.exp(-e.deltaY * 0.01));
      } else if (isMouseWheel(e)) {
        zoomAt(e.clientX, e.clientY, Math.exp(-Math.sign(e.deltaY) * 0.18));
      } else {
        tf.current.x -= e.deltaX;
        tf.current.y -= e.deltaY;
        apply();
      }
      commit();
    };

    // Safari native pinch.
    let gsBase = 1;
    const onGestureStart = (e: Event) => {
      e.preventDefault();
      isGesturing = true;
      gsBase = tf.current.zoom;
    };
    const onGestureChange = (e: Event) => {
      e.preventDefault();
      const ge = e as Event & { scale: number; clientX: number; clientY: number };
      zoomAt(ge.clientX, ge.clientY, (gsBase * ge.scale) / tf.current.zoom);
      commit();
    };
    const onGestureEnd = (e: Event) => {
      e.preventDefault();
      isGesturing = false;
      commit();
    };

    // Drag-pan: middle button anywhere, or primary on empty background.
    let drag: { id: number; lx: number; ly: number } | null = null;
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as Element;
      const onBg = !target.closest("[data-fa-piece], .fa-editable, [data-fa-chrome]");
      if (!(e.button === 1 || (e.button === 0 && onBg))) return;
      e.preventDefault();
      vp.setPointerCapture(e.pointerId);
      drag = { id: e.pointerId, lx: e.clientX, ly: e.clientY };
      vp.style.cursor = "grabbing";
    };
    const onPointerMove = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      tf.current.x += e.clientX - drag.lx;
      tf.current.y += e.clientY - drag.ly;
      drag.lx = e.clientX;
      drag.ly = e.clientY;
      apply();
    };
    const onPointerUp = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      vp.releasePointerCapture(e.pointerId);
      drag = null;
      vp.style.cursor = "";
      commit();
    };

    vp.addEventListener("wheel", onWheel, { passive: false });
    vp.addEventListener("gesturestart", onGestureStart as EventListener, { passive: false });
    vp.addEventListener("gesturechange", onGestureChange as EventListener, { passive: false });
    vp.addEventListener("gestureend", onGestureEnd as EventListener, { passive: false });
    vp.addEventListener("pointerdown", onPointerDown);
    vp.addEventListener("pointermove", onPointerMove);
    vp.addEventListener("pointerup", onPointerUp);
    vp.addEventListener("pointercancel", onPointerUp);
    return () => {
      vp.removeEventListener("wheel", onWheel);
      vp.removeEventListener("gesturestart", onGestureStart as EventListener);
      vp.removeEventListener("gesturechange", onGestureChange as EventListener);
      vp.removeEventListener("gestureend", onGestureEnd as EventListener);
      vp.removeEventListener("pointerdown", onPointerDown);
      vp.removeEventListener("pointermove", onPointerMove);
      vp.removeEventListener("pointerup", onPointerUp);
      vp.removeEventListener("pointercancel", onPointerUp);
    };
  }, [apply, commit]);

  return (
    <div ref={vpRef} className={"fa-viewport " + (className ?? "")} style={style}>
      <div ref={worldRef} className="fa-world">
        <div
          className="fa-grid"
          style={{ backgroundImage: gridSvg }}
          aria-hidden
        />
        {children}
      </div>
    </div>
  );
}

import { createContext, useContext, type ReactNode } from "react";
import type { ArtBoardValue, ArtSectionData } from "../lib/types";
import type { HtmlPolicy } from "../lib/html/policy";

/** Internal board context shared by Section / PieceFrame / FocusOverlay. */
export type ArtBoardCtx = {
  value: ArtBoardValue;
  /** JSX content for `kind:"node"` pieces, keyed by piece id. */
  nodes: Map<string, ReactNode>;
  /** Current scale (1/--fa-inv-zoom) — used by drag math to map screen px. */
  patchValue: (next: ArtBoardValue) => void;
  setSections: (fn: (sections: ArtSectionData[]) => ArtSectionData[]) => void;
  focus: string | null;
  setFocus: (pieceId: string | null) => void;
  onExport?: (pieceId: string, kind: "png" | "html") => void;
  /** Host-owned trust policy for agent-authored HTML. */
  htmlPolicy?: HtmlPolicy;
};

export const ArtBoardContext = createContext<ArtBoardCtx | null>(null);

export function useArtBoard(): ArtBoardCtx {
  const ctx = useContext(ArtBoardContext);
  if (!ctx) throw new Error("ArtBoard subcomponent used outside <ArtBoard>");
  return ctx;
}

import type { HtmlOrigin } from "./html/policy";

export type Viewport = { x: number; y: number; zoom: number };
export type ArtPieceContent =
  | { kind: "image"; src: string; alt?: string }
  | { kind: "html"; html: string }
  | { kind: "node" };
export type ArtPieceData = {
  id: string; label?: string; width?: number; height?: number;
  content: ArtPieceContent; pending?: boolean;
  /**
   * Who authored this piece. Drives the HTML trust policy together with
   * `pending`. Absent is treated as `"agent"` — the conservative assumption on
   * an open-world board, so unlabelled HTML is sanitised/sandboxed rather than
   * trusted.
   */
  origin?: HtmlOrigin;
};
export type ArtSectionData = { id: string; title: string; subtitle?: string; pieces: ArtPieceData[] };

/**
 * A free-floating note, as DATA.
 *
 * Notes existed only as React children, and `NoteProps` carried no id — so an
 * agent driving the board read every piece and was blind to every note: it
 * could not enumerate them, resolve one, or author one without emitting JSX.
 * That broke both halves of the component contract at once ("stable handles"
 * and "avoid forcing React children for things the agent must populate"), in a
 * package whose entire subject is a shared human+agent canvas.
 *
 * Mirrors {@link NoteProps} so a note round-trips between the two forms.
 */
export type ArtNoteData = {
  /** Stable handle. Rendered as `data-fa-note-id` so an agent never guesses DOM. */
  id: string;
  /** Note text. Named `text` rather than `value` because this is data, not a control. */
  text?: string;
  top?: number | string;
  left?: number | string;
  right?: number | string;
  bottom?: number | string;
  rotate?: number;
  width?: number | string;
  /** Paper colour — a react-fancy StickyNote preset or any CSS colour. */
  color?: string;
  /** Trust-but-verify: an agent-proposed note awaiting a human. */
  pending?: boolean;
};

export type ArtBoardValue = {
  sections: ArtSectionData[];
  /**
   * Optional so this is additive: a board written before notes were data still
   * type-checks, and the JSX-children form keeps working alongside it.
   */
  notes?: ArtNoteData[];
};

import { type ReactNode } from "react";
import { StickyNote } from "@particle-academy/react-fancy";

export type NoteProps = {
  /**
   * Stable handle. Rendered as `data-fa-note-id` so an agent can resolve this
   * note instead of guessing at the DOM — the contract's "stable handles"
   * clause, which this component previously failed.
   *
   * Optional so notes written before it existed keep working; they are simply
   * not addressable.
   */
  id?: string;
  top?: number | string;
  left?: number | string;
  right?: number | string;
  bottom?: number | string;
  rotate?: number;
  width?: number | string;
  /** Paper color — react-fancy StickyNote preset or any CSS color. */
  color?: string;
  /** Note text (controlled). */
  value?: string;
  onChange?: (text: string) => void;
  /** Static content; overrides editable text. */
  children?: ReactNode;
  editable?: boolean;
  selected?: boolean;
};

/**
 * Absolutely-positioned sticky note placed in the canvas world. The paper and
 * editable text are react-fancy's `<StickyNote>`; this wrapper owns position +
 * rotation (mirroring the reference DCPostIt).
 */
export function Note({
  id,
  top,
  left,
  right,
  bottom,
  rotate = -2,
  width = 180,
  color = "yellow",
  value,
  onChange,
  children,
  editable,
  selected,
}: NoteProps) {
  return (
    <div
      className="fa-note"
      data-fa-note=""
      data-fa-note-id={id}
      style={{ position: "absolute", top, left, right, bottom, zIndex: 5 }}
    >
      <StickyNote
        value={value}
        onChange={onChange}
        color={color}
        rotate={rotate}
        width={width}
        editable={editable ?? !children}
        selected={selected}
      >
        {children}
      </StickyNote>
    </div>
  );
}
Note.displayName = "ArtBoard.Note";

import { useEffect, useState } from "react";
import { Modal, Button, Dropdown } from "@particle-academy/react-fancy";
import type { ArtBoardValue, ArtPieceData, ArtSectionData } from "../../types";
import { useArtBoard } from "../../../artboard/context";
import { PolicyHtml } from "../../html/PolicyHtml";
import type { HtmlPolicy } from "../../html/policy";

const DEFAULT_W = 260;
const DEFAULT_H = 480;

/** Locate the focused piece + its section within the board value. */
function locate(value: ArtBoardValue, pieceId: string) {
  for (let s = 0; s < value.sections.length; s++) {
    const sec = value.sections[s];
    const p = sec.pieces.findIndex((piece) => piece.id === pieceId);
    if (p >= 0) return { sec, secIdx: s, piece: sec.pieces[p], pieceIdx: p };
  }
  return null;
}

/**
 * Full-screen focus overlay (driven by `focus`). Arrow nav: <- / -> within the
 * section, up / down across sections; a dots row + a section dropdown. Renders
 * through react-fancy's `<Modal size="full">` (its own portal).
 */
export function FocusOverlay() {
  const board = useArtBoard();
  const focusId = board.focus;
  const loc = focusId ? locate(board.value, focusId) : null;

  const [vp, setVp] = useState({ w: 1280, h: 800 });
  useEffect(() => {
    const r = () => setVp({ w: window.innerWidth, h: window.innerHeight });
    r();
    window.addEventListener("resize", r);
    return () => window.removeEventListener("resize", r);
  }, []);

  // Arrow navigation.
  useEffect(() => {
    if (!loc) return;
    const k = (e: KeyboardEvent) => {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        step(-1);
      } else if (e.key === "ArrowRight") {
        e.preventDefault();
        step(1);
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        stepSection(-1);
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        stepSection(1);
      }
    };
    document.addEventListener("keydown", k);
    return () => document.removeEventListener("keydown", k);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loc?.piece.id]);

  if (!loc) return null;
  const { sec, secIdx, piece, pieceIdx } = loc;
  const peers = sec.pieces;

  function step(d: number) {
    const next = peers[(pieceIdx + d + peers.length) % peers.length];
    if (next) board.setFocus(next.id);
  }
  function stepSection(d: number) {
    const sections = board.value.sections;
    const n = sections.length;
    for (let i = 1; i <= n; i++) {
      const ns = sections[(((secIdx + d * i) % n) + n) % n];
      if (ns.pieces[0]) {
        board.setFocus(ns.pieces[0].id);
        return;
      }
    }
  }

  const width = piece.width ?? DEFAULT_W;
  const height = piece.height ?? DEFAULT_H;
  const scale = Math.max(0.1, Math.min((vp.w - 200) / width, (vp.h - 260) / height, 2));

  const close = () => board.setFocus(null);

  return (
    <Modal open onClose={close} size="full" className="fa-focus">
      <div className="fa-focus-bar" data-fa-chrome="">
        <SectionPicker
          sections={board.value.sections}
          current={sec}
          onPick={(id) => board.setFocus(id)}
        />
        <div style={{ flex: 1 }} />
        <Button variant="ghost" icon="x" onClick={close} aria-label="Close focus" />
      </div>

      <div className="fa-focus-stage">
        <div
          className="fa-focus-card-wrap"
          style={{ width: width * scale, height: height * scale }}
        >
          <div
            className="fa-focus-card"
            style={{ width, height, transform: `scale(${scale})` }}
          >
            <FocusContent
              piece={piece}
              nodes={board.nodes}
              sectionId={sec.id}
              htmlPolicy={board.htmlPolicy}
            />
          </div>
        </div>
        <div className="fa-focus-caption">
          {piece.label ?? piece.id}
          <span className="fa-focus-index">
            {pieceIdx + 1} / {peers.length}
          </span>
        </div>
      </div>

      <Button
        variant="circle"
        icon="chevron-left"
        className="fa-focus-arrow fa-focus-arrow-left"
        onClick={() => step(-1)}
        aria-label="Previous"
      />
      <Button
        variant="circle"
        icon="chevron-right"
        className="fa-focus-arrow fa-focus-arrow-right"
        onClick={() => step(1)}
        aria-label="Next"
      />

      <div className="fa-focus-dots" data-fa-chrome="">
        {peers.map((p, i) => (
          <button
            key={p.id}
            type="button"
            className={"fa-focus-dot" + (i === pieceIdx ? " fa-focus-dot-on" : "")}
            onClick={() => board.setFocus(p.id)}
            aria-label={`Go to ${p.label ?? p.id}`}
          />
        ))}
      </div>
    </Modal>
  );
}

function FocusContent({
  piece,
  nodes,
  sectionId,
  htmlPolicy,
}: {
  piece: ArtPieceData;
  nodes: Map<string, React.ReactNode>;
  sectionId: string;
  htmlPolicy?: HtmlPolicy;
}) {
  const c = piece.content;
  if (c.kind === "image")
    return (
      <img
        src={c.src}
        alt={c.alt ?? piece.label ?? piece.id}
        style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
      />
    );
  if (c.kind === "html")
    return (
      <PolicyHtml
        html={c.html}
        policy={htmlPolicy}
        context={{
          pieceId: piece.id,
          sectionId,
          origin: piece.origin ?? "agent",
          reviewState: piece.pending ? "pending" : "accepted",
        }}
      />
    );
  return <>{nodes.get(piece.id) ?? null}</>;
}

function SectionPicker({
  sections,
  current,
  onPick,
}: {
  sections: ArtSectionData[];
  current: ArtSectionData;
  onPick: (firstPieceId: string) => void;
}) {
  const populated = sections.filter((s) => s.pieces.length > 0);
  return (
    <Dropdown placement="bottom-start">
      <Dropdown.Trigger>
        <button type="button" className="fa-focus-title">
          <span className="fa-focus-title-text">{current.title}</span>
          <svg width="11" height="11" viewBox="0 0 11 11" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden>
            <path d="M2 4l3.5 3.5L9 4" />
          </svg>
          {current.subtitle && <span className="fa-focus-subtitle">{current.subtitle}</span>}
        </button>
      </Dropdown.Trigger>
      <Dropdown.Items>
        {populated.map((s) => (
          <Dropdown.Item key={s.id} onClick={() => onPick(s.pieces[0].id)}>
            {s.title}
          </Dropdown.Item>
        ))}
      </Dropdown.Items>
    </Dropdown>
  );
}

/**
 * Host-owned trust policy for agent-authored HTML.
 *
 * ArtBoard is open-world: an agent can propose a piece whose content is raw
 * HTML. That HTML used to reach `dangerouslySetInnerHTML` untouched, and a live
 * probe confirmed script execution from an `<img onerror>` handler **while the
 * piece was still PROPOSED** — so "pending review" was visual state, not a
 * security boundary.
 *
 * The fix is not to close the world but to make trust an explicit decision the
 * HOST owns and content can never elevate:
 *
 *     effective mode = most restrictive of (host policy × origin × review state)
 *
 * Nothing in a payload selects its own mode.
 */

/** How a piece's HTML is allowed to render. Ordered least → most restrictive. */
export type HtmlRenderMode = "trusted" | "sanitize" | "sandbox" | "blocked";

/** Restrictiveness rank — higher wins when combining decisions. */
const RANK: Record<HtmlRenderMode, number> = {
  trusted: 0,
  sanitize: 1,
  sandbox: 2,
  blocked: 3,
};

/** Return whichever mode is more restrictive. */
export function mostRestrictive(a: HtmlRenderMode, b: HtmlRenderMode): HtmlRenderMode {
  return RANK[a] >= RANK[b] ? a : b;
}

export type HtmlOrigin = "host" | "human" | "agent" | "external";
export type HtmlReviewState = "pending" | "accepted";

export type HtmlPolicyContext = {
  pieceId: string;
  sectionId: string;
  origin: HtmlOrigin;
  reviewState: HtmlReviewState;
};

export type SanitizedHtmlResult = {
  html: string;
  /** What was stripped, so a human can see why the render differs. */
  removed: Array<{ kind: string; detail: string }>;
};

export type HtmlPolicyViolation = {
  context: HtmlPolicyContext;
  /** What tripped: a removed construct, or a limit that was exceeded. */
  kind: string;
  detail: string;
};

export type HtmlPolicyLimits = {
  maxBytes?: number;
  maxDepth?: number;
  maxNodes?: number;
};

export type HtmlPolicy = {
  /** Mode for content that a human has accepted. Default `sanitize`. */
  accepted?: HtmlRenderMode;
  /**
   * Mode for content still awaiting review. Default `sandbox`.
   * `trusted` is deliberately not assignable — unreviewed content can never
   * run with full privileges.
   */
  pending?: Exclude<HtmlRenderMode, "trusted">;
  /** Final say. Its result is still floored by the origin/review baseline. */
  resolve?: (context: HtmlPolicyContext) => HtmlRenderMode;
  /** Replace the built-in sanitizer. */
  sanitizer?: (html: string, context: HtmlPolicyContext) => SanitizedHtmlResult;
  onViolation?: (event: HtmlPolicyViolation) => void;
  limits?: HtmlPolicyLimits;
};

export const DEFAULT_LIMITS: Required<HtmlPolicyLimits> = {
  maxBytes: 512_000,
  maxDepth: 64,
  maxNodes: 5_000,
};

/**
 * The floor for a given origin + review state, before the host's policy applies.
 *
 * Host-authored content is the only thing that may be trusted outright, and
 * only once it is not pending. Unknown provenance is blocked rather than
 * guessed at.
 */
function baseline(context: HtmlPolicyContext): HtmlRenderMode {
  if (context.reviewState === "pending") return "sandbox";
  switch (context.origin) {
    case "host":
      return "trusted";
    case "human":
    case "agent":
      return "sanitize";
    case "external":
      return "sanitize";
    default:
      return "blocked";
  }
}

/**
 * Resolve the effective render mode.
 *
 * Every input can only tighten: the host's `resolve`/`accepted`/`pending`
 * choice is combined with the origin baseline via `mostRestrictive`, so a host
 * may harden its own content but a policy can never loosen what the origin
 * and review state already require.
 */
export function resolveHtmlMode(
  policy: HtmlPolicy | undefined,
  context: HtmlPolicyContext,
): HtmlRenderMode {
  const floor = baseline(context);

  const configured =
    context.reviewState === "pending"
      ? (policy?.pending ?? "sandbox")
      : (policy?.accepted ?? "sanitize");

  let mode = mostRestrictive(floor, configured);

  if (policy?.resolve) {
    // A resolver may tighten further, never loosen below the baseline.
    mode = mostRestrictive(mode, policy.resolve(context));
  }

  return mode;
}

const EVENT_ATTR = /^on/i;
const UNSAFE_URL = /^(javascript|vbscript|data):/i;
/**
 * Unsafe schemes anywhere in a CSS value — `background:url(javascript:…)` puts
 * the scheme mid-string, so this one is deliberately unanchored. `data:` is
 * left alone except for text/html, since data-URI images are ordinary in CSS.
 */
const UNSAFE_CSS = /(javascript|vbscript)\s*:|data\s*:\s*text\/html/i;

/**
 * Normalize a URL attribute before testing its scheme.
 *
 * Browsers ignore whitespace and control characters inside a scheme, so
 * `java\tscript:` and `java\nscript:` both execute. Strip them first, or the
 * anchored test above is trivially bypassed.
 */
function normalizeUrl(value: string): string {
  // Drop spaces, control characters and NBSP by code point. Written as a filter
  // rather than a regex character class so the literal control bytes never end
  // up in this source file.
  return Array.from(value)
    .filter((ch) => {
      const code = ch.charCodeAt(0);
      return code > 32 && code !== 127 && code !== 160;
    })
    .join("");
}
const BLOCKED_TAGS = new Set([
  "SCRIPT",
  "IFRAME",
  "OBJECT",
  "EMBED",
  "APPLET",
  "FORM",
  "BASE",
  "META",
  "LINK",
  "STYLE",
  "FOREIGNOBJECT",
]);
const URL_ATTRS = ["href", "src", "action", "formaction", "xlink:href", "poster", "background"];

/**
 * Built-in sanitizer: strips active content and reports what it removed.
 *
 * Deliberately implemented here rather than delegating to react-fancy's
 * `sanitizeHtml`, for two reasons — it must return a removal REPORT, and that
 * helper returns its input unchanged when `DOMParser` is unavailable, which
 * would silently pass raw agent HTML through during SSR. This one fails closed
 * instead (see `sanitizeHtmlWithReport`).
 */
export function sanitizeHtmlWithReport(html: string): SanitizedHtmlResult {
  const removed: SanitizedHtmlResult["removed"] = [];

  if (typeof DOMParser === "undefined") {
    // No parser (SSR / non-DOM runtime) means no way to make this safe. Emit
    // nothing rather than the raw string — failing closed is the whole point.
    return {
      html: "",
      removed: [{ kind: "unavailable", detail: "No DOMParser available; HTML withheld." }],
    };
  }

  // CodeQL flags this line as `js/html-constructed-from-input` (medium). It is a
  // FALSE POSITIVE, dismissed on the alert — recorded here because a dismissal in
  // GitHub's UI is invisible to anyone reading the code, and the next person to
  // see the warning deserves the reasoning rather than a rediscovery.
  //
  // `parseFromString(..., "text/html")` builds an INERT document: no script
  // executes, no resource is fetched, no side effect occurs. That is precisely
  // why it is the standard way to sanitize untrusted HTML, and it is the parse
  // step of the sanitizer — the walk below is what makes the output safe, and the
  // only consumer (`PolicyHtml`) passes the SANITIZED result to
  // `dangerouslySetInnerHTML`, never this input.
  //
  // CodeQL traces "library input -> HTML string -> parser" without modelling
  // either of those facts. If this ever stops being a sanitizer — if the parsed
  // document or the raw `html` reaches the DOM without the walk — the warning
  // becomes real and this comment is wrong.
  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");
  const body = doc.body;
  if (!body) return { html: "", removed: [{ kind: "unparsable", detail: "HTML could not be parsed." }] };

  const walk = (el: Element) => {
    for (const child of Array.from(el.children)) walk(child);

    if (BLOCKED_TAGS.has(el.tagName)) {
      removed.push({ kind: "element", detail: `<${el.tagName.toLowerCase()}>` });
      el.remove();
      return;
    }

    for (const attr of Array.from(el.attributes)) {
      const name = attr.name.toLowerCase();

      if (EVENT_ATTR.test(name)) {
        removed.push({ kind: "event-handler", detail: `${el.tagName.toLowerCase()}[${name}]` });
        el.removeAttribute(attr.name);
        continue;
      }

      if (URL_ATTRS.includes(name) && UNSAFE_URL.test(normalizeUrl(attr.value))) {
        removed.push({ kind: "unsafe-url", detail: `${name}="${attr.value.slice(0, 40)}"` });
        el.removeAttribute(attr.name);
        continue;
      }

      // url(javascript:…) and friends inside inline styles.
      if (name === "style" && UNSAFE_CSS.test(attr.value)) {
        removed.push({ kind: "unsafe-css", detail: "style contains an unsafe url()" });
        el.removeAttribute(attr.name);
      }
    }
  };

  for (const child of Array.from(body.children)) walk(child);

  return { html: body.innerHTML, removed };
}

/** Measure a document fragment against the configured limits. */
export function checkLimits(
  html: string,
  limits: HtmlPolicyLimits | undefined,
): { ok: boolean; violation?: { kind: string; detail: string } } {
  const merged = { ...DEFAULT_LIMITS, ...limits };

  const bytes = html.length;
  if (bytes > merged.maxBytes) {
    return { ok: false, violation: { kind: "limit", detail: `${bytes} bytes exceeds maxBytes ${merged.maxBytes}` } };
  }

  if (typeof DOMParser === "undefined") return { ok: true };

  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");
  const body = doc.body;
  if (!body) return { ok: true };

  let nodes = 0;
  let deepest = 0;
  const measure = (el: Element, depth: number) => {
    nodes++;
    if (depth > deepest) deepest = depth;
    for (const child of Array.from(el.children)) measure(child, depth + 1);
  };
  for (const child of Array.from(body.children)) measure(child, 1);

  if (nodes > merged.maxNodes) {
    return { ok: false, violation: { kind: "limit", detail: `${nodes} nodes exceeds maxNodes ${merged.maxNodes}` } };
  }
  if (deepest > merged.maxDepth) {
    return { ok: false, violation: { kind: "limit", detail: `depth ${deepest} exceeds maxDepth ${merged.maxDepth}` } };
  }
  return { ok: true };
}

import { type CSSProperties, type ElementType } from "react";
import { cx } from "../lib/cx";

export type InlineEditorProps = {
  value: string;
  onChange?: (value: string) => void;
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  onClick?: (e: React.MouseEvent) => void;
  title?: string;
};

/**
 * Tiny contentEditable inline editor — crisp under counter-scale. Commits on
 * blur or Enter; Escape reverts. Stops pointerdown so it doesn't initiate a
 * viewport pan or a grip drag.
 */
export function InlineEditor({
  value,
  onChange,
  as,
  className,
  style,
  onClick,
  title,
}: InlineEditorProps) {
  const Tag = (as || "span") as ElementType;
  return (
    <Tag
      className={cx("fa-editable", className)}
      contentEditable
      suppressContentEditableWarning
      spellCheck={false}
      title={title}
      onClick={onClick}
      onPointerDown={(e: React.PointerEvent) => e.stopPropagation()}
      onBlur={(e: React.FocusEvent<HTMLElement>) =>
        onChange?.(e.currentTarget.textContent ?? "")
      }
      onKeyDown={(e: React.KeyboardEvent<HTMLElement>) => {
        if (e.key === "Enter") {
          e.preventDefault();
          e.currentTarget.blur();
        } else if (e.key === "Escape") {
          e.preventDefault();
          e.currentTarget.textContent = value;
          e.currentTarget.blur();
        }
      }}
      style={style}
    >
      {value}
    </Tag>
  );
}

import { useMemo, type CSSProperties } from "react";
import {
  checkLimits,
  resolveHtmlMode,
  sanitizeHtmlWithReport,
  type HtmlPolicy,
  type HtmlPolicyContext,
} from "./policy";

/**
 * The one place agent-authored HTML is rendered.
 *
 * `PieceFrame` and `FocusOverlay` both used their own `dangerouslySetInnerHTML`
 * call, which is how the same hole existed twice. Both now render through this
 * component, so a policy change lands everywhere and neither surface can drift
 * back to raw output.
 */
export type PolicyHtmlProps = {
  html: string;
  policy?: HtmlPolicy;
  context: HtmlPolicyContext;
  style?: CSSProperties;
  className?: string;
};

const FILL: CSSProperties = { width: "100%", height: "100%" };

export function PolicyHtml({ html, policy, context, style, className }: PolicyHtmlProps) {
  const mode = resolveHtmlMode(policy, context);

  const resolved = useMemo(() => {
    if (mode === "blocked") return { html: "", removed: [], blocked: true as const };

    const limits = checkLimits(html, policy?.limits);
    if (!limits.ok) {
      policy?.onViolation?.({ context, kind: limits.violation!.kind, detail: limits.violation!.detail });
      return { html: "", removed: [limits.violation!], blocked: true as const };
    }

    if (mode === "trusted") return { html, removed: [], blocked: false as const };
    if (mode === "sandbox") return { html, removed: [], blocked: false as const };

    const result = policy?.sanitizer ? policy.sanitizer(html, context) : sanitizeHtmlWithReport(html);
    for (const item of result.removed) {
      policy?.onViolation?.({ context, kind: item.kind, detail: item.detail });
    }
    return { ...result, blocked: false as const };
    // `policy` identity churn would re-sanitize every render; the fields that
    // actually affect the output are the deps.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [html, mode, policy?.sanitizer, policy?.limits, context.pieceId, context.reviewState, context.origin]);

  const base = { ...FILL, ...style };

  if (resolved.blocked) {
    return (
      <div
        className={className}
        style={base}
        data-artboard-html-mode="blocked"
        data-artboard-html-blocked=""
      />
    );
  }

  if (mode === "sandbox") {
    // No allow-scripts and no allow-same-origin: the document is inert and
    // cannot reach this origin. This is what makes "pending" an actual boundary
    // rather than a label — unreviewed markup renders visually without ever
    // executing.
    return (
      <iframe
        className={className}
        style={{ ...base, border: 0, background: "transparent" }}
        sandbox=""
        srcDoc={resolved.html}
        title={`artboard-piece-${context.pieceId}`}
        data-artboard-html-mode="sandbox"
      />
    );
  }

  return (
    <div
      className={className}
      style={base}
      data-artboard-html-mode={mode}
      data-artboard-html-removed={resolved.removed.length || undefined}
      dangerouslySetInnerHTML={{ __html: resolved.html }}
    />
  );
}

// Tiny classnames join — no third-party deps (no clsx).
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

// Self-contained per-piece export. Clones the live DOM node with computed
// styles baked in, inlines @font-face / <img> / inline-style background-image
// urls as data URIs, then emits either a PNG (foreignObject -> canvas at 3x)
// or a standalone HTML document. Independent of viewport zoom.
//
// Rebuilt clean from the dirty reference's `dcExport` — no host coupling.

export type ExportKind = "png" | "html";

const toDataURL = (url: string): Promise<string> =>
  fetch(url)
    .then((r) => r.blob())
    .then(
      (b) =>
        new Promise<string>((res) => {
          const fr = new FileReader();
          fr.onload = () => res(String(fr.result));
          fr.onerror = () => res(url);
          fr.readAsDataURL(b);
        }),
    )
    .catch(() => url);

// Collect @font-face rules across all stylesheets. Cross-origin sheets throw
// SecurityError on .cssRules — fall back to fetching the CSS text directly and
// regex-extracting the blocks. @import / nested groups are walked.
async function collectFontCss(): Promise<string> {
  const fontRules: Array<{ css: string; base: string }> = [];
  const pending: Array<Promise<void>> = [];
  const seen = new Set<string>();

  const scrapeCss = (href: string) => {
    if (seen.has(href)) return;
    seen.add(href);
    pending.push(
      fetch(href)
        .then((r) => r.text())
        .then((css) => {
          for (const m of css.match(/@font-face\s*{[^}]*}/g) || [])
            fontRules.push({ css: m, base: href });
          for (const m of css.matchAll(/@import\s+(?:url\()?['"]?([^'")\s;]+)/g))
            scrapeCss(new URL(m[1], href).href);
        })
        .catch(() => {}),
    );
  };

  const walk = (rules: CSSRuleList, base: string) => {
    for (const r of Array.from(rules)) {
      if (r.type === CSSRule.FONT_FACE_RULE) {
        fontRules.push({ css: r.cssText, base });
      } else if (r.type === CSSRule.IMPORT_RULE && (r as CSSImportRule).styleSheet) {
        const sheet = (r as CSSImportRule).styleSheet as CSSStyleSheet;
        const ibase = sheet.href || base;
        try {
          walk(sheet.cssRules, ibase);
        } catch {
          scrapeCss(ibase);
        }
      } else if ((r as CSSGroupingRule).cssRules) {
        walk((r as CSSGroupingRule).cssRules, base);
      }
    }
  };

  for (const ss of Array.from(document.styleSheets)) {
    const base = ss.href || location.href;
    try {
      walk(ss.cssRules, base);
    } catch {
      if (ss.href) scrapeCss(ss.href);
    }
  }
  while (pending.length) await pending.shift();

  return (
    await Promise.all(
      fontRules.map(async (rule) => {
        let out = rule.css;
        const re = /url\((['"]?)([^'")]+)\1\)/g;
        let m: RegExpExecArray | null;
        while ((m = re.exec(rule.css))) {
          if (m[2].indexOf("data:") === 0) continue;
          let abs: string;
          try {
            abs = new URL(m[2], rule.base).href;
          } catch {
            continue;
          }
          out = out.split(m[0]).join('url("' + (await toDataURL(abs)) + '")');
        }
        return out;
      }),
    )
  ).join("\n");
}

// Deep clone with every computed style baked into an inline style attribute,
// canvases rasterized to <img>, scripts/comments dropped.
function cloneStyled(src: Node): Node {
  if (src.nodeType === 8 || (src.nodeType === 1 && (src as Element).tagName === "SCRIPT"))
    return document.createTextNode("");
  const dst = src.cloneNode(false);
  if (src.nodeType === 1) {
    const el = src as Element;
    const cs = getComputedStyle(el);
    let txt = "";
    for (let i = 0; i < cs.length; i++) txt += cs[i] + ":" + cs.getPropertyValue(cs[i]) + ";";
    (dst as Element).setAttribute("style", txt + "animation:none;transition:none;");
    if (el.tagName === "CANVAS") {
      try {
        const im = document.createElement("img");
        im.src = (el as HTMLCanvasElement).toDataURL();
        im.setAttribute("style", txt);
        return im;
      } catch {
        /* tainted canvas — fall through to the styled clone */
      }
    }
  }
  for (let c = src.firstChild; c; c = c.nextSibling) dst.appendChild(cloneStyled(c));
  return dst;
}

const triggerDownload = (blob: Blob | null, name: string, ext: string) => {
  if (!blob) return;
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = name + "." + ext;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
};

/**
 * Export a piece's content DOM node as a PNG or standalone HTML file.
 * @param node  the live element to capture (the piece content host)
 * @param w     natural width in px (artboard width)
 * @param h     natural height in px (artboard height)
 * @param name  download filename (sans extension)
 * @param kind  "png" | "html"
 */
export async function exportPiece(
  node: HTMLElement,
  w: number,
  h: number,
  name: string,
  kind: ExportKind,
): Promise<void> {
  try {
    await document.fonts.ready;
  } catch {
    /* fonts API may be unavailable */
  }
  const fontCss = await collectFontCss();

  const clone = cloneStyled(node) as HTMLElement;
  clone.setAttribute("xmlns", "http://www.w3.org/1999/xhtml");
  // Flush w x h rect — drop the frame's own shadow/radius.
  clone.style.boxShadow = "none";
  clone.style.borderRadius = "0";

  const jobs: Array<Promise<void>> = [];
  clone.querySelectorAll("img").forEach((el) => {
    const s = el.getAttribute("src");
    if (s && s.indexOf("data:") !== 0)
      jobs.push(toDataURL((el as HTMLImageElement).src).then((d) => el.setAttribute("src", d)));
  });
  [clone, ...Array.from(clone.querySelectorAll<HTMLElement>("*"))].forEach((el) => {
    const bg = el.style.backgroundImage;
    if (!bg) return;
    const re = /url\(["']?([^"')]+)["']?\)/g;
    let m: RegExpExecArray | null;
    while ((m = re.exec(bg))) {
      const tok = m[0];
      const url = m[1];
      if (url.indexOf("data:") === 0) continue;
      jobs.push(
        toDataURL(url).then((d) => {
          el.style.backgroundImage = el.style.backgroundImage.split(tok).join('url("' + d + '")');
        }),
      );
    }
  });
  await Promise.all(jobs);

  const xml = new XMLSerializer().serializeToString(clone);

  if (kind === "html") {
    const html =
      '<!doctype html><html><head><meta charset="utf-8"><title>' +
      name +
      "</title>" +
      (fontCss ? "<style>" + fontCss + "</style>" : "") +
      '</head><body style="margin:0">' +
      xml +
      "</body></html>";
    triggerDownload(new Blob([html], { type: "text/html" }), name, "html");
    return;
  }

  // PNG — the SVG's own width/height is the output resolution; viewBox maps the
  // w x h foreignObject onto the px*w x px*h canvas so the browser renders the
  // HTML at full resolution (not an upscaled 1x bitmap).
  const px = 3;
  const svg =
    '<svg xmlns="http://www.w3.org/2000/svg" width="' +
    w * px +
    '" height="' +
    h * px +
    '" viewBox="0 0 ' +
    w +
    " " +
    h +
    '"><foreignObject width="' +
    w +
    '" height="' +
    h +
    '">' +
    (fontCss ? "<style><![CDATA[" + fontCss + "]]></style>" : "") +
    xml +
    "</foreignObject></svg>";
  const img = new Image();
  await new Promise<void>((res, rej) => {
    img.onload = () => res();
    img.onerror = () => rej(new Error("svg load failed"));
    img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
  });
  const cv = document.createElement("canvas");
  cv.width = w * px;
  cv.height = h * px;
  cv.getContext("2d")?.drawImage(img, 0, 0);
  await new Promise<void>((res) => {
    cv.toBlob((blob) => {
      triggerDownload(blob, name, "png");
      res();
    }, "image/png");
  });
}

/** Sanitize a label/id into a safe download filename stem. */
export function exportName(label: string | undefined, id: string): string {
  return String(label || id || "artpiece").replace(/[^\w\s.-]+/g, "_");
}

