import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { forwardRef, useCallback, useEffect, useRef, useState } from "react";
import { cn } from "../lib/utils/cn";
import { Portal } from "../portal";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { useFloatingPosition } from "../lib/hooks/use-floating-position";
import { useOutsideClick } from "../lib/hooks/use-outside-click";
import { useEscapeKey } from "../lib/hooks/use-escape-key";
import { useFieldMode } from "../lib/components/inputs/mode/FieldMode.context";
import { useInlineEdit } from "../lib/components/inputs/mode/useInlineEdit";
import type { AutocompleteProps } from "./Autocomplete.types";

export const Autocomplete = forwardRef<HTMLInputElement, AutocompleteProps>(
  function Autocomplete(
    {
      value: controlledValue,
      defaultValue = "",
      onChange,
      onSearch,
      options,
      placeholder,
      loading = false,
      emptyMessage = "No results found.",
      disabled = false,
      className,
      mode,
    },
    ref,
  ) {
    const [value, setValue] = useControllableState(
      controlledValue,
      defaultValue,
      onChange,
    );
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
    const [query, setQuery] = useState(value);
    const [open, setOpen] = useState(false);
    const [activeIndex, setActiveIndex] = useState(-1);

    const anchorRef = useRef<HTMLInputElement>(null);
    const listRef = useRef<HTMLDivElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    const position = useFloatingPosition(anchorRef, listRef, {
      placement: "bottom-start",
      offset: 4,
      enabled: open,
    });

    const close = useCallback(() => {
      setOpen(false);
      setActiveIndex(-1);
    }, []);

    useOutsideClick(wrapperRef, close, open);
    useEscapeKey(close, open);

    const filtered = options.filter((o) =>
      o.label.toLowerCase().includes(query.toLowerCase()),
    );

    const select = useCallback(
      (val: string) => {
        setValue(val);
        const opt = options.find((o) => o.value === val);
        setQuery(opt?.label ?? val);
        close();
      },
      [setValue, options, close],
    );

    useEffect(() => {
      onSearch?.(query);
    }, [query, onSearch]);

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (!open) {
        if (e.key === "ArrowDown") {
          setOpen(true);
          return;
        }
        return;
      }

      if (e.key === "ArrowDown") {
        e.preventDefault();
        setActiveIndex((i) => Math.min(i + 1, filtered.length - 1));
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setActiveIndex((i) => Math.max(i - 1, 0));
      } else if (e.key === "Enter" && activeIndex >= 0) {
        e.preventDefault();
        const item = filtered[activeIndex];
        if (item && !item.disabled) select(item.value);
      }
    };

    if (!showControl) {
      const matched = options.find((o) => o.value === value);
      return (
        <div
          data-react-fancy-autocomplete=""
          data-mode="view"
          ref={wrapperRef}
          role={interactive ? "button" : undefined}
          tabIndex={interactive ? 0 : undefined}
          title={interactive ? "Click to edit" : undefined}
          onClick={interactive ? enterEdit : undefined}
          onKeyDown={
            interactive
              ? (e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    enterEdit();
                  }
                }
              : undefined
          }
          className={cn(
            "text-sm text-zinc-900 dark:text-zinc-100",
            !value && "text-zinc-400 dark:text-zinc-500",
            interactive &&
              "cursor-pointer rounded-md outline-none transition-colors hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-blue-500/40 dark:hover:bg-zinc-800",
            className,
          )}
        >
          {matched?.label ?? value ?? "—"}
        </div>
      );
    }

    return (
      <div
        data-react-fancy-autocomplete=""
        ref={wrapperRef}
        className={cn("relative", className)}
        onBlur={(e) => {
          // Options live in a Portal; only exit when closed and focus left.
          if (interactive && !open && !e.currentTarget.contains(e.relatedTarget as Node)) {
            exitEdit();
          }
        }}
      >
        <input
          ref={(node) => {
            (anchorRef as React.MutableRefObject<HTMLInputElement | null>).current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) (ref as React.MutableRefObject<HTMLInputElement | null>).current = node;
          }}
          type="text"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setOpen(true);
            setActiveIndex(-1);
          }}
          onFocus={() => setOpen(true)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          disabled={disabled}
          autoFocus={interactive}
          role="combobox"
          aria-expanded={open}
          aria-autocomplete="list"
          className="w-full rounded-lg border border-zinc-200 bg-white px-3 py-2 text-sm text-zinc-900 placeholder:text-zinc-400 outline-none transition-[border-color,box-shadow] duration-150 focus:border-blue-500 focus:ring-2 focus:ring-blue-500/40 dark:border-zinc-700 dark:bg-[#1e1e24] dark:text-zinc-100 dark:placeholder:text-zinc-500 dark:focus:border-blue-400 dark:focus:ring-blue-400/20"
        />
        {open && (
          <Portal>
            <div
              ref={listRef}
              role="listbox"
              className="fixed z-50 max-h-60 min-w-[8rem] overflow-y-auto rounded-xl border border-zinc-200 bg-white p-1 shadow-lg dark:border-zinc-700 dark:bg-zinc-900 dark:shadow-zinc-950/50 fancy-scale-in"
              style={{
                left: position.x,
                top: position.y,
                width: anchorRef.current?.offsetWidth,
              }}
            >
              {loading ? (
                <div className="px-3 py-2 text-sm text-zinc-400">Loading...</div>
              ) : filtered.length === 0 ? (
                <div className="px-3 py-2 text-sm text-zinc-400">
                  {emptyMessage}
                </div>
              ) : (
                filtered.map((option, i) => (
                  <button
                    key={option.value}
                    type="button"
                    role="option"
                    aria-selected={i === activeIndex}
                    disabled={option.disabled}
                    onClick={() => select(option.value)}
                    className={cn(
                      "flex w-full items-center rounded-lg px-3 py-2 text-left text-sm text-zinc-700 transition-colors dark:text-zinc-200",
                      i === activeIndex
                        ? "bg-zinc-100 dark:bg-zinc-800"
                        : "hover:bg-zinc-50 dark:hover:bg-zinc-800/50",
                      option.disabled && "cursor-not-allowed opacity-50",
                    )}
                  >
                    <HighlightMatch text={option.label} query={query} />
                  </button>
                ))
              )}
            </div>
          </Portal>
        )}
      </div>
    );
  },
);

function HighlightMatch({ text, query }: { text: string; query: string }) {
  if (!query) return <>{text}</>;

  const idx = text.toLowerCase().indexOf(query.toLowerCase());
  if (idx === -1) return <>{text}</>;

  return (
    <>
      {text.slice(0, idx)}
      <span className="font-semibold text-zinc-900 dark:text-white">
        {text.slice(idx, idx + query.length)}
      </span>
      {text.slice(idx + query.length)}
    </>
  );
}

