 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { createContext, useContext } from "react";
import type { CanvasContextValue } from "./Canvas.types";

export const CanvasContext = createContext<CanvasContextValue | null>(null);

export function useCanvas(): CanvasContextValue {
  const ctx = useContext(CanvasContext);
  if (!ctx) throw new Error("useCanvas must be used within a Canvas component");
  return ctx;
}

import type { ViewportState } from "../lib/hooks/use-pan-zoom";

/**
 * The CanvasEngine interface lets `<Canvas>` host any 3D backend alongside
 * its 2D pan/zoom surface.
 *
 * fancy-3d itself ships only the engine-agnostic core + the `dom` engine
 * (plain DOM / CSS3D). WebGL engines live in companion adapter packages:
 *
 *   - `@particle-academy/fancy-3d-babylon` for BabylonJS
 *   - (sibling packages can ship three.js, WebGPU, WebXR, etc.)
 *
 * Implement this interface to plug in any future spatial runtime. Pass the
 * implementation directly to `<Canvas engine={yourEngine}>`.
 */
export interface CanvasEngine {
  /** Identifier surfaced via {@link EngineHandle.name} for adapters that
   *  branch on engine type. */
  name: string;

  /**
   * Mount the engine onto a host element (the Canvas's outer container).
   * Called once when the Canvas mounts. Return an {@link EngineHandle} that
   * exposes the engine's scene root and lifecycle hooks.
   */
  mount(host: HTMLElement, viewport: ViewportState): EngineHandle;
}

export interface EngineHandle {
  /** Same as {@link CanvasEngine.name}. */
  name: string;
  /**
   * Engine-native scene root. Type is `unknown` because the shape varies per
   * engine — Babylon engines expose a `BABYLON.Scene`, three.js a `THREE.Scene`,
   * the `dom` engine the host `HTMLElement` itself.
   *
   * Adapter components that target a specific engine should narrow with
   * `if (engine?.name === "babylon") { const scene = engine.root as Scene; ... }`.
   */
  root: unknown;
  /**
   * Sync engine state from Canvas pan/zoom. For 2D engines this is the
   * `ViewportState` directly; 3D engines may map it to camera transforms or
   * (for MR) leave it as a no-op when 6DoF tracking owns viewport state.
   */
  updateViewport(viewport: ViewportState): void;
  /** Engine teardown on Canvas unmount. */
  dispose(): void;
}

/**
 * String shorthand for built-in engines. Only `"dom"` is currently built
 * into fancy-3d itself; pass a `CanvasEngine` object for any other backend
 * (e.g. `babylonEngine` from `@particle-academy/fancy-3d-babylon/engine`).
 */
export type CanvasEngineSpec = CanvasEngine | "dom";

import { useMemo, useRef, useEffect, useState, Children, type ReactElement } from "react";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { usePanZoom, type ViewportState } from "../lib/hooks/use-pan-zoom";
import { useNodeRegistry } from "../lib/hooks/use-node-registry";
import { CanvasContext } from "./Canvas.context";
import { CanvasNode } from "./CanvasNode";
import { CanvasEdge } from "./CanvasEdge";
import { CanvasMinimap } from "./CanvasMinimap";
import { CanvasControls } from "./CanvasControls";
import { domEngine } from "./engines/dom";
import type { CanvasEngine, CanvasEngineSpec, EngineHandle } from "./Canvas.engine";
import type { CanvasProps } from "./Canvas.types";

// fancy-3d ships only the engine-agnostic core + the DOM engine.
// WebGL engines live in companion packages (e.g. @particle-academy/fancy-3d-babylon)
// — import the engine from there and pass the object directly via <Canvas engine={...}>.
function resolveEngine(spec: CanvasEngineSpec | undefined): CanvasEngine {
  if (!spec || spec === "dom") return domEngine;
  return spec;
}

const DEFAULT_VIEWPORT: ViewportState = { panX: 0, panY: 0, zoom: 1 };

function CanvasRoot({
  children,
  viewport: controlledViewport,
  defaultViewport = DEFAULT_VIEWPORT,
  onViewportChange,
  minZoom = 0.1,
  maxZoom = 3,
  pannable = true,
  zoomable = true,
  showGrid = false,
  gridStyle = "dots",
  gridSize = 20,
  gridColor = "rgb(161 161 170 / 0.3)",
  snapToGrid = false,
  fitOnMount = false,
  engine: engineSpec,
  className,
  style,
}: CanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [viewport, setViewport] = useControllableState(controlledViewport, defaultViewport, onViewportChange);
  const { registerNode, unregisterNode, nodeRects, version: registryVersion } = useNodeRegistry();
  const [engineHandle, setEngineHandle] = useState<EngineHandle | null>(null);

  // Mount the chosen engine once per spec change. Default "dom" engine is a
  // no-op so this does not affect existing consumers.
  useEffect(() => {
    const host = containerRef.current;
    if (!host) return;
    const resolved = resolveEngine(engineSpec);
    let handle: EngineHandle | null = null;
    try {
      handle = resolved.mount(host, viewport);
      setEngineHandle(handle);
    } catch (err) {
      console.error(`[fancy-3d] Canvas engine "${resolved.name}" failed to mount:`, err);
      setEngineHandle(null);
    }
    return () => {
      try { handle?.dispose(); } catch (err) {
        console.error(`[fancy-3d] Canvas engine "${handle?.name}" failed to dispose:`, err);
      }
      setEngineHandle(null);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [engineSpec]);

  // Push viewport changes to the active engine so it can mirror pan/zoom.
  useEffect(() => {
    engineHandle?.updateViewport(viewport);
  }, [engineHandle, viewport]);

  const { containerProps } = usePanZoom({
    viewport,
    setViewport,
    minZoom,
    maxZoom,
    pannable,
    zoomable,
    containerRef,
  });

  const ctx = useMemo(
    () => ({ viewport, setViewport, registerNode, unregisterNode, nodeRects, registryVersion, containerRef, gridSize, snapToGrid, engine: engineHandle }),
    [viewport, setViewport, registerNode, unregisterNode, nodeRects, registryVersion, gridSize, snapToGrid, engineHandle],
  );

  // Auto-fit all nodes into view on mount once nodes are registered
  const hasFitted = useRef(false);
  useEffect(() => {
    if (!fitOnMount || hasFitted.current || nodeRects.size === 0) return;
    const container = containerRef.current;
    if (!container || container.clientWidth === 0) return;

    hasFitted.current = true;

    // Use rAF to ensure layout is settled before measuring
    requestAnimationFrame(() => {
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      nodeRects.forEach((r) => {
        minX = Math.min(minX, r.x);
        minY = Math.min(minY, r.y);
        maxX = Math.max(maxX, r.x + r.width);
        maxY = Math.max(maxY, r.y + r.height);
      });

      const padding = 40;
      const contentW = maxX - minX + padding * 2;
      const contentH = maxY - minY + padding * 2;
      const cw = container.clientWidth;
      const ch = container.clientHeight;
      const zoom = Math.min(cw / contentW, ch / contentH, 1.5);
      const panX = (cw - contentW * zoom) / 2 - minX * zoom + padding * zoom;
      const panY = (ch - contentH * zoom) / 2 - minY * zoom + padding * zoom;

      setViewport({ panX, panY, zoom });
    });
  }, [fitOnMount, nodeRects, registryVersion, setViewport]);

  // Separate edge children from node/other children
  const edges: ReactElement[] = [];
  const others: ReactElement[] = [];
  const overlays: ReactElement[] = []; // minimap, controls

  Children.forEach(children, (child) => {
    const el = child as ReactElement;
    if (!el || !el.type) return;
    const elType = el.type as any;
    if (elType === CanvasEdge || elType?._isCanvasEdge) {
      edges.push(el);
    } else if (elType === CanvasMinimap || elType === CanvasControls) {
      overlays.push(el);
    } else {
      others.push(el);
    }
  });

  return (
    <CanvasContext.Provider value={ctx}>
      <div
        ref={containerRef}
        data-react-fancy-canvas=""
        className={cn("relative overflow-hidden", className)}
        style={{ touchAction: "none", ...style }}
        {...containerProps}
      >
        {/* Background */}
        <div
          data-canvas-bg=""
          className="absolute inset-0"
          style={
            showGrid && gridStyle !== "none"
              ? gridStyle === "lines"
                ? {
                    backgroundImage: `linear-gradient(to right, ${gridColor} 1px, transparent 1px), linear-gradient(to bottom, ${gridColor} 1px, transparent 1px)`,
                    backgroundSize: `${gridSize * viewport.zoom}px ${gridSize * viewport.zoom}px`,
                    backgroundPosition: `${viewport.panX}px ${viewport.panY}px`,
                  }
                : {
                    backgroundImage: `radial-gradient(circle, ${gridColor} 1px, transparent 1px)`,
                    backgroundSize: `${gridSize * viewport.zoom}px ${gridSize * viewport.zoom}px`,
                    backgroundPosition: `${viewport.panX}px ${viewport.panY}px`,
                  }
              : undefined
          }
        />

        {/* Transformed layer for nodes */}
        <div
          className="absolute origin-top-left"
          style={{
            transform: `translate(${viewport.panX}px, ${viewport.panY}px) scale(${viewport.zoom})`,
          }}
        >
          {others}
        </div>

        {/* SVG layer for edges */}
        <svg
          className="pointer-events-none absolute inset-0 h-full w-full"
          style={{
            transform: `translate(${viewport.panX}px, ${viewport.panY}px) scale(${viewport.zoom})`,
            transformOrigin: "0 0",
          }}
        >
          <defs>
            {/* Generic markers */}
            <marker id="canvas-arrow" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="8" markerHeight="8" orient="auto">
              <path d="M0,0 L10,5 L0,10 Z" fill="#71717a" />
            </marker>
            <marker id="canvas-circle" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="8" markerHeight="8" orient="auto">
              <circle cx="5" cy="5" r="3.5" fill="#71717a" />
            </marker>
            <marker id="canvas-diamond" viewBox="0 0 12 12" refX="6" refY="6" markerWidth="10" markerHeight="10" orient="auto">
              <polygon points="6,0 12,6 6,12 0,6" fill="none" stroke="#71717a" strokeWidth="1.5" />
            </marker>

            {/* ERD: "one" perpendicular bar at path endpoint */}
            <marker id="canvas-one" viewBox="0 0 2 16" refX="1" refY="8" markerWidth="2" markerHeight="14" orient="auto">
              <line x1="1" y1="0" x2="1" y2="16" stroke="#71717a" strokeWidth="2" />
            </marker>

            {/* ERD: crow's foot at path endpoint — fork fans backward along the line */}
            {/* orient="auto" aligns x-axis with path direction at the endpoint.
                At markerEnd the path goes left→right into the entity.
                refX=16 places the rightmost edge at the endpoint (entity side).
                Fan lines go from right (x=16, entity) back-left into the line. */}
            <marker id="canvas-crow-foot" viewBox="0 0 16 16" refX="16" refY="8" markerWidth="14" markerHeight="14" orient="auto">
              <line x1="16" y1="8" x2="0" y2="0" stroke="#71717a" strokeWidth="2" strokeLinecap="round" />
              <line x1="16" y1="8" x2="0" y2="8" stroke="#71717a" strokeWidth="2" strokeLinecap="round" />
              <line x1="16" y1="8" x2="0" y2="16" stroke="#71717a" strokeWidth="2" strokeLinecap="round" />
              <line x1="16" y1="0" x2="16" y2="16" stroke="#71717a" strokeWidth="2" strokeLinecap="round" />
            </marker>
          </defs>
          {edges}
        </svg>

        {/* Overlays (minimap, controls) sit outside the transform */}
        {overlays}
      </div>
    </CanvasContext.Provider>
  );
}

export const Canvas = Object.assign(CanvasRoot, {
  Node: CanvasNode,
  Edge: CanvasEdge,
  Minimap: CanvasMinimap,
  Controls: CanvasControls,
});

import type { ReactNode, CSSProperties } from "react";
import type { ViewportState } from "../lib/hooks/use-pan-zoom";
import type { NodeRect } from "../lib/hooks/use-node-registry";
import type { CanvasEngineSpec, EngineHandle } from "./Canvas.engine";

export type { ViewportState } from "../lib/hooks/use-pan-zoom";
export type { CanvasEngine, CanvasEngineSpec, EngineHandle } from "./Canvas.engine";

export type EdgeAnchor = "top" | "bottom" | "left" | "right" | "center" | "auto";

export interface CanvasContextValue {
  viewport: ViewportState;
  setViewport: (vp: ViewportState | ((prev: ViewportState) => ViewportState)) => void;
  registerNode: (id: string, rect: NodeRect) => void;
  unregisterNode: (id: string) => void;
  nodeRects: Map<string, NodeRect>;
  registryVersion: number;
  containerRef: React.RefObject<HTMLDivElement | null>;
  /** Grid spacing in canvas-space pixels (unaffected by zoom). */
  gridSize: number;
  /** When true, dragged nodes snap their top-left corner to the grid. */
  snapToGrid: boolean;
  /** Active 3D engine, if any. `null` while the engine is mounting or when
   *  the Canvas was created without an engine prop. */
  engine: EngineHandle | null;
}

export type GridStyle = "dots" | "lines" | "none";

export interface CanvasProps {
  children: ReactNode;
  viewport?: ViewportState;
  defaultViewport?: ViewportState;
  onViewportChange?: (viewport: ViewportState) => void;
  minZoom?: number;
  maxZoom?: number;
  pannable?: boolean;
  zoomable?: boolean;
  /** Grid spacing in canvas-space pixels. Defaults to 20. */
  gridSize?: number;
  /** Show/hide the canvas grid. Defaults to false. */
  showGrid?: boolean;
  /** Grid pattern when shown — dots (default), lines, or none. Setting this
   *  to "none" hides the grid even when `showGrid` is true. */
  gridStyle?: GridStyle;
  /** Grid color (any CSS color). Defaults to a faint zinc. */
  gridColor?: string;
  /** Snap dragged nodes to the grid. Defaults to false. */
  snapToGrid?: boolean;
  /** Automatically fit all nodes into view on initial mount */
  fitOnMount?: boolean;
  /**
   * 3D engine to mount alongside the 2D canvas. Default `"dom"` (no extra
   * engine — plain DOM/CSS3D). For WebGL pass an engine object from a
   * companion adapter package, e.g.
   *
   *   import { babylonEngine } from "@particle-academy/fancy-3d-babylon/engine";
   *   <Canvas engine={babylonEngine} />
   *
   * Or implement `CanvasEngine` yourself for three.js, native canvas, WebXR,
   * etc. The active engine is exposed via `useCanvas().engine`.
   */
  engine?: CanvasEngineSpec;
  className?: string;
  style?: CSSProperties;
}

export interface CanvasNodeProps {
  children: ReactNode;
  id: string;
  x: number;
  y: number;
  /** Allow drag-to-move */
  draggable?: boolean;
  /** Called when the node is dragged to a new position */
  onPositionChange?: (x: number, y: number) => void;
  className?: string;
  style?: CSSProperties;
}

export interface CanvasEdgeProps {
  from: string;
  to: string;
  fromAnchor?: EdgeAnchor;
  toAnchor?: EdgeAnchor;
  curve?: "bezier" | "step" | "straight";
  color?: string;
  strokeWidth?: number;
  dashed?: boolean;
  animated?: boolean;
  label?: ReactNode;
  className?: string;
  markerStart?: string;
  markerEnd?: string;
}

export interface CanvasMinimapProps {
  width?: number;
  height?: number;
  className?: string;
}

export interface CanvasControlsProps {
  className?: string;
  showZoomIn?: boolean;
  showZoomOut?: boolean;
  showReset?: boolean;
  showFitAll?: boolean;
}

import { ZoomIn, ZoomOut, Maximize, RotateCcw } from "lucide-react";
import { cn } from "../lib/utils/cn";
import { useCanvas } from "./Canvas.context";
import type { CanvasControlsProps } from "./Canvas.types";

export function CanvasControls({
  className,
  showZoomIn = true,
  showZoomOut = true,
  showReset = true,
  showFitAll = true,
}: CanvasControlsProps) {
  const { setViewport, nodeRects, containerRef } = useCanvas();

  const zoomIn = () => setViewport((v) => ({ ...v, zoom: Math.min(3, v.zoom * 1.25) }));
  const zoomOut = () => setViewport((v) => ({ ...v, zoom: Math.max(0.1, v.zoom / 1.25) }));
  const reset = () => setViewport({ panX: 0, panY: 0, zoom: 1 });

  const fitAll = () => {
    const container = containerRef.current;
    if (!container || nodeRects.size === 0) return reset();

    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    nodeRects.forEach((r) => {
      minX = Math.min(minX, r.x);
      minY = Math.min(minY, r.y);
      maxX = Math.max(maxX, r.x + r.width);
      maxY = Math.max(maxY, r.y + r.height);
    });

    const padding = 40;
    const contentW = maxX - minX + padding * 2;
    const contentH = maxY - minY + padding * 2;
    const cw = container.clientWidth;
    const ch = container.clientHeight;
    const zoom = Math.min(cw / contentW, ch / contentH, 1.5);
    const panX = (cw - contentW * zoom) / 2 - minX * zoom + padding * zoom;
    const panY = (ch - contentH * zoom) / 2 - minY * zoom + padding * zoom;

    setViewport({ panX, panY, zoom });
  };

  const btnClass =
    "flex h-8 w-8 items-center justify-center rounded-md text-zinc-500 hover:bg-zinc-100 hover:text-zinc-700 dark:hover:bg-zinc-800 dark:hover:text-zinc-300 transition-colors";

  return (
    <div
      data-react-fancy-canvas-controls=""
      className={cn(
        "absolute bottom-3 left-3 flex gap-1 rounded-lg border border-zinc-200 bg-white/90 p-1 shadow-sm dark:border-zinc-700 dark:bg-zinc-900/90",
        className,
      )}
    >
      {showZoomIn && (
        <button type="button" onClick={zoomIn} className={btnClass} aria-label="Zoom in">
          <ZoomIn size={16} />
        </button>
      )}
      {showZoomOut && (
        <button type="button" onClick={zoomOut} className={btnClass} aria-label="Zoom out">
          <ZoomOut size={16} />
        </button>
      )}
      {showReset && (
        <button type="button" onClick={reset} className={btnClass} aria-label="Reset view">
          <RotateCcw size={16} />
        </button>
      )}
      {showFitAll && (
        <button type="button" onClick={fitAll} className={btnClass} aria-label="Fit all">
          <Maximize size={16} />
        </button>
      )}
    </div>
  );
}

CanvasControls.displayName = "CanvasControls";

import { useMemo } from "react";
import { cn } from "../lib/utils/cn";
import { useCanvas } from "./Canvas.context";
import { getAnchorPoint, getEdgePath } from "./canvas.utils";
import type { CanvasEdgeProps } from "./Canvas.types";

export function CanvasEdge({
  from,
  to,
  fromAnchor = "auto",
  toAnchor = "auto",
  curve = "bezier",
  color = "currentColor",
  strokeWidth = 2,
  dashed = false,
  animated = false,
  label,
  className,
  markerStart,
  markerEnd,
}: CanvasEdgeProps) {
  const { nodeRects, registryVersion } = useCanvas();

  const path = useMemo(() => {
    const fromRect = nodeRects.get(from);
    const toRect = nodeRects.get(to);
    if (!fromRect || !toRect) return null;

    const fromPt = getAnchorPoint(fromRect, fromAnchor, toRect);
    const toPt = getAnchorPoint(toRect, toAnchor, fromRect);
    return {
      d: getEdgePath(fromPt, toPt, curve),
      midX: (fromPt.x + toPt.x) / 2,
      midY: (fromPt.y + toPt.y) / 2,
    };
  }, [from, to, fromAnchor, toAnchor, curve, nodeRects, registryVersion]);

  if (!path) return null;

  return (
    <g data-react-fancy-canvas-edge="" className={cn("text-zinc-300 dark:text-zinc-600", className)}>
      <path
        d={path.d}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeDasharray={dashed ? "6 4" : undefined}
        markerStart={markerStart ? `url(#${markerStart})` : undefined}
        markerEnd={markerEnd ? `url(#${markerEnd})` : undefined}
        className={animated ? "animate-[dash_1s_linear_infinite]" : ""}
        style={animated ? { strokeDasharray: "8 4" } : undefined}
      />
      {label && (
        <foreignObject x={path.midX - 40} y={path.midY - 12} width={80} height={24}>
          <div className="flex items-center justify-center text-xs text-zinc-500">{label}</div>
        </foreignObject>
      )}
    </g>
  );
}

