import type { NodeRect } from "../lib/hooks/use-node-registry";
import type { EdgeAnchor } from "./Canvas.types";

export interface Point {
  x: number;
  y: number;
}

export function getAnchorPoint(rect: NodeRect, anchor: EdgeAnchor, otherRect?: NodeRect): Point {
  const cx = rect.x + rect.width / 2;
  const cy = rect.y + rect.height / 2;

  if (anchor === "auto" && otherRect) {
    const ocx = otherRect.x + otherRect.width / 2;
    const ocy = otherRect.y + otherRect.height / 2;
    const dx = ocx - cx;
    const dy = ocy - cy;

    if (Math.abs(dx) > Math.abs(dy)) {
      return dx > 0
        ? { x: rect.x + rect.width, y: cy }
        : { x: rect.x, y: cy };
    }
    return dy > 0
      ? { x: cx, y: rect.y + rect.height }
      : { x: cx, y: rect.y };
  }

  switch (anchor) {
    case "top": return { x: cx, y: rect.y };
    case "bottom": return { x: cx, y: rect.y + rect.height };
    case "left": return { x: rect.x, y: cy };
    case "right": return { x: rect.x + rect.width, y: cy };
    case "center": return { x: cx, y: cy };
    default: return { x: cx, y: cy };
  }
}

export function bezierPath(from: Point, to: Point): string {
  const dx = Math.abs(to.x - from.x);
  const dy = Math.abs(to.y - from.y);

  // Determine if the connection is more horizontal or vertical
  if (dx > dy) {
    // Horizontal: control points extend horizontally
    const offset = dx * 0.5;
    const cp1x = from.x + (to.x > from.x ? offset : -offset);
    const cp2x = to.x + (to.x > from.x ? -offset : offset);
    return `M${from.x},${from.y} C${cp1x},${from.y} ${cp2x},${to.y} ${to.x},${to.y}`;
  }
  // Vertical: control points extend vertically
  const offset = Math.max(dy * 0.5, 30);
  const cp1y = from.y + (to.y > from.y ? offset : -offset);
  const cp2y = to.y + (to.y > from.y ? -offset : offset);
  return `M${from.x},${from.y} C${from.x},${cp1y} ${to.x},${cp2y} ${to.x},${to.y}`;
}

export function stepPath(from: Point, to: Point): string {
  const midX = (from.x + to.x) / 2;
  return `M${from.x},${from.y} H${midX} V${to.y} H${to.x}`;
}

export function straightPath(from: Point, to: Point): string {
  return `M${from.x},${from.y} L${to.x},${to.y}`;
}

export function getEdgePath(
  from: Point,
  to: Point,
  curve: "bezier" | "step" | "straight" = "bezier",
): string {
  switch (curve) {
    case "bezier": return bezierPath(from, to);
    case "step": return stepPath(from, to);
    case "straight": return straightPath(from, to);
  }
}

export { Canvas } from "./Canvas";
export { useCanvas } from "./Canvas.context";
export type {
  CanvasProps,
  CanvasNodeProps,
  CanvasEdgeProps,
  CanvasMinimapProps,
  CanvasControlsProps,
  CanvasContextValue,
  ViewportState,
  EdgeAnchor,
  GridStyle,
  CanvasEngine,
  CanvasEngineSpec,
  EngineHandle,
} from "./Canvas.types";
export { domEngine } from "./engines/dom";

import type { CanvasEngine, EngineHandle } from "../Canvas.engine";
import type { ViewportState } from "../../lib/hooks/use-pan-zoom";

/**
 * Default engine — plain DOM with optional CSS3D `matrix3d` projection per
 * node, the approach `<Stage>`, `<Screen>`, and `<dom.tsx>` already use.
 *
 * It's a deliberate no-op: there's no extra runtime to mount because the
 * Canvas already renders DOM nodes inside a transformed wrapper. The handle
 * exposes the host element so adapters that target DOM (e.g. CSS3D overlays
 * for hybrid 2D-in-3D scenes) can attach to it.
 */
export const domEngine: CanvasEngine = {
  name: "dom",
  mount(host: HTMLElement, _viewport: ViewportState): EngineHandle {
    return {
      name: "dom",
      root: host,
      updateViewport: () => {},
      dispose: () => {},
    };
  },
};

import { useCallback, useEffect, useRef } from "react";

export interface ViewportState {
  panX: number;
  panY: number;
  zoom: number;
}

interface UsePanZoomOptions {
  viewport: ViewportState;
  setViewport: (vp: ViewportState | ((prev: ViewportState) => ViewportState)) => void;
  minZoom: number;
  maxZoom: number;
  pannable: boolean;
  zoomable: boolean;
  containerRef: React.RefObject<HTMLElement | null>;
}

interface UsePanZoomReturn {
  containerProps: {
    onPointerDown: (e: React.PointerEvent) => void;
    onPointerMove: (e: React.PointerEvent) => void;
    onPointerUp: (e: React.PointerEvent) => void;
  };
  isPanning: boolean;
}

export function usePanZoom({
  viewport,
  setViewport,
  minZoom,
  maxZoom,
  pannable,
  zoomable,
  containerRef,
}: UsePanZoomOptions): UsePanZoomReturn {
  const isPanningRef = useRef(false);
  const startRef = useRef({ x: 0, y: 0, panX: 0, panY: 0 });

  // Store latest values in refs so the native wheel listener always sees current state
  const viewportRef = useRef(viewport);
  viewportRef.current = viewport;
  const setViewportRef = useRef(setViewport);
  setViewportRef.current = setViewport;
  const zoomableRef = useRef(zoomable);
  zoomableRef.current = zoomable;
  const minZoomRef = useRef(minZoom);
  minZoomRef.current = minZoom;
  const maxZoomRef = useRef(maxZoom);
  maxZoomRef.current = maxZoom;

  // Attach a non-passive wheel listener so preventDefault() actually stops page scroll
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    function handleWheel(e: WheelEvent) {
      if (!zoomableRef.current) return;
      // Require Ctrl+wheel (or pinch gesture) to zoom — don't hijack normal page scroll
      if (!e.ctrlKey && !e.metaKey) return;
      e.preventDefault();

      const rect = container!.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      setViewportRef.current((prev) => {
        const factor = 1 - e.deltaY * 0.001;
        const newZoom = Math.min(maxZoomRef.current, Math.max(minZoomRef.current, prev.zoom * factor));
        const ratio = newZoom / prev.zoom;

        return {
          zoom: newZoom,
          panX: mouseX - (mouseX - prev.panX) * ratio,
          panY: mouseY - (mouseY - prev.panY) * ratio,
        };
      });
    }

    container.addEventListener("wheel", handleWheel, { passive: false });
    return () => {
      container.removeEventListener("wheel", handleWheel);
    };
  }, [containerRef]);

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (!pannable) return;
      // Only pan on primary button and when clicking the background
      if (e.button !== 0) return;
      const target = e.target as HTMLElement;
      if (target !== containerRef.current && !target.hasAttribute("data-canvas-bg")) return;

      isPanningRef.current = true;
      startRef.current = { x: e.clientX, y: e.clientY, panX: viewport.panX, panY: viewport.panY };
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      e.preventDefault();
    },
    [pannable, viewport.panX, viewport.panY, containerRef],
  );

  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isPanningRef.current) return;
      const dx = e.clientX - startRef.current.x;
      const dy = e.clientY - startRef.current.y;
      setViewport((prev) => ({
        ...prev,
        panX: startRef.current.panX + dx,
        panY: startRef.current.panY + dy,
      }));
    },
    [setViewport],
  );

  const onPointerUp = useCallback(() => {
    isPanningRef.current = false;
  }, []);

  return {
    containerProps: { onPointerDown, onPointerMove, onPointerUp },
    isPanning: isPanningRef.current,
  };
}

type ClassValue = string | number | boolean | undefined | null | ClassValue[] | { [key: string]: unknown };

function flatten(value: ClassValue): string {
  if (!value) return "";
  if (typeof value === "string" || typeof value === "number") return String(value);
  if (Array.isArray(value)) return value.map(flatten).filter(Boolean).join(" ");
  if (typeof value === "object") {
    return Object.entries(value)
      .filter(([, v]) => Boolean(v))
      .map(([k]) => k)
      .join(" ");
  }
  return "";
}

export function cn(...inputs: ClassValue[]): string {
  return inputs.map(flatten).filter(Boolean).join(" ");
}

import { useCallback, useRef, useState } from "react";

export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  const setValue = useCallback(
    (next: T | ((prev: T) => T)) => {
      const nextValue =
        typeof next === "function" ? (next as (prev: T) => T)(value) : next;

      if (!isControlled) {
        setUncontrolledValue(nextValue);
      }

      onChangeRef.current?.(nextValue);
    },
    [isControlled, value],
  );

  return [value, setValue];
}

import { useCallback, useRef, useState } from "react";

export interface NodeRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

interface UseNodeRegistryReturn {
  registerNode: (id: string, rect: NodeRect) => void;
  unregisterNode: (id: string) => void;
  nodeRects: Map<string, NodeRect>;
  version: number;
}

export function useNodeRegistry(): UseNodeRegistryReturn {
  const rectsRef = useRef(new Map<string, NodeRect>());
  const [version, setVersion] = useState(0);

  const registerNode = useCallback((id: string, rect: NodeRect) => {
    rectsRef.current.set(id, rect);
    setVersion((v) => v + 1);
  }, []);

  const unregisterNode = useCallback((id: string) => {
    rectsRef.current.delete(id);
    setVersion((v) => v + 1);
  }, []);

  return { registerNode, unregisterNode, nodeRects: rectsRef.current, version };
}

import type { CardPadding, CardSize } from "./Card.types";

/**
 * One table per thing a `size` or a `padding` step scales.
 *
 * They live together, and apart from the components, because four of them have
 * to agree: the card's own radius, `Card.Media`'s top radius, the inset a
 * `dividerInset` rule stops at, and the negative margin a `Card.Bleed` uses to
 * escape. Those last three are all derived from the PADDING step — get one
 * wrong and the mismatch is a few pixels, which is the kind of defect that
 * survives review and then looks like a browser bug.
 *
 * Radius is keyed by `size`; everything that has to line up with the padding is
 * keyed by the padding step. Those are NOT the same key: `size` only picks the
 * DEFAULT padding, and an explicit `padding` prop overrides it. Keying the
 * inset and the bleed off `size` made `<Card size="md" padding="lg">` draw a
 * rule inset by 1rem over content inset by 1.5rem, and `padding="none"` pull a
 * bleed clean outside the card.
 *
 * **`md` must stay byte-identical to what Card rendered before `size` existed**
 * (`rounded-lg`, `px-4`, `py-3`). `size` defaults to `md`, so that is what
 * makes this whole feature additive rather than a restyle of every consumer.
 */

export const paddingClasses: Record<CardPadding, string> = {
  none: "",
  xs: "[&>*]:px-2 [&>*]:py-1.5",
  sm: "[&>*]:px-3 [&>*]:py-2",
  md: "[&>*]:px-4 [&>*]:py-3",
  lg: "[&>*]:px-6 [&>*]:py-4",
};

/** The padding step a `size` implies when `padding` is not given. */
export const sizePadding: Record<CardSize, CardPadding> = {
  xs: "xs",
  sm: "sm",
  md: "md",
  lg: "lg",
};

export const radiusClasses: Record<CardSize, string> = {
  xs: "rounded",
  sm: "rounded-md",
  md: "rounded-lg",
  lg: "rounded-xl",
};

/** `rounded-t-*` / `rounded-b-*` counterparts, for media and bleed. */
export const radiusTop: Record<CardSize, string> = {
  xs: "rounded-t",
  sm: "rounded-t-md",
  md: "rounded-t-lg",
  lg: "rounded-t-xl",
};

export const radiusBottom: Record<CardSize, string> = {
  xs: "rounded-b",
  sm: "rounded-b-md",
  md: "rounded-b-lg",
  lg: "rounded-b-xl",
};

/** Padding a STANDALONE header/footer applies to itself, having no card. */
export const selfPadding: Record<CardPadding, string> = {
  none: "",
  xs: "px-2 py-1.5",
  sm: "px-3 py-2",
  md: "px-4 py-3",
  lg: "px-6 py-4",
};

/**
 * Where an inset divider stops — matches the horizontal padding step.
 *
 * Written out per variant rather than composed as `` `after:${insetX[step]}` ``.
 * **Tailwind generates CSS by scanning source for LITERAL class names**, so a
 * template string produces a class that exists in the DOM and in no stylesheet:
 * the divider silently does not render, and nothing in the build complains. The
 * duplication is the price of the scanner being a text search, and
 * `tests/card-tailwind.test.ts` compiles every one of these through Tailwind so
 * a typo cannot pass either.
 */
export const dividerInsetAfter: Record<CardPadding, string> = {
  none: "after:inset-x-0",
  xs: "after:inset-x-2",
  sm: "after:inset-x-3",
  md: "after:inset-x-4",
  lg: "after:inset-x-6",
};

export const dividerInsetBefore: Record<CardPadding, string> = {
  none: "before:inset-x-0",
  xs: "before:inset-x-2",
  sm: "before:inset-x-3",
  md: "before:inset-x-4",
  lg: "before:inset-x-6",
};

/**
 * Negative margins a nested `Card.Bleed` uses to reach the card's edges.
 *
 * `none` is empty on purpose: with no padding to escape, a negative margin
 * would drag the content OUT of the card rather than to its edge.
 */
export const bleedX: Record<CardPadding, string> = {
  none: "",
  xs: "-mx-2",
  sm: "-mx-3",
  md: "-mx-4",
  lg: "-mx-6",
};

export const bleedTop: Record<CardPadding, string> = {
  none: "",
  xs: "-mt-1.5",
  sm: "-mt-2",
  md: "-mt-3",
  lg: "-mt-4",
};

export const bleedBottom: Record<CardPadding, string> = {
  none: "",
  xs: "-mb-1.5",
  sm: "-mb-2",
  md: "-mb-3",
  lg: "-mb-4",
};

import { forwardRef, useMemo } from "react";
import { cn } from "../lib/utils/cn";
import { CardHeader } from "./CardHeader";
import { CardBody } from "./CardBody";
import { CardFooter } from "./CardFooter";
import { CardMedia } from "./CardMedia";
import { CardBleed } from "./CardBleed";
import { CardContext } from "./Card.context";
import { paddingClasses, radiusClasses, sizePadding } from "./Card.scales";
import type { CardContextValue, CardProps } from "./Card.types";

const variantClasses: Record<NonNullable<CardProps["variant"]>, string> = {
  outlined: "border border-zinc-200 dark:border-zinc-700",
  elevated: "shadow-md border border-zinc-100 dark:border-zinc-800",
  flat: "bg-zinc-50 dark:bg-zinc-800/50",
  // Tint steps between "no tint" and `flat`. They work the same way `flat`
  // does: a later `bg-*` in the class string beats the base `bg-white`, because
  // `cn` is tailwind-merge and resolves conflicting utilities last-wins. Class
  // ORDER decides this, not CSS specificity — so these must stay after the base
  // background in the `cn(...)` call below.
  muted: "bg-zinc-100 dark:bg-zinc-800",
  soft: "bg-zinc-50/70 dark:bg-zinc-800/40",
};

/**
 * Padding is applied to the card's DIRECT CHILDREN rather than the card
 * itself, so a full-bleed child (`Card.Media`) can opt out with `!px-0`
 * without having to undo a padding that is already baked into the frame.
 *
 * The selector is `&>*`, not `&>div`. It was `&>div` until 5.24.0, which meant
 * the tag a caller happened to choose silently decided whether that child was
 * padded: `<Card><div>a</div><p>b</p></Card>` inset the div and left the
 * paragraph hard against the border. Nothing in the caller's code hinted at
 * the rule, and the result read as a bug in the card.
 *
 * It is also why there is no `gap` to scale with `size`, which looks like an
 * omission and is not: each direct child carries its own `py-*`, so two
 * adjacent parts already have twice that between their content. Adding a row
 * gap on the card would double a space that is already there.
 */

const CardRoot = forwardRef<HTMLDivElement, CardProps>(
  (
    {
      variant = "outlined",
      size = "md",
      padding,
      sections = "divided",
      dividerInset = false,
      highlight = false,
      interactive = false,
      className,
      children,
      ...props
    },
    ref,
  ) => {
    // `padding` stays authoritative over the step `size` implies. That order is
    // what keeps `size` additive: a caller already passing `padding` sees no
    // change, and `padding="none"` still means none.
    const resolvedPadding = padding ?? sizePadding[size];

    // The RESOLVED step goes into the context, not `size`. A part that has to
    // meet the content's edge — an inset divider, a `Card.Bleed` — needs the
    // distance the card actually applied, and `size` is only the default.
    const context = useMemo<CardContextValue>(
      () => ({ size, padding: resolvedPadding, sections, dividerInset }),
      [size, resolvedPadding, sections, dividerInset],
    );

    return (
      <CardContext.Provider value={context}>
        <div
          ref={ref}
          data-react-fancy-card=""
          className={cn(
            "bg-white dark:bg-zinc-900",
            radiusClasses[size],
            variantClasses[variant],
            // A pseudo-element rather than an inset box-shadow: `shadow-*` and
            // `shadow-[inset...]` are the same tailwind-merge group, so an
            // inset shadow here would have SILENTLY DELETED `elevated`'s
            // `shadow-md`. Highlight and elevation have to be able to coexist.
            // `dark:` carries a REAL colour. It was `dark:before:bg-transparent`,
            // which made `highlight` a no-op in the mode that needs it most:
            // a dark surface has no border contrast of its own, and a 10% white
            // top edge is the whole reason Flux turns this on by default.
            highlight &&
              "relative before:pointer-events-none before:absolute before:inset-x-0 before:top-0 before:h-px before:bg-white/70 dark:before:bg-white/10",
            // `overflow-hidden` is part of `interactive` rather than always-on:
            // clipping unconditionally would cut off popovers and dropdowns that
            // legitimately overflow a static card.
            interactive &&
              "overflow-hidden transition hover:-translate-y-0.5 hover:shadow-lg hover:border-zinc-300 dark:hover:border-zinc-600",
            paddingClasses[resolvedPadding],
            className,
          )}
          {...props}
        >
          {children}
        </div>
      </CardContext.Provider>
    );
  },
);

CardRoot.displayName = "Card";

export const Card = Object.assign(CardRoot, {
  Media: CardMedia,
  Header: CardHeader,
  Body: CardBody,
  Footer: CardFooter,
  Bleed: CardBleed,
});

import type { HTMLAttributes, ReactNode } from "react";

/** Scales the card's padding and its corner radius. */
export type CardSize = "xs" | "sm" | "md" | "lg";

/**
 * The inset applied to the card's direct children.
 *
 * Separate from `CardSize` because they are separate keys: `size` only picks
 * the DEFAULT step, and `padding` overrides it. Anything that has to line up
 * with the content's edge — an inset divider, a `Card.Bleed` — is keyed by this
 * and never by `size`.
 */
export type CardPadding = "none" | "xs" | "sm" | "md" | "lg";

/**
 * How `Card.Header` / `Card.Body` / `Card.Footer` are set apart.
 *
 * `"divided"` is the default because it is what Card has always rendered.
 * Seamless is arguably the nicer default — it is what Flux chose — but making
 * it the default here would have silently restyled every card in every
 * consumer, which is not a thing a minor release may do.
 */
export type CardSections = "divided" | "plain" | "banded";

/** Which of the card's edges a `Card.Bleed` reaches. */
export type CardBleedEdges = "x" | "top" | "bottom" | "all";

export interface CardContextValue {
  size: CardSize;
  /**
   * The step the card ACTUALLY pads its children by, after `padding` has had
   * its say over `size`. Parts that must meet the content's edge read this.
   */
  padding: CardPadding;
  sections: CardSections;
  dividerInset: boolean;
}

export interface CardProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The card's surface. `muted` and `soft` are tint steps between `outlined`
   * (no tint) and `flat`.
   */
  variant?: "outlined" | "elevated" | "flat" | "muted" | "soft";
  /**
   * Padding on the card's direct children. Defaults to the step implied by
   * `size`; pass it to override that, including `"none"`.
   */
  padding?: CardPadding;
  /** Scales padding and corner radius together. Default `"md"`. */
  size?: CardSize;
  /** How the header, body and footer are separated. Default `"divided"`. */
  sections?: CardSections;
  /**
   * With `sections="divided"`, stop the rules at the content's edge instead of
   * running them across the card.
   */
  dividerInset?: boolean;
  /**
   * A faint hairline along the inside of the top edge — white at 70% in light
   * mode, white at 10% in dark, so a tinted or elevated surface reads as lit
   * from above in both.
   *
   * Default `false`, deliberately unlike Flux's `true` — flipping a decorative
   * hairline on by default would change the appearance of every existing card.
   */
  highlight?: boolean;
  /**
   * Card is a link or a grid tile: adds the hover lift + border/shadow
   * response, and clips children to the rounded corners so a `Card.Media`
   * sits flush.
   */
  interactive?: boolean;
}

export interface CardMediaProps extends HTMLAttributes<HTMLDivElement> {
  /** Image URL. Omit for a pure colour/gradient tile. */
  src?: string;
  alt?: string;
  /** CSS `aspect-ratio`. Default `"16/9"`. Ignored when `height` is set. */
  ratio?: string;
  /** Fixed height instead of an aspect ratio. */
  height?: number | string;
  /**
   * Shown UNDER the image — while it loads, and permanently if it never
   * arrives. Any CSS background value, so a gradient works.
   */
  background?: string;
  /** `object-position` for the image. Default `"center"`. */
  objectPosition?: string;
  loading?: "lazy" | "eager";
  /** Slots pinned to the media's corners — a number chip, a status pill. */
  topLeft?: ReactNode;
  topRight?: ReactNode;
  bottomLeft?: ReactNode;
  bottomRight?: ReactNode;
}

/**
 * Shared by `Card.Header` and `Card.Footer`.
 *
 * `heading` / `description` / `actions` exist so the common header does not
 * need a layout wrapper from the caller. Two pages in this suite's own showcase
 * were writing `<div style={{ display: "flex", justifyContent: "space-between"
 * }}>` INSIDE a `Card.Header` — inline styles, in the app whose job is to
 * demonstrate the kit. 136 headers there, and nothing in the kit laid one out.
 *
 * `children` is the escape hatch and it WINS: pass it and the three props are
 * ignored rather than rendered alongside, so a caller who sets both gets one
 * title instead of two.
 */
export interface CardSectionProps extends HTMLAttributes<HTMLDivElement> {
  /** The title. Rendered through `<Heading>`. */
  heading?: ReactNode;
  /** Which heading element to render. Default `"h3"`. */
  headingLevel?: "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
  /** Supporting line under the heading. Rendered through muted `<Text>`. */
  description?: ReactNode;
  /** Controls pushed to the far end, vertically centred on the heading. */
  actions?: ReactNode;
  /**
   * Only used when there is no `Card` above this — a standalone header takes
   * its own size, because there is no card to inherit one from.
   */
  size?: CardSize;
  /** Full control. Replaces heading/description/actions, keeps the frame. */
  children?: ReactNode;
}

export interface CardHeaderProps extends CardSectionProps {}

export interface CardFooterProps extends CardSectionProps {}

export interface CardBodyProps extends HTMLAttributes<HTMLDivElement> {}

export interface CardBleedProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Which card edges to reach. Default `"x"` — the sides only, which is what
   * an inline image or table wants.
   */
  edges?: CardBleedEdges;
}

import { forwardRef } from "react";
import { cn } from "../lib/utils/cn";
import { useCardContext, useCardSectionPadding } from "./Card.context";
import { bleedBottom, bleedTop, bleedX, radiusBottom, radiusTop } from "./Card.scales";
import type { CardBleedProps } from "./Card.types";

/**
 * Run content out to the card's edges — an image, a table, a chart strip.
 *
 * ## Why this is arithmetic and not a CSS-variable protocol
 *
 * Flux solves the same problem with a published set of custom properties
 * (`--flux-bleed-x`, `--flux-bleed-top`, …) that any child component may read.
 * It has to: its padding sits on the CARD, so a descendant has no way to know
 * how far it must reach. That is a public CSS API — a cross-package contract to
 * version forever.
 *
 * Ours does not need one, because padding sits on the card's direct CHILDREN.
 * The distance to the edge is therefore always one padding step, which the
 * padded section passes down in context. No variables, nothing for a consumer
 * to depend on, nothing to keep stable across releases.
 *
 * ## Two cases, and they are opposites
 *
 * - **Inside a `Card.Header` / `Card.Body` / `Card.Footer`** (the normal case):
 *   the padding is on that section, so reaching the edge is a NEGATIVE MARGIN.
 * - **As a direct child of `Card`**: the padding is on this element, so
 *   reaching the edge is ZEROING it. A negative margin here would pull the
 *   content clean outside the card.
 *
 * A component cannot see its own depth, so the sections publish their padding
 * step in context and its absence means "you are the padded element". Both
 * cases read as "cancel the padding", which is exactly why picking either one
 * alone ships looking correct in whichever demo the author happened to write.
 *
 * The distance comes from that context and NOT from the card's `size`, because
 * the two disagree whenever `padding` is passed explicitly — and disagree by a
 * whole step, which looks like a rendering bug rather than a prop conflict.
 *
 * Corners are rounded only where the content actually meets the card's edge, so
 * a mid-body strip stays square while one at the top follows the card's radius.
 */
export const CardBleed = forwardRef<HTMLDivElement, CardBleedProps>(
  ({ edges = "x", className, children, ...props }, ref) => {
    const card = useCardContext();
    const section = useCardSectionPadding();
    // Radius follows the CARD (that is whose corners are being met); the
    // distance follows the PADDING.
    const size = card?.size ?? "md";

    const touchesTop = edges === "top" || edges === "all";
    const touchesBottom = edges === "bottom" || edges === "all";

    return (
      <div
        ref={ref}
        data-react-fancy-card-bleed=""
        className={cn(
          // Clip children to whatever corners we round, or an image's square
          // edge sits over the card's curve.
          "overflow-hidden",
          section !== null
            ? cn(
                bleedX[section],
                touchesTop && bleedTop[section],
                touchesBottom && bleedBottom[section],
              )
            : // Direct child of the card: `!` because the padding it is undoing
              // comes from the card's own `[&>*]` rule, which is equally
              // specific. Same mechanism `Card.Media` uses.
              cn(
                "!px-0",
                touchesTop && "!pt-0",
                touchesBottom && "!pb-0",
              ),
          touchesTop && radiusTop[size],
          touchesBottom && radiusBottom[size],
          className,
        )}
        {...props}
      >
        {children}
      </div>
    );
  },
);

CardBleed.displayName = "CardBleed";

import { forwardRef } from "react";
import { cn } from "../lib/utils/cn";
import { CardSectionContext, useCardContext } from "./Card.context";
import type { CardBodyProps } from "./Card.types";

export const CardBody = forwardRef<HTMLDivElement, CardBodyProps>(
  ({ className, children, ...props }, ref) => {
    // The step the CARD pads this element by. `"none"` with no card above,
    // because then nothing pads it and there is nothing for a nested
    // `Card.Bleed` to escape.
    const padding = useCardContext()?.padding ?? "none";

    return (
      <div
        ref={ref}
        data-react-fancy-card-body=""
        className={cn(className)}
        {...props}
      >
        {/*
          Body carries no classes of its own -- the card pads it through
          `[&>*]`, and giving it padding here would double that. The context is
          the only thing it adds: it tells a nested `Card.Bleed` that the
          padding to escape is on THIS element, and how much of it there is.
        */}
        <CardSectionContext.Provider value={padding}>{children}</CardSectionContext.Provider>
      </div>
    );
  },
);

CardBody.displayName = "CardBody";

import { forwardRef } from "react";
import { CardSection } from "./CardSection";
import type { CardFooterProps } from "./Card.types";

/**
 * A card's footer. Its rule sits on the TOP edge, and a lone `actions` block
