import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { createContext, useContext } from "react";
import type { CarouselContextValue } from "./Carousel.types";

export const CarouselContext = createContext<CarouselContextValue | null>(null);
CarouselContext.displayName = "CarouselContext";

export function useCarousel(): CarouselContextValue {
  const ctx = useContext(CarouselContext);
  if (!ctx) {
    throw new Error("Carousel compound components must be used within <Carousel>");
  }
  return ctx;
}

import { forwardRef, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { CarouselContext } from "./Carousel.context";
import { CarouselPanels } from "./CarouselPanels";
import { CarouselSlide } from "./CarouselSlide";
import { CarouselControls } from "./CarouselControls";
import { CarouselSteps } from "./CarouselSteps";
import type { CarouselProps, CarouselContextValue } from "./Carousel.types";

const CarouselRoot = forwardRef<HTMLDivElement, CarouselProps>(
  (
    {
      children,
      defaultIndex = 0,
      activeIndex: controlledIndex,
      onIndexChange,
      className,
      autoPlay = false,
      interval = 5000,
      loop = false,
      variant = "directional",
      headless = false,
      onFinish,
    },
    ref,
  ) => {
    const [activeIndex, setActiveIndex] = useControllableState<number>(
      controlledIndex,
      defaultIndex,
      onIndexChange,
    );
    const [totalSlides, setTotalSlides] = useState(0);
    const [slideNames, setSlideNames] = useState<string[]>([]);
    const [isPaused, setIsPaused] = useState(false);
    const onFinishRef = useRef(onFinish);
    onFinishRef.current = onFinish;

    const registerSlides = useCallback((count: number) => {
      setTotalSlides(count);
    }, []);

    const registerSlideNames = useCallback((names: string[]) => {
      setSlideNames(names);
    }, []);

    const next = useCallback(() => {
      setActiveIndex((i: number) => {
        if (i >= totalSlides - 1) {
          return loop ? 0 : i;
        }
        return i + 1;
      });
    }, [totalSlides, loop, setActiveIndex]);

    const prev = useCallback(() => {
      setActiveIndex((i: number) => {
        if (i <= 0) {
          return loop ? totalSlides - 1 : i;
        }
        return i - 1;
      });
    }, [totalSlides, loop, setActiveIndex]);

    const goTo = useCallback(
      (index: number) => setActiveIndex(index),
      [setActiveIndex],
    );

    // AutoPlay
    useEffect(() => {
      if (!autoPlay || isPaused || totalSlides <= 1) {
        return;
      }

      const id = setInterval(() => {
        setActiveIndex((i: number) => {
          if (i >= totalSlides - 1) {
            return loop ? 0 : i;
          }
          return i + 1;
        });
      }, interval);

      return () => clearInterval(id);
    }, [autoPlay, interval, isPaused, totalSlides, loop, setActiveIndex]);

    const ctx = useMemo<CarouselContextValue>(
      () => ({
        activeIndex,
        totalSlides,
        next,
        prev,
        goTo,
        registerSlides,
        variant,
        loop,
        slideNames,
        registerSlideNames,
        onFinish: onFinishRef.current,
        headless,
      }),
      [
        activeIndex,
        totalSlides,
        next,
        prev,
        goTo,
        registerSlides,
        variant,
        loop,
        slideNames,
        registerSlideNames,
        headless,
      ],
    );

    const handleMouseEnter = useCallback(() => {
      if (autoPlay) {
        setIsPaused(true);
      }
    }, [autoPlay]);

    const handleMouseLeave = useCallback(() => {
      if (autoPlay) {
        setIsPaused(false);
      }
    }, [autoPlay]);

    return (
      <CarouselContext.Provider value={ctx}>
        <div
          data-react-fancy-carousel=""
          ref={ref}
          className={cn("relative", className)}
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
        >
          {children}
        </div>
      </CarouselContext.Provider>
    );
  },
);

CarouselRoot.displayName = "Carousel";

