import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import type { ReactNode } from "react";
import { Button, Callout, cn } from "@particle-academy/react-fancy";
import type { Entitlements } from "./types";

export type FeatureGateMode = "replace" | "blur" | "hide";

export interface FeatureGateProps {
  /** Feature key to check in `entitlements`. */
  feature: string;
  /** The viewer's entitlements (from your FMS check). */
  entitlements: Entitlements;
  /** Human label for the locked prompt (defaults to the feature key). */
  featureName?: string;
  children: ReactNode;
  /**
   * How to render when locked: `replace` (default) swaps in an upgrade prompt,
   * `blur` overlays the (blurred) children, `hide` renders `fallback` or nothing.
   */
  mode?: FeatureGateMode;
  /** Custom locked UI — overrides the built-in prompt. Receives the reason. */
  renderLocked?: (reason: LockedReason) => ReactNode;
  /** Rendered when `mode="hide"` and locked. */
  fallback?: ReactNode;
  /** CTA on the built-in prompt. */
  onUpgrade?: () => void;
  upgradeHref?: string;
  upgradeLabel?: string;
  className?: string;
}

export type LockedReason =
  | { kind: "no-access" }
  | { kind: "quota"; used: number; limit: number };

/** Resolve whether a feature is currently usable (access + quota). */
export function gateStatus(
  entitlements: Entitlements,
  feature: string,
): { unlocked: boolean; reason: LockedReason | null } {
  const ent = entitlements.features[feature];
  if (!ent || !ent.access) return { unlocked: false, reason: { kind: "no-access" } };
  // Resource quota: if a finite limit + usage are known, enforce it.
  if (ent.limit != null && ent.used != null && ent.used >= ent.limit) {
    return { unlocked: false, reason: { kind: "quota", used: ent.used, limit: ent.limit } };
  }
  return { unlocked: true, reason: null };
}

/**
 * Gate UI behind an FMS feature entitlement. When the viewer has access (and
 * any resource quota remains) it renders `children`; otherwise it shows an
 * upgrade prompt (or blurs / hides, per `mode`). Pure + controlled: you supply
 * `entitlements` from your own FMS check.
 */
export function FeatureGate({
  feature,
  entitlements,
  featureName,
  children,
  mode = "replace",
  renderLocked,
  fallback,
  onUpgrade,
  upgradeHref,
  upgradeLabel = "Upgrade",
  className,
}: FeatureGateProps) {
  const { unlocked, reason } = gateStatus(entitlements, feature);
  if (unlocked) return <>{children}</>;

  if (mode === "hide") return <>{fallback ?? null}</>;

  const name = featureName ?? feature;
  const locked = renderLocked?.(reason!) ?? (
    <Callout
      color={reason?.kind === "quota" ? "amber" : "blue"}
      className={cn("flex flex-col items-start gap-2", className)}
    >
      <div className="font-medium">
        {reason?.kind === "quota"
          ? `You've reached your ${name} limit (${reason.used}/${reason.limit}).`
          : `${name} is not included in your plan.`}
      </div>
      <p className="text-sm opacity-80">
        {reason?.kind === "quota"
          ? "Upgrade for a higher limit."
          : `Upgrade to unlock ${name}.`}
      </p>
      {(onUpgrade || upgradeHref) &&
        (upgradeHref ? (
          <a href={upgradeHref}>
            <Button color="blue" size="sm">
              {upgradeLabel}
            </Button>
          </a>
        ) : (
          <Button color="blue" size="sm" onClick={onUpgrade}>
            {upgradeLabel}
          </Button>
        ))}
    </Callout>
  );

  if (mode === "blur") {
    return (
      <div data-fancy-feature-gate="" data-locked="" className={cn("relative", className)}>
        <div aria-hidden className="pointer-events-none select-none blur-sm">
          {children}
        </div>
        <div className="absolute inset-0 flex items-center justify-center bg-white/40 p-4 backdrop-blur-[1px] dark:bg-zinc-950/40">
          {locked}
        </div>
      </div>
    );
  }

  return (
    <div data-fancy-feature-gate="" data-locked="">
      {locked}
    </div>
  );
}

FeatureGate.displayName = "FeatureGate";

import { Fragment } from "react";
import { cn } from "@particle-academy/react-fancy";
import type { FeatureDef, Plan, PlanFeatureValue } from "./types";

export interface FeatureMatrixProps {
  plans: Plan[];
  features: FeatureDef[];
  /** Order of feature `group`s; ungrouped features render first, un-headed. */
  groupOrder?: string[];
  /** Sticky the first column + header (default true). */
  sticky?: boolean;
  className?: string;
}

/**
 * A plan × feature comparison table. Rows are features (optionally grouped),
 * columns are plans; each cell renders the plan's `features[key]` value —
 * a check/dash for boolean features, a limit (or "Unlimited") for resource
 * features. Framework-agnostic: feed it normalized `Plan[]` + `FeatureDef[]`.
 */
export function FeatureMatrix({
  plans,
  features,
  groupOrder,
  sticky = true,
  className,
}: FeatureMatrixProps) {
  // Bucket features by group, preserving order.
  const groups: { group: string | null; items: FeatureDef[] }[] = [];
  const index = new Map<string | null, FeatureDef[]>();
  for (const f of features) {
    const g = f.group ?? null;
    if (!index.has(g)) {
      index.set(g, []);
      groups.push({ group: g, items: index.get(g)! });
    }
    index.get(g)!.push(f);
  }
  if (groupOrder) {
    groups.sort(
      (a, b) =>
        (a.group ? groupOrder.indexOf(a.group) : -1) -
        (b.group ? groupOrder.indexOf(b.group) : -1),
    );
  }

  return (
    <div
      data-fancy-feature-matrix=""
      className={cn("overflow-x-auto rounded-xl border border-zinc-200 dark:border-zinc-700", className)}
    >
      <table className="w-full border-collapse text-sm">
        <thead>
          <tr className="border-b border-zinc-200 dark:border-zinc-700">
            <th
              className={cn(
                "p-3 text-left font-medium text-zinc-500",
                sticky && "sticky left-0 bg-white dark:bg-zinc-900",
              )}
            >
              Features
            </th>
            {plans.map((plan) => (
              <th
                key={plan.id}
                className={cn(
                  "p-3 text-center font-semibold text-zinc-900 dark:text-zinc-100",
                  plan.recommended && "text-blue-600 dark:text-blue-400",
                )}
              >
                {plan.name}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {groups.map(({ group, items }) => (
            <Fragment key={group ?? "_"}>
              {group && (
                <tr className="bg-zinc-50 dark:bg-zinc-800/50">
                  <td
                    colSpan={plans.length + 1}
                    className="px-3 py-2 text-xs font-semibold uppercase tracking-wide text-zinc-400"
                  >
                    {group}
                  </td>
                </tr>
              )}
              {items.map((feature) => (
                <tr
                  key={feature.key}
                  className="border-b border-zinc-100 last:border-0 dark:border-zinc-800"
                >
                  <td
                    className={cn(
                      "p-3 text-left text-zinc-700 dark:text-zinc-300",
                      sticky && "sticky left-0 bg-white dark:bg-zinc-900",
                    )}
                  >
                    <span className="font-medium">{feature.name}</span>
                    {feature.description && (
                      <span className="block text-xs text-zinc-400">{feature.description}</span>
                    )}
                  </td>
                  {plans.map((plan) => (
                    <td key={plan.id} className="p-3 text-center align-middle">
                      <Cell value={plan.features?.[feature.key]} unit={feature.unit} />
                    </td>
                  ))}
                </tr>
              ))}
            </Fragment>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function Cell({ value, unit }: { value?: PlanFeatureValue; unit?: string }) {
  if (!value || value.enabled === false) {
    return <DashIcon className="mx-auto h-4 w-4 text-zinc-300 dark:text-zinc-600" />;
  }
  if (value.type === "boolean") {
    return <CheckIcon className="mx-auto h-5 w-5 text-green-500" />;
  }
  // resource
  if (value.limit === null) {
    return <span className="font-medium text-zinc-700 dark:text-zinc-200">Unlimited</span>;
  }
  return (
    <span className="font-medium tabular-nums text-zinc-700 dark:text-zinc-200">
      {value.limit.toLocaleString()}
      {unit ? ` ${unit}` : ""}
    </span>
  );
}

function CheckIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 20 20" fill="currentColor" className={className} aria-label="Included">
      <path
        fillRule="evenodd"
        d="M16.7 5.3a1 1 0 0 1 0 1.4l-7.5 7.5a1 1 0 0 1-1.4 0L3.3 10.7a1 1 0 1 1 1.4-1.4l3.3 3.29 6.8-6.8a1 1 0 0 1 1.4 0Z"
        clipRule="evenodd"
      />
    </svg>
  );
}

function DashIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 20 20" fill="currentColor" className={className} aria-label="Not included">
      <path d="M5 9.25h10a.75.75 0 0 1 0 1.5H5a.75.75 0 0 1 0-1.5Z" />
    </svg>
  );
}

