    '[&_ol]:my-1 [&_ol]:list-decimal [&_ol]:pl-5',
    '[&_li]:my-0.5',
    '[&_h1]:text-base [&_h2]:text-base [&_h3]:text-sm',
    '[&_h1]:font-semibold [&_h2]:font-semibold [&_h3]:font-semibold',
    '[&_h1]:mt-2 [&_h2]:mt-2 [&_h3]:mt-2 [&_h1:first-child]:mt-0 [&_h2:first-child]:mt-0 [&_h3:first-child]:mt-0',
    '[&_code]:rounded [&_code]:bg-black/5 [&_code]:dark:bg-white/10 [&_code]:px-1 [&_code]:py-0.5 [&_code]:text-[0.85em]',
    '[&_pre]:my-2 [&_pre]:overflow-x-auto [&_pre]:rounded [&_pre]:bg-black/5 [&_pre]:dark:bg-white/10 [&_pre]:p-2',
    '[&_pre_code]:bg-transparent [&_pre_code]:p-0',
    '[&_a]:underline [&_a]:underline-offset-2',
    '[&_blockquote]:border-l-2 [&_blockquote]:border-secondary-300 [&_blockquote]:pl-3 [&_blockquote]:italic',
    '[&_table]:my-2 [&_table]:w-full [&_table]:text-left',
    '[&_th]:border-b [&_th]:border-secondary-300 [&_th]:pr-3 [&_th]:font-medium',
    '[&_td]:border-b [&_td]:border-secondary-200 [&_td]:pr-3 [&_td]:align-top',
    '[&_hr]:my-2 [&_hr]:border-secondary-300',
].join(' ');

export interface ChatTranscriptProps {
    history: ChatEntry[];
    agentName: string;
    /** Renders the working indicator while a turn is in flight. */
    thinking?: boolean;
    /** Replaces the default empty state. */
    emptyState?: React.ReactNode;
}

/**
 * The conversation.
 *
 * Renders `display` in preference to `content`: the latter is what the model
 * was sent, with extracted file text folded in, and showing it would paste a
 * whole handbook back at the teacher.
 */
export function ChatTranscript({ history, agentName, thinking, emptyState }: ChatTranscriptProps) {
    const endRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        endRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }, [history.length, thinking]);

    if (history.length === 0 && !thinking) {
        return (
            <div className="flex flex-1 items-center justify-center px-6 py-12 text-center">
                {emptyState ?? (
                    <div className="max-w-md">
                        <Text className="!text-sm !text-secondary-600">
                            Describe the course you want, or attach the material to build it from —
                            a handbook, a slide deck, a question bank.
                        </Text>
                        <Text className="!text-xs !text-secondary-500 !mt-3">
                            {agentName} drafts changes for you to review. It cannot save anything itself.
                        </Text>
                    </div>
                )}
            </div>
        );
    }

    return (
        <div className="flex-1 overflow-y-auto px-4 py-4 grid gap-4 content-start">
            {history.map((entry, i) => (
                <Bubble key={i} entry={entry} agentName={agentName} />
            ))}

            {thinking && (
                <div className="flex gap-3">
                    <Who label={agentName} />
                    <div className="rounded-lg bg-secondary-100 px-3 py-2">
                        <span className="inline-flex gap-1" aria-label={`${agentName} is working`}>
                            <Dot delay="0ms" />
                            <Dot delay="150ms" />
                            <Dot delay="300ms" />
                        </span>
                    </div>
                </div>
            )}

            <div ref={endRef} />
        </div>
    );
}

function Bubble({ entry, agentName }: { entry: ChatEntry; agentName: string }) {
    const mine = entry.role === 'user';
    const body = entry.display || entry.content || '';

    return (
        <div className={`flex gap-3 ${mine ? 'flex-row-reverse' : ''}`}>
            <Who label={mine ? 'You' : agentName} />
            <div className={`max-w-[46rem] ${mine ? 'text-right' : ''}`}>
                <div
                    className={`inline-block rounded-lg px-3 py-2 text-left break-words text-sm ${
                        mine
                            ? 'bg-brand text-white whitespace-pre-wrap'
                            : 'bg-secondary-100 text-secondary-900'
                    }`}
                >
                    {mine ? (
                        // The teacher's own words, verbatim. Rendering these as
                        // markdown would silently reformat what they typed.
                        body
                    ) : (
                        // Model output is markdown, and it is not trusted input —
                        // it can carry whatever an uploaded file talked it into
                        // writing. ContentRenderer sanitizes by default; never
                        // pass `unsafe` here.
                        <ContentRenderer value={body} format="markdown" className={PROSE} />
                    )}
                </div>
                {entry.files && entry.files.length > 0 && (
                    <div className={`mt-1.5 flex flex-wrap gap-1.5 ${mine ? 'justify-end' : ''}`}>
                        {entry.files.map((name) => (
                            <Badge key={name} color="gray" variant="soft" size="sm">
                                {name}
                            </Badge>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

function Who({ label }: { label: string }) {
    return (
        <div className="shrink-0 pt-1">
            <span className="text-[10px] font-semibold uppercase tracking-wide text-secondary-500">
                {label}
            </span>
        </div>
    );
}

function Dot({ delay }: { delay: string }) {
    return (
        <span
            className="h-1.5 w-1.5 rounded-full bg-secondary-400 animate-bounce"
            style={{ animationDelay: delay }}
        />
    );
}

/**
 * The shapes this UX renders. They mirror what particle-academy/teachers-aid
 * serialises, but nothing here imports it — the package is a view over plain
 * JSON, so a host on any backend can feed it.
 */

export type ChangeAction = 'create' | 'update' | 'delete';

/** One proposed change. Inert until a human applies the plan it belongs to. */
export interface ChangeOperation {
    action: ChangeAction;
    entity: string;
    /** Human-readable one-liner for the review list. */
    description: string;
    attributes?: Record<string, unknown>;
    /** Present on updates and deletes. */
    id?: number;
    /**
     * Name this operation's new record is referred to by later in the same
     * plan, e.g. a lesson pointing at `$c1` before the course has an id.
     */
    ref?: string;
}

export interface ChangePlan {
    operations: ChangeOperation[];
    /** Counts keyed by "action entity", e.g. `{"create lesson": 3}`. */
    summary?: Record<string, number>;
    count: number;
}

export interface ChatEntry {
    role: 'user' | 'assistant';
    /**
     * What to show. Distinct from what the model was sent, which has extracted
     * file text folded into it — rendering that would paste a whole handbook
     * back at the teacher.
     */
    display?: string;
    content?: string;
    /** Names of files attached to this turn. */
    files?: string[];
}

import { forwardRef, useEffect, useId, useRef } from "react";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { useFieldMode } from "../lib/components/inputs/mode/FieldMode.context";
import { useInlineEdit } from "../lib/components/inputs/mode/useInlineEdit";
import { dirtyRingClasses } from "../lib/components/inputs/inputs.utils";
import type { CheckboxProps } from "./Checkbox.types";

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      size = "md",
      dirty,
      error,
      label,
      description,
      required,
      disabled,
      className,
      id,
      name,
      checked: controlledChecked,
      defaultChecked = false,
      onCheckedChange,
      indeterminate,
      mode,
      ...rest
    },
    ref,
  ) => {
    const autoId = useId();
    const checkboxId = id ?? autoId;
    const internalRef = useRef<HTMLInputElement | null>(null);
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
    const [checked, setChecked] = useControllableState(
      controlledChecked,
      defaultChecked,
      onCheckedChange,
    );

    useEffect(() => {
      const el = internalRef.current;
      if (el) {
        el.indeterminate = indeterminate ?? false;
      }
    }, [indeterminate]);

    const sizeClasses = {
      xs: "h-3.5 w-3.5",
      sm: "h-4 w-4",
      md: "h-[18px] w-[18px]",
      lg: "h-5 w-5",
      xl: "h-6 w-6",
    }[size];

    const glyph = indeterminate ? "—" : checked ? "✓" : "✕";

    return (
      <div {...rest} data-react-fancy-checkbox="" className={cn("flex items-start gap-2", className)}>
        {!showControl ? (
          <span
            data-react-fancy-display=""
            data-mode="view"
            role={interactive ? "button" : undefined}
            tabIndex={interactive ? 0 : undefined}
            title={interactive ? "Click to edit" : undefined}
            onClick={interactive ? enterEdit : undefined}
            onKeyDown={
              interactive
                ? (e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      enterEdit();
                    }
                  }
                : undefined
            }
            className={cn(
              "flex shrink-0 items-center justify-center text-zinc-700 dark:text-zinc-200",
              sizeClasses,
              interactive &&
                "cursor-pointer rounded outline-none transition-colors hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-blue-500/40 dark:hover:text-white",
            )}
            aria-hidden={interactive ? undefined : "true"}
          >
            {glyph}
          </span>
        ) : (
        <div className="relative flex items-center">
          <input
            ref={(node) => {
              internalRef.current = node;
              if (typeof ref === "function") {
                ref(node);
              } else if (ref) {
                ref.current = node;
              }
            }}
            id={checkboxId}
            type="checkbox"
            name={name}
            disabled={disabled}
            required={required}
            checked={checked}
            autoFocus={interactive}
            onBlur={() => {
              if (interactive) exitEdit();
            }}
            onChange={(e) => setChecked(e.target.checked)}
            className={cn(
              sizeClasses,
              "cursor-pointer rounded border border-zinc-300 bg-white text-blue-600 transition-[border-color,box-shadow] duration-150 focus:ring-2 focus:ring-blue-500/40 focus:ring-offset-0 disabled:cursor-not-allowed disabled:opacity-50 dark:border-zinc-700 dark:bg-[#1e1e24]",
              dirtyRingClasses(dirty),
              error && "border-red-500",
            )}
          />
        </div>
        )}
        {(label || description) && (
          <div className="flex flex-col">
            {label && (
              <label
                htmlFor={checkboxId}
                className={cn(
                  "cursor-pointer text-sm text-zinc-700 dark:text-zinc-100",
                  disabled && "cursor-not-allowed opacity-50",
                )}
              >
                {label}
                {required && <span className="ml-0.5 text-red-500">*</span>}
              </label>
            )}
            {description && (
              <span className="text-xs text-zinc-500 dark:text-zinc-400">
                {description}
              </span>
            )}
            {error && <span className="text-xs text-red-500">{error}</span>}
          </div>
        )}
      </div>
    );
  },
);

Checkbox.displayName = "Checkbox";

import type { HTMLAttributes } from "react";
import type { InputBaseProps } from "../lib/components/inputs/inputs.types";

export interface CheckboxProps
  extends Omit<InputBaseProps, "label">,
    Omit<HTMLAttributes<HTMLDivElement>, "color" | "defaultChecked" | "onChange" | "id"> {
