import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import { createContext, useContext } from "react";
import type { FieldMode } from "../inputs.types";

export interface FieldModeContextValue {
  mode: FieldMode;
}

export const FieldModeContext = createContext<FieldModeContextValue | null>(null);

/**
 * Resolve the effective mode for an input. Precedence: an explicit prop wins,
 * then the nearest `<Form>` / `<FormProvider>` context, then `"edit"`.
 *
 * Deliberately tolerant (returns `"edit"` outside any provider) — unlike a slot
 * guard — so every input works standalone with zero context and existing call
 * sites behave identically.
 */
export function useFieldMode(explicit?: FieldMode): FieldMode {
  const ctx = useContext(FieldModeContext);
  return explicit ?? ctx?.mode ?? "edit";
}

import { useCallback, useState } from "react";
import type { FieldMode } from "../inputs.types";

export interface InlineEdit {
  /** Render the editable control (`true`) vs. the read-only value display (`false`). */
  showControl: boolean;
  /** Whether view mode is interactive (click-to-edit) — i.e. `view` and not disabled. */
  interactive: boolean;
  /** Enter edit mode (no-op unless interactive). */
  enterEdit: () => void;
  /** Leave edit mode, back to the value display. */
  exitEdit: () => void;
}

/**
 * Inline click-to-edit for `mode="view"`. The bound value shows as clean static
 * text; clicking it swaps in the focused control; blur returns to the display
 * (the control's `onChange` / `onBlur` fire as usual, so a host can persist on
 * commit). `mode="edit"` is always the control; a **disabled** view stays static
 * text (no click-to-edit).
 *
 * This is the value of "view mode": tidy read-only surfaces where each field
 * becomes editable only when the user reaches for it.
 */
export function useInlineEdit(mode: FieldMode, disabled?: boolean): InlineEdit {
  const [editing, setEditing] = useState(false);
  const interactive = mode === "view" && !disabled;
  const showControl = mode !== "view" || (interactive && editing);
  const enterEdit = useCallback(() => {
    if (interactive) setEditing(true);
  }, [interactive]);
  const exitEdit = useCallback(() => setEditing(false), []);
  return { showControl, interactive, enterEdit, exitEdit };
}

import type { Size } from "../../utils/types";
import type { InputOption } from "./inputs.types";

export const inputSizeClasses: Record<Size, string> = {
  xs: "px-2 py-1 text-xs rounded",
  sm: "px-2.5 py-1.5 text-sm rounded-md",
  md: "px-3 py-2 text-sm rounded-lg",
  lg: "px-4 py-2.5 text-base rounded-lg",
  xl: "px-5 py-3 text-lg rounded-xl",
};

export const labelSizeClasses: Record<Size, string> = {
  xs: "text-xs",
  sm: "text-xs",
  md: "text-sm",
  lg: "text-sm",
  xl: "text-base",
};

export function dirtyClasses(dirty?: boolean): string {
  return dirty ? "border-l-[3px] border-l-amber-400" : "";
}

export function dirtyRingClasses(dirty?: boolean): string {
  return dirty ? "ring-2 ring-amber-400/50" : "";
}

export function errorClasses(error?: string): string {
  return error ? "border-red-500 focus:ring-red-500" : "";
}

export const inputBaseClasses =
  "border border-zinc-300 bg-white text-zinc-900 placeholder:text-zinc-400 transition-[border-color,box-shadow] duration-150 focus:outline-none focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500 disabled:opacity-50 disabled:cursor-not-allowed dark:border-zinc-700 dark:bg-[#1e1e24] dark:text-zinc-100 dark:placeholder:text-zinc-500 dark:focus:border-blue-400 dark:focus:ring-blue-400/20";

export function resolveOption<V = string>(
  option: InputOption<V>,
): { value: V; label: string; disabled?: boolean; description?: string } {
  if (typeof option === "string") {
    return { value: option as unknown as V, label: option };
  }
  return option;
}

import type { ReactNode } from "react";
import type { Size } from "../../utils/types";

export type InputOption<V = string> =
  | string
  | { value: V; label: string; disabled?: boolean; description?: string };

export type InputOptionGroup<V = string> = {
  label: string;
  options: InputOption<V>[];
};

/**
 * Edit vs. read-only display. In `"view"` mode an input renders the bound value
 * as static text instead of an interactive control — the React/Inertia analog of
 * Livewire's public/bindable properties. Declared here (rather than in `mode/`)
 * to keep `InputBaseProps` free of an import cycle. Resolved per input via
 * {@link useFieldMode}: explicit prop → `<Form>`/`<FormProvider>` context → `"edit"`.
 */
export type FieldMode = "edit" | "view";

export interface InputBaseProps {
  size?: Size;
  dirty?: boolean;
  error?: string;
  label?: string;
  /**
   * Keep the label for assistive tech, but do not draw it.
   *
   * For a control whose options already say what it does — a filter toolbar's
   * segmented switches, say — where a visible label is noise but an unnamed
   * control is a bug. Without this the only choices were an unnamed control or
   * a label the design does not have, and the silent one is the one that ships.
   */
  labelHidden?: boolean;
  description?: string;
  required?: boolean;
  disabled?: boolean;
  className?: string;
  id?: string;
  name?: string;
  /** `"edit"` (default) renders the control; `"view"` renders the value as text. Overrides the `<Form mode>` context. */
  mode?: FieldMode;
}

export type AffixPosition = "inside" | "outside";

export interface InputAffixProps {
  prefix?: ReactNode;
  suffix?: ReactNode;
  prefixPosition?: AffixPosition;
  suffixPosition?: AffixPosition;
}

import { useId } from "react";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { Field } from "../field";
import { useFieldMode } from "../lib/components/inputs/mode/FieldMode.context";
import { DisplayValue } from "../lib/components/inputs/mode/DisplayValue";
import { useInlineEdit } from "../lib/components/inputs/mode/useInlineEdit";
import { dirtyRingClasses, resolveOption } from "../lib/components/inputs/inputs.utils";
import type { CheckboxGroupProps } from "./CheckboxGroup.types";

export function CheckboxGroup<V = string>({
  size = "md",
  dirty,
  error,
  label,
  labelHidden,
  description,
  required,
  disabled,
  className,
  name,
  list,
  value: controlledValue,
  defaultValue = [],
  onValueChange,
  orientation = "vertical",
  mode,
  ...rest
}: CheckboxGroupProps<V>) {
  const groupId = useId();
  const resolvedMode = useFieldMode(mode);
  const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
  const [value, setValue] = useControllableState(
    controlledValue,
    defaultValue,
    onValueChange,
  );

  const handleToggle = (optionValue: V) => {
    const next = value.includes(optionValue)
      ? value.filter((v) => v !== optionValue)
      : [...value, optionValue];
    setValue(next);
  };

  const sizeClasses = {
    xs: "h-3.5 w-3.5",
    sm: "h-4 w-4",
    md: "h-[18px] w-[18px]",
    lg: "h-5 w-5",
    xl: "h-6 w-6",
  }[size];

  const content = !showControl ? (
    <DisplayValue size={size} interactive={interactive} onActivate={enterEdit}>
      {list
        .map(resolveOption)
        .filter((o) => value.includes(o.value))
        .map((o) => o.label)
        .join(", ")}
    </DisplayValue>
  ) : (
    <div
      {...rest}
      data-react-fancy-checkbox-group=""
      onBlur={(e) => {
        if (interactive && !e.currentTarget.contains(e.relatedTarget as Node)) exitEdit();
      }}
      className={cn(
        "flex gap-3",
        orientation === "vertical" ? "flex-col" : "flex-row flex-wrap",
        className,
      )}
    >
      {list.map((option, index) => {
        const resolved = resolveOption(option);
        const optionId = `${groupId}-${index}`;
        const isChecked = value.includes(resolved.value);

        return (
          <div key={optionId} className="flex items-start gap-2">
            <input
              id={optionId}
              type="checkbox"
              name={name}
              value={String(resolved.value)}
              checked={isChecked}
              disabled={disabled || resolved.disabled}
              autoFocus={interactive && index === 0}
              onChange={() => handleToggle(resolved.value)}
              className={cn(
                sizeClasses,
                "cursor-pointer rounded border border-zinc-300 bg-white text-blue-600 transition-[border-color,box-shadow] duration-150 focus:ring-2 focus:ring-blue-500/40 focus:ring-offset-0 disabled:cursor-not-allowed disabled:opacity-50 dark:border-zinc-700 dark:bg-[#1e1e24]",
                dirtyRingClasses(dirty),
                error && "border-red-500",
              )}
            />
            <div className="flex flex-col">
              <label
                htmlFor={optionId}
                className={cn(
                  "cursor-pointer text-sm text-zinc-700 dark:text-zinc-100",
                  (disabled || resolved.disabled) &&
                    "cursor-not-allowed opacity-50",
                )}
              >
                {resolved.label}
              </label>
              {resolved.description && (
                <span className="text-xs text-zinc-500 dark:text-zinc-400">
                  {resolved.description}
                </span>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );

  if (label || error || description) {
    return (
      <Field
        label={label}
        labelHidden={labelHidden}
        description={description}
        error={error}
        required={required}
        size={size}
      >
        {content}
      </Field>
    );
  }

  return content;
}

CheckboxGroup.displayName = "CheckboxGroup";

import type { InputBaseProps, InputOption } from "../lib/components/inputs/inputs.types";

export interface CheckboxGroupProps<V = string>
