        {template
          ? items.map((item, index) => (
              <RenderNode key={index} doc={doc} id={template.id} registry={registry} data={{ ...data, item, index }} />
            ))
          : null}
      </div>
    );
  }

  const kids = childrenOf(doc, id).map((child) => (
    <RenderNode key={child.id} doc={doc} id={child.id} registry={registry} data={data} />
  ));

  const resolve = (v: Bound<Json> | undefined) => resolveValue(v, data);
  const text = (v: Bound<Json> | undefined): string => {
    const r = resolve(v);
    return r === undefined || r === null ? "" : String(r);
  };

  const renderer = registry[node.type];
  const inner = renderer ? renderer({ node, doc, children: kids, data, resolve, text }) : node.island ? null : kids;

  return (
    <div data-cms={node.id} data-cms-island={node.island ? node.type : undefined} className={node.className}>
      {inner}
    </div>
  );
}

import type { ReactNode } from "react";
import { isBinding, type Bound, type Json, type Node, type PageDoc } from "../lib/document/types";

/** The page data context bindings resolve against (e.g. server props, repeater `item`). */
export type DataContext = Record<string, unknown>;

export interface ElementContext {
  node: Node;
  doc: PageDoc;
  /** Pre-rendered child nodes, in order. */
  children: ReactNode;
  /** The data context this node renders in (page data + any repeater scope). */
  data?: DataContext;
  /** Resolve a (possibly bound) value to its raw resolved value. */
  resolve: (v: Bound<Json> | undefined) => unknown;
  /** Resolve a (possibly bound) value to a display string. */
  text: (v: Bound<Json> | undefined) => string;
}

/**
 * Renders the INNER content of a node. The outer `[data-cms]` wrapper is added
 * by {@link RenderNode}, so a renderer only returns what goes inside.
 */
export type ElementRenderer = (ctx: ElementContext) => ReactNode;

export type ElementRegistry = Record<string, ElementRenderer>;

/** Read a dotted path (`a.b.c`) out of the data context. */
export function getPath(data: DataContext | undefined, path: string): unknown {
  return path.split(".").reduce<unknown>((o, k) => (o == null ? undefined : (o as Record<string, unknown>)[k]), data);
}

/** Resolve a value: a `{ $bind }` reads from the data context; anything else is literal. */
export function resolveValue(v: Bound<Json> | undefined, data?: DataContext): unknown {
  if (v === undefined || v === null) return v;
  if (isBinding(v)) return getPath(data, v.$bind);
  return v;
}

/** Built-in native elements. Containers render their children; leaves render content. */
export const defaultRegistry: ElementRegistry = {
  section: ({ children }) => children,
  stack: ({ children }) => children,
  grid: ({ children }) => children,
  frame: ({ children }) => children,
  shape: ({ children }) => children,
  card: ({ children }) => children,
  text: ({ node, text }) => text(node.props.content),
  heading: ({ node, text }) => text(node.props.content) || "Heading",
  // Rich text — inline-formatted HTML (gradient spans, links, <code>, …) that
  // plain `text` can't express. The author owns the markup (it's their content).
  richtext: ({ node, text }) => <div dangerouslySetInnerHTML={{ __html: text(node.props.html) }} />,
  link: ({ node, text }) => (
    <a href={text(node.props.href) || "#"} style={{ color: "inherit", textDecoration: "underline" }}>
      {text(node.props.content) || "link"}
    </a>
  ),
  divider: () => <hr style={{ border: "none", borderTop: "1px solid #e2e8f0", margin: 0 }} />,
  callout: ({ node, text }) => {
    const tone = ({ info: "#3b82f6", success: "#10b981", warning: "#f59e0b", danger: "#ef4444" } as Record<string, string>)[text(node.props.variant)] ?? "#3b82f6";
    return (
      <div style={{ display: "flex", gap: 10, padding: "12px 14px", borderRadius: 10, background: `${tone}14`, borderLeft: `3px solid ${tone}` }}>
        <span style={{ fontSize: 13 }}>{text(node.props.content) || "Callout"}</span>
      </div>
    );
  },
  code: ({ node, text }) => (
    <pre style={{ margin: 0, padding: "12px 14px", borderRadius: 10, background: "#0b1220", color: "#e2e8f0", fontFamily: "ui-monospace, monospace", fontSize: 13, overflowX: "auto" }}>
      <code>{text(node.props.content)}</code>
    </pre>
  ),
  button: ({ node, text }) => {
    const label = text(node.props.label) || text(node.props.content) || "Button";
    const variant = text(node.props.variant) || "primary";
    return <span data-cms-button={variant} style={buttonStyle(variant)}>{label}</span>;
  },
  image: ({ node, text }) => (
    <img
      src={text(node.props.src)}
      alt={text(node.props.alt)}
      style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
    />
  ),
};

/**
 * A self-contained button look so the `button` primitive renders sensibly with
 * zero host CSS. Hosts that want their own button classes override the `button`
 * renderer in their registry (e.g. the sandbox maps it to `.btn .btn-primary`).
 */
function buttonStyle(variant: string): import("react").CSSProperties {
  const base: import("react").CSSProperties = {
    display: "inline-flex",
    alignItems: "center",
    gap: 6,
    padding: "9px 16px",
    borderRadius: 8,
    fontWeight: 600,
    fontSize: 14,
    lineHeight: 1,
    cursor: "pointer",
    userSelect: "none",
  };
  if (variant === "ghost") return { ...base, background: "transparent", color: "inherit", border: "1px solid currentColor" };
  if (variant === "outline") return { ...base, background: "transparent", color: "#7c3aed", border: "1px solid #7c3aed" };
  return { ...base, background: "#7c3aed", color: "#fff", border: "1px solid #7c3aed" };
}

/**
 * Stages document model — see `fancy-ui/docs/fancy-cms.md` §4.
 *
 * A page is a vertical stack of full-bleed **sections**; inside each, **layers**
 * are positioned by constraints (free + bold stays responsive), with stack/grid
 * containers where structure is wanted. Nodes live in a **flat map** keyed by id
 * (Figma-style) so ops target a stable identity and collab merges stay clean.
 */

import type { DocNode, DocTree } from "@particle-academy/fancy-doc-commons";

/** A node id. Alias of doc-commons' `DocId`, kept for readability in CMS code. */
export type NodeId = string;

export type ScrollMode = "snap" | "smooth";

/** Ordered, mobile-first. Convention: `"base" | "md" | "lg"`. */
export type Breakpoint = string;

export type Json = string | number | boolean | null | Json[] | { [key: string]: Json };

/** A literal value OR a binding into the page's data context (`{ $bind: "profile.coins" }`). */
export interface Binding {
  $bind: string;
  /**
   * Which live query this path reads from — `["catalog", "products"]`.
   *
   * Optional: a host-supplied static context is still legitimate, and every
   * document saved before this has no `$source`.
   *
   * When present it is the Live Contract's vocabulary — the same
   * `[namespace, resource, …]` shape `fancy-query`'s `liveKey()` produces —
   * NOT a CMS-local name. See `./bindings` for why that matters and for
   * `bindingSources()`, which answers "what does this page depend on?".
   */
  $source?: readonly (string | number)[];
}
export type Bound<T> = T | Binding;

export function isBinding(v: unknown): v is Binding {
  return typeof v === "object" && v !== null && typeof (v as Binding).$bind === "string";
}

// ── Sizing ────────────────────────────────────────────────────────────────

export type LengthUnit = "px" | "%" | "vw" | "vh" | "rem" | "fr";
export interface Length {
  value: number;
  unit: LengthUnit;
}
export type SizeMode = Length | "fill" | "hug";

export interface Constraints {
  /** Pinned offsets within a `free` parent (null = unpinned). */
  left?: Length | null;
  right?: Length | null;
  top?: Length | null;
  bottom?: Length | null;
  centerX?: boolean;
  centerY?: boolean;
  width: SizeMode;
  height: SizeMode;
}

export type LayoutMode = "free" | "stack" | "grid";

// ── Style (compiles deterministically to CSS in both emitters) ──────────────

export interface StyleProps {
  // box
  padding?: Length;
  margin?: Length;
  radius?: Length;
  // color / surface
  background?: string; // color | gradient | url(...)
  color?: string;
  opacity?: number;
  // typography
  fontFamily?: string;
  fontSize?: Length;
  fontWeight?: number;
  lineHeight?: number;
  textAlign?: "left" | "center" | "right" | "justify";
  letterSpacing?: Length;
  // border / shadow / effects (static)
  border?: string;
  boxShadow?: string;
  transform?: string;
  filter?: string;
  // container knobs (when layout = stack | grid)
  gap?: Length;
  direction?: "row" | "column";
  columns?: number;
  align?: "start" | "center" | "end" | "stretch";
  justify?: "start" | "center" | "end" | "between" | "around";
}

/** Per-breakpoint overrides; `base` is required, others cascade mobile-first. */
export type PerBreakpoint<T> = { base: T } & Partial<Record<Breakpoint, Partial<T>>>;

// ── Animation (typed for Phase 2; ignored by the static CSS emitter) ────────

export type AnimDriver = "enter" | "scroll" | "loop" | "hover" | "click" | "drag";
export interface Keyframe {
  at: number; // 0..1
  props: Record<string, number | string>;
}
export interface Anim {
  id: string;
  driver: AnimDriver;
  keyframes: Keyframe[];
  range?: { start: number; end: number };
  ease?: string;
  duration?: number;
  delay?: number;
  stagger?: number;
  once?: boolean;
  emit?: "css" | "js";
}

// ── Actions (typed for Phase 3/4) ───────────────────────────────────────────

export type ActionEvent = "click" | "submit" | "change" | "load" | "timer" | "scroll-into" | "hover";
export type ActionHandler =
  | { kind: "navigate"; href: Bound<string> }
  | { kind: "submitForm"; endpoint: string; method?: "post" | "put" }
  | { kind: "mutate"; target: string; value: Bound<Json> }
  | { kind: "callEndpoint"; endpoint: string; method?: string }
  | { kind: "runFlow"; flow: string }
  | { kind: "openModal"; node: NodeId }
  | { kind: "openDrawer"; node: NodeId }
  | { kind: "playTimeline"; section: NodeId }
  | { kind: "toggleNode"; node: NodeId };
export interface Action {
  on: ActionEvent;
  do: ActionHandler;
}

// ── Nodes & document ────────────────────────────────────────────────────────

/**
 * A page node.
 *
 * Extends {@link DocNode} from `fancy-doc-commons` rather than redeclaring it:
 * id / type / parent / order / props are the shared substrate every Fancy
 * document surface uses, and the CMS adds its own domain fields on top. That
 * is what lets `registerDocBridge` drive a CMS page and a fancy-screens screen
 * through the same tools, with no CMS-specific bridge.
 */
export interface Node extends DocNode<Record<string, Bound<Json>>> {
  /** Addon key: `section | text | image | shape | stack | grid | frame | <addon>`. */
  type: string;
  /** How this node arranges its children. */
  layout?: LayoutMode;
  /** How this node positions itself within its parent. */
  constraints?: PerBreakpoint<Constraints>;
  style: PerBreakpoint<StyleProps>;
  animations?: Anim[];
  actions?: Action[];
  /** Repeater: render this node once per item of a bound array. */
  repeat?: { each: Binding; as: string };
  /**
   * Host CSS class(es) applied to the node's element. The migration enabler:
   * reuse the host site's existing stylesheet for pixel-perfect reproduction
   * instead of re-deriving every rule through {@link StyleProps}.
   */
  className?: string;
  /** Derived from the addon manifest — interactive/3rd-party ⇒ hydration island. */
  island?: boolean;
}

export interface ThemeTokens {
  name?: string;
  [key: string]: Json | undefined;
}

export interface PageMeta {
  title: string;
  slug: string;
  scrollMode: ScrollMode;
  seo?: Record<string, string>;
}

export interface PageDoc {
  id: string;
  /** Op counter — collab ordering + revision checkpoints. */
  seq: number;
  meta: PageMeta;
  theme: ThemeTokens;
  /** Ordered, mobile-first. */
  breakpoints: Breakpoint[];
  /**
   * Flat map — not a nested tree. This is a {@link DocTree}, so every
   * doc-commons walk (`childrenOf`, `roots`, `descendantsOf`) works on it
   * directly.
   *
   * There is no separate `sections[]` any more. Top-level order used to live in
   * its own array while every other level used fractional `order` keys, which
   * meant two ordering mechanisms that could disagree — a node could be a root
   * by `parent === null` and absent from `sections`, and then simply not
   * render. Roots are now ordered exactly like any other sibling group.
   */
  nodes: Record<NodeId, Node>;
}

/** Runtime boundary check for the one structural field every document walk needs. */
export function hasNodeMap(value: unknown): value is { nodes: Record<NodeId, Node> } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const nodes = (value as { nodes?: unknown }).nodes;
  return typeof nodes === "object" && nodes !== null && !Array.isArray(nodes);
}

/** Default breakpoint → min-width (px) map. `base` has no media query. */
export const DEFAULT_BREAKPOINTS: Record<string, number> = {
  base: 0,
  md: 768,
  lg: 1024,
};

/** A minimal empty document. */
export function emptyDoc(id: string, slug = "/"): PageDoc {
  return {
    id,
    seq: 0,
    meta: { title: "Untitled", slug, scrollMode: "smooth" },
    theme: { name: "default" },
    breakpoints: ["base", "md", "lg"],
    nodes: {},
  };
}

/**
 * The pure, total reducer. `reduce(doc, op)` returns a new document; an invalid
 * op is a **logged no-op** (returns the same doc, `seq` unchanged). That single
 * property is what makes undo, revisions, collaboration, and agent edits all
 * flow through one spine.
 *
 * Ordering: EVERY level uses the fractional `order` field among siblings,
 * including the roots. Top-level order used to live in a separate `sections`
 * array, which meant two mechanisms that could disagree — a node could be a
 * root by `parent === null` and missing from `sections`, and then simply not
 * render, with nothing reporting it.
 */
import {
  childrenOf as docChildrenOf,
  descendantsOf,
  fractionalKey,
} from "@particle-academy/fancy-doc-commons";
import { hasNodeMap, type Action, type Node, type NodeId, type PageDoc, type StyleProps } from "./types";
import type { PageOp } from "./ops";

export interface ReduceOptions {
  /** Called when an op can't apply. Default: silent. */
  onInvalid?: (op: PageOp, reason: string) => void;
}

/**
 * Children of a node (or the roots when `parent` is null), in order.
 *
 * Delegates to doc-commons so the CMS, fancy-screens and any future surface
 * walk a document the same way. Roots are no longer a special case.
 */
export function childrenOf(doc: PageDoc, parent: NodeId | null): Node[] {
  return docChildrenOf<Node>(doc, parent);
}

/**
 * The top-level node ids, in order.
 *
 * Replaces the old `doc.sections` array. Kept as a named helper because the two
 * things callers actually wanted from that array — "list the roots" and "the
 * last root" — read badly as `childrenOf(doc, null).map(n => n.id)` at every
 * call site.
 */
export function rootIds(doc: PageDoc): NodeId[] {
  if (!hasNodeMap(doc)) return [];
  return childrenOf(doc, null).map((n) => n.id);
}

/** The last top-level node, or null — the default parent for a new insert. */
export function lastRootId(doc: PageDoc): NodeId | null {
  const r = rootIds(doc);
  return r[r.length - 1] ?? null;
}

/** Every transitive descendant id of `id` (excludes `id`). */
export function descendantIds(doc: PageDoc, id: NodeId): NodeId[] {
  return descendantsOf<Node>(doc, id);
}

function patchNode(doc: PageDoc, id: NodeId, patch: Partial<Node>): PageDoc {
  const node = doc.nodes[id]!;
  return {
    ...doc,
    nodes: { ...doc.nodes, [id]: { ...node, ...patch } },
    seq: doc.seq + 1,
  };
}

export function reduce(doc: PageDoc, op: PageOp, opts: ReduceOptions = {}): PageDoc {
  const invalid = (reason: string): PageDoc => {
    opts.onInvalid?.(op, reason);
    return doc;
  };

  switch (op.t) {
    case "insert_node": {
      if (doc.nodes[op.node.id]) return invalid("node id already exists");
      if (op.node.parent !== null && !doc.nodes[op.node.parent]) return invalid("parent not found");
      return {
        ...doc,
        nodes: { ...doc.nodes, [op.node.id]: op.node },
        seq: doc.seq + 1,
      };
    }

    case "remove_node": {
      if (!doc.nodes[op.id]) return invalid("node not found");
      const dead = new Set<NodeId>([op.id, ...descendantIds(doc, op.id)]);
      const nodes: Record<NodeId, Node> = {};
      for (const id of Object.keys(doc.nodes)) {
        if (!dead.has(id)) nodes[id] = doc.nodes[id]!;
      }
      return {
        ...doc,
        nodes,
        seq: doc.seq + 1,
      };
    }

    case "move_node": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      if (op.parent === op.id) return invalid("cannot parent a node to itself");
      if (op.parent !== null && !doc.nodes[op.parent]) return invalid("new parent not found");
      if (op.parent !== null && descendantIds(doc, op.id).includes(op.parent)) {
        return invalid("move would create a cycle");
      }
      return {
        ...doc,
        nodes: { ...doc.nodes, [op.id]: { ...node, parent: op.parent, order: op.order } },
        seq: doc.seq + 1,
      };
    }

    case "set_node_props": {
      if (!doc.nodes[op.id]) return invalid("node not found");
      return patchNode(doc, op.id, {
        props: { ...doc.nodes[op.id]!.props, ...op.patch } as unknown as Node["props"],
      });
    }

    case "set_layout": {
      if (!doc.nodes[op.id]) return invalid("node not found");
      return patchNode(doc, op.id, { layout: op.layout });
    }

    case "set_style": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      const prev = node.style[op.breakpoint] ?? {};
      return patchNode(doc, op.id, {
        style: { ...node.style, [op.breakpoint]: { ...prev, ...op.patch } } as Node["style"],
      });
    }

    case "set_constraints": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      const base = node.constraints ?? { base: { width: "hug", height: "hug" } };
      const prev = base[op.breakpoint] ?? {};
      return patchNode(doc, op.id, {
        constraints: { ...base, [op.breakpoint]: { ...prev, ...op.patch } } as Node["constraints"],
      });
    }

    case "set_animation": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      const list = node.animations ?? [];
      const idx = list.findIndex((a) => a.id === op.anim.id);
      return patchNode(doc, op.id, {
        animations: idx >= 0 ? list.map((a, i) => (i === idx ? op.anim : a)) : [...list, op.anim],
      });
    }

    case "remove_animation": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      return patchNode(doc, op.id, {
        animations: (node.animations ?? []).filter((a) => a.id !== op.animId),
      });
    }

    case "set_action": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      const list = node.actions ?? [];
      let actions: Action[];
      if (op.action === null) actions = list.filter((_, i) => i !== op.index);
      else if (op.index >= list.length) actions = [...list, op.action];
      else actions = list.map((a, i) => (i === op.index ? op.action! : a));
      return patchNode(doc, op.id, { actions });
    }

    case "set_meta":
      return { ...doc, meta: { ...doc.meta, ...op.patch }, seq: doc.seq + 1 };

    case "set_theme":
      return { ...doc, theme: { ...doc.theme, ...op.patch }, seq: doc.seq + 1 };

    case "reorder_roots": {
      // Roots are ordered by their own fractional keys now, so a reorder
      // REWRITES those keys rather than replacing a list. Still validated as a
      // permutation: a partial list would silently drop roots out of the page.
      const currentRoots = childrenOf(doc, null);
      const current = new Set(currentRoots.map((n) => n.id));
      const same =
        op.order.length === currentRoots.length && op.order.every((id) => current.has(id));
      if (!same) return invalid("reorder must be a permutation of the current roots");

      const nodes = { ...doc.nodes };
      let prev: string | null = null;
      for (const id of op.order) {
        prev = fractionalKey(prev, null);
        nodes[id] = { ...nodes[id]!, order: prev };
      }
      return { ...doc, nodes, seq: doc.seq + 1 };
    }

    default:
      return invalid(`unknown op "${(op as PageOp).t}"`);
  }
}

/** Apply a sequence of ops, threading the document. */
export function reduceAll(doc: PageDoc, ops: PageOp[], opts?: ReduceOptions): PageDoc {
  return ops.reduce((d, op) => reduce(d, op, opts), doc);
}

/**
 * Inverse op(s) for undo, computed against the **pre-op** document. Structural
 * ops invert cleanly; merge-style ops (`set_props`/`set_style`/`set_constraints`)
 * restore the previous values of the touched keys (keys that did not previously
 * exist can't be deleted via a merge — a known Phase-0 limitation).
 */
export function invert(doc: PageDoc, op: PageOp): PageOp[] {
  switch (op.t) {
    case "insert_node":
      return [{ t: "remove_node", id: op.node.id }];

    case "remove_node": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      // Re-insert the subtree parent-first, then restore section order.
      const ids = [op.id, ...descendantIds(doc, op.id)];
      const inserts: PageOp[] = ids.map((id) => ({ t: "insert_node", node: doc.nodes[id]! }));
      if (node.parent === null) {
        inserts.push({ t: "reorder_roots", order: childrenOf(doc, null).map((n) => n.id) });
      }
      return inserts;
    }

    case "move_node": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      const back: PageOp[] = [{ t: "move_node", id: op.id, parent: node.parent, order: node.order }];
      if (node.parent === null) {
        back.push({ t: "reorder_roots", order: childrenOf(doc, null).map((n) => n.id) });
      }
      return back;
    }

    case "set_node_props": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      const prev: Record<string, unknown> = {};
      for (const k of Object.keys(op.patch)) prev[k] = node.props[k];
      return [{ t: "set_node_props", id: op.id, patch: prev }];
    }

    case "set_layout": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      return [{ t: "set_layout", id: op.id, layout: node.layout }];
    }

    case "set_style": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      const prevBp = (node.style[op.breakpoint] ?? {}) as Record<string, unknown>;
      const prev: Partial<StyleProps> = {};
      for (const k of Object.keys(op.patch)) (prev as Record<string, unknown>)[k] = prevBp[k];
      return [{ t: "set_style", id: op.id, breakpoint: op.breakpoint, patch: prev }];
    }

    case "set_meta":
      return [{ t: "set_meta", patch: pick(doc.meta, Object.keys(op.patch)) }];

    case "set_theme":
      return [{ t: "set_theme", patch: pick(doc.theme, Object.keys(op.patch)) }];

    case "reorder_roots":
      return [{ t: "reorder_roots", order: childrenOf(doc, null).map((n) => n.id) }];

    default:
      return [];
  }
}

function pick<T extends object>(obj: T, keys: string[]): Partial<T> {
  const out: Partial<T> = {};
  for (const k of keys) (out as Record<string, unknown>)[k] = (obj as Record<string, unknown>)[k];
  return out;
}

/**
 * Forward migration for documents saved before roots were ordered like every
 * other sibling group.
 *
 * ## Why this cannot be skipped
 *
 * The old model carried top-level order TWICE: a `sections: NodeId[]` array, and
 * an `order` key on every node like any other sibling. The old `reorder_sections`
 * op permuted the array and **left the order keys untouched** — so the moment a
 * user dragged a section, the two disagreed, and `sections[]` was the one that
 * won (it was what the renderer walked).
 *
 * Which means: dropping `sections[]` and falling back to the order keys does not
 * merely lose a redundant field. On every page whose sections were ever
 * rearranged, it silently reverts them to the order they were first created in.
 * The page still loads, nothing throws, and the layout is wrong.
 *
 * So the migration rewrites root `order` keys to agree with `sections[]` before
 * the array is discarded. `sections[]` is treated as authoritative for exactly
 * the reason above.
 *
 * ## Idempotent, and safe on already-migrated documents
 *
 * A doc with no `sections` is returned unchanged (same reference). Running this
 * twice is a no-op, so a host can call it unconditionally on load rather than
 * tracking a schema version.
 */

import { fractionalKey } from "@particle-academy/fancy-doc-commons";
import { emptyDoc, hasNodeMap, type NodeId, type PageDoc } from "./types";

/** A `PageDoc` as persisted before this change — with the extra array. */
export type LegacyPageDoc = PageDoc & { sections?: NodeId[] };

export interface MigrateResult {
  doc: PageDoc;
  /** True when the input actually carried `sections[]` and was rewritten. */
  migrated: boolean;
  /**
   * Ids listed in `sections[]` with no matching node. Skipped rather than
   * faulted — a dangling id is a stale write, and refusing to open the document
   * over it would be a worse outcome than dropping it.
   */
  danglingIds: NodeId[];
  /**
   * Roots present in `nodes` but missing from `sections[]`. Under the old model
   * these did not render at all. They are appended after the listed sections, in
   * their existing order-key order, because making a node visible is recoverable
   * and deleting one is not.
   */
  unlistedRootIds: NodeId[];
}

function normalizeDoc(input: unknown): LegacyPageDoc | PageDoc {
  if (hasNodeMap(input)) return input as LegacyPageDoc | PageDoc;

  const id =
    typeof input === "object" && input !== null && !Array.isArray(input) &&
    typeof (input as { id?: unknown }).id === "string"
      ? (input as { id: string }).id
      : "malformed";

  return emptyDoc(id);
}

/**
 * Migrate a possibly-legacy document, reporting what was found.
 *
 * Use {@link migrateDoc} unless you want the diagnostics.
 */
export function migrateDocVerbose(input: LegacyPageDoc | PageDoc): MigrateResult {
  const normalized = normalizeDoc(input);
  const legacy = normalized as LegacyPageDoc;
  const sections = legacy.sections;

  if (!Array.isArray(sections)) {
    return { doc: normalized as PageDoc, migrated: false, danglingIds: [], unlistedRootIds: [] };
  }

  const danglingIds: NodeId[] = [];
  const ordered: NodeId[] = [];
  const seen = new Set<NodeId>();

  for (const id of sections) {
    if (!normalized.nodes[id]) {
      danglingIds.push(id);
      continue;
    }
    // A duplicate id in the array would otherwise be minted two order keys, and
    // the second would overwrite the first — take the first occurrence.
    if (seen.has(id)) continue;
    seen.add(id);
    ordered.push(id);
  }

  // Roots that the array never mentioned. Sorted by their existing key so their
  // relative order is at least stable rather than dependent on object insertion.
  const unlistedRootIds = Object.values(normalized.nodes)
    .filter((n) => n.parent === null && !seen.has(n.id))
    .sort((a, b) => (a.order < b.order ? -1 : a.order > b.order ? 1 : 0))
    .map((n) => n.id);

  const finalOrder = [...ordered, ...unlistedRootIds];

  const nodes = { ...normalized.nodes };
  let prev: string | null = null;

  for (const id of finalOrder) {
    const key = fractionalKey(prev, null);
    nodes[id] = { ...nodes[id]!, order: key };
    prev = key;
  }

  const { sections: _dropped, ...rest } = legacy;

  return {
    doc: { ...rest, nodes } as PageDoc,
    migrated: true,
    danglingIds,
    unlistedRootIds,
  };
}

/**
 * Migrate a possibly-legacy document. Safe to call on every load — an
 * already-migrated document is returned unchanged, by reference.
 */
export function migrateDoc(input: LegacyPageDoc | PageDoc): PageDoc {
  return migrateDocVerbose(input).doc;
}

/** True when the document still carries the pre-migration `sections[]` array. */
export function needsMigration(input: LegacyPageDoc | PageDoc): boolean {
  return Array.isArray((input as LegacyPageDoc).sections);
}

/**
 * The JS style → CSS emitter (one half of the dual-emitter pair; the PHP
 * `particle-academy/fancy-cms` mirrors it byte-for-byte). Output is
 * **deterministic**: declarations are sorted, selectors and media blocks use a
 * fixed format, and nodes are emitted in sorted-id order — so the parity harness
 * can diff the two engines' CSS exactly.
 *
 * Phase 0 covers the static subset (layout / constraints / style). Motion lands
 * in Phase 2.
 */
import {
  DEFAULT_BREAKPOINTS,
  hasNodeMap,
  type Constraints,
  type Length,
  type Node,
  type PageDoc,
  type SizeMode,
  type StyleProps,
} from "../document/types";

const selectorFor = (id: string): string => `[data-cms="${id}"]`;

function lengthToCss(len: Length): string {
  return `${len.value}${len.unit}`;
}

function sizeToCss(size: SizeMode): string {
  if (size === "fill") return "100%";
  if (size === "hug") return "auto";
  return lengthToCss(size);
}

const ALIGN: Record<string, string> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  stretch: "stretch",
};
const JUSTIFY: Record<string, string> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  between: "space-between",
  around: "space-around",
};

/** Map StyleProps → CSS declarations (property → value). */
function styleDecls(style: Partial<StyleProps>): Record<string, string> {
  const d: Record<string, string> = {};
  if (style.padding) d["padding"] = lengthToCss(style.padding);
  if (style.margin) d["margin"] = lengthToCss(style.margin);
  if (style.radius) d["border-radius"] = lengthToCss(style.radius);
  if (style.background !== undefined) d["background"] = style.background;
  if (style.color !== undefined) d["color"] = style.color;
  if (style.opacity !== undefined) d["opacity"] = String(style.opacity);
  if (style.fontFamily !== undefined) d["font-family"] = style.fontFamily;
  if (style.fontSize) d["font-size"] = lengthToCss(style.fontSize);
  if (style.fontWeight !== undefined) d["font-weight"] = String(style.fontWeight);
  if (style.lineHeight !== undefined) d["line-height"] = String(style.lineHeight);
  if (style.textAlign !== undefined) d["text-align"] = style.textAlign;
  if (style.letterSpacing) d["letter-spacing"] = lengthToCss(style.letterSpacing);
  if (style.border !== undefined) d["border"] = style.border;
  if (style.boxShadow !== undefined) d["box-shadow"] = style.boxShadow;
  if (style.transform !== undefined) d["transform"] = style.transform;
  if (style.filter !== undefined) d["filter"] = style.filter;
  if (style.gap) d["gap"] = lengthToCss(style.gap);
  if (style.align !== undefined) d["align-items"] = ALIGN[style.align] ?? style.align;
  if (style.justify !== undefined) d["justify-content"] = JUSTIFY[style.justify] ?? style.justify;
  return d;
}

/** Container behaviour from `node.layout`. */
function layoutDecls(node: Node): Record<string, string> {
  const d: Record<string, string> = {};
  if (node.layout === "stack") {
    d["display"] = "flex";
    d["flex-direction"] = node.style.base.direction ?? "column";
  } else if (node.layout === "grid") {
    d["display"] = "grid";
    d["grid-template-columns"] = `repeat(${node.style.base.columns ?? 1}, 1fr)`;
  } else if (node.layout === "free") {
    d["position"] = "relative";
  }
  return d;
}

/** Self-positioning from constraints (absolute pins only inside a `free` parent). */
function constraintDecls(c: Partial<Constraints>, parentFree: boolean): Record<string, string> {
  const d: Record<string, string> = {};
  const transforms: string[] = [];
  if (parentFree) {
    d["position"] = "absolute";
    if (c.left) d["left"] = lengthToCss(c.left);
    if (c.right) d["right"] = lengthToCss(c.right);
    if (c.top) d["top"] = lengthToCss(c.top);
    if (c.bottom) d["bottom"] = lengthToCss(c.bottom);
    if (c.centerX) {
      d["left"] = "50%";
      transforms.push("translateX(-50%)");
    }
    if (c.centerY) {
      d["top"] = "50%";
      transforms.push("translateY(-50%)");
    }
    if (transforms.length) d["transform"] = transforms.join(" ");
  }
  if (c.width) d["width"] = sizeToCss(c.width);
  if (c.height) d["height"] = sizeToCss(c.height);
  return d;
}

function isParentFree(doc: PageDoc, node: Node): boolean {
  if (node.parent === null) return false; // sections stack in the page flow
  const parent = doc.nodes[node.parent];
  return !parent || parent.layout === undefined || parent.layout === "free";
}

function serializeRule(selector: string, decls: Record<string, string>, indent: string): string {
  const props = Object.keys(decls).sort();
  if (props.length === 0) return "";
  const body = props.map((p) => `${indent}  ${p}: ${decls[p]};`).join("\n");
  return `${indent}${selector} {\n${body}\n${indent}}`;
}

/** Emit the full stylesheet for a document. Deterministic. */
export function emitDocCss(doc: PageDoc): string {
  if (!hasNodeMap(doc)) return "";

  const breakpointPx = DEFAULT_BREAKPOINTS;
  const blocks: string[] = [];

  for (const id of Object.keys(doc.nodes).sort()) {
    const node = doc.nodes[id]!;
    const selector = selectorFor(id);
    const parentFree = isParentFree(doc, node);

    // base = style.base + layout + constraints.base
    const base: Record<string, string> = {
      ...layoutDecls(node),
      ...(node.constraints ? constraintDecls(node.constraints.base, parentFree) : {}),
      ...styleDecls(node.style.base),
    };
    const baseRule = serializeRule(selector, base, "");
    if (baseRule) blocks.push(baseRule);

    // per-breakpoint overrides (mobile-first, in doc order, skipping base)
    for (const bp of doc.breakpoints) {
      if (bp === "base") continue;
      const px = breakpointPx[bp];
      if (px === undefined) continue;
      const decls: Record<string, string> = {
        ...(node.constraints?.[bp] ? constraintDecls(node.constraints[bp]!, parentFree) : {}),
        ...(node.style[bp] ? styleDecls(node.style[bp]!) : {}),
      };
      const inner = serializeRule(selector, decls, "  ");
      if (inner) blocks.push(`@media (min-width: ${px}px) {\n${inner}\n}`);
    }
  }

  return blocks.join("\n\n") + (blocks.length ? "\n" : "");
}

/**
 * `PageOp` — the closed set of mutations. Every edit (human drag, agent tool
 * call, collab message) is one of these, reduced by the pure `reduce` in
 * `reduce.ts`. See `fancy-ui/docs/fancy-cms.md` §4.
 */
import type {
  Action,
  Anim,
  Breakpoint,
  Constraints,
  LayoutMode,
  Node,
  NodeId,
  PageMeta,
  StyleProps,
  ThemeTokens,
} from "./types";

export type Actor = { kind: "human" | "agent"; id: string };

export type PageOp =
  | { t: "insert_node"; node: Node }
  | { t: "remove_node"; id: NodeId }
  | { t: "move_node"; id: NodeId; parent: NodeId | null; order: string }
  /**
   * Renamed from `set_props` in 0.6.0, and the reason is a wire-format
   * collision rather than taste.
   *
   * `fancy-doc-commons`' `TreeOp` uses the SAME discriminator `t` and also had
   * a `set_props` variant with a byte-identical shape — so a stored
   * `{t:"set_props", id, patch}` was valid under two vocabularies and reduced
   * by two different reducers, with nothing in the document able to say which
   * one it meant.
   *
   * Every other variant here was already disjoint (`insert_node` vs `insert`,
   * `move_node` vs `move`), so closing the collision cost exactly one rename
   * rather than a versioned envelope on every op in the kit.
   */
  | { t: "set_node_props"; id: NodeId; patch: Record<string, unknown> }
  | { t: "set_layout"; id: NodeId; layout: LayoutMode | undefined }
  | { t: "set_style"; id: NodeId; breakpoint: Breakpoint; patch: Partial<StyleProps> }
  | { t: "set_constraints"; id: NodeId; breakpoint: Breakpoint; patch: Partial<Constraints> }
  | { t: "set_animation"; id: NodeId; anim: Anim }
  | { t: "remove_animation"; id: NodeId; animId: string }
  | { t: "set_action"; id: NodeId; index: number; action: Action | null }
  | { t: "set_meta"; patch: Partial<PageMeta> }
  | { t: "set_theme"; patch: Partial<ThemeTokens> }
  | { t: "reorder_roots"; order: NodeId[] };

export type PageOpType = PageOp["t"];

/** Wire envelope — carries provenance + ordering. `pending` = an agent proposal. */
export interface OpEnvelope {
  op: PageOp;
  actor: Actor;
  ts: number;
  seq: number;
  pending?: boolean;
}

import { Fragment, type ReactElement } from "react";
import type { PageDoc } from "../lib/document/types";
import { emitDocCss } from "../lib/render/css";
import { RenderNode } from "./RenderNode";
import { defaultRegistry, type ElementRegistry } from "./registry";

export interface CmsRegionProps {
  doc: PageDoc;
  /** Root node id of the region to render (a section, or any node). */
  root: string;
  registry?: ElementRegistry;
  includeStyles?: boolean;
}

/**
 * Render a single subtree — drop into a hand-coded page so the CMS owns just
 * that region (the "guest, not host" mounting mode). Phase 0/1 emits the whole
 * document's CSS; scoping it to the subtree is a later optimization.
 */
export function CmsRegion({
  doc,
  root,
  registry = defaultRegistry,
  includeStyles = true,
}: CmsRegionProps): ReactElement {
  return (
    <Fragment>
      {includeStyles ? <style data-cms-styles="">{emitDocCss(doc)}</style> : null}
      <RenderNode doc={doc} id={root} registry={registry} />
    </Fragment>
  );
}

import type { ReactElement } from "react";
import type { Bound, Json, PageDoc } from "../lib/document/types";
import { childrenOf } from "../lib/document/reduce";
import { defaultRegistry, resolveValue, type DataContext, type ElementRegistry } from "./registry";

export interface RenderNodeProps {
  doc: PageDoc;
  id: string;
  registry?: ElementRegistry;
  /** Data context bindings resolve against (page data + any repeater scope). */
  data?: DataContext;
}

/**
 * Render one node (and its subtree) to a `[data-cms]`-tagged element. The CSS
 * emitted by `emitDocCss` targets these `data-cms` handles. Interactive /
 * 3rd-party **islands** with no registered renderer become an empty, sized
 * placeholder the host hydrates client-side — mirroring the PHP renderer.
 *
 * `repeater` nodes are special-cased: their first child is a template rendered
 * once per item of the bound `items` array, each in a scope that exposes `item`
 * and `index` to nested `{ $bind: "item.…" }` bindings.
 */
export function RenderNode({ doc, id, registry = defaultRegistry, data }: RenderNodeProps): ReactElement | null {
  const node = doc.nodes[id];
  if (!node) return null;

  if (node.type === "repeater") {
    const arr = resolveValue(node.props.items as Bound<Json> | undefined, data);
    const items = Array.isArray(arr) ? arr : [];
    const template = childrenOf(doc, id)[0];
    return (
      <div data-cms={node.id} className={node.className}>
        {template
          ? items.map((item, index) => (
              <RenderNode key={index} doc={doc} id={template.id} registry={registry} data={{ ...data, item, index }} />
            ))
          : null}
      </div>
    );
  }

  const kids = childrenOf(doc, id).map((child) => (
    <RenderNode key={child.id} doc={doc} id={child.id} registry={registry} data={data} />
  ));

  const resolve = (v: Bound<Json> | undefined) => resolveValue(v, data);
  const text = (v: Bound<Json> | undefined): string => {
    const r = resolve(v);
    return r === undefined || r === null ? "" : String(r);
  };

  const renderer = registry[node.type];
  const inner = renderer ? renderer({ node, doc, children: kids, data, resolve, text }) : node.island ? null : kids;

  return (
    <div data-cms={node.id} data-cms-island={node.island ? node.type : undefined} className={node.className}>
      {inner}
    </div>
  );
}

import type { ReactNode } from "react";
import { isBinding, type Bound, type Json, type Node, type PageDoc } from "../lib/document/types";

/** The page data context bindings resolve against (e.g. server props, repeater `item`). */
export type DataContext = Record<string, unknown>;

export interface ElementContext {
  node: Node;
  doc: PageDoc;
  /** Pre-rendered child nodes, in order. */
  children: ReactNode;
  /** The data context this node renders in (page data + any repeater scope). */
  data?: DataContext;
  /** Resolve a (possibly bound) value to its raw resolved value. */
  resolve: (v: Bound<Json> | undefined) => unknown;
  /** Resolve a (possibly bound) value to a display string. */
  text: (v: Bound<Json> | undefined) => string;
}

/**
 * Renders the INNER content of a node. The outer `[data-cms]` wrapper is added
 * by {@link RenderNode}, so a renderer only returns what goes inside.
 */
export type ElementRenderer = (ctx: ElementContext) => ReactNode;

export type ElementRegistry = Record<string, ElementRenderer>;

/** Read a dotted path (`a.b.c`) out of the data context. */
export function getPath(data: DataContext | undefined, path: string): unknown {
  return path.split(".").reduce<unknown>((o, k) => (o == null ? undefined : (o as Record<string, unknown>)[k]), data);
}

/** Resolve a value: a `{ $bind }` reads from the data context; anything else is literal. */
export function resolveValue(v: Bound<Json> | undefined, data?: DataContext): unknown {
  if (v === undefined || v === null) return v;
  if (isBinding(v)) return getPath(data, v.$bind);
  return v;
}

/** Built-in native elements. Containers render their children; leaves render content. */
export const defaultRegistry: ElementRegistry = {
  section: ({ children }) => children,
  stack: ({ children }) => children,
  grid: ({ children }) => children,
  frame: ({ children }) => children,
  shape: ({ children }) => children,
  card: ({ children }) => children,
  text: ({ node, text }) => text(node.props.content),
  heading: ({ node, text }) => text(node.props.content) || "Heading",
  // Rich text — inline-formatted HTML (gradient spans, links, <code>, …) that
  // plain `text` can't express. The author owns the markup (it's their content).
  richtext: ({ node, text }) => <div dangerouslySetInnerHTML={{ __html: text(node.props.html) }} />,
  link: ({ node, text }) => (
    <a href={text(node.props.href) || "#"} style={{ color: "inherit", textDecoration: "underline" }}>
      {text(node.props.content) || "link"}
    </a>
  ),
  divider: () => <hr style={{ border: "none", borderTop: "1px solid #e2e8f0", margin: 0 }} />,
  callout: ({ node, text }) => {
    const tone = ({ info: "#3b82f6", success: "#10b981", warning: "#f59e0b", danger: "#ef4444" } as Record<string, string>)[text(node.props.variant)] ?? "#3b82f6";
    return (
      <div style={{ display: "flex", gap: 10, padding: "12px 14px", borderRadius: 10, background: `${tone}14`, borderLeft: `3px solid ${tone}` }}>
        <span style={{ fontSize: 13 }}>{text(node.props.content) || "Callout"}</span>
      </div>
    );
  },
  code: ({ node, text }) => (
    <pre style={{ margin: 0, padding: "12px 14px", borderRadius: 10, background: "#0b1220", color: "#e2e8f0", fontFamily: "ui-monospace, monospace", fontSize: 13, overflowX: "auto" }}>
      <code>{text(node.props.content)}</code>
    </pre>
  ),
  button: ({ node, text }) => {
    const label = text(node.props.label) || text(node.props.content) || "Button";
    const variant = text(node.props.variant) || "primary";
    return <span data-cms-button={variant} style={buttonStyle(variant)}>{label}</span>;
  },
  image: ({ node, text }) => (
    <img
      src={text(node.props.src)}
      alt={text(node.props.alt)}
      style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
    />
  ),
};

/**
 * A self-contained button look so the `button` primitive renders sensibly with
 * zero host CSS. Hosts that want their own button classes override the `button`
 * renderer in their registry (e.g. the sandbox maps it to `.btn .btn-primary`).
 */
function buttonStyle(variant: string): import("react").CSSProperties {
  const base: import("react").CSSProperties = {
    display: "inline-flex",
    alignItems: "center",
    gap: 6,
    padding: "9px 16px",
    borderRadius: 8,
    fontWeight: 600,
    fontSize: 14,
    lineHeight: 1,
    cursor: "pointer",
    userSelect: "none",
  };
  if (variant === "ghost") return { ...base, background: "transparent", color: "inherit", border: "1px solid currentColor" };
  if (variant === "outline") return { ...base, background: "transparent", color: "#7c3aed", border: "1px solid #7c3aed" };
  return { ...base, background: "#7c3aed", color: "#fff", border: "1px solid #7c3aed" };
}

/**
 * Stages document model — see `fancy-ui/docs/fancy-cms.md` §4.
 *
 * A page is a vertical stack of full-bleed **sections**; inside each, **layers**
 * are positioned by constraints (free + bold stays responsive), with stack/grid
 * containers where structure is wanted. Nodes live in a **flat map** keyed by id
 * (Figma-style) so ops target a stable identity and collab merges stay clean.
 */

import type { DocNode, DocTree } from "@particle-academy/fancy-doc-commons";

/** A node id. Alias of doc-commons' `DocId`, kept for readability in CMS code. */
export type NodeId = string;

export type ScrollMode = "snap" | "smooth";

/** Ordered, mobile-first. Convention: `"base" | "md" | "lg"`. */
export type Breakpoint = string;

export type Json = string | number | boolean | null | Json[] | { [key: string]: Json };

/** A literal value OR a binding into the page's data context (`{ $bind: "profile.coins" }`). */
export interface Binding {
  $bind: string;
  /**
   * Which live query this path reads from — `["catalog", "products"]`.
   *
   * Optional: a host-supplied static context is still legitimate, and every
   * document saved before this has no `$source`.
   *
   * When present it is the Live Contract's vocabulary — the same
   * `[namespace, resource, …]` shape `fancy-query`'s `liveKey()` produces —
   * NOT a CMS-local name. See `./bindings` for why that matters and for
   * `bindingSources()`, which answers "what does this page depend on?".
   */
  $source?: readonly (string | number)[];
}
export type Bound<T> = T | Binding;

export function isBinding(v: unknown): v is Binding {
  return typeof v === "object" && v !== null && typeof (v as Binding).$bind === "string";
}

// ── Sizing ────────────────────────────────────────────────────────────────

export type LengthUnit = "px" | "%" | "vw" | "vh" | "rem" | "fr";
export interface Length {
  value: number;
  unit: LengthUnit;
}
export type SizeMode = Length | "fill" | "hug";

export interface Constraints {
  /** Pinned offsets within a `free` parent (null = unpinned). */
  left?: Length | null;
  right?: Length | null;
  top?: Length | null;
  bottom?: Length | null;
  centerX?: boolean;
  centerY?: boolean;
  width: SizeMode;
  height: SizeMode;
}

export type LayoutMode = "free" | "stack" | "grid";

// ── Style (compiles deterministically to CSS in both emitters) ──────────────

export interface StyleProps {
  // box
  padding?: Length;
  margin?: Length;
  radius?: Length;
  // color / surface
  background?: string; // color | gradient | url(...)
  color?: string;
  opacity?: number;
  // typography
  fontFamily?: string;
  fontSize?: Length;
  fontWeight?: number;
  lineHeight?: number;
  textAlign?: "left" | "center" | "right" | "justify";
  letterSpacing?: Length;
  // border / shadow / effects (static)
  border?: string;
  boxShadow?: string;
  transform?: string;
  filter?: string;
  // container knobs (when layout = stack | grid)
  gap?: Length;
  direction?: "row" | "column";
  columns?: number;
  align?: "start" | "center" | "end" | "stretch";
  justify?: "start" | "center" | "end" | "between" | "around";
}

/** Per-breakpoint overrides; `base` is required, others cascade mobile-first. */
export type PerBreakpoint<T> = { base: T } & Partial<Record<Breakpoint, Partial<T>>>;

// ── Animation (typed for Phase 2; ignored by the static CSS emitter) ────────

export type AnimDriver = "enter" | "scroll" | "loop" | "hover" | "click" | "drag";
export interface Keyframe {
  at: number; // 0..1
  props: Record<string, number | string>;
}
export interface Anim {
  id: string;
  driver: AnimDriver;
  keyframes: Keyframe[];
  range?: { start: number; end: number };
  ease?: string;
  duration?: number;
  delay?: number;
  stagger?: number;
  once?: boolean;
  emit?: "css" | "js";
}

// ── Actions (typed for Phase 3/4) ───────────────────────────────────────────

export type ActionEvent = "click" | "submit" | "change" | "load" | "timer" | "scroll-into" | "hover";
export type ActionHandler =
  | { kind: "navigate"; href: Bound<string> }
  | { kind: "submitForm"; endpoint: string; method?: "post" | "put" }
  | { kind: "mutate"; target: string; value: Bound<Json> }
  | { kind: "callEndpoint"; endpoint: string; method?: string }
  | { kind: "runFlow"; flow: string }
  | { kind: "openModal"; node: NodeId }
  | { kind: "openDrawer"; node: NodeId }
  | { kind: "playTimeline"; section: NodeId }
  | { kind: "toggleNode"; node: NodeId };
export interface Action {
  on: ActionEvent;
  do: ActionHandler;
}

// ── Nodes & document ────────────────────────────────────────────────────────

/**
 * A page node.
 *
 * Extends {@link DocNode} from `fancy-doc-commons` rather than redeclaring it:
 * id / type / parent / order / props are the shared substrate every Fancy
 * document surface uses, and the CMS adds its own domain fields on top. That
 * is what lets `registerDocBridge` drive a CMS page and a fancy-screens screen
 * through the same tools, with no CMS-specific bridge.
 */
export interface Node extends DocNode<Record<string, Bound<Json>>> {
  /** Addon key: `section | text | image | shape | stack | grid | frame | <addon>`. */
  type: string;
  /** How this node arranges its children. */
  layout?: LayoutMode;
  /** How this node positions itself within its parent. */
  constraints?: PerBreakpoint<Constraints>;
  style: PerBreakpoint<StyleProps>;
  animations?: Anim[];
  actions?: Action[];
  /** Repeater: render this node once per item of a bound array. */
  repeat?: { each: Binding; as: string };
  /**
   * Host CSS class(es) applied to the node's element. The migration enabler:
   * reuse the host site's existing stylesheet for pixel-perfect reproduction
   * instead of re-deriving every rule through {@link StyleProps}.
   */
  className?: string;
  /** Derived from the addon manifest — interactive/3rd-party ⇒ hydration island. */
  island?: boolean;
}

export interface ThemeTokens {
  name?: string;
  [key: string]: Json | undefined;
}

export interface PageMeta {
  title: string;
  slug: string;
  scrollMode: ScrollMode;
  seo?: Record<string, string>;
}

export interface PageDoc {
  id: string;
  /** Op counter — collab ordering + revision checkpoints. */
  seq: number;
  meta: PageMeta;
  theme: ThemeTokens;
  /** Ordered, mobile-first. */
  breakpoints: Breakpoint[];
  /**
   * Flat map — not a nested tree. This is a {@link DocTree}, so every
   * doc-commons walk (`childrenOf`, `roots`, `descendantsOf`) works on it
   * directly.
   *
   * There is no separate `sections[]` any more. Top-level order used to live in
   * its own array while every other level used fractional `order` keys, which
   * meant two ordering mechanisms that could disagree — a node could be a root
   * by `parent === null` and absent from `sections`, and then simply not
   * render. Roots are now ordered exactly like any other sibling group.
   */
  nodes: Record<NodeId, Node>;
}

/** Runtime boundary check for the one structural field every document walk needs. */
export function hasNodeMap(value: unknown): value is { nodes: Record<NodeId, Node> } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const nodes = (value as { nodes?: unknown }).nodes;
  return typeof nodes === "object" && nodes !== null && !Array.isArray(nodes);
}

/** Default breakpoint → min-width (px) map. `base` has no media query. */
export const DEFAULT_BREAKPOINTS: Record<string, number> = {
  base: 0,
  md: 768,
  lg: 1024,
};

/** A minimal empty document. */
export function emptyDoc(id: string, slug = "/"): PageDoc {
  return {
    id,
    seq: 0,
    meta: { title: "Untitled", slug, scrollMode: "smooth" },
    theme: { name: "default" },
    breakpoints: ["base", "md", "lg"],
    nodes: {},
  };
}

/**
 * The JS style → CSS emitter (one half of the dual-emitter pair; the PHP
 * `particle-academy/fancy-cms` mirrors it byte-for-byte). Output is
 * **deterministic**: declarations are sorted, selectors and media blocks use a
 * fixed format, and nodes are emitted in sorted-id order — so the parity harness
 * can diff the two engines' CSS exactly.
 *
 * Phase 0 covers the static subset (layout / constraints / style). Motion lands
 * in Phase 2.
 */
import {
  DEFAULT_BREAKPOINTS,
  hasNodeMap,
  type Constraints,
  type Length,
  type Node,
  type PageDoc,
  type SizeMode,
  type StyleProps,
} from "../document/types";

const selectorFor = (id: string): string => `[data-cms="${id}"]`;

function lengthToCss(len: Length): string {
  return `${len.value}${len.unit}`;
}

function sizeToCss(size: SizeMode): string {
  if (size === "fill") return "100%";
  if (size === "hug") return "auto";
  return lengthToCss(size);
}

const ALIGN: Record<string, string> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  stretch: "stretch",
};
const JUSTIFY: Record<string, string> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  between: "space-between",
  around: "space-around",
};

/** Map StyleProps → CSS declarations (property → value). */
function styleDecls(style: Partial<StyleProps>): Record<string, string> {
  const d: Record<string, string> = {};
  if (style.padding) d["padding"] = lengthToCss(style.padding);
  if (style.margin) d["margin"] = lengthToCss(style.margin);
  if (style.radius) d["border-radius"] = lengthToCss(style.radius);
  if (style.background !== undefined) d["background"] = style.background;
  if (style.color !== undefined) d["color"] = style.color;
  if (style.opacity !== undefined) d["opacity"] = String(style.opacity);
  if (style.fontFamily !== undefined) d["font-family"] = style.fontFamily;
  if (style.fontSize) d["font-size"] = lengthToCss(style.fontSize);
  if (style.fontWeight !== undefined) d["font-weight"] = String(style.fontWeight);
  if (style.lineHeight !== undefined) d["line-height"] = String(style.lineHeight);
  if (style.textAlign !== undefined) d["text-align"] = style.textAlign;
  if (style.letterSpacing) d["letter-spacing"] = lengthToCss(style.letterSpacing);
  if (style.border !== undefined) d["border"] = style.border;
  if (style.boxShadow !== undefined) d["box-shadow"] = style.boxShadow;
  if (style.transform !== undefined) d["transform"] = style.transform;
  if (style.filter !== undefined) d["filter"] = style.filter;
  if (style.gap) d["gap"] = lengthToCss(style.gap);
  if (style.align !== undefined) d["align-items"] = ALIGN[style.align] ?? style.align;
  if (style.justify !== undefined) d["justify-content"] = JUSTIFY[style.justify] ?? style.justify;
  return d;
}

/** Container behaviour from `node.layout`. */
function layoutDecls(node: Node): Record<string, string> {
  const d: Record<string, string> = {};
  if (node.layout === "stack") {
    d["display"] = "flex";
    d["flex-direction"] = node.style.base.direction ?? "column";
  } else if (node.layout === "grid") {
    d["display"] = "grid";
    d["grid-template-columns"] = `repeat(${node.style.base.columns ?? 1}, 1fr)`;
  } else if (node.layout === "free") {
    d["position"] = "relative";
  }
  return d;
}

/** Self-positioning from constraints (absolute pins only inside a `free` parent). */
function constraintDecls(c: Partial<Constraints>, parentFree: boolean): Record<string, string> {
  const d: Record<string, string> = {};
  const transforms: string[] = [];
  if (parentFree) {
    d["position"] = "absolute";
    if (c.left) d["left"] = lengthToCss(c.left);
    if (c.right) d["right"] = lengthToCss(c.right);
    if (c.top) d["top"] = lengthToCss(c.top);
    if (c.bottom) d["bottom"] = lengthToCss(c.bottom);
    if (c.centerX) {
      d["left"] = "50%";
      transforms.push("translateX(-50%)");
    }
    if (c.centerY) {
      d["top"] = "50%";
      transforms.push("translateY(-50%)");
    }
    if (transforms.length) d["transform"] = transforms.join(" ");
  }
  if (c.width) d["width"] = sizeToCss(c.width);
  if (c.height) d["height"] = sizeToCss(c.height);
  return d;
}

function isParentFree(doc: PageDoc, node: Node): boolean {
  if (node.parent === null) return false; // sections stack in the page flow
  const parent = doc.nodes[node.parent];
  return !parent || parent.layout === undefined || parent.layout === "free";
}

function serializeRule(selector: string, decls: Record<string, string>, indent: string): string {
  const props = Object.keys(decls).sort();
  if (props.length === 0) return "";
  const body = props.map((p) => `${indent}  ${p}: ${decls[p]};`).join("\n");
  return `${indent}${selector} {\n${body}\n${indent}}`;
}

/** Emit the full stylesheet for a document. Deterministic. */
export function emitDocCss(doc: PageDoc): string {
  if (!hasNodeMap(doc)) return "";

  const breakpointPx = DEFAULT_BREAKPOINTS;
  const blocks: string[] = [];

  for (const id of Object.keys(doc.nodes).sort()) {
    const node = doc.nodes[id]!;
    const selector = selectorFor(id);
    const parentFree = isParentFree(doc, node);

    // base = style.base + layout + constraints.base
    const base: Record<string, string> = {
      ...layoutDecls(node),
      ...(node.constraints ? constraintDecls(node.constraints.base, parentFree) : {}),
      ...styleDecls(node.style.base),
    };
    const baseRule = serializeRule(selector, base, "");
    if (baseRule) blocks.push(baseRule);

    // per-breakpoint overrides (mobile-first, in doc order, skipping base)
    for (const bp of doc.breakpoints) {
      if (bp === "base") continue;
      const px = breakpointPx[bp];
      if (px === undefined) continue;
      const decls: Record<string, string> = {
        ...(node.constraints?.[bp] ? constraintDecls(node.constraints[bp]!, parentFree) : {}),
        ...(node.style[bp] ? styleDecls(node.style[bp]!) : {}),
      };
      const inner = serializeRule(selector, decls, "  ");
      if (inner) blocks.push(`@media (min-width: ${px}px) {\n${inner}\n}`);
    }
  }

  return blocks.join("\n\n") + (blocks.length ? "\n" : "");
}

/**
 * The pure, total reducer. `reduce(doc, op)` returns a new document; an invalid
 * op is a **logged no-op** (returns the same doc, `seq` unchanged). That single
 * property is what makes undo, revisions, collaboration, and agent edits all
 * flow through one spine.
 *
 * Ordering: EVERY level uses the fractional `order` field among siblings,
 * including the roots. Top-level order used to live in a separate `sections`
 * array, which meant two mechanisms that could disagree — a node could be a
 * root by `parent === null` and missing from `sections`, and then simply not
 * render, with nothing reporting it.
 */
import {
  childrenOf as docChildrenOf,
  descendantsOf,
  fractionalKey,
} from "@particle-academy/fancy-doc-commons";
import { hasNodeMap, type Action, type Node, type NodeId, type PageDoc, type StyleProps } from "./types";
import type { PageOp } from "./ops";

export interface ReduceOptions {
  /** Called when an op can't apply. Default: silent. */
  onInvalid?: (op: PageOp, reason: string) => void;
}

/**
 * Children of a node (or the roots when `parent` is null), in order.
 *
 * Delegates to doc-commons so the CMS, fancy-screens and any future surface
 * walk a document the same way. Roots are no longer a special case.
 */
export function childrenOf(doc: PageDoc, parent: NodeId | null): Node[] {
  return docChildrenOf<Node>(doc, parent);
}

/**
 * The top-level node ids, in order.
 *
 * Replaces the old `doc.sections` array. Kept as a named helper because the two
 * things callers actually wanted from that array — "list the roots" and "the
 * last root" — read badly as `childrenOf(doc, null).map(n => n.id)` at every
 * call site.
 */
export function rootIds(doc: PageDoc): NodeId[] {
  if (!hasNodeMap(doc)) return [];
  return childrenOf(doc, null).map((n) => n.id);
}

/** The last top-level node, or null — the default parent for a new insert. */
export function lastRootId(doc: PageDoc): NodeId | null {
  const r = rootIds(doc);
  return r[r.length - 1] ?? null;
}

/** Every transitive descendant id of `id` (excludes `id`). */
export function descendantIds(doc: PageDoc, id: NodeId): NodeId[] {
  return descendantsOf<Node>(doc, id);
}

function patchNode(doc: PageDoc, id: NodeId, patch: Partial<Node>): PageDoc {
  const node = doc.nodes[id]!;
  return {
    ...doc,
    nodes: { ...doc.nodes, [id]: { ...node, ...patch } },
    seq: doc.seq + 1,
  };
}

export function reduce(doc: PageDoc, op: PageOp, opts: ReduceOptions = {}): PageDoc {
  const invalid = (reason: string): PageDoc => {
    opts.onInvalid?.(op, reason);
    return doc;
  };

  switch (op.t) {
    case "insert_node": {
      if (doc.nodes[op.node.id]) return invalid("node id already exists");
      if (op.node.parent !== null && !doc.nodes[op.node.parent]) return invalid("parent not found");
      return {
        ...doc,
        nodes: { ...doc.nodes, [op.node.id]: op.node },
        seq: doc.seq + 1,
      };
    }

    case "remove_node": {
      if (!doc.nodes[op.id]) return invalid("node not found");
      const dead = new Set<NodeId>([op.id, ...descendantIds(doc, op.id)]);
      const nodes: Record<NodeId, Node> = {};
      for (const id of Object.keys(doc.nodes)) {
        if (!dead.has(id)) nodes[id] = doc.nodes[id]!;
      }
      return {
        ...doc,
        nodes,
        seq: doc.seq + 1,
      };
    }

    case "move_node": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      if (op.parent === op.id) return invalid("cannot parent a node to itself");
      if (op.parent !== null && !doc.nodes[op.parent]) return invalid("new parent not found");
      if (op.parent !== null && descendantIds(doc, op.id).includes(op.parent)) {
        return invalid("move would create a cycle");
      }
      return {
        ...doc,
        nodes: { ...doc.nodes, [op.id]: { ...node, parent: op.parent, order: op.order } },
        seq: doc.seq + 1,
      };
    }

    case "set_node_props": {
      if (!doc.nodes[op.id]) return invalid("node not found");
      return patchNode(doc, op.id, {
        props: { ...doc.nodes[op.id]!.props, ...op.patch } as unknown as Node["props"],
      });
    }

    case "set_layout": {
      if (!doc.nodes[op.id]) return invalid("node not found");
      return patchNode(doc, op.id, { layout: op.layout });
    }

    case "set_style": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      const prev = node.style[op.breakpoint] ?? {};
      return patchNode(doc, op.id, {
        style: { ...node.style, [op.breakpoint]: { ...prev, ...op.patch } } as Node["style"],
      });
    }

    case "set_constraints": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      const base = node.constraints ?? { base: { width: "hug", height: "hug" } };
      const prev = base[op.breakpoint] ?? {};
      return patchNode(doc, op.id, {
        constraints: { ...base, [op.breakpoint]: { ...prev, ...op.patch } } as Node["constraints"],
      });
    }

    case "set_animation": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      const list = node.animations ?? [];
      const idx = list.findIndex((a) => a.id === op.anim.id);
      return patchNode(doc, op.id, {
        animations: idx >= 0 ? list.map((a, i) => (i === idx ? op.anim : a)) : [...list, op.anim],
      });
    }

    case "remove_animation": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      return patchNode(doc, op.id, {
        animations: (node.animations ?? []).filter((a) => a.id !== op.animId),
      });
    }

    case "set_action": {
      const node = doc.nodes[op.id];
      if (!node) return invalid("node not found");
      const list = node.actions ?? [];
      let actions: Action[];
      if (op.action === null) actions = list.filter((_, i) => i !== op.index);
      else if (op.index >= list.length) actions = [...list, op.action];
      else actions = list.map((a, i) => (i === op.index ? op.action! : a));
      return patchNode(doc, op.id, { actions });
    }

    case "set_meta":
      return { ...doc, meta: { ...doc.meta, ...op.patch }, seq: doc.seq + 1 };

    case "set_theme":
      return { ...doc, theme: { ...doc.theme, ...op.patch }, seq: doc.seq + 1 };

    case "reorder_roots": {
      // Roots are ordered by their own fractional keys now, so a reorder
      // REWRITES those keys rather than replacing a list. Still validated as a
      // permutation: a partial list would silently drop roots out of the page.
      const currentRoots = childrenOf(doc, null);
      const current = new Set(currentRoots.map((n) => n.id));
      const same =
        op.order.length === currentRoots.length && op.order.every((id) => current.has(id));
      if (!same) return invalid("reorder must be a permutation of the current roots");

      const nodes = { ...doc.nodes };
      let prev: string | null = null;
      for (const id of op.order) {
        prev = fractionalKey(prev, null);
        nodes[id] = { ...nodes[id]!, order: prev };
      }
      return { ...doc, nodes, seq: doc.seq + 1 };
    }

    default:
      return invalid(`unknown op "${(op as PageOp).t}"`);
  }
}

/** Apply a sequence of ops, threading the document. */
export function reduceAll(doc: PageDoc, ops: PageOp[], opts?: ReduceOptions): PageDoc {
  return ops.reduce((d, op) => reduce(d, op, opts), doc);
}

/**
 * Inverse op(s) for undo, computed against the **pre-op** document. Structural
 * ops invert cleanly; merge-style ops (`set_props`/`set_style`/`set_constraints`)
 * restore the previous values of the touched keys (keys that did not previously
 * exist can't be deleted via a merge — a known Phase-0 limitation).
 */
export function invert(doc: PageDoc, op: PageOp): PageOp[] {
  switch (op.t) {
    case "insert_node":
      return [{ t: "remove_node", id: op.node.id }];

    case "remove_node": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      // Re-insert the subtree parent-first, then restore section order.
      const ids = [op.id, ...descendantIds(doc, op.id)];
      const inserts: PageOp[] = ids.map((id) => ({ t: "insert_node", node: doc.nodes[id]! }));
      if (node.parent === null) {
        inserts.push({ t: "reorder_roots", order: childrenOf(doc, null).map((n) => n.id) });
      }
      return inserts;
    }

    case "move_node": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      const back: PageOp[] = [{ t: "move_node", id: op.id, parent: node.parent, order: node.order }];
      if (node.parent === null) {
        back.push({ t: "reorder_roots", order: childrenOf(doc, null).map((n) => n.id) });
      }
      return back;
    }

    case "set_node_props": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      const prev: Record<string, unknown> = {};
      for (const k of Object.keys(op.patch)) prev[k] = node.props[k];
      return [{ t: "set_node_props", id: op.id, patch: prev }];
    }

    case "set_layout": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      return [{ t: "set_layout", id: op.id, layout: node.layout }];
    }

    case "set_style": {
      const node = doc.nodes[op.id];
      if (!node) return [];
      const prevBp = (node.style[op.breakpoint] ?? {}) as Record<string, unknown>;
      const prev: Partial<StyleProps> = {};
      for (const k of Object.keys(op.patch)) (prev as Record<string, unknown>)[k] = prevBp[k];
      return [{ t: "set_style", id: op.id, breakpoint: op.breakpoint, patch: prev }];
    }

    case "set_meta":
      return [{ t: "set_meta", patch: pick(doc.meta, Object.keys(op.patch)) }];

    case "set_theme":
      return [{ t: "set_theme", patch: pick(doc.theme, Object.keys(op.patch)) }];

    case "reorder_roots":
      return [{ t: "reorder_roots", order: childrenOf(doc, null).map((n) => n.id) }];

    default:
      return [];
  }
}

function pick<T extends object>(obj: T, keys: string[]): Partial<T> {
  const out: Partial<T> = {};
  for (const k of keys) (out as Record<string, unknown>)[k] = (obj as Record<string, unknown>)[k];
  return out;
}

/**
 * `PageOp` — the closed set of mutations. Every edit (human drag, agent tool
 * call, collab message) is one of these, reduced by the pure `reduce` in
 * `reduce.ts`. See `fancy-ui/docs/fancy-cms.md` §4.
 */
import type {
  Action,
  Anim,
  Breakpoint,
  Constraints,
  LayoutMode,
  Node,
  NodeId,
  PageMeta,
  StyleProps,
  ThemeTokens,
} from "./types";

export type Actor = { kind: "human" | "agent"; id: string };

export type PageOp =
  | { t: "insert_node"; node: Node }
  | { t: "remove_node"; id: NodeId }
  | { t: "move_node"; id: NodeId; parent: NodeId | null; order: string }
  /**
   * Renamed from `set_props` in 0.6.0, and the reason is a wire-format
   * collision rather than taste.
   *
   * `fancy-doc-commons`' `TreeOp` uses the SAME discriminator `t` and also had
   * a `set_props` variant with a byte-identical shape — so a stored
   * `{t:"set_props", id, patch}` was valid under two vocabularies and reduced
   * by two different reducers, with nothing in the document able to say which
   * one it meant.
   *
   * Every other variant here was already disjoint (`insert_node` vs `insert`,
   * `move_node` vs `move`), so closing the collision cost exactly one rename
   * rather than a versioned envelope on every op in the kit.
   */
  | { t: "set_node_props"; id: NodeId; patch: Record<string, unknown> }
  | { t: "set_layout"; id: NodeId; layout: LayoutMode | undefined }
  | { t: "set_style"; id: NodeId; breakpoint: Breakpoint; patch: Partial<StyleProps> }
  | { t: "set_constraints"; id: NodeId; breakpoint: Breakpoint; patch: Partial<Constraints> }
  | { t: "set_animation"; id: NodeId; anim: Anim }
  | { t: "remove_animation"; id: NodeId; animId: string }
  | { t: "set_action"; id: NodeId; index: number; action: Action | null }
  | { t: "set_meta"; patch: Partial<PageMeta> }
  | { t: "set_theme"; patch: Partial<ThemeTokens> }
  | { t: "reorder_roots"; order: NodeId[] };

export type PageOpType = PageOp["t"];

/** Wire envelope — carries provenance + ordering. `pending` = an agent proposal. */
export interface OpEnvelope {
  op: PageOp;
  actor: Actor;
  ts: number;
  seq: number;
  pending?: boolean;
}

import { createContext, useContext } from "react";
import type { CodeEditorContextValue } from "./CodeEditor.types";

