import type { ReactNode, RefObject } from "react";
import type { DiffAnnotations } from "@particle-academy/fancy-file-commons";
import type { UseEditorEngineReturn } from "../lib/hooks/use-editor-engine";

export interface CodeEditorProps {
  children: ReactNode;
  className?: string;
  /** Controlled value */
  value?: string;
  /** Initial value (uncontrolled) */
  defaultValue?: string;
  /** Called when the document changes */
  onChange?: (value: string) => void;
  /** Language name or alias (default: "javascript") */
  language?: string;
  /** Called when the language changes via the toolbar selector */
  onLanguageChange?: (lang: string) => void;
  /** Theme name: "light", "dark", "auto", or a custom registered name (default: "auto") */
  theme?: string;
  /** Prevent editing (default: false) */
  readOnly?: boolean;
  /** Show line numbers (default: true) */
  lineNumbers?: boolean;
  /** Enable word wrap (default: false) */
  wordWrap?: boolean;
  /** Tab size in spaces (default: 2) */
  tabSize?: number;
  /** Placeholder shown when empty */
  placeholder?: string;
  /** Minimum height in px */
  minHeight?: number;
  /** Maximum height in px (scrolls beyond this) */
  maxHeight?: number;
  /**
   * 1-based line to reveal (scroll to + place the caret on). Applied on mount
   * and whenever it (or `cursorColumn`) changes — so opening a file *at* a line,
   * or re-targeting an already-open file, scrolls the line into view. Does not
   * steal focus; call the imperative `revealLine`/`setCursor` (or `focus`) for
   * that. Out-of-range values clamp to document bounds.
   */
  cursorLine?: number;
  /** 1-based column for {@link cursorLine} (default 1). */
  cursorColumn?: number;
  /**
   * 1-based lines to mark with a full-width band — "here is the line you were
   * sent to". Purely visual and independent of the caret; lines outside the
   * document are ignored. Sized for unwrapped lines, as the gutter is.
   */
  highlightLines?: readonly number[];
  /**
   * Baseline document for the diff gutter. When set, the line-number column
   * shows per-line change marks of the CURRENT value against this baseline —
   * VS Code convention: a green bar for added lines, a blue bar for modified
   * lines, and a red wedge where lines were deleted. Recomputed live as the
   * user types (line-level only — cheap). `null`/omitted disables the gutter
   * marks. Requires `lineNumbers`.
   */
  diffBase?: string | null;
}

export interface CodeEditorContextValue {
  /** Get the current document text */
  getValue: () => string;
  /** Get the currently selected text */
  getSelection: () => string;
  /** Replace the entire document */
  setValue: (value: string) => void;
  /** Replace the current selection */
  replaceSelection: (text: string) => void;
  /** Focus the editor */
  focus: () => void;
  /**
   * Scroll to + place the caret on a 1-based `line` (optional 1-based `column`),
   * focusing the editor. Out-of-range positions clamp to document bounds.
   */
  revealLine: (line: number, column?: number) => void;
  /** Place the caret at a 1-based `{ line, column }` and reveal it (focuses). */
  setCursor: (pos: { line: number; column?: number }) => void;
  /** Current language name */
  language: string;
  /** Change the active language */
  setLanguage: (lang: string) => void;
  /** Current theme name */
  theme: string;
  /** Whether the editor is read-only */
  readOnly: boolean;
  /** Whether line numbers are shown */
  lineNumbers: boolean;
  /** Whether word wrap is enabled */
  wordWrap: boolean;
  /** Current tab size */
  tabSize: number;
  /** Toggle word wrap on/off */
  toggleWordWrap: () => void;
  /** Toggle line numbers on/off */
  toggleLineNumbers: () => void;
  /** Copy entire document to clipboard */
  copyToClipboard: () => Promise<void>;
  /** Current cursor position */
  cursorPosition: { line: number; col: number };
  /** Length of the current selection (0 if none) */
  selectionLength: number;
  /**
   * Ref to the underlying `<textarea>` element. Exposed so external
   * widgets — e.g. `<InputTag>`'s `textareaAdapter` — can attach to
   * the same input the editor renders into. Will be `null` before
   * the editor has mounted.
   */
  textareaRef: RefObject<HTMLTextAreaElement | null>;
  /** Placeholder text */
  placeholder?: string;
  /**
   * Totals of the live diff against {@link CodeEditorProps.diffBase} —
   * `{ added, modified, removed }` — or `null` when no baseline is set.
   * Handy for a status-bar chip or a host's save indicator.
   */
  diffStats: { added: number; modified: number; removed: number } | null;
  /** @internal — per-line gutter annotations for the diff marks. */
  _diffAnnotations: DiffAnnotations | null;
  /** @internal */
  _engineReturn: UseEditorEngineReturn | null;
  /** @internal */
  _minHeight?: number;
  /** @internal */
  _maxHeight?: number;
  /** @internal — lines to band; see {@link CodeEditorProps.highlightLines}. */
  _highlightLines?: readonly number[];
}

export interface CodeEditorToolbarProps {
  children?: ReactNode;
  className?: string;
}

export interface CodeEditorPanelProps {
  className?: string;
}

export interface CodeEditorStatusBarProps {
  children?: ReactNode;
  className?: string;
}

import { useMemo } from "react";
import { cn } from "@particle-academy/react-fancy";
import { useCodeEditor } from "./CodeEditor.context";
import {
  diffMarkColor,
  diffRemovedColor,
  gutterDiffMark,
  hasDeletedAtEnd,
} from "./diff-gutter";
import type { CodeEditorPanelProps } from "./CodeEditor.types";

export function CodeEditorPanel({ className }: CodeEditorPanelProps) {
  const {
    _engineReturn: engine,
    lineNumbers,
    wordWrap,
    readOnly,
    placeholder,
    _diffAnnotations: diffAnnotations,
    _maxHeight,
    _minHeight,
    _highlightLines: highlightLines,
  } = useCodeEditor();

  // This `useMemo` MUST run before the `!engine` guard below it.
  //
  // The guard used to come first, so a render without an engine ran ZERO hooks
  // and the next one ran one. React compares hook counts between renders, so
  // that transition desyncs the hook order and throws from deep inside React,
  // naming none of this code. `_engineReturn` is typed `| null` and starts null,
  // so the transition is real rather than theoretical.
  //
  // Reading the engine's fields inside the callback (rather than destructuring
  // above) is what lets the hook run unconditionally.
  const lineNumberElements = useMemo(() => {
    if (!engine || !lineNumbers) return null;
    const { themeColors, lineCount, activeLine } = engine;
    const removed = diffRemovedColor(themeColors);
    const highlighted = new Set(highlightLines ?? []);
    const lines = [];
    for (let i = 1; i <= lineCount; i++) {
      const mark = gutterDiffMark(diffAnnotations, i);
      lines.push(
        <div
          key={i}
          data-diff={mark?.type}
          data-diff-deleted-above={mark?.deletedAbove ? "" : undefined}
          style={{
            position: "relative",
            color: i === activeLine || highlighted.has(i) ? themeColors.foreground : themeColors.gutterForeground,
            backgroundColor: i === activeLine ? themeColors.activeLineBackground : undefined,
            fontWeight: highlighted.has(i) ? 600 : undefined,
          }}
          className="pr-3 text-right text-[13px] leading-[1.5] select-none"
        >
          {/* Change bar — VS Code convention: green added, blue modified. */}
          {mark?.type && (
            <span
              aria-hidden="true"
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                bottom: 0,
                width: 3,
                borderRadius: 2,
                backgroundColor: diffMarkColor(mark.type, themeColors),
              }}
            />
          )}
          {/* Deletion wedge — lines were removed immediately above this one. */}
          {mark?.deletedAbove && (
            <span
              aria-hidden="true"
              style={{
                position: "absolute",
                left: 0,
                top: -4,
                width: 0,
                height: 0,
                borderLeft: `8px solid ${removed}`,
                borderTop: "4px solid transparent",
                borderBottom: "4px solid transparent",
              }}
            />
          )}
          {i}
          {/* Deletion at EOF — removed lines hang below the last line. */}
          {i === lineCount && hasDeletedAtEnd(diffAnnotations) && (
            <span
              aria-hidden="true"
              data-diff-deleted-at-end=""
              style={{
                position: "absolute",
                left: 0,
                bottom: -4,
                width: 0,
                height: 0,
                borderLeft: `8px solid ${removed}`,
                borderTop: "4px solid transparent",
                borderBottom: "4px solid transparent",
              }}
            />
          )}
        </div>,
      );
    }
    return lines;
  }, [engine, lineNumbers, diffAnnotations, highlightLines]);

  // Every hook is above this line.
  if (!engine) return null;

  const {
    textareaRef,
    highlightedHtml,
    lineCount,
    activeLine,
    themeColors,
    handleKeyDown,
    handleInput,
    handleScroll,
    handleSelect,
    scrollTop,
    scrollLeft,
  } = engine;

  const gutterWidth = lineNumbers ? `${Math.max(String(lineCount).length, 2) * 0.75 + 1.5}em` : "0";

  const containerStyle: React.CSSProperties = {
    backgroundColor: themeColors.background,
    color: themeColors.foreground,
    minHeight: _minHeight,
    maxHeight: _maxHeight,
  };

  const isEmpty = textareaRef.current ? textareaRef.current.value.length === 0 : highlightedHtml.length === 0;

  return (
    <div
      data-fancy-code-panel=""
      className={cn("relative overflow-auto", className)}
      style={containerStyle}
    >
      <div className="flex min-h-full">
        {/* Line numbers gutter */}
        {lineNumbers && (
          <div
            className="sticky left-0 z-10 shrink-0 pt-2.5 pb-2.5 pl-2"
            style={{
              backgroundColor: themeColors.gutterBackground,
              borderRight: `1px solid ${themeColors.gutterBorder}`,
              width: gutterWidth,
            }}
          >
            {lineNumberElements}
          </div>
        )}

        {/* Editor area */}
        <div className={cn("relative flex-1", wordWrap && "min-w-0")}>
          {/*
            Line bands — "here is the line you were sent to". Behind the code, and
            placed in em so they track the 13px / 1.5 line grid the gutter uses;
            0.625rem is the editor's top padding (p-2.5).
          */}
          {(highlightLines ?? [])
            .filter((n) => Number.isInteger(n) && n >= 1 && n <= lineCount)
            .map((n) => (
              <div
                key={`highlight-${n}`}
                data-fancy-code-highlight-line={n}
                aria-hidden="true"
                className="pointer-events-none absolute inset-x-0 text-[13px] leading-[1.5]"
                style={{
                  top: `calc(0.625rem + ${(n - 1) * 1.5}em)`,
                  height: "1.5em",
                  backgroundColor: themeColors.selectionBackground,
                  opacity: 0.55,
                }}
              />
            ))}

          {/* Highlighted code overlay */}
          <pre
            className="pointer-events-none absolute inset-0 m-0 overflow-hidden border-none p-2.5 text-[13px] leading-[1.5]"
            aria-hidden="true"
            style={{
              whiteSpace: wordWrap ? "pre-wrap" : "pre",
              overflowWrap: wordWrap ? "break-word" : "normal",
            }}
          >
            <code dangerouslySetInnerHTML={{ __html: highlightedHtml + "\n" }} />
          </pre>

          {/* Placeholder */}
          {placeholder && isEmpty && (
            <div
              className="pointer-events-none absolute left-0 top-0 p-2.5 text-[13px] leading-[1.5] opacity-40"
              style={{ color: themeColors.foreground }}
            >
              {placeholder}
            </div>
          )}

          {/* Actual textarea for input */}
          <textarea
            ref={textareaRef}
            className={cn(
              "relative m-0 block resize-none border-none bg-transparent p-2.5 text-[13px] leading-[1.5] text-transparent outline-none",
              wordWrap ? "w-full" : "min-w-full",
            )}
            style={{
              caretColor: themeColors.cursorColor,
              minHeight: _minHeight ? _minHeight - 40 : 80,
              overflow: "hidden",
              whiteSpace: wordWrap ? "pre-wrap" : "pre",
              overflowWrap: wordWrap ? "break-word" : "normal",
            }}
            spellCheck={false}
            autoComplete="off"
            autoCorrect="off"
            autoCapitalize="off"
            readOnly={readOnly}
            onKeyDown={handleKeyDown}
            onInput={handleInput}
            onScroll={handleScroll}
            onSelect={handleSelect}
            onClick={handleSelect}
          />
        </div>
      </div>
    </div>
  );
}

