export { registerLanguage, getLanguage, getRegisteredLanguages } from "./registry";

// Register built-in languages on import
import "./builtin";

// `ThemeColors` (the token/chrome palette) is defined in
// @particle-academy/fancy-file-commons and re-exported here. `ThemeDefinition`
// — the named, registrable wrapper — stays local to fancy-code's theme registry.
export type { ThemeColors } from "@particle-academy/fancy-file-commons";
import type { ThemeColors } from "@particle-academy/fancy-file-commons";

export interface ThemeDefinition {
  /** Unique theme name */
  name: string;
  /** Whether this is a dark or light theme */
  variant: "light" | "dark";
  /** Color definitions */
  colors: ThemeColors;
}

export type { ThemeDefinition, ThemeColors } from "./types";
export { registerTheme, getTheme, getRegisteredThemes } from "./registry";

// Register built-in themes on import
import "./light";
import "./dark";

// `highlightCode` now lives in @particle-academy/fancy-file-commons (shared
// pure core). Re-exported so existing `../engine/highlight` imports are stable.
export { highlightCode } from "@particle-academy/fancy-file-commons";

/**
 * Convert a 1-based `line` / `column` into a 0-based character offset within
 * `text`. Out-of-range values clamp to the document and line bounds, so the
 * result is always a valid offset in `[0, text.length]`.
 *
 * - `line` below 1 clamps to line 1; above the last line clamps to the last line.
 * - `column` below 1 clamps to column 1; past the end of the line clamps to just
 *   after the last character (so you can place the caret at the line end).
 */
export function lineColumnToOffset(text: string, line: number, column = 1): number {
  const lines = text.split("\n");
  const targetLine = Math.max(1, Math.min(Math.trunc(line) || 1, lines.length));

  let offset = 0;
  for (let i = 0; i < targetLine - 1; i++) {
    offset += lines[i].length + 1; // +1 for the consumed "\n"
  }

  const lineText = lines[targetLine - 1] ?? "";
  const col = Math.max(1, Math.min(Math.trunc(column) || 1, lineText.length + 1));
  return offset + (col - 1);
}

// The tokenizer primitives now live in @particle-academy/fancy-file-commons
// (the shared pure core). Re-exported here so fancy-code's tokenizers and
// engine keep their existing `../tokenizer` import paths unchanged.
export type { Token, TokenType, Tokenizer } from "@particle-academy/fancy-file-commons";
export { tok } from "@particle-academy/fancy-file-commons";

import type { Tokenizer } from "../engine/tokenizer";

export interface LanguageDefinition {
  /** Display name shown in UI (e.g., "JavaScript") */
  name: string;
  /** Alternative keys (e.g., ["js", "javascript"]) */
  aliases?: string[];
  /** Tokenizer function for syntax highlighting */
  tokenize: Tokenizer;
}

import type { LanguageDefinition } from "./types";

const languageRegistry = new Map<string, LanguageDefinition>();

export function registerLanguage(def: LanguageDefinition): void {
  languageRegistry.set(def.name.toLowerCase(), def);
  if (def.aliases) {
    for (const alias of def.aliases) {
      languageRegistry.set(alias.toLowerCase(), def);
    }
  }
}

export function getLanguage(name: string): LanguageDefinition | undefined {
  return languageRegistry.get(name.toLowerCase());
}

export function getRegisteredLanguages(): string[] {
  const seen = new Set<LanguageDefinition>();
  const names: string[] = [];
  for (const [, def] of languageRegistry) {
    if (!seen.has(def)) {
      seen.add(def);
      names.push(def.name);
    }
  }
  return names;
}

import type { ThemeDefinition } from "./types";

const themeRegistry = new Map<string, ThemeDefinition>();

export function registerTheme(theme: ThemeDefinition): void {
  themeRegistry.set(theme.name.toLowerCase(), theme);
}

export function getTheme(name: string): ThemeDefinition | undefined {
  return themeRegistry.get(name.toLowerCase());
}

export function getRegisteredThemes(): string[] {
  return Array.from(themeRegistry.keys());
}

import { useEffect, useMemo, useRef, useSyncExternalStore } from "react";
import {
  highlightCode,
  tokenizeHtml,
  LIGHT_COLORS,
  DARK_COLORS,
  type ThemeColors,
} from "@particle-academy/fancy-file-commons";
import { cn } from "../lib/utils/cn";
import type { CodeViewProps } from "./CodeView.types";

// ── Dark-mode detection ────────────────────────────────────────────────────
// The highlight palette is baked in as inline colors, so we resolve light/dark
// ourselves. Follow BOTH signals so we match whatever drives the surrounding
// `dark:` Tailwind variants: the `.dark` class (class strategy) OR the
// prefers-color-scheme media query (media strategy).

function subscribeDark(callback: () => void): () => void {
  const mq = window.matchMedia("(prefers-color-scheme: dark)");
  mq.addEventListener("change", callback);
  const observer = new MutationObserver(callback);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class"],
  });
  return () => {
    mq.removeEventListener("change", callback);
    observer.disconnect();
  };
}

function darkSnapshot(): boolean {
  return (
    document.documentElement.classList.contains("dark") ||
    window.matchMedia("(prefers-color-scheme: dark)").matches
  );
}

function useIsDark(): boolean {
  return useSyncExternalStore(subscribeDark, darkSnapshot, () => false);
}

// Shared text metrics — the overlay and the textarea MUST match exactly (font,
// size, line-height, padding, wrapping) so the highlighted glyphs sit under the
// caret. Keep this string identical on both layers.
const TEXT_METRICS = "m-0 p-3 font-mono text-xs leading-relaxed";

/**
 * A lightweight, syntax-highlighted source view built on the pure highlight
 * primitives in `@particle-academy/fancy-file-commons` — a highlight overlay
 * with a transparent, auto-growing textarea on top; the container scrolls both
 * together. Fills its parent's height (`h-full`) and grows with content down to
 * `minHeight`. Only HTML is highlighted; other languages render as plain text.
 */
export function CodeView({
  value,
  onChange,
  language = "plaintext",
  readOnly = false,
  placeholder,
  minHeight = 120,
  maxHeight,
  className,
}: CodeViewProps) {
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const isDark = useIsDark();
  const colors: ThemeColors = isDark ? DARK_COLORS : LIGHT_COLORS;

  const highlighted = useMemo(() => {
    const tokens = language === "html" ? tokenizeHtml(value) : [];
    return highlightCode(value, tokens, colors);
  }, [value, language, colors]);

  // Grow the textarea to its content height so it never scrolls internally —
  // the outer container owns scrolling and moves overlay + textarea in lockstep.
  useEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${el.scrollHeight}px`;
  }, [value]);

  const editable = !readOnly && !!onChange;

  return (
    <div
      data-react-fancy-code-view=""
      // No baked-in height: the consumer picks the fill mechanism — `flex-1`
      // inside a flex column (the Editor source body), or `h-full` when the
      // parent has a definite height. A hard-coded `h-full` here collapses to
      // content height under a flex-computed (indefinite) parent.
      className={cn("relative overflow-auto", className)}
      style={{ backgroundColor: colors.background, color: colors.foreground, minHeight, maxHeight }}
    >
      <div className="relative min-h-full">
        {/* Highlight overlay */}
        <pre
          aria-hidden="true"
          className={cn("pointer-events-none absolute inset-0 overflow-hidden border-none", TEXT_METRICS)}
          style={{ whiteSpace: "pre-wrap", overflowWrap: "break-word" }}
        >
          <code dangerouslySetInnerHTML={{ __html: highlighted + "\n" }} />
        </pre>

        {/* Placeholder */}
        {placeholder && value.length === 0 && (
          <div className={cn("pointer-events-none absolute left-0 top-0 opacity-40", TEXT_METRICS)}>
            {placeholder}
          </div>
        )}

        {/* Transparent input layer (caret + selection visible, glyphs from overlay) */}
        <textarea
          ref={textareaRef}
          data-react-fancy-code-view-input=""
          value={value}
          onChange={editable ? (e) => onChange!(e.target.value) : undefined}
          readOnly={!editable}
          spellCheck={false}
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="off"
          aria-label={placeholder}
          className={cn(
            "relative block w-full resize-none border-none bg-transparent text-transparent outline-none",
            TEXT_METRICS,
          )}
          style={{
            caretColor: colors.cursorColor,
            overflow: "hidden",
            whiteSpace: "pre-wrap",
            overflowWrap: "break-word",
            minHeight,
          }}
        />
      </div>
    </div>
  );
}

CodeView.displayName = "CodeView";

export interface CodeViewProps {
  /** Source text to display / edit. Controlled. */
  value: string;
  /**
   * Called on edit. Omit (or set `readOnly`) for a read-only view. When
   * provided, the view is an editable source surface (transparent textarea over
   * the highlight overlay).
   */
  onChange?: (value: string) => void;
  /**
   * Language id for syntax highlighting. Only `"html"` is highlighted (the one
   * grammar shipped by `fancy-file-commons`); everything else — including
   * `"markdown"` and `"plaintext"` — renders un-highlighted. For richer language
   * highlighting use `@particle-academy/fancy-code`'s `CodeEditor`.
   * @default "plaintext"
   */
  language?: "html" | "markdown" | "plaintext" | (string & {});
  /** Read-only mode (no editing even if `onChange` is passed). @default false */
  readOnly?: boolean;
  /** Placeholder shown when empty. */
  placeholder?: string;
  /** Min height in px before the view grows with content. @default 120 */
  minHeight?: number;
  /** Max height in px before the view scrolls internally. */
  maxHeight?: number;
  /** Additional classes on the scroll container (e.g. `h-full`, `flex-auto`). */
  className?: string;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

