import { Button, Form, Input, Textarea } from "@particle-academy/react-fancy";
import type { FieldMode } from "@particle-academy/react-fancy";

export interface CommitDraft {
  message: string;
  description?: string;
}

export interface CommitComposerProps {
  value: CommitDraft;
  onChange: (value: CommitDraft) => void;
  onSubmit?: (value: CommitDraft) => void;
  pending?: boolean;
  /**
   * `"view"` renders the draft as text instead of fields.
   *
   * This is the propose-then-confirm half of the package's trust-but-verify
   * shape: an agent fills a draft, and the human reviewing it should be reading
   * a message, not looking at an edit form they might change by accident.
   */
  mode?: FieldMode;
  className?: string;
}

/**
 * A commit message, and the intent to commit it.
 *
 * `<Form>` rather than a bare `<form>`, which is what makes `mode` work: it
 * broadcasts the field mode to every input inside, so the whole composer flips
 * to read-only in one prop rather than each field growing its own branch.
 */
export function CommitComposer({ value, onChange, onSubmit, pending, mode, className }: CommitComposerProps) {
  return (
    <Form
      className={className}
      mode={mode}
      data-git-commit-composer=""
      onSubmit={(event) => {
        event.preventDefault();
        onSubmit?.(value);
      }}
    >
      <Input
        label="Summary"
        required
        value={value.message}
        onValueChange={(message) => onChange({ ...value, message })}
        placeholder="Fix the merge point"
      />
      <Textarea
        label="Description"
        rows={3}
        value={value.description ?? ""}
        onValueChange={(description) => onChange({ ...value, description })}
      />
      <Button type="submit" size="sm" disabled={pending || !value.message.trim()}>
        Review commit proposal
      </Button>
    </Form>
  );
}

import { Avatar, Button, Text } from "@particle-academy/react-fancy";
import type { Commit } from "@particle-academy/fancy-git";

/**
 * Initials for an author name, for the avatar fallback.
 *
 * Git author names are free text — "Ada Lovelace", "ada", "dependabot[bot]" —
 * so this takes the first letter of the first two words and gives up gracefully
 * rather than assuming a first/last shape that plenty of commits do not have.
 */
function initials(name: string): string {
  return (
    name
      .split(/[\s_-]+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0]?.toUpperCase() ?? "")
      .join("") || "?"
  );
}

export interface CommitHistoryProps {
  value: Commit[];
  selectedId?: string;
  onSelectedIdChange?: (id: string) => void;
  onLoadMore?: () => void;
  hasMore?: boolean;
  className?: string;
}

/**
 * A log, with a selected commit.
 *
 * Each row stays a `<button>` rather than becoming a `<Timeline>` event: the
 * point of this surface is *selecting* a commit, and Timeline's events are
 * presentational — swapping to it would render a prettier list you cannot
 * click. So the primitives that earn their place are the ones inside the row:
 * `<Avatar>` for the author, `<Text>` for the subject, `<Button>` for the
 * pager.
 *
 * A worked example of the rule this package got wrong: reach for a primitive
 * where it carries the behaviour, not wherever the shape looks similar.
 */
export function CommitHistory({
  value,
  selectedId,
  onSelectedIdChange,
  onLoadMore,
  hasMore,
  className,
}: CommitHistoryProps) {
  return (
    <section className={className} data-git-commit-history="" aria-label="Commit history">
      <ol>
        {value.map((commit) => (
          <li key={commit.id} data-git-commit-id={commit.id} data-selected={selectedId === commit.id || undefined}>
            <button
              type="button"
              aria-pressed={selectedId === commit.id}
              onClick={() => onSelectedIdChange?.(commit.id)}
            >
              <Avatar fallback={initials(commit.authorName)} alt={commit.authorName} size="xs" />
              <span data-git-commit-body="">
                <Text size="sm" className="!font-medium">
                  {commit.subject}
                </Text>
                <Text size="xs" className="!text-zinc-500">
                  <code>{commit.shortId}</code> · {commit.authorName}
                </Text>
              </span>
            </button>
          </li>
        ))}
      </ol>

      {hasMore && (
        <Button type="button" variant="ghost" size="sm" onClick={onLoadMore}>
          Load more
        </Button>
      )}
    </section>
  );
}

import { forwardRef, useCallback, useMemo, useRef } from "react";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import {
  endsOf,
  InlinePasteEditor,
  PastedFilesInput,
  useInlinePaste,
  withSeparators,
  type HeldPaste,
  type InlinePasteEditorHandle,
} from "../paste-pills";
import type { ComposerProps } from "./Composer.types";

/** Characters of a held paste shown at each end of the hover preview, unless `previewChars` says otherwise. */
const PREVIEW_CHARS = 20;

export const Composer = forwardRef<HTMLDivElement, ComposerProps>(
  function Composer(
    {
      value: controlledValue,
      defaultValue = "",
      onChange,
      onSubmit,
      placeholder = "Type a message...",
      actions,
      disabled = false,
      className,
      pasteThreshold,
      pastePlacement = "above",
      pasteImages = false,
      previewChars = PREVIEW_CHARS,
      renderPastePreview,
      classNames,
      heldPastes: controlledHeldPastes,
      onHeldPastesChange,
      heldImages: controlledHeldImages,
      onHeldImagesChange,
      pasteFilesName,
    },
    ref,
  ) {
    const inline = pastePlacement === "inline";
    const [value, setValue] = useControllableState(
      controlledValue,
      defaultValue,
      onChange,
    );
    const textareaRef = useRef<HTMLTextAreaElement>(null);
    const editorRef = useRef<InlinePasteEditorHandle>(null);
    /*
     * The holding logic lives in `usePastePills`, wrapped by `useInlinePaste` for
     * the inline placement — which `PromptInput` shares, so the two components
     * cannot disagree about what a pill means. The rule that must not drift is
     * the one below: a send with pills still closed carries the text.
     */
    const paste = useInlinePaste({
      pasteThreshold,
      pasteImages,
      previewChars,
      renderPastePreview,
      classNames,
      disabled,
      heldPastes: controlledHeldPastes,
      onHeldPastesChange,
      heldImages: controlledHeldImages,
      onHeldImagesChange,
      editorRef,
    });
    const pills = paste.pills;
    const heldPastes = paste.heldPastes;
    const pastedFiles = useMemo(
      () => (inline && pasteImages ? paste.imagesIn(value).map((i) => i.file) : []),
      [inline, pasteImages, paste, value],
    );

    const handlePaste = useCallback(
      (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
        // Composable by design, so this reads as a question rather than a handover.
        // Nothing else here wants the paste, so the answer is simply ignored.
        pills.handlePaste(e);
      },
      [pills],
    );

    const handleInlineChange = useCallback(
      (next: string) => {
        setValue(next);
        paste.prune(next);
      },
      [setValue, paste],
    );

    /** Everything the person believes they are sending, in the order they built it. */
    const composeOutgoing = useCallback(() => {
      if (inline) return paste.expand(value);

      return [value, ...heldPastes.map((p) => p.text)].filter(Boolean).join("\n\n");
    }, [inline, value, heldPastes, paste]);

    const hasContent = value.trim().length > 0 || (!inline && heldPastes.length > 0);

    const focusInput = useCallback(() => {
      if (inline) editorRef.current?.focus();
      else textareaRef.current?.focus();
    }, [inline]);

    const handleSubmit = useCallback(() => {
      if (!hasContent || disabled) return;

      /*
       * THE DANGEROUS STATE, and the reason this feature needed a spec rather than
       * a guess. A pill reads as "your paste is attached" — so a send that drops it
       * means asking a question about a document without the document, and nobody
       * can tell: the sender believes it went, the receiver sees a question about
       * nothing.
       *
       * Above the input, held pastes go out in arrival order after what was typed,
       * because people type the question BEFORE pasting the thing it is about.
       * Inline, every pill goes out exactly where it sits.
       */
      const images = inline ? paste.imagesIn(value) : [];

      onSubmit?.(composeOutgoing(), { images });
      setValue("");
      paste.clear();
      focusInput();
    }, [hasContent, disabled, value, inline, paste, onSubmit, composeOutgoing, setValue, focusInput]);

    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        handleSubmit();
      }
    };

    /** Above the input: click a pill to dump it in, APPENDED to what is already typed. */
    const insertPaste = useCallback(
      (held: HeldPaste) => {
        // `expand` removes it and hands back the text; inserting is this
        // component's job because the hook owns no DOM.
        const text = pills.expand(held.id);

        if (text === undefined) return;

        setValue((current) => (current ? `${current}\n\n${text}` : text));
        textareaRef.current?.focus();
      },
      [pills, setValue],
    );

    return (
      <div
        data-react-fancy-composer=""
        ref={ref}
        className={cn(
          "rounded-xl border border-zinc-200 bg-white dark:border-zinc-700 dark:bg-zinc-900",
          disabled && "opacity-50",
          className,
        )}
      >
        {!inline && heldPastes.length > 0 && (
          <div
            data-react-fancy-composer-paste-pills=""
            className="flex flex-wrap gap-1.5 px-3 pt-3"
          >
            {heldPastes.map((paste) => (
              // `group` + `group-hover` rather than hover state: the preview is
              // presentation, and a useState for it would be one more thing an
              // agent could desynchronise.
              <span key={paste.id} className="group relative inline-flex">
                <button
                  type="button"
                  data-react-fancy-composer-paste-pill={paste.id}
                  onClick={() => insertPaste(paste)}
                  disabled={disabled}
                  // No `title`. A native tooltip plus the hover preview below
                  // renders TWO tooltips on the same hover, at different delays.
                  // The label says what clicking does; the preview says what the
                  // text is, and it is linked rather than merely adjacent so a
                  // screen reader reaches it too.
                  aria-label={`Insert this pasted text, ${withSeparators(paste.text.length)} characters`}
                  aria-describedby={`${paste.id}-preview`}
                  // `pr-7` leaves room for the absolutely-positioned × that sits
                  // over this button's right edge. With a smaller right padding the
                  // × lands on top of the label.
                  className={cn(
                    "inline-flex items-center gap-1.5 rounded-full border border-zinc-200 bg-zinc-50 py-1 pl-2.5 pr-7 text-xs text-zinc-700 transition-colors hover:bg-zinc-100 dark:border-zinc-700 dark:bg-zinc-800 dark:text-zinc-200 dark:hover:bg-zinc-700",
                    classNames?.pill,
                    classNames?.textPill,
                  )}
                >
                  <span>
                    Pasted text · {withSeparators(paste.text.length)} characters
                  </span>
                </button>

                <button
                  type="button"
                  data-react-fancy-composer-paste-pill-remove={paste.id}
                  onClick={() => pills.remove(paste.id)}
                  disabled={disabled}
                  aria-label="Discard this pasted text"
                  className={cn(
                    "absolute right-1 top-1/2 -translate-y-1/2 rounded-full px-1 text-xs text-zinc-400 transition-colors hover:text-zinc-700 dark:hover:text-zinc-100",
                    classNames?.remove,
                  )}
                >
                  ×
                </button>

                <span
                  id={`${paste.id}-preview`}
                  data-react-fancy-composer-paste-pill-preview={paste.id}
                  role="tooltip"
                  className={cn(
                    "pointer-events-none absolute bottom-full left-0 z-10 mb-1 hidden max-w-xs whitespace-pre-wrap break-all rounded-md bg-zinc-900 px-2 py-1 text-xs text-white group-hover:block dark:bg-zinc-100 dark:text-zinc-900",
                    classNames?.preview,
                  )}
                >
                  {renderPastePreview?.({ kind: "text", paste }) ??
                    endsOf(paste.text, previewChars)}
                </span>
              </span>
            ))}
          </div>
        )}

        {inline ? (
          <>
            <InlinePasteEditor
              ref={editorRef}
              value={value}
              known={paste.known}
              onChange={handleInlineChange}
              onSubmit={handleSubmit}
              onPaste={paste.decidePaste}
              onHostsChange={paste.onHostsChange}
              placeholder={placeholder}
              disabled={disabled}
              className={classNames?.input}
            />
            {paste.portals}
            {pasteImages && pasteFilesName && (
              <PastedFilesInput name={pasteFilesName} files={pastedFiles} />
            )}
          </>
        ) : (
          <textarea
            ref={textareaRef}
            value={value}
            onChange={(e) => setValue(e.target.value)}
            onKeyDown={handleKeyDown}
            onPaste={handlePaste}
            placeholder={placeholder}
            disabled={disabled}
            rows={3}
            className={cn(
              "w-full resize-none bg-transparent px-4 pt-3 text-sm outline-none placeholder:text-zinc-400",
              classNames?.input,
            )}
          />
        )}
        <div className="flex items-center justify-between border-t border-zinc-100 px-3 py-2 dark:border-zinc-800">
          <div className="flex items-center gap-1">{actions}</div>
          <button
            type="button"
            onClick={handleSubmit}
            disabled={disabled || !hasContent}
            className="rounded-lg bg-zinc-900 px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-zinc-800 disabled:opacity-50 dark:bg-white dark:text-zinc-900 dark:hover:bg-zinc-100"
          >
            Send
          </button>
        </div>
      </div>
    );
  },
);

Composer.displayName = "Composer";

import type { ReactNode } from "react";

/*
 * The paste-pill shapes live with the shared core in `PastePills`, re-exported
 * here so the import paths that 5.31.0 and 5.38.0 published keep working.
 */
import type {
  ComposerPasteClassNames,
  ComposerPastePreview,
  HeldImage,
  HeldPaste,
} from "../paste-pills/PastePills.types";

export type { ComposerPasteClassNames, ComposerPastePreview, HeldImage, HeldPaste };

export interface ComposerSubmitExtras {
  /**
   * Images still pasted into the message when it was sent, in the order they
   * appear in it. Each one's place in the sent text is marked `[Pasted image N]`,
   * matching its `label`.
   */
  images: HeldImage[];
}

export interface ComposerProps {
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /**
   * The second argument only ever carries anything with `pasteImages` on. A
   * one-argument handler stays valid.
   */
  onSubmit?: (value: string, extras: ComposerSubmitExtras) => void;
  placeholder?: string;
  actions?: ReactNode;
  disabled?: boolean;
  className?: string;
  /**
   * Hold a paste of at least this many characters as a pill, instead of inserting
   * it. Try 500 — about a long paragraph.
   *
   * **Omit it and paste behaves exactly as it always has.** Opt-in on purpose:
   * paste is a fundamental interaction and this library is past 1.0, so a minor
   * release must not quietly change what pasting does for every consumer. There is
   * no default threshold for the same reason.
   *
   * Below the threshold nothing changes at all — no prevented event, no pill, no
   * ceremony for an address or a name.
   */
  pasteThreshold?: number;
  /**
   * Where a pill goes.
   *
   * - `"above"` (default, and the only behaviour before 5.38.0) — in a row above
   *   the input; a send appends held text after what was typed.
   * - `"inline"` — **in the message, where the paste happened.** A text pill gets
   *   a line to itself; clicking it puts the full text back exactly there; an
   *   image pill sits in the sentence. Backspace deletes a pill like a character.
   *
   * With `"inline"`, `value` carries a marker for each pill (see `pasteMarker`),
   * because the message is then the one record of what is attached and where.
   * `onSubmit` always receives the expanded text, never a marker.
   */
  pastePlacement?: "above" | "inline";
  /**
   * Hold a pasted IMAGE as a pill (`"inline"` placement only). Off by default —
   * turning it on is a promise to read `onSubmit`'s second argument, because a pill
   * reads as "attached" and an image a host never sends is an attachment the
   * person believes went and did not.
   *
   * A clipboard carrying text as well as an image (copying from a document often
   * includes a picture of the selection) pastes the TEXT: the image there is a
   * rendering, not the thing that was copied.
   */
  pasteImages?: boolean;
  /** Characters of a held text paste shown at EACH end of its hover preview. Default 20. */
  previewChars?: number;
  /** Replace the hover popover's content. Its box is styled by `classNames.preview`. */
  renderPastePreview?: (preview: ComposerPastePreview) => ReactNode;
  /** Restyle the pills and their popover. */
  classNames?: ComposerPasteClassNames;
  /**
   * The held pastes, if you want to own them.
   *
   * Controllable rather than internal because the component contract forbids
   * internal-only state for anything an agent might need to read or write — an
   * agent driving this surface has to be able to see that a paste is attached, and
   * to attach one itself.
   */
  heldPastes?: HeldPaste[];
  onHeldPastesChange?: (pastes: HeldPaste[]) => void;
  /** The held images, if you want to own them. Same reasoning as `heldPastes`. */
  heldImages?: HeldImage[];
  onHeldImagesChange?: (images: HeldImage[]) => void;
  /**
   * Submit pasted images with an enclosing `<form>`, under this field name.
   *
   * Renders a hidden `<input type="file" multiple>` that always holds the images
   * still in the message, in message order — delete a pill and its file leaves
   * the input. Needs `pasteImages`. Name it `photos[]` for a backend that
   * reads arrays from brackets (PHP, Laravel).
   */
  pasteFilesName?: string;
}

