export function useOutsideClick(
  ref: RefObject<HTMLElement | null>,
  handler: (event: MouseEvent | TouchEvent) => void,
  enabled: boolean = true,
  ignoreRef?: RefObject<HTMLElement | null>,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: MouseEvent | TouchEvent) => {
      const el = ref.current;
      if (!el || el.contains(event.target as Node)) return;
      // Ignore clicks on the trigger/anchor element — the trigger's
      // own onClick handler manages toggling.
      if (ignoreRef?.current?.contains(event.target as Node)) return;
      handler(event);
    };

    document.addEventListener("mousedown", listener);
    document.addEventListener("touchstart", listener);

    return () => {
      document.removeEventListener("mousedown", listener);
      document.removeEventListener("touchstart", listener);
    };
  }, [ref, handler, enabled, ignoreRef]);
}

import { useEffect } from "react";

export function useEscapeKey(
  handler: () => void,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        handler();
      }
    };

    document.addEventListener("keydown", listener);
    return () => document.removeEventListener("keydown", listener);
  }, [handler, enabled]);
}

import { useCallback, useEffect, useRef, useState } from "react";

interface UseAnimationOptions {
  open: boolean;
  enterClass: string;
  exitClass: string;
}

interface UseAnimationReturn {
  mounted: boolean;
  className: string;
  ref: React.RefObject<HTMLElement | null>;
}

export function useAnimation({
  open,
  enterClass,
  exitClass,
}: UseAnimationOptions): UseAnimationReturn {
  const [mounted, setMounted] = useState(open);
  const [animClass, setAnimClass] = useState(open ? enterClass : "");
  const ref = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (open) {
      setMounted(true);
      setAnimClass(enterClass);
    } else if (mounted) {
      setAnimClass(exitClass);
    }
  }, [open, enterClass, exitClass, mounted]);

  const handleAnimationEnd = useCallback(() => {
    if (!open) {
      setMounted(false);
      setAnimClass("");
    }
  }, [open]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    el.addEventListener("animationend", handleAnimationEnd);
    return () => el.removeEventListener("animationend", handleAnimationEnd);
  }, [handleAnimationEnd, mounted]);

  return { mounted, className: animClass, ref };
}

import { useMemo, useState } from "react";
import {
  Badge,
  Breadcrumbs,
  Button,
  Card,
  cn,
  Heading,
  Progress,
  Sidebar,
  Text,
} from "@particle-academy/react-fancy";
import { LessonView } from "./LessonView";
import { TestRunner } from "./TestRunner";
import type {
  AnswerInput,
  Course,
  Enrollment,
  Lesson,
  Test,
  TestAttempt,
} from "../lib/types";

export interface CoursePlayerProps {
  course: Course;
  enrollment: Enrollment;
  completedLessonIds: Set<number>;
  onMarkLessonComplete: (lesson: Lesson) => void | Promise<void>;
  onStartAttempt: (test: Test) => Promise<TestAttempt>;
  onSubmitAttempt: (
    attempt: TestAttempt,
    answers: AnswerInput[],
  ) => Promise<TestAttempt>;
}

type Selection =
  | { kind: "lesson"; lesson: Lesson }
  | { kind: "test"; test: Test; attempt: TestAttempt | null };

export function CoursePlayer({
  course,
  completedLessonIds,
  onMarkLessonComplete,
  onStartAttempt,
  onSubmitAttempt,
}: CoursePlayerProps) {
  const allTests = useMemo(() => collectTests(course), [course]);
  const lessons = course.lessons ?? [];
  const [selection, setSelection] = useState<Selection | null>(() => {
    const first = lessons[0];
    return first ? { kind: "lesson", lesson: first } : null;
  });

  const completedLessonCount = lessons.filter((l) =>
    completedLessonIds.has(l.id),
  ).length;
  const totalCount = lessons.length + allTests.length;
  const completedCount = completedLessonCount;
  const percentComplete =
    totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;

  function selectLesson(lesson: Lesson): void {
    setSelection({ kind: "lesson", lesson });
  }

  async function selectTest(test: Test): Promise<void> {
    const attempt = await onStartAttempt(test);
    setSelection({ kind: "test", test: attempt.test ?? test, attempt });
  }

  const currentLessonIdx =
    selection?.kind === "lesson"
      ? lessons.findIndex((l) => l.id === selection.lesson.id)
      : -1;

  return (
    <div className="grid gap-4">
      {/* Above the grid, not inside the right column. As the column's first
                child it pushed that card down by its own height, so the two
                panels started at different heights — the misalignment the layout
                looked like it had. */}
      <Breadcrumbs
        separator={<span className="text-secondary-300 mx-1">›</span>}
      >
        <Breadcrumbs.Item href="/dashboard">
          <span className="text-sm text-secondary-500 hover:text-brand">
            Dashboard
          </span>
        </Breadcrumbs.Item>
        <Breadcrumbs.Item>
          <span className="text-sm text-secondary-500">{course.title}</span>
        </Breadcrumbs.Item>
        {selection?.kind === "lesson" && (
          <Breadcrumbs.Item active>
            <span className="text-sm font-semibold text-secondary-900">
              {selection.lesson.title}
            </span>
          </Breadcrumbs.Item>
        )}
        {selection?.kind === "test" && (
          <Breadcrumbs.Item active>
            <span className="text-sm font-semibold text-secondary-900">
              {selection.test.title}
            </span>
          </Breadcrumbs.Item>
        )}
      </Breadcrumbs>
      <div className="grid grid-cols-1 md:grid-cols-[300px_1fr] gap-6 items-start">
        <Card
          variant="outlined"
          padding="none"
          className="!rounded-xl !shadow-sm overflow-hidden md:sticky md:top-4"
        >
          <div className="px-5 py-4 border-b border-secondary-200">
            <Heading as="h2" size="md" weight="bold">
              {course.title}
            </Heading>
            {course.description && (
              <Text size="sm" color="muted" className="!mt-1 line-clamp-2">
                {course.description}
              </Text>
            )}
            <div className="mt-3 grid gap-1.5">
              <Progress
                value={percentComplete}
                max={100}
                color="red"
                size="sm"
              />
              <div className="flex items-center justify-between">
                <Text size="xs" color="muted">
                  {completedLessonCount}/{lessons.length} lessons
                </Text>
                <Text size="xs" weight="semibold" className="!text-brand">
                  {percentComplete}%
                </Text>
              </div>
            </div>
          </div>

          <div className="px-2 py-3">
            {/* `embedded`: this rail lives inside a Card that already draws the
                        surface. Without it the fixed-width rail puts its right border
                        mid-panel, which reads as a line slicing the card. */}
            <Sidebar embedded>
              {lessons.length > 0 && (
                <Sidebar.Group label="Lessons">
                  {lessons.map((lesson, i) => {
                    const active =
                      selection?.kind === "lesson" &&
                      selection.lesson.id === lesson.id;
                    const done = completedLessonIds.has(lesson.id);
                    return (
                      <Sidebar.Item
                        key={lesson.id}
                        active={active}
                        icon={
                          <LessonNumber n={i + 1} done={done} active={active} />
                        }
                        badge={
                          done ? (
                            <Badge color="green" variant="soft" size="sm">
                              ✓
                            </Badge>
                          ) : undefined
                        }
                        onClick={() => selectLesson(lesson)}
                        className={cn(
                          active && "!bg-primary-50 !text-brand !font-semibold",
                        )}
                      >
                        <span className="truncate">{lesson.title}</span>
                      </Sidebar.Item>
                    );
                  })}
                </Sidebar.Group>
              )}

              {allTests.length > 0 && (
                <Sidebar.Group label="Assessments">
                  {allTests.map((test) => {
                    const active =
                      selection?.kind === "test" &&
                      selection.test.id === test.id;
                    return (
                      <Sidebar.Item
                        key={test.id}
                        active={active}
                        icon={<TestIcon />}
                        badge={
                          test.is_final ? (
                            <Badge color="amber" variant="soft" size="sm">
                              Final
                            </Badge>
                          ) : undefined
                        }
                        onClick={() => void selectTest(test)}
                        className={cn(
                          active && "!bg-primary-50 !text-brand !font-semibold",
                        )}
                      >
                        <span className="truncate">{test.title}</span>
                      </Sidebar.Item>
                    );
                  })}
                </Sidebar.Group>
              )}
            </Sidebar>
          </div>
        </Card>

        <div className="grid gap-4">
          {!selection && (
            <Card
              variant="outlined"
              padding="lg"
              className="!rounded-xl !shadow-sm text-center"
            >
              <Text>This course has no content yet.</Text>
            </Card>
          )}

          {selection?.kind === "lesson" && (
            <>
              <LessonView
                lesson={selection.lesson}
                completed={completedLessonIds.has(selection.lesson.id)}
                onMarkComplete={onMarkLessonComplete}
                onNext={() => {
                  const next = lessons[currentLessonIdx + 1];
                  if (next) selectLesson(next);
                  else if (allTests.length > 0) void selectTest(allTests[0]);
                }}
              />
              <LessonFooter
                prevLabel={lessons[currentLessonIdx - 1]?.title}
                nextLabel={
                  lessons[currentLessonIdx + 1]?.title ?? allTests[0]?.title
                }
                onPrev={
                  lessons[currentLessonIdx - 1]
                    ? () => selectLesson(lessons[currentLessonIdx - 1])
                    : undefined
                }
                onNext={
                  lessons[currentLessonIdx + 1]
                    ? () => selectLesson(lessons[currentLessonIdx + 1])
                    : allTests[0]
                      ? () => void selectTest(allTests[0])
                      : undefined
                }
              />
            </>
          )}

          {selection?.kind === "test" && selection.attempt && (
            <TestRunner
              test={selection.test}
              onSubmit={(answers) =>
                onSubmitAttempt(selection.attempt!, answers)
              }
            />
          )}

          {selection?.kind === "test" && !selection.attempt && (
            <Card
              variant="outlined"
              padding="lg"
              className="!rounded-xl !shadow-sm"
            >
              <div className="grid gap-3 text-center">
                <Heading as="h3" size="lg" weight="bold">
                  Ready to begin?
                </Heading>
                <Text color="muted">
                  Once you start, your attempt will be recorded.
                </Text>
                <div className="flex justify-center">
                  <Button
                    onClick={() => void selectTest(selection.test)}
                    className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-6 !py-2.5 !rounded-md !shadow-sm"
                  >
                    Start test
                  </Button>
                </div>
              </div>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

function LessonNumber({
  n,
  done,
  active,
}: {
  n: number;
  done: boolean;
  active: boolean;
}) {
  return (
    <span
      className={cn(
        "inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-xs font-semibold",
        done
          ? "bg-emerald-100 text-emerald-700"
          : active
            ? "bg-brand text-white"
            : "bg-secondary-100 text-secondary-700",
      )}
    >
      {n}
    </span>
  );
}

function TestIcon() {
  return (
    <svg
      className="h-4 w-4 shrink-0 text-secondary-500"
      fill="none"
      viewBox="0 0 24 24"
      stroke="currentColor"
      strokeWidth={2}
    >
      <path
        strokeLinecap="round"
        strokeLinejoin="round"
        d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
      />
    </svg>
  );
}

function LessonFooter({
  prevLabel,
  nextLabel,
  onPrev,
  onNext,
}: {
  prevLabel?: string;
  nextLabel?: string;
  onPrev?: () => void;
  onNext?: () => void;
}) {
  return (
    <div className="flex items-center justify-between gap-3">
      {onPrev ? (
        <Button variant="ghost" onClick={onPrev} className="hover:!text-brand">
          ←{" "}
          <span className="hidden sm:inline ml-1">
            {prevLabel ?? "Previous"}
          </span>
          <span className="sm:hidden ml-1">Previous</span>
        </Button>
      ) : (
        <span />
      )}
      {onNext && (
        <Button
          onClick={onNext}
          className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-5 !py-2.5 !rounded-md !shadow-sm"
        >
          <span className="hidden sm:inline">
            Next: {nextLabel ?? "Continue"}
          </span>
          <span className="sm:hidden">Next</span> →
        </Button>
      )}
    </div>
  );
}

function collectTests(course: Course): Test[] {
  return [
    ...(course.tests ?? []),
    ...(course.modules ?? []).flatMap((m) => m.tests ?? []),
    ...(course.lessons ?? []).flatMap((l) => l.tests ?? []),
  ];
}

import {
    Badge,
    Button,
    Callout,
    Card,
    ContentRenderer,
    Heading,
    Text,
    Tooltip,
} from '@particle-academy/react-fancy';
import type { Lesson } from '../lib/types';

export interface LessonViewProps {
    lesson: Lesson;
    completed?: boolean;
    onMarkComplete?: (lesson: Lesson) => void | Promise<void>;
    onNext?: (lesson: Lesson) => void;
    /**
     * Hosts a lesson video may be embedded from. Defaults to the common
     * providers below; pass your own to allow a self-hosted player.
     *
     * `lesson.video_url` is admin-supplied and validated on the server as
     * nothing more than a URL, so without this the component would frame
     * whatever a compromised or careless admin put in that column.
     */
    allowedVideoHosts?: string[];
}

/**
 * The default embed allowlist — the hosts a course video actually comes from.
 *
 * Deliberately not "anything https". An `<iframe>` runs a third party's code in
 * the learner's browser inside your page, so the set of origins allowed to do
 * that should be a decision someone made, not a side effect of what an admin
 * typed into a text field.
 */
const DEFAULT_VIDEO_HOSTS = [
    'youtube.com',
    'www.youtube.com',
    'youtube-nocookie.com',
    'www.youtube-nocookie.com',
    'youtu.be',
    'player.vimeo.com',
    'vimeo.com',
    'fast.wistia.net',
    'iframe.mediadelivery.net',
    'player.cloudinary.com',
];

/**
 * Whether a URL is safe to frame: https, and a host on the allowlist.
 *
 * Subdomain matching is exact or a dotted suffix, never `endsWith` on the bare
 * name — `evil-youtube.com`.endsWith(`youtube.com`) is true, and that is the
 * usual way an allowlist turns out not to be one.
 */
export function isEmbeddableVideo(url: string | null | undefined, allowed: string[]): boolean {
    if (!url) return false;

    let parsed: URL;
    try {
        parsed = new URL(url);
    } catch {
        return false;
    }

    if (parsed.protocol !== 'https:') return false;

    const host = parsed.hostname.toLowerCase();

    return allowed.some((entry) => {
        const allowedHost = entry.toLowerCase();

        return host === allowedHost || host.endsWith(`.${allowedHost}`);
    });
}

export function LessonView({
    lesson,
    completed,
    onMarkComplete,
    onNext: _onNext,
    allowedVideoHosts = DEFAULT_VIDEO_HOSTS,
}: LessonViewProps) {
    const contentType = lesson.content_type ?? 'text';
    const embeddable = isEmbeddableVideo(lesson.video_url, allowedVideoHosts);

    return (
        <Card
            variant="outlined"
            padding="none"
            className="!rounded-xl !shadow-sm overflow-hidden"
        >
            <div className="px-6 py-5 border-b border-secondary-200 flex items-start justify-between gap-4">
                <div>
                    <Heading as="h1" size="xl" weight="bold">
                        {lesson.title}
                    </Heading>
                    {lesson.estimated_minutes && (
                        <div className="mt-1 flex items-center gap-2">
                            <ClockIcon />
                            <Text size="sm" color="muted">
                                ~{lesson.estimated_minutes} min
                            </Text>
                        </div>
                    )}
                </div>
                {completed && (
                    <Tooltip content="You've completed this lesson">
                        <Badge color="green" variant="soft" size="md">
                            ✓ Completed
                        </Badge>
                    </Tooltip>
                )}
            </div>

            <div className="px-6 py-6 grid gap-5">
                {(contentType === 'video' || contentType === 'mixed') && lesson.video_url && (
                    embeddable ? (
                        <div className="relative pt-[56.25%] rounded-xl overflow-hidden bg-secondary-900 shadow-sm">
                            <iframe
                                src={lesson.video_url}
                                title={lesson.title}
                                // allow-same-origin refers to the FRAME's own origin, not
                                // this page's, so a cross-origin player still cannot reach
                                // into the host document. Both it and allow-scripts are
                                // required for any real video player to run.
                                sandbox="allow-scripts allow-same-origin allow-presentation allow-popups allow-popups-to-escape-sandbox"
                                allow="autoplay; encrypted-media; picture-in-picture; fullscreen"
                                referrerPolicy="strict-origin-when-cross-origin"
                                loading="lazy"
                                allowFullScreen
                                className="absolute inset-0 w-full h-full border-0"
                            />
                        </div>
                    ) : (
                        // Loud, not silent. A blocked embed that rendered nothing would
                        // look like a lesson with no video, and nobody would know to fix
                        // the URL.
                        <Callout color="amber" data-lesson-video-blocked>
                            <p className="font-medium">This lesson&apos;s video cannot be shown here.</p>
                            <p className="text-sm">
                                It is hosted somewhere this course is not configured to embed from. Ask an
                                administrator to use an approved video host, or open it directly:{' '}
                                <a
                                    href={lesson.video_url}
                                    target="_blank"
                                    rel="noopener noreferrer nofollow"
                                    className="underline"
                                >
                                    open the video
                                </a>
                                .
                            </p>
                        </Callout>
                    )
                )}

                {(contentType === 'text' || contentType === 'mixed') && lesson.content && (
                    <div className="prose prose-secondary max-w-none prose-headings:font-bold prose-headings:text-secondary-900 prose-p:text-secondary-700 prose-strong:text-secondary-900 prose-a:text-brand">
                        <ContentRenderer value={lesson.content} format="html" />
                    </div>
                )}

                {completed && (
                    <Callout color="green">
                        <div className="flex items-center gap-2">
                            <Text weight="semibold">Lesson complete.</Text>
                            <Text size="sm">Move to the next item when you're ready.</Text>
                        </div>
                    </Callout>
                )}
            </div>

            {!completed && onMarkComplete && (
                <div className="px-6 py-4 border-t border-secondary-200 bg-secondary-50/50 flex items-center justify-end gap-3">
                    <Tooltip content="Confirms you've finished reading this lesson">
                        <Button
                            color="red"
                            icon="check"
                            onClick={() => onMarkComplete(lesson)}
                            className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-5 !py-2.5 !rounded-md !shadow-sm"
                        >
                            Mark complete
                        </Button>
                    </Tooltip>
                </div>
            )}
        </Card>
    );
}

function ClockIcon() {
    return (
        <svg
            className="h-4 w-4 text-secondary-400"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth={2}
        >
            <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
            />
        </svg>
    );
}

import { useMemo, useState } from 'react';
import {
    Badge,
    Button,
    Callout,
    Card,
    cn,
    Heading,
    Modal,
    Progress,
    Text,
} from '@particle-academy/react-fancy';
import {
    QuestionRenderer,
    type AnswerValue,
    answerValueToPayload,
} from './QuestionRenderer';
import type { AnswerInput, Test, TestAttempt } from '../lib/types';

export interface TestRunnerProps {
    test: Test;
    onSubmit: (answers: AnswerInput[]) => Promise<TestAttempt>;
    onFinished?: (attempt: TestAttempt) => void;
}

export function TestRunner({ test, onSubmit, onFinished }: TestRunnerProps) {
    const questions = useMemo(() => test.questions ?? [], [test.questions]);
    const [answers, setAnswers] = useState<Record<number, AnswerValue>>({});
    const [submitting, setSubmitting] = useState(false);
    const [result, setResult] = useState<TestAttempt | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [confirmOpen, setConfirmOpen] = useState(false);

    const answeredCount = Object.values(answers).filter(
        (a) => a !== null && a !== undefined,
    ).length;
    const percent = questions.length
        ? Math.round((answeredCount / questions.length) * 100)
        : 0;
    const allAnswered = answeredCount === questions.length && questions.length > 0;

    async function handleSubmit(): Promise<void> {
        setConfirmOpen(false);
        setSubmitting(true);
        setError(null);
        try {
            const payload: AnswerInput[] = questions.map(
                (q) => answerValueToPayload(q.id, answers[q.id] ?? null) as AnswerInput,
            );
            const attempt = await onSubmit(payload);
            setResult(attempt);
            onFinished?.(attempt);
        } catch (e) {
            const message = e instanceof Error ? e.message : String(e);
            setError(message);
        } finally {
            setSubmitting(false);
        }
    }

    if (result) {
        return <TestResult attempt={result} />;
    }

    return (
        <>
            <Card
                variant="outlined"
                padding="none"
                className="!rounded-xl !shadow-sm overflow-hidden"
            >
                <div className="px-6 py-5 border-b border-secondary-200">
                    <div className="flex items-start justify-between gap-4">
                        <div>
                            <Heading as="h1" size="xl" weight="bold">
                                {test.title}
                            </Heading>
                            {test.description && (
                                <Text className="!mt-1" color="muted">
                                    {test.description}
                                </Text>
                            )}
                        </div>
                        <div className="flex flex-col items-end gap-2">
                            {test.is_final && (
                                <Badge color="amber" variant="soft" size="md">
                                    Final exam
                                </Badge>
                            )}
                            <Text size="xs" color="muted">
                                Pass at {test.passing_score}%
                            </Text>
                        </div>
                    </div>

                    <div className="mt-4 grid gap-1.5">
                        <Progress
                            value={percent}
                            max={100}
                            color="red"
                            size="sm"
                        />
                        <div className="flex items-center justify-between">
                            <Text size="xs" color="muted">
                                {answeredCount} of {questions.length} answered
                            </Text>
                            <Text size="xs" weight="semibold" className="!text-brand">
                                {percent}%
                            </Text>
                        </div>
                    </div>
                </div>

                <div className="px-6 py-6 grid gap-5">
                    {questions.map((q, i) => (
                        <Card
                            key={q.id}
                            variant="outlined"
                            padding="md"
                            className="!rounded-lg"
                        >
                            <div className="flex items-center justify-between mb-3">
                                <Text size="xs" weight="semibold" className="uppercase tracking-wide" color="muted">
                                    Question {i + 1} of {questions.length}
                                </Text>
                                <Badge color="zinc" variant="soft" size="sm">
                                    {q.points} pt{q.points === 1 ? '' : 's'}
                                </Badge>
                            </div>
                            <QuestionRenderer
                                question={q}
                                value={answers[q.id] ?? null}
                                onChange={(next) =>
                                    setAnswers((prev) => ({ ...prev, [q.id]: next }))
                                }
                            />
                        </Card>
                    ))}
                </div>

                {error && (
                    <div className="px-6 pb-4">
                        <Callout color="red">{error}</Callout>
                    </div>
                )}

                <div className="px-6 py-4 border-t border-secondary-200 bg-secondary-50/50 flex items-center justify-between gap-3">
                    <Text size="sm" color="muted">
                        {allAnswered
                            ? "You've answered every question."
                            : `${questions.length - answeredCount} question${questions.length - answeredCount === 1 ? '' : 's'} remaining`}
                    </Text>
                    <Button
                        loading={submitting}
                        disabled={submitting || answeredCount === 0}
                        onClick={() => setConfirmOpen(true)}
                        className="!bg-brand hover:!bg-primary-600 disabled: !text-white !font-semibold !px-6 !py-2.5 !rounded-md !shadow-sm"
                    >
                        {submitting ? 'Submitting…' : 'Submit test'}
                    </Button>
                </div>
            </Card>

            <Modal open={confirmOpen} onClose={() => setConfirmOpen(false)} size="sm">
                <Card variant="flat" padding="lg">
                    <Heading as="h2" size="lg" weight="bold">
                        Submit your answers?
                    </Heading>
                    <Text color="muted" className="!mt-2">
                        {allAnswered
                            ? `You've answered all ${questions.length} questions. You can't change your answers after submitting.`
                            : `You have ${questions.length - answeredCount} unanswered question${questions.length - answeredCount === 1 ? '' : 's'}. Unanswered questions count as zero.`}
                    </Text>
                    <div className="mt-6 flex justify-end gap-3">
                        <Button
                            variant="ghost"
                            onClick={() => setConfirmOpen(false)}
                            className="hover:!text-brand !px-4 !py-2"
                        >
                            Keep working
                        </Button>
                        <Button
                            onClick={handleSubmit}
                            className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-5 !py-2 !rounded-md"
                        >
                            Submit
                        </Button>
                    </div>
                </Card>
            </Modal>
        </>
    );
}

function TestResult({ attempt }: { attempt: TestAttempt }) {
    const passed = attempt.passed === true;
    const pending = attempt.passed === null;
    const score = attempt.score !== null ? Number(attempt.score) : null;

    return (
        <Card
            variant="outlined"
            padding="none"
            className="!rounded-xl !shadow-sm overflow-hidden"
        >
            <div
                className={cn(
                    'px-6 py-5',
                    pending
                            ? 'bg-blue-50 dark:bg-blue-950/40'
                            : passed
                              ? 'bg-emerald-50 dark:bg-emerald-950/40'
                              : 'bg-red-50 dark:bg-red-950/40',
                )}
            >
                <div className="flex items-center gap-3">
                    <div
                        className={cn(
                            'flex h-12 w-12 items-center justify-center rounded-full text-xl font-bold',
                            pending
                                ? 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200'
                                : passed
                                ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-200'
                                : 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200',
                        )}
                    >
                        {pending ? '…' : passed ? '✓' : '✕'}
                    </div>
                    <div>
                        <Heading as="h2" size="xl" weight="bold">
                            {pending ? 'Awaiting grading' : passed ? 'You passed!' : 'Did not pass'}
                        </Heading>
                        <Text className="!mt-0.5" color="muted">
                            {pending
                                ? 'Some answers require manual review.'
                                : passed
                                ? 'Nice work. Your certificate is being issued.'
                                : 'Review the material and try again.'}
                        </Text>
                    </div>
                </div>
            </div>

            <div className="px-6 py-5 grid sm:grid-cols-3 gap-4">
                <Stat label="Score" value={score !== null ? `${score}%` : '—'} highlight />
                <Stat
                    label="Points awarded"
                    value={
                        attempt.points_awarded !== null && attempt.max_score !== null
                            ? `${attempt.points_awarded} / ${attempt.max_score}`
                            : '—'
                    }
                />
                <Stat label="Attempt" value={`#${attempt.attempt_number}`} />
            </div>
        </Card>
    );
}

function Stat({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
    return (
        <div className="rounded-lg border border-secondary-200 bg-secondary-50/50 px-4 py-3">
            <Text size="xs" weight="semibold" className="uppercase tracking-wide" color="muted">
                {label}
            </Text>
            <div
                className={cn(
                    'mt-1 text-2xl font-bold',
                    highlight ? 'text-brand' : 'text-secondary-900',
                )}
            >
                {value}
            </div>
        </div>
    );
}

import {
    CheckboxGroup,
    RadioGroup,
    Text,
    Textarea,
} from '@particle-academy/react-fancy';
import type { Question } from '../lib/types';

export type AnswerValue =
    | { kind: 'option_id'; value: number }
    | { kind: 'option_ids'; value: number[] }
    | { kind: 'text'; value: string }
    | null;

export interface QuestionRendererProps {
    question: Question;
    value: AnswerValue;
    onChange: (next: AnswerValue) => void;
    disabled?: boolean;
}

export function QuestionRenderer({
    question,
    value,
    onChange,
    disabled,
}: QuestionRendererProps) {
    const options = question.options ?? [];

    if (question.type === 'multiple_choice' || question.type === 'true_false') {
        const selected =
            value?.kind === 'option_id' ? String(value.value) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <RadioGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_id', value: Number(next) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    if (question.type === 'multiple_select') {
        const selected =
            value?.kind === 'option_ids' ? value.value.map(String) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <Text size="sm" color="muted">
                    Select all that apply.
                </Text>
                <CheckboxGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_ids', value: next.map(Number) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    // short_answer
    const text = value?.kind === 'text' ? value.value : '';
    return (
        <div className="grid gap-3">
            <Text weight="semibold" className="!text-base">
                {question.prompt}
            </Text>
            <Textarea
                value={text}
                onChange={(e) =>
                    onChange({
                        kind: 'text',
                        value: (e.target as HTMLTextAreaElement).value,
                    })
                }
                disabled={disabled}
                rows={4}
                placeholder="Type your answer here…"
            />
        </div>
    );
}

export function answerValueToPayload(
    questionId: number,
    value: AnswerValue,
): { question_id: number; answer: unknown } {
    if (!value) return { question_id: questionId, answer: null };
    switch (value.kind) {
        case 'option_id':
            return { question_id: questionId, answer: { option_id: value.value } };
        case 'option_ids':
            return { question_id: questionId, answer: { option_ids: value.value } };
        case 'text':
            return { question_id: questionId, answer: { text: value.value } };
    }
}

