/**
 * Full deck editor — toolbar + rail + canvas + inspector + speaker notes.
 *
 * Controlled (`value` + `onChange`). State is intentionally simple: deck
 * lives in the consumer, the editor just renders a view + dispatches ops.
 * The same `DeckOp` enum that the agent bridge speaks runs through here —
 * agents and humans drive identical mutations.
 *
 * This is the **default layout** over a shared controller. To build a bespoke
 * editor — reposition panels, drop an app panel *beside* them, restyle each —
 * compose the parts yourself: `<DeckEditor.Provider>` runs the controller, and
 * `DeckEditor.Toolbar` / `.Rail` / `.Canvas` / `.Inspector` / `.Notes` /
 * `.StatusBar` are slots that share it (selection included). `useDeckEditor()`
 * exposes the same controller to any panel of your own.
 */
export function DeckEditor({
    value,
    onChange,
    onOp,
    onPresent,
    selectedSlideId,
    onSelectedSlideChange,
    renderElement,
    hideRail = false,
    hideNotes = false,
    hideToolbar = false,
    hideInspector = false,
    toolbarExtra,
    themes,
    idStrategy = "client",
    renderToolbar,
    className,
}: DeckEditorProps) {
    return (
        <DeckEditorProvider
            value={value}
            onChange={onChange}
            onOp={onOp}
            onPresent={onPresent}
            selectedSlideId={selectedSlideId}
            onSelectedSlideChange={onSelectedSlideChange}
            renderElement={renderElement}
            themes={themes}
            idStrategy={idStrategy}
        >
            <div
                className={`fs-editor flex h-full w-full flex-col bg-zinc-100 dark:bg-zinc-950 ${className ?? ""}`}
                data-fancy-slides-editor={value.id}
            >
                {!hideToolbar && <DeckEditorToolbar renderToolbar={renderToolbar} extra={toolbarExtra} />}

                <div className="flex min-h-0 flex-1">
                    {!hideRail && <DeckEditorRail />}

                    <div className="flex min-w-0 flex-1 flex-col">
                        <DeckEditorCanvas />
                        {!hideNotes && <DeckEditorNotes />}
                    </div>

                    {!hideInspector && <DeckEditorInspector />}
                </div>
            </div>
        </DeckEditorProvider>
    );
}

// Compound slot statics — match the house style (direct assignment, like
// EditorToolbar.Title) so consumers compose `<DeckEditor.Provider>` +
// `<DeckEditor.Rail>` etc.
DeckEditor.Provider = DeckEditorProvider;
DeckEditor.Toolbar = DeckEditorToolbar;
DeckEditor.Rail = DeckEditorRail;
DeckEditor.Canvas = DeckEditorCanvas;
DeckEditor.Inspector = DeckEditorInspector;
DeckEditor.Notes = DeckEditorNotes;
DeckEditor.StatusBar = DeckEditorStatusBar;

import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";
import type {
    ChartElement,
    CodeElement,
    Deck,
    DeckOp,
    ImageElement,
    ShapeElement,
    ShapeKind,
    Slide as SlideData,
    SlideElement,
    TableElement,
    TextElement,
    Theme,
} from "../lib/types";
import { resolveTheme } from "../lib/theme/theme-utils";
import { builtinThemes } from "../lib/theme/default-theme";
import { elementId } from "../lib/utils/ids";
import { useDeckState, type IdStrategy } from "../lib/hooks/use-deck-state";
import { migrateDeck } from "../lib/utils/serialize";
import { chartStarterOption, type ChartKind } from "../lib/utils/chart-presets";
import { type ToolbarApi } from "../lib/components/EditorToolbar";
import { defaultElementRegistry } from "../lib/registry";
import { DeckEditorContext, type DeckEditorContextValue } from "./context";

export interface DeckEditorProviderProps {
    /** Controlled deck — pair with `onChange`. */
    value: Deck;
    onChange: (next: Deck) => void;
    /** Called after every mutation with the op that produced it — feed into AgentPanel / audit log. */
    onOp?: (op: DeckOp) => void;
    /** Called when the user clicks Present. The host decides how to open the SlideViewer. */
    onPresent?: () => void;
    /** Controlled selected slide id. Uncontrolled by default. */
    selectedSlideId?: string | null;
    onSelectedSlideChange?: (id: string | null) => void;
    /**
     * Renderer for chart / code / table / embed elements. Defaults to the
     * built-in `defaultElementRegistry`; pass your own to override (it wins
     * entirely).
     */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /**
     * Theme list the toolbar's picker offers. Defaults to the built-in themes;
     * pass user-authored themes (`[...builtinThemes, myTheme]`) to extend it.
     */
    themes?: Theme[];
    /** Who mints new slide/element ids. Defaults to `"client"`. See {@link IdStrategy}. */
    idStrategy?: IdStrategy;
    /** The composed editor — `DeckEditor.*` slots plus any app chrome. */
    children: ReactNode;
}

/**
 * Runs the editor controller — op surface, slide + element selection, insert
 * handlers, the toolbar action surface — and provides it to every
 * `DeckEditor.*` slot via {@link useDeckEditor}. `<DeckEditor>` mounts this for
 * you with its default layout; mount it yourself to compose a bespoke editor
 * from the slot parts (and your own panels) sharing one controller.
 *
 * Controlled (`value` + `onChange`). The same `DeckOp` enum the agent bridge
 * speaks runs through here — agents and humans drive identical mutations.
 */
export function DeckEditorProvider({
    value,
    onChange,
    onOp,
    onPresent,
    selectedSlideId: controlledSlideId,
    onSelectedSlideChange,
    renderElement = defaultElementRegistry,
    themes,
    idStrategy = "client",
    children,
}: DeckEditorProviderProps) {
    const deck = value;
    const ops = useDeckState({ value: deck, onChange, onOp, idStrategy });

    // Migrate an older-schema deck forward on load and emit one normalized
    // onChange so the consumer can persist the upgraded shape. migrateDeck is
    // idempotent (returns the same ref once current), so this won't loop. Keyed
    // on deck id: a freshly-loaded deck re-runs the migration.
    useEffect(() => {
        const migrated = migrateDeck(value);
        if (migrated !== value) onChange(migrated);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [value.id]);

    // Slide selection — controlled or internal.
    const [internalSlideId, setInternalSlideId] = useState<string | null>(deck.slides[0]?.id ?? null);
    const isControlled = controlledSlideId !== undefined;
    const slideId = isControlled ? controlledSlideId! : internalSlideId;
    const setSlideId = useCallback(
        (id: string | null) => {
            if (!isControlled) setInternalSlideId(id);
            onSelectedSlideChange?.(id);
        },
        [isControlled, onSelectedSlideChange],
    );

    // If the selected slide disappears (deletion / agent ops), fall back to the first slide.
    useEffect(() => {
        if (slideId && !deck.slides.some((s) => s.id === slideId)) {
            setSlideId(deck.slides[0]?.id ?? null);
        } else if (!slideId && deck.slides.length > 0) {
            setSlideId(deck.slides[0]!.id);
        }
    }, [deck.slides, slideId, setSlideId]);

    const slide: SlideData | undefined = deck.slides.find((s) => s.id === slideId);

    // Element selection — internal, resets on slide change.
    const [elementIdSelected, setElementIdSelected] = useState<string | null>(null);
    useEffect(() => {
        setElementIdSelected(null);
    }, [slideId]);

    const selectedElement = slide && elementIdSelected ? slide.elements.find((e) => e.id === elementIdSelected) ?? null : null;

    // ─── Toolbar insert handlers ───────────────────────────────────────────
    const insertEl = useCallback(
        (element: Omit<SlideElement, "id">) => {
            if (!slide) return;
            const id = ops.addElement(slide.id, { id: elementId(), ...element });
            setElementIdSelected(id);
        },
        [slide, ops],
    );

    const insertText = useCallback(
        () =>
            insertEl({
                type: "text",
                x: 0.1,
                y: 0.4,
                w: 0.8,
                h: 0.2,
                content: "Click to edit",
                format: "plain",
                style: { fontSize: 36, weight: "semibold", align: "center" },
            } as Omit<TextElement, "id">),
        [insertEl],
    );

    const insertImage = useCallback(
        () =>
            insertEl({
                type: "image",
                x: 0.25,
                y: 0.25,
                w: 0.5,
                h: 0.5,
                src: "https://placehold.co/600x400?text=Image",
                fit: "contain",
            } as Omit<ImageElement, "id">),
        [insertEl],
    );

    const insertShape = useCallback(
        (shape: ShapeKind) =>
            insertEl({
                type: "shape",
                shape,
                x: 0.3,
                y: 0.3,
                w: 0.4,
                h: 0.4,
                fill: shape === "line" || shape === "arrow" ? "none" : "rgba(139,92,246,0.15)",
                stroke: "#8b5cf6",
                strokeWidth: 2,
            } as Omit<ShapeElement, "id">),
        [insertEl],
    );

    const insertChart = useCallback(
        (kind: ChartKind = "bar") =>
            insertEl({
                type: "chart",
                x: 0.1,
                y: 0.2,
                w: 0.8,
                h: 0.6,
                option: chartStarterOption(kind),
            } as Omit<ChartElement, "id">),
        [insertEl],
    );

    const insertCode = useCallback(
        () =>
            insertEl({
                type: "code",
                x: 0.15,
                y: 0.2,
                w: 0.7,
                h: 0.6,
                code: "function hello() {\n  return \"world\";\n}\n",
                language: "typescript",
                codeTheme: "dark",
            } as Omit<CodeElement, "id">),
        [insertEl],
    );

    const insertTable = useCallback(
        () =>
            insertEl({
                type: "table",
                x: 0.15,
                y: 0.25,
                w: 0.7,
                h: 0.5,
                columns: [
                    { key: "name", label: "Name" },
                    { key: "value", label: "Value" },
                ],
                rows: [
                    { name: "Alpha", value: 12 },
                    { name: "Beta", value: 34 },
                    { name: "Gamma", value: 56 },
                ],
            } as Omit<TableElement, "id">),
        [insertEl],
    );

    const insert = useMemo<DeckEditorContextValue["insert"]>(
        () => ({ text: insertText, image: insertImage, shape: insertShape, chart: insertChart, code: insertCode, table: insertTable }),
        [insertText, insertImage, insertShape, insertChart, insertCode, insertTable],
    );

    const themeList = themes ?? Object.values(builtinThemes);

    // The toolbar action surface — handed to a custom `renderToolbar`, and the
    // source for the default toolbar too.
    const toolbarApi: ToolbarApi = useMemo(
        () => ({
            title: { value: deck.title, onChange: (t) => ops.setTitle(t) },
            theme: { name: deck.theme.name, themes: themeList, onApply: (t) => ops.applyTheme(t) },
            insert,
            present: onPresent,
            disabled: !slide,
        }),
        [deck.title, deck.theme.name, themeList, ops, insert, onPresent, slide],
    );

    const ctx = useMemo<DeckEditorContextValue>(
        () => ({
            deck,
            theme: resolveTheme(deck.theme),
            ops,
            slideId,
            setSlideId,
            slide,
            selectedElementId: elementIdSelected,
            setSelectedElementId: setElementIdSelected,
            selectedElement,
            insert,
            toolbarApi,
            renderElement,
            themes: themeList,
            onPresent,
        }),
        [deck, ops, slideId, setSlideId, slide, elementIdSelected, selectedElement, insert, toolbarApi, renderElement, themeList, onPresent],
    );

    return <DeckEditorContext.Provider value={ctx}>{children}</DeckEditorContext.Provider>;
}

import { createContext, useContext, type ReactNode } from "react";
import type { Deck, ShapeKind, Slide as SlideData, SlideElement, Theme } from "../lib/types";
import type { DeckStateApi } from "../lib/hooks/use-deck-state";
import type { ChartKind, ToolbarApi } from "../lib/components/EditorToolbar";

/**
 * The editor's insert action surface — one entry per element type the toolbar
 * can add. Each inserts a starter element on the active slide and selects it.
 */
export interface DeckEditorInsertApi {
    text(): void;
    image(): void;
    shape(kind: ShapeKind): void;
    chart(kind?: ChartKind): void;
    code(): void;
    table(): void;
}

/**
 * The shared editor controller — everything a slot part needs to render itself
 * and drive the deck. Provided by {@link DeckEditorProvider} (and therefore by
 * `<DeckEditor>` itself), read by every `DeckEditor.*` slot via
 * {@link useDeckEditor}. Selection lives here, so all slots — and any app panel
 * the host drops alongside them — share one controller rather than re-deriving
 * their own.
 */
export interface DeckEditorContextValue {
    /** The controlled deck (== the provider's `value`). */
    deck: Deck;
    /** Resolved theme (`resolveTheme(deck.theme)`) — defaults filled in. */
    theme: Theme;
    /** The op surface from `useDeckState`. */
    ops: DeckStateApi;
    /** Currently-selected slide id. */
    slideId: string | null;
    setSlideId: (id: string | null) => void;
    /** The currently-selected slide, if any. */
    slide: SlideData | undefined;
    /** Currently-selected element id (shared across slots — the crux of #11). */
    selectedElementId: string | null;
    setSelectedElementId: (id: string | null) => void;
    /** The currently-selected element, if any. */
    selectedElement: SlideElement | null;
    /** Insert handlers — add a starter element of each type to the active slide. */
    insert: DeckEditorInsertApi;
    /** The toolbar action surface (title / theme / insert / present / disabled). */
    toolbarApi: ToolbarApi;
    /** Renderer for chart / code / table / embed elements. */
    renderElement: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** The theme list the picker offers (defaults to the built-ins). */
    themes: Theme[];
    /** Present handler, if the host wired one. */
    onPresent?: () => void;
}

export const DeckEditorContext = createContext<DeckEditorContextValue | null>(null);

/**
 * Read the shared editor controller. Must be called inside a
 * `<DeckEditor.Provider>` (which `<DeckEditor>` mounts for you) — throws a clear
 * error otherwise, mirroring `EditorToolbar`'s slot guard.
 */
export function useDeckEditor(): DeckEditorContextValue {
    const ctx = useContext(DeckEditorContext);
    if (!ctx) {
        throw new Error("useDeckEditor() (and DeckEditor.* slots) must be used inside <DeckEditor.Provider> (mounted for you by <DeckEditor>).");
    }
    return ctx;
}

export { DeckEditor } from "./DeckEditor";
export type { DeckEditorProps } from "./DeckEditor";

export { DeckEditorProvider } from "./DeckEditorProvider";
export type { DeckEditorProviderProps } from "./DeckEditorProvider";

export { useDeckEditor, DeckEditorContext } from "./context";
export type { DeckEditorContextValue, DeckEditorInsertApi } from "./context";

export {
    DeckEditorToolbar,
    DeckEditorRail,
    DeckEditorCanvas,
    DeckEditorInspector,
    DeckEditorNotes,
    DeckEditorStatusBar,
} from "./slots";
export type {
    DeckEditorToolbarProps,
    DeckEditorRailProps,
    DeckEditorCanvasProps,
    DeckEditorInspectorProps,
    DeckEditorNotesProps,
    DeckEditorStatusBarProps,
} from "./slots";

import { type CSSProperties, type ReactNode } from "react";
import type { SlideElement, TextElement } from "../lib/types";
import { Slide } from "../slide";
import { SlideRail } from "../lib/components/SlideRail";
import { EditorToolbar, type ToolbarApi } from "../lib/components/EditorToolbar";
import { ElementInspector } from "../lib/components/ElementInspector";
import { SpeakerNotes } from "../lib/components/SpeakerNotes";
import { useDeckEditor } from "./context";

export interface DeckEditorToolbarProps {
    className?: string;
    /**
     * Compose the toolbar yourself. Receives the toolbar action surface and
     * returns the toolbar node. When omitted, the default `EditorToolbar` is
     * rendered.
     */
    renderToolbar?: (api: ToolbarApi) => ReactNode;
    /** Extra content on the toolbar's trailing edge (default toolbar only). */
    extra?: ReactNode;
}

/**
 * The editor toolbar, wired to the shared controller. Renders the default
 * `EditorToolbar` from the `toolbarApi`, or your `renderToolbar(api)` node.
 */
export function DeckEditorToolbar({ className, renderToolbar, extra }: DeckEditorToolbarProps) {
    const { toolbarApi, deck, ops, themes } = useDeckEditor();
    if (renderToolbar) {
        return <>{renderToolbar(toolbarApi)}</>;
    }
    const bar = (
        <EditorToolbar
            title={deck.title}
            onTitleChange={(t) => ops.setTitle(t)}
            themeName={deck.theme.name}
            onApplyTheme={(t) => ops.applyTheme(t)}
            themes={themes}
            onInsertText={toolbarApi.insert.text}
            onInsertImage={toolbarApi.insert.image}
            onInsertShape={toolbarApi.insert.shape}
            onInsertChart={toolbarApi.insert.chart}
            onInsertCode={toolbarApi.insert.code}
            onInsertTable={toolbarApi.insert.table}
            onPresent={toolbarApi.present}
            disabled={toolbarApi.disabled}
            toolbarExtra={extra}
        />
    );
    // Keep the default layout's DOM byte-identical: wrap only when a className
    // is supplied (bespoke composition), otherwise render the bar bare.
    return className ? <div className={className}>{bar}</div> : bar;
}

export interface DeckEditorRailProps {
    className?: string;
    style?: CSSProperties;
}

/** The slide rail — thumbnails, add / duplicate / remove / reorder, selection. */
export function DeckEditorRail({ className, style }: DeckEditorRailProps) {
    const { deck, ops, slideId, setSlideId, renderElement } = useDeckEditor();
    return (
        <div
            className={`w-56 shrink-0 overflow-y-auto border-r border-zinc-200 bg-white dark:border-zinc-800 dark:bg-zinc-950${className ? ` ${className}` : ""}`}
            style={style}
        >
            <SlideRail
                slides={deck.slides}
                selectedId={slideId}
                theme={deck.theme}
                onSelect={setSlideId}
                onAdd={(after) => {
                    const id = ops.addSlide(after !== undefined ? after : deck.slides.length);
                    setSlideId(id);
                }}
                onDuplicate={(id) => {
                    const newId = ops.duplicateSlide(id);
                    setSlideId(newId);
                }}
                onRemove={(id) => ops.removeSlide(id)}
                onReorder={(id, toIndex) => ops.reorderSlide(id, toIndex)}
                renderElement={renderElement}
            />
        </div>
    );
}

export interface DeckEditorCanvasProps {
    className?: string;
    style?: CSSProperties;
}

/** The centered, editable slide canvas (drag / resize / inline-edit). */
export function DeckEditorCanvas({ className, style }: DeckEditorCanvasProps) {
    const { deck, theme, slide, ops, selectedElementId, setSelectedElementId, renderElement } = useDeckEditor();
    return (
        <div className={`flex flex-1 items-center justify-center overflow-auto p-6${className ? ` ${className}` : ""}`} style={style}>
            {slide ? (
                <div
                    className="rounded-lg shadow-xl"
                    style={{
                        width: "min(96%, 1280px)",
                        aspectRatio: String(theme.aspectRatio ?? 16 / 9),
                        background: "white",
                    }}
                >
                    <Slide
                        slide={slide}
                        theme={deck.theme}
                        editing
                        onElementContentChange={(eid, content) => ops.updateElement(slide.id, eid, { content, format: "markdown" } as Partial<TextElement>)}
                        onElementSelect={setSelectedElementId}
                        selectedElementId={selectedElementId}
                        onElementMove={(eid, x, y) => ops.moveElement(slide.id, eid, x, y)}
                        onElementResize={(eid, patch) => ops.updateElement(slide.id, eid, patch as Partial<SlideElement>)}
                        renderElement={renderElement}
                    />
                </div>
            ) : (
                <div className="grid place-items-center rounded-lg border border-dashed border-zinc-300 bg-white px-12 py-24 text-sm text-zinc-500 dark:border-zinc-700 dark:bg-zinc-950">
                    Add a slide to start editing.
                </div>
            )}
        </div>
    );
}

export interface DeckEditorInspectorProps {
    className?: string;
    style?: CSSProperties;
}

/** The right-hand element / slide inspector. */
export function DeckEditorInspector({ className, style }: DeckEditorInspectorProps) {
    const { slide, ops, selectedElement, selectedElementId, setSelectedElementId } = useDeckEditor();
    return (
        <div className={`w-72 shrink-0 overflow-y-auto${className ? ` ${className}` : ""}`} style={style}>
            <ElementInspector
                element={selectedElement}
                slide={slide ?? null}
                onPatch={(patch) => slide && selectedElementId && ops.updateElement(slide.id, selectedElementId, patch)}
                onDelete={() => {
                    if (!slide || !selectedElementId) return;
                    ops.removeElement(slide.id, selectedElementId);
                    setSelectedElementId(null);
                }}
                onLockToggle={(locked) => slide && selectedElementId && ops.updateElement(slide.id, selectedElementId, { locked } as Partial<SlideElement>)}
                onSetTransition={(transition) => slide && ops.setTransition(slide.id, transition)}
                onSetBackground={(background) => slide && ops.setBackground(slide.id, background)}
                onSetLayout={(layout) => slide && ops.setLayout(slide.id, layout)}
                onSetAnimation={(animation) => slide && selectedElementId && ops.setAnimation(slide.id, selectedElementId, animation)}
                onSetElementAnimation={(eid, animation) => slide && ops.setAnimation(slide.id, eid, animation)}
            />
        </div>
    );
}

export interface DeckEditorNotesProps {
    className?: string;
    placeholder?: string;
}

/** Speaker notes for the active slide. Renders nothing when no slide is selected. */
export function DeckEditorNotes({ className, placeholder }: DeckEditorNotesProps) {
    const { slide, ops } = useDeckEditor();
    if (!slide) return null;
    const notes = <SpeakerNotes notes={slide.notes} onChange={(n) => ops.setNotes(slide.id, n)} placeholder={placeholder} />;
    // Match the default layout: render bare unless a className wrapper is asked for.
    return className ? <div className={className}>{notes}</div> : notes;
}

export interface DeckEditorStatusBarProps {
    className?: string;
    style?: CSSProperties;
    /** Custom content. Receives the shared controller for a bespoke bar. */
    children?: ReactNode | ((ctx: ReturnType<typeof useDeckEditor>) => ReactNode);
}

/**
 * A status bar summarizing the current slide + selection. Not part of the
 * default `<DeckEditor>` layout — drop it into a bespoke composition. Pass
 * `children` (node or render-prop) to replace the default summary entirely.
 */
export function DeckEditorStatusBar({ className, style, children }: DeckEditorStatusBarProps) {
    const ctx = useDeckEditor();
    const { deck, slideId, slide, selectedElement } = ctx;
    const cls = `fs-statusbar flex items-center gap-3 border-t border-zinc-200 bg-white px-4 py-1.5 text-xs text-zinc-500 dark:border-zinc-800 dark:bg-zinc-950${className ? ` ${className}` : ""}`;

    if (children !== undefined) {
        return (
            <div className={cls} style={style}>
                {typeof children === "function" ? children(ctx) : children}
            </div>
        );
    }

    const index = slideId ? deck.slides.findIndex((s) => s.id === slideId) : -1;
    const pct = (n: number) => `${Math.round(n * 100)}%`;
    return (
        <div className={cls} style={style}>
            <span>{slide ? `Slide ${index + 1}/${deck.slides.length}` : `${deck.slides.length} slide${deck.slides.length === 1 ? "" : "s"}`}</span>
            {selectedElement && (
                <>
                    <span className="text-zinc-300 dark:text-zinc-700">·</span>
                    <span className="font-mono">{selectedElement.type}</span>
                    <span className="font-mono">
                        x {pct(selectedElement.x)} · y {pct(selectedElement.y)} · w {pct(selectedElement.w)} · h {pct(selectedElement.h)}
                    </span>
                </>
            )}
        </div>
    );
}

/**
 * The fancy-slides data model.
 *
 * Every shape here is JSON-friendly — pure objects, arrays, primitives, and
 * tagged unions. No React children, no functions, no class instances. This
 * is the contract the deck schema commits to: an LLM can emit a deck, a
 * server can store one, a designer can hand-edit one, and the viewer +
 * editor will render it identically.
 *
 * Coordinate system: elements position themselves in slide-relative units
 * where the slide is a 1.0 × (1 / aspectRatio) rectangle. So `x: 0.5, y: 0.5`
 * is the centre of the slide regardless of how big it's rendered. This
 * keeps decks resolution-independent — a fullscreen 1920×1080 viewer and a
 * thumbnail at 320×180 render the same layout.
 */

// ─── Deck ──────────────────────────────────────────────────────────────────

export interface Deck {
    /** Stable id. Required even when persistence is in-memory. */
    id: string;
    /** Human title — shown in the editor chrome + browser tab. */
    title: string;
    /** Ordered slide list. The viewer steps through in this order. */
    slides: Slide[];
    /** Visual theme for the whole deck. */
    theme: Theme;
    /**
     * Schema version the deck was authored against. Omitted == version 1 (the
     * implicit version for decks created before versioning). Used by the
     * serialize / parse helpers to migrate older shapes forward. Mirrors
     * `dark-slide`'s `Schema::SCHEMA_VERSION`.
     */
    version?: number;
    /** Free-form metadata — `{ author, createdAt, updatedAt, tags, … }`. */
    metadata?: Record<string, unknown>;
}

/**
 * Current deck schema version. Bump when a structural change needs migration on
 * load. Kept in lockstep with the sibling `dark-slide` PHP package.
 */
export const SCHEMA_VERSION = 1;

// ─── Slide ─────────────────────────────────────────────────────────────────

/** Layout presets that pre-populate / constrain element placement. */
export type SlideLayout =
    | "blank"            // empty canvas, free placement
    | "title"            // centered title
    | "title-content"    // title at top, content area below
    | "two-column"       // left + right halves
    | "section-divider"  // section header with subtitle
    | "image-text"       // image left, text right
    | "text-image"       // text left, image right
    | "quote";           // big centered quote

export interface Slide {
    /** Stable id. */
    id: string;
    /** Optional layout preset. Mostly used by agents — humans tend to free-place. */
    layout?: SlideLayout;
    /** Elements rendered on the slide in z-order (last on top). */
    elements: SlideElement[];
    /** Background fill — color, image, or gradient. Inherits from theme when absent. */
    background?: SlideBackground;
    /** Entrance transition for this slide. Inherits from theme.transition when absent. */
    transition?: SlideTransition;
    /** Speaker notes — markdown. */
    notes?: string;
    /**
     * Plain-text narration script for AI-narrated decks: TTS reads from
     * `narration`, presenter view shows `notes`. Opaque to the pptx writer
     * (stored as data, not rendered into the slide).
     */
    narration?: string;
    /** Free-form metadata — `{ title, tags, durationSec, … }`. */
    metadata?: Record<string, unknown>;
}

// ─── Elements ──────────────────────────────────────────────────────────────

/**
 * Every element is positioned in slide-relative coordinates (0..1). x/y are
 * the top-left corner; w/h are width/height as a fraction of the slide.
 */
export interface ElementBase {
    /** Stable id. Agents reference elements by id. */
    id: string;
    /** Element kind — discriminator. */
    type: SlideElement["type"];
    /** Left edge, 0..1 (fraction of slide width). */
    x: number;
    /** Top edge, 0..1 (fraction of slide height). */
    y: number;
    /** Width, 0..1. */
    w: number;
    /** Height, 0..1. */
    h: number;
    /** Rotation in degrees, clockwise. */
    rotation?: number;
    /** Z-order — higher renders on top. Falls back to array order when undefined. */
    z?: number;
    /** Lock from editing. */
    locked?: boolean;
    /** Hide on this slide (still in the data — for animated reveals). */
    hidden?: boolean;
    /**
     * Whole-element hyperlink. When set, the element becomes a click target in
     * the viewer (opens in a new tab) and the pptx writer emits an
     * `<a:hlinkClick>` on the shape / picture. For rich inline links *within*
     * text, use a markdown `[label](url)` in the text content instead.
     */
    href?: string;
    /** Entrance build animation — when present the element participates in the slide's build sequence. */
    animation?: ElementAnimation;
}

// ─── Element entrance animations (builds) ────────────────────────────────────

/** Visual entrance effect played when an element builds onto the slide. */
export type AnimationEffect = "fade" | "fly-in" | "zoom" | "wipe";

/** When an element's build fires relative to the surrounding builds. */
export type AnimationTrigger = "on-click" | "with-prev" | "after-prev";

/**
 * Per-element entrance animation ("build step"). Elements with an `animation`
 * start hidden and reveal as the presenter advances through the slide's build
 * sequence. The shape is shared with the sibling `dark-slide` PHP package, so
 * keep it byte-for-byte aligned.
 */
export interface ElementAnimation {
    /** Visual effect. */
    effect: AnimationEffect;
    /** When the build fires relative to its neighbours. Default `"on-click"`. */
    trigger?: AnimationTrigger;
    /** Direction for `fly-in` / `wipe`. Default `"left"`. */
    direction?: "left" | "right" | "up" | "down";
    /** Effect duration in ms. Default `500`. */
    duration?: number;
    /** Delay before the effect starts, in ms. Default `0`. */
    delay?: number;
    /** Build order within the slide, ascending; ties broken by element array index. */
    order?: number;
    /**
     * Reveal a TEXT element one paragraph/line at a time (PowerPoint/Google
     * Slides "By paragraph"). The element expands into one build per paragraph
     * — the element's `content` split on `"\n"` (a trailing empty line is
     * dropped). The first paragraph uses this animation's `trigger`; every
     * subsequent paragraph reveals on a fresh click. Only meaningful for text
     * elements; ignored for other types and when the element has 0/1 paragraphs
     * (then it behaves like a normal single build).
     */
    byParagraph?: boolean;
}

export interface TextElement extends ElementBase {
    type: "text";
    /** Content — markdown by default; can also be plain text or HTML. */
    content: string;
    /** Content format. Defaults to `"markdown"`. */
    format?: "markdown" | "html" | "plain";
    /** Typography. */
    style?: TextStyle;
}

export interface TextStyle {
    /** Font family — falls back to theme.fonts.body. */
    fontFamily?: string;
    /** Font size in px at the slide's design width (theme.slideWidth). */
    fontSize?: number;
    /** Font weight (`100..900`, or `"normal" | "bold"`). */
    weight?: "normal" | "medium" | "semibold" | "bold" | number;
    /** Horizontal alignment. */
    align?: "left" | "center" | "right" | "justify";
    /** Vertical alignment within the box. */
    verticalAlign?: "top" | "middle" | "bottom";
    /** Color (any CSS color). Falls back to theme.colors.text. */
    color?: string;
    /** Line height (multiplier). */
    lineHeight?: number;
    /** Italic. */
    italic?: boolean;
    /** Underline. */
    underline?: boolean;
}

export interface ImageElement extends ElementBase {
    type: "image";
    /** Image URL or data URI. */
    src: string;
    /** Alt text for accessibility. */
    alt?: string;
    /** How the image is fit inside its box. */
    fit?: "contain" | "cover" | "fill" | "scale-down";
    /** Optional crop window (slide-relative). */
    crop?: { x: number; y: number; w: number; h: number };
}

export interface ChartElement extends ElementBase {
    type: "chart";
    /** Apache ECharts option object. Passed straight to `<EChart>`. */
    option: Record<string, unknown>;
    /** Theme name passed to `<EChart>`. */
    chartTheme?: string;
}

export interface CodeElement extends ElementBase {
    type: "code";
    /** Source code. */
    code: string;
    /** Language alias for the highlighter. */
    language?: string;
    /** Show line numbers. Defaults to `true`. */
    lineNumbers?: boolean;
    /** Theme — `"light"`, `"dark"`, `"auto"`, or a custom registered name. */
    codeTheme?: string;
}

/**
 * One table column. `key` is what every row is keyed BY; `label` is what the
 * header shows, and falls back to `key` when absent, as dark-slide’s writer
 * resolves it.
 */
/**
 * A table cell's look: dark-slide's table cell model, drawn the same way here.
 * Precedence: cell > row > column > band (header | stripe | body) > table >
 * theme > default. `false` stops the chain and means off.
 */
export interface TableCellStyle {
    fill?: string | false;
    color?: string;
    bold?: boolean;
    italic?: boolean;
    underline?: boolean;
    align?: "left" | "center" | "right" | "justify";
    anchor?: "top" | "middle" | "bottom";
    /** Design px, scaled like text. */
    fontSize?: number;
    fontFamily?: string;
    /** `false` for none, or one rule for every side: `{ color, width }` (width in design px). */
    borders?: false | { color?: string; width?: number };
}

export interface TableColumn extends TableCellStyle {
    key: string;
    label?: string;
    /** A fraction of the table (all widths <= 1) or a weight. */
    width?: number;
}

/** A cell given as an object: its text plus its own style. */
export interface TableCell extends TableCellStyle {
    text: string;
}

export interface TableStyle extends TableCellStyle {
    /** The header row's band (default: theme accent, white, bold); `false` for no header row. */
    header?: TableCellStyle | false;
    /** Every second body row's band (default: theme surface); `false` for none. */
    stripe?: TableCellStyle | false;
    /** Every body row's band. */
    body?: TableCellStyle;
}

/**
 * One table row: an object keyed by each column’s `key`, or the values in COLUMN
 * ORDER.
 *
 * The keyed form is canonical — it survives a column reorder, and it is the only
 * one that can also carry row-level style for the pptx writer. The positional
 * form is accepted because it is what an author guesses from a bare column list,
 * and guessing it used to render a full-size grid with every cell blank and
 * nothing logged (#14).
 */
export type TableRow = Record<string, unknown> | unknown[];

export interface TableElement extends ElementBase {
    type: "table";
    /** Column definitions — `{ key, label }`. */
    columns: TableColumn[];
    /** Row data — objects keyed by column `key`, or values in column order. A value is text or a `TableCell`. */
    rows: TableRow[];
    /** The table's look, as dark-slide writes it. */
    style?: TableStyle;
}

export type ShapeKind = "rect" | "rounded-rect" | "ellipse" | "line" | "arrow" | "triangle";

export interface ShapeElement extends ElementBase {
    type: "shape";
    shape: ShapeKind;
    /** Fill color (any CSS color, or `"none"`). */
    fill?: string;
    /** Stroke color. */
    stroke?: string;
    /** Stroke width in px at the slide's design width. */
    strokeWidth?: number;
    /** Dashed stroke. */
    dashed?: boolean;
    /**
     * Corner radius for `rounded-rect`, in px at the slide's design width (default 8),
     * capped at half the shorter side. A plain `rect` has square corners.
     */
    radius?: number;
}

export interface EmbedElement extends ElementBase {
    type: "embed";
    /** Embed URL — typically a video, dashboard, or fancy-screens Screen. */
    src: string;
    /** iframe `title` for accessibility. */
    title?: string;
    /** Sandbox attribute. Defaults to allow-scripts (no allow-same-origin). */
    sandbox?: string;
}

export type SlideElement =
    | TextElement
    | ImageElement
    | ChartElement
    | CodeElement
    | TableElement
    | ShapeElement
    | EmbedElement;

// ─── Background, transitions, theme ────────────────────────────────────────

export interface SlideBackground {
    /** Solid color, or `"transparent"` to inherit theme. */
    color?: string;
    /** Image background URL. Takes precedence over color when present. */
    image?: string;
    /** How the background image is fit. Defaults to `"cover"`. */
    imageFit?: "contain" | "cover" | "fill";
    /** Optional gradient — `"linear-gradient(...)"` or `"radial-gradient(...)"` string. */
    gradient?: string;
}

export type TransitionKind = "none" | "fade" | "slide" | "zoom";

export interface SlideTransition {
    kind: TransitionKind;
    /** Duration in ms. */
    duration?: number;
    /** Direction for `slide` transitions. */
    direction?: "left" | "right" | "up" | "down";
}

export interface Theme {
    /** Theme name — used for serialization + agent routing. */
    name: string;
    /** Aspect ratio — defaults to 16:9. Custom themes can pick anything. */
    aspectRatio?: number;
    /** Design width in px. Slides scale to fit; this just sets the unit base for fontSize/strokeWidth. */
    slideWidth?: number;
    colors?: ThemeColors;
    fonts?: ThemeFonts;
    /** Default transition for slides that don't specify their own. */
    defaultTransition?: SlideTransition;
}

export interface ThemeColors {
    background?: string;
    text?: string;
    muted?: string;
    accent?: string;
    surface?: string;
}

export interface ThemeFonts {
    /** Used for `Heading`-like text elements (the default for large fontSize). */
    heading?: string;
    /** Used for body text. */
    body?: string;
    /** Used by CodeElement. */
    mono?: string;
}

// ─── Agent / Human+ surface ────────────────────────────────────────────────

/**
 * Agent activity broadcast whenever the deck mutates. Hosts subscribe to feed
 * an AgentPanel, presence layer, or audit log.
 */
export interface DeckActivity {
    /** Stable activity id. */
    id: string;
    /** Wall-clock timestamp. */
    at: number;
    /** Who made the change. */
    actor: { kind: "human" | "agent"; id: string; name?: string; color?: string };
    /** What changed. */
    op: DeckOp;
}

/**
 * The canonical, language-neutral deck operation vocabulary (v0.13+).
 *
 * Every op is a flat JSON object discriminated by a dotted `op` string. The
 * shape is deliberately language-neutral so the *same* op contract is shared
 * with the sibling `dark-slide` PHP package: an op emitted by `<DeckEditor>` in
 * the browser can be reduced server-side by `DarkSlide\Reducer::apply()`, and a
 * server-computed `DarkSlide\Agent::diff()` replays in the editor — one
 * vocabulary, one reducer per authoritative host. Published as a JSON Schema via
 * {@link deckOpSchema} so any backend can validate it.
 *
 * Ids are always named `slideId` / `elementId` (never a bare `id`), and `op`
 * names are `subject.verb` in camelCase. Migrating from the pre-0.13
 * `kind`-flavored ops: {@link mapLegacyOp}.
 */
export type DeckOp =
    | { op: "deck.setTitle"; title: string }
    | { op: "deck.setTheme"; theme: Theme }
    /** Replace the entire deck atomically — stream a full presentation IN in one op. */
    | { op: "deck.replace"; deck: Deck }
    | { op: "slide.add"; index: number; slide: Slide }
    | { op: "slide.remove"; slideId: string }
    | { op: "slide.reorder"; slideId: string; toIndex: number }
    | { op: "slide.setLayout"; slideId: string; layout: SlideLayout }
    | { op: "slide.setNotes"; slideId: string; notes: string }
    | { op: "slide.setBackground"; slideId: string; background?: SlideBackground }
    | { op: "slide.setTransition"; slideId: string; transition?: SlideTransition }
    | { op: "element.add"; slideId: string; element: SlideElement }
    | { op: "element.remove"; slideId: string; elementId: string }
    | { op: "element.update"; slideId: string; elementId: string; patch: Partial<SlideElement> }
    | { op: "element.move"; slideId: string; elementId: string; x: number; y: number }
    | { op: "element.resize"; slideId: string; elementId: string; w: number; h: number }
    | { op: "element.setAnimation"; slideId: string; elementId: string; animation?: ElementAnimation };

/** The dotted `op` discriminator of every {@link DeckOp}. */
export type DeckOpType = DeckOp["op"];

/**
 * The pre-0.13 `kind`-flavored op vocabulary. Retained so existing consumers can
 * map their stored/streamed ops forward with {@link mapLegacyOp}. Prefer
 * {@link DeckOp} in new code.
 *
 * @deprecated Use {@link DeckOp}; convert with {@link mapLegacyOp}.
 */
export type LegacyDeckOp =
    | { kind: "deck_set_title"; title: string }
    | { kind: "deck_apply_theme"; theme: Theme }
    | { kind: "deck_set"; deck: Deck }
    | { kind: "slide_add"; index: number; slide: Slide }
    | { kind: "slide_remove"; id: string }
    | { kind: "slide_reorder"; id: string; toIndex: number }
    | { kind: "slide_set_layout"; id: string; layout: SlideLayout }
    | { kind: "slide_set_notes"; id: string; notes: string }
    | { kind: "slide_set_background"; id: string; background?: SlideBackground }
    | { kind: "slide_set_transition"; id: string; transition?: SlideTransition }
    | { kind: "element_add"; slideId: string; element: SlideElement }
    | { kind: "element_remove"; slideId: string; elementId: string }
    | { kind: "element_update"; slideId: string; elementId: string; patch: Partial<SlideElement> }
    | { kind: "element_move"; slideId: string; elementId: string; x: number; y: number }
    | { kind: "element_resize"; slideId: string; elementId: string; w: number; h: number }
    | { kind: "element_set_animation"; slideId: string; elementId: string; animation?: ElementAnimation };

import { useCallback, useMemo } from "react";
import type { Deck, DeckOp, ElementAnimation, Slide, SlideElement, SlideLayout, Theme, SlideBackground, SlideTransition } from "../types";
import { elementId, slideId } from "../utils/ids";

/**
 * Throw an `Error` naming the missing slide/element an op targets — the strict
 * pre-check behind `reduce(deck, op, { onMissing: "throw" })`. Deck-level ops
 * and `slide.add` address nothing existing, so they always pass.
 */
function assertTargetsExist(deck: Deck, op: DeckOp): void {
    const sid = "slideId" in op ? op.slideId : undefined;
    if (sid === undefined) return;
    const slide = deck.slides.find((s) => s.id === sid);
    if (!slide) throw new Error(`No slide '${sid}' in the deck.`);
    const eid = "elementId" in op ? op.elementId : undefined;
    if (eid === undefined) return;
    if (!slide.elements.some((e) => e.id === eid)) {
        throw new Error(`No element '${eid}' on slide '${sid}'.`);
    }
}

/**
 * Hook that wraps a controlled deck with a typed mutation API. Every helper
 * applies a `DeckOp` and emits the new deck via `onChange`. Consumers that
 * want raw control over the deck can skip this and edit the deck directly
 * — the helpers exist so the editor / agent bridge / undo system all funnel
 * through the same shape.
 */
/**
 * Who mints new slide/element ids.
 *
 * - `"client"` (default) — ids are final, minted locally. Instant; right for
 *   solo editors.
 * - `"optimistic"` — ids are minted as provisional `tmp_…` ids and surfaced in
 *   the emitted op, so a collaborative/agent-driven host can reconcile them to
 *   the server-assigned id when the op echoes back (see `useDeckSync`).
 * - `"server"` — same provisional `tmp_…` minting; the `tmp_` prefix is the
 *   signal that the authoritative id comes from the server. (The element still
 *   renders immediately under its tmp id; gate on confirmation host-side if you
 *   need strict server-only ids.)
 */
export type IdStrategy = "client" | "optimistic" | "server";

export interface UseDeckStateOptions {
    value: Deck;
    onChange: (next: Deck) => void;
    /** Called after every mutation with the op that produced it — wire up an AgentPanel / audit log. */
    onOp?: (op: DeckOp) => void;
    /** Who mints new ids. Defaults to `"client"`. See {@link IdStrategy}. */
    idStrategy?: IdStrategy;
}

export interface DeckStateApi {
    /** Apply a raw DeckOp — the catch-all that every helper funnels through. */
    apply: (op: DeckOp) => void;
    /** Deck-level helpers. */
    setTitle: (title: string) => void;
    applyTheme: (theme: Theme) => void;
    /** Replace the entire deck — stream a full presentation in atomically. */
    setDeck: (deck: Deck) => void;
    /** Slide-level helpers. */
    addSlide: (index?: number, partial?: Partial<Slide>) => string;
    duplicateSlide: (id: string) => string;
    removeSlide: (id: string) => void;
    reorderSlide: (id: string, toIndex: number) => void;
    setLayout: (id: string, layout: SlideLayout) => void;
    setNotes: (id: string, notes: string) => void;
    setBackground: (id: string, bg?: SlideBackground) => void;
    setTransition: (id: string, transition?: SlideTransition) => void;
    /** Element-level helpers. */
    addElement: (slideId: string, element: Omit<SlideElement, "id"> & { id?: string }) => string;
    removeElement: (slideId: string, elementId: string) => void;
    updateElement: (slideId: string, elementId: string, patch: Partial<SlideElement>) => void;
    moveElement: (slideId: string, elementId: string, x: number, y: number) => void;
    resizeElement: (slideId: string, elementId: string, w: number, h: number) => void;
    /** Set or clear an element's entrance build animation. Pass `undefined` to clear. */
    setAnimation: (slideId: string, elementId: string, animation?: ElementAnimation) => void;
    /** Convenience lookups. */
    getSlide: (id: string) => Slide | undefined;
    getElement: (slideId: string, elementId: string) => SlideElement | undefined;
}

export function useDeckState({ value, onChange, onOp, idStrategy = "client" }: UseDeckStateOptions): DeckStateApi {
    const apply = useCallback(
        (op: DeckOp) => {
            const next = reduce(value, op);
            onChange(next);
            onOp?.(op);
        },
        [value, onChange, onOp],
    );

    // Provisional ids are tagged `tmp_` so a collaborative host can reconcile
    // them to a server-assigned id once the op echoes back.
    const mkId = useCallback(
        (gen: () => string): string => (idStrategy === "client" ? gen() : `tmp_${gen()}`),
        [idStrategy],
    );

    return useMemo<DeckStateApi>(() => {
        return {
            apply,
            setTitle: (title) => apply({ op: "deck.setTitle", title }),
            applyTheme: (theme) => apply({ op: "deck.setTheme", theme }),
            setDeck: (deck) => apply({ op: "deck.replace", deck }),
            addSlide: (index, partial) => {
                const id = partial?.id ?? mkId(slideId);
                const slide: Slide = {
                    id,
                    layout: partial?.layout ?? "blank",
                    elements: partial?.elements ?? [],
                    background: partial?.background,
                    transition: partial?.transition,
                    notes: partial?.notes,
                    metadata: partial?.metadata,
                };
                apply({ op: "slide.add", index: index ?? value.slides.length, slide });
                return id;
            },
            duplicateSlide: (id) => {
                const src = value.slides.find((s) => s.id === id);
                if (!src) return id;
                const newId = mkId(slideId);
                const clone: Slide = {
                    ...src,
                    id: newId,
                    elements: src.elements.map((e) => ({ ...e, id: mkId(elementId) })),
                };
                const idx = value.slides.findIndex((s) => s.id === id);
                apply({ op: "slide.add", index: idx + 1, slide: clone });
                return newId;
            },
            removeSlide: (id) => apply({ op: "slide.remove", slideId: id }),
            reorderSlide: (id, toIndex) => apply({ op: "slide.reorder", slideId: id, toIndex }),
            setLayout: (id, layout) => apply({ op: "slide.setLayout", slideId: id, layout }),
            setNotes: (id, notes) => apply({ op: "slide.setNotes", slideId: id, notes }),
            setBackground: (id, background) => apply({ op: "slide.setBackground", slideId: id, background }),
            setTransition: (id, transition) => apply({ op: "slide.setTransition", slideId: id, transition }),
            addElement: (slideIdArg, element) => {
                const id = element.id ?? mkId(elementId);
                apply({ op: "element.add", slideId: slideIdArg, element: { ...element, id } as SlideElement });
                return id;
            },
            removeElement: (slideIdArg, elementIdArg) => apply({ op: "element.remove", slideId: slideIdArg, elementId: elementIdArg }),
            updateElement: (slideIdArg, elementIdArg, patch) =>
                apply({ op: "element.update", slideId: slideIdArg, elementId: elementIdArg, patch }),
            moveElement: (slideIdArg, elementIdArg, x, y) => apply({ op: "element.move", slideId: slideIdArg, elementId: elementIdArg, x, y }),
            resizeElement: (slideIdArg, elementIdArg, w, h) => apply({ op: "element.resize", slideId: slideIdArg, elementId: elementIdArg, w, h }),
            setAnimation: (slideIdArg, elementIdArg, animation) =>
                apply({ op: "element.setAnimation", slideId: slideIdArg, elementId: elementIdArg, animation }),
            getSlide: (id) => value.slides.find((s) => s.id === id),
            getElement: (slideIdArg, elementIdArg) => value.slides.find((s) => s.id === slideIdArg)?.elements.find((e) => e.id === elementIdArg),
        };
    }, [apply, value.slides, mkId]);
}

/** How `reduce` treats an op whose target slide/element isn't on the deck. */
export interface ReduceOptions {
    /**
     * `"skip"` (default) returns the deck unchanged on a missing target —
     * resilient for broadcast replay. `"throw"` raises an `Error` naming the
     * missing id, so an agent/MCP tool path gets a correctable signal instead
     * of a silent no-op. Twin of dark-slide's `Reducer::strictApply()`.
     */
    onMissing?: "skip" | "throw";
}

/**
 * Pure reducer — the single source of truth for how every DeckOp mutates a
 * Deck. Agents, undo stacks, replay logs, and the editor all funnel through
 * this. Never mutates the input.
 *
 * Pass `{ onMissing: "throw" }` on agent-facing paths to surface bad targets
 * (`reduce(deck, op, { onMissing: "throw" })` — exported as `reduceDeck`).
 */
export function reduce(deck: Deck, op: DeckOp, opts?: ReduceOptions): Deck {
    if (opts?.onMissing === "throw") {
        assertTargetsExist(deck, op);
    }
    switch (op.op) {
        case "deck.setTitle":
            return { ...deck, title: op.title };
        case "deck.setTheme":
            return { ...deck, theme: op.theme };
        case "deck.replace":
            // Replace the whole deck — streaming a full presentation in. The
            // previous deck is what an undo entry would snapshot.
            return op.deck;
        case "slide.add": {
            const slides = [...deck.slides];
            slides.splice(Math.max(0, Math.min(slides.length, op.index)), 0, op.slide);
            return { ...deck, slides };
        }
        case "slide.remove":
            return { ...deck, slides: deck.slides.filter((s) => s.id !== op.slideId) };
        case "slide.reorder": {
            const idx = deck.slides.findIndex((s) => s.id === op.slideId);
            if (idx < 0) return deck;
            const slides = [...deck.slides];
            const [moved] = slides.splice(idx, 1);
            slides.splice(Math.max(0, Math.min(slides.length, op.toIndex)), 0, moved);
            return { ...deck, slides };
        }
        case "slide.setLayout":
            return { ...deck, slides: deck.slides.map((s) => (s.id === op.slideId ? { ...s, layout: op.layout } : s)) };
        case "slide.setNotes":
            return { ...deck, slides: deck.slides.map((s) => (s.id === op.slideId ? { ...s, notes: op.notes } : s)) };
        case "slide.setBackground":
            return { ...deck, slides: deck.slides.map((s) => (s.id === op.slideId ? { ...s, background: op.background } : s)) };
        case "slide.setTransition":
            return { ...deck, slides: deck.slides.map((s) => (s.id === op.slideId ? { ...s, transition: op.transition } : s)) };
        case "element.add":
            return {
                ...deck,
                slides: deck.slides.map((s) => (s.id === op.slideId ? { ...s, elements: [...s.elements, op.element] } : s)),
            };
        case "element.remove":
            return {
                ...deck,
                slides: deck.slides.map((s) =>
                    s.id === op.slideId ? { ...s, elements: s.elements.filter((e) => e.id !== op.elementId) } : s,
                ),
            };
        case "element.update":
            return {
                ...deck,
                slides: deck.slides.map((s) =>
                    s.id === op.slideId
                        ? { ...s, elements: s.elements.map((e) => (e.id === op.elementId ? ({ ...e, ...op.patch } as SlideElement) : e)) }
                        : s,
                ),
            };
        case "element.move":
            return {
                ...deck,
                slides: deck.slides.map((s) =>
                    s.id === op.slideId
                        ? { ...s, elements: s.elements.map((e) => (e.id === op.elementId ? { ...e, x: op.x, y: op.y } : e)) }
                        : s,
                ),
            };
        case "element.resize":
            return {
                ...deck,
                slides: deck.slides.map((s) =>
                    s.id === op.slideId
                        ? { ...s, elements: s.elements.map((e) => (e.id === op.elementId ? { ...e, w: op.w, h: op.h } : e)) }
                        : s,
                ),
            };
        case "element.setAnimation":
            return {
                ...deck,
                slides: deck.slides.map((s) =>
                    s.id === op.slideId
                        ? {
                              ...s,
                              elements: s.elements.map((e) => {
                                  if (e.id !== op.elementId) return e;
                                  if (op.animation === undefined) {
                                      // Clear: drop the key entirely so the element leaves the build sequence.
                                      const { animation: _drop, ...rest } = e;
                                      return rest as SlideElement;
                                  }
                                  return { ...e, animation: op.animation };
                              }),
                          }
                        : s,
                ),
            };
    }
}

import type { Theme } from "../types";
