/**
 * A CSS font-family for a theme face, with a generic fallback.
 *
 * A deck names brand faces ("Poppins", "Inter") that the viewing browser often
 * does not have. Without a fallback the browser picks its default, which is a
 * SERIF, so a sans-serif deck drew its titles in Times; PowerPoint and
 * LibreOffice substitute a sans. Names with spaces are quoted; a value that is
 * already a stack (it has a comma) is left as the author wrote it.
 */
const GENERIC = {
    sans: "ui-sans-serif, system-ui, sans-serif",
    mono: "ui-monospace, SFMono-Regular, Menlo, monospace",
} as const;

export function fontStack(face: string | null | undefined, kind: keyof typeof GENERIC = "sans"): string {
    const name = typeof face === "string" ? face.trim() : "";
    if (name === "") return GENERIC[kind];
    if (name.includes(",")) return name;
    const quoted = /\s/.test(name) && !/^["'].*["']$/.test(name) ? `"${name}"` : name;
    return `${quoted}, ${GENERIC[kind]}`;
}

import type { TableColumn, TableRow } from "../types";

/**
 * One table row's cells, keyed by column key.
 *
 * A row is canonically an object keyed by each column's `key`. A row given as an
 * ARRAY is POSITIONAL: its values are read in column order.
 *
 * The positional form used to resolve every cell to `undefined`, so the table drew
 * at the correct size with every cell blank — no exception, nothing logged,
 * because the geometry comes from `columns` and `rows.length` rather than from any
 * cell. It is also the shape an author guesses whenever the published schema shows
 * a column list and no row shape, which is what `dark-slide` published until
 * 0.10.4. Reported as #14, after reaching a customer as "the table rows were
 * empty".
 *
 * Surplus values have nowhere to go and are dropped; columns past the last value
 * read as empty, exactly as a missing key does. The matching rule lives in
 * `dark-slide`'s `TableResolver::cellMap` in all three writer engines, and is
 * pinned cross-language by `fancy-conformance` rows 0029–0033.
 *
 * It lives here rather than in the renderer because the EDITOR needs the identical
 * rule — two readings of one row is how a deck renders one way and edits another.
 */
export function tableCells(row: TableRow, columns: TableColumn[]): Record<string, unknown> {
    // A row can itself be null in hand-written JSON.
    if (!row) return {};
    if (!Array.isArray(row)) return row;

    const cells: Record<string, unknown> = {};
    row.forEach((value, i) => {
        const column = columns[i];
        if (column) cells[column.key] = value;
    });

    return cells;
}

/**
 * Every row in the canonical keyed form.
 *
 * Use it before EDITING: an editor that patches a positional row by key would
 * write a cell the renderer then reads from a different place. Converting on the
 * way in means a deck authored positionally is saved back keyed, which is the form
 * that survives a column reorder.
 */
export function tableRowsAsRecords(rows: TableRow[], columns: TableColumn[]): Record<string, unknown>[] {
    return (Array.isArray(rows) ? rows : []).map((row) => tableCells(row, columns));
}

/**
 * The rows no rule can rescue: OBJECT rows that match no column key.
 *
 * A positional row is read by order and a partially-filled row is ordinary, so
 * what remains is a row keyed by something no column reads — in practice a
 * mis-cased or renamed key. Nothing says which column `{"Plan": …}` meant, and it
 * fails the same silent way: full-size grid, every cell empty.
 */
export function unreadableTableRows(rows: TableRow[], columns: TableColumn[]): TableRow[] {
    const keys = columns.map((c) => c.key);

    return (Array.isArray(rows) ? rows : []).filter((row) => {
        if (!row || Array.isArray(row)) return false;
        const rowKeys = Object.keys(row);
        return rowKeys.length > 0 && !rowKeys.some((k) => keys.includes(k));
    });
}

import type { TableColumn, TableElement, Theme } from "../types";

/**
 * A table cell's look, resolved the way dark-slide's `TableResolver` resolves it,
 * so a deck draws here as it prints:
 *
 *     cell > row > column > band (header | stripe | body) > table > theme > default
 *
 * An ABSENT key falls through to the next layer; `false` stops the chain and
 * means off (no fill, no borders). Lengths are design pixels on the deck canvas
 * (`theme.slideWidth`, 1920 by default) and are scaled by the caller.
 *
 * Kept to what a viewer draws: fill, text colour, weight, slant, underline,
 * alignment, vertical anchor, size, face and borders.
 */
export interface CellLook {
    text: string;
    fill: string | null;
    color: string;
    bold: boolean;
    italic: boolean;
    underline: boolean;
    align: "left" | "center" | "right" | "justify";
    anchor: "top" | "middle" | "bottom";
    fontSize: number;
    fontFamily: string | null;
    /** A border colour, or null for none. One rule for all four sides. */
    border: string | null;
    /** The border width, design px (0.75pt default = 2px on the 1920 canvas). */
    borderWidth: number;
}

const STYLE_KEYS = ["fill", "color", "bold", "italic", "underline", "align", "anchor", "fontSize", "fontFamily", "borders"] as const;

export const DEFAULT_FONT_SIZE = 28;
const DEFAULT_BODY_COLOR = "#0F172A";
const DEFAULT_HEADER_COLOR = "#FFFFFF";
const DEFAULT_ACCENT = "#8B5CF6";
const DEFAULT_STRIPE_FILL = "#F8FAFC";
const DEFAULT_BORDER_COLOR = "#D9DEE4";
/** 0.75pt on a 720pt slide, in design px on the 1920 canvas. */
const DEFAULT_BORDER_PX = 2;

type Layer = Record<string, unknown>;

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

function styleKeys(source: unknown): Layer {
    const out: Layer = {};
    if (!isObject(source)) return out;
    for (const k of STYLE_KEYS) {
        if (k in source && source[k] !== null && source[k] !== undefined) out[k] = source[k];
    }
    return out;
}

function themeColor(theme: Theme | undefined, key: "text" | "accent" | "surface" | "background", fallback: string): string {
    const v = theme?.colors?.[key];
    return typeof v === "string" && v !== "" ? v : fallback;
}

function hex6(color: string): string | null {
    const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(color.trim());
    if (!m) return null;
    const h = m[1]!;
    return (h.length === 3 ? h.split("").map((c) => c + c).join("") : h).toUpperCase();
}

/** The stripe band dark-slide draws: theme surface; on a dark theme, background 8% toward text; else light. */
function stripeDefault(theme: Theme | undefined): string {
    const surface = theme?.colors?.surface;
    if (typeof surface === "string" && surface !== "") return surface;
    const bg = hex6(themeColor(theme, "background", "#FFFFFF")) ?? "FFFFFF";
    const lum = (299 * parseInt(bg.slice(0, 2), 16) + 587 * parseInt(bg.slice(2, 4), 16) + 114 * parseInt(bg.slice(4, 6), 16)) / 255000;
    if (lum >= 0.5) return DEFAULT_STRIPE_FILL;
    const text = hex6(themeColor(theme, "text", "#F9FAFB")) ?? "F9FAFB";
    let out = "#";
    for (const i of [0, 2, 4]) {
        const x = parseInt(bg.slice(i, i + 2), 16);
        const y = parseInt(text.slice(i, i + 2), 16);
        out += (x + Math.trunc(((y - x) * 8) / 100)).toString(16).toUpperCase().padStart(2, "0");
    }
    return out;
}

/** A cell value: a string/number, or an object carrying `text` and its own style keys. */
export function cellSpec(value: unknown): Layer & { text: string } {
    if (isObject(value) && ("text" in value || STYLE_KEYS.some((k) => k in value))) {
        return { ...styleKeys(value), text: value.text == null ? "" : String(value.text) };
    }
    if (value == null) return { text: "" };
    if (typeof value === "object") return { text: JSON.stringify(value) };
    return { text: String(value) };
}

/**
 * Resolve one cell. `bodyIndex` counts body rows from 0 (the header is not one);
 * striping applies to odd body rows, as dark-slide stripes them.
 */
export function resolveCell(
    element: TableElement,
    theme: Theme | undefined,
    column: TableColumn,
    value: unknown,
    position: { header: true } | { header: false; bodyIndex: number; row?: unknown },
): CellLook {
    const style: Layer = isObject((element as { style?: unknown }).style) ? ((element as { style?: unknown }).style as Layer) : {};

    const defaults: Layer = { color: themeColor(theme, "text", DEFAULT_BODY_COLOR), align: "left", anchor: "middle", fontSize: DEFAULT_FONT_SIZE };
    let band: Layer = {};
    if (position.header) {
        band = { fill: themeColor(theme, "accent", DEFAULT_ACCENT), color: DEFAULT_HEADER_COLOR, bold: true, ...(isObject(style.header) ? styleKeys(style.header) : {}) };
    } else {
        band = isObject(style.body) ? styleKeys(style.body) : {};
        if (style.stripe !== false && position.bodyIndex % 2 === 1) {
            band = { ...band, fill: stripeDefault(theme), ...(isObject(style.stripe) ? styleKeys(style.stripe) : {}) };
        }
    }
    const spec = position.header ? { text: column.label ?? column.key } : cellSpec(value);
    const rowLayer = position.header ? {} : styleKeys(position.row);
    const layers: Layer[] = [defaults, styleKeys(style), band, styleKeys(column), rowLayer, spec];

    const r: Layer = {};
    let border: string | null = DEFAULT_BORDER_COLOR;
    let borderWidth = DEFAULT_BORDER_PX;
    for (const layer of layers) {
        for (const [k, v] of Object.entries(layer)) {
            if (k === "borders") {
                if (v === false || v === "none") {
                    border = null;
                } else if (isObject(v)) {
                    const all = isObject(v.all) ? v.all : v;
                    if (typeof all.color === "string") border = all.color;
                    if (typeof all.width === "number") borderWidth = all.width;
                }
                continue;
            }
            if (k !== "text") r[k] = v;
        }
    }

    const fill = r.fill;
    const align = r.align === "center" || r.align === "centre" ? "center" : r.align === "right" ? "right" : r.align === "justify" ? "justify" : "left";
    const anchor = r.anchor === "top" ? "top" : r.anchor === "bottom" ? "bottom" : "middle";
    return {
        text: spec.text,
        fill: fill === false || fill === "none" || fill == null ? null : String(fill),
        color: String(r.color),
        bold: r.bold === true,
        italic: r.italic === true,
        underline: r.underline === true,
        align,
        anchor,
        fontSize: typeof r.fontSize === "number" ? r.fontSize : Number(r.fontSize) || DEFAULT_FONT_SIZE,
        fontFamily: typeof r.fontFamily === "string" ? r.fontFamily : null,
        border,
        borderWidth,
    };
}

/**
 * Tiny class-name joiner. Avoids pulling clsx as a dep for this small package.
 */
export function cn(...parts: Array<string | false | null | undefined>): string {
    return parts.filter(Boolean).join(" ");
}

/**
 * Build (entrance-animation) sequencing — the shared model used by both
 * `SlideViewer` and `PresenterView` so step-through behaves identically.
 *
 * A slide's *builds* are the elements that carry an `animation`. They are
 * stable-sorted by `(order ?? 0)` then original element array index, then
 * grouped into *click steps*:
 *
 *   - The first build, and every build whose trigger is `"on-click"`, starts
 *     a NEW step.
 *   - `"with-prev"` plays simultaneously with the current step's lead.
 *   - `"after-prev"` plays after a delay equal to the current step's lead
 *     duration (chained onto its `delay`).
 *
 * `buildStep` semantics (used by the viewer/presenter):
 *   - `0`  → nothing built yet; only non-animated elements are visible.
 *   - `n`  → the first `n` steps have fired; their elements are visible.
 *   - `totalSteps` → every build is shown (the fully-built slide).
 */

import type { ElementAnimation, Slide, SlideElement } from "../types";

/** One element participating in a build, paired with its (defaulted) animation. */
export interface Build {
    element: SlideElement;
    animation: ElementAnimation;
    /** Original index of the element in the slide's `elements` array (tie-breaker). */
    index: number;
    /**
     * For a "by paragraph" text build, which paragraph index (0-based) this
     * build reveals. Undefined for whole-element builds. The renderer uses this
     * to show "the first K paragraphs of this element".
     */
    paraIndex?: number;
}

/**
 * Split a text element's `content` into paragraphs for a "by paragraph" build.
 * Splits on `"\n"` and drops a single trailing empty line (so content ending in
 * a newline doesn't manifest a phantom blank build). Empty interior lines are
 * preserved — they still consume a click, matching PowerPoint's behaviour.
 */
export function splitParagraphs(content: string): string[] {
    const lines = content.split("\n");
    if (lines.length > 1 && lines[lines.length - 1] === "") lines.pop();
    return lines;
}

/**
 * The blocks a text element renders as in the static (non-build) path, given its
 * `format`. Markdown/HTML content is split line-by-line (one block per `"\n"`) so
 * a single newline is a hard line/paragraph break — the canonical line-based
 * model (`splitParagraphs`, `normalizeSlideMarkdown`, dark-slide's pptx export).
 * Passing the whole multi-line string to a CommonMark renderer would instead
 * fold a lone `"\n"` into a soft break (a space), collapsing the lines.
 *
 * `plain` content is returned as a single block: it renders with
 * `white-space: pre-wrap`, which already preserves its newlines.
 */
export function textBlocks(content: string, format: "markdown" | "html" | "plain"): string[] {
    return format === "plain" ? [content] : splitParagraphs(content);
}

/**
 * Whether an element expands into per-paragraph builds: a text element whose
 * animation has `byParagraph` and that splits into 2+ paragraphs. With 0/1
 * paragraphs it behaves like a normal single build.
 */
export function isByParagraph(element: SlideElement, animation: ElementAnimation): boolean {
    if (!animation.byParagraph || element.type !== "text") return false;
    return splitParagraphs(element.content).length > 1;
}

/** A click step — the set of builds revealed by a single forward advance. */
export interface BuildStep {
    /** Builds that reveal on this step (lead first, then with-prev / after-prev). */
    builds: Build[];
}

const DEFAULT_BUILD_DURATION = 500;

/**
 * Collect a slide's builds in resolved order: every element with an
 * `animation`, stable-sorted by `(order ?? 0)` then array index.
 */
export function collectBuilds(slide: Slide | undefined): Build[] {
    if (!slide) return [];
    const builds: Build[] = [];
    slide.elements.forEach((element, index) => {
        if (element.animation) {
            builds.push({ element, animation: element.animation, index });
        }
    });
    // Stable sort: Array.prototype.sort is stable in modern engines, but we
    // tie-break on the captured array index explicitly to be safe.
    const ordered = builds.sort((a, b) => {
        const ao = a.animation.order ?? 0;
        const bo = b.animation.order ?? 0;
        if (ao !== bo) return ao - bo;
        return a.index - b.index;
    });

    // Expand "by paragraph" text builds into one build per paragraph. The first
    // paragraph keeps the element's own trigger (so it can be with-prev /
    // after-prev relative to a prior element); every subsequent paragraph is
    // "on-click" — one line per click. They stay contiguous, so the rest of an
    // element's paragraphs fire before the next element's builds.
    const expanded: Build[] = [];
    for (const build of ordered) {
        if (isByParagraph(build.element, build.animation)) {
            const paras = splitParagraphs((build.element as { content: string }).content);
            paras.forEach((_, paraIndex) => {
                const animation: ElementAnimation =
                    paraIndex === 0 ? build.animation : { ...build.animation, trigger: "on-click" };
                expanded.push({ element: build.element, animation, index: build.index, paraIndex });
            });
        } else {
            expanded.push(build);
        }
    }
    return expanded;
}

/**
 * Group a slide's builds into click steps. The first build always opens a
 * step; thereafter an `"on-click"` trigger opens a new step while
 * `"with-prev"` / `"after-prev"` attach to the current one.
 */
export function buildSteps(slide: Slide | undefined): BuildStep[] {
    const builds = collectBuilds(slide);
    const steps: BuildStep[] = [];
    for (const build of builds) {
        const trigger = build.animation.trigger ?? "on-click";
        if (steps.length === 0 || trigger === "on-click") {
            steps.push({ builds: [build] });
        } else {
            steps[steps.length - 1]!.builds.push(build);
        }
    }
    return steps;
}

/** Total number of click steps for a slide (0 when the slide has no builds). */
export function totalBuildSteps(slide: Slide | undefined): number {
    return buildSteps(slide).length;
}

/**
 * Given a slide and a `buildStep` (0..totalSteps), return the set of element
 * ids that should be VISIBLE. Elements with no animation are always visible;
 * animated elements become visible once their owning step has fired.
 */
export function visibleElementIds(slide: Slide | undefined, buildStep: number): Set<string> {
    const visible = new Set<string>();
    if (!slide) return visible;
    const steps = buildSteps(slide);
    const stepOfElement = new Map<string, number>(); // 1-based step at which an element FIRST reveals
    steps.forEach((step, i) => {
        for (const b of step.builds) {
            // For by-paragraph builds many builds share one element id; the
            // element is visible once its earliest (first paragraph) step fires.
            if (!stepOfElement.has(b.element.id)) stepOfElement.set(b.element.id, i + 1);
        }
    });
    for (const element of slide.elements) {
        const revealStep = stepOfElement.get(element.id);
        if (revealStep === undefined) {
            visible.add(element.id); // no animation → always visible
        } else if (buildStep >= revealStep) {
            visible.add(element.id); // step has fired
        }
    }
    return visible;
}

/**
 * Per-element paragraph reveal state for a "by paragraph" text build at a given
 * `buildStep`. Keyed by element id:
 *   - `revealed` — how many paragraphs (0..count) should be shown so far.
 *   - `firingParaIndex` — the paragraph index revealing on the step that just
 *     fired (so the renderer plays its entrance effect), or `undefined` when no
 *     paragraph of this element fires on `buildStep`.
 * Only elements that actually expand by-paragraph appear in the map.
 */
export interface ParaReveal {
    revealed: number;
    firingParaIndex?: number;
}

export function paragraphReveals(slide: Slide | undefined, buildStep: number): Map<string, ParaReveal> {
    const out = new Map<string, ParaReveal>();
    if (!slide) return out;
    const steps = buildSteps(slide);
    steps.forEach((step, i) => {
        const stepNum = i + 1; // 1-based
        for (const b of step.builds) {
            if (b.paraIndex === undefined) continue;
            const fired = buildStep >= stepNum;
            const prev = out.get(b.element.id) ?? { revealed: 0 };
            if (fired) {
                prev.revealed = Math.max(prev.revealed, b.paraIndex + 1);
                if (stepNum === buildStep) prev.firingParaIndex = b.paraIndex;
            }
            out.set(b.element.id, prev);
        }
    });
    return out;
}

/**
 * The builds that fire when advancing INTO `buildStep` (1-based). Returns the
 * lead build first; the viewer uses `with-prev` / `after-prev` to compute each
 * element's effective `delay`. Empty when `buildStep` is out of range.
 */
export function buildsForStep(slide: Slide | undefined, buildStep: number): Build[] {
    const steps = buildSteps(slide);
    const step = steps[buildStep - 1];
    return step ? step.builds : [];
}

/**
 * Compute the effective entrance delay (ms) for each build within a step,
 * honouring `with-prev` (0 extra) and `after-prev` (lead duration). The lead
 * build keeps its own `delay`; followers add to it. Keyed by element id.
 */
export function stepDelays(builds: Build[]): Map<string, number> {
    const delays = new Map<string, number>();
    const lead = builds[0];
    if (!lead) return delays;
    const leadDelay = lead.animation.delay ?? 0;
    const leadDuration = lead.animation.duration ?? DEFAULT_BUILD_DURATION;
    delays.set(lead.element.id, leadDelay);
    for (let i = 1; i < builds.length; i++) {
        const b = builds[i]!;
        const own = b.animation.delay ?? 0;
        const trigger = b.animation.trigger ?? "on-click";
        // with-prev → simultaneous with lead; after-prev → starts after lead finishes.
        const base = trigger === "after-prev" ? leadDelay + leadDuration : leadDelay;
        delays.set(b.element.id, base + own);
    }
    return delays;
}

import { lazy, Suspense, type ComponentType, type ReactNode } from "react";

/**
 * Editable code field for the inspector — the real fancy-code CodeEditor, not a
 * plain textarea. fancy-code is an OPTIONAL peer, so (like code-host) it loads
 * via a dynamic import and falls back to a monospace textarea when absent.
 */
interface Props {
    value: string;
    language: string;
    theme: string;
    onChange: (value: string) => void;
}

type CodeEditorComponent = ComponentType<{
    value: string;
    onChange?: (value: string) => void;
    language?: string;
    theme?: string;
    readOnly?: boolean;
    lineNumbers?: boolean;
    wordWrap?: boolean;
    minHeight?: number;
    maxHeight?: number;
    children?: ReactNode;
}> & { Panel: ComponentType };

function FallbackTextarea({ value, onChange }: Props) {
    return (
        <textarea
            className="block w-full resize-y rounded-md border border-zinc-300 bg-zinc-950 p-2 font-mono text-xs text-zinc-100 dark:border-zinc-700"
            rows={8}
            value={value}
            spellCheck={false}
            onChange={(e) => onChange(e.target.value)}
        />
    );
}

const CodeInputInner: ComponentType<Props> = lazy(async () => {
    try {
        const mod: Record<string, unknown> = await import("@particle-academy/fancy-code");
        const CodeEditor = mod.CodeEditor as CodeEditorComponent | undefined;
        if (!CodeEditor) return { default: FallbackTextarea };
        return {
            default: ({ value, language, theme, onChange }: Props) => (
                <div className="overflow-hidden rounded-md border border-zinc-300 dark:border-zinc-700">
                    <CodeEditor
                        value={value}
                        onChange={onChange}
                        language={language}
                        theme={theme}
                        lineNumbers
                        wordWrap
                        minHeight={140}
                        maxHeight={280}
                    >
                        <CodeEditor.Panel />
                    </CodeEditor>
                </div>
            ),
        };
    } catch {
        return { default: FallbackTextarea };
    }
});

export function CodeInput(props: Props) {
    return (
        <div className="space-y-1">
            <label className="block text-xs font-medium text-zinc-600 dark:text-zinc-400">Code</label>
            <Suspense fallback={<FallbackTextarea {...props} />}>
                <CodeInputInner {...props} />
            </Suspense>
        </div>
    );
}

import type { CSSProperties, ReactNode } from "react";
import type { Slide as SlideData, SlideElement, Theme } from "../../types";
import { Slide } from "../../../slide";
import { resolveTheme } from "../../theme/theme-utils";
import { cn } from "../../utils/cn";

export interface SlideThumbnailProps {
    slide: SlideData;
    theme?: Theme;
    /** Width of the thumbnail in px. Height comes from the theme's aspect ratio. */
    width?: number;
    /** When true, the thumbnail is rendered with a focused outline. */
    active?: boolean;
    onClick?: () => void;
    onContextMenu?: (e: React.MouseEvent) => void;
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    className?: string;
    style?: CSSProperties;
}

/**
 * Compact slide preview. Used by the slide rail in the editor, by the
 * presenter view, and anywhere else a deck wants to show its slides as
 * thumbnails. Re-uses the shared <Slide> so the layout matches the viewer
 * exactly — no second rendering path.
 *
 * The slide is rendered at its full DESIGN width and the whole thing is
 * CSS-`scale()`d down to the thumbnail size (the same approach fancy-artboard
 * uses for its piece previews). Scaling the rendered output — rather than
 * rendering the slide *at* the thumbnail width — is what makes heavy embedded
 * surfaces (ECharts charts, the fancy-code editor) shrink proportionally:
 * those render at fixed internal font sizes that ignore `slideWidthPx`, so a
 * directly-undersized render leaves them oversized in the thumb. A uniform
 * transform shrinks everything identically, so the thumb is a faithful
 * miniature of the live slide.
 */
export function SlideThumbnail({
    slide,
    theme,
    width = 200,
    active = false,
    onClick,
    onContextMenu,
    renderElement,
    className,
    style,
}: SlideThumbnailProps) {
    const resolved = resolveTheme(theme);
    const ratio = resolved.aspectRatio ?? 16 / 9;
    const designWidth = resolved.slideWidth ?? 1280;
    const scale = width / designWidth;
    const height = width / ratio;

    return (
        <div
            className={cn("fs-thumbnail", className)}
            style={{
                cursor: onClick ? "pointer" : "default",
                borderRadius: 6,
                border: active ? "2px solid #8b5cf6" : "1px solid rgba(0,0,0,0.08)",
                overflow: "hidden",
                boxShadow: active ? "0 0 0 3px rgba(139, 92, 246, 0.2)" : "0 1px 2px rgba(0,0,0,0.05)",
                background: "#ffffff",
                width,
                height,
                ...style,
            }}
            onClick={onClick}
            onContextMenu={onContextMenu}
            data-fancy-slides-thumbnail={slide.id}
        >
            <div
                style={{
                    width: designWidth,
                    height: designWidth / ratio,
                    transform: `scale(${scale})`,
                    transformOrigin: "top left",
                    // The thumb owns interaction — charts/code/iframes inside the
                    // scaled slide shouldn't capture clicks.
                    pointerEvents: "none",
                }}
            >
                <Slide slide={slide} theme={theme} width={designWidth} renderElement={renderElement} />
            </div>
        </div>
    );
}

import { useMemo } from "react";
import {
  fileLabel,
  parseUnifiedDiff,
  type AcceptanceState,
  type AcceptanceStatus,
  type Diff,
  type DiffLine,
  type Hunk,
} from "@particle-academy/fancy-file-commons";

/**
 * A git diff, on the suite's shared diff model.
 *
 * ## Why it takes a patch string
 *
 * `fancy-git` hands back `Diff { patch, files }` — a unified diff. This used to
 * take a bespoke `DiffFile[]` instead, so every consumer had to write their own
 * unified-diff parser to get from what git returns to what the viewer renders.
 * `parseUnifiedDiff` already exists and is already the parser fancy-diff and
 * fancy-code use, so the patch goes straight in.
 *
 * ## Why the model is fancy-file-commons'
 *
 * This component used to declare its own `DiffLine` / `DiffFile`, so a `Diff`
 * produced by fancy-diff could not be handed to it and vice versa — two diff
 * models in one suite, and this was the poorer of the two: no word-level
 * segmentation, no stable content-derived hunk ids, and acceptance expressed as
 * a bare `string[]` of selected ids, which cannot say *rejected*.
 */
export interface DiffViewerProps {
  /**
   * A unified diff, or already-parsed files.
   *
   * The string form is what `fancy-git`'s `Diff.patch` carries. Pass parsed
   * `Diff[]` when the caller already has them — from `computeDiff`, or from one
   * parse shared with another surface.
   */
  value: string | Diff[];
  /**
   * Per-hunk accept / reject / pending. Controlled.
   *
   * A hunk with no entry is `pending`. That is not the same as rejected, and
   * conflating them is what the old `selectedHunkIds: string[]` did: an id was
   * either in the list or absent, so "not looked at yet" and "explicitly turned
   * down" were one state, and a review could not tell whether it was finished.
   */
  acceptance?: AcceptanceState;
  onAcceptanceChange?: (next: AcceptanceState) => void;
  /** `split` renders before and after side by side. */
  mode?: "unified" | "split";
  onModeChange?: (mode: "unified" | "split") => void;
  /** Hide `equal` hunks — the context lines git includes around each change. */
  hideContext?: boolean;
  className?: string;
}

/** Cycles pending → accepted → rejected → pending, so one control reaches all three. */
function nextStatus(current: AcceptanceStatus): AcceptanceStatus {
  return current === "pending" ? "accepted" : current === "accepted" ? "rejected" : "pending";
}

export function DiffViewer({
  value,
  acceptance = {},
  onAcceptanceChange,
  mode = "unified",
  onModeChange,
  hideContext = false,
  className,
}: DiffViewerProps) {
  // Parsing is the expensive part, and a patch does not change between renders.
  const files = useMemo(() => (typeof value === "string" ? parseUnifiedDiff(value) : value), [value]);

  const toggle = (hunkId: string) =>
    onAcceptanceChange?.({ ...acceptance, [hunkId]: nextStatus(acceptance[hunkId] ?? "pending") });

  return (
    <section className={className} data-git-diff="" data-git-diff-mode={mode} aria-label="Git diff">
      <header>
        <strong>Changes</strong>
        <button
          type="button"
          data-git-diff-mode-toggle=""
          onClick={() => onModeChange?.(mode === "unified" ? "split" : "unified")}
        >
          {mode}
        </button>
      </header>

      {files.length === 0 && <p data-git-diff-empty="">No changes</p>}

      {files.map((file, index) => (
        <FileDiff
          // `fileLabel` is undefined for a diff with no header — a computed
          // diff rather than a parsed patch — so the index carries it.
          key={fileLabel(file.file) ?? index}
          file={file}
          acceptance={acceptance}
          onToggle={onAcceptanceChange ? toggle : undefined}
          mode={mode}
          hideContext={hideContext}
        />
      ))}
    </section>
  );
}

function FileDiff({
  file,
  acceptance,
  onToggle,
  mode,
  hideContext,
}: {
  file: Diff;
  acceptance: AcceptanceState;
  onToggle?: (hunkId: string) => void;
  mode: "unified" | "split";
  hideContext: boolean;
}) {
  const path = fileLabel(file.file) ?? "(no path)";
  const hunks = hideContext ? file.hunks.filter((hunk) => hunk.type !== "equal") : file.hunks;

  return (
    <article data-git-diff-file={path}>
      <h3>{path}</h3>
      {file.file?.partial && (
        // A unified diff carries only the changed hunks plus a little context,
        // never the whole file. Saying so stops a reader taking a line's
        // absence as evidence it is not in the file.
        <p data-git-diff-partial="">Showing changed regions only</p>
      )}
      {hunks.map((hunk) => (
        <HunkView
          key={hunk.id}
          hunk={hunk}
          status={acceptance[hunk.id] ?? "pending"}
          onToggle={onToggle}
          mode={mode}
        />
      ))}
    </article>
  );
}

function HunkView({
  hunk,
  status,
  onToggle,
  mode,
}: {
  hunk: Hunk;
  status: AcceptanceStatus;
  onToggle?: (hunkId: string) => void;
  mode: "unified" | "split";
}) {
  // Equal hunks are context, not proposals — there is nothing to accept, and a
  // control implies there is.
  const reviewable = hunk.type !== "equal" && onToggle !== undefined;

  return (
    <div data-git-hunk={hunk.id} data-hunk-type={hunk.type} data-hunk-status={status}>
      {reviewable && (
        <button
          type="button"
          data-git-hunk-toggle={hunk.id}
          aria-pressed={status === "accepted"}
          aria-label={`${status} — ${hunk.type} hunk`}
          onClick={() => onToggle(hunk.id)}
        >
          {status}
        </button>
      )}
      {mode === "split" ? <SplitLines hunk={hunk} /> : <UnifiedLines hunk={hunk} />}
    </div>
  );
}

function UnifiedLines({ hunk }: { hunk: Hunk }) {
  return (
    <pre data-git-diff-lines="unified">
      {hunk.lines.map((line, index) => (
        <Line key={index} line={line} />
      ))}
    </pre>
  );
}

/**
 * Before and after, side by side.
 *
 * The old component had a `split` mode that was a data attribute and a toggle
 * button with nothing behind it — the markup was identical either way, so the
 * control changed a label and no output.
 *
 * Rows pair by position within each side rather than by line number: a
 * `replace` hunk's removals and additions correspond in order, and the line
 * numbers diverge exactly where the file changed, which is every row here.
 */
function SplitLines({ hunk }: { hunk: Hunk }) {
  const before = hunk.lines.filter((line) => line.side !== "after");
  const after = hunk.lines.filter((line) => line.side !== "before");
  const rows = Math.max(before.length, after.length);

  return (
    <div data-git-diff-lines="split">
      <pre data-git-diff-side="before">
        {Array.from({ length: rows }, (_, index) =>
          before[index] ? (
            <Line key={index} line={before[index]} side="before" />
          ) : (
            // A pad, not an omission: without it the two columns drift out of
            // alignment and a removal stops lining up with what replaced it.
            <span key={index} data-git-diff-pad="" />
          ),
        )}
      </pre>
      <pre data-git-diff-side="after">
        {Array.from({ length: rows }, (_, index) =>
          after[index] ? <Line key={index} line={after[index]} side="after" /> : <span key={index} data-git-diff-pad="" />,
        )}
      </pre>
    </div>
  );
}

function Line({ line, side }: { line: DiffLine; side?: "before" | "after" }) {
  // On a split side one number is meaningful; in unified mode both are shown,
  // which is what makes it unified.
  const shown = side === "before" ? line.beforeLineNo : side === "after" ? line.afterLineNo : undefined;

  return (
    <span data-git-diff-line={line.side} data-kind={kindOf(line)}>
      {side ? (
        <span data-git-line-no="">{shown ?? " "}</span>
      ) : (
        <>
          <span data-git-line-no="before">{line.beforeLineNo ?? " "}</span>
          <span data-git-line-no="after">{line.afterLineNo ?? " "}</span>
        </>
      )}
      <code>{line.text}</code>
    </span>
  );
}

/** The +/-/context a reader expects, derived rather than stored a second time. */
function kindOf(line: DiffLine): "addition" | "deletion" | "context" {
  return line.side === "after" ? "addition" : line.side === "before" ? "deletion" : "context";
}

import { useState, type ComponentProps, type ReactNode } from "react";
import { cn, Badge } from "@particle-academy/react-fancy";
import type { DownlineEdge, DownlineMember } from "./types";
import { buildDownline, type DownlineNode } from "./tree";

type BadgeColor = ComponentProps<typeof Badge>["color"];

export interface DownlineTreeProps<T extends DownlineMember = DownlineMember> {
  /** Flat member list (controlled). Linked into a tree by `edge`. */
  value: T[];
  /**
   * Which pointer links the tree — `"sponsor"` (unilevel, default) or
   * `"placement"` (binary / matrix). The same `value` renders every tree shape.
   */
  edge?: DownlineEdge;
  /** Render only this member's subtree. */
  rootId?: string | null;
  /** Highlight a member (controlled selection). */
  selectedId?: string | null;
  onSelect?: (id: string, member: T) => void;
  /** Map a tier to a react-fancy Badge color. */
  tierColor?: (tier: string | undefined) => BadgeColor;
  /** Replace the default member row content. */
  renderMember?: (member: T, node: DownlineNode<T>) => ReactNode;
  className?: string;
}

/**
 * Genealogy / downline tree. Controlled `value`, stable `data-mlm-node` handles
 * on every member, controlled selection, and JSON-friendly inputs — an agent can
 * read the tree and drive selection without scraping the DOM.
 */
export function DownlineTree<T extends DownlineMember = DownlineMember>({
  value,
  edge = "sponsor",
  rootId,
  selectedId,
  onSelect,
  tierColor,
  renderMember,
  className,
}: DownlineTreeProps<T>) {
  const forest = buildDownline(value, rootId, edge);

  return (
    <div data-fancy-mlm="downline-tree" data-mlm-edge={edge} className={cn("fancy-mlm-tree", className)}>
      <ul className="fancy-mlm-tree__list" role="tree">
        {forest.map((node) => (
          <DownlineNodeView
            key={node.member.id}
            node={node}
            selectedId={selectedId}
            onSelect={onSelect}
            tierColor={tierColor}
            renderMember={renderMember}
          />
        ))}
      </ul>
    </div>
  );
}

function DownlineNodeView<T extends DownlineMember>({
  node,
  selectedId,
  onSelect,
  tierColor,
  renderMember,
}: {
  node: DownlineNode<T>;
  selectedId?: string | null;
  onSelect?: (id: string, member: T) => void;
  tierColor?: (tier: string | undefined) => BadgeColor;
  renderMember?: (member: T, node: DownlineNode<T>) => ReactNode;
}) {
  const [expanded, setExpanded] = useState(true);
  const { member, children } = node;
  const hasChildren = children.length > 0;
  const active = member.active ?? true;

  return (
    <li className="fancy-mlm-tree__item" data-mlm-node={member.id} role="treeitem" aria-expanded={hasChildren ? expanded : undefined}>
      <div
        className={cn(
          "fancy-mlm-tree__row",
          selectedId === member.id && "is-selected",
          !active && "is-inactive",
        )}
      >
        {hasChildren ? (
          <button
            type="button"
            className="fancy-mlm-tree__toggle"
            aria-label={expanded ? "Collapse" : "Expand"}
            aria-expanded={expanded}
            onClick={() => setExpanded((value) => !value)}
          >
            {expanded ? "▾" : "▸"}
          </button>
        ) : (
          <span className="fancy-mlm-tree__toggle fancy-mlm-tree__toggle--leaf" aria-hidden="true" />
        )}

        <button
          type="button"
          className="fancy-mlm-tree__label"
          data-mlm-member={member.id}
          onClick={() => onSelect?.(member.id, member)}
        >
          {renderMember ? (
            renderMember(member, node)
          ) : (
            <>
              <span className="fancy-mlm-tree__name">{member.label ?? member.id}</span>
              {member.tier ? (
                <Badge color={tierColor?.(member.tier)} variant="soft">
                  {member.tier}
                </Badge>
              ) : null}
              {!active ? <span className="fancy-mlm-tree__muted">inactive</span> : null}
            </>
          )}
        </button>
      </div>

      {hasChildren && expanded ? (
        <ul className="fancy-mlm-tree__list" role="group">
          {children.map((child) => (
            <DownlineNodeView
              key={child.member.id}
              node={child}
              selectedId={selectedId}
              onSelect={onSelect}
              tierColor={tierColor}
              renderMember={renderMember}
            />
          ))}
        </ul>
      ) : null}
    </li>
  );
}

/** A network member as the UI consumes it — JSON-friendly, agent-emittable. */
export interface DownlineMember {
  id: string;
  /** Enroller pointer — the edge a unilevel tree draws by. */
  sponsorId?: string | null;
  /** Placement pointer — the edge binary / matrix trees draw by (falls back to `sponsorId`). */
  placementId?: string | null;
  label?: string;
  tier?: string;
  active?: boolean;
  meta?: Record<string, unknown>;
}

/**
 * Which parent pointer links the tree — `"sponsor"` (unilevel, the enroller tree)
 * or `"placement"` (binary / matrix, the placement tree, falling back to
 * `sponsorId`). Mirrors the engine's tree types.
 */
export type DownlineEdge = "sponsor" | "placement";

export type CommissionStatus = "pending" | "paid" | "held" | "reversed";

/** One row of a commission statement — mirrors the engine's RewardComputation. */
export interface CommissionRow {
  id?: string;
  recipientMemberId?: string;
  recipientLabel?: string;
  level: number;
  metric?: string;
  tier?: string;
  amount: number;
  status?: CommissionStatus;
}

import type { DownlineEdge, DownlineMember } from "./types";

export interface DownlineNode<T extends DownlineMember = DownlineMember> {
  member: T;
  depth: number;
  children: DownlineNode<T>[];
}

/** The parent pointer an edge follows — sponsor tree vs placement tree (with fallback). */
function parentOf(member: DownlineMember, edge: DownlineEdge): string | null {
  if (edge === "placement") {
    return member.placementId ?? member.sponsorId ?? null;
  }
  return member.sponsorId ?? null;
}

/**
 * Build a downline forest from a flat member list. By default members are linked
 * by `sponsorId` (unilevel, the enroller tree); pass `edge: "placement"` to link
 * by `placementId` (binary / matrix, the placement tree, falling back to
 * `sponsorId`) — the same list renders every tree shape. When `rootId` is given,
 * returns just that member's subtree. Members whose parent isn't in the list
 * become roots; cyclic references are broken (each member appears at most once).
 */
export function buildDownline<T extends DownlineMember>(
  members: T[],
  rootId?: string | null,
  edge: DownlineEdge = "sponsor",
): DownlineNode<T>[] {
  const byId = new Map<string, T>();
  for (const member of members) {
    byId.set(member.id, member);
  }

  const childrenOf = new Map<string, T[]>();
  for (const member of members) {
    const parentId = parentOf(member, edge);
    if (parentId !== null && byId.has(parentId)) {
      const bucket = childrenOf.get(parentId);
      if (bucket) {
        bucket.push(member);
      } else {
        childrenOf.set(parentId, [member]);
      }
    }
  }

  const seen = new Set<string>();
  const build = (member: T, depth: number): DownlineNode<T> => {
    seen.add(member.id);
    const children = (childrenOf.get(member.id) ?? [])
      .filter((child) => !seen.has(child.id))
      .map((child) => build(child, depth + 1));
    return { member, depth, children };
  };

  if (rootId != null) {
    const root = byId.get(rootId);
    return root ? [build(root, 0)] : [];
  }

  const roots = members.filter((member) => {
    const parentId = parentOf(member, edge);
    return parentId === null || !byId.has(parentId);
  });

  return roots.filter((root) => !seen.has(root.id)).map((root) => build(root, 0));
}

import { createContext, useContext } from "react";
import type { DrawerContextValue } from "./Drawer.types";

export const DrawerContext = createContext<DrawerContextValue | null>(null);

export function useDrawer(): DrawerContextValue {
  const ctx = useContext(DrawerContext);
  if (!ctx) {
    throw new Error("Drawer compound components must be used within <Drawer>");
  }
  return ctx;
}

import { useCallback, useEffect, useMemo, useRef } from "react";
import { cn } from "../lib/utils/cn";
import { Portal } from "../portal";
import { DrawerContext } from "./Drawer.context";
import { DrawerHeader } from "./DrawerHeader";
import { DrawerBody } from "./DrawerBody";
import { DrawerFooter } from "./DrawerFooter";
import { DrawerContainer } from "./DrawerContainer";
import { useFocusTrap } from "../lib/hooks/use-focus-trap";
import { useEscapeKey } from "../lib/hooks/use-escape-key";
import { useAnimation } from "../lib/hooks/use-animation";
import type { DrawerProps, DrawerSide } from "./Drawer.types";

/**
 * `size` addresses the drawer's own axis: width on the horizontal edges,
 * height on the vertical ones. Keeping one scale across both means `size="lg"`
 * does not have to be re-learned when a drawer moves from the side to the
 * bottom.
 */
const WIDTH = {
  sm: "w-64",
  md: "w-80",
  lg: "w-96",
  xl: "w-[32rem]",
  full: "w-full",
} as const;

const HEIGHT = {
  sm: "h-32",
  md: "h-64",
  lg: "h-96",
  xl: "h-[32rem]",
  full: "h-full",
} as const;

const ANCHOR: Record<DrawerSide, string> = {
  left: "inset-y-0 left-0",
  right: "inset-y-0 right-0",
  top: "inset-x-0 top-0",
  bottom: "inset-x-0 bottom-0",
};

const ENTER: Record<DrawerSide, string> = {
  left: "fancy-slide-in-left",
  right: "fancy-slide-in-right",
  top: "fancy-slide-in-top",
  bottom: "fancy-slide-in-bottom",
};

const EXIT: Record<DrawerSide, string> = {
  left: "fancy-slide-out-left",
  right: "fancy-slide-out-right",
  top: "fancy-slide-out-top",
  bottom: "fancy-slide-out-bottom",
};

/** The panel's edge shadow reads as depth away from the anchored edge. */
const EDGE: Record<DrawerSide, string> = {
  left: "border-r",
  right: "border-l",
  top: "border-b",
  bottom: "border-t",
};

function DrawerRoot({
  children,
  open,
  onClose,
  side = "right",
  size = "md",
  attach = "viewport",
  backdrop = true,
  dismissOnBackdrop = true,
  dismissOnEscape = true,
  className,
  ...rest
}: DrawerProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const horizontal = side === "left" || side === "right";
  const isViewport = attach === "viewport";

  const close = useCallback(() => onClose(), [onClose]);
  useEscapeKey(close, open && dismissOnEscape);

  // A container-attached drawer is a panel, not a dialog — trapping focus in it
  // would strand keyboard users inside a Card. Only the viewport form is modal.
  useFocusTrap(panelRef, open && isViewport);

  useEffect(() => {
    if (!open || !isViewport) return;
    const original = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = original;
    };
  }, [open, isViewport]);

  const { mounted, className: animClass, ref: animRef } = useAnimation({
    open,
    enterClass: ENTER[side],
    exitClass: EXIT[side],
  });

  const ctx = useMemo(() => ({ open, close, side }), [open, close, side]);

  if (!mounted) return null;

  const frame = (
    <div
      data-react-fancy-drawer-frame=""
      className={cn(isViewport ? "fixed inset-0 z-50" : "absolute inset-0 z-20", !backdrop && "pointer-events-none")}
    >
      {backdrop ? (
        <div
          data-react-fancy-drawer-backdrop=""
          className={cn(
            "absolute inset-0 bg-black/40 transition-opacity",
            isViewport && "backdrop-blur-sm",
            open ? "opacity-100" : "opacity-0",
          )}
          onClick={dismissOnBackdrop ? close : undefined}
          aria-hidden="true"
        />
      ) : null}

      <div
        ref={(node) => {
          panelRef.current = node;
          (animRef as React.MutableRefObject<HTMLElement | null>).current = node;
        }}
        data-react-fancy-drawer=""
        data-side={side}
        role="dialog"
        aria-modal={isViewport || undefined}
        {...rest}
        className={cn(
          "pointer-events-auto absolute flex flex-col border-zinc-200 bg-white shadow-xl dark:border-zinc-700 dark:bg-zinc-900",
          ANCHOR[side],
          EDGE[side],
          horizontal ? WIDTH[size] : HEIGHT[size],
          // Cross-axis fills the anchor; the main axis is capped so a viewport
          // drawer can never grow past the screen on a small device.
          horizontal ? "h-full" : "w-full",
          isViewport && (horizontal ? "max-w-[90vw]" : "max-h-[90vh]"),
          !isViewport && (horizontal ? "max-w-full" : "max-h-full"),
          animClass,
          className,
        )}
      >
        {children}
      </div>
    </div>
  );

  return (
    <DrawerContext.Provider value={ctx}>
      {isViewport ? <Portal>{frame}</Portal> : frame}
    </DrawerContext.Provider>
  );
}

