import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useEffect, type RefObject } from "react";

const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled])",
  "textarea:not([disabled])",
  "select:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(", ");

export function useFocusTrap(
  ref: RefObject<HTMLElement | null>,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const el = ref.current;
    if (!el) return;

    const previouslyFocused = document.activeElement as HTMLElement | null;

    const focusables = () =>
      Array.from(el.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR));

    // Focus first focusable element
    const first = focusables()[0];
    first?.focus();

    const listener = (event: KeyboardEvent) => {
      if (event.key !== "Tab") return;

      const items = focusables();
      if (items.length === 0) return;

      const firstItem = items[0];
      const lastItem = items[items.length - 1];

      if (event.shiftKey) {
        if (document.activeElement === firstItem) {
          event.preventDefault();
          lastItem.focus();
        }
      } else {
        if (document.activeElement === lastItem) {
          event.preventDefault();
          firstItem.focus();
        }
      }
    };

    el.addEventListener("keydown", listener);

    return () => {
      el.removeEventListener("keydown", listener);
      previouslyFocused?.focus();
    };
  }, [ref, enabled]);
}

import { useEffect } from "react";

export function useEscapeKey(
  handler: () => void,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        handler();
      }
    };

    document.addEventListener("keydown", listener);
    return () => document.removeEventListener("keydown", listener);
  }, [handler, enabled]);
}

import { useCallback, useEffect, useRef, useState } from "react";

interface UseAnimationOptions {
  open: boolean;
  enterClass: string;
  exitClass: string;
}

interface UseAnimationReturn {
  mounted: boolean;
  className: string;
  ref: React.RefObject<HTMLElement | null>;
}

export function useAnimation({
  open,
  enterClass,
  exitClass,
}: UseAnimationOptions): UseAnimationReturn {
  const [mounted, setMounted] = useState(open);
  const [animClass, setAnimClass] = useState(open ? enterClass : "");
  const ref = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (open) {
      setMounted(true);
      setAnimClass(enterClass);
    } else if (mounted) {
      setAnimClass(exitClass);
    }
  }, [open, enterClass, exitClass, mounted]);

  const handleAnimationEnd = useCallback(() => {
    if (!open) {
      setMounted(false);
      setAnimClass("");
    }
  }, [open]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    el.addEventListener("animationend", handleAnimationEnd);
    return () => el.removeEventListener("animationend", handleAnimationEnd);
  }, [handleAnimationEnd, mounted]);

  return { mounted, className: animClass, ref };
}

import { type CSSProperties, useCallback, useEffect, useRef, useState } from "react";
import type { Point, Stroke } from "../lib/types";

export type DrawingProps = {
  strokes: Stroke[];
  onStrokeStart?: (stroke: Stroke) => void;
  onStrokePoint?: (id: string, point: Point) => void;
  onStrokeEnd?: (stroke: Stroke) => void;
  color?: string;
  size?: number;
  /** SVG canvas width. Optional — auto-measures the rendered element when omitted. */
  width?: number;
  /** SVG canvas height. Optional — auto-measures the rendered element when omitted. */
  height?: number;
  enabled?: boolean;
  className?: string;
  style?: CSSProperties;
};

/**
 * Drawing — freeform pen layer. Controlled: parent owns `strokes`.
 *
 * Coordinates are in screen pixels relative to the rendered SVG. By default
 * the component auto-measures itself with a ResizeObserver so width/height
 * always match the visible area, keeping user coords 1:1 with click position.
 *
 * Streams new strokes via the callbacks so apps can broadcast them as they
 * form (live multi-user pen view).
 */
export function Drawing({
  strokes,
  onStrokeStart,
  onStrokePoint,
  onStrokeEnd,
  color = "#111827",
  size = 2,
  width,
  height,
  enabled = true,
  className,
  style,
}: DrawingProps) {
  const [active, setActive] = useState<Stroke | null>(null);
  const [measured, setMeasured] = useState({ w: width ?? 0, h: height ?? 0 });
  const ref = useRef<SVGSVGElement>(null);

  // Auto-measure rendered size so coords map 1:1 to clicks regardless of
  // CSS sizing. Skipped when caller supplied explicit width AND height.
  useEffect(() => {
    if (width != null && height != null) return;
    const el = ref.current;
    if (!el) return;
    const update = () => {
      const r = el.getBoundingClientRect();
      setMeasured({ w: Math.max(1, Math.round(r.width)), h: Math.max(1, Math.round(r.height)) });
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, [width, height]);

  const w = width ?? measured.w;
  const h = height ?? measured.h;

  const localPoint = useCallback((e: React.PointerEvent | PointerEvent): Point => {
    const rect = ref.current?.getBoundingClientRect();
    return { x: e.clientX - (rect?.left ?? 0), y: e.clientY - (rect?.top ?? 0) };
  }, []);

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (!enabled || e.button !== 0) return;
      e.preventDefault();
      const id = `s_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
      const stroke: Stroke = { id, points: [localPoint(e)], color, size };
      setActive(stroke);
      onStrokeStart?.(stroke);
      const target = e.currentTarget;
      target.setPointerCapture(e.pointerId);
      const move = (ev: PointerEvent) => {
        const p = localPoint(ev);
        setActive((prev) => (prev ? { ...prev, points: [...prev.points, p] } : prev));
        onStrokePoint?.(id, p);
      };
      const up = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        setActive((prev) => {
          if (prev) onStrokeEnd?.(prev);
          return null;
        });
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
    },
    [enabled, color, size, localPoint, onStrokeStart, onStrokePoint, onStrokeEnd],
  );

  const all = active ? [...strokes, active] : strokes;

  return (
    <svg
      ref={ref}
      className={className}
      style={{
        pointerEvents: enabled ? "auto" : "none",
        // FILL THE CONTAINER BY CSS when no explicit size was given, and let the
        // ResizeObserver read the result. Without this the component could not
        // bootstrap: `measured` starts at 0, so no width attribute was rendered,
        // so the <svg> fell back to the browser default of 300x150, so the
        // effect measured 300x150 -- its own fallback -- and pinned itself
        // there. It was measuring itself before anything had given it a size.
        //
        // Before `...style`, so a caller sizing it themselves still wins.
        ...(width == null && height == null ? { width: "100%", height: "100%" } : null),
        ...style,
      }}
      // Only as ATTRIBUTES when the caller asked for them. Deriving these from
      // the measurement is what froze the element at its own default.
      width={width ?? undefined}
      height={height ?? undefined}
      onPointerDown={onPointerDown}
    >
      {/* Transparent hit-target so empty SVG area catches pointer events. */}
      {enabled && w > 0 && h > 0 && (
        <rect x={0} y={0} width={w} height={h} fill="transparent" />
      )}
      {all.map((s) => (
        <path
          key={s.id}
          d={toPath(s.points)}
          fill="none"
          stroke={s.color ?? "#111827"}
          strokeWidth={s.size ?? 2}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      ))}
    </svg>
  );
}

function toPath(points: Point[]): string {
  if (!points.length) return "";
  return points.map((p, i) => `${i === 0 ? "M" : "L"}${p.x},${p.y}`).join(" ");
}

