  EChartComponentProps,
  SeriesComponentProps,
  ChartDivProps,
} from "../lib/types";

const DEFAULT_STYLE: React.CSSProperties = { width: "100%", height: 400 };

/** Base EChart component — accepts any ECharts option. */
const EChartBase = forwardRef<HTMLDivElement, EChartComponentProps>(
  (
    {
      option,
      theme,
      renderer,
      notMerge,
      lazyUpdate,
      showLoading,
      loadingOption,
      onEvents,
      autoResize = true,
      style,
      className,
      ...rest
    },
    _ref
  ) => {
    const { chartRef } = useECharts({
      option,
      theme,
      renderer,
      notMerge,
      lazyUpdate,
      showLoading,
      loadingOption,
      onEvents,
      autoResize,
    });

    return (
      <div
        ref={chartRef}
        style={{ ...DEFAULT_STYLE, ...style }}
        className={className}
        {...rest}
      />
    );
  }
);

EChartBase.displayName = "EChart";

// --- Helper to create typed series sub-components ---

function createSeriesComponent(
  seriesType: string,
  displayName: string
): React.FC<SeriesComponentProps & ChartDivProps> {
  const Component: React.FC<SeriesComponentProps & ChartDivProps> = ({
    data,
    title,
    xAxis,
    yAxis,
    tooltip = true,
    legend = false,
    grid,
    seriesOptions = {},
    option: extraOption = {},
    style,
    className,
    ...rest
  }) => {
    const option = useMemo((): EChartsOption => {
      const base: EChartsOption = {};

      if (title) {
        base.title = { text: title };
      }

      if (tooltip === true) {
        base.tooltip = { trigger: "axis" };
      } else if (tooltip && typeof tooltip === "object") {
        base.tooltip = tooltip;
      }

      if (legend === true) {
        base.legend = {};
      } else if (legend && typeof legend === "object") {
        base.legend = legend;
      }

      if (grid) {
        base.grid = grid;
      }

      // Handle axis-based charts
      const axisCharts = [
        "line",
        "bar",
        "scatter",
        "candlestick",
        "boxplot",
        "heatmap",
        "effectScatter",
        "pictorialBar",
      ];
      if (axisCharts.includes(seriesType)) {
        base.xAxis = xAxis ?? { type: "category" };
        base.yAxis = yAxis ?? { type: "value" };
      }

      // Handle data format
      if (Array.isArray(data)) {
        base.series = [{ type: seriesType, data, ...seriesOptions }] as any;
      } else if (data && typeof data === "object" && "series" in data) {
        // Multi-series: { categories: [...], series: [{ name, data }, ...] }
        const multiData = data as {
          categories?: string[];
          series: Array<{ name?: string; data: any[]; [k: string]: any }>;
        };
        if (multiData.categories && axisCharts.includes(seriesType)) {
          base.xAxis = xAxis ?? {
            type: "category",
            data: multiData.categories,
          };
        }
        base.series = multiData.series.map((s) => ({
          type: seriesType,
          ...seriesOptions,
          ...s,
        })) as any;
      } else {
        base.series = [{ type: seriesType, data, ...seriesOptions }] as any;
      }

      return { ...base, ...extraOption };
    }, [
      data,
      title,
      xAxis,
      yAxis,
      tooltip,
      legend,
      grid,
      seriesOptions,
      extraOption,
    ]);

    return (
      <EChartBase
        option={option}
        style={style}
        className={className}
        {...rest}
      />
    );
  };

  Component.displayName = displayName;
  return Component;
}

// --- Compound component with all chart type sub-components ---

export const EChart = Object.assign(EChartBase, {
  Line: createSeriesComponent("line", "EChart.Line"),
  Bar: createSeriesComponent("bar", "EChart.Bar"),
  Pie: createSeriesComponent("pie", "EChart.Pie"),
  Scatter: createSeriesComponent("scatter", "EChart.Scatter"),
  Radar: createSeriesComponent("radar", "EChart.Radar"),
  Heatmap: createSeriesComponent("heatmap", "EChart.Heatmap"),
  Gauge: createSeriesComponent("gauge", "EChart.Gauge"),
  Funnel: createSeriesComponent("funnel", "EChart.Funnel"),
  Treemap: createSeriesComponent("treemap", "EChart.Treemap"),
  Sunburst: createSeriesComponent("sunburst", "EChart.Sunburst"),
  Sankey: createSeriesComponent("sankey", "EChart.Sankey"),
  Graph: createSeriesComponent("graph", "EChart.Graph"),
  Candlestick: createSeriesComponent("candlestick", "EChart.Candlestick"),
  Boxplot: createSeriesComponent("boxplot", "EChart.Boxplot"),
  Parallel: createSeriesComponent("parallel", "EChart.Parallel"),
  ThemeRiver: createSeriesComponent("themeRiver", "EChart.ThemeRiver"),
  Map: createSeriesComponent("map", "EChart.Map"),
  Custom: createSeriesComponent("custom", "EChart.Custom"),
  EffectScatter: createSeriesComponent(
    "effectScatter",
    "EChart.EffectScatter"
  ),
  PictorialBar: createSeriesComponent("pictorialBar", "EChart.PictorialBar"),
});

import { useEffect, useRef, useState, useSyncExternalStore, type RefObject } from "react";
import { init, getInstanceByDom, type EChartsType } from "echarts/core";
import type { EChartsOption } from "echarts";

type ECharts = EChartsType;
import { useResizeObserver } from "./use-resize-observer";

export interface UseEChartsOptions {
  option: EChartsOption;
  theme?: string | object;
  renderer?: "canvas" | "svg";
  notMerge?: boolean;
  lazyUpdate?: boolean;
  showLoading?: boolean;
  loadingOption?: object;
  onEvents?: Record<string, (params: any) => void>;
  autoResize?: boolean;
}

export interface UseEChartsReturn {
  chartRef: RefObject<HTMLDivElement | null>;
  instance: ECharts | null;
}

/** Detect system dark mode preference reactively. */
function useDarkMode(): boolean {
  return useSyncExternalStore(
    (callback) => {
      const mq = window.matchMedia("(prefers-color-scheme: dark)");
      mq.addEventListener("change", callback);
      return () => mq.removeEventListener("change", callback);
    },
    () => window.matchMedia("(prefers-color-scheme: dark)").matches,
    () => false,
  );
}

/** Collect the chart/component type names an option references, so a render
 *  failure can name the likely-unregistered culprits. */
function collectOptionTypes(option: EChartsOption): string[] {
  const types = new Set<string>();
  const o = option as Record<string, unknown>;
  const series = o.series;
  const arr = Array.isArray(series) ? series : series ? [series] : [];
  for (const s of arr) {
    const t = (s as { type?: unknown })?.type;
    if (typeof t === "string") types.add(`series:${t}`);
  }
  for (const key of [
    "radar", "polar", "geo", "parallel", "calendar", "singleAxis",
    "timeline", "visualMap", "dataZoom", "toolbox", "brush", "graphic", "dataset",
  ]) {
    if (o[key] != null) types.add(key);
  }
  return [...types];
}

export function useECharts(options: UseEChartsOptions): UseEChartsReturn {
  const {
    option,
    theme,
    renderer = "canvas",
    notMerge = false,
    lazyUpdate = false,
    showLoading = false,
    loadingOption,
    onEvents,
    autoResize = true,
  } = options;

  const isDark = useDarkMode();
  // Auto-detect theme: use explicit theme if provided, otherwise "dark" or undefined
  const autoDark = theme === undefined && isDark;
  const resolvedTheme = theme !== undefined ? theme : isDark ? "dark" : undefined;

  const chartRef = useRef<HTMLDivElement | null>(null);
  const instanceRef = useRef<ECharts | null>(null);
  const [instance, setInstance] = useState<ECharts | null>(null);

  // Init/dispose — re-init when theme changes (including dark mode toggle)
  useEffect(() => {
    if (!chartRef.current) return;

    // Dispose any existing instance (handles StrictMode double-mount)
    const existing = getInstanceByDom(chartRef.current);
    if (existing) {
      existing.dispose();
    }

    const chart = init(chartRef.current, resolvedTheme, { renderer });
    instanceRef.current = chart;
    setInstance(chart);

    return () => {
      chart.dispose();
      instanceRef.current = null;
      setInstance(null);
    };
  }, [resolvedTheme, renderer]);

  // Set option
  useEffect(() => {
    const chart = instanceRef.current;
    if (!chart || !option) return;
    // When using auto-detected dark theme, force transparent background
    // so charts blend with the page's own dark background
    const finalOption = autoDark
      ? { backgroundColor: "transparent", ...option }
      : option;
    try {
      chart.setOption(finalOption, { notMerge, lazyUpdate });
    } catch (err) {
      // echarts throws a cryptic minified error (e.g. "_u[o] is not a
      // constructor") when an option uses a chart/component type that was
      // never registered. Re-throw something actionable that names the likely
      // culprits and points at registration — which is module-scoped per
      // bundle, so every entry that renders charts must call registerAll().
      const types = collectOptionTypes(finalOption);
      throw new Error(
        `[fancy-echarts] Failed to render chart — a chart/component type is likely not registered. ` +
          `This option uses: ${types.length ? types.join(", ") : "(none detected)"}. ` +
          `Call registerAll() once at app startup, or registerCharts(...)/registerComponents(...) for the types you use. ` +
          `Registration is module-scoped per bundle entry — every entry that renders charts must register. ` +
          `Original error: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }, [option, notMerge, lazyUpdate, autoDark]);

  // Loading state
  useEffect(() => {
    const chart = instanceRef.current;
    if (!chart) return;
    if (showLoading) {
      chart.showLoading("default", loadingOption);
    } else {
      chart.hideLoading();
    }
  }, [showLoading, loadingOption]);

  // Event binding
  useEffect(() => {
    const chart = instanceRef.current;
    if (!chart || !onEvents) return;

    const entries = Object.entries(onEvents);
    for (const [event, handler] of entries) {
      chart.on(event, handler);
    }

    return () => {
      for (const [event, handler] of entries) {
        chart.off(event, handler);
      }
    };
  }, [onEvents]);

  // Auto-resize
  useResizeObserver(chartRef, () => {
    if (autoResize && instanceRef.current) {
      instanceRef.current.resize();
    }
  });

  return { chartRef, instance };
}

import type {
  EChartsOption,
  SetOptionOpts,
  ECharts as EChartsInstance,
} from "echarts";

export type { EChartsOption, SetOptionOpts, EChartsInstance };

export interface EChartBaseProps {
  option: EChartsOption;
  theme?: string | object;
  renderer?: "canvas" | "svg";
  notMerge?: boolean;
  lazyUpdate?: boolean;
  showLoading?: boolean;
  loadingOption?: object;
  onEvents?: Record<string, (params: any) => void>;
  autoResize?: boolean;
}

export interface SeriesComponentProps<T = any>
  extends Omit<EChartBaseProps, "option"> {
  data: T;
  title?: string;
  xAxis?: EChartsOption["xAxis"];
  yAxis?: EChartsOption["yAxis"];
  tooltip?: boolean | EChartsOption["tooltip"];
  legend?: boolean | EChartsOption["legend"];
  grid?: EChartsOption["grid"];
  seriesOptions?: Record<string, any>;
  option?: Partial<EChartsOption>;
}

export interface ChartDivProps {
  style?: React.CSSProperties;
  className?: string;
}

export type EChartComponentProps = EChartBaseProps &
  ChartDivProps &
  React.HTMLAttributes<HTMLDivElement>;

import { useEffect, useRef, type RefObject } from "react";

export function useResizeObserver(
  ref: RefObject<HTMLElement | null>,
  callback: () => void
): void {
  const callbackRef = useRef(callback);
  callbackRef.current = callback;

  useEffect(() => {
    const element = ref.current;
    if (!element) return;

    const observer = new ResizeObserver(() => {
      callbackRef.current();
    });

    observer.observe(element);

    return () => {
      observer.disconnect();
    };
  }, [ref]);
}

import React, { forwardRef, useEffect, useMemo, useState } from "react";
import type { EChartsOption } from "echarts";
import { useECharts } from "../lib/hooks/use-echarts";
import type {
  EChartComponentProps,
  SeriesComponentProps,
  ChartDivProps,
} from "../lib/types";

const DEFAULT_STYLE: React.CSSProperties = { width: "100%", height: 500 };

let glLoaded = false;
let glPromise: Promise<void> | null = null;

function loadEChartsGL(): Promise<void> {
  if (glLoaded) return Promise.resolve();
  if (!glPromise) {
    glPromise = import("echarts-gl")
      .then(() => {
        glLoaded = true;
      })
      .catch((err: unknown) => {
        console.warn("Failed to load echarts-gl for 3D charts:", err);
      });
  }
  return glPromise;
}

/** Wrapper that delays mount until echarts-gl is loaded */
function WithGL({ children, style, className }: { children: React.ReactNode; style?: React.CSSProperties; className?: string }) {
  const [ready, setReady] = useState(glLoaded);

  useEffect(() => {
    if (glLoaded) {
      setReady(true);
      return;
    }
    loadEChartsGL().then(() => setReady(true));
  }, []);

  if (!ready) {
    return (
      <div style={{ ...DEFAULT_STYLE, ...style, display: "flex", alignItems: "center", justifyContent: "center" }} className={className}>
        <span style={{ color: "#9ca3af", fontSize: 14 }}>Loading 3D engine...</span>
      </div>
    );
  }

  return <>{children}</>;
}

