import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import { useEffect, type RefObject } from "react";

export function useOutsideClick(
  ref: RefObject<HTMLElement | null>,
  handler: (event: MouseEvent | TouchEvent) => void,
  enabled: boolean = true,
  ignoreRef?: RefObject<HTMLElement | null>,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: MouseEvent | TouchEvent) => {
      const el = ref.current;
      if (!el || el.contains(event.target as Node)) return;
      // Ignore clicks on the trigger/anchor element — the trigger's
      // own onClick handler manages toggling.
      if (ignoreRef?.current?.contains(event.target as Node)) return;
      handler(event);
    };

    document.addEventListener("mousedown", listener);
    document.addEventListener("touchstart", listener);

    return () => {
      document.removeEventListener("mousedown", listener);
      document.removeEventListener("touchstart", listener);
    };
  }, [ref, handler, enabled, ignoreRef]);
}

import { useEffect } from "react";

export function useEscapeKey(
  handler: () => void,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        handler();
      }
    };

    document.addEventListener("keydown", listener);
    return () => document.removeEventListener("keydown", listener);
  }, [handler, enabled]);
}

import { useEffect, type RefObject } from "react";

const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled])",
  "textarea:not([disabled])",
  "select:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(", ");

export function useFocusTrap(
  ref: RefObject<HTMLElement | null>,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const el = ref.current;
    if (!el) return;

    const previouslyFocused = document.activeElement as HTMLElement | null;

    const focusables = () =>
      Array.from(el.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR));

    // Focus first focusable element
    const first = focusables()[0];
    first?.focus();

    const listener = (event: KeyboardEvent) => {
      if (event.key !== "Tab") return;

      const items = focusables();
      if (items.length === 0) return;

      const firstItem = items[0];
      const lastItem = items[items.length - 1];

      if (event.shiftKey) {
        if (document.activeElement === firstItem) {
          event.preventDefault();
          lastItem.focus();
        }
      } else {
        if (document.activeElement === lastItem) {
          event.preventDefault();
          firstItem.focus();
        }
      }
    };

    el.addEventListener("keydown", listener);

    return () => {
      el.removeEventListener("keydown", listener);
      previouslyFocused?.focus();
    };
  }, [ref, enabled]);
}

import { useCallback, useEffect, useState, type RefObject } from "react";
import type { Placement } from "../utils/types";

interface FloatingPosition {
  x: number;
  y: number;
  placement: Placement;
}

interface UseFloatingPositionOptions {
  placement?: Placement;
  offset?: number;
  enabled?: boolean;
}

function getPosition(
  anchor: DOMRect,
  floating: DOMRect,
  placement: Placement,
  offset: number,
): FloatingPosition {
  let x = 0;
  let y = 0;
  const base = placement.split("-")[0] as "top" | "bottom" | "left" | "right";
  const align = placement.split("-")[1] as "start" | "end" | undefined;

  switch (base) {
    case "top":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.top - floating.height - offset;
      break;
    case "bottom":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.bottom + offset;
      break;
    case "left":
      x = anchor.left - floating.width - offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
    case "right":
      x = anchor.right + offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
  }

  if (base === "top" || base === "bottom") {
    if (align === "start") x = anchor.left;
    else if (align === "end") x = anchor.right - floating.width;
  }

  if (base === "left" || base === "right") {
    if (align === "start") y = anchor.top;
    else if (align === "end") y = anchor.bottom - floating.height;
  }

  // Viewport clamping
  let finalPlacement = placement;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  if (base === "bottom" && y + floating.height > vh) {
    y = anchor.top - floating.height - offset;
    finalPlacement = placement.replace("bottom", "top") as Placement;
  } else if (base === "top" && y < 0) {
    y = anchor.bottom + offset;
    finalPlacement = placement.replace("top", "bottom") as Placement;
  }

  x = Math.max(4, Math.min(x, vw - floating.width - 4));
  y = Math.max(4, Math.min(y, vh - floating.height - 4));

  return { x, y, placement: finalPlacement };
}

export function useFloatingPosition(
  anchorRef: RefObject<HTMLElement | null>,
  floatingRef: RefObject<HTMLElement | null>,
  options: UseFloatingPositionOptions = {},
): FloatingPosition {
  const { placement = "bottom", offset = 8, enabled = true } = options;
  const [position, setPosition] = useState<FloatingPosition>({
    x: -9999,
    y: -9999,
    placement,
  });

  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const floating = floatingRef.current;
    if (!anchor || !floating) return;

    const anchorRect = anchor.getBoundingClientRect();
    const floatingRect = floating.getBoundingClientRect();
    const next = getPosition(anchorRect, floatingRect, placement, offset);
    // Bail out when nothing changed so this can run after every commit
    // (below) without causing an infinite render loop.
    setPosition((prev) =>
      prev.x === next.x && prev.y === next.y && prev.placement === next.placement
        ? prev
        : next,
    );
  }, [anchorRef, floatingRef, placement, offset]);

  // Re-measure after every commit while open.
  //
  // The floating element mounts a frame or two AFTER `enabled` flips — its
  // render is gated behind a state flip (e.g. useAnimation's `mounted`), so at
  // the moment `enabled` turns true the floating ref is still null and a single
  // measurement no-ops, leaving the popover parked at its off-screen sentinel.
  //
  // A passive effect with no deps runs after *every* commit — including the one
  // that finally mounts the floating element — and, crucially, keeps running in
  // hidden/background tabs where `requestAnimationFrame` is paused. The bail-out
  // in `update` makes the steady-state calls free, so this both fixes the
  // late-mount race and survives tab-visibility throttling.
  useEffect(() => {
    if (enabled) update();
  });

  // …but the per-commit effect ISN'T enough when the floating element mounts
  // through a <Portal> whose own mount gate (SSR-safe; renders nothing until its
  // useEffect runs) attaches the node WITHOUT re-rendering this hook's component.
  // Then no commit happens here, the measurement never runs, and the popover
  // stays parked at its off-screen sentinel until an unrelated scroll/resize
  // fires `update()` — the "menu only appears after I scroll" bug. Poll with rAF
  // until the node is actually in the DOM, measure it, then keep it observed for
  // size changes (async content / lazily-loaded icons).
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    let ro: ResizeObserver | null = null;
    const tick = () => {
      const el = floatingRef.current;
      if (el) {
        update();
        if (typeof ResizeObserver !== "undefined") {
          ro = new ResizeObserver(() => update());
          ro.observe(el);
        }
      } else {
        raf = requestAnimationFrame(tick);
      }
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      ro?.disconnect();
    };
  }, [enabled, update, floatingRef]);

  // Park off-screen when closed so the next open re-measures from scratch.
  useEffect(() => {
    if (!enabled) {
      setPosition((prev) =>
        prev.x === -9999 ? prev : { x: -9999, y: -9999, placement },
      );
    }
  }, [enabled, placement]);

  // Reposition on scroll/resize while open.
  useEffect(() => {
    if (!enabled) return;

    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);

    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [update, enabled]);

  return position;
}

import { useCallback, useEffect, useRef, useState } from "react";

interface UseAnimationOptions {
  open: boolean;
  enterClass: string;
  exitClass: string;
}

interface UseAnimationReturn {
  mounted: boolean;
  className: string;
  ref: React.RefObject<HTMLElement | null>;
}

export function useAnimation({
  open,
  enterClass,
  exitClass,
}: UseAnimationOptions): UseAnimationReturn {
  const [mounted, setMounted] = useState(open);
  const [animClass, setAnimClass] = useState(open ? enterClass : "");
  const ref = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (open) {
      setMounted(true);
      setAnimClass(enterClass);
    } else if (mounted) {
      setAnimClass(exitClass);
    }
  }, [open, enterClass, exitClass, mounted]);

  const handleAnimationEnd = useCallback(() => {
    if (!open) {
      setMounted(false);
      setAnimClass("");
    }
  }, [open]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    el.addEventListener("animationend", handleAnimationEnd);
    return () => el.removeEventListener("animationend", handleAnimationEnd);
  }, [handleAnimationEnd, mounted]);

  return { mounted, className: animClass, ref };
}

import { useId as useReactId } from "react";

export function useId(prefix?: string): string {
  const id = useReactId();
  return prefix ? `${prefix}-${id}` : id;
}

import { useCallback, useEffect, useRef } from "react";

export interface ViewportState {
  panX: number;
  panY: number;
  zoom: number;
}

interface UsePanZoomOptions {
  viewport: ViewportState;
  setViewport: (vp: ViewportState | ((prev: ViewportState) => ViewportState)) => void;
  minZoom: number;
  maxZoom: number;
  pannable: boolean;
  zoomable: boolean;
  containerRef: React.RefObject<HTMLElement | null>;
}

interface UsePanZoomReturn {
  containerProps: {
    onPointerDown: (e: React.PointerEvent) => void;
    onPointerMove: (e: React.PointerEvent) => void;
    onPointerUp: (e: React.PointerEvent) => void;
  };
  isPanning: boolean;
}

export function usePanZoom({
  viewport,
  setViewport,
  minZoom,
  maxZoom,
  pannable,
  zoomable,
  containerRef,
}: UsePanZoomOptions): UsePanZoomReturn {
  const isPanningRef = useRef(false);
  const startRef = useRef({ x: 0, y: 0, panX: 0, panY: 0 });

  // Store latest values in refs so the native wheel listener always sees current state
  const viewportRef = useRef(viewport);
  viewportRef.current = viewport;
  const setViewportRef = useRef(setViewport);
  setViewportRef.current = setViewport;
  const zoomableRef = useRef(zoomable);
  zoomableRef.current = zoomable;
  const minZoomRef = useRef(minZoom);
  minZoomRef.current = minZoom;
  const maxZoomRef = useRef(maxZoom);
  maxZoomRef.current = maxZoom;

  // Attach a non-passive wheel listener so preventDefault() actually stops page scroll
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    function handleWheel(e: WheelEvent) {
      if (!zoomableRef.current) return;
      // Require Ctrl+wheel (or pinch gesture) to zoom — don't hijack normal page scroll
      if (!e.ctrlKey && !e.metaKey) return;
      e.preventDefault();

      const rect = container!.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      setViewportRef.current((prev) => {
        const factor = 1 - e.deltaY * 0.001;
        const newZoom = Math.min(maxZoomRef.current, Math.max(minZoomRef.current, prev.zoom * factor));
        const ratio = newZoom / prev.zoom;

        return {
          zoom: newZoom,
          panX: mouseX - (mouseX - prev.panX) * ratio,
          panY: mouseY - (mouseY - prev.panY) * ratio,
        };
      });
    }

    container.addEventListener("wheel", handleWheel, { passive: false });
    return () => {
      container.removeEventListener("wheel", handleWheel);
    };
  }, [containerRef]);

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (!pannable) return;
      // Only pan on primary button and when clicking the background
      if (e.button !== 0) return;
      const target = e.target as HTMLElement;
      if (target !== containerRef.current && !target.hasAttribute("data-canvas-bg")) return;

      isPanningRef.current = true;
      startRef.current = { x: e.clientX, y: e.clientY, panX: viewport.panX, panY: viewport.panY };
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      e.preventDefault();
    },
    [pannable, viewport.panX, viewport.panY, containerRef],
  );

  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isPanningRef.current) return;
      const dx = e.clientX - startRef.current.x;
      const dy = e.clientY - startRef.current.y;
      setViewport((prev) => ({
        ...prev,
        panX: startRef.current.panX + dx,
        panY: startRef.current.panY + dy,
      }));
    },
    [setViewport],
  );

  const onPointerUp = useCallback(() => {
    isPanningRef.current = false;
  }, []);

  return {
    containerProps: { onPointerDown, onPointerMove, onPointerUp },
    isPanning: isPanningRef.current,
  };
}

import { useCallback, useRef, useState } from "react";

export interface NodeRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

interface UseNodeRegistryReturn {
  registerNode: (id: string, rect: NodeRect) => void;
  unregisterNode: (id: string) => void;
  nodeRects: Map<string, NodeRect>;
  version: number;
}

export function useNodeRegistry(): UseNodeRegistryReturn {
  const rectsRef = useRef(new Map<string, NodeRect>());
  const [version, setVersion] = useState(0);

  const registerNode = useCallback((id: string, rect: NodeRect) => {
    rectsRef.current.set(id, rect);
    setVersion((v) => v + 1);
  }, []);

  const unregisterNode = useCallback((id: string) => {
    rectsRef.current.delete(id);
    setVersion((v) => v + 1);
  }, []);

  return { registerNode, unregisterNode, nodeRects: rectsRef.current, version };
}

import { useCallback, useEffect, useState } from "react";
import {
    getThemePreference,
    resolveTheme,
    setThemePreference,
    subscribeTheme,
    type ResolvedTheme,
    type ThemePreference,
} from "../theme";

export type UseThemeResult = {
    /** What the user asked for, including `"system"`. */
    preference: ThemePreference;
    /** What is actually on screen. */
    resolved: ResolvedTheme;
    setPreference: (preference: ThemePreference) => void;
};

/**
 * Read and set the theme from a component, re-rendering when it changes —
 * including when the OS theme changes underneath a `"system"` preference.
 *
 * The initial state is deliberately `system` / `light` rather than the real
 * theme: the server has neither storage nor an OS preference, so reading the
 * truth during render is exactly the hydration mismatch this project has
 * already chased down more than once. The effect syncs immediately on mount.
 */
export function useTheme(): UseThemeResult {
    const [state, setState] = useState<{ preference: ThemePreference; resolved: ResolvedTheme }>({
        preference: "system",
        resolved: "light",
    });

    useEffect(() => {
        const sync = (): void => {
            setState({ preference: getThemePreference(), resolved: resolveTheme() });
        };
        sync();
        return subscribeTheme(sync);
    }, []);

    const setPreference = useCallback((preference: ThemePreference): void => {
        setThemePreference(preference);
    }, []);

    return { ...state, setPreference };
}

/**
 * Light / dark / **system** theming.
 *
 * `styles.css` in this package defines the dark contract — it redefines the
 * whole `--color-secondary-*` scale under `:where(.dark)` so that "900" always
 * means strongest foreground and "50" always means faintest surface. This module
 * is the other half of that contract: the thing that decides when `.dark` is on.
 *
 * It lives here rather than in each app because every consumer was hand-rolling
 * it, and every hand-rolled copy had the same two holes:
 *
 *  - **No live listener.** The OS preference was read once at boot, so changing
 *    the system theme with the page open did nothing. That is a default, not a
 *    "system" mode.
 *  - **No way back.** Choosing light or dark wrote to storage forever, so
 *    "follow my system" was unreachable after a single click.
 *
 * Both are fixed by treating **"system" as the absence of a stored choice**
 * rather than as a third stored value.
 *
 * Every export is safe to call during SSR, where it is a no-op that resolves to
 * `"light"`. Pair it with `useTheme`, which deliberately renders `system/light`
 * on the server and syncs in an effect — this project has paid for hydration
 * mismatches caused by reading the real theme during render.
 */

export type ThemePreference = "light" | "dark" | "system";
export type ResolvedTheme = "light" | "dark";

/**
 * Deliberately the key the showcase already used, so adopting this module keeps
 * a returning visitor's saved choice instead of silently resetting it.
 */
export const THEME_STORAGE_KEY = "fancy-ui.theme";

const DARK_QUERY = "(prefers-color-scheme: dark)";

type ThemeListener = (resolved: ResolvedTheme, preference: ThemePreference) => void;

const listeners = new Set<ThemeListener>();
let storageKey = THEME_STORAGE_KEY;
let stopWatchingSystem: (() => void) | null = null;

function canUseDom(): boolean {
    return typeof window !== "undefined" && typeof document !== "undefined";
}

/** The stored choice, or `"system"` when there isn't one. */
export function getThemePreference(): ThemePreference {
    if (!canUseDom()) return "system";
    try {
        const saved = window.localStorage.getItem(storageKey);
        return saved === "light" || saved === "dark" ? saved : "system";
    } catch {
        // Private browsing and blocked storage both throw here. A theme is not
        // worth taking the page down over.
        return "system";
    }
}

function systemTheme(): ResolvedTheme {
    if (!canUseDom() || typeof window.matchMedia !== "function") return "light";
    return window.matchMedia(DARK_QUERY).matches ? "dark" : "light";
}

/** What is actually on screen, as opposed to what the user asked for. */
export function resolveTheme(preference: ThemePreference = getThemePreference()): ResolvedTheme {
    return preference === "system" ? systemTheme() : preference;
}

function applyToDocument(resolved: ResolvedTheme): void {
    if (!canUseDom()) return;
    const root = document.documentElement;
    // The class is what this package's CSS keys off; the attribute is for
    // consumers whose own styles key off `[data-theme]`.
    root.classList.toggle("dark", resolved === "dark");
    root.setAttribute("data-theme", resolved);
}

function publish(): void {
    const preference = getThemePreference();
    const resolved = resolveTheme(preference);
    applyToDocument(resolved);
    listeners.forEach((listener) => listener(resolved, preference));
}

/**
 * Choose a theme. `"system"` REMOVES the stored value rather than storing the
 * string — an absent choice is what lets the OS keep speaking for the user.
 */
export function setThemePreference(preference: ThemePreference): void {
    if (canUseDom()) {
        try {
            if (preference === "system") {
                window.localStorage.removeItem(storageKey);
            } else {
                window.localStorage.setItem(storageKey, preference);
            }
        } catch {
            // As above: still apply it for this page even if it cannot persist.
        }
    }
    publish();
}

/** Observe theme changes. Returns an unsubscribe. */
export function subscribeTheme(listener: ThemeListener): () => void {
    listeners.add(listener);
    return () => {
        listeners.delete(listener);
    };
}

/**
 * Apply the current theme and start following the OS. Call once, as early as
 * possible — before first paint if you want to avoid a flash of the wrong
 * theme. Returns a disposer; calling it again is harmless.
 */
export function initTheme(options: { storageKey?: string } = {}): () => void {
    if (options.storageKey) storageKey = options.storageKey;
    if (!canUseDom()) return () => {};

    applyToDocument(resolveTheme());

    if (!stopWatchingSystem && typeof window.matchMedia === "function") {
        const media = window.matchMedia(DARK_QUERY);
        const onSystemChange = (): void => {
            // Only "system" follows the OS. An explicit choice has to survive
            // the user switching their OS theme, or it isn't a choice.
            if (getThemePreference() === "system") publish();
        };

        if (typeof media.addEventListener === "function") {
            media.addEventListener("change", onSystemChange);
            stopWatchingSystem = () => media.removeEventListener("change", onSystemChange);
        } else {
            // Safari < 14 and friends.
            media.addListener(onSystemChange);
            stopWatchingSystem = () => media.removeListener(onSystemChange);
        }
    }

    return () => {
        stopWatchingSystem?.();
        stopWatchingSystem = null;
    };
}

import { cn } from "../lib/utils/cn";
import { applyTone, resolve } from "../lib/data/emoji-utils";
import type { EmojiProps } from "./Emoji.types";

export function Emoji({ name, emoji, tone, size = "md", className }: EmojiProps) {
  const base = emoji ?? (name ? resolve(name) : undefined);
  if (!base) return null;

  const resolved = tone ? applyTone(base, tone) : base;

  const sizeClass = {
    sm: "text-base",
    md: "text-2xl",
    lg: "text-4xl",
    xl: "text-6xl",
  }[size];

  return (
    <span
      role="img"
      aria-label={name ?? resolved}
      data-react-fancy-emoji=""
      className={cn("inline-block leading-none", sizeClass, className)}
    >
      {resolved}
    </span>
  );
}

import type { SkinTone } from "../lib/data/emoji-utils";

export interface EmojiProps {
  name?: string;
  emoji?: string;
  tone?: SkinTone;
  size?: "sm" | "md" | "lg" | "xl";
  className?: string;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { EMOJI_DATA, EMOJI_ENTRIES, type EmojiCategoryKey, type EmojiEntry } from "./emoji-data";

export const SKIN_TONES = ["light", "medium-light", "medium", "medium-dark", "dark"] as const;
export type SkinTone = typeof SKIN_TONES[number];

type IndexedEntry = EmojiEntry & { category: EmojiCategoryKey };

let byName: Map<string, IndexedEntry> | null = null;
let byChar: Map<string, IndexedEntry> | null = null;

function ensureIndexes() {
  if (byName && byChar) return;
  byName = new Map();
  byChar = new Map();
  for (const [category, group] of Object.entries(EMOJI_DATA) as [EmojiCategoryKey, typeof EMOJI_DATA[EmojiCategoryKey]][]) {
    for (const emoji of group.emojis) {
      const entry: IndexedEntry = { ...emoji, category };
      byName.set(emoji.name.toLowerCase(), entry);
      byChar.set(emoji.char, entry);
      if (emoji.skinTones) {
        for (const toned of emoji.skinTones) {
          byChar.set(toned, entry);
        }
      }
    }
  }
}

/** Resolve an emoji name to its character. */
export function resolve(name: string): string | undefined {
  ensureIndexes();
  return byName!.get(name.toLowerCase())?.char;
}

/** Search emojis by name substring. Returns matching base emoji characters. */
export function search(query: string): string[] {
  const lower = query.toLowerCase();
  return EMOJI_ENTRIES.filter((e) => e.name.includes(lower)).map((e) => e.char);
}

/** Find an emoji entry by its character (toned or base). */
export function find(char: string): IndexedEntry | undefined {
  ensureIndexes();
  return byChar!.get(char);
}

/** Return the 5-tone variant array for an emoji (by char, toned or base). */
export function skinTones(char: string): readonly [string, string, string, string, string] | undefined {
  return find(char)?.skinTones;
}

/** Whether an emoji supports skin tones. */
export function hasSkinTones(char: string): boolean {
  return !!find(char)?.skinTones;
}

/** Return the toned variant for an emoji, or the base if no tones. */
export function applyTone(char: string, tone: SkinTone | null): string {
  if (!tone) return char;
  const entry = find(char);
  if (!entry?.skinTones) return char;
  const idx = SKIN_TONES.indexOf(tone);
  return entry.skinTones[idx] ?? char;
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { EMOJI_CATEGORY_ORDER, EMOJI_DATA, type EmojiCategoryKey, type EmojiEntry } from "../lib/data/emoji-data";
import { applyTone, SKIN_TONES, type SkinTone } from "../lib/data/emoji-utils";
import type { EmojiSelectProps } from "./EmojiSelect.types";

const TONE_STORAGE_KEY = "fancy:emoji-tone";
const LONG_PRESS_MS = 400;
const HOVER_INTENT_MS = 120;
const HOVER_LEAVE_GRACE_MS = 220;

type ToneTarget = {
  emoji: EmojiEntry;
  rect: { left: number; top: number; width: number };
};

// Deliberately no hover-capability gate. We use `pointerType` on pointer events so touch
// inputs never trigger the hover path (they go through long-press instead), and mouse/pen
// inputs always work regardless of what `(hover: hover)` resolves to in the current env.

function readStoredTone(): SkinTone | null {
  if (typeof window === "undefined") return null;
  try {
    const v = window.localStorage?.getItem(TONE_STORAGE_KEY);
    return (SKIN_TONES as readonly string[]).includes(v ?? "") ? (v as SkinTone) : null;
  } catch {
    return null;
  }
}

export function EmojiSelect({ value, defaultValue, onChange, placeholder = "Search emojis...", className }: EmojiSelectProps) {
  const [selected, setSelected] = useControllableState(value, defaultValue ?? "", onChange);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState<EmojiCategoryKey>("smileys");
  const [tone, setToneState] = useState<SkinTone | null>(() => readStoredTone());
  const [toneTarget, setToneTarget] = useState<ToneTarget | null>(null);
  const leaveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const setTone = useCallback((t: SkinTone | null) => {
    setToneState(t);
    if (typeof window === "undefined") return;
    try {
      if (t) window.localStorage?.setItem(TONE_STORAGE_KEY, t);
      else window.localStorage?.removeItem(TONE_STORAGE_KEY);
    } catch {}
  }, []);

  const filtered = useMemo(() => {
    if (!query) return null;
    const lower = query.toLowerCase();
    const hits: EmojiEntry[] = [];
    for (const group of Object.values(EMOJI_DATA)) {
      for (const e of group.emojis) {
        if (e.name.includes(lower)) hits.push(e);
      }
    }
    return hits;
  }, [query]);

  const closePicker = useCallback(() => setToneTarget(null), []);

  const openPicker = useCallback((target: ToneTarget) => {
    if (leaveTimer.current) {
      clearTimeout(leaveTimer.current);
      leaveTimer.current = null;
    }
    setToneTarget(target);
  }, []);

  const scheduleClose = useCallback(() => {
    if (leaveTimer.current) clearTimeout(leaveTimer.current);
    leaveTimer.current = setTimeout(closePicker, HOVER_LEAVE_GRACE_MS);
  }, [closePicker]);

  const cancelClose = useCallback(() => {
    if (leaveTimer.current) {
      clearTimeout(leaveTimer.current);
      leaveTimer.current = null;
    }
  }, []);

  const pick = (emoji: EmojiEntry) => {
    const char = emoji.skinTones && tone ? applyTone(emoji.char, tone) : emoji.char;
    setSelected(char);
    setOpen(false);
    setQuery("");
    closePicker();
  };

  const pickTone = (emoji: EmojiEntry, t: SkinTone) => {
    setTone(t);
    const char = applyTone(emoji.char, t);
    setSelected(char);
    setOpen(false);
    setQuery("");
    closePicker();
  };

  useEffect(() => {
    if (!open) closePicker();
  }, [open, closePicker]);

  return (
    <div className={cn("relative inline-block", className)} data-react-fancy-emoji-select="">
      <button
        type="button"
        className="flex items-center gap-2 rounded-lg border border-zinc-300 px-3 py-2 text-sm transition-[border-color,box-shadow] duration-150 dark:border-zinc-700 dark:bg-[#1e1e24]"
        onClick={() => setOpen((v) => !v)}
      >
        {selected ? <span className="text-xl">{selected}</span> : <span className="text-zinc-400">Pick emoji</span>}
      </button>

      {open && (
        <div className="absolute z-50 mt-1 w-80 rounded-lg border border-zinc-200 bg-white p-2 shadow-lg dark:border-zinc-700 dark:bg-zinc-800 fancy-fade-in">
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={placeholder}
            className="mb-2 w-full rounded-md border border-zinc-200 px-2 py-1 text-sm transition-[border-color,box-shadow] duration-150 dark:border-zinc-700 dark:bg-[#1e1e24] dark:text-zinc-100"
            autoFocus
          />

          {!query && (
            <div className="mb-2 flex gap-1 overflow-x-auto border-b border-zinc-100 pb-2 dark:border-zinc-700">
              {EMOJI_CATEGORY_ORDER.map((key) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setActiveCategory(key)}
                  className={cn(
                    "shrink-0 rounded p-1 text-lg hover:bg-zinc-100 dark:hover:bg-zinc-700",
                    activeCategory === key && "bg-zinc-100 dark:bg-zinc-700",
                  )}
                  aria-label={EMOJI_DATA[key].label}
                >
                  {EMOJI_DATA[key].icon}
                </button>
              ))}
            </div>
          )}

          <div className="max-h-64 overflow-y-auto">
            {query ? (
              <EmojiGrid
                emojis={filtered ?? []}
                tone={tone}
                openPicker={openPicker}
                scheduleClose={scheduleClose}
                cancelClose={cancelClose}
                onPick={pick}
              />
            ) : (
              <div>
                <div className="px-1 py-1 text-xs font-semibold uppercase text-zinc-500">
                  {EMOJI_DATA[activeCategory].label}
                </div>
                <EmojiGrid
                  emojis={EMOJI_DATA[activeCategory].emojis}
                  tone={tone}
                  openPicker={openPicker}
                  scheduleClose={scheduleClose}
                  cancelClose={cancelClose}
                  onPick={pick}
                />
              </div>
            )}
          </div>
        </div>
      )}

      {toneTarget && typeof document !== "undefined" &&
        createPortal(
          <TonePopover
            target={toneTarget}
            onPickBase={() => pick(toneTarget.emoji)}
            onPickTone={(t) => pickTone(toneTarget.emoji, t)}
            onMouseEnter={cancelClose}
            onMouseLeave={scheduleClose}
          />,
          document.body,
        )}
    </div>
  );
}

type GridProps = {
  emojis: EmojiEntry[];
  tone: SkinTone | null;
  openPicker: (target: ToneTarget) => void;
  scheduleClose: () => void;
  cancelClose: () => void;
  onPick: (emoji: EmojiEntry) => void;
};

function EmojiGrid({ emojis, tone, openPicker, scheduleClose, cancelClose, onPick }: GridProps) {
  return (
    <div className="grid grid-cols-8 gap-0.5">
      {emojis.map((emoji) => (
        <EmojiCell
          key={emoji.char}
          emoji={emoji}
          tone={tone}
          openPicker={openPicker}
          scheduleClose={scheduleClose}
          cancelClose={cancelClose}
          onPick={() => onPick(emoji)}
        />
      ))}
    </div>
  );
}

type CellProps = {
  emoji: EmojiEntry;
  tone: SkinTone | null;
  openPicker: (target: ToneTarget) => void;
  scheduleClose: () => void;
  cancelClose: () => void;
  onPick: () => void;
};

function EmojiCell({ emoji, tone, openPicker, scheduleClose, cancelClose, onPick }: CellProps) {
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hoverTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longPressed = useRef(false);

  const tonable = !!emoji.skinTones;
  const displayChar = tonable && tone ? applyTone(emoji.char, tone) : emoji.char;

  useEffect(() => () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
    if (hoverTimer.current) clearTimeout(hoverTimer.current);
  }, []);

  const triggerOpen = () => {
    const node = buttonRef.current;
    if (!node) return;
    const r = node.getBoundingClientRect();
    openPicker({ emoji, rect: { left: r.left, top: r.top, width: r.width } });
  };

  const handlePointerEnter = (e: React.PointerEvent) => {
    if (!tonable || e.pointerType === "touch") return;
    cancelClose();
    if (hoverTimer.current) clearTimeout(hoverTimer.current);
    hoverTimer.current = setTimeout(triggerOpen, HOVER_INTENT_MS);
  };

  const handlePointerLeave = (e: React.PointerEvent) => {
    if (e.pointerType === "touch") return;
    if (hoverTimer.current) {
      clearTimeout(hoverTimer.current);
      hoverTimer.current = null;
    }
    if (tonable) scheduleClose();
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!tonable || e.pointerType !== "touch") return;
    longPressed.current = false;
    longPressTimer.current = setTimeout(() => {
      longPressed.current = true;
      triggerOpen();
    }, LONG_PRESS_MS);
  };
  const handlePointerUp = () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
    longPressTimer.current = null;
  };

  const handleClick = () => {
    if (longPressed.current) {
      longPressed.current = false;
      return;
    }
    onPick();
  };

  return (
    <button
      ref={buttonRef}
      type="button"
      onClick={handleClick}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      className="relative rounded p-1 text-xl hover:bg-zinc-100 dark:hover:bg-zinc-700"
      aria-label={emoji.name}
      title={emoji.name}
    >
      {displayChar}
      {tonable && (
        <span className="absolute right-0.5 bottom-0.5 h-1 w-1 rounded-full bg-amber-400" aria-hidden />
      )}
    </button>
  );
}

type PopoverProps = {
  target: ToneTarget;
  onPickBase: () => void;
  onPickTone: (tone: SkinTone) => void;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
};

function TonePopover({ target, onPickBase, onPickTone, onMouseEnter, onMouseLeave }: PopoverProps) {
  const { emoji, rect } = target;
  if (!emoji.skinTones) return null;

  const centerX = rect.left + rect.width / 2;
  const top = rect.top;
  const POPOVER_HEIGHT_APPROX = 44;
  const flipDown = top < POPOVER_HEIGHT_APPROX + 8;

  const style: React.CSSProperties = flipDown
    ? { position: "fixed", left: centerX, top: top + 32, transform: "translateX(-50%)" }
    : { position: "fixed", left: centerX, top: top - 4, transform: "translate(-50%, -100%)" };

  return (
    <div
      style={{ ...style, zIndex: 9999 }}
      className="flex gap-0.5 rounded-md border border-zinc-200 bg-white p-1 shadow-lg dark:border-zinc-700 dark:bg-zinc-800"
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      <button
        type="button"
        onClick={onPickBase}
        className="rounded p-1 text-lg hover:bg-zinc-100 dark:hover:bg-zinc-700"
        aria-label={`${emoji.name} (no tone)`}
      >
        {emoji.char}
      </button>
      {SKIN_TONES.map((t, i) => (
        <button
          key={t}
          type="button"
          onClick={() => onPickTone(t)}
          className="rounded p-1 text-lg hover:bg-zinc-100 dark:hover:bg-zinc-700"
          aria-label={`${emoji.name} ${t} skin tone`}
        >
          {emoji.skinTones![i]}
        </button>
      ))}
    </div>
  );
}

export interface EmojiSelectProps {
  value?: string;
  defaultValue?: string;
  onChange?: (emoji: string) => void;
  placeholder?: string;
  className?: string;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import { EMOJI_DATA, EMOJI_ENTRIES, type EmojiCategoryKey, type EmojiEntry } from "./emoji-data";

export const SKIN_TONES = ["light", "medium-light", "medium", "medium-dark", "dark"] as const;
export type SkinTone = typeof SKIN_TONES[number];

type IndexedEntry = EmojiEntry & { category: EmojiCategoryKey };

let byName: Map<string, IndexedEntry> | null = null;
let byChar: Map<string, IndexedEntry> | null = null;

function ensureIndexes() {
  if (byName && byChar) return;
  byName = new Map();
  byChar = new Map();
  for (const [category, group] of Object.entries(EMOJI_DATA) as [EmojiCategoryKey, typeof EMOJI_DATA[EmojiCategoryKey]][]) {
    for (const emoji of group.emojis) {
      const entry: IndexedEntry = { ...emoji, category };
      byName.set(emoji.name.toLowerCase(), entry);
      byChar.set(emoji.char, entry);
      if (emoji.skinTones) {
        for (const toned of emoji.skinTones) {
          byChar.set(toned, entry);
        }
      }
    }
  }
}

/** Resolve an emoji name to its character. */
export function resolve(name: string): string | undefined {
  ensureIndexes();
  return byName!.get(name.toLowerCase())?.char;
}

/** Search emojis by name substring. Returns matching base emoji characters. */
export function search(query: string): string[] {
  const lower = query.toLowerCase();
  return EMOJI_ENTRIES.filter((e) => e.name.includes(lower)).map((e) => e.char);
}

/** Find an emoji entry by its character (toned or base). */
export function find(char: string): IndexedEntry | undefined {
  ensureIndexes();
  return byChar!.get(char);
}

/** Return the 5-tone variant array for an emoji (by char, toned or base). */
export function skinTones(char: string): readonly [string, string, string, string, string] | undefined {
  return find(char)?.skinTones;
}

/** Whether an emoji supports skin tones. */
export function hasSkinTones(char: string): boolean {
  return !!find(char)?.skinTones;
}

/** Return the toned variant for an emoji, or the base if no tones. */
export function applyTone(char: string, tone: SkinTone | null): string {
  if (!tone) return char;
  const entry = find(char);
  if (!entry?.skinTones) return char;
  const idx = SKIN_TONES.indexOf(tone);
  return entry.skinTones[idx] ?? char;
}

import { Badge, Button, Card, Heading, Text } from '@particle-academy/react-fancy';
import { formatLocation, formatPay, postingStatusColor } from '../lib/format';
import type { JobPosting } from '../lib/types';

export interface EmployerJobListProps {
    postings: JobPosting[];
    onEdit?: (posting: JobPosting) => void;
    onPublish?: (posting: JobPosting) => void;
    onUnpublish?: (posting: JobPosting) => void;
    onClose?: (posting: JobPosting) => void;
    onViewApplicants?: (posting: JobPosting) => void;
    onCreate?: () => void;
    /** Publishing is gated by the host; false renders the reason instead. */
    canPublish?: boolean;
    publishBlockedReason?: string;
    /**
     * Label for the publish action, per posting. Hosts that charge per listing
     * or meter it against a plan use this to say so up front — "Publish — $49"
     * beats a bare "Publish" that silently opens a checkout.
     */
    publishLabel?: (posting: JobPosting) => string;
    /** Slug of the posting currently mid-action, to show a spinner on its row. */
    busyId?: number | null;
    className?: string;
}

/**
 * The employer's own postings, in every status, with the actions that move
 * them between statuses.
 */
export function EmployerJobList({
    postings,
    onEdit,
    onPublish,
    onUnpublish,
    onClose,
    onViewApplicants,
    onCreate,
    canPublish = true,
    publishBlockedReason,
    publishLabel,
    busyId = null,
    className,
}: EmployerJobListProps) {
    if (postings.length === 0) {
        return (
            <Card
                variant="outlined"
                padding="lg"
                className={`!rounded-xl !border-secondary-200 text-center ${className ?? ''}`}
            >
                <Heading as="h3" size="lg" weight="bold" className="!text-secondary-900">
                    No postings yet
                </Heading>
                <Text color="muted" className="!mt-2">
                    Create your first job posting to start receiving applications.
                </Text>
                {onCreate && (
                    <div className="mt-5 flex justify-center">
                        <Button
                            type="button"
                            onClick={onCreate}
                            className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-6 !py-2.5 !rounded-md !shadow-sm"
                        >
                            New posting
                        </Button>
                    </div>
                )}
            </Card>
        );
    }

    return (
        <div className={`grid gap-3 ${className ?? ''}`}>
            {postings.map((posting) => {
                const busy = busyId === posting.id;
                const pay = formatPay(posting);
                const location = formatLocation(posting);

                return (
                    <Card
                        key={posting.id}
                        variant="outlined"
                        padding="lg"
                        className="!rounded-xl !border-secondary-200 !shadow-sm"
                    >
                        <div className="flex flex-wrap items-start justify-between gap-4">
                            <div className="min-w-0">
                                <div className="flex items-center gap-2">
                                    <Badge
                                        color={postingStatusColor(posting.status)}
                                        variant="soft"
                                        size="sm"
                                    >
                                        {posting.status_label}
                                    </Badge>
                                    {posting.employment_type_label && (
                                        <Text size="xs" color="muted">
                                            {posting.employment_type_label}
                                        </Text>
                                    )}
                                </div>

                                <Heading
                                    as="h3"
                                    size="lg"
                                    weight="bold"
                                    className="!mt-2 !text-secondary-900"
                                >
                                    {posting.title}
                                </Heading>

                                <Text size="sm" color="muted" className="!mt-1">
                                    {[location, pay].filter(Boolean).join(' · ') || 'No location or pay set'}
                                </Text>
                            </div>

                            <div className="text-right">
                                <Text size="lg" weight="bold" className="!text-secondary-900 !text-2xl">
                                    {posting.applications_count}
                                </Text>
                                <Text size="xs" color="muted">
                                    {posting.applications_count === 1 ? 'applicant' : 'applicants'}
                                </Text>
                            </div>
                        </div>

                        <div className="mt-4 flex flex-wrap items-center gap-2 border-t border-secondary-200 pt-4">
                            {onViewApplicants && posting.applications_count > 0 && (
                                <Button
                                    type="button"
                                    onClick={() => onViewApplicants(posting)}
                                    className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-4 !py-2 !rounded-md"
                                >
                                    View applicants
                                </Button>
                            )}

                            {onEdit && (
                                <Button
                                    type="button"
                                    variant="ghost"
                                    onClick={() => onEdit(posting)}
                                    className="!text-secondary-700 hover:!text-brand"
                                >
                                    Edit
                                </Button>
                            )}

                            {posting.status !== 'published' && onPublish && (
                                canPublish ? (
                                    <Button
                                        type="button"
                                        variant="ghost"
                                        loading={busy}
                                        disabled={busy}
                                        onClick={() => onPublish(posting)}
                                        className="!text-secondary-700 hover:!text-brand"
                                    >
                                        {publishLabel?.(posting) ?? 'Publish'}
                                    </Button>
                                ) : (
                                    <Text size="xs" color="muted">
                                        {publishBlockedReason ?? 'Publishing locked until approved'}
                                    </Text>
                                )
                            )}

                            {posting.status === 'published' && onUnpublish && (
                                <Button
                                    type="button"
                                    variant="ghost"
                                    loading={busy}
                                    disabled={busy}
                                    onClick={() => onUnpublish(posting)}
                                    className="!text-secondary-700 hover:!text-brand"
                                >
                                    Unpublish
                                </Button>
                            )}

                            {posting.status !== 'closed' && onClose && (
                                <Button
                                    type="button"
                                    variant="ghost"
                                    loading={busy}
                                    disabled={busy}
                                    onClick={() => onClose(posting)}
                                    className="!text-secondary-700 hover:!text-brand"
                                >
                                    Close
                                </Button>
                            )}
                        </div>
                    </Card>
                );
            })}
        </div>
    );
}

import type { ApplicationStatus, JobPosting, JobPostingStatus } from './types';

const PAY_UNIT_SUFFIX: Record<string, string> = {
    hour: '/hr',
    day: '/day',
    week: '/wk',
    month: '/mo',
    year: '/yr',
};

/**
 * "$20–$30/hr", "From $45,000/yr", "Up to $25/hr", or null when the posting
 * gives no pay information — callers should omit the line entirely rather than
 * print an empty range.
 */
export function formatPay(posting: Pick<JobPosting, 'pay_min' | 'pay_max' | 'pay_unit' | 'currency'>): string | null {
    const { pay_min, pay_max, pay_unit, currency } = posting;

    if (pay_min == null && pay_max == null) {
        return null;
    }

    const money = (n: number) =>
        new Intl.NumberFormat(undefined, {
            style: 'currency',
            currency: currency || 'USD',
            maximumFractionDigits: n % 1 === 0 ? 0 : 2,
        }).format(n);

    const suffix = pay_unit ? (PAY_UNIT_SUFFIX[pay_unit] ?? `/${pay_unit}`) : '';

    if (pay_min != null && pay_max != null) {
        return pay_min === pay_max
            ? `${money(pay_min)}${suffix}`
            : `${money(pay_min)}–${money(pay_max)}${suffix}`;
    }

    return pay_min != null
        ? `From ${money(pay_min)}${suffix}`
        : `Up to ${money(pay_max as number)}${suffix}`;
}

/** "Torrance, CA", "Remote", or "Remote · Torrance, CA" when it is both. */
export function formatLocation(posting: Pick<JobPosting, 'location' | 'is_remote'>): string | null {
    if (posting.is_remote && posting.location) {
        return `Remote · ${posting.location}`;
    }
    if (posting.is_remote) {
        return 'Remote';
    }
    return posting.location || null;
}

/** Coarse "posted" line. Deliberately vague — exact times add nothing here. */
export function formatPosted(iso?: string | null): string | null {
    if (!iso) return null;

    const then = new Date(iso).getTime();
    if (Number.isNaN(then)) return null;

    const days = Math.floor((Date.now() - then) / 86_400_000);

    if (days <= 0) return 'Posted today';
    if (days === 1) return 'Posted yesterday';
    if (days < 7) return `Posted ${days} days ago`;
    if (days < 14) return 'Posted last week';
    if (days < 60) return `Posted ${Math.floor(days / 7)} weeks ago`;
    return `Posted ${Math.floor(days / 30)} months ago`;
}

/** Fancy Badge colours, chosen so status reads at a glance. */
export function postingStatusColor(status: JobPostingStatus): 'green' | 'zinc' | 'red' {
    switch (status) {
        case 'published':
            return 'green';
        case 'closed':
            return 'red';
        default:
            return 'zinc';
    }
}

export function applicationStatusColor(status: ApplicationStatus): 'green' | 'zinc' | 'red' | 'blue' {
    switch (status) {
        case 'hired':
            return 'green';
        case 'shortlisted':
            return 'blue';
        case 'rejected':
        case 'withdrawn':
            return 'red';
        default:
            return 'zinc';
    }
}

