/**
 * Does a file satisfy an `accept` string?
 *
 * The browser enforces `accept` in the FILE PICKER only. A drag-and-drop never
 * opens a picker, so on the drop path this is the only thing standing between an
 * image-only dropzone and a dropped executable. Forwarding the attribute to the
 * hidden input is half the job; this is the other half.
 *
 * Follows the HTML `accept` grammar: a comma-separated list of extensions
 * (`.csv`), exact MIME types (`text/plain`) and type wildcards (`image/*`).
 * Matching is case-insensitive, because a drop reports whatever the OS says and
 * `TEXT/PLAIN` is a real thing to receive.
 *
 * A dropped file often carries an EMPTY `type` — the OS may not know it and
 * `File.type` is a hint, never a guarantee. That is why extension rules are
 * checked against the name and not the type: an `accept=".csv"` zone has to work
 * for a .csv whose type is `""`, which is the common case rather than the edge.
 */
export function matchesAccept(file: File, accept: string): boolean {
  const rules = accept
    .split(",")
    .map((rule) => rule.trim().toLowerCase())
    .filter(Boolean);

  // An accept string that lists nothing constrains nothing. Failing closed here
  // would turn `accept=""` into a dropzone that silently swallows every file.
  if (rules.length === 0) return true;

  const type = file.type.toLowerCase();
  const name = file.name.toLowerCase();

  return rules.some((rule) => {
    if (rule.startsWith(".")) return name.endsWith(rule);
    if (rule.endsWith("/*")) return type.startsWith(rule.slice(0, -1));
    return type === rule;
  });
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
