export interface FileViewerProps {
  /**
   * File name or path — used to detect the file kind / editor language, and as
   * a label / alt text. Pass `mime` too when you have it (it's preferred).
   */
  filename?: string;
  /** MIME type — preferred over `filename` for detection. */
  mime?: string;
  /**
   * Source URL for **media** files (image / video / audio / PDF) —
   * `http(s):` / `data:` / `blob:`. Required when the file resolves to media.
   */
  src?: string;
  /** Text content for **text** files. */
  value?: string;
  /** Called when text content changes (ignored when `readOnly`). */
  onChange?: (value: string) => void;
  /**
   * Read-only. Defaults to `true` — `FileViewer` is a viewer. Media is always
   * read-only regardless. Set `false` (with `onChange`) to edit text.
   */
  readOnly?: boolean;
  /** Editor theme for text: `"light" | "dark" | "auto"` or a registered name (default `"auto"`). */
  theme?: string;
  /** Force the file kind, bypassing detection. */
  fileKind?: FileKind;
  /** Show line numbers in the text editor (default `true`). */
  lineNumbers?: boolean;
  /** Wrap long lines in the text editor (default `false`). */
  wordWrap?: boolean;
  /**
   * 1-based line to land on: scrolled to the middle of the view, caret placed,
   * and highlighted. Applied on mount and again whenever it changes, so
   * re-targeting an open file scrolls again. Text files only; does not steal focus.
   */
  line?: number;
  /** 1-based column for {@link line} (default 1). */
  column?: number;
  /**
   * Lines to highlight. Defaults to `[line]` when `line` is set; pass your own
   * (a range, several hits) to override, or `[]` to land without highlighting.
   */
  highlightLines?: readonly number[];
  /** Editor height bounds (px). */
  minHeight?: number;
  maxHeight?: number;
  /** Extra props forwarded to `<MediaViewer>` for media files. */
  mediaProps?: Partial<Omit<MediaViewerProps, "src" | "mime" | "alt">>;
  className?: string;
  style?: CSSProperties;
}

import { resolveMediaType, type MediaKind } from "@particle-academy/react-fancy";
import { languageFromFilename } from "@particle-academy/fancy-file-commons";

/**
 * The decision a file viewer makes about a file: render it as editable text, or
 * hand it to a media viewer. `media` carries the resolved {@link MediaKind};
 * `text` carries the editor language id.
 */
export type FileKind =
  | { kind: "text"; language: string }
  | { kind: "media"; mediaKind: MediaKind };

export interface ResolveFileKindInput {
  /** File name or path — sniffed for an extension (and used for the media check). */
  filename?: string;
  /** MIME type — preferred over the filename when known. */
  mime?: string;
}

// Filename → language now lives in @particle-academy/fancy-file-commons (the
// shared core for the file packages — one EXT_LANGUAGE map suite-wide).
// Re-exported so existing `fancy-code` imports keep working.
export { languageFromFilename };

/**
 * Decide whether a file is previewable media (image / video / audio / PDF) or
 * text, from its MIME type (preferred) and/or filename. Media wins when the
 * type resolves to one; otherwise it's text and the editor language is derived
 * from the extension.
 *
 * Exposed so consumers can branch their own chrome (tabs, save buttons) the
 * same way `<FileViewer>` does internally.
 *
 * ```ts
 * resolveFileKind({ filename: "logo.png" });   // { kind: "media", mediaKind: "image" }
 * resolveFileKind({ filename: "app.tsx" });     // { kind: "text", language: "typescript" }
 * resolveFileKind({ mime: "application/pdf" }); // { kind: "media", mediaKind: "pdf" }
 * ```
 */
export function resolveFileKind({ filename, mime }: ResolveFileKindInput): FileKind {
  const media = resolveMediaType({ mime, src: filename });
  if (media !== "unknown") return { kind: "media", mediaKind: media };
  return { kind: "text", language: languageFromFilename(filename) };
}

import { useEffect, useRef, useCallback, useState, useMemo, type RefObject } from "react";
import { getLanguage } from "../languages";
import { getTheme } from "../themes";
import { highlightCode } from "../engine/highlight";
import { lineColumnToOffset } from "../engine/position";
import type { ThemeColors } from "../themes/types";
import type { Tokenizer } from "../engine/tokenizer";

export interface UseEditorEngineOptions {
  containerRef: RefObject<HTMLDivElement | null>;
  value: string;
  onChange?: (value: string) => void;
  language: string;
  theme: string;
  readOnly: boolean;
  lineNumbers: boolean;
  wordWrap: boolean;
  tabSize: number;
  placeholder?: string;
  minHeight?: number;
  maxHeight?: number;
  onCursorChange?: (pos: { line: number; col: number; selectionLength: number }) => void;
}

export interface UseEditorEngineReturn {
  textareaRef: RefObject<HTMLTextAreaElement | null>;
  highlightedHtml: string;
  lineCount: number;
  activeLine: number;
  themeColors: ThemeColors;
  handleKeyDown: (e: React.KeyboardEvent<HTMLTextAreaElement>) => void;
  handleInput: () => void;
  handleScroll: () => void;
  handleSelect: () => void;
  /**
   * Place the caret on a 1-based `line` / `column` and scroll the editor so the
   * line is centered in view. Out-of-range positions clamp to document bounds.
   */
  revealLine: (line: number, column?: number, opts?: { focus?: boolean }) => void;
  scrollTop: number;
  scrollLeft: number;
}

const DEFAULT_COLORS: ThemeColors = {
  background: "#18181b",
  foreground: "#e4e4e7",
  gutterBackground: "#18181b",
  gutterForeground: "#52525b",
  gutterBorder: "#27272a",
  activeLineBackground: "#27272a",
  selectionBackground: "#1e3a5f",
  cursorColor: "#60a5fa",
  keyword: "#c084fc",
  string: "#34d399",
  comment: "#71717a",
  number: "#fbbf24",
  operator: "#22d3ee",
  function: "#60a5fa",
  type: "#fbbf24",
  tag: "#f87171",
  attribute: "#fbbf24",
  attributeValue: "#34d399",
  punctuation: "#a1a1aa",
  variable: "#e4e4e7",
};

export function useEditorEngine({
  value,
  onChange,
  language,
  theme,
  readOnly,
  wordWrap,
  tabSize,
  onCursorChange,
}: UseEditorEngineOptions): UseEditorEngineReturn {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const onChangeRef = useRef(onChange);
  const onCursorChangeRef = useRef(onCursorChange);
  onChangeRef.current = onChange;
  onCursorChangeRef.current = onCursorChange;

  const [scrollTop, setScrollTop] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [activeLine, setActiveLine] = useState(1);

  // Resolve theme colors
  const themeColors = useMemo<ThemeColors>(() => {
    const def = getTheme(theme);
    return def?.colors ?? DEFAULT_COLORS;
  }, [theme]);

  // Resolve tokenizer
  const tokenizer = useMemo<Tokenizer | null>(() => {
    const def = getLanguage(language);
    return def?.tokenize ?? null;
  }, [language]);

  // Generate highlighted HTML
  const highlightedHtml = useMemo(() => {
    if (!tokenizer) {
      // No tokenizer — just escape HTML
      return value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
    }
    const tokens = tokenizer(value);
    return highlightCode(value, tokens, themeColors);
  }, [value, tokenizer, themeColors]);

  const lineCount = useMemo(() => {
    let count = 1;
    for (let i = 0; i < value.length; i++) {
      if (value[i] === "\n") count++;
    }
    return count;
  }, [value]);

  // Auto-resize textarea to match content so caret is always visible
  const autoResize = useCallback(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    ta.style.height = "auto";
    ta.style.height = ta.scrollHeight + "px";

    if (!wordWrap) {
      // Shrink to 0 to measure true content width, then expand
      ta.style.width = "0";
      ta.style.width = ta.scrollWidth + "px";
    } else {
      ta.style.width = "";
    }
  }, [wordWrap]);

  // Sync textarea value and auto-resize when value changes
  useEffect(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    if (ta.value !== value) {
      const { selectionStart, selectionEnd } = ta;
      ta.value = value;
      ta.selectionStart = selectionStart;
      ta.selectionEnd = selectionEnd;
    }
    // Always resize — handles initial mount and external value changes
    autoResize();
  }, [value, autoResize]);

  const updateCursorInfo = useCallback(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    const pos = ta.selectionStart;
    const textBefore = ta.value.slice(0, pos);
    const line = (textBefore.match(/\n/g) || []).length + 1;
    const lastNewline = textBefore.lastIndexOf("\n");
    const col = pos - lastNewline;
    const selLen = Math.abs(ta.selectionEnd - ta.selectionStart);
    setActiveLine(line);
    onCursorChangeRef.current?.({ line, col, selectionLength: selLen });
  }, []);

  const handleInput = useCallback(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    onChangeRef.current?.(ta.value);
    autoResize();
    updateCursorInfo();
  }, [autoResize, updateCursorInfo]);

  const handleSelect = useCallback(() => {
    updateCursorInfo();
  }, [updateCursorInfo]);

  const handleScroll = useCallback(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    setScrollTop(ta.scrollTop);
    setScrollLeft(ta.scrollLeft);
  }, []);

  const revealLine = useCallback(
    (line: number, column = 1, opts?: { focus?: boolean }) => {
      const ta = textareaRef.current;
      if (!ta) return;

      const offset = lineColumnToOffset(ta.value, line, column);
      if (opts?.focus) ta.focus();
      ta.selectionStart = ta.selectionEnd = offset;
      updateCursorInfo();

      // Scroll the editor's scroll container (the panel) so the target line is
      // centered. The textarea is auto-sized to fit its content, so the panel —
      // not the textarea — is what scrolls.
      const panel = ta.closest<HTMLElement>("[data-fancy-code-panel]");
      if (!panel) return;
      const cs = getComputedStyle(ta);
      const lineHeight = parseFloat(cs.lineHeight) || 19.5;
      const paddingTop = parseFloat(cs.paddingTop) || 0;
      const lineIndex = (ta.value.slice(0, offset).match(/\n/g) || []).length; // clamped (targetLine - 1)
      const textareaTopInPanel =
        ta.getBoundingClientRect().top - panel.getBoundingClientRect().top + panel.scrollTop;
      const lineTop = textareaTopInPanel + paddingTop + lineIndex * lineHeight;
      const target = lineTop - panel.clientHeight / 2 + lineHeight / 2;
      const maxScroll = panel.scrollHeight - panel.clientHeight;
      panel.scrollTop = Math.max(0, Math.min(target, maxScroll));
    },
    [updateCursorInfo],
  );

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (readOnly) {
        // Allow copy shortcuts in read-only mode
        if (e.key === "c" && (e.metaKey || e.ctrlKey)) return;
        if (e.key === "a" && (e.metaKey || e.ctrlKey)) return;
        e.preventDefault();
        return;
      }

      // Tab key — insert spaces
      if (e.key === "Tab") {
        e.preventDefault();
        const ta = e.currentTarget;
        const start = ta.selectionStart;
        const end = ta.selectionEnd;
        const spaces = " ".repeat(tabSize);

        if (e.shiftKey) {
          // Dedent: remove leading spaces from selected lines
          const lines = ta.value.split("\n");
          const startLine = ta.value.slice(0, start).split("\n").length - 1;
          const endLine = ta.value.slice(0, end).split("\n").length - 1;
          let removed = 0;
          for (let i = startLine; i <= endLine; i++) {
            const match = lines[i].match(new RegExp(`^ {1,${tabSize}}`));
            if (match) {
              removed += match[0].length;
              lines[i] = lines[i].slice(match[0].length);
            }
          }
          const newValue = lines.join("\n");
          ta.value = newValue;
          ta.selectionStart = Math.max(0, start - (startLine === endLine ? removed : tabSize));
          ta.selectionEnd = Math.max(0, end - removed);
          onChangeRef.current?.(newValue);
        } else if (start !== end) {
          // Indent selected lines
          const lines = ta.value.split("\n");
          const startLine = ta.value.slice(0, start).split("\n").length - 1;
          const endLine = ta.value.slice(0, end).split("\n").length - 1;
          for (let i = startLine; i <= endLine; i++) {
            lines[i] = spaces + lines[i];
          }
          const newValue = lines.join("\n");
          ta.value = newValue;
          ta.selectionStart = start + tabSize;
          ta.selectionEnd = end + (endLine - startLine + 1) * tabSize;
          onChangeRef.current?.(newValue);
        } else {
          // Insert tab at cursor
          const before = ta.value.slice(0, start);
          const after = ta.value.slice(end);
          ta.value = before + spaces + after;
          ta.selectionStart = ta.selectionEnd = start + tabSize;
          onChangeRef.current?.(ta.value);
        }
        autoResize();
        updateCursorInfo();
        return;
      }

      // Enter — auto-indent
      if (e.key === "Enter") {
        e.preventDefault();
        const ta = e.currentTarget;
        const start = ta.selectionStart;
        const end = ta.selectionEnd;
        const before = ta.value.slice(0, start);
        const after = ta.value.slice(end);
        const currentLine = before.split("\n").pop() || "";
        const indent = currentLine.match(/^(\s*)/)?.[1] || "";

        // Extra indent after { or (
        const lastChar = before.trimEnd().slice(-1);
        const extraIndent = (lastChar === "{" || lastChar === "(") ? " ".repeat(tabSize) : "";

        const insertion = "\n" + indent + extraIndent;
        ta.value = before + insertion + after;
        ta.selectionStart = ta.selectionEnd = start + insertion.length;
        onChangeRef.current?.(ta.value);
        autoResize();
        updateCursorInfo();
        return;
      }
    },
    [readOnly, tabSize, autoResize, updateCursorInfo],
  );

  return {
    textareaRef,
    highlightedHtml,
    lineCount,
    activeLine,
    themeColors,
    handleKeyDown,
    handleInput,
    handleScroll,
    handleSelect,
    revealLine,
    scrollTop,
    scrollLeft,
  };
}

import { useSyncExternalStore } from "react";

function subscribe(callback: () => void): () => void {
  const mq = window.matchMedia("(prefers-color-scheme: dark)");
  mq.addEventListener("change", callback);
  return () => mq.removeEventListener("change", callback);
}

function getSnapshot(): boolean {
  return window.matchMedia("(prefers-color-scheme: dark)").matches;
}

function getServerSnapshot(): boolean {
  return false;
}

export function useDarkMode(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

