  builtins?: FlowEditorBuiltins;
  /** Replace whole regions of the editor. */
  slots?: FlowEditorSlots;
  /** Forwarded to `<FlowCanvas>` / React Flow — snapToGrid, minimap, context
   *  menus, edge types, and anything else xyflow accepts. */
  canvasProps?: Partial<Omit<FlowCanvasProps, "nodes" | "edges">>;
  /** Called whenever the graph changes — host can persist. */
  onChange?: (graph: FlowGraph) => void;
  /** Called when the selected node changes. */
  onSelectionChange?: (node: FlowNode | null) => void;
  /** Called after nodes are deleted, with the deleted ids. */
  onDelete?: (ids: string[]) => void;
  /** Called after connections are broken, with the deleted edge ids. */
  onEdgeDelete?: (ids: string[]) => void;
  /**
   * Stage destructive edits for human confirmation. When set, every delete path
   * — keyboard, panel, context menu, and `api.deleteNodes`/`deleteEdges` —
   * calls this first; return false to veto. Default: delete immediately. This
   * realizes the component contract's "agents propose, humans confirm" on the
   * canvas.
   */
  confirmDelete?: (targets: { nodes: FlowNode[]; edges: Edge[] }) => boolean | Promise<boolean>;
  className?: string;
  style?: CSSProperties;
};

/**
 * FlowEditor — batteries-included workflow editor, but not a black box.
 *
 * Defaults compose NodePalette + FlowCanvas + NodeConfigPanel + run controls +
 * feed. Every part is replaceable: pass `actions` for custom toolbar buttons,
 * `slots` to swap a whole region, `canvasProps` to reach React Flow, or grab
 * the {@link FlowEditorApi} from `ref` / `useFlowEditor()` and build your own
 * chrome around the primitives.
 */
export const FlowEditor = forwardRef<FlowEditorApi, FlowEditorProps>(function FlowEditor(props, ref) {
  return (
    <ReactFlowProvider>
      <div
        // Which panes EXIST is declared on the root, so the grid columns can be
        // a function of it. Before this the grid was a fixed `216px 1fr 300px`
        // and the panes were merely conditionally rendered, so `showPalette=
        // {false}` put the canvas in the 216px column with an empty 300px
        // column beside it (#16). Two sources of truth for one fact.
        className={[
          "ff-editor",
          props.showPalette === false ? "ff-editor--no-palette" : "",
          props.showPanel === false ? "ff-editor--no-panel" : "",
          props.className ?? "",
        ]
          .filter(Boolean)
          .join(" ")}
        style={{ height: props.height ?? 720, ...props.style }}
      >
        <FlowEditorInner {...props} apiRef={ref} />
      </div>
    </ReactFlowProvider>
  );
});

function FlowEditorInner({
  initial = { nodes: [], edges: [] },
  value,
  executors = {},
  metadata,
  showPalette = true,
  showPanel = true,
  fieldRenderers,
  fieldFilter,
  kindFilter,
  showFeed = true,
  extraToolbar,
  actions = [],
  builtins = {},
  slots = {},
  canvasProps = {},
  onChange,
  onSelectionChange,
  onDelete,
  onEdgeDelete,
  confirmDelete,
  humanFieldRenderers,
  apiRef,
}: FlowEditorProps & { apiRef?: React.ForwardedRef<FlowEditorApi> }) {
  const internal = useFlowState(initial);
  const runner = useFlowRun();
  const rf = useReactFlow();

  // In-editor human-input: when a run reaches a `user_input` / `human_approval`
  // node, open a modal and BLOCK the run until the person submits. These are
  // DEFAULT executors — a host that passes its own `user_input` / `human_approval`
  // executor overrides them (host executors are spread last below).
  const [prompt, setPrompt] = useState<HumanPromptRequest | null>(null);
  const humanExecutors = useMemo<ExecutorRegistry>(
    () => ({
      user_input: ({ node }) =>
        new Promise((resolve) => {
          const cfg = (((node as any).data?.config ?? {}) as Record<string, unknown>);
          setPrompt({
            kind: "input",
            title: (typeof cfg.title === "string" && cfg.title) || "Your input",
            submitLabel: typeof cfg.submitLabel === "string" ? cfg.submitLabel : undefined,
            fields: humanInputFields(cfg),
            resolve: (values) => { setPrompt(null); resolve(values); },
          });
        }),
      human_approval: ({ node }) =>
        new Promise((resolve) => {
          const cfg = (((node as any).data?.config ?? {}) as Record<string, unknown>);
          setPrompt({
            kind: "approval",
            title: (typeof cfg.title === "string" && cfg.title) || "Approve action",
            description: typeof cfg.description === "string" ? cfg.description : undefined,
            resolve: (approved) => { setPrompt(null); resolve({ branch: approved ? "approved" : "denied" }); },
          });
        }),
    }),
    [],
  );
  const runExecutors = useMemo(() => ({ ...humanExecutors, ...executors }), [humanExecutors, executors]);
  // Close the modal if the run ends (finished or cancelled) while it's open.
  useEffect(() => {
    if (!runner.running) setPrompt(null);
  }, [runner.running]);

  // When `value` is provided we run in controlled mode: host owns nodes/edges,
  // local edits go through onChange. Internal state is unused but the hook
  // still has to run (rules of hooks).
  const controlled = value !== undefined;
  const baseFlow = controlled ? makeControlledFlowAdapter(value!, onChange) : internal;
  // Wrap the sink with the commit/undo pipeline — one interception point for
  // every committing mutation, whichever mode we're in.
  const hist = useFlowHistory(baseFlow);
  const flow = hist.flow;

  // Re-render when registry kinds change so the palette + nodeTypes reflect it.
  const [, force] = useState(0);
  useEffect(() => onNodeKindsChanged(() => force((n) => n + 1)), []);
  const nodeTypes = useMemo(() => buildNodeTypes(), [listNodeKinds().length]); // eslint-disable-line react-hooks/exhaustive-deps

  const renderedNodes = useMemo(
    () =>
      applyOutputsToNodes(
        applyStatusesToNodes(flow.nodes, runner.statuses, runner.statusText),
        runner.outputs,
      ),
    [flow.nodes, runner.statuses, runner.statusText, runner.outputs],
  );

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const selected = useMemo(() => flow.nodes.find((n) => n.id === selectedId) ?? null, [flow.nodes, selectedId]);

  useEffect(() => onSelectionChange?.(selected), [selected, onSelectionChange]);

  const [selectedEdgeId, setSelectedEdgeId] = useState<string | null>(null);
  const selectedEdge = useMemo(
    () => flow.edges.find((e: Edge) => e.id === selectedEdgeId) ?? null,
    [flow.edges, selectedEdgeId],
  );

  const handleNodeClick: NodeMouseHandler = (_e, node) => {
    setSelectedId(node.id);
    // Node and edge selection are mutually exclusive, so Delete is never
    // ambiguous about what it would remove.
    setSelectedEdgeId(null);
  };

  // Right-click menu, for a node OR a connection. Anchored in viewport coords
  // (position: fixed), so it is not clipped by the canvas' overflow.
  const [menu, setMenu] = useState<
    { x: number; y: number; target: { type: "node" | "edge"; id: string } } | null
  >(null);
  // Inline "label this connection" editor, anchored like the menu.
  const [labelEdit, setLabelEdit] = useState<{ x: number; y: number; edgeId: string } | null>(null);

  const closeMenu = useCallback(() => setMenu(null), []);

  const handleNodeContextMenu: NodeMouseHandler = (event, node) => {
    event.preventDefault();
    setSelectedId(node.id);
    setSelectedEdgeId(null);
    setMenu({ x: event.clientX, y: event.clientY, target: { type: "node", id: node.id } });
  };

  const handleEdgeClick = (_e: React.MouseEvent, edge: Edge) => {
    setSelectedEdgeId(edge.id);
  };

  const handleEdgeContextMenu = (event: React.MouseEvent, edge: Edge) => {
    event.preventDefault();
    setSelectedEdgeId(edge.id);
    setMenu({ x: event.clientX, y: event.clientY, target: { type: "edge", id: edge.id } });
  };

  // Dismiss on any outside click, scroll, or Escape.
  useEffect(() => {
    if (menu === null && labelEdit === null) return;
    const close = () => { setMenu(null); setLabelEdit(null); };
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && close();
    window.addEventListener("click", close);
    window.addEventListener("scroll", close, true);
    window.addEventListener("keydown", onKey);
    return () => {
      window.removeEventListener("click", close);
      window.removeEventListener("scroll", close, true);
      window.removeEventListener("keydown", onKey);
    };
  }, [menu, labelEdit]);

  // Editor keyboard shortcuts. Ignored while a field is focused, so Ctrl+Z does
  // native text-undo inside inputs/textareas rather than reverting the graph.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable)) return;
      if (!(e.ctrlKey || e.metaKey)) return;
      const key = e.key.toLowerCase();
      if (key === "z" && !e.shiftKey) {
        e.preventDefault();
        hist.undo();
      } else if ((key === "z" && e.shiftKey) || key === "y") {
        e.preventDefault();
        hist.redo();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [hist]);

  // Uncontrolled: notify host on every graph mutation. Controlled mode
  // already notifies via the adapter on each setNodes/setEdges call.
  useEffect(() => {
    if (!controlled) onChange?.({ nodes: flow.nodes, edges: flow.edges });
  }, [flow.nodes, flow.edges, onChange, controlled]);

  const addNode = useCallback(
    (kindName: string, position?: { x: number; y: number }): string | null => {
      const kind = getNodeKind(kindName);
      if (!kind) return null;
      const at = position ?? { x: 80, y: 80 };
      const id = newNodeId();
      flow.setNodes((all: FlowNode[]) => [
        ...all,
        {
          id,
          type: kind.name,
          position: at,
          data: { kind: kind.name, label: kind.label, config: defaultConfigFor(kind) } as any,
        } as FlowNode,
      ]);
      setSelectedId(id);
      return id;
    },
    [flow],
  );

  /** Delete nodes AND every edge attached to them — an orphaned edge would
   *  otherwise survive the node it connected. */
  const deleteNodes = useCallback(
    async (ids: string[]) => {
      if (ids.length === 0) return;
      const targets = flow.nodes.filter((n) => ids.includes(n.id));
      if (targets.length === 0) return;
      if (confirmDelete) {
        const attached = flow.edges.filter((e: Edge) => ids.includes(e.source) || ids.includes(e.target));
        if (!(await confirmDelete({ nodes: targets, edges: attached }))) return;
      }
      const doomed = new Set(ids);
      // Atomic: prune edges + remove nodes in ONE commit — one undo step, and
      // correct in controlled mode where two sequential writes would clobber.
      flow.setGraph(removeNodes({ nodes: flow.nodes, edges: flow.edges }, ids));
      setSelectedId((cur) => (cur !== null && doomed.has(cur) ? null : cur));
      onDelete?.(ids);
    },
    [flow, onDelete, confirmDelete],
  );

  const deleteEdges = useCallback(
    async (ids: string[]) => {
      if (ids.length === 0) return;
      const targets = flow.edges.filter((e: Edge) => ids.includes(e.id));
      if (targets.length === 0) return;
      if (confirmDelete && !(await confirmDelete({ nodes: [], edges: targets }))) return;
      flow.setEdges((all: Edge[]) => removeEdges(all, ids));
      setSelectedEdgeId((cur) => (cur !== null && ids.includes(cur) ? null : cur));
      onEdgeDelete?.(ids);
    },
    [flow, onEdgeDelete, confirmDelete],
  );

  // ── Multi-selection + clipboard (Release 2) ──
  // xyflow owns the real multi-selection (box / shift-click) on `node.selected`;
  // we read it rather than tracking a parallel list.
  const selectedNodes = useMemo(() => flow.nodes.filter((n) => n.selected), [flow.nodes]);
  const selectedIds = useMemo(() => selectedNodes.map((n) => n.id), [selectedNodes]);

  const clipboard = useRef<FlowGraph | null>(null);

  const copySelection = useCallback(() => {
    const sel = flow.nodes.filter((n) => n.selected);
    if (sel.length === 0) return;
    const ids = new Set(sel.map((n) => n.id));
    const edges = flow.edges.filter((e: Edge) => ids.has(e.source) && ids.has(e.target));
    clipboard.current = { nodes: sel.map((n) => ({ ...n })), edges: edges.map((e) => ({ ...e })) };
  }, [flow]);

  const pasteClipboard = useCallback(
    (at?: { x: number; y: number }) => {
      const clip = clipboard.current;
      if (!clip || clip.nodes.length === 0) return;
      const { nodes: clones, edges: cloneEdges } = cloneSubgraph(clip.nodes, clip.edges, { makeId: newNodeId, offset: 40 });
      let placed = clones;
      if (at) {
        const minX = Math.min(...clones.map((n) => n.position.x));
        const minY = Math.min(...clones.map((n) => n.position.y));
        placed = clones.map((n) => ({ ...n, position: { x: n.position.x - minX + at.x, y: n.position.y - minY + at.y } }));
      }
      flow.setGraph({
        nodes: [...flow.nodes.map((n) => ({ ...n, selected: false })), ...placed.map((n) => ({ ...n, selected: true }))],
        edges: [...flow.edges, ...cloneEdges],
      });
    },
    [flow],
  );

  const duplicateSelected = useCallback(() => {
    const sel = flow.nodes.filter((n) => n.selected);
    if (sel.length === 0) return;
    const ids = new Set(sel.map((n) => n.id));
    const internal = flow.edges.filter((e: Edge) => ids.has(e.source) && ids.has(e.target));
    const { nodes: clones, edges: cloneEdges } = cloneSubgraph(sel, internal, { makeId: newNodeId, offset: 40 });
    flow.setGraph({
      nodes: [...flow.nodes.map((n) => ({ ...n, selected: false })), ...clones.map((n) => ({ ...n, selected: true }))],
      edges: [...flow.edges, ...cloneEdges],
    });
  }, [flow]);

  const alignSelected = useCallback(
    (edge: AlignEdge) => {
      const sel = flow.nodes.filter((n) => n.selected);
      if (sel.length < 2) return;
      const byId = new Map(alignNodes(sel, edge).map((n) => [n.id, n] as const));
      flow.setNodes((all: FlowNode[]) => all.map((n) => byId.get(n.id) ?? n));
    },
    [flow],
  );

  const distributeSelected = useCallback(
    (axis: "h" | "v") => {
      const sel = flow.nodes.filter((n) => n.selected);
      if (sel.length < 3) return;
      const byId = new Map(distributeNodes(sel, axis).map((n) => [n.id, n] as const));
      flow.setNodes((all: FlowNode[]) => all.map((n) => byId.get(n.id) ?? n));
    },
    [flow],
  );

  const onReconnect = useCallback(
    (oldEdge: Edge, conn: Connection) => flow.setEdges((eds: Edge[]) => reconnectEdge(eds, oldEdge, conn)),
    [flow],
  );

  // ── Swimlanes (Release 4) ──
  const isLaneNode = useCallback(
    (n: FlowNode) => getNodeKind((n.data as any)?.kind ?? n.type)?.category === "layout",
    [],
  );

  const addLane = useCallback(
    (orientation: "horizontal" | "vertical" = "horizontal", title?: string): string => {
      const vertical = orientation === "vertical";
      const lanes = flow.nodes.filter(isLaneNode);
      const w = vertical ? 280 : 680;
      const h = vertical ? 480 : 168;
      const end = lanes.reduce(
        (m, l) =>
          Math.max(m, vertical ? l.position.x + ((l as any).width ?? w) : l.position.y + ((l as any).height ?? h)),
        0,
      );
      const id = newNodeId();
      const name = title ?? `Lane ${lanes.length + 1}`;
      const node = {
        id,
        type: "@particle-academy/lane",
        position: vertical ? { x: lanes.length ? end + 12 : 0, y: 0 } : { x: 0, y: lanes.length ? end + 12 : 0 },
        width: w,
        height: h,
        data: { kind: "@particle-academy/lane", label: name, config: { title: name, orientation } } as any,
      } as FlowNode;
      flow.setNodes((all: FlowNode[]) => [...all, node]);
      setSelectedId(id);
      return id;
    },
    [flow, isLaneNode],
  );

  // Drop a node onto a lane to file it there; drag it out to unfile it.
  const handleNodeDragStop = useCallback(
    (_e: MouseEvent | TouchEvent, node: FlowNode) => {
      if (isLaneNode(node)) return; // v1: lanes don't nest inside lanes
      const overLane = rf.getIntersectingNodes(node).find((n) => isLaneNode(n as FlowNode));
      const currentParent = (node as any).parentId as string | undefined;
      if (overLane && overLane.id !== currentParent) {
        flow.setNodes((all: FlowNode[]) => assignToLaneOp(all, node.id, overLane.id));
      } else if (!overLane && currentParent) {
        flow.setNodes((all: FlowNode[]) => removeFromLaneOp(all, node.id));
      }
    },
    [rf, flow, isLaneNode],
  );

  // Clipboard + duplicate shortcuts. (Undo/redo live in the effect above.)
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable)) return;
      if (!(e.ctrlKey || e.metaKey)) return;
      const key = e.key.toLowerCase();
      if (key === "c") copySelection();
      else if (key === "x") {
        e.preventDefault();
        copySelection();
        deleteNodes(selectedIds);
      } else if (key === "v") {
        e.preventDefault();
        pasteClipboard();
      } else if (key === "d") {
        e.preventDefault();
        duplicateSelected();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [copySelection, pasteClipboard, duplicateSelected, deleteNodes, selectedIds]);

  const api: FlowEditorApi = useMemo(() => {
    const toWorkflow = () => exportWorkflow({ nodes: flow.nodes, edges: flow.edges }, metadata);

    return {
      graph: { nodes: flow.nodes, edges: flow.edges },
      nodes: flow.nodes,
      edges: flow.edges,
      selectedId,
      selected,
      selectedEdgeId,
      selectedEdge,
      selectedIds,
      selectedNodes,
      running: runner.running,
      statuses: runner.statuses,

      select: setSelectedId,
      selectEdge: setSelectedEdgeId,

      addNode,
      updateNode: (next) => flow.setNodes((all: FlowNode[]) => all.map((x) => (x.id === next.id ? next : x))),
      deleteNodes,
      deleteSelected: () => deleteNodes(selectedId ? [selectedId] : []),
      deleteEdges,
      deleteSelectedEdge: () => deleteEdges(selectedEdgeId ? [selectedEdgeId] : []),
      setEdgeLabel: (id, label) => flow.setEdges((all: Edge[]) => setEdgeLabel(all, id, label)),
      duplicateNode: (id) => {
        const src = flow.nodes.find((n) => n.id === id);
        if (!src) return null;
        const copy = cloneNode(src, newNodeId());
        flow.setNodes((all: FlowNode[]) => [...all, copy]);
        setSelectedId(copy.id);
        return copy.id;
      },
      setGraph: (graph) => flow.setGraph(graph),

      duplicateSelected,
      alignSelected,
      distributeSelected,
      copy: copySelection,
      cut: () => {
        copySelection();
        deleteNodes(selectedIds);
      },
      paste: pasteClipboard,

      addLane,
      assignToLane: (nodeId, laneId) => flow.setNodes((all: FlowNode[]) => assignToLaneOp(all, nodeId, laneId)),
      removeFromLane: (nodeId) => flow.setNodes((all: FlowNode[]) => removeFromLaneOp(all, nodeId)),
      // dagre is loaded lazily so it stays out of the eager bundle — consumers
      // who never tidy pay nothing for it.
      autoLayout: (opts) => {
        void import("../lib/layout").then(({ autoLayout }) =>
          flow.setGraph({ nodes: autoLayout({ nodes: flow.nodes, edges: flow.edges }, opts), edges: flow.edges }),
        );
      },
      tidyLane: (laneId) => {
        void import("../lib/layout").then(({ autoLayout }) =>
          flow.setGraph({ nodes: autoLayout({ nodes: flow.nodes, edges: flow.edges }, { scope: laneId }), edges: flow.edges }),
        );
      },

      run: () => runner.run({ nodes: flow.nodes, edges: flow.edges }, runExecutors),
      cancel: runner.cancel,
      reset: runner.reset,

      toWorkflow,
      exportWorkflow: () => downloadWorkflow(toWorkflow(), metadata),
      importWorkflow: () => pickWorkflow((graph) => flow.setGraph(graph)),

      fitView: () => rf.fitView({ padding: 0.2 }),

      undo: hist.undo,
      redo: hist.redo,
      canUndo: hist.canUndo,
      canRedo: hist.canRedo,
    };
  }, [flow, selectedId, selected, selectedEdgeId, selectedEdge, selectedIds, selectedNodes, runner, runExecutors, metadata, addNode, deleteNodes, deleteEdges, duplicateSelected, alignSelected, distributeSelected, copySelection, pasteClipboard, addLane, hist, rf]);

  useImperativeHandle(apiRef, () => api, [api]);

  const dropHandlers = paletteDropHandlers((kindName, evt) => {
    const point = rf.screenToFlowPosition({ x: evt.clientX, y: evt.clientY });
    addNode(kindName, { x: point.x - 100, y: point.y - 30 });
  });

  const startActions = actions.filter((a) => a.placement === "start");
  const endActions = actions.filter((a) => a.placement !== "start");

  const toolbar = slots.toolbar ? (
    slots.toolbar(api)
  ) : (
    <>
      {startActions.map((a) => renderAction(a, api))}
      {builtins.run !== false && (
        <FlowRunControls running={api.running} onRun={api.run} onCancel={api.cancel} onReset={api.reset} />
      )}
      {builtins.history !== false && (
        <>
          <span className="ff-editor__sep" />
          <button
            className="ff-editor__btn"
            data-action="undo"
            title="Undo (Ctrl+Z)"
            disabled={!api.canUndo}
            onClick={api.undo}
          >
            ↶ Undo
          </button>
          <button
            className="ff-editor__btn"
            data-action="redo"
            title="Redo (Ctrl+Shift+Z)"
            disabled={!api.canRedo}
            onClick={api.redo}
          >
            ↷ Redo
          </button>
        </>
      )}
      {builtins.addLane !== false && (
        <>
          <span className="ff-editor__sep" />
          <button className="ff-editor__btn" data-action="add-lane" title="Add a swimlane" onClick={() => api.addLane()}>
            ▤ Lane
          </button>
        </>
      )}
      {builtins.autoLayout !== false && (
        <button className="ff-editor__btn" data-action="auto-layout" title="Tidy — auto-arrange" onClick={() => api.autoLayout()}>
          ⤢ Tidy
        </button>
      )}
      {(builtins.export !== false || builtins.import !== false) && (
        <span className="ff-editor__sep" />
      )}
      {/* Node deletion is not a toolbar button — it lives in NodeConfigPanel
          (see below), so the affordance is a property of the reusable panel
          rather than duplicated chrome that drifts. Keyboard Del/Backspace and
          the right-click menu still delete. `builtins.delete` gates the panel
          button. */}
      {builtins.export !== false && (
        <button className="ff-editor__btn" data-action="export" onClick={api.exportWorkflow}>↓ Export</button>
      )}
      {builtins.import !== false && (
        <button className="ff-editor__btn" data-action="import" onClick={api.importWorkflow}>↑ Import</button>
      )}
      {endActions.map((a) => renderAction(a, api))}
      {extraToolbar}
      {builtins.count !== false && (
        <span className="ff-editor__count">{api.nodes.length} nodes · {api.edges.length} edges</span>
      )}
    </>
  );

  return (
    <FlowEditorProvider value={api}>
      {showPalette &&
        (slots.palette ? (
          slots.palette(api)
        ) : (
          <NodePalette className="ff-editor__palette" kindFilter={kindFilter} />
        ))}
      <div className="ff-editor__main" {...dropHandlers}>
        <FlowCanvas
          nodes={renderedNodes}
          edges={flow.edges}
          nodeTypes={nodeTypes}
          onNodesChange={flow.onNodesChange}
          onEdgesChange={flow.onEdgesChange}
          onConnect={flow.onConnect}
          // Drag an edge endpoint to rewire it; the new endpoint is validated by
          // the same isValidConnection rule (G2), so a bad reconnect is refused.
          onReconnect={onReconnect}
          edgesReconnectable
          // Snapshot the pre-drag graph once so a drag is a single undo step.
          onNodeDragStart={hist.onNodeDragStart}
          // Drop a node onto a lane to file it there (or drag it out to unfile).
          onNodeDragStop={handleNodeDragStop}
          onNodeClick={handleNodeClick}
          onNodeContextMenu={builtins.contextMenu === false ? undefined : handleNodeContextMenu}
          onEdgeClick={handleEdgeClick}
          onEdgeContextMenu={builtins.edgeContextMenu === false ? undefined : handleEdgeContextMenu}
          onEdgesDelete={(deleted: Edge[]) => onEdgeDelete?.(deleted.map((e) => e.id))}
          onNodesDelete={(deleted) => onDelete?.(deleted.map((n) => n.id))}
          // Stage the native (keyboard) delete path when a confirm gate is wired.
          onBeforeDelete={
            confirmDelete
              ? async ({ nodes, edges }) => confirmDelete({ nodes: nodes as FlowNode[], edges })
              : undefined
          }
          // Both keys delete, so muscle memory from either platform works.
          deleteKeyCode={["Delete", "Backspace"]}
          height="100%"
          toolbar={toolbar}
          {...canvasProps}
        />
        {slots.empty && api.nodes.length === 0 && (
          <div className="ff-editor__empty">{slots.empty(api)}</div>
        )}
        {menu?.target.type === "node" && builtins.contextMenu !== false && (
          <div
            className="ff-editor__ctx"
            style={{ top: menu.y, left: menu.x }}
            role="menu"
            // Keep the outside-click listener from closing us before the click lands.
            onClick={(e) => e.stopPropagation()}
          >
            {slots.contextMenu ? (
              slots.contextMenu(api, menu.target.id, closeMenu)
            ) : (
              <>
                <button
                  type="button"
                  role="menuitem"
                  className="ff-editor__ctx-item"
                  data-action="ctx-duplicate"
                  onClick={() => { api.duplicateNode(menu.target.id); closeMenu(); }}
                >
                  Duplicate
                </button>
                <button
                  type="button"
                  role="menuitem"
                  className="ff-editor__ctx-item ff-editor__ctx-item--danger"
                  data-action="ctx-delete"
                  onClick={() => { api.deleteNodes([menu.target.id]); closeMenu(); }}
                >
                  Delete
                </button>
              </>
            )}
          </div>
        )}

        {menu?.target.type === "edge" && builtins.edgeContextMenu !== false && (
          <div
            className="ff-editor__ctx"
            style={{ top: menu.y, left: menu.x }}
            role="menu"
            onClick={(e) => e.stopPropagation()}
          >
            {slots.edgeContextMenu ? (
              slots.edgeContextMenu(api, menu.target.id, closeMenu)
            ) : (
              <>
                <button
                  type="button"
                  role="menuitem"
                  className="ff-editor__ctx-item"
                  data-action="ctx-edge-label"
                  onClick={() => {
                    setLabelEdit({ x: menu.x, y: menu.y, edgeId: menu.target.id });
                    setMenu(null);
                  }}
                >
                  Label…
                </button>
                <button
                  type="button"
                  role="menuitem"
                  className="ff-editor__ctx-item ff-editor__ctx-item--danger"
                  data-action="ctx-edge-delete"
                  onClick={() => { api.deleteEdges([menu.target.id]); closeMenu(); }}
                >
                  Delete connection
                </button>
              </>
            )}
          </div>
        )}

        {labelEdit !== null && (
          <EdgeLabelEditor
            x={labelEdit.x}
            y={labelEdit.y}
            initial={
              (flow.edges.find((e: Edge) => e.id === labelEdit.edgeId)?.label as string | undefined) ?? ""
            }
            onCommit={(text) => {
              api.setEdgeLabel(labelEdit.edgeId, text);
              setLabelEdit(null);
            }}
            onCancel={() => setLabelEdit(null)}
          />
        )}
        {showFeed &&
          (slots.feed ? slots.feed(api) : <FlowRunFeed entries={runner.feed} running={api.running} className="ff-editor__feed" />)}
        {prompt && (
          <HumanPrompt
            request={prompt}
            onCancel={() => { setPrompt(null); runner.cancel(); }}
            fieldRenderers={humanFieldRenderers}
          />
        )}
      </div>
      {showPanel &&
        (slots.panel ? (
          slots.panel(api)
        ) : (
          <div className="ff-editor__panel-wrap">
            <NodeConfigPanel
              className="ff-editor__panel"
              node={api.selected}
              onChange={api.updateNode}
              fieldRenderers={fieldRenderers}
              fieldFilter={fieldFilter}
              // The editor already holds the graph; passing it is what turns the
              // {{ }} picker from a static list into a context-aware one.
              graph={flow}
              // The delete affordance lives IN the panel (one source of truth),
              // not a private FlowEditor toolbar button — so a dev composing
              // their own editor from NodeConfigPanel gets it for free.
              onDelete={builtins.delete === false ? undefined : (n) => api.deleteNodes([n.id])}
            />
            {slots.panelFooter && <div className="ff-editor__panel-footer">{slots.panelFooter(api)}</div>}
          </div>
        ))}
    </FlowEditorProvider>
  );
}

function renderAction(action: FlowEditorAction, api: FlowEditorApi) {
  if (action.visible && !action.visible(api)) return null;
  const disabled = action.disabled ? action.disabled(api) : action.requiresSelection === true && api.selected === null;
  return (
    <button
      key={action.id}
      className="ff-editor__btn"
      data-action={action.id}
      title={action.title}
      disabled={disabled}
      onClick={() => action.onSelect(api)}
    >
      {action.label}
    </button>
  );
}

function newNodeId(): string {
  return `n_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
}

function downloadWorkflow(schema: WorkflowSchema, metadata?: WorkflowMetadata) {
  const url = URL.createObjectURL(workflowToBlob(schema));
  const a = document.createElement("a");
  a.href = url;
  a.download = `${metadata?.id ?? "workflow"}.json`;
  a.click();
  URL.revokeObjectURL(url);
}

function pickWorkflow(onLoad: (graph: FlowGraph) => void) {
  const input = document.createElement("input");
  input.type = "file";
  input.accept = "application/json";
  input.onchange = async () => {
    const file = input.files?.[0];
    if (!file) return;
    try {
      loadImportedWorkflow(importWorkflow(JSON.parse(await file.text()), { lenient: true }), onLoad);
    } catch (e) {
      console.error("import failed", e);
    }
  };
  input.click();
}

/**
 * Hand an imported graph to the editor unless the import REFUSED the document.
 *
 * A refused import (not an object, or not `version: 1`, which `lenient` never
 * softens) is `ok: false` with an EMPTY graph. Loading it would replace
 * whatever the person had on the canvas with nothing, so the refusal is logged
 * and the canvas left alone.
 *
 * `ok: false` alone is not a refusal. A graph that was read but carries an
 * error (a node wired to nothing, say) still loads, as it always has: the
 * editor is where that gets fixed.
 *
 * @internal exported for tests
 */
export function loadImportedWorkflow(result: ImportResult, onLoad: (graph: FlowGraph) => void): boolean {
  if (!result.ok && result.graph.nodes.length === 0 && result.graph.edges.length === 0) {
    console.error("import refused", result.issues);
    return false;
  }
  onLoad(result.graph);
  return true;
}

/**
 * Build a UseFlowStateReturn-shaped adapter that proxies through to the
 * host's onChange. Edits route through onChange; reads come from `value`.
 */
function makeControlledFlowAdapter(
  value: FlowGraph,
  onChange?: (graph: FlowGraph) => void,
): UseFlowStateReturn {
  const apply = (next: FlowGraph) => onChange?.(next);
  return {
    nodes: value.nodes,
    edges: value.edges,
    setNodes: (next) => {
      const nextNodes = typeof next === "function" ? (next as any)(value.nodes) : next;
      apply({ nodes: nextNodes, edges: value.edges });
    },
    setEdges: (next) => {
      const nextEdges = typeof next === "function" ? (next as any)(value.edges) : next;
      apply({ nodes: value.nodes, edges: nextEdges });
    },
    // Atomic both-at-once commit — the reason this exists (see UseFlowStateReturn).
    setGraph: (graph) => apply(graph),
    onNodesChange: (changes) => {
      apply({ nodes: applyNodeChanges(changes, value.nodes) as any, edges: value.edges });
    },
    onEdgesChange: (changes) => {
      apply({ nodes: value.nodes, edges: applyEdgeChanges(changes, value.edges) });
    },
    onConnect: (connection: Connection) => {
      apply({ nodes: value.nodes, edges: addEdge(connection, value.edges) as Edge[] });
    },
    toGraph: () => value,
  };
}

/**
 * EdgeLabelEditor — small popover for naming a connection.
 *
 * Anchored in viewport coords like the context menu it replaces. Enter
 * commits, Escape cancels, blur commits (so clicking away doesn't silently
 * discard the edit).
 */
function EdgeLabelEditor({
  x,
  y,
  initial,
  onCommit,
  onCancel,
}: {
  x: number;
  y: number;
  initial: string;
  onCommit: (text: string) => void;
  onCancel: () => void;
}) {
  const [text, setText] = useState(initial);
  const ref = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    ref.current?.focus();
    ref.current?.select();
  }, []);

  return (
    <div
      className="ff-editor__ctx ff-editor__edge-label"
      style={{ top: y, left: x }}
      onClick={(e) => e.stopPropagation()}
    >
      <input
        ref={ref}
        className="ff-panel__input"
        value={text}
        placeholder="Label this connection"
        aria-label="Connection label"
        data-action="edge-label-input"
        onChange={(e) => setText(e.target.value)}
        onKeyDown={(e) => {
          // Stop the canvas seeing these — Backspace would delete the edge
          // out from under the editor.
          e.stopPropagation();
          if (e.key === "Enter") onCommit(text);
          if (e.key === "Escape") onCancel();
        }}
        onBlur={() => onCommit(text)}
      />
    </div>
  );
}

import { useEffect, useId, useRef, useState } from "react";
import type { ReactNode } from "react";
import type { HumanField, HumanFieldType } from "./human-fields";

/** What a host renderer is handed for one field. */
export type HumanFieldRenderContext = {
  field: HumanField;
  /** The id the field's `<label>` points at — put it on your control. */
  id: string;
  value: unknown;
  onChange: (v: unknown) => void;
  /** Present only on the first field; attach it so the modal autofocuses. */
  autoFocusRef?: React.RefObject<HTMLElement | null>;
};

/**
 * Render one field, or return `null` to decline it.
 *
 * `null` means "not mine" and falls through to the built-in control. That is
 * what makes a PARTIAL map safe to spread: a host handing over someone else's
 * renderers does not silently lose every type that map does not cover.
 */
export type HumanFieldRenderFn = (ctx: HumanFieldRenderContext) => ReactNode | null;

/**
 * Host overrides for pause-form controls, keyed by CANONICAL field type
 * (`"switch"`, not `"boolean"` — aliases are normalised before the lookup, so
 * one entry covers every spelling of that type).
 *
 * The built-ins are deliberately native `--ff-*`-themed elements rather than
 * react-fancy primitives: react-fancy is an OPTIONAL peer and this modal ships
 * in the main entry, so importing it here would break a standalone install and
 * bypass the token layer a host themes `.ff-editor` with. This seam is how a
 * host that HAS react-fancy gets Fancy controls anyway —
 * `@particle-academy/fancy-flow/fields/react-fancy` exports a ready map.
 */
export type HumanFieldRenderers = Partial<Record<HumanFieldType, HumanFieldRenderFn>>;

/** What the modal was asked to collect — a form, or a yes/no decision. */
export type HumanPromptRequest =
  | { kind: "input"; title: string; submitLabel?: string; fields: HumanField[]; resolve: (values: Record<string, unknown>) => void }
  | { kind: "approval"; title: string; description?: string; resolve: (approved: boolean) => void };

export {
  humanInputFields,
  humanFieldType,
  humanFieldOptions,
  HUMAN_FIELD_TYPE_ALIASES,
  type HumanField,
  type HumanFieldType,
  type HumanFieldOption,
} from "./human-fields";

/** The `<input type>` each canonical field renders with. */
const INPUT_TYPE: Partial<Record<HumanFieldType, string>> = {
  text: "text",
  number: "number",
  date: "date",
  datetime: "datetime-local",
  time: "time",
  email: "email",
  url: "url",
  tel: "tel",
  password: "password",
};

/**
 * The value a field starts on, in the type the field will resolve in.
 *
 * A switch starts `false` rather than `""` so the submitted value is a boolean
 * whether or not the person touched it — a form that returns `""` for an
 * untouched checkbox and `true` for a touched one hands the next node two
 * different types for the same field.
 */
function initialValues(fields: HumanField[]): Record<string, unknown> {
  const v: Record<string, unknown> = {};
  for (const f of fields) {
    if (f.type === "switch") {
      v[f.key] = !!f.default;
    } else if (f.type === "number") {
      v[f.key] = typeof f.default === "number" ? f.default : f.default === undefined || f.default === "" ? "" : Number(f.default);
    } else {
      v[f.key] = f.default ?? "";
    }
  }
  return v;
}

/**
 * The in-editor human-input modal. When a run reaches a `user_input` or
 * `human_approval` node, FlowEditor's default executor opens this and BLOCKS the
 * run (the executor returns a Promise) until the person submits — the same
 * async-executor pattern the headless engine already supports. A host that
 * passes its own `user_input` / `human_approval` executor overrides this.
 *
 * ## Why the controls are native elements and not react-fancy primitives
 *
 * Same reason the config panel's are, and it is a hard constraint rather than a
 * preference: `@particle-academy/react-fancy` is an OPTIONAL peer of this
 * package (`peerDependenciesMeta`) and is listed `external` in `tsup.config.ts`.
 * This file ships in the main `.` entry, so importing react-fancy here would
 * make a standalone `npm install @particle-academy/fancy-flow` fail to resolve
 * at import time — and it would break the `--ff-*` token layer a host overrides
 * on `.ff-editor`, because react-fancy's primitives are hardcoded Tailwind
 * palette classes that read no custom properties. See the docblock on
 * `src/fields/react-fancy.tsx` and the one on `tests/panel-labels.test.tsx`.
 *
 * A host that wants react-fancy controls here already has the seam: pass its
 * own `user_input` executor to `<FlowEditor executors={…}>` and render whatever
 * it likes. Host executors are spread last, so they win.
 */

export function HumanPrompt({
  request,
  onCancel,
  fieldRenderers,
}: {
  request: HumanPromptRequest;
  onCancel: () => void;
  fieldRenderers?: HumanFieldRenderers;
}) {
  const firstRef = useRef<HTMLElement | null>(null);
  useEffect(() => {
    firstRef.current?.focus();
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onCancel(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onCancel]);

  return (
    <div className="ff-prompt-overlay" role="dialog" aria-modal="true" aria-label={request.title}>
      <div className="ff-prompt" onClick={(e) => e.stopPropagation()}>
        <div className="ff-prompt__title">{request.title}</div>
        {request.kind === "approval" ? (
          <ApprovalBody request={request} onCancel={onCancel} />
        ) : (
          <InputBody request={request} onCancel={onCancel} firstRef={firstRef} fieldRenderers={fieldRenderers} />
        )}
      </div>
    </div>
  );
}

function ApprovalBody({ request, onCancel }: { request: Extract<HumanPromptRequest, { kind: "approval" }>; onCancel: () => void }) {
  return (
    <>
      {request.description && <p className="ff-prompt__desc">{request.description}</p>}
      <div className="ff-prompt__actions">
        <button type="button" className="ff-prompt__btn ff-prompt__btn--ghost" onClick={onCancel}>Cancel</button>
        <button type="button" className="ff-prompt__btn ff-prompt__btn--danger" onClick={() => request.resolve(false)}>Deny</button>
        <button type="button" className="ff-prompt__btn ff-prompt__btn--primary" onClick={() => request.resolve(true)}>Approve</button>
      </div>
    </>
  );
}

function InputBody({
  request,
  onCancel,
  firstRef,
  fieldRenderers,
}: {
  request: Extract<HumanPromptRequest, { kind: "input" }>;
  onCancel: () => void;
  firstRef: React.RefObject<HTMLElement | null>;
  fieldRenderers?: HumanFieldRenderers;
}) {
  const [values, setValues] = useState<Record<string, unknown>>(() => initialValues(request.fields));
  const set = (k: string, v: unknown) => setValues((prev) => ({ ...prev, [k]: v }));

  // Ids are scoped to this modal instance so two prompts on one page — a split
  // view, a comparison — never share an id and make one label focus the other's
  // control. Keyed by the FIELD, not its position, so an agent that stored
  // `data-ff-field="email"` still finds it after the schema is reordered.
  const uid = useId();
  const fieldId = (key: string) => `${uid}-${key}`;

  const missing = request.fields.filter((f) => f.required && (values[f.key] === undefined || values[f.key] === ""));
  const submit = () => { if (missing.length === 0) request.resolve(values); };

  return (
    <form
      onSubmit={(e) => { e.preventDefault(); submit(); }}
      onKeyDown={(e) => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) { e.preventDefault(); submit(); } }}
    >
      <div className="ff-prompt__fields">
        {request.fields.map((f, i) => (
          <div key={f.key} className="ff-prompt__field">
            <label className="ff-prompt__label" htmlFor={fieldId(f.key)}>
              {f.label ?? f.key}
              {/* aria-hidden so the field is announced "Email", not "Email star". */}
              {f.required && <span className="ff-prompt__req" aria-hidden="true"> *</span>}
            </label>
            <FieldControl
              field={f}
              id={fieldId(f.key)}
              value={values[f.key]}
              onChange={(v) => set(f.key, v)}
              autoFocusRef={i === 0 ? firstRef : undefined}
              renderers={fieldRenderers}
            />
          </div>
        ))}
      </div>
      <div className="ff-prompt__actions">
        <button type="button" className="ff-prompt__btn ff-prompt__btn--ghost" onClick={onCancel}>Cancel</button>
        <button type="submit" className="ff-prompt__btn ff-prompt__btn--primary" disabled={missing.length > 0}>
          {request.submitLabel || "Continue"}
        </button>
      </div>
    </form>
  );
}

/**
 * One control, chosen by the field's canonical type.
 *
 * Every branch is controlled (`value` + `onChange`) and carries the same two
 * handles — the `id` its label points at, and `data-ff-field` keyed by the
 * field — because this modal is a Human+ surface an agent drives through an
 * MCP bridge rather than by guessing at the DOM.
 */
function FieldControl({
  field,
  id,
  value,
  onChange,
  autoFocusRef,
  renderers,
}: {
  field: HumanField;
  id: string;
  value: unknown;
  onChange: (v: unknown) => void;
  autoFocusRef?: React.RefObject<HTMLElement | null>;
  renderers?: HumanFieldRenderers;
}) {
  // A host override wins, but only if it actually renders something. `null`
  // is the documented way to decline a field, so a partial map falls through
  // to the built-in below instead of leaving an empty row where a control
  // belongs -- which would read as a rendering bug rather than a seam working.
  const override = renderers?.[field.type ?? "text"];
  if (override) {
    const rendered = override({ field, id, value, onChange, autoFocusRef });
    if (rendered !== null && rendered !== undefined) return <>{rendered}</>;
  }

  const handle = { id, "data-ff-field": field.key } as const;

  if (field.type === "textarea") {
    return (
      <textarea
        {...handle}
        className="ff-prompt__input"
        placeholder={field.placeholder}
        ref={autoFocusRef as React.RefObject<HTMLTextAreaElement> | undefined}
        rows={3}
        value={String(value ?? "")}
        onChange={(e) => onChange(e.target.value)}
      />
    );
  }

  if (field.type === "switch") {
    return (
      <input
        {...handle}
        type="checkbox"
        className="ff-prompt__switch"
        ref={autoFocusRef as React.RefObject<HTMLInputElement> | undefined}
        checked={!!value}
        onChange={(e) => onChange(e.target.checked)}
      />
    );
  }

  if (field.type === "select") {
    // A select stays a select even with nothing to choose. Falling through to a
    // text box — which is what used to happen — hid the authoring mistake AND
    // collected an unconstrained string for a field whose whole point is that
    // the downstream node gets one of a fixed set.
    const options = field.options ?? [];
    return (
      <select
        {...handle}
        className="ff-prompt__input"
        ref={autoFocusRef as React.RefObject<HTMLSelectElement> | undefined}
        value={String(value ?? "")}
        onChange={(e) => onChange(e.target.value)}
      >
        <option value="" disabled>{options.length ? "Choose…" : "No choices configured"}</option>
        {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
      </select>
    );
  }

  return (
    <input
      {...handle}
      className="ff-prompt__input"
      placeholder={field.placeholder}
      ref={autoFocusRef as React.RefObject<HTMLInputElement> | undefined}
      type={INPUT_TYPE[field.type ?? "text"] ?? "text"}
      value={String(value ?? "")}
      onChange={(e) =>
        onChange(field.type === "number" ? (e.target.value === "" ? "" : Number(e.target.value)) : e.target.value)
      }
    />
  );
}

import { createContext, useContext } from "react";
import type { ReactNode } from "react";
import type { Edge } from "@xyflow/react";
import type { FlowGraph, FlowNode, NodeRunStatus } from "../lib/types";
import type { WorkflowSchema } from "../lib/schema";
import type { AlignEdge } from "./graph-ops";
import type { AutoLayoutOptions } from "../lib/layout";

/**
 * Everything the editor knows and can do, handed to every extension point.
 *
 * This is the seam that makes `<FlowEditor>` composable instead of fixed: it is
 * passed to custom actions and slots, returned from `useFlowEditor()` inside
 * any child, and exposed on the editor `ref` so a host can drive the editor
 * imperatively (or an MCP bridge can drive it for an agent).
 */
export type FlowEditorApi = {
  // ── State ────────────────────────────────────────────────────────────
  /** The current graph. */
  graph: FlowGraph;
  nodes: FlowNode[];
  edges: Edge[];
  /** Currently selected node id, or null. */
  selectedId: string | null;
  /** Currently selected node, or null. */
  selected: FlowNode | null;
  /** Currently selected edge id, or null. Independent of node selection. */
  selectedEdgeId: string | null;
  /** Currently selected edge, or null. */
  selectedEdge: Edge | null;
  /** All multi-selected node ids (xyflow box / shift selection). */
  selectedIds: string[];
  /** All multi-selected nodes. */
  selectedNodes: FlowNode[];
  /** True while a run is in flight. */
  running: boolean;
  /** Per-node run status, keyed by node id. */
  statuses: Record<string, NodeRunStatus>;

  // ── Selection ────────────────────────────────────────────────────────
  select: (id: string | null) => void;
  /** Select an edge (the connection between two nodes), or clear with null. */
  selectEdge: (id: string | null) => void;

  // ── Graph mutation ───────────────────────────────────────────────────
  /** Add a node of `kind` at an optional flow position. Returns the new id. */
  addNode: (kind: string, position?: { x: number; y: number }) => string | null;
  /** Replace one node (matched by id). */
  updateNode: (node: FlowNode) => void;
  /** Delete nodes by id, pruning every edge attached to them. */
  deleteNodes: (ids: string[]) => void;
  /** Delete the current selection (no-op when nothing is selected). */
  deleteSelected: () => void;
  /** Delete edges by id — i.e. break the connections between nodes. */
  deleteEdges: (ids: string[]) => void;
  /** Delete the selected edge (no-op when no edge is selected). */
  deleteSelectedEdge: () => void;
  /** Label a connection, or clear the label by passing undefined/"". */
  setEdgeLabel: (id: string, label: string | undefined) => void;
  /** Copy a node (offset slightly) and select the copy. Returns the new id. */
  duplicateNode: (id: string) => string | null;
  /** Replace the whole graph. */
  setGraph: (graph: FlowGraph) => void;

  // ── Bulk (multi-selection) ───────────────────────────────────────────
  /** Duplicate the current multi-selection, preserving edges between them. */
  duplicateSelected: () => void;
  /** Align the multi-selection to a shared edge/center of its bounding box. */
  alignSelected: (edge: AlignEdge) => void;
  /** Evenly distribute the multi-selection's gaps along an axis (needs 3+). */
  distributeSelected: (axis: "h" | "v") => void;

  // ── Swimlanes ────────────────────────────────────────────────────────
  /** Add a swimlane, stacked with existing lanes. Returns the new lane id. */
  addLane: (orientation?: "horizontal" | "vertical", title?: string) => string | null;
  /** Put a node inside a lane (sets parentId + a lane-relative position). */
  assignToLane: (nodeId: string, laneId: string) => void;
  /** Remove a node from its lane (restores its absolute position). */
  removeFromLane: (nodeId: string) => void;
  /** Auto-arrange the graph (or a lane's children) into a tidy DAG layout. */
  autoLayout: (options?: AutoLayoutOptions) => void;
  /** Tidy just one lane's children. */
  tidyLane: (laneId: string) => void;

  // ── Clipboard ────────────────────────────────────────────────────────
  /** Copy the current selection to the editor clipboard. */
  copy: () => void;
  /** Copy then delete the current selection. */
  cut: () => void;
  /** Paste the clipboard (optionally at a flow position) and select the result. */
  paste: (at?: { x: number; y: number }) => void;

  // ── Run ──────────────────────────────────────────────────────────────
  run: () => void;
  cancel: () => void;
  reset: () => void;

  // ── Workflow I/O ─────────────────────────────────────────────────────
  /** The current graph as a WorkflowSchema (what `export` downloads). */
  toWorkflow: () => WorkflowSchema;
  /** Download the workflow as JSON. */
  exportWorkflow: () => void;
  /** Open a file picker and load a workflow. */
  importWorkflow: () => void;

  // ── Viewport ─────────────────────────────────────────────────────────
  fitView: () => void;

  // ── History ──
  /** Undo the last committing edit (add / delete / connect / config / drag /
   *  import). Transient interactions (a drag in progress, selection) are not
   *  their own steps. */
  undo: () => void;
  /** Redo the last undone edit. */
  redo: () => void;
  /** True when there is an edit to undo. */
  canUndo: boolean;
  /** True when there is an undone edit to redo. */
  canRedo: boolean;
};

/**
 * A declarative toolbar button. JSON-friendly on purpose — a host (or an
 * agent) can describe editor affordances as data rather than JSX.
 */
export type FlowEditorAction = {
  /** Stable id — also the `data-action` handle, so agents never guess DOM. */
  id: string;
  label: ReactNode;
  /** Native tooltip. */
  title?: string;
  /** Where it sits relative to the built-in buttons. Default "end". */
  placement?: "start" | "end";
  /** Disable when this returns true. Re-evaluated on every render. */
  disabled?: (api: FlowEditorApi) => boolean;
  /** Hide entirely when this returns false. */
  visible?: (api: FlowEditorApi) => boolean;
  /** Only enabled when a node is selected. Sugar over `disabled`. */
  requiresSelection?: boolean;
  onSelect: (api: FlowEditorApi) => void;
};

/** Which built-in toolbar affordances to render. All default to true. */
export type FlowEditorBuiltins = {
  run?: boolean;
  delete?: boolean;
  /** Undo/redo toolbar buttons. Default true. */
  history?: boolean;
  /** "Add lane" toolbar button. Default true. */
  addLane?: boolean;
  /** "Tidy" (auto-layout) toolbar button. Default true. */
  autoLayout?: boolean;
  /** Right-click a node for Delete / Duplicate. Default true. */
  contextMenu?: boolean;
  /** Right-click a connection for Label / Delete. Default true. */
  edgeContextMenu?: boolean;
  export?: boolean;
  import?: boolean;
  count?: boolean;
};

/** Replaceable regions. Each receives the editor API. */
export type FlowEditorSlots = {
  /** Replace the ENTIRE toolbar (built-ins and actions are not rendered). */
  toolbar?: (api: FlowEditorApi) => ReactNode;
  /** Replace the left palette. */
  palette?: (api: FlowEditorApi) => ReactNode;
  /** Replace the right config panel. */
  panel?: (api: FlowEditorApi) => ReactNode;
  /** Appended inside the config panel, under the fields — per-node actions. */
  panelFooter?: (api: FlowEditorApi) => ReactNode;
  /** Replace the run feed. */
  feed?: (api: FlowEditorApi) => ReactNode;
  /** Rendered over the canvas when the graph is empty. */
  empty?: (api: FlowEditorApi) => ReactNode;
  /** Replace the node right-click menu. Receives the right-clicked node id;
   *  call `close` when an item is chosen. */
  contextMenu?: (api: FlowEditorApi, nodeId: string, close: () => void) => ReactNode;
  /** Replace the connection right-click menu. Receives the right-clicked edge
   *  id; call `close` when an item is chosen. */
  edgeContextMenu?: (api: FlowEditorApi, edgeId: string, close: () => void) => ReactNode;
};

const FlowEditorContext = createContext<FlowEditorApi | null>(null);

export const FlowEditorProvider = FlowEditorContext.Provider;

/**
 * Read the editor API from any child of `<FlowEditor>`. Throws outside one, so
 * a misplaced custom control fails loudly instead of silently doing nothing.
 */
export function useFlowEditor(): FlowEditorApi {
  const api = useContext(FlowEditorContext);
  if (api === null) {
    throw new Error("useFlowEditor() must be called inside <FlowEditor>.");
  }
  return api;
}

/** Non-throwing variant, for components that may render outside an editor. */
export function useFlowEditorOptional(): FlowEditorApi | null {
  return useContext(FlowEditorContext);
}

import { reconnectEdge as xyReconnectEdge, type Connection, type Edge } from "@xyflow/react";
import type { FlowGraph, FlowNode } from "../lib/types";

/**
 * Remove nodes AND every edge attached to them.
 *
 * Deleting a node without pruning its edges leaves danglers that point at
 * nothing — they survive a round-trip through the schema and blow up the
 * runner, so the two always move together.
 */
export function removeNodes(graph: FlowGraph, ids: string[]): FlowGraph {
  if (ids.length === 0) return graph;
  const doomed = new Set(ids);

  return {
    nodes: graph.nodes.filter((n) => !doomed.has(n.id)),
    edges: graph.edges.filter((e) => !doomed.has(e.source) && !doomed.has(e.target)),
  };
}

/** Remove edges by id, leaving nodes untouched. */
export function removeEdges(edges: Edge[], ids: string[]): Edge[] {
  if (ids.length === 0) return edges;
  const doomed = new Set(ids);

  return edges.filter((e) => !doomed.has(e.id));
}

/**
 * Set (or clear) an edge's label.
 *
 * An empty/whitespace label is removed rather than stored as `""` — xyflow
 * renders an empty label as an empty chip on the wire, and a blank key would
 * survive export into the workflow schema.
 */
export function setEdgeLabel(edges: Edge[], id: string, label: string | undefined): Edge[] {
  const next = label?.trim();
  return edges.map((e) => {
    if (e.id !== id) return e;
    if (!next) {
      const { label: _drop, ...rest } = e;
      return rest as Edge;
    }
    return { ...e, label: next };
  });
}

/** Copy a node with a fresh id, offset so it doesn't sit exactly on top. */
export function duplicateNode(node: FlowNode, id: string, offset = 40): FlowNode {
  return {
    ...node,
    id,
    position: { x: node.position.x + offset, y: node.position.y + offset },
    // Deep copy so the clone's config edits don't mutate the original.
    data: JSON.parse(JSON.stringify(node.data ?? {})),
  } as FlowNode;
}

/**
 * Clone a set of nodes AND the edges internal to that set, remapping every id.
 * This is the piece `duplicateNode` lacks: a copy/paste (or duplicate-selection)
 * that preserves the wiring *between* the copied nodes. Edges with an endpoint
 * outside the set are dropped (they'd dangle). A `parentId` pointing inside the
 * set is remapped; one pointing outside is detached.
 */
export function cloneSubgraph(
  nodes: FlowNode[],
  edges: Edge[],
  opts: { makeId: () => string; offset?: number },
): { nodes: FlowNode[]; edges: Edge[]; idMap: Map<string, string> } {
  const offset = opts.offset ?? 40;
  const idMap = new Map<string, string>();
  for (const n of nodes) idMap.set(n.id, opts.makeId());

  const clonedNodes = nodes.map((n) => {
    const cloned = duplicateNode(n, idMap.get(n.id)!, offset) as any;
    const parentId = (n as any).parentId;
    if (parentId && idMap.has(parentId)) cloned.parentId = idMap.get(parentId);
    else if (parentId) delete cloned.parentId;
    return cloned as FlowNode;
  });

  const clonedEdges = edges
    .filter((e) => idMap.has(e.source) && idMap.has(e.target))
    .map((e) => ({ ...e, id: opts.makeId(), source: idMap.get(e.source)!, target: idMap.get(e.target)! }));

  return { nodes: clonedNodes, edges: clonedEdges, idMap };
}

/**
 * Rewire one edge's endpoint(s) — wraps xyflow's `reconnectEdge`. Keeps the
 * edge's id (`shouldReplaceId: false`) so its label and identity survive the
 * rewire instead of being regenerated from the new endpoints.
 */
export function reconnectEdge(edges: Edge[], oldEdge: Edge, newConnection: Connection): Edge[] {
  return xyReconnectEdge(oldEdge, newConnection, edges, { shouldReplaceId: false });
}

export type AlignEdge = "left" | "hcenter" | "right" | "top" | "vcenter" | "bottom";

const nodeW = (n: FlowNode): number => (n as any).width ?? (n as any).measured?.width ?? 0;
const nodeH = (n: FlowNode): number => (n as any).height ?? (n as any).measured?.height ?? 0;

/** Align a selection to a shared edge/center of its bounding box. */
export function alignNodes(nodes: FlowNode[], edge: AlignEdge): FlowNode[] {
  if (nodes.length < 2) return nodes;
  const minL = Math.min(...nodes.map((n) => n.position.x));
  const maxR = Math.max(...nodes.map((n) => n.position.x + nodeW(n)));
  const minT = Math.min(...nodes.map((n) => n.position.y));
  const maxB = Math.max(...nodes.map((n) => n.position.y + nodeH(n)));
  const cx = (minL + maxR) / 2;
  const cy = (minT + maxB) / 2;
  return nodes.map((n) => {
    let { x, y } = n.position;
    if (edge === "left") x = minL;
    else if (edge === "right") x = maxR - nodeW(n);
    else if (edge === "hcenter") x = cx - nodeW(n) / 2;
    else if (edge === "top") y = minT;
    else if (edge === "bottom") y = maxB - nodeH(n);
    else if (edge === "vcenter") y = cy - nodeH(n) / 2;
    return { ...n, position: { x, y } };
  });
}

/**
 * Order nodes so every parent precedes its children — xyflow misrenders (and
 * warns) when a child appears before its `parentId` in the array. Stable
 * otherwise. Apply at the render boundary once grouping is in play.
 */
export function sortNodesParentFirst<T extends { id: string; parentId?: string }>(nodes: T[]): T[] {
  const byId = new Map(nodes.map((n) => [n.id, n] as const));
  const seen = new Set<string>();
  const out: T[] = [];
  const visit = (n: T) => {
    if (seen.has(n.id)) return;
    const pid = (n as any).parentId as string | undefined;
    if (pid && byId.has(pid) && !seen.has(pid)) visit(byId.get(pid)!);
    seen.add(n.id);
    out.push(n);
  };
  for (const n of nodes) visit(n);
  return out;
}

/** Absolute position of a node, accounting for one level of parent nesting. */
function absolutePosition(node: FlowNode, nodes: FlowNode[]): { x: number; y: number } {
  const pid = (node as any).parentId as string | undefined;
  if (!pid) return node.position;
  const parent = nodes.find((n) => n.id === pid);
  return parent ? { x: node.position.x + parent.position.x, y: node.position.y + parent.position.y } : node.position;
}

/**
 * Put a node inside a lane/container: set `parentId` + `extent:'parent'` and
 * convert its position to be relative to the lane. Idempotent-safe; a no-op if
 * either id is missing or they're the same node.
 */
export function assignToLane(nodes: FlowNode[], nodeId: string, laneId: string): FlowNode[] {
  if (nodeId === laneId) return nodes;
  const node = nodes.find((n) => n.id === nodeId);
  const lane = nodes.find((n) => n.id === laneId);
  if (!node || !lane) return nodes;
  const abs = absolutePosition(node, nodes);
  const laneAbs = absolutePosition(lane, nodes);
  const rel = { x: abs.x - laneAbs.x, y: abs.y - laneAbs.y };
  return nodes.map((n) => (n.id === nodeId ? ({ ...n, parentId: laneId, extent: "parent", position: rel } as FlowNode) : n));
}

/** Take a node out of its lane: drop `parentId`/`extent`, restore absolute position. */
export function removeFromLane(nodes: FlowNode[], nodeId: string): FlowNode[] {
  const node = nodes.find((n) => n.id === nodeId);
  if (!node || !(node as any).parentId) return nodes;
  const abs = absolutePosition(node, nodes);
  return nodes.map((n) => {
    if (n.id !== nodeId) return n;
    const { parentId: _p, extent: _e, ...rest } = n as any;
    return { ...rest, position: abs } as FlowNode;
  });
}

/**
 * Stack lanes into contiguous rows (horizontal) or columns (vertical) — the
 * "fixed rows/columns" behavior. `isLane` picks which nodes are lanes; they're
 * ordered by their current cross-axis position and repacked from the first
 * lane's origin. Each lane keeps its own size (independently resizable).
 */
export function stackLanes(
  nodes: FlowNode[],
  isLane: (n: FlowNode) => boolean,
  opts: { orientation?: "horizontal" | "vertical"; gap?: number } = {},
): FlowNode[] {
  const orientation = opts.orientation ?? "horizontal";
  const gap = opts.gap ?? 12;
  const vertical = orientation === "vertical";
  const lanes = nodes.filter(isLane).sort((a, b) => (vertical ? a.position.x - b.position.x : a.position.y - b.position.y));
  if (lanes.length === 0) return nodes;
  const originX = lanes[0].position.x;
  const originY = lanes[0].position.y;
  const moves = new Map<string, { x: number; y: number }>();
  let cursor = vertical ? originX : originY;
  for (const lane of lanes) {
    moves.set(lane.id, vertical ? { x: cursor, y: originY } : { x: originX, y: cursor });
    cursor += (vertical ? ((lane as any).width ?? 320) : ((lane as any).height ?? 160)) + gap;
  }
  return nodes.map((n) => (moves.has(n.id) ? { ...n, position: moves.get(n.id)! } : n));
}

/** Evenly distribute a selection's gaps along an axis (needs 3+ nodes). */
export function distributeNodes(nodes: FlowNode[], axis: "h" | "v"): FlowNode[] {
  if (nodes.length < 3) return nodes;
  const size = (n: FlowNode) => (axis === "h" ? nodeW(n) : nodeH(n));
  const coord = (n: FlowNode) => (axis === "h" ? n.position.x : n.position.y);
  const sorted = [...nodes].sort((a, b) => coord(a) - coord(b));
  const start = coord(sorted[0]);
  const last = sorted[sorted.length - 1];
  const end = coord(last) + size(last);
  const totalSize = sorted.reduce((s, n) => s + size(n), 0);
  const gap = (end - start - totalSize) / (sorted.length - 1);
  const posById = new Map<string, number>();
  let cursor = start;
  for (const n of sorted) {
    posById.set(n.id, cursor);
    cursor += size(n) + gap;
  }
  return nodes.map((n) => {
    const p = posById.get(n.id)!;
    return { ...n, position: axis === "h" ? { ...n.position, x: p } : { ...n.position, y: p } };
  });
}

/**
 * The field vocabulary a `user_input` node declares, and the normalizer that
 * turns whatever was actually written into something renderable.
 *
 * ## Why this is a separate module from `HumanPrompt.tsx`
 *
 * `src/registry/builtin.ts` needs `humanFieldType` for the `user_input` kind's
 * `outputShape`, and `builtin.ts` is in the import graph of the `/engine`
 * entry — the one `tests/core-nodes.test.ts` guards as React-free so a queue
 * worker or a CLI can register kinds without dragging React in. Importing the
 * modal's `.tsx` from there put a React module on that path and left the guard
 * standing only because treeshaking happened to drop it.
 *
 * Pure functions over plain data, in a `.ts` file, so the headless path cannot
 * regress on a future edit to the component.
 */

/**
 * The control a field renders as, after {@link humanInputFields} has resolved
 * whatever the author, a peer runtime or an agent actually wrote.
 *
 * These are the CANONICAL names. The vocabulary an author may write is wider —
 * see {@link HUMAN_FIELD_TYPE_ALIASES} — because a `fields` array arrives from
 * three places (the config panel, a hand-written workflow JSON, and the PHP /
 * Python runtimes) and each has its own habits for spelling "boolean".
 */
export type HumanFieldType =
  | "text"
  | "textarea"
  | "number"
  | "select"
  | "switch"
  | "date"
  | "datetime"
  | "time"
  | "email"
  | "url"
  | "tel"
  | "password";

/** One choice in a `select` field, after normalization. */
export type HumanFieldOption = { value: string; label: string };

/** A field the input modal renders. Mirrors a `user_input` `fields` row. */
export type HumanField = {
  key: string;
  label?: string;
  type?: HumanFieldType;
  required?: boolean;
  placeholder?: string;
  options?: HumanFieldOption[];
  default?: unknown;
};

/**
 * Every spelling of a field type this accepts, mapped onto its canonical
 * control.
 *
 * The bug this table exists to fix: the old normalizer accepted exactly five
 * literal names and coerced everything else to `text`, so `boolean`, `date`,
 * `email` and `enum` — the words a person reaches for first, and the words the
 * peer runtimes' own docs use — all arrived at the form as a plain text box.
 * The person then typed a date into a text field and the run resumed with a
 * string where a date was declared, which nothing downstream could detect.
 *
 * Aliases rather than a stricter schema because the declaration is DATA. It is
 * written by hand and emitted by agents, and rejecting `boolean` on a spelling
 * technicality would be a worse failure than accepting it.
 */
export const HUMAN_FIELD_TYPE_ALIASES: Readonly<Record<string, HumanFieldType>> = {
  text: "text",
  string: "text",
  str: "text",
  input: "text",

  textarea: "textarea",
  long_text: "textarea",
  longtext: "textarea",
  "long-text": "textarea",
  multiline: "textarea",
  paragraph: "textarea",
  markdown: "textarea",

  number: "number",
  numeric: "number",
  integer: "number",
  int: "number",
  float: "number",
  decimal: "number",

  select: "select",
  enum: "select",
  choice: "select",
  choices: "select",
  dropdown: "select",
  options: "select",
  radio: "select",

  switch: "switch",
  bool: "switch",
  boolean: "switch",
  checkbox: "switch",
  toggle: "switch",

  date: "date",

  datetime: "datetime",
  "datetime-local": "datetime",
  datetimelocal: "datetime",
  timestamp: "datetime",

  time: "time",

  email: "email",
  "e-mail": "email",

  url: "url",
  uri: "url",
  link: "url",

  tel: "tel",
  phone: "tel",
  telephone: "tel",

  password: "password",
  secret: "password",
};

/**
 * Resolve a declared type name to a control.
 *
 * An unrecognised name becomes `text` — never a crash and never a dropped
 * field. A field the form refuses to render is a value the run will never
 * receive, which is strictly worse than rendering it as free text.
 */
export function humanFieldType(raw: unknown): HumanFieldType {
  if (typeof raw !== "string") return "text";
  return HUMAN_FIELD_TYPE_ALIASES[raw.trim().toLowerCase()] ?? "text";
}

/**
 * Normalize whatever an author wrote for a select's choices.
 *
 * Accepts the three shapes that actually turn up:
 *
 * - `["small", "large"]` — bare strings, the shorthand `TextConfigField.choices`
 *   already accepts elsewhere in this package.
 * - `[{ value: "s", label: "Small" }]` — the explicit form.
 * - `{ s: "Small", l: "Large" }` — what the config panel's `keyvalue` control
 *   stores, which is how choices are authored on the `user_input` node.
 *
 * A missing `label` falls back to the value rather than rendering an empty
 * option — the old code read `o.label` off a bare string and put `undefined`
 * into both the value and the text, so a shorthand list rendered as a dropdown
 * of blank rows.
 */
export function humanFieldOptions(raw: unknown): HumanFieldOption[] | undefined {
  const entries: HumanFieldOption[] = [];

  if (Array.isArray(raw)) {
    for (const item of raw) {
      if (typeof item === "string" || typeof item === "number") {
        const value = String(item);
        if (value !== "") entries.push({ value, label: value });
        continue;
      }
      if (item && typeof item === "object") {
        const value = (item as { value?: unknown }).value;
        if (value === undefined || value === null || value === "") continue;
        const label = (item as { label?: unknown }).label;
        entries.push({
          value: String(value),
          label: typeof label === "string" && label !== "" ? label : String(value),
        });
      }
    }
  } else if (raw && typeof raw === "object") {
    for (const [value, label] of Object.entries(raw as Record<string, unknown>)) {
      if (value === "") continue;
      entries.push({ value, label: typeof label === "string" && label !== "" ? label : value });
    }
  }

  return entries.length ? entries : undefined;
}

/**
 * Normalize a `user_input` node's `fields` config into renderable fields. Falls
 * back to a single text field so even an unconfigured User Input node still
 * collects something rather than silently returning nothing.
 */
export function humanInputFields(config: Record<string, unknown>): HumanField[] {
  const raw = Array.isArray((config as any)?.fields) ? ((config as any).fields as any[]) : [];
  const fields: HumanField[] = raw
    .filter((f) => f && typeof f === "object" && typeof (f as any).key === "string" && (f as any).key)
    .map((f: any) => ({
      key: f.key,
      label: typeof f.label === "string" && f.label ? f.label : f.key,
      type: humanFieldType(f.type),
      required: !!f.required,
      placeholder: typeof f.placeholder === "string" ? f.placeholder : undefined,
      options: humanFieldOptions(f.options ?? f.choices),
      default: f.default,
    }));
  if (fields.length) return fields;
  const title = typeof (config as any)?.title === "string" && (config as any).title ? (config as any).title : "Your answer";
  return [{ key: "value", label: title, type: "textarea", required: true }];
}

