import type { CSSProperties } from "react";

export type FlowRunControlsProps = {
  running: boolean;
  onRun: () => void;
  onCancel?: () => void;
  onReset?: () => void;
  className?: string;
  style?: CSSProperties;
};

/** FlowRunControls — Run / Cancel / Reset buttons. Wire to a `useFlowRun`. */
export function FlowRunControls({ running, onRun, onCancel, onReset, className, style }: FlowRunControlsProps) {
  return (
    <div className={["ff-run-controls", className ?? ""].filter(Boolean).join(" ")} style={style}>
      {!running ? (
        <button type="button" className="ff-run-controls__btn ff-run-controls__btn--run" onClick={onRun}>
          ▶ Run
        </button>
      ) : (
        <button type="button" className="ff-run-controls__btn ff-run-controls__btn--cancel" onClick={onCancel}>
          ⏹ Cancel
        </button>
      )}
      {onReset && (
        <button type="button" className="ff-run-controls__btn ff-run-controls__btn--reset" onClick={onReset} disabled={running}>
          Reset
        </button>
      )}
    </div>
  );
}

import { type CSSProperties, useEffect, useRef } from "react";
import type { FlowRunFeedEntry } from "../runtime/use-flow-run";

export type FlowRunFeedProps = {
  entries: FlowRunFeedEntry[];
  /** Show the header bar (title + running badge + event count). Default true. */
  showHeader?: boolean;
  /** Header title. Default "Run feed". */
  title?: string;
  /** When true, a "running" badge shows in the header. */
  running?: boolean;
  className?: string;
  style?: CSSProperties;
};

/**
 * FlowRunFeed — scrolling run log with a header (title + live event count).
 * Auto-scrolls its body to the bottom on new entries.
 */
export function FlowRunFeed({ entries, showHeader = true, title = "Run feed", running, className, style }: FlowRunFeedProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [entries.length]);

  return (
    <div className={["ff-run-feed", className ?? ""].filter(Boolean).join(" ")} style={style}>
      {showHeader && (
        <div className="ff-run-feed__header">
          <span className="ff-run-feed__title" aria-hidden>▸</span>
          <span className="ff-run-feed__title-text">{title}</span>
          {running && <span className="ff-run-feed__badge">running</span>}
          <span className="ff-run-feed__count">{entries.length} {entries.length === 1 ? "event" : "events"}</span>
        </div>
      )}
      <div className="ff-run-feed__body" ref={scrollRef}>
        {entries.length === 0 ? (
          <p className="ff-run-feed__empty">No run events yet.</p>
        ) : (
          entries.map((e) => (
            <div key={e.id} className={`ff-run-feed__row ff-run-feed__row--${e.level}`}>
              <span className="ff-run-feed__time">{formatTime(e.at)}</span>
              {e.nodeId && <span className="ff-run-feed__node">{e.nodeId}</span>}
              <span className="ff-run-feed__text">{e.text}</span>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

function formatTime(at: number): string {
  const d = new Date(at);
  return `${d.getMinutes().toString().padStart(2, "0")}:${d.getSeconds().toString().padStart(2, "0")}.${Math.floor(d.getMilliseconds() / 100)}`;
}

import { useCallback, useMemo, useRef, useState } from "react";
import type { EdgeChange, NodeChange } from "@xyflow/react";
import type { FlowGraph } from "../types";
import { createHistory } from "./history";
import type { UseFlowStateReturn } from "./use-flow-state";

export type UseFlowHistoryReturn = {
  /** The flow sink wrapped so committing mutations snapshot for undo first. */
  flow: UseFlowStateReturn;
  undo: () => void;
  redo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  /** Snapshot the current graph as an undo point (before a programmatic edit). */
  capture: () => void;
  /** Wire to `<FlowCanvas onNodeDragStart>` — snapshots the pre-drag graph. */
  onNodeDragStart: () => void;
};

/**
 * useFlowHistory — the commit/undo pipeline. Wraps a flow sink (the uncontrolled
 * `useFlowState` hook OR the controlled adapter) so every *committing* mutation
 * records a snapshot first, giving undo/redo without the editor threading
 * history through each call site. This is the single interception point the
 * two-sink architecture otherwise lacks.
 *
 * Granularity: a burst of setState calls from one logical op (e.g. a
 * delete = setNodes+setEdges) is coalesced into ONE undo step; transient
 * interactive changes (drag-move, dimension-measure, selection) are NOT captured
 * — a drag is captured once at `onNodeDragStart` instead.
 */
export function useFlowHistory(flow: UseFlowStateReturn): UseFlowHistoryReturn {
  const history = useRef(createHistory()).current;
  const restoring = useRef(false);
  const coalesced = useRef(false);
  const [, bump] = useState(0);
  const rerender = useCallback(() => bump((n) => n + 1), []);

  // Latest graph via a ref, so capture never reads a stale snapshot.
  const graphRef = useRef<FlowGraph>({ nodes: flow.nodes, edges: flow.edges });
  graphRef.current = { nodes: flow.nodes, edges: flow.edges };

  const capture = useCallback(() => {
    if (restoring.current || coalesced.current) return;
    coalesced.current = true;
    queueMicrotask(() => {
      coalesced.current = false;
    });
    history.push(graphRef.current);
    rerender();
  }, [history, rerender]);

  const restore = useCallback(
    (g: FlowGraph | null) => {
      if (!g) return;
      restoring.current = true;
      flow.setGraph(g);
      queueMicrotask(() => {
        restoring.current = false;
      });
      rerender();
    },
    [flow, rerender],
  );

  const undo = useCallback(() => restore(history.undo(graphRef.current)), [history, restore]);
  const redo = useCallback(() => restore(history.redo(graphRef.current)), [history, restore]);

  const wrapped = useMemo<UseFlowStateReturn>(
    () => ({
      ...flow,
      setNodes: (next) => {
        capture();
        flow.setNodes(next);
      },
      setEdges: (next) => {
        capture();
        flow.setEdges(next);
      },
      setGraph: (g) => {
        capture();
        flow.setGraph(g);
      },
      onNodesChange: (changes: NodeChange[]) => {
        // Only structural removes commit; position/dimensions/select are transient.
        if (!restoring.current && changes.some((c) => c.type === "remove")) capture();
        flow.onNodesChange(changes);
      },
      onEdgesChange: (changes: EdgeChange[]) => {
        if (!restoring.current && changes.some((c) => c.type === "remove")) capture();
        flow.onEdgesChange(changes);
      },
      onConnect: (conn) => {
        capture();
        flow.onConnect(conn);
      },
    }),
    [flow, capture],
  );

  return {
    flow: wrapped,
    undo,
    redo,
    canUndo: history.canUndo(),
    canRedo: history.canRedo(),
    capture,
    onNodeDragStart: capture,
  };
}

import { useCallback, useRef, useState } from "react";
import { runFlow, type RunOptions, type RunResult } from "./run-flow";
import { getNodeKind } from "../registry/registry";
import type {
  ExecutorRegistry,
  FlowGraph,
  NodeRunStatus,
  RunEvent,
} from "../types";

export type FlowRunFeedEntry = {
  id: string;
  at: number;
  /**
   * `message` is a node's own human-facing announcement (`startingMsg` /
   * `stoppingMsg`), kept distinct from `status` and `info` so a progress UI can
   * show ONLY the narration. Folded in with diagnostics it would be unfindable,
   * which is the same as not having it.
   */
  level: "info" | "warn" | "error" | "status" | "message";
  text: string;
  nodeId?: string;
  detail?: unknown;
};

export type UseFlowRunReturn = {
  /** Status keyed by nodeId — drive the UI overlay from this. */
  statuses: Record<string, NodeRunStatus>;
  /** Per-node status text (e.g. error message). */
  statusText: Record<string, string | undefined>;
  /** Latest computed output value per node (for reactive kinds). */
  outputs: Record<string, unknown>;
  /**
   * Latest status message per nodeId, from the node's own `startingMsg` /
   * `stoppingMsg`. Undefined for the nodes that declared none, which is most
   * of them by design.
   */
  nodeMessages: Record<string, string | undefined>;
  /** Live event log (capped to last N). */
  feed: FlowRunFeedEntry[];
  /** Whether a run is currently in progress. */
  running: boolean;
  /** Last run result, or null. */
  lastResult: RunResult | null;
  /** Kick off a run with the provided graph + executors. */
  run: (graph: FlowGraph, executors: ExecutorRegistry, options?: RunOptions) => Promise<RunResult>;
  /** Cancel the current run (if any). */
  cancel: () => void;
  /** Reset all runtime state (statuses, feed, lastResult). */
  reset: () => void;
};

export type UseFlowRunOptions = {
  /** Cap the in-memory feed to this many entries. Default 200. */
  maxFeed?: number;
};

/**
 * useFlowRun — drives `runFlow` + maintains observability state. Pair with
 * `applyStatusesToNodes` (below) before passing nodes to `<FlowCanvas>` so
 * the per-node status badge renders.
 */
export function useFlowRun({ maxFeed = 200 }: UseFlowRunOptions = {}): UseFlowRunReturn {
  const [statuses, setStatuses] = useState<Record<string, NodeRunStatus>>({});
  const [statusText, setStatusText] = useState<Record<string, string | undefined>>({});
  const [nodeMessages, setNodeMessages] = useState<Record<string, string | undefined>>({});
  const [outputs, setOutputs] = useState<Record<string, unknown>>({});
  const [feed, setFeed] = useState<FlowRunFeedEntry[]>([]);
  const [running, setRunning] = useState(false);
  const [lastResult, setLastResult] = useState<RunResult | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const handleEvent = useCallback(
    (e: RunEvent) => {
      switch (e.type) {
        case "node-status":
          setStatuses((s) => ({ ...s, [e.nodeId]: e.status }));
          setStatusText((t) => ({ ...t, [e.nodeId]: e.text }));
          appendFeed({ level: "status", text: `${e.nodeId} → ${e.status}${e.text ? ` (${e.text})` : ""}`, nodeId: e.nodeId });
          break;
        case "node-message":
          setNodeMessages((m) => ({ ...m, [e.nodeId]: e.message }));
          appendFeed({ level: "message", text: e.message, nodeId: e.nodeId });
          break;
        case "node-output":
          setOutputs((o) => ({ ...o, [e.nodeId]: e.value }));
          appendFeed({ level: "info", text: `${e.nodeId}.${e.portId} = ${preview(e.value)}`, nodeId: e.nodeId, detail: e.value });
          break;
        case "log":
          appendFeed({ level: e.level, text: e.message, nodeId: e.nodeId, detail: e.detail });
          break;
        case "run-start":
          appendFeed({ level: "info", text: "▶ run started" });
          break;
        case "run-end":
          appendFeed({ level: e.ok ? "info" : "error", text: e.ok ? "✓ run complete" : "✗ run failed" });
          break;
        case "run-error":
          appendFeed({ level: "error", text: e.error });
          break;
      }
      function appendFeed(partial: Omit<FlowRunFeedEntry, "id" | "at">) {
        setFeed((f) => {
          const entry: FlowRunFeedEntry = { id: `${Date.now()}_${f.length}`, at: Date.now(), ...partial };
          const next = [...f, entry];
          return next.length > maxFeed ? next.slice(next.length - maxFeed) : next;
        });
      }
    },
    [maxFeed],
  );

  const run = useCallback(
    async (graph: FlowGraph, executors: ExecutorRegistry, options: RunOptions = {}) => {
      if (running) {
        return { ok: false, outputs: {}, error: "another run is already in progress" } satisfies RunResult;
      }
      const controller = new AbortController();
      abortRef.current = controller;
      // Reset previous statuses for the nodes we're about to run.
      const idleStatuses: Record<string, NodeRunStatus> = {};
      for (const n of graph.nodes) idleStatuses[n.id] = "idle";
      setStatuses(idleStatuses);
      setStatusText({});
      setOutputs({});
      setRunning(true);
      try {
        const result = await runFlow(graph, executors, handleEvent, { ...options, signal: controller.signal });
        setLastResult(result);
        return result;
      } finally {
        setRunning(false);
        abortRef.current = null;
      }
    },
    [handleEvent, running],
  );

  const cancel = useCallback(() => abortRef.current?.abort(), []);

  const reset = useCallback(() => {
    setStatuses({});
    setStatusText({});
    setOutputs({});
    setFeed([]);
    setLastResult(null);
  }, []);

  return { statuses, statusText, nodeMessages, outputs, feed, running, lastResult, run, cancel, reset };
}

/**
 * Write each reactive kind's latest run output into its `data.output`, so its
 * card can render the computed value live. Non-reactive kinds are returned
 * untouched. Pair with `applyStatusesToNodes` before rendering.
 */
export function applyOutputsToNodes<TNode extends { id: string; type?: string; data: any }>(
  nodes: TNode[],
  outputs: Record<string, unknown>,
): TNode[] {
  return nodes.map((n) => {
    const kind = getNodeKind((n.data as any)?.kind ?? n.type ?? "");
    if (!kind?.reactive || !(n.id in outputs)) return n;
    return { ...n, data: { ...n.data, output: outputs[n.id] } };
  });
}

/** Merge runtime statuses into nodes for rendering. */
export function applyStatusesToNodes<TNode extends { id: string; data: any }>(
  nodes: TNode[],
  statuses: Record<string, NodeRunStatus>,
  statusText: Record<string, string | undefined>,
): TNode[] {
  return nodes.map((n) => ({
    ...n,
    data: {
      ...n.data,
      status: statuses[n.id] ?? n.data?.status ?? "idle",
      statusText: statusText[n.id] ?? n.data?.statusText,
    },
  }));
}

function preview(v: unknown): string {
  try {
    const s = JSON.stringify(v);
    return s && s.length > 60 ? s.slice(0, 57) + "…" : (s ?? String(v));
  } catch {
    return String(v);
  }
}

