/**
 * Default xyflow `nodeTypes` map covering the kit. Spread into your own:
 *
 *   <FlowCanvas nodeTypes={{ ...defaultNodeTypes, custom: MyNode }} ... />
 */
export const defaultNodeTypes: NodeTypes = {
  trigger: TriggerNode,
  action: ActionNode,
  decision: DecisionNode,
  output: OutputNode,
  note: NoteNode,
  subgraph: SubgraphNode,
};

import type { Connection, Edge } from "@xyflow/react";
import type { FlowNode, PortDescriptor } from "../types";
import { getNodeKind } from "./registry";
import { resolveNodePorts } from "./ports";

/**
 * Connection validation — the single rule that decides whether an edge between
 * two ports is allowed. Lives here (React-free, registry-adjacent) so BOTH the
 * canvas (`<FlowCanvas isValidConnection>`) and the agent bridge's
 * `flow_connect` tool call the same function: a connection the canvas refuses
 * is a connection an agent cannot sneak past, and vice versa — no drift.
 *
 * `PortDescriptor.type` has always documented itself as being "for hosts that
 * want to validate connections", but nothing consumed it. This wires it up.
 */

/**
 * Wildcard port type — matches any other type. A port that declares no `type`
 * is treated as a wildcard too, so existing flows (whose ports are untyped)
 * validate exactly as before.
 */
export const ANY_PORT_TYPE = "any";

/** Decides whether a source-output port may feed a target-input port. */
export type PortCompatibility = (
  source: PortDescriptor | undefined,
  target: PortDescriptor | undefined,
) => boolean;

/**
 * Default compatibility rule: allow the connection UNLESS both ports declare a
 * concrete, differing type. An absent type or the `any` wildcard matches
 * anything — so typed ports get enforced while untyped ports stay permissive,
 * making this a safe default that never breaks an existing untyped graph.
 */
export const defaultPortCompatibility: PortCompatibility = (source, target) => {
  const s = source?.type;
  const t = target?.type;
  if (!s || !t) return true;
  if (s === ANY_PORT_TYPE || t === ANY_PORT_TYPE) return true;
  return s === t;
};

export type ConnectionValidatorOptions = {
  /** Override the type-compatibility rule. Defaults to {@link defaultPortCompatibility}. */
  compatible?: PortCompatibility;
  /**
   * Allow a node's own output to feed its own input (a self-loop). Default
   * false — self-connections are almost always an accident, and the rare flow
   * that wants one can opt in.
   */
  allowSelfConnection?: boolean;
};

/** Resolve a node's effective ports for one side, going through the registry. */
function portsFor(node: FlowNode, side: "inputs" | "outputs"): PortDescriptor[] {
  const kind = getNodeKind((node.data as any)?.kind ?? node.type);
  const resolved = resolveNodePorts(node, kind ?? undefined);
  return resolved[side] ?? [];
}

/**
 * Resolve which port a handle id refers to. When a side has a single port and
 * the handle id is absent (React Flow omits it for a lone default handle), use
 * that port; otherwise match by id.
 */
function findPort(
  ports: PortDescriptor[],
  handleId: string | null | undefined,
): PortDescriptor | undefined {
  if (handleId == null) return ports.length === 1 ? ports[0] : undefined;
  return ports.find((p) => p.id === handleId);
}

/**
 * Build an `isValidConnection` predicate that enforces port-type compatibility
 * against a live node list. Pass it straight to `<FlowCanvas isValidConnection>`
 * or reuse it to gate an agent's `flow_connect`.
 *
 * `getNodes` is called on every check so the validator always sees the current
 * graph (wire it to a ref/state getter, not a snapshot).
 *
 * A connection is rejected when: an endpoint is missing; it is a self-loop and
 * `allowSelfConnection` is off; either node is unknown; or the resolved ports
 * are type-incompatible. Nodes/ports with no declared type validate as before.
 */
export function createConnectionValidator(
  getNodes: () => FlowNode[],
  options: ConnectionValidatorOptions = {},
): (connection: Connection | Edge) => boolean {
  const compatible = options.compatible ?? defaultPortCompatibility;
  return (connection) => {
    const { source, target, sourceHandle, targetHandle } = connection;
    if (!source || !target) return false;
    if (!options.allowSelfConnection && source === target) return false;

    const nodes = getNodes();
    const src = nodes.find((n) => n.id === source);
    const tgt = nodes.find((n) => n.id === target);
    if (!src || !tgt) return false;

    const outPort = findPort(portsFor(src, "outputs"), sourceHandle);
    const inPort = findPort(portsFor(tgt, "inputs"), targetHandle);
    return compatible(outPort, inPort);
  };
}

import type { FlowNode } from "../../types";

export type HelperLineChange = { id: string; position?: { x: number; y: number } };

export type HelperLinesResult = {
  /** Y of a horizontal guide line (flow coords), if the drag aligns on Y. */
  horizontal?: number;
  /** X of a vertical guide line (flow coords), if the drag aligns on X. */
  vertical?: number;
  /** The snapped position to apply to the dragged node. */
  snapPosition: { x?: number; y?: number };
};

const w = (n: FlowNode): number => (n as any).width ?? (n as any).measured?.width ?? 0;
const h = (n: FlowNode): number => (n as any).height ?? (n as any).measured?.height ?? 0;

/**
 * Compute alignment guide lines (and a snapped position) for a node being
 * dragged to `change.position`, against the other nodes. Standard "helper
 * lines" algorithm: match the dragged node's left/right/top/bottom edges to any
 * other node's edges within `distance`, snapping to the nearest. Pure + testable.
 */
export function getHelperLines(change: HelperLineChange, nodes: FlowNode[], distance = 6): HelperLinesResult {
  const result: HelperLinesResult = { snapPosition: { x: undefined, y: undefined } };
  const a = nodes.find((n) => n.id === change.id);
  if (!a || !change.position) return result;

  const A = {
    left: change.position.x,
    right: change.position.x + w(a),
    top: change.position.y,
    bottom: change.position.y + h(a),
    width: w(a),
    height: h(a),
  };
  let vDist = distance;
  let hDist = distance;

  for (const b of nodes) {
    if (b.id === a.id) continue;
    const B = { left: b.position.x, right: b.position.x + w(b), top: b.position.y, bottom: b.position.y + h(b) };

    // Vertical guides (X alignment).
    const ll = Math.abs(A.left - B.left);
    if (ll < vDist) { result.snapPosition.x = B.left; result.vertical = B.left; vDist = ll; }
    const rr = Math.abs(A.right - B.right);
    if (rr < vDist) { result.snapPosition.x = B.right - A.width; result.vertical = B.right; vDist = rr; }
    const lr = Math.abs(A.left - B.right);
    if (lr < vDist) { result.snapPosition.x = B.right; result.vertical = B.right; vDist = lr; }
    const rl = Math.abs(A.right - B.left);
    if (rl < vDist) { result.snapPosition.x = B.left - A.width; result.vertical = B.left; vDist = rl; }

    // Horizontal guides (Y alignment).
    const tt = Math.abs(A.top - B.top);
    if (tt < hDist) { result.snapPosition.y = B.top; result.horizontal = B.top; hDist = tt; }
    const bb = Math.abs(A.bottom - B.bottom);
    if (bb < hDist) { result.snapPosition.y = B.bottom - A.height; result.horizontal = B.bottom; hDist = bb; }
    const tb = Math.abs(A.top - B.bottom);
    if (tb < hDist) { result.snapPosition.y = B.bottom; result.horizontal = B.bottom; hDist = tb; }
    const bt = Math.abs(A.bottom - B.top);
    if (bt < hDist) { result.snapPosition.y = B.top - A.height; result.horizontal = B.top; hDist = bt; }
  }

  return result;
}

import type { FlowNode } from "../../types";

export type MeasuredSizes = Readonly<Record<string, { width: number; height: number }>>;

/**
 * The node sizes React Flow has reported, folded into a map by node id.
 *
 * React Flow measures every rendered node and announces the result as a
 * `dimensions` change through `onNodesChange`. A host that APPLIES node changes
 * ends up with `measured` on its node objects. A host that renders a graph
 * read-only never applies anything, and its node objects never learn their size.
 *
 * Returns the previous map unchanged when nothing moved, so a React state setter
 * can bail out instead of re-rendering on every measurement pass.
 */
export function collectMeasuredSizes(
  previous: MeasuredSizes,
  changes: ReadonlyArray<{ type: string; id?: string; dimensions?: { width: number; height: number } }>,
): MeasuredSizes {
  let next: Record<string, { width: number; height: number }> | null = null;

  for (const change of changes) {
    if (change.type !== "dimensions" || !change.id || !change.dimensions) continue;
    const { width, height } = change.dimensions;
    const known = (next ?? previous)[change.id];
    if (known && known.width === width && known.height === height) continue;
    next ??= { ...previous };
    next[change.id] = { width, height };
  }

  return next ?? previous;
}

/**
 * Nodes carrying the sizes the canvas measured, for any node that arrived
 * without its own.
 *
 * WHY: React Flow's `<MiniMap>` draws a node only when the node object the host
 * passed has dimensions (`nodeHasDimensions(node.internals.userNode)`). The main
 * canvas draws from React Flow's internal copy, which is measured either way. So
 * a read-only `FlowViewer` rendered its whole graph while its minimap found no
 * node to draw, and showed an empty rectangle over the canvas (fancy-flow #15).
 *
 * A node the host already measured is returned as is, so an editor applying its
 * own changes is untouched; so is the array itself when there is nothing to add.
 */
export function withMeasuredSizes<T extends FlowNode>(nodes: T[], sizes: MeasuredSizes): T[] {
  let changed = false;
  const out = nodes.map((node) => {
    const size = sizes[node.id];
    if (!size || node.measured?.width !== undefined) return node;
    changed = true;
    return { ...node, measured: { width: size.width, height: size.height } };
  });

  return changed ? out : nodes;
}

import { categoryAccent, getNodeKind } from "../../registry/registry";
import type { FlowNode } from "../../types";

/**
 * A minimap node in its kind's accent, the colour of the node's own header.
 *
 * React Flow's default fills every minimap node with one grey, and in dark mode
 * that is #2b2b2b on a #141414 panel: present in the DOM and invisible on the
 * page. With the header colour the minimap reads as the graph it mirrors, and a
 * trigger, an LLM call and an output are told apart at a glance.
 */
export function minimapNodeColor(node: FlowNode): string {
  const kind = getNodeKind(String(node.data?.kind ?? node.type ?? ""));

  return kind?.accent ?? categoryAccent(kind?.category ?? "custom");
}

import { ViewportPortal } from "@xyflow/react";

/**
 * HelperLines — alignment guides drawn during a drag. Rendered in flow
 * coordinate space (ViewportPortal), so the lines track pan/zoom. Positions come
 * from `getHelperLines`.
 */
export function HelperLines({ horizontal, vertical }: { horizontal?: number; vertical?: number }) {
  if (horizontal === undefined && vertical === undefined) return null;
  return (
    <ViewportPortal>
      {vertical !== undefined && (
        <div
          className="ff-helper-line"
          style={{ position: "absolute", transform: `translateX(${vertical}px)`, top: -5000, height: 10000, width: 1, pointerEvents: "none" }}
        />
      )}
      {horizontal !== undefined && (
        <div
          className="ff-helper-line"
          style={{ position: "absolute", transform: `translateY(${horizontal}px)`, left: -5000, width: 10000, height: 1, pointerEvents: "none" }}
        />
      )}
    </ViewportPortal>
  );
}

import { useEffect, useState } from "react";

/** The resolved mode React Flow and our own `ff-` tokens both understand. */
export type FlowColorMode = "light" | "dark";

/**
 * What a host may PASS. React Flow's own `ColorMode` includes `"system"`, and
 * it is meaningful here rather than something to cast away: it means "follow
 * the environment", which is the same job `undefined` now does.
 */
export type FlowColorModeInput = FlowColorMode | "system";

/**
 * Read the app's theme off the document, the way every host in this suite
 * signals it.
 *
 * Checked in the order a host actually sets them: an explicit `data-theme`
 * beats a `.dark` class (a host that writes both, like the showcase, is
 * consistent either way), and only when neither is present does the OS
 * preference decide.
 */
function readDocumentTheme(): FlowColorMode {
  if (typeof document === "undefined") return "light";

  const root = document.documentElement;
  const attr = root.getAttribute("data-theme");
  if (attr === "dark" || attr === "light") return attr;
  if (root.classList.contains("dark")) return "dark";

  return typeof window !== "undefined" && window.matchMedia?.("(prefers-color-scheme: dark)").matches
    ? "dark"
    : "light";
}

/**
 * The colour mode the canvas should actually use.
 *
 * **Why this exists.** `colorMode` used to be passed straight through to React
 * Flow, so a host that did not supply one got React Flow's own default —
 * `light` — no matter what the surrounding app was doing. Our `ff-` styles
 * still looked right, because they hang off an ancestor `.dark`, which is
 * exactly what made the bug hard to see: the nodes we style were fine while
 * React Flow's own layer stayed light underneath. Any node whose kind is not
 * registered falls back to React Flow's default node, and on a dark page that
 * is a white box with unreadable text. Edges, handles, the selection rectangle
 * and the controls were light too.
 *
 * So an unset `colorMode` now means "follow the app", not "light". Passing one
 * explicitly still wins — a canvas deliberately pinned light on a dark page is
 * a real thing, and this does not take it away.
 *
 * The subscription matters as much as the initial read: a theme toggle changes
 * an attribute on `<html>`, which triggers no React render on its own, so
 * without an observer the canvas would be correct on load and wrong the moment
 * someone flipped the switch.
 */
export function useResolvedColorMode(explicit?: FlowColorModeInput): FlowColorMode {
  // Start light on the server and on first paint. Reading the DOM in the
  // initialiser would differ between server and client markup and trip
  // hydration; the effect below corrects it before anything is visible.
  const [resolved, setResolved] = useState<FlowColorMode>("light");

  // `"system"` is treated exactly like an unset prop: both mean "follow the
  // environment", and collapsing them here keeps one resolution path.
  const pinned = explicit === "light" || explicit === "dark" ? explicit : undefined;

  useEffect(() => {
    if (pinned) return;
    if (typeof document === "undefined") return;

    const sync = () => setResolved(readDocumentTheme());
    sync();

    const observer = new MutationObserver(sync);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme"],
    });

    const media = window.matchMedia?.("(prefers-color-scheme: dark)");
    media?.addEventListener?.("change", sync);

    return () => {
      observer.disconnect();
      media?.removeEventListener?.("change", sync);
    };
  }, [pinned]);

  return pinned ?? resolved;
}

import { type CSSProperties, useEffect, useMemo, useState } from "react";
import { categoryAccent, listNodeKinds, onNodeKindsChanged } from "../../registry/registry";
import type { NodeCategory, NodeKindDefinition } from "../../registry/types";

export type NodePaletteProps = {
  /** Filter to only these categories. */
  categories?: NodeCategory[];
  /**
   * Presentation-only visibility policy for KINDS. Returning `false` omits the
   * row, leaving the registered kind and its runtime behaviour untouched — the
   * same contract `fieldFilter` has on `NodeConfigPanel`, one level up.
   *
   * `categories` cannot express this. A host that supports a subset of the
   * vocabulary is the normal case, not an exotic one: a runtime with no way to
   * RESUME a paused run has to keep `human_approval` / `user_input` /
   * `rich_user_input` out of the palette, and those three sit in a category
   * alongside nothing else it wants to hide.
   *
   * Without it the only lever was `overrideNodeKind` to re-categorise the
   * host's OWN nodes until a category filter happened to exclude ours — which
   * distorts the host's taxonomy to work around a gap in ours. A consumer
   * reported doing exactly that analysis and filing instead (#14).
   *
   * Deliberately a predicate over the full definition rather than a list of
   * ids: it has to serve custom kinds a host registered and kinds vendored in
   * from the marketplace, whose names the palette cannot know in advance.
   */
  kindFilter?: (context: { kind: NodeKindDefinition }) => boolean;
  /** Called when the user clicks a kind (in addition to drag). Optional. */
  onPick?: (kind: NodeKindDefinition) => void;
  className?: string;
  style?: CSSProperties;
};

const CATEGORY_ORDER: NodeCategory[] = ["trigger", "logic", "data", "ai", "io", "human", "output", "layout", "annotation", "custom"];
const CATEGORY_LABELS: Record<NodeCategory, string> = {
  trigger: "Triggers",
  logic: "Logic",
  data: "Data",
  ai: "AI",
  io: "Connectors",
  human: "Human",
  output: "Output",
  layout: "Layout",
  annotation: "Notes",
  custom: "Custom",
};

/**
 * NodePalette — sidebar listing every registered node kind, grouped by
 * category. Drag a kind onto a `<FlowCanvas>` to add a new node — set
 * `onDrop` on the canvas to handle the drop with the kind name from the
 * `application/x-fancy-flow-kind` data type.
 */
export function NodePalette({ categories, kindFilter, onPick, className, style }: NodePaletteProps) {
  const [, setRev] = useState(0);
  useEffect(() => onNodeKindsChanged(() => setRev((n) => n + 1)), []);

  const [query, setQuery] = useState("");
  const visibleCats = categories ?? CATEGORY_ORDER;

  const grouped = useMemo(() => {
    const all = listNodeKinds();
    const q = query.trim().toLowerCase();
    // Host policy first, then the user's search. Applying the search first
    // would let a hidden kind reappear the moment somebody typed its name --
    // which is the one moment a host hiding an unsupported kind most needs it
    // to stay hidden.
    const allowed = kindFilter ? all.filter((k) => kindFilter({ kind: k })) : all;
    const filtered = q
      ? allowed.filter((k) => k.name.includes(q) || k.label.toLowerCase().includes(q) || (k.description ?? "").toLowerCase().includes(q))
      : allowed;
    const map = new Map<NodeCategory, NodeKindDefinition[]>();
    for (const cat of visibleCats) map.set(cat, []);
    for (const k of filtered) {
      if (!map.has(k.category)) map.set(k.category, []);
      map.get(k.category)!.push(k);
    }
    return map;
  }, [query, visibleCats, kindFilter]);

  return (
    <aside className={["ff-palette", className ?? ""].filter(Boolean).join(" ")} style={style}>
      <div className="ff-palette__search">
        <input
          className="ff-palette__search-input"
          placeholder="Search nodes…"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>
      <div className="ff-palette__list">
        {Array.from(grouped.entries()).map(([cat, kinds]) =>
          kinds.length === 0 ? null : (
            <section key={cat} className="ff-palette__group">
              <header className="ff-palette__group-label">{CATEGORY_LABELS[cat] ?? cat}</header>
              {kinds.map((k) => (
                <KindRow key={k.name} kind={k} onPick={onPick} />
              ))}
            </section>
          ),
        )}
      </div>
    </aside>
  );
}

function KindRow({ kind, onPick }: { kind: NodeKindDefinition; onPick?: (k: NodeKindDefinition) => void }) {
  const accent = kind.accent ?? categoryAccent(kind.category);
  const onDragStart = (e: React.DragEvent) => {
    e.dataTransfer.effectAllowed = "copy";
    e.dataTransfer.setData("application/x-fancy-flow-kind", kind.name);
    // Setting both lets non-aware drop targets (e.g. text inputs) ignore it cleanly.
    e.dataTransfer.setData("text/plain", kind.name);
  };
  return (
    <button
      type="button"
      className="ff-palette__row"
      draggable
      onDragStart={onDragStart}
      onClick={() => onPick?.(kind)}
      title={kind.description ?? kind.name}
    >
      <span className="ff-palette__row-dot" style={{ background: accent }}>{kind.icon ?? ""}</span>
      <span className="ff-palette__row-text">
        <span className="ff-palette__row-label">{kind.label}</span>
        {kind.description && <span className="ff-palette__row-desc">{kind.description}</span>}
      </span>
    </button>
  );
}

/**
 * useDropFromPalette — wires the canvas drop target. Returns the drop /
 * dragOver handlers; they parse the dragged kind name and call `onDrop`
 * with `(kindName, position)` in viewport coords.
 */
export function paletteDropHandlers(onDrop: (kindName: string, evt: React.DragEvent) => void) {
  return {
    onDragOver: (e: React.DragEvent) => {
      if (e.dataTransfer.types.includes("application/x-fancy-flow-kind")) {
        e.preventDefault();
        e.dataTransfer.dropEffect = "copy";
      }
    },
    onDrop: (e: React.DragEvent) => {
      const name = e.dataTransfer.getData("application/x-fancy-flow-kind");
      if (!name) return;
      e.preventDefault();
      onDrop(name, e);
    },
  };
}

import { type ReactNode, useId, useMemo } from "react";
import type { FlowNode, FlowGraph} from "../../types";
import type { ConfigField, NodeKindDefinition } from "../../registry/types";
import { categoryAccent, getNodeKind, validateConfig } from "../../registry/registry";
import { getRichInputAdapter } from "../../registry/rich-input";
import { ConfigFieldRenderer, type ConfigFieldRenderFn } from "./ConfigFieldRenderer";

export type NodeConfigPanelProps = {
  /** Currently-selected node — pass null to render the empty state. */
  node: FlowNode | null;
  /** Called when the user edits the node label, description, or config. */
  onChange: (next: FlowNode) => void;
  /**
   * Called when the user deletes the node from the panel. When provided, the
   * panel renders a "Delete node" button while a node is selected — so the
   * delete affordance lives WITH the panel (a dev composing their own editor
   * gets it for free), rather than in a host toolbar it has to re-implement.
   */
  onDelete?: (node: FlowNode) => void;
  /** Label for the delete button. Default "Delete node". */
  deleteLabel?: string;
  /** Optional header content (e.g. close button). */
  header?: ReactNode;
  /** Optional credential picker hook — host renders the picker. */
  renderCredentialField?: (props: {
    credentialType: string;
    value: unknown;
    onChange: (next: unknown) => void;
  }) => ReactNode;
  /**
   * Optional document editor hook — host renders the editor for `document`
   * fields. Lets rich authored content live in node config without fancy-flow
   * taking on a document model.
   */
  /** Host renderers keyed by field `type`. See {@link ConfigFieldRenderer}. */
  fieldRenderers?: Record<string, ConfigFieldRenderFn>;
  /**
   * Presentation-only visibility policy for schema fields. Returning `false`
   * omits the complete field wrapper (label, description, and control) while
   * leaving the registered kind and its runtime schema untouched.
   */
  fieldFilter?: (context: {
    node: FlowNode;
    kind: NodeKindDefinition;
    field: ConfigField;
  }) => boolean;
  /**
   * The graph the node lives in. Supplying it is what makes the `{{ }}` variable
   * picker context-aware — it reads the UPSTREAM node's declared `outputShape`
   * to list what is actually reachable here (issue #5). Without it the picker
   * still opens, but can only offer the whole input.
   */
  graph?: FlowGraph;
  renderDocumentField?: (props: {
    documentType?: string;
    value: unknown;
    onChange: (next: unknown) => void;
  }) => ReactNode;
  className?: string;
  style?: React.CSSProperties;
};

/**
 * NodeConfigPanel — schema-driven form for the selected node. Defers to
 * `kind.renderPanel` if the kind opts out of the auto-form.
 */
export function NodeConfigPanel({
  node,
  onChange,
  onDelete,
  deleteLabel = "Delete node",
  header,
  renderCredentialField,
  renderDocumentField,
  fieldRenderers,
  fieldFilter,
  graph,
  className,
  style,
}: NodeConfigPanelProps) {
  // EVERY hook runs before EVERY early return.
  //
  // The two `useMemo`s below used to sit after the `if (!node)` return, so the
  // panel called no hooks with nothing selected and two with a node — a
  // rules-of-hooks violation that React reports as #310, "rendered more hooks
  // than during the previous render". It survived because nothing in this repo
  // could render a component: the vitest config collected only `.test.ts`.
  // Adding a third hook is what finally made it crash on selecting a node.
  //
  // `uid` gives one prefix per mounted panel, so two panels on a page (a split
  // view, a comparison) cannot mint the same id and steal each other's label
  // clicks.
  const uid = useId();
  const kindName = node ? ((node.data as any).kind ?? node.type) : null;
  const kind = useMemo(() => (kindName ? getNodeKind(kindName) : undefined), [kindName]);
  const config = useMemo(
    () => ((node?.data as any)?.config ?? {}) as Record<string, unknown>,
    [node?.data],
  );

  /**
   * A stable DOM id for one field's control.
   *
   * The field KEY is in the id rather than an index, so the handle survives
   * reordering the schema, and an agent reading `data-ff-field` finds the same
   * element the label points at.
   */
  const fieldId = (key: string) => `${uid}-${key}`;

  if (!node) {
    return (
      <aside className={["ff-panel", "ff-panel--empty", className ?? ""].filter(Boolean).join(" ")} style={style}>
        {header}
        <p className="ff-panel__empty">Select a node to configure it.</p>
      </aside>
    );
  }

  if (!kind) {
    return (
      <aside className={["ff-panel", className ?? ""].filter(Boolean).join(" ")} style={style}>
        {header}
        <p className="ff-panel__empty">Unknown kind: {kindName}</p>
        {onDelete && (
          <div className="ff-panel__actions">
            <button
              type="button"
              className="ff-panel__delete"
              data-action="delete-node"
              onClick={() => onDelete(node)}
              title="Delete this node (Del / Backspace)"
            >
              ✕ {deleteLabel}
            </button>
          </div>
        )}
      </aside>
    );
  }

  const setLabel = (label: string) =>
    onChange({ ...node, data: { ...node.data, label } });

  const setDescription = (description: string) =>
    onChange({ ...node, data: { ...node.data, description } });

  const setStatusMsg = (key: "startingMsg" | "stoppingMsg", value: string) =>
    onChange({ ...node, data: { ...node.data, [key]: value } });

  const setConfigValue = (key: string, value: unknown) =>
    onChange({ ...node, data: { ...node.data, config: { ...config, [key]: value } } });

  const configFields = (kind.configSchema ?? []).filter((field) =>
    fieldFilter ? fieldFilter({ node, kind, field }) : true,
  );
  const visibleFieldKeys = new Set(configFields.map((field) => field.key));
  // Validation itself still runs against the complete registered schema. Only
  // its presentation follows fieldFilter: a host-owned hidden value must not
  // leave an impossible warning for a control the host deliberately removed.
  const issues = validateConfig(kind, config).filter((issue) => visibleFieldKeys.has(issue.key));

  // An explicit prop wins; otherwise fall back to the rich-input adapter, so a
  // single registerRichInputAdapter() call enables BOTH authoring here and the
  // in-node preview without the host wiring the same editor twice.
  const adapter = getRichInputAdapter();
  const documentField = renderDocumentField
    ?? (adapter?.renderEditor
      ? ({ value, onChange: set }: { value: unknown; onChange: (n: unknown) => void }) =>
          adapter.renderEditor!({ value, onChange: set })
      : undefined);

  return (
    <aside className={["ff-panel", className ?? ""].filter(Boolean).join(" ")} style={style}>
      {header}
      <header className="ff-panel__header">
        <span className="ff-panel__head-icon" style={{ background: kind.accent ?? categoryAccent(kind.category) }} aria-hidden>
          {kind.icon}
        </span>
        <span className="ff-panel__head-text">
          <span className="ff-panel__head-kind">{kind.label}</span>
          <span className="ff-panel__head-name">{node.data.label || kind.label}</span>
        </span>
      </header>
      {kind.description && <p className="ff-panel__kind-desc">{kind.description}</p>}

      <div className="ff-panel__field">
        <label className="ff-panel__label" htmlFor={fieldId("label")}>Label</label>
        <input
          id={fieldId("label")}
          data-ff-field="label"
          className="ff-panel__input"
          value={node.data.label ?? ""}
          onChange={(e) => setLabel(e.target.value)}
          placeholder={kind.label}
        />
      </div>

      <div className="ff-panel__field">
        <label className="ff-panel__label" htmlFor={fieldId("description")}>Description</label>
        <textarea
          id={fieldId("description")}
          data-ff-field="description"
          className="ff-panel__input ff-panel__input--textarea"
          rows={2}
          value={node.data.description ?? ""}
          onChange={(e) => setDescription(e.target.value)}
        />
      </div>

      {/* Run narration. Node-level and kind-agnostic, so it sits with label and
          description rather than in the kind's configSchema — any node can
          announce itself, and no kind should have to opt in to be allowed to.
          Left blank on most nodes by design: narrating every step buries the
          two or three a person actually follows. */}
      <div className="ff-panel__field">
        <label className="ff-panel__label" htmlFor={fieldId("startingMsg")}>Message when it starts</label>
        <input
          id={fieldId("startingMsg")}
          data-ff-field="startingMsg"
          className="ff-panel__input"
          value={(node.data.startingMsg as string) ?? ""}
          onChange={(e) => setStatusMsg("startingMsg", e.target.value)}
          placeholder="e.g. Starting the deep analysis"
        />
        <p className="ff-panel__hint">Announced just before this node runs. Leave blank to say nothing.</p>
      </div>

      <div className="ff-panel__field">
        <label className="ff-panel__label" htmlFor={fieldId("stoppingMsg")}>Message when it finishes</label>
        <input
          id={fieldId("stoppingMsg")}
          data-ff-field="stoppingMsg"
          className="ff-panel__input"
          value={(node.data.stoppingMsg as string) ?? ""}
          onChange={(e) => setStatusMsg("stoppingMsg", e.target.value)}
          placeholder="e.g. Analysis complete"
        />
        <p className="ff-panel__hint">Announced only if the node succeeds — never after a failure.</p>
      </div>

      {kind.renderPanel ? (
        kind.renderPanel({
          config: config as any,
          onChange: (next) => onChange({ ...node, data: { ...node.data, config: next } }),
          nodeId: node.id,
        })
      ) : (
        <>
          {configFields.length > 0 && <hr className="ff-panel__divider" />}
          {configFields.map((field) => (
            <div key={field.key} className="ff-panel__field">
              <label className="ff-panel__label" htmlFor={fieldId(field.key)}>
                {field.label}
                {field.required && <span className="ff-panel__required" aria-hidden> *</span>}
              </label>
              {field.description && <p className="ff-panel__hint">{field.description}</p>}
              <ConfigFieldRenderer
                id={fieldId(field.key)}
                field={field}
                value={config[field.key]}
                onChange={(v) => setConfigValue(field.key, v)}
                renderCredentialField={renderCredentialField}
                renderDocumentField={documentField}
                fieldRenderers={fieldRenderers}
                graph={graph}
                nodeId={node.id}
              />
            </div>
          ))}
        </>
      )}

      {issues.length > 0 && (
        <div className="ff-panel__issues">
          {issues.map((iss) => (
            <p key={iss.key} className="ff-panel__issue">⚠ {iss.message}</p>
          ))}
        </div>
      )}

      {onDelete && (
        <div className="ff-panel__actions">
          <button
            type="button"
            className="ff-panel__delete"
            data-action="delete-node"
            onClick={() => onDelete(node)}
            title="Delete this node (Del / Backspace)"
          >
            ✕ {deleteLabel}
          </button>
        </div>
      )}
    </aside>
  );
}

import { type ReactNode, useMemo, useRef, useState } from "react";
import { ExpressionField } from "./ExpressionField";
import type { FlowGraph } from "../../types";
import type {
  ConfigField,
  KeyValueConfigField,
  RepeaterConfigField,
  TextConfigField,
} from "../../registry/types";

/** What a host renderer is handed. */
export type ConfigFieldRenderContext = {
  field: ConfigField;
  value: unknown;
  onChange: (next: unknown) => void;
  /** The id the panel's `<label>` points at. Put it on your control. */
  id?: string;
};

/**
 * Render one field. Return `null` to fall back to the package's own rendering,
 * so a host can claim a type conditionally instead of reimplementing every case.
 *
 * Named `...Fn` because `ConfigFieldRenderer` is already the component this
 * module exports; two things with one name in a public API is a paper cut a
 * consumer pays for, not us.
 */
export type ConfigFieldRenderFn = (ctx: ConfigFieldRenderContext) => ReactNode;

export type ConfigFieldRendererProps = {
  field: ConfigField;
  value: unknown;
  onChange: (value: unknown) => void;
  /**
   * DOM id for the control this renders.
   *
   * Supplied by the caller rather than generated here so the panel's `<label>`
   * can point at it — a label beside a control is not a label attached to one.
   * Also the agent-facing handle: the Human+ contract asks that every
   * interactive element have a stable identity so an agent targets it instead
   * of guessing at the DOM, and until this existed nothing in the editor had
   * one.
   */
  id?: string;
  renderCredentialField?: (props: {
    credentialType: string;
    value: unknown;
    onChange: (next: unknown) => void;
  }) => ReactNode;
  /**
   * Editor for `document` fields. fancy-flow stores the document but never
   * interprets it — the host owns the editing surface, exactly as it does for
   * `credential`. This is the seam for rich human-input steps (authored pages,
   * required reading, multi-section forms) without the package depending on
   * any particular document model.
   */
  renderDocumentField?: (props: {
    documentType?: string;
    value: unknown;
    onChange: (next: unknown) => void;
  }) => ReactNode;
  /**
   * Host renderers keyed by field `type`.
   *
   * The generic form of `renderDocumentField` / `renderCredentialField`: those
   * cover two types the package deliberately does not interpret, this covers
   * any type at all — including one the package has never heard of.
   *
   * Without it, a richer field had to be rendered OUTSIDE the panel, so that
   * node's config stopped living where every other field does. An unknown type
   * also fell through to `default:` and rendered nothing, so the schema said the
   * field existed and the panel showed empty space.
   *
   * Consulted BEFORE the built-in switch, so a host can also replace a built-in
   * (react-fancy inputs, say) through the same seam rather than a second one.
   */
  fieldRenderers?: Record<string, ConfigFieldRenderFn>;
  /**
   * The graph and the node being edited — what makes the `{{ }}` picker
   * CONTEXT-aware rather than a static list. Optional: a panel composed without
   * them still renders, it just cannot offer node-specific variables.
   */
  graph?: FlowGraph;
  nodeId?: string;
};

/**
 * ConfigFieldRenderer — dispatches to the right input element per field type.
 *
 * Plain HTML inputs styled via the package's CSS so the package stays
 * standalone (no react-fancy import required) and every surface stays themeable
 * through the `--ff-*` token layer. Hosts that want react-fancy form components
 * can supply their own field renderers via the kind's `renderPanel`.
 *
 * Each control carries the caller's `id` and a `data-ff-field` handle keyed by
 * the field, so a label can point at it and an agent can find it by name.
 */
export function ConfigFieldRenderer({
  field,
  value,
  onChange,
  id,
  renderCredentialField,
  renderDocumentField,
  fieldRenderers,
  graph,
  nodeId,
}: ConfigFieldRendererProps) {
  /** Applied to whichever control this field renders. */
  const handle = { id, "data-ff-field": field.key } as const;

  // Host renderers win, and `null` means "you take it" — so claiming a type
  // conditionally does not mean reimplementing the rest.
  const custom = fieldRenderers?.[field.type];
  if (custom) {
    const rendered = custom({ field, value, onChange, id });
    if (rendered !== null && rendered !== undefined) return <>{rendered}</>;
  }

  switch (field.type) {
    case "text": {
      // Declaring `choices` turns a text field into a picker without changing
      // its type or the shape of the value it stores.
      if (field.choices?.length) {
        return <ChoiceField field={field} value={value} onChange={onChange} />;
      }
      return (
        <input
          {...handle}
          className="ff-panel__input"
          type="text"
          value={(value as string) ?? ""}
          placeholder={field.placeholder}
          onChange={(e) => onChange(e.target.value)}
        />
      );
    }

    case "textarea":
      return (
        <textarea
          {...handle}
          className="ff-panel__input ff-panel__input--textarea"
          rows={field.rows ?? 4}
          value={(value as string) ?? ""}
          placeholder={field.placeholder}
          onChange={(e) => onChange(e.target.value)}
        />
      );

    case "number":
      return (
        <input
          {...handle}
          className="ff-panel__input"
          type="number"
          value={(value as number) ?? ""}
          min={field.min}
          max={field.max}
          step={field.step ?? 1}
          onChange={(e) => onChange(e.target.value === "" ? undefined : Number(e.target.value))}
        />
      );

    case "switch":
      return (
        <label className="ff-panel__switch">
          <input
            {...handle}
            type="checkbox"
            checked={!!value}
            onChange={(e) => onChange(e.target.checked)}
          />
          <span className="ff-panel__switch-slider" />
        </label>
      );

    case "select":
      return (
        <select
          {...handle}
          className="ff-panel__input"
          value={(value as string) ?? ""}
          onChange={(e) => onChange(e.target.value)}
        >
          <option value="" disabled>—</option>
          {field.options.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>
      );

    case "json":
      return <JsonField value={value} onChange={onChange} rows={field.rows} handle={handle} />;

    case "expression":
      return (
        <ExpressionField
          handle={handle}
          value={(value as string) ?? ""}
          onChange={onChange}
          placeholder={field.example ?? "{{ $json.field }}"}
          graph={graph}
          nodeId={nodeId}
        />
      );

    case "credential":
      if (renderCredentialField) {
        return <>{renderCredentialField({ credentialType: field.credentialType, value, onChange })}</>;
      }
      return (
        <input
          className="ff-panel__input ff-panel__input--credential"
          type="text"
          value={(value as string) ?? ""}
          placeholder={`Credential reference (${field.credentialType})`}
          onChange={(e) => onChange(e.target.value)}
        />
      );

    case "repeater":
      return (
        <RepeaterField
          id={id}
          field={field}
          value={value}
          onChange={onChange}
          renderCredentialField={renderCredentialField}
          renderDocumentField={renderDocumentField}
          fieldRenderers={fieldRenderers}
          graph={graph}
          nodeId={nodeId}
        />
      );

    case "keyvalue":
      return <KeyValueField id={id} field={field} value={value} onChange={onChange} />;

    case "document":
      if (renderDocumentField) {
        return <>{renderDocumentField({ documentType: field.documentType, value, onChange })}</>;
      }
      return (
        <p className="ff-panel__hint ff-panel__hint--missing">
          No document editor supplied. Pass <code>renderDocumentField</code> to
          NodeConfigPanel to author this field.
        </p>
      );

    default:
      return null;
  }
}

/** Normalize the `choices` shorthand — a bare string means value === label. */
export function normalizeChoices(
  choices: NonNullable<TextConfigField["choices"]>,
): Array<{ value: string; label: string }> {
  return choices.map((c) =>
    typeof c === "string" ? { value: c, label: c } : { value: c.value, label: c.label ?? c.value },
  );
}

/**
 * ChoiceField — a text field rendered as a select because the kind declared
 * `choices`.
 *
 * A stored value that is no longer among the choices is appended as an option
 * instead of being dropped. Choices are authored data and can change after
 * configs are saved; silently resetting the author's value on render would
 * lose work with no indication it happened.
 */
function ChoiceField({
  field,
  value,
  onChange,
}: {
  field: TextConfigField;
  value: unknown;
  onChange: (v: unknown) => void;
}) {
  const options = normalizeChoices(field.choices ?? []);
  const current = typeof value === "string" ? value : "";
  const known = options.some((o) => o.value === current);

  return (
    <select
      className="ff-panel__input"
      value={current}
      onChange={(e) => onChange(e.target.value)}
    >
      <option value="" disabled>{field.placeholder ?? "—"}</option>
      {options.map((o) => (
        <option key={o.value} value={o.value}>{o.label}</option>
      ))}
      {current !== "" && !known && (
        <option value={current}>{current} (not in list)</option>
      )}
    </select>
  );
}

/**
 * RepeaterField — editable list of objects, each row driven by the field's
 * own sub-schema. Rows carry stable `data-ff-repeater-row` indices so an
 * agent can target a specific row without guessing DOM.
 */
function RepeaterField({
  id,
  field,
  value,
  onChange,
  graph,
  nodeId,
  renderCredentialField,
  renderDocumentField,
  fieldRenderers,
}: {
  id?: string;
  field: RepeaterConfigField;
  value: unknown;
  onChange: (v: unknown) => void;
  renderCredentialField?: ConfigFieldRendererProps["renderCredentialField"];
  renderDocumentField?: ConfigFieldRendererProps["renderDocumentField"];
  fieldRenderers?: ConfigFieldRendererProps["fieldRenderers"];
  graph?: FlowGraph;
  nodeId?: string;
}) {
  const rows: Array<Record<string, unknown>> = Array.isArray(value) ? (value as Array<Record<string, unknown>>) : [];
  const max = field.maxItems ?? Infinity;
  const min = field.minItems ?? 0;

  const replace = (next: Array<Record<string, unknown>>) => onChange(next);

  const addRow = () => {
    const blank: Record<string, unknown> = {};
    for (const f of field.fields) {
      if ("default" in f && f.default !== undefined) blank[f.key] = f.default;
    }
    replace([...rows, blank]);
  };

  const removeRow = (i: number) => replace(rows.filter((_, idx) => idx !== i));

  const moveRow = (i: number, delta: number) => {
    const target = i + delta;
    if (target < 0 || target >= rows.length) return;
    const next = [...rows];
    [next[i], next[target]] = [next[target], next[i]];
    replace(next);
  };

  const setCell = (i: number, key: string, cell: unknown) =>
    replace(rows.map((row, idx) => (idx === i ? { ...row, [key]: cell } : row)));

  const rowTitle = (row: Record<string, unknown>, i: number): string => {
    const key = field.titleKey ?? field.fields[0]?.key;
    const raw = key ? row[key] : undefined;
    if (typeof raw === "string" && raw.trim() !== "") return raw;
    if (typeof raw === "number" || typeof raw === "boolean") return String(raw);
    return `Item ${i + 1}`;
  };

  return (
    <div id={id} role="group" className="ff-repeater" data-ff-repeater={field.key} data-ff-field={field.key}>
      {rows.length === 0 && <p className="ff-repeater__empty">None yet.</p>}

      {rows.map((row, i) => (
        <div className="ff-repeater__row" key={i} data-ff-repeater-row={i}>
          <div className="ff-repeater__row-head">
            <span className="ff-repeater__row-title">{rowTitle(row, i)}</span>
            <div className="ff-repeater__row-actions">
              <button
                type="button"
                className="ff-repeater__btn"
                onClick={() => moveRow(i, -1)}
                disabled={i === 0}
                aria-label={`Move ${rowTitle(row, i)} up`}
              >↑</button>
              <button
                type="button"
                className="ff-repeater__btn"
                onClick={() => moveRow(i, 1)}
                disabled={i === rows.length - 1}
                aria-label={`Move ${rowTitle(row, i)} down`}
              >↓</button>
              <button
                type="button"
                className="ff-repeater__btn ff-repeater__btn--danger"
                onClick={() => removeRow(i)}
                disabled={rows.length <= min}
                aria-label={`Remove ${rowTitle(row, i)}`}
              >✕</button>
            </div>
          </div>

          {field.fields.map((sub) => (
            <div className="ff-repeater__cell" key={sub.key}>
              <label className="ff-panel__label ff-panel__label--sub">
                {sub.label}
                {sub.required && <span className="ff-panel__required" aria-hidden> *</span>}
              </label>
              <ConfigFieldRenderer
                graph={graph}
                nodeId={nodeId}
                field={sub}
                value={row[sub.key]}
                onChange={(cell) => setCell(i, sub.key, cell)}
                renderCredentialField={renderCredentialField}
                renderDocumentField={renderDocumentField}
                fieldRenderers={fieldRenderers}
              />
            </div>
          ))}
        </div>
      ))}

      <button
        type="button"
        className="ff-repeater__add"
        onClick={addRow}
        disabled={rows.length >= max}
      >
        + {field.addLabel ?? "Add"}
      </button>
    </div>
  );
}

/**
 * KeyValueField — editable string→string map.
 *
 * Renaming a key preserves insertion order (rebuilding the object rather than
 * delete-then-add), so rows don't jump around while the author is typing.
 */
function KeyValueField({
  id,
  field,
  value,
  onChange,
}: {
  id?: string;
  field: KeyValueConfigField;
  value: unknown;
  onChange: (v: unknown) => void;
}) {
  const map = (value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, string>)
    : {}) as Record<string, string>;
  const entries = Object.entries(map);

  const commit = (next: Array<[string, string]>) => {
    const obj: Record<string, string> = {};
    for (const [k, v] of next) {
      if (k === "") continue;
      obj[k] = v;
    }
    onChange(obj);
  };

  const setKey = (i: number, key: string) =>
    commit(entries.map(([k, v], idx) => (idx === i ? [key, v] : [k, v])));
  const setVal = (i: number, val: string) =>
    commit(entries.map(([k, v], idx) => (idx === i ? [k, val] : [k, v])));
  const remove = (i: number) => commit(entries.filter((_, idx) => idx !== i));
  const add = () => commit([...entries, ["", ""]]);

  return (
    <div id={id} role="group" className="ff-keyvalue" data-ff-keyvalue={field.key} data-ff-field={field.key}>
      {entries.length > 0 && (
        <div className="ff-keyvalue__head">
          <span>{field.keyLabel ?? "Key"}</span>
          <span>{field.valueLabel ?? "Value"}</span>
          <span />
        </div>
      )}

      {entries.map(([k, v], i) => (
        <div className="ff-keyvalue__row" key={i} data-ff-keyvalue-row={i}>
          <input
            className="ff-panel__input"
            value={k}
            placeholder={field.keyPlaceholder}
            aria-label={`${field.keyLabel ?? "Key"} ${i + 1}`}
            onChange={(e) => setKey(i, e.target.value)}
          />
          {field.valueOptions ? (
            <select
              className="ff-panel__input"
              value={v ?? ""}
              aria-label={`${field.valueLabel ?? "Value"} ${i + 1}`}
              onChange={(e) => setVal(i, e.target.value)}
            >
              <option value="" disabled>—</option>
              {field.valueOptions.map((o) => (
                <option key={o.value} value={o.value}>{o.label}</option>
              ))}
            </select>
          ) : (
            <input
              className="ff-panel__input"
              value={v ?? ""}
              placeholder={field.valuePlaceholder}
              aria-label={`${field.valueLabel ?? "Value"} ${i + 1}`}
              onChange={(e) => setVal(i, e.target.value)}
            />
          )}
          <button
            type="button"
            className="ff-repeater__btn ff-repeater__btn--danger"
            onClick={() => remove(i)}
            aria-label={`Remove ${k || `entry ${i + 1}`}`}
          >✕</button>
        </div>
      ))}

      <button type="button" className="ff-repeater__add" onClick={add}>
        + {field.addLabel ?? "Add"}
      </button>
    </div>
  );
}

/**
 * JsonField — the built-in fallback for `type: "json"`.
 *
 * **It used to eat invalid input.** Parsing happened on blur and the `catch`
 * block was empty save for a comment claiming the visual would revert. It could
 * not: the textarea was uncontrolled, so the broken text stayed on screen while
 * the config silently kept its previous value. The panel showed one document
 * and the node ran another, with nothing anywhere saying so — and a missing
 * comma is not a rare event in an `api_request` body.
 *
 * Now the text is a real buffer, the parse error is reported, and the config is
 * still never written from unparseable text. Refusing to store garbage was
 * right; doing it silently was not.
 *
 * The error appears on blur rather than per keystroke — every partially-typed
 * object is invalid on the way to being valid, and flagging that is noise.
 *
 * Hosts on react-fancy can swap this for a real typed editor by passing
 * `fieldRenderers` from `@particle-academy/fancy-flow/fields/react-fancy`.
 */
function JsonField({
  value,
  onChange,
  rows,
  handle,
}: {
  value: unknown;
  onChange: (v: unknown) => void;
  rows?: number;
  handle: { id?: string; "data-ff-field": string };
}) {
  const serialized = useMemo(() => {
    try {
      return value === undefined ? "" : JSON.stringify(value, null, 2);
    } catch {
      return "";
    }
  }, [value]);

  const [text, setText] = useState(serialized);
  const [error, setError] = useState<string | null>(null);
  const [touched, setTouched] = useState(false);

  // Two refs, because "the props changed" and "our own edit came back" are
  // different events and only the first should touch the buffer.
  const lastProps = useRef(serialized);
  const committed = useRef<string | null>(null);

  // Re-sync on a genuinely EXTERNAL change — an undo, an agent write, another
  // node selected into the same panel.
  //
  // Comparing props against previous props (not against our own last commit) is
  // what keeps this from fighting a host that doesn't apply changes
  // immediately: a debounced or read-only host leaves `value` alone, which used
  // to read as "reverted externally" and wiped whatever had just been typed.
  // And skipping when the incoming value is our own commit is what stops the
  // author's `{"a":1}` being reformatted onto four lines mid-edit.
  if (serialized !== lastProps.current) {
    lastProps.current = serialized;
    if (serialized !== committed.current) {
      setText(serialized);
      setError(null);
      setTouched(false);
    }
  }

  /** Parse and commit; returns the message when it cannot. */
  const commit = (next: string): string | null => {
    const trimmed = next.trim();
    if (trimmed === "") {
      committed.current = "";
      onChange(undefined);
      return null;
    }
    try {
      const parsed = JSON.parse(trimmed);
      // Record what this commit will serialize to, so recognising it on the way
      // back is an exact string comparison rather than a guess.
      committed.current = JSON.stringify(parsed, null, 2);
      onChange(parsed);
      return null;
    } catch (e) {
      return e instanceof Error ? e.message : "Invalid JSON";
    }
  };

  const errorId = handle.id ? `${handle.id}-error` : undefined;
  const showError = touched && error !== null;

  return (
    <>
      <textarea
        {...handle}
        className="ff-panel__input ff-panel__input--json"
        rows={rows ?? 6}
        value={text}
        spellCheck={false}
        aria-invalid={showError || undefined}
        aria-describedby={showError ? errorId : undefined}
        onChange={(e) => {
          setText(e.target.value);
          setError(commit(e.target.value));
        }}
        onBlur={(e) => {
          setTouched(true);
          setError(commit(e.target.value));
        }}
      />
      {showError && (
        <p className="ff-panel__issue ff-panel__issue--field" id={errorId} role="alert">
          ⚠ {error}
        </p>
      )}
    </>
  );
}

import type { FlowGraph } from "../types";

/**
 * Undo/redo history — a pure, React-free snapshot controller. The editor pushes
 * a graph snapshot BEFORE each committing mutation; `undo`/`redo` swap snapshots
 * between the past/future stacks. Kept free of React so it can be unit-tested
 * and reused by any host (or a headless driver).
 *
 * Coalescing (collapsing a burst of setState calls from one logical op into a
 * single undo step) is the caller's job — see `useFlowHistory`.
 */
export type HistoryController = {
  /** Record `graph` as an undo point. Clears the redo stack (new branch). */
  push: (graph: FlowGraph) => void;
  /** Pop the last undo point; `current` is pushed onto the redo stack. */
  undo: (current: FlowGraph) => FlowGraph | null;
  /** Pop the last redo point; `current` is pushed back onto the undo stack. */
  redo: (current: FlowGraph) => FlowGraph | null;
  canUndo: () => boolean;
  canRedo: () => boolean;
  clear: () => void;
  /** Test/inspection helper — sizes of the two stacks. */
  size: () => { past: number; future: number };
};

export function createHistory(limit = 100): HistoryController {
  let past: FlowGraph[] = [];
  let future: FlowGraph[] = [];

  return {
    push(graph) {
      past.push(graph);
      if (past.length > limit) past.shift();
      future = [];
    },
    undo(current) {
      const prev = past.pop();
      if (prev === undefined) return null;
      future.push(current);
      return prev;
    },
    redo(current) {
      const next = future.pop();
      if (next === undefined) return null;
      past.push(current);
      return next;
    },
    canUndo: () => past.length > 0,
    canRedo: () => future.length > 0,
    clear() {
      past = [];
      future = [];
    },
    size: () => ({ past: past.length, future: future.length }),
  };
}

import type {
  ExecutorRegistry,
  FlowEdge,
  FlowGraph,
  FlowNode,
  NodeExecutor,
  RunEvent,
} from "../types";
// Both modules are React-free by design — the `/engine` entry must not pull in
// React. Import them directly rather than via the `registry` barrel, which
// re-exports the RegistryNode component.
import { getNodeKind, kindIds } from "../registry/registry";
import { resolveNodePorts } from "../registry/ports";
import { RunIdentity, type RunIdentityJson } from "./run-identity";
import { TerminalSessions, specForLane } from "./terminal-sessions";
import { undeliveredEdgeWarnings } from "./undelivered-edges";
import { resolveWorkflowProps } from "./workflow-props";

export type RunOptions = {
  /** Stop the run after this many ms. Default: no timeout. */
  timeoutMs?: number;
  /** Abort signal — host can cancel the run. */
  signal?: AbortSignal;
  /** Initial inputs supplied to entry-point nodes (no incoming edges). */
  initialInputs?: Record<string, Record<string, unknown>>;
  /**
   * Values for the inputs the graph DECLARES, passed by name.
   *
   * The flat, node-id-free way to configure a run. `initialInputs` is keyed by
   * node id, so a caller had to know the trigger was called `t` and a rename
   * broke every caller while the graph stayed valid. Props are checked against
   * `graph.inputs`, so a misspelling fails the run instead of sitting unread.
   */
  props?: Record<string, unknown>;
  /**
   * Which ENTRY POINTS are live — the ids of nodes with NO incoming edges this
   * run should start from. Omit it and every entry point runs, exactly as
   * before the option existed.
   *
   * A graph may hold more than one trigger — a `manual_trigger` for
   * hand-testing beside the event trigger that runs it for real — and a trigger
   * has no inbound edges, which IS the readiness rule. So without this, every
   * trigger's branch runs on every run, whichever one fired. The triggers
   * themselves are harmless; everything DOWNSTREAM of the ones that did not
   * fire is not. A `user_input` stranded on the manual branch parks an
   * event-driven run to ask a person for data the event already supplied,
   * which from outside looks like the event trigger being ignored.
   *
   * Naming the live entry points makes the others INACTIVE, and the existing
   * "at least one active inbound edge" rule then skips everything reachable
   * only from them. No new routing logic.
   *
   * Three edges, each pinned by `flow/entry-points` in
   * `@particle-academy/fancy-conformance`:
   *  - `undefined` is NOT `[]`. Unset runs every entry point; an empty array
   *    says none is live and runs nothing.
   *  - A node reachable from SEVERAL entry points still runs when any one of
   *    them fires — one active inbound edge is enough, as always.
   *  - Naming a node that HAS inbound edges names no entry point, so every real
   *    entry is inactive and nothing runs. That falls out of the rule rather
   *    than being special-cased; validate your ids if you want a typo to be
   *    loud, because the runtime cannot tell one from a deliberate empty
   *    selection.
   */
  entryNodes?: string[];
  /** Nesting depth — set by `subflow` when it runs a child graph. */
  depth?: number;
  /**
   * Who is running, so a writing node can derive a stable idempotency key.
   *
   * A bare string is taken as the run key. **Deliberately not defaulted:** a
   * minted-per-call key would change on every whole-run retry, which is exactly
   * the failure an idempotency key exists to prevent — so a host that has not
   * supplied one gets `ctx.run === undefined` and a connector that declines to
   * write blind, rather than a plausible-looking key that double-charges.
   */
  run?: RunIdentity | RunIdentityJson | string;
  /**
   * Outputs already checkpointed for this run, keyed by node id.
   *
   * A node present here is **republished, not re-executed** — its stored value
   * goes back onto the same ports, so downstream routing reproduces exactly
   * what it did the first time. This is what makes a per-node durable driver
   * possible without a second copy of the routing rules, and it is how the PHP
   * and Python runtimes have always resumed.
   */
  resumeOutputs?: Record<string, unknown>;
  /**
   * Executors bound to ONE node id each, matched against `node.id` and nothing
   * else. They outrank every entry of the executor registry.
   *
   * The registry cannot say this. It is one flat object, and `executorLookupIds`
   * tries a key as the node's id AND as its kind, so a key that is both is both:
   * binding `host_kind` to pin the node CALLED `host_kind` also rebinds every
   * node whose kind is `host_kind`. That is the registry's contract (pinned by
   * `flow/executor-resolution`) and it stays. This is the separate channel for a
   * binding that must not leak into the kind namespace -- the PHP twin's
   * `bindNode`, which has always been kept apart from `bind`.
   *
   * The durable replay fences every node but its target through this. Through
   * the registry, a node whose id matched a kind fenced every node of that kind,
   * and the durable run reported success having run nothing.
   *
   * NOT handed down to a nested run. Node ids belong to one graph: a `subflow`
   * child's `t` is not its parent's `t`, so `ctx.executors` stays the registry
   * alone.
   */
  nodeExecutors?: Record<string, NodeExecutor>;
};

export type RunResult = {
  ok: boolean;
  /** Outputs collected per node, keyed by node id. */
  outputs: Record<string, unknown>;
  /** Error captured if any node threw. */
  error?: string;
};

/**
 * runFlow — topological execution of a FlowGraph against an ExecutorRegistry.
 *
 * Each node runs once, when all upstream nodes have produced outputs on the
 * connected ports. Decision nodes (or any executor that returns `{ branch:
 * 'true' }`) can short-circuit specific output ports — only edges leaving
 * an "active" port propagate to downstream nodes.
 *
 * Cycles are detected and abort the run with an error.
 *
 * The `onEvent` callback receives a stream of `RunEvent`s — wire it to a
 * status feed, log panel, or store.
 */
export async function runFlow(
  graph: FlowGraph,
  executors: ExecutorRegistry,
  onEvent: (event: RunEvent) => void = () => {},
  options: RunOptions = {},
): Promise<RunResult> {
  const { signal, initialInputs = {}, timeoutMs, depth = 0, resumeOutputs = {}, entryNodes, nodeExecutors } = options;
  const run = options.run === undefined ? undefined : RunIdentity.from(options.run);
  const outputs: Record<string, unknown> = {};
  const portValues = new Map<string, unknown>(); // key: `${nodeId}:${portId}`
  const completed = new Set<string>();
  const errors: string[] = [];

  // Topological order via Kahn's algorithm. We allow nodes to run as soon
  // as their incoming edges' source ports have produced values, so the
  // order here is just a deterministic baseline used for cycle detection.
  const order = topoSort(graph);
  if (order === null) {
    const msg = "Cycle detected in flow graph — aborting.";
    onEvent({ type: "run-error", error: msg });
    return { ok: false, outputs, error: msg };
  }

  // Props are checked BEFORE anything runs, and a failure aborts the run.
  //
  // Before a node executes, not after: a workflow whose third node needed a
  // value the caller misspelled would otherwise do two nodes' worth of real
  // work — sending, writing, charging — and only then discover the call was
  // malformed. Validation that happens after a side effect is not validation.
  const propsCheck = resolveWorkflowProps(graph.inputs, options.props);
  if (!propsCheck.ok) {
    onEvent({ type: "run-error", error: propsCheck.error });
    return { ok: false, outputs, error: propsCheck.error };
  }
  const props = propsCheck.props;
  const declaresProps = (graph.inputs?.length ?? 0) > 0;

  const incomingByNode = indexIncoming(graph.edges);
  // Built ONCE. Used only to explain an undelivered edge, but building it per
  // node would make a diagnostic quietly O(n^2) on the hot path.
  const nodesById = new Map(graph.nodes.map((n) => [n.id, n]));

  // Terminal lanes. Constructed unconditionally and costing nothing until a
  // node inside one actually runs — a graph with no terminal lane never asks
  // for a host, so nothing spawns and nothing needs one registered.
  const sessions = new TerminalSessions(graph);
  const isTerminalLane = (candidate: FlowNode): boolean =>
    getNodeKind(candidate.type ?? "")?.name === "@particle-academy/terminal_lane";

  const terminalAccessorFor = (node: FlowNode) => {
    const laneId = sessions.laneFor(node.id, isTerminalLane);
    if (laneId === null) return undefined;

    const lane = graph.nodes.find((n) => n.id === laneId);
    if (!lane) return undefined;

    // Returned as a FUNCTION rather than an open session, so the terminal opens
    // on first USE rather than when a node in the lane starts. A node that
    // never touches its terminal never spawns one, which is what makes the
    // lane safe to draw around nodes that mostly do other things.
    return {
      session: () => sessions.session(laneId, specForLane(lane)),
      // Awaits the session first on purpose. A transcript handed out before
      // anything is feeding it would look perfectly healthy and match nothing,
      // and "waited and nothing came" is the hardest failure here to tell apart
      // from a process that is simply slow.
      transcript: async () => {
        await sessions.session(laneId, specForLane(lane));
        return sessions.transcriptFor(laneId);
      },
    };
  };

  const timer = timeoutMs ? setTimeout(() => errors.push(`Run timed out after ${timeoutMs}ms`), timeoutMs) : null;

  onEvent({ type: "run-start" });

  try {
    for (const node of order) {
      if (signal?.aborted) throw new Error("aborted");
      if (errors.length) break;

      // A checkpointed node is republished, never re-executed. Publishing the
      // stored value back onto its own ports is what makes the resume exact:
      // the branch it took, the ports it lit and the inputs its successors
      // collect are all reproduced by the engine's own rules rather than by a
      // driver's recollection of them.
      if (Object.prototype.hasOwnProperty.call(resumeOutputs, node.id)) {
        const stored = resumeOutputs[node.id];
        outputs[node.id] = stored;
        const activated = activatedPorts(node, stored);
        for (const portId of activated.ports) {
          const value = portValueOf(activated, portId);
          portValues.set(`${node.id}:${portId}`, value);
          onEvent({ type: "node-output", nodeId: node.id, portId, value });
        }
        completed.add(node.id);
        onEvent({ type: "node-status", nodeId: node.id, status: "done", text: "resumed" });
        continue;
      }

      const incoming = incomingByNode.get(node.id) ?? [];

      // An ENTRY POINT this run did not start from is inactive.
      //
      // A node with no inbound edges is unconditionally ready -- that IS the
      // readiness rule -- so a graph with two triggers ran both branches on
      // every run, whichever trigger actually fired. Marking the unnamed ones
      // inactive here lets the "at least one active inbound edge" test below
      // skip everything reachable only from them, with no new routing logic.
      //
      // Gates only nodes with NO incoming edges: a node further down the graph
      // is not an entry point, and its readiness is still decided by its edges.
      if (incoming.length === 0 && entryNodes !== undefined && !entryNodes.includes(node.id)) {
        onEvent({ type: "node-status", nodeId: node.id, status: "idle", text: "skipped" });
        continue;
      }

      // AN EDGE THAT DELIVERS NOTHING MUST SAY SO.
      //
      // Checked HERE, before the activity gate, because the two outcomes are
      // both silent and only one reaches `collectInputs`: a node whose only
      // inbound edge is bad is SKIPPED, and one with another live edge RUNS with
      // that port missing. The rule itself lives in `undeliveredEdgeWarnings`,
      // which the durable coordinator also asks at its skip decision -- one
      // implementation, so the two paths cannot disagree about a handle.
      for (const warning of undeliveredEdgeWarnings(node, incoming, portValues, completed, nodesById)) {
        onEvent(warning);
      }

      // Run a node once any upstream branch reaches it. We iterate in
      // topological order, so by the time we reach this node every upstream
      // node has been processed — each incoming edge is therefore *settled*
      // (active or dead, never still-pending). Requiring ALL incoming edges to
      // be active wrongly skipped MERGE POINTS: when a Decision routes down one
      // branch, the other branch's edge stays dead forever, so an `every` check
      // skipped the shared continuation node and halted the run after the first
      // branch (#1). Run when AT LEAST ONE incoming edge is active —
      // collectInputs() only reads from the active ones. A genuine parallel
      // join still works: in topo order both of its inputs are already active.
      if (incoming.length > 0) {
        const anyActive = incoming.some((e) => portValues.has(`${e.source}:${e.sourceHandle ?? "out"}`));
        if (!anyActive) {
          onEvent({ type: "node-status", nodeId: node.id, status: "idle", text: "skipped" });
          continue;
        }
      }

      // Notes/annotations + layout (lane/pool) nodes are visual only — never
      // executed and never fed to runners. Their config (a note's text, a lane's
      // title) stays in the document for editors + MCP tools, but the engine
      // walks straight past them. Edges cross lanes freely, so grouping never
      // affects topology.
      const visualKind = getNodeKind(node.type ?? "");
      const isLayout = visualKind?.category === "layout";
      const isAnnotation = node.type === "note" || visualKind?.category === "annotation";
      if (isLayout || isAnnotation) {
        onEvent({
          type: "node-status",
          nodeId: node.id,
          status: "idle",
          text: isLayout ? "lane" : "annotation",
        });
        continue;
      }

      onEvent({ type: "node-status", nodeId: node.id, status: "running" });
      announce(onEvent, node, "start");

      const inputs = collectInputs(node, incoming, portValues, initialInputs, props, declaresProps);
      const exec = pickExecutor(executors, node, nodeExecutors);
      if (!exec) {
        // Name what was LOOKED FOR, not just what the node calls itself.
        //
        // This said `kind=${node.type}` — so a registry keyed under one of the
        // kind's other ids produced "kind=manual_trigger is missing" about a
        // kind that exists AND is registered, just under a different key. The
        // consumer who reported it reasonably read that as the kind being
        // absent and went looking for a missing package.
        // The wildcard is part of `executorLookupIds` now, so it is already in
        // the list — appending "and the wildcard" as well made the message name
        // it twice, and the test that reads the ids back out of the message
        // parsed the prose between the two quoted stars as an id.
        const tried = executorLookupIds(node);
        const msg = `No executor registered for kind=${node.type}`
          + ` — tried ${tried.map((id) => `"${id}"`).join(", ")}`
          + `. Key your registry by one of those.`;
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }

      try {
        const result = await Promise.resolve(
          exec({
            node,
            inputs,
            abort: (reason) => { throw new Error(reason ?? "aborted"); },
            emit: onEvent,
            executors,
            depth,
            run,
            // Structural executors derive a nested lane from the graph they are
            // in; `for_each`'s `item` port cannot be implemented without it.
            graph,
            terminal: terminalAccessorFor(node),
          }),
        );
        outputs[node.id] = result;

        // Decide which output ports were activated. Three conventions:
        //  1) If result is `{ __port: "out", value: x }`, only that port emits.
        //  2) If result has `branch: <portId>`, only that port emits (decision sugar).
        //  3) If result has `__ports`, exactly those emit — a list shares one
        //     payload, a map gives each its own.
        //  4) Otherwise, the value is published on every declared output port.
        const activated = activatedPorts(node, result);
        for (const portId of activated.ports) {
          const value = portValueOf(activated, portId);
          portValues.set(`${node.id}:${portId}`, value);
          onEvent({ type: "node-output", nodeId: node.id, portId, value });
        }
        completed.add(node.id);
        onEvent({ type: "node-status", nodeId: node.id, status: "done" });
        // Only on the success path, and deliberately so: a `stoppingMsg` of
        // "Analysis complete" emitted after a throw tells a human the opposite
        // of what happened, in the part of the UI they trust most. A failure
        // reports through node-status/log, which is what those exist for.
        announce(onEvent, node, "end");
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }
    }
  } finally {
    if (timer) clearTimeout(timer);

    // Terminals close HERE, in the same `finally` that clears the timer, so
    // they go away on the error and abort paths too — not only when a run ends
    // tidily. A PTY that outlives its run is a process nobody is watching and
    // nothing will close.
    //
    // Failures are reported and swallowed rather than thrown: this is the
    // teardown path, and throwing would replace the run's real error with a
    // cleanup error, hiding what actually went wrong behind the consequence.
    for (const error of await sessions.closeAll()) {
      onEvent({ type: "log", level: "warn", message: `terminal close failed: ${error.message}` });
    }
  }

  const ok = errors.length === 0;
  onEvent({ type: "run-end", ok });
  return ok ? { ok, outputs } : { ok, outputs, error: errors[0] };
}

function indexIncoming(edges: FlowEdge[]): Map<string, FlowEdge[]> {
  const map = new Map<string, FlowEdge[]>();
  for (const e of edges) {
    const list = map.get(e.target) ?? [];
    list.push(e);
    map.set(e.target, list);
  }
  return map;
}

function topoSort(graph: FlowGraph): FlowNode[] | null {
  const inDegree = new Map<string, number>();
  for (const n of graph.nodes) inDegree.set(n.id, 0);
  for (const e of graph.edges) inDegree.set(e.target, (inDegree.get(e.target) ?? 0) + 1);
  const queue: string[] = [];
  for (const [id, d] of inDegree) if (d === 0) queue.push(id);
  const ordered: string[] = [];
  while (queue.length) {
    const id = queue.shift()!;
    ordered.push(id);
    for (const e of graph.edges) {
      if (e.source !== id) continue;
      const next = (inDegree.get(e.target) ?? 0) - 1;
      inDegree.set(e.target, next);
      if (next === 0) queue.push(e.target);
    }
  }
  if (ordered.length !== graph.nodes.length) return null;
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  return ordered.map((id) => byId.get(id)!).filter(Boolean);
}

function collectInputs(
  node: FlowNode,
  incoming: FlowEdge[],
  portValues: Map<string, unknown>,
  initial: Record<string, Record<string, unknown>>,
  props: Record<string, unknown>,
  declaresProps: boolean,
): Record<string, unknown> {
  const inputs: Record<string, unknown> = { ...(initial[node.id] ?? {}) };

  // ENTRY POINTS are seeded with the props by their bare names.
  //
  // This is what lets an existing graph keep working unchanged. A trigger that
  // reads `{{ topic }}` was fed by `initialInputs[triggerId].topic`; a caller
  // moving to props passes `{ topic }` and the node sees exactly what it saw
  // before. Only entry points, because a node in the middle of a graph reading
  // a bare `topic` would be shadowing whatever its upstream edge is called.
  //
  // Never clobbers: a value already seeded by the host is the host's.
  if (incoming.length === 0) {
    for (const [name, value] of Object.entries(props)) {
      if (!(name in inputs)) inputs[name] = value;
    }
  }
  for (const e of incoming) {
    const portId = e.targetHandle ?? "in";
    const key = `${e.source}:${e.sourceHandle ?? "out"}`;
    // A branch that never fired has no entry in portValues. Assigning its
    // `undefined` would CLOBBER the value the branch that DID fire already
    // contributed on this same handle — emptying every merge point downstream
    // of a decision, silently, with the run still reporting success.
    //
    // This is the other half of the merge-point bug above: that fix stopped the
    // shared continuation node being skipped, but it still arrived with nothing
    // whenever a later inactive edge happened to be last in `incoming`.
    if (!portValues.has(key)) continue;
    inputs[portId] = portValues.get(key);

    // ALSO address it by the SOURCE NODE'S ID, when the edge named no handle.
    //
    // Authors reach for node ids -- every graph tool addresses nodes that way,
    // so `{{ n2.text }}` is the first thing written, by people and far more
    // often by assistants generating graphs. That resolved to nothing, and
    // NOTHING FAILED: an unresolvable path yields "", so the node ran, the run
    // reported success, and the damage was output that was quietly wrong. A
    // consumer shipped a file named `document.md` containing the literal text
    // of its own template, on a green run (fancy-flow-php#8).
    //
    // `targetHandle` already covers this and stays the right mechanism for
    // reading something other than the immediate predecessor -- but it is set
    // on the EDGE, which is not where an author is looking while writing a
    // node's config. The model was not wrong; the obvious spelling meant
    // nothing.
    //
    // Only for edges that declared NO handle: an edge that named one said what
    // it meant, and a second key under the source id would quietly widen a
    // deliberate contract. `??=` so nothing already seeded -- by the host's
    // initialInputs or an earlier edge -- is ever clobbered.
    if (e.targetHandle == null && !(e.source in inputs)) {
      inputs[e.source] = portValues.get(key);
    }
  }

  // EVERY node gets `$props` — but ONLY when the workflow declares inputs.
  //
  // The first half is what makes props usable at depth. Seeding entry points
  // alone would mean a node six hops downstream had the value threaded through
  // every edge in between, and every hop is somewhere it can be dropped. It
  // costs nothing to resolve because `$props` is an ORDINARY KEY in the inputs
  // object: `resolvePath` already walks dot-paths against it, so
  // `{{ $props.topic }}` works with no change to any expression resolver in any
  // of the three runtimes.
  //
  // The second half is a CORRECTION, and the golden parity fixtures caught it.
  // An earlier draft wrote `$props` unconditionally, justified as "so
  // `{{ $props.x }}` resolves to null rather than throwing" — which is not
  // true. `resolvePath` returns null for any unresolvable path, so on a graph
  // declaring nothing the key changes no behaviour at all. What it DOES do is
  // add a key to every executor's inputs, on every graph, forever — which
  // showed up instantly as a diff in every stored golden.
  //
  // `ConnectorFacet::from` states the same rule for the same reason: a payload
  // gaining a key on every entry is a wire change for no gain, and the ABSENCE
  // of a key is already the honest way to say "this one takes no props".
  //
  // Keyed on the DECLARATION rather than on whether a value arrived: a workflow
  // whose inputs are all optional and all omitted still declared a contract, so
  // `$props` is present and empty.
  if (declaresProps) inputs.$props = props;

  return inputs;
}

/**
 * Every key a node's executor may legitimately be registered under, in
 * precedence order. **This is the resolution rule** — `pickExecutor` walks this
 * list and takes the first hit, and the failure message lists the same ids.
 *
 * That sharing is the point, and it used to be a claim rather than a fact: this
 * docblock already said "shared by the lookup and by its failure message" while
 * `pickExecutor` re-implemented the walk beside it. The two agreed until the
 * precedence changed, and then the message listed an id the lookup no longer
 * tried — sending a reader to check something that never happened, which the
 * comment correctly named as worse than listing nothing. **Prose next to a check
 * is not the check.** One list now, walked by both, so they cannot drift.
 *
 * The order, and why:
 *
 * 1. `node.id` — the per-node override. First so a graph can pin ONE node to a
 *    stub without unbinding that kind for every other node using it.
 * 2. `node.type`, then every id its kind answers to — **if `node.type` names a
 *    registered kind, it is authoritative and `data.kind` is not consulted at
 *    all.** A node that says it is an `llm_call` must never quietly run another
 *    kind's code; it fails closed instead.
 * 3. Otherwise `data.kind` and its kind's ids. A `node.type` naming no
 *    registered kind is not a claim about behaviour — usually it is an xyflow
 *    RENDERER type (`"fancyNode"`), which is ordinary practice, and then
 *    `data.kind` is the only real answer. This branch also covers `type` absent.
 * 4. `"*"` — the wildcard, last, and a sentinel rather than a kind: it is never
 *    expanded through the alias machinery, or every unmatched node would bind to
 *    whatever a kind literally named `*` aliased to.
 *
 * Pinned as `flow/executor-resolution` in `@particle-academy/fancy-conformance`.
 */
function executorLookupIds(node: FlowNode): string[] {
  const ids: string[] = [node.id];
  if (node.type) ids.push(node.type);

  const typeKind = node.type ? getNodeKind(node.type) : null;

  if (typeKind) {
    for (const id of kindIds(typeKind)) ids.push(id);
  } else {
    const declared = (node.data as { kind?: unknown } | undefined)?.kind;
    const kindName = typeof declared === "string" && declared !== "" ? declared : null;

    if (kindName) {
      ids.push(kindName);
      const dataKind = getNodeKind(kindName);
      if (dataKind) {
        for (const id of kindIds(dataKind)) ids.push(id);
      }
    }
  }

  ids.push("*");

  return [...new Set(ids)];
}

function pickExecutor(
  executors: ExecutorRegistry,
  node: FlowNode,
  nodeExecutors?: Record<string, NodeExecutor>,
): NodeExecutor | undefined {
  // A node-only binding is looked up by the node's id and NO other key, which
  // is the whole reason it is not an entry in `executors` (see
  // `RunOptions.nodeExecutors`). Own properties only: a node called
  // `constructor` must not find `Object`.
  const pinned = nodeExecutors && Object.prototype.hasOwnProperty.call(nodeExecutors, node.id)
    ? nodeExecutors[node.id]
    : undefined;
  if (pinned) return pinned;

  // The whole rule lives in `executorLookupIds` -- see its docblock. Walking
  // that one list is what keeps the resolution and the failure message from
  // ever disagreeing about which keys were tried.
  //
  // The HOST registry is consulted first, and that order is the contract: a
  // kind ships an executor as a default, and a host that registers its own
  // takes over. Reversing it would make a builtin unoverridable.
  for (const id of executorLookupIds(node)) {
    if (executors[id]) return executors[id];
  }

  // Then the kind's own, for the kinds that ship one.
  //
  // This fallback did not exist, and `NodeKindDefinition.executor` was
  // therefore a field nothing read. `subflow` and `llm_router` have both
  // declared one since they were written, and both were unreachable through
  // `runFlow`: a consumer who called `registerBuiltinKinds()` and ran a graph
  // containing a subflow node got "No executor registered for kind=subflow"
  // about a kind that ships its executor in the same object as its schema.
  //
  // It survived because the two are unit-tested by calling the executor
  // directly — which proves the executor works and says nothing about whether
  // anything can reach it. A declared capability with no reader is the shape
  // this estate keeps finding, and the only reliable way to catch it is a test
  // that goes through the front door.
  return getNodeKind(node.type ?? "")?.executor;
}

function activatedPorts(node: FlowNode, result: unknown): { ports: string[]; value: unknown; values?: Record<string, unknown> } {
  if (result && typeof result === "object") {
    const r = result as Record<string, unknown>;
    if (typeof r.__port === "string") {
      return { ports: [r.__port], value: r.value };
    }
    // A CHOSEN SUBSET (fancy-flow-php#18): a list lights those ports with one
    // payload, a map gives each lit port its own. Before this a node could light
    // one port or all of them, so a router that matched two of five had to drop
    // work or wake lanes nobody asked for.
    //
    // An empty list lights NOTHING, deliberately — the same rule an explicitly
    // empty `outputs` array follows below. `values` is read per port, so a
    // payload that is present and null stays null rather than falling back to
    // the whole result, which is the trap `branch` already had to learn.
    if (Array.isArray(r.__ports)) {
      return { ports: r.__ports.filter((p): p is string => typeof p === "string"), value: r.value };
    }
    if (r.__ports && typeof r.__ports === "object") {
      const values = r.__ports as Record<string, unknown>;
      return { ports: Object.keys(values), value: r.value, values };
    }
    if (typeof r.branch === "string") {
      // `Object.hasOwn`, NOT `??`. The two are different questions:
      //   no `value` key at all -> the whole result IS the payload (the case
      //                            this fallback exists for)
      //   `value` present, null -> the payload is null; pass null on
      // `r.value ?? r` cannot tell them apart, so a branch whose payload was
      // null leaked the WRAPPER downstream -- every following node received
      // `{ branch, value }`, two fields no kind declares, while the fields it
      // does declare were absent. The reachable path is an upstream `transform`
      // whose dot-path did not resolve, which is exactly the silent-null case.
      // `Port.only`'s `?? null` never had it. All four runtimes shared this,
      // identically -- so no parity table could catch it; they agreed on being
      // wrong.
      return { ports: [r.branch], value: Object.prototype.hasOwnProperty.call(r, "value") ? r.value : r };
    }
  }
  // Resolve through the shared helper so the ports the runtime activates are
  // the same ones the canvas drew — including config-driven ports, which the
  // node's `data` does not carry. Falls back to a lone `out` when a node
  // declares nothing.
  const kind = getNodeKind((node.data as any)?.kind ?? node.type ?? "") ?? undefined;
  const declared = resolveNodePorts(node, kind).outputs?.map((p) => p.id);

  // THREE states, and the middle one is the point. `undefined` means nothing —
  // neither the node nor its kind — declared any ports, which falls back to a
  // lone `out` so a hand-written document can omit them entirely and still
  // chain. An empty ARRAY means a node (or a terminal kind) declaring that it
  // publishes NOTHING, and it is honoured literally.
  //
  // This line read `declared?.length ? declared : ["out"]` until 0.76.0, and
  // `[]` is falsy, so the two collapsed into one: a node that had explicitly
  // said it publishes nothing published `out` instead. That made this engine
  // disagree with the PHP, Python and Rust twins on the identical document —
  // and this editor WRITES `outputs: []` on export for a terminal node, so the
  // disagreement was reachable by round-tripping a graph rather than by
  // hand-authoring anything unusual.
  //
  // It was a silent truncation the other way round that justified the old
  // behaviour: publishing nothing cuts every chain through such a node. That
  // cut is no longer silent — an edge leaving a node that published nothing
  // raises the undelivered-edge warning, whose port lookup honours the same
  // three states. Strict AND loud; either alone would have been worse than
  // neither.
  return { ports: declared ?? ["out"], value: result };
}

/**
 * What one lit port carries: its own entry when the result named ports
 * individually, otherwise the single payload every lit port shares.
 *
 * `hasOwnProperty`, not `??`: a per-port payload that is present and null is a
 * payload. `values[portId] ?? value` would quietly hand that port the shared
 * value instead — the same confusion `branch` had between "no key" and "null".
 */
function portValueOf(activated: { value: unknown; values?: Record<string, unknown> }, portId: string): unknown {
  return activated.values && Object.prototype.hasOwnProperty.call(activated.values, portId)
    ? activated.values[portId]
    : activated.value;
}

/**
 * Emit a node's own status message for one phase of its execution, if it
 * declared one.
 *
 * Opt-in by absence: a node with no `startingMsg` / `stoppingMsg` says nothing,
 * because most nodes in a real graph are plumbing and narrating all of them
 * buries the two or three steps a person actually wants to follow.
 *
 * A message must be a non-empty string after trimming. An empty string is the
 * shape a cleared editor field takes, and a blank line in a progress feed is
 * indistinguishable from a real message that happens to render as nothing —
 * so it is treated as "not set" rather than as "announce nothing visible".
 */
function announce(
  onEvent: (event: RunEvent) => void,
  node: FlowNode,
  phase: "start" | "end",
): void {
  const data = node.data as { startingMsg?: unknown; stoppingMsg?: unknown } | undefined;
  const raw = phase === "start" ? data?.startingMsg : data?.stoppingMsg;
  if (typeof raw !== "string") return;

  const message = raw.trim();
  if (message === "") return;

  onEvent({ type: "node-message", nodeId: node.id, phase, message });
}

import type { ConfigField, NodeCategory, NodeKindDefinition } from "./types";
// The DATA module, deliberately -- importing `./builtin` here is what put
// React into `/engine` (#11). See that file for the whole story.
import { registerBuiltinKindData } from "./builtin-kinds";

const kinds = new Map<string, NodeKindDefinition<any, any, any>>();
/** alias → canonical name. See `resolveKindId`. */
const aliases = new Map<string, string>();
const listeners = new Set<() => void>();
/**
 * canonical name → presentation patch. See `overrideNodeKind`.
 *
 * Kept SEPARATE from `kinds` on purpose: an override has to survive its base
 * kind being re-registered (HMR, a later `registerBuiltinKinds()`, a package
 * upgrade). Merging into the definition would mean the next registration
 * silently reverts the consumer's naming.
 */
const overrides = new Map<string, NodeKindPresentation>();

/**
 * Names a HOST registered, as opposed to names the builtin kit registered.
 *
 * Builtin registration is not a one-shot event: `registerBuiltinKinds()` is
 * exported, the four kinds with renderers are deliberately registered twice
 * (React-free table, then decorated), and since 0.66.1 the root barrel calls it
 * as an import side effect. So "the builtins register again" happens routinely
 * and at times no consumer can predict.
 *
 * Without this set, every one of those occasions silently reverted a host's
 * replacement of a builtin — the only mechanism we offer for extending one.
 * A consumer's field would vanish from the editor while their server kept
 * validating it, and whether it happened at all depended on which module their
 * bundler evaluated second.
 *
 * This is the same protection `overrides` already had, and for the same stated
 * reason. Presentation patches were kept safe from re-registration; behavioural
 * replacement was not, and nothing marked the asymmetry.
 */
const hostOwned = new Set<string>();

/**
 * canonical name -> schema patch from a SERVER. See `applyKindSchemaOverlay`.
 *
 * Kept in its own map for the reason `overrides` is: a patch stored ON the kind
 * is reverted the next time that kind is registered, and builtin registration
 * is not a one-shot event. 0.66.2 was exactly that bug for behavioural
 * replacement; this is the same shape and gets the same protection rather than
 * waiting to learn it twice.
 */
const schemaOverlays = new Map<string, KindSchemaOverlay>();

/**
 * The builtin definition for a name, kept even while a host owns the name.
 *
 * Without it, releasing a claim could only DELETE the entry — which is a worse
 * state than before the override, not a return to it: the palette loses the
 * node and the canvas renders raw kind ids where a label belongs.
 */
const builtinDefs = new Map<string, NodeKindDefinition<any, any, any>>();

let builtinsEnsured = false;

/**
 * Put the builtin kit in the registry before anyone reads or writes it.
 *
 * Registration used to be a bare `registerBuiltinKinds()` in `src/index.ts`, so
 * it fired ONLY as an import side effect of that one entry. Every other route in
 * — the `/engine` and `/registry` subpaths, or a root import that TypeScript
 * erases because it only took types — got an empty registry, and an empty
 * registry is silent: `getNodeKind()` returns null, `FlowViewer` falls through
 * its title chain, and the canvas shows `@particle-academy/llm_call` where a
 * name belongs.
 *
 * Doing it here instead means correctness no longer depends on which entry a
 * consumer imported, or on a bundler agreeing to keep a top-level statement.
 *
 * The flag is set BEFORE the call so a listener that reads the registry from
 * inside `notify()` cannot recurse. `registerNodeKind` ensures too, so builtins
 * are always in place before a host registers over one of them.
 */
export function ensureBuiltinKinds(): void {
  if (builtinsEnsured) return;
  builtinsEnsured = true;
  registerBuiltinKindData();
}

/**
 * The presentation fields a consumer may override on someone else's node kind.
 *
 * Deliberately excludes everything behavioural — `executor`, `inputs`,
 * `outputs`, `configSchema`, `sideEffects`. An "override" that could change
 * those is not an override, it is a fork wearing a friendly name, and it would
 * desync the graph from the runtime that executes it.
 *
 * `category` IS included: which drawer a node appears in is presentation, and a
 * consumer regrouping their palette is the same kind of act as renaming.
 */
export type NodeKindPresentation = Partial<
  Pick<NodeKindDefinition, "label" | "description" | "icon" | "accent" | "category">
>;

/**
 * registerNodeKind — install a node kind in the global registry. Returns
 * an `unregister` function. Calling with the same name replaces the prior
 * registration (handy for HMR).
 *
 * A kind's `name` is its CANONICAL id and is what gets written into saved
 * documents. Publish namespaced (`@fancy/llm_branch`, `@acme/salesforce_upsert`)
 * and list any previous bare names in `aliases`, so graphs saved before the
 * rename keep resolving.
 */
export function registerNodeKind<TC = any, TI = any, TO = any>(
  definition: NodeKindDefinition<TC, TI, TO>,
): () => void {
  ensureBuiltinKinds();
  // Claiming the name is what protects it: from here on the builtin kit will
  // not overwrite this entry, however many times it re-registers.
  hostOwned.add(definition.name);
  kinds.set(definition.name, definition as NodeKindDefinition<any, any, any>);
  for (const alias of definition.aliases ?? []) aliases.set(alias, definition.name);
  notify();
  return () => {
    if (kinds.get(definition.name) === (definition as any)) {
      kinds.delete(definition.name);
      hostOwned.delete(definition.name);
      for (const alias of definition.aliases ?? []) {
        if (aliases.get(alias) === definition.name) aliases.delete(alias);
      }
      notify();
    }
  };
}

/**
 * Register a kind AS PART OF THE BUILTIN KIT — never overwriting a host.
 *
 * The builtin modules use this instead of `registerNodeKind` so that repeated
 * builtin registration is safe. It still replaces builtins (the four kinds with
 * renderers are registered twice on purpose, plain table then decorated), but
 * it steps aside for any name a host has claimed.
 *
 * Internal: not re-exported from the package. A consumer wanting to install a
 * kind uses `registerNodeKind`, and gets ownership of the name by doing so.
 */
export function registerBuiltinKindInternal(
  definition: NodeKindDefinition<any, any, any>,
): void {
  // Recorded BEFORE the ownership check: a host owning the name now is exactly
  // when we will later need the builtin to hand back.
  builtinDefs.set(definition.name, definition);

  if (hostOwned.has(definition.name)) return;

  kinds.set(definition.name, definition);
  for (const alias of definition.aliases ?? []) {
    if (!hostOwned.has(aliases.get(alias) ?? "")) aliases.set(alias, definition.name);
  }
}

/**
 * Release a host's claim on a name and restore the builtin behind it.
 *
 * The counterpart to `registerNodeKind` replacing a builtin. `registerNodeKind`
 * does return an unregister closure, but a consumer reading the export list
 * cannot find it, and one correctly concluded no such operation existed — so
 * this is the named form.
 *
 * **Test isolation is the reason it matters.** Before 0.66.2, calling
 * `registerBuiltinKinds()` restored the builtins over any override, and people
 * reasonably used that to reset between tests. Since 0.66.2 it correctly
 * refuses to overwrite a host's registration, so that reset silently stopped
 * resetting — and it does not fail where it broke, it fails as a wrong
 * assertion in a later, unrelated test. Use this instead.
 *
 * Returns whether anything was actually released, so a typo'd name is visible
 * rather than a silent no-op — a reset helper that quietly stops resetting is
 * the failure this exists to prevent.
 */
export function unregisterNodeKind(name: string): boolean {
  const canonical = resolveKindId(name) ?? name;

  const released = hostOwned.delete(canonical);
  if (!released && !kinds.has(canonical)) return false;

  const builtin = builtinDefs.get(canonical);
  if (builtin) {
    kinds.set(canonical, builtin);
    for (const alias of builtin.aliases ?? []) aliases.set(alias, canonical);
  } else {
    const previous = kinds.get(canonical);
    kinds.delete(canonical);
    for (const alias of previous?.aliases ?? []) {
      if (aliases.get(alias) === canonical) aliases.delete(alias);
    }
  }

  notify();

  return released;
}

/**
 * Empty the registry completely, builtins included.
 *
 * For tests that need a clean slate — in particular any test asserting how host
 * and builtin registration interact, which cannot be written against a registry
 * still holding the previous test's kinds. Production code has no reason to
 * call it: a registry that can be emptied at runtime is a registry that can be
 * emptied at the wrong moment.
 */
export function resetNodeKindsForTests(): void {
  kinds.clear();
  aliases.clear();
  overrides.clear();
  schemaOverlays.clear();
  hostOwned.clear();
  builtinDefs.clear();
  builtinsEnsured = false;
  notify();
}

/**
 * A schema patch for a kind, sourced from a host's SERVER-side registry.
 *
 * fancy-flow has two kind registries. The PHP one lets a host decorate a
 * builtin and that decoration reaches the runtime and validation; the editor,
 * built from the JS registry, never learned any of it. A consumer hit this as a
 * field that existed, ran, and had no control in the panel.
 *
 * **The server owns what a node is CONFIGURED with. The client keeps what a
 * node DOES.** Only the serialisable half is here on purpose: `executor`,
 * `component`, `renderBody` and `icon` cannot cross a wire, and neither can
 * ports — `PortSpec` may be a FUNCTION of config, and three builtins use that
 * form (`switch_case` groups match keys onto one port and joins their labels;
 * `subflow` branches on a derived mode and cares about order). Expressing those
 * as data needs a mini-language with grouping, conditionals and ordering, which
 * is a second implementation of logic that already exists.
 */
export type KindSchemaOverlay = {
  /** Canonical id or alias — resolved either way. */
  kind: string;
  /**
   * REPLACES the kind's schema. Never merges.
   *
   * The motivating case is *drop seven fields and add one*, and a merge cannot
   * express a removal. A `remove: string[]` beside a merge would be two
   * mechanisms for one job, and their interaction would be the next bug. The
   * server sends the schema it wants; that is the point of it owning one.
   */
  configSchema?: ConfigField[];
  label?: string;
  description?: string;
  category?: NodeCategory;
};

export type KindSchemaOverlayResult = {
  /** Canonical ids that matched a registered kind. */
  applied: string[];
  /**
   * Ids that matched NOTHING, reported rather than dropped.
   *
   * A server lists many kinds and a client will not have registered all of
   * them. Applying what matches and staying quiet about the rest is how a
   * field goes missing with no error anywhere — which is the defect this whole
   * mechanism exists to end, so it must not be reintroduced by the fix.
   */
  unknown: string[];
  unapply: () => void;
};

/**
 * Apply server-sourced schema patches to kinds this client already has.
 *
 * It does NOT register kinds. A kind must exist locally for its executor,
 * ports and renderer; the overlay corrects its schema, it does not conjure one.
 */
export function applyKindSchemaOverlay(
  overlays: readonly KindSchemaOverlay[],
): KindSchemaOverlayResult {
  ensureBuiltinKinds();

  const applied: string[] = [];
  const unknown: string[] = [];
  const previous = new Map<string, KindSchemaOverlay | undefined>();

  for (const overlay of overlays) {
    const canonical = resolveKindId(overlay.kind);
    if (!canonical) {
      unknown.push(overlay.kind);
      continue;
    }

    if (!previous.has(canonical)) previous.set(canonical, schemaOverlays.get(canonical));
    schemaOverlays.set(canonical, { ...overlay, kind: canonical });
    applied.push(canonical);
  }

  if (applied.length > 0) notify();

  return {
    applied,
    unknown,
    unapply: () => {
      for (const [canonical, before] of previous) {
        if (before) {
          schemaOverlays.set(canonical, before);
        } else {
          schemaOverlays.delete(canonical);
        }
      }
      notify();
    },
  };
}

/** Drop every server-sourced schema patch. Mostly for tests. */
export function clearKindSchemaOverlays(): void {
  if (schemaOverlays.size === 0) return;
  schemaOverlays.clear();
  notify();
}

/**
 * Resolve any id — canonical or alias — to the canonical one, or null.
 *
 * `kind` is persisted inside every saved graph, so a bare name that two
 * packages could both claim is unfixable after the fact: the ambiguous string
 * is already in the document. Canonical ids are namespaced; aliases exist so
 * documents written before namespacing keep opening.
 */
export function resolveKindId(id: string): string | null {
  ensureBuiltinKinds();
  if (kinds.has(id)) return id;
  const canonical = aliases.get(id);
  return canonical && kinds.has(canonical) ? canonical : null;
}

/**
 * Rename or re-describe a kind you did not author.
 *
 * Before this existed the only way to relabel a builtin was `registerNodeKind`
 * with a full definition — which REPLACES the kind, so a consumer wanting
 * "Call an API" instead of "HTTP Request" had to re-declare that node's
 * configSchema, ports, executor and renderer, and silently forfeited whatever
 * the builtin gained in the next release. In practice nobody renamed a node,
 * and the palette could not be localised at all.
 *
 * ```ts
 * const undo = overrideNodeKind("@particle-academy/api_request", {
 *   label: "Call an API",
 *   description: "Fetch or post JSON to a URL",
 * });
 * ```
 *
 * Applies at `getNodeKind()` and `listNodeKinds()`, so one call reaches the
 * palette, the node cards on the canvas, `FlowViewer`, and anything else that
 * reads the registry. Returns an unsubscribe, matching `registerNodeKind`.
 *
 * Patching an unregistered id is allowed and takes effect if that kind is
 * registered later — order of module side effects is not something a consumer
 * should have to reason about.
 */
export function overrideNodeKind(name: string, patch: NodeKindPresentation): () => void {
  const canonical = resolveKindId(name) ?? name;
  const previous = overrides.get(canonical);

  overrides.set(canonical, { ...previous, ...patch });
  notify();

  return () => {
    if (previous) {
      overrides.set(canonical, previous);
    } else {
      overrides.delete(canonical);
    }
    notify();
  };
}

/** Remove every presentation override. Mostly for tests. */
export function clearNodeKindOverrides(): void {
  if (overrides.size === 0) return;
  overrides.clear();
  notify();
}

function withOverride(kind: NodeKindDefinition | undefined): NodeKindDefinition | null {
  if (!kind) return null;

  // base -> SERVER schema -> LOCAL presentation override.
  //
  // The local override wins, and the order is pinned by a test because it is
  // invisible until the two disagree: `overrideNodeKind` is the app author's
  // explicit choice about naming, which is more specific than a server default.
  const overlay = schemaOverlays.get(kind.name);
  const patch = overrides.get(kind.name);
  if (!overlay && !patch) return kind;

  const withSchema = overlay
    ? ({
        ...kind,
        ...(overlay.configSchema !== undefined ? { configSchema: overlay.configSchema } : {}),
        ...(overlay.label !== undefined ? { label: overlay.label } : {}),
        ...(overlay.description !== undefined ? { description: overlay.description } : {}),
        ...(overlay.category !== undefined ? { category: overlay.category } : {}),
      } as NodeKindDefinition)
    : kind;

  return patch ? ({ ...withSchema, ...patch } as NodeKindDefinition) : withSchema;
}

/** Get a single kind by canonical id or alias, or null. */
export function getNodeKind(name: string): NodeKindDefinition | null {
  const canonical = resolveKindId(name);
  return canonical ? withOverride(kinds.get(canonical) as NodeKindDefinition) : null;
}

/** Every id a kind answers to — canonical first. Used to key node-type maps. */
export function kindIds(kind: NodeKindDefinition): string[] {
  return [kind.name, ...(kind.aliases ?? [])];
}

/** List every registered kind, optionally filtered by category. */
export function listNodeKinds(category?: string): NodeKindDefinition[] {
  ensureBuiltinKinds();
  const all = Array.from(kinds.values()).map((k) =>
    withOverride(k as NodeKindDefinition),
  ) as NodeKindDefinition[];
  // Filter AFTER applying overrides, so an override that moves a node to a
  // different category actually moves it in the palette rather than leaving it
  // filed under the old one with a new name.
  return category ? all.filter((k) => k.category === category) : all;
}

/** Subscribe to registry changes. Returns an unsubscribe function. */
export function onNodeKindsChanged(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function notify(): void {
  for (const l of listeners) l();
}

/** Fill in defaults from a kind's configSchema for newly-created nodes. */
export function defaultConfigFor(kind: NodeKindDefinition): Record<string, unknown> {
  const fromKind = kind.defaultConfig ? { ...(kind.defaultConfig as Record<string, unknown>) } : {};
  for (const field of kind.configSchema ?? []) {
    if (fromKind[field.key] !== undefined) continue;
    if ("default" in field && (field as any).default !== undefined) {
      fromKind[field.key] = (field as any).default;
    }
  }
  return fromKind;
}

/**
 * Validate a config object against a kind's schema. Returns an array of
 * issues (empty = valid). Validation is intentionally light — type
 * coercion + required-field checks. Hosts can layer Zod / Ajv on top.
 */
export function validateConfig(
  kind: NodeKindDefinition,
  config: Record<string, unknown>,
): Array<{ key: string; message: string }> {
  const issues: Array<{ key: string; message: string }> = [];
  for (const field of kind.configSchema ?? []) {
    const value = config[field.key];
    if (field.required && (value === undefined || value === null || value === "")) {
      issues.push({ key: field.key, message: `${field.label} is required` });
      continue;
    }
    if (value === undefined || value === null) continue;
    const issue = validateField(field, value);
    if (issue) issues.push({ key: field.key, message: issue });
  }
  return issues;
}

function validateField(field: ConfigField, value: unknown): string | null {
  switch (field.type) {
    case "text":
    case "textarea":
    case "expression":
    case "credential":
      return typeof value === "string" ? null : `${field.label} must be a string`;
    case "number": {
      if (typeof value !== "number" || !Number.isFinite(value)) return `${field.label} must be a number`;
      if (field.min !== undefined && value < field.min) return `${field.label} must be >= ${field.min}`;
      if (field.max !== undefined && value > field.max) return `${field.label} must be <= ${field.max}`;
      return null;
    }
    case "switch":
      return typeof value === "boolean" ? null : `${field.label} must be a boolean`;
    case "select": {
      const allowed = field.options.map((o) => o.value);
      return allowed.includes(String(value)) ? null : `${field.label} must be one of ${allowed.join(", ")}`;
    }
    case "json":
      return null; // permissive — just JSON-shaped
    case "repeater": {
      if (!Array.isArray(value)) return `${field.label} must be a list`;
      if (field.minItems !== undefined && value.length < field.minItems) {
        return `${field.label} needs at least ${field.minItems}`;
      }
      if (field.maxItems !== undefined && value.length > field.maxItems) {
        return `${field.label} allows at most ${field.maxItems}`;
      }
      // Surface the first offending row so the author knows WHICH one.
      for (let i = 0; i < value.length; i++) {
        const row = value[i];
        if (!row || typeof row !== "object" || Array.isArray(row)) {
          return `${field.label} item ${i + 1} must be an object`;
        }
        for (const sub of field.fields) {
          const cell = (row as Record<string, unknown>)[sub.key];
          if (sub.required && (cell === undefined || cell === null || cell === "")) {
            return `${field.label} item ${i + 1}: ${sub.label} is required`;
          }
          if (cell === undefined || cell === null) continue;
          const issue = validateField(sub, cell);
          if (issue) return `${field.label} item ${i + 1}: ${issue}`;
        }
      }
      return null;
    }
    case "keyvalue": {
      if (typeof value !== "object" || value === null || Array.isArray(value)) {
        return `${field.label} must be a key/value map`;
      }
      const allowed = field.valueOptions?.map((o) => o.value);
      for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
        if (typeof v !== "string") return `${field.label}: "${k}" must be a string`;
        if (allowed && !allowed.includes(v)) {
          return `${field.label}: "${k}" must be one of ${allowed.join(", ")}`;
        }
      }
      return null;
    }
    case "document":
      return null; // opaque to fancy-flow — the host's editor owns its shape
    default:
      return null;
  }
}

/** Default accents per category. */
export function categoryAccent(category: string): string {
  switch (category) {
    case "trigger": return "#10b981";
    case "logic":   return "#f59e0b";
    case "data":    return "#0ea5e9";
    case "ai":      return "#8b5cf6";
    case "io":      return "#3b82f6";
    case "human":   return "#ec4899";
    case "output":  return "#a855f7";
    case "layout":  return "#64748b";
    case "annotation": return "#eab308";
    default:        return "#71717a";
  }
}

import type { FlowEdge, FlowGraph, FlowNode, PortDescriptor, WorkflowInput } from "../types";
import { checkGraphConnectivity } from "../analysis/graph-connectivity";
import { defaultConfigFor, getNodeKind, validateConfig } from "../registry/registry";
import { resolveNodePorts } from "../registry/ports";

/** Schema version. Bump on breaking shape changes; add migrations as needed. */
export const WORKFLOW_SCHEMA_VERSION = 1 as const;
export const WORKFLOW_SCHEMA_URL = "https://particle.academy/schemas/workflow/v1.json";

export type WorkflowSchema = {
  $schema: typeof WORKFLOW_SCHEMA_URL;
  version: typeof WORKFLOW_SCHEMA_VERSION;
  metadata?: WorkflowMetadata;
  /**
   * What this workflow accepts at run start, passed BY NAME.
   *
   * Lives beside `graph` rather than inside it because it describes the
   * workflow's CONTRACT, not its topology: a caller reads this to know what to
   * pass, and reading it should not mean walking nodes looking for a trigger.
   *
   * Omitted entirely when a workflow takes none, so every existing saved
   * document is unchanged byte for byte.
   */
  inputs?: WorkflowInput[];
  graph: {
    nodes: WorkflowSchemaNode[];
    edges: WorkflowSchemaEdge[];
  };
  view?: {
    viewport?: { x: number; y: number; zoom: number };
  };
};

export type WorkflowMetadata = {
  id?: string;
  name?: string;
  description?: string;
  createdAt?: number;
  updatedAt?: number;
  author?: string;
  tags?: string[];
};

export type WorkflowSchemaNode = {
  id: string;
  /** Registry kind name (e.g. "memory_store"). */
  kind: string;
  position: { x: number; y: number };
  label?: string;
  description?: string;
  /**
   * Announced to a person just before / just after this node runs. Omitted
   * entirely when unset, so a graph of ordinary plumbing nodes does not carry
   * a pair of empty keys per node and every diff of a saved graph stays
   * readable.
   */
  startingMsg?: string;
  stoppingMsg?: string;
  config?: Record<string, unknown>;
  /**
   * Resolved ports, written on export.
   *
   * A kind may derive its ports from config (`switch_case` cases,
   * `llm_branch` routes), and that derivation is a JavaScript function — a
   * runtime in another language cannot execute it. Without the resolved ports
   * in the document, the PHP twin sees no declared outputs and falls back to a
   * single `out`, so every branch edge in an exported flow silently stops
   * firing. Serializing them keeps the schema self-describing and preserves
   * the cross-runtime guarantee: same JSON in, same routing out.
   *
   * Optional and additive — a hand-written schema may omit them, and each
   * runtime then falls back to its own kind registry.
   */
  inputs?: PortDescriptor[];
  outputs?: PortDescriptor[];
  /**
   * Node grouping and visual layout — additive + optional. `parentId`/`extent`
   * say which container a node sits in (swimlanes); `width`/`height` carry an
   * explicit (resized) size; `style` carries inline presentation.
   *
   * **`parentId` is NOT decoration, and a runtime that drops it is wrong.** It
   * decides which terminal a node talks to — a terminal lane owns one session
   * and membership is this field, deliberately, so there is no second copy of
   * the grouping in each node's config to drift from what the canvas shows.
   *
   * This comment used to say these fields exist "purely for the canvas", so a
   * runtime that only walks edges and ports could ignore all of them. The
   * Python twin read that literally and carried none of them: a graph loaded
   * there and saved back lost every grouping a person had drawn, silently. The
   * sentence was true when it was written and became false without being
   * revisited, which is the more common way a comment does harm.
   *
   * An older reader that does not know these fields still drops them — that is
   * forward-compatibility, not permission.
   */
  parentId?: string;
  extent?: "parent" | [[number, number], [number, number]];
  width?: number;
  height?: number;
  style?: Record<string, unknown>;
};

export type WorkflowSchemaEdge = {
  id: string;
  source: string;
  target: string;
  sourceHandle?: string;
  targetHandle?: string;
  label?: string;
};

export type ImportIssue = {
  level: "error" | "warning";
  nodeId?: string;
  edgeId?: string;
  message: string;
};

export type ImportResult = {
  graph: FlowGraph;
  issues: ImportIssue[];
  /** True when the import produced a usable graph (errors may have been
   *  rewritten to warnings via `lenient: true`, except an unsupported schema
   *  version, which is always an error). */
  ok: boolean;
};

/** Snapshot the in-memory graph as a portable WorkflowSchema. */
export function exportWorkflow(
  graph: FlowGraph,
  metadata?: WorkflowMetadata,
  view?: WorkflowSchema["view"],
): WorkflowSchema {
  return {
    $schema: WORKFLOW_SCHEMA_URL,
    version: WORKFLOW_SCHEMA_VERSION,
    metadata: metadata ? { ...metadata, updatedAt: Date.now() } : undefined,
    // Round-trips, or a saved workflow silently forgets its own contract and
    // every caller's props become "unknown input" on the next load.
    ...(graph.inputs && graph.inputs.length > 0 ? { inputs: graph.inputs } : {}),
    graph: {
      nodes: graph.nodes.map(toSchemaNode),
      edges: graph.edges.map(toSchemaEdge),
    },
    view,
  };
}

function toSchemaNode(n: FlowNode): WorkflowSchemaNode {
  const data: any = n.data ?? {};
  const kindName = data.kind ?? n.type ?? "custom";
  // Resolve through the same helper the canvas and runtime use, so a
  // config-driven kind writes its ACTUAL ports into the document instead of
  // leaving another language's runtime to guess at them.
  const ports = resolveNodePorts(n, getNodeKind(kindName) ?? undefined);
  const node = n as any;
  return {
    id: n.id,
    kind: kindName,
    position: { x: n.position.x, y: n.position.y },
    label: data.label,
    description: data.description,
    ...(typeof data.startingMsg === "string" && data.startingMsg !== "" ? { startingMsg: data.startingMsg } : {}),
    ...(typeof data.stoppingMsg === "string" && data.stoppingMsg !== "" ? { stoppingMsg: data.stoppingMsg } : {}),
    config: data.config,
    inputs: ports.inputs,
    outputs: ports.outputs,
    // Visual layout — only when explicitly set (never persist auto-`measured`
    // dimensions, which are derived, not authored).
    ...(node.parentId ? { parentId: node.parentId } : {}),
    ...(node.extent ? { extent: node.extent } : {}),
    ...(typeof node.width === "number" ? { width: node.width } : {}),
    ...(typeof node.height === "number" ? { height: node.height } : {}),
    ...(node.style ? { style: node.style } : {}),
  };
}

function toSchemaEdge(e: FlowEdge): WorkflowSchemaEdge {
  return {
    id: e.id,
    source: e.source,
    target: e.target,
    sourceHandle: e.sourceHandle ?? undefined,
    targetHandle: e.targetHandle ?? undefined,
    label: typeof e.label === "string" ? e.label : undefined,
  };
}

export type ImportOptions = {
  /** When true, unknown kinds become warnings + a "custom" placeholder
   *  instead of errors. Default false. It never softens the schema version:
   *  a document that is not `version: 1` (after migration) is refused either
   *  way, because no runtime can honour a format it does not know. */
  lenient?: boolean;
};

/** A migration step: takes a version-N document to version N+1. */
export type MigrationStep = (schema: Record<string, unknown>) => Record<string, unknown>;

/**
 * Every migration step, keyed by the version it upgrades FROM.
 *
 * Empty today because v1 is current — when a BREAKING bump lands, add the step
 * here and every stored document upgrades on read, in this runtime and its
 * PHP and Python twins.
 */
export const MIGRATIONS: Record<number, MigrationStep> = {};

/**
 * Migrate a raw schema object up to the current version, as far as it can go.
 *
 * Additive changes need no migration — an older document simply lacks the newer
 * optional fields. This is the seam for a future BREAKING bump, and
 * `importWorkflow` runs it before validating the version.
 *
 * ## The three rules, each with a reason
 *
 *  - **A PAST version migrates forward**, step by step, to the current one.
 *  - **A FUTURE version is left ALONE.** We cannot know what a later schema
 *    means, and migrating downward would be guessing. Untouched hands it to the
 *    version check, which reports it honestly.
 *  - **A GAP in the table is left alone too.** A missing step is not a licence
 *    to guess.
 *
 * ## Why `steps` is a parameter
 *
 * With only v1 in existence there is no old document to migrate, so a seam
 * tested against the built-in (empty) table is a check that CANNOT fail — it
 * would pass identically against a function that returned its input untouched,
 * which is what this was until the twins needed the same seam.
 *
 * The PHP and Python runtimes carry the identical shape. That mattered more
 * than it sounds: they had no migration at all and errored on any version
 * mismatch, so a v2 bump would have made every stored Op unreadable on exactly
 * the runtimes where durable runs resume.
 */
export function migrateSchema(
  schema: unknown,
  steps: Record<number, MigrationStep> = MIGRATIONS,
): unknown {
  if (!schema || typeof schema !== "object") return schema;

  const doc = schema as Record<string, unknown>;
  let version = doc.version;

  if (typeof version !== "number" || !Number.isInteger(version) || version >= WORKFLOW_SCHEMA_VERSION) {
    return schema;
  }

  let out = doc;
  while (version < WORKFLOW_SCHEMA_VERSION) {
    const step = steps[version];
    if (!step) return out;

    out = step(out);
    version += 1;
    out.version = version;
  }

  return out;
}

/**
 * Hydrate a schema into runtime FlowGraph + validate kinds/configs against
 * the registry. Reports issues for unknown kinds, missing required config,
 * and dangling edges.
 */
export function importWorkflow(schema: unknown, options: ImportOptions = {}): ImportResult {
  const issues: ImportIssue[] = [];
  const lenient = options.lenient === true;
  schema = migrateSchema(schema);

  if (!schema || typeof schema !== "object") {
    return { ok: false, graph: { nodes: [], edges: [] }, issues: [{ level: "error", message: "Schema is not an object." }] };
  }
  const s = schema as Partial<WorkflowSchema>;
  // NEVER softened by `lenient`. That flag is about unknown VOCABULARY (a kind
  // this host has not registered); a version is the format itself, and a
  // runtime cannot honour a format it does not know. It used to become a
  // warning, and fancy-flow-php imports leniently on every run(), so one
  // versionless document ran in Laravel and was refused by a default (strict)
  // import here. Past versions were migrated above, so anything still unequal
  // is refused.
  if (s.version !== WORKFLOW_SCHEMA_VERSION) {
    issues.push({
      level: "error",
      message: `Unsupported workflow schema version: ${s.version} (expected ${WORKFLOW_SCHEMA_VERSION})`,
    });
    return { ok: false, graph: { nodes: [], edges: [] }, issues };
  }

  const rawNodes = s.graph?.nodes ?? [];
  const rawEdges = s.graph?.edges ?? [];

  const nodes: FlowNode[] = rawNodes.map((n) => {
    const kind = getNodeKind(n.kind);
    if (!kind) {
      issues.push({
        level: lenient ? "warning" : "error",
        nodeId: n.id,
        message: `Unknown kind "${n.kind}" — register it before importing.`,
      });
    }
    const config = n.config ?? (kind ? defaultConfigFor(kind) : {});
    if (kind) {
      for (const iss of validateConfig(kind, config)) {
        issues.push({ level: "warning", nodeId: n.id, message: `${iss.key}: ${iss.message}` });
      }
    }
    // Canonicalise on the way in: a document may carry a pre-namespace id, and
    // rewriting it here means the graph converges on the canonical id the next
    // time it is saved, rather than carrying the ambiguous name forever.
    const kindId = kind?.name ?? n.kind;
    return {
      id: n.id,
      type: kindId,
      position: { x: n.position?.x ?? 0, y: n.position?.y ?? 0 },
      // Rehydrate visual layout onto the node's top level (where xyflow reads it).
      ...(n.parentId ? { parentId: n.parentId } : {}),
      ...(n.extent ? { extent: n.extent } : {}),
      ...(typeof n.width === "number" ? { width: n.width } : {}),
      ...(typeof n.height === "number" ? { height: n.height } : {}),
      ...(n.style ? { style: n.style } : {}),
      data: {
        kind: kindId,
        label: n.label ?? kind?.label ?? n.kind,
        description: n.description,
        ...(n.startingMsg ? { startingMsg: n.startingMsg } : {}),
        ...(n.stoppingMsg ? { stoppingMsg: n.stoppingMsg } : {}),
        config,
        // Carry serialized ports back onto the node so a round-trip is stable
        // and an unknown kind still routes the way the document described.
        ...(n.inputs ? { inputs: n.inputs } : {}),
        ...(n.outputs ? { outputs: n.outputs } : {}),
      } as any,
    };
  });

  const nodeIds = new Set(nodes.map((n) => n.id));
  const edges: FlowEdge[] = rawEdges
    .map((e) => {
      if (!nodeIds.has(e.source)) {
        issues.push({ level: "warning", edgeId: e.id, message: `Edge source "${e.source}" not found.` });
        return null;
      }
      if (!nodeIds.has(e.target)) {
        issues.push({ level: "warning", edgeId: e.id, message: `Edge target "${e.target}" not found.` });
        return null;
      }
      return {
        id: e.id,
        source: e.source,
        target: e.target,
        sourceHandle: e.sourceHandle,
        targetHandle: e.targetHandle,
        label: e.label,
      } as FlowEdge;
    })
    .filter((e): e is FlowEdge => e !== null);

  // WIRING, not merely dataflow: a node no edge reaches and that reaches no
  // edge, and an edge reading from a node that publishes nothing.
  //
  // Deliberately AFTER the edge loop, so it sees the same edges the engine will
  // -- a dangling edge is dropped with a warning above, and running this first
  // would let a dropped edge count as a connection.
  //
  // Deliberately NOT gated on `lenient`. That flag is about unknown VOCABULARY
  // (a kind this host has not registered), never about wiring.
  issues.push(...checkGraphConnectivity({ nodes, edges }));

  const ok = issues.every((i) => i.level !== "error");
  // The declaration comes back with the graph. Dropping it on import would be
  // the worse half of losing it on export: the document still says what it
  // accepts, the loaded graph does not, and every prop a caller passes becomes
  // "unknown input" — an error pointing at the caller for a bug in the loader.
  const declaredInputs = Array.isArray(s.inputs)
    ? (s.inputs as WorkflowInput[]).filter(
        (input): input is WorkflowInput =>
          input !== null && typeof input === "object" && typeof (input as WorkflowInput).name === "string",
      )
    : undefined;

  return {
    ok,
    graph: {
      nodes,
      edges,
      ...(declaredInputs && declaredInputs.length > 0 ? { inputs: declaredInputs } : {}),
    },
    issues,
  };
}

/** Convenience: serialize a schema as a downloadable JSON Blob. */
export function workflowToBlob(schema: WorkflowSchema): Blob {
  return new Blob([JSON.stringify(schema, null, 2)], { type: "application/json" });
}

import type { ComponentType, ReactNode } from "react";
import type { OutputShape } from "../expressions/variables";
import type { NodeProps } from "@xyflow/react";
import type { FlowNode, NodeExecutor, PortDescriptor } from "../types";
import type { PauseAwaiting } from "./pause";
import type { SideEffects } from "../marketplace/manifest";

/** Categories used by the palette for grouping. */
export type NodeCategory =
  | "trigger"
  | "logic"
  | "data"
  | "ai"
  | "io"
  | "human"
  | "output"
  | "layout"
  | "annotation"
  | "custom";

/**
 * Tagged-union of config-field shapes the auto-form knows how to render.
 * Each variant has a `key` (the config object property it writes to) and
 * a `label`. Hosts can render fully custom panels via the kind's
 * `renderPanel` instead.
 */
export type ConfigField =
  | TextConfigField
  | TextareaConfigField
  | NumberConfigField
  | SelectConfigField
  | SwitchConfigField
  | JsonConfigField
  | ExpressionConfigField
  | CredentialConfigField
  | RepeaterConfigField
  | KeyValueConfigField
  | DocumentConfigField;

/**
 * Field types that may appear inside a `repeater` row. Excludes `repeater`
 * itself — a row of rows has no sane form rendering, and the nesting would
 * make the config shape hard for an agent to emit.
 */
export type RepeaterRowField = Exclude<ConfigField, RepeaterConfigField>;

type ConfigFieldBase = {
  key: string;
  label: string;
  description?: string;
  required?: boolean;
};

export type TextConfigField = ConfigFieldBase & {
  type: "text";
  placeholder?: string;
  default?: string;
  /**
   * Optional fixed choices. When present the field renders as a select
   * instead of a free-text input — the same field declaration serves both a
   * free-form value and a constrained one, so a kind can gain choices later
   * without changing its `type` or migrating stored config.
   *
   * Bare strings are shorthand for `{ value, label: value }`.
   *
   * Unlike `type: "select"`, a stored value outside the list is preserved and
   * shown rather than rejected — choices can change after configs are saved,
   * and silently dropping an author's value is worse than showing a stale one.
   */
  choices?: Array<string | { value: string; label?: string }>;
};
export type TextareaConfigField = ConfigFieldBase & {
  type: "textarea";
  placeholder?: string;
  rows?: number;
  default?: string;
};
export type NumberConfigField = ConfigFieldBase & {
  type: "number";
  min?: number;
  max?: number;
  step?: number;
  default?: number;
};
export type SelectConfigField = ConfigFieldBase & {
  type: "select";
  options: Array<{ value: string; label: string }>;
  default?: string;
};
export type SwitchConfigField = ConfigFieldBase & {
  type: "switch";
  default?: boolean;
};
export type JsonConfigField = ConfigFieldBase & {
  type: "json";
  language?: "json" | "yaml" | "javascript";
  rows?: number;
  default?: unknown;
  /**
   * Declared types per path, as a JSON **string** — `{"retries":"integer"}`.
   *
   * Consumed by richer editors (see `/fields/react-fancy`) to pick a control
   * per value and report contradictions; ignored by the built-in textarea,
   * which has nowhere to put it. Optional, because plenty of JSON config —
   * an arbitrary request body, a JSON Schema — has no fixed shape to declare.
   *
   * A string rather than an object so it survives an MCP round-trip: a kind
   * definition travels as JSON to agents, and a nested object here would be
   * indistinguishable from the value it describes.
   */
  keyMap?: string;
};
export type ExpressionConfigField = ConfigFieldBase & {
  type: "expression";
  /** A short example string shown as placeholder, e.g. "{{ $json.name }}". */
  example?: string;
  default?: string;
};
export type CredentialConfigField = ConfigFieldBase & {
  type: "credential";
  /** Logical credential type. The host implements lookup / picker. */
  credentialType: string;
};

/**
 * Repeater — an editable list of objects, each row authored with its own
 * sub-schema of ConfigFields. This is what a node kind should reach for
 * instead of `type: "json"` whenever its config is list-shaped (form field
 * lists, router routes, tool bindings). Keeping it declarative is what lets
 * `NodeConfigPanel` stay the single authoring surface for humans AND keeps
 * the shape introspectable for agents.
 *
 * Value shape: `Array<Record<string, unknown>>`.
 */
export type RepeaterConfigField = ConfigFieldBase & {
  type: "repeater";
  /** Schema applied to every row. */
  fields: RepeaterRowField[];
  /**
   * Row field whose value titles the row in the editor. Falls back to the
   * first field's value, then to "Item N".
   */
  titleKey?: string;
  /** Label for the add button. Default: "Add". */
  addLabel?: string;
  /** Bounds enforced by validation + the add/remove controls. */
  minItems?: number;
  maxItems?: number;
  default?: Array<Record<string, unknown>>;
};

/**
 * Key/value map — an editable `Record<string, string>`. Use for filter maps,
 * input bindings, header maps, and case→port tables.
 *
 * Value shape: `Record<string, string>`.
 */
export type KeyValueConfigField = ConfigFieldBase & {
  type: "keyvalue";
  keyLabel?: string;
  valueLabel?: string;
  keyPlaceholder?: string;
  valuePlaceholder?: string;
  /** Constrain values to a fixed set (e.g. the node's own port ids). */
  valueOptions?: Array<{ value: string; label: string }>;
  addLabel?: string;
  default?: Record<string, string>;
};

/**
 * Document — an opaque rich/structured document stored in node config and
 * edited by a HOST-SUPPLIED editor, wired through
 * `NodeConfigPanel`'s `renderDocumentField`.
 *
 * fancy-flow deliberately does not know what a document *is* — same
 * arrangement as `credential`. That keeps rich human-input surfaces (authored
 * pages, required-reading steps, multi-section forms) possible without the
 * editor taking a dependency on any particular document model or CMS.
 */
export type DocumentConfigField = ConfigFieldBase & {
  type: "document";
  /**
   * Logical document format, passed through to the host renderer so one host
   * can serve several (e.g. "stages", "markdown", "portable-text").
   */
  documentType?: string;
  default?: unknown;
};

/**
 * Port declaration — either a fixed list, or a function of the node's config
 * for kinds whose branches ARE their config (switch cases, router routes).
 *
 * Declaring the function form keeps the canvas ports, the config, and the
 * ports the runtime activates in lockstep automatically; a static list forces
 * every consumer to hand-sync `data.outputs` from config in a custom renderer,
 * and forgetting to breaks routing silently at execution time.
 */
export type PortSpec<TConfig = unknown> =
  | PortDescriptor[]
  | ((config: TConfig) => PortDescriptor[]);

/**
 * Context passed to a kind's optional `renderBody`. Hosts can read the
 * resolved config + node id to render whatever fancy-* component they
 * want inside the node card.
 */
export type RenderBodyContext<TConfig = unknown> = {
  nodeId: string;
  config: TConfig;
  selected: boolean;
};

/**
 * How a kind's output relates to its input. See `NodeKindDefinition.emits`.
 *
 * Every value is TOP-LEVEL by construction — a relation cannot describe a value
 * nested under a key, which is why `wait` declares a field list instead.
 */
export type EmitsRelation =
  | "input"
  | "inputs-merged"
  | "input-map-merged"
  | `expression:${string}`;

/**
 * NodeKindDefinition — declares an authorable node type. Register one
 * via `registerNodeKind()`. Hosts (and the agent bridge) introspect the
 * registry to know what's authorable.
 */
export type NodeKindDefinition<TConfig = Record<string, unknown>, TIn = any, TOut = any> = {
  /**
   * Canonical identifier — the xyflow node `type` and the value persisted as
   * `kind` in every saved document.
   *
   * Namespace it when publishing (`@fancy/llm_branch`,
   * `@acme/salesforce_upsert`). A bare name that two packages could both claim
   * makes stored graphs ambiguous, and that is unfixable afterwards because the
   * ambiguous string is already written into the document.
   */
  name: string;
  /**
   * Other ids this kind answers to — previous bare names, or a short alias.
   * Resolution accepts them, but export always writes `name`, so documents
   * converge on the canonical id as they are re-saved.
   */
  aliases?: string[];
  /** Palette grouping. */
  category: NodeCategory;
  /** Display label. */
  label: string;
  /** One-line summary surfaced in the palette + agent bridge. */
  description?: string;
  /**
   * Icon rendered in the node header and the palette row. A glyph string is
   * fine; any ReactNode works, so a brand SVG can be dropped in directly.
   */
  icon?: ReactNode;
  /** Hex / CSS color for the header bar. Falls back to a category default. */
  accent?: string;

  /** Declarative form schema for the config panel. */
  configSchema?: ConfigField[];
  /** Default config values used when a node of this kind is created. */
  defaultConfig?: TConfig;

  /** Input ports. Defaults vary by category. See `PortSpec`. */
  inputs?: PortSpec<TConfig>;
  /** Output ports. Defaults vary by category. See `PortSpec`. */
  outputs?: PortSpec<TConfig>;
  /**
   * What this kind EMITS, described well enough for an author to reference it
   * in a `{{ }}` field. Distinct from `outputs`, which describes wires (port
   * ids), not the data on them — nothing in the registry described the latter,
   * so a variable picker had nothing to read.
   *
   * A function when the honest answer depends on config: a `user_input` step
   * emits the field keys its author defined, which no static list can know.
   */
  outputShape?: OutputShape<TConfig>;

  /**
   * How this kind's output RELATES to its input, when the relation is what is
   * knowable rather than a field list.
   *
   * `outputShape` answers *which fields*; this answers *where they come from*.
   * Separate because they are separate questions, and one field carrying
   * sometimes-a-list-sometimes-a-keyword is one a reader handles only in the
   * form it met first.
   *
   * - `"input"` — emits its input unchanged
   * - `"inputs-merged"` — the union of every input PAYLOAD's fields
   * - `"input-map-merged"` — the raw input MAP merged in, whose shape
   *   DEPENDS ON POSITION: `collectInputs` seeds an entry node flat and
   *   keys every other node by handle, so a `schedule_trigger` with an
   *   inbound edge emits `{ cron, timezone, in: {...} }`. Two names because
   *   they are two operations, not one plus a positional rule.
   * - `` `expression:${string}` `` — the shape the expression in THAT CONFIG KEY
   *   names. The key is part of the value because a consumer hardcoding "the
   *   field called expression" has copied our knowledge one level down, which is
   *   the thing this removes: `transform` reads `expression`, `variable` reads
   *   `value`.
   * - a function of config, for a kind whose relation depends on how it was
   *   configured.
   *
   * **A relation with no destination can only express a TOP-LEVEL merge.**
   * `wait` returns `{ waited, duration, input }` — it NESTS its input under a
   * key. `emits: "input"` there would make a reader accept
   * `{{ in.<any inbound field> }}` at top level, which resolves to nothing at
   * run time. It keeps a static `outputShape` with an opaque `input` field
   * instead. Read the executor and ask *merge or nest* before assigning one;
   * under-claiming is free.
   *
   * An `expression` relation is knowable only when the whole config string is a
   * SINGLE reference. Interpolating several yields a string with no addressable
   * fields, and a reader that expands it anyway over-permits.
   */
  emits?: EmitsRelation | ((config: TConfig) => EmitsRelation | null);

  /** Optional custom body rendered inside the node card. */
  renderBody?: (ctx: RenderBodyContext<TConfig>) => ReactNode;

  /**
   * Optional override for the config panel. Receives the current config and
   * an onChange to update it. Defaults to the auto-generated form.
   */
  renderPanel?: (props: {
    config: TConfig;
    onChange: (next: TConfig) => void;
    nodeId: string;
  }) => ReactNode;

  /**
   * Executor — host-implemented function that runs at flow execution.
   * Optional: built-in agentic kinds ship without one so the host wires
   * the actual work (memory store backend, LLM client, HTTP fetcher, etc.).
   */
  executor?: NodeExecutor<TIn, TOut>;

  /**
   * Declares that this kind halts the run to wait for a person, and what for.
   *
   * Only a declaration — the executor still emits the pause (via
   * `pauseForHuman`). Its value is that it is readable WITHOUT running the
   * graph: a host can be told "this workflow needs a resume path you haven't
   * built" before the first run parks itself forever, and the marketplace can
   * refuse to list a pausing node whose package never says so.
   */
  pausesForHuman?: PauseAwaiting;

  /**
   * Whether a node of this kind is safe to run twice.
   *
   * The same three values a marketplace manifest declares (see `SideEffects`),
   * lifted onto the KIND so it is readable at run time. A manifest is install-
   * time data; a durable runner needs this while deciding whether to retry, and
   * cannot go and read a manifest to find out.
   *
   * `fancy-flow-php`'s per-node queue driver keys its retry policy on exactly
   * this: an `unsafe-to-replay` node gets one attempt whatever `tries` says,
   * because a retried `git_pr_open` opens a second pull request. This field is
   * the TypeScript half of that contract — the twins declare the same kind
   * metadata or they are not twins.
   *
   * Declaration only. Nothing here enforces it; a host's runner decides what to
   * do with it, and the TS in-process runner currently does not retry at all.
   */
  sideEffects?: SideEffects;

  /**
   * Make nodes of this kind resizable via drag handles (xyflow NodeResizer).
   * `true` enables it with defaults; pass options to bound it. The resulting
   * width/height are written onto the node and persisted by the schema (0.21+).
   */
  resizable?:
    | boolean
    | { minWidth?: number; minHeight?: number; maxWidth?: number; maxHeight?: number; keepAspectRatio?: boolean };

  /**
   * Contextual per-node toolbar (xyflow NodeToolbar), shown while the node is
   * selected — a discoverable, agent-legible alternative to the right-click
   * menu. Call `useFlowEditor()` inside it to reach the editor api.
   */
  toolbar?: (ctx: { nodeId: string; config: TConfig; selected: boolean }) => ReactNode;

  /**
   * Full custom node renderer. When set, `buildNodeTypes` uses this component
   * for the kind INSTEAD of the default `RegistryNode` card — the escape hatch
   * for nodes that aren't cards (lanes / containers / groups). Receives
   * xyflow's `NodeProps`.
   */
  component?: ComponentType<NodeProps<FlowNode>>;

  /**
   * Opt this kind into reactive data flow: during a run, a node's computed
   * output is written back into its `data.output`, so its card reflects the
   * value live ("computing flows"). Default off — non-reactive kinds are
   * untouched, so this is purely additive.
   */
  reactive?: boolean;
};

import type { FlowNode, PortDescriptor } from "../types";
import type { NodeKindDefinition, PortSpec } from "./types";

/**
 * Port resolution — the single place a node's ports are derived, shared by
 * the canvas renderer and the headless runtime.
 *
 * This module is deliberately React-free: `runFlow` (the `/engine` entry)
 * imports it, and the engine bundle must stay free of React.
 *
 * ## Why this is centralized
 *
 * Ports used to be read in two places that disagreed — the canvas consulted
 * `data.outputs ?? kind.outputs`, while the runtime consulted `data.outputs`
 * ONLY and fell back to a single `out` port. A kind that declared branch ports
 * therefore drew correctly and then routed as if it had one output, unless the
 * host remembered to mirror the ports onto every node's `data`. Both callers
 * now go through `resolveNodePorts`, so declared ports and executed ports
 * cannot drift apart.
 */

/**
 * Resolve a `PortSpec` against a config object.
 *
 * A config-driven spec is author-supplied and runs on every render, so a throw
 * is contained: it degrades to "undeclared" (letting the caller fall back)
 * rather than taking out the canvas or aborting a run mid-flight.
 */
export function resolvePortSpec<TConfig>(
  spec: PortSpec<TConfig> | undefined,
  config: TConfig,
): PortDescriptor[] | undefined {
  if (spec === undefined) return undefined;
  if (typeof spec !== "function") return spec;
  try {
    const resolved = (spec as (c: TConfig) => PortDescriptor[])(config);
    return Array.isArray(resolved) ? resolved : undefined;
  } catch {
    return undefined;
  }
}

/** Read the config bag off a node, tolerating the FlowNodeData union. */
export function nodeConfig(node: Pick<FlowNode, "data">): Record<string, unknown> {
  return ((node.data as any)?.config ?? {}) as Record<string, unknown>;
}

/**
 * Resolve a node's effective ports.
 *
 * Precedence: explicit `data.inputs`/`data.outputs` (a per-node host override)
 * beats the kind's declaration. `undefined` means "nothing declared" — the
 * caller applies its own category default.
 */
export function resolveNodePorts(
  node: Pick<FlowNode, "data">,
  kind?: Pick<NodeKindDefinition<any>, "inputs" | "outputs">,
): { inputs?: PortDescriptor[]; outputs?: PortDescriptor[] } {
  const config = nodeConfig(node);
  const data = node.data as any;
  return {
    inputs: data?.inputs ?? resolvePortSpec(kind?.inputs, config),
    outputs: data?.outputs ?? resolvePortSpec(kind?.outputs, config),
  };
}

import type { FlowGraph } from "../types";

/**
 * Host capabilities — the services core nodes need but must never depend on.
 *
 * A node that imports a provider SDK forces every consumer to install it: a
 * workflow app that never calls a model should not inherit an LLM dependency.
 * So core declares the CONTRACT and the host supplies the implementation, the
 * same arrangement `renderDocumentField` already uses for documents.
 *
 * That keeps opinionated nodes in core without their opinions: `llm_branch`
 * ships the routing semantics, port derivation and config UI, while whichever
 * client the host registers — Prism, an OpenAI SDK, a local model, a fake in a
 * test — decides how the question actually gets asked.
 *
 * Registration is deliberately explicit and typed per capability rather than a
 * stringly-keyed bag, so a missing one is a clear error at the seam instead of
 * an undefined somewhere downstream.
 */

// ── LLM ─────────────────────────────────────────────────────────────────────

export type LlmRoute = { port: string; description?: string };

export type LlmRouteRequest = {
  /** Optional framing for the decision. */
  system?: string;
  /** What the model is deciding about. */
  prompt: string;
  /** The ports it must choose between. */
  routes: LlmRoute[];
  provider?: string;
  model?: string;
  /** Host-resolved credential reference, never a raw key. */
  credential?: string;
};

export type LlmRouteChoice = {
  /** Must be one of the requested route ports. */
  port: string;
  /** Why — carried down the chosen port so a run is explainable afterwards. */
  reason?: string;
};

/**
 * The only thing core asks of an LLM: given routes, pick one.
 *
 * Deliberately not a general chat interface. A narrow contract is one a host
 * can satisfy in a few lines over any SDK, and it keeps the choice
 * machine-checkable — an implementation should constrain the model to the
 * declared ports (structured output / enum) rather than parsing prose.
 */
export type LlmClient = {
  chooseRoute: (request: LlmRouteRequest) => Promise<LlmRouteChoice> | LlmRouteChoice;
};

let llmClient: LlmClient | null = null;

/** Install the host's LLM client. Returns an unregister function. */
export function registerLlmClient(client: LlmClient): () => void {
  llmClient = client;
  return () => {
    if (llmClient === client) llmClient = null;
  };
}

export function getLlmClient(): LlmClient | null {
  return llmClient;
}

// ── Terminal ────────────────────────────────────────────────────────────────

/** What to launch. Omit `command` for the host's default shell. */
export type TerminalSessionSpec = {
  command?: string;
  args?: string[];
  cwd?: string;
  env?: Record<string, string>;
  cols?: number;
  rows?: number;
};

export type TerminalExit = { exitCode: number; signal?: string };

/**
 * One live terminal, owned by the host for as long as the run needs it.
 *
 * Output arrives by SUBSCRIPTION rather than a `read()` the engine calls. A TUI
 * emits continuously and on its own schedule — repainting, streaming a reply,
 * redrawing a spinner — so a polled read either misses bytes between calls or
 * has to buffer them anyway, and every host would invent that buffer
 * differently.
 */
export type TerminalSession = {
  id: string;
  write: (data: string) => void | Promise<void>;
  /** Subscribe to output. Returns an unsubscribe. */
  onData: (listener: (chunk: string) => void) => () => void;
  /**
   * Resolves when the process exits.
   *
   * A promise rather than an `exited` flag the engine polls, so "the agent
   * quit" and "the agent has not answered yet" are distinguishable while
   * waiting. Without it a node awaiting output cannot tell a slow reply from a
   * dead process, and waits out its timeout either way.
   */
  exited: Promise<TerminalExit>;
  close: () => void | Promise<void>;
};

/**
 * The only thing core asks of a terminal: open one.
 *
 * ## Why the contract stops at the PTY
 *
 * There is deliberately no `waitForOutput(pattern)` here, though every terminal
 * node needs one. Matching is derivable from `onData`, so putting it in the
 * contract would mean every host implements it — and two implementations of one
 * agreed rule is precisely how a week of registry defects happened: both sides
 * agreed output matching should work, and would have disagreed on whether a
 * pattern spans chunk boundaries, whether ANSI escapes are stripped first, and
 * what a timeout returns.
 *
 * So core owns the matching and the host owns the process. A host satisfies
 * this in a few lines over `node-pty`; nothing about how a run interprets the
 * bytes is up to it.
 *
 * ## Why this exists at all
 *
 * A terminal cannot live in the engine. `node-pty` is a native addon, so
 * importing it would break every browser build of this package and force the
 * dependency on consumers who never run a terminal node — the same reason the
 * LLM client is a contract rather than an SDK import. The desktop app that CAN
 * spawn a PTY registers one; everyone else never notices the capability exists.
 */
export type TerminalHost = {
  open: (spec: TerminalSessionSpec) => Promise<TerminalSession> | TerminalSession;
};

let terminalHost: TerminalHost | null = null;

/** Install the host's terminal. Returns an unregister function. */
export function registerTerminalHost(host: TerminalHost): () => void {
  terminalHost = host;
  return () => {
    if (terminalHost === host) terminalHost = null;
  };
}

export function getTerminalHost(): TerminalHost | null {
  return terminalHost;
}

// ── Workflow resolution ─────────────────────────────────────────────────────

/**
 * Why a workflow reference could not be resolved.
 *
 * `missing` and `version-mismatch` are deliberately distinct. Collapsing them
 * into a bare null makes "no such workflow" indistinguishable from "that
 * workflow exists, but it is not the one you pinned" — and the second wants an
 * error naming both versions, because it is the interesting failure.
 */
export type WorkflowResolutionFailure = {
  reason: "missing" | "version-mismatch";
  /** The version the host actually holds, when it holds one. */
  available?: number;
  message?: string;
};

export type WorkflowResolution = FlowGraph | WorkflowResolutionFailure | null;

/**
 * Resolve a workflow reference to a runnable graph.
 *
 * `subflow` names another workflow rather than embedding it, so the host owns
 * where workflows live — a database, a file, an API.
 *
 * ## Why `version` is here
 *
 * A workflow another workflow depends on is an INTERFACE, and interfaces need
 * pins. Without a version, a parent goes on calling `invoice-triage`, someone
 * edits that child, and the parent now runs different logic having reported
 * success the whole time — correct-looking, no error, wrong behaviour. The same
 * failure family as the 0.9.0 routing divergence.
 *
 * The parameter lives on the resolver rather than being encoded into the ref
 * string (`invoice-triage@3`) because a stringly-typed protocol is one every
 * host invents differently — the "three vocabularies for one node" problem.
 *
 * Raised by the MOIC Suite consumer, whose `workflow_ref` pins versions and
 * fails loudly on mismatch. Their point: a host COULD NOT implement pinning
 * before this, because the node had no way to ask and the resolver no way to
 * receive.
 *
 * Returning `null` still means "no such workflow". Return a
 * {@link WorkflowResolutionFailure} to distinguish a version mismatch.
 */
export type WorkflowResolver = (
  ref: string,
  version?: number,
) => Promise<WorkflowResolution> | WorkflowResolution;

/** Narrow a resolver's return value to an explicit failure. */
export function isResolutionFailure(value: WorkflowResolution): value is WorkflowResolutionFailure {
  return (
    typeof value === "object" &&
    value !== null &&
    "reason" in value &&
    (value as WorkflowResolutionFailure).reason !== undefined
  );
}

let workflowResolver: WorkflowResolver | null = null;

/** Install the host's workflow resolver. Returns an unregister function. */
export function registerWorkflowResolver(resolver: WorkflowResolver): () => void {
  workflowResolver = resolver;
  return () => {
    if (workflowResolver === resolver) workflowResolver = null;
  };
}

export function getWorkflowResolver(): WorkflowResolver | null {
  return workflowResolver;
}

// ── Introspection ───────────────────────────────────────────────────────────

export type CapabilityId = "llm" | "workflow_resolver" | "document" | "terminal";

/**
 * Which capabilities are currently satisfied.
 *
 * Exists so a host (or the CLI, or an agent over MCP) can answer "what does
 * this graph need that I haven't wired?" BEFORE a run fails halfway through.
 */
export function capabilityStatus(): Record<CapabilityId, boolean> {
  // Imported lazily to avoid dragging the React-dependent rich-input module
  // into the headless engine.
  let documentReady = false;
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
    documentReady = Boolean((globalThis as any).__fancyFlowDocumentAdapter);
  } catch {
    documentReady = false;
  }
  return {
    llm: llmClient !== null,
    workflow_resolver: workflowResolver !== null,
    document: documentReady,
    // Listed here for the reason this function exists at all. A graph with a
    // terminal lane and no host registered fails PART WAY THROUGH — after the
    // nodes before it have already run and possibly written somewhere — and the
    // whole point of asking up front is to learn that before starting. Leaving
    // it out would have made the one check designed to catch this report
    // all-clear for exactly the case it was built for.
    terminal: terminalHost !== null,
  };
}

/**
 * The human-pause contract.
 *
 * A workflow that waits for a person is not an error, but it travels the same
 * channel as one: the executor aborts, the engine records a reason string, and
 * the durable runner decides whether that string meant "failed" or "waiting".
 *
 * That seam existed before this module, as two `str_starts_with` checks in the
 * Laravel run job against constants owned by two BUILTIN executors. It worked,
 * and it was invisible: a third-party human-input node had no way to announce
 * that it pauses, and nothing stopped a refactor from removing the mechanism
 * out from under published packages. Reported by the MOIC Suite consumer, who
 * needed exactly that and had to reach for a private constant to get it.
 *
 * So the encoding is now public, typed, and versioned by prefix rather than
 * implied. The wire format stays a plain string on purpose — it survives the
 * existing abort → `RunResult.error` path unchanged, crosses a queue boundary,
 * and decodes identically in PHP, none of which a thrown class would do.
 *
 * @see decodePause — the one function a durable runner needs.
 */

/**
 * What the run is waiting for.
 *
 * `approval` and `input` are the shapes both runtimes ship. The type stays open
 * because the whole point is that a marketplace node can define its own —
 * a signature step, a payment confirmation, a review queue — and a runner that
 * does not recognise one should report it rather than guess.
 */
export type PauseAwaiting = "approval" | "input" | (string & {});

/** A run halted, waiting for a person. */
export type PauseSignal = {
  /** The node that paused — where a submission gets injected on resume. */
  nodeId: string;
  awaiting: PauseAwaiting;
  /**
   * Kind-supplied context for whoever renders the wait — a form schema, the
   * question being asked, a diff to approve. Must be JSON-serializable: it
   * crosses a queue boundary and, for durable runs, a database column.
   */
  detail?: unknown;
};

/** Marks a reason string as a pause rather than a failure. */
export const PAUSE_PREFIX = "fancy-flow:pause:";

/**
 * Reason prefixes shipped before this contract, kept decodable forever.
 *
 * These are what `DurableApprovalExecutor` and `DurableUserInputExecutor`
 * emitted, and they are written into the `error` column of every run that
 * paused under an older version. Dropping them would strand those runs
 * mid-flight — a resume path that only works for new runs is not a resume path.
 */
export const LEGACY_PAUSE_PREFIXES: ReadonlyArray<readonly [string, PauseAwaiting]> = [
  ["awaiting-approval:", "approval"],
  ["awaiting-input:", "input"],
];

/**
 * Encode a pause as the reason string an executor aborts with.
 *
 * The payload is JSON rather than delimited fields because a node id may
 * contain a colon, and a positional encoding that breaks on user data is the
 * kind of bug that only shows up in someone else's graph.
 */
export function encodePause(signal: PauseSignal): string {
  const { nodeId, awaiting, detail } = signal;
  return PAUSE_PREFIX + JSON.stringify(detail === undefined ? { nodeId, awaiting } : { nodeId, awaiting, detail });
}

/**
 * Decode a run's error reason into a pause, or null if it was a real failure.
 *
 * This is the whole contract from a runner's side: call it on `result.error`,
 * and if it returns non-null, persist the run as waiting on `signal.nodeId`
 * instead of failing it. Accepts the legacy prefixes, so a runner written
 * against this handles runs that paused under an older version.
 */
export function decodePause(reason: string | null | undefined): PauseSignal | null {
  if (typeof reason !== "string") return null;

  if (reason.startsWith(PAUSE_PREFIX)) {
    const body = reason.slice(PAUSE_PREFIX.length);
    try {
      const parsed = JSON.parse(body) as Partial<PauseSignal>;
      // A malformed payload is a corrupt pause, not a failure to report as a
      // crash — but it is also not something to invent a node id for.
      if (typeof parsed?.nodeId !== "string" || typeof parsed?.awaiting !== "string") return null;
      return "detail" in parsed
        ? { nodeId: parsed.nodeId, awaiting: parsed.awaiting, detail: parsed.detail }
        : { nodeId: parsed.nodeId, awaiting: parsed.awaiting };
    } catch {
      return null;
    }
  }

  for (const [prefix, awaiting] of LEGACY_PAUSE_PREFIXES) {
    if (reason.startsWith(prefix)) {
      return { nodeId: reason.slice(prefix.length), awaiting };
    }
  }

  return null;
}

/** True when a run's error reason is actually a pause. */
export function isPause(reason: string | null | undefined): boolean {
  return decodePause(reason) !== null;
}

/**
 * Abort the current node as a pause.
 *
 * Called from inside an executor with its own context. Node authors should
 * reach for this rather than hand-encoding a reason, so the format stays ours
 * to change:
 *
 * ```ts
 * const values = ctx.inputs.values;
 * if (values === undefined) pauseForHuman(ctx, "input", { fields });
 * return values;
 * ```
 *
 * Note the `undefined` check — an empty submission (`{}`) is a real answer and
 * must resume. Truthiness here pauses forever on an empty form.
 */
export function pauseForHuman(
  ctx: { node: { id: string }; abort: (reason?: string) => never },
  awaiting: PauseAwaiting,
  detail?: unknown,
): never {
  return ctx.abort(encodePause({ nodeId: ctx.node.id, awaiting, detail }));
}

import { getWorkflowResolver, isResolutionFailure } from "./capabilities";
import { runFlow } from "../runtime/run-flow";
import { decodePause } from "./pause";
import type { FlowGraph, NodeExecutor, RunEvent } from "../types";

/**
 * `@fancy/subflow` — run another workflow and bring its result home.
 *
 * Core, not marketplace: it introduces no third-party dependency. It runs a
 * child graph through the very same engine, so the only thing it needs from the
 * host is where workflows live (`registerWorkflowResolver`).
 *
 * Three output modes, because both halves are genuinely useful:
 *
 *   - `output` — the child's outputs arrive on `out` when it finishes.
 *   - `stream` — the child's events are forwarded live on `stream` as they
 *     happen, so a parent can show progress instead of a spinner.
 *   - `both`   — stream while running AND deliver the final outputs.
 *
 * Recursion is guarded by depth. A workflow that references itself (directly or
 * through a chain) would otherwise recurse until the stack dies, which surfaces
 * as an opaque crash rather than "you built a loop".
 */

export const DEFAULT_MAX_DEPTH = 8;

export type SubflowMode = "output" | "stream" | "both";

export function subflowMode(config: Record<string, unknown>): SubflowMode {
  const mode = config.mode;
  return mode === "stream" || mode === "both" ? mode : "output";
}

/** Ports follow the mode — `stream` only exists when something streams. */
export function subflowPorts(config: Record<string, unknown>) {
  const mode = subflowMode(config);
  const ports = [{ id: "out", label: "result" }];
  if (mode === "stream" || mode === "both") ports.unshift({ id: "stream", label: "stream" });
  return ports;
}

/**
 * Entry-point inputs for the child run: the node's explicit `inputs` mapping,
 * or — absent or empty — the parent's inputs handed to every entry node (a node
 * with no incoming edge), so the simple case needs no configuration at all.
 *
 * The same rule as the PHP and Python engines. This used to seed
 * `{ __parent: inputs }`: `initialInputs` is keyed by node id and nothing is
 * called `__parent`, so the child ran with no inputs and nothing said so.
 */
export function childInputs(
  config: Record<string, unknown>,
  child: FlowGraph,
  inputs: Record<string, unknown>,
): Record<string, Record<string, unknown>> {
  const mapping = config.inputs;

  if (mapping && typeof mapping === "object" && !Array.isArray(mapping) && Object.keys(mapping).length > 0) {
    return mapping as Record<string, Record<string, unknown>>;
  }

  const hasIncoming = new Set(child.edges.map((edge) => edge.target));
  const seeded: Record<string, Record<string, unknown>> = {};

  for (const node of child.nodes) {
    if (!hasIncoming.has(node.id)) seeded[node.id] = inputs;
  }

  return seeded;
}

export const subflowExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;
  const ref = String(config.workflow ?? "").trim();
  if (!ref) ctx.abort("subflow has no workflow reference configured");

  const resolver = getWorkflowResolver();
  if (!resolver) {
    ctx.abort(
      "No workflow resolver registered. Call registerWorkflowResolver() so subflow can find the workflow it references.",
    );
  }

  const maxDepth = Number.isFinite(config.maxDepth) ? Number(config.maxDepth) : DEFAULT_MAX_DEPTH;
  const depth = ctx.depth ?? 0;
  if (depth + 1 > maxDepth) {
    // Name the cause. "Maximum call stack exceeded" tells an author nothing
    // about the workflow they wired into itself.
    ctx.abort(
      `subflow depth limit reached (${maxDepth}) at "${ref}" — a workflow is referencing itself, directly or through a chain.`,
    );
  }

  // An optional pin. A workflow another workflow depends on is an interface:
  // without a pin, someone edits the child and the parent silently runs
  // different logic while still reporting success.
  const pinned = config.version === undefined || config.version === "" ? undefined : Number(config.version);
  if (pinned !== undefined && !Number.isInteger(pinned)) {
    ctx.abort(`subflow "${ref}" has a non-integer version pin (${String(config.version)}).`);
  }

  const resolved = await resolver!(ref, pinned);

  // A mismatch names BOTH versions. Reporting it as "not found" would send an
  // author looking for a workflow that is sitting right there — which is why
  // the resolver can say which of the two failures it hit.
  const child = isResolutionFailure(resolved)
    ? ctx.abort(
        resolved.reason === "version-mismatch"
          ? (resolved.message ??
            `subflow "${ref}" is pinned to version ${pinned}, but the host has ${resolved.available ?? "a different version"}.`)
          : (resolved.message ?? `subflow could not resolve workflow "${ref}"`),
      )
    : resolved;

  if (!child) ctx.abort(`subflow could not resolve workflow "${ref}"`);

  const mode = subflowMode(config);
  const streaming = mode === "stream" || mode === "both";

  const forward = (event: RunEvent) => {
    if (!streaming) return;
    // Surface the child's progress on the PARENT's feed as a log line against
    // this node. Re-emitting the child's raw events would collide with the
    // parent's own node ids — a child's "node-status" for its `output` node is
    // not a status for anything in the parent graph.
    const detail =
      event.type === "node-status"
        ? `${event.nodeId} ${event.status}`
        : event.type === "run-end"
          ? `finished (${event.ok ? "ok" : "failed"})`
          : event.type;
    ctx.emit({
      type: "log",
      nodeId: ctx.node.id,
      level: "info",
      message: `[${ref}] ${detail}`,
    });
  };

  const result = await runFlow(
    child!,
    // Inherit the parent's registry, then let the graph layer its own on top.
    // The inherited half is the fix; the layered half keeps a graph that
    // deliberately hands its child extra or different executors working.
    { ...(ctx.executors ?? {}), ...((config.executors as Record<string, unknown>) ?? {}) } as never,
    forward,
    {
      initialInputs: childInputs(config, child!, ctx.inputs as Record<string, unknown>),
      depth: depth + 1,
      // Push THIS node onto the identity path, so a node inside the child graph
      // cannot share an idempotency key with a same-named node in the parent —
      // or with the same child graph invoked from a different parent node.
      // Attempt and the first-attempt clock ride down unchanged: the child's
      // work happens inside this node's attempt.
      run: ctx.run?.descend(ctx.node.id),
    },
  );

  if (!result.ok) {
    const reason = result.error ?? "unknown error";

    // A PAUSE IS NOT A FAILURE, and it travels this same channel.
    //
    // Until 0.77.0 every unsuccessful child run was wrapped as
    // `subflow "x" failed: <reason>`. `decodePause` is prefix-anchored
    // (`reason.startsWith(PAUSE_PREFIX)`), so a `human_approval` or
    // `user_input` one level down produced a string that no longer decoded:
    // the durable coordinator read a FAILED run instead of a run parked on a
    // person, the gate became unresumable, and retry policy counted someone's
    // pending decision as a fault.
    //
    // The Rust twin never had this and says why at the same line; this
    // runtime, PHP and Python all did.
    if (decodePause(reason)) {
      ctx.abort(reason);
    }

    // A genuine failure still names the subflow. That context is worth
    // keeping; it is only the pause that must travel untouched.
    ctx.abort(`subflow "${ref}" failed: ${reason}`);
  }

  // `stream` alone still emits a final value on `stream` so downstream nodes
  // have something to run on; `both` publishes on every declared port.
  if (mode === "stream") {
    return { __port: "stream", value: result.outputs };
  }
  if (mode === "both") {
    return result.outputs;
  }
  return { __port: "out", value: result.outputs };
};

import { getLlmClient, type LlmRoute } from "./capabilities";
import type { NodeExecutor } from "../types";

/**
 * `@fancy/llm_branch` — a SHUTTLE, not an engine.
 *
 * It carries the declared routes and the decision prompt out to whatever LLM
 * client the host registered, and carries the chosen port back down the graph.
 * It contains no provider SDK, no prompt engineering, no response parsing and
 * no retry policy — all of that belongs to the host's client, which is what
 * lets this node live in core without every consumer inheriting an LLM
 * dependency.
 *
 * The one thing it does own is graph integrity, because that is a workflow
 * concern rather than an AI one: a port the model invents must never route.
 */

/** Read the node's declared routes out of config. */
export function declaredRoutes(config: Record<string, unknown>): LlmRoute[] {
  const raw = config.routes;
  if (!Array.isArray(raw)) return [];
  return raw
    .map((r) => ({ port: String((r as any)?.port ?? "").trim(), description: (r as any)?.description }))
    .filter((r) => r.port !== "");
}

/**
 * Where a run goes when the model returns a port that was never offered.
 *
 * Emitting on a port with no edge silently ends the branch — the worst failure
 * mode in a workflow engine, because the run reports success having done
 * nothing. So: the `fallback` port when it exists, else the first declared
 * route, and always loudly.
 */
export function resolveFallbackPort(routes: LlmRoute[], fallbackEnabled: boolean): string {
  if (fallbackEnabled) return "fallback";
  // Callers only reach this with at least one declared route (a node with none
  // aborts earlier), so there is always somewhere safe to land.
  return routes[0]?.port ?? "out";
}

export const llmRouterExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;
  const routes = declaredRoutes(config);

  if (routes.length === 0) {
    ctx.abort("llm_router has no routes configured");
  }

  const client = getLlmClient();
  if (!client) {
    // Fail loudly rather than guessing a branch. A silent default here would
    // look like the model made a choice.
    ctx.abort(
      "No LLM client registered. Call registerLlmClient() with your provider adapter — fancy-flow ships the routing, not the model call.",
    );
  }

  const fallbackEnabled = config.fallback !== false;

  const choice = await client!.chooseRoute({
    system: typeof config.system === "string" ? config.system : undefined,
    prompt: String(config.prompt ?? ctx.inputs ?? ""),
    routes,
    provider: typeof config.provider === "string" ? config.provider : undefined,
    model: typeof config.model === "string" ? config.model : undefined,
    credential: typeof config.credential === "string" ? config.credential : undefined,
  });

  const offered = new Set(routes.map((r) => r.port));
  let port = choice?.port ?? "";
  let reason = choice?.reason;

  if (!offered.has(port)) {
    const safe = resolveFallbackPort(routes, fallbackEnabled);
    ctx.emit({
      type: "log",
      nodeId: ctx.node.id,
      level: "warn",
      message: `llm_router: model returned "${port || "(nothing)"}", which is not a declared route. Routing to "${safe}".`,
    });
    reason = reason ?? `unrecognised route "${port}"`;
    port = safe;
  }

  // The reason travels WITH the value, so a completed run explains itself
  // without needing the model call replayed.
  return { __port: port, value: { route: port, reason, input: ctx.inputs } };
};

import type { ComponentType, ReactNode } from "react";

/**
 * Rich user input — the injection point.
 *
 * `rich_user_input` pauses a run on a fully authored page (long-form content,
 * required reading + confirmation, multi-section forms) rather than a flat
 * field list. That page IS a fancy-cms document — fancy-flow defines no
 * document schema of its own and never re-implements one.
 *
 * The wiring ships in the box. Import the subpath once and the node lights up:
 *
 * ```ts
 * import "@particle-academy/fancy-flow/rich-input";
 * ```
 *
 * That module registers fancy-cms's `PageDoc` + `CmsPage` renderer + `Editor`
 * against this seam. It lives on a separate entry so `@particle-academy/
 * fancy-cms-ui` and `@particle-academy/react-fancy` stay OPTIONAL peers — most
 * flows never use a rich input, and a workflow editor should not drag a CMS
 * into every install.
 *
 * The seam stays public so a host can substitute a different document engine,
 * but that is the escape hatch, not the expected path.
 *
 * Until something registers, the node still registers and still round-trips
 * its config — it renders a "how to enable" body rather than an empty card.
 */
export type RichInputAdapter = {
  /**
   * react-fancy's `FauxClient` (or any component with the same shape) — a
   * frame that mimics a browser window or device and scales its content down
   * to fit. Used to preview the authored page inside the node card.
   */
  FauxClient?: ComponentType<any>;
  /**
   * Props for the frame — e.g. `{ variant: "browser", width: 1280, scale: "fit" }`
   * so a full-width page renders at its real width and scales down into the
   * node card instead of reflowing to a cramped layout that misrepresents it.
   */
  frameProps?: Record<string, unknown>;
  /** Render the stored document read-only, for the in-node preview. */
  renderDocument?: (doc: unknown) => ReactNode;
  /** Editor mounted in the config panel via `renderDocumentField`. */
  renderEditor?: (props: { value: unknown; onChange: (next: unknown) => void }) => ReactNode;
};

let adapter: RichInputAdapter | null = null;
const listeners = new Set<() => void>();

/** Install the host's document editor + preview frame. Returns an unregister fn. */
export function registerRichInputAdapter(next: RichInputAdapter): () => void {
  adapter = next;
  for (const l of listeners) l();
  return () => {
    if (adapter === next) {
      adapter = null;
      for (const l of listeners) l();
    }
  };
}

/** The registered adapter, or null when the host hasn't wired one. */
export function getRichInputAdapter(): RichInputAdapter | null {
  return adapter;
}

/** True once a host has wired an adapter — i.e. the node is usable. */
export function isRichInputEnabled(): boolean {
  return adapter !== null && (adapter.renderDocument !== undefined || adapter.renderEditor !== undefined);
}

/** Subscribe to adapter changes (so nodes re-render when it lands). */
export function onRichInputAdapterChanged(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

/**
 * RichInputPreview — the node card body. Shows the authored page inside a
 * FauxClient frame so an author can see, at a glance on the canvas, what the
 * person hitting this step will be looking at.
 *
 * Degrades in two steps rather than one: no adapter at all → install hint;
 * adapter but nothing authored yet → an empty frame with the step title. A
 * blank node body would read as "broken" in both cases.
 */
export function RichInputPreview({ config }: { config: Record<string, unknown> }) {
  const a = getRichInputAdapter();
  const title = typeof config.title === "string" && config.title.trim() !== "" ? config.title : "Untitled step";
  const doc = config.document;

  if (!a || (!a.renderDocument && !a.renderEditor)) {
    return (
      <div className="ff-rich-preview">
        <span className="ff-rich-preview__title">{title}</span>
        <div className="ff-rich-preview__unavailable">
          Add <code>@particle-academy/fancy-cms-ui</code> +{" "}
          <code>@particle-academy/react-fancy</code>, then{" "}
          <code>import "@particle-academy/fancy-flow/rich-input"</code>.
        </div>
      </div>
    );
  }

  const body = doc === undefined || doc === null
    ? <p className="ff-rich-preview__unavailable">Nothing authored yet.</p>
    : a.renderDocument?.(doc) ?? null;

  const Frame = a.FauxClient;

  return (
    <div className="ff-rich-preview">
      <span className="ff-rich-preview__title">{title}</span>
      <div className="ff-rich-preview__frame">
        {Frame ? <Frame {...(a.frameProps ?? { variant: "browser" })}>{body}</Frame> : body}
      </div>
    </div>
  );
}

import { memo, useMemo } from "react";
import { Handle, NodeResizer, NodeToolbar, Position, type NodeProps } from "@xyflow/react";
import type { FlowNode, NodeRunStatus, PortDescriptor } from "../types";
import { categoryAccent, getNodeKind } from "./registry";
import { nodeConfig, resolveNodePorts } from "./ports";
import { useUndeclaredInboundHandles } from "../components/nodes/inbound-handles";

/**
 * RegistryNode — generic node renderer that looks up the node's kind in
 * the registry and applies its `accent`/`label`/`icon`/`renderBody`. Used
 * as the xyflow node component for every registered kind.
 */
function RegistryNodeInner(props: NodeProps<FlowNode>) {
  const kindName = (props.data as any).kind ?? props.type;
  const kind = useMemo(() => getNodeKind(kindName), [kindName]);
  const data = props.data;
  const resolved = kind ? resolveNodePorts(props, kind) : {};
  const inputs: PortDescriptor[] = resolved.inputs ?? (kind ? defaultInputs(kind.category) : []);
  const fallbackInputs = useUndeclaredInboundHandles(props.id, inputs);

  if (!kind) {
    return (
      <div className="ff-node ff-node--unknown">
        <div className="ff-node__header" style={{ background: "#71717a" }}>
          <span className="ff-node__tag">UNKNOWN</span>
          <span className="ff-node__label">{kindName}</span>
        </div>
        <p className="ff-node__desc">No registered kind for "{kindName}".</p>
      </div>
    );
  }

  const status: NodeRunStatus = data.status ?? "idle";
  const accent = kind.accent ?? categoryAccent(kind.category);
  const outputs: PortDescriptor[] = resolved.outputs ?? defaultOutputs(kind.category);
  const allInputs = [...inputs, ...fallbackInputs.map<PortDescriptor>((id) => ({ id }))];
  const config = nodeConfig(props);
  const label = data.label ?? kind.label;

  return (
    <div
      className={[
        "ff-node",
        `ff-node--status-${status}`,
        `ff-node--cat-${kind.category}`,
        props.selected ? "ff-node--selected" : "",
        kind.resizable ? "ff-node--resizable" : "",
      ].filter(Boolean).join(" ")}
      style={{ borderColor: props.selected ? accent : undefined }}
    >
      {kind.resizable && (
        <NodeResizer
          isVisible={props.selected ?? false}
          color={accent}
          {...(typeof kind.resizable === "object" ? kind.resizable : {})}
        />
      )}
      {kind.toolbar && (
        <NodeToolbar isVisible={props.selected ?? false}>
          {kind.toolbar({ nodeId: props.id, config: config as any, selected: props.selected ?? false })}
        </NodeToolbar>
      )}
      <header className="ff-node__header" style={{ background: accent }}>
        {kind.icon && <span className="ff-node__icon" aria-hidden>{kind.icon}</span>}
        <span className="ff-node__tag">{kind.label.toUpperCase()}</span>
        <span className="ff-node__label">{label}</span>
        {status !== "idle" && <span className={`ff-node__dot ff-node__dot--${status}`} aria-label={`status ${status}`} />}
      </header>

      {data.description && <p className="ff-node__desc">{data.description}</p>}

      <div className="ff-node__body">
        {kind.renderBody
          ? kind.renderBody({ nodeId: props.id, config: config as any, selected: props.selected ?? false })
          : <DefaultBody config={config} kind={kind.configSchema} />}
      </div>

      {data.statusText && <p className="ff-node__status-text">{data.statusText}</p>}

      {(data as any).output !== undefined && (
        <p className="ff-node__output" title="Latest output">→ {previewValue((data as any).output)}</p>
      )}

      {allInputs.map((p, i) => (
        <Handle
          key={p.id}
          type="target"
          position={Position.Left}
          id={p.id}
          style={portStyle(i, allInputs.length)}
          title={p.label ?? p.id}
          {...(i >= inputs.length
            ? {
                "aria-label": `Input handle ${p.id}`,
                "data-flow-target-handle": p.id,
                className: "ff-node__fallback-handle",
              }
            : {})}
        >
          {i >= inputs.length && <span aria-hidden>{p.id}</span>}
        </Handle>
      ))}
      {outputs.map((p, i) => (
        <Handle
          key={p.id}
          type="source"
          position={Position.Right}
          id={p.id}
          style={portStyle(i, outputs.length)}
          title={p.label ?? p.id}
        />
      ))}
    </div>
  );
}

export const RegistryNode = memo(RegistryNodeInner);

function defaultInputs(category: string): PortDescriptor[] {
  return category === "trigger" ? [] : [{ id: "in" }];
}
function defaultOutputs(category: string): PortDescriptor[] {
  return category === "output" ? [] : [{ id: "out" }];
}

function portStyle(i: number, total: number): React.CSSProperties {
  if (total <= 1) return {};
  const slot = (100 / (total + 1)) * (i + 1);
  return { top: `${slot}%` };
}

/**
 * DefaultBody — compact summary of the config values for nodes that
 * don't provide a custom renderBody. Skips fields that look empty.
 */
function DefaultBody({ config, kind }: { config: Record<string, unknown>; kind?: import("./types").ConfigField[] }) {
  const fields = kind ?? [];
  // A kind with no config schema has nothing to configure — don't nag with a
  // "configure in the panel" prompt (that's only for a kind that HAS fields but
  // none are filled in yet). Triggers, Output, etc. render as just their header.
  if (fields.length === 0) return null;
  const visible = fields
    .map((f) => ({ field: f, value: config[f.key] }))
    .filter(({ value }) => value !== undefined && value !== "" && value !== null);
  if (visible.length === 0) {
    return <div className="ff-node__body-empty">— configure in the panel</div>;
  }
  return (
    <ul className="ff-node__summary">
      {visible.slice(0, 4).map(({ field, value }) => (
        <li key={field.key}>
          <span className="ff-node__summary-key">{field.label}:</span>
          <span className="ff-node__summary-value">{previewValue(value)}</span>
        </li>
      ))}
      {visible.length > 4 && <li className="ff-node__summary-more">+ {visible.length - 4} more</li>}
    </ul>
  );
}

const truncate = (s: string, n = 30): string => (s.length > n ? s.slice(0, n - 1) + "…" : s);

/** A short, human name for one item in a repeater/list value. */
function itemLabel(item: unknown): string {
  if (item && typeof item === "object") {
    const o = item as Record<string, unknown>;
    const name = o.label ?? o.name ?? o.key ?? o.title ?? o.id;
    if (typeof name === "string" && name) return name;
    if (typeof name === "number") return String(name);
    return "item";
  }
  return String(item ?? "");
}

/**
 * A node card's job is to read at a glance, not to be a data dump — so a value
 * is summarised, never `JSON.stringify`d. An array becomes its item names (or a
 * count), an object becomes a field count. Raw JSON on a card was the specific
 * thing to kill: `Fields: [{"key":"answer",…}]` reads as noise.
 */
export function previewValue(v: unknown): string {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return truncate(v);
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  if (Array.isArray(v)) {
    if (v.length === 0) return "none";
    const names = v.slice(0, 3).map(itemLabel).filter(Boolean).join(", ");
    const rest = v.length > 3 ? `, +${v.length - 3}` : "";
    return names ? truncate(names + rest) : `${v.length} item${v.length === 1 ? "" : "s"}`;
  }
  if (typeof v === "object") {
    const keys = Object.keys(v as object);
    return keys.length === 0 ? "empty" : `${keys.length} field${keys.length === 1 ? "" : "s"}`;
  }
  return "…";
}

import { createElement } from "react";
import { ensureBuiltinKinds, registerBuiltinKindInternal } from "./registry";
import { RichInputPreview } from "./rich-input";
import { LaneNode } from "../components/nodes/LaneNode";
import { NoteNode } from "../components/nodes/NoteNode";
import { BUILTIN_KIND_DATA } from "./builtin-kinds";
import type { NodeKindDefinition } from "./types";

/**
 * The built-in kit WITH its React renderers — the editor's door into it.
 *
 * ## Why this file is a decorator rather than the table
 *
 * `/engine` promised to be React-free and was not (#11). The exact edge was
 * `engine.ts → registry/registry.ts → registry/builtin.ts → react`, and it was
 * a REGRESSION of a fix whose comment is still in `engine.ts`: that file
 * imports from the module rather than the barrel precisely to avoid this, and
 * `registry.ts` later gained a `builtin.ts` import so the registry
 * self-populates. Both changes were right. Nothing tested the property, so the
 * second silently undid the first.
 *
 * The surface turned out to be four lines across three kinds in a 1,064-line
 * file, so the table moved to `builtin-kinds.ts` (React-free, what `registry.ts`
 * imports) and only the renderers stayed here.
 *
 * ## Where this gets applied, and why THERE
 *
 * `src/index.ts` calls `registerBuiltinKinds()` at module scope. That is not an
 * arbitrary choice: `package.json`'s `sideEffects` lists `./dist/index.js` and
 * `./dist/index.cjs` and NOT `./dist/registry.js`, so a consumer's bundler is
 * entitled to drop a top-level statement in the registry chunk and obliged to
 * keep one in the root barrel. Putting it anywhere else would work until
 * somebody's tree-shaker disagreed, and the symptom would be lanes quietly
 * rendering as ordinary cards.
 *
 * A consumer who never imports the React root still gets every kind — schema,
 * ports, executors — because `registry.ts` self-populates from the data
 * module. They simply get no renderers, which is correct: a queue worker has
 * no DOM to render into.
 *
 * ## Host and marketplace kinds are untouched
 *
 * Both arrive at runtime through `registerNodeKind` carrying their own
 * `component` / `renderBody`, and never pass through here. This split is
 * first-party-only by construction and adds no rule a third-party kind has to
 * follow.
 */

/** The renderers, by canonical kind name. */
const RENDERERS: Record<string, Partial<NodeKindDefinition>> = {
  "@particle-academy/lane": { component: LaneNode },
  "@particle-academy/terminal_lane": { component: LaneNode },
  "@particle-academy/note": { component: NoteNode },
  "@particle-academy/rich_user_input": {
    // Previews the authored page inside a FauxClient frame, so the canvas shows
    // what the person hitting this step will actually see.
    renderBody: (ctx) =>
      createElement(RichInputPreview, { config: (ctx.config ?? {}) as Record<string, unknown> }),
  },
};

/**
 * Every builtin, with renderers attached to the four that have one.
 *
 * A kind with no renderer is passed through by identity rather than copied, so
 * `BUILTIN_KINDS` and `BUILTIN_KIND_DATA` share objects wherever there is
 * nothing to add.
 */
export const BUILTIN_KINDS: NodeKindDefinition[] = BUILTIN_KIND_DATA.map((kind) => {
  const renderer = RENDERERS[kind.name];
  return renderer ? { ...kind, ...renderer } : kind;
});

/**
 * Register every built-in kind, renderers included.
 *
 * Idempotent, and safe to call after `registry.ts` has already self-populated
 * the plain table: it goes through `registerBuiltinKindInternal`, which
 * replaces a BUILTIN by name, so this UPGRADES the four kinds in place rather
 * than duplicating anything.
 *
 * It does NOT replace a name a host has claimed with `registerNodeKind`. That
 * is the whole point of 0.66.2 — a consumer's replacement of a builtin used to
 * be silently reverted every time this ran, and since the root barrel calls it
 * as an import side effect, whether that happened depended on bundler ordering.
 *
 * The distinction matters to anyone reading this to decide whether calling it
 * is safe: safe against builtins, deliberately powerless against a host.
 */
export function registerBuiltinKinds(): void {
  // Lay the React-free table down FIRST, through the same lazy path every other
  // entry point uses. Without this the flag is still unset, so the next read
  // anywhere — `getNodeKind`, the palette, a viewer — triggers
  // `ensureBuiltinKinds()` and re-registers the plain table OVER the decorated
  // kinds, silently dropping the four renderers this function exists to attach.
  ensureBuiltinKinds();

  for (const kind of BUILTIN_KINDS) registerBuiltinKindInternal(kind);
}

// Everything else the table exports keeps its old import path, so no consumer
// of `./builtin` has to change.
export { BUILTIN_KIND_DATA, registerBuiltinKindData } from "./builtin-kinds";

/**
 * What a terminal has said, in a form a node can wait on.
 *
 * A raw `onData` stream is not something a workflow can match against, for
 * three reasons that all fail the same way — intermittently, and usually only
 * once there is real output moving:
 *
 *  1. **Chunks are arbitrary.** A PTY splits wherever it splits, so `Ready >`
 *     can arrive as `Rea` + `dy >`. Testing each chunk on its own finds the
 *     pattern when output is small enough to land in one write and misses it
 *     when it is not. So matching runs against an ACCUMULATED buffer, never a
 *     chunk.
 *
 *  2. **Output arrives before anyone is listening.** A node that types at a
 *     process and a node that waits for its reply are two steps, and anything
 *     printed between them is gone if the buffer starts when the wait does.
 *     So the transcript is attached when the SESSION opens, and a wait reads
 *     what has already accumulated before it subscribes to anything new.
 *
 *  3. **Escape sequences are everywhere and they also straddle.** An agent TUI
 *     writes `Ready` as `ESC[32m Ready ESC[0m`, so matching raw bytes fails on
 *     text a person can plainly read. Stripping per chunk reintroduces problem
 *     1 in a second guise — `ESC[3` + `2mReady` strips to `ESC[32mReady` with
 *     the escape now INSIDE the text. So an incomplete trailing sequence is
 *     held back until the rest of it arrives.
 *
 * Text is consumed through a match, so two waits for the same pattern do not
 * both resolve on the first occurrence — which would let a loop appear to make
 * progress while reading one old line forever.
 */

/**
 * The control characters, by code point rather than as literals.
 *
 * A raw ESC byte sitting in a `.ts` file survives most tools and not all of
 * them, and the failure is the quiet kind: strip one out and the pattern below
 * still parses, still looks right in review, and matches nothing — so every
 * wait fails on coloured output while the code reads as correct. It happened
 * twice while this file was being written, which is the argument.
 */
const ESC = String.fromCharCode(0x1b);
const CSI = String.fromCharCode(0x9b);
const BEL = String.fromCharCode(0x07);

/**
 * CSI (`ESC [ ... final`), OSC (`ESC ] ... BEL|ST`), and the two-character
 * escapes. Written out rather than taken from a dependency: it is a regex, and
 * the suite's rule is that third-party code is a liability carried for years.
 */
const ANSI = new RegExp(
  `[${ESC}${CSI}](?:\\[[0-?]*[ -/]*[@-~]|\\][^${BEL}${ESC}]*(?:${BEL}|${ESC}\\\\)|[@-Z\\\\-_])`,
  "g",
);

/**
 * How much unterminated escape to hold back before giving up on it.
 *
 * An OSC sequence carrying a window title is legitimately long, but a lone
 * `ESC` that never terminates is just a byte — holding the rest of the stream
 * hostage behind it would stall a wait forever, which is a worse failure than
 * one stray character in the output.
 */
const MAX_PENDING_ESCAPE = 1024;

/**
 * Cap on retained text. A chatty process across a long run would otherwise grow
 * this without limit. Dropping from the FRONT keeps the recent output — which
 * is what a wait is about to match — and a pattern spanning a megabyte of
 * output is not a pattern anybody wrote.
 */
const MAX_BUFFER = 1_000_000;

export type TranscriptWaitResult =
  | { status: "matched"; text: string; match: RegExpMatchArray }
  | { status: "timeout"; text: string }
  | { status: "exited"; text: string; exitCode: number; signal?: string };

export class TerminalTranscript {
  /** Stripped, complete text not yet consumed by a wait. */
  private text = "";

  /** Raw bytes held back because they may be the start of an escape sequence. */
  private tail = "";

  private readonly waiters = new Set<() => void>();

  /** Feed raw terminal output in. Safe to call with any chunking. */
  append(chunk: string): void {
    this.tail += chunk;

    const safe = this.safeLength();
    if (safe > 0) {
      this.text += this.tail.slice(0, safe).replace(ANSI, "");
      this.tail = this.tail.slice(safe);
    }

    if (this.text.length > MAX_BUFFER) {
      this.text = this.text.slice(this.text.length - MAX_BUFFER);
    }

    for (const wake of [...this.waiters]) wake();
  }

  /**
   * How much of `tail` can be stripped now.
   *
   * Everything, unless the final `ESC` has not yet been terminated — in which
   * case processing stops there and resumes when the rest arrives.
   */
  private safeLength(): number {
    const lastEsc = Math.max(this.tail.lastIndexOf(ESC), this.tail.lastIndexOf(CSI));
    if (lastEsc === -1) return this.tail.length;

    // A complete sequence starting there means nothing is pending.
    ANSI.lastIndex = lastEsc;
    const match = ANSI.exec(this.tail);
    ANSI.lastIndex = 0;
    if (match && match.index === lastEsc) return this.tail.length;

    // Unterminated, but long enough that it is not really an escape.
    if (this.tail.length - lastEsc > MAX_PENDING_ESCAPE) return this.tail.length;

    return lastEsc;
  }

  /** Unconsumed output, escape sequences removed. */
  peek(): string {
    return this.text;
  }

  /** Drop everything currently buffered — used before typing a new command. */
  clear(): void {
    this.text = "";
    this.tail = "";
  }

  /**
   * Wait until `pattern` matches the unconsumed text.
   *
   * Checks what has ALREADY arrived before subscribing, because the common case
   * is that the process answered while the previous node was still finishing.
   *
   * `exited` is raced deliberately. Without it, a shell that dies reports as
   * "timed out waiting for X" — sending whoever reads it to lengthen a timeout
   * for a process that is not running. Naming the exit is the difference
   * between a diagnosis and a wrong lead.
   */
  waitFor(
    pattern: RegExp,
    options: { timeoutMs: number; exited?: Promise<{ exitCode: number; signal?: string }> },
  ): Promise<TranscriptWaitResult> {
    return new Promise<TranscriptWaitResult>((resolve) => {
      let settled = false;
      let timer: ReturnType<typeof setTimeout> | undefined;

      const finish = (result: TranscriptWaitResult) => {
        if (settled) return;
        settled = true;
        this.waiters.delete(check);
        if (timer) clearTimeout(timer);
        resolve(result);
      };

      const check = () => {
        // A global or sticky pattern carries `lastIndex` between calls, so it
        // would start each attempt part-way through a buffer it has not read.
        pattern.lastIndex = 0;
        const match = pattern.exec(this.text);
        if (!match) return;

        // `|| 1` so a pattern that can match empty still makes progress rather
        // than consuming nothing and matching the same position forever.
        const through = match.index + (match[0].length || 1);
        const text = this.text.slice(0, through);
        this.text = this.text.slice(through);
        finish({ status: "matched", text, match });
      };

      this.waiters.add(check);
      check();
      if (settled) return;

      if (options.timeoutMs > 0) {
        timer = setTimeout(() => {
          const text = this.text;
          this.text = "";
          finish({ status: "timeout", text });
        }, options.timeoutMs);
        // Never hold a Node process open just to time out a wait nobody wants.
        (timer as unknown as { unref?: () => void }).unref?.();
      }

      options.exited?.then(
        (exit) => {
          // No re-check here, deliberately. `append` wakes every waiter the
          // instant data lands, so a process that prints its answer and then
          // exits has already matched by the time this runs — `settled` is
          // true and this returns. A re-check looked like it was guarding that
          // race and was in fact unreachable, which is worse than absent: it
          // read as a guarantee while the actual guarantee lived elsewhere.
          if (settled) return;
          const text = this.text;
          this.text = "";
          finish({ status: "exited", text, exitCode: exit.exitCode, signal: exit.signal });
        },
        () => {},
      );
    });
  }
}

/**
 * Who is running, which step this is, and how many times it has been tried.
 *
 * ## Why an engine needs this at all
 *
 * A node that WRITES to somebody else's system — charge a card, send a message,
 * open a pull request — can only survive a retry if the retry carries the same
 * idempotency key the first attempt did. Otherwise the provider treats the
 * second call as a new request and the customer is charged twice.
 *
 * Until this existed the executor context was `{ node, inputs, emit, abort }`,
 * which is not enough to derive one. Both obvious fallbacks are worse than
 * sending no key at all:
 *
 * - **the node id alone** is stable across retries, and also across RUNS — two
 *   legitimate payments share a key and the provider silently collapses the
 *   second into the first. A payment that never happened, reported as success;
 * - **a fresh random value** is unique per run, and also per ATTEMPT — a retry
 *   creates a second charge, which is the thing being avoided.
 *
 * ## What actually identifies a step
 *
 * Not `(run, node)`. A node legitimately executes more than once inside one
 * run: once per subflow invocation, once per iteration of a loop an executor
 * drives itself. `(run, node)` would give every one of those the same key, and
 * a provider would honour exactly one of them.
 *
 * So a step is identified by the **path of invocations that led to it**, plus
 * an optional **occurrence** for repetition at the same level:
 *
 * ```text
 * runKey ":" segment ("/" segment)*        segment := escape(id) ["#" occurrence]
 * ```
 *
 * And the part that is easy to get backwards: **`attempt` is NOT in the key.**
 * It is carried here for logging and for {@link RunIdentity.isReplaySafe}, and
 * putting it in the key would restore the exact bug the key exists to prevent.
 *
 * Pinned cross-runtime by `shared/flow-run-identity` in
 * `@particle-academy/fancy-conformance`.
 */

/** The wire shape — what a queue job payload carries. */
export type RunIdentityJson = {
  runKey: string;
  path?: string[];
  attempt?: number;
  firstAttemptAt?: string;
};

/**
 * Escape one segment so the composition is injective.
 *
 * `%` FIRST, or the escaping is not reversible: escaping `/` before `%` turns a
 * literal `a%2Fb` into the same text as the escaped form of `a/b`, which is the
 * collision this exists to prevent, reintroduced by its own fix.
 */
export function escapeSegment(value: string): string {
  // Not `replaceAll` — the package targets ES2020, and this must produce the
  // identical string on every runtime that reads the conformance table.
  return value.replace(/%/g, "%25").replace(/\//g, "%2F").replace(/#/g, "%23");
}

function renderSegment(value: string, occurrence?: number | null): string {
  const escaped = escapeSegment(value);
  // `occurrence === 0` is a real occurrence. A truthiness check here silently
  // collapses iteration 0 into the un-iterated key.
  return occurrence === undefined || occurrence === null ? escaped : `${escaped}#${occurrence}`;
}

function instant(value: string): number {
  const ms = Date.parse(value);
  if (Number.isNaN(ms)) {
    throw new Error(
      `RunIdentity: firstAttemptAt is not a parseable timestamp: ${JSON.stringify(value)}`,
    );
  }
  return ms;
}

/**
 * A run, a position inside it, and how many times this position has been tried.
 *
 * Immutable. {@link descend} returns a new identity rather than mutating, so an
 * executor cannot change what its siblings see.
 */
export class RunIdentity {
  /** Stable for the whole run: same across retries, resumes, workers and hosts. */
  readonly runKey: string;

  /**
   * Enclosing invocation segments, outermost first, ALREADY RENDERED.
   *
   * Empty at the top level. A subflow pushes the invoking node's id; an
   * executor that loops pushes `id#i`.
   */
  readonly path: readonly string[];

  /**
   * 1-based attempt of THIS logical step. Never part of the key.
   *
   * The durable driver sets it from the node's claim row, which is exact. A
   * plain in-process `runFlow` gets whatever the host passed, which is
   * run-scoped and therefore conservative — see `isReplaySafe`.
   */
  readonly attempt: number;

  /** ISO-8601 UTC instant of attempt 1 of this step. */
  readonly firstAttemptAt: string;

  constructor(
    runKey: string,
    path: readonly string[] = [],
    attempt = 1,
    firstAttemptAt: string = new Date().toISOString(),
  ) {
    if (!runKey || runKey.trim() === "") {
      throw new Error("RunIdentity: runKey must be a non-empty string.");
    }
    this.runKey = runKey;
    this.path = Object.freeze([...path]);
    this.attempt = Math.max(1, Math.trunc(attempt));
    this.firstAttemptAt = firstAttemptAt;
    Object.freeze(this);
  }

  /**
   * The identity of one execution of one node — stable across retries of that
   * execution, distinct from every other execution of the same node.
   *
   * Pass `occurrence` when an executor runs the same node more than once at the
   * same level (a loop body, one item of a fan-out it drives itself).
   */
  stepKey(nodeId: string, occurrence?: number | null): string {
    return `${this.runKey}:${[...this.path, renderSegment(nodeId, occurrence)].join("/")}`;
  }

  /**
   * A child identity for work nested inside this step.
   *
   * `subflow` pushes the invoking node's id, so a node inside the child graph
   * cannot collide with a same-named node in the parent. Attempt and
   * `firstAttemptAt` are carried down unchanged: the nested work happens inside
   * this step's attempt, and shares its clock.
   */
  descend(segment: string, occurrence?: number | null): RunIdentity {
    return new RunIdentity(
      this.runKey,
      [...this.path, renderSegment(segment, occurrence)],
      this.attempt,
      this.firstAttemptAt,
    );
  }

  /** A copy on a different attempt, first-attempt clock preserved. */
  withAttempt(attempt: number, firstAttemptAt?: string): RunIdentity {
    return new RunIdentity(
      this.runKey,
      this.path,
      attempt,
      firstAttemptAt ?? this.firstAttemptAt,
    );
  }

  /**
   * May this attempt reuse the step key and still be deduplicated?
   *
   * Providers forget idempotency keys — Stripe after 24 hours. Past that
   * window, resending the key creates a second charge and sending a fresh one
   * creates a second charge, so **the caller must refuse rather than pick
   * between them**: a loud stuck run beats a silent double write.
   *
   * `true` on attempt 1 whatever the elapsed time — nothing was sent on an
   * earlier attempt, so there is nothing for the provider to have forgotten.
   * That is what lets a run park on a human gate for a week and then write.
   *
   * `windowSeconds: null` means the provider does not expire keys. `0` means
   * it does not dedupe at all, so no retry may reuse a key — it is a real
   * window, not an absent one, and the two must not be conflated: reading `0`
   * as `null` turns "this provider does not dedupe" into "this provider
   * dedupes forever", which is the more dangerous of the two by a distance.
   */
  isReplaySafe(windowSeconds: number | null | undefined, now: Date | string = new Date()): boolean {
    if (this.attempt <= 1) return true;
    if (windowSeconds === null || windowSeconds === undefined) return true;
    if (windowSeconds <= 0) return false;

    const nowMs = typeof now === "string" ? instant(now) : now.getTime();
    // Clock skew between two workers must not turn a legitimate retry into a
    // refusal, so a negative elapsed clamps to zero.
    const elapsedSeconds = Math.max(0, (nowMs - instant(this.firstAttemptAt)) / 1000);

    // Inclusive: a key written at T is remembered THROUGH T + window.
    return elapsedSeconds <= windowSeconds;
  }

  toJSON(): Required<RunIdentityJson> {
    return {
      runKey: this.runKey,
      path: [...this.path],
      attempt: this.attempt,
      firstAttemptAt: this.firstAttemptAt,
    };
  }

  /** Rebuild from a queue payload. */
  static from(value: RunIdentity | RunIdentityJson | string): RunIdentity {
    if (value instanceof RunIdentity) return value;
    if (typeof value === "string") return new RunIdentity(value);
    return new RunIdentity(
      value.runKey,
      value.path ?? [],
      value.attempt ?? 1,
      value.firstAttemptAt ?? new Date().toISOString(),
    );
  }
}

