import { type ReactNode, memo } from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import type { FlowNode, NodeRunStatus, PortDescriptor } from "../../types";
import { useUndeclaredInboundHandles } from "./inbound-handles";

export type NodeShellProps = {
  /** Required: the xyflow node this is rendering. */
  node: NodeProps<FlowNode>;
  /** Accent color for the title bar / status ring. */
  accent: string;
  /** Tag/label shown to the left of the title (e.g. "TRIGGER", "ACTION"). */
  tag: string;
  /** Optional icon glyph (single-character string is fine). */
  icon?: ReactNode;
  /** Whether to show input handles on the left. Defaults true. */
  showInputs?: boolean;
  /** Whether to show output handles on the right. Defaults true. */
  showOutputs?: boolean;
  /** Body content under the title bar. */
  children?: ReactNode;
};

/**
 * Shared chrome for every kit node — title bar, accent border, status ring,
 * port handles. Specific node kinds compose this with their body content.
 */
function NodeShellInner({
  node,
  accent,
  tag,
  icon,
  showInputs = true,
  showOutputs = true,
  children,
}: NodeShellProps) {
  const data = node.data;
  const status: NodeRunStatus = data.status ?? "idle";
  const inputs = data.inputs ?? defaultInputs(showInputs);
  const outputs = data.outputs ?? defaultOutputs(showOutputs);
  const fallbackInputs = useUndeclaredInboundHandles(node.id, inputs);
  const allInputs = [...inputs, ...fallbackInputs.map<PortDescriptor>((id) => ({ id }))];

  return (
    <div
      className={["ff-node", `ff-node--status-${status}`, node.selected ? "ff-node--selected" : ""].filter(Boolean).join(" ")}
      style={{ borderColor: node.selected ? accent : undefined }}
    >
      <header className="ff-node__header" style={{ background: accent }}>
        <span className="ff-node__icon" aria-hidden>{icon ?? null}</span>
        <span className="ff-node__tag">{tag}</span>
        <span className="ff-node__label">{data.label}</span>
        {status !== "idle" && <StatusDot status={status} />}
      </header>

      {data.description && <p className="ff-node__desc">{data.description}</p>}
      {children && <div className="ff-node__body">{children}</div>}
      {data.statusText && <p className="ff-node__status-text">{data.statusText}</p>}

      {allInputs.map((p, i) => (
        <Handle
          key={p.id}
          type="target"
          position={Position.Left}
          id={p.id}
          style={portStyle(i, allInputs.length)}
          title={p.label ?? p.id}
          {...(i >= inputs.length
            ? {
                "aria-label": `Input handle ${p.id}`,
                "data-flow-target-handle": p.id,
                className: "ff-node__fallback-handle",
              }
            : {})}
        >
          {i >= inputs.length && <span aria-hidden>{p.id}</span>}
        </Handle>
      ))}
      {outputs.map((p, i) => (
        <Handle
          key={p.id}
          type="source"
          position={Position.Right}
          id={p.id}
          style={portStyle(i, outputs.length)}
          title={p.label ?? p.id}
        />
      ))}
    </div>
  );
}

export const NodeShell = memo(NodeShellInner);

function defaultInputs(show: boolean): PortDescriptor[] {
  return show ? [{ id: "in" }] : [];
}
function defaultOutputs(show: boolean): PortDescriptor[] {
  return show ? [{ id: "out" }] : [];
}

function portStyle(i: number, total: number): React.CSSProperties {
  if (total <= 1) return {};
  const slot = (100 / (total + 1)) * (i + 1);
  return { top: `${slot}%` };
}

function StatusDot({ status }: { status: NodeRunStatus }) {
  return <span className={`ff-node__dot ff-node__dot--${status}`} aria-label={`status ${status}`} />;
}

import { getTerminalHost, type TerminalSession, type TerminalSessionSpec } from "../registry/capabilities";
import { TerminalTranscript } from "./terminal-transcript";
import type { FlowGraph, FlowNode } from "../types";

/**
 * One terminal per terminal lane, for the length of a run.
 *
 * ## The lifetime, and why it is not per-node
 *
 * A terminal node is only useful if the process it talks to is the SAME one the
 * last node talked to. `cd` has to persist; an agent TUI has to still be
 * running with its conversation intact. A session opened per node would give
 * every node a fresh shell and quietly turn a sequence of steps into a series
 * of unrelated ones — each individually correct, the whole thing meaningless.
 *
 * So the session is keyed on the LANE, opened lazily by the first node inside
 * it, and closed once when the run ends. A graph that never reaches a terminal
 * node spawns no process at all, which is what makes it safe for the lane to
 * exist on a canvas that mostly does other things.
 *
 * ## Why membership is `parentId`
 *
 * It is what the canvas already means by "inside", and it already persists into
 * the WorkflowSchema — so a headless runtime resolves exactly the grouping a
 * person drew, with no second association to keep in step. The alternative, a
 * lane id typed into each node's config, is the same fact in two places and
 * would drift the first time somebody dragged a node out of a lane.
 *
 * Nesting is followed to the nearest terminal lane, so an ordinary lane inside
 * a terminal lane still resolves — grouping for looks should not change which
 * terminal a node talks to.
 */
export class TerminalSessions {
  private readonly open = new Map<string, Promise<TerminalSession>>();

  private readonly laneOf = new Map<string, string | null>();

  private readonly transcripts = new Map<string, TerminalTranscript>();

  private readonly listening = new Map<string, () => void>();

  constructor(private readonly graph: FlowGraph) {}

  /**
   * The terminal lane a node belongs to, or null.
   *
   * Walks up `parentId` rather than checking only the immediate parent, and
   * caches per node id — a graph is walked once per run, and the answer cannot
   * change while it runs.
   */
  laneFor(nodeId: string, isTerminalLane: (node: FlowNode) => boolean): string | null {
    const cached = this.laneOf.get(nodeId);
    if (cached !== undefined) return cached;

    const byId = new Map(this.graph.nodes.map((n) => [n.id, n]));
    const seen = new Set<string>();

    let current = byId.get(nodeId);
    let answer: string | null = null;

    while (current) {
      // A cycle in `parentId` is malformed rather than impossible — a dragged
      // node with a stale parent can produce one — and walking it forever would
      // hang the run rather than fail it.
      if (seen.has(current.id)) break;
      seen.add(current.id);

      if (current.id !== nodeId && isTerminalLane(current)) {
        answer = current.id;
        break;
      }

      const parentId = (current as unknown as { parentId?: string }).parentId;
      current = parentId ? byId.get(parentId) : undefined;
    }

    this.laneOf.set(nodeId, answer);
    return answer;
  }

  /**
   * The session for a lane, opening it on first use.
   *
   * The PROMISE is cached, not the resolved session. Two nodes cannot run
   * concurrently in the current engine, but a caller that awaits a
   * half-finished open would otherwise start a second process — and two shells
   * where a graph says one is the failure this class exists to prevent, arriving
   * only under concurrency and therefore only sometimes.
   */
  session(laneId: string, spec: TerminalSessionSpec): Promise<TerminalSession> {
    const existing = this.open.get(laneId);
    if (existing) return existing;

    const host = getTerminalHost();

    if (!host) {
      // Named as a MISSING HOST rather than a failed open. A node in a terminal
      // lane with no host registered is a configuration problem — the desktop
      // app did not install one — and reporting it as "the terminal failed"
      // sends someone to debug a process that was never started.
      const failed = Promise.reject(
        new Error(
          "No terminal host is registered. A terminal lane needs one — call registerTerminalHost() "
            + "from the desktop app, or install @particle-academy/fancy-flow/terminal/fancy-term-host.",
        ),
      );
      // Cached so every node in the lane fails the same way rather than the
      // first one failing and the rest re-asking a question already answered.
      this.open.set(laneId, failed);
      // Nothing awaits this until a node does; keep node from warning meanwhile.
      failed.catch(() => {});
      return failed;
    }

    // Subscribed the moment the session resolves, not when a node first waits.
    //
    // A process answers on its own schedule, and the node that types at it and
    // the node that reads the reply are two separate steps. Anything printed in
    // between is unrecoverable if the buffer starts when the WAIT does — so a
    // fast process would be missed and a slow one caught, which is the same bug
    // presenting as flakiness rather than as a bug.
    const opening = Promise.resolve(host.open(spec)).then((session) => {
      const transcript = this.transcriptFor(laneId);
      this.listening.set(laneId, session.onData((chunk) => transcript.append(chunk)));
      return session;
    });

    this.open.set(laneId, opening);
    opening.catch(() => {});
    return opening;
  }

  /**
   * The accumulated output for a lane.
   *
   * Created on demand and kept for the run, so it exists before the session
   * resolves and survives every node that reads it. Consuming is the reader's
   * job — see `TerminalTranscript.waitFor`.
   */
  transcriptFor(laneId: string): TerminalTranscript {
    const existing = this.transcripts.get(laneId);
    if (existing) return existing;

    const created = new TerminalTranscript();
    this.transcripts.set(laneId, created);
    return created;
  }

  /** True once a lane has a session — used to avoid opening one during teardown. */
  isOpen(laneId: string): boolean {
    return this.open.has(laneId);
  }

  /**
   * Close every session this run opened.
   *
   * Every close is attempted even if one throws: a host that fails to close one
   * PTY must not strand the others, which would leave processes alive after the
   * run reported that it had finished. Errors are returned rather than thrown,
   * because teardown runs in a `finally` and throwing there would replace the
   * run's real error with a cleanup error.
   */
  async closeAll(): Promise<Error[]> {
    const errors: Error[] = [];

    for (const [laneId, pending] of this.open) {
      try {
        // Unsubscribe BEFORE closing. A host that emits a final chunk while
        // shutting down would otherwise append to a transcript nobody will read
        // again, and a listener outliving its session is how a closed terminal
        // keeps a run's objects alive.
        this.listening.get(laneId)?.();
        this.listening.delete(laneId);

        const session = await pending;
        await session.close();
      } catch (e) {
        errors.push(e instanceof Error ? e : new Error(`${laneId}: ${String(e)}`));
      }
    }

    this.open.clear();
    this.listening.clear();
    this.transcripts.clear();
    return errors;
  }
}

/** The spec a terminal lane node declares. */
export function specForLane(lane: FlowNode): TerminalSessionSpec {
  const config = ((lane.data as { config?: Record<string, unknown> } | undefined)?.config ?? {}) as Record<
    string,
    unknown
  >;

  const text = (key: string): string | undefined => {
    const value = config[key];
    return typeof value === "string" && value !== "" ? value : undefined;
  };

  const env = config.env;

  return {
    command: text("command"),
    cwd: text("cwd"),
    env:
      env && typeof env === "object" && !Array.isArray(env)
        ? Object.fromEntries(
            Object.entries(env as Record<string, unknown>).map(([k, v]) => [k, String(v)]),
          )
        : undefined,
  };
}

/**
 * AN EDGE THAT DELIVERS NOTHING MUST SAY SO — the one implementation of that
 * check, shared by every path that can reach it.
 *
 * `runFlow` asks it of each node it reaches. The durable `Coordinator` asks it
 * of each node its frontier SKIPS, because a skipped node never gets a job and
 * so never replays to ask it for itself. Two copies of this check would agree
 * for a while and then disagree on one handle — which is exactly the kind of
 * divergence the warning exists to report — so there is one, and it EMITS
 * nothing. It returns the events and each caller decides where they go.
 *
 * Kept React-free on purpose: `run-flow.ts` imports it, and the `/engine` entry
 * must not reach React.
 */
import type { FlowEdge, FlowNode, RunEvent } from "../types";
// React-free modules, imported directly rather than via the `registry` barrel,
// which re-exports the RegistryNode component.
import { defaultConfigFor, getNodeKind } from "../registry/registry";
import { nodeConfig, resolvePortSpec } from "../registry/ports";
import { outputFieldsFor } from "../expressions/variables";

/**
 * The `log` / `warn` events for every inbound edge of `target` that delivers
 * nothing and never could.
 *
 * Asked BEFORE the activity gate, because the two outcomes are both silent and
 * only one reaches `collectInputs`. If the bad edge is the node's only inbound
 * one the node is SKIPPED; if it has another live edge it RUNS with that port
 * simply missing -- and then a downstream template that is entirely correct
 * renders empty, because the payload never arrived to have a field in it.
 *
 * Keyed on the source having COMPLETED and on the handle being a port the source
 * could NEVER publish. A branch that was not taken is ordinary and must never
 * warn; a source that finished and cannot publish this port is a
 * misconfiguration that delivers nothing on any run. A warning that fires on
 * ordinary branching is noise, and noise is how a real warning stops being read.
 * PHP has always said this; this runtime ran the same graph and said nothing
 * (fancy-flow#17). Pinned by `flow/run-diagnostics`.
 *
 * - `incoming` — the target's inbound edges, in graph order.
 * - `portValues` — keyed `"<nodeId>:<portId>"`, one key per port a node
 *   published, in publication order. Only the KEYS are read: which ports
 *   published, never what they carried.
 * - `completed` — the ids of nodes that ran to an output. A source that did not
 *   complete is never judged (row 0014).
 * - `nodesById` — every node of the graph, to resolve a source's ports and
 *   output fields.
 */
export function undeliveredEdgeWarnings(
  target: FlowNode,
  incoming: readonly FlowEdge[],
  portValues: ReadonlyMap<string, unknown>,
  completed: ReadonlySet<string>,
  nodesById: ReadonlyMap<string, FlowNode>,
): RunEvent[] {
  const events: RunEvent[] = [];

  for (const e of incoming) {
    const handle = e.sourceHandle ?? "out";
    if (portValues.has(`${e.source}:${handle}`) || !completed.has(e.source)) continue;
    if (possiblePortIds(nodesById.get(e.source)).includes(handle)) continue;

    events.push({
      type: "log",
      nodeId: target.id,
      level: "warn",
      message: undeliveredEdgeMessage(e, target, portValues, nodesById),
      detail: { edge: e.id, source: e.source, sourceHandle: handle },
    });
  }

  return events;
}

/**
 * Every port this node COULD publish — not the ones it did.
 *
 * The distinction that keeps the undelivered-edge warning honest. A `branch`
 * that took `true` publishes no `false`, and the edge leaving `false` binds
 * nothing: that is ORDINARY BRANCHING. A handle that is not a port of the node
 * at all can never bind on any run. "Did it publish?" cannot tell those apart —
 * both are absent — so this asks what is POSSIBLE.
 *
 * The rule is the PHP twin's `PortResolution::possible`, precedence and all,
 * because a warning one runtime raises and another does not is a parity failure:
 *
 *   1. the node's own declared `outputs`;
 *   2. the kind's CONFIG-DERIVED ports, when the config declares any;
 *   3. the kind's declared ports;
 *   4. `out`.
 *
 * It differs from `resolveNodePorts` in exactly one place, on purpose. A kind
 * whose ports come from config — `switch_case`, `llm_router` — and whose config
 * declares none yet answers with its DEFAULT-config shape (`case_a`, `case_b`,
 * `default`), which is what PHP's static declaration for that kind is.
 * `resolveNodePorts` answers with what that empty config yields (`default`
 * alone), which is right for the canvas and for `activatedPorts`, so it is left
 * alone: this only decides whether to warn, never what routes.
 */
function possiblePortIds(node: FlowNode | undefined): string[] {
  if (!node) return ["out"];

  const own = (node.data as { outputs?: unknown } | undefined)?.outputs;
  if (Array.isArray(own)) return own.map((p: { id: string }) => p.id);

  // An unregistered kind is not ambiguous: `activatedPorts` falls back to
  // exactly `out` for a kind it cannot resolve, so that is all it publishes.
  const kind = getNodeKind((node.data as any)?.kind ?? node.type ?? "");
  if (!kind) return ["out"];

  const config = nodeConfig(node);
  const representative = typeof kind.outputs === "function" && !configDeclaresPorts(kind.name, config);
  const resolved = resolvePortSpec(kind.outputs, representative ? defaultConfigFor(kind) : config);

  // THREE states, not two. `undefined` is "this kind declares nothing", which
  // falls back to `out` exactly as `activatedPorts` does. An empty ARRAY is a
  // kind declaring it has no output ports, and it is returned as such.
  //
  // This line read `ids.length > 0 ? ids : ["out"]` until 0.76.0, collapsing
  // both into `out` — the same empty-to-`out` collapse `activatedPorts` made,
  // in the other of the two gates that shape a port set. Fixing only the
  // activation side would have been half a fix, and the dangerous half: the
  // node would publish nothing while this lookup still reported `out` as
  // deliverable, so the undelivered-edge warning would stay SILENT for exactly
  // the edge that had just stopped delivering.
  if (resolved === undefined) return ["out"];

  return resolved.map((p) => p.id);
}

/**
 * Whether a config-driven kind's config declares any ports of its own — PHP's
 * `configDerived` returning non-empty. Matched on the BARE kind name, as there:
 * graphs carry both `switch_case` and `@particle-academy/switch_case`.
 */
function configDeclaresPorts(kindName: string, config: Record<string, unknown>): boolean {
  const bare = kindName.startsWith("@") ? kindName.slice(kindName.lastIndexOf("/") + 1) : kindName;

  if (bare === "switch_case") {
    // `cases` maps VALUE => PORT, so the ports are its values.
    const cases = config.cases;
    return !!cases && typeof cases === "object"
      && Object.values(cases).some((port) => typeof port === "string" && port !== "");
  }

  if (bare === "llm_router") {
    const routes = config.routes;
    return Array.isArray(routes)
      && routes.some((route) => (route as { port?: unknown } | null)?.port != null && (route as { port: unknown }).port !== "");
  }

  return true;
}

/**
 * The message for an edge whose source port publishes nothing.
 *
 * The PHP twin's wording, byte for byte, and each part earns its place:
 *
 *   1. THE EDGE ID FIRST — the thing the author, looking at a graph, can act on.
 *   2. THE CONSEQUENCE, IN RUNTIME TERMS. Without "nothing would reach X" this
 *      reads as a schema nit, and a handle string feels cosmetic.
 *   3. THE AVAILABLE PORTS — what the source ACTUALLY published on this run, in
 *      publication order, so a config-driven kind reports its real ports.
 *   4. THE REMEDY FOR THE COMMON CASE. Nearly every occurrence is an agent
 *      ADDING a handle that should not be there, so "leave sourceHandle off" —
 *      offered only when there is a handle to leave off.
 *
 * Plus the part only the engine can supply: when the handle names a FIELD of
 * the source kind's output shape, say so. That is the actual confusion — a field
 * name where a port belongs — and naming it turns a correction into an
 * explanation.
 */
function undeliveredEdgeMessage(
  edge: FlowEdge,
  target: FlowNode,
  portValues: ReadonlyMap<string, unknown>,
  nodesById: ReadonlyMap<string, FlowNode>,
): string {
  const handle = edge.sourceHandle ?? "out";

  const prefix = `${edge.source}:`;
  const available: string[] = [];
  for (const key of portValues.keys()) {
    if (key.startsWith(prefix)) available.push(key.slice(prefix.length));
  }

  let message =
    `Edge ${edge.id} reads port "${handle}" from node ${edge.source}, which never publishes it — ` +
    `nothing would reach ${target.id} at run time.`;

  if (available.length > 0) message += ` Available: ${available.join(", ")}.`;

  // The near-miss: a FIELD of that name, where a PORT was expected.
  const source = nodesById.get(edge.source);
  if (source && outputFieldsFor(source).some((field) => field?.path === handle)) {
    message +=
      ` Note: "${handle}" is a FIELD this node emits, not a port — read it downstream as ` +
      `{{ in.${handle} }} rather than naming it as a source handle.`;
  }

  if (edge.sourceHandle != null) message += " Leave sourceHandle off to read the node's output.";

  return message;
}

import type { WorkflowInput } from "../types";

/**
 * Resolving what a caller passed against what a workflow declared.
 *
 * Kept in its own module, and deliberately a pure function over two plain
 * objects, because the PHP and Python runtimes implement the same rules and
 * `suites/flow/workflow-props` in `@particle-academy/fancy-conformance` is the
 * table all three run. A rule that lives inside a runner is a rule each runtime
 * re-derives; a rule that is a function over maps is one they can share a
 * fixture for.
 *
 * ## Every branch here exists to make a mistake LOUD
 *
 * The failure this replaces was silence. `initialInputs` was keyed by node id,
 * so a caller passed `{ t: { topic: "otters" } }` and had to know the trigger
 * was named `t`; and nothing declared what a workflow accepted, so a
 * misspelled key was not an error — the value sat unread, the node saw
 * nothing, and the run reported success with output that was quietly wrong.
 *
 * So: an unknown key fails, a missing required value fails, and a wrong type
 * fails. None of those is a warning. A warning on a queue worker is a line in a
 * log nobody opens.
 */

/**
 * Why a resolution failed, in a vocabulary that is the same in every runtime.
 *
 * The MESSAGE is English prose and each runtime words it slightly differently,
 * which is fine for a human and useless for a shared fixture table. The CODE is
 * what `suites/flow/workflow-props` asserts, so parity is pinned on the
 * decision rather than on the phrasing — otherwise the three implementations
 * would be held to a translation instead of a behaviour.
 */
export type PropsErrorCode = "unknown_input" | "missing_required" | "type_mismatch";

/** The outcome of checking a caller's props against a declaration. */
export type PropsResolution =
  | { ok: true; props: Record<string, unknown> }
  | { ok: false; code: PropsErrorCode; error: string };

/**
 * The runtime type of a value, in the vocabulary a declaration uses.
 *
 * Arrays are checked before objects because `typeof []` is `"object"` and a
 * declaration that says `array` means a list — accepting `{}` there would be
 * the check passing while meaning nothing.
 */
function typeOf(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

/**
 * Check and fill a caller's props.
 *
 * Returns the resolved map — declared defaults filled in, nothing else added —
 * or the first error. One error rather than a list, because a run stops at the
 * first one anyway and a caller fixing a call wants the thing to fix, not a
 * report.
 */
export function resolveWorkflowProps(
  declared: WorkflowInput[] | undefined,
  passed: Record<string, unknown> | undefined,
): PropsResolution {
  const inputs = declared ?? [];
  const given = passed ?? {};
  const byName = new Map(inputs.map((input) => [input.name, input]));

  // UNKNOWN KEYS FIRST, and this is the check the whole feature is for.
  //
  // A caller who misspells `topic` as `topik` has configured nothing, and
  // before this the run went ahead and looked fine. Checking it before
  // anything else means the error names what they typed rather than
  // complaining that the thing they thought they passed is missing.
  for (const name of Object.keys(given)) {
    if (!byName.has(name)) {
      const known = inputs.map((input) => input.name);
      const suffix = known.length === 0
        ? "this workflow declares no inputs"
        : `known inputs: ${known.join(", ")}`;

      return {
        ok: false,
        code: "unknown_input",
        error: `Unknown workflow input "${name}" — ${suffix}.`,
      };
    }
  }

  const resolved: Record<string, unknown> = {};

  for (const input of inputs) {
    // `hasOwnProperty`, not a truthiness or `??` check. `0`, `false` and `""`
    // are real values a caller meant to pass, and a default applied over them
    // is a silent override — a limit of 0 quietly becoming 10 is not an error
    // anybody sees.
    const supplied = Object.prototype.hasOwnProperty.call(given, input.name);
    const hasDefault = Object.prototype.hasOwnProperty.call(input, "default");

    if (!supplied) {
      if (hasDefault) {
        resolved[input.name] = input.default;
        continue;
      }

      if (input.required) {
        return {
          ok: false,
          code: "missing_required",
          error: `Missing required workflow input "${input.name}"${
            input.type ? ` (${input.type})` : ""
          }.`,
        };
      }

      // Not supplied, no default, not required — absent rather than
      // `undefined`, so `{{ $props.x }}` resolves to null on both runtimes
      // instead of one of them inventing a key.
      continue;
    }

    const value = given[input.name];

    // An undeclared type accepts anything. "I am not asserting a shape" must
    // not degrade into "nothing is allowed".
    if (input.type !== undefined) {
      const actual = typeOf(value);
      if (actual !== input.type) {
        return {
          ok: false,
          code: "type_mismatch",
          error: `Workflow input "${input.name}" expects ${input.type}, got ${actual}.`,
        };
      }
    }

    resolved[input.name] = value;
  }

  return { ok: true, props: resolved };
}

/**
 * `{{ }}` resolution — the TypeScript twin of `FancyFlow\Nodes\Support\Expr`.
 *
 * ## Why this is opt-in and not wired into `runFlow`
 *
 * The PHP runtime resolves expressions inside its batteries-included executors.
 * The JS runtime never has: `runFlow` hands `node.data.config` to your executor
 * verbatim, so every host that uses `{{ }}` today already resolves it itself.
 * Turning resolution on inside `runFlow` would interpolate a second time over
 * values those hosts had already substituted — silently, and only for graphs
 * that happen to contain `{{` in their DATA.
 *
 * So this exports the semantics and changes no behaviour. Call it yourself:
 *
 * ```ts
 * const url = evaluateExpression(node.data.config.url, inputs);
 * ```
 *
 * ## The semantics are the PHP file's, deliberately
 *
 * This is not a general expression language and must not grow into one. It
 * resolves a dot-path against a context and nothing else — no arithmetic, no
 * comparisons, no calls. Hosts that want real expressions override the executor
 * (the PHP docblock points at symfony/expression-language for the same reason).
 *
 * Divergence here is a correctness bug rather than a style difference: the same
 * graph is authored once and may run on either runtime. `suites/shared/expr`
 * in `@particle-academy/fancy-conformance` is the fixture table both sides run,
 * so parity is a test result instead of a claim.
 */

/** Anything a context or a resolved value can be. */
export type ExprValue = unknown;

/** The context an expression resolves against — the executor's `inputs`. */
export type ExprContext = Record<string, ExprValue>;

/**
 * `{{ … }}` is parsed by SCANNING, not by a regular expression.
 *
 * Two CodeQL `js/polynomial-redos` alerts (#2, #3) came out of the regex
 * version, and the second survived the obvious fix — which is the useful part.
 * Dropping the ambiguous `\s*` around the capture killed one witness
 * (`'{{{{' + ' '.repeat(n)`) and CodeQL immediately produced another
 * (`'{{{{a'` repeated). That is not a pattern bug: a GLOBAL lazy scan for a
 * delimiter that never arrives is quadratic by construction — O(n) starts, each
 * scanning O(n) forward — and no amount of tuning the pattern removes it.
 *
 * `indexOf` has no backtracking at all. Each character is visited a bounded
 * number of times, so this is linear by construction rather than by careful
 * pattern-writing, and there is no next witness to find.
 *
 * The behaviour matches the PHP twin's regexes, and `shared/expr` is what holds
 * the two together.
 */

/**
 * The inner text of a template that is EXACTLY one expression, else `null`.
 *
 * Starting with `{{` and ending with `}}` is not enough: the inner text may
 * contain neither `}}` nor `{{`. Without that check `{{ in.text }} --- {{
 * user.transcript }}` was ONE path, `in.text }} --- {{ user.transcript`, that
 * resolves to nothing, so the template returned null (fancy-flow-php#16). That
 * corner came from PHP's end-anchored pattern, whose lazy capture grew to reach
 * the end; it was documented here as deliberate and mirrored in every runtime,
 * so no parity table could see it. A template with several references now
 * interpolates each, and `{{a}}{{b}}` is two references.
 */
function wholeExpression(trimmed: string): string | null {
  if (trimmed.length < 4) return null;
  if (!trimmed.startsWith("{{") || !trimmed.endsWith("}}")) return null;
  const inner = trimmed.slice(2, -2);
  if (inner.includes("}}") || inner.includes("{{")) return null;
  return inner;
}

/**
 * Replace every `{{ … }}` run, left to right, in a single pass.
 *
 * An unterminated `{{` is literal text — the same thing the regex did by simply
 * not matching, and the case an author hits constantly while typing.
 */
function interpolate(template: string, resolve: (path: string) => string): string {
  let out = "";
  let i = 0;

  for (;;) {
    const open = template.indexOf("{{", i);
    if (open === -1) return out + template.slice(i);

    const close = template.indexOf("}}", open + 2);
    if (close === -1) return out + template.slice(i);

    out += template.slice(i, open) + resolve(template.slice(open + 2, close));
    i = close + 2;
  }
}

/**
 * Strings PHP's `Expr::truthy` treats as false.
 *
 * `"0"` and `"false"` are the ones that matter: a branch condition arriving as
 * text from a form or a JSON body would otherwise be truthy for every non-empty
 * string, and `"false"` taking the true branch is the kind of bug that looks
 * like the engine is broken.
 */
const FALSY_STRINGS = new Set(["", "0", "false", "no", "off", "null"]);

/**
 * What a resolution attempt ANSWERS — did the path resolve, and to what.
 *
 * `resolvePath` cannot express this, and that is the defect it exists to fix:
 * it returns `null` both for "this path does not exist" and for "this path
 * exists and holds null". One value standing for two states.
 *
 * At the interpolation layer the collapse is worse, because `null` stringifies
 * to `""`. A consumer put it exactly:
 *
 * > "An unresolvable path yields `''`, so a wrong field is indistinguishable
 * > from an empty one at runtime."
 *
 * A misspelled field renders as an empty string, which looks precisely like a
 * field that is legitimately empty. The graph runs, the node succeeds, and the
 * output is quietly missing a value nobody is told about — worst on
 * LLM-authored graphs, where the field name was guessed in the first place.
 *
 * Same shape as the four `??` collapses fixed across all four runtimes on
 * 2026-08-26 (absent vs null), one layer up: **presence is the only correct
 * test, and a return value that cannot express presence cannot be tested for
 * it.** Hence a second return channel rather than a cleverer sentinel — every
 * sentinel is a legal value for somebody.
 */
export interface Resolution {
  /** Whether the path resolved at all. `false` means it does not exist. */
  resolved: boolean;
  /** The value, when `resolved`. `null` when not — do not read it blind. */
  value: ExprValue;
}

/** Thrown by the `"throw"` policy when a path does not resolve. */
export class UnresolvedPathError extends Error {
  constructor(readonly path: string) {
    super(
      `Expression path "${path}" did not resolve. ` +
        `Under the "throw" policy an unresolvable path is an error rather than an empty string.`,
    );
    this.name = "UnresolvedPathError";
  }
}

/**
 * What evaluation does with a path that does not resolve.
 *
 * - `"empty"` — today's behaviour, and the DEFAULT. Interpolates to `""`; a
 *   whole expression yields `null`. Unchanged so that widening this API breaks
 *   nobody: 40 call sites across the runtimes assume it.
 * - `"keep"` — leave the `{{ … }}` text in place. The failure becomes VISIBLE
 *   in the output without stopping the run, which is what you want for
 *   human-reviewed content: a rendered `{{ in.recipient_naem }}` is self-
 *   diagnosing in a way an absence never is.
 * - `"throw"` — refuse. For hosts that would rather fail a run than deliver a
 *   silently incomplete result.
 *
 * Opt-in before default at the request of the consumer who reported it — the
 * host with the most LLM-authored graphs, and so both the biggest beneficiary
 * and the right place for it to break first if it is going to.
 */
export type UnresolvedPolicy = "empty" | "keep" | "throw";

/** Options for {@link evaluateExpression} / {@link evaluateConfig}. */
export interface EvaluateOptions {
  /** What to do with a path that does not resolve. Default `"empty"`. */
  onUnresolved?: UnresolvedPolicy;
}

/**
 * Resolve a dot-path, reporting WHETHER it resolved.
 *
 * The same walk as `resolvePath` — deliberately, so the two can never disagree
 * about what resolves; `resolvePath` is defined in terms of this one below.
 *
 * A note on JS having two absent values: a key present with the value
 * `undefined` reports `resolved: false`, matching `resolvePath`'s long-standing
 * behaviour. It cannot arise from graph data (JSON has no `undefined`), and
 * changing it would make the two functions disagree for no reachable gain.
 */
export function tryResolvePath(path: string, context: ExprContext): Resolution {
  const unresolved: Resolution = { resolved: false, value: null };

  const trimmed = path.trim();
  if (trimmed === "") return unresolved;

  const segments = trimmed.split(".");
  let cursor: ExprValue;

  const head = segments[0];
  if (head === "$json" || head === "$input") {
    cursor = context !== null && typeof context === "object" && "in" in context ? context.in : context;
    segments.shift();
  } else {
    cursor = context;
  }

  for (const segment of segments) {
    if (cursor === null || cursor === undefined) return unresolved;
    if (typeof cursor !== "object") return unresolved;
    // Arrays are indexed by their numeric keys, matching PHP's list access.
    const next = (cursor as Record<string, ExprValue>)[segment];
    if (next === undefined) return unresolved;
    cursor = next;
  }

  return { resolved: true, value: cursor === undefined ? null : cursor };
}

/**
 * Resolve a dot-path against the context, honouring the `$json` / `$input`
 * alias.
 *
 * Both aliases point at the `in` port value when the context has one, and at
 * the whole context otherwise — the same fallback the PHP does, which is what
 * makes `{{ $json.x }}` work on a trigger node that has no upstream input.
 *
 * A path that does not resolve returns `null`, never `undefined`: PHP has one
 * absent value and JS has two, and letting the difference leak would make the
 * two runtimes disagree about `{{ missing }}` for no useful reason.
 */
export function resolvePath(path: string, context: ExprContext): ExprValue {
  // Defined in terms of `tryResolvePath` rather than repeating the walk. Two
  // copies of a traversal agree right up until someone edits one of them, and
  // nothing anywhere reports that -- the same reason the shared conformance
  // tables exist instead of hand-copied fixture rows.
  return tryResolvePath(path, context).value;
}

/**
 * Evaluate a template against a context.
 *
 * A string that is EXACTLY one expression returns the resolved value with its
 * type intact — `{{ $json.count }}` gives you a number, not `"3"`. Anything
 * else interpolates each run as text. That distinction is load-bearing: it is
 * what lets a config field carry either a value or a sentence.
 *
 * Non-string templates pass through untouched, so this is safe to map over a
 * whole config object.
 */
export function evaluateExpression(
  template: ExprValue,
  context: ExprContext,
  options: EvaluateOptions = {},
): ExprValue {
  if (typeof template !== "string") return template;

  const policy = options.onUnresolved ?? "empty";

  const whole = wholeExpression(template.trim());
  if (whole !== null) {
    const r = tryResolvePath(whole, context);
    if (r.resolved) return r.value;

    // The whole-expression branch returns `null` under `"empty"`, not `""` --
    // that is what it has always done, and the asymmetry is deliberate: this
    // branch preserves TYPE, so its absent value is the typed one.
    if (policy === "throw") throw new UnresolvedPathError(whole);
    return policy === "keep" ? template : null;
  }

  return interpolate(template, (path) => {
    const r = tryResolvePath(path, context);
    if (r.resolved) return stringify(r.value);
    if (policy === "throw") throw new UnresolvedPathError(path);
    return policy === "keep" ? `{{${path}}}` : "";
  });
}

/**
 * Truthiness for branch / switch decisions.
 *
 * Mirrors PHP's rules rather than JavaScript's, because the graph is authored
 * once and may run on either side. The two disagree in exactly the places a
 * workflow hits: `"0"` and `"false"` are truthy in JS and falsy here, and an
 * empty array is truthy in JS and falsy here.
 */
export function truthy(value: ExprValue): boolean {
  if (typeof value === "boolean") return value;
  if (value === null || value === undefined) return false;
  if (typeof value === "string") return !FALSY_STRINGS.has(value.trim().toLowerCase());
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === "number") return value !== 0;
  return Boolean(value);
}

/** Coerce a value to text the way interpolation does. */
export function text(value: ExprValue): string {
  return stringify(value);
}

function stringify(value: ExprValue): string {
  if (typeof value === "string") return value;
  if (typeof value === "boolean") return value ? "true" : "false";
  if (value === null || value === undefined) return "";
  if (typeof value === "number" || typeof value === "bigint") return String(value);
  try {
    return JSON.stringify(value) ?? "";
  } catch {
    return "";
  }
}

/**
 * Resolve every string in a config object, one level of nesting at a time.
 *
 * The convenience most hosts actually want, and the shape their hand-rolled
 * version usually takes. Opt-in like the rest of this module.
 */
export function evaluateConfig<T extends Record<string, ExprValue>>(
  config: T,
  context: ExprContext,
  options: EvaluateOptions = {},
): T {
  const out: Record<string, ExprValue> = {};
  for (const [key, value] of Object.entries(config)) {
    out[key] = Array.isArray(value)
      ? value.map((v) => evaluateExpression(v, context, options))
      : value !== null && typeof value === "object"
        ? evaluateConfig(value as Record<string, ExprValue>, context, options)
        : evaluateExpression(value, context, options);
  }
  return out as T;
}

import dagre from "@dagrejs/dagre";
import type { FlowGraph, FlowNode } from "../types";

export type AutoLayoutDirection = "LR" | "TB" | "RL" | "BT";

export type AutoLayoutOptions = {
  /** Rank direction. Default "LR" (left→right). */
  direction?: AutoLayoutDirection;
  /** Separation between nodes in the same rank. Default 48. */
  nodeSep?: number;
  /** Separation between ranks. Default 96. */
  rankSep?: number;
  /**
   * Lay out only the children of this node (relative coords) — the lane-scoped
   * "tidy this lane". Omit to lay out the top-level (parentless) graph.
   */
  scope?: string;
  defaultWidth?: number;
  defaultHeight?: number;
};

/**
 * Auto-arrange a graph into a tidy DAG layout with dagre. Returns the nodes with
 * new positions (edges untouched). `scope` restricts the layout to one parent's
 * children — powering a lane-scoped tidy. dagre is bundled, so consumers who
 * never call this still pay nothing to install it, and it works headlessly.
 *
 * React-free: reachable from anywhere, testable without a DOM.
 */
export function autoLayout(graph: FlowGraph, options: AutoLayoutOptions = {}): FlowNode[] {
  const dir = options.direction ?? "LR";
  const nodesep = options.nodeSep ?? 48;
  const ranksep = options.rankSep ?? 96;
  const dw = options.defaultWidth ?? 180;
  const dh = options.defaultHeight ?? 64;

  const inScope = (n: FlowNode) => (options.scope ? (n as any).parentId === options.scope : !(n as any).parentId);
  const targets = graph.nodes.filter(inScope);
  if (targets.length === 0) return graph.nodes;
  const ids = new Set(targets.map((n) => n.id));

  const g = new dagre.graphlib.Graph();
  g.setGraph({ rankdir: dir, nodesep, ranksep });
  g.setDefaultEdgeLabel(() => ({}));
  for (const n of targets) {
    g.setNode(n.id, { width: (n as any).width ?? dw, height: (n as any).height ?? dh });
  }
  for (const e of graph.edges) {
    if (ids.has(e.source) && ids.has(e.target)) g.setEdge(e.source, e.target);
  }
  dagre.layout(g);

  const pos = new Map<string, { x: number; y: number }>();
  for (const n of targets) {
    const d = g.node(n.id);
    // dagre positions are node centers; xyflow wants the top-left corner.
    if (d) pos.set(n.id, { x: d.x - d.width / 2, y: d.y - d.height / 2 });
  }
  return graph.nodes.map((n) => {
    const p = pos.get(n.id);
    return p ? { ...n, position: p } : n;
  });
}

import type { FlowEdge, FlowGraph, FlowNode, PortDescriptor, WorkflowInput } from "../types";
import { checkGraphConnectivity } from "../analysis/graph-connectivity";
import { defaultConfigFor, getNodeKind, validateConfig } from "../registry/registry";
import { resolveNodePorts } from "../registry/ports";

/** Schema version. Bump on breaking shape changes; add migrations as needed. */
export const WORKFLOW_SCHEMA_VERSION = 1 as const;
export const WORKFLOW_SCHEMA_URL = "https://particle.academy/schemas/workflow/v1.json";

export type WorkflowSchema = {
  $schema: typeof WORKFLOW_SCHEMA_URL;
  version: typeof WORKFLOW_SCHEMA_VERSION;
  metadata?: WorkflowMetadata;
  /**
   * What this workflow accepts at run start, passed BY NAME.
   *
   * Lives beside `graph` rather than inside it because it describes the
   * workflow's CONTRACT, not its topology: a caller reads this to know what to
   * pass, and reading it should not mean walking nodes looking for a trigger.
   *
   * Omitted entirely when a workflow takes none, so every existing saved
   * document is unchanged byte for byte.
   */
  inputs?: WorkflowInput[];
  graph: {
    nodes: WorkflowSchemaNode[];
    edges: WorkflowSchemaEdge[];
  };
  view?: {
    viewport?: { x: number; y: number; zoom: number };
  };
};

export type WorkflowMetadata = {
  id?: string;
  name?: string;
  description?: string;
  createdAt?: number;
  updatedAt?: number;
  author?: string;
  tags?: string[];
};

export type WorkflowSchemaNode = {
  id: string;
  /** Registry kind name (e.g. "memory_store"). */
  kind: string;
  position: { x: number; y: number };
  label?: string;
  description?: string;
  /**
   * Announced to a person just before / just after this node runs. Omitted
   * entirely when unset, so a graph of ordinary plumbing nodes does not carry
   * a pair of empty keys per node and every diff of a saved graph stays
   * readable.
   */
  startingMsg?: string;
  stoppingMsg?: string;
  config?: Record<string, unknown>;
  /**
   * Resolved ports, written on export.
   *
   * A kind may derive its ports from config (`switch_case` cases,
   * `llm_branch` routes), and that derivation is a JavaScript function — a
   * runtime in another language cannot execute it. Without the resolved ports
   * in the document, the PHP twin sees no declared outputs and falls back to a
   * single `out`, so every branch edge in an exported flow silently stops
   * firing. Serializing them keeps the schema self-describing and preserves
   * the cross-runtime guarantee: same JSON in, same routing out.
   *
   * Optional and additive — a hand-written schema may omit them, and each
   * runtime then falls back to its own kind registry.
   */
  inputs?: PortDescriptor[];
  outputs?: PortDescriptor[];
  /**
   * Node grouping and visual layout — additive + optional. `parentId`/`extent`
   * say which container a node sits in (swimlanes); `width`/`height` carry an
   * explicit (resized) size; `style` carries inline presentation.
   *
   * **`parentId` is NOT decoration, and a runtime that drops it is wrong.** It
   * decides which terminal a node talks to — a terminal lane owns one session
   * and membership is this field, deliberately, so there is no second copy of
   * the grouping in each node's config to drift from what the canvas shows.
   *
   * This comment used to say these fields exist "purely for the canvas", so a
   * runtime that only walks edges and ports could ignore all of them. The
   * Python twin read that literally and carried none of them: a graph loaded
   * there and saved back lost every grouping a person had drawn, silently. The
   * sentence was true when it was written and became false without being
   * revisited, which is the more common way a comment does harm.
   *
   * An older reader that does not know these fields still drops them — that is
   * forward-compatibility, not permission.
   */
  parentId?: string;
  extent?: "parent" | [[number, number], [number, number]];
  width?: number;
  height?: number;
  style?: Record<string, unknown>;
};

export type WorkflowSchemaEdge = {
  id: string;
  source: string;
  target: string;
  sourceHandle?: string;
  targetHandle?: string;
  label?: string;
};

export type ImportIssue = {
  level: "error" | "warning";
  nodeId?: string;
  edgeId?: string;
  message: string;
};

export type ImportResult = {
  graph: FlowGraph;
  issues: ImportIssue[];
  /** True when the import produced a usable graph (errors may have been
   *  rewritten to warnings via `lenient: true`, except an unsupported schema
   *  version, which is always an error). */
  ok: boolean;
};

/** Snapshot the in-memory graph as a portable WorkflowSchema. */
export function exportWorkflow(
  graph: FlowGraph,
  metadata?: WorkflowMetadata,
  view?: WorkflowSchema["view"],
): WorkflowSchema {
  return {
    $schema: WORKFLOW_SCHEMA_URL,
    version: WORKFLOW_SCHEMA_VERSION,
    metadata: metadata ? { ...metadata, updatedAt: Date.now() } : undefined,
    // Round-trips, or a saved workflow silently forgets its own contract and
    // every caller's props become "unknown input" on the next load.
    ...(graph.inputs && graph.inputs.length > 0 ? { inputs: graph.inputs } : {}),
    graph: {
      nodes: graph.nodes.map(toSchemaNode),
      edges: graph.edges.map(toSchemaEdge),
    },
    view,
  };
}

function toSchemaNode(n: FlowNode): WorkflowSchemaNode {
  const data: any = n.data ?? {};
  const kindName = data.kind ?? n.type ?? "custom";
  // Resolve through the same helper the canvas and runtime use, so a
  // config-driven kind writes its ACTUAL ports into the document instead of
  // leaving another language's runtime to guess at them.
  const ports = resolveNodePorts(n, getNodeKind(kindName) ?? undefined);
  const node = n as any;
  return {
    id: n.id,
    kind: kindName,
    position: { x: n.position.x, y: n.position.y },
    label: data.label,
    description: data.description,
    ...(typeof data.startingMsg === "string" && data.startingMsg !== "" ? { startingMsg: data.startingMsg } : {}),
    ...(typeof data.stoppingMsg === "string" && data.stoppingMsg !== "" ? { stoppingMsg: data.stoppingMsg } : {}),
    config: data.config,
    inputs: ports.inputs,
    outputs: ports.outputs,
    // Visual layout — only when explicitly set (never persist auto-`measured`
    // dimensions, which are derived, not authored).
    ...(node.parentId ? { parentId: node.parentId } : {}),
    ...(node.extent ? { extent: node.extent } : {}),
    ...(typeof node.width === "number" ? { width: node.width } : {}),
    ...(typeof node.height === "number" ? { height: node.height } : {}),
    ...(node.style ? { style: node.style } : {}),
  };
}

function toSchemaEdge(e: FlowEdge): WorkflowSchemaEdge {
  return {
    id: e.id,
    source: e.source,
    target: e.target,
    sourceHandle: e.sourceHandle ?? undefined,
    targetHandle: e.targetHandle ?? undefined,
    label: typeof e.label === "string" ? e.label : undefined,
  };
}

export type ImportOptions = {
  /** When true, unknown kinds become warnings + a "custom" placeholder
   *  instead of errors. Default false. It never softens the schema version:
   *  a document that is not `version: 1` (after migration) is refused either
   *  way, because no runtime can honour a format it does not know. */
  lenient?: boolean;
};

/** A migration step: takes a version-N document to version N+1. */
export type MigrationStep = (schema: Record<string, unknown>) => Record<string, unknown>;

/**
 * Every migration step, keyed by the version it upgrades FROM.
 *
 * Empty today because v1 is current — when a BREAKING bump lands, add the step
 * here and every stored document upgrades on read, in this runtime and its
 * PHP and Python twins.
 */
export const MIGRATIONS: Record<number, MigrationStep> = {};

/**
 * Migrate a raw schema object up to the current version, as far as it can go.
 *
 * Additive changes need no migration — an older document simply lacks the newer
 * optional fields. This is the seam for a future BREAKING bump, and
 * `importWorkflow` runs it before validating the version.
 *
 * ## The three rules, each with a reason
 *
 *  - **A PAST version migrates forward**, step by step, to the current one.
 *  - **A FUTURE version is left ALONE.** We cannot know what a later schema
 *    means, and migrating downward would be guessing. Untouched hands it to the
 *    version check, which reports it honestly.
 *  - **A GAP in the table is left alone too.** A missing step is not a licence
 *    to guess.
 *
 * ## Why `steps` is a parameter
 *
 * With only v1 in existence there is no old document to migrate, so a seam
 * tested against the built-in (empty) table is a check that CANNOT fail — it
 * would pass identically against a function that returned its input untouched,
 * which is what this was until the twins needed the same seam.
 *
 * The PHP and Python runtimes carry the identical shape. That mattered more
 * than it sounds: they had no migration at all and errored on any version
 * mismatch, so a v2 bump would have made every stored Op unreadable on exactly
 * the runtimes where durable runs resume.
 */
export function migrateSchema(
  schema: unknown,
  steps: Record<number, MigrationStep> = MIGRATIONS,
): unknown {
  if (!schema || typeof schema !== "object") return schema;

  const doc = schema as Record<string, unknown>;
  let version = doc.version;

  if (typeof version !== "number" || !Number.isInteger(version) || version >= WORKFLOW_SCHEMA_VERSION) {
    return schema;
  }

  let out = doc;
  while (version < WORKFLOW_SCHEMA_VERSION) {
    const step = steps[version];
    if (!step) return out;

    out = step(out);
    version += 1;
    out.version = version;
  }

  return out;
}

/**
 * Hydrate a schema into runtime FlowGraph + validate kinds/configs against
 * the registry. Reports issues for unknown kinds, missing required config,
 * and dangling edges.
 */
export function importWorkflow(schema: unknown, options: ImportOptions = {}): ImportResult {
  const issues: ImportIssue[] = [];
  const lenient = options.lenient === true;
  schema = migrateSchema(schema);

  if (!schema || typeof schema !== "object") {
    return { ok: false, graph: { nodes: [], edges: [] }, issues: [{ level: "error", message: "Schema is not an object." }] };
  }
  const s = schema as Partial<WorkflowSchema>;
  // NEVER softened by `lenient`. That flag is about unknown VOCABULARY (a kind
  // this host has not registered); a version is the format itself, and a
  // runtime cannot honour a format it does not know. It used to become a
  // warning, and fancy-flow-php imports leniently on every run(), so one
  // versionless document ran in Laravel and was refused by a default (strict)
  // import here. Past versions were migrated above, so anything still unequal
  // is refused.
  if (s.version !== WORKFLOW_SCHEMA_VERSION) {
    issues.push({
      level: "error",
      message: `Unsupported workflow schema version: ${s.version} (expected ${WORKFLOW_SCHEMA_VERSION})`,
    });
    return { ok: false, graph: { nodes: [], edges: [] }, issues };
  }

  const rawNodes = s.graph?.nodes ?? [];
  const rawEdges = s.graph?.edges ?? [];

  const nodes: FlowNode[] = rawNodes.map((n) => {
    const kind = getNodeKind(n.kind);
    if (!kind) {
      issues.push({
        level: lenient ? "warning" : "error",
        nodeId: n.id,
        message: `Unknown kind "${n.kind}" — register it before importing.`,
      });
    }
    const config = n.config ?? (kind ? defaultConfigFor(kind) : {});
    if (kind) {
      for (const iss of validateConfig(kind, config)) {
        issues.push({ level: "warning", nodeId: n.id, message: `${iss.key}: ${iss.message}` });
      }
    }
    // Canonicalise on the way in: a document may carry a pre-namespace id, and
    // rewriting it here means the graph converges on the canonical id the next
    // time it is saved, rather than carrying the ambiguous name forever.
    const kindId = kind?.name ?? n.kind;
    return {
      id: n.id,
      type: kindId,
      position: { x: n.position?.x ?? 0, y: n.position?.y ?? 0 },
      // Rehydrate visual layout onto the node's top level (where xyflow reads it).
      ...(n.parentId ? { parentId: n.parentId } : {}),
      ...(n.extent ? { extent: n.extent } : {}),
      ...(typeof n.width === "number" ? { width: n.width } : {}),
      ...(typeof n.height === "number" ? { height: n.height } : {}),
      ...(n.style ? { style: n.style } : {}),
      data: {
        kind: kindId,
        label: n.label ?? kind?.label ?? n.kind,
        description: n.description,
        ...(n.startingMsg ? { startingMsg: n.startingMsg } : {}),
        ...(n.stoppingMsg ? { stoppingMsg: n.stoppingMsg } : {}),
        config,
        // Carry serialized ports back onto the node so a round-trip is stable
        // and an unknown kind still routes the way the document described.
        ...(n.inputs ? { inputs: n.inputs } : {}),
        ...(n.outputs ? { outputs: n.outputs } : {}),
      } as any,
    };
  });

  const nodeIds = new Set(nodes.map((n) => n.id));
  const edges: FlowEdge[] = rawEdges
    .map((e) => {
      if (!nodeIds.has(e.source)) {
        issues.push({ level: "warning", edgeId: e.id, message: `Edge source "${e.source}" not found.` });
        return null;
      }
      if (!nodeIds.has(e.target)) {
        issues.push({ level: "warning", edgeId: e.id, message: `Edge target "${e.target}" not found.` });
        return null;
      }
      return {
        id: e.id,
        source: e.source,
        target: e.target,
        sourceHandle: e.sourceHandle,
        targetHandle: e.targetHandle,
        label: e.label,
      } as FlowEdge;
    })
    .filter((e): e is FlowEdge => e !== null);

  // WIRING, not merely dataflow: a node no edge reaches and that reaches no
  // edge, and an edge reading from a node that publishes nothing.
  //
  // Deliberately AFTER the edge loop, so it sees the same edges the engine will
  // -- a dangling edge is dropped with a warning above, and running this first
  // would let a dropped edge count as a connection.
  //
  // Deliberately NOT gated on `lenient`. That flag is about unknown VOCABULARY
  // (a kind this host has not registered), never about wiring.
  issues.push(...checkGraphConnectivity({ nodes, edges }));

  const ok = issues.every((i) => i.level !== "error");
  // The declaration comes back with the graph. Dropping it on import would be
  // the worse half of losing it on export: the document still says what it
  // accepts, the loaded graph does not, and every prop a caller passes becomes
  // "unknown input" — an error pointing at the caller for a bug in the loader.
  const declaredInputs = Array.isArray(s.inputs)
    ? (s.inputs as WorkflowInput[]).filter(
        (input): input is WorkflowInput =>
          input !== null && typeof input === "object" && typeof (input as WorkflowInput).name === "string",
      )
    : undefined;

  return {
    ok,
    graph: {
      nodes,
      edges,
      ...(declaredInputs && declaredInputs.length > 0 ? { inputs: declaredInputs } : {}),
    },
    issues,
  };
}

/** Convenience: serialize a schema as a downloadable JSON Blob. */
export function workflowToBlob(schema: WorkflowSchema): Blob {
  return new Blob([JSON.stringify(schema, null, 2)], { type: "application/json" });
}

import { getNodeKind, kindIds } from "../registry/registry";
import type { FlowGraph, FlowNode } from "../types";
import type { ImportIssue } from "../schema/workflow-schema";

/**
 * Refuse a graph whose nodes cannot take part in the workflow's dataflow.
 *
 * Two shapes, both of which import cleanly and then quietly do nothing. Neither
 * FAILS — which is what makes them worth refusing at authoring time, because a
 * run that reports success is the worst way for a workflow to be wrong. Both
 * were measured against the PHP twin's engine before this was written, and both
 * behave the same way here:
 *
 * ## 1. A FLOATING node — no inbound and no outbound edge
 *
 * It is NOT skipped. A node with no incoming edge is a root, so the topo sort
 * runs it: a three-node graph with one floating `log` executed `t,lonely,o`. It
 * runs disconnected — receiving nothing from the graph and reaching nobody in
 * it — which is precisely the state an author cannot see on a canvas.
 *
 * ## 2. An edge leaving a TERMINATOR
 *
 * A terminal kind — `output`, `log` — declares an EMPTY output port list. It
 * ends a chain. Measured: `t -> output -> log` imported clean and the `log` DID
 * run, with `{{ input }}` resolving to `""`. `collectInputs` binds a payload
 * only when `"<sourceId>:<handle>"` exists, and a node publishing no ports never
 * creates that key — so the edge does not fail, it delivers nothing, and the
 * node downstream operates on a hole.
 *
 * That is the same silent-nothing the undelivered-edge diagnostic reports at run
 * time, but this one is decidable FROM THE DOCUMENT ALONE.
 *
 * ## What may float
 *
 * See {@link mayFloat}. Not only `note`: any `annotation` or `layout` kind (a
 * swimlane is never wired to anything — that is what a lane IS), and any kind
 * the registry does not know.
 */
export function checkGraphConnectivity(graph: FlowGraph): ImportIssue[] {
  const { nodes, edges } = graph;
  const issues: ImportIssue[] = [];

  const hasIncoming = new Set<string>();
  const hasOutgoing = new Set<string>();
  for (const edge of edges) {
    hasIncoming.add(edge.target);
    hasOutgoing.add(edge.source);
  }

  // A single-node graph is not "floating" — it is a graph with one step, which
  // is a legitimate (if small) workflow and what every graph looks like on the
  // way to a bigger one. Refusing it would make the editor unusable from the
  // first node placed.
  const single = nodes.length === 1;

  for (const node of nodes) {
    if (single || mayFloat(node)) continue;

    if (!hasIncoming.has(node.id) && !hasOutgoing.has(node.id)) {
      issues.push({
        level: "error",
        nodeId: node.id,
        message:
          `Node "${node.id}" is connected to nothing — no inbound edge and no outbound edge. ` +
          `It still RUNS (a node with no inbound edge is a root), but it receives nothing from ` +
          `the graph and reaches nobody in it, so it is either unwired or left behind by a ` +
          `deletion. Only a note, an annotation or a lane may float.`,
      });
    }
  }

  const byId = new Map(nodes.map((n) => [n.id, n]));

  for (const edge of edges) {
    const source = byId.get(edge.source);
    if (!source || !isTerminator(source)) continue;

    issues.push({
      level: "error",
      edgeId: edge.id,
      message:
        `Edge "${edge.id}" reads from "${edge.source}", which is a TERMINAL node and publishes ` +
        `no output ports at all. Nothing can ever travel this edge: it does not fail at run ` +
        `time, it delivers nothing, and "${edge.target}" runs anyway with an empty input.`,
    });
  }

  return issues;
}

/**
 * Which nodes are allowed to sit unconnected.
 *
 * Three answers, and the third is the one that took a second pass — it was
 * missed in the PHP twin's first release and shipped as 0.48.1:
 *
 * 1. **`note`**, across every id the kind answers to, so a graph saved with the
 *    canonical `@particle-academy/note` stays an annotation rather than becoming
 *    an unwireable node.
 * 2. **Any `annotation` or `layout` kind.** A host may register its own note,
 *    and `@particle-academy/lane` is a swimlane the engine walks straight past.
 *    Neither is a step and neither is ever wired.
 * 3. **A kind the registry has never heard of.** Not a loophole — the honest
 *    answer. An unknown kind already produces its own issue, and we cannot know
 *    whether it is a step, an annotation or a lane. Claiming it must be wired
 *    would assert something unverifiable, and it lands hardest on the graphs
 *    that deserve it least: a laned graph loaded by a runtime without `lane`
 *    registered would report every swimlane twice, the second time wrongly.
 *
 * The note/annotation/layout half matches the test `run-flow` uses to skip a
 * node. The unknown-kind half deliberately does NOT — see the closing comment in
 * this file for why the two must not become one helper.
 */
export function mayFloat(node: FlowNode): boolean {
  const type = node.type;
  if (!type) return false;
  if (type === "note") return true;

  const kind = getNodeKind(type);
  if (!kind) return true;

  return kindIds(kind).includes("note") || kind.category === "annotation" || kind.category === "layout";
}

/**
 * A kind that declares an EMPTY output list ends a chain.
 *
 * `[]` and `undefined` are different answers and only the first means this.
 * `undefined` is "nobody declared what this publishes", which resolves to `out`
 * and is most nodes in most graphs; `[]` is an explicit claim that there is
 * nothing to connect from. Reading them alike would refuse nearly every
 * workflow ever written.
 */
function isTerminator(node: FlowNode): boolean {
  // A node carrying its own ports overrides its kind — the engine reads these
  // first, so an author who has said what this node publishes is believed.
  // (The PHP twin's importer DROPS node-level ports, so this branch is reachable
  // there only for a hand-built graph. Noted rather than smoothed over: the two
  // importers genuinely differ here.)
  const own = (node.data as { outputs?: unknown[] } | undefined)?.outputs;
  if (Array.isArray(own)) return own.length === 0;

  const kind = node.type ? getNodeKind(node.type) : null;

  // An unregistered kind falls back to `out` in the engine, so it is not a
  // terminator. Refusing here would break a host mid-registration, and would
  // use "I do not know" as evidence.
  if (!kind) return false;

  return Array.isArray(kind.outputs) && kind.outputs.length === 0;
}

/**
 * NOT shared with `frontier`'s / `run-flow`'s annotation test, deliberately.
 *
 * The two predicates look identical and have OPPOSITE safe defaults, which is
 * exactly how a shared helper becomes a bug:
 *
 * - **Here** an unknown kind may float. Being permissive costs nothing — the
 *   unknown-kind issue already fires, and we would otherwise assert something
 *   unverifiable.
 * - **In the engine** an unknown kind must NOT be treated as an annotation.
 *   Being permissive there means SKIPPING a node the host meant to run, which
 *   is silent and unrecoverable.
 *
 * So the note/annotation/layout half is the same question and the unknown half
 * is a different one. Collapsing them into one function would read as tidier and
 * would make a host's unregistered kind stop executing.
 */

import { forwardRef } from "react";
import { cn } from "../lib/utils/cn";
import type { GridProps } from "./Grid.types";

/**
 * Gutter lengths. The grid applies these ITSELF rather than through a Tailwind
 * `gap-*` class, because the column cap has to divide by the gap that is
 * actually in effect — and a class is a value the component does not control.
 *
 * 5.23.0 kept the class and hard-coded the matching length beside it. In the
 * showcase those two disagreed by 2px, which was enough: with the real gutter
 * wider than the arithmetic assumed, N tracks plus N-1 gaps overflowed the row
 * and `auto-fit` dropped to N-1. A 3-up grid rendered 2-up, and nothing was
 * wrong with either value on its own.
 */
const GAP = { sm: "0.75rem", md: "1.5rem", lg: "2.5rem" } as const;

/** Narrowest a column may get before the grid drops one. */
const MIN_TRACK = "16rem";

/**
 * The modular grid.
 *
 * Column count goes through a custom property rather than a `grid-cols-N` class
 * because N is a prop: Tailwind cannot generate a class it never sees in source,
 * and every hand-rolled copy in the gallery worked around that differently. The
 * property also gives a design a single place to override the breakpoint
 * behaviour in CSS without fighting a utility.
 *
 * ## `cols` is a CEILING, not a fixed count
 *
 * The responsive template reads `--fancy-grid-cols`, so `cols` means "this many
 * at most, fewer when narrow". Until 5.23.0 it meant nothing at all while
 * `responsive` was on: the template was a fixed `repeat(auto-fit, minmax(min(
 * 100%, 16rem), 1fr))`, so a grid asked for 2 and a grid asked for 5 rendered
 * the same track list, and the only way to get a real column count was
 * `responsive={false}` — which then had no breakpoints at all. The property this
 * doc comment has always advertised was set and never read.
 *
 * The gutter is in the arithmetic because it has to be: N tracks each `100%/N`
 * wide plus N-1 gaps overflow the row, and `auto-fit` responds by fitting N-1.
 * An off-by-one that looks like a design decision.
 *
 * Which is why the grid sets its own `gap` from `--fancy-grid-gap` instead of a
 * Tailwind `gap-*` class: the cap must divide by the gutter actually in effect,
 * and a class is a value this component does not control. Override the property
 * to change the gutter — that moves the spacing and the arithmetic together.
 */
export const Grid = forwardRef<HTMLDivElement, GridProps>(
  ({ children, cols = 3, gap = "md", responsive = true, className, style, ...props }, ref) => {
    // The largest a track may be: an even share of the row once the gutters are
    // paid for. `max()` against MIN_TRACK keeps the collapse; `min()` against
    // 100% stops a single column overflowing a narrow viewport.
    const cap =
      "calc((100% - (var(--fancy-grid-cols) - 1) * var(--fancy-grid-gap)) / var(--fancy-grid-cols))";

    return (
      <div
        ref={ref}
        {...props}
        data-react-fancy-grid=""
        data-responsive={responsive ? "true" : "false"}
        className={cn("grid", className)}
        style={{
          ...style,
          ["--fancy-grid-cols" as string]: String(cols),
          ["--fancy-grid-gap" as string]: GAP[gap],
          // Read back rather than inlined, so overriding the property in CSS
          // moves the gutter AND the arithmetic together.
          gap: "var(--fancy-grid-gap)",
          gridTemplateColumns: responsive
            ? `repeat(auto-fit, minmax(min(100%, max(${MIN_TRACK}, ${cap})), 1fr))`
            : "repeat(var(--fancy-grid-cols), minmax(0, 1fr))",
        }}
      >
        {children}
      </div>
    );
  },
);

Grid.displayName = "Grid";

import type { HTMLAttributes, ReactNode } from "react";

export interface GridProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
  /**
   * The most columns this grid may use. Default `3`.
   *
   * A CEILING, not a fixed count: with `responsive` on (the default) the grid
   * uses fewer as it narrows and never more than this. Published as
   * `--fancy-grid-cols`, which the track template reads — so overriding that
   * property in CSS genuinely changes the layout.
   */
  cols?: number;
  /** Gutter. Default `md`. */
  gap?: "sm" | "md" | "lg";
  /**
   * Collapse toward one column on small screens. Default `true`.
   *
   * Off for grids that are genuinely fixed — a 2-up of icons, say — where
   * collapsing looks broken rather than responsive.
   */
  responsive?: boolean;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { forwardRef } from "react";
import { cn } from "../lib/utils/cn";
import type { HeadingProps } from "./Heading.types";

const sizeClasses: Record<NonNullable<HeadingProps["size"]>, string> = {
  xs: "text-xs",
  sm: "text-sm",
  md: "text-base",
  lg: "text-lg",
  xl: "text-2xl",
  "2xl": "text-4xl",
  // Display steps. Each is the next Tailwind size up, continuing the ramp.
  "3xl": "text-5xl",
  "4xl": "text-6xl",
  "5xl": "text-7xl",
  "6xl": "text-8xl",
  "7xl": "text-9xl",
};

/**
 * Tracking for the display steps only.
 *
 * Default letter-spacing is tuned for headings that sit near body text. At
 * display scale the same spacing reads loose — which is exactly why the big-type
 * gallery style hand-rolled its own `<h1>` rather than use this component.
 */
const trackingClasses: Partial<Record<NonNullable<HeadingProps["size"]>, string>> = {
  "3xl": "tracking-tight",
  "4xl": "tracking-tight",
  "5xl": "tracking-tighter",
  "6xl": "tracking-tighter",
  "7xl": "tracking-tighter",
};

const weightClasses: Record<NonNullable<HeadingProps["weight"]>, string> = {
  normal: "font-normal",
  medium: "font-medium",
  semibold: "font-semibold",
  bold: "font-bold",
};

export const Heading = forwardRef<HTMLHeadingElement, HeadingProps>(
  (
    {
      as: Tag = "h2",
      size = "lg",
      weight = "bold",
      className,
      children,
      ...props
    },
    ref,
  ) => {
    return (
      <Tag
        ref={ref}
        data-react-fancy-heading=""
        className={cn(
          "text-zinc-900 dark:text-zinc-100",
          sizeClasses[size],
          trackingClasses[size],
          weightClasses[weight],
          className,
        )}
        {...props}
      >
        {children}
      </Tag>
    );
  },
);

Heading.displayName = "Heading";

import type { HTMLAttributes } from "react";

export interface HeadingProps extends HTMLAttributes<HTMLHeadingElement> {
  /** Which heading element to render */
  as?: "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
  /**
   * Text size, on a SEMANTIC ramp — the names are steps on this scale, not
   * Tailwind class names. `xl` is `text-2xl` and `2xl` is `text-4xl`, and that
   * offset has been true since the component shipped, so the display steps
   * below continue the same ramp rather than re-basing it and silently
   * resizing every existing heading.
   *
   * `3xl`–`7xl` are DISPLAY sizes: hero type, "typography at maximum volume".
   * They carry tighter tracking, because letter-spacing tuned for body-adjacent
   * headings reads loose and unset once type gets big.
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "4xl" | "5xl" | "6xl" | "7xl";
  /** Font weight */
  weight?: "normal" | "medium" | "semibold" | "bold";
}

