import { Button, Input, Textarea } from "@particle-academy/react-fancy";
import type { HumansTxtEntry, HumansTxtModel } from "../lib/model";
import { validateHumansTxt } from "../lib/validate";
import { IssueList, Section, StringList } from "./internal";

export interface HumansTxtEditorProps {
  value: HumansTxtModel;
  onChange: (next: HumansTxtModel) => void;
  hideIssues?: boolean;
  className?: string;
}

/** Controlled humans.txt editor: team credits + thanks + site colophon. */
export function HumansTxtEditor({
  value,
  onChange,
  hideIssues,
  className,
}: HumansTxtEditorProps) {
  const issues = validateHumansTxt(value);
  const patch = (next: Partial<HumansTxtModel>) =>
    onChange({ ...value, ...next });

  const updateMember = (index: number, next: Partial<HumansTxtEntry>) =>
    patch({
      team: value.team.map((m, i) => (i === index ? { ...m, ...next } : m)),
    });

  const addMember = () =>
    patch({ team: [...value.team, { role: "", name: "" }] });

  const removeMember = (index: number) =>
    patch({ team: value.team.filter((_, i) => i !== index) });

  return (
    <div className={className} data-x-editor="humansTxt">
      <Section
        title="Team"
        handle="humans-team"
        action={
          <Button
            type="button"
            variant="ghost"
            onClick={addMember}
            data-x-add="humans-member"
          >
            Add person
          </Button>
        }
      >
        {value.team.map((member, i) => (
          <div
            key={i}
            data-x-member={i}
            style={{
              display: "flex",
              gap: "0.4rem",
              alignItems: "end",
              flexWrap: "wrap",
            }}
          >
            <div style={{ flex: "1 1 7rem" }}>
              <Input
                label={i === 0 ? "Role" : undefined}
                value={member.role}
                onValueChange={(role) => updateMember(i, { role })}
                placeholder="Developer"
                data-x-input={`humans-role:${i}`}
              />
            </div>
            <div style={{ flex: "1 1 8rem" }}>
              <Input
                label={i === 0 ? "Name" : undefined}
                value={member.name}
                onValueChange={(name) => updateMember(i, { name })}
                placeholder="Ada Lovelace"
                data-x-input={`humans-name:${i}`}
              />
            </div>
            <div style={{ flex: "1 1 8rem" }}>
              <Input
                label={i === 0 ? "Contact" : undefined}
                value={member.contact ?? ""}
                onValueChange={(v) =>
                  updateMember(i, { contact: v || undefined })
                }
                placeholder="@handle"
                data-x-input={`humans-contact:${i}`}
              />
            </div>
            <Button
              type="button"
              variant="ghost"
              color="red"
              onClick={() => removeMember(i)}
              data-x-remove={`humans-member:${i}`}
            >
              ×
            </Button>
          </div>
        ))}
      </Section>

      <Section title="Thanks" handle="humans-thanks">
        <StringList
          handle="humans-thanks"
          values={value.thanks ?? []}
          onChange={(thanks) => patch({ thanks: thanks.length ? thanks : undefined })}
          placeholder="Open-source maintainers"
        />
      </Section>

      <Section title="Site" handle="humans-site">
        <Textarea
          value={value.site ?? ""}
          onValueChange={(v) => patch({ site: v || undefined })}
          placeholder={"Standards: HTML5, CSS3\nComponents: react-fancy"}
          data-x-input="humans-site"
        />
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="humansTxt" />}
    </div>
  );
}

import { useState } from "react";
import { Badge, Button, Callout, Input } from "@particle-academy/react-fancy";

/**
 * Shared internal building blocks for the editors. Not exported from the
 * package root — these are implementation details of the editors.
 */

/** Surface a list of validation issues as a soft warning callout. */
export function IssueList({
  issues,
  testid,
}: {
  issues: string[];
  testid?: string;
}) {
  if (!issues.length) return null;
  return (
    <Callout color="amber" data-x-issues={testid ?? ""}>
      <ul style={{ margin: 0, paddingLeft: "1.1rem" }}>
        {issues.map((issue, i) => (
          <li key={i} data-x-issue>
            {issue}
          </li>
        ))}
      </ul>
    </Callout>
  );
}

/**
 * Controlled add/remove list of plain strings rendered as chips with an
 * inline "add a row" input. `disallowedValues` are rejected on add and, if
 * already present, flagged — used by RobotsEditor to keep protected paths out
 * of an Allow list.
 */
export function StringList({
  label,
  values,
  onChange,
  placeholder,
  handle,
  disallowedValues,
  disallowedReason,
}: {
  label?: string;
  values: string[];
  onChange: (next: string[]) => void;
  placeholder?: string;
  /** data-* handle base, e.g. "robots-allow". */
  handle: string;
  disallowedValues?: string[];
  disallowedReason?: (value: string) => string;
}) {
  const [draft, setDraft] = useState("");
  const blocked = new Set(disallowedValues ?? []);

  const add = () => {
    const v = draft.trim();
    if (!v || values.includes(v)) {
      setDraft("");
      return;
    }
    onChange([...values, v]);
    setDraft("");
  };

  const remove = (value: string) =>
    onChange(values.filter((v) => v !== value));

  return (
    <div data-x-list={handle}>
      {label ? (
        <div
          style={{ fontSize: "0.8rem", fontWeight: 600, marginBottom: "0.25rem" }}
        >
          {label}
        </div>
      ) : null}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "0.35rem",
          marginBottom: values.length ? "0.4rem" : 0,
        }}
      >
        {values.map((value) => {
          const isBlocked = blocked.has(value);
          return (
            <Badge
              key={value}
              color={isBlocked ? "red" : "slate"}
              variant={isBlocked ? "soft" : "outline"}
              data-x-chip={`${handle}:${value}`}
              title={
                isBlocked && disallowedReason
                  ? disallowedReason(value)
                  : undefined
              }
            >
              {value}
              <button
                type="button"
                onClick={() => remove(value)}
                aria-label={`Remove ${value}`}
                data-x-remove={`${handle}:${value}`}
                style={{
                  marginLeft: "0.35rem",
                  border: "none",
                  background: "transparent",
                  cursor: "pointer",
                  fontWeight: 700,
                }}
              >
                ×
              </button>
            </Badge>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: "0.4rem" }}>
        <Input
          value={draft}
          onValueChange={setDraft}
          placeholder={placeholder}
          data-x-input={`${handle}-draft`}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              add();
            }
          }}
        />
        <Button
          type="button"
          variant="ghost"
          onClick={add}
          data-x-add={handle}
        >
          Add
        </Button>
      </div>
    </div>
  );
}

/** A labelled section wrapper used to group fields inside an editor. */
export function Section({
  title,
  action,
  children,
  handle,
}: {
  title: string;
  action?: React.ReactNode;
  children: React.ReactNode;
  handle?: string;
}) {
  return (
    <section
      data-x-section={handle}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "0.5rem",
        marginBottom: "1rem",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <h4 style={{ margin: 0, fontSize: "0.9rem", fontWeight: 700 }}>
          {title}
        </h4>
        {action}
      </div>
      {children}
    </section>
  );
}

/**
 * TS model types for the well-known files modeled by `fancy-x-files`.
 *
 * These are intentionally small, standalone shapes (this package does NOT
 * import the PHP/JS port) so the editor builds + ships independently. They
 * mirror the canonical shapes emitted by the `fancy-x-files` packages.
 *
 * Every model is plain JSON: arrays of objects + primitives. That makes the
 * whole surface agent-emittable — an embedded agent can read the current
 * model, propose a new one, and hand it back through the same `onChange`
 * channel a human uses (Human+ UX contract).
 */

/** The well-known files this suite can edit + preview. */
export type XFileKind =
  | "robots"
  | "securityTxt"
  | "llmsTxt"
  | "humansTxt"
  | "sitemap"
  | "agents";

/** robots.txt — grouped crawl rules, sitemaps, host, protected paths. */
export interface RobotsGroup {
  /** `User-agent` lines for this group. `["*"]` for all. */
  userAgents: string[];
  /** `Allow:` paths. */
  allow: string[];
  /** `Disallow:` paths. */
  disallow: string[];
  /** Optional `Crawl-delay:` seconds. */
  crawlDelay?: number;
}

export interface RobotsModel {
  groups: RobotsGroup[];
  /** Absolute `Sitemap:` URLs. */
  sitemaps: string[];
  /**
   * Paths that must be Disallowed for every user-agent and may NEVER be
   * Allowed — mirrors the PHP `protect()` safety rail. The renderer pins
   * these as Disallow on every group; the editor refuses to Allow them.
   */
  protectedPaths: string[];
  /** Optional `Host:` directive. */
  host?: string;
}

/** security.txt (RFC 9116). */
export interface SecurityTxtModel {
  /** `Contact:` — one or more mailto:/https: URIs. At least one required. */
  contact: string[];
  /** `Expires:` — ISO 8601 timestamp; MUST be in the future. */
  expires: string;
  /** `Encryption:` URI. */
  encryption?: string;
  /** `Acknowledgments:` URI. */
  acknowledgments?: string;
  /** `Preferred-Languages:` comma-separated tags. */
  preferredLanguages?: string;
  /** `Canonical:` URI. */
  canonical?: string;
  /** `Policy:` URI. */
  policy?: string;
  /** `Hiring:` URI. */
  hiring?: string;
}

/** llms.txt — Markdown index of resources for LLMs. */
export interface LlmsLink {
  title: string;
  url: string;
  notes?: string;
}

export interface LlmsSection {
  name: string;
  links: LlmsLink[];
}

export interface LlmsTxtModel {
  title: string;
  /** The blockquote summary directly under the H1. */
  summary?: string;
  /** Free-form Markdown paragraph(s) of detail. */
  details?: string;
  sections: LlmsSection[];
}

/** humans.txt — credits + site colophon. */
export interface HumansTxtEntry {
  /** e.g. "Developer", "Designer". */
  role: string;
  name: string;
  /** Optional contact / handle / site. */
  contact?: string;
}

export interface HumansTxtModel {
  team: HumansTxtEntry[];
  /** "Site" section free-text (Standards, Components, Software, …). */
  site?: string;
  thanks?: string[];
}

/** sitemap.xml — a flat URL set. */
export type SitemapChangeFreq =
  | "always"
  | "hourly"
  | "daily"
  | "weekly"
  | "monthly"
  | "yearly"
  | "never";

export interface SitemapUrl {
  loc: string;
  /** ISO 8601 date. */
  lastmod?: string;
  changefreq?: SitemapChangeFreq;
  /** 0.0 – 1.0. */
  priority?: number;
}

export interface SitemapModel {
  urls: SitemapUrl[];
}

/**
 * /AGENTS — a machine-readable register of the agents allowed (or denied) to
 * act on the site, mirroring the robots-style "agent policy" idea.
 */
export interface AgentEntry {
  /** Stable identifier / handle for the agent. */
  id: string;
  /** Human label. */
  name?: string;
  /** Policy for this agent. */
  policy: "allow" | "deny";
  /** Optional homepage / contact URL. */
  url?: string;
  /** Optional one-line description of permitted scope. */
  scope?: string;
}

export interface AgentsModel {
  agents: AgentEntry[];
  /** Optional contact for policy questions. */
  contact?: string;
}

/** The aggregate value held by `XFilesManager`. */
export interface XFilesModel {
  robots?: RobotsModel;
  securityTxt?: SecurityTxtModel;
  llmsTxt?: LlmsTxtModel;
  humansTxt?: HumansTxtModel;
  sitemap?: SitemapModel;
  agents?: AgentsModel;
}

/** Map a file kind to its model type. */
export interface XFileModelMap {
  robots: RobotsModel;
  securityTxt: SecurityTxtModel;
  llmsTxt: LlmsTxtModel;
  humansTxt: HumansTxtModel;
  sitemap: SitemapModel;
  agents: AgentsModel;
}

/** Empty-but-valid starting models, handy for "add this file" affordances. */
export const emptyRobots = (): RobotsModel => ({
  groups: [{ userAgents: ["*"], allow: [], disallow: [] }],
  sitemaps: [],
  protectedPaths: [],
});

export const emptySecurityTxt = (): SecurityTxtModel => ({
  contact: [],
  expires: "",
});

export const emptyLlmsTxt = (): LlmsTxtModel => ({
  title: "",
  sections: [],
});

export const emptyHumansTxt = (): HumansTxtModel => ({ team: [] });

export const emptySitemap = (): SitemapModel => ({ urls: [] });

export const emptyAgents = (): AgentsModel => ({ agents: [] });

/** Human-readable label + on-disk filename for each kind. */
export const X_FILE_META: Record<
  XFileKind,
  { label: string; filename: string }
> = {
  robots: { label: "robots.txt", filename: "robots.txt" },
  securityTxt: { label: "security.txt", filename: ".well-known/security.txt" },
  llmsTxt: { label: "llms.txt", filename: "llms.txt" },
  humansTxt: { label: "humans.txt", filename: "humans.txt" },
  sitemap: { label: "sitemap.xml", filename: "sitemap.xml" },
  agents: { label: "AGENTS", filename: ".well-known/agents.json" },
};

/**
 * Validation helpers. Each `validate*` returns a flat `string[]` of
 * human-readable issues (empty array == valid). The editors surface these
 * inline, and an embedded agent can call them to check a proposal before
 * handing it back.
 */
import type {
  AgentsModel,
  HumansTxtModel,
  LlmsTxtModel,
  RobotsModel,
  SecurityTxtModel,
  SitemapModel,
  XFileKind,
} from "./model";

const looksLikeUrl = (s: string): boolean =>
  /^https?:\/\/\S+$/i.test(s.trim());

export function validateRobots(model: RobotsModel): string[] {
  const issues: string[] = [];
  if (!model.groups.length) {
    issues.push("At least one user-agent group is required.");
  }
  model.groups.forEach((group, i) => {
    const where = `Group ${i + 1}`;
    if (!group.userAgents.length) {
      issues.push(`${where}: needs at least one User-agent (use "*" for all).`);
    }
    // Protected paths must never be Allowed — mirrors PHP protect() safety.
    for (const path of group.allow) {
      if (model.protectedPaths.includes(path)) {
        issues.push(
          `${where}: "${path}" is a protected path and cannot be Allowed. Remove it from Allow or unprotect it.`,
        );
      }
    }
    if (group.crawlDelay != null && group.crawlDelay < 0) {
      issues.push(`${where}: Crawl-delay must be ≥ 0.`);
    }
  });
  for (const sm of model.sitemaps) {
    if (!looksLikeUrl(sm)) {
      issues.push(`Sitemap "${sm}" should be an absolute http(s) URL.`);
    }
  }
  return issues;
}

export function validateSecurityTxt(model: SecurityTxtModel): string[] {
  const issues: string[] = [];
  if (!model.contact.length || model.contact.every((c) => !c.trim())) {
    issues.push("At least one Contact is required (mailto: or https: URI).");
  }
  if (!model.expires) {
    issues.push("Expires is required.");
  } else {
    const when = new Date(model.expires);
    if (Number.isNaN(when.getTime())) {
      issues.push("Expires must be a valid date/time.");
    } else if (when.getTime() <= Date.now()) {
      issues.push("Expires must be a date in the future.");
    }
  }
  return issues;
}

export function validateLlmsTxt(model: LlmsTxtModel): string[] {
  const issues: string[] = [];
  if (!model.title.trim()) issues.push("Title is required.");
  model.sections.forEach((section, i) => {
    if (!section.name.trim()) {
      issues.push(`Section ${i + 1}: needs a name.`);
    }
    section.links.forEach((link, j) => {
      const where = `Section ${i + 1} · link ${j + 1}`;
      if (!link.title.trim()) issues.push(`${where}: needs a title.`);
      if (!looksLikeUrl(link.url)) {
        issues.push(`${where}: URL should be an absolute http(s) URL.`);
      }
    });
  });
  return issues;
}

export function validateHumansTxt(model: HumansTxtModel): string[] {
  const issues: string[] = [];
  model.team.forEach((m, i) => {
    if (!m.role.trim()) issues.push(`Team member ${i + 1}: needs a role.`);
    if (!m.name.trim()) issues.push(`Team member ${i + 1}: needs a name.`);
  });
  return issues;
}

export function validateSitemap(model: SitemapModel): string[] {
  const issues: string[] = [];
  if (!model.urls.length) issues.push("Add at least one URL.");
  model.urls.forEach((u, i) => {
    if (!looksLikeUrl(u.loc)) {
      issues.push(`URL ${i + 1}: <loc> should be an absolute http(s) URL.`);
    }
    if (u.priority != null && (u.priority < 0 || u.priority > 1)) {
      issues.push(`URL ${i + 1}: priority must be between 0.0 and 1.0.`);
    }
  });
  return issues;
}

export function validateAgents(model: AgentsModel): string[] {
  const issues: string[] = [];
  const seen = new Set<string>();
  model.agents.forEach((a, i) => {
    if (!a.id.trim()) {
      issues.push(`Agent ${i + 1}: needs an id.`);
    } else if (seen.has(a.id)) {
      issues.push(`Agent ${i + 1}: duplicate id "${a.id}".`);
    } else {
      seen.add(a.id);
    }
    if (a.url && !looksLikeUrl(a.url)) {
      issues.push(`Agent ${i + 1}: url should be an absolute http(s) URL.`);
    }
  });
  return issues;
}

/** Dispatch validation by file kind. */
export function validateModel(kind: XFileKind, model: unknown): string[] {
  switch (kind) {
    case "robots":
      return validateRobots(model as RobotsModel);
    case "securityTxt":
      return validateSecurityTxt(model as SecurityTxtModel);
    case "llmsTxt":
      return validateLlmsTxt(model as LlmsTxtModel);
    case "humansTxt":
      return validateHumansTxt(model as HumansTxtModel);
    case "sitemap":
      return validateSitemap(model as SitemapModel);
    case "agents":
      return validateAgents(model as AgentsModel);
  }
}

import { forwardRef, useSyncExternalStore } from "react";
import { cn } from "../lib/utils/cn";
import { resolveIcon, subscribeIconResolution, getIconResolutionVersion } from "./icon-config";
import type { IconProps } from "./Icon.types";

const sizeClasses: Record<NonNullable<IconProps["size"]>, string> = {
  xs: "h-3 w-3",
  sm: "h-4 w-4",
  md: "h-5 w-5",
  lg: "h-6 w-6",
  xl: "h-8 w-8",
};

const sizePixels: Record<NonNullable<IconProps["size"]>, number> = {
  xs: 12,
  sm: 16,
  md: 20,
  lg: 24,
  xl: 32,
};

export const Icon = forwardRef<HTMLSpanElement, IconProps>(
  ({ size = "md", className, children, name, iconSet, ...props }, ref) => {
    // Re-render when the lazy lucide barrel lands, so `<Icon name>` auto-resolved
    // from lucide appears once loaded. Registered icons resolve synchronously and
    // never trigger the lazy load. SSR snapshot is the same getter (version 0).
    useSyncExternalStore(
      subscribeIconResolution,
      getIconResolutionVersion,
      getIconResolutionVersion,
    );

    let content = children;

    if (name && !children) {
      const ResolvedIcon = resolveIcon(name, iconSet);
      if (ResolvedIcon) {
        content = <ResolvedIcon size={sizePixels[size]} />;
      }
    }

    return (
      <span
        ref={ref}
        aria-hidden="true"
        data-react-fancy-icon=""
        className={cn(
          "inline-flex items-center justify-center flex-shrink-0",
          sizeClasses[size],
          className,
        )}
        {...props}
      >
        {content}
      </span>
    );
  },
);

Icon.displayName = "Icon";

import type { HTMLAttributes } from "react";

export interface IconProps extends HTMLAttributes<HTMLSpanElement> {
  /** Icon container size */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /** Icon name to resolve from the registered icon set (e.g., "rocket", "arrow-right") */
  name?: string;
  /** Which registered icon set to use (defaults to the configured default) */
  iconSet?: string;
}

import type { ComponentType } from "react";
import type { IconSet } from "./icon-config.types";

type IconComponent = ComponentType<{ className?: string; size?: number }>;

const registry = new Map<string, IconSet>();
let defaultSetName = "lucide";

/**
 * Addendum layer — icon sets consulted across EVERY lookup, after the active
 * base set but before the lucide auto-fallback, regardless of `defaultSet`.
 * This is how a brand-icon pack (e.g. `@particle-academy/fancy-brand-icons`)
 * layers in: `<Icon name="github" />` resolves the brand mark on top of Lucide
 * (or any swapped base) without a `set=` query. Base set still wins; addenda
 * supplement. Empty by default ⇒ behavior unchanged.
 */
const addenda: IconSet[] = [];

/** Register an icon set as an addendum (supplements every base set). */
export function registerIconAddendum(set: IconSet): void {
  if (!addenda.includes(set)) addenda.push(set);
}

function resolveFromAddenda(name: string): IconComponent | null {
  for (const set of addenda) {
    const hit = set.resolve(name);
    if (hit) return hit as IconComponent;
  }
  return null;
}

function kebabToPascal(str: string): string {
  return str
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");
}

/**
 * Lazy lucide barrel. The auto-fallback (`<Icon name="…" />` resolving ANY
 * lucide icon by kebab name) needs the whole namespace because names are
 * dynamic — un-tree-shakeable. Importing it eagerly forced all ~5400 icons
 * into react-fancy's main bundle for every consumer (~548KB). Instead we
 * dynamic-import it on first auto-resolve, so the barrel becomes a lazy chunk
 * loaded ONLY by apps that actually use `<Icon name>` with an unregistered
 * icon — never on the critical path. Consumers wanting sync resolution +
 * tree-shaking should `registerIcons({ ...named imports })` (those win and
 * never trigger the lazy load).
 */
let lucideModule: Record<string, IconComponent | undefined> | null = null;
let lucidePromise: Promise<unknown> | null = null;
let lucideVersion = 0;
const lucideListeners = new Set<() => void>();

function ensureLucideLoaded(): void {
  if (lucideModule || lucidePromise) return;
  lucidePromise = import("lucide-react")
    .then((mod) => {
      lucideModule = mod as unknown as Record<string, IconComponent | undefined>;
      lucideVersion++;
      for (const listener of lucideListeners) listener();
    })
    .catch(() => {
      // Leave lucidePromise set so we don't hammer a failed import.
    });
}

/** Subscribe to the lazy lucide load so `<Icon>` can re-render once it lands. */
export function subscribeIconResolution(listener: () => void): () => void {
  lucideListeners.add(listener);
  return () => lucideListeners.delete(listener);
}

/** Snapshot for useSyncExternalStore — bumps when the lucide barrel loads. */
export function getIconResolutionVersion(): number {
  return lucideVersion;
}

/**
 * Fallback resolver: look up any lucide-react icon by its kebab-case name
 * without requiring the consumer to call `registerIcons()` first. Returns null
 * until the lazy barrel has loaded (the first call kicks off the import; `<Icon>`
 * re-renders via `subscribeIconResolution` when it's ready). Overrides
 * registered via `registerIcons()` still win and resolve synchronously.
 */
function resolveFromLucide(name: string): IconComponent | null {
  // SSR-deterministic: never resolve the lazily-imported lucide barrel on the
  // server. A long-running SSR process (e.g. Inertia's node SSR daemon) loads
  // the barrel after its first request, then renders auto-fallback lucide icons
  // that a fresh client (barrel not yet loaded) does NOT have at hydration →
  // React #418 ("server HTML didn't match"). Returning null on the server makes
  // the server render match the client's FIRST render; the icon then appears
  // once the client loads the barrel (via subscribeIconResolution). Registered
  // icons + addenda (brand packs) still resolve synchronously on both sides.
  if (typeof window === "undefined") return null;
  if (!lucideModule) {
    ensureLucideLoaded();
    return null;
  }
  const pascal = kebabToPascal(name);
  const icon = lucideModule[pascal];
  return typeof icon === "function" || (icon && typeof icon === "object") ? (icon as IconComponent) : null;
}

/**
 * Register individual icon components by their kebab-case name.
 *
 * ```tsx
 * import { registerIcons } from "@particle-academy/react-fancy";
 * import { Home, Settings, Mail } from "lucide-react";
 *
 * registerIcons({ Home, Settings, Mail });
 * ```
 *
 * Icons are registered into the default "lucide" icon set and resolved
 * by the `<Icon name="home" />` component using kebab-case names.
 */
export function registerIcons(
  icons: Record<string, ComponentType<{ className?: string; size?: number }>>,
): void {
  let set = registry.get("lucide");
  if (!set) {
    const map = new Map<string, ComponentType<{ className?: string; size?: number }>>();
    set = {
      resolve: (name: string) => {
        const pascal = kebabToPascal(name);
        return map.get(pascal) ?? null;
      },
      _map: map,
    } as IconSet & { _map: Map<string, ComponentType<{ className?: string; size?: number }>> };
    registry.set("lucide", set);
  }
  const map = (set as IconSet & { _map: Map<string, ComponentType<{ className?: string; size?: number }>> })._map;
  for (const [key, component] of Object.entries(icons)) {
    map.set(key, component);
  }
}

export function registerIconSet(name: string, set: IconSet): void {
  registry.set(name, set);
}

export function configureIcons(options: { defaultSet?: string }): void {
  if (options.defaultSet) {
    defaultSetName = options.defaultSet;
  }
}

export function resolveIcon(
  name: string,
  setName?: string,
): IconComponent | null {
  const resolvedSet = setName ?? defaultSetName;
  const set = registry.get(resolvedSet);
  const registered = set ? set.resolve(name) : null;
  if (registered) return registered;
  // Addenda fill gaps after the base set, before the lucide auto-fallback — so a
  // brand pack's `github` wins over lucide's auto-resolved one.
  const fromAddenda = resolveFromAddenda(name);
  if (fromAddenda) return fromAddenda;
  if (resolvedSet === "lucide") return resolveFromLucide(name);
  return null;
}

import type { ComponentType } from "react";

export interface IconSet {
  resolve: (name: string) => ComponentType<{ className?: string; size?: number }> | null;
}

export { Icon } from "./Icon";
export type { IconProps } from "./Icon.types";
export { registerIcons, registerIconSet, registerIconAddendum, configureIcons, resolveIcon } from "./icon-config";
export type { IconSet } from "./icon-config.types";

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import type { CSSProperties } from "react";
import type { ImageElement } from "../lib/types";

export interface ImageElementRendererProps {
    element: ImageElement;
}

/**
 * Renders an image element. When `element.crop` is set (a window in
 * image-relative 0..1 coords `{x,y,w,h}`), the image is shown cropped to that
 * window: an `overflow:hidden` box clips an inner `<img>` that's been scaled up
 * by `1/w` × `1/h` and offset so the crop window exactly fills the box. Without
 * a crop it's the plain `object-fit` image. The same renderer feeds both the
 * editor canvas and the viewer, so a crop is visible everywhere.
 */
export function ImageElementRenderer({ element }: ImageElementRendererProps) {
    const crop = element.crop;
    const fit = element.fit ?? "contain";

    if (crop && crop.w > 0 && crop.h > 0) {
        // The inner image is scaled so the crop window (fraction w×h of the
        // image) fills 100% of the box; then translated so the window's
        // top-left aligns with the box's top-left.
        const inner: CSSProperties = {
            position: "absolute",
            left: 0,
            top: 0,
            width: `${(1 / crop.w) * 100}%`,
            height: `${(1 / crop.h) * 100}%`,
            transform: `translate(${(-crop.x / crop.w) * 100}%, ${(-crop.y / crop.h) * 100}%)`,
            transformOrigin: "top left",
            objectFit: fit,
            display: "block",
        };
        return (
            <div style={{ position: "relative", width: "100%", height: "100%", overflow: "hidden" }}>
                <img src={element.src} alt={element.alt ?? ""} style={inner} draggable={false} />
            </div>
        );
    }

    return (
        <img
            src={element.src}
            alt={element.alt ?? ""}
            style={{
                width: "100%",
                height: "100%",
                objectFit: fit,
                display: "block",
            }}
            draggable={false}
        />
    );
}

/**
 * The fancy-slides data model.
 *
 * Every shape here is JSON-friendly — pure objects, arrays, primitives, and
 * tagged unions. No React children, no functions, no class instances. This
 * is the contract the deck schema commits to: an LLM can emit a deck, a
 * server can store one, a designer can hand-edit one, and the viewer +
 * editor will render it identically.
 *
 * Coordinate system: elements position themselves in slide-relative units
 * where the slide is a 1.0 × (1 / aspectRatio) rectangle. So `x: 0.5, y: 0.5`
 * is the centre of the slide regardless of how big it's rendered. This
 * keeps decks resolution-independent — a fullscreen 1920×1080 viewer and a
 * thumbnail at 320×180 render the same layout.
 */

// ─── Deck ──────────────────────────────────────────────────────────────────

export interface Deck {
    /** Stable id. Required even when persistence is in-memory. */
    id: string;
    /** Human title — shown in the editor chrome + browser tab. */
    title: string;
    /** Ordered slide list. The viewer steps through in this order. */
    slides: Slide[];
    /** Visual theme for the whole deck. */
    theme: Theme;
    /**
     * Schema version the deck was authored against. Omitted == version 1 (the
     * implicit version for decks created before versioning). Used by the
     * serialize / parse helpers to migrate older shapes forward. Mirrors
     * `dark-slide`'s `Schema::SCHEMA_VERSION`.
     */
    version?: number;
    /** Free-form metadata — `{ author, createdAt, updatedAt, tags, … }`. */
    metadata?: Record<string, unknown>;
}

/**
 * Current deck schema version. Bump when a structural change needs migration on
 * load. Kept in lockstep with the sibling `dark-slide` PHP package.
 */
export const SCHEMA_VERSION = 1;

// ─── Slide ─────────────────────────────────────────────────────────────────

/** Layout presets that pre-populate / constrain element placement. */
export type SlideLayout =
    | "blank"            // empty canvas, free placement
    | "title"            // centered title
    | "title-content"    // title at top, content area below
    | "two-column"       // left + right halves
    | "section-divider"  // section header with subtitle
    | "image-text"       // image left, text right
    | "text-image"       // text left, image right
    | "quote";           // big centered quote

export interface Slide {
    /** Stable id. */
    id: string;
    /** Optional layout preset. Mostly used by agents — humans tend to free-place. */
    layout?: SlideLayout;
    /** Elements rendered on the slide in z-order (last on top). */
    elements: SlideElement[];
    /** Background fill — color, image, or gradient. Inherits from theme when absent. */
    background?: SlideBackground;
    /** Entrance transition for this slide. Inherits from theme.transition when absent. */
    transition?: SlideTransition;
    /** Speaker notes — markdown. */
    notes?: string;
    /**
     * Plain-text narration script for AI-narrated decks: TTS reads from
     * `narration`, presenter view shows `notes`. Opaque to the pptx writer
     * (stored as data, not rendered into the slide).
     */
    narration?: string;
    /** Free-form metadata — `{ title, tags, durationSec, … }`. */
    metadata?: Record<string, unknown>;
}

// ─── Elements ──────────────────────────────────────────────────────────────

/**
 * Every element is positioned in slide-relative coordinates (0..1). x/y are
 * the top-left corner; w/h are width/height as a fraction of the slide.
 */
export interface ElementBase {
    /** Stable id. Agents reference elements by id. */
    id: string;
    /** Element kind — discriminator. */
    type: SlideElement["type"];
    /** Left edge, 0..1 (fraction of slide width). */
    x: number;
    /** Top edge, 0..1 (fraction of slide height). */
    y: number;
    /** Width, 0..1. */
    w: number;
    /** Height, 0..1. */
    h: number;
    /** Rotation in degrees, clockwise. */
    rotation?: number;
    /** Z-order — higher renders on top. Falls back to array order when undefined. */
    z?: number;
    /** Lock from editing. */
    locked?: boolean;
    /** Hide on this slide (still in the data — for animated reveals). */
    hidden?: boolean;
    /**
     * Whole-element hyperlink. When set, the element becomes a click target in
     * the viewer (opens in a new tab) and the pptx writer emits an
     * `<a:hlinkClick>` on the shape / picture. For rich inline links *within*
     * text, use a markdown `[label](url)` in the text content instead.
     */
    href?: string;
    /** Entrance build animation — when present the element participates in the slide's build sequence. */
    animation?: ElementAnimation;
}

// ─── Element entrance animations (builds) ────────────────────────────────────

/** Visual entrance effect played when an element builds onto the slide. */
export type AnimationEffect = "fade" | "fly-in" | "zoom" | "wipe";

/** When an element's build fires relative to the surrounding builds. */
export type AnimationTrigger = "on-click" | "with-prev" | "after-prev";

/**
 * Per-element entrance animation ("build step"). Elements with an `animation`
 * start hidden and reveal as the presenter advances through the slide's build
 * sequence. The shape is shared with the sibling `dark-slide` PHP package, so
 * keep it byte-for-byte aligned.
 */
export interface ElementAnimation {
    /** Visual effect. */
    effect: AnimationEffect;
    /** When the build fires relative to its neighbours. Default `"on-click"`. */
    trigger?: AnimationTrigger;
    /** Direction for `fly-in` / `wipe`. Default `"left"`. */
    direction?: "left" | "right" | "up" | "down";
    /** Effect duration in ms. Default `500`. */
    duration?: number;
    /** Delay before the effect starts, in ms. Default `0`. */
    delay?: number;
    /** Build order within the slide, ascending; ties broken by element array index. */
    order?: number;
    /**
     * Reveal a TEXT element one paragraph/line at a time (PowerPoint/Google
     * Slides "By paragraph"). The element expands into one build per paragraph
     * — the element's `content` split on `"\n"` (a trailing empty line is
     * dropped). The first paragraph uses this animation's `trigger`; every
     * subsequent paragraph reveals on a fresh click. Only meaningful for text
     * elements; ignored for other types and when the element has 0/1 paragraphs
     * (then it behaves like a normal single build).
     */
    byParagraph?: boolean;
}

export interface TextElement extends ElementBase {
    type: "text";
    /** Content — markdown by default; can also be plain text or HTML. */
    content: string;
    /** Content format. Defaults to `"markdown"`. */
    format?: "markdown" | "html" | "plain";
    /** Typography. */
    style?: TextStyle;
}

export interface TextStyle {
    /** Font family — falls back to theme.fonts.body. */
    fontFamily?: string;
    /** Font size in px at the slide's design width (theme.slideWidth). */
    fontSize?: number;
    /** Font weight (`100..900`, or `"normal" | "bold"`). */
    weight?: "normal" | "medium" | "semibold" | "bold" | number;
    /** Horizontal alignment. */
    align?: "left" | "center" | "right" | "justify";
    /** Vertical alignment within the box. */
    verticalAlign?: "top" | "middle" | "bottom";
    /** Color (any CSS color). Falls back to theme.colors.text. */
    color?: string;
    /** Line height (multiplier). */
    lineHeight?: number;
    /** Italic. */
    italic?: boolean;
    /** Underline. */
    underline?: boolean;
}

export interface ImageElement extends ElementBase {
    type: "image";
    /** Image URL or data URI. */
    src: string;
    /** Alt text for accessibility. */
    alt?: string;
    /** How the image is fit inside its box. */
    fit?: "contain" | "cover" | "fill" | "scale-down";
    /** Optional crop window (slide-relative). */
    crop?: { x: number; y: number; w: number; h: number };
}

export interface ChartElement extends ElementBase {
    type: "chart";
    /** Apache ECharts option object. Passed straight to `<EChart>`. */
    option: Record<string, unknown>;
    /** Theme name passed to `<EChart>`. */
    chartTheme?: string;
}

export interface CodeElement extends ElementBase {
    type: "code";
    /** Source code. */
    code: string;
    /** Language alias for the highlighter. */
    language?: string;
    /** Show line numbers. Defaults to `true`. */
    lineNumbers?: boolean;
    /** Theme — `"light"`, `"dark"`, `"auto"`, or a custom registered name. */
    codeTheme?: string;
}

/**
 * One table column. `key` is what every row is keyed BY; `label` is what the
 * header shows, and falls back to `key` when absent, as dark-slide’s writer
 * resolves it.
 */
/**
 * A table cell's look: dark-slide's table cell model, drawn the same way here.
 * Precedence: cell > row > column > band (header | stripe | body) > table >
 * theme > default. `false` stops the chain and means off.
 */
export interface TableCellStyle {
    fill?: string | false;
    color?: string;
    bold?: boolean;
    italic?: boolean;
    underline?: boolean;
    align?: "left" | "center" | "right" | "justify";
    anchor?: "top" | "middle" | "bottom";
    /** Design px, scaled like text. */
    fontSize?: number;
    fontFamily?: string;
    /** `false` for none, or one rule for every side: `{ color, width }` (width in design px). */
    borders?: false | { color?: string; width?: number };
}

export interface TableColumn extends TableCellStyle {
    key: string;
    label?: string;
    /** A fraction of the table (all widths <= 1) or a weight. */
    width?: number;
}

/** A cell given as an object: its text plus its own style. */
export interface TableCell extends TableCellStyle {
    text: string;
}

export interface TableStyle extends TableCellStyle {
    /** The header row's band (default: theme accent, white, bold); `false` for no header row. */
    header?: TableCellStyle | false;
    /** Every second body row's band (default: theme surface); `false` for none. */
    stripe?: TableCellStyle | false;
    /** Every body row's band. */
    body?: TableCellStyle;
}

/**
 * One table row: an object keyed by each column’s `key`, or the values in COLUMN
 * ORDER.
 *
 * The keyed form is canonical — it survives a column reorder, and it is the only
 * one that can also carry row-level style for the pptx writer. The positional
 * form is accepted because it is what an author guesses from a bare column list,
 * and guessing it used to render a full-size grid with every cell blank and
 * nothing logged (#14).
 */
export type TableRow = Record<string, unknown> | unknown[];

export interface TableElement extends ElementBase {
    type: "table";
    /** Column definitions — `{ key, label }`. */
    columns: TableColumn[];
    /** Row data — objects keyed by column `key`, or values in column order. A value is text or a `TableCell`. */
    rows: TableRow[];
    /** The table's look, as dark-slide writes it. */
    style?: TableStyle;
}

export type ShapeKind = "rect" | "rounded-rect" | "ellipse" | "line" | "arrow" | "triangle";

export interface ShapeElement extends ElementBase {
    type: "shape";
    shape: ShapeKind;
    /** Fill color (any CSS color, or `"none"`). */
    fill?: string;
    /** Stroke color. */
    stroke?: string;
    /** Stroke width in px at the slide's design width. */
    strokeWidth?: number;
    /** Dashed stroke. */
    dashed?: boolean;
    /**
     * Corner radius for `rounded-rect`, in px at the slide's design width (default 8),
     * capped at half the shorter side. A plain `rect` has square corners.
     */
    radius?: number;
}

export interface EmbedElement extends ElementBase {
    type: "embed";
    /** Embed URL — typically a video, dashboard, or fancy-screens Screen. */
    src: string;
    /** iframe `title` for accessibility. */
    title?: string;
    /** Sandbox attribute. Defaults to allow-scripts (no allow-same-origin). */
    sandbox?: string;
}

export type SlideElement =
    | TextElement
    | ImageElement
    | ChartElement
    | CodeElement
    | TableElement
    | ShapeElement
    | EmbedElement;

// ─── Background, transitions, theme ────────────────────────────────────────

export interface SlideBackground {
    /** Solid color, or `"transparent"` to inherit theme. */
    color?: string;
    /** Image background URL. Takes precedence over color when present. */
    image?: string;
    /** How the background image is fit. Defaults to `"cover"`. */
    imageFit?: "contain" | "cover" | "fill";
    /** Optional gradient — `"linear-gradient(...)"` or `"radial-gradient(...)"` string. */
    gradient?: string;
}

export type TransitionKind = "none" | "fade" | "slide" | "zoom";

export interface SlideTransition {
    kind: TransitionKind;
    /** Duration in ms. */
    duration?: number;
    /** Direction for `slide` transitions. */
    direction?: "left" | "right" | "up" | "down";
}

export interface Theme {
    /** Theme name — used for serialization + agent routing. */
    name: string;
    /** Aspect ratio — defaults to 16:9. Custom themes can pick anything. */
    aspectRatio?: number;
    /** Design width in px. Slides scale to fit; this just sets the unit base for fontSize/strokeWidth. */
    slideWidth?: number;
    colors?: ThemeColors;
    fonts?: ThemeFonts;
    /** Default transition for slides that don't specify their own. */
    defaultTransition?: SlideTransition;
}

export interface ThemeColors {
    background?: string;
    text?: string;
    muted?: string;
    accent?: string;
    surface?: string;
}

export interface ThemeFonts {
    /** Used for `Heading`-like text elements (the default for large fontSize). */
    heading?: string;
    /** Used for body text. */
    body?: string;
    /** Used by CodeElement. */
    mono?: string;
}

// ─── Agent / Human+ surface ────────────────────────────────────────────────

/**
 * Agent activity broadcast whenever the deck mutates. Hosts subscribe to feed
 * an AgentPanel, presence layer, or audit log.
 */
export interface DeckActivity {
    /** Stable activity id. */
    id: string;
    /** Wall-clock timestamp. */
    at: number;
    /** Who made the change. */
    actor: { kind: "human" | "agent"; id: string; name?: string; color?: string };
    /** What changed. */
    op: DeckOp;
}

/**
 * The canonical, language-neutral deck operation vocabulary (v0.13+).
 *
 * Every op is a flat JSON object discriminated by a dotted `op` string. The
 * shape is deliberately language-neutral so the *same* op contract is shared
 * with the sibling `dark-slide` PHP package: an op emitted by `<DeckEditor>` in
 * the browser can be reduced server-side by `DarkSlide\Reducer::apply()`, and a
 * server-computed `DarkSlide\Agent::diff()` replays in the editor — one
 * vocabulary, one reducer per authoritative host. Published as a JSON Schema via
 * {@link deckOpSchema} so any backend can validate it.
 *
 * Ids are always named `slideId` / `elementId` (never a bare `id`), and `op`
 * names are `subject.verb` in camelCase. Migrating from the pre-0.13
 * `kind`-flavored ops: {@link mapLegacyOp}.
 */
export type DeckOp =
    | { op: "deck.setTitle"; title: string }
    | { op: "deck.setTheme"; theme: Theme }
    /** Replace the entire deck atomically — stream a full presentation IN in one op. */
    | { op: "deck.replace"; deck: Deck }
    | { op: "slide.add"; index: number; slide: Slide }
    | { op: "slide.remove"; slideId: string }
    | { op: "slide.reorder"; slideId: string; toIndex: number }
    | { op: "slide.setLayout"; slideId: string; layout: SlideLayout }
    | { op: "slide.setNotes"; slideId: string; notes: string }
    | { op: "slide.setBackground"; slideId: string; background?: SlideBackground }
    | { op: "slide.setTransition"; slideId: string; transition?: SlideTransition }
    | { op: "element.add"; slideId: string; element: SlideElement }
    | { op: "element.remove"; slideId: string; elementId: string }
    | { op: "element.update"; slideId: string; elementId: string; patch: Partial<SlideElement> }
    | { op: "element.move"; slideId: string; elementId: string; x: number; y: number }
    | { op: "element.resize"; slideId: string; elementId: string; w: number; h: number }
    | { op: "element.setAnimation"; slideId: string; elementId: string; animation?: ElementAnimation };

/** The dotted `op` discriminator of every {@link DeckOp}. */
export type DeckOpType = DeckOp["op"];

/**
 * The pre-0.13 `kind`-flavored op vocabulary. Retained so existing consumers can
 * map their stored/streamed ops forward with {@link mapLegacyOp}. Prefer
 * {@link DeckOp} in new code.
 *
 * @deprecated Use {@link DeckOp}; convert with {@link mapLegacyOp}.
 */
export type LegacyDeckOp =
    | { kind: "deck_set_title"; title: string }
    | { kind: "deck_apply_theme"; theme: Theme }
    | { kind: "deck_set"; deck: Deck }
    | { kind: "slide_add"; index: number; slide: Slide }
    | { kind: "slide_remove"; id: string }
    | { kind: "slide_reorder"; id: string; toIndex: number }
    | { kind: "slide_set_layout"; id: string; layout: SlideLayout }
    | { kind: "slide_set_notes"; id: string; notes: string }
    | { kind: "slide_set_background"; id: string; background?: SlideBackground }
    | { kind: "slide_set_transition"; id: string; transition?: SlideTransition }
    | { kind: "element_add"; slideId: string; element: SlideElement }
    | { kind: "element_remove"; slideId: string; elementId: string }
    | { kind: "element_update"; slideId: string; elementId: string; patch: Partial<SlideElement> }
    | { kind: "element_move"; slideId: string; elementId: string; x: number; y: number }
    | { kind: "element_resize"; slideId: string; elementId: string; w: number; h: number }
    | { kind: "element_set_animation"; slideId: string; elementId: string; animation?: ElementAnimation };

import {
  forwardRef,
  useCallback,
  useRef,
  useState,
  type CSSProperties,
} from "react";
import { cn } from "../lib/utils/cn";
import { usePanZoom } from "../lib/hooks/use-pan-zoom";
import type { ImageViewerProps, ImageViewerViewport } from "./ImageViewer.types";

const DEFAULT_VIEWPORT: ImageViewerViewport = { panX: 0, panY: 0, zoom: 1 };

const fitClasses: Record<NonNullable<ImageViewerProps["fit"]>, string> = {
  contain: "h-full w-full object-contain",
  cover: "h-full w-full object-cover",
  none: "max-w-none object-none",
};

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n));
}

/**
 * A standalone image viewer: fits the image to its container, with optional
 * Ctrl/⌘+wheel zoom, click-drag panning, and a transparency checkerboard. Works
 * anywhere on its own and is also what `<MediaViewer>` renders for images.
 *
 * The pan/zoom viewport is controllable (`viewport` + `onViewportChange`) so an
 * agent bridge can drive it; it's uncontrolled by default.
 *
 * ```tsx
 * <ImageViewer src="/logo.png" alt="logo.png" style={{ height: 320 }} />
 * ```
 */
export const ImageViewer = forwardRef<HTMLDivElement, ImageViewerProps>(
  (
    {
      src,
      alt = "",
      fit = "contain",
      zoomable = true,
      pannable = true,
      controls,
      minZoom = 0.25,
      maxZoom = 8,
      checkerboard = true,
      viewport,
      defaultViewport,
      onViewportChange,
      onLoad,
      onError,
      className,
      style,
    },
    ref,
  ) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [status, setStatus] = useState<"loading" | "loaded" | "error">("loading");

    // Controllable viewport supporting functional updates (usePanZoom needs them).
    const isControlled = viewport !== undefined;
    const [internal, setInternal] = useState<ImageViewerViewport>(
      defaultViewport ?? DEFAULT_VIEWPORT,
    );
    const current = isControlled ? viewport! : internal;
    const currentRef = useRef(current);
    currentRef.current = current;

    const setViewport = useCallback(
      (
        next:
          | ImageViewerViewport
          | ((prev: ImageViewerViewport) => ImageViewerViewport),
      ) => {
        const resolved =
          typeof next === "function" ? next(currentRef.current) : next;
        if (!isControlled) setInternal(resolved);
        onViewportChange?.(resolved);
      },
      [isControlled, onViewportChange],
    );

    const interactive = status === "loaded";
    const { containerProps, isPanning } = usePanZoom({
      viewport: current,
      setViewport,
      minZoom,
      maxZoom,
      pannable: pannable && interactive,
      zoomable: zoomable && interactive,
      containerRef,
    });

    // Zoom about the container centre — used by the +/− buttons.
    const zoomBy = useCallback(
      (factor: number) => {
        const el = containerRef.current;
        if (!el) return;
        const rect = el.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        setViewport((prev) => {
          const newZoom = clamp(prev.zoom * factor, minZoom, maxZoom);
          const ratio = newZoom / prev.zoom;
          return {
            zoom: newZoom,
            panX: cx - (cx - prev.panX) * ratio,
            panY: cy - (cy - prev.panY) * ratio,
          };
        });
      },
      [setViewport, minZoom, maxZoom],
    );

    const reset = useCallback(() => setViewport(DEFAULT_VIEWPORT), [setViewport]);

    const showControls = (controls ?? zoomable) && interactive;
    const transform = `translate(${current.panX}px, ${current.panY}px) scale(${current.zoom})`;

    return (
      <div
        ref={ref}
        data-react-fancy-image-viewer=""
        className={cn(
          "relative isolate overflow-hidden rounded-md select-none",
          checkerboard
            ? "fancy-checkerboard"
            : "bg-zinc-100 dark:bg-zinc-900",
          className,
        )}
        style={style}
      >
        <div
          ref={containerRef}
          data-canvas-bg=""
          className={cn(
            "absolute inset-0 flex items-center justify-center",
            isPanning
              ? "cursor-grabbing"
              : pannable && interactive
                ? "cursor-grab"
                : "",
          )}
          style={
            {
              transform,
              transformOrigin: "0 0",
              willChange: "transform",
              touchAction: zoomable || pannable ? "none" : undefined,
            } as CSSProperties
          }
          onDoubleClick={zoomable ? reset : undefined}
          {...containerProps}
        >
          <img
            src={src}
            alt={alt}
            draggable={false}
            onLoad={() => {
              setStatus("loaded");
              onLoad?.();
            }}
            onError={() => {
              setStatus("error");
              onError?.();
            }}
            className={cn(
              "pointer-events-none block",
              status === "error" && "hidden",
              fitClasses[fit],
            )}
          />
        </div>

        {status === "error" && (
          <div
            data-react-fancy-image-viewer-error=""
            className="absolute inset-0 flex flex-col items-center justify-center gap-1 p-4 text-center text-sm text-zinc-500 dark:text-zinc-400"
          >
            <span className="font-medium">Couldn&apos;t load image</span>
            <span className="max-w-full truncate text-xs opacity-70">{alt || src}</span>
          </div>
        )}

        {showControls && (
          <div
            data-react-fancy-image-viewer-controls=""
            className="absolute bottom-2 right-2 flex items-center gap-0.5 rounded-md border border-zinc-200 bg-white/90 p-0.5 text-zinc-700 shadow-sm backdrop-blur dark:border-zinc-700 dark:bg-zinc-900/90 dark:text-zinc-200"
          >
            <button
              type="button"
              aria-label="Zoom out"
              onClick={() => zoomBy(1 / 1.25)}
              className="flex h-6 w-6 items-center justify-center rounded text-base leading-none hover:bg-zinc-100 dark:hover:bg-zinc-800"
            >
              −
            </button>
            <button
              type="button"
              aria-label="Reset zoom"
              onClick={reset}
              className="min-w-[3rem] rounded px-1 text-center text-xs tabular-nums hover:bg-zinc-100 dark:hover:bg-zinc-800"
            >
              {Math.round(current.zoom * 100)}%
            </button>
            <button
              type="button"
              aria-label="Zoom in"
              onClick={() => zoomBy(1.25)}
              className="flex h-6 w-6 items-center justify-center rounded text-base leading-none hover:bg-zinc-100 dark:hover:bg-zinc-800"
            >
              +
            </button>
          </div>
        )}
      </div>
    );
  },
);

ImageViewer.displayName = "ImageViewer";

import type { CSSProperties } from "react";

/** Pan offset (in container pixels) + zoom factor for an `<ImageViewer>`. */
export interface ImageViewerViewport {
  panX: number;
  panY: number;
  zoom: number;
}

export interface ImageViewerProps {
  /** Image source — an `http(s):`, `data:`, or `blob:` URL. */
  src: string;
  /** Alt text for the image (also used as the download filename hint). */
  alt?: string;
  /**
   * How the image sits in its container at zoom 1. `"contain"` (default) fits
   * the whole image, `"cover"` fills and crops, `"none"` shows it at natural
   * size (pan to see the rest).
   */
  fit?: "contain" | "cover" | "none";
  /** Allow Ctrl/⌘+wheel zoom and the zoom controls (default `true`). */
  zoomable?: boolean;
  /** Allow click-drag panning (default `true`). */
  pannable?: boolean;
  /** Show the floating zoom controls. Defaults to the value of `zoomable`. */
  controls?: boolean;
  /** Minimum zoom factor (default `0.25`). */
  minZoom?: number;
  /** Maximum zoom factor (default `8`). */
  maxZoom?: number;
  /**
   * Paint a checkerboard behind the image so transparency reads clearly
   * (default `true`). Set `false` for a flat themed surface.
   */
  checkerboard?: boolean;
  /**
   * Controlled viewport (pan + zoom). Pair with `onViewportChange`. Omit for
   * uncontrolled internal state. Exposed so an agent can pan/zoom to point at
   * something via a bridge.
   */
  viewport?: ImageViewerViewport;
  /** Initial viewport when uncontrolled. */
  defaultViewport?: ImageViewerViewport;
  /** Called whenever the viewport (pan/zoom) changes. */
  onViewportChange?: (viewport: ImageViewerViewport) => void;
  /** Fired when the image finishes loading. */
  onLoad?: () => void;
  /** Fired when the image fails to load. */
  onError?: () => void;
  /** Additional CSS classes for the viewport container. */
  className?: string;
  /** Inline styles for the viewport container (e.g. a fixed height). */
  style?: CSSProperties;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useCallback, useEffect, useRef } from "react";

export interface ViewportState {
  panX: number;
  panY: number;
  zoom: number;
}

interface UsePanZoomOptions {
  viewport: ViewportState;
  setViewport: (vp: ViewportState | ((prev: ViewportState) => ViewportState)) => void;
  minZoom: number;
  maxZoom: number;
  pannable: boolean;
  zoomable: boolean;
  containerRef: React.RefObject<HTMLElement | null>;
}

interface UsePanZoomReturn {
  containerProps: {
    onPointerDown: (e: React.PointerEvent) => void;
    onPointerMove: (e: React.PointerEvent) => void;
    onPointerUp: (e: React.PointerEvent) => void;
  };
  isPanning: boolean;
}

export function usePanZoom({
  viewport,
  setViewport,
  minZoom,
  maxZoom,
  pannable,
  zoomable,
  containerRef,
}: UsePanZoomOptions): UsePanZoomReturn {
  const isPanningRef = useRef(false);
  const startRef = useRef({ x: 0, y: 0, panX: 0, panY: 0 });

  // Store latest values in refs so the native wheel listener always sees current state
  const viewportRef = useRef(viewport);
  viewportRef.current = viewport;
  const setViewportRef = useRef(setViewport);
  setViewportRef.current = setViewport;
  const zoomableRef = useRef(zoomable);
  zoomableRef.current = zoomable;
  const minZoomRef = useRef(minZoom);
  minZoomRef.current = minZoom;
  const maxZoomRef = useRef(maxZoom);
  maxZoomRef.current = maxZoom;

  // Attach a non-passive wheel listener so preventDefault() actually stops page scroll
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    function handleWheel(e: WheelEvent) {
      if (!zoomableRef.current) return;
      // Require Ctrl+wheel (or pinch gesture) to zoom — don't hijack normal page scroll
      if (!e.ctrlKey && !e.metaKey) return;
      e.preventDefault();

      const rect = container!.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      setViewportRef.current((prev) => {
        const factor = 1 - e.deltaY * 0.001;
        const newZoom = Math.min(maxZoomRef.current, Math.max(minZoomRef.current, prev.zoom * factor));
        const ratio = newZoom / prev.zoom;

        return {
          zoom: newZoom,
          panX: mouseX - (mouseX - prev.panX) * ratio,
          panY: mouseY - (mouseY - prev.panY) * ratio,
        };
      });
    }

    container.addEventListener("wheel", handleWheel, { passive: false });
    return () => {
      container.removeEventListener("wheel", handleWheel);
    };
  }, [containerRef]);

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (!pannable) return;
      // Only pan on primary button and when clicking the background
      if (e.button !== 0) return;
      const target = e.target as HTMLElement;
      if (target !== containerRef.current && !target.hasAttribute("data-canvas-bg")) return;

      isPanningRef.current = true;
      startRef.current = { x: e.clientX, y: e.clientY, panX: viewport.panX, panY: viewport.panY };
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      e.preventDefault();
    },
    [pannable, viewport.panX, viewport.panY, containerRef],
  );

  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isPanningRef.current) return;
      const dx = e.clientX - startRef.current.x;
      const dy = e.clientY - startRef.current.y;
      setViewport((prev) => ({
        ...prev,
        panX: startRef.current.panX + dx,
        panY: startRef.current.panY + dy,
      }));
    },
    [setViewport],
  );

  const onPointerUp = useCallback(() => {
    isPanningRef.current = false;
  }, []);

  return {
    containerProps: { onPointerDown, onPointerMove, onPointerUp },
    isPanning: isPanningRef.current,
  };
}

import { forwardRef } from "react";
import { cn } from "../lib/utils/cn";
import type { IndexListProps } from "./IndexList.types";

/**
 * A flush-left numbered index — `num · title · meta · trailing value`, each row
 * optionally a single clickable target.
 *
 * Thirteen gallery styles build this, and the sandbox uses a `stretched-link`
 * treatment in twenty-four places.
 *
 * ## Exactly one anchor per row, by construction
 *
 * The row is `relative` and the title's `<a>` carries `after:absolute
 * after:inset-0`, so the anchor's own pseudo-element covers the row. The
 * alternative — wrapping the row in an `<a>` and putting more links inside —
 * produces nested anchors, which is issue #418: the browser silently
 * restructures that DOM, so the server HTML and the client tree disagree and
 * hydration blows up. A test asserts one anchor per row for that reason.
 *
 * The link text stays the title rather than becoming an `aria-label` on an
 * invisible overlay, so the accessible name is the thing you would say out loud.
 */
export const IndexList = forwardRef<HTMLOListElement, IndexListProps>(
  ({ items, linkAs, className, ...props }, ref) => {
    const Link = linkAs ?? "a";

    return (
      <ol ref={ref} data-react-fancy-index-list="" className={cn("m-0 list-none p-0", className)} {...props}>
        {items.map((item, i) => (
          <li
            key={item.id ?? i}
            data-react-fancy-index-row=""
            className="relative flex items-baseline gap-4 border-b border-zinc-200 py-3 last:border-b-0 dark:border-zinc-800"
          >
            {item.num != null && (
              <span data-react-fancy-index-num="" className="shrink-0 font-mono text-xs tabular-nums text-zinc-400 dark:text-zinc-500">
                {item.num}
              </span>
            )}

            <span data-react-fancy-index-title="" className="min-w-0 flex-1 truncate font-medium text-zinc-900 dark:text-zinc-100">
              {item.href ? (
                <Link
                  href={item.href}
                  className="no-underline after:absolute after:inset-0 after:content-[''] hover:underline"
                >
                  {item.title}
                </Link>
              ) : (
                item.title
              )}
            </span>

            {item.meta != null && (
              <span data-react-fancy-index-meta="" className="shrink-0 truncate text-sm text-zinc-500 dark:text-zinc-400">{item.meta}</span>
            )}

            {item.value != null && (
              <span data-react-fancy-index-value="" className="ml-auto shrink-0 font-mono text-xs tabular-nums text-zinc-500 dark:text-zinc-400">
                {item.value}
              </span>
            )}
          </li>
        ))}
      </ol>
    );
  },
);

IndexList.displayName = "IndexList";

import type { HTMLAttributes, ReactNode } from "react";

export interface IndexListItem {
  /** Row marker — `"01"`, `"1."`. Rendered tabular so the column aligns. */
  num?: ReactNode;
  /** The row's subject, and the link text when `href` is set. */
  title: ReactNode;
  /** Secondary text after the title. */
  meta?: ReactNode;
  /** Trailing value, pushed to the far end — a year, a count. */
  value?: ReactNode;
  /** Makes the whole row clickable. See the note on nested anchors. */
  href?: string;
  /** Stable key. Defaults to the index. */
  id?: string;
}

export interface IndexListProps extends Omit<HTMLAttributes<HTMLOListElement>, "children"> {
  items: IndexListItem[];
  /**
   * Render an `<a>` for `href`. Pass your router's link (Inertia `Link`,
   * `next/link`) to keep client-side navigation. It receives `href`,
   * `className` and `children`.
   */
  linkAs?: React.ElementType;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { forwardRef, useId, useMemo, useRef } from "react";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { useAdornmentWidth } from "../lib/hooks/use-adornment-width";
import { Field } from "../field";
import { InputWrapper } from "../lib/components/inputs/InputWrapper";
import {
  dirtyClasses,
  errorClasses,
  inputBaseClasses,
  inputSizeClasses,
} from "../lib/components/inputs/inputs.utils";
import { useFieldMode } from "../lib/components/inputs/mode/FieldMode.context";
import { DisplayValue } from "../lib/components/inputs/mode/DisplayValue";
import { useInlineEdit } from "../lib/components/inputs/mode/useInlineEdit";
import {
  InlinePasteEditor,
  PastedFilesInput,
  useInlinePaste,
  type InlinePasteEditorHandle,
} from "../paste-pills";
import type { InputProps } from "./Input.types";

export const Input = forwardRef<HTMLInputElement, InputProps>(
  (
    {
      type = "text",
      size = "md",
      dirty,
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      leading,
      trailing,
      prefix,
      suffix,
      prefixPosition,
      suffixPosition,
      mode,
      onValueChange,
      onChange,
      reveal,
      revealed,
      onRevealedChange,
      revealLabel = "Show password",
      hideLabel = "Hide password",
      pasteThreshold,
      pasteImages = false,
      pasteFilesName,
      previewChars = 20,
      renderPastePreview,
      pasteClassNames,
      heldPastes,
      onHeldPastesChange,
      heldImages,
      onHeldImagesChange,
      ...props
    },
    ref,
  ) => {
    const autoId = useId();
    const inputId = id ?? autoId;
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);

    // Measured, not assumed: `leading`/`trailing` take arbitrary content, and a
    // fixed padding can only ever be right for one width. See
    // `useAdornmentWidth` for what went wrong with the fixed version.
    const [leadingRef, leadingWidth] = useAdornmentWidth();
    const [trailingRef, trailingWidth] = useAdornmentWidth();

    // Only meaningful on a password field: a reveal on an already-visible input
    // is a button that does nothing.
    const canReveal = reveal === true && type === "password";
    const [isRevealed, setRevealed] = useControllableState(revealed, false, onRevealedChange);
    const shown = canReveal && isRevealed;
    // The rendered type, NOT the declared one — `type` stays "password" so the
    // display-mode masking below and any caller reading props are unaffected.
    const renderedType = shown ? "text" : type;

    /*
     * Paste pills: the same core `Composer` and `PromptInput` use, so the three
     * cannot disagree about what a pill holds or what a send carries. Hooks run
     * whether or not it is on (Rules of Hooks); nothing is rendered unless asked.
     */
    const pasting = pasteThreshold !== undefined || pasteImages;
    const editorRef = useRef<InlinePasteEditorHandle>(null);
    const hiddenRef = useRef<HTMLInputElement | null>(null);
    const paste = useInlinePaste({
      pasteThreshold,
      pasteImages,
      previewChars,
      renderPastePreview,
      classNames: pasteClassNames,
      disabled: disabled === true,
      heldPastes,
      onHeldPastesChange,
      heldImages,
      onHeldImagesChange,
      editorRef,
      blockText: false,
    });
    const [pasteValue, setPasteValue] = useControllableState<string>(
      props.value === undefined ? undefined : String(props.value),
      props.defaultValue === undefined ? "" : String(props.defaultValue),
      onValueChange,
    );
    const filesName = pasteFilesName ?? (props.name ? `${props.name}_files[]` : undefined);
    const pastedFiles = useMemo(
      () => (pasteImages ? paste.imagesIn(pasteValue).map((i) => i.file) : []),
      [pasteImages, paste, pasteValue],
    );
    const labelId = `${inputId}-label`;

    const input = !showControl ? (
      <DisplayValue
        size={size}
        interactive={interactive}
        onActivate={enterEdit}
        leading={leading ?? prefix}
        trailing={trailing ?? suffix}
      >
        {type === "password" ? (props.value ? "••••••" : "") : (props.value as string | undefined)}
      </DisplayValue>
    ) : (
      <InputWrapper
        prefix={prefix}
        suffix={suffix}
        prefixPosition={prefixPosition}
        suffixPosition={suffixPosition}
        size={size}
      >
        <div data-react-fancy-input="" className="relative flex items-center">
          {leading && (
            <span
              ref={leadingRef}
              className="pointer-events-none absolute left-3 text-zinc-400 dark:text-zinc-500"
            >
              {leading}
            </span>
          )}
          {pasting ? (
            <>
              <div className="min-w-0 flex-1">
                <InlinePasteEditor
                  ref={editorRef}
                  id={inputId}
                  value={pasteValue}
                  known={paste.known}
                  onChange={(next) => {
                    setPasteValue(next);
                    paste.prune(next);
                  }}
                  // Enter in a text field submits its form; keep that.
                  onSubmit={() => hiddenRef.current?.form?.requestSubmit()}
                  multiline={false}
                  onPaste={paste.decidePaste}
                  onHostsChange={paste.onHostsChange}
                  placeholder={props.placeholder ?? ""}
                  disabled={disabled === true}
                  ariaLabelledBy={label ? labelId : props["aria-labelledby"]}
                  ariaInvalid={Boolean(error)}
                  placeholderClassName={cn(pastePlaceholderClasses[size], leading ? "left-9" : undefined)}
                  style={{
                    ...(leadingWidth ? { paddingLeft: leadingWidth + 20 } : null),
                    ...(trailingWidth ? { paddingRight: trailingWidth + 20 } : null),
                  }}
                  className={cn(
                    inputBaseClasses,
                    inputSizeClasses[size],
                    dirtyClasses(dirty),
                    errorClasses(error),
                    // One line, like the <input> it stands in for.
                    "min-h-0 max-h-none w-full overflow-x-auto overflow-y-hidden whitespace-nowrap break-normal",
                    leading && !leadingWidth && "pl-9",
                    trailing && !trailingWidth && "pr-9",
                    className,
                    pasteClassNames?.input,
                  )}
                />
              </div>
              {paste.portals}
              {/* What a native submit posts: the value with every pill expanded. */}
              <input
                ref={(el) => {
                  hiddenRef.current = el;
                  if (typeof ref === "function") ref(el);
                  else if (ref) ref.current = el;
                }}
                type="hidden"
                name={props.name}
                form={props.form}
                value={paste.expand(pasteValue)}
              />
              {pasteImages && filesName && (
                <PastedFilesInput name={filesName} files={pastedFiles} form={props.form} />
              )}
            </>
          ) : (
            <input
              ref={ref}
              id={inputId}
              type={renderedType}
              disabled={disabled}
              required={required}
              className={cn(
                inputBaseClasses,
                inputSizeClasses[size],
                dirtyClasses(dirty),
                errorClasses(error),
                "w-full",
                // The fixed classes are the PRE-MEASURE fallback only. Once the
                // adornment is measured, the inline style below overrides them
                // with its real width -- a fixed 36px is correct for one icon and
                // wrong for anything wider, which is how `https://` came to
                // render on top of the value.
                leading && !leadingWidth && "pl-9",
                (trailing || canReveal) && !trailingWidth && "pr-9",
                className,
              )}
              style={{
                // 12px clears `left-3`/`right-3`; 8px is the gap to the text.
                ...(leadingWidth ? { paddingLeft: leadingWidth + 20 } : null),
                ...(trailingWidth ? { paddingRight: trailingWidth + 20 } : null),
                ...props.style,
              }}
              onChange={(e) => {
                onChange?.(e);
                onValueChange?.(e.target.value);
              }}
              {...props}
              // Inline click-to-edit: focus on entering edit, return to the display
              // (and run the host's onBlur) when focus leaves.
              autoFocus={interactive || props.autoFocus}
              onBlur={(e) => {
                props.onBlur?.(e);
                if (interactive) exitEdit();
              }}
            />
          )}
          {canReveal ? (
            <button
              type="button"
              // type="button" is load-bearing: the default is "submit", so a
              // reveal inside a login form would submit it on every click.
              id={`${inputId}-reveal`}
              data-react-fancy-reveal=""
              onClick={() => setRevealed((v) => !v)}
              disabled={disabled}
              aria-controls={inputId}
              aria-pressed={shown}
              aria-label={shown ? hideLabel : revealLabel}
              title={shown ? hideLabel : revealLabel}
              // Not focusable by tab: the field and the submit button are the
              // path through a login form, and a reveal in between is a stop
              // most people do not want. Still reachable by click and by
              // screen readers.
              tabIndex={-1}
              className="absolute right-2 inline-flex items-center justify-center rounded p-1 text-zinc-400 transition-colors hover:text-zinc-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500/40 disabled:cursor-not-allowed disabled:opacity-50 dark:text-zinc-500 dark:hover:text-zinc-300"
            >
              {shown ? <EyeOffIcon /> : <EyeIcon />}
            </button>
          ) : (
            trailing && (
              <span
                ref={trailingRef}
                className="pointer-events-none absolute right-3 text-zinc-400 dark:text-zinc-500"
              >
                {trailing}
              </span>
            )
          )}
        </div>
      </InputWrapper>
    );

    if (label || error || description) {
      return (
        <Field
          label={label}
          labelId={pasting ? labelId : undefined}
          labelHidden={labelHidden}
          description={description}
          error={error}
          required={required}
          htmlFor={inputId}
          size={size}
        >
          {input}
        </Field>
      );
    }

    return input;
  },
);

Input.displayName = "Input";

/** Where the placeholder sits over the paste editor, matching `inputSizeClasses`. */
const pastePlaceholderClasses = {
  xs: "left-2 top-1 text-xs",
  sm: "left-2.5 top-1.5 text-sm",
  md: "left-3 top-2 text-sm",
  lg: "left-4 top-2.5 text-base",
  xl: "left-5 top-3 text-lg",
} as const;

/**
 * Inline SVGs rather than the Icon component: Input is the most-installed
 * primitive in the kit, and routing it through the icon registry would make
 * every consumer's password field depend on an icon set being configured.
 */
function EyeIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0" />
      <circle cx="12" cy="12" r="3" />
    </svg>
  );
}

function EyeOffIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M10.733 5.076a10.744 10.744 0 0 1 11.205 6.575 1 1 0 0 1 0 .696 10.747 10.747 0 0 1-1.444 2.49" />
      <path d="M14.084 14.158a3 3 0 0 1-4.242-4.242" />
      <path d="M17.479 17.499a10.75 10.75 0 0 1-15.417-5.151 1 1 0 0 1 0-.696 10.75 10.75 0 0 1 4.446-5.143" />
      <path d="m2 2 20 20" />
    </svg>
  );
}

import type { InputHTMLAttributes, ReactNode } from "react";
import type { InputBaseProps, InputAffixProps } from "../lib/components/inputs/inputs.types";
import type {
  ComposerPasteClassNames,
  ComposerPastePreview,
  HeldImage,
  HeldPaste,
} from "../paste-pills";

export interface InputProps
  extends InputBaseProps,
    InputAffixProps,
    Omit<InputHTMLAttributes<HTMLInputElement>, "size" | "type" | "prefix"> {
  type?: "text" | "email" | "password" | "number" | "tel" | "url" | "search";
  onValueChange?: (value: string) => void;
  leading?: ReactNode;
  trailing?: ReactNode;
  /**
   * Show a toggle that reveals the value, for `type="password"`.
   *
   * Ignored on other input types — a reveal on a field that is already visible
   * is a button that does nothing.
   *
   * It occupies the trailing slot, so it replaces `trailing` when both are set:
   * the two would otherwise stack in the same corner, and the reveal is the one
   * a person needs to click.
   */
  reveal?: boolean;
  /** Controlled reveal state. Omit to let the input own it. */
  revealed?: boolean;
  onRevealedChange?: (revealed: boolean) => void;
  /** Accessible label for the toggle. Defaults to "Show password" / "Hide password". */
  revealLabel?: string;
  hideLabel?: string;
  /**
   * Hold a paste of at least this many characters as a pill in the field, as
   * `Composer` and `PromptInput` do — same code, from `PastePills`. Try 500.
   *
   * **Omit it (and `pasteImages`) and this is a plain `<input>`, exactly as
   * before.** Setting either swaps it for a single-line editor that can hold a
   * pill, plus a hidden `<input name={name}>` that posts the value with every pill
   * expanded, so a native form submit sends the whole paste. `ref` then points at
   * that hidden input; `onValueChange` receives the value with a marker for each
   * pill (see `pasteMarker`), and `onChange` is not called.
   */
  pasteThreshold?: number;
  /**
   * Hold a pasted image as a pill, and put the file in a hidden
   * `<input type="file" multiple>` in the same form so a submit posts it. The text
   * marks where it sat as `[Pasted image N]`.
   */
  pasteImages?: boolean;
  /**
   * The field name pasted files are posted under. Defaults to `{name}_files[]`
   * (an array for PHP / Laravel); without either, the files are held but not
   * posted.
   */
  pasteFilesName?: string;
  /** Characters of a held paste shown at EACH end of its hover preview. Default 20. */
  previewChars?: number;
  renderPastePreview?: (preview: ComposerPastePreview) => ReactNode;
  pasteClassNames?: ComposerPasteClassNames;
  /** The held pastes and images, if you want to own them (an agent attaching one, a restored draft). */
  heldPastes?: HeldPaste[];
  onHeldPastesChange?: (pastes: HeldPaste[]) => void;
  heldImages?: HeldImage[];
  onHeldImagesChange?: (images: HeldImage[]) => void;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import { useCallback, useEffect, useState } from "react";

/**
 * Measure an inline adornment so the input can reserve exactly its width.
 *
 * ## Why this exists
 *
 * `leading` / `trailing` render ABSOLUTELY over the input, so they take no
 * space in flow and the input must be padded by hand to keep text clear of
 * them. That padding used to be a fixed `pl-9` / `pr-9` — 36px, sized for a
 * single icon. Any wider adornment ran straight under the value: `leading =
 * "https://"` is roughly 50px, so `https://` and `fancy.app` rendered on top of
 * one another.
 *
 * A fixed padding cannot be right for arbitrary content, and these props accept
 * arbitrary content — a currency code, a unit, a protocol, a short label. So
 * the width is measured rather than assumed.
 *
 * Returns `0` until measured (and on the server), which is the signal to keep
 * the old fixed padding as a fallback: an unmeasured render is then no worse
 * than it was before, rather than unpadded.
 *
 * `ResizeObserver` rather than a one-shot read, because the width changes after
 * first paint for reasons the first paint cannot see — a webfont swapping in,
 * the adornment's own content changing, a container query resizing the text.
 */
export function useAdornmentWidth(): [(node: HTMLElement | null) => void, number] {
  const [width, setWidth] = useState(0);
  const [node, setNode] = useState<HTMLElement | null>(null);

  const ref = useCallback((n: HTMLElement | null) => setNode(n), []);

  useEffect(() => {
    if (!node) {
      setWidth(0);

      return;
    }

    const read = () => setWidth(node.getBoundingClientRect().width);
    read();

    if (typeof ResizeObserver === "undefined") return;

    const observer = new ResizeObserver(read);
    observer.observe(node);

    return () => observer.disconnect();
  }, [node]);

  return [ref, width];
}

import type { ReactNode } from "react";
import { cn } from "../../utils/cn";
import type { AffixPosition } from "./inputs.types";
import type { Size } from "../../utils/types";

interface InputWrapperProps {
  children: ReactNode;
  prefix?: ReactNode;
  suffix?: ReactNode;
  prefixPosition?: AffixPosition;
  suffixPosition?: AffixPosition;
  size?: Size;
  /** Extra padding className to apply to the input when affixes are "inside" */
  insidePrefixPadding?: string;
  insideSuffixPadding?: string;
}

// NOTE: these must be COMPLETE, static class strings. Tailwind only detects
// utilities it can see verbatim in the source — building the arbitrary variant
// at runtime (e.g. `[&_input]:${"pl-9"}`) means `[&_input]:pl-9` is never
// emitted to CSS, so the inside affix gets no padding and overlaps the text
// (issue #6). Keep input/select/textarea spelled out here.
const insidePaddingLeft: Record<Size, string> = {
  xs: "[&_input]:pl-7 [&_select]:pl-7 [&_textarea]:pl-7",
  sm: "[&_input]:pl-8 [&_select]:pl-8 [&_textarea]:pl-8",
  md: "[&_input]:pl-9 [&_select]:pl-9 [&_textarea]:pl-9",
  lg: "[&_input]:pl-10 [&_select]:pl-10 [&_textarea]:pl-10",
  xl: "[&_input]:pl-11 [&_select]:pl-11 [&_textarea]:pl-11",
};

const insidePaddingRight: Record<Size, string> = {
  xs: "[&_input]:pr-7 [&_select]:pr-7 [&_textarea]:pr-7",
  sm: "[&_input]:pr-8 [&_select]:pr-8 [&_textarea]:pr-8",
  md: "[&_input]:pr-9 [&_select]:pr-9 [&_textarea]:pr-9",
  lg: "[&_input]:pr-10 [&_select]:pr-10 [&_textarea]:pr-10",
  xl: "[&_input]:pr-11 [&_select]:pr-11 [&_textarea]:pr-11",
};

const affixOutsideClasses =
  "inline-flex items-center border border-zinc-300 bg-zinc-50 px-3 text-sm text-zinc-500 dark:border-zinc-700 dark:bg-zinc-800 dark:text-zinc-400";

export function InputWrapper({
  children,
  prefix,
  suffix,
  prefixPosition = "inside",
  suffixPosition = "inside",
  size = "md",
}: InputWrapperProps) {
  const hasInsidePrefix = prefix && prefixPosition === "inside";
  const hasInsideSuffix = suffix && suffixPosition === "inside";
  const hasOutsidePrefix = prefix && prefixPosition === "outside";
  const hasOutsideSuffix = suffix && suffixPosition === "outside";
  const hasOutside = hasOutsidePrefix || hasOutsideSuffix;

  if (!prefix && !suffix) {
    return <>{children}</>;
  }

  if (hasOutside) {
    return (
      <div data-react-fancy-input-wrapper="" className="flex">
        {hasOutsidePrefix && (
          <span className={cn(affixOutsideClasses, "rounded-l-lg border-r-0")}>
            {prefix}
          </span>
        )}
        <div
          className={cn(
            "relative flex flex-1 items-center",
            hasInsidePrefix && "relative",
          )}
        >
          {hasInsidePrefix && (
            <span className="pointer-events-none absolute left-3 z-10 text-zinc-400 dark:text-zinc-500">
              {prefix}
            </span>
          )}
          <div
            className={cn(
              "w-full [&>*]:w-full",
              hasOutsidePrefix && !hasOutsideSuffix && "[&_input]:rounded-l-none [&_select]:rounded-l-none [&_textarea]:rounded-l-none",
              !hasOutsidePrefix && hasOutsideSuffix && "[&_input]:rounded-r-none [&_select]:rounded-r-none [&_textarea]:rounded-r-none",
              hasOutsidePrefix && hasOutsideSuffix && "[&_input]:rounded-none [&_select]:rounded-none [&_textarea]:rounded-none",
              hasInsidePrefix && insidePaddingLeft[size],
            )}
          >
            {children}
          </div>
          {hasInsideSuffix && (
            <span className="pointer-events-none absolute right-3 z-10 text-zinc-400 dark:text-zinc-500">
              {suffix}
            </span>
          )}
        </div>
        {hasOutsideSuffix && (
          <span className={cn(affixOutsideClasses, "rounded-r-lg border-l-0")}>
            {suffix}
          </span>
        )}
      </div>
    );
  }

  // Both inside
  return (
    <div data-react-fancy-input-wrapper="" className="relative flex items-center">
      {hasInsidePrefix && (
        <span className="pointer-events-none absolute left-3 z-10 text-zinc-400 dark:text-zinc-500">
          {prefix}
        </span>
      )}
      <div
        className={cn(
          "w-full",
          hasInsidePrefix && insidePaddingLeft[size],
          hasInsideSuffix && insidePaddingRight[size],
        )}
      >
        {children}
      </div>
      {hasInsideSuffix && (
        <span className="pointer-events-none absolute right-3 z-10 text-zinc-400 dark:text-zinc-500">
          {suffix}
        </span>
      )}
    </div>
  );
}

import type { Size } from "../../utils/types";
import type { InputOption } from "./inputs.types";

export const inputSizeClasses: Record<Size, string> = {
  xs: "px-2 py-1 text-xs rounded",
  sm: "px-2.5 py-1.5 text-sm rounded-md",
  md: "px-3 py-2 text-sm rounded-lg",
  lg: "px-4 py-2.5 text-base rounded-lg",
  xl: "px-5 py-3 text-lg rounded-xl",
};

export const labelSizeClasses: Record<Size, string> = {
  xs: "text-xs",
  sm: "text-xs",
  md: "text-sm",
  lg: "text-sm",
  xl: "text-base",
};

export function dirtyClasses(dirty?: boolean): string {
  return dirty ? "border-l-[3px] border-l-amber-400" : "";
}

export function dirtyRingClasses(dirty?: boolean): string {
  return dirty ? "ring-2 ring-amber-400/50" : "";
}

export function errorClasses(error?: string): string {
  return error ? "border-red-500 focus:ring-red-500" : "";
}

export const inputBaseClasses =
  "border border-zinc-300 bg-white text-zinc-900 placeholder:text-zinc-400 transition-[border-color,box-shadow] duration-150 focus:outline-none focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500 disabled:opacity-50 disabled:cursor-not-allowed dark:border-zinc-700 dark:bg-[#1e1e24] dark:text-zinc-100 dark:placeholder:text-zinc-500 dark:focus:border-blue-400 dark:focus:ring-blue-400/20";

export function resolveOption<V = string>(
  option: InputOption<V>,
): { value: V; label: string; disabled?: boolean; description?: string } {
  if (typeof option === "string") {
    return { value: option as unknown as V, label: option };
  }
  return option;
}

import { createContext, useContext } from "react";
import type { FieldMode } from "../inputs.types";

export interface FieldModeContextValue {
  mode: FieldMode;
}

export const FieldModeContext = createContext<FieldModeContextValue | null>(null);

/**
 * Resolve the effective mode for an input. Precedence: an explicit prop wins,
 * then the nearest `<Form>` / `<FormProvider>` context, then `"edit"`.
 *
 * Deliberately tolerant (returns `"edit"` outside any provider) — unlike a slot
 * guard — so every input works standalone with zero context and existing call
 * sites behave identically.
 */
export function useFieldMode(explicit?: FieldMode): FieldMode {
  const ctx = useContext(FieldModeContext);
  return explicit ?? ctx?.mode ?? "edit";
}

import type { KeyboardEvent, ReactNode } from "react";
import { cn } from "../../../utils/cn";
import type { Size } from "../../../utils/types";
import { inputSizeClasses } from "../inputs.utils";

export interface DisplayValueProps {
  /** The formatted value to show. Empty / null / undefined renders `empty`. */
  children?: ReactNode;
  size?: Size;
  /** Static adornment rendered before the value (mirrors an input's `leading`/`prefix`). */
  leading?: ReactNode;
  /** Static adornment rendered after the value (mirrors an input's `trailing`/`suffix`). */
  trailing?: ReactNode;
  /** Shown when the value is empty. Default `—`. */
  empty?: ReactNode;
  /** When true the value is clickable to enter edit mode (inline click-to-edit). */
  interactive?: boolean;
  /** Called when an interactive value is activated (click / Enter / Space). */
  onActivate?: () => void;
  className?: string;
}

function isEmpty(value: ReactNode): boolean {
  return value === null || value === undefined || value === "";
}

/**
 * The read-only counterpart to an `<input>`. Renders a non-interactive value
 * with the same size rhythm as the editable control (reusing
 * {@link inputSizeClasses}) but without the border / background / focus ring.
 *
 * When `interactive` (inline click-to-edit), the value becomes a focusable,
 * hoverable target that calls `onActivate` on click / Enter / Space to swap in
 * the real control. Dropped into the SAME `Field` wrapper the editable control
 * uses, so label / description / error chrome stays byte-identical between the
 * display and the editor.
 *
 * Carries `data-react-fancy-display` / `data-mode="view"` stable handles for
 * agents and tests (Human+ contract).
 */
export function DisplayValue({
  children,
  size = "md",
  leading,
  trailing,
  empty = "—",
  interactive,
  onActivate,
  className,
}: DisplayValueProps) {
  const empties = isEmpty(children);

  const onKeyDown = interactive
    ? (e: KeyboardEvent<HTMLDivElement>) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onActivate?.();
        }
      }
    : undefined;

  return (
    <div
      data-react-fancy-display=""
      data-mode="view"
      role={interactive ? "button" : undefined}
      tabIndex={interactive ? 0 : undefined}
      title={interactive ? "Click to edit" : undefined}
      onClick={interactive ? onActivate : undefined}
      onKeyDown={onKeyDown}
      className={cn(
        "flex w-full items-center gap-2 text-zinc-900 dark:text-zinc-100",
        inputSizeClasses[size],
        // Strip the editable box look — keep only the size/padding rhythm.
        "border-0 bg-transparent px-0",
        interactive &&
          "-mx-2 cursor-text rounded-md px-2 outline-none transition-colors hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-blue-500/40 dark:hover:bg-zinc-800",
        empties && "text-zinc-400 dark:text-zinc-500",
        className,
      )}
    >
      {leading && <span className="text-zinc-400 dark:text-zinc-500">{leading}</span>}
      <span className="min-w-0 truncate">{empties ? empty : children}</span>
      {trailing && <span className="text-zinc-400 dark:text-zinc-500">{trailing}</span>}
    </div>
  );
}

import { useCallback, useState } from "react";
import type { FieldMode } from "../inputs.types";

export interface InlineEdit {
  /** Render the editable control (`true`) vs. the read-only value display (`false`). */
  showControl: boolean;
  /** Whether view mode is interactive (click-to-edit) — i.e. `view` and not disabled. */
  interactive: boolean;
  /** Enter edit mode (no-op unless interactive). */
  enterEdit: () => void;
  /** Leave edit mode, back to the value display. */
  exitEdit: () => void;
}

/**
 * Inline click-to-edit for `mode="view"`. The bound value shows as clean static
 * text; clicking it swaps in the focused control; blur returns to the display
 * (the control's `onChange` / `onBlur` fire as usual, so a host can persist on
 * commit). `mode="edit"` is always the control; a **disabled** view stays static
 * text (no click-to-edit).
 *
 * This is the value of "view mode": tidy read-only surfaces where each field
 * becomes editable only when the user reaches for it.
 */
export function useInlineEdit(mode: FieldMode, disabled?: boolean): InlineEdit {
  const [editing, setEditing] = useState(false);
  const interactive = mode === "view" && !disabled;
  const showControl = mode !== "view" || (interactive && editing);
  const enterEdit = useCallback(() => {
    if (interactive) setEditing(true);
  }, [interactive]);
  const exitEdit = useCallback(() => setEditing(false), []);
  return { showControl, interactive, enterEdit, exitEdit };
}

import type { ReactNode } from "react";
import type { Size } from "../../utils/types";

export type InputOption<V = string> =
  | string
  | { value: V; label: string; disabled?: boolean; description?: string };

export type InputOptionGroup<V = string> = {
  label: string;
  options: InputOption<V>[];
};

/**
 * Edit vs. read-only display. In `"view"` mode an input renders the bound value
 * as static text instead of an interactive control — the React/Inertia analog of
 * Livewire's public/bindable properties. Declared here (rather than in `mode/`)
 * to keep `InputBaseProps` free of an import cycle. Resolved per input via
 * {@link useFieldMode}: explicit prop → `<Form>`/`<FormProvider>` context → `"edit"`.
 */
export type FieldMode = "edit" | "view";

export interface InputBaseProps {
  size?: Size;
  dirty?: boolean;
  error?: string;
  label?: string;
  /**
   * Keep the label for assistive tech, but do not draw it.
   *
   * For a control whose options already say what it does — a filter toolbar's
   * segmented switches, say — where a visible label is noise but an unnamed
   * control is a bug. Without this the only choices were an unnamed control or
   * a label the design does not have, and the silent one is the one that ships.
   */
  labelHidden?: boolean;
  description?: string;
  required?: boolean;
  disabled?: boolean;
  className?: string;
  id?: string;
  name?: string;
  /** `"edit"` (default) renders the control; `"view"` renders the value as text. Overrides the `<Form mode>` context. */
  mode?: FieldMode;
}

export type AffixPosition = "inside" | "outside";

export interface InputAffixProps {
  prefix?: ReactNode;
  suffix?: ReactNode;
  prefixPosition?: AffixPosition;
  suffixPosition?: AffixPosition;
}

import { useCallback, useEffect, useState, type RefObject } from "react";
import type { Placement } from "../utils/types";

interface FloatingPosition {
  x: number;
  y: number;
  placement: Placement;
}

interface UseFloatingPositionOptions {
  placement?: Placement;
  offset?: number;
  enabled?: boolean;
}

function getPosition(
  anchor: DOMRect,
  floating: DOMRect,
  placement: Placement,
  offset: number,
): FloatingPosition {
  let x = 0;
  let y = 0;
  const base = placement.split("-")[0] as "top" | "bottom" | "left" | "right";
  const align = placement.split("-")[1] as "start" | "end" | undefined;

  switch (base) {
    case "top":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.top - floating.height - offset;
      break;
    case "bottom":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.bottom + offset;
      break;
    case "left":
      x = anchor.left - floating.width - offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
    case "right":
      x = anchor.right + offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
  }

  if (base === "top" || base === "bottom") {
    if (align === "start") x = anchor.left;
    else if (align === "end") x = anchor.right - floating.width;
  }

  if (base === "left" || base === "right") {
    if (align === "start") y = anchor.top;
    else if (align === "end") y = anchor.bottom - floating.height;
  }

  // Viewport clamping
  let finalPlacement = placement;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  if (base === "bottom" && y + floating.height > vh) {
    y = anchor.top - floating.height - offset;
    finalPlacement = placement.replace("bottom", "top") as Placement;
  } else if (base === "top" && y < 0) {
    y = anchor.bottom + offset;
    finalPlacement = placement.replace("top", "bottom") as Placement;
  }

  x = Math.max(4, Math.min(x, vw - floating.width - 4));
  y = Math.max(4, Math.min(y, vh - floating.height - 4));

  return { x, y, placement: finalPlacement };
}

export function useFloatingPosition(
  anchorRef: RefObject<HTMLElement | null>,
  floatingRef: RefObject<HTMLElement | null>,
  options: UseFloatingPositionOptions = {},
): FloatingPosition {
  const { placement = "bottom", offset = 8, enabled = true } = options;
  const [position, setPosition] = useState<FloatingPosition>({
    x: -9999,
    y: -9999,
    placement,
  });

  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const floating = floatingRef.current;
    if (!anchor || !floating) return;

    const anchorRect = anchor.getBoundingClientRect();
    const floatingRect = floating.getBoundingClientRect();
    const next = getPosition(anchorRect, floatingRect, placement, offset);
    // Bail out when nothing changed so this can run after every commit
    // (below) without causing an infinite render loop.
    setPosition((prev) =>
      prev.x === next.x && prev.y === next.y && prev.placement === next.placement
        ? prev
        : next,
    );
  }, [anchorRef, floatingRef, placement, offset]);

  // Re-measure after every commit while open.
  //
  // The floating element mounts a frame or two AFTER `enabled` flips — its
  // render is gated behind a state flip (e.g. useAnimation's `mounted`), so at
  // the moment `enabled` turns true the floating ref is still null and a single
  // measurement no-ops, leaving the popover parked at its off-screen sentinel.
  //
  // A passive effect with no deps runs after *every* commit — including the one
  // that finally mounts the floating element — and, crucially, keeps running in
  // hidden/background tabs where `requestAnimationFrame` is paused. The bail-out
  // in `update` makes the steady-state calls free, so this both fixes the
  // late-mount race and survives tab-visibility throttling.
  useEffect(() => {
    if (enabled) update();
  });

  // …but the per-commit effect ISN'T enough when the floating element mounts
  // through a <Portal> whose own mount gate (SSR-safe; renders nothing until its
  // useEffect runs) attaches the node WITHOUT re-rendering this hook's component.
  // Then no commit happens here, the measurement never runs, and the popover
  // stays parked at its off-screen sentinel until an unrelated scroll/resize
  // fires `update()` — the "menu only appears after I scroll" bug. Poll with rAF
  // until the node is actually in the DOM, measure it, then keep it observed for
  // size changes (async content / lazily-loaded icons).
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    let ro: ResizeObserver | null = null;
    const tick = () => {
      const el = floatingRef.current;
      if (el) {
        update();
        if (typeof ResizeObserver !== "undefined") {
          ro = new ResizeObserver(() => update());
          ro.observe(el);
        }
      } else {
        raf = requestAnimationFrame(tick);
      }
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      ro?.disconnect();
    };
  }, [enabled, update, floatingRef]);

  // Park off-screen when closed so the next open re-measures from scratch.
  useEffect(() => {
    if (!enabled) {
      setPosition((prev) =>
        prev.x === -9999 ? prev : { x: -9999, y: -9999, placement },
      );
    }
  }, [enabled, placement]);

  // Reposition on scroll/resize while open.
  useEffect(() => {
    if (!enabled) return;

    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);

    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [update, enabled]);

  return position;
}

import {
  type CSSProperties,
  type ReactNode,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";

/**
 * InputTag — attach a `/`-style or `@`-style autocomplete picker to *any*
 * text surface (a `<textarea>`, an `<input>`, a `contenteditable`, a code
 * editor, a sheet cell editor, a whiteboard sticky note…) via an adapter
 * that abstracts the surface's read/write/caret API.
 *
 * The component is "headless" in the sense that it has no input of its
 * own — it floats a small picker menu near the surface and writes back
 * through the adapter when the user picks an item.
 *
 *   <textarea ref={ref} value={text} onChange={...} />
 *   <InputTag
 *     adapter={textareaAdapter(ref)}
 *     triggers={{
 *       "/": { items: commands, insert: (c) => `${c.name} ` },
 *       "@": { items: mentions, insert: (m) => `@${m.name} ` },
 *     }}
 *   />
 *
 * For non-DOM surfaces, write a small adapter that conforms to
 * {@link InputTagAdapter}. Adapters typically run 20–40 lines.
 */

/** What the surface tells the picker on every text/caret change. */
export type InputTagAdapterState = {
  text: string;
  caretIndex: number;
};

/**
 * The contract every input surface implements. The picker subscribes to
 * state changes, anchors itself using `getAnchorRect`, intercepts
 * navigation keys via `onKey`, and writes the selected item back through
 * `replaceRange`.
 */
export type InputTagAdapter = {
  /** Push current state whenever text or caret changes. Returns an unsubscribe. */
  subscribe: (fn: (state: InputTagAdapterState) => void) => () => void;
  /** Replace text in `[start, end)` with `replacement`. The adapter is
   *  responsible for moving the caret to the end of the inserted text. */
  replaceRange: (start: number, end: number, replacement: string) => void;
  /** Screen-space rect to anchor the picker against. Usually the surface's
   *  bounding rect; for editors that can compute caret-precise coordinates,
   *  return a small rect there instead. */
  getAnchorRect: () => DOMRect | null;
  /** Subscribe to keydown events on the surface. The handler may return
   *  `true` to consume the event (the adapter then calls
   *  `preventDefault` / `stopPropagation`). Returns an unsubscribe. */
  onKey: (handler: (e: KeyboardEvent) => boolean) => () => void;
};

/**
 * Per-trigger configuration. `T` is the item shape — typically a
 * `{ id, name, ... }` object, but any shape works as long as `keyOf` /
 * `insert` know how to handle it.
 */
export type InputTagTrigger<T> = {
  /** The pool the picker filters against. */
  items: T[];
  /** Text inserted in place of `<triggerChar><query>`. */
  insert: (item: T, query: string) => string;
  /** Custom filter. Default: case-insensitive prefix match against
   *  `String(keyOf(item))`. Pass `() => true` to disable filtering and
   *  rely on `items` being pre-filtered (e.g. from an async source). */
  filter?: (item: T, query: string) => boolean;
  /** How to render each row. Default renders the result of `keyOf(item)`. */
  render?: (item: T, active: boolean) => ReactNode;
  /** How to derive a stable key + default label for each item. Default
   *  reads `item.name` then `item.id` then `String(item)`. */
  keyOf?: (item: T) => string;
  /** Optional header label shown above the list. */
  label?: string;
};

export type InputTagTriggers = Record<string, InputTagTrigger<any>>;

export interface InputTagProps {
  adapter: InputTagAdapter;
  triggers: InputTagTriggers;
  /** Max rows shown. Default 8. */
  maxItems?: number;
  /** Where the picker anchors relative to the surface. Default `"bottom-left"`. */
  placement?: "bottom-left" | "bottom-right" | "top-left" | "top-right";
  /** Custom class for the popover container. */
  className?: string;
  /** Inline style for the popover container. */
  style?: CSSProperties;
  /** Fires whenever an item is picked. */
  onPick?: (info: { triggerChar: string; query: string; item: unknown }) => void;
};

type ActiveTrigger = {
  char: string;
  start: number;
  end: number;
  query: string;
};

function defaultKeyOf(item: unknown): string {
  if (item && typeof item === "object") {
    const r = item as Record<string, unknown>;
    if (typeof r.name === "string") return r.name;
    if (typeof r.id === "string") return r.id;
  }
  return String(item);
}

function defaultFilter(item: unknown, query: string): boolean {
  if (!query) return true;
  return defaultKeyOf(item).toLowerCase().includes(query.toLowerCase());
}

/**
 * Walk back from `caret` to detect an active trigger. A trigger is active
 * when one of the configured characters appears between `caret` and the
 * nearest preceding whitespace (or start-of-text), with no other
 * non-trigger-non-whitespace breaks. The "query" is everything after
 * the trigger up to the caret.
 */
function detectTrigger(
  text: string,
  caret: number,
  triggerChars: Set<string>,
): ActiveTrigger | null {
  for (let i = caret - 1; i >= 0; i--) {
    const ch = text[i];
    if (ch === undefined) break;
    if (triggerChars.has(ch)) {
      // Must be at a word boundary: start of text OR preceded by whitespace.
      if (i === 0 || /\s/.test(text[i - 1])) {
        return {
          char: ch,
          start: i,
          end: caret,
          query: text.slice(i + 1, caret),
        };
      }
      return null;
    }
    if (/\s/.test(ch)) return null;
  }
  return null;
}

export function InputTag({
  adapter,
  triggers,
  maxItems = 8,
  placement = "bottom-left",
  className,
  style,
  onPick,
}: InputTagProps) {
  const triggerChars = useMemo(() => new Set(Object.keys(triggers)), [triggers]);
  const [active, setActive] = useState<ActiveTrigger | null>(null);
  const [cursor, setCursor] = useState(0);
  const [anchorRect, setAnchorRect] = useState<DOMRect | null>(null);

  // Latest state in refs so key handlers see fresh data without re-registering.
  const stateRef = useRef<InputTagAdapterState>({ text: "", caretIndex: 0 });
  const activeRef = useRef<ActiveTrigger | null>(null);
  const cursorRef = useRef(0);
  activeRef.current = active;
  cursorRef.current = cursor;

  // Filtered items for the active trigger.
  const items: unknown[] = useMemo(() => {
    if (!active) return [];
    const cfg = triggers[active.char];
    if (!cfg) return [];
    const filter = cfg.filter ?? defaultFilter;
    const out: unknown[] = [];
    for (const item of cfg.items) {
      if (filter(item, active.query)) out.push(item);
      if (out.length >= maxItems) break;
    }
    return out;
  }, [active, triggers, maxItems]);

  // Subscribe to text/caret changes.
  useEffect(() => {
    return adapter.subscribe((s) => {
      stateRef.current = s;
      const next = detectTrigger(s.text, s.caretIndex, triggerChars);
      setActive((prev) => {
        // Reset cursor when the trigger char or position changes.
        if (!prev || !next || prev.char !== next.char || prev.start !== next.start) {
          setCursor(0);
        }
        return next;
      });
      if (next) setAnchorRect(adapter.getAnchorRect());
    });
  }, [adapter, triggerChars]);

  // Refresh anchor rect on scroll/resize while picker is open.
  useLayoutEffect(() => {
    if (!active) return;
    const update = () => setAnchorRect(adapter.getAnchorRect());
    update();
    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);
    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [active, adapter]);

  // Clamp cursor when the visible items shrink.
  useEffect(() => {
    if (cursor >= items.length) setCursor(Math.max(0, items.length - 1));
  }, [items.length, cursor]);

  const pickItem = useCallback(
    (item: unknown) => {
      const cur = activeRef.current;
      if (!cur) return;
      const cfg = triggers[cur.char];
      if (!cfg) return;
      const replacement = cfg.insert(item, cur.query);
      adapter.replaceRange(cur.start, cur.end, replacement);
      onPick?.({ triggerChar: cur.char, query: cur.query, item });
      setActive(null);
    },
    [adapter, triggers, onPick],
  );

  // Key handling.
  useEffect(() => {
    return adapter.onKey((e) => {
      const cur = activeRef.current;
      if (!cur) return false;
      const visible = items;
      switch (e.key) {
        case "ArrowDown":
          if (visible.length === 0) return false;
          setCursor((c) => (c + 1) % visible.length);
          return true;
        case "ArrowUp":
          if (visible.length === 0) return false;
          setCursor((c) => (c - 1 + visible.length) % visible.length);
          return true;
        case "Enter":
        case "Tab": {
          if (visible.length === 0) return false;
          const idx = Math.min(cursorRef.current, visible.length - 1);
          pickItem(visible[idx]);
          return true;
        }
        case "Escape":
          setActive(null);
          return true;
        default:
          return false;
      }
    });
  }, [adapter, items, pickItem]);

  if (!active || !anchorRect || items.length === 0) return null;

  const cfg = triggers[active.char];
  if (!cfg) return null;

  const popStyle = computePopoverStyle(anchorRect, placement);

  return (
    <div
      role="listbox"
      aria-label={cfg.label ?? `Pick a ${active.char === "/" ? "command" : "mention"}`}
      className={[
        "fixed z-50 w-72 overflow-hidden rounded-md border border-zinc-200 bg-white shadow-lg dark:border-zinc-700 dark:bg-zinc-900",
        className ?? "",
      ]
        .filter(Boolean)
        .join(" ")}
      style={{ ...popStyle, ...style }}
    >
      {(cfg.label || active.query) && (
        <div className="flex items-center justify-between border-b border-zinc-100 bg-zinc-50 px-2 py-1 text-[10px] font-semibold uppercase tracking-wider text-zinc-500 dark:border-zinc-800 dark:bg-zinc-950">
          <span>{cfg.label ?? labelForChar(active.char)}</span>
          {active.query && (
            <span className="font-mono text-[10px] normal-case tracking-normal text-zinc-400">
              {active.char}
              {active.query}
            </span>
          )}
        </div>
      )}
      <ul className="max-h-60 overflow-y-auto">
        {items.map((item, i) => {
          const renderer = cfg.render ?? ((it: unknown) => <span>{defaultKeyOf(it)}</span>);
          const active2 = i === cursor;
          const key = (cfg.keyOf ?? defaultKeyOf)(item);
          return (
            <li
              key={key}
              role="option"
              aria-selected={active2}
              onMouseDown={(e) => {
                e.preventDefault();
                pickItem(item);
              }}
              onMouseEnter={() => setCursor(i)}
              className={[
                "cursor-pointer px-2 py-1.5 text-[12px]",
                active2
                  ? "bg-violet-100 dark:bg-violet-900/30"
                  : "hover:bg-zinc-50 dark:hover:bg-zinc-800",
              ].join(" ")}
            >
              {renderer(item, active2)}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function labelForChar(ch: string): string {
  if (ch === "/") return "Commands";
  if (ch === "@") return "Mentions";
  if (ch === "#") return "Tags";
  if (ch === ":") return "Emoji";
  return `Trigger ${ch}`;
}

function computePopoverStyle(
  anchor: DOMRect,
  placement: NonNullable<InputTagProps["placement"]>,
): CSSProperties {
  const offset = 4;
  switch (placement) {
    case "bottom-right":
      return { top: anchor.bottom + offset, right: window.innerWidth - anchor.right };
    case "top-left":
      return { bottom: window.innerHeight - anchor.top + offset, left: anchor.left };
    case "top-right":
      return { bottom: window.innerHeight - anchor.top + offset, right: window.innerWidth - anchor.right };
    case "bottom-left":
    default:
      return { top: anchor.bottom + offset, left: anchor.left };
  }
}

import type { RefObject } from "react";
import type { InputTagAdapter } from "./InputTag";

/**
 * Built-in DOM adapters. Each one wraps a familiar input element and
 * exposes the {@link InputTagAdapter} contract so `<InputTag>` can
 * attach to it. For non-DOM surfaces (code editor, sheet cell editor,
 * whiteboard sticky note), write your own — the contract is small.
 */

/**
 * Get React's monkey-patched-aside native value setter on a DOM
 * element. Required when programmatically updating `value` on a
 * controlled input: React's intercepted setter would otherwise swallow
 * the change and the consumer's `onChange` would never fire.
 */
function nativeValueSetter(el: HTMLInputElement | HTMLTextAreaElement): ((v: string) => void) | null {
  const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
  const desc = Object.getOwnPropertyDescriptor(proto, "value");
  if (!desc?.set) return null;
  return desc.set.bind(el);
}

function replaceInValueElement(
  el: HTMLInputElement | HTMLTextAreaElement,
  start: number,
  end: number,
  replacement: string,
): void {
  const current = el.value;
  const next = current.slice(0, start) + replacement + current.slice(end);
  const setter = nativeValueSetter(el);
  if (setter) {
    setter(next);
  } else {
    el.value = next;
  }
  // Dispatch a native `input` event so any controlled-component
  // onChange handler upstream gets the new value.
  el.dispatchEvent(new Event("input", { bubbles: true }));
  // Place caret at the end of the inserted text.
  const caret = start + replacement.length;
  el.setSelectionRange(caret, caret);
  el.focus();
}

function valueElementAdapter(
  ref: RefObject<HTMLTextAreaElement | HTMLInputElement | null>,
): InputTagAdapter {
  return {
    subscribe(fn) {
      const handler = () => {
        const el = ref.current;
        if (!el) return;
        fn({
          text: el.value,
          caretIndex: el.selectionStart ?? el.value.length,
        });
      };
      const el = ref.current;
      if (el) {
        el.addEventListener("input", handler);
        el.addEventListener("click", handler);
        el.addEventListener("keyup", handler);
        el.addEventListener("focus", handler);
      }
      return () => {
        const el2 = ref.current;
        if (el2) {
          el2.removeEventListener("input", handler);
          el2.removeEventListener("click", handler);
          el2.removeEventListener("keyup", handler);
          el2.removeEventListener("focus", handler);
        }
      };
    },
    replaceRange(start, end, replacement) {
      const el = ref.current;
      if (!el) return;
      replaceInValueElement(el, start, end, replacement);
    },
    getAnchorRect() {
      const el = ref.current;
      return el ? el.getBoundingClientRect() : null;
    },
    onKey(handler) {
      const fn = (e: KeyboardEvent) => {
        if (handler(e)) {
          e.preventDefault();
          e.stopPropagation();
        }
      };
      const el = ref.current;
      if (el) el.addEventListener("keydown", fn as EventListener);
      return () => {
        const el2 = ref.current;
        if (el2) el2.removeEventListener("keydown", fn as EventListener);
      };
    },
  };
}

/**
 * Adapter for a DOM `<textarea>`. Works whether the consumer manages
 * `value` via React state (controlled) or lets the DOM hold it
 * (uncontrolled) — `replaceRange` uses React's native value setter and
 * dispatches a native `input` event so the upstream onChange fires.
 */
export function textareaAdapter(
  ref: RefObject<HTMLTextAreaElement | null>,
): InputTagAdapter {
  return valueElementAdapter(ref);
}

/** Adapter for a DOM `<input type="text|search|...">`. */
export function inputAdapter(
  ref: RefObject<HTMLInputElement | null>,
): InputTagAdapter {
  return valueElementAdapter(ref);
}

/**
 * Adapter for any `contenteditable` element. Operates on the element's
 * `textContent`; rich-text editors with their own internal model should
 * write a custom adapter that talks to that model instead.
 */
export function contentEditableAdapter(
  ref: RefObject<HTMLElement | null>,
): InputTagAdapter {
  function caretIndex(el: HTMLElement): number {
    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0) return 0;
    const range = sel.getRangeAt(0).cloneRange();
    range.selectNodeContents(el);
    range.setEnd(sel.focusNode!, sel.focusOffset);
    return range.toString().length;
  }
  /**
   * Resolve an index into the element's visible text to a position inside the
   * text node that actually holds it. Returns null when the index is past the
   * end, or when there is no text node at all (an empty editable).
   *
   * This is the single walk that `setCaret` and `replaceRange` share. They used
   * to disagree: `setCaret` walked, `replaceRange` went through `textContent`.
   */
  function locate(
    el: HTMLElement,
    index: number,
  ): { node: Text; offset: number } | null {
    const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    let remaining = index;
    let node = walker.nextNode() as Text | null;
    while (node) {
      const len = node.textContent?.length ?? 0;
      if (remaining <= len) return { node, offset: remaining };
      remaining -= len;
      node = walker.nextNode() as Text | null;
    }
    return null;
  }
  function setCaret(el: HTMLElement, index: number): void {
    const sel = window.getSelection();
    if (!sel) return;
    const at = locate(el, index);
    const range = document.createRange();
    if (at) {
      range.setStart(at.node, at.offset);
      range.collapse(true);
    } else {
      // Past end (or nothing to walk): place at end.
      range.selectNodeContents(el);
      range.collapse(false);
    }
    sel.removeAllRanges();
    sel.addRange(range);
  }
  return {
    subscribe(fn) {
      const handler = () => {
        const el = ref.current;
        if (!el) return;
        fn({ text: el.textContent ?? "", caretIndex: caretIndex(el) });
      };
      const el = ref.current;
      if (el) {
        el.addEventListener("input", handler);
        el.addEventListener("click", handler);
        el.addEventListener("keyup", handler);
        el.addEventListener("focus", handler);
      }
      return () => {
        const el2 = ref.current;
        if (el2) {
          el2.removeEventListener("input", handler);
          el2.removeEventListener("click", handler);
          el2.removeEventListener("keyup", handler);
          el2.removeEventListener("focus", handler);
        }
      };
    },
    replaceRange(start, end, replacement) {
      const el = ref.current;
      if (!el) return;

      // Edit through a Range rather than rewriting `textContent`. Assigning
      // `textContent` destroys EVERY element child, so a host that renders a
      // resolved tag as a pill could only ever insert one: the next insert
      // flattened the first away. A Range touches nothing outside itself.
      const from = locate(el, start);
      const to = locate(el, end);
      const inserted = document.createTextNode(replacement);

      if (from && to) {
        const range = document.createRange();
        range.setStart(from.node, from.offset);
        range.setEnd(to.node, to.offset);
        range.deleteContents();
        range.insertNode(inserted);
      } else {
        // Past the end, or an empty editable with no text node to address.
        el.append(inserted);
      }

      // Anchor the caret on the node just written instead of re-deriving an
      // index: the text offsets have moved, and the node has not.
      const sel = window.getSelection();
      if (sel) {
        const after = document.createRange();
        after.setStart(inserted, inserted.length);
        after.collapse(true);
        sel.removeAllRanges();
        sel.addRange(after);
      }

      el.dispatchEvent(new Event("input", { bubbles: true }));
      el.focus();
    },
    getAnchorRect() {
      const el = ref.current;
      return el ? el.getBoundingClientRect() : null;
    },
    onKey(handler) {
      const fn = (e: KeyboardEvent) => {
        if (handler(e)) {
          e.preventDefault();
          e.stopPropagation();
        }
      };
      const el = ref.current;
      if (el) el.addEventListener("keydown", fn as EventListener);
      return () => {
        const el2 = ref.current;
        if (el2) el2.removeEventListener("keydown", fn as EventListener);
      };
    },
  };
}

/**
 * Adapter for hosts that fully control the text state themselves. Use
 * this when you can't (or don't want to) let the DOM be the source of
 * truth — for code editors with internal state, sheet cell editors, or
 * any host that already has `value` + `onChange` and wants to reach the
 * picker programmatically.
 *
 * The host calls `notify({ text, caretIndex })` after every text or
 * caret change. `<InputTag>` calls `onReplaceRange` to write back.
 */
export type ControlledAdapterHandle = InputTagAdapter & {
  /** Push the latest text + caret to the picker. */
  notify: (state: { text: string; caretIndex: number }) => void;
};

export function controlledAdapter(opts: {
  /** Element used as anchor + key target. Usually the visible input. */
  anchorRef: RefObject<HTMLElement | null>;
  /** Called when the picker writes back an insertion. */
  onReplaceRange: (start: number, end: number, replacement: string) => void;
}): ControlledAdapterHandle {
  let listener: ((s: { text: string; caretIndex: number }) => void) | null = null;
  let keyHandler: ((e: KeyboardEvent) => boolean) | null = null;

  const installKey = () => {
    const el = opts.anchorRef.current;
    if (!el || !keyHandler) return () => {};
    const fn = (e: KeyboardEvent) => {
      if (keyHandler && keyHandler(e)) {
        e.preventDefault();
        e.stopPropagation();
      }
    };
    el.addEventListener("keydown", fn);
    return () => el.removeEventListener("keydown", fn);
  };

  return {
    notify(state) {
      listener?.(state);
    },
    subscribe(fn) {
      listener = fn;
      return () => {
        if (listener === fn) listener = null;
      };
    },
    replaceRange(start, end, replacement) {
      opts.onReplaceRange(start, end, replacement);
    },
    getAnchorRect() {
      const el = opts.anchorRef.current;
      return el ? el.getBoundingClientRect() : null;
    },
    onKey(handler) {
      keyHandler = handler;
      const uninstall = installKey();
      return () => {
        if (keyHandler === handler) keyHandler = null;
        uninstall();
      };
    },
  };
}

export { InputTag } from "./InputTag";
export type {
  InputTagProps,
  InputTagAdapter,
  InputTagAdapterState,
  InputTagTrigger,
  InputTagTriggers,
} from "./InputTag";
export {
  textareaAdapter,
  inputAdapter,
  contentEditableAdapter,
  controlledAdapter,
  type ControlledAdapterHandle,
} from "./adapters";

import { Button, Card, Heading, Input, Select, Switch, Text } from '@particle-academy/react-fancy';
import { EMPLOYMENT_TYPE_OPTIONS } from '../lib/format';
import type { JobBoardFilters, JobPosting } from '../lib/types';
import { JobCard } from './JobCard';

export interface JobBoardProps {
    postings: JobPosting[];
    /** Controlled filter state. */
    filters?: JobBoardFilters;
    onFiltersChange?: (filters: JobBoardFilters) => void;
    onOpenPosting?: (posting: JobPosting) => void;
    loading?: boolean;
    /** Shown when there are no results. */
    emptyMessage?: string;
    /** Hide the filter bar for embedded/compact uses. */
    showFilters?: boolean;
    className?: string;
}

/**
 * The public board: a filter bar over a grid of postings.
 *
 * Fully controlled — it owns no filter state of its own, so the host can drive
 * it from a URL query string, an Inertia page prop, or an agent.
 */
export function JobBoard({
    postings,
    filters = {},
    onFiltersChange,
    onOpenPosting,
    loading = false,
    emptyMessage = 'No openings match your search right now.',
    showFilters = true,
    className,
}: JobBoardProps) {
    const patch = (next: Partial<JobBoardFilters>) => onFiltersChange?.({ ...filters, ...next });

    const hasFilters = Boolean(
        filters.search || filters.employment_type || filters.location || filters.is_remote,
    );

    return (
        <div className={`grid gap-5 ${className ?? ''}`}>
            {showFilters && (
                <Card
                    variant="outlined"
                    padding="lg"
                    className="!rounded-xl !border-secondary-200 !shadow-sm"
                >
                    <div className="grid gap-4 md:grid-cols-4 md:items-end">
                        <div className="md:col-span-2">
                            <Input
                                type="search"
                                label="Search"
                                placeholder="Job title, keyword or location"
                                value={filters.search ?? ''}
                                onValueChange={(search) => patch({ search })}
                            />
                        </div>

                        <Select
                            label="Type"
                            placeholder="Any type"
                            list={[...EMPLOYMENT_TYPE_OPTIONS]}
                            value={filters.employment_type ?? ''}
                            onValueChange={(v) =>
                                patch({ employment_type: (v || '') as JobBoardFilters['employment_type'] })
                            }
                        />

                        <div className="flex items-center justify-between gap-3 md:pb-2">
                            <Switch
                                label="Remote only"
                                checked={Boolean(filters.is_remote)}
                                onCheckedChange={(checked) =>
                                    patch({ is_remote: checked || undefined })
                                }
                            />
                            {hasFilters && onFiltersChange && (
                                <Button
                                    type="button"
                                    variant="ghost"
                                    onClick={() => onFiltersChange({})}
                                    className="!text-secondary-700 hover:!text-brand"
                                >
                                    Clear
                                </Button>
                            )}
                        </div>
                    </div>
                </Card>
            )}

            {loading ? (
                <Text color="muted">Loading openings…</Text>
            ) : postings.length === 0 ? (
                <Card
                    variant="outlined"
                    padding="lg"
                    className="!rounded-xl !border-secondary-200 text-center"
                >
                    <Heading as="h3" size="lg" weight="bold" className="!text-secondary-900">
                        Nothing here yet
                    </Heading>
                    <Text color="muted" className="!mt-2">
                        {emptyMessage}
                    </Text>
                </Card>
            ) : (
                <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                    {postings.map((posting) => (
                        <JobCard key={posting.id} posting={posting} onOpen={onOpenPosting} />
                    ))}
                </div>
            )}
        </div>
    );
}

import { Badge, Button, Card, Heading, Text } from '@particle-academy/react-fancy';
import { formatLocation, formatPay, formatPosted } from '../lib/format';
import type { JobPosting } from '../lib/types';

export interface JobCardProps {
    posting: JobPosting;
    /** Called when the card is opened. Omit to render a non-interactive card. */
    onOpen?: (posting: JobPosting) => void;
    /** Label for the action. Defaults to "View job". */
    actionLabel?: string;
    /** Show the employer name. Off inside an employer's own list. */
    showEmployer?: boolean;
    className?: string;
}

/**
 * One posting, as it appears in a list. Presentational and controlled — it
 * raises `onOpen` and renders nothing else interactive.
 */
export function JobCard({
    posting,
    onOpen,
    actionLabel = 'View job',
    showEmployer = true,
    className,
}: JobCardProps) {
    const pay = formatPay(posting);
    const location = formatLocation(posting);
    const posted = formatPosted(posting.published_at);

    return (
        <Card
            variant="outlined"
            padding="lg"
            className={`!rounded-xl !border-secondary-200 !shadow-sm hover:!shadow-md transition flex flex-col ${className ?? ''}`}
        >
            <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                    <Heading as="h3" size="lg" weight="bold" className="!text-secondary-900">
                        {posting.title}
                    </Heading>
                    {showEmployer && posting.employer?.name && (
                        <Text size="sm" color="muted" className="!mt-1">
                            {posting.employer.name}
                        </Text>
                    )}
                </div>
                {posting.employment_type_label && (
                    // shrink-0/nowrap: as a flex sibling of a long title the
                    // badge otherwise gets squeezed and wraps mid-label.
                    <Badge
                        color="zinc"
                        variant="soft"
                        size="sm"
                        className="!shrink-0 !whitespace-nowrap"
                    >
                        {posting.employment_type_label}
                    </Badge>
                )}
            </div>

            {posting.description && (
                <Text color="muted" size="sm" className="!mt-3 line-clamp-2">
                    {posting.description}
                </Text>
            )}

            <div className="mt-4 grid gap-1">
                {location && (
                    <Text size="sm" className="!text-secondary-700">
                        {location}
                    </Text>
                )}
                {pay && (
                    <Text size="sm" weight="semibold" className="!text-secondary-900">
                        {pay}
                    </Text>
                )}
            </div>

            <div className="mt-auto pt-5 flex items-center justify-between gap-3">
                <Text size="xs" color="muted">
                    {posted ?? ' '}
                </Text>
                {onOpen && (
                    <Button
                        type="button"
                        onClick={() => onOpen(posting)}
                        className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-4 !py-2 !rounded-md !shadow-sm"
                    >
                        {actionLabel}
                    </Button>
                )}
            </div>
        </Card>
    );
}

