import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import type { KeyboardEvent, ReactNode } from "react";
import { cn } from "../../../utils/cn";
import type { Size } from "../../../utils/types";
import { inputSizeClasses } from "../inputs.utils";

export interface DisplayValueProps {
  /** The formatted value to show. Empty / null / undefined renders `empty`. */
  children?: ReactNode;
  size?: Size;
  /** Static adornment rendered before the value (mirrors an input's `leading`/`prefix`). */
  leading?: ReactNode;
  /** Static adornment rendered after the value (mirrors an input's `trailing`/`suffix`). */
  trailing?: ReactNode;
  /** Shown when the value is empty. Default `—`. */
  empty?: ReactNode;
  /** When true the value is clickable to enter edit mode (inline click-to-edit). */
  interactive?: boolean;
  /** Called when an interactive value is activated (click / Enter / Space). */
  onActivate?: () => void;
  className?: string;
}

function isEmpty(value: ReactNode): boolean {
  return value === null || value === undefined || value === "";
}

/**
 * The read-only counterpart to an `<input>`. Renders a non-interactive value
 * with the same size rhythm as the editable control (reusing
 * {@link inputSizeClasses}) but without the border / background / focus ring.
 *
 * When `interactive` (inline click-to-edit), the value becomes a focusable,
 * hoverable target that calls `onActivate` on click / Enter / Space to swap in
 * the real control. Dropped into the SAME `Field` wrapper the editable control
 * uses, so label / description / error chrome stays byte-identical between the
 * display and the editor.
 *
 * Carries `data-react-fancy-display` / `data-mode="view"` stable handles for
 * agents and tests (Human+ contract).
 */
export function DisplayValue({
  children,
  size = "md",
  leading,
  trailing,
  empty = "—",
  interactive,
  onActivate,
  className,
}: DisplayValueProps) {
  const empties = isEmpty(children);

  const onKeyDown = interactive
    ? (e: KeyboardEvent<HTMLDivElement>) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onActivate?.();
        }
      }
    : undefined;

  return (
    <div
      data-react-fancy-display=""
      data-mode="view"
      role={interactive ? "button" : undefined}
      tabIndex={interactive ? 0 : undefined}
      title={interactive ? "Click to edit" : undefined}
      onClick={interactive ? onActivate : undefined}
      onKeyDown={onKeyDown}
      className={cn(
        "flex w-full items-center gap-2 text-zinc-900 dark:text-zinc-100",
        inputSizeClasses[size],
        // Strip the editable box look — keep only the size/padding rhythm.
        "border-0 bg-transparent px-0",
        interactive &&
          "-mx-2 cursor-text rounded-md px-2 outline-none transition-colors hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-blue-500/40 dark:hover:bg-zinc-800",
        empties && "text-zinc-400 dark:text-zinc-500",
        className,
      )}
    >
      {leading && <span className="text-zinc-400 dark:text-zinc-500">{leading}</span>}
      <span className="min-w-0 truncate">{empties ? empty : children}</span>
      {trailing && <span className="text-zinc-400 dark:text-zinc-500">{trailing}</span>}
    </div>
  );
}

import { useCallback, useState } from "react";
import type { FieldMode } from "../inputs.types";

export interface InlineEdit {
  /** Render the editable control (`true`) vs. the read-only value display (`false`). */
  showControl: boolean;
  /** Whether view mode is interactive (click-to-edit) — i.e. `view` and not disabled. */
  interactive: boolean;
  /** Enter edit mode (no-op unless interactive). */
  enterEdit: () => void;
  /** Leave edit mode, back to the value display. */
  exitEdit: () => void;
}

/**
 * Inline click-to-edit for `mode="view"`. The bound value shows as clean static
 * text; clicking it swaps in the focused control; blur returns to the display
 * (the control's `onChange` / `onBlur` fire as usual, so a host can persist on
 * commit). `mode="edit"` is always the control; a **disabled** view stays static
 * text (no click-to-edit).
 *
 * This is the value of "view mode": tidy read-only surfaces where each field
 * becomes editable only when the user reaches for it.
 */
export function useInlineEdit(mode: FieldMode, disabled?: boolean): InlineEdit {
  const [editing, setEditing] = useState(false);
  const interactive = mode === "view" && !disabled;
  const showControl = mode !== "view" || (interactive && editing);
  const enterEdit = useCallback(() => {
    if (interactive) setEditing(true);
  }, [interactive]);
  const exitEdit = useCallback(() => setEditing(false), []);
  return { showControl, interactive, enterEdit, exitEdit };
}

/**
 * HTML and URL sanitization utilities.
 *
 * Hand-rolled (no third-party deps) using browser-native `DOMParser`. Designed
 * for the trust model "consumer passes user-generated markdown/HTML to a
 * react-fancy component" — strips script tags, event handlers, and dangerous
 * URI schemes from `href`/`src` attributes.
 *
 * For server-side rendering (no `window`), `sanitizeHtml` returns the input
 * unchanged. Consumers SSR-rendering untrusted content should sanitize on the
 * server with their own pipeline.
 */

const DANGEROUS_TAGS = new Set([
  "script",
  "style",
  "iframe",
  "object",
  "embed",
  "link",
  "meta",
  "base",
  "form",
]);

const URL_ATTRS = new Set(["href", "src", "action", "formaction", "xlink:href"]);

const SAFE_PROTOCOL = /^(?:https?:|mailto:|tel:|sms:|ftp:|#|\/|\.\/|\.\.\/|[^:]*$)/i;

/**
 * Validate a URL/href against an allow-list of safe protocols. Returns the
 * input if safe, or `undefined` if it begins with a dangerous scheme like
 * `javascript:`, `data:`, or `vbscript:`. Relative URLs and fragment links
 * are allowed.
 */
export function sanitizeHref(href: string | undefined | null): string | undefined {
  if (href == null) return undefined;
  const trimmed = href.trim();
  if (!trimmed) return undefined;
  return SAFE_PROTOCOL.test(trimmed) ? trimmed : undefined;
}

function stripDangerousAttrs(el: Element): void {
  // Collect names first; mutating during iteration is awkward with NamedNodeMap.
  const names: string[] = [];
  for (let i = 0; i < el.attributes.length; i++) {
    names.push(el.attributes[i].name);
  }

  for (const name of names) {
    const lower = name.toLowerCase();

    // All on* event handlers
    if (lower.startsWith("on")) {
      el.removeAttribute(name);
      continue;
    }

    // URL attributes — protocol-filter
    if (URL_ATTRS.has(lower)) {
      const sanitized = sanitizeHref(el.getAttribute(name));
      if (sanitized === undefined) {
        el.removeAttribute(name);
      } else {
        el.setAttribute(name, sanitized);
      }
      continue;
    }

    // srcdoc executes JS in the iframe — drop wholesale
    if (lower === "srcdoc") {
      el.removeAttribute(name);
    }
  }
}

function walk(el: Element, removeQueue: Element[]): void {
  const tag = el.tagName.toLowerCase();

  if (DANGEROUS_TAGS.has(tag)) {
    removeQueue.push(el);
    return;
  }

  stripDangerousAttrs(el);

  const children = Array.from(el.children);
  for (const child of children) {
    walk(child, removeQueue);
  }
}

/**
 * Sanitize an HTML string by removing dangerous tags (script, iframe, etc.),
 * event-handler attributes (`onclick`, `onerror`, ...), and dangerous URI
 * schemes in `href`/`src` attributes.
 *
 * Uses the browser's `DOMParser`. In non-browser environments returns the
 * input unchanged — sanitize on the server in those cases.
 */
export function sanitizeHtml(html: string): string {
  if (typeof window === "undefined" || typeof DOMParser === "undefined") {
    return html;
  }

  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");
  const body = doc.body;
  if (!body) return html;

  const removeQueue: Element[] = [];
  for (const child of Array.from(body.children)) {
    walk(child, removeQueue);
  }

  for (const el of removeQueue) {
    el.parentNode?.removeChild(el);
  }

  return body.innerHTML;
}

import { EMOJI_DATA, EMOJI_ENTRIES, type EmojiCategoryKey, type EmojiEntry } from "./emoji-data";

export const SKIN_TONES = ["light", "medium-light", "medium", "medium-dark", "dark"] as const;
export type SkinTone = typeof SKIN_TONES[number];

type IndexedEntry = EmojiEntry & { category: EmojiCategoryKey };

let byName: Map<string, IndexedEntry> | null = null;
let byChar: Map<string, IndexedEntry> | null = null;

function ensureIndexes() {
  if (byName && byChar) return;
  byName = new Map();
  byChar = new Map();
  for (const [category, group] of Object.entries(EMOJI_DATA) as [EmojiCategoryKey, typeof EMOJI_DATA[EmojiCategoryKey]][]) {
    for (const emoji of group.emojis) {
      const entry: IndexedEntry = { ...emoji, category };
      byName.set(emoji.name.toLowerCase(), entry);
      byChar.set(emoji.char, entry);
      if (emoji.skinTones) {
        for (const toned of emoji.skinTones) {
          byChar.set(toned, entry);
        }
      }
    }
  }
}

/** Resolve an emoji name to its character. */
export function resolve(name: string): string | undefined {
  ensureIndexes();
  return byName!.get(name.toLowerCase())?.char;
}

/** Search emojis by name substring. Returns matching base emoji characters. */
export function search(query: string): string[] {
  const lower = query.toLowerCase();
  return EMOJI_ENTRIES.filter((e) => e.name.includes(lower)).map((e) => e.char);
}

/** Find an emoji entry by its character (toned or base). */
export function find(char: string): IndexedEntry | undefined {
  ensureIndexes();
  return byChar!.get(char);
}

/** Return the 5-tone variant array for an emoji (by char, toned or base). */
export function skinTones(char: string): readonly [string, string, string, string, string] | undefined {
  return find(char)?.skinTones;
}

/** Whether an emoji supports skin tones. */
export function hasSkinTones(char: string): boolean {
  return !!find(char)?.skinTones;
}

/** Return the toned variant for an emoji, or the base if no tones. */
export function applyTone(char: string, tone: SkinTone | null): string {
  if (!tone) return char;
  const entry = find(char);
  if (!entry?.skinTones) return char;
  const idx = SKIN_TONES.indexOf(tone);
  return entry.skinTones[idx] ?? char;
}

import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import { useCallback, useEffect, useState } from "react";

/**
 * Measure an inline adornment so the input can reserve exactly its width.
 *
 * ## Why this exists
 *
 * `leading` / `trailing` render ABSOLUTELY over the input, so they take no
 * space in flow and the input must be padded by hand to keep text clear of
 * them. That padding used to be a fixed `pl-9` / `pr-9` — 36px, sized for a
 * single icon. Any wider adornment ran straight under the value: `leading =
 * "https://"` is roughly 50px, so `https://` and `fancy.app` rendered on top of
 * one another.
 *
 * A fixed padding cannot be right for arbitrary content, and these props accept
 * arbitrary content — a currency code, a unit, a protocol, a short label. So
 * the width is measured rather than assumed.
 *
 * Returns `0` until measured (and on the server), which is the signal to keep
 * the old fixed padding as a fallback: an unmeasured render is then no worse
 * than it was before, rather than unpadded.
 *
 * `ResizeObserver` rather than a one-shot read, because the width changes after
 * first paint for reasons the first paint cannot see — a webfont swapping in,
 * the adornment's own content changing, a container query resizing the text.
 */
export function useAdornmentWidth(): [(node: HTMLElement | null) => void, number] {
  const [width, setWidth] = useState(0);
  const [node, setNode] = useState<HTMLElement | null>(null);

  const ref = useCallback((n: HTMLElement | null) => setNode(n), []);

  useEffect(() => {
    if (!node) {
      setWidth(0);

      return;
    }

    const read = () => setWidth(node.getBoundingClientRect().width);
    read();

    if (typeof ResizeObserver === "undefined") return;

    const observer = new ResizeObserver(read);
    observer.observe(node);

    return () => observer.disconnect();
  }, [node]);

  return [ref, width];
}

import type { ReactNode } from "react";
import { cn } from "../../utils/cn";
import type { AffixPosition } from "./inputs.types";
import type { Size } from "../../utils/types";

interface InputWrapperProps {
  children: ReactNode;
  prefix?: ReactNode;
  suffix?: ReactNode;
  prefixPosition?: AffixPosition;
  suffixPosition?: AffixPosition;
  size?: Size;
  /** Extra padding className to apply to the input when affixes are "inside" */
  insidePrefixPadding?: string;
  insideSuffixPadding?: string;
}

// NOTE: these must be COMPLETE, static class strings. Tailwind only detects
// utilities it can see verbatim in the source — building the arbitrary variant
// at runtime (e.g. `[&_input]:${"pl-9"}`) means `[&_input]:pl-9` is never
// emitted to CSS, so the inside affix gets no padding and overlaps the text
// (issue #6). Keep input/select/textarea spelled out here.
const insidePaddingLeft: Record<Size, string> = {
  xs: "[&_input]:pl-7 [&_select]:pl-7 [&_textarea]:pl-7",
  sm: "[&_input]:pl-8 [&_select]:pl-8 [&_textarea]:pl-8",
  md: "[&_input]:pl-9 [&_select]:pl-9 [&_textarea]:pl-9",
  lg: "[&_input]:pl-10 [&_select]:pl-10 [&_textarea]:pl-10",
  xl: "[&_input]:pl-11 [&_select]:pl-11 [&_textarea]:pl-11",
};

const insidePaddingRight: Record<Size, string> = {
  xs: "[&_input]:pr-7 [&_select]:pr-7 [&_textarea]:pr-7",
  sm: "[&_input]:pr-8 [&_select]:pr-8 [&_textarea]:pr-8",
  md: "[&_input]:pr-9 [&_select]:pr-9 [&_textarea]:pr-9",
  lg: "[&_input]:pr-10 [&_select]:pr-10 [&_textarea]:pr-10",
  xl: "[&_input]:pr-11 [&_select]:pr-11 [&_textarea]:pr-11",
};

const affixOutsideClasses =
  "inline-flex items-center border border-zinc-300 bg-zinc-50 px-3 text-sm text-zinc-500 dark:border-zinc-700 dark:bg-zinc-800 dark:text-zinc-400";

export function InputWrapper({
  children,
  prefix,
  suffix,
  prefixPosition = "inside",
  suffixPosition = "inside",
  size = "md",
}: InputWrapperProps) {
  const hasInsidePrefix = prefix && prefixPosition === "inside";
  const hasInsideSuffix = suffix && suffixPosition === "inside";
  const hasOutsidePrefix = prefix && prefixPosition === "outside";
  const hasOutsideSuffix = suffix && suffixPosition === "outside";
  const hasOutside = hasOutsidePrefix || hasOutsideSuffix;

  if (!prefix && !suffix) {
    return <>{children}</>;
  }

  if (hasOutside) {
    return (
      <div data-react-fancy-input-wrapper="" className="flex">
        {hasOutsidePrefix && (
          <span className={cn(affixOutsideClasses, "rounded-l-lg border-r-0")}>
            {prefix}
          </span>
        )}
        <div
          className={cn(
            "relative flex flex-1 items-center",
            hasInsidePrefix && "relative",
          )}
        >
          {hasInsidePrefix && (
            <span className="pointer-events-none absolute left-3 z-10 text-zinc-400 dark:text-zinc-500">
              {prefix}
            </span>
          )}
          <div
            className={cn(
              "w-full [&>*]:w-full",
              hasOutsidePrefix && !hasOutsideSuffix && "[&_input]:rounded-l-none [&_select]:rounded-l-none [&_textarea]:rounded-l-none",
              !hasOutsidePrefix && hasOutsideSuffix && "[&_input]:rounded-r-none [&_select]:rounded-r-none [&_textarea]:rounded-r-none",
              hasOutsidePrefix && hasOutsideSuffix && "[&_input]:rounded-none [&_select]:rounded-none [&_textarea]:rounded-none",
              hasInsidePrefix && insidePaddingLeft[size],
            )}
          >
            {children}
          </div>
          {hasInsideSuffix && (
            <span className="pointer-events-none absolute right-3 z-10 text-zinc-400 dark:text-zinc-500">
              {suffix}
            </span>
          )}
        </div>
        {hasOutsideSuffix && (
          <span className={cn(affixOutsideClasses, "rounded-r-lg border-l-0")}>
            {suffix}
          </span>
        )}
      </div>
    );
  }

  // Both inside
  return (
    <div data-react-fancy-input-wrapper="" className="relative flex items-center">
      {hasInsidePrefix && (
        <span className="pointer-events-none absolute left-3 z-10 text-zinc-400 dark:text-zinc-500">
          {prefix}
        </span>
      )}
      <div
        className={cn(
          "w-full",
          hasInsidePrefix && insidePaddingLeft[size],
          hasInsideSuffix && insidePaddingRight[size],
        )}
      >
        {children}
      </div>
      {hasInsideSuffix && (
        <span className="pointer-events-none absolute right-3 z-10 text-zinc-400 dark:text-zinc-500">
          {suffix}
        </span>
      )}
    </div>
  );
}

import { createContext, useContext } from "react";
import type { FieldMode } from "../inputs.types";

export interface FieldModeContextValue {
  mode: FieldMode;
}

export const FieldModeContext = createContext<FieldModeContextValue | null>(null);

/**
 * Resolve the effective mode for an input. Precedence: an explicit prop wins,
 * then the nearest `<Form>` / `<FormProvider>` context, then `"edit"`.
 *
 * Deliberately tolerant (returns `"edit"` outside any provider) — unlike a slot
 * guard — so every input works standalone with zero context and existing call
 * sites behave identically.
 */
export function useFieldMode(explicit?: FieldMode): FieldMode {
  const ctx = useContext(FieldModeContext);
  return explicit ?? ctx?.mode ?? "edit";
}

import { useCallback, useEffect, useState, type RefObject } from "react";
import type { Placement } from "../utils/types";

interface FloatingPosition {
  x: number;
  y: number;
  placement: Placement;
}

interface UseFloatingPositionOptions {
  placement?: Placement;
  offset?: number;
  enabled?: boolean;
}

function getPosition(
  anchor: DOMRect,
  floating: DOMRect,
  placement: Placement,
  offset: number,
): FloatingPosition {
  let x = 0;
  let y = 0;
  const base = placement.split("-")[0] as "top" | "bottom" | "left" | "right";
  const align = placement.split("-")[1] as "start" | "end" | undefined;

  switch (base) {
    case "top":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.top - floating.height - offset;
      break;
    case "bottom":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.bottom + offset;
      break;
    case "left":
      x = anchor.left - floating.width - offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
    case "right":
      x = anchor.right + offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
  }

  if (base === "top" || base === "bottom") {
    if (align === "start") x = anchor.left;
    else if (align === "end") x = anchor.right - floating.width;
  }

  if (base === "left" || base === "right") {
    if (align === "start") y = anchor.top;
    else if (align === "end") y = anchor.bottom - floating.height;
  }

  // Viewport clamping
  let finalPlacement = placement;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  if (base === "bottom" && y + floating.height > vh) {
    y = anchor.top - floating.height - offset;
    finalPlacement = placement.replace("bottom", "top") as Placement;
  } else if (base === "top" && y < 0) {
    y = anchor.bottom + offset;
    finalPlacement = placement.replace("top", "bottom") as Placement;
  }

  x = Math.max(4, Math.min(x, vw - floating.width - 4));
  y = Math.max(4, Math.min(y, vh - floating.height - 4));

  return { x, y, placement: finalPlacement };
}

export function useFloatingPosition(
  anchorRef: RefObject<HTMLElement | null>,
  floatingRef: RefObject<HTMLElement | null>,
  options: UseFloatingPositionOptions = {},
): FloatingPosition {
  const { placement = "bottom", offset = 8, enabled = true } = options;
  const [position, setPosition] = useState<FloatingPosition>({
    x: -9999,
    y: -9999,
    placement,
  });

  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const floating = floatingRef.current;
    if (!anchor || !floating) return;

    const anchorRect = anchor.getBoundingClientRect();
    const floatingRect = floating.getBoundingClientRect();
    const next = getPosition(anchorRect, floatingRect, placement, offset);
    // Bail out when nothing changed so this can run after every commit
    // (below) without causing an infinite render loop.
    setPosition((prev) =>
      prev.x === next.x && prev.y === next.y && prev.placement === next.placement
        ? prev
        : next,
    );
  }, [anchorRef, floatingRef, placement, offset]);

  // Re-measure after every commit while open.
  //
  // The floating element mounts a frame or two AFTER `enabled` flips — its
  // render is gated behind a state flip (e.g. useAnimation's `mounted`), so at
  // the moment `enabled` turns true the floating ref is still null and a single
  // measurement no-ops, leaving the popover parked at its off-screen sentinel.
  //
  // A passive effect with no deps runs after *every* commit — including the one
  // that finally mounts the floating element — and, crucially, keeps running in
  // hidden/background tabs where `requestAnimationFrame` is paused. The bail-out
  // in `update` makes the steady-state calls free, so this both fixes the
  // late-mount race and survives tab-visibility throttling.
  useEffect(() => {
    if (enabled) update();
  });

  // …but the per-commit effect ISN'T enough when the floating element mounts
  // through a <Portal> whose own mount gate (SSR-safe; renders nothing until its
  // useEffect runs) attaches the node WITHOUT re-rendering this hook's component.
  // Then no commit happens here, the measurement never runs, and the popover
  // stays parked at its off-screen sentinel until an unrelated scroll/resize
  // fires `update()` — the "menu only appears after I scroll" bug. Poll with rAF
  // until the node is actually in the DOM, measure it, then keep it observed for
  // size changes (async content / lazily-loaded icons).
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    let ro: ResizeObserver | null = null;
    const tick = () => {
      const el = floatingRef.current;
      if (el) {
        update();
        if (typeof ResizeObserver !== "undefined") {
          ro = new ResizeObserver(() => update());
          ro.observe(el);
        }
      } else {
        raf = requestAnimationFrame(tick);
      }
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      ro?.disconnect();
    };
  }, [enabled, update, floatingRef]);

  // Park off-screen when closed so the next open re-measures from scratch.
  useEffect(() => {
    if (!enabled) {
      setPosition((prev) =>
        prev.x === -9999 ? prev : { x: -9999, y: -9999, placement },
      );
    }
  }, [enabled, placement]);

  // Reposition on scroll/resize while open.
  useEffect(() => {
    if (!enabled) return;

    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);

    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [update, enabled]);

  return position;
}

import { useEffect, type RefObject } from "react";

export function useOutsideClick(
  ref: RefObject<HTMLElement | null>,
  handler: (event: MouseEvent | TouchEvent) => void,
  enabled: boolean = true,
  ignoreRef?: RefObject<HTMLElement | null>,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: MouseEvent | TouchEvent) => {
      const el = ref.current;
      if (!el || el.contains(event.target as Node)) return;
      // Ignore clicks on the trigger/anchor element — the trigger's
      // own onClick handler manages toggling.
      if (ignoreRef?.current?.contains(event.target as Node)) return;
      handler(event);
    };

    document.addEventListener("mousedown", listener);
    document.addEventListener("touchstart", listener);

    return () => {
      document.removeEventListener("mousedown", listener);
      document.removeEventListener("touchstart", listener);
    };
  }, [ref, handler, enabled, ignoreRef]);
}

import { useEffect } from "react";

export function useEscapeKey(
  handler: () => void,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        handler();
      }
    };

    document.addEventListener("keydown", listener);
    return () => document.removeEventListener("keydown", listener);
  }, [handler, enabled]);
}

import { createContext, useContext } from "react";
import type { KanbanContextValue } from "./Kanban.types";

export const KanbanContext = createContext<KanbanContextValue | null>(null);

export function useKanban(): KanbanContextValue {
  const ctx = useContext(KanbanContext);
  if (!ctx) {
    throw new Error("Kanban compound components must be used within <Kanban>");
  }
  return ctx;
}

export const KanbanColumnContext = createContext<string>("");

export function useKanbanColumn(): string {
  return useContext(KanbanColumnContext);
}

import { useCallback, useMemo, useRef, useState } from "react";
import { cn } from "../lib/utils/cn";
import { KanbanContext } from "./Kanban.context";
import { KanbanColumn } from "./KanbanColumn";
import { KanbanCard } from "./KanbanCard";
import { KanbanColumnHandle } from "./KanbanColumnHandle";
import type { KanbanProps } from "./Kanban.types";

/**
 * Kanban board.
 *
 * Compound:
 *   <Kanban onCardMove={...} onColumnMove={...}>
 *     <Kanban.Column id="todo" wipLimit={4}>
 *       <Kanban.ColumnHandle>...header...</Kanban.ColumnHandle>  // optional
 *       <Kanban.Card id="...">...</Kanban.Card>
 *     </Kanban.Column>
 *   </Kanban>
 *
 * Cards drag between columns AND within a column. Drop position is
 * computed from mouse Y at hover time and surfaced via the `toIndex`
 * argument on `onCardMove`.
 *
 * Columns drag horizontally to reorder when a `<Kanban.ColumnHandle>`
 * is mounted inside them. The root computes the drop index from
 * mouse X and surfaces it via `onColumnMove`.
 */
function KanbanRoot({
  children,
  onCardMove,
  onColumnMove,
  className,
}: KanbanProps) {
  const [draggedCard, setDraggedCard] = useState<string | null>(null);
  const [dragSource, setDragSource] = useState<string | null>(null);
  const [draggedColumn, setDraggedColumn] = useState<string | null>(null);

  const orderRef = useRef<string[]>([]);
  const [columnIds, setColumnIds] = useState<string[]>([]);

  const registerColumn = useCallback((id: string) => {
    if (!orderRef.current.includes(id)) {
      orderRef.current = [...orderRef.current, id];
      setColumnIds(orderRef.current);
    }
    return () => {
      orderRef.current = orderRef.current.filter((x) => x !== id);
      setColumnIds(orderRef.current);
    };
  }, []);

  const ctx = useMemo(
    () => ({
      draggedCard,
      setDraggedCard,
      dragSource,
      setDragSource,
      draggedColumn,
      setDraggedColumn,
      onCardMove,
      onColumnMove,
      columnIds,
      registerColumn,
    }),
    [
      draggedCard,
      dragSource,
      draggedColumn,
      onCardMove,
      onColumnMove,
      columnIds,
      registerColumn,
    ],
  );

  // ── Column-level drop handling ────────────────────────────────────────
  // Root listens only when a column is being dragged. Drop index is
  // computed from mouse X versus each column's horizontal midpoint.
  const containerRef = useRef<HTMLDivElement>(null);

  const handleDragOver = useCallback(
    (e: React.DragEvent) => {
      if (!draggedColumn) return;
      e.preventDefault();
    },
    [draggedColumn],
  );

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      if (!draggedColumn || !containerRef.current) return;
      e.preventDefault();

      const cols = containerRef.current.querySelectorAll<HTMLElement>(
        '[data-react-fancy-kanban-column]',
      );
      const x = e.clientX;
      let dropIdx = cols.length;
      for (let i = 0; i < cols.length; i++) {
        const rect = cols[i]!.getBoundingClientRect();
        if (x < rect.left + rect.width / 2) {
          dropIdx = i;
          break;
        }
      }

      const sourceIdx = columnIds.indexOf(draggedColumn);
      // When moving rightward, dropping at index N visually means landing
      // at N - 1 after the source is removed.
      const finalIdx =
        sourceIdx >= 0 && dropIdx > sourceIdx ? dropIdx - 1 : dropIdx;

      if (finalIdx !== sourceIdx) {
        onColumnMove?.(draggedColumn, finalIdx);
      }
      setDraggedColumn(null);
    },
    [draggedColumn, columnIds, onColumnMove],
  );

  return (
    <KanbanContext.Provider value={ctx}>
      <div
        ref={containerRef}
        data-react-fancy-kanban=""
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        role="application"
        aria-roledescription="kanban board"
        className={cn("flex gap-4 overflow-x-auto p-4", className)}
      >
        {children}
      </div>
    </KanbanContext.Provider>
  );
}

export const Kanban = Object.assign(KanbanRoot, {
  Column: KanbanColumn,
  Card: KanbanCard,
  ColumnHandle: KanbanColumnHandle,
});

import type { ReactNode } from "react";

/**
 * Fired when a card is dropped into a column. `toIndex` is the position
 * the card should land at within the destination column (0-based;
 * `toIndex === current count` means append).
 *
 * For a same-column reorder, `fromColumn === toColumn` and `toIndex` is
 * the new position.
 */
export type KanbanCardMoveHandler = (
  cardId: string,
  fromColumn: string,
  toColumn: string,
  toIndex: number,
) => void;

/**
 * Fired when a column is dropped at a new position. `toIndex` is the
 * new position among registered columns (0-based).
 */
export type KanbanColumnMoveHandler = (
  columnId: string,
  toIndex: number,
) => void;

export interface KanbanContextValue {
  // Card drag state
  draggedCard: string | null;
  setDraggedCard: (id: string | null) => void;
  dragSource: string | null;
  setDragSource: (id: string | null) => void;

  // Column drag state
  draggedColumn: string | null;
  setDraggedColumn: (id: string | null) => void;

  // Callbacks
  onCardMove?: KanbanCardMoveHandler;
  onColumnMove?: KanbanColumnMoveHandler;

  // Column registration — root tracks order for column-reorder math
  columnIds: string[];
  registerColumn: (id: string) => () => void;
}

export interface KanbanProps {
  children: ReactNode;
  /**
   * Called when a card is dropped into a column. Receives the destination
   * index so handlers can support within-column reorder.
   */
  onCardMove?: KanbanCardMoveHandler;
  /**
   * Called when a column is dropped at a new position. Only fires if at
   * least one column inside the board has a `<Kanban.ColumnHandle>` and
   * a column was actually dragged.
   */
  onColumnMove?: KanbanColumnMoveHandler;
  className?: string;
}

export interface KanbanColumnProps {
  children: ReactNode;
  id: string;
  title?: string;
  className?: string;
  /**
   * Skip the column's default visuals (background, padding, min-height,
   * fixed width). Drop-target wiring and the drag-over ring stay.
   */
  unstyled?: boolean;
  /**
   * Soft work-in-progress limit. Shown in the column header (when `title`
   * is provided) as `count/limit`. Turns red over capacity. Drops are
   * still accepted — enforce hard via the consumer's `onCardMove`.
   */
  wipLimit?: number;
  /**
   * If true, the column renders nothing when it has zero card children.
   * Useful for filter UIs that want clean collapse instead of empty
   * placeholders.
   */
  hideWhenEmpty?: boolean;
}

export interface KanbanCardProps {
  children: ReactNode;
  id: string;
  className?: string;
  /**
   * Skip the card's default visuals (border, padding, shadow). Drag
   * handlers and `draggable` stay.
   */
  unstyled?: boolean;
}

export interface KanbanColumnHandleProps {
  children: ReactNode;
  className?: string;
}

import { useCallback } from "react";
import { cn } from "../lib/utils/cn";
import { useKanban, useKanbanColumn } from "./Kanban.context";
import type { KanbanCardProps } from "./Kanban.types";

const DEFAULT_CARD_CLASSES =
  "rounded-lg border border-zinc-200 bg-white p-3 shadow-sm transition-shadow hover:shadow-md dark:border-zinc-700 dark:bg-zinc-900";

export function KanbanCard({ children, id, className, unstyled }: KanbanCardProps) {
  const { setDraggedCard, setDragSource } = useKanban();
  const columnId = useKanbanColumn();

  const handleDragStart = useCallback(() => {
    setDraggedCard(id);
    setDragSource(columnId);
  }, [id, columnId, setDraggedCard, setDragSource]);

  const handleDragEnd = useCallback(() => {
    setDraggedCard(null);
    setDragSource(null);
  }, [setDraggedCard, setDragSource]);

  return (
    <div
      data-react-fancy-kanban-card=""
      draggable
      onDragStart={handleDragStart}
