export function dirtyClasses(dirty?: boolean): string {
  return dirty ? "border-l-[3px] border-l-amber-400" : "";
}

export function dirtyRingClasses(dirty?: boolean): string {
  return dirty ? "ring-2 ring-amber-400/50" : "";
}

export function errorClasses(error?: string): string {
  return error ? "border-red-500 focus:ring-red-500" : "";
}

export const inputBaseClasses =
  "border border-zinc-300 bg-white text-zinc-900 placeholder:text-zinc-400 transition-[border-color,box-shadow] duration-150 focus:outline-none focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500 disabled:opacity-50 disabled:cursor-not-allowed dark:border-zinc-700 dark:bg-[#1e1e24] dark:text-zinc-100 dark:placeholder:text-zinc-500 dark:focus:border-blue-400 dark:focus:ring-blue-400/20";

export function resolveOption<V = string>(
  option: InputOption<V>,
): { value: V; label: string; disabled?: boolean; description?: string } {
  if (typeof option === "string") {
    return { value: option as unknown as V, label: option };
  }
  return option;
}

import { createContext, useContext } from "react";
import type { FieldMode } from "../inputs.types";

export interface FieldModeContextValue {
  mode: FieldMode;
}

export const FieldModeContext = createContext<FieldModeContextValue | null>(null);

/**
 * Resolve the effective mode for an input. Precedence: an explicit prop wins,
 * then the nearest `<Form>` / `<FormProvider>` context, then `"edit"`.
 *
 * Deliberately tolerant (returns `"edit"` outside any provider) — unlike a slot
 * guard — so every input works standalone with zero context and existing call
 * sites behave identically.
 */
export function useFieldMode(explicit?: FieldMode): FieldMode {
  const ctx = useContext(FieldModeContext);
  return explicit ?? ctx?.mode ?? "edit";
}

import type { KeyboardEvent, ReactNode } from "react";
import { cn } from "../../../utils/cn";
import type { Size } from "../../../utils/types";
import { inputSizeClasses } from "../inputs.utils";

export interface DisplayValueProps {
  /** The formatted value to show. Empty / null / undefined renders `empty`. */
  children?: ReactNode;
  size?: Size;
  /** Static adornment rendered before the value (mirrors an input's `leading`/`prefix`). */
  leading?: ReactNode;
  /** Static adornment rendered after the value (mirrors an input's `trailing`/`suffix`). */
  trailing?: ReactNode;
  /** Shown when the value is empty. Default `—`. */
  empty?: ReactNode;
  /** When true the value is clickable to enter edit mode (inline click-to-edit). */
  interactive?: boolean;
  /** Called when an interactive value is activated (click / Enter / Space). */
  onActivate?: () => void;
  className?: string;
}

function isEmpty(value: ReactNode): boolean {
  return value === null || value === undefined || value === "";
}

/**
 * The read-only counterpart to an `<input>`. Renders a non-interactive value
 * with the same size rhythm as the editable control (reusing
 * {@link inputSizeClasses}) but without the border / background / focus ring.
 *
 * When `interactive` (inline click-to-edit), the value becomes a focusable,
 * hoverable target that calls `onActivate` on click / Enter / Space to swap in
 * the real control. Dropped into the SAME `Field` wrapper the editable control
 * uses, so label / description / error chrome stays byte-identical between the
 * display and the editor.
 *
 * Carries `data-react-fancy-display` / `data-mode="view"` stable handles for
 * agents and tests (Human+ contract).
 */
export function DisplayValue({
  children,
  size = "md",
  leading,
  trailing,
  empty = "—",
  interactive,
  onActivate,
  className,
}: DisplayValueProps) {
  const empties = isEmpty(children);

  const onKeyDown = interactive
    ? (e: KeyboardEvent<HTMLDivElement>) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onActivate?.();
        }
      }
    : undefined;

  return (
    <div
      data-react-fancy-display=""
      data-mode="view"
      role={interactive ? "button" : undefined}
      tabIndex={interactive ? 0 : undefined}
      title={interactive ? "Click to edit" : undefined}
      onClick={interactive ? onActivate : undefined}
      onKeyDown={onKeyDown}
      className={cn(
        "flex w-full items-center gap-2 text-zinc-900 dark:text-zinc-100",
        inputSizeClasses[size],
        // Strip the editable box look — keep only the size/padding rhythm.
        "border-0 bg-transparent px-0",
        interactive &&
          "-mx-2 cursor-text rounded-md px-2 outline-none transition-colors hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-blue-500/40 dark:hover:bg-zinc-800",
        empties && "text-zinc-400 dark:text-zinc-500",
        className,
      )}
    >
      {leading && <span className="text-zinc-400 dark:text-zinc-500">{leading}</span>}
      <span className="min-w-0 truncate">{empties ? empty : children}</span>
      {trailing && <span className="text-zinc-400 dark:text-zinc-500">{trailing}</span>}
    </div>
  );
}

import { useCallback, useState } from "react";
import type { FieldMode } from "../inputs.types";

export interface InlineEdit {
  /** Render the editable control (`true`) vs. the read-only value display (`false`). */
  showControl: boolean;
  /** Whether view mode is interactive (click-to-edit) — i.e. `view` and not disabled. */
  interactive: boolean;
  /** Enter edit mode (no-op unless interactive). */
  enterEdit: () => void;
  /** Leave edit mode, back to the value display. */
  exitEdit: () => void;
}

/**
 * Inline click-to-edit for `mode="view"`. The bound value shows as clean static
 * text; clicking it swaps in the focused control; blur returns to the display
 * (the control's `onChange` / `onBlur` fire as usual, so a host can persist on
 * commit). `mode="edit"` is always the control; a **disabled** view stays static
 * text (no click-to-edit).
 *
 * This is the value of "view mode": tidy read-only surfaces where each field
 * becomes editable only when the user reaches for it.
 */
export function useInlineEdit(mode: FieldMode, disabled?: boolean): InlineEdit {
  const [editing, setEditing] = useState(false);
  const interactive = mode === "view" && !disabled;
  const showControl = mode !== "view" || (interactive && editing);
  const enterEdit = useCallback(() => {
    if (interactive) setEditing(true);
  }, [interactive]);
  const exitEdit = useCallback(() => setEditing(false), []);
  return { showControl, interactive, enterEdit, exitEdit };
}

/**
 * HTML and URL sanitization utilities.
 *
 * Hand-rolled (no third-party deps) using browser-native `DOMParser`. Designed
 * for the trust model "consumer passes user-generated markdown/HTML to a
 * react-fancy component" — strips script tags, event handlers, and dangerous
 * URI schemes from `href`/`src` attributes.
 *
 * For server-side rendering (no `window`), `sanitizeHtml` returns the input
 * unchanged. Consumers SSR-rendering untrusted content should sanitize on the
 * server with their own pipeline.
 */

const DANGEROUS_TAGS = new Set([
  "script",
  "style",
  "iframe",
  "object",
  "embed",
  "link",
  "meta",
  "base",
  "form",
]);

const URL_ATTRS = new Set(["href", "src", "action", "formaction", "xlink:href"]);

const SAFE_PROTOCOL = /^(?:https?:|mailto:|tel:|sms:|ftp:|#|\/|\.\/|\.\.\/|[^:]*$)/i;

/**
 * Validate a URL/href against an allow-list of safe protocols. Returns the
 * input if safe, or `undefined` if it begins with a dangerous scheme like
 * `javascript:`, `data:`, or `vbscript:`. Relative URLs and fragment links
 * are allowed.
 */
export function sanitizeHref(href: string | undefined | null): string | undefined {
  if (href == null) return undefined;
  const trimmed = href.trim();
  if (!trimmed) return undefined;
  return SAFE_PROTOCOL.test(trimmed) ? trimmed : undefined;
}

function stripDangerousAttrs(el: Element): void {
  // Collect names first; mutating during iteration is awkward with NamedNodeMap.
  const names: string[] = [];
  for (let i = 0; i < el.attributes.length; i++) {
    names.push(el.attributes[i].name);
  }

  for (const name of names) {
    const lower = name.toLowerCase();

    // All on* event handlers
    if (lower.startsWith("on")) {
      el.removeAttribute(name);
      continue;
    }

    // URL attributes — protocol-filter
    if (URL_ATTRS.has(lower)) {
      const sanitized = sanitizeHref(el.getAttribute(name));
      if (sanitized === undefined) {
        el.removeAttribute(name);
      } else {
        el.setAttribute(name, sanitized);
      }
      continue;
    }

    // srcdoc executes JS in the iframe — drop wholesale
    if (lower === "srcdoc") {
      el.removeAttribute(name);
    }
  }
}

function walk(el: Element, removeQueue: Element[]): void {
  const tag = el.tagName.toLowerCase();

  if (DANGEROUS_TAGS.has(tag)) {
    removeQueue.push(el);
    return;
  }

  stripDangerousAttrs(el);

  const children = Array.from(el.children);
  for (const child of children) {
    walk(child, removeQueue);
  }
}

/**
 * Sanitize an HTML string by removing dangerous tags (script, iframe, etc.),
 * event-handler attributes (`onclick`, `onerror`, ...), and dangerous URI
 * schemes in `href`/`src` attributes.
 *
 * Uses the browser's `DOMParser`. In non-browser environments returns the
 * input unchanged — sanitize on the server in those cases.
 */
export function sanitizeHtml(html: string): string {
  if (typeof window === "undefined" || typeof DOMParser === "undefined") {
    return html;
  }

  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");
  const body = doc.body;
  if (!body) return html;

  const removeQueue: Element[] = [];
  for (const child of Array.from(body.children)) {
    walk(child, removeQueue);
  }

  for (const el of removeQueue) {
    el.parentNode?.removeChild(el);
  }

  return body.innerHTML;
}

import { EMOJI_DATA, EMOJI_ENTRIES, type EmojiCategoryKey, type EmojiEntry } from "./emoji-data";

export const SKIN_TONES = ["light", "medium-light", "medium", "medium-dark", "dark"] as const;
export type SkinTone = typeof SKIN_TONES[number];

type IndexedEntry = EmojiEntry & { category: EmojiCategoryKey };

let byName: Map<string, IndexedEntry> | null = null;
let byChar: Map<string, IndexedEntry> | null = null;

function ensureIndexes() {
  if (byName && byChar) return;
  byName = new Map();
  byChar = new Map();
  for (const [category, group] of Object.entries(EMOJI_DATA) as [EmojiCategoryKey, typeof EMOJI_DATA[EmojiCategoryKey]][]) {
    for (const emoji of group.emojis) {
      const entry: IndexedEntry = { ...emoji, category };
      byName.set(emoji.name.toLowerCase(), entry);
      byChar.set(emoji.char, entry);
      if (emoji.skinTones) {
        for (const toned of emoji.skinTones) {
          byChar.set(toned, entry);
        }
      }
    }
  }
}

/** Resolve an emoji name to its character. */
export function resolve(name: string): string | undefined {
  ensureIndexes();
  return byName!.get(name.toLowerCase())?.char;
}

/** Search emojis by name substring. Returns matching base emoji characters. */
export function search(query: string): string[] {
  const lower = query.toLowerCase();
  return EMOJI_ENTRIES.filter((e) => e.name.includes(lower)).map((e) => e.char);
}

/** Find an emoji entry by its character (toned or base). */
export function find(char: string): IndexedEntry | undefined {
  ensureIndexes();
  return byChar!.get(char);
}

/** Return the 5-tone variant array for an emoji (by char, toned or base). */
export function skinTones(char: string): readonly [string, string, string, string, string] | undefined {
  return find(char)?.skinTones;
}

/** Whether an emoji supports skin tones. */
export function hasSkinTones(char: string): boolean {
  return !!find(char)?.skinTones;
}

/** Return the toned variant for an emoji, or the base if no tones. */
export function applyTone(char: string, tone: SkinTone | null): string {
  if (!tone) return char;
  const entry = find(char);
  if (!entry?.skinTones) return char;
  const idx = SKIN_TONES.indexOf(tone);
  return entry.skinTones[idx] ?? char;
}

import type { ReactNode } from "react";
import type { Size } from "../../utils/types";

export type InputOption<V = string> =
  | string
  | { value: V; label: string; disabled?: boolean; description?: string };

export type InputOptionGroup<V = string> = {
  label: string;
  options: InputOption<V>[];
};

/**
 * Edit vs. read-only display. In `"view"` mode an input renders the bound value
 * as static text instead of an interactive control — the React/Inertia analog of
 * Livewire's public/bindable properties. Declared here (rather than in `mode/`)
 * to keep `InputBaseProps` free of an import cycle. Resolved per input via
 * {@link useFieldMode}: explicit prop → `<Form>`/`<FormProvider>` context → `"edit"`.
 */
export type FieldMode = "edit" | "view";

export interface InputBaseProps {
  size?: Size;
  dirty?: boolean;
  error?: string;
  label?: string;
  /**
   * Keep the label for assistive tech, but do not draw it.
   *
   * For a control whose options already say what it does — a filter toolbar's
   * segmented switches, say — where a visible label is noise but an unnamed
   * control is a bug. Without this the only choices were an unnamed control or
   * a label the design does not have, and the silent one is the one that ships.
   */
  labelHidden?: boolean;
  description?: string;
  required?: boolean;
  disabled?: boolean;
  className?: string;
  id?: string;
  name?: string;
  /** `"edit"` (default) renders the control; `"view"` renders the value as text. Overrides the `<Form mode>` context. */
  mode?: FieldMode;
}

export type AffixPosition = "inside" | "outside";

export interface InputAffixProps {
  prefix?: ReactNode;
  suffix?: ReactNode;
  prefixPosition?: AffixPosition;
  suffixPosition?: AffixPosition;
}

import { useEffect, useRef, useState, type CSSProperties } from "react";
import type { LatLng, MapHandle, MapMarker, MapProvider, MapView } from "./types";

export type MapProps = {
  /** The map engine to render with — `leafletProvider()` / `googleProvider({ apiKey })`. */
  provider: MapProvider;
  /** Controlled camera. */
  view: MapView;
  /** Fires when the user pans/zooms (or a provider animation settles). */
  onViewChange?: (view: MapView) => void;
  /** Controlled markers (JSON-friendly; an agent can emit these directly). */
  markers?: MapMarker[];
  /** Controlled selection. */
  selectedId?: string | null;
  onSelect?: (id: string | null, marker?: MapMarker) => void;
  /** Fires when a draggable marker is released. */
  onMarkerDragEnd?: (id: string, position: LatLng) => void;
  /** Fires when the map background (not a marker) is clicked. */
  onMapClick?: (position: LatLng) => void;
  /**
   * Live follow — keep this marker centered as its position updates. Set it to a
   * moving marker's id (a vehicle, a delivery, the agent) for live tracking.
   */
  follow?: string | null;
  /** One-shot: fit the camera to enclose these points (re-runs on array identity change). */
  fitTo?: LatLng[];
  /** Grab the imperative handle once the engine is live (e.g. for a bridge's fitBounds). */
  onReady?: (handle: MapHandle) => void;
  /** Called if the provider fails to mount (e.g. Google SDK load error). */
  onError?: (error: unknown) => void;
  className?: string;
  style?: CSSProperties;
  "aria-label"?: string;
};

const EMPTY_MARKERS: MapMarker[] = [];

/** Whether two cameras are close enough to treat as "the same" (echo guard). */
function viewsClose(a: MapView, b: MapView): boolean {
  return (
    Math.abs(a.center.lat - b.center.lat) < 1e-7 &&
    Math.abs(a.center.lng - b.center.lng) < 1e-7 &&
    Math.abs(a.zoom - b.zoom) < 1e-3
  );
}

/**
 * The engine-agnostic map surface. Fully controlled (view + markers + selection),
 * SSR-safe (renders a sized placeholder on the server; the provider mounts inside
 * an effect, so there's no `window`/engine access during render and no hydration
 * mismatch), and driveable by both a human and — via the Human+ map bridge in
 * `@particle-academy/agent-integrations` — an agent, over the same controlled state.
 */
export function Map({
  provider,
  view,
  onViewChange,
  markers = EMPTY_MARKERS,
  selectedId = null,
  onSelect,
  onMarkerDragEnd,
  onMapClick,
  follow = null,
  fitTo,
  onReady,
  onError,
  className,
  style,
  "aria-label": ariaLabel = "Map",
}: MapProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const handleRef = useRef<MapHandle | null>(null);
  // A bump counter that flips once the (async) provider handle is live, so the
  // prop-sync effects below re-run and apply current props to the fresh engine.
  const [ready, setReady] = useState(0);

  // Latest callbacks + the initial mount snapshot, kept in refs so the mount
  // effect stays mount-once (it only re-runs when the provider identity changes).
  const cbRef = useRef({ onViewChange, onSelect, onMarkerDragEnd, onMapClick, onReady, onError });
  cbRef.current = { onViewChange, onSelect, onMarkerDragEnd, onMapClick, onReady, onError };
  const initialRef = useRef({ view, markers, selectedId });
  // The last camera the map itself emitted — lets the view-sync effect ignore
  // the echo of a user pan (which would otherwise fight the animation).
  const lastEmitted = useRef<MapView | null>(null);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) {
      return;
    }
    let disposed = false;
    let handle: MapHandle | null = null;
    const offs: Array<() => void> = [];

    Promise.resolve(
      provider.mount(host, {
        view: initialRef.current.view,
        markers: initialRef.current.markers,
        selectedId: initialRef.current.selectedId,
        interactive: true,
      }),
    )
      .then((h) => {
        if (disposed) {
          h.destroy();
          return;
        }
        handle = h;
        handleRef.current = h;
        offs.push(
          h.on("viewchange", (v) => {
            lastEmitted.current = v;
            cbRef.current.onViewChange?.(v);
          }),
          h.on("markerclick", ({ id, marker }) => cbRef.current.onSelect?.(id, marker)),
          h.on("markerdragend", ({ id, position }) => cbRef.current.onMarkerDragEnd?.(id, position)),
          h.on("click", ({ position }) => cbRef.current.onMapClick?.(position)),
        );
        cbRef.current.onReady?.(h);
        setReady((n) => n + 1);
      })
      .catch((err) => {
        if (!disposed) {
          cbRef.current.onError?.(err);
        }
      });

    return () => {
      disposed = true;
      for (const off of offs) {
        off();
      }
      handle?.destroy();
      if (handleRef.current === handle) {
        handleRef.current = null;
      }
    };
  }, [provider]);

  // Sync camera — skip the echo of the map's own emitted view.
  useEffect(() => {
    const h = handleRef.current;
    if (!h) {
      return;
    }
    if (lastEmitted.current && viewsClose(lastEmitted.current, view)) {
      return;
    }
    h.setView(view, true);
  }, [view, ready]);

  // Sync markers (provider diffs internally — cheap on live-tracking updates).
  useEffect(() => {
    handleRef.current?.setMarkers(markers);
  }, [markers, ready]);

  // Sync selection.
  useEffect(() => {
    handleRef.current?.setSelected(selectedId);
  }, [selectedId, ready]);

  // Live follow — recenter on the followed marker whenever it moves.
  useEffect(() => {
    if (!follow) {
      return;
    }
    const h = handleRef.current;
    if (!h) {
      return;
    }
    const m = markers.find((x) => x.id === follow);
    if (m) {
      h.setView({ center: m.position }, true);
    }
  }, [follow, markers, ready]);

  // One-shot fit.
  useEffect(() => {
    if (fitTo && fitTo.length) {
      handleRef.current?.fitBounds(fitTo);
    }
  }, [fitTo, ready]);

  return (
    <div
      ref={hostRef}
      className={className}
      role="region"
      aria-label={ariaLabel}
      data-fancy-map={provider.name}
      style={{ position: "relative", width: "100%", height: "100%", minHeight: 240, ...style }}
    />
  );
}

/**
 * fancy-map core types — provider-agnostic. Leaflet, Google Maps, and any
 * future engine (MapLibre, Mapbox GL) speak this same vocabulary, so swapping
 * the `provider` prop is the only change needed to move between map engines.
 *
 * Coordinates are `{ lat, lng }` objects (not `[lng, lat]` tuples): it matches
 * both Leaflet (`L.latLng`) and Google (`{ lat, lng }`) native conventions and
 * reads unambiguously in agent-emitted JSON.
 */

/** A geographic point. */
export type LatLng = { lat: number; lng: number };

/** The camera. `bearing`/`pitch` are honored only by providers that support them. */
export type MapView = {
  center: LatLng;
  zoom: number;
  bearing?: number;
  pitch?: number;
};

/**
 * A map marker. JSON-friendly so an agent can emit an array of these directly.
 * `id` is the stable handle — it appears as `data-map-marker-id` on the rendered
 * element and is how selection, updates, and the bridge address a marker.
 */
export type MapMarker = {
  id: string;
  position: LatLng;
  /** Tooltip / popup label. */
  label?: string;
  /** CSS color for the default pin (e.g. "#2563eb"). */
  color?: string;
  /** Emoji or 1–2 chars rendered inside the pin (e.g. "🚚", "A"). */
  icon?: string;
  /** Whether the human can drag this marker (fires onMarkerDragEnd). */
  draggable?: boolean;
  /** Arbitrary JSON payload carried with the marker (agent/host use). */
  data?: Record<string, unknown>;
};

/** Payloads for the events a {@link MapHandle} emits. */
export type MapEventMap = {
  /** Camera moved (user pan/zoom or a provider animation settling). */
  viewchange: MapView;
  /** A marker was clicked. */
  markerclick: { id: string; marker: MapMarker };
  /** A draggable marker was released. */
  markerdragend: { id: string; position: LatLng };
  /** The map background (not a marker) was clicked. */
  click: { position: LatLng };
};

/** Options a provider receives when the component mounts it. */
export type MapMountOptions = {
  view: MapView;
  markers: MapMarker[];
  selectedId?: string | null;
  /** True when the component is server/hydration constrained; providers ignore. */
  interactive?: boolean;
};

/**
 * The imperative handle a provider returns from {@link MapProvider.mount}. The
 * `<Map>` component drives it from props, and the Human+ bridge drives it from
 * an agent — both through this one surface.
 */
export type MapHandle = {
  /** Move the camera. Partial: pass only what changes. */
  setView(view: Partial<MapView>, animate?: boolean): void;
  /** Read the current camera. */
  getView(): MapView;
  /** Reconcile the rendered markers to exactly this set (providers diff). */
  setMarkers(markers: MapMarker[]): void;
  /** Highlight one marker (or clear with null). */
  setSelected(id: string | null): void;
  /** Fit the camera to enclose all points (with optional px padding). */
  fitBounds(points: LatLng[], padding?: number): void;
  /** Subscribe to an event; returns an unsubscribe fn. */
  on<K extends keyof MapEventMap>(event: K, cb: (payload: MapEventMap[K]) => void): () => void;
  /** Tear down the engine and release the host element. */
  destroy(): void;
};

/**
 * A map engine, ready to mount. Created by `leafletProvider()` /
 * `googleProvider({ apiKey })`. `mount` may be async (Google loads its SDK over
 * the network) — the component awaits it.
 */
export type MapProvider = {
  name: string;
  mount(host: HTMLElement, options: MapMountOptions): MapHandle | Promise<MapHandle>;
};

import { cn, ContentRenderer, useControllableState } from "@particle-academy/react-fancy";
import { CodeEditor } from "../code-editor";

export type MarkdownEditorMode = "split" | "edit" | "preview";

export interface MarkdownEditorProps {
  /** Controlled markdown value. */
  value?: string;
  /** Initial value (uncontrolled). */
  defaultValue?: string;
  /** Called with the new markdown whenever the document changes. */
  onValueChange?: (markdown: string) => void;
  /**
   * Layout: `split` (editor + live preview side by side), `edit` (editor only),
   * or `preview` (rendered only). Default `split`.
   */
  mode?: MarkdownEditorMode;
  /** Editor theme — `"light" | "dark" | "auto"` or a registered name. Default `auto`. */
  theme?: string;
  /** Prevent editing. */
  readOnly?: boolean;
  /** Show line numbers in the editor (default false — prose reads better without). */
  lineNumbers?: boolean;
  /** Wrap long lines in the editor (default true for prose). */
  wordWrap?: boolean;
  /** Placeholder shown when empty. */
  placeholder?: string;
  /**
   * Height bounds (px). `maxHeight` constrains the PREVIEW pane as well as the
   * editor — it previously reached only the editor, so a long document rendered
   * at full height instead of scrolling.
   */
  minHeight?: number;
  maxHeight?: number;
  className?: string;
  /**
   * Swap the markdown → HTML renderer used by the preview pane.
   *
   * Rarely needed now: the preview renders through react-fancy's
   * `<ContentRenderer format="markdown">`, which is a full CommonMark + GFM
   * parse. Supply this only to impose your own pipeline — the returned HTML is
   * injected as-is, so it must already be sanitised.
   */
  renderPreview?: (markdown: string) => string;
}

/**
 * A markdown-aware editor: a syntax-highlighted `CodeEditor` (the registered
 * `markdown` language) with an optional live preview pane. Controlled via
 * `value` + `onValueChange`. The preview renders through react-fancy's
 * `<ContentRenderer format="markdown">` — a full CommonMark + GFM parse,
 * sanitised by default. Pass `renderPreview` to impose your own pipeline.
 *
 * ```tsx
 * <MarkdownEditor value={md} onValueChange={setMd} mode="split" minHeight={240} />
 * ```
 */
export function MarkdownEditor({
  value,
  defaultValue = "",
  onValueChange,
  mode = "split",
  theme = "auto",
  readOnly = false,
  lineNumbers = false,
  wordWrap = true,
  placeholder,
  minHeight,
  maxHeight,
  className,
  renderPreview,
}: MarkdownEditorProps) {
  const [content, setContent] = useControllableState(value, defaultValue, onValueChange);

  const showEditor = mode !== "preview";
  const showPreview = mode !== "edit";

  return (
    <div
      data-fancy-markdown-editor=""
      data-mode={mode}
      className={cn("fancy-md-editor", className)}
    >
      {showEditor && (
        <div className="fancy-md-editor-pane">
          <CodeEditor
            value={content}
            onChange={setContent}
            language="markdown"
            theme={theme}
            readOnly={readOnly}
            lineNumbers={lineNumbers}
            wordWrap={wordWrap}
            placeholder={placeholder}
            minHeight={minHeight}
            maxHeight={maxHeight}
          >
            <CodeEditor.Panel />
          </CodeEditor>
        </div>
      )}
      {showPreview && (
        <div
          data-fancy-markdown-preview=""
          className="fancy-md-preview"
          style={maxHeight ? { maxHeight, overflowY: "auto" } : undefined}
        >
          {renderPreview ? (
            // The host imposed its own pipeline; its HTML is injected as-is and
            // is its own responsibility to sanitise.
            <div dangerouslySetInnerHTML={{ __html: renderPreview(content) }} />
          ) : (
            // The kit's own renderer — a full CommonMark + GFM parse that
            // sanitises by default. `marked` already sits in this tree as a
            // react-fancy runtime dependency, so the built-in renderer this
            // replaced was a second, weaker markdown implementation next to a
            // complete one.
            <ContentRenderer value={content} format="markdown" />
          )}
        </div>
      )}
    </div>
  );
}

MarkdownEditor.displayName = "MarkdownEditor";

import { useEffect, useRef, useCallback, useState, useMemo, type RefObject } from "react";
import { getLanguage } from "../languages";
import { getTheme } from "../themes";
import { highlightCode } from "../engine/highlight";
import { lineColumnToOffset } from "../engine/position";
import type { ThemeColors } from "../themes/types";
import type { Tokenizer } from "../engine/tokenizer";

export interface UseEditorEngineOptions {
  containerRef: RefObject<HTMLDivElement | null>;
  value: string;
  onChange?: (value: string) => void;
  language: string;
  theme: string;
  readOnly: boolean;
  lineNumbers: boolean;
  wordWrap: boolean;
  tabSize: number;
  placeholder?: string;
  minHeight?: number;
  maxHeight?: number;
  onCursorChange?: (pos: { line: number; col: number; selectionLength: number }) => void;
}

export interface UseEditorEngineReturn {
  textareaRef: RefObject<HTMLTextAreaElement | null>;
  highlightedHtml: string;
  lineCount: number;
  activeLine: number;
  themeColors: ThemeColors;
  handleKeyDown: (e: React.KeyboardEvent<HTMLTextAreaElement>) => void;
  handleInput: () => void;
  handleScroll: () => void;
  handleSelect: () => void;
  /**
   * Place the caret on a 1-based `line` / `column` and scroll the editor so the
   * line is centered in view. Out-of-range positions clamp to document bounds.
   */
  revealLine: (line: number, column?: number, opts?: { focus?: boolean }) => void;
  scrollTop: number;
  scrollLeft: number;
}

const DEFAULT_COLORS: ThemeColors = {
  background: "#18181b",
  foreground: "#e4e4e7",
  gutterBackground: "#18181b",
  gutterForeground: "#52525b",
  gutterBorder: "#27272a",
  activeLineBackground: "#27272a",
  selectionBackground: "#1e3a5f",
  cursorColor: "#60a5fa",
  keyword: "#c084fc",
  string: "#34d399",
  comment: "#71717a",
  number: "#fbbf24",
  operator: "#22d3ee",
  function: "#60a5fa",
  type: "#fbbf24",
  tag: "#f87171",
  attribute: "#fbbf24",
  attributeValue: "#34d399",
  punctuation: "#a1a1aa",
  variable: "#e4e4e7",
};

export function useEditorEngine({
  value,
  onChange,
  language,
  theme,
  readOnly,
  wordWrap,
  tabSize,
  onCursorChange,
}: UseEditorEngineOptions): UseEditorEngineReturn {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const onChangeRef = useRef(onChange);
  const onCursorChangeRef = useRef(onCursorChange);
  onChangeRef.current = onChange;
  onCursorChangeRef.current = onCursorChange;

  const [scrollTop, setScrollTop] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [activeLine, setActiveLine] = useState(1);

  // Resolve theme colors
  const themeColors = useMemo<ThemeColors>(() => {
    const def = getTheme(theme);
    return def?.colors ?? DEFAULT_COLORS;
  }, [theme]);

  // Resolve tokenizer
  const tokenizer = useMemo<Tokenizer | null>(() => {
    const def = getLanguage(language);
    return def?.tokenize ?? null;
  }, [language]);

  // Generate highlighted HTML
  const highlightedHtml = useMemo(() => {
    if (!tokenizer) {
      // No tokenizer — just escape HTML
      return value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
    }
    const tokens = tokenizer(value);
    return highlightCode(value, tokens, themeColors);
  }, [value, tokenizer, themeColors]);

  const lineCount = useMemo(() => {
    let count = 1;
    for (let i = 0; i < value.length; i++) {
      if (value[i] === "\n") count++;
    }
    return count;
  }, [value]);

  // Auto-resize textarea to match content so caret is always visible
  const autoResize = useCallback(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    ta.style.height = "auto";
    ta.style.height = ta.scrollHeight + "px";

    if (!wordWrap) {
      // Shrink to 0 to measure true content width, then expand
      ta.style.width = "0";
      ta.style.width = ta.scrollWidth + "px";
    } else {
      ta.style.width = "";
    }
  }, [wordWrap]);

  // Sync textarea value and auto-resize when value changes
  useEffect(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    if (ta.value !== value) {
      const { selectionStart, selectionEnd } = ta;
      ta.value = value;
      ta.selectionStart = selectionStart;
      ta.selectionEnd = selectionEnd;
    }
    // Always resize — handles initial mount and external value changes
    autoResize();
  }, [value, autoResize]);

  const updateCursorInfo = useCallback(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    const pos = ta.selectionStart;
    const textBefore = ta.value.slice(0, pos);
    const line = (textBefore.match(/\n/g) || []).length + 1;
    const lastNewline = textBefore.lastIndexOf("\n");
    const col = pos - lastNewline;
    const selLen = Math.abs(ta.selectionEnd - ta.selectionStart);
    setActiveLine(line);
    onCursorChangeRef.current?.({ line, col, selectionLength: selLen });
  }, []);

  const handleInput = useCallback(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    onChangeRef.current?.(ta.value);
    autoResize();
    updateCursorInfo();
  }, [autoResize, updateCursorInfo]);

  const handleSelect = useCallback(() => {
    updateCursorInfo();
  }, [updateCursorInfo]);

  const handleScroll = useCallback(() => {
    const ta = textareaRef.current;
    if (!ta) return;
    setScrollTop(ta.scrollTop);
    setScrollLeft(ta.scrollLeft);
  }, []);

  const revealLine = useCallback(
    (line: number, column = 1, opts?: { focus?: boolean }) => {
      const ta = textareaRef.current;
      if (!ta) return;

      const offset = lineColumnToOffset(ta.value, line, column);
      if (opts?.focus) ta.focus();
      ta.selectionStart = ta.selectionEnd = offset;
      updateCursorInfo();

      // Scroll the editor's scroll container (the panel) so the target line is
      // centered. The textarea is auto-sized to fit its content, so the panel —
      // not the textarea — is what scrolls.
      const panel = ta.closest<HTMLElement>("[data-fancy-code-panel]");
      if (!panel) return;
      const cs = getComputedStyle(ta);
      const lineHeight = parseFloat(cs.lineHeight) || 19.5;
      const paddingTop = parseFloat(cs.paddingTop) || 0;
      const lineIndex = (ta.value.slice(0, offset).match(/\n/g) || []).length; // clamped (targetLine - 1)
      const textareaTopInPanel =
        ta.getBoundingClientRect().top - panel.getBoundingClientRect().top + panel.scrollTop;
      const lineTop = textareaTopInPanel + paddingTop + lineIndex * lineHeight;
      const target = lineTop - panel.clientHeight / 2 + lineHeight / 2;
      const maxScroll = panel.scrollHeight - panel.clientHeight;
      panel.scrollTop = Math.max(0, Math.min(target, maxScroll));
    },
    [updateCursorInfo],
  );

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (readOnly) {
        // Allow copy shortcuts in read-only mode
        if (e.key === "c" && (e.metaKey || e.ctrlKey)) return;
        if (e.key === "a" && (e.metaKey || e.ctrlKey)) return;
        e.preventDefault();
        return;
      }

      // Tab key — insert spaces
      if (e.key === "Tab") {
        e.preventDefault();
        const ta = e.currentTarget;
        const start = ta.selectionStart;
        const end = ta.selectionEnd;
        const spaces = " ".repeat(tabSize);

        if (e.shiftKey) {
          // Dedent: remove leading spaces from selected lines
          const lines = ta.value.split("\n");
          const startLine = ta.value.slice(0, start).split("\n").length - 1;
          const endLine = ta.value.slice(0, end).split("\n").length - 1;
          let removed = 0;
          for (let i = startLine; i <= endLine; i++) {
            const match = lines[i].match(new RegExp(`^ {1,${tabSize}}`));
            if (match) {
              removed += match[0].length;
              lines[i] = lines[i].slice(match[0].length);
            }
          }
          const newValue = lines.join("\n");
          ta.value = newValue;
          ta.selectionStart = Math.max(0, start - (startLine === endLine ? removed : tabSize));
          ta.selectionEnd = Math.max(0, end - removed);
          onChangeRef.current?.(newValue);
        } else if (start !== end) {
          // Indent selected lines
          const lines = ta.value.split("\n");
          const startLine = ta.value.slice(0, start).split("\n").length - 1;
          const endLine = ta.value.slice(0, end).split("\n").length - 1;
          for (let i = startLine; i <= endLine; i++) {
            lines[i] = spaces + lines[i];
          }
          const newValue = lines.join("\n");
          ta.value = newValue;
          ta.selectionStart = start + tabSize;
          ta.selectionEnd = end + (endLine - startLine + 1) * tabSize;
          onChangeRef.current?.(newValue);
        } else {
          // Insert tab at cursor
          const before = ta.value.slice(0, start);
          const after = ta.value.slice(end);
          ta.value = before + spaces + after;
          ta.selectionStart = ta.selectionEnd = start + tabSize;
          onChangeRef.current?.(ta.value);
        }
        autoResize();
        updateCursorInfo();
        return;
      }

      // Enter — auto-indent
      if (e.key === "Enter") {
        e.preventDefault();
        const ta = e.currentTarget;
        const start = ta.selectionStart;
        const end = ta.selectionEnd;
        const before = ta.value.slice(0, start);
        const after = ta.value.slice(end);
        const currentLine = before.split("\n").pop() || "";
        const indent = currentLine.match(/^(\s*)/)?.[1] || "";

        // Extra indent after { or (
        const lastChar = before.trimEnd().slice(-1);
        const extraIndent = (lastChar === "{" || lastChar === "(") ? " ".repeat(tabSize) : "";

        const insertion = "\n" + indent + extraIndent;
        ta.value = before + insertion + after;
        ta.selectionStart = ta.selectionEnd = start + insertion.length;
        onChangeRef.current?.(ta.value);
        autoResize();
        updateCursorInfo();
        return;
      }
    },
    [readOnly, tabSize, autoResize, updateCursorInfo],
  );

  return {
    textareaRef,
    highlightedHtml,
    lineCount,
    activeLine,
    themeColors,
    handleKeyDown,
    handleInput,
    handleScroll,
    handleSelect,
    revealLine,
    scrollTop,
    scrollLeft,
  };
}

import { useSyncExternalStore } from "react";

function subscribe(callback: () => void): () => void {
  const mq = window.matchMedia("(prefers-color-scheme: dark)");
  mq.addEventListener("change", callback);
  return () => mq.removeEventListener("change", callback);
}

function getSnapshot(): boolean {
  return window.matchMedia("(prefers-color-scheme: dark)").matches;
}

function getServerSnapshot(): boolean {
  return false;
}

export function useDarkMode(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

