  return themeRegistry.get(name.toLowerCase());
}

export function getRegisteredThemes(): string[] {
  return Array.from(themeRegistry.keys());
}

import {
  Children,
  Fragment,
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { cn } from "../lib/utils/cn";
import type { MarqueeProps } from "./Marquee.types";

function toLength(value: string | number): string {
  return typeof value === "number" ? `${value}px` : value;
}

export const Marquee = forwardRef<HTMLDivElement, MarqueeProps>(
  (
    {
      children,
      items,
      speed = 40,
      duration,
      direction = "left",
      pauseOnHover = false,
      paused = false,
      gap = 40,
      fade = true,
      separator,
      angle = 0,
      decorative = true,
      className,
      style,
      ...rest
    },
    ref,
  ) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const unitRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

    // copies = how many times the item sequence repeats inside ONE loop copy,
    // so short content still fills the strip edge-to-edge (no blank wrap).
    const [copies, setCopies] = useState(1);
    const [measuredDuration, setMeasuredDuration] = useState<number | null>(null);

    // Measure one content unit (incl. its trailing gap) + the container:
    //  - auto-fill: repeat the unit until one loop copy covers the container
    //  - px/s mode: derive the loop duration from the loop distance so the
    //    perceived speed stays constant regardless of content width.
    // Browser-only (effect) — SSR renders one unit at the fallback pace.
    useEffect(() => {
      const root = rootRef.current;
      const unit = unitRef.current;
      if (!root || !unit || typeof ResizeObserver === "undefined") return;
      const update = () => {
        const unitWidth = unit.getBoundingClientRect().width;
        const containerWidth = root.clientWidth;
        if (unitWidth <= 0) return;
        const nextCopies = Math.max(1, Math.ceil(containerWidth / unitWidth));
        setCopies(nextCopies);
        if (duration === undefined) {
          setMeasuredDuration((unitWidth * nextCopies) / Math.max(speed, 1));
        }
      };
      update();
      const observer = new ResizeObserver(update);
      observer.observe(root);
      observer.observe(unit);
      return () => observer.disconnect();
    }, [duration, speed]);

    const loopSeconds = duration ?? measuredDuration ?? 40;
    const itemNodes: ReactNode[] = items ?? Children.toArray(children);
    const hasSeparator = separator !== undefined && separator !== null;

    // One unit = the item sequence once (separator after every item so the
    // wrap point looks identical to any other joint).
    const renderUnit = (duplicate: boolean, unitElRef?: React.Ref<HTMLDivElement>) => (
      <div
        ref={unitElRef}
        className="fancy-marquee__unit"
        aria-hidden={duplicate || undefined}
      >
        {itemNodes.map((node, i) => (
          <Fragment key={i}>
            <div className="fancy-marquee__item" data-react-fancy-marquee-item="" data-index={i}>
              {node}
            </div>
            {hasSeparator && (
              <div
                className="fancy-marquee__separator"
                data-react-fancy-marquee-separator=""
                aria-hidden="true"
              >
                {separator}
              </div>
            )}
          </Fragment>
        ))}
      </div>
    );

    // Two identical groups + translateX(-50%) keyframes = seamless wrap. Only
    // the very first unit is exposed to AT; every repeat is aria-hidden.
    const renderGroup = (duplicate: boolean) => (
      <div
        className="fancy-marquee__group"
        data-react-fancy-marquee-group=""
        aria-hidden={duplicate || undefined}
      >
        {Array.from({ length: copies }, (_, c) =>
          <Fragment key={c}>
            {renderUnit(duplicate || c > 0, !duplicate && c === 0 ? unitRef : undefined)}
          </Fragment>,
        )}
      </div>
    );

    const cssVars: CSSProperties = {
      "--fancy-marquee-duration": `${loopSeconds}s`,
      "--fancy-marquee-gap": toLength(gap),
      ...(fade !== false && {
        "--fancy-marquee-fade": fade === true ? "48px" : toLength(fade),
      }),
    } as CSSProperties;

    // Tilted strips widen slightly (the classic 102% / -1% trick) so the
    // rotation never exposes the page background at the edges.
    const angleStyle: CSSProperties = angle
      ? { transform: `rotate(${angle}deg)`, width: "102%", marginLeft: "-1%" }
      : {};

    return (
      <div
        ref={rootRef}
        data-react-fancy-marquee=""
        data-direction={direction}
        data-paused={paused ? "" : undefined}
        aria-hidden={decorative || undefined}
        className={cn(
          "fancy-marquee",
          fade !== false && "fancy-marquee--fade",
          pauseOnHover && "fancy-marquee--pause-hover",
          className,
        )}
        style={{ ...cssVars, ...angleStyle, ...style }}
        {...rest}
      >
        <div className="fancy-marquee__track" data-react-fancy-marquee-track="">
          {renderGroup(false)}
          {renderGroup(true)}
        </div>
      </div>
    );
  },
);

Marquee.displayName = "Marquee";

import type { HTMLAttributes, ReactNode } from "react";

export type MarqueeDirection = "left" | "right";

export interface MarqueeProps extends HTMLAttributes<HTMLDivElement> {
  /** Item nodes — each child is one strip item (alternative to `items`) */
  children?: ReactNode;
  /** Data-driven items (alternative to children) — strings or nodes */
  items?: ReactNode[];
  /**
   * Scroll speed in px/s — keeps perceived speed constant regardless of
   * content width. Ignored when `duration` is set. Default: 40
   */
  speed?: number;
  /** Explicit seconds per loop (overrides `speed`) */
  duration?: number;
  /** Scroll direction. Default: "left" */
  direction?: MarqueeDirection;
  /** Pause the animation while hovered. Default: false */
  pauseOnHover?: boolean;
  /** Controlled pause — `true` freezes the strip. Default: false */
  paused?: boolean;
  /** Gap between items (number = px). Default: 40 */
  gap?: number | string;
  /**
   * Masked fade at the strip edges: `true` (48px, default), `false` to
   * disable, or a number/CSS length for a custom fade width
   */
  fade?: boolean | number | string;
  /** Optional node rendered between items */
  separator?: ReactNode;
  /**
   * Tilt the whole strip in degrees (e.g. `-1` for the torn, off-axis band
   * look). The strip widens slightly to stay edge-to-edge. Default: 0
   */
  angle?: number;
  /**
   * Decorative strips are `aria-hidden` (default). Set `false` to expose the
   * content to assistive tech — the duplicated loop copy stays hidden either
   * way. Default: true
   */
  decorative?: boolean;
  className?: string;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { cn } from "../lib/utils/cn";

interface MediaFallbackProps {
  src: string;
  mime?: string;
  label?: string;
  className?: string;
}

/** Filename guess from a URL, ignoring query/hash and `data:`/`blob:` URLs. */
function basename(src: string): string | null {
  if (/^(data|blob):/i.test(src)) return null;
  const seg = src.split(/[?#]/, 1)[0].split("/").pop();
  return seg ? decodeURIComponent(seg) : null;
}

/**
 * Shown by `<MediaViewer>` when a source isn't a previewable media type — a
 * small themed card naming the file and offering a download.
 */
export function MediaFallback({ src, mime, label, className }: MediaFallbackProps) {
  const name = label || basename(src);
  return (
    <div
      data-react-fancy-media-fallback=""
      className={cn(
        "flex flex-col items-center justify-center gap-2 rounded-lg border border-zinc-200 bg-white p-6 text-center dark:border-zinc-700 dark:bg-zinc-900",
        className,
      )}
    >
      <span className="text-sm font-medium text-zinc-700 dark:text-zinc-200">
        No preview available
      </span>
      {(name || mime) && (
        <span className="max-w-full truncate text-xs text-zinc-500 dark:text-zinc-400">
          {name}
          {name && mime ? " · " : ""}
          {mime}
        </span>
      )}
      <a
        href={src}
        download={name ?? undefined}
        className="text-xs font-medium text-blue-600 hover:underline dark:text-blue-400"
      >
        Download
      </a>
    </div>
  );
}

import { forwardRef } from "react";
import { resolveMediaType } from "../lib/utils/media-type";
import { ImageViewer } from "../image-viewer";
import { VideoViewer } from "../video-viewer";
import { AudioViewer } from "../audio-viewer";
import { PdfViewer } from "../pdf-viewer";
import { MediaFallback } from "./MediaFallback";
import type { MediaViewerProps } from "./MediaViewer.types";

/**
 * Renders the right viewer for a media file, picked from its `mime` (preferred)
 * or `src` — image, video, audio, or PDF — and a download fallback for anything
 * else. SVG renders through `<ImageViewer>`. The single entry point for showing
 * a file from a tree/workspace when you don't know its type ahead of time.
 *
 * ```tsx
 * <MediaViewer src={url} mime="image/png" alt="logo.png" style={{ height: 320 }} />
 * ```
 */
export const MediaViewer = forwardRef<HTMLDivElement, MediaViewerProps>(
  (
    {
      src,
      mime,
      alt,
      kind,
      imageProps,
      videoProps,
      audioProps,
      pdfProps,
      fallback,
      onError,
      className,
      style,
    },
    ref,
  ) => {
    const resolved = kind ?? resolveMediaType({ mime, src });

    switch (resolved) {
      case "image":
        return (
          <ImageViewer
            ref={ref}
            src={src}
            alt={alt ?? ""}
            onError={onError}
            className={className}
            style={style}
            {...imageProps}
          />
        );
      case "video":
        return (
          <VideoViewer
            ref={ref}
            src={src}
            onError={onError}
            className={className}
            style={style}
            {...videoProps}
          />
        );
      case "audio":
        return (
          <AudioViewer
            ref={ref}
            src={src}
            title={alt}
            onError={onError}
            className={className}
            style={style}
            {...audioProps}
          />
        );
      case "pdf":
        return (
          <PdfViewer
            ref={ref}
            src={src}
            title={alt}
            className={className}
            style={style}
            {...pdfProps}
          />
        );
      default:
        return (
          <div
            ref={ref}
            data-react-fancy-media-viewer=""
            className={className}
            style={style}
          >
            {fallback ?? <MediaFallback src={src} mime={mime} label={alt} />}
          </div>
        );
    }
  },
);

MediaViewer.displayName = "MediaViewer";

import type { CSSProperties, ReactNode } from "react";
import type { MediaKind } from "../lib/utils/media-type";
import type { ImageViewerProps } from "../image-viewer/ImageViewer.types";
import type { VideoViewerProps } from "../video-viewer/VideoViewer.types";
import type { AudioViewerProps } from "../audio-viewer/AudioViewer.types";
import type { PdfViewerProps } from "../pdf-viewer/PdfViewer.types";

export interface MediaViewerProps {
  /** Media source — an `http(s):`, `data:`, or `blob:` URL. */
  src: string;
  /**
   * MIME type — preferred for picking the viewer. When omitted, the kind is
   * sniffed from `src` (extension or `data:` URI). Always pass `mime` with a
   * bare `blob:` URL, which carries no type of its own.
   */
  mime?: string;
  /** Alt text / label, forwarded as image alt and audio/PDF title. */
  alt?: string;
  /** Force a specific viewer, bypassing detection. */
  kind?: MediaKind;
  /** Extra props for the underlying `<ImageViewer>`. */
  imageProps?: Partial<Omit<ImageViewerProps, "src" | "alt">>;
  /** Extra props for the underlying `<VideoViewer>`. */
  videoProps?: Partial<Omit<VideoViewerProps, "src">>;
  /** Extra props for the underlying `<AudioViewer>`. */
  audioProps?: Partial<Omit<AudioViewerProps, "src">>;
  /** Extra props for the underlying `<PdfViewer>`. */
  pdfProps?: Partial<Omit<PdfViewerProps, "src">>;
  /** Rendered for unknown / unpreviewable types (default: a download card). */
  fallback?: ReactNode;
  /** Fired when the chosen viewer reports a load error. */
  onError?: () => void;
  /** Additional CSS classes, forwarded to the chosen viewer. */
  className?: string;
  /** Inline styles, forwarded to the chosen viewer. */
  style?: CSSProperties;
}

