import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useEffect, type RefObject } from "react";

const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled])",
  "textarea:not([disabled])",
  "select:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(", ");

export function useFocusTrap(
  ref: RefObject<HTMLElement | null>,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const el = ref.current;
    if (!el) return;

    const previouslyFocused = document.activeElement as HTMLElement | null;

    const focusables = () =>
      Array.from(el.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR));

    // Focus first focusable element
    const first = focusables()[0];
    first?.focus();

    const listener = (event: KeyboardEvent) => {
      if (event.key !== "Tab") return;

      const items = focusables();
      if (items.length === 0) return;

      const firstItem = items[0];
      const lastItem = items[items.length - 1];

      if (event.shiftKey) {
        if (document.activeElement === firstItem) {
          event.preventDefault();
          lastItem.focus();
        }
      } else {
        if (document.activeElement === lastItem) {
          event.preventDefault();
          firstItem.focus();
        }
      }
    };

    el.addEventListener("keydown", listener);

    return () => {
      el.removeEventListener("keydown", listener);
      previouslyFocused?.focus();
    };
  }, [ref, enabled]);
}

import { useEffect } from "react";

export function useEscapeKey(
  handler: () => void,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        handler();
      }
    };

    document.addEventListener("keydown", listener);
    return () => document.removeEventListener("keydown", listener);
  }, [handler, enabled]);
}

import { useCallback, useEffect, useRef, useState } from "react";

interface UseAnimationOptions {
  open: boolean;
  enterClass: string;
  exitClass: string;
}

interface UseAnimationReturn {
  mounted: boolean;
  className: string;
  ref: React.RefObject<HTMLElement | null>;
}

export function useAnimation({
  open,
  enterClass,
  exitClass,
}: UseAnimationOptions): UseAnimationReturn {
  const [mounted, setMounted] = useState(open);
  const [animClass, setAnimClass] = useState(open ? enterClass : "");
  const ref = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (open) {
      setMounted(true);
      setAnimClass(enterClass);
    } else if (mounted) {
      setAnimClass(exitClass);
    }
  }, [open, enterClass, exitClass, mounted]);

  const handleAnimationEnd = useCallback(() => {
    if (!open) {
      setMounted(false);
      setAnimClass("");
    }
  }, [open]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    el.addEventListener("animationend", handleAnimationEnd);
    return () => el.removeEventListener("animationend", handleAnimationEnd);
  }, [handleAnimationEnd, mounted]);

  return { mounted, className: animClass, ref };
}

import { useCallback, useRef, useState } from "react";

/**
 * MoodMeter — a 2D draggable pad that captures a value AND the
 * confidence in that value on the same handle.
 *
 *   <MoodMeter
 *     min={0} max={1}
 *     value={value} confidence={confidence}
 *     onChange={(v, c) => { setValue(v); setConfidence(c); }}
 *   />
 *
 *   • x-axis maps to [min..max]
 *   • y-axis maps to [0..1] confidence (top = sure)
 *   • the halo around the handle scales inversely with confidence —
 *     uncertain readings literally look fuzzier
 *
 * Why pair them in one control? When AIs post a number, humans
 * immediately ask "how sure are you?". Making confidence an explicit
 * sibling of value — and letting the user drag either independently —
 * turns vague "AI suggestion" UX into something you can argue with
 * precisely.
 *
 * The agent's posted value/confidence renders as a dashed ghost
 * handle alongside the live user handle, so the human can see where
 * the agent landed and how far they've drifted.
 */
export interface MoodMeterProps {
  /** Range minimum. */
  min: number;
  /** Range maximum. */
  max: number;
  /** Step for value snapping. Defaults to (max-min)/100. */
  step?: number;
  /** Current value (controlled). */
  value: number;
  /** Current confidence 0..1 (controlled). */
  confidence: number;
  /** Called with (value, confidence) on drag / pointer events. */
  onChange: (value: number, confidence: number) => void;
  /** Optional agent post — renders as a dashed ghost handle. */
  posted?: { value: number; confidence: number };
  /** Pixel width of the pad. Defaults to 320. */
  width?: number;
  /** Pixel height of the pad. Defaults to 220. */
  height?: number;
  /** Show the grid + axis labels. Defaults to true. */
  showGrid?: boolean;
  /** Color of the user handle. Defaults to sky blue. */
  color?: string;
  /** Color of the posted-ghost handle. Defaults to violet. */
  postedColor?: string;
  /** Optional prefix for the value label (e.g. "$"). */
  prefix?: string;
  /** Optional suffix for the value label (e.g. "k", "%"). */
  suffix?: string;
  /** Optional label text override. Falls back to formatted value. */
  formatValue?: (v: number) => string;
  /** Optional className applied to the outer pad. */
  className?: string;
}

export function MoodMeter({
  min,
  max,
  step,
  value,
  confidence,
  onChange,
  posted,
  width = 320,
  height = 220,
  showGrid = true,
  color = "#0ea5e9",
  postedColor = "#a855f7",
  prefix = "",
  suffix = "",
  formatValue,
  className,
}: MoodMeterProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [dragging, setDragging] = useState(false);

  const snapStep = step ?? (max - min) / 100;

  const fmt = useCallback(
    (v: number) => {
      if (formatValue) return formatValue(v);
      const num = snapStep < 1 ? v.toFixed(2) : Math.round(v).toString();
      return `${prefix}${num}${suffix}`;
    },
    [formatValue, snapStep, prefix, suffix],
  );

  const set = useCallback(
    (clientX: number, clientY: number) => {
      const el = ref.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const x = clamp((clientX - rect.left) / rect.width, 0, 1);
      const y = clamp((clientY - rect.top) / rect.height, 0, 1);
      const raw = min + x * (max - min);
      const snapped = round(raw, snapStep, min);
      const c = clamp(1 - y, 0, 1);
      onChange(snapped, Math.round(c * 100) / 100);
    },
    [min, max, snapStep, onChange],
  );

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    (e.target as Element).setPointerCapture?.(e.pointerId);
    setDragging(true);
    set(e.clientX, e.clientY);
  };
  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    set(e.clientX, e.clientY);
  };
  const onPointerUp = () => setDragging(false);

  const xPct = ((value - min) / (max - min)) * 100;
  const yPct = (1 - confidence) * 100;
  const haloR = 18 + (1 - confidence) * 70;

  const pxPct = posted ? ((posted.value - min) / (max - min)) * 100 : 0;
  const pyPct = posted ? (1 - posted.confidence) * 100 : 0;
  const pHaloR = posted ? 16 + (1 - posted.confidence) * 60 : 0;

  return (
    <div
      ref={ref}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      className={`relative cursor-crosshair touch-none select-none overflow-hidden rounded-md border border-zinc-200 bg-zinc-50 dark:border-zinc-800 dark:bg-zinc-950 ${className ?? ""}`}
      style={{ width, height }}
    >
      {showGrid && (
        <svg className="pointer-events-none absolute inset-0 h-full w-full" aria-hidden>
          {[0.25, 0.5, 0.75].map((p, i) => (
            <line
              key={`v${i}`}
              x1={`${p * 100}%`}
              x2={`${p * 100}%`}
              y1="0"
              y2="100%"
              stroke="#a1a1aa"
              strokeOpacity={0.18}
              strokeDasharray="3 4"
            />
          ))}
          {[0.25, 0.5, 0.75].map((p, i) => (
            <line
              key={`h${i}`}
              x1="0"
              x2="100%"
              y1={`${p * 100}%`}
              y2={`${p * 100}%`}
              stroke="#a1a1aa"
              strokeOpacity={0.18}
              strokeDasharray="3 4"
            />
          ))}
        </svg>
      )}

      {showGrid && (
        <>
          <div className="pointer-events-none absolute left-1.5 top-1.5 text-[10px] uppercase tracking-wider text-zinc-400">
            ↑ sure
          </div>
          <div className="pointer-events-none absolute bottom-1.5 left-1.5 text-[10px] uppercase tracking-wider text-zinc-400">
            ↓ unsure
          </div>
          <div className="pointer-events-none absolute right-1.5 top-1.5 text-[10px] uppercase tracking-wider text-zinc-400">
            {fmt(max)} →
          </div>
          <div className="pointer-events-none absolute bottom-1.5 right-1.5 text-[10px] uppercase tracking-wider text-zinc-400">
            ← {fmt(min)}
          </div>
        </>
      )}

      {posted && (
        <Handle
          xPct={pxPct}
          yPct={pyPct}
          haloR={pHaloR}
          color={postedColor}
          dashed
          label="agent"
        />
      )}
      <Handle
        xPct={xPct}
        yPct={yPct}
        haloR={haloR}
        color={color}
        label={fmt(value)}
      />
    </div>
  );
}

function Handle({
  xPct,
  yPct,
  haloR,
  color,
  dashed = false,
  label,
}: {
  xPct: number;
  yPct: number;
  haloR: number;
  color: string;
  dashed?: boolean;
  label: string;
}) {
  return (
    <>
      <div
        className="pointer-events-none absolute -translate-x-1/2 -translate-y-1/2 rounded-full"
        style={{
          left: `${xPct}%`,
          top: `${yPct}%`,
          width: haloR * 2,
          height: haloR * 2,
          background: color + (dashed ? "11" : "22"),
          border: dashed ? `1px dashed ${color}` : "none",
        }}
      />
      <div
        className="pointer-events-none absolute -translate-x-1/2 -translate-y-1/2 rounded-full ring-2 ring-white dark:ring-zinc-900"
        style={{
          left: `${xPct}%`,
          top: `${yPct}%`,
          width: 14,
          height: 14,
          background: color,
          opacity: dashed ? 0.6 : 1,
        }}
      />
      <div
        className="pointer-events-none absolute -translate-x-1/2 rounded px-1.5 py-0.5 font-mono text-[10px]"
        style={{
          left: `${xPct}%`,
          top: `calc(${yPct}% + 14px)`,
          color,
        }}
      >
        {label}
      </div>
    </>
  );
}

function clamp(n: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, n));
}

function round(n: number, step: number, min: number) {
  if (step >= 1) return Math.round(n);
  return Math.round((n - min) / step) * step + min;
}

import { useLayoutEffect, useMemo, useRef, type CSSProperties, type ReactNode } from "react";
import type { TimelineDoc } from "../lib/timeline/types";
import { flattenTimeline, sampleKeyframes, toCss } from "../lib/engine/interpolate";

export interface MotionStageProps {
  timeline: TimelineDoc;
  /** Attribute whose value identifies a node to animate (default `data-cms`). */
  nodeAttr?: string;
  className?: string;
  children: ReactNode;
}

/**
 * Runtime player: turns scroll into a timeline playhead and morphs the pinned
 * content between whole-page snapshots. A `frames × viewport` spacer creates the
 * scroll distance; the content is pinned (sticky) and scrubbed by scroll
 * progress (0..1).
 *
 * Spine scope: continuous **scroll** scrub on the **vertical** axis (the
 * horizontal axis is the symmetric X mapping). Per-keyframe **snap** scrolling
 * and **scene** pinning are runtime behaviors layered on next.
 */
export function MotionStage({ timeline, nodeAttr = "data-cms", className, children }: MotionStageProps) {
  const spacerRef = useRef<HTMLDivElement>(null);
  const pinRef = useRef<HTMLDivElement>(null);
  const flat = useMemo(() => flattenTimeline(timeline), [timeline]);
  const horizontal = timeline.axis === "horizontal";

  useLayoutEffect(() => {
    const spacer = spacerRef.current;
    const pin = pinRef.current;
    if (!spacer || !pin || typeof window === "undefined") return;

    let raf = 0;
    const apply = () => {
      raf = 0;
      const rect = spacer.getBoundingClientRect();
      const vp = horizontal ? window.innerWidth : window.innerHeight;
      const total = horizontal ? spacer.offsetWidth : spacer.offsetHeight;
      const scrolled = horizontal ? -rect.left : -rect.top;
      const len = total - vp;
      const progress = len > 0 ? Math.min(1, Math.max(0, scrolled / len)) : 0;

      const snap = sampleKeyframes(flat, progress);
      pin.querySelectorAll<HTMLElement>(`[${nodeAttr}]`).forEach((el) => {
        const id = el.getAttribute(nodeAttr);
        const state = id ? snap[id] : undefined;
        if (!state) {
          el.style.transform = "";
          el.style.opacity = "";
          return;
        }
        const css = toCss(state);
        el.style.transform = css.transform;
        el.style.opacity = String(css.opacity);
      });
    };

    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(apply);
    };

    apply();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [flat, nodeAttr, horizontal]);

  const frames = Math.max(1, timeline.frames);
  const spacerStyle: CSSProperties = horizontal
    ? { position: "relative", width: `${frames * 100}vw`, height: "100vh" }
    : { position: "relative", height: `${frames * 100}vh` };
  const pinStyle: CSSProperties = {
    position: "sticky",
    top: 0,
    left: horizontal ? 0 : undefined,
    height: "100vh",
    width: horizontal ? "100vw" : undefined,
    overflow: "hidden",
  };

  return (
    <div ref={spacerRef} className={className} style={spacerStyle} data-fancy-motion-stage="">
      <div ref={pinRef} style={pinStyle}>
        {children}
      </div>
    </div>
  );
}

/**
 * TimelineDoc — the scroll-timeline model owned by fancy-motion. The page is a
 * video and scroll is the playhead. Authoring is **whole-page snapshots**: each
 * keyframe captures animatable per-node state; the engine tweens the diff
 * between consecutive snapshots as the playhead scrubs.
 */

export type Axis = "vertical" | "horizontal";

/** Animatable per-node state captured in a snapshot. Extensible. */
export interface NodeState {
  /** translate px along/across the layout (transform) */
  x?: number;
  y?: number;
  opacity?: number; // 0..1
  scale?: number;
  rotate?: number; // deg
  /**
   * Explicit size in px. Unlike the transform fields these are **optional with
   * no default** — absent means "leave the element auto-sized". They tween only
   * when present in the bracketing keyframes, so a pure move/scale never forces
   * a width onto an element that didn't ask for one.
   */
  w?: number;
  h?: number;
}

/** A whole-page snapshot: animatable state keyed by node id (e.g. the `data-cms` value). */
export type Snapshot = Record<string, NodeState>;

export type KeyframeMode = "snap" | "scroll";
export type Ease = "linear" | "ease-in" | "ease-out" | "ease-in-out";

export interface Keyframe {
  id: string;
  /** Proportional position on the timeline, 0..1 — responsive-safe. */
  at: number;
  /** `snap` → snap the scroll here + auto-tween; `scroll` → scrub toward it. */
  mode: KeyframeMode;
  snapshot: Snapshot;
  /** Easing into this keyframe from the previous one (default linear). */
  ease?: Ease;
}

/** A pinned sub-sequence: the page holds while internal keyframes play, then releases. */
export interface Scene {
  id: string;
  /** Where the scene pins on the parent timeline, 0..1. */
  at: number;
  /** Proportional scroll length consumed while pinned, in 0..1 of the parent timeline. */
  length: number;
  /** Internal keyframes, each positioned 0..1 within the scene. */
  keyframes: Keyframe[];
}

export interface TimelineDoc {
  id: string;
  axis: Axis;
  /** Ruler length in viewport-sized frames (total scroll = frames × viewport). */
  frames: number;
  /** Top-level keyframes (engine sorts by `at`). */
  keyframes: Keyframe[];
  scenes?: Scene[];
}

export function emptyTimeline(id: string, axis: Axis = "vertical"): TimelineDoc {
  return { id, axis, frames: 1, keyframes: [], scenes: [] };
}

/**
 * The pure scroll → snapshot tween engine. Given a playhead `progress` (0..1)
 * it resolves the interpolated {@link Snapshot} by lerping between the two
 * bracketing keyframes (elements matched by node id). Framework-agnostic and
 * fully unit-tested — the runtime player just feeds it scroll progress.
 */
import type { Ease, Keyframe, NodeState, Snapshot, TimelineDoc } from "../timeline/types";

const EASES: Record<Ease, (t: number) => number> = {
  linear: (t) => t,
  "ease-in": (t) => t * t,
  "ease-out": (t) => 1 - (1 - t) * (1 - t),
  "ease-in-out": (t) => (t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2),
};

/** The transform fields all default; size (w/h) deliberately does not. */
type Transformed = Required<Omit<NodeState, "w" | "h">>;
const DEFAULT: Transformed = { x: 0, y: 0, opacity: 1, scale: 1, rotate: 0 };

function resolve(s: NodeState | undefined): Transformed {
  const { w: _w, h: _h, ...rest } = s ?? {};
  return { ...DEFAULT, ...rest };
}

const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

export function lerpState(a: NodeState | undefined, b: NodeState | undefined, t: number): NodeState {
  const ra = resolve(a);
  const rb = resolve(b);
  const out: NodeState = {
    x: lerp(ra.x, rb.x, t),
    y: lerp(ra.y, rb.y, t),
    opacity: lerp(ra.opacity, rb.opacity, t),
    scale: lerp(ra.scale, rb.scale, t),
    rotate: lerp(ra.rotate, rb.rotate, t),
  };
  // Size has no default — only tween it when at least one side declares it, so
  // a plain move/scale keyframe never pins a width onto an auto-sized element.
  if (a?.w !== undefined || b?.w !== undefined) out.w = lerp(a?.w ?? b?.w ?? 0, b?.w ?? a?.w ?? 0, t);
  if (a?.h !== undefined || b?.h !== undefined) out.h = lerp(a?.h ?? b?.h ?? 0, b?.h ?? a?.h ?? 0, t);
  return out;
}

/**
 * Flatten top-level keyframes + each scene's internal keyframes (mapped into the
 * scene's pinned [at, at+length] range) into one list sorted by absolute
 * proportional position. The sampler then treats everything uniformly.
 */
export function flattenTimeline(doc: TimelineDoc): Keyframe[] {
  const out: Keyframe[] = [...doc.keyframes];
  for (const scene of doc.scenes ?? []) {
    for (const k of scene.keyframes) {
      out.push({ ...k, at: scene.at + k.at * scene.length });
    }
  }
  return out.sort((a, b) => a.at - b.at);
}

/** Resolve the snapshot at playhead `progress` (0..1) for a whole timeline. Pure. */
export function sampleTimeline(doc: TimelineDoc, progress: number): Snapshot {
  return sampleKeyframes(flattenTimeline(doc), progress);
}

/** Resolve the snapshot at `progress` from a sorted keyframe list. Pure. */
export function sampleKeyframes(keyframes: Keyframe[], progress: number): Snapshot {
  if (keyframes.length === 0) return {};
  const p = Math.min(1, Math.max(0, progress));
  const first = keyframes[0]!;
  const last = keyframes[keyframes.length - 1]!;
  if (p <= first.at) return first.snapshot;
  if (p >= last.at) return last.snapshot;

  let a = first;
  let b = last;
  for (let i = 0; i < keyframes.length - 1; i++) {
    const lo = keyframes[i]!;
    const hi = keyframes[i + 1]!;
    if (p >= lo.at && p < hi.at) {
      a = lo;
      b = hi;
      break;
    }
  }

  const span = b.at - a.at || 1;
  const localT = (p - a.at) / span;
  const easeFn = EASES[b.ease ?? "linear"] ?? EASES.linear;
  const eased = easeFn(localT);

  const out: Snapshot = {};
  for (const id of new Set([...Object.keys(a.snapshot), ...Object.keys(b.snapshot)])) {
    out[id] = lerpState(a.snapshot[id], b.snapshot[id], eased);
  }
  return out;
}

/** CSS transform string + opacity (+ explicit size when the state declares it). */
export function toCss(state: NodeState): { transform: string; opacity: number; width?: string; height?: string } {
  const r = resolve(state);
  return {
    transform: `translate3d(${r.x}px, ${r.y}px, 0) scale(${r.scale}) rotate(${r.rotate}deg)`,
    opacity: r.opacity,
    ...(state.w !== undefined ? { width: `${state.w}px` } : {}),
    ...(state.h !== undefined ? { height: `${state.h}px` } : {}),
  };
}

import { useRef, useState, useEffect, useCallback, useId } from "react";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { Field } from "../field";
import { useFieldMode } from "../lib/components/inputs/mode/FieldMode.context";
import { DisplayValue } from "../lib/components/inputs/mode/DisplayValue";
import { useInlineEdit } from "../lib/components/inputs/mode/useInlineEdit";
import { resolveOption } from "../lib/components/inputs/inputs.utils";
import type { Size } from "../lib/utils/types";
import type { MultiSwitchProps } from "./MultiSwitch.types";

const sizeClasses: Record<Size, string> = {
  xs: "px-2 py-1 text-xs",
  sm: "px-2.5 py-1.5 text-sm",
  md: "px-3 py-2 text-sm",
  lg: "px-4 py-2.5 text-base",
  xl: "px-5 py-3 text-lg",
};

export function MultiSwitch<V = string>({
  size = "md",
  dirty,
  error,
  label,
  labelHidden,
  description,
  required,
  disabled,
  className,
  id,
  name,
  list,
  value: controlledValue,
  defaultValue,
  onValueChange,
  linear,
  mode,
  ...rest
}: MultiSwitchProps<V>) {
  const reactId = useId();
  // A `<label for>` cannot name a div[role="radiogroup"], so the group points at
  // the label instead. Needs an id the label and the group both agree on.
  const labelId = label ? `${id ?? reactId}-label` : undefined;

  const resolvedOptions = list.map(resolveOption);
  const fallback = defaultValue ?? resolvedOptions[0]?.value;
  const resolvedMode = useFieldMode(mode);
  const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
  const [value, setValue] = useControllableState(controlledValue, fallback as V, onValueChange);

  const containerRef = useRef<HTMLDivElement>(null);
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const [indicator, setIndicator] = useState<{ left: number; width: number } | null>(null);

  const selectedIndex = resolvedOptions.findIndex(
    (o) => o.value === value,
  );

  const updateIndicator = useCallback(() => {
    const container = containerRef.current;
    const activeItem = itemRefs.current[selectedIndex];
    if (!container || !activeItem) {
      setIndicator(null);
      return;
    }
    const containerRect = container.getBoundingClientRect();
    const itemRect = activeItem.getBoundingClientRect();
    setIndicator({
      left: itemRect.left - containerRect.left,
      width: itemRect.width,
    });
  }, [selectedIndex]);

  useEffect(() => {
    updateIndicator();
  }, [updateIndicator]);

  const control = !showControl ? (
    <DisplayValue size={size} interactive={interactive} onActivate={enterEdit}>
      {resolvedOptions.find((o) => o.value === value)?.label}
    </DisplayValue>
  ) : (
    <div
      ref={containerRef}
      {...rest}
      data-react-fancy-multi-switch=""
      role="radiogroup"
      id={id}
      aria-labelledby={labelId}
      onBlur={(e) => {
        if (interactive && !e.currentTarget.contains(e.relatedTarget as Node)) exitEdit();
      }}
      className={cn(
        "relative inline-flex rounded-lg border border-zinc-300 bg-zinc-100 dark:border-zinc-700 dark:bg-zinc-800",
        dirty && "ring-2 ring-amber-400/50",
        error && "ring-2 ring-red-500/50",
        disabled && "opacity-50 cursor-not-allowed",
        className,
      )}
    >
      {indicator && (
        <span
          className="absolute top-0 bottom-0 rounded-lg bg-blue-600 transition-all duration-200 ease-out"
          style={{ left: indicator.left, width: indicator.width }}
        />
      )}
      {resolvedOptions.map((option, index) => {
        const isSelected = option.value === value;
        return (
          <button
            key={String(option.value)}
            ref={(el) => { itemRefs.current[index] = el; }}
            type="button"
            role="radio"
            aria-checked={isSelected}
            disabled={disabled || option.disabled}
            autoFocus={interactive && (selectedIndex === -1 ? index === 0 : isSelected)}
            onClick={() => {
              if (linear) {
                const nextIndex = (selectedIndex + 1) % resolvedOptions.length;
                setValue(resolvedOptions[nextIndex].value as V);
              } else {
                setValue(option.value as V);
              }
            }}
            className={cn(
              "relative z-10 font-medium transition-colors duration-200",
              sizeClasses[size],
              isSelected
                ? "text-white"
                : "text-zinc-600 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-zinc-100",
              (disabled || option.disabled) && "cursor-not-allowed",
            )}
          >
            {option.label}
          </button>
        );
      })}
      {name && <input type="hidden" name={name} value={String(value)} />}
    </div>
  );

  if (label || error || description) {
    return (
      <Field
        label={label}
        labelHidden={labelHidden}
        labelId={labelId}
        description={description}
        error={error}
        required={required}
        htmlFor={id}
        size={size}
      >
        {control}
      </Field>
    );
  }

  return control;
}

MultiSwitch.displayName = "MultiSwitch";

import type { HTMLAttributes } from "react";
import type { InputBaseProps, InputOption } from "../lib/components/inputs/inputs.types";

/**
 * The container's DOM attributes are part of the API because the component
 * already spreads its rest props onto that container — `style`, `data-*` and
 * `aria-*` all worked at runtime while the type refused them, so a caller got a
 * compiler error for something the component does correctly.
 *
 * `onChange` is omitted because this control reports through `onValueChange`,
 * and admitting both would offer a handler that never fires.
 */
export interface MultiSwitchProps<V = string>
  extends InputBaseProps,
    Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  list: InputOption<V>[];
  value?: V;
  defaultValue?: V;
  onValueChange?: (value: V) => void;
  linear?: boolean;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import { createContext, useContext } from "react";
import type { FieldMode } from "../inputs.types";

export interface FieldModeContextValue {
  mode: FieldMode;
}

export const FieldModeContext = createContext<FieldModeContextValue | null>(null);

/**
 * Resolve the effective mode for an input. Precedence: an explicit prop wins,
 * then the nearest `<Form>` / `<FormProvider>` context, then `"edit"`.
 *
 * Deliberately tolerant (returns `"edit"` outside any provider) — unlike a slot
 * guard — so every input works standalone with zero context and existing call
 * sites behave identically.
 */
export function useFieldMode(explicit?: FieldMode): FieldMode {
  const ctx = useContext(FieldModeContext);
  return explicit ?? ctx?.mode ?? "edit";
}

import type { KeyboardEvent, ReactNode } from "react";
import { cn } from "../../../utils/cn";
import type { Size } from "../../../utils/types";
import { inputSizeClasses } from "../inputs.utils";

export interface DisplayValueProps {
  /** The formatted value to show. Empty / null / undefined renders `empty`. */
  children?: ReactNode;
  size?: Size;
  /** Static adornment rendered before the value (mirrors an input's `leading`/`prefix`). */
  leading?: ReactNode;
  /** Static adornment rendered after the value (mirrors an input's `trailing`/`suffix`). */
  trailing?: ReactNode;
  /** Shown when the value is empty. Default `—`. */
  empty?: ReactNode;
  /** When true the value is clickable to enter edit mode (inline click-to-edit). */
  interactive?: boolean;
  /** Called when an interactive value is activated (click / Enter / Space). */
  onActivate?: () => void;
  className?: string;
}

function isEmpty(value: ReactNode): boolean {
  return value === null || value === undefined || value === "";
}

/**
 * The read-only counterpart to an `<input>`. Renders a non-interactive value
 * with the same size rhythm as the editable control (reusing
 * {@link inputSizeClasses}) but without the border / background / focus ring.
 *
 * When `interactive` (inline click-to-edit), the value becomes a focusable,
 * hoverable target that calls `onActivate` on click / Enter / Space to swap in
 * the real control. Dropped into the SAME `Field` wrapper the editable control
 * uses, so label / description / error chrome stays byte-identical between the
 * display and the editor.
 *
 * Carries `data-react-fancy-display` / `data-mode="view"` stable handles for
 * agents and tests (Human+ contract).
 */
export function DisplayValue({
  children,
  size = "md",
  leading,
  trailing,
  empty = "—",
  interactive,
  onActivate,
  className,
}: DisplayValueProps) {
  const empties = isEmpty(children);

  const onKeyDown = interactive
    ? (e: KeyboardEvent<HTMLDivElement>) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onActivate?.();
        }
      }
    : undefined;

  return (
    <div
      data-react-fancy-display=""
      data-mode="view"
      role={interactive ? "button" : undefined}
      tabIndex={interactive ? 0 : undefined}
      title={interactive ? "Click to edit" : undefined}
      onClick={interactive ? onActivate : undefined}
      onKeyDown={onKeyDown}
      className={cn(
        "flex w-full items-center gap-2 text-zinc-900 dark:text-zinc-100",
        inputSizeClasses[size],
        // Strip the editable box look — keep only the size/padding rhythm.
        "border-0 bg-transparent px-0",
        interactive &&
          "-mx-2 cursor-text rounded-md px-2 outline-none transition-colors hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-blue-500/40 dark:hover:bg-zinc-800",
        empties && "text-zinc-400 dark:text-zinc-500",
        className,
      )}
    >
      {leading && <span className="text-zinc-400 dark:text-zinc-500">{leading}</span>}
      <span className="min-w-0 truncate">{empties ? empty : children}</span>
      {trailing && <span className="text-zinc-400 dark:text-zinc-500">{trailing}</span>}
    </div>
  );
}

import { useCallback, useState } from "react";
import type { FieldMode } from "../inputs.types";

export interface InlineEdit {
  /** Render the editable control (`true`) vs. the read-only value display (`false`). */
  showControl: boolean;
  /** Whether view mode is interactive (click-to-edit) — i.e. `view` and not disabled. */
  interactive: boolean;
  /** Enter edit mode (no-op unless interactive). */
  enterEdit: () => void;
  /** Leave edit mode, back to the value display. */
  exitEdit: () => void;
}

/**
 * Inline click-to-edit for `mode="view"`. The bound value shows as clean static
 * text; clicking it swaps in the focused control; blur returns to the display
 * (the control's `onChange` / `onBlur` fire as usual, so a host can persist on
 * commit). `mode="edit"` is always the control; a **disabled** view stays static
 * text (no click-to-edit).
 *
 * This is the value of "view mode": tidy read-only surfaces where each field
 * becomes editable only when the user reaches for it.
 */
export function useInlineEdit(mode: FieldMode, disabled?: boolean): InlineEdit {
  const [editing, setEditing] = useState(false);
  const interactive = mode === "view" && !disabled;
  const showControl = mode !== "view" || (interactive && editing);
  const enterEdit = useCallback(() => {
    if (interactive) setEditing(true);
  }, [interactive]);
  const exitEdit = useCallback(() => setEditing(false), []);
  return { showControl, interactive, enterEdit, exitEdit };
}

