}

import { ChevronLeft, ChevronRight } from "lucide-react";
import { useMemo } from "react";
import { cn } from "../lib/utils/cn";
import type { PaginationProps } from "./Pagination.types";

function range(start: number, end: number): number[] {
  return Array.from({ length: end - start + 1 }, (_, i) => start + i);
}

function getPages(
  page: number,
  totalPages: number,
  siblings: number,
): (number | "ellipsis")[] {
  const totalSlots = siblings * 2 + 5; // siblings + boundaries + ellipses + current
  if (totalPages <= totalSlots) return range(1, totalPages);

  const leftSibling = Math.max(page - siblings, 1);
  const rightSibling = Math.min(page + siblings, totalPages);

  const showLeftEllipsis = leftSibling > 2;
  const showRightEllipsis = rightSibling < totalPages - 1;

  if (!showLeftEllipsis && showRightEllipsis) {
    const leftRange = range(1, 3 + siblings * 2);
    return [...leftRange, "ellipsis", totalPages];
  }

  if (showLeftEllipsis && !showRightEllipsis) {
    const rightRange = range(totalPages - (2 + siblings * 2), totalPages);
    return [1, "ellipsis", ...rightRange];
  }

  return [
    1,
    "ellipsis",
    ...range(leftSibling, rightSibling),
    "ellipsis",
    totalPages,
  ];
}

export function Pagination({
  page,
  onPageChange,
  totalPages,
  siblingCount = 1,
  className,
}: PaginationProps) {
  const pages = useMemo(
    () => getPages(page, totalPages, siblingCount),
    [page, totalPages, siblingCount],
  );

  if (totalPages <= 1) return null;

  const btnBase =
    "inline-flex h-9 min-w-9 items-center justify-center rounded-lg border text-sm transition-colors";
  const btnDefault =
    "border-zinc-200 bg-white hover:bg-zinc-50 dark:border-zinc-700 dark:bg-zinc-900 dark:hover:bg-zinc-800";
  const btnActive =
    "border-zinc-900 bg-zinc-900 text-white dark:border-white dark:bg-white dark:text-zinc-900";
  const btnDisabled = "cursor-not-allowed opacity-50";

  return (
    <nav aria-label="Pagination" data-react-fancy-pagination="" className={cn("flex items-center gap-1", className)}>
      <button
        type="button"
        disabled={page <= 1}
        onClick={() => onPageChange(page - 1)}
        className={cn(btnBase, btnDefault, page <= 1 && btnDisabled, "px-2")}
        aria-label="Previous page"
      >
        <ChevronLeft size={16} />
      </button>

      {pages.map((p, i) =>
        p === "ellipsis" ? (
          <span key={`e-${i}`} className="px-1 text-zinc-400">
            ...
          </span>
        ) : (
          <button
            key={p}
            type="button"
            onClick={() => onPageChange(p)}
            aria-current={p === page ? "page" : undefined}
            className={cn(
              btnBase,
              p === page ? btnActive : btnDefault,
              "px-2",
            )}
          >
            {p}
          </button>
        ),
      )}

      <button
        type="button"
        disabled={page >= totalPages}
        onClick={() => onPageChange(page + 1)}
        className={cn(
          btnBase,
          btnDefault,
          page >= totalPages && btnDisabled,
          "px-2",
        )}
        aria-label="Next page"
      >
        <ChevronRight size={16} />
      </button>
    </nav>
  );
}

Pagination.displayName = "Pagination";

export interface PaginationProps {
  page: number;
  onPageChange: (page: number) => void;
  totalPages: number;
  siblingCount?: number;
  className?: string;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useCallback, useRef } from "react";
import { Badge, Button, Callout, Input, cn } from "@particle-academy/react-fancy";
import { normalizeCeremonyError } from "./client";
import { activityEvent, isoDate } from "./activity";
import type { PasskeyActivityEvent, PasskeyStateError, PasskeySummary } from "./types";

export interface PasskeyPendingRevoke {
  /** Credential ID staged for revocation. */
  id: string;
  /**
   * True when this is the account's only remaining passkey — i.e. confirming
   * locks the user out of passkey sign-in entirely. Computed by the component
   * and rendered in the confirmation copy, because "are you sure?" has not
   * actually warned anyone.
   */
  isLastPasskey: boolean;
}

export interface PasskeyManagerState {
  passkeys: PasskeySummary[];
  pendingRevoke: PasskeyPendingRevoke | null;
  renamingId: string | null;
  draftName: string;
  status: "idle" | "busy" | "error";
  error: PasskeyStateError | null;
}

export interface PasskeyManagerProps {
  value: PasskeyManagerState;
  /** Always called with the **full** next state — never a slice. */
  onChange: (next: PasskeyManagerState) => void;
  onRename?: (input: { id: string; name: string }) => Promise<void> | void;
  onRevoke?: (input: { id: string }) => Promise<void> | void;
  /**
   * Start enrolling a new passkey. The ceremony itself belongs to the host (and
   * to the human at the keyboard) — this is only the intent.
   */
  onEnroll?: () => Promise<void> | void;
  /**
   * Stage revokes for human confirmation instead of performing them.
   * **Defaults to `true`**: revoking is destructive, revoking the last passkey
   * is a lockout, and this is exactly the action the trust-but-verify hook
   * exists for. Set `false` only when something else already confirmed.
   */
  pendingMode?: boolean;
  /** Root handle. Default `"passkey-manager"`. */
  surfaceId?: string;
  onActivity?: (event: PasskeyActivityEvent) => void;
  emptyLabel?: string;
  className?: string;
}

/**
 * A controlled list of a user's passkeys, with rename and revoke.
 *
 * Every row is handled by **credential ID** (`data-fancy-passkey-item`), never
 * by list index. An index-keyed handle points at a different credential after a
 * sort or a revoke, so "revoke the one the agent named" silently revokes
 * somebody else's laptop — and nothing reports it.
 */
export function PasskeyManager({
  value,
  onChange,
  onRename,
  onRevoke,
  onEnroll,
  pendingMode = true,
  surfaceId = "passkey-manager",
  onActivity,
  emptyLabel = "No passkeys yet.",
  className,
}: PasskeyManagerProps) {
  // See PasskeySignIn: read the latest rendered state when an async handler
  // resolves, so the full-state emission reflects what the surface now shows.
  const valueRef = useRef(value);
  valueRef.current = value;

  const emit = useCallback(
    (event: PasskeyActivityEvent) => {
      onActivity?.(event);
    },
    [onActivity],
  );

  const fail = useCallback(
    (err: unknown, target?: string) => {
      const failure = normalizeCeremonyError(err);
      const error: PasskeyStateError = {
        code: failure.serverCode ?? failure.code,
        message: failure.message,
      };
      onChange({ ...valueRef.current, status: "error", error });
      emit(activityEvent(surfaceId, "error", target, { code: error.code }));
    },
    [emit, onChange, surfaceId],
  );

  const startRename = useCallback(
    (passkey: PasskeySummary) => {
      onChange({
        ...valueRef.current,
        renamingId: passkey.id,
        draftName: passkey.name ?? "",
        error: null,
      });
    },
    [onChange],
  );

  const cancelRename = useCallback(() => {
    onChange({ ...valueRef.current, renamingId: null, draftName: "" });
  }, [onChange]);

  const commitRename = useCallback(
    async (id: string) => {
      const name = valueRef.current.draftName.trim();
      emit(activityEvent(surfaceId, "rename", id, { name }));
      onChange({ ...valueRef.current, status: "busy", error: null });
      try {
        await onRename?.({ id, name });
        const current = valueRef.current;
        onChange({
          ...current,
          passkeys: current.passkeys.map((passkey) =>
            passkey.id === id ? { ...passkey, name: name.length > 0 ? name : null } : passkey,
          ),
          renamingId: null,
          draftName: "",
          status: "idle",
          error: null,
        });
      } catch (err) {
        fail(err, id);
      }
    },
    [emit, fail, onChange, onRename, surfaceId],
  );

  const performRevoke = useCallback(
    async (id: string) => {
      onChange({ ...valueRef.current, status: "busy", error: null });
      try {
        await onRevoke?.({ id });
        const current = valueRef.current;
        onChange({
          ...current,
          passkeys: current.passkeys.filter((passkey) => passkey.id !== id),
          pendingRevoke: null,
          renamingId: current.renamingId === id ? null : current.renamingId,
          status: "idle",
          error: null,
        });
      } catch (err) {
        fail(err, id);
      }
    },
    [fail, onChange, onRevoke],
  );

  const proposeRevoke = useCallback(
    (id: string) => {
      const current = valueRef.current;
      const isLastPasskey = current.passkeys.length <= 1;

      if (!pendingMode) {
        emit(activityEvent(surfaceId, "revoke-confirmed", id, { isLastPasskey, staged: false }));
        void performRevoke(id);
        return;
      }

      emit(activityEvent(surfaceId, "revoke-proposed", id, { isLastPasskey }));
      onChange({ ...current, pendingRevoke: { id, isLastPasskey }, error: null });
    },
    [emit, onChange, pendingMode, performRevoke, surfaceId],
  );

  const confirmRevoke = useCallback(
    (id: string) => {
      const isLastPasskey = valueRef.current.pendingRevoke?.isLastPasskey ?? false;
      emit(activityEvent(surfaceId, "revoke-confirmed", id, { isLastPasskey, staged: true }));
      void performRevoke(id);
    },
    [emit, performRevoke, surfaceId],
  );

  const cancelRevoke = useCallback(
    (id: string) => {
      emit(activityEvent(surfaceId, "revoke-cancelled", id));
      onChange({ ...valueRef.current, pendingRevoke: null });
    },
    [emit, onChange, surfaceId],
  );

  const enroll = useCallback(async () => {
    emit(activityEvent(surfaceId, "enroll"));
    onChange({ ...valueRef.current, status: "busy", error: null });
    try {
      await onEnroll?.();
      onChange({ ...valueRef.current, status: "idle", error: null });
    } catch (err) {
      fail(err);
    }
  }, [emit, fail, onChange, onEnroll, surfaceId]);

  const busy = value.status === "busy";

  return (
    <div
      data-fancy-passkey-surface={surfaceId}
      data-fancy-passkey-status={value.status}
      className={cn("fancy-passkey fancy-passkey-manager", className)}
    >
      {/* `Callout` already carries `role="alert"`; these wrappers carry only the
          handle, so a surface never nests two alerts. */}
      {value.error ? (
        <div data-fancy-passkey-error={value.error.code} className="fancy-passkey__error">
          <Callout color="red">{value.error.message}</Callout>
        </div>
      ) : null}

      {value.passkeys.length === 0 ? (
        <p data-fancy-passkey-empty="" className="fancy-passkey__hint">
          {emptyLabel}
        </p>
      ) : (
        <ul className="fancy-passkey-manager__list">
          {value.passkeys.map((passkey) => {
            const renaming = value.renamingId === passkey.id;
            const pending = value.pendingRevoke?.id === passkey.id ? value.pendingRevoke : null;

            return (
              <li
                key={passkey.id}
                data-fancy-passkey-item={passkey.id}
                className="fancy-passkey-manager__row"
              >
                <div className="fancy-passkey-manager__main">
                  {renaming ? (
                    <Input
                      type="text"
                      value={value.draftName}
                      placeholder="Name this passkey"
                      disabled={busy}
                      data-fancy-passkey-field="name"
                      data-fancy-passkey-id={passkey.id}
                      onChange={(event) =>
                        onChange({ ...valueRef.current, draftName: event.target.value })
                      }
                    />
                  ) : (
                    <span data-fancy-passkey-name={passkey.id} className="fancy-passkey-manager__name">
                      {passkey.name ?? "Unnamed passkey"}
                    </span>
                  )}

                  <span className="fancy-passkey-manager__meta">
                    <Badge variant="soft" data-fancy-passkey-backed-up={String(passkey.backedUp)}>
                      {passkey.backedUp ? "Synced" : "This device only"}
                    </Badge>
                    {passkey.transports.length > 0 ? (
                      <span data-fancy-passkey-transports={passkey.transports.join(" ")}>
                        {passkey.transports.join(", ")}
                      </span>
                    ) : null}
                    <span>
                      Added <time dateTime={passkey.createdAt}>{isoDate(passkey.createdAt)}</time>
                    </span>
                    <span>
                      {passkey.lastUsedAt ? (
                        <>
                          Last used{" "}
                          <time dateTime={passkey.lastUsedAt}>{isoDate(passkey.lastUsedAt)}</time>
                        </>
                      ) : (
                        "Never used"
                      )}
                    </span>
                  </span>
                </div>

                {passkey.clonedAt ? (
                  <div
                    data-fancy-passkey-cloned={passkey.id}
                    className="fancy-passkey-manager__cloned"
                  >
                    <Callout color="red">
                      Possible clone detected on{" "}
                      <time dateTime={passkey.clonedAt}>{isoDate(passkey.clonedAt)}</time>. This
                      credential&apos;s signature counter went backwards, which means the private
                      key may exist on more than one device. Revoke it.
                    </Callout>
                  </div>
                ) : null}

                <div className="fancy-passkey-manager__actions">
                  {renaming ? (
                    <>
                      <Button
                        type="button"
                        size="sm"
                        color="blue"
                        disabled={busy}
                        data-fancy-passkey-action="save-rename"
                        data-fancy-passkey-id={passkey.id}
                        onClick={() => void commitRename(passkey.id)}
                      >
                        Save
                      </Button>
                      <Button
                        type="button"
                        size="sm"
                        variant="ghost"
                        disabled={busy}
                        data-fancy-passkey-action="cancel-rename"
                        data-fancy-passkey-id={passkey.id}
                        onClick={cancelRename}
                      >
                        Cancel
                      </Button>
                    </>
                  ) : (
                    <Button
                      type="button"
                      size="sm"
                      variant="ghost"
                      icon="pencil"
                      disabled={busy}
                      data-fancy-passkey-action="rename"
                      data-fancy-passkey-id={passkey.id}
                      onClick={() => startRename(passkey)}
                    >
                      Rename
                    </Button>
                  )}

                  <Button
                    type="button"
                    size="sm"
                    variant="ghost"
                    icon="trash-2"
                    warn
                    disabled={busy || pending !== null}
                    data-fancy-passkey-action="revoke"
                    data-fancy-passkey-id={passkey.id}
                    onClick={() => proposeRevoke(passkey.id)}
                  >
                    Revoke
                  </Button>
                </div>

                {pending ? (
                  <div
                    role="alertdialog"
                    aria-label="Confirm passkey revocation"
                    data-fancy-passkey-confirm={pending.id}
                    data-fancy-passkey-last={String(pending.isLastPasskey)}
                    className="fancy-passkey-manager__confirm"
                  >
                    <Callout color={pending.isLastPasskey ? "red" : "amber"}>
                      {pending.isLastPasskey
                        ? `This is your last passkey. Revoking “${passkey.name ?? "Unnamed passkey"}” removes the only passkey on this account — if it is also your only way in, you will be locked out.`
                        : `Revoke “${passkey.name ?? "Unnamed passkey"}”? That authenticator will no longer be able to sign in.`}
                    </Callout>
                    <div className="fancy-passkey-manager__actions">
                      <Button
                        type="button"
                        size="sm"
                        color="red"
                        disabled={busy}
                        data-fancy-passkey-action="confirm-revoke"
                        data-fancy-passkey-id={pending.id}
                        onClick={() => confirmRevoke(pending.id)}
                      >
                        Revoke passkey
                      </Button>
                      <Button
                        type="button"
                        size="sm"
                        variant="ghost"
                        disabled={busy}
                        data-fancy-passkey-action="cancel-revoke"
                        data-fancy-passkey-id={pending.id}
                        onClick={() => cancelRevoke(pending.id)}
                      >
                        Keep it
                      </Button>
                    </div>
                  </div>
                ) : null}
              </li>
            );
          })}
        </ul>
      )}

      {onEnroll ? (
        <div className="fancy-passkey-manager__footer">
          <Button
            type="button"
            color="blue"
            icon="plus"
            loading={busy}
            disabled={busy}
            data-fancy-passkey-action="enroll"
            data-fancy-passkey-surface-id={surfaceId}
            onClick={() => void enroll()}
          >
            Add a passkey
          </Button>
        </div>
      ) : null}
    </div>
  );
}

/**
 * `@particle-academy/fancy-passkeys-ui/client` — the browser half of both
 * WebAuthn ceremonies, with **zero React**.
 *
 * Every frontend needs this code and only some of them are React, so it lives
 * behind its own entry point: importing the React surfaces never costs you a
 * second copy of the ceremony, and importing the ceremony never costs a Vue or
 * Svelte app a React dependency. `packaging.test.ts` asserts the built
 * `dist/client.js` contains no React import — if that test fails, something
 * moved into the wrong entry.
 *
 * What this module does NOT contain is anything that lets a caller *complete* a
 * ceremony without the human at the keyboard. `navigator.credentials.get()`
 * needs a user gesture and a biometric or PIN, and both of those are things only
 * a person has. That boundary is the whole reason a passkey is worth having, so
 * it is not softened here and will not grow an escape hatch.
 */

import {
  startAuthentication,
  startRegistration,
  browserSupportsWebAuthnAutofill,
  platformAuthenticatorIsAvailable,
  WebAuthnAbortService,
} from "@simplewebauthn/browser";
import type {
  AuthenticationResponseJSON,
  PublicKeyCredentialCreationOptionsJSON,
  PublicKeyCredentialRequestOptionsJSON,
  RegistrationResponseJSON,
} from "@simplewebauthn/browser";
import type { PasskeyServerErrorCode, PasskeySummary } from "./types";

export type {
  PasskeySummary,
  PasskeyServerErrorCode,
  PasskeyStateError,
  PasskeyActivityAction,
  PasskeyActivityEvent,
} from "./types";

export type {
  AuthenticationResponseJSON,
  PublicKeyCredentialCreationOptionsJSON,
  PublicKeyCredentialRequestOptionsJSON,
  RegistrationResponseJSON,
};

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

/**
 * How a ceremony ended, from the browser's point of view.
 *
 * `cancelled` is deliberately its own code and **is not a failure**. The browser
 * reports "the human dismissed the prompt" and "the prompt timed out" with the
 * same `NotAllowedError` it would use for a genuine refusal, and a sign-in
 * surface that paints abandonment red teaches people the surface is broken.
 */
export type PasskeyCeremonyErrorCode =
  | "cancelled"
  | "not_supported"
  | "already_registered"
  | "security_error"
  | "ceremony_failed";

export interface PasskeyCeremonyErrorOptions {
  /** The original `DOMException` / `WebAuthnError` / transport rejection. */
  cause?: unknown;
  /** The backend's own `PasskeyErrorCode`, when the failure came from a response body. */
  serverCode?: string;
  /** HTTP status, when the failure came from a response. */
  status?: number;
}

/** Every rejection from this module is one of these. */
export class PasskeyCeremonyError extends Error {
  readonly code: PasskeyCeremonyErrorCode;
  /**
   * The backend's own error code, preserved verbatim rather than flattened
   * into `ceremony_failed`.
   *
   * Note that the first-party backends deliberately redact
   * `unknown_credential`, `user_handle_mismatch` and `counter_regressed` to
   * `verification_failed` before they reach the wire — each answers a question
   * about a credential the server holds, and an unauthenticated caller has no
   * business asking. Do not branch on those three; they will never arrive.
   */
  readonly serverCode?: string;
  readonly status?: number;
  // Declared here rather than `override`n: the package targets ES2021, whose
  // `Error` has no `cause` to override.
  readonly cause?: unknown;

  constructor(
    code: PasskeyCeremonyErrorCode,
    message: string,
    options: PasskeyCeremonyErrorOptions = {},
  ) {
    super(message);
    this.name = "PasskeyCeremonyError";
    this.code = code;
    if (options.serverCode !== undefined) this.serverCode = options.serverCode;
    if (options.status !== undefined) this.status = options.status;
    if (options.cause !== undefined) this.cause = options.cause;
  }
}

/**
 * A 4xx from either backend, carrying the wire contract's
 * `{ "error": { "code", "message" } }` payload.
 *
 * It extends {@link PasskeyCeremonyError} so `instanceof PasskeyCeremonyError`
 * still catches everything, while `serverCode` stays exact.
 */
export class PasskeyServerError extends PasskeyCeremonyError {
  override readonly serverCode: string;

  constructor(
    serverCode: PasskeyServerErrorCode | string,
    message: string,
    options: { status?: number; cause?: unknown } = {},
  ) {
    super(ceremonyCodeForServerCode(serverCode), message, { ...options, serverCode });
    this.name = "PasskeyServerError";
    this.serverCode = serverCode;
  }
}

function ceremonyCodeForServerCode(serverCode: string): PasskeyCeremonyErrorCode {
  switch (serverCode) {
    case "credential_already_registered":
      return "already_registered";
    case "origin_not_allowed":
    case "rp_id_mismatch":
    case "user_handle_mismatch":
      return "security_error";
    case "not_supported":
      return "not_supported";
    default:
      return "ceremony_failed";
  }
}

function nameOf(err: unknown): string | undefined {
  if (typeof err !== "object" || err === null) return undefined;
  const name = (err as { name?: unknown }).name;
  return typeof name === "string" ? name : undefined;
}

function messageOf(err: unknown, fallback: string): string {
  if (typeof err !== "object" || err === null) return fallback;
  const message = (err as { message?: unknown }).message;
  return typeof message === "string" && message.length > 0 ? message : fallback;
}

/**
 * Turn anything a ceremony can throw into a typed {@link PasskeyCeremonyError}.
 *
 * The mapping that matters:
 *
 * | thrown | code |
 * |---|---|
 * | `NotAllowedError` | `cancelled` — the human dismissed it or it timed out |
 * | `AbortError` | `cancelled` — the host tore the ceremony down (see `signal`) |
 * | `InvalidStateError` | `already_registered` — this authenticator already holds a credential for this account |
 * | `SecurityError` | `security_error` — RP ID / origin does not match |
 * | `NotSupportedError` | `not_supported` |
 * | anything else | `ceremony_failed` |
 *
 * `@simplewebauthn/browser` wraps the `DOMException` in a `WebAuthnError` whose
 * `name` defaults to the underlying exception's, so both shapes land in the same
 * rows; the `cause` chain is checked too for the cases where it does not.
 *
 * An error that is already a `PasskeyCeremonyError` (including a
 * {@link PasskeyServerError}) is returned untouched — that is what stops a
 * server's own code being flattened into `ceremony_failed` by a caller that
 * normalises defensively.
 */
export function normalizeCeremonyError(err: unknown): PasskeyCeremonyError {
  if (err instanceof PasskeyCeremonyError) return err;

  const names = [nameOf(err), nameOf((err as { cause?: unknown } | null)?.cause)];

  for (const name of names) {
    switch (name) {
      case "NotAllowedError":
        return new PasskeyCeremonyError(
          "cancelled",
          messageOf(err, "The passkey prompt was dismissed or timed out."),
          { cause: err },
        );
      case "AbortError":
        return new PasskeyCeremonyError(
          "cancelled",
          messageOf(err, "The passkey ceremony was aborted."),
          { cause: err },
        );
      case "InvalidStateError":
        return new PasskeyCeremonyError(
          "already_registered",
          messageOf(err, "This device already holds a passkey for this account."),
          { cause: err },
        );
      case "SecurityError":
        return new PasskeyCeremonyError(
          "security_error",
          messageOf(err, "The passkey could not be used on this origin."),
          { cause: err },
        );
      case "NotSupportedError":
        return new PasskeyCeremonyError(
          "not_supported",
          messageOf(err, "This browser or authenticator does not support passkeys."),
          { cause: err },
        );
      default:
        break;
    }
  }

  return new PasskeyCeremonyError("ceremony_failed", messageOf(err, "The passkey ceremony failed."), {
    cause: err,
  });
}

// ---------------------------------------------------------------------------
// Feature detection
// ---------------------------------------------------------------------------

/**
 * Whether this browser can do WebAuthn at all.
 *
 * Checked directly rather than delegated, so it is honest in an SSR pass, in a
 * test environment, and in an insecure context — all three of which are places a
 * surface renders before any authenticator exists.
 */
export function isPasskeySupported(): boolean {
  if (typeof window === "undefined" || typeof navigator === "undefined") return false;
  if (typeof (globalThis as Record<string, unknown>)["PublicKeyCredential"] !== "function") {
    return false;
  }
  const credentials = navigator.credentials as CredentialsContainer | undefined;
  return typeof credentials?.create === "function" && typeof credentials.get === "function";
}

/**
 * Whether a *platform* authenticator (Touch ID, Windows Hello, Android
 * biometrics) is present. `false` does not mean passkeys are unavailable — a
 * phone over hybrid, or a hardware key, still works.
 */
export async function isPlatformAuthenticatorAvailable(): Promise<boolean> {
  if (!isPasskeySupported()) return false;
  try {
    return await platformAuthenticatorIsAvailable();
  } catch {
    return false;
  }
}

/**
 * Whether the browser can offer a passkey from inside a username field
 * (conditional UI / autofill). Only worth acting on when you render
 * `mode="email"`.
 */
export async function isConditionalUiAvailable(): Promise<boolean> {
  if (!isPasskeySupported()) return false;
  try {
    return await browserSupportsWebAuthnAutofill();
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// Transport
// ---------------------------------------------------------------------------

/**
 * How the ceremony reaches your backend.
 *
 * Deliberately one method. Both backends expose four POST endpoints and nothing
 * else, so an app that routes through Inertia, axios, a fetch wrapper with
 * retries, or its own auth headers implements this in four lines instead of
 * configuring ours.
 */
export interface PasskeyTransport {
  /**
   * POST `path` (relative to whatever prefix the transport owns) and resolve
   * with the decoded JSON body. **Reject on a non-2xx** — ideally with a
   * {@link PasskeyServerError} so the backend's own error code survives.
   */
  post(path: string, body?: unknown): Promise<unknown>;
}

export interface FetchTransportOptions {
  /**
   * Route prefix both backends mount their four endpoints under.
   * Default `"/passkeys"`. A trailing slash is trimmed.
   */
  baseUrl?: string;
  /** Extra headers merged over the defaults. */
  headers?: Record<string, string>;
  /** Default `"same-origin"` — a passkey session is a cookie session. */
  credentials?: RequestCredentials;
  /**
   * Laravel CSRF token, or a getter for one (useful when the token rotates).
   *
   * When omitted the transport reads the `XSRF-TOKEN` cookie, which is what a
   * Laravel app already sets and what `axios` would have sent.
   */
  csrfToken?: string | (() => string | null);
}

function readCookie(name: string): string | null {
  if (typeof document === "undefined") return null;
  const prefix = `${name}=`;
  for (const part of document.cookie.split(";")) {
    const entry = part.trim();
    if (entry.startsWith(prefix)) return decodeURIComponent(entry.slice(prefix.length));
  }
  return null;
}

/**
 * The transport most apps want: `fetch`, JSON in and out, same-origin cookies,
 * and Laravel's CSRF header filled in.
 *
 * A non-2xx carrying the wire contract's `{ error: { code, message } }` becomes
 * a {@link PasskeyServerError} with that exact `code`.
 */
export function createFetchTransport(options: FetchTransportOptions = {}): PasskeyTransport {
  // Scanned, not matched. `/\/+$/` anchors a greedy run at the end, so on a
  // long run of slashes NOT followed by end-of-string the engine restarts the
  // run at every position — quadratic (CodeQL js/polynomial-redos, #1).
  // Measured: 30k slashes took ~590ms through the regex and 0ms through this.
  let baseUrl = options.baseUrl ?? "/passkeys";
  while (baseUrl.endsWith("/")) {
    baseUrl = baseUrl.slice(0, -1);
  }
  const credentials = options.credentials ?? "same-origin";

  return {
    async post(path: string, body?: unknown): Promise<unknown> {
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
        Accept: "application/json",
      };

      const explicitToken =
        typeof options.csrfToken === "function" ? options.csrfToken() : options.csrfToken;

      if (explicitToken) {
        // Laravel reads `X-CSRF-TOKEN` first and only falls back to
        // `X-XSRF-TOKEN` (the encrypted cookie form) when it is absent, so
        // sending both lets the same option carry either kind of token.
        headers["X-CSRF-TOKEN"] = explicitToken;
        headers["X-XSRF-TOKEN"] = explicitToken;
      } else {
        const cookieToken = readCookie("XSRF-TOKEN");
        if (cookieToken) headers["X-XSRF-TOKEN"] = cookieToken;
      }

      Object.assign(headers, options.headers ?? {});

      const response = await fetch(`${baseUrl}${path}`, {
        method: "POST",
        credentials,
        headers,
        body: body === undefined ? undefined : JSON.stringify(body),
      });

      const text = await response.text();
      let payload: unknown;
      if (text.length > 0) {
        try {
          payload = JSON.parse(text);
        } catch {
          payload = undefined;
        }
      }

      if (!response.ok) {
        const wire = (payload as { error?: { code?: unknown; message?: unknown } } | undefined)
          ?.error;
        if (wire && typeof wire.code === "string") {
          throw new PasskeyServerError(
            wire.code,
            typeof wire.message === "string" ? wire.message : "The passkey request was rejected.",
            { status: response.status },
          );
        }
        throw new PasskeyCeremonyError(
          "ceremony_failed",
          `The passkey request failed (HTTP ${response.status}).`,
          { status: response.status },
        );
      }

      return payload;
    },
  };
}

// ---------------------------------------------------------------------------
// Ceremonies
// ---------------------------------------------------------------------------

/** `POST {prefix}/register/options` and `POST {prefix}/login/options` both return this. */
interface OptionsResponse<T> {
  state: string;
  publicKey: T;
}

export interface RegisterPasskeyOptions {
  /** Label for the new credential, e.g. "MacBook Touch ID". */
  name?: string;
}

export interface RegisterPasskeyResult {
  credential: PasskeySummary;
}

/**
 * Enroll a new passkey for the **already authenticated** user.
 *
 * Two round trips, exactly as the wire contract specifies:
 *
 * 1. `POST {prefix}/register/options` → `{ state, publicKey }`
 * 2. `navigator.credentials.create()` via `startRegistration`
 * 3. `POST {prefix}/register` with `{ state, name?, response }` → `{ credential }`
 *
 * The `state` handle is round-tripped untouched. It is an opaque pointer to the
 * server-side challenge record, which is single-use and pulled before
 * verification — so a replayed response fails at "no such challenge" whether or
 * not its signature is valid.
 */
export async function registerPasskey(
  transport: PasskeyTransport,
  options: RegisterPasskeyOptions = {},
): Promise<RegisterPasskeyResult> {
  try {
    if (!isPasskeySupported()) {
      throw new PasskeyCeremonyError(
        "not_supported",
        "This browser does not support passkeys.",
      );
    }

    const begun = (await transport.post(
      "/register/options",
    )) as OptionsResponse<PublicKeyCredentialCreationOptionsJSON>;

    const response: RegistrationResponseJSON = await startRegistration({
      optionsJSON: begun.publicKey,
    });

    const body: { state: string; name?: string; response: RegistrationResponseJSON } = {
      state: begun.state,
      response,
    };
    if (options.name !== undefined) body.name = options.name;

    return (await transport.post("/register", body)) as RegisterPasskeyResult;
  } catch (err) {
    throw normalizeCeremonyError(err);
  }
}

export interface AuthenticateWithPasskeyOptions {
  /**
   * Username-first flow. Omit for the discoverable (usernameless) flow, which is
   * the one v1 optimises for and the one that has nothing to enumerate.
   */
  email?: string;
  /**
   * Start a conditional-UI (autofill) ceremony instead of a modal one. Pair it
   * with an `autocomplete="username webauthn"` input, and check
   * {@link isConditionalUiAvailable} first.
   */
  conditional?: boolean;
  /**
   * Tear the ceremony down — the case that actually matters is a long-lived
   * conditional-UI request that outlives the route that started it.
   *
   * Aborting calls `WebAuthnAbortService.cancelCeremony()`, so the browser's own
   * prompt closes rather than being merely ignored, and the promise settles as
   * `cancelled` (never `ceremony_failed`).
   */
  signal?: AbortSignal;
}

export interface AuthenticateWithPasskeyResult {
  /** Whatever the backend considers a user. Opaque here on purpose. */
  user: unknown;
  credential: PasskeySummary;
}

/**
 * Sign in with a passkey.
 *
 * 1. `POST {prefix}/login/options` (body `{ email }` only when one was given) → `{ state, publicKey }`
 * 2. `navigator.credentials.get()` via `startAuthentication`
 * 3. `POST {prefix}/login` with `{ state, response }` → `{ user, credential }`
 *
 * There is no variant of this function an agent can complete, and there is not
 * going to be one. Step 2 requires a user gesture and a biometric or PIN.
 */
export async function authenticateWithPasskey(
  transport: PasskeyTransport,
  options: AuthenticateWithPasskeyOptions = {},
): Promise<AuthenticateWithPasskeyResult> {
  const { signal } = options;

  try {
    if (!isPasskeySupported()) {
      throw new PasskeyCeremonyError(
        "not_supported",
        "This browser does not support passkeys.",
      );
    }
    throwIfAborted(signal);

    const begun = (await transport.post(
      "/login/options",
      options.email === undefined ? undefined : { email: options.email },
    )) as OptionsResponse<PublicKeyCredentialRequestOptionsJSON>;

    throwIfAborted(signal);

    const response = await withCeremonyAbort(signal, () =>
      startAuthentication({
        optionsJSON: begun.publicKey,
        useBrowserAutofill: options.conditional === true,
      }),
    );

    throwIfAborted(signal);

    return (await transport.post("/login", {
      state: begun.state,
      response,
    })) as AuthenticateWithPasskeyResult;
  } catch (err) {
    throw normalizeCeremonyError(err);
  }
}

function throwIfAborted(signal: AbortSignal | undefined): void {
  if (signal?.aborted) {
    throw new PasskeyCeremonyError("cancelled", "The passkey ceremony was aborted.");
  }
}

/**
 * Run a ceremony, wiring `signal` to the library's abort singleton so an abort
 * closes the browser prompt instead of leaving it up while we walk away.
 */
async function withCeremonyAbort<T>(
  signal: AbortSignal | undefined,
  run: () => Promise<T>,
): Promise<T> {
  if (!signal) return run();

  const cancel = () => {
    WebAuthnAbortService.cancelCeremony();
  };
  signal.addEventListener("abort", cancel, { once: true });
  try {
    return await run();
  } finally {
    signal.removeEventListener("abort", cancel);
  }
}

import type { PasskeyActivityAction, PasskeyActivityEvent } from "./types";

/**
 * Build one `AgentActivity`-shaped event.
 *
 * Kept in one place so every surface stamps the same shape — a presence or undo
 * layer subscribing to these should never have to special-case which component
 * emitted.
 */
export function activityEvent(
  surface: string,
  action: PasskeyActivityAction,
  target?: string,
  detail?: Record<string, unknown>,
): PasskeyActivityEvent {
  const event: PasskeyActivityEvent = { surface, action, at: new Date().toISOString() };
  if (target !== undefined) event.target = target;
  if (detail !== undefined) event.detail = detail;
  return event;
}

/** `2026-07-31T09:12:00Z` → `2026-07-31`, without dragging in a locale. */
export function isoDate(value: string): string {
  return value.length >= 10 ? value.slice(0, 10) : value;
}

/**
 * Shared, **type-only** vocabulary for both entry points.
 *
 * Nothing in this file emits runtime code, which is what lets the React-free
 * `./client` entry and the React entry share it without either one dragging the
 * other into a consumer's bundle.
 */

/**
 * One registered credential, exactly as both backends serialise it
 * (`PasskeySummaryJSON` in the wire contract).
 *
 * Every field is JSON-primitive on purpose: `createdAt` is an ISO string rather
 * than a `Date` so a whole surface state survives
 * `JSON.parse(JSON.stringify(state))` unchanged — the property an agent needs in
 * order to read a surface back out and write one in.
 */
export interface PasskeySummary {
  /** base64url credential ID. Globally unique, and the handle every agent-facing action is keyed by. */
  id: string;
  /** Human-chosen label ("MacBook Touch ID"). `null` when the user never named it. */
  name: string | null;
  /** ISO-8601. */
  createdAt: string;
  /** ISO-8601, or `null` when the credential has never been used to sign in. */
  lastUsedAt: string | null;
  /** Transport hints reported at registration ("internal", "hybrid", "usb", …). */
  transports: string[];
  /** True for a *synced* passkey (the BE/BS flags). False means this device only. */
  backedUp: boolean;
  /** Authenticator model identifier. Stored, never used for a trust decision in v1. */
  aaguid: string;
  /**
   * ISO-8601 when the signature counter regressed for this credential — i.e. the
   * server saw evidence the private key may have been cloned. A security event,
   * and the surfaces render it as one.
   */
  clonedAt: string | null;
}

/**
 * The closed set of error codes both backends emit in
 * `{ "error": { "code", "message" } }`. Kept as a union *plus* `string` at the
 * call sites so a newer backend adding a code does not become a type error in an
 * older UI.
 */
export type PasskeyServerErrorCode =
  | "challenge_expired"
  | "challenge_not_found"
  | "challenge_type_mismatch"
  | "origin_not_allowed"
  | "rp_id_mismatch"
  | "unknown_credential"
  | "credential_already_registered"
  | "counter_regressed"
  | "user_verification_required"
  | "user_handle_mismatch"
  | "verification_failed"
  | "invalid_response"
  | "not_supported";

/**
 * The error shape carried *in surface state* — a plain object, not an `Error`,
 * because state has to be serialisable.
 */
export interface PasskeyStateError {
  /** A `PasskeyServerErrorCode` when the server rejected, otherwise a `PasskeyCeremonyErrorCode`. */
  code: string;
  message: string;
}

/** Every mutation a surface can report. */
export type PasskeyActivityAction =
  | "authenticate"
  | "enroll"
  | "rename"
  | "revoke-proposed"
  | "revoke-confirmed"
  | "revoke-cancelled"
  | "cancelled"
  | "error";

/**
 * `AgentActivity`-shaped event emitted on every mutation, so presence, undo and
 * coaching layers compose without this package knowing about them.
 */
export interface PasskeyActivityEvent {
  /** The `surfaceId` of the emitting surface. */
  surface: string;
  action: PasskeyActivityAction;
  /** Credential ID, where the action has one. */
  target?: string;
  /** ISO-8601. */
  at: string;
  detail?: Record<string, unknown>;
}

import { useCallback, useRef } from "react";
import { Button, Callout, Input, cn } from "@particle-academy/react-fancy";
import { normalizeCeremonyError } from "./client";
import { activityEvent } from "./activity";
import type { PasskeyActivityEvent, PasskeyStateError } from "./types";

/**
 * Where a sign-in surface is in the ceremony.
 *
 * `cancelled` is a first-class status and **not** an error: the human dismissed
 * the prompt, which is an ordinary thing to do. `checking` and `verifying` are
 * host-set — the component never runs the ceremony, so it cannot know when the
 * browser prompt closed or when the server finished verifying.
 */
export type PasskeySignInStatus =
  | "idle"
  | "checking"
  | "prompting"
  | "verifying"
  | "success"
  | "error"
  | "cancelled"
  | "unsupported";

export interface PasskeySignInState {
  status: PasskeySignInStatus;
  /** Only meaningful in `mode="email"`. Carried always so the state shape is stable. */
  email: string;
  error: PasskeyStateError | null;
}

export type PasskeySignInLabelKey =
  | "button"
  | "emailLabel"
  | "emailPlaceholder"
  | "unsupported"
  | "cancelled"
  | "prompting"
  | "verifying";

export interface PasskeySignInProps {
  value: PasskeySignInState;
  /** Always called with the **full** next state — never a slice. */
  onChange: (next: PasskeySignInState) => void;
  /**
   * Run the ceremony. **Resolve means signed in; throw means it failed** — the
   * component maps a thrown `NotAllowedError` to `status: "cancelled"` and
   * anything else to `status: "error"`.
   *
   * The component deliberately does not call `navigator.credentials` itself.
   * Keeping the ceremony in the host's hands is what makes this surface pure,
   * testable without an authenticator, and impossible to complete from a bridge.
   */
  onAuthenticate: (input: { email?: string }) => Promise<void> | void;
  /**
   * `"discoverable"` (default) shows only the button and takes no username —
   * the usernameless flow the plan optimises for, and the one with nothing to
   * enumerate. `"email"` renders the username-first input.
   */
  mode?: "discoverable" | "email";
  /** Root handle. Default `"passkey-sign-in"`. */
  surfaceId?: string;
  labels?: Partial<Record<PasskeySignInLabelKey, string>>;
  /**
   * Opt into conditional UI (autofill). In `mode="email"` this switches the
   * input to `autocomplete="username webauthn"`, which is what makes the browser
   * offer a passkey from the field itself.
   */
  conditional?: boolean;
  onActivity?: (event: PasskeyActivityEvent) => void;
  className?: string;
}

const DEFAULT_LABELS: Record<PasskeySignInLabelKey, string> = {
  button: "Sign in with a passkey",
  emailLabel: "Email",
  emailPlaceholder: "you@example.com",
  unsupported: "This browser can't use passkeys. Sign in another way, or try a different browser.",
  cancelled: "Passkey sign-in was cancelled. You can try again whenever you like.",
  prompting: "Waiting for your passkey…",
  verifying: "Verifying your passkey…",
};

const BUSY: ReadonlySet<PasskeySignInStatus> = new Set(["checking", "prompting", "verifying"]);

/**
 * A controlled passkey sign-in surface.
 *
 * Everything an agent can meaningfully do here — read the status, read the
 * error, fill the email field, press the button — is state and has a handle.
 * The one thing it cannot do is finish the ceremony, because
 * `navigator.credentials.get()` wants a user gesture and a biometric. That is
 * not a gap in the bridge; it is the property that makes a passkey worth having.
 */
export function PasskeySignIn({
  value,
  onChange,
  onAuthenticate,
  mode = "discoverable",
  surfaceId = "passkey-sign-in",
  labels,
  conditional,
  onActivity,
  className,
}: PasskeySignInProps) {
  // The latest rendered state, read at the moment an async handler resolves so a
  // full-state emission is built from what the surface currently shows rather
  // than from a closure captured before the await.
  const valueRef = useRef(value);
  valueRef.current = value;

  const label = (key: PasskeySignInLabelKey): string => labels?.[key] ?? DEFAULT_LABELS[key];

  const emit = useCallback(
    (event: PasskeyActivityEvent) => {
      onActivity?.(event);
    },
    [onActivity],
  );

  const authenticate = useCallback(async () => {
    const current = valueRef.current;
    if (current.status === "unsupported" || BUSY.has(current.status)) return;

    const email = mode === "email" ? current.email : undefined;

    emit(activityEvent(surfaceId, "authenticate", undefined, { mode, conditional: !!conditional }));
    onChange({ ...current, status: "prompting", error: null });

    try {
      await onAuthenticate(email === undefined ? {} : { email });
      onChange({ ...valueRef.current, status: "success", error: null });
    } catch (err) {
      const failure = normalizeCeremonyError(err);
      if (failure.code === "cancelled") {
        // Not a failure. Rendered as a muted hint, never as an alert.
        onChange({ ...valueRef.current, status: "cancelled", error: null });
        emit(activityEvent(surfaceId, "cancelled"));
        return;
      }
      const error: PasskeyStateError = {
        code: failure.serverCode ?? failure.code,
        message: failure.message,
      };
      onChange({ ...valueRef.current, status: "error", error });
      emit(activityEvent(surfaceId, "error", undefined, { code: error.code }));
    }
  }, [conditional, emit, mode, onAuthenticate, onChange, surfaceId]);

  const unsupported = value.status === "unsupported";
  const busy = BUSY.has(value.status);

  const hint =
    value.status === "unsupported"
      ? { key: "unsupported" as const, text: label("unsupported") }
      : value.status === "cancelled"
        ? { key: "cancelled" as const, text: label("cancelled") }
        : value.status === "prompting"
          ? { key: "prompting" as const, text: label("prompting") }
          : value.status === "verifying"
            ? { key: "verifying" as const, text: label("verifying") }
            : null;

  const button = (
    <Button
      type="button"
      color="blue"
      icon="fingerprint"
      loading={busy}
      disabled={unsupported || busy || value.status === "success"}
      onClick={() => void authenticate()}
      data-fancy-passkey-action="authenticate"
      data-fancy-passkey-surface-id={surfaceId}
    >
      {label("button")}
    </Button>
  );

  return (
    <div
      data-fancy-passkey-surface={surfaceId}
      data-fancy-passkey-status={value.status}
      data-fancy-passkey-mode={mode}
      className={cn("fancy-passkey fancy-passkey-signin", className)}
    >
      {mode === "email" ? (
        <form
          className="fancy-passkey-signin__form"
          onSubmit={(event) => {
            event.preventDefault();
            void authenticate();
          }}
        >
          <Input
            type="email"
            name="email"
            label={label("emailLabel")}
            placeholder={label("emailPlaceholder")}
            value={value.email}
            disabled={unsupported || busy}
            // The `webauthn` token is what lets the browser surface a passkey
            // from inside the field. Without conditional UI it is a plain
            // username field and claiming otherwise would be a lie to the
            // autofill engine.
            autoComplete={conditional ? "username webauthn" : "username"}
            data-fancy-passkey-field="email"
            onChange={(event) => onChange({ ...valueRef.current, email: event.target.value })}
          />
          {button}
        </form>
      ) : (
        button
      )}

      {/* `Callout` already carries `role="alert"`, so this wrapper carries only
          the handle — nesting a second alert makes the region ambiguous to a
          screen reader and to `getByRole`. */}
      {value.status === "error" && value.error ? (
        <div data-fancy-passkey-error={value.error.code} className="fancy-passkey__error">
          <Callout color="red">{value.error.message}</Callout>
        </div>
      ) : null}

      {hint ? (
        <p data-fancy-passkey-hint={hint.key} className="fancy-passkey__hint">
          {hint.text}
        </p>
      ) : null}
    </div>
  );
}

/**
 * `@particle-academy/fancy-passkeys-ui/client` — the browser half of both
 * WebAuthn ceremonies, with **zero React**.
 *
 * Every frontend needs this code and only some of them are React, so it lives
 * behind its own entry point: importing the React surfaces never costs you a
 * second copy of the ceremony, and importing the ceremony never costs a Vue or
 * Svelte app a React dependency. `packaging.test.ts` asserts the built
 * `dist/client.js` contains no React import — if that test fails, something
 * moved into the wrong entry.
 *
 * What this module does NOT contain is anything that lets a caller *complete* a
 * ceremony without the human at the keyboard. `navigator.credentials.get()`
 * needs a user gesture and a biometric or PIN, and both of those are things only
 * a person has. That boundary is the whole reason a passkey is worth having, so
 * it is not softened here and will not grow an escape hatch.
 */

import {
  startAuthentication,
  startRegistration,
  browserSupportsWebAuthnAutofill,
  platformAuthenticatorIsAvailable,
  WebAuthnAbortService,
} from "@simplewebauthn/browser";
import type {
  AuthenticationResponseJSON,
  PublicKeyCredentialCreationOptionsJSON,
  PublicKeyCredentialRequestOptionsJSON,
  RegistrationResponseJSON,
} from "@simplewebauthn/browser";
import type { PasskeyServerErrorCode, PasskeySummary } from "./types";

export type {
  PasskeySummary,
  PasskeyServerErrorCode,
  PasskeyStateError,
  PasskeyActivityAction,
  PasskeyActivityEvent,
} from "./types";

export type {
  AuthenticationResponseJSON,
  PublicKeyCredentialCreationOptionsJSON,
  PublicKeyCredentialRequestOptionsJSON,
  RegistrationResponseJSON,
};

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

/**
 * How a ceremony ended, from the browser's point of view.
 *
 * `cancelled` is deliberately its own code and **is not a failure**. The browser
 * reports "the human dismissed the prompt" and "the prompt timed out" with the
 * same `NotAllowedError` it would use for a genuine refusal, and a sign-in
 * surface that paints abandonment red teaches people the surface is broken.
 */
export type PasskeyCeremonyErrorCode =
  | "cancelled"
  | "not_supported"
  | "already_registered"
  | "security_error"
  | "ceremony_failed";

export interface PasskeyCeremonyErrorOptions {
  /** The original `DOMException` / `WebAuthnError` / transport rejection. */
  cause?: unknown;
  /** The backend's own `PasskeyErrorCode`, when the failure came from a response body. */
  serverCode?: string;
  /** HTTP status, when the failure came from a response. */
  status?: number;
}

/** Every rejection from this module is one of these. */
export class PasskeyCeremonyError extends Error {
  readonly code: PasskeyCeremonyErrorCode;
  /**
   * The backend's own error code, preserved verbatim rather than flattened
   * into `ceremony_failed`.
   *
   * Note that the first-party backends deliberately redact
   * `unknown_credential`, `user_handle_mismatch` and `counter_regressed` to
   * `verification_failed` before they reach the wire — each answers a question
   * about a credential the server holds, and an unauthenticated caller has no
   * business asking. Do not branch on those three; they will never arrive.
   */
  readonly serverCode?: string;
  readonly status?: number;
  // Declared here rather than `override`n: the package targets ES2021, whose
  // `Error` has no `cause` to override.
  readonly cause?: unknown;

  constructor(
    code: PasskeyCeremonyErrorCode,
    message: string,
    options: PasskeyCeremonyErrorOptions = {},
  ) {
    super(message);
    this.name = "PasskeyCeremonyError";
    this.code = code;
    if (options.serverCode !== undefined) this.serverCode = options.serverCode;
    if (options.status !== undefined) this.status = options.status;
    if (options.cause !== undefined) this.cause = options.cause;
  }
}

/**
 * A 4xx from either backend, carrying the wire contract's
 * `{ "error": { "code", "message" } }` payload.
 *
 * It extends {@link PasskeyCeremonyError} so `instanceof PasskeyCeremonyError`
 * still catches everything, while `serverCode` stays exact.
 */
export class PasskeyServerError extends PasskeyCeremonyError {
  override readonly serverCode: string;

  constructor(
    serverCode: PasskeyServerErrorCode | string,
    message: string,
    options: { status?: number; cause?: unknown } = {},
  ) {
    super(ceremonyCodeForServerCode(serverCode), message, { ...options, serverCode });
    this.name = "PasskeyServerError";
    this.serverCode = serverCode;
  }
}

function ceremonyCodeForServerCode(serverCode: string): PasskeyCeremonyErrorCode {
  switch (serverCode) {
    case "credential_already_registered":
      return "already_registered";
    case "origin_not_allowed":
    case "rp_id_mismatch":
    case "user_handle_mismatch":
      return "security_error";
    case "not_supported":
      return "not_supported";
    default:
      return "ceremony_failed";
  }
}

function nameOf(err: unknown): string | undefined {
  if (typeof err !== "object" || err === null) return undefined;
  const name = (err as { name?: unknown }).name;
  return typeof name === "string" ? name : undefined;
}

function messageOf(err: unknown, fallback: string): string {
  if (typeof err !== "object" || err === null) return fallback;
  const message = (err as { message?: unknown }).message;
  return typeof message === "string" && message.length > 0 ? message : fallback;
}

/**
 * Turn anything a ceremony can throw into a typed {@link PasskeyCeremonyError}.
 *
 * The mapping that matters:
 *
 * | thrown | code |
 * |---|---|
 * | `NotAllowedError` | `cancelled` — the human dismissed it or it timed out |
 * | `AbortError` | `cancelled` — the host tore the ceremony down (see `signal`) |
 * | `InvalidStateError` | `already_registered` — this authenticator already holds a credential for this account |
 * | `SecurityError` | `security_error` — RP ID / origin does not match |
 * | `NotSupportedError` | `not_supported` |
 * | anything else | `ceremony_failed` |
 *
 * `@simplewebauthn/browser` wraps the `DOMException` in a `WebAuthnError` whose
 * `name` defaults to the underlying exception's, so both shapes land in the same
 * rows; the `cause` chain is checked too for the cases where it does not.
 *
 * An error that is already a `PasskeyCeremonyError` (including a
 * {@link PasskeyServerError}) is returned untouched — that is what stops a
 * server's own code being flattened into `ceremony_failed` by a caller that
 * normalises defensively.
 */
export function normalizeCeremonyError(err: unknown): PasskeyCeremonyError {
  if (err instanceof PasskeyCeremonyError) return err;

  const names = [nameOf(err), nameOf((err as { cause?: unknown } | null)?.cause)];

  for (const name of names) {
    switch (name) {
      case "NotAllowedError":
        return new PasskeyCeremonyError(
          "cancelled",
          messageOf(err, "The passkey prompt was dismissed or timed out."),
          { cause: err },
        );
      case "AbortError":
        return new PasskeyCeremonyError(
          "cancelled",
          messageOf(err, "The passkey ceremony was aborted."),
          { cause: err },
        );
      case "InvalidStateError":
        return new PasskeyCeremonyError(
          "already_registered",
          messageOf(err, "This device already holds a passkey for this account."),
          { cause: err },
        );
      case "SecurityError":
        return new PasskeyCeremonyError(
          "security_error",
          messageOf(err, "The passkey could not be used on this origin."),
          { cause: err },
        );
      case "NotSupportedError":
        return new PasskeyCeremonyError(
          "not_supported",
          messageOf(err, "This browser or authenticator does not support passkeys."),
          { cause: err },
        );
      default:
        break;
    }
  }

  return new PasskeyCeremonyError("ceremony_failed", messageOf(err, "The passkey ceremony failed."), {
    cause: err,
  });
}

// ---------------------------------------------------------------------------
// Feature detection
// ---------------------------------------------------------------------------

/**
 * Whether this browser can do WebAuthn at all.
 *
 * Checked directly rather than delegated, so it is honest in an SSR pass, in a
 * test environment, and in an insecure context — all three of which are places a
 * surface renders before any authenticator exists.
 */
export function isPasskeySupported(): boolean {
  if (typeof window === "undefined" || typeof navigator === "undefined") return false;
  if (typeof (globalThis as Record<string, unknown>)["PublicKeyCredential"] !== "function") {
    return false;
  }
  const credentials = navigator.credentials as CredentialsContainer | undefined;
  return typeof credentials?.create === "function" && typeof credentials.get === "function";
}

/**
 * Whether a *platform* authenticator (Touch ID, Windows Hello, Android
 * biometrics) is present. `false` does not mean passkeys are unavailable — a
 * phone over hybrid, or a hardware key, still works.
 */
export async function isPlatformAuthenticatorAvailable(): Promise<boolean> {
  if (!isPasskeySupported()) return false;
  try {
    return await platformAuthenticatorIsAvailable();
  } catch {
    return false;
  }
}

/**
 * Whether the browser can offer a passkey from inside a username field
 * (conditional UI / autofill). Only worth acting on when you render
 * `mode="email"`.
 */
export async function isConditionalUiAvailable(): Promise<boolean> {
  if (!isPasskeySupported()) return false;
  try {
    return await browserSupportsWebAuthnAutofill();
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// Transport
// ---------------------------------------------------------------------------

/**
 * How the ceremony reaches your backend.
 *
 * Deliberately one method. Both backends expose four POST endpoints and nothing
 * else, so an app that routes through Inertia, axios, a fetch wrapper with
 * retries, or its own auth headers implements this in four lines instead of
 * configuring ours.
 */
export interface PasskeyTransport {
  /**
   * POST `path` (relative to whatever prefix the transport owns) and resolve
   * with the decoded JSON body. **Reject on a non-2xx** — ideally with a
   * {@link PasskeyServerError} so the backend's own error code survives.
   */
  post(path: string, body?: unknown): Promise<unknown>;
}

export interface FetchTransportOptions {
  /**
   * Route prefix both backends mount their four endpoints under.
   * Default `"/passkeys"`. A trailing slash is trimmed.
   */
  baseUrl?: string;
  /** Extra headers merged over the defaults. */
  headers?: Record<string, string>;
  /** Default `"same-origin"` — a passkey session is a cookie session. */
  credentials?: RequestCredentials;
  /**
   * Laravel CSRF token, or a getter for one (useful when the token rotates).
   *
   * When omitted the transport reads the `XSRF-TOKEN` cookie, which is what a
   * Laravel app already sets and what `axios` would have sent.
   */
  csrfToken?: string | (() => string | null);
}

function readCookie(name: string): string | null {
  if (typeof document === "undefined") return null;
  const prefix = `${name}=`;
  for (const part of document.cookie.split(";")) {
    const entry = part.trim();
    if (entry.startsWith(prefix)) return decodeURIComponent(entry.slice(prefix.length));
  }
  return null;
}

/**
 * The transport most apps want: `fetch`, JSON in and out, same-origin cookies,
 * and Laravel's CSRF header filled in.
 *
 * A non-2xx carrying the wire contract's `{ error: { code, message } }` becomes
 * a {@link PasskeyServerError} with that exact `code`.
 */
export function createFetchTransport(options: FetchTransportOptions = {}): PasskeyTransport {
  // Scanned, not matched. `/\/+$/` anchors a greedy run at the end, so on a
  // long run of slashes NOT followed by end-of-string the engine restarts the
  // run at every position — quadratic (CodeQL js/polynomial-redos, #1).
  // Measured: 30k slashes took ~590ms through the regex and 0ms through this.
  let baseUrl = options.baseUrl ?? "/passkeys";
  while (baseUrl.endsWith("/")) {
    baseUrl = baseUrl.slice(0, -1);
  }
  const credentials = options.credentials ?? "same-origin";

  return {
    async post(path: string, body?: unknown): Promise<unknown> {
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
        Accept: "application/json",
      };

      const explicitToken =
        typeof options.csrfToken === "function" ? options.csrfToken() : options.csrfToken;

      if (explicitToken) {
        // Laravel reads `X-CSRF-TOKEN` first and only falls back to
        // `X-XSRF-TOKEN` (the encrypted cookie form) when it is absent, so
        // sending both lets the same option carry either kind of token.
        headers["X-CSRF-TOKEN"] = explicitToken;
        headers["X-XSRF-TOKEN"] = explicitToken;
      } else {
        const cookieToken = readCookie("XSRF-TOKEN");
        if (cookieToken) headers["X-XSRF-TOKEN"] = cookieToken;
      }

      Object.assign(headers, options.headers ?? {});

      const response = await fetch(`${baseUrl}${path}`, {
        method: "POST",
        credentials,
        headers,
        body: body === undefined ? undefined : JSON.stringify(body),
      });

      const text = await response.text();
      let payload: unknown;
      if (text.length > 0) {
        try {
          payload = JSON.parse(text);
        } catch {
          payload = undefined;
        }
      }

      if (!response.ok) {
        const wire = (payload as { error?: { code?: unknown; message?: unknown } } | undefined)
          ?.error;
        if (wire && typeof wire.code === "string") {
          throw new PasskeyServerError(
            wire.code,
            typeof wire.message === "string" ? wire.message : "The passkey request was rejected.",
            { status: response.status },
          );
        }
        throw new PasskeyCeremonyError(
          "ceremony_failed",
          `The passkey request failed (HTTP ${response.status}).`,
          { status: response.status },
        );
      }

      return payload;
    },
  };
}

// ---------------------------------------------------------------------------
// Ceremonies
// ---------------------------------------------------------------------------

/** `POST {prefix}/register/options` and `POST {prefix}/login/options` both return this. */
interface OptionsResponse<T> {
  state: string;
  publicKey: T;
}

export interface RegisterPasskeyOptions {
  /** Label for the new credential, e.g. "MacBook Touch ID". */
  name?: string;
}

export interface RegisterPasskeyResult {
  credential: PasskeySummary;
}

/**
 * Enroll a new passkey for the **already authenticated** user.
 *
 * Two round trips, exactly as the wire contract specifies:
 *
 * 1. `POST {prefix}/register/options` → `{ state, publicKey }`
 * 2. `navigator.credentials.create()` via `startRegistration`
 * 3. `POST {prefix}/register` with `{ state, name?, response }` → `{ credential }`
 *
 * The `state` handle is round-tripped untouched. It is an opaque pointer to the
 * server-side challenge record, which is single-use and pulled before
 * verification — so a replayed response fails at "no such challenge" whether or
 * not its signature is valid.
 */
export async function registerPasskey(
  transport: PasskeyTransport,
  options: RegisterPasskeyOptions = {},
): Promise<RegisterPasskeyResult> {
  try {
    if (!isPasskeySupported()) {
      throw new PasskeyCeremonyError(
        "not_supported",
        "This browser does not support passkeys.",
      );
    }

    const begun = (await transport.post(
      "/register/options",
    )) as OptionsResponse<PublicKeyCredentialCreationOptionsJSON>;

    const response: RegistrationResponseJSON = await startRegistration({
      optionsJSON: begun.publicKey,
    });

    const body: { state: string; name?: string; response: RegistrationResponseJSON } = {
      state: begun.state,
      response,
    };
    if (options.name !== undefined) body.name = options.name;

    return (await transport.post("/register", body)) as RegisterPasskeyResult;
  } catch (err) {
    throw normalizeCeremonyError(err);
  }
}

export interface AuthenticateWithPasskeyOptions {
  /**
   * Username-first flow. Omit for the discoverable (usernameless) flow, which is
   * the one v1 optimises for and the one that has nothing to enumerate.
   */
  email?: string;
  /**
   * Start a conditional-UI (autofill) ceremony instead of a modal one. Pair it
   * with an `autocomplete="username webauthn"` input, and check
   * {@link isConditionalUiAvailable} first.
   */
  conditional?: boolean;
  /**
   * Tear the ceremony down — the case that actually matters is a long-lived
   * conditional-UI request that outlives the route that started it.
   *
   * Aborting calls `WebAuthnAbortService.cancelCeremony()`, so the browser's own
   * prompt closes rather than being merely ignored, and the promise settles as
   * `cancelled` (never `ceremony_failed`).
   */
  signal?: AbortSignal;
}

export interface AuthenticateWithPasskeyResult {
  /** Whatever the backend considers a user. Opaque here on purpose. */
  user: unknown;
  credential: PasskeySummary;
}

/**
 * Sign in with a passkey.
 *
 * 1. `POST {prefix}/login/options` (body `{ email }` only when one was given) → `{ state, publicKey }`
 * 2. `navigator.credentials.get()` via `startAuthentication`
 * 3. `POST {prefix}/login` with `{ state, response }` → `{ user, credential }`
 *
 * There is no variant of this function an agent can complete, and there is not
 * going to be one. Step 2 requires a user gesture and a biometric or PIN.
 */
export async function authenticateWithPasskey(
  transport: PasskeyTransport,
  options: AuthenticateWithPasskeyOptions = {},
): Promise<AuthenticateWithPasskeyResult> {
  const { signal } = options;

  try {
    if (!isPasskeySupported()) {
      throw new PasskeyCeremonyError(
        "not_supported",
        "This browser does not support passkeys.",
      );
    }
    throwIfAborted(signal);

    const begun = (await transport.post(
      "/login/options",
      options.email === undefined ? undefined : { email: options.email },
    )) as OptionsResponse<PublicKeyCredentialRequestOptionsJSON>;

    throwIfAborted(signal);

    const response = await withCeremonyAbort(signal, () =>
      startAuthentication({
        optionsJSON: begun.publicKey,
        useBrowserAutofill: options.conditional === true,
      }),
    );

    throwIfAborted(signal);

    return (await transport.post("/login", {
      state: begun.state,
      response,
    })) as AuthenticateWithPasskeyResult;
  } catch (err) {
    throw normalizeCeremonyError(err);
  }
}

function throwIfAborted(signal: AbortSignal | undefined): void {
  if (signal?.aborted) {
    throw new PasskeyCeremonyError("cancelled", "The passkey ceremony was aborted.");
  }
}

/**
 * Run a ceremony, wiring `signal` to the library's abort singleton so an abort
 * closes the browser prompt instead of leaving it up while we walk away.
 */
async function withCeremonyAbort<T>(
  signal: AbortSignal | undefined,
  run: () => Promise<T>,
): Promise<T> {
  if (!signal) return run();

  const cancel = () => {
    WebAuthnAbortService.cancelCeremony();
  };
  signal.addEventListener("abort", cancel, { once: true });
  try {
    return await run();
  } finally {
    signal.removeEventListener("abort", cancel);
  }
}

import type { PasskeyActivityAction, PasskeyActivityEvent } from "./types";

/**
 * Build one `AgentActivity`-shaped event.
 *
 * Kept in one place so every surface stamps the same shape — a presence or undo
 * layer subscribing to these should never have to special-case which component
 * emitted.
 */
export function activityEvent(
  surface: string,
  action: PasskeyActivityAction,
  target?: string,
  detail?: Record<string, unknown>,
): PasskeyActivityEvent {
  const event: PasskeyActivityEvent = { surface, action, at: new Date().toISOString() };
  if (target !== undefined) event.target = target;
  if (detail !== undefined) event.detail = detail;
  return event;
}

/** `2026-07-31T09:12:00Z` → `2026-07-31`, without dragging in a locale. */
export function isoDate(value: string): string {
  return value.length >= 10 ? value.slice(0, 10) : value;
}

/**
 * Shared, **type-only** vocabulary for both entry points.
 *
 * Nothing in this file emits runtime code, which is what lets the React-free
 * `./client` entry and the React entry share it without either one dragging the
 * other into a consumer's bundle.
 */

/**
 * One registered credential, exactly as both backends serialise it
 * (`PasskeySummaryJSON` in the wire contract).
 *
 * Every field is JSON-primitive on purpose: `createdAt` is an ISO string rather
 * than a `Date` so a whole surface state survives
 * `JSON.parse(JSON.stringify(state))` unchanged — the property an agent needs in
 * order to read a surface back out and write one in.
 */
export interface PasskeySummary {
  /** base64url credential ID. Globally unique, and the handle every agent-facing action is keyed by. */
  id: string;
  /** Human-chosen label ("MacBook Touch ID"). `null` when the user never named it. */
  name: string | null;
  /** ISO-8601. */
  createdAt: string;
  /** ISO-8601, or `null` when the credential has never been used to sign in. */
  lastUsedAt: string | null;
  /** Transport hints reported at registration ("internal", "hybrid", "usb", …). */
  transports: string[];
  /** True for a *synced* passkey (the BE/BS flags). False means this device only. */
  backedUp: boolean;
  /** Authenticator model identifier. Stored, never used for a trust decision in v1. */
  aaguid: string;
  /**
   * ISO-8601 when the signature counter regressed for this credential — i.e. the
   * server saw evidence the private key may have been cloned. A security event,
   * and the surfaces render it as one.
   */
  clonedAt: string | null;
}

/**
 * The closed set of error codes both backends emit in
 * `{ "error": { "code", "message" } }`. Kept as a union *plus* `string` at the
 * call sites so a newer backend adding a code does not become a type error in an
 * older UI.
 */
export type PasskeyServerErrorCode =
  | "challenge_expired"
  | "challenge_not_found"
  | "challenge_type_mismatch"
  | "origin_not_allowed"
  | "rp_id_mismatch"
  | "unknown_credential"
  | "credential_already_registered"
  | "counter_regressed"
  | "user_verification_required"
  | "user_handle_mismatch"
  | "verification_failed"
  | "invalid_response"
  | "not_supported";

/**
 * The error shape carried *in surface state* — a plain object, not an `Error`,
 * because state has to be serialisable.
 */
export interface PasskeyStateError {
  /** A `PasskeyServerErrorCode` when the server rejected, otherwise a `PasskeyCeremonyErrorCode`. */
  code: string;
  message: string;
}

/** Every mutation a surface can report. */
export type PasskeyActivityAction =
  | "authenticate"
  | "enroll"
  | "rename"
  | "revoke-proposed"
  | "revoke-confirmed"
  | "revoke-cancelled"
  | "cancelled"
  | "error";

/**
 * `AgentActivity`-shaped event emitted on every mutation, so presence, undo and
 * coaching layers compose without this package knowing about them.
 */
export interface PasskeyActivityEvent {
  /** The `surfaceId` of the emitting surface. */
  surface: string;
  action: PasskeyActivityAction;
  /** Credential ID, where the action has one. */
  target?: string;
  /** ISO-8601. */
  at: string;
  detail?: Record<string, unknown>;
}

import { Badge, cn } from "@particle-academy/react-fancy";

export interface PasskeyStatusProps {
  /** Result of `isPasskeySupported()`. */
  supported: boolean;
  /**
   * Result of `isPlatformAuthenticatorAvailable()`. `null` while unknown.
   * `false` is not a failure — a phone over hybrid or a hardware key still
   * works.
   */
  platformAuthenticator?: boolean | null;
  /** Result of `isConditionalUiAvailable()`. `null` while unknown. */
  conditionalUi?: boolean | null;
  /** Root handle. Default `"passkey-status"`. */
  surfaceId?: string;
  className?: string;
}

/**
 * A read-only "can this browser do passkeys?" indicator.
 *
 * Purely visual, so it owes only the authoring half of the component contract:
 * it takes plain booleans and renders. It runs no detection of its own on
 * purpose — probing inside a component makes it non-deterministic in SSR and in
 * tests, and the host already has the three `./client` predicates.
 */
export function PasskeyStatus({
  supported,
  platformAuthenticator = null,
  conditionalUi = null,
  surfaceId = "passkey-status",
  className,
}: PasskeyStatusProps) {
  return (
    <div
      data-fancy-passkey-surface={surfaceId}
      data-fancy-passkey-supported={String(supported)}
      className={cn("fancy-passkey fancy-passkey-status", className)}
    >
      <Badge variant="soft" color={supported ? "emerald" : "zinc"} data-fancy-passkey-flag="supported">
        {supported ? "Passkeys supported" : "Passkeys unavailable"}
      </Badge>

      {supported && platformAuthenticator !== null ? (
        <Badge
          variant="soft"
          color={platformAuthenticator ? "emerald" : "zinc"}
          data-fancy-passkey-flag="platform-authenticator"
        >
          {platformAuthenticator ? "Built-in authenticator" : "No built-in authenticator"}
        </Badge>
      ) : null}

      {supported && conditionalUi !== null ? (
        <Badge
          variant="soft"
          color={conditionalUi ? "emerald" : "zinc"}
          data-fancy-passkey-flag="conditional-ui"
        >
          {conditionalUi ? "Autofill sign-in" : "No autofill sign-in"}
        </Badge>
      ) : null}
    </div>
  );
}

import {
  forwardRef,
  useCallback,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
} from "react";
import { cn } from "../lib/utils/cn";
import { PILL_MARK, pasteMarker, segmentValue } from "./paste-markers";

/** The attribute on the placeholder span a pill is portalled into. */
export const HOST_ATTR = "data-react-fancy-composer-paste-host";

/** What a paste becomes, as decided by `Composer`. `block` pills get their own line. */
export interface PillToInsert {
  id: string;
  block: boolean;
}

export interface InlinePasteEditorHandle {
  focus(): void;
  /** Swap a pill for plain text, where it sits. */
  replacePill(id: string, text: string): void;
  /**
   * Replace the whole value and put the caret at `caret` (an offset into the
   * value). For a host that edits text itself — `PromptInput`'s `/` and `@`
   * pickers — where rebuilding from `value` alone would lose the caret.
   */
  setValue(value: string, caret: number): void;
}

interface InlinePasteEditorProps {
  value: string;
  /** Ids the composer holds. A marker for anything else stays text. */
  known: ReadonlySet<string>;
  /** `caret` is the caret's offset into `value`, or `value.length` if it is elsewhere. */
  onChange(value: string, caret: number): void;
  onSubmit(): void;
  /**
   * Which key sends. `"enter"` (default): Enter sends, Shift+Enter is a newline.
   * `"mod-enter"`: Ctrl/⌘+Enter sends and a plain Enter is a newline.
   */
  submitKey?: "enter" | "mod-enter";
  /** Runs BEFORE the editor's own key handling; `preventDefault()` to claim the key. */
  onKeyDown?(e: React.KeyboardEvent<HTMLDivElement>): void;
  placeholderClassName?: string;
  /** Height in px past which the input scrolls. Defaults to the class's max height. */
  maxHeight?: number;
  /** Return the pills a paste becomes, or null to insert its text as typed. */
  onPaste(data: DataTransfer | null): PillToInsert[] | null;
  /** Every pill placeholder currently in the editor, for the composer to portal into. */
  onHostsChange(hosts: ReadonlyMap<string, HTMLElement>): void;
  placeholder: string;
  disabled: boolean;
  className?: string;
  /**
   * `false` makes it a single-line field, as `Input` uses it: Enter always
   * submits, and a newline in pasted text becomes a space, as a browser does for
   * an `<input>`. A held paste keeps its newlines; it is only the field that has
   * one line. Default `true`.
   */
  multiline?: boolean;
  /** The editable surface's id, so a host can find it. */
  id?: string;
  /** Names the textbox for assistive tech; a `<div>` cannot be the target of a `<label>`. */
  ariaLabelledBy?: string;
  ariaInvalid?: boolean;
  style?: React.CSSProperties;
}

/**
 * Walk a node's children back into a value string.
 *
 * `<br>` as the LAST child of its parent is filler — browsers put one in an empty
 * line, and this editor puts one after a trailing newline so the caret has a line
 * to sit on — so it counts for nothing. Block elements a browser invents count as
 * a line break before them. Non-breaking spaces become spaces: a browser inserts
 * them for typed spaces it fears would collapse, not because anyone asked.
 */
function serialize(parent: Node, keep: (id: string) => boolean): string {
  let out = "";
  const children = Array.from(parent.childNodes);

  children.forEach((node, i) => {
    if (node.nodeType === Node.TEXT_NODE) {
      out += (node.textContent ?? "").replace(/\u00A0/g, " ");
      return;
    }
    if (!(node instanceof HTMLElement)) return;

    const id = node.getAttribute(HOST_ATTR);
    if (id !== null) {
      if (keep(id)) out += pasteMarker(id);
      return;
    }
    if (node.tagName === "BR") {
      if (i !== children.length - 1) out += "\n";
      return;
    }
    if (/^(DIV|P)$/.test(node.tagName) && out.length > 0 && !out.endsWith("\n")) {
      out += "\n";
    }
    out += serialize(node, keep);
  });

  return out;
}

function makeHost(id: string): HTMLElement {
  const host = document.createElement("span");
  host.setAttribute("contenteditable", "false");
  host.setAttribute(HOST_ATTR, id);
  host.className = "inline-block align-baseline";
  return host;
}

/** A value ending in a newline needs a `<br>` after it, or the caret has no line to sit on. */
function ensureTrailingBreak(root: HTMLElement, value: string) {
  const last = root.lastChild;
  const hasBreak = last instanceof HTMLElement && last.tagName === "BR";

  if (value.endsWith("\n") && !hasBreak) root.append(document.createElement("br"));
  if (!value.endsWith("\n") && hasBreak && value.length > 0) last.remove();
}

function placeCaretAfter(node: Node) {
  const selection = window.getSelection();
  if (!selection) return;

  const range = document.createRange();
  range.setStartAfter(node);
  range.collapse(true);
  selection.removeAllRanges();
  selection.addRange(range);
}

/**
 * Put the caret `offset` characters into the serialised value. Walks the shape
 * `render` produces — text nodes, pill hosts (each worth its marker's length) and
 * a trailing `<br>` — so it is only called straight after a render.
 */
function placeCaretAtOffset(root: HTMLElement, offset: number, keep: (id: string) => boolean) {
  const selection = window.getSelection();
  if (!selection) return;

  const range = document.createRange();
  let remaining = offset;
  let placed = false;

  for (const node of Array.from(root.childNodes)) {
    if (node.nodeType === Node.TEXT_NODE) {
      const length = node.textContent?.length ?? 0;
      if (remaining <= length) {
        range.setStart(node, remaining);
        placed = true;
        break;
      }
      remaining -= length;
      continue;
    }
    const id = node instanceof HTMLElement ? node.getAttribute(HOST_ATTR) : null;
    if (id !== null && keep(id)) {
      const length = pasteMarker(id).length;
      if (remaining < length) {
        range.setStartAfter(node);
        placed = true;
        break;
      }
      remaining -= length;
    }
  }

  if (!placed) {
    range.selectNodeContents(root);
    range.collapse(false);
    const last = root.lastChild;
    if (last instanceof HTMLElement && last.tagName === "BR") range.setStartBefore(last);
  }
  range.collapse(true);
  selection.removeAllRanges();
  selection.addRange(range);
}

/**
 * The plain-text-plus-pills surface behind `Composer`'s inline placement.
 *
 * The DOM is the source of truth WHILE TYPING and `value` is its serialisation;
 * the DOM is rebuilt from `value` only when `value` changes from outside (a send,
 * a host, an agent). Rebuilding on every keystroke would throw the caret away.
 *
 * Every insertion is done here by hand, never by the browser: a paste is always
 * intercepted, so no foreign HTML ever lands in the editor, and Enter is handled
 * so a browser never invents a `<div>` per line.
 */
export const InlinePasteEditor = forwardRef<InlinePasteEditorHandle, InlinePasteEditorProps>(
  function InlinePasteEditor(
    {
      value,
      known,
      onChange,
      onSubmit,
      onPaste,
      onHostsChange,
      placeholder,
      disabled,
      className,
      submitKey = "enter",
      onKeyDown,
      placeholderClassName,
      maxHeight,
      multiline = true,
      id,
      ariaLabelledBy,
      ariaInvalid,
      style,
    },
    ref,
  ) {
    const rootRef = useRef<HTMLDivElement>(null);
    /** The last value this editor produced or rendered. Anything else came from outside. */
    const lastValue = useRef<string | null>(null);
    /**
     * Ids inserted here whose hold has not reached `known` yet. A pill is held and
     * placed in the same event, and the composer's state lands a render later.
     */
    const pending = useRef(new Set<string>());
    const knownRef = useRef(known);
    knownRef.current = known;

    const keep = useCallback(
      (id: string) => knownRef.current.has(id) || pending.current.has(id),
      [],
    );

    const reportHosts = useCallback(() => {
      const root = rootRef.current;
      if (!root) return;

      const hosts = new Map<string, HTMLElement>();
      root.querySelectorAll<HTMLElement>(`[${HOST_ATTR}]`).forEach((el) => {
        const id = el.getAttribute(HOST_ATTR)!;
        if (keep(id)) hosts.set(id, el);
      });
      onHostsChange(hosts);
    }, [keep, onHostsChange]);

    /** The caret's offset into the serialised value, or its length if the caret is elsewhere. */
    const caretOffset = useCallback(
      (whole: string): number => {
        const root = rootRef.current;
        const selection = window.getSelection();
        if (!root || !selection || selection.rangeCount === 0) return whole.length;

        const range = selection.getRangeAt(0);
        if (!root.contains(range.endContainer)) return whole.length;

        const head = document.createRange();
        head.selectNodeContents(root);
        head.setEnd(range.endContainer, range.endOffset);
        return serialize(head.cloneContents(), keep).length;
      },
      [keep],
    );

    /** Read the DOM back into a value and tell the composer. */
    const emit = useCallback(() => {
      const root = rootRef.current;
      if (!root) return;

      const next = serialize(root, keep);
      ensureTrailingBreak(root, next);
      reportHosts();

      // Reported even when the value is unchanged: a host reading the caret (a
      // `/` picker) needs to hear about it.
      lastValue.current = next;
      onChange(next, caretOffset(next));
    }, [keep, onChange, reportHosts, caretOffset]);

    /** Rebuild the DOM from a value. Throws the caret away; callers put it back. */
    const render = useCallback(
      (next: string) => {
        const root = rootRef.current;
        if (!root) return;

        root.replaceChildren();
        for (const segment of segmentValue(next, knownRef.current)) {
          if (segment.type === "text") {
            root.append(document.createTextNode(segment.text));
          } else {
            root.append(makeHost(segment.id));
          }
        }
        ensureTrailingBreak(root, next);
        lastValue.current = next;
        reportHosts();
      },
      [reportHosts],
    );

    /** The caret's range, or the end of the editor if the caret is elsewhere. */
    const caret = useCallback((): Range => {
      const root = rootRef.current!;
      const selection = window.getSelection();

      if (selection && selection.rangeCount > 0) {
        const range = selection.getRangeAt(0);
        if (root.contains(range.commonAncestorContainer)) return range;
      }

      const range = document.createRange();
      range.selectNodeContents(root);
      range.collapse(false);
      const last = root.lastChild;
      if (last instanceof HTMLElement && last.tagName === "BR") {
        range.setStartBefore(last);
        range.collapse(true);
      }
      return range;
    }, []);

    /** Replace the selection with `nodes` and leave the caret after them. */
    const insert = useCallback(
      (build: (before: string, after: string) => Node[]) => {
        const root = rootRef.current!;
        const range = caret();
        range.deleteContents();

        const head = document.createRange();
        head.selectNodeContents(root);
        head.setEnd(range.startContainer, range.startOffset);
        const tail = document.createRange();
        tail.selectNodeContents(root);
        tail.setStart(range.endContainer, range.endOffset);

        const nodes = build(
          serialize(head.cloneContents(), () => true),
          serialize(tail.cloneContents(), () => true),
        );
        if (nodes.length === 0) return;

        const fragment = document.createDocumentFragment();
        nodes.forEach((n) => fragment.append(n));
        range.insertNode(fragment);
        placeCaretAfter(nodes[nodes.length - 1]);
        emit();
      },
      [caret, emit],
    );

    const insertText = useCallback(
      (text: string) => insert(() => (text ? [document.createTextNode(text)] : [])),
      [insert],
    );

    /*
     * Rebuild from `value` when it changed from outside — or when `known` now
     * disagrees with the pills on screen, e.g. a host set a marker and then the
     * paste it names. Never on our own edits: that would discard the caret.
     */
    useLayoutEffect(() => {
      const root = rootRef.current;
      if (!root) return;

      for (const id of pending.current) if (known.has(id)) pending.current.delete(id);

      const wanted = segmentValue(value, known)
        .flatMap((s) => (s.type === "pill" ? [s.id] : []))
        .join(PILL_MARK);
      const onScreen = Array.from(root.querySelectorAll(`[${HOST_ATTR}]`))
        .map((el) => el.getAttribute(HOST_ATTR))
        .filter((id): id is string => id !== null && keep(id))
        .join(PILL_MARK);

      if (value === lastValue.current && wanted === onScreen) return;

      render(value);
    }, [value, known, keep, render]);

    useImperativeHandle(
      ref,
      () => ({
        focus() {
          const root = rootRef.current;
          if (!root) return;
          root.focus();
          const range = caret();
          const selection = window.getSelection();
          selection?.removeAllRanges();
          selection?.addRange(range);
        },
        replacePill(id, text) {
          const root = rootRef.current;
          const host = Array.from(
            root?.querySelectorAll(`[${HOST_ATTR}]`) ?? [],
          ).find((el) => el.getAttribute(HOST_ATTR) === id);
          if (!root || !host) return;

          const node = document.createTextNode(text);
          host.replaceWith(node);
          root.focus();
          placeCaretAfter(node);
          emit();
        },
        setValue(next, offset) {
          const root = rootRef.current;
          if (!root) return;

          render(next);
          root.focus();
          placeCaretAtOffset(root, offset, keep);
          emit();
        },
      }),
      [caret, emit, render, keep],
    );

    const handlePaste = (e: React.ClipboardEvent<HTMLDivElement>) => {
      // ALWAYS intercepted: a browser left to paste into a contenteditable inserts
      // the clipboard's HTML, styles and all.
      e.preventDefault();
      if (disabled) return;

      const pills = onPaste(e.clipboardData);

      if (pills === null) {
        const text = (e.clipboardData?.getData("text/plain") ?? "").replace(/\r\n?/g, "\n");
        insertText(multiline ? text : text.replace(/\n+/g, " "));
        return;
      }

      for (const { id } of pills) pending.current.add(id);

      insert((before, after) => {
        const nodes: Node[] = [];

        for (const { id, block } of pills) {
          if (block) {
            // A text pill gets a line to itself: a newline above unless it is
            // already at the start of one, and below unless one follows.
            const precededByBreak =
              nodes.length === 0
                ? before === "" || before.endsWith("\n")
                : nodes[nodes.length - 1].textContent === "\n";
            if (!precededByBreak) nodes.push(document.createTextNode("\n"));
            nodes.push(makeHost(id));
            nodes.push(document.createTextNode("\n"));
          } else {
            nodes.push(makeHost(id));
          }
        }

        // The trailing newline of a block pill is redundant if one already follows.
        const last = nodes[nodes.length - 1];
        if (last.textContent === "\n" && after.startsWith("\n")) nodes.pop();

        return nodes;
      });
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(e);
      if (e.defaultPrevented) return;
      if (e.key !== "Enter" || e.nativeEvent.isComposing) return;

      e.preventDefault();
      const sends =
        !multiline || (submitKey === "mod-enter" ? e.ctrlKey || e.metaKey : !e.shiftKey);
      if (sends) {
        onSubmit();
      } else {
        insertText("\n");
      }
    };

    return (
      <div className="relative">
        {value === "" && (
          <span
            aria-hidden="true"
            className={cn(
              "pointer-events-none absolute left-4 top-3 text-sm text-zinc-400",
              placeholderClassName,
            )}
          >
            {placeholder}
          </span>
        )}
        <div
          ref={rootRef}
          id={id}
          data-react-fancy-composer-input=""
          role="textbox"
          aria-multiline={multiline}
          aria-labelledby={ariaLabelledBy}
          aria-invalid={ariaInvalid || undefined}
          aria-placeholder={placeholder}
          aria-disabled={disabled || undefined}
          contentEditable={!disabled}
          suppressContentEditableWarning
          onInput={emit}
          onPaste={handlePaste}
          onKeyDown={handleKeyDown}
          style={maxHeight === undefined ? style : { ...style, maxHeight }}
          className={cn(
            "max-h-72 min-h-[4.5rem] w-full overflow-y-auto whitespace-pre-wrap break-words bg-transparent px-4 pt-3 text-sm outline-none",
            className,
          )}
        />
      </div>
    );
  },
);

import { useEffect, useState, type ReactNode } from "react";
import { cn } from "../lib/utils/cn";
import { Tooltip } from "../tooltip";
import type { ComposerPasteClassNames, ComposerPastePreview } from "./PastePills.types";

/**
 * Thousands separators, written out rather than left to `toLocaleString()`.
 *
 * The number exists so someone can size the paste at a glance, and `2,036` sizes
 * faster than `2036`. It is not left to the runtime locale because the label beside
 * it ("Pasted text") is not localised either, so a locale-formatted number next to
 * an English noun would be half a translation.
 */
export function withSeparators(n: number): string {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

/** First and last N characters, middle elided. The ends say WHICH paste this is. */
export function endsOf(text: string, chars: number): string {
  if (text.length <= chars * 2) return text;

  return `${text.slice(0, chars)} … ${text.slice(-chars)}`;
}

const PILL_BASE =
  "inline-flex select-none items-center rounded-md px-2 py-0.5 text-xs leading-5 transition-colors";
const TEXT_PILL =
  "cursor-pointer bg-zinc-100 text-zinc-700 hover:bg-zinc-200 dark:bg-zinc-800 dark:text-zinc-200 dark:hover:bg-zinc-700";
const IMAGE_PILL =
  "bg-rose-100 font-medium text-rose-600 dark:bg-rose-500/20 dark:text-rose-300";
const PREVIEW_BASE = "max-w-xs whitespace-pre-wrap break-all text-xs";

/** An image's thumbnail, made from the File only while the preview is open. */
function ImageThumb({ file }: { file: File }) {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    if (typeof URL.createObjectURL !== "function") return;
    const made = URL.createObjectURL(file);
    setUrl(made);
    return () => URL.revokeObjectURL(made);
  }, [file]);

  return url ? (
    <img src={url} alt="" className="max-h-40 max-w-[16rem] rounded" />
  ) : (
    <span>{file.name}</span>
  );
}

interface InlinePillProps {
  preview: ComposerPastePreview;
  previewChars: number;
  renderPastePreview?: (preview: ComposerPastePreview) => ReactNode;
  classNames?: ComposerPasteClassNames;
  disabled: boolean;
  onExpand: (id: string) => void;
}

/**
 * One pill inside the message, portalled by `Composer` into a placeholder the
 * editor made. Internal — its own file so its props are not read as `Composer`'s.
 *
 * The hover preview is a portalled `Tooltip`, so the scrolling input cannot clip it.
 */
export function InlinePill({
  preview,
  previewChars,
  renderPastePreview,
  classNames,
  disabled,
  onExpand,
}: InlinePillProps) {
  const id = preview.kind === "text" ? preview.paste.id : preview.image.id;
  const content = (
    <span data-react-fancy-composer-paste-pill-preview={id}>
      {renderPastePreview?.(preview) ??
        (preview.kind === "text" ? (
          endsOf(preview.paste.text, previewChars)
        ) : (
          <ImageThumb file={preview.image.file} />
        ))}
    </span>
  );
  const tooltipClass = cn(PREVIEW_BASE, classNames?.preview);

  if (preview.kind === "image") {
    return (
      <Tooltip content={content} className={tooltipClass}>
        <span
          data-react-fancy-composer-image-pill={id}
          role="img"
          aria-label={preview.image.label}
          className={cn(PILL_BASE, IMAGE_PILL, classNames?.pill, classNames?.imagePill)}
        >
          {preview.image.label}
        </span>
      </Tooltip>
    );
  }

  const count = withSeparators(preview.paste.text.length);

  return (
    <Tooltip content={content} className={tooltipClass}>
      <button
        type="button"
        data-react-fancy-composer-paste-pill={id}
        onClick={() => onExpand(id)}
        disabled={disabled}
        aria-label={`Insert this pasted text, ${count} characters`}
        className={cn(PILL_BASE, TEXT_PILL, classNames?.pill, classNames?.textPill)}
      >
        Pasted text · {count} characters
      </button>
    </Tooltip>
  );
}

import type { HeldPaste } from "./use-paste-pills";
import type { HeldImage } from "./paste-markers";

export type { HeldPaste, HeldImage };

/** What a hover preview is being asked to show. */
export type ComposerPastePreview =
  | { kind: "text"; paste: HeldPaste }
  | { kind: "image"; image: HeldImage };

/**
 * Classes for the paste pills, MERGED onto the defaults rather than replacing them,
 * so a restyle can be one class or a whole new look.
 */
export interface ComposerPasteClassNames {
  /** Every pill, text or image. */
  pill?: string;
  /** Text pills only — `Pasted text · 669 characters`. */
  textPill?: string;
  /** Image pills only — `Pasted image 1`. */
  imagePill?: string;
  /** The hover popover. */
  preview?: string;
  /** The × discard control (beside-the-input placement only; inline pills are backspaced). */
  remove?: string;
  /** The editable surface itself. */
  input?: string;
}

/** The same shapes under the names they have outside `Composer`. */
export type PastePreview = ComposerPastePreview;
export type PasteClassNames = ComposerPasteClassNames;

import { useEffect, useRef } from "react";

export interface PastedFilesInputProps {
  /** The form field name the files are submitted under. */
  name: string;
  /** The files to submit, in the order the message holds them. */
  files: readonly File[];
  /** Associate with a `<form id>` elsewhere in the document, as `<input form>` does. */
  form?: string;
}

/**
 * A hidden `<input type="file">` carrying the files pasted into a field, so a
 * plain `<form>` submits them with everything else.
 *
 * A pasted file is not in any form field: the clipboard hands it to the paste
 * handler and nowhere else. Held as a pill, it is attached as far as the person can
 * see, and a native submit would then post the text without it. A file input is
 * the one element a form posts files from, and its `files` can be set from a
 * `DataTransfer`, so the pills keep it in step: delete a pill and its file leaves
 * the input too.
 *
 * Hidden rather than visually hidden: `hidden` keeps it out of the tab order and
 * the accessibility tree, where the pills already represent it, and does not stop
 * a form submitting it.
 */
export function PastedFilesInput({ name, files, form }: PastedFilesInputProps) {
  const ref = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const el = ref.current;
    // No DataTransfer (a server render, an old engine): nothing can be set, and
    // the host still has the files from its own state.
    if (!el || typeof DataTransfer === "undefined") return;

    const transfer = new DataTransfer();
    for (const file of files) transfer.items.add(file);
    el.files = transfer.files;
  }, [files]);

  return (
    <input
      ref={ref}
      type="file"
      name={name}
      form={form}
      multiple
      hidden
      tabIndex={-1}
      data-react-fancy-pasted-files={name}
    />
  );
}

/*
 * The paste-pill core, shared by `Composer`, `PromptInput` and `Input`.
 *
 * One folder rather than a hook in `hooks/` and the rest inside `Composer`, so
 * `npx fancy-cli add` copies it ONCE, as a dependency of whichever of those you
 * add, and the copies cannot drift: there is only one.
 */
export { usePastePills } from "./use-paste-pills";
export type {
  HeldPaste,
  PasteEventLike,
  UsePastePillsOptions,
  UsePastePillsResult,
} from "./use-paste-pills";
export { useInlinePaste } from "./use-inline-paste";
export type { UseInlinePasteOptions } from "./use-inline-paste";
export { InlinePasteEditor, HOST_ATTR } from "./InlinePasteEditor";
export type { InlinePasteEditorHandle, PillToInsert } from "./InlinePasteEditor";
export { InlinePill, endsOf, withSeparators } from "./InlinePill";
export { PastedFilesInput } from "./PastedFilesInput";
export type { PastedFilesInputProps } from "./PastedFilesInput";
export { PILL_MARK, pasteMarker, segmentValue, markedIds, expandMarkers } from "./paste-markers";
export type { HeldImage, ValueSegment } from "./paste-markers";
export type {
  ComposerPasteClassNames,
  ComposerPastePreview,
  PasteClassNames,
  PastePreview,
} from "./PastePills.types";

import type { HeldPaste } from "./use-paste-pills";

/**
 * An image pasted into a `Composer` and held as a pill.
 *
 * `label` is stored rather than derived because the number in it is the order of
 * ARRIVAL: "Pasted image 2" must stay 2 after image 1 is deleted, and nothing left
 * in the list could recompute that.
 */
export interface HeldImage {
  id: string;
  file: File;
  label: string;
}

/**
 * U+FFFC OBJECT REPLACEMENT CHARACTER — Unicode's own "an embedded object sits
 * here". A marker is the id wrapped in a pair of them.
 *
 * Why the message carries a marker at all: with inline placement the message
 * ITSELF is the record of what is attached and where, so there is one answer to
 * "what am I sending?" rather than a text plus a parallel list that can disagree
 * the moment someone backspaces a pill. This is the MOIC estate's design for their
 * own composer, and the reason they withdrew from the beside-the-input layout.
 *
 * Only a marker whose id the composer actually holds is a pill; anything else is
 * left as text, so a stray U+FFFC in pasted content cannot invent an attachment.
 */
export const PILL_MARK = "\uFFFC";

const MARKER = /\uFFFC([^\uFFFC\n]+)\uFFFC/g;

/** The marker for a held paste or image, for a host or agent writing `value` itself. */
export function pasteMarker(id: string): string {
  return `${PILL_MARK}${id}${PILL_MARK}`;
}

export type ValueSegment =
  | { type: "text"; text: string }
  | { type: "pill"; id: string };

/** Split a value into text and pills. Markers for ids not in `known` stay text. */
export function segmentValue(value: string, known: ReadonlySet<string>): ValueSegment[] {
  const out: ValueSegment[] = [];
  let last = 0;

  for (const match of value.matchAll(MARKER)) {
    const id = match[1];
    if (!known.has(id)) continue;

    const start = match.index ?? 0;
    if (start > last) out.push({ type: "text", text: value.slice(last, start) });
    out.push({ type: "pill", id });
    last = start + match[0].length;
  }

  if (last < value.length) out.push({ type: "text", text: value.slice(last) });

  return out;
}

/** The id of every marker the value contains, in order, held or not. */
export function markedIds(value: string): string[] {
  return Array.from(value.matchAll(MARKER), (m) => m[1]);
}

/**
 * What actually gets sent: every text pill replaced by its full text, every image
 * pill by `[Pasted image N]` so the reader of the message can see where the image
 * sat. The images themselves go to `onSubmit`'s second argument.
 */
export function expandMarkers(
  value: string,
  pastes: readonly HeldPaste[],
  images: readonly HeldImage[],
): string {
  const text = new Map(pastes.map((p) => [p.id, p.text]));
  const image = new Map(images.map((i) => [i.id, `[${i.label}]`]));

  return value.replace(MARKER, (whole, id: string) => text.get(id) ?? image.get(id) ?? whole);
}

import { useCallback, useMemo, useRef, useState, type ReactNode, type RefObject } from "react";
import { createPortal } from "react-dom";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { usePastePills, type HeldPaste } from "./use-paste-pills";
import { InlinePill } from "./InlinePill";
import type { InlinePasteEditorHandle, PillToInsert } from "./InlinePasteEditor";
import { expandMarkers, markedIds, type HeldImage } from "./paste-markers";
import type { ComposerPasteClassNames, ComposerPastePreview } from "./PastePills.types";

export interface UseInlinePasteOptions {
  pasteThreshold?: number;
  pasteImages?: boolean;
  previewChars: number;
  renderPastePreview?: (preview: ComposerPastePreview) => ReactNode;
  classNames?: ComposerPasteClassNames;
  disabled: boolean;
  heldPastes?: HeldPaste[];
  onHeldPastesChange?: (pastes: HeldPaste[]) => void;
  heldImages?: HeldImage[];
  onHeldImagesChange?: (images: HeldImage[]) => void;
  editorRef: RefObject<InlinePasteEditorHandle | null>;
  /**
   * Give a text pill a line to itself. Default `true`; a single-line field
   * (`Input`) has no lines to give, so its pills sit in the text.
   */
  blockText?: boolean;
}

/**
 * Everything inline paste pills need besides the editor itself: the held pastes
 * and images, deciding what a paste becomes, dropping a pill's hold when it is
 * deleted from the message, rendering the pills into the editor, and expanding
 * them on send.
 *
 * Shared by `Composer`, `PromptInput` and `Input` so they cannot disagree about
 * what a pill means. The rule that must not drift is the one `expand` and `imagesIn`
 * carry: a send with pills still closed carries everything they hold.
 */
export function useInlinePaste({
  pasteThreshold,
  pasteImages = false,
  previewChars,
  renderPastePreview,
  classNames,
  disabled,
  heldPastes: controlledHeldPastes,
  onHeldPastesChange,
  heldImages: controlledHeldImages,
  onHeldImagesChange,
  editorRef,
  blockText = true,
}: UseInlinePasteOptions) {
  const pills = usePastePills({
    threshold: pasteThreshold,
    heldPastes: controlledHeldPastes,
    onHeldPastesChange,
  });
  const heldPastes = pills.heldPastes;
  const [heldImages, setHeldImages] = useControllableState<HeldImage[]>(
    controlledHeldImages,
    [],
    onHeldImagesChange,
  );
  const imageCount = useRef(0);

  const known = useMemo(
    () => new Set([...heldPastes.map((p) => p.id), ...heldImages.map((i) => i.id)]),
    [heldPastes, heldImages],
  );

  const holdImage = useCallback(
    (file: File): string => {
      let id: string;
      do {
        imageCount.current += 1;
        id = `image-${imageCount.current}`;
      } while (heldImages.some((i) => i.id === id));

      const image = { id, file, label: `Pasted image ${imageCount.current}` };
      setHeldImages((current) => [...current, image]);

      return id;
    },
    [heldImages, setHeldImages],
  );

  /** What a paste becomes. `null` means "just text". */
  const decidePaste = useCallback(
    (data: DataTransfer | null): PillToInsert[] | null => {
      const text = data?.getData("text/plain") ?? "";

      // Only a PURE image paste: a clipboard with text as well usually carries a
      // picture OF that text (copying from a document), and holding it would turn
      // every pasted sentence into a screenshot of the sentence.
      if (pasteImages && text === "") {
        const files = Array.from(data?.files ?? []).filter((f) =>
          f.type.startsWith("image/"),
        );
        if (files.length > 0) {
          return files.map((file) => ({ id: holdImage(file), block: false }));
        }
      }

      if (pasteThreshold && pasteThreshold > 0 && text.length >= pasteThreshold) {
        return [{ id: pills.hold(text), block: blockText }];
      }

      return null;
    },
    [pasteImages, pasteThreshold, holdImage, pills, blockText],
  );

  /*
   * The message is the record of what is attached. A pill backspaced out of it is
   * no longer attached, so its held entry goes too — otherwise state would say
   * "attached" about something the message no longer contains.
   */
  const prune = useCallback(
    (next: string) => {
      const present = new Set(markedIds(next));
      for (const paste of heldPastes) if (!present.has(paste.id)) pills.remove(paste.id);
      if (heldImages.some((i) => !present.has(i.id))) {
        setHeldImages((current) => current.filter((i) => present.has(i.id)));
      }
    },
    [heldPastes, heldImages, pills, setHeldImages],
  );

  const [hosts, setHosts] = useState<ReadonlyMap<string, HTMLElement>>(new Map());
  const onHostsChange = useCallback((next: ReadonlyMap<string, HTMLElement>) => {
    setHosts((prev) => {
      if (prev.size === next.size && [...next].every(([id, el]) => prev.get(id) === el)) {
        return prev;
      }
      return next;
    });
  }, []);

  /** Click a text pill and its full text takes the pill's place. */
  const expandPill = useCallback(
    (id: string) => {
      const text = pills.expand(id);
      if (text === undefined) return;
      editorRef.current?.replacePill(id, text);
    },
    [pills, editorRef],
  );

  /** The value as it is sent: every text pill expanded, every image marked. */
  const expand = useCallback(
    (value: string) => expandMarkers(value, heldPastes, heldImages),
    [heldPastes, heldImages],
  );

  /** The images the value still contains, in message order. */
  const imagesIn = useCallback(
    (value: string) =>
      markedIds(value).flatMap((id) => heldImages.filter((i) => i.id === id)),
    [heldImages],
  );

  const clear = useCallback(() => {
    pills.clear();
    setHeldImages([]);
  }, [pills, setHeldImages]);

  /** The pills, portalled into the placeholders the editor made. Render this anywhere. */
  const portals = Array.from(hosts, ([id, host]) => {
    const paste = heldPastes.find((p) => p.id === id);
    const image = paste ? undefined : heldImages.find((i) => i.id === id);
    const preview: ComposerPastePreview | null = paste
      ? { kind: "text", paste }
      : image
        ? { kind: "image", image }
        : null;

    return preview
      ? createPortal(
          <InlinePill
            preview={preview}
            previewChars={previewChars}
            renderPastePreview={renderPastePreview}
            classNames={classNames}
            disabled={disabled}
            onExpand={expandPill}
          />,
          host,
          id,
        )
      : null;
  });

  return {
    pills,
    heldPastes,
    heldImages,
    known,
    decidePaste,
    prune,
    onHostsChange,
    expand,
    imagesIn,
    clear,
    portals,
  };
}

import { useCallback, useRef } from "react";
import { useControllableState } from "../lib/hooks/use-controllable-state";

/**
 * A paste held beside a composer rather than inserted into it.
 *
 * There is deliberately **no `length` field.** It would be `text.length` and
 * nothing else, and a derived value stored beside its source is a value that can
 * disagree with it — the two drift the moment anything edits one. Read
 * `paste.text.length`.
 */
export interface HeldPaste {
  id: string;
  text: string;
}

/**
 * The minimum of a clipboard event this hook touches.
 *
 * Structural rather than `React.ClipboardEvent` so a host can call it from a
 * native listener, a synthetic one, or a test double. React's own event satisfies
 * it.
 */
export interface PasteEventLike {
  clipboardData?: { getData(type: string): string } | null;
  preventDefault(): void;
}

export interface UsePastePillsOptions {
  /**
   * Hold a paste of at least this many characters. Try 500 — about a long
   * paragraph.
   *
   * **No default, on purpose.** Paste is a fundamental interaction, so holding one
   * is something a host asks for rather than something it discovers. Omit this and
   * `handlePaste` always returns `false` and touches nothing.
   */
  threshold?: number;
  /** Own the list yourself. Omit to let the hook keep it. */
  heldPastes?: HeldPaste[];
  onHeldPastesChange?: (pastes: HeldPaste[]) => void;
}

export interface UsePastePillsResult {
  heldPastes: HeldPaste[];
  /**
   * Call this from your OWN paste handler. Returns `true` if it took the paste —
   * in which case it has already called `preventDefault()` — and `false` if it
   * declined, having touched nothing.
   *
   * Composable on purpose: a host whose handler already intercepts paste for its
   * own reasons needs to ask "did you want this?" rather than hand over the event.
   *
   *     function onPaste(e) {
   *       if (pills.handlePaste(e)) return;
   *       // ...your own handling
   *     }
   */
  handlePaste: (event: PasteEventLike) => boolean;
  /**
   * Hold `text` unconditionally and return the new pill's id.
   *
   * For a host that decides for itself what to hold and needs to know WHICH pill
   * it made — `Composer`'s inline placement puts the pill at the caret, so it needs
   * the id at paste time. Ignores `threshold`; the caller has already decided.
   */
  hold: (text: string) => string;
  /**
   * Removes the paste and returns its text, for the host to insert into its own
   * surface. `undefined` if there is no such id.
   *
   * The hook cannot insert it — it owns no DOM and does not know what a host's
   * surface is. That is the point.
   */
  expand: (id: string) => string | undefined;
  /** Discard one without returning it. */
  remove: (id: string) => void;
  /** Empty the list, e.g. after a send. */
  clear: () => void;
}

/**
 * Hold a large paste as state, so a composer can show it as a pill instead of
 * turning itself into a scrolling wall.
 *
 * ---------------------------------------------------------------------------
 * Why this is a hook and not just a feature of `Composer`
 * ---------------------------------------------------------------------------
 *
 * `Composer` shipped the behaviour in 5.31.0 and the MOIC estate, who specified it,
 * then established something I had missed: their chat input is a contenteditable
 * rendering inline `[deal:42|Acme]` badges, so they **cannot** adopt `Composer` (a
 * plain textarea) however much they want its behaviour. Their plan to delete their
 * own composer when ours landed could never have worked.
 *
 * So the logic lives here and **`Composer` is its first caller.** One
 * implementation rather than two, which matters more than the convenience: two
 * copies of a rule drift, and the copy nobody reads is the one that rots. The rule
 * that must not drift is the one in `Composer`'s own tests — a send with pills
 * still closed carries the text.
 *
 * It owns no DOM. The host renders the pills.
 *
 * ---------------------------------------------------------------------------
 * Who actually calls this (as of 5.32.0): `Composer`, and nothing else
 * ---------------------------------------------------------------------------
 *
 * The estate that specified it **withdrew before adopting it**, hours after it
 * shipped — their design moved the pill INTO the message as a `[paste:id|label]`
 * marker in the same grammar as their other object tags, which makes the message
 * itself the record of what is attached. A parallel `heldPastes` array would then be
 * a second place answering "what am I sending?", and the two would disagree the
 * moment someone backspaced a badge. Their reasoning was better than the spec.
 *
 * Recorded because a reader should not infer an extension point under active
 * external use. It is kept rather than withdrawn for two reasons that are about
 * cost, not optimism: it is published API on a 5.x package, so removing it needs a
 * major; and `Composer` calls it, so it is exercised by that component's tests on
 * every run and cannot rot unnoticed.
 *
 * **It gets no further surface without a real caller.** No extra options, no second
 * hook. An API with one hypothetical consumer is how a package accumulates surface
 * nobody uses.
 *
 * `hold` (5.38.0) met that bar: `Composer`'s inline placement — MOIC's
 * pill-inside-the-message design, built into the component — needs the id of the
 * pill it just made so it can put it at the caret.
 */
export function usePastePills({
  threshold,
  heldPastes: controlledHeldPastes,
  onHeldPastesChange,
}: UsePastePillsOptions = {}): UsePastePillsResult {
  const [heldPastes, setHeldPastes] = useControllableState<HeldPaste[]>(
    controlledHeldPastes,
    [],
    onHeldPastesChange,
  );

  /*
   * A counter rather than `crypto.randomUUID()` or an index.
   *
   * An index is not an id — removing the first pill renumbers the rest, and a host
   * keying its DOM on that remounts every pill and loses hover state. A counter in
   * a ref is stable for the life of the component and needs no platform API that a
   * server renderer might lack.
   */
  const nextId = useRef(0);

  const hold = useCallback(
    (text: string): string => {
      /*
       * Skip any id the list already holds. A controlled list can arrive seeded
       * (restored drafts, an agent attaching a paste) before this counter has
       * counted anything, and minting `paste-1` beside an existing `paste-1` gives
       * two pills one id — expanding either then takes both.
       */
      let id: string;
      do {
        nextId.current += 1;
        id = `paste-${nextId.current}`;
      } while (heldPastes.some((p) => p.id === id));

      setHeldPastes((current) => [...current, { id, text }]);

      return id;
    },
    [heldPastes, setHeldPastes],
  );

  const handlePaste = useCallback(
    (event: PasteEventLike): boolean => {
      if (!threshold || threshold <= 0) return false;

      const text = event.clipboardData?.getData("text/plain") ?? "";

      // Below the threshold, decline WITHOUT touching the event. A host calling
      // this from inside its own handler has to be able to carry on as if the hook
      // were not there.
      if (text.length < threshold) return false;

      event.preventDefault();
      hold(text);

      return true;
    },
    [threshold, hold],
  );

  const expand = useCallback(
    (id: string): string | undefined => {
      const found = heldPastes.find((p) => p.id === id);

      if (found === undefined) return undefined;

      setHeldPastes((current) => current.filter((p) => p.id !== id));

      return found.text;
    },
    [heldPastes, setHeldPastes],
  );

  const remove = useCallback(
    (id: string) => setHeldPastes((current) => current.filter((p) => p.id !== id)),
    [setHeldPastes],
  );

  const clear = useCallback(() => setHeldPastes([]), [setHeldPastes]);

  return { heldPastes, handlePaste, hold, expand, remove, clear };
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import { useCallback, useEffect, useState, type RefObject } from "react";
import type { Placement } from "../utils/types";

interface FloatingPosition {
  x: number;
  y: number;
  placement: Placement;
}

interface UseFloatingPositionOptions {
  placement?: Placement;
  offset?: number;
  enabled?: boolean;
}

function getPosition(
  anchor: DOMRect,
  floating: DOMRect,
  placement: Placement,
  offset: number,
): FloatingPosition {
  let x = 0;
  let y = 0;
  const base = placement.split("-")[0] as "top" | "bottom" | "left" | "right";
  const align = placement.split("-")[1] as "start" | "end" | undefined;

  switch (base) {
    case "top":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.top - floating.height - offset;
      break;
    case "bottom":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.bottom + offset;
      break;
    case "left":
      x = anchor.left - floating.width - offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
    case "right":
      x = anchor.right + offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
  }

  if (base === "top" || base === "bottom") {
    if (align === "start") x = anchor.left;
    else if (align === "end") x = anchor.right - floating.width;
  }

  if (base === "left" || base === "right") {
    if (align === "start") y = anchor.top;
    else if (align === "end") y = anchor.bottom - floating.height;
  }

  // Viewport clamping
  let finalPlacement = placement;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  if (base === "bottom" && y + floating.height > vh) {
    y = anchor.top - floating.height - offset;
    finalPlacement = placement.replace("bottom", "top") as Placement;
  } else if (base === "top" && y < 0) {
    y = anchor.bottom + offset;
    finalPlacement = placement.replace("top", "bottom") as Placement;
  }

  x = Math.max(4, Math.min(x, vw - floating.width - 4));
  y = Math.max(4, Math.min(y, vh - floating.height - 4));

  return { x, y, placement: finalPlacement };
}

export function useFloatingPosition(
  anchorRef: RefObject<HTMLElement | null>,
  floatingRef: RefObject<HTMLElement | null>,
  options: UseFloatingPositionOptions = {},
): FloatingPosition {
  const { placement = "bottom", offset = 8, enabled = true } = options;
  const [position, setPosition] = useState<FloatingPosition>({
    x: -9999,
    y: -9999,
    placement,
  });

  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const floating = floatingRef.current;
    if (!anchor || !floating) return;

    const anchorRect = anchor.getBoundingClientRect();
    const floatingRect = floating.getBoundingClientRect();
    const next = getPosition(anchorRect, floatingRect, placement, offset);
    // Bail out when nothing changed so this can run after every commit
    // (below) without causing an infinite render loop.
    setPosition((prev) =>
      prev.x === next.x && prev.y === next.y && prev.placement === next.placement
        ? prev
        : next,
    );
  }, [anchorRef, floatingRef, placement, offset]);

  // Re-measure after every commit while open.
  //
  // The floating element mounts a frame or two AFTER `enabled` flips — its
  // render is gated behind a state flip (e.g. useAnimation's `mounted`), so at
  // the moment `enabled` turns true the floating ref is still null and a single
  // measurement no-ops, leaving the popover parked at its off-screen sentinel.
  //
  // A passive effect with no deps runs after *every* commit — including the one
  // that finally mounts the floating element — and, crucially, keeps running in
  // hidden/background tabs where `requestAnimationFrame` is paused. The bail-out
  // in `update` makes the steady-state calls free, so this both fixes the
  // late-mount race and survives tab-visibility throttling.
  useEffect(() => {
    if (enabled) update();
  });

  // …but the per-commit effect ISN'T enough when the floating element mounts
  // through a <Portal> whose own mount gate (SSR-safe; renders nothing until its
  // useEffect runs) attaches the node WITHOUT re-rendering this hook's component.
  // Then no commit happens here, the measurement never runs, and the popover
  // stays parked at its off-screen sentinel until an unrelated scroll/resize
  // fires `update()` — the "menu only appears after I scroll" bug. Poll with rAF
  // until the node is actually in the DOM, measure it, then keep it observed for
  // size changes (async content / lazily-loaded icons).
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    let ro: ResizeObserver | null = null;
    const tick = () => {
      const el = floatingRef.current;
      if (el) {
        update();
        if (typeof ResizeObserver !== "undefined") {
          ro = new ResizeObserver(() => update());
          ro.observe(el);
        }
      } else {
        raf = requestAnimationFrame(tick);
      }
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      ro?.disconnect();
    };
  }, [enabled, update, floatingRef]);

  // Park off-screen when closed so the next open re-measures from scratch.
  useEffect(() => {
    if (!enabled) {
      setPosition((prev) =>
        prev.x === -9999 ? prev : { x: -9999, y: -9999, placement },
      );
    }
  }, [enabled, placement]);

  // Reposition on scroll/resize while open.
  useEffect(() => {
    if (!enabled) return;

    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);

    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [update, enabled]);

  return position;
}

