import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { forwardRef, useCallback, useRef, useState } from "react";
import { X } from "lucide-react";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import type { PillboxProps } from "./Pillbox.types";

export const Pillbox = forwardRef<HTMLDivElement, PillboxProps>(
  function Pillbox(
    {
      value: controlledValue,
      defaultValue = [],
      onChange,
      placeholder = "Type and press Enter...",
      maxItems,
      disabled = false,
      className,
    },
    ref,
  ) {
    const [items, setItems] = useControllableState(
      controlledValue,
      defaultValue,
      onChange,
    );
    const [input, setInput] = useState("");
    const inputRef = useRef<HTMLInputElement>(null);

    const addItem = useCallback(
      (text: string) => {
        const trimmed = text.trim();
        if (!trimmed || items.includes(trimmed)) return;
        if (maxItems && items.length >= maxItems) return;
        setItems([...items, trimmed]);
        setInput("");
      },
      [items, setItems, maxItems],
    );

    const removeItem = useCallback(
      (index: number) => {
        setItems(items.filter((_, i) => i !== index));
      },
      [items, setItems],
    );

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === "Enter") {
        e.preventDefault();
        addItem(input);
      } else if (e.key === "Backspace" && !input && items.length > 0) {
        removeItem(items.length - 1);
      }
    };

    return (
      <div
        data-react-fancy-pillbox=""
        ref={ref}
        className={cn(
          "flex flex-wrap items-center gap-1.5 rounded-lg border border-zinc-200 bg-white px-3 py-2 transition-[border-color,box-shadow] duration-150 focus-within:border-blue-500 focus-within:ring-2 focus-within:ring-blue-500/40 dark:border-zinc-700 dark:bg-[#1e1e24] dark:text-zinc-100 dark:focus-within:border-blue-400 dark:focus-within:ring-blue-400/20",
          disabled && "cursor-not-allowed opacity-50",
          className,
        )}
        onClick={() => inputRef.current?.focus()}
      >
        {items.map((item, i) => (
          <span
            key={`${item}-${i}`}
            className="inline-flex items-center gap-1 rounded-md bg-zinc-100 px-2 py-0.5 text-sm dark:bg-zinc-800"
          >
            {item}
            {!disabled && (
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  removeItem(i);
                }}
                className="text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-300"
                aria-label={`Remove ${item}`}
              >
                <X size={12} />
              </button>
            )}
          </span>
        ))}
        <input
          ref={inputRef}
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={items.length === 0 ? placeholder : ""}
          disabled={disabled}
          className="min-w-[80px] flex-1 bg-transparent text-sm outline-none placeholder:text-zinc-400"
        />
      </div>
    );
  },
);

Pillbox.displayName = "Pillbox";

export interface PillboxProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (values: string[]) => void;
  placeholder?: string;
  maxItems?: number;
  disabled?: boolean;
  className?: string;
}

