import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import { Badge, Button, Heading, Text, type Color } from '@particle-academy/react-fancy';
import { useState } from 'react';
import type { ChangeAction, ChangePlan } from '../lib/types';

const ACTION_COLOR: Record<ChangeAction, Color> = {
    create: 'green',
    update: 'blue',
    delete: 'red',
};

export interface PlanReviewProps {
    plan?: ChangePlan | null;
    onApply: () => void;
    onDiscard: () => void;
    busy?: boolean;
    /** Shown in the footer. Set to null to drop the note entirely. */
    draftNote?: React.ReactNode;
    /** react-fancy Button colour for the apply action. */
    color?: Color;
}

/** Scalar values short enough to read inline, which is where they belong. */
function inlineFields(attributes: Record<string, unknown>): [string, string][] {
    return Object.entries(attributes)
        .filter(([, v]) => v !== null && typeof v !== 'object')
        .map(([k, v]) => [k, String(v)] as [string, string])
        .filter(([, v]) => v.length <= 60);
}

/**
 * The approval surface — the only place a proposal becomes rows.
 *
 * Every operation is inspectable before anything is written, raw attributes
 * included. A reviewer who cannot see what they are approving is not really
 * approving it, and "Apply" on an opaque list is just a slower yes.
 *
 * ---------------------------------------------------------------------------
 * That paragraph was true of the intent and false of the behaviour
 * ---------------------------------------------------------------------------
 *
 * Attributes WERE all rendered — behind a click, one operation at a time, with
 * the Apply button available from the start. So a reviewer saw
 * "Radio Discipline Check — a quiz on callsigns · 5 fields" and could approve it
 * without ever seeing `passing_score: 0`, which is the single attribute deciding
 * whether that certification exam means anything.
 *
 * It mattered because these proposals come from a model, and Teachers Aid extracts
 * uploaded course material into the turn. `passing_score` is a legitimate,
 * model-controlled field: nothing is bypassed when an injected instruction proposes
 * zero. The tool is working as designed and **the review IS the control.** A
 * control that requires a click nobody is prompted to make is not one.
 *
 * So scalar attributes now render inline on every row, always. Expansion is for
 * long text and nested objects only, and several rows can be open at once —
 * reviewing a twelve-operation plan through a one-at-a-time accordion is twelve
 * clicks and no way to compare two rows, which is its own pressure to skip.
 *
 * Raised by a consumer who went looking for a mass-assignment hole in the PHP
 * side, did not find one, and asked the better question: what can an admin
 * actually see at the moment they commit?
 */
export function PlanReview({ plan, onApply, onDiscard, busy, draftNote, color = 'red' }: PlanReviewProps) {
    const [expanded, setExpanded] = useState<ReadonlySet<number>>(new Set());

    if (!plan || !plan.operations?.length) return null;

    const summary = Object.entries(plan.summary ?? {})
        .map(([key, count]) => `${count} × ${key.replace('_', ' ')}`)
        .join(' · ');

    return (
        <section className="rounded-lg border border-amber-300 bg-amber-50/60 overflow-hidden">
            <header className="flex flex-wrap items-center justify-between gap-3 border-b border-amber-200 bg-amber-100/60 px-4 py-3">
                <div>
                    <Heading as="h2" size="sm" weight="semibold" className="!text-sm">
                        Proposed changes — nothing has been saved yet
                    </Heading>
                    {summary && <Text className="!text-xs !text-secondary-600 !mt-0.5">{summary}</Text>}
                </div>
                <div className="flex gap-2">
                    <Button
                        onClick={onDiscard}
                        disabled={busy}
                        className="!border !border-secondary-300 !bg-white dark:!bg-zinc-900 !text-secondary-700 !text-sm !px-3 !py-1.5 !rounded-md"
                    >
                        Discard
                    </Button>
                    <Button
                        onClick={onApply}
                        // See MessageComposer: colour is a prop, never a forced
                        // `!bg-brand` class the host may not define.
                        color={color}
                        loading={busy}
                        disabled={busy}
                        className="!font-semibold !text-sm"
                    >
                        Apply {plan.count} change{plan.count === 1 ? '' : 's'}
                    </Button>
                </div>
            </header>

            <ol className="divide-y divide-amber-200">
                {plan.operations.map((op, i) => {
                    const open = expanded.has(i);
                    const attributes = Object.entries(op.attributes ?? {});
                    const inline = inlineFields(op.attributes ?? {});
                    const rest = attributes.length - inline.length;

                    return (
                        <li key={i} className="px-4 py-3">
                            <button
                                type="button"
                                onClick={() =>
                                    setExpanded((prev) => {
                                        const next = new Set(prev);
                                        if (!next.delete(i)) next.add(i);
                                        return next;
                                    })
                                }
                                className="flex w-full items-start gap-3 text-left"
                                aria-expanded={open}
                            >
                                <Badge color={ACTION_COLOR[op.action] ?? 'gray'} variant="soft" size="sm">
                                    {op.action}
                                </Badge>
                                <span className="flex-1">
                                    <Text className="!text-sm !font-medium">{op.description}</Text>

                                    {/*
                                     * Inline, always, and NOT behind the toggle. This is the
                                     * difference between a review and a slower yes -- see the
                                     * component docblock for the `passing_score: 0` case.
                                     */}
                                    {inline.length > 0 && (
                                        <span
                                            className="mt-1 flex flex-wrap gap-x-3 gap-y-1"
                                            data-plan-op-fields={i}
                                        >
                                            {inline.map(([key, value]) => (
                                                <span key={key} className="text-xs text-secondary-600">
                                                    <span className="font-medium uppercase tracking-wide text-secondary-500">
                                                        {key}
                                                    </span>{' '}
                                                    <span className="text-secondary-800">{value}</span>
                                                </span>
                                            ))}
                                        </span>
                                    )}

                                    {op.ref && (
                                        <Text className="!text-xs !text-secondary-500 !mt-0.5">
                                            referenced later as ${op.ref}
                                        </Text>
                                    )}
                                </span>
                                <span className="text-xs text-secondary-500 shrink-0">
                                    {open
                                        ? 'Hide'
                                        : rest > 0
                                          ? `${rest} more field${rest === 1 ? '' : 's'}`
                                          : 'Details'}
                                </span>
                            </button>

                            {open && (
                                <dl className="mt-3 grid gap-2 rounded-md bg-white/70 dark:bg-zinc-900/70 p-3 text-sm">
                                    {attributes.map(([key, value]) => (
                                        <div key={key} className="grid sm:grid-cols-[10rem_1fr] gap-1 sm:gap-3">
                                            <dt className="text-xs font-medium uppercase tracking-wide text-secondary-500">
                                                {key}
                                            </dt>
                                            <dd className="whitespace-pre-wrap break-words text-secondary-800">
                                                {value !== null && typeof value === 'object'
                                                    ? JSON.stringify(value, null, 2)
                                                    : String(value)}
                                            </dd>
                                        </div>
                                    ))}
                                </dl>
                            )}
                        </li>
                    );
                })}
            </ol>

            {draftNote !== null && (
                <footer className="border-t border-amber-200 px-4 py-2">
                    <Text className="!text-xs !text-secondary-600">
                        {draftNote ?? (
                            <>
                                Applied changes are saved as <strong>drafts</strong>. Publishing stays a
                                separate, deliberate step.
                            </>
                        )}
                    </Text>
                </footer>
            )}
        </section>
    );
}

/**
 * The shapes this UX renders. They mirror what particle-academy/teachers-aid
 * serialises, but nothing here imports it — the package is a view over plain
 * JSON, so a host on any backend can feed it.
 */

export type ChangeAction = 'create' | 'update' | 'delete';

/** One proposed change. Inert until a human applies the plan it belongs to. */
export interface ChangeOperation {
    action: ChangeAction;
    entity: string;
    /** Human-readable one-liner for the review list. */
    description: string;
    attributes?: Record<string, unknown>;
    /** Present on updates and deletes. */
    id?: number;
    /**
     * Name this operation's new record is referred to by later in the same
     * plan, e.g. a lesson pointing at `$c1` before the course has an id.
     */
    ref?: string;
}

export interface ChangePlan {
    operations: ChangeOperation[];
    /** Counts keyed by "action entity", e.g. `{"create lesson": 3}`. */
    summary?: Record<string, number>;
    count: number;
}

export interface ChatEntry {
    role: 'user' | 'assistant';
    /**
     * What to show. Distinct from what the model was sent, which has extracted
     * file text folded into it — rendering that would paste a whole handbook
     * back at the teacher.
     */
    display?: string;
    content?: string;
    /** Names of files attached to this turn. */
    files?: string[];
}

import { createContext, useContext } from "react";
import type { PopoverContextValue } from "./Popover.types";

export const PopoverContext = createContext<PopoverContextValue | null>(null);

export function usePopover(): PopoverContextValue {
  const ctx = useContext(PopoverContext);
  if (!ctx) {
    throw new Error("Popover compound components must be used within <Popover>");
  }
  return ctx;
}

import { useCallback, useMemo, useRef, useState } from "react";
import { PopoverContext } from "./Popover.context";
import { PopoverTrigger } from "./PopoverTrigger";
import { PopoverContent } from "./PopoverContent";
import type { PopoverProps } from "./Popover.types";

function PopoverRoot({
  children,
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  placement = "bottom",
  offset = 8,
  hover = false,
  hoverDelay = 200,
  hoverCloseDelay = 300,
}: PopoverProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : internalOpen;

  const anchorRef = useRef<HTMLElement>(null);
  const floatingRef = useRef<HTMLDivElement>(null);
  const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);

  const setOpen = useCallback(
    (next: boolean) => {
      if (!isControlled) setInternalOpen(next);
      onOpenChange?.(next);
    },
    [isControlled, onOpenChange],
  );

  const onHoverEnter = useCallback(() => {
    if (!hover) return;
    clearTimeout(hoverTimeoutRef.current);
    hoverTimeoutRef.current = setTimeout(() => setOpen(true), hoverDelay);
  }, [hover, hoverDelay, setOpen]);

  const onHoverLeave = useCallback(() => {
    if (!hover) return;
    clearTimeout(hoverTimeoutRef.current);
    hoverTimeoutRef.current = setTimeout(() => setOpen(false), hoverCloseDelay);
  }, [hover, hoverCloseDelay, setOpen]);

  const ctx = useMemo(
    () => ({ open, setOpen, anchorRef, floatingRef, placement, offset, hover, onHoverEnter, onHoverLeave }),
    [open, setOpen, placement, offset, hover, onHoverEnter, onHoverLeave],
  );

  return (
    <PopoverContext.Provider value={ctx}>{children}</PopoverContext.Provider>
  );
}

export const Popover = Object.assign(PopoverRoot, {
  Trigger: PopoverTrigger,
  Content: PopoverContent,
});

import type { HTMLAttributes, ReactNode } from "react";
import type { Placement } from "../lib/utils/types";

export interface PopoverContextValue {
  open: boolean;
  setOpen: (open: boolean) => void;
  anchorRef: React.RefObject<HTMLElement | null>;
  floatingRef: React.RefObject<HTMLDivElement | null>;
  placement: Placement;
  offset: number;
  hover: boolean;
  onHoverEnter: () => void;
  onHoverLeave: () => void;
}

export interface PopoverProps {
  children: ReactNode;
  /** Controlled open state */
  open?: boolean;
  /** Default open state (uncontrolled) */
  defaultOpen?: boolean;
  /** Callback when open state changes */
  onOpenChange?: (open: boolean) => void;
  /** Placement of the popover relative to the trigger */
  placement?: Placement;
  /** Pixel offset from the trigger */
  offset?: number;
  /** Open on hover instead of click */
  hover?: boolean;
  /** Delay in ms before opening on hover. Default: 200 */
  hoverDelay?: number;
  /** Delay in ms before closing after hover leaves. Default: 300 */
  hoverCloseDelay?: number;
}

/**
 * The trigger renders a `<span>` — it extends its attributes so consumers can
 * forward `aria-*`, `data-*`, `id`, `title`, etc. onto the actual anchor node
 * (e.g. `aria-label` for an icon-only trigger). Popover-owned props (ref,
 * onClick, aria-expanded/haspopup) always win over forwarded ones.
 */
export interface PopoverTriggerProps extends HTMLAttributes<HTMLSpanElement> {
  children: ReactNode;
}

/**
 * The content renders a `<div>` — it extends its attributes so consumers can
 * forward `aria-*`/`data-*`/`role`/`id` onto the floating panel. Consumer
 * `style` is merged under the Popover's positioning (left/top always win).
 */
export interface PopoverContentProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
}

import { useCallback, useRef } from "react";
import { cn } from "../lib/utils/cn";
import { Portal } from "../portal";
import { usePopover } from "./Popover.context";
import { useFloatingPosition } from "../lib/hooks/use-floating-position";
import { useOutsideClick } from "../lib/hooks/use-outside-click";
import { useEscapeKey } from "../lib/hooks/use-escape-key";
import type { PopoverContentProps } from "./Popover.types";

export function PopoverContent({ children, className, style, ...rest }: PopoverContentProps) {
  const { open, setOpen, anchorRef, floatingRef, placement, offset, hover, onHoverEnter, onHoverLeave } = usePopover();
  const outsideRef = useRef<HTMLDivElement>(null);

  const position = useFloatingPosition(anchorRef, floatingRef, {
    placement,
    offset,
    enabled: open,
  });

  const close = useCallback(() => setOpen(false), [setOpen]);
  useOutsideClick(outsideRef, close, open && !hover, anchorRef);
  useEscapeKey(close, open);

  // Hide until position is calculated to prevent flash at (-9999, -9999)
  const positioned = position.x !== -9999 && position.y !== -9999;

  if (!open) return null;

  return (
    <Portal>
      <div
        {...rest}
        ref={(node) => {
          outsideRef.current = node;
          (floatingRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        data-react-fancy-popover=""
        className={cn(
          "fixed z-50 rounded-xl border border-zinc-200 bg-white p-4 text-zinc-700 shadow-lg dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-200 dark:shadow-zinc-950/50",
          positioned ? "fancy-scale-in" : "invisible",
          className,
        )}
        style={{ ...style, left: position.x, top: position.y }}
        onMouseEnter={hover ? onHoverEnter : undefined}
        onMouseLeave={hover ? onHoverLeave : undefined}
      >
        {children}
      </div>
    </Portal>
  );
}

PopoverContent.displayName = "PopoverContent";

import { cn } from "../lib/utils/cn";
import { usePopover } from "./Popover.context";
import type { PopoverTriggerProps } from "./Popover.types";

export function PopoverTrigger({ children, className, ...rest }: PopoverTriggerProps) {
  const { setOpen, open, anchorRef, hover, onHoverEnter, onHoverLeave } = usePopover();

  return (
    <span
      {...rest}
      ref={anchorRef as React.RefObject<HTMLSpanElement>}
      data-react-fancy-popover-trigger=""
      className={cn("inline-flex", className)}
      onClick={hover ? undefined : () => setOpen(!open)}
      onMouseEnter={hover ? onHoverEnter : undefined}
      onMouseLeave={hover ? onHoverLeave : undefined}
      aria-expanded={open}
      aria-haspopup
    >
      {children}
    </span>
  );
}

PopoverTrigger.displayName = "PopoverTrigger";

