import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

/**
 * Which modifier key the user actually has.
 *
 * This exists because a keyboard hint is a CLAIM about the reader's hardware.
 * `⌘ + Enter to send` on Windows or Linux names a key that is not on the
 * keyboard, and a reader who cannot act on a hint learns to ignore hints — so
 * the cost is not one wrong glyph, it is the credibility of every hint beside
 * it. (Reported from a real Electron app running on Linux, where the glyph had
 * no font behind it either and rendered as tofu.)
 *
 * Two deliberate choices:
 *
 * 1. **The platform is an ARGUMENT, never a global read.** `detectPlatform`
 *    takes the hints; `modifierKeyLabel` takes the verdict. Both branches are
 *    therefore reachable from one machine, which is the only way a test can
 *    cover the platform you are not sitting at. A function that reads
 *    `navigator` internally can only ever be tested on the developer's own OS.
 * 2. **`generic` is the fallback, and that is not arbitrary.** Every Fancy
 *    surface that submits on a modifier accepts `metaKey || ctrlKey`, so
 *    `Ctrl` is a TRUE label on an Apple keyboard while `⌘` is a FALSE one
 *    everywhere else. The honest default is the one that is pressable on all
 *    of them.
 */
export type FancyPlatform = "apple" | "generic";

/**
 * The parts of `navigator` the detection reads — nothing more, so a caller can
 * hand it a literal (a test, an Electron main process forwarding `process.platform`,
 * a server with a stored preference).
 */
export interface PlatformHints {
  /** `navigator.userAgentData` — the modern, non-spoofed answer where it exists. */
  userAgentData?: { platform?: string } | null;
  /** `navigator.platform` — deprecated, still the most reliable legacy signal. */
  platform?: string | null;
  /** `navigator.userAgent` — last resort. */
  userAgent?: string | null;
}

/**
 * `userAgentData.platform` is a short enumerated token ("macOS", "Windows",
 * "Linux", "Android", "iOS"), so it is matched exactly rather than by substring.
 */
const APPLE_UA_DATA_PLATFORMS = new Set(["macos", "ios", "ipados"]);

/**
 * Legacy `platform` / `userAgent` are free text. iPadOS reports `MacIntel`, and
 * iOS user agents say "like Mac OS X" — both are Apple, so a Mac match is
 * correct for them too.
 */
const APPLE_FREE_TEXT = /\b(mac|macintosh|iphone|ipad|ipod|darwin)/i;

/** Resolve a platform from navigator-shaped hints. Unknown or absent ⇒ `generic`. */
export function detectPlatform(hints?: PlatformHints | null): FancyPlatform {
  if (!hints) return "generic";

  const uaData = hints.userAgentData?.platform;
  if (typeof uaData === "string" && uaData.length > 0) {
    // When the browser gives an enumerated answer, TRUST IT and stop. Falling
    // through to the free-text test would let a Windows UA string containing
    // the word "Mac" (a font name, a device model) overturn it.
    return APPLE_UA_DATA_PLATFORMS.has(uaData.trim().toLowerCase()) ? "apple" : "generic";
  }

  for (const value of [hints.platform, hints.userAgent]) {
    if (typeof value === "string" && APPLE_FREE_TEXT.test(value)) return "apple";
  }

  return "generic";
}

/**
 * The modifier key to NAME for a platform.
 *
 * `⌘` is emitted for `apple` and nothing else. A test enumerates the platform
 * values and counts that no other one can produce it, because a hint that names
 * the wrong key is worse than no hint.
 */
export function modifierKeyLabel(platform: FancyPlatform): "⌘" | "Ctrl" {
  return platform === "apple" ? "⌘" : "Ctrl";
}

/** SSR-safe read of the live browser hints. `null` off a browser. */
export function browserPlatformHints(): PlatformHints | null {
  if (typeof navigator === "undefined") return null;
  return navigator as PlatformHints;
}

/**
 * HTML and URL sanitization utilities.
 *
 * Hand-rolled (no third-party deps) using browser-native `DOMParser`. Designed
 * for the trust model "consumer passes user-generated markdown/HTML to a
 * react-fancy component" — strips script tags, event handlers, and dangerous
 * URI schemes from `href`/`src` attributes.
 *
 * For server-side rendering (no `window`), `sanitizeHtml` returns the input
 * unchanged. Consumers SSR-rendering untrusted content should sanitize on the
 * server with their own pipeline.
 */

const DANGEROUS_TAGS = new Set([
  "script",
  "style",
  "iframe",
  "object",
  "embed",
  "link",
  "meta",
  "base",
  "form",
]);

const URL_ATTRS = new Set(["href", "src", "action", "formaction", "xlink:href"]);

const SAFE_PROTOCOL = /^(?:https?:|mailto:|tel:|sms:|ftp:|#|\/|\.\/|\.\.\/|[^:]*$)/i;

/**
 * Validate a URL/href against an allow-list of safe protocols. Returns the
 * input if safe, or `undefined` if it begins with a dangerous scheme like
 * `javascript:`, `data:`, or `vbscript:`. Relative URLs and fragment links
 * are allowed.
 */
export function sanitizeHref(href: string | undefined | null): string | undefined {
  if (href == null) return undefined;
  const trimmed = href.trim();
  if (!trimmed) return undefined;
  return SAFE_PROTOCOL.test(trimmed) ? trimmed : undefined;
}

function stripDangerousAttrs(el: Element): void {
  // Collect names first; mutating during iteration is awkward with NamedNodeMap.
  const names: string[] = [];
  for (let i = 0; i < el.attributes.length; i++) {
    names.push(el.attributes[i].name);
  }

  for (const name of names) {
    const lower = name.toLowerCase();

    // All on* event handlers
    if (lower.startsWith("on")) {
      el.removeAttribute(name);
      continue;
    }

    // URL attributes — protocol-filter
    if (URL_ATTRS.has(lower)) {
      const sanitized = sanitizeHref(el.getAttribute(name));
      if (sanitized === undefined) {
        el.removeAttribute(name);
      } else {
        el.setAttribute(name, sanitized);
      }
      continue;
    }

    // srcdoc executes JS in the iframe — drop wholesale
    if (lower === "srcdoc") {
      el.removeAttribute(name);
    }
  }
}

function walk(el: Element, removeQueue: Element[]): void {
  const tag = el.tagName.toLowerCase();

  if (DANGEROUS_TAGS.has(tag)) {
    removeQueue.push(el);
    return;
  }

  stripDangerousAttrs(el);

  const children = Array.from(el.children);
  for (const child of children) {
    walk(child, removeQueue);
  }
}

/**
 * Sanitize an HTML string by removing dangerous tags (script, iframe, etc.),
 * event-handler attributes (`onclick`, `onerror`, ...), and dangerous URI
 * schemes in `href`/`src` attributes.
 *
 * Uses the browser's `DOMParser`. In non-browser environments returns the
 * input unchanged — sanitize on the server in those cases.
 */
export function sanitizeHtml(html: string): string {
  if (typeof window === "undefined" || typeof DOMParser === "undefined") {
    return html;
  }

  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");
  const body = doc.body;
  if (!body) return html;

  const removeQueue: Element[] = [];
  for (const child of Array.from(body.children)) {
    walk(child, removeQueue);
  }

  for (const el of removeQueue) {
    el.parentNode?.removeChild(el);
  }

  return body.innerHTML;
}

import { EMOJI_DATA, EMOJI_ENTRIES, type EmojiCategoryKey, type EmojiEntry } from "./emoji-data";

export const SKIN_TONES = ["light", "medium-light", "medium", "medium-dark", "dark"] as const;
export type SkinTone = typeof SKIN_TONES[number];

type IndexedEntry = EmojiEntry & { category: EmojiCategoryKey };

let byName: Map<string, IndexedEntry> | null = null;
let byChar: Map<string, IndexedEntry> | null = null;

function ensureIndexes() {
  if (byName && byChar) return;
  byName = new Map();
  byChar = new Map();
  for (const [category, group] of Object.entries(EMOJI_DATA) as [EmojiCategoryKey, typeof EMOJI_DATA[EmojiCategoryKey]][]) {
    for (const emoji of group.emojis) {
      const entry: IndexedEntry = { ...emoji, category };
      byName.set(emoji.name.toLowerCase(), entry);
      byChar.set(emoji.char, entry);
      if (emoji.skinTones) {
        for (const toned of emoji.skinTones) {
          byChar.set(toned, entry);
        }
      }
    }
  }
}

/** Resolve an emoji name to its character. */
export function resolve(name: string): string | undefined {
  ensureIndexes();
  return byName!.get(name.toLowerCase())?.char;
}

/** Search emojis by name substring. Returns matching base emoji characters. */
export function search(query: string): string[] {
  const lower = query.toLowerCase();
  return EMOJI_ENTRIES.filter((e) => e.name.includes(lower)).map((e) => e.char);
}

/** Find an emoji entry by its character (toned or base). */
export function find(char: string): IndexedEntry | undefined {
  ensureIndexes();
  return byChar!.get(char);
}

/** Return the 5-tone variant array for an emoji (by char, toned or base). */
export function skinTones(char: string): readonly [string, string, string, string, string] | undefined {
  return find(char)?.skinTones;
}

/** Whether an emoji supports skin tones. */
export function hasSkinTones(char: string): boolean {
  return !!find(char)?.skinTones;
}

/** Return the toned variant for an emoji, or the base if no tones. */
export function applyTone(char: string, tone: SkinTone | null): string {
  if (!tone) return char;
  const entry = find(char);
  if (!entry?.skinTones) return char;
  const idx = SKIN_TONES.indexOf(tone);
  return entry.skinTones[idx] ?? char;
}

import { useCallback, useEffect, useState, type RefObject } from "react";
import type { Placement } from "../utils/types";

interface FloatingPosition {
  x: number;
  y: number;
  placement: Placement;
}

interface UseFloatingPositionOptions {
  placement?: Placement;
  offset?: number;
  enabled?: boolean;
}

function getPosition(
  anchor: DOMRect,
  floating: DOMRect,
  placement: Placement,
  offset: number,
): FloatingPosition {
  let x = 0;
  let y = 0;
  const base = placement.split("-")[0] as "top" | "bottom" | "left" | "right";
  const align = placement.split("-")[1] as "start" | "end" | undefined;

  switch (base) {
    case "top":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.top - floating.height - offset;
      break;
    case "bottom":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.bottom + offset;
      break;
    case "left":
      x = anchor.left - floating.width - offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
    case "right":
      x = anchor.right + offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
  }

  if (base === "top" || base === "bottom") {
    if (align === "start") x = anchor.left;
    else if (align === "end") x = anchor.right - floating.width;
  }

  if (base === "left" || base === "right") {
    if (align === "start") y = anchor.top;
    else if (align === "end") y = anchor.bottom - floating.height;
  }

  // Viewport clamping
  let finalPlacement = placement;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  if (base === "bottom" && y + floating.height > vh) {
    y = anchor.top - floating.height - offset;
    finalPlacement = placement.replace("bottom", "top") as Placement;
  } else if (base === "top" && y < 0) {
    y = anchor.bottom + offset;
    finalPlacement = placement.replace("top", "bottom") as Placement;
  }

  x = Math.max(4, Math.min(x, vw - floating.width - 4));
  y = Math.max(4, Math.min(y, vh - floating.height - 4));

  return { x, y, placement: finalPlacement };
}

export function useFloatingPosition(
  anchorRef: RefObject<HTMLElement | null>,
  floatingRef: RefObject<HTMLElement | null>,
  options: UseFloatingPositionOptions = {},
): FloatingPosition {
  const { placement = "bottom", offset = 8, enabled = true } = options;
  const [position, setPosition] = useState<FloatingPosition>({
    x: -9999,
    y: -9999,
    placement,
  });

  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const floating = floatingRef.current;
    if (!anchor || !floating) return;

    const anchorRect = anchor.getBoundingClientRect();
    const floatingRect = floating.getBoundingClientRect();
    const next = getPosition(anchorRect, floatingRect, placement, offset);
    // Bail out when nothing changed so this can run after every commit
    // (below) without causing an infinite render loop.
    setPosition((prev) =>
      prev.x === next.x && prev.y === next.y && prev.placement === next.placement
        ? prev
        : next,
    );
  }, [anchorRef, floatingRef, placement, offset]);

  // Re-measure after every commit while open.
  //
  // The floating element mounts a frame or two AFTER `enabled` flips — its
  // render is gated behind a state flip (e.g. useAnimation's `mounted`), so at
  // the moment `enabled` turns true the floating ref is still null and a single
  // measurement no-ops, leaving the popover parked at its off-screen sentinel.
  //
  // A passive effect with no deps runs after *every* commit — including the one
  // that finally mounts the floating element — and, crucially, keeps running in
  // hidden/background tabs where `requestAnimationFrame` is paused. The bail-out
  // in `update` makes the steady-state calls free, so this both fixes the
  // late-mount race and survives tab-visibility throttling.
  useEffect(() => {
    if (enabled) update();
  });

  // …but the per-commit effect ISN'T enough when the floating element mounts
  // through a <Portal> whose own mount gate (SSR-safe; renders nothing until its
  // useEffect runs) attaches the node WITHOUT re-rendering this hook's component.
  // Then no commit happens here, the measurement never runs, and the popover
  // stays parked at its off-screen sentinel until an unrelated scroll/resize
  // fires `update()` — the "menu only appears after I scroll" bug. Poll with rAF
  // until the node is actually in the DOM, measure it, then keep it observed for
  // size changes (async content / lazily-loaded icons).
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    let ro: ResizeObserver | null = null;
    const tick = () => {
      const el = floatingRef.current;
      if (el) {
        update();
        if (typeof ResizeObserver !== "undefined") {
          ro = new ResizeObserver(() => update());
          ro.observe(el);
        }
      } else {
        raf = requestAnimationFrame(tick);
      }
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      ro?.disconnect();
    };
  }, [enabled, update, floatingRef]);

  // Park off-screen when closed so the next open re-measures from scratch.
  useEffect(() => {
    if (!enabled) {
      setPosition((prev) =>
        prev.x === -9999 ? prev : { x: -9999, y: -9999, placement },
      );
    }
  }, [enabled, placement]);

  // Reposition on scroll/resize while open.
  useEffect(() => {
    if (!enabled) return;

    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);

    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [update, enabled]);

  return position;
}

import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

