export const MIN_VERSION = 1;
export const MAX_VERSION = 40;

/** Block structure for a version and error correction level. */
export function blockLayout(version: number, ec: QrErrorCorrection): BlockLayout {
  const row = BLOCK_TABLE[version - 1]?.[EC_LEVELS.indexOf(ec)];
  if (!row) {
    throw new RangeError(`No block layout for version ${version} level ${ec}`);
  }
  const [dataCodewords, ecPerBlock, g1Blocks, g1Size, g2Blocks, g2Size] = row;
  return { dataCodewords, ecPerBlock, g1Blocks, g1Size, g2Blocks, g2Size };
}

/**
 * The 15-bit format information for a level and mask, as published.
 *
 * These are a BCH(15,5) code XOR'd with a fixed mask, so they could be
 * computed — and the first draft did compute them. They are listed instead
 * because the computation and its verification would then share one
 * implementation: a wrong generator polynomial would produce a wrong table and
 * a test that agreed with it. A transcribed table cannot agree with a bug.
 *
 * Source: <https://www.thonky.com/qr-code-tutorial/format-version-tables>.
 * Indexed `[level][mask]`.
 */
export const FORMAT_BITS: Record<QrErrorCorrection, readonly number[]> = {
  L: [
    0b111011111000100, 0b111001011110011, 0b111110110101010, 0b111100010011101,
    0b110011000101111, 0b110001100011000, 0b110110001000001, 0b110100101110110,
  ],
  M: [
    0b101010000010010, 0b101000100100101, 0b101111001111100, 0b101101101001011,
    0b100010111111001, 0b100000011001110, 0b100111110010111, 0b100101010100000,
  ],
  Q: [
    0b011010101011111, 0b011000001101000, 0b011111100110001, 0b011101000000110,
    0b010010010110100, 0b010000110000011, 0b010111011011010, 0b010101111101101,
  ],
  H: [
    0b001011010001001, 0b001001110111110, 0b001110011100111, 0b001100111010000,
    0b000011101100010, 0b000001001010101, 0b000110100001100, 0b000100000111011,
  ],
};

/**
 * The 18-bit version information, present only for versions 7 and up.
 *
 * A BCH(18,6) code. Computed rather than tabled — 34 rows of 18 bits is more
 * transcription risk than the arithmetic is, and unlike the format bits there
 * are published values for versions 7, 8, 9, 10 and 40 to check it against,
 * which the test does.
 */
export function versionBits(version: number): number {
  let remainder = version;
  for (let i = 0; i < 12; i += 1) {
    remainder = (remainder << 1) ^ ((remainder >>> 11) * 0b1111100100101);
  }
  return ((version << 12) | remainder) >>> 0;
}

/**
 * Centre coordinates of the alignment patterns for a version.
 *
 * Derived rather than tabled, and the derivation is checked by the codeword
 * count equation in the test: a wrong position changes how many modules are
 * free for data, so the count would not match the block table.
 *
 * Version 32 is a genuine special case in the standard — its spacing does not
 * follow the rule the other versions do.
 */
export function alignmentPositions(version: number): number[] {
  if (version === 1) {
    return [];
  }
  const count = Math.floor(version / 7) + 2;
  const size = version * 4 + 17;
  const step = version === 32 ? 26 : Math.ceil((size - 13) / (count * 2 - 2)) * 2;

  const positions = [6];
  for (let pos = size - 7; positions.length < count; pos -= step) {
    positions.unshift(pos);
  }
  return positions.sort((a, b) => a - b);
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import {
    CheckboxGroup,
    RadioGroup,
    Text,
    Textarea,
} from '@particle-academy/react-fancy';
import type { Question } from '../lib/types';

export type AnswerValue =
    | { kind: 'option_id'; value: number }
    | { kind: 'option_ids'; value: number[] }
    | { kind: 'text'; value: string }
    | null;

export interface QuestionRendererProps {
    question: Question;
    value: AnswerValue;
    onChange: (next: AnswerValue) => void;
    disabled?: boolean;
}

export function QuestionRenderer({
    question,
    value,
    onChange,
    disabled,
}: QuestionRendererProps) {
    const options = question.options ?? [];

    if (question.type === 'multiple_choice' || question.type === 'true_false') {
        const selected =
            value?.kind === 'option_id' ? String(value.value) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <RadioGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_id', value: Number(next) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    if (question.type === 'multiple_select') {
        const selected =
            value?.kind === 'option_ids' ? value.value.map(String) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <Text size="sm" color="muted">
                    Select all that apply.
                </Text>
                <CheckboxGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_ids', value: next.map(Number) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    // short_answer
    const text = value?.kind === 'text' ? value.value : '';
    return (
        <div className="grid gap-3">
            <Text weight="semibold" className="!text-base">
                {question.prompt}
            </Text>
            <Textarea
                value={text}
                onChange={(e) =>
                    onChange({
                        kind: 'text',
                        value: (e.target as HTMLTextAreaElement).value,
                    })
                }
                disabled={disabled}
                rows={4}
                placeholder="Type your answer here…"
            />
        </div>
    );
}

export function answerValueToPayload(
    questionId: number,
    value: AnswerValue,
): { question_id: number; answer: unknown } {
    if (!value) return { question_id: questionId, answer: null };
    switch (value.kind) {
        case 'option_id':
            return { question_id: questionId, answer: { option_id: value.value } };
        case 'option_ids':
            return { question_id: questionId, answer: { option_ids: value.value } };
        case 'text':
            return { question_id: questionId, answer: { text: value.value } };
    }
}

