/**
 * Built-in agentic node kit — schema + UI for every kind, and an executor for
 * the ones that need nothing from the host.
 *
 * **MOST kinds ship no executor, not all of them.** This comment used to say
 * "every kind ships with schema + UI but NO executor", and that was false for
 * nine of the thirty-one — including `branch` and `transform`, which are
 * exactly the ones a host is most likely to hand-write after reading it. A
 * wrong comment on a library's front door is worse than no comment: it is
 * confidently actionable, and the action it prompts is wasted work.
 *
 * The fourteen that DO carry one are the ones needing nothing from the host:
 * `subflow`, `branch`, `for_each`, `merge`, `transform`, `llm_router`,
 * `terminal_run`, `terminal_send`, `terminal_await`, and — added once the
 * omission was noticed — `manual_trigger`, `output`, `log`, `variable` and
 * `switch_case`.
 *
 * The rest are left to the host because they need a decision only the host can
 * make: where memory, data, network and AI calls actually go. That is a choice
 * this runtime makes for being a BROWSER library rather than a property of the
 * contract — the PHP and Python twins ship ~25 and take those decisions by
 * injection instead (`ExecutorDeps` carries the notifier, store, llm, http).
 *
 * `wait`, `user_input` and `human_approval` stay host-wired even though they
 * look pure. Each HALTS a run, and how a run halts — a durable pause, a sleep,
 * a queue re-drive — is the host's architecture, not a default anyone can pick
 * on its behalf.
 */

/**
 * What each `user_input` control actually resolves to, in the vocabulary
 * `OutputField.type` uses.
 *
 * Date / time controls are strings deliberately — the form resolves the input's
 * `value`, which is an ISO-ish string, not a `Date`. Claiming otherwise here
 * would make the picker lie in the other direction.
 */
const HUMAN_FIELD_OUTPUT_TYPE: Record<HumanFieldType, "string" | "number" | "boolean"> = {
  text: "string",
  textarea: "string",
  select: "string",
  date: "string",
  datetime: "string",
  time: "string",
  email: "string",
  url: "string",
  tel: "string",
  password: "string",
  number: "number",
  switch: "boolean",
};

/**
 * Ports for `switch_case`, derived from its `cases` map (match value → port).
 *
 * Several match values may route to the same port, so ports are de-duplicated
 * and labelled with every value that reaches them ("a|c"). `default` is always
 * present — unmatched input has to land somewhere.
 */
function casePorts(cases: unknown): PortDescriptor[] {
  const byPort = new Map<string, string[]>();
  if (cases && typeof cases === "object" && !Array.isArray(cases)) {
    for (const [match, port] of Object.entries(cases as Record<string, unknown>)) {
      if (typeof port !== "string" || port === "" || port === "default") continue;
      const matches = byPort.get(port) ?? [];
      matches.push(match);
      byPort.set(port, matches);
    }
  }
  const ports: PortDescriptor[] = [...byPort].map(([id, matches]) => ({
    id,
    label: matches.join("|"),
  }));
  return [...ports, { id: "default", label: "default" }];
}

/**
 * Ports for `llm_branch`, derived from its `routes` list. Blank and duplicate
 * port names are dropped so a half-typed route can't collide with a real one.
 */
function routePorts(routes: unknown, fallback?: unknown): PortDescriptor[] {
  const ports: PortDescriptor[] = [];
  const seen = new Set<string>();
  if (Array.isArray(routes)) {
    for (const route of routes) {
      const id = (route as any)?.port;
      if (typeof id !== "string" || id.trim() === "" || seen.has(id)) continue;
      seen.add(id);
      ports.push({ id, label: id });
    }
  }
  if (fallback !== false && !seen.has("fallback")) {
    ports.push({ id: "fallback", label: "fallback" });
  }
  if (ports.length === 0) ports.push({ id: "out" });
  return ports;
}

