import { type CSSProperties, useEffect, useRef, useState } from "react";
import type { SessionDescriptor } from "../lib/sharing/token";
import type { AgentActivity } from "../agent-panel";
import { buildShareConfig, buildShareUrl } from "../lib/sharing/token";

export type ShareControlsProps = {
  /** The active session, or null when not sharing yet. */
  session: SessionDescriptor | null;
  onStart: () => void;
  onStop: () => void;
  /** Optional connection-state badge text. */
  status?: string;
  /**
   * True once an agent has actually connected to the session.
   *
   * Flips the panel from "here is how to connect" to "here is what the agent is
   * doing" — the paste-this-prompt UI is dead weight the moment it has been
   * pasted, and what the human needs then is visibility.
   */
  agentConnected?: boolean;
  /**
   * What the agent has done, newest last. Reuses `AgentActivity` from
   * `AgentPanel` rather than a second shape, so a host already collecting
   * presence events can pass the same array to both.
   */
  activity?: AgentActivity[];
  /** Override the URL base used in the share URL. */
  shareBaseUrl?: string;
  className?: string;
  style?: CSSProperties;
};

type Tab = "activity" | "prompt" | "url" | "json" | "curl";

/**
 * ShareControls — the host-facing UI for turning sharing on/off and
 * surfacing the resulting connection details (URL / JSON / cURL).
 */
export function ShareControls({
  session,
  onStart,
  onStop,
  status,
  agentConnected = false,
  activity,
  shareBaseUrl,
  className,
  style,
}: ShareControlsProps) {
  const [tab, setTab] = useState<Tab>("prompt");

  // Switch to the log the FIRST time an agent connects, then leave the tab
  // alone. Forcing it on every render would fight a human who deliberately went
  // back to copy the URL again — the panel should follow the session, not
  // overrule the person reading it.
  const wasConnected = useRef(false);
  useEffect(() => {
    if (agentConnected && !wasConnected.current) {
      wasConnected.current = true;
      setTab("activity");
    }
    if (!agentConnected) wasConnected.current = false;
  }, [agentConnected]);

  if (!session) {
    return (
      <div className={["fai-share fai-share--idle", className ?? ""].filter(Boolean).join(" ")} style={style}>
        <button type="button" className="fai-share__start" onClick={onStart}>
          Start shared session
        </button>
        <p className="fai-share__hint">
          Generates a session id + secret token. Hand the <strong>Agent prompt</strong> to an AI agent, share the URL with humans, or give the JSON config to an MCP-capable client.
        </p>
      </div>
    );
  }

  const url = buildShareUrl(session, shareBaseUrl);
  const config = buildShareConfig(session);
  const curl = buildCurlRecipe(session);
  const prompt = buildAgentPrompt(url);

  return (
    <div className={["fai-share fai-share--active", className ?? ""].filter(Boolean).join(" ")} style={style}>
      <div className="fai-share__header">
        <div>
          <strong>Sharing</strong>
          <span className="fai-share__id">
            session <code>{session.id}</code> · token <code>{session.display}…</code>
          </span>
        </div>
        <div className="fai-share__header-actions">
          {status && <span className="fai-share__status">{status}</span>}
          <button type="button" className="fai-share__stop" onClick={onStop}>
            Stop
          </button>
        </div>
      </div>

      <div className="fai-share__tabs" role="tablist">
        {agentConnected && (
          <TabButton tab="activity" active={tab} setTab={setTab}>
            Activity
          </TabButton>
        )}
        <TabButton tab="prompt" active={tab} setTab={setTab}>Agent prompt</TabButton>
        <TabButton tab="url" active={tab} setTab={setTab}>URL</TabButton>
        <TabButton tab="json" active={tab} setTab={setTab}>JSON</TabButton>
        <TabButton tab="curl" active={tab} setTab={setTab}>cURL recipe</TabButton>
      </div>

      <div className="fai-share__panel">
        {tab === "activity" && <ActivityLog activity={activity} />}
        {tab === "prompt" && (
          <CopyBox
            label="Paste this straight into an AI agent — it connects over MCP, no browser"
            value={prompt}
            multiline
          />
        )}
        {tab === "url" && <CopyBox label="Open this URL in another tab to join the session" value={url} />}
        {tab === "json" && (
          <CopyBox
            label="Paste into Claude Desktop / Cline MCP server config"
            value={JSON.stringify(config, null, 2)}
          />
        )}
        {tab === "curl" && (
          <CopyBox
            label="Connect from a terminal (verifies the relay is reachable)"
            value={curl}
            multiline
          />
        )}
      </div>
    </div>
  );
}

/**
 * What the agent has actually done, newest first.
 *
 * The panel used to keep showing the paste-this-prompt UI after the agent was
 * already connected and driving — dead weight at exactly the moment the human
 * needs the opposite: visibility. A connected agent with no visible activity is
 * indistinguishable from a broken one, which is precisely how a stalled session
 * goes unnoticed.
 */
function ActivityLog({ activity }: { activity?: AgentActivity[] }) {
  const entries = (activity ?? []).slice().reverse();

  if (entries.length === 0) {
    return (
      <p className="fai-share__empty">
        Connected. Nothing yet — actions appear here as the agent takes them.
      </p>
    );
  }

  return (
    <ol className="fai-share__activity" aria-live="polite">
      {entries.map((entry) => (
        <li key={entry.id} className="fai-share__activity-row" data-kind={entry.kind}>
          <time className="fai-share__activity-time" dateTime={new Date(entry.at).toISOString()}>
            {new Date(entry.at).toLocaleTimeString(undefined, {
              hour: "2-digit",
              minute: "2-digit",
              second: "2-digit",
            })}
          </time>
          <span className="fai-share__activity-source">{entry.source}</span>
          <span className="fai-share__activity-text">{entry.text}</span>
        </li>
      ))}
    </ol>
  );
}

function TabButton({ tab, active, setTab, children }: { tab: Tab; active: Tab; setTab: (t: Tab) => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      role="tab"
      aria-selected={tab === active}
      className={`fai-share__tab${tab === active ? " is-active" : ""}`}
      onClick={() => setTab(tab)}
    >
      {children}
    </button>
  );
}

function CopyBox({ label, value, multiline }: { label: string; value: string; multiline?: boolean }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      setTimeout(() => setCopied(false), 1200);
    } catch {
      // ignore
    }
  };
  return (
    <div>
      <div className="fai-share__panel-label">{label}</div>
      <div className="fai-share__copy">
        <pre className={`fai-share__pre${multiline ? " is-multi" : ""}`}>{value}</pre>
        <button type="button" className="fai-share__copy-btn" onClick={copy}>
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
    </div>
  );
}

/**
 * Build a copy-paste natural-language prompt to hand directly to an AI agent.
 * Agents handed a bare URL tend to try to *open it in a browser* — this spells
 * out that the link is a live MCP co-browsing session it should drive over MCP
 * tools (via the zero-install relay client), never visit.
 */
export function buildAgentPrompt(url: string): string {
  return [
    `You're joining a live Human+ co-browsing session on a web app. This is an MCP`,
    `(Model Context Protocol) session — NOT a website to visit. Do NOT open the URL`,
    `in a browser and do NOT use any browser/Playwright tool. You drive the real,`,
    `running app through MCP tools while a human watches and can take over.`,
    ``,
    `Session link (carries the session id + token — treat it as a secret):`,
    `  ${url}`,
    ``,
    `Connect by running the relay client as an MCP server (zero install):`,
    `  npx -y mcp-relay-client "${url}"`,
    ``,
    `That exposes the app's own tools (e.g. page_describe, page_read, nav_visit,`,
    `page_click, page_set_field, page_submit, plus surface tools like whiteboard_*).`,
    `Then:`,
    `  1. Call page_describe first to see the current page and its interactive handles.`,
    `  2. Act only on the STABLE HANDLES the tools return — never guess DOM selectors.`,
    `  3. Navigate with nav_visit, type with page_set_field, click with page_click.`,
    `     Submits and destructive clicks are staged for the human to confirm.`,
    ``,
    `If you can't register an MCP server but can run a shell, drive it directly:`,
    `  curl -O https://raw.githubusercontent.com/Particle-Academy/mcp-relay-client/main/connect.sh`,
    `  bash connect.sh "${url}" tools`,
    `  bash connect.sh "${url}" call page_describe '{}'`,
  ].join("\n");
}

/** Build a copy-paste cURL recipe for connecting an external MCP client. */
function buildCurlRecipe(session: SessionDescriptor): string {
  const base =
    typeof window !== "undefined"
      ? `${window.location.protocol}//${window.location.host}`
      : "http://localhost";
  const inbox = `${base}/agent-relay/${session.id}/inbox?token=${session.token}`;
  const events = `${base}/agent-relay/${session.id}/events?token=${session.token}`;
  return [
    `# 1) In one terminal, subscribe to server-pushed frames (SSE)`,
    `curl -N "${events}"`,
    ``,
    `# 2) In another terminal, send an initialize handshake`,
    `curl -X POST "${inbox}" \\`,
    `  -H 'content-type: application/json' \\`,
    `  -d '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}'`,
    ``,
    `# 3) List the tools the bridge exposes`,
    `curl -X POST "${inbox}" \\`,
    `  -H 'content-type: application/json' \\`,
    `  -d '{"jsonrpc":"2.0","id":2,"method":"tools/list"}'`,
    ``,
    `# 4) Add a sticky note`,
    `curl -X POST "${inbox}" \\`,
    `  -H 'content-type: application/json' \\`,
    `  -d '{"jsonrpc":"2.0","id":3,"method":"tools/call","params":{"name":"whiteboard_add_sticky","arguments":{"x":300,"y":300,"text":"hello from curl"}}}'`,
  ].join("\n");
}

/**
 * Session-token utilities. The token is a high-entropy secret; possession
 * grants read/write on the session. We don't HMAC frames — frames carry
 * the token directly (which is fine for in-process / same-origin / TLS
 * transports). For lower-trust transports, host apps can layer signing
 * on top of the BroadcastChannelTransport.
 */

const TOKEN_BYTES = 24; // 192 bits, base64url-encoded → 32 chars

export type SessionDescriptor = {
  /** Stable session identifier. Channel name = `fai:share:${id}`. */
  id: string;
  /** Secret token. Treat as a password — anyone with it can read/write. */
  token: string;
  /** Pretty hash for display (first 8 chars of token). */
  display: string;
};

export function createSessionDescriptor(): SessionDescriptor {
  const id = randomId(8);
  const token = randomToken();
  return { id, token, display: token.slice(0, 8) };
}

export function describeSession(id: string, token: string): SessionDescriptor {
  return { id, token, display: token.slice(0, 8) };
}

/**
 * Build the shareable URL for the current page (preserves path, adds
 * session+token in the URL FRAGMENT).
 *
 * The token goes in the `#fragment`, never the `?query`: a fragment is never
 * transmitted to the server, so it can't leak through access/proxy logs or the
 * `Referer` header sent to third-party assets on the page. The recipient reads
 * it back with {@link readSessionFromUrl}. (The on-wire relay leg still sends
 * `?token=` today — moving that off the query is the larger transport change.)
 */
export function buildShareUrl(
  descriptor: SessionDescriptor,
  baseUrl: string = typeof window !== "undefined" ? window.location.href.split("?")[0] : "",
): string {
  const u = new URL(baseUrl);
  u.hash = new URLSearchParams({ session: descriptor.id, token: descriptor.token }).toString();
  return u.toString();
}

/** Build the JSON config form (suitable for Claude Desktop / Cline / etc.). */
export function buildShareConfig(descriptor: SessionDescriptor, transport = "broadcast-channel") {
  return {
    name: `whiteboard-${descriptor.id}`,
    transport,
    session: descriptor.id,
    token: descriptor.token,
    channel: `fai:share:${descriptor.id}`,
    protocol_version: "2025-06-18",
  };
}

/**
 * Read session descriptor from the current URL, or null if not a shared link.
 * Prefers the fragment (the non-leaking form {@link buildShareUrl} now emits),
 * falling back to the query string for links minted before that change.
 */
export function readSessionFromUrl(): SessionDescriptor | null {
  if (typeof window === "undefined") return null;
  const url = new URL(window.location.href);
  const frag = new URLSearchParams(url.hash.replace(/^#/, ""));
  const id = frag.get("session") ?? url.searchParams.get("session");
  const token = frag.get("token") ?? url.searchParams.get("token");
  if (!id || !token) return null;
  return describeSession(id, token);
}

function randomToken(): string {
  const bytes = new Uint8Array(TOKEN_BYTES);
  crypto.getRandomValues(bytes);
  return base64Url(bytes);
}

function randomId(len: number): string {
  const bytes = new Uint8Array(Math.ceil((len * 3) / 4));
  crypto.getRandomValues(bytes);
  return base64Url(bytes).slice(0, len);
}

function base64Url(bytes: Uint8Array): string {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** Constant-time string compare so a mismatched token leaks no timing info. */
export function constantTimeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

