import { type CSSProperties, type ReactNode, useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Board,
  StickyNote,
  Connector,
  Shape,
  CursorLayer,
  type StickyNoteItem,
  type ShapeItem,
  type ConnectorItem,
  type Stroke,
  type RemoteCursor,
  type Viewport,
} from "@particle-academy/fancy-whiteboard";
import { MicroMcpServer, type Transport } from "../lib/mcp/server";
import { attachInProcess, type InProcessTransport } from "../lib/mcp/transports/in-process";
import { attachSseRelay, type RelayState, type SseRelayTransport } from "../lib/sharing/sse-relay";
import { createSessionDescriptor, type SessionDescriptor } from "../lib/sharing/token";
import { registerWhiteboardBridge } from "../lib/bridges/whiteboard";
import type { Bridge } from "../lib/bridges/types";
import { ShareControls } from "../share-controls";
import { AgentPanel, type AgentActivity } from "../agent-panel";
import { AgentCursor } from "../agent-cursor";
import { AgentActivityHighlight } from "../lib/components/AgentActivityHighlight";

export type SharedWhiteboardProps = {
  /** Initial board contents. */
  initialNotes?: StickyNoteItem[];
  initialShapes?: ShapeItem[];
  initialConnectors?: ConnectorItem[];
  initialStrokes?: Stroke[];
  initialViewport?: Viewport;

  /** Agent identity displayed in the panel + cursor. */
  agent?: { id: string; name?: string; color?: string };

  /**
   * Where the relay HTTP endpoints live. The host app implements these (see
   * docs/relay-protocol.md). Pass `null` to disable sharing — the board
   * still works locally with the in-process MCP server.
   */
  shareBaseUrl?: string | null;

  /**
   * Optional callback to register a new session token with the host's
   * relay broker. Receives `{ session, token }` and should return after
   * registration. Defaults to POSTing JSON to `${shareBaseUrl}/register`.
   */
  onRegisterSession?: (descriptor: SessionDescriptor) => Promise<void>;

  /** Show the agent panel. Default true. */
  showAgentPanel?: boolean;

  /** Show share controls. Default true. */
  showShareControls?: boolean;

  /** Auto-broadcast local edits as `notifications/state_update`. Default true. */
  broadcastEdits?: boolean;

  /** Pixel height of the board area. Default 640. */
  height?: number;

  /** Header content rendered above the board. */
  header?: ReactNode;

  className?: string;
  style?: CSSProperties;
};

const DEFAULT_AGENT = { id: "agent", name: "Agent", color: "#a855f7" };

/**
 * SharedWhiteboard — drop-in component that bundles every piece of the
 * "agent-collaborative whiteboard" UX: board with all primitives, in-page
 * MCP server, share controls, agent panel, presence cursor, activity
 * highlight, and outbound state broadcast.
 *
 * Most apps only need this one component. For deeper customization, swap
 * it for the lower-level primitives (Board, MicroMcpServer, ShareControls).
 */
export function SharedWhiteboard({
  initialNotes = [],
  initialShapes = [],
  initialConnectors = [],
  initialStrokes = [],
  initialViewport = { x: 0, y: 0, zoom: 1 },
  agent = DEFAULT_AGENT,
  shareBaseUrl = "/agent-relay",
  onRegisterSession,
  showAgentPanel = true,
  showShareControls = true,
  broadcastEdits = true,
  height = 640,
  header,
  className,
  style,
}: SharedWhiteboardProps) {
  // Board state
  const [notes, setNotes] = useState<StickyNoteItem[]>(initialNotes);
  const [shapes, setShapes] = useState<ShapeItem[]>(initialShapes);
  const [connectors, setConnectors] = useState<ConnectorItem[]>(initialConnectors);
  const [strokes, setStrokes] = useState<Stroke[]>(initialStrokes);
  const [viewport, setViewport] = useState<Viewport>(initialViewport);
  const [agentCursor, setAgentCursor] = useState<RemoteCursor | null>(null);

  // Agent UX state
  const [activity, setActivity] = useState<AgentActivity[]>([]);
  const [highlight, setHighlight] = useState<{ pulseKey: number; bounds: { x: number; y: number; width: number; height: number } } | null>(null);

  const stateRefs = useRef({ notes, shapes, connectors, strokes, viewport });
  useEffect(() => { stateRefs.current = { notes, shapes, connectors, strokes, viewport }; }, [notes, shapes, connectors, strokes, viewport]);

  // MCP server + bridge
  const serverRef = useRef<MicroMcpServer | null>(null);
  const inProcRef = useRef<InProcessTransport | null>(null);
  const bridgeRef = useRef<Bridge | null>(null);

  useEffect(() => {
    const server = new MicroMcpServer({
      info: { name: "shared-whiteboard", version: "0.2.0" },
      instructions: "Collaborative whiteboard. Use whiteboard_* tools to read or modify the board.",
    });
    bridgeRef.current = registerWhiteboardBridge(server, {
      adapter: {
        getNotes: () => stateRefs.current.notes,
        setNotes: (next) => setNotes(typeof next === "function" ? next : () => next),
        getShapes: () => stateRefs.current.shapes,
        setShapes: (next) => setShapes(typeof next === "function" ? next : () => next),
        getConnectors: () => stateRefs.current.connectors,
        setConnectors: (next) => setConnectors(typeof next === "function" ? next : () => next),
        getStrokes: () => stateRefs.current.strokes,
        setStrokes: (next) => setStrokes(typeof next === "function" ? next : () => next),
        getViewport: () => stateRefs.current.viewport,
        setViewport,
        setAgentCursor,
      },
      agent,
    });
    inProcRef.current = attachInProcess(server);
    serverRef.current = server;

    // Pulse a highlight whenever a tool call returns a structured id.
    const off = inProcRef.current.onServerMessage((msg: any) => {
      if (msg?.id !== undefined && "result" in msg && msg.result?.structuredContent?.id) {
        const id = msg.result.structuredContent.id;
        requestAnimationFrame(() => pulseFor(id));
      }
    });
    return () => {
      off();
      bridgeRef.current?.dispose();
      bridgeRef.current = null;
      if (inProcRef.current) server.detach(inProcRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const pulseFor = (id: string) => {
    const n = stateRefs.current.notes.find((x) => x.id === id);
    if (n) return setHighlight({ pulseKey: Date.now(), bounds: { x: n.x, y: n.y, width: n.width, height: n.height } });
    const s = stateRefs.current.shapes.find((x) => x.id === id);
    if (s) return setHighlight({ pulseKey: Date.now(), bounds: { x: s.x, y: s.y, width: s.width, height: s.height } });
  };

  const log = useCallback((entry: Omit<AgentActivity, "id" | "at">) => {
    setActivity((all) => [...all.slice(-200), { id: `a_${Date.now()}_${all.length}`, at: Date.now(), ...entry }]);
  }, []);

  // Sharing
  const [session, setSession] = useState<SessionDescriptor | null>(null);
  const [relayState, setRelayState] = useState<RelayState>("idle");
  const sseRef = useRef<SseRelayTransport | null>(null);
  const logEsRef = useRef<EventSource | null>(null);

  const startShare = async () => {
    if (session || !serverRef.current || !shareBaseUrl) return;
    const desc = createSessionDescriptor();

    try {
      if (onRegisterSession) {
        await onRegisterSession(desc);
      } else {
        const csrf = (document.querySelector('meta[name="csrf-token"]') as HTMLMetaElement | null)?.content ?? "";
        const reg = await fetch(`${shareBaseUrl}/register`, {
          method: "POST",
          headers: { "content-type": "application/json", "x-csrf-token": csrf, accept: "application/json" },
          body: JSON.stringify({ session: desc.id, token: desc.token }),
        });
        if (!reg.ok) throw new Error(`registration failed (HTTP ${reg.status})`);
      }
    } catch (e) {
      log({ kind: "error", source: "share", text: e instanceof Error ? e.message : String(e) });
      return;
    }

    const relay = attachSseRelay(serverRef.current, {
      baseUrl: shareBaseUrl,
      sessionId: desc.id,
      token: desc.token,
    });
    sseRef.current = relay;
    relay.onStateChange(setRelayState);

    // Activity log mirror — does NOT call deliverFromRemote (relay does it).
    const es = new EventSource(`${shareBaseUrl}/${desc.id}/events?token=${desc.token}&direction=inbound`);
    es.addEventListener("mcp", (ev: MessageEvent) => {
      try {
        const frame = JSON.parse(ev.data);
        if (frame.method === "notifications/peer_joined") {
          // External agent just opened an outbound subscription. Surface it
          // so the human can see "an agent is connecting" before any tools
          // arrive. The agent itself should follow up with set_agent_cursor
          // immediately, but in case it doesn't, drop a placeholder cursor
          // at the canvas origin so presence is visible right away.
          setAgentCursor((c) => c ?? { userId: agent.id, name: agent.name, color: agent.color, x: 60, y: 60 });
          log({ kind: "info", source: "presence", text: `${agent.name ?? "Agent"} connected` });
          return;
        }
        if (frame.method === "notifications/peer_left") {
          setAgentCursor(null);
          log({ kind: "info", source: "presence", text: `${agent.name ?? "Agent"} disconnected` });
          return;
        }
        if (frame.method === "notifications/agent_message") {
          log({ kind: "message", source: agent.name ?? "Agent", text: String(frame.params?.text ?? "") });
        } else if (frame.method === "notifications/agent_status") {
          log({ kind: "info", source: agent.name ?? "Agent", text: String(frame.params?.text ?? "") });
        } else if (frame.method?.startsWith("notifications/")) {
          // ignore other notifications in the feed
        } else {
          log({ kind: "tool", source: "remote", text: `← ${frame.method ?? `id:${frame.id}`}`, detail: frame });
        }
      } catch {
        /* noop */
      }
    });
    logEsRef.current = es;

    setSession(desc);
    log({ kind: "info", source: "share", text: `Sharing started · session ${desc.id}` });
  };

  const stopShare = async () => {
    if (!session) return;
    const desc = session;
    setSession(null);
    logEsRef.current?.close();
    logEsRef.current = null;
    if (sseRef.current && serverRef.current) serverRef.current.detach(sseRef.current);
    sseRef.current = null;
    setRelayState("closed");
    if (shareBaseUrl) {
      const csrf = (document.querySelector('meta[name="csrf-token"]') as HTMLMetaElement | null)?.content ?? "";
      await fetch(`${shareBaseUrl}/${desc.id}/unregister?token=${encodeURIComponent(desc.token)}`, {
        method: "POST",
        headers: { "x-csrf-token": csrf, accept: "application/json" },
      }).catch(() => {});
    }
    log({ kind: "info", source: "share", text: "Sharing stopped." });
  };

  // Outbound state broadcast — every state change pushes a notification on
  // the relay (capped to ~12 Hz) so external agents see human edits live.
  const lastBroadcastRef = useRef(0);
  useEffect(() => {
    if (!broadcastEdits || !sseRef.current || !session) return;
    const now = Date.now();
    if (now - lastBroadcastRef.current < 80) return;
    lastBroadcastRef.current = now;
    sseRef.current.send({
      jsonrpc: "2.0",
      method: "notifications/state_update",
      params: { notes, shapes, connectors, viewport, ts: now },
    });
  }, [notes, shapes, connectors, viewport, session, broadcastEdits]);

  const handleSubmit = (text: string) => {
    if (!sseRef.current) {
      log({ kind: "error", source: "you", text: "Start a shared session first." });
      return;
    }
    sseRef.current.send({
      jsonrpc: "2.0",
      method: "notifications/user_message",
      params: { text, ts: Date.now() },
    });
    log({ kind: "message", source: "You", text });
  };

  // The agent cursor is rendered by <AgentCursor> below — keep it OUT of
  // the cursors array so we don't double-render it via CursorLayer.
  // (CursorLayer is reserved for human participants once relay sync lands.)
  const cursors: RemoteCursor[] = useMemo(() => [], []);
  const statusText = (() => {
    switch (relayState) {
      case "open": return "live";
      case "connecting": return "connecting…";
      case "error": return "error";
      case "closed": return "closed";
      default: return undefined;
    }
  })();

  return (
    <div className={["fai-shared-whiteboard", className ?? ""].filter(Boolean).join(" ")} style={style}>
      {header}
      {showShareControls && shareBaseUrl !== null && (
        <div className="fai-shared-whiteboard__controls">
          <ShareControls session={session} onStart={startShare} onStop={stopShare} status={statusText} />
        </div>
      )}
      <div
        className="fai-shared-whiteboard__layout"
        style={{
          display: "grid",
          gap: 16,
          gridTemplateColumns: showAgentPanel ? "1fr 360px" : "1fr",
        }}
      >
        <div
          className="fai-shared-whiteboard__board"
          style={{
            position: "relative",
            overflow: "hidden",
            borderRadius: 12,
            border: "1px solid #e4e4e7",
            background:
              "radial-gradient(circle at 1px 1px, rgba(0,0,0,0.07) 1px, transparent 0)",
            backgroundSize: "20px 20px",
            height,
          }}
        >
          <Board viewport={viewport} onViewportChange={setViewport} style={{ width: "100%", height: "100%" }}>
            {connectors.map((c) => {
              const a = resolveCenter(c.from, notes, shapes);
              const b = resolveCenter(c.to, notes, shapes);
              if (!a || !b) return null;
              return <Connector key={c.id} from={a} to={b} color={c.color ?? "#64748b"} />;
            })}
            {shapes.map((s) => (
              <Shape key={s.id} item={s} onChange={(next) => setShapes((all) => all.map((x) => (x.id === next.id ? next : x)))} />
            ))}
            {notes.map((n) => (
              <StickyNote key={n.id} item={n} onChange={(next) => setNotes((all) => all.map((x) => (x.id === next.id ? next : x)))} />
            ))}
            <CursorLayer cursors={cursors} />
            {agentCursor && (
              <AgentCursor x={agentCursor.x} y={agentCursor.y} name={agentCursor.name} color={agentCursor.color} />
            )}
            {highlight && (
              <AgentActivityHighlight
                x={highlight.bounds.x}
                y={highlight.bounds.y}
                width={highlight.bounds.width}
                height={highlight.bounds.height}
                color={agent.color ?? "#a855f7"}
                pulseKey={highlight.pulseKey}
              />
            )}
          </Board>
        </div>
        {showAgentPanel && (
          <div style={{ height }}>
            <AgentPanel
              agent={agent}
              activity={activity}
              onSubmit={handleSubmit}
            />
          </div>
        )}
      </div>
    </div>
  );
}

function resolveCenter(
  ref: ConnectorItem["from"],
  notes: StickyNoteItem[],
  shapes: ShapeItem[],
): { x: number; y: number } | null {
  if (typeof ref === "string") {
    const n = notes.find((x) => x.id === ref);
    if (n) return { x: n.x + n.width / 2, y: n.y + n.height / 2 };
    const s = shapes.find((x) => x.id === ref);
    if (s) return { x: s.x + s.width / 2, y: s.y + s.height / 2 };
    return null;
  }
  return ref;
}

// Internal-import safety
type _UseTransport = Transport;

import {
  type CallToolResult,
  type JsonObject,
  type JsonRpcMessage,
  type JsonRpcRequest,
  type JsonRpcId,
  type RegisteredTool,
  type ServerCapabilities,
  type ServerInfo,
  type ToolDefinition,
  type ToolHandler,
  JSONRPC_INTERNAL_ERROR,
  JSONRPC_INVALID_PARAMS,
  JSONRPC_METHOD_NOT_FOUND,
  MCP_PROTOCOL_VERSION,
} from "./types";
import { ToolRegistry } from "./tool-host";

export type McpServerOptions = {
  info: ServerInfo;
  /** Defaults to { tools: { listChanged: true } } */
  capabilities?: ServerCapabilities;
  /** Free-text instructions surfaced to clients during initialize. */
  instructions?: string;
  /**
   * The protocol revisions this server speaks, NEWEST FIRST.
   *
   * `initialize` echoes the client's requested revision when it is in this
   * list, and answers the first entry otherwise — the spec's rule, which leaves
   * the client to decide whether it can live with the answer.
   *
   * Defaults to `[MCP_PROTOCOL_VERSION]`: one revision, answered whatever the
   * client asks, which is exactly what this server did before the option
   * existed. Only list a revision the tools you register are correct under.
   */
  protocolVersions?: readonly string[];
};

export type Transport = {
  /** Called by the server when it has a message to deliver to the client. */
  send: (message: JsonRpcMessage) => void;
  /** Called by the server when it's torn down so the transport can clean up. */
  close?: () => void;
};

/**
 * MicroMcpServer — protocol-level MCP server, transport-agnostic.
 *
 * Use it like:
 *
 *   const server = new MicroMcpServer({ info: { name: "session", version: "0.1" } });
 *   server.registerTool({ name: "...", inputSchema: { type: "object" } }, async (args) => ({...}));
 *   const transport = new InProcessTransport();
 *   server.attach(transport);
 *   transport.deliver({ ... }); // client → server frames
 *
 * The same server can serve multiple transports (e.g. an in-process agent
 * AND a relayed external client) by attaching each one.
 */
export class MicroMcpServer extends ToolRegistry {
  private transports = new Set<Transport>();
  /**
   * Transports owed a `tools/list_changed` at the end of this tick. Empty when
   * none is scheduled. See {@link scheduleListChangedNotification}.
   */
  private listChangedOwed = new Set<Transport>();

  readonly info: ServerInfo;
  readonly capabilities: ServerCapabilities;
  readonly instructions?: string;
  readonly protocolVersions: readonly string[];

  constructor(options: McpServerOptions) {
    super();
    this.info = options.info;
    this.capabilities = options.capabilities ?? { tools: { listChanged: true } };
    this.instructions = options.instructions;
    if (options.protocolVersions && options.protocolVersions.length === 0) {
      // No answer exists for a client's initialize. Fail here, next to the
      // mistake, rather than in a handshake nobody is watching.
      throw new Error("MicroMcpServer: protocolVersions is empty — a server must speak at least one protocol revision.");
    }
    this.protocolVersions = options.protocolVersions ? [...options.protocolVersions] : [MCP_PROTOCOL_VERSION];
  }

  attach(transport: Transport): () => void {
    this.transports.add(transport);
    return () => this.detach(transport);
  }

  detach(transport: Transport): void {
    if (this.transports.delete(transport)) {
      transport.close?.();
    }
  }

  unregisterTool(name: string): void {
    if (this.tools.delete(name)) {
      this.scheduleListChangedNotification();
    }
  }

  protected onToolsChanged(): void {
    this.scheduleListChangedNotification();
  }

  /**
   * Receive a JSON-RPC frame from a client (called by the transport).
   * The transport is responsible for sending the response back.
   */
  async receive(transport: Transport, message: JsonRpcMessage): Promise<void> {
    if (!("method" in message)) return; // It's a response, not a request — ignore.

    const isNotification = !("id" in message);
    if (isNotification) {
      // Notifications are fire-and-forget. We ignore unknown methods.
      return;
    }

    const request = message as JsonRpcRequest;
    try {
      const result = await this.handle(request, transport);
      transport.send({ jsonrpc: "2.0", id: request.id, result });
    } catch (err) {
      transport.send({
        jsonrpc: "2.0",
        id: request.id,
        error: this.toRpcError(err),
      });
    }
  }

  private async handle(request: JsonRpcRequest, transport: Transport): Promise<any> {
    const { method, params } = request;
    switch (method) {
      case "initialize":
        return {
          protocolVersion: this.negotiate(params?.protocolVersion),
          capabilities: this.capabilities,
          serverInfo: this.info,
          ...(this.instructions ? { instructions: this.instructions } : {}),
        };

      case "tools/list":
        return { tools: this.listTools() };

      case "tools/call": {
        const name = params?.name;
        const args = (params?.arguments ?? {}) as JsonObject;
        if (typeof name !== "string") {
          throw rpcError(JSONRPC_INVALID_PARAMS, "tools/call requires `name`");
        }
        const tool = this.tools.get(name);
        if (!tool) {
          throw rpcError(JSONRPC_METHOD_NOT_FOUND, this.missingToolMessage(name));
        }
        const result = await tool.handler(args, { transport });
        return result satisfies CallToolResult;
      }

      case "ping":
        return {};

      default:
        throw rpcError(JSONRPC_METHOD_NOT_FOUND, `Unsupported method: ${method}`);
    }
  }

  /** The revision to answer `initialize` with: the one asked for if spoken, else the newest. */
  private negotiate(requested: unknown): string {
    return typeof requested === "string" && this.protocolVersions.includes(requested)
      ? requested
      : this.protocolVersions[0];
  }

  /**
   * Tell the transports that SAW the old tool list that it changed.
   *
   * Changes in one tick coalesce into one notification. The recipients are the
   * transports attached at the moment of a change, not at the moment the
   * notification goes out: a transport attached afterwards never had the old
   * list, so "your list is stale" is noise to it — and on stdio, where a host
   * builds the server and attaches stdin/stdout in the same tick, it was the
   * first frame a client received, before it had even sent `initialize`.
   */
  private scheduleListChangedNotification(): void {
    if (this.transports.size === 0) return;
    const scheduled = this.listChangedOwed.size > 0;
    for (const t of this.transports) this.listChangedOwed.add(t);
    if (scheduled) return;
    queueMicrotask(() => {
      const owed = this.listChangedOwed;
      this.listChangedOwed = new Set();
      for (const t of owed) {
        // Detached since the change: it is not listening any more.
        if (this.transports.has(t)) t.send({ jsonrpc: "2.0", method: "notifications/tools/list_changed" });
      }
    });
  }

  /** Send an application notification to every client, or one attached transport. */
  notify(message: JsonRpcMessage, transport?: Transport): void {
    if (transport) transport.send(message);
    else this.broadcast(message);
  }

  private broadcast(message: JsonRpcMessage): void {
    for (const t of this.transports) t.send(message);
  }

  private toRpcError(err: unknown): { code: number; message: string; data?: any } {
    if (err && typeof err === "object" && "code" in err && "message" in err) {
      return err as any;
    }
    return {
      code: JSONRPC_INTERNAL_ERROR,
      message: err instanceof Error ? err.message : String(err),
    };
  }
}

export function rpcError(code: number, message: string, data?: any) {
  return { code, message, ...(data !== undefined ? { data } : {}) };
}

/**
 * Helper to build a CallToolResult from a string or structured value.
 */
export function textResult(text: string, structured?: any): CallToolResult {
  return {
    content: [{ type: "text", text }],
    ...(structured !== undefined ? { structuredContent: structured } : {}),
  };
}

export function errorResult(text: string): CallToolResult {
  return { content: [{ type: "text", text }], isError: true };
}

// Internal helper so the JsonRpcId import isn't dropped by tsup
type _KeepIdImport = JsonRpcId;

import type { JsonRpcMessage } from "../types";
import type { MicroMcpServer, Transport } from "../server";

/**
 * InProcessTransport — direct function-call wiring between an in-page MCP
 * client (e.g. an embedded chat agent) and a MicroMcpServer running in
 * the same JS context. No serialization, no network.
 *
 * Usage:
 *
 *   const t = new InProcessTransport();
 *   server.attach(t);
 *   t.onServerMessage((msg) => { ... });   // client subscribes
 *   t.send({ jsonrpc: "2.0", id: 1, method: "tools/list" }); // client → server
 */
export class InProcessTransport implements Transport {
  private server?: MicroMcpServer;
  private listeners = new Set<(msg: JsonRpcMessage) => void>();

  /** Bind to a server. Called from the client's setup, not directly. */
  bindServer(server: MicroMcpServer): void {
    this.server = server;
  }

  /** Server → client (delivered to subscribed listeners). */
  send(message: JsonRpcMessage): void {
    for (const l of this.listeners) l(message);
  }

  /** Client → server. Awaitable so callers can flush. */
  async deliver(message: JsonRpcMessage): Promise<void> {
    if (!this.server) throw new Error("InProcessTransport has no bound server");
    await this.server.receive(this, message);
  }

  /** Subscribe to messages the server pushes to this client. */
  onServerMessage(listener: (msg: JsonRpcMessage) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  close(): void {
    this.listeners.clear();
  }
}

/**
 * Convenience: create a server-attached in-process transport in one call.
 */
export function attachInProcess(server: MicroMcpServer): InProcessTransport {
  const transport = new InProcessTransport();
  transport.bindServer(server);
  server.attach(transport);
  return transport;
}

import type { JsonRpcMessage } from "../mcp/types";
import type { Transport } from "../mcp/server";
import type { MicroMcpServer } from "../mcp/server";
import type { RelayChannelHandle } from "@particle-academy/fancy-cf-relay";
import { constantTimeEqual } from "./token";
import type { AgentActivityEvent } from "../presence/types";
import { emitActivity } from "../presence/registry";

/**
 * SseRelayTransport — bridges the in-page MicroMcpServer to a host-app
 * relay broker over Server-Sent Events (inbound) + POST (outbound).
 *
 * Wire model:
 *   - Browser opens an EventSource at `${baseUrl}/${sessionId}/events?token=…`.
 *     Each `event: mcp` carries one JSON-RPC frame from a remote client.
 *   - Browser POSTs JSON-RPC frames to `${baseUrl}/${sessionId}/outbox?token=…`
 *     when the local server has a response/notification to send.
 *
 * The host provides the relay endpoint (any HTTP server). See the demo
 * `WhiteboardShareController` for the reference implementation.
 *
 * Token authentication is the host's job — this transport just carries the
 * token in the query string. For lower-trust deployments, layer signing on
 * top by wrapping `send` / `deliverFromRemote`.
 */
export type SseRelayOptions = {
  /**
   * Which in-process activity events this relay forwards to ITS agent.
   *
   * The activity bus is global to the page, so with two concurrent sessions —
   * site co-browse and the agent playground — each relay forwarded the other's
   * traffic and every agent saw every other agent's navigations. Returning
   * `false` drops the event for this relay only.
   *
   * Omitted means forward everything, which is the historical behaviour and
   * correct for the common single-session case. A throwing predicate drops that
   * one event and keeps the subscription: a host predicate is host code, and
   * one bad event must not silently end forwarding for the session — that looks
   * exactly like the agent going quiet.
   */
  activityFilter?: (event: AgentActivityEvent) => boolean;
  /**
   * Identity stamped on the relay's own connect/disconnect activity.
   *
   * These were emitted with a literal `agentId: "agent"`, which made two
   * sessions' connect events indistinguishable — and unfilterable, since there
   * was nothing to tell them apart by.
   */
  agent?: { id: string; name?: string; color?: string };
  baseUrl: string;
  sessionId: string;
  token: string;
  /** Override fetch (testing / non-browser). Defaults to global fetch. */
  fetch?: typeof fetch;
};

export class SseRelayTransport implements Transport {
  private server?: MicroMcpServer;
  private es?: EventSource;
  private channel?: RelayChannelHandle;
  private disposed = false;
  private opts: SseRelayOptions;
  private sendQueue: JsonRpcMessage[] = [];
  private connected = false;
  private listeners = new Set<(state: RelayState) => void>();
  private state: RelayState = "idle";
  private expectedToken: string;
  private peers = new Set<string>();
  private peerListeners = new Set<(count: number) => void>();

  constructor(options: SseRelayOptions) {
    this.opts = options;
    this.expectedToken = options.token;
  }

  bindServer(server: MicroMcpServer): void {
    this.server = server;
  }

  /** Open the receive channel. Idempotent. */
  start(): void {
    if (this.connected || this.disposed || typeof window === "undefined") return;
    this.setState("connecting");
    // Prefer @particle-academy/fancy-cf-relay's adaptive channel (auto SSE↔
    // long-poll with Cloudflare detection) so the receive leg survives a
    // Cloudflare HTTP/3 (QUIC) edge that resets long-lived SSE streams. It's an
    // OPTIONAL peer: if it isn't installed, fall back to a plain EventSource.
    void import("@particle-academy/fancy-cf-relay")
      .then(({ createRelayChannel }) => {
        if (this.connected || this.disposed) return;
        this.channel = createRelayChannel({
          baseUrl: this.opts.baseUrl,
          session: this.opts.sessionId,
          token: this.opts.token,
          transport: "auto",
          receiveDirection: "inbound",
          sendPath: "outbox",
          onFrame: (raw) => this.handleInbound(raw),
          onOpen: () => this.markOpen(),
          onError: () => this.setState("error"),
          fetchImpl: this.opts.fetch,
        });
        this.channel.start();
      })
      .catch(() => {
        if (!this.disposed) this.startSse();
      });
  }

  /** Fallback receive leg: a plain EventSource (no fancy-cf-relay installed). */
  private startSse(): void {
    if (this.connected || this.disposed) return;
    const url = `${this.opts.baseUrl}/${encodeURIComponent(this.opts.sessionId)}/events?token=${encodeURIComponent(this.opts.token)}`;
    const es = new EventSource(url, { withCredentials: false });
    this.es = es;
    es.addEventListener("open", () => this.markOpen());
    es.addEventListener("mcp", (ev: MessageEvent) => this.handleInbound(ev.data));
    es.addEventListener("error", () => this.setState("error")); // EventSource auto-reconnects
  }

  /** Mark the channel live + flush any queued outbound frames. */
  private markOpen(): void {
    this.connected = true;
    this.setState("open");
    const queued = this.sendQueue.splice(0);
    for (const msg of queued) this.postOut(msg);
  }

  send(message: JsonRpcMessage): void {
    if (!this.connected) {
      this.sendQueue.push(message);
      return;
    }
    this.postOut(message);
  }

  close(): void {
    this.disposed = true;
    this.channel?.stop();
    this.channel = undefined;
    this.es?.close();
    this.es = undefined;
    this.connected = false;
    this.peers.clear();
    this.notifyPeers();
    this.setState("closed");
  }

  onStateChange(listener: (state: RelayState) => void): () => void {
    this.listeners.add(listener);
    listener(this.state);
    return () => this.listeners.delete(listener);
  }

  /** How many remote peers (agents) are currently attached to this session. */
  peerCount(): number {
    return this.peers.size;
  }

  /**
   * Subscribe to peer arrivals/departures. Fires immediately with the current
   * count.
   *
   * This is the ONLY honest answer to "is an agent actually here?".
   * `onStateChange` reports the BROWSER's own channel to the relay, which opens
   * the instant sharing starts — so a UI keyed on it announces "Agent is
   * driving" to a human who has not yet handed the link to anybody, and can
   * never tell them when one really arrives.
   */
  onPeersChange(listener: (count: number) => void): () => void {
    this.peerListeners.add(listener);
    listener(this.peers.size);
    return () => this.peerListeners.delete(listener);
  }

  private notifyPeers(): void {
    for (const l of this.peerListeners) l(this.peers.size);
  }

  /**
   * For relays that wrap each frame with auth metadata: hosts can call this
   * directly when a frame arrives via a non-SSE path. The transport will
   * dispatch it to the bound server.
   */
  async deliverFromRemote(payload: JsonRpcMessage | string, token?: string): Promise<void> {
    if (token !== undefined && !constantTimeEqual(token, this.expectedToken)) return;
    if (!this.server) throw new Error("SseRelayTransport has no bound server");
    const message: JsonRpcMessage = typeof payload === "string" ? JSON.parse(payload) : payload;
    await this.server.receive(this, message);
  }

  private async postOut(message: JsonRpcMessage): Promise<void> {
    const url = `${this.opts.baseUrl}/${encodeURIComponent(this.opts.sessionId)}/outbox?token=${encodeURIComponent(this.opts.token)}`;
    const f = this.opts.fetch ?? fetch;
    try {
      await f(url, {
        method: "POST",
        headers: { "content-type": "application/json", "accept": "application/json" },
        body: JSON.stringify(message),
      });
    } catch {
      // Drop — relay errors are surfaced via state change separately.
    }
  }

  private async handleInbound(raw: string): Promise<void> {
    if (!this.server) return;
    let message: JsonRpcMessage;
    try {
      message = JSON.parse(raw);
    } catch {
      return;
    }
    if ("method" in message && message.method === "notifications/peer_joined") {
      const subscriberId = String((message.params as { subscriberId?: unknown } | undefined)?.subscriberId ?? "peer");
      this.peers.add(subscriberId);
      this.notifyPeers();
      emitActivity({
        agentId: this.opts.agent?.id ?? "agent",
        agentName: this.opts.agent?.name ?? "Agent",
        agentColor: this.opts.agent?.color ?? "#a855f7",
        action: "agent_connected",
        timestamp: Date.now(),
        target: { kind: "navigation", label: "Agent connected" },
        meta: { subscriberId },
      });
      return;
    }
    if ("method" in message && message.method === "notifications/peer_left") {
      const subscriberId = String((message.params as { subscriberId?: unknown } | undefined)?.subscriberId ?? "peer");
      this.peers.delete(subscriberId);
      this.notifyPeers();
      if (this.peers.size === 0) {
        emitActivity({
          agentId: this.opts.agent?.id ?? "agent",
          agentName: this.opts.agent?.name ?? "Agent",
          agentColor: this.opts.agent?.color ?? "#a855f7",
          action: "agent_disconnected",
          timestamp: Date.now(),
          target: { kind: "navigation", label: "Agent disconnected" },
          meta: { subscriberId },
        });
      }
      return;
    }
    await this.server.receive(this, message);
  }

  private setState(state: RelayState): void {
    this.state = state;
    for (const l of this.listeners) l(state);
  }
}

export type RelayState = "idle" | "connecting" | "open" | "closed" | "error";

export function attachSseRelay(server: MicroMcpServer, options: SseRelayOptions): SseRelayTransport {
  const transport = new SseRelayTransport(options);
  transport.bindServer(server);
  server.attach(transport);
  transport.start();

  // Forward in-process agent activity events out over the relay so external
  // subscribers can render presence indicators in real time. Uses a dynamic
  // import so the relay doesn't hard-depend on the presence module if it's
  // tree-shaken out.
  import("../presence/registry").then(({ onActivity }) => {
    const off = onActivity((event) => {
      if (options.activityFilter) {
        let keep: boolean;
        try {
          keep = options.activityFilter(event);
        } catch {
          // Host code threw. Drop this event, keep the subscription — the
          // alternative is a session that goes permanently silent because one
          // event was shaped unexpectedly.
          return;
        }
        if (!keep) return;
      }
      transport.send({
        jsonrpc: "2.0",
        method: "notifications/agent_activity",
        params: event as any,
      });
    });
    // Tear down the subscription when the transport closes.
    const origClose = transport.close.bind(transport);
    transport.close = () => {
      off();
      origClose();
    };
  }).catch(() => {
    // Presence module unavailable — silently no-op (relay still works).
  });

  return transport;
}

/**
 * Session-token utilities. The token is a high-entropy secret; possession
 * grants read/write on the session. We don't HMAC frames — frames carry
 * the token directly (which is fine for in-process / same-origin / TLS
 * transports). For lower-trust transports, host apps can layer signing
 * on top of the BroadcastChannelTransport.
 */

const TOKEN_BYTES = 24; // 192 bits, base64url-encoded → 32 chars

export type SessionDescriptor = {
  /** Stable session identifier. Channel name = `fai:share:${id}`. */
  id: string;
  /** Secret token. Treat as a password — anyone with it can read/write. */
  token: string;
  /** Pretty hash for display (first 8 chars of token). */
  display: string;
};

export function createSessionDescriptor(): SessionDescriptor {
  const id = randomId(8);
  const token = randomToken();
  return { id, token, display: token.slice(0, 8) };
}

export function describeSession(id: string, token: string): SessionDescriptor {
  return { id, token, display: token.slice(0, 8) };
}

/**
 * Build the shareable URL for the current page (preserves path, adds
 * session+token in the URL FRAGMENT).
 *
 * The token goes in the `#fragment`, never the `?query`: a fragment is never
 * transmitted to the server, so it can't leak through access/proxy logs or the
 * `Referer` header sent to third-party assets on the page. The recipient reads
 * it back with {@link readSessionFromUrl}. (The on-wire relay leg still sends
 * `?token=` today — moving that off the query is the larger transport change.)
 */
export function buildShareUrl(
  descriptor: SessionDescriptor,
  baseUrl: string = typeof window !== "undefined" ? window.location.href.split("?")[0] : "",
): string {
  const u = new URL(baseUrl);
  u.hash = new URLSearchParams({ session: descriptor.id, token: descriptor.token }).toString();
  return u.toString();
}

/** Build the JSON config form (suitable for Claude Desktop / Cline / etc.). */
export function buildShareConfig(descriptor: SessionDescriptor, transport = "broadcast-channel") {
  return {
    name: `whiteboard-${descriptor.id}`,
    transport,
    session: descriptor.id,
    token: descriptor.token,
    channel: `fai:share:${descriptor.id}`,
    protocol_version: "2025-06-18",
  };
}

/**
 * Read session descriptor from the current URL, or null if not a shared link.
 * Prefers the fragment (the non-leaking form {@link buildShareUrl} now emits),
 * falling back to the query string for links minted before that change.
 */
export function readSessionFromUrl(): SessionDescriptor | null {
  if (typeof window === "undefined") return null;
  const url = new URL(window.location.href);
  const frag = new URLSearchParams(url.hash.replace(/^#/, ""));
  const id = frag.get("session") ?? url.searchParams.get("session");
  const token = frag.get("token") ?? url.searchParams.get("token");
  if (!id || !token) return null;
  return describeSession(id, token);
}

function randomToken(): string {
  const bytes = new Uint8Array(TOKEN_BYTES);
  crypto.getRandomValues(bytes);
  return base64Url(bytes);
}

function randomId(len: number): string {
  const bytes = new Uint8Array(Math.ceil((len * 3) / 4));
  crypto.getRandomValues(bytes);
  return base64Url(bytes).slice(0, len);
}

function base64Url(bytes: Uint8Array): string {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** Constant-time string compare so a mismatched token leaks no timing info. */
export function constantTimeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

import type {
  BoardItem,
  ConnectorItem,
  RemoteCursor,
  ShapeItem,
  ShapeKind,
  StickyNoteItem,
  Stroke,
  Viewport,
} from "@particle-academy/fancy-whiteboard";
import { textResult, errorResult } from "../mcp/server";
import type { ToolHost } from "../mcp/tool-host";
import type { JsonObject } from "../mcp/types";
import type { Bridge } from "./types";
import { wrapToolWithActivity } from "../presence/wrap-tool-with-activity";
import type { AgentTarget } from "../presence/types";
import { pushUndoEntry } from "../undo/undo-stack";
import { ensureUndoToolsRegistered } from "../undo/undo-tools";

/**
 * State accessors / mutators the bridge needs from the host. The host owns
 * whiteboard state (controlled props on fancy-whiteboard components); the
 * bridge calls into these to read or change it.
 */
export type WhiteboardBridgeAdapter = {
  getNotes: () => StickyNoteItem[];
  setNotes: (next: StickyNoteItem[] | ((prev: StickyNoteItem[]) => StickyNoteItem[])) => void;
  getShapes: () => ShapeItem[];
  setShapes: (next: ShapeItem[] | ((prev: ShapeItem[]) => ShapeItem[])) => void;
  getConnectors: () => ConnectorItem[];
  setConnectors: (next: ConnectorItem[] | ((prev: ConnectorItem[]) => ConnectorItem[])) => void;
  getStrokes: () => Stroke[];
  setStrokes: (next: Stroke[] | ((prev: Stroke[]) => Stroke[])) => void;
  getViewport: () => Viewport;
  setViewport: (next: Viewport) => void;
  /** Optional: agent presence cursor (for the visualizer). */
  setAgentCursor?: (cursor: RemoteCursor | null) => void;
};

export type WhiteboardBridgeOptions = {
  adapter: WhiteboardBridgeAdapter;
  /** Identity used when the agent stamps authorId on items / cursor. */
  agent?: { id: string; name?: string; color?: string };
};

const DEFAULT_AGENT = { id: "agent", name: "Agent", color: "#a855f7" };
const VALID_SHAPES: ShapeKind[] = ["rect", "rounded-rect", "ellipse", "diamond", "triangle", "line", "arrow", "text"];

const num = (v: unknown, fallback?: number): number =>
  typeof v === "number" && Number.isFinite(v) ? v : fallback ?? 0;
const str = (v: unknown, fallback = ""): string => (typeof v === "string" ? v : fallback);
const bool = (v: unknown, fallback = false): boolean => (typeof v === "boolean" ? v : fallback);

const newId = (prefix: string) =>
  `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;

/**
 * registerWhiteboardBridge — wires a full MCP tool set against a fancy-
 * whiteboard session controlled by the host. Returns a Bridge handle the
 * host can dispose to tear everything down.
 */
export function registerWhiteboardBridge(
  host: ToolHost,
  options: WhiteboardBridgeOptions,
): Bridge {
  const { adapter } = options;
  const agent = { ...DEFAULT_AGENT, ...(options.agent ?? {}) };
  const disposers: Array<() => void> = [];

  // Register agent_undo / agent_redo / agent_history once per server. Idempotent.
  ensureUndoToolsRegistered(host, { defaultAgentId: agent.id });

  // Cursor narration is the agent's responsibility — call
  // whiteboard_set_agent_cursor as a separate prerequisite before any
  // mutation. This keeps the protocol honest: each tool does one thing.

  // Activity-target resolver shared by every mutation tool. Pulls the id
  // from the freshly-created item (structuredContent) when present, falls
  // back to the args id (for update/delete tools).
  const wbTarget = (args: any, result: any): AgentTarget => ({
    kind: "whiteboard",
    elementId: (result?.structuredContent?.id as string | undefined) ?? (args?.id as string | undefined),
  });


  const reg = (
    name: string,
    description: string,
    inputProperties: Record<string, unknown>,
    required: string[],
    handler: (args: JsonObject) => Promise<any> | any,
    /** Optional: resolve the activity target so the presence layer can render
     *  a focus indicator on the touched element. Read tools omit this. */
    resolveTarget?: (args: JsonObject, result: any) => AgentTarget | null,
  ) => {
    const wrapped = async (args: JsonObject) => {
      try {
        return await handler(args);
      } catch (e) {
        return errorResult(e instanceof Error ? e.message : String(e));
      }
    };
    const final = resolveTarget
      ? wrapToolWithActivity(wrapped, {
          toolName: name,
          agent: { id: agent.id, name: agent.name, color: agent.color },
          kind: "whiteboard",
          resolveTarget: ({ args, result }) => resolveTarget(args, result),
        })
      : wrapped;
    disposers.push(
      host.registerTool(
        {
          name,
          description,
          inputSchema: {
            type: "object",
            properties: inputProperties as any,
            required,
            additionalProperties: false,
          },
        },
        final as any,
      ),
    );
  };

  // ───────────── Read tools ─────────────

  reg("whiteboard_get_state", "Get the full board state: viewport, all items, strokes.", {}, [], () => {
    const state = {
      viewport: adapter.getViewport(),
      notes: adapter.getNotes(),
      shapes: adapter.getShapes(),
      connectors: adapter.getConnectors(),
      strokes: adapter.getStrokes(),
    };
    return textResult(JSON.stringify(state, null, 2), state);
  });

  reg("whiteboard_list_items", "List notes, shapes, and connectors with id, kind, and bounds.", {}, [], () => {
    const items: Array<{ id: string; kind: string; summary: string }> = [];
    for (const n of adapter.getNotes()) {
      items.push({
        id: n.id,
        kind: "sticky",
        summary: `"${(n.text ?? "").slice(0, 40)}" @(${Math.round(n.x)},${Math.round(n.y)}) ${n.width}×${n.height}`,
      });
    }
    for (const s of adapter.getShapes()) {
      items.push({
        id: s.id,
        kind: `shape:${s.shape}`,
        summary: `${s.text ? `"${s.text}" ` : ""}@(${Math.round(s.x)},${Math.round(s.y)}) ${s.width}×${s.height}`,
      });
    }
    for (const c of adapter.getConnectors()) {
      items.push({ id: c.id, kind: "connector", summary: `from=${JSON.stringify(c.from)} to=${JSON.stringify(c.to)}` });
    }
    return textResult(items.map((i) => `${i.kind} ${i.id}: ${i.summary}`).join("\n") || "(empty board)", items);
  });

  reg(
    "whiteboard_get_item",
    "Get a single item (sticky / shape / connector) by id.",
    { id: { type: "string" } },
    ["id"],
    (args) => {
      const id = str(args.id);
      const all: BoardItem[] = [...adapter.getNotes(), ...adapter.getShapes(), ...adapter.getConnectors()];
      const found = all.find((x) => x.id === id);
      if (!found) return errorResult(`No item with id ${id}`);
      return textResult(JSON.stringify(found, null, 2), found);
    },
  );

  // ───────────── Sticky CRUD ─────────────

  reg(
    "whiteboard_add_sticky",
    "Add a sticky note. Position is in world coordinates.",
    {
      x: { type: "number" },
      y: { type: "number" },
      text: { type: "string" },
      width: { type: "number" },
      height: { type: "number" },
      color: { type: "string", description: "CSS color, e.g. #fde68a" },
    },
    ["x", "y"],
    async (args) => {
      const x = num(args.x);
      const y = num(args.y);
      const width = num(args.width, 180);
      const height = num(args.height, 140);
// (cursor narration is now an explicit separate tool call)
      const note: StickyNoteItem = {
        id: newId("n"),
        kind: "sticky",
        x, y, width, height,
        text: str(args.text),
        color: typeof args.color === "string" ? args.color : "#fde68a",
        authorId: agent.id,
      };
      adapter.setNotes((all) => [...all, note]);
      pushUndoEntry(agent.id, {
        timestamp: Date.now(),
        bridgeId: "whiteboard",
        action: "whiteboard_add_sticky",
        label: `Added sticky ${note.id}`,
        undo: () => adapter.setNotes((all) => all.filter((n) => n.id !== note.id)),
        redo: () => adapter.setNotes((all) => [...all, note]),
      });
      return textResult(`Added sticky ${note.id}`, note);
    },
    wbTarget,
  );

  reg(
    "whiteboard_stream_text",
    "Type text into a sticky note character-by-character so the human can read it forming. The tool returns once streaming finishes.",
    {
      id: { type: "string" },
      text: { type: "string" },
      cps: { type: "number", description: "Characters per second. Default 25." },
      append: { type: "boolean", description: "Append to existing text instead of replacing. Default false." },
    },
    ["id", "text"],
    async (args) => {
      const id = str(args.id);
      const target = str(args.text);
      const cps = Math.max(1, num(args.cps, 25));
      const append = bool(args.append);
      const startNote = adapter.getNotes().find((n) => n.id === id);
      if (!startNote) return errorResult(`No sticky with id ${id}`);
      const base = append ? (startNote.text ?? "") : "";
      const interval = Math.max(8, Math.round(1000 / cps));
      for (let i = 0; i <= target.length; i++) {
        const nextText = base + target.slice(0, i);
        adapter.setNotes((all) => all.map((n) => (n.id === id ? { ...n, text: nextText } : n)));
        if (i < target.length) await new Promise((r) => setTimeout(r, interval));
      }
      return textResult(`Streamed ${target.length} chars to ${id}`, { id, text: base + target });
    },
  );

  reg(
    "whiteboard_update_sticky",
    "Update fields on a sticky note. Only provided fields are changed.",
    {
      id: { type: "string" },
      x: { type: "number" },
      y: { type: "number" },
      width: { type: "number" },
      height: { type: "number" },
      text: { type: "string" },
      color: { type: "string" },
    },
    ["id"],
    async (args) => {
      const id = str(args.id);
      const existing = adapter.getNotes().find((n) => n.id === id);
      if (!existing) return errorResult(`No sticky with id ${id}`);
      const nextX = args.x !== undefined ? num(args.x) : existing.x;
      const nextY = args.y !== undefined ? num(args.y) : existing.y;
      const nextW = args.width !== undefined ? num(args.width) : existing.width;
      const nextH = args.height !== undefined ? num(args.height) : existing.height;
// (cursor narration is now an explicit separate tool call)
      let updated: StickyNoteItem | null = null;
      adapter.setNotes((all) =>
        all.map((n) => {
          if (n.id !== id) return n;
          updated = {
            ...n,
            x: nextX, y: nextY, width: nextW, height: nextH,
            ...(args.text !== undefined ? { text: str(args.text) } : {}),
            ...(args.color !== undefined ? { color: str(args.color) } : {}),
          };
          return updated;
        }),
      );
      return textResult(`Updated sticky ${id}`, updated);
    },
    wbTarget,
  );

  // ───────────── Shape CRUD ─────────────

  reg(
    "whiteboard_add_shape",
    `Add a shape. Kind must be one of: ${VALID_SHAPES.join(", ")}.`,
    {
      shape: { type: "string", enum: VALID_SHAPES },
      x: { type: "number" },
      y: { type: "number" },
      width: { type: "number" },
      height: { type: "number" },
      text: { type: "string" },
      fill: { type: "string" },
      stroke: { type: "string" },
      flipX: { type: "boolean" },
      flipY: { type: "boolean" },
    },
    ["shape", "x", "y", "width", "height"],
    async (args) => {
      const kind = str(args.shape) as ShapeKind;
      if (!VALID_SHAPES.includes(kind)) return errorResult(`Invalid shape kind: ${kind}`);
      const x = num(args.x);
      const y = num(args.y);
      const width = num(args.width);
      const height = num(args.height);
// (cursor narration is now an explicit separate tool call)
      const shape: ShapeItem = {
        id: newId("s"),
        kind: "shape",
        shape: kind,
        x, y, width, height,
        ...(args.text !== undefined ? { text: str(args.text) } : {}),
        ...(args.fill !== undefined ? { fill: str(args.fill) } : {}),
        ...(args.stroke !== undefined ? { stroke: str(args.stroke) } : {}),
        ...(args.flipX !== undefined ? { flipX: bool(args.flipX) } : {}),
        ...(args.flipY !== undefined ? { flipY: bool(args.flipY) } : {}),
      };
      adapter.setShapes((all) => [...all, shape]);
      return textResult(`Added ${kind} ${shape.id}`, shape);
    },
    wbTarget,
  );

  reg(
    "whiteboard_update_shape",
    "Update fields on a shape.",
    {
      id: { type: "string" },
      x: { type: "number" },
      y: { type: "number" },
      width: { type: "number" },
      height: { type: "number" },
      text: { type: "string" },
      fill: { type: "string" },
      stroke: { type: "string" },
    },
    ["id"],
    async (args) => {
      const id = str(args.id);
      const existing = adapter.getShapes().find((s) => s.id === id);
      if (!existing) return errorResult(`No shape with id ${id}`);
      const nextX = args.x !== undefined ? num(args.x) : existing.x;
      const nextY = args.y !== undefined ? num(args.y) : existing.y;
      const nextW = args.width !== undefined ? num(args.width) : existing.width;
      const nextH = args.height !== undefined ? num(args.height) : existing.height;
// (cursor narration is now an explicit separate tool call)
      let updated: ShapeItem | null = null;
      adapter.setShapes((all) =>
        all.map((s) => {
          if (s.id !== id) return s;
          updated = {
            ...s,
            x: nextX, y: nextY, width: nextW, height: nextH,
            ...(args.text !== undefined ? { text: str(args.text) } : {}),
            ...(args.fill !== undefined ? { fill: str(args.fill) } : {}),
            ...(args.stroke !== undefined ? { stroke: str(args.stroke) } : {}),
          };
          return updated;
        }),
      );
      return textResult(`Updated shape ${id}`, updated);
    },
    wbTarget,
  );

  // ───────────── Connectors ─────────────

  reg(
    "whiteboard_add_connector",
    "Connect two items by id, or specify explicit world-space points.",
    {
      from: { description: "Item id (string) or {x,y}" },
      to: { description: "Item id (string) or {x,y}" },
      color: { type: "string" },
    },
    ["from", "to"],
    (args) => {
      const c: ConnectorItem = {
        id: newId("c"),
        kind: "connector",
        from: args.from as any,
        to: args.to as any,
        ...(args.color !== undefined ? { color: str(args.color) } : {}),
      };
      adapter.setConnectors((all) => [...all, c]);
      return textResult(`Added connector ${c.id}`, c);
    },
    wbTarget,
  );

  // ───────────── Drawing ─────────────

  reg(
    "whiteboard_add_stroke",
    "Add a freeform pen stroke. Points are absolute screen coords (matching the Drawing layer).",
    {
      points: {
        type: "array",
        description: "Array of {x,y} points",
      },
      color: { type: "string" },
      size: { type: "number" },
    },
    ["points"],
    (args) => {
      const points = (Array.isArray(args.points) ? args.points : []).map((p: any) => ({
        x: num(p?.x),
        y: num(p?.y),
      }));
      if (!points.length) return errorResult("Stroke requires at least one point");
      const stroke: Stroke = {
        id: newId("st"),
        points,
        color: typeof args.color === "string" ? args.color : "#0f172a",
        size: typeof args.size === "number" ? args.size : 2,
        authorId: agent.id,
      };
      adapter.setStrokes((all) => [...all, stroke]);
      return textResult(`Added stroke ${stroke.id} (${points.length} points)`, stroke);
    },
    wbTarget,
  );

  // ───────────── Generic delete ─────────────

  reg(
    "whiteboard_delete_item",
    "Remove any item by id (sticky / shape / connector / stroke).",
    { id: { type: "string" } },
    ["id"],
    (args) => {
      const id = str(args.id);
      // Snapshot the items being removed so undo can re-insert them.
      const removedNotes = adapter.getNotes().filter((x) => x.id === id);
      const removedShapes = adapter.getShapes().filter((x) => x.id === id);
      const removedConnectors = adapter.getConnectors().filter((x) => x.id === id);
      const removedStrokes = adapter.getStrokes().filter((x) => x.id === id);
      const removed = removedNotes.length + removedShapes.length + removedConnectors.length + removedStrokes.length > 0;
      if (!removed) return errorResult(`No item with id ${id}`);
      adapter.setNotes((all) => all.filter((x) => x.id !== id));
      adapter.setShapes((all) => all.filter((x) => x.id !== id));
      adapter.setConnectors((all) => all.filter((x) => x.id !== id));
      adapter.setStrokes((all) => all.filter((x) => x.id !== id));
      pushUndoEntry(agent.id, {
        timestamp: Date.now(),
        bridgeId: "whiteboard",
        action: "whiteboard_delete_item",
        label: `Deleted ${id}`,
        undo: () => {
          if (removedNotes.length) adapter.setNotes((all) => [...all, ...removedNotes]);
          if (removedShapes.length) adapter.setShapes((all) => [...all, ...removedShapes]);
          if (removedConnectors.length) adapter.setConnectors((all) => [...all, ...removedConnectors]);
          if (removedStrokes.length) adapter.setStrokes((all) => [...all, ...removedStrokes]);
        },
        redo: () => {
          adapter.setNotes((all) => all.filter((x) => x.id !== id));
          adapter.setShapes((all) => all.filter((x) => x.id !== id));
          adapter.setConnectors((all) => all.filter((x) => x.id !== id));
          adapter.setStrokes((all) => all.filter((x) => x.id !== id));
        },
      });
      return textResult(`Deleted ${id}`);
    },
    wbTarget,
  );

  // ───────────── Viewport / agent presence ─────────────

  reg(
    "whiteboard_set_viewport",
    "Pan / zoom the viewport.",
    { x: { type: "number" }, y: { type: "number" }, zoom: { type: "number" } },
    [],
    (args) => {
      const v = adapter.getViewport();
      const next: Viewport = {
        x: args.x !== undefined ? num(args.x) : v.x,
        y: args.y !== undefined ? num(args.y) : v.y,
        zoom: args.zoom !== undefined ? num(args.zoom) : v.zoom,
      };
      adapter.setViewport(next);
      return textResult(`Viewport → ${JSON.stringify(next)}`, next);
    },
    wbTarget,
  );

  reg(
    "whiteboard_set_agent_cursor",
    "Move the agent's presence cursor (or pass null to hide it).",
    {
      x: { type: "number" },
      y: { type: "number" },
      hide: { type: "boolean" },
    },
    [],
    (args) => {
      if (!adapter.setAgentCursor) return errorResult("Host did not provide setAgentCursor");
      if (bool(args.hide)) {
        adapter.setAgentCursor(null);
        return textResult("Agent cursor hidden");
      }
      const cursor: RemoteCursor = {
        userId: agent.id,
        name: agent.name,
        color: agent.color,
        x: num(args.x),
        y: num(args.y),
      };
      adapter.setAgentCursor(cursor);
      return textResult(`Cursor → (${cursor.x}, ${cursor.y})`, cursor);
    },
    wbTarget,
  );

  return {
    id: "whiteboard",
    title: "Whiteboard",
    dispose: () => {
      for (const d of disposers) d();
      adapter.setAgentCursor?.(null);
    },
  };
}

import type { ToolHost } from "../mcp/tool-host";

/**
 * Bridge — registers a cohesive set of MCP tools/resources for a single
 * fancy-* package or app concern. Each bridge owns its lifecycle: install
 * to register handlers on a server, dispose to remove them.
 */
export type Bridge = {
  /** Stable identifier — surfaces in agent activity logs. */
  id: string;
  /** Human-readable label for UI. */
  title?: string;
  /** Disposes the bridge. Must remove every tool it registered. */
  dispose: () => void;
};

export type BridgeFactory<TOptions> = (
  host: ToolHost,
  options: TOptions,
) => Bridge;

/**
 * Minimal MCP (Model Context Protocol) types — covers the subset this
 * package implements: initialize, tools/list, tools/call, plus JSON-RPC.
 *
 * Aligned with the public MCP spec but trimmed to v0.1 needs. See
 * https://spec.modelcontextprotocol.io/ for the full surface.
 */

export type JsonValue =
  | string
  | number
  | boolean
  | null
  | { [key: string]: JsonValue }
  | JsonValue[];

export type JsonObject = { [key: string]: JsonValue };

export type JsonRpcId = string | number | null;

export type JsonRpcRequest = {
  jsonrpc: "2.0";
  id: JsonRpcId;
  method: string;
  params?: JsonObject;
};

export type JsonRpcNotification = {
  jsonrpc: "2.0";
  method: string;
  params?: JsonObject;
};

export type JsonRpcSuccess = {
  jsonrpc: "2.0";
  id: JsonRpcId;
  result: JsonValue;
};

export type JsonRpcError = {
  jsonrpc: "2.0";
  id: JsonRpcId;
  error: { code: number; message: string; data?: JsonValue };
};

export type JsonRpcMessage = JsonRpcRequest | JsonRpcNotification | JsonRpcSuccess | JsonRpcError;

export const JSONRPC_PARSE_ERROR = -32700;
export const JSONRPC_INVALID_REQUEST = -32600;
export const JSONRPC_METHOD_NOT_FOUND = -32601;
export const JSONRPC_INVALID_PARAMS = -32602;
export const JSONRPC_INTERNAL_ERROR = -32603;

export type ServerCapabilities = {
  tools?: { listChanged?: boolean };
  resources?: { listChanged?: boolean; subscribe?: boolean };
  prompts?: { listChanged?: boolean };
  logging?: Record<string, never>;
  experimental?: Record<string, JsonValue>;
};

export type ServerInfo = {
  name: string;
  version: string;
  title?: string;
};

export type InitializeResult = {
  protocolVersion: string;
  capabilities: ServerCapabilities;
  serverInfo: ServerInfo;
  instructions?: string;
};

export type ToolInputSchema = {
  /** The JSON Schema dialect, when a server states it (e.g. draft-07). */
  $schema?: string;
  type: "object";
  properties?: Record<string, JsonValue>;
  required?: string[];
  additionalProperties?: boolean;
};

/** Behaviour hints a client may use when presenting or gating a tool. */
export type ToolAnnotations = {
  title?: string;
  readOnlyHint?: boolean;
  destructiveHint?: boolean;
  idempotentHint?: boolean;
  openWorldHint?: boolean;
};

/**
 * A tool as `tools/list` reports it. Every field is passed to the client
 * verbatim, so the optional ones below are the spec's, not extensions.
 */
export type ToolDefinition = {
  name: string;
  title?: string;
  description?: string;
  inputSchema: ToolInputSchema;
  /** JSON Schema for `structuredContent`, when the tool returns it. */
  outputSchema?: ToolInputSchema;
  annotations?: ToolAnnotations;
  /** 2025-11-25: whether the tool may run as a task. */
  execution?: { taskSupport?: "forbidden" | "optional" | "required" };
  _meta?: { [key: string]: JsonValue };
};

export type ContentBlock =
  | { type: "text"; text: string }
  | { type: "image"; data: string; mimeType: string }
  | { type: "resource"; resource: { uri: string; text?: string; mimeType?: string } };

export type CallToolResult = {
  content: ContentBlock[];
  isError?: boolean;
  /** Structured tool output — non-spec but useful for typed bridges. */
  structuredContent?: JsonValue;
};

/** Handler signature for a tool registered on the MicroMcpServer. */
export type ToolCallContext = { transport?: unknown };
export type ToolHandler = (args: JsonObject, context?: ToolCallContext) => Promise<CallToolResult> | CallToolResult;

/** Internal record kept by the server. */
export type RegisteredTool = {
  definition: ToolDefinition;
  handler: ToolHandler;
};

export const MCP_PROTOCOL_VERSION = "2025-06-18";

import type {
  CallToolResult,
  JsonObject,
  RegisteredTool,
  ToolDefinition,
  ToolHandler,
} from "./types";

/**
 * ToolHost — the minimal surface a bridge needs to register its tools.
 *
 * Bridges (whiteboard, flow, sheets, code, charts, screens, scene, form)
 * speak only through this interface. The MCP server implements it
 * alongside its transport / JSON-RPC duties, and the standalone
 * {@link ToolRegistry} implements it for in-process agents that don't
 * need any of MCP's wire framing.
 *
 * Net effect: every bridge works equally well behind an MCP server
 * (browser ↔ external agents over SSE) or behind a plain registry
 * (in-process agent calling `host.callTool("sheet_set_cell", { … })`).
 */
export interface ToolHost {
  /** Register a tool. Returns a disposer that unregisters it. */
  registerTool(definition: ToolDefinition, handler: ToolHandler): () => void;

  /** Look up an already-registered tool's definition + handler, or null. */
  getTool(name: string): RegisteredTool | null;

  /** Snapshot of all currently-registered tool definitions. */
  listTools(): ToolDefinition[];

  /**
   * Invoke a registered tool directly, bypassing any transport layer.
   * Throws if no tool is registered under `name`.
   *
   * This is the single entry point in-process agents use to drive the
   * surface — no JSON-RPC framing, no transport plumbing.
   */
  callTool(name: string, args?: JsonObject): Promise<CallToolResult>;
}

/**
 * Standalone in-memory ToolHost. Use this when no MCP server is needed —
 * e.g. an in-process agent that just wants to register the same bridges
 * and call them directly.
 *
 * Example:
 *
 *   const host = new ToolRegistry();
 *   registerSheetsBridge(host, { adapter });
 *   const result = await host.callTool("sheet_set_cell", { address: "B3", value: 42 });
 *
 * Pair with a MicroMcpServer in the same app to expose the same tools
 * to remote agents over SSE while in-process agents still get
 * zero-overhead direct calls.
 */
export class ToolRegistry implements ToolHost {
  protected readonly tools = new Map<string, RegisteredTool>();

  /**
   * Tools that existed and were withdrawn, kept so a call that races an unmount
   * can say WHICH thing happened.
   *
   * The tool surface is dynamic by design — "site tools always, page tools while
   * mounted" — so an agent deciding to call a tool while the human navigates
   * away is normal traffic, not an edge case. Reporting that as `Unknown tool`
   * is the least useful thing available: it reads as "the agent is broken" or
   * "you asked for something imaginary", when the truth is "that surface just
   * closed".
   *
   * Names only. Nothing about the handler is retained, so this cannot keep a
   * disposed surface alive.
   */
  protected readonly withdrawn = new Set<string>();

  registerTool(definition: ToolDefinition, handler: ToolHandler): () => void {
    this.tools.set(definition.name, { definition, handler });
    // A remounted surface must stop apologising for a previous unmount.
    this.withdrawn.delete(definition.name);
    this.onToolsChanged();
    return () => {
      if (this.tools.delete(definition.name)) {
        this.withdrawn.add(definition.name);
        this.onToolsChanged();
      }
    };
  }

  /** Why `name` is not callable, phrased for whoever has to act on it. */
  protected missingToolMessage(name: string): string {
    return this.withdrawn.has(name)
      ? `Tool "${name}" was withdrawn: the surface it targets is no longer mounted. `
        + `Call tools/list for the current surface — the site-wide tools remain available.`
      : `Unknown tool: ${name}`;
  }

  getTool(name: string): RegisteredTool | null {
    return this.tools.get(name) ?? null;
  }

  listTools(): ToolDefinition[] {
    return Array.from(this.tools.values()).map((t) => t.definition);
  }

  async callTool(name: string, args: JsonObject = {}): Promise<CallToolResult> {
    const tool = this.tools.get(name);
    if (!tool) {
      throw new Error(this.missingToolMessage(name));
    }
    return tool.handler(args);
  }

  /**
   * Hook for subclasses (e.g. MicroMcpServer) to notify subscribers
   * when the tool catalog changes. Default no-op.
   */
  protected onToolsChanged(): void {}
}

/**
 * Presence layer types. These now live in `@particle-academy/fancy-auto-common`
 * as the unified `Auto*` family (shared with fancy-flow's FlowRunnerUx). The
 * historical `Agent*` names are kept here as back-compat aliases so existing
 * consumers (cursors, highlights, fancy-screens presence) don't change.
 */
export type {
  AutoTargetKind as AgentTargetKind,
  AutoTarget as AgentTarget,
  AutoActivityEvent as AgentActivityEvent,
  AutoActivityListener as AgentActivityListener,
  ActivityFilter,
} from "@particle-academy/fancy-auto-common";

/**
 * In-process registry of activity events. Now backed by the shared bus in
 * `@particle-academy/fancy-auto-common`, so agent activity (here) and flow
 * activity (fancy-flow's FlowRunnerUx) land in ONE stream — presence layers
 * render both. Re-exported under the same names for back-compat.
 */
export {
  emitActivity,
  onActivity,
  readActivityHistory,
  resetActivityRegistry,
} from "@particle-academy/fancy-auto-common";

import type { CallToolResult } from "../mcp/types";
import { emitActivity } from "./registry";
import type { AgentTarget } from "./types";

export type ActivityAgent = { id: string; name?: string; color?: string };

export type ActivityResolverContext<TArgs = Record<string, unknown>> = {
  /** Tool name as registered. */
  toolName: string;
  /** Arguments the tool was called with. */
  args: TArgs;
  /** The CallToolResult the underlying handler produced. */
  result: CallToolResult;
};

/**
 * Resolves an `AgentTarget` for an executed tool. Bridges declare one of
 * these per registration so the wrapper knows which surface / element /
 * screen the activity belongs to.
 *
 * The resolver runs AFTER the tool handler so it can inspect the result
 * (e.g. read a newly-created item id from `structuredContent`).
 */
export type ActivityTargetResolver<TArgs = Record<string, unknown>> = (
  ctx: ActivityResolverContext<TArgs>,
) => AgentTarget | null;

export type ToolHandler<TArgs = Record<string, unknown>> = (
  args: TArgs,
) => Promise<CallToolResult> | CallToolResult;

/**
 * wrapToolWithActivity — decorate a bridge tool handler so every successful
 * call emits an `AgentActivityEvent`. Returns a new handler with the same shape.
 *
 * Usage in a bridge:
 *
 *   server.registerTool(
 *     definition,
 *     wrapToolWithActivity(
 *       handler,
 *       { agent, kind: "whiteboard", resolveTarget: ({ args }) => ({
 *           kind: "whiteboard", elementId: args.id as string,
 *         }) },
 *     ),
 *   );
 */
export function wrapToolWithActivity<TArgs = Record<string, unknown>>(
  handler: ToolHandler<TArgs>,
  options: {
    toolName: string;
    agent: ActivityAgent;
    /** Optional fancy-screens screen id this bridge is scoped to. */
    screenId?: string;
    /** Default target kind if the resolver returns one without `kind`. */
    kind: AgentTarget["kind"];
    /** Per-call resolver. Return `null` to skip emitting (e.g. for read-only tools). */
    resolveTarget?: ActivityTargetResolver<TArgs>;
    /** Optional ttl override. */
    ttlMs?: number;
    /**
     * Build the `meta` broadcast to all relay peers. Defaults to the tool's full
     * `structuredContent`. Override to REDACT sensitive fields before fan-out —
     * e.g. the terminal bridge strips raw command/keystroke bytes so a command
     * line (or its secrets) is never broadcast verbatim to every peer.
     */
    buildMeta?: (result: CallToolResult) => Record<string, unknown> | undefined;
  },
): ToolHandler<TArgs> {
  return async (args) => {
    const result = await handler(args);
    if (result.isError) return result;

    let target: AgentTarget | null;
    if (options.resolveTarget) {
      target = options.resolveTarget({ toolName: options.toolName, args, result });
    } else {
      target = { kind: options.kind, screenId: options.screenId };
    }
    if (!target) return result;

    emitActivity({
      agentId: options.agent.id,
      agentName: options.agent.name,
      agentColor: options.agent.color,
      target: { ...target, kind: target.kind ?? options.kind, screenId: target.screenId ?? options.screenId },
      action: options.toolName,
      timestamp: Date.now(),
      meta: options.buildMeta ? options.buildMeta(result) : extractMeta(result),
      ttlMs: options.ttlMs,
    });
    return result;
  };
}

function extractMeta(result: CallToolResult): Record<string, unknown> | undefined {
  const sc = result.structuredContent;
  if (sc && typeof sc === "object" && !Array.isArray(sc)) {
    return sc as Record<string, unknown>;
  }
  return undefined;
}

import { textResult, errorResult } from "../mcp/server";
import type { ToolHost } from "../mcp/tool-host";
import { readHistory, redoOne, undoOne } from "./undo-stack";

export type UndoToolsOptions = {
  /** Default agent id when the caller doesn't pass one. */
  defaultAgentId?: string;
};

/**
 * Idempotent tracker so multiple bridges on the same server only register
 * agent_undo / agent_redo / agent_history once.
 */
const installedHosts = new WeakSet<ToolHost>();

/**
 * ensureUndoToolsRegistered — bridges call this on construction. Safe to
 * call repeatedly with the same server; subsequent calls are no-ops.
 */
export function ensureUndoToolsRegistered(host: ToolHost, options: UndoToolsOptions = {}): void {
  if (installedHosts.has(host)) return;
  installedHosts.add(host);
  registerUndoTools(host, options);
}

/**
 * registerUndoTools — add agent_undo / agent_redo / agent_history to the
 * server. Returns a disposer that unregisters all three.
 */
export function registerUndoTools(host: ToolHost, options: UndoToolsOptions = {}): () => void {
  const defaultAgent = options.defaultAgentId ?? "agent";
  const disposers: Array<() => void> = [];
  const agentOf = (args: any): string =>
    typeof args?.agentId === "string" ? args.agentId : defaultAgent;

  disposers.push(
    host.registerTool(
      {
        name: "agent_undo",
        description: "Undo the most recent action on the agent's stack. Optional agentId targets a specific agent.",
        inputSchema: {
          type: "object",
          properties: { agentId: { type: "string" } },
          additionalProperties: false,
        },
      },
      async (args) => {
        const entry = await undoOne(agentOf(args));
        if (!entry) return errorResult("Nothing to undo.");
        return textResult(`Undid: ${entry.label}`, { entry: serialize(entry) });
      },
    ),
  );

  disposers.push(
    host.registerTool(
      {
        name: "agent_redo",
        description: "Redo the most recently undone action.",
        inputSchema: {
          type: "object",
          properties: { agentId: { type: "string" } },
          additionalProperties: false,
        },
      },
      async (args) => {
        const entry = await redoOne(agentOf(args));
        if (!entry) return errorResult("Nothing to redo.");
        return textResult(`Redid: ${entry.label}`, { entry: serialize(entry) });
      },
    ),
  );

  disposers.push(
    host.registerTool(
      {
        name: "agent_history",
        description: "List the agent's undo stack (oldest first). Useful for understanding what's reversible.",
        inputSchema: {
          type: "object",
          properties: { agentId: { type: "string" } },
          additionalProperties: false,
        },
      },
      async (args) => {
        const history = readHistory(agentOf(args)).map(serialize);
        const text = history.map((e) => `${new Date(e.timestamp).toISOString()} ${e.bridgeId} ${e.action}: ${e.label}`).join("\n");
        return textResult(text || "(empty)", history);
      },
    ),
  );

  return () => disposers.forEach((d) => d());
}

function serialize(entry: import("./undo-stack").UndoEntry) {
  return {
    timestamp: entry.timestamp,
    bridgeId: entry.bridgeId,
    action: entry.action,
    label: entry.label,
  };
}

import { type CSSProperties, useEffect, useState } from "react";

export type AgentActivityHighlightProps = {
  /** Bounds of the highlighted item in the parent's coord system. */
  x: number;
  y: number;
  width: number;
  height: number;
  /** Trigger token — change it (e.g. set to Date.now()) to re-fire the pulse. */
  pulseKey?: string | number;
  /** Highlight tint. */
  color?: string;
  /** Pulse duration in ms. Defaults 1200. */
  duration?: number;
  className?: string;
  style?: CSSProperties;
};

/**
 * AgentActivityHighlight — short pulsing outline that flashes around an
 * item the agent just touched. Position the parent so this can be placed
 * absolutely matching the item's bounds.
 */
export function AgentActivityHighlight({
  x,
  y,
  width,
  height,
  pulseKey,
  color = "#a855f7",
  duration = 1200,
  className,
  style,
}: AgentActivityHighlightProps) {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (pulseKey === undefined) return;
    setVisible(true);
    const t = setTimeout(() => setVisible(false), duration);
    return () => clearTimeout(t);
  }, [pulseKey, duration]);

  if (!visible) return null;

  return (
    <div
      className={["fai-highlight", className ?? ""].filter(Boolean).join(" ")}
      style={{
        position: "absolute",
        left: x - 4,
        top: y - 4,
        width: width + 8,
        height: height + 8,
        borderRadius: 8,
        boxShadow: `0 0 0 2px ${color}, 0 0 16px ${color}66`,
        pointerEvents: "none",
        animation: `fai-pulse ${duration}ms ease-out forwards`,
        ...style,
      }}
    />
  );
}

