import React from "react";
import { Button, Select, cn } from "@particle-academy/react-fancy";
import { useSpreadsheet } from "../Spreadsheet/Spreadsheet.context";
import { defaultDecimals } from "../../engine/cell-display";

/** Toolbar button groups that can be toggled on/off */
export type ToolbarButton = "undo" | "bold" | "align" | "freeze" | "format" | "decimals" | "formulaBar";

const ALL_BUTTONS: ToolbarButton[] = ["undo", "bold", "align", "freeze", "format", "decimals", "formulaBar"];

interface SpreadsheetToolbarProps {
  children?: React.ReactNode;
  className?: string;
  /** Additional toolbar content appended after default buttons */
  extra?: React.ReactNode;
  /** Which built-in button groups to show (default: all). Omit to show everything. */
  buttons?: ToolbarButton[];
}

/**
 * Extra classes for a toolbar button.
 *
 * The buttons are `<Button variant="ghost" size="xs">` now. react-fancy's ghost
 * styling is what this string used to spell out by hand — same padding, same
 * hover, same disabled fade — so the swap keeps a dense, size-sensitive toolbar
 * dimensionally identical while picking up the shared focus ring.
 */
const btnClass = "text-[12px]";

const activeBtnClass = "bg-zinc-200 dark:bg-zinc-700";

function DefaultToolbar({ extra, buttons }: { extra?: React.ReactNode; buttons: Set<ToolbarButton> }) {
  const {
    selection,
    activeSheet,
    editingCell,
    editValue,
    updateEdit,
    confirmEdit,
    startEdit,
    setCellFormat,
    setFrozenRows,
    setFrozenCols,
    undo,
    redo,
    canUndo,
    canRedo,
    readOnly,
  } = useSpreadsheet();

  const cell = activeSheet.cells[selection.activeCell];
  const isBold = cell?.format?.bold ?? false;
  const isItalic = cell?.format?.italic ?? false;
  const textAlign = cell?.format?.textAlign ?? "left";
  const displayFormat = cell?.format?.displayFormat ?? "auto";
  const explicitDecimals = cell?.format?.decimals;

  // Detect actual decimal places from the cell's current value
  const cellValue = cell?.computedValue ?? cell?.value;
  const inferredDecimals = (() => {
    if (explicitDecimals !== undefined) return explicitDecimals;
    // A number format with no places set shows its default, so the stepper counts from what is on screen.
    const formatDefault = defaultDecimals(displayFormat);
    if (formatDefault !== undefined) return formatDefault;
    if (typeof cellValue === "number") {
      const str = String(cellValue);
      const dotIdx = str.indexOf(".");
      return dotIdx === -1 ? 0 : str.length - dotIdx - 1;
    }
    return 0;
  })();
  const currentDecimals = explicitDecimals ?? inferredDecimals;

  const selectedAddresses = [selection.activeCell];

  const handleFormulaBarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (editingCell) {
      updateEdit(e.target.value);
    } else {
      startEdit(e.target.value);
    }
  };

  const handleFormulaBarKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault();
      confirmEdit();
    }
  };

  const formulaBarValue = editingCell
    ? editValue
    : cell?.formula
      ? "=" + cell.formula
      : cell?.value != null
        ? String(cell.value)
        : "";

  const divider = <div className="mx-1 h-4 w-px bg-zinc-200 dark:bg-zinc-700" />;

  // Collect visible button groups, inserting dividers between them
  const groups: React.ReactNode[] = [];

  if (buttons.has("undo")) {
    groups.push(
      <React.Fragment key="undo">
        <Button aria-label="Undo (Ctrl+Z)" type="button" variant="ghost" size="xs" className={btnClass} onClick={undo} disabled={!canUndo || readOnly} title="Undo (Ctrl+Z)">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="1 4 1 10 7 10" /><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10" /></svg>
        </Button>
        <Button aria-label="Redo (Ctrl+Y)" type="button" variant="ghost" size="xs" className={btnClass} onClick={redo} disabled={!canRedo || readOnly} title="Redo (Ctrl+Y)">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="23 4 23 10 17 10" /><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10" /></svg>
        </Button>
      </React.Fragment>,
    );
  }

  if (buttons.has("bold")) {
    groups.push(
      <React.Fragment key="bold">
        <Button aria-label="Bold" type="button" variant="ghost" size="xs" className={cn(btnClass, isBold && activeBtnClass)} onClick={() => setCellFormat(selectedAddresses, { bold: !isBold })} disabled={readOnly} title="Bold">
          <span className="font-bold">B</span>
        </Button>
        <Button aria-label="Italic" type="button" variant="ghost" size="xs" className={cn(btnClass, isItalic && activeBtnClass)} onClick={() => setCellFormat(selectedAddresses, { italic: !isItalic })} disabled={readOnly} title="Italic">
          <span className="italic">I</span>
        </Button>
      </React.Fragment>,
    );
  }

  if (buttons.has("align")) {
    groups.push(
      <React.Fragment key="align">
        {(["left", "center", "right"] as const).map((align) => (
          <Button aria-label={`Align ${align}`} type="button" variant="ghost" size="xs" key={align} className={cn(btnClass, textAlign === align && activeBtnClass)} onClick={() => setCellFormat(selectedAddresses, { textAlign: align })} disabled={readOnly} title={`Align ${align}`}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <line x1="3" y1="6" x2="21" y2="6" />
              <line x1={align === "left" ? "3" : align === "center" ? "6" : "9"} y1="12" x2={align === "left" ? "15" : align === "center" ? "18" : "21"} y2="12" />
              <line x1="3" y1="18" x2="21" y2="18" />
            </svg>
          </Button>
        ))}
      </React.Fragment>,
    );
  }

  if (buttons.has("freeze")) {
    groups.push(
      <React.Fragment key="freeze">
        <Button type="button" variant="ghost" size="xs"
          className={cn(btnClass, activeSheet.frozenRows > 0 && activeBtnClass)}
          onClick={() => {
            if (activeSheet.frozenRows > 0) { setFrozenRows(0); }
            else { const row = selection.activeCell.match(/\d+/); setFrozenRows(row ? parseInt(row[0], 10) - 1 || 1 : 1); }
          }}
          disabled={readOnly}
          aria-label={activeSheet.frozenRows > 0 ? `Unfreeze rows (${activeSheet.frozenRows} frozen)` : "Freeze rows above current cell"}
          title={activeSheet.frozenRows > 0 ? `Unfreeze rows (${activeSheet.frozenRows} frozen)` : "Freeze rows above current cell"}
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            <line x1="3" y1="9" x2="21" y2="9" /><line x1="3" y1="4" x2="21" y2="4" />
            <line x1="3" y1="14" x2="21" y2="14" strokeDasharray="3 3" /><line x1="3" y1="19" x2="21" y2="19" strokeDasharray="3 3" />
          </svg>
        </Button>
        <Button type="button" variant="ghost" size="xs"
          className={cn(btnClass, activeSheet.frozenCols > 0 && activeBtnClass)}
          onClick={() => {
            if (activeSheet.frozenCols > 0) { setFrozenCols(0); }
            else {
              const colMatch = selection.activeCell.match(/^([A-Z]+)/);
              if (colMatch) { const col = colMatch[1].split("").reduce((acc, ch) => acc * 26 + ch.charCodeAt(0) - 64, 0) - 1; setFrozenCols(col || 1); }
              else { setFrozenCols(1); }
            }
          }}
          disabled={readOnly}
          aria-label={activeSheet.frozenCols > 0 ? `Unfreeze columns (${activeSheet.frozenCols} frozen)` : "Freeze columns left of current cell"}
          title={activeSheet.frozenCols > 0 ? `Unfreeze columns (${activeSheet.frozenCols} frozen)` : "Freeze columns left of current cell"}
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            <line x1="9" y1="3" x2="9" y2="21" /><line x1="4" y1="3" x2="4" y2="21" />
            <line x1="14" y1="3" x2="14" y2="21" strokeDasharray="3 3" /><line x1="19" y1="3" x2="19" y2="21" strokeDasharray="3 3" />
          </svg>
        </Button>
      </React.Fragment>,
    );
  }

  if (buttons.has("format")) {
    groups.push(
      <React.Fragment key="format">
        {/* Was a bare <select> with a `title` and no label, so it was
            announced as an unlabelled combobox. <Select> carries the name. */}
        <Select
          aria-label="Cell format"
          size="sm"
          // <Select> is full-width by default; the bare <select> it replaced was
          // h-6 and content-sized, so without this it eats the whole toolbar.
          className="w-36 text-[11px]"
          value={displayFormat}
          onValueChange={(v) => setCellFormat(selectedAddresses, { displayFormat: v as any })}
          disabled={readOnly}
          list={[
            { value: "auto", label: "Auto" },
            { value: "text", label: "Text" },
            { value: "number", label: "Number" },
            { value: "currency", label: "Currency ($)" },
            { value: "percentage", label: "Percentage (%)" },
            { value: "date", label: "Date" },
            { value: "datetime", label: "Date & Time" },
          ]}
        />
      </React.Fragment>,
    );
  }

  if (buttons.has("decimals")) {
    groups.push(
      <React.Fragment key="decimals">
        <Button aria-label={`Decrease decimal places (currently ${currentDecimals})`} type="button" variant="ghost" size="xs" className={btnClass} onClick={() => setCellFormat(selectedAddresses, { decimals: Math.max(0, currentDecimals - 1) })} disabled={readOnly || currentDecimals <= 0} title={`Decrease decimal places (currently ${currentDecimals})`}>
          <span className="text-[10px]">.0</span><span className="text-[8px]">←</span>
        </Button>
        <Button aria-label={`Increase decimal places (currently ${currentDecimals})`} type="button" variant="ghost" size="xs" className={btnClass} onClick={() => setCellFormat(selectedAddresses, { decimals: currentDecimals + 1 })} disabled={readOnly} title={`Increase decimal places (currently ${currentDecimals})`}>
          <span className="text-[10px]">.00</span><span className="text-[8px]">→</span>
        </Button>
      </React.Fragment>,
    );
  }

  if (extra) {
    groups.push(<React.Fragment key="extra">{extra}</React.Fragment>);
  }

  return (
    <>
      {groups.length > 0 && (
        <div className="flex items-center gap-0.5 border-b border-zinc-200 px-1.5 py-1 dark:border-zinc-700">
          {groups.map((group, i) => (
            <React.Fragment key={i}>
              {i > 0 && divider}
              {group}
            </React.Fragment>
          ))}
        </div>
      )}

      {buttons.has("formulaBar") && (
        <div data-fancy-sheets-formula-bar="" className="flex items-center gap-2 border-b border-zinc-200 px-2 py-1 dark:border-zinc-700">
          <span className="w-12 shrink-0 text-center text-[11px] font-medium text-zinc-500 dark:text-zinc-400">
            {selection.activeCell}
          </span>
          <div className="h-4 w-px bg-zinc-200 dark:bg-zinc-700" />
          <input
            aria-label={`Formula bar — ${selection.activeCell}`}
            data-fancy-sheets-formula-input=""
            className="flex-1 bg-transparent text-[13px] outline-none dark:text-zinc-100"
            value={formulaBarValue}
            onChange={handleFormulaBarChange}
            onKeyDown={handleFormulaBarKeyDown}
            readOnly={readOnly}
            placeholder="Enter value or formula (=SUM(A1:A5))"
          />
        </div>
      )}
    </>
  );
}

export function SpreadsheetToolbar({ children, className, extra, buttons: buttonsProp }: SpreadsheetToolbarProps) {
  const buttonsSet = new Set(buttonsProp ?? ALL_BUTTONS);
  return (
    <div data-fancy-sheets-toolbar="" className={cn("", className)}>
      {children ?? <DefaultToolbar extra={extra} buttons={buttonsSet} />}
    </div>
  );
}

SpreadsheetToolbar.displayName = "SpreadsheetToolbar";

import { createContext, useContext } from "react";
import type { SpreadsheetContextValue } from "./Spreadsheet.types";

export const SpreadsheetContext = createContext<SpreadsheetContextValue | null>(null);

export function useSpreadsheet(): SpreadsheetContextValue {
  const ctx = useContext(SpreadsheetContext);
  if (!ctx) {
    throw new Error("useSpreadsheet must be used within a <Spreadsheet> component");
  }
  return ctx;
}

import { useReducer, useCallback, useMemo } from "react";
import type { CellValue, CellData, CellFormat } from "../types/cell";
import type { WorkbookData, SheetData } from "../types/sheet";
import type { SelectionState, CellRange } from "../types/selection";
import { createEmptyWorkbook, createEmptySheet } from "../types/sheet";
import { parseAddress, toAddress } from "../engine/cell-utils";
import { recalculateWorkbook } from "../engine/recalc";

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

export interface SpreadsheetState {
  workbook: WorkbookData;
  selection: SelectionState;
  editingCell: string | null;
  editValue: string;
  undoStack: WorkbookData[];
  redoStack: WorkbookData[];
}

function createInitialState(data?: WorkbookData): SpreadsheetState {
  const workbook = data ?? createEmptyWorkbook();
  return {
    workbook: recalculateWorkbook(workbook),
    selection: { activeCell: "A1", ranges: [{ start: "A1", end: "A1" }] },
    editingCell: null,
    editValue: "",
    undoStack: [],
    redoStack: [],
  };
}

// ---------------------------------------------------------------------------
// Actions
// ---------------------------------------------------------------------------

type Action =
  | { type: "SET_CELL_VALUE"; address: string; value: string }
  | { type: "SET_CELL_FORMAT"; addresses: string[]; format: Partial<CellFormat> }
  | { type: "SET_SELECTION"; cell: string }
  | { type: "EXTEND_SELECTION"; cell: string }
  | { type: "ADD_SELECTION"; cell: string }
  | { type: "SELECT_RANGE"; start: string; end: string }
  | { type: "NAVIGATE"; direction: "up" | "down" | "left" | "right"; extend?: boolean }
  | { type: "START_EDIT"; value?: string }
  | { type: "UPDATE_EDIT"; value: string }
  | { type: "CONFIRM_EDIT" }
  | { type: "CANCEL_EDIT" }
  | { type: "RESIZE_COLUMN"; col: number; width: number }
  | { type: "ADD_SHEET" }
  | { type: "RENAME_SHEET"; sheetId: string; name: string }
  | { type: "DELETE_SHEET"; sheetId: string }
  | { type: "SET_ACTIVE_SHEET"; sheetId: string }
  | { type: "SET_FROZEN_ROWS"; count: number }
  | { type: "SET_FROZEN_COLS"; count: number }
  | { type: "UNDO" }
  | { type: "REDO" }
  | { type: "SET_WORKBOOK"; workbook: WorkbookData };

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getActiveSheet(state: SpreadsheetState): SheetData {
  return state.workbook.sheets.find((s) => s.id === state.workbook.activeSheetId)!;
}

function updateActiveSheet(state: SpreadsheetState, updater: (sheet: SheetData) => SheetData): WorkbookData {
  return {
    ...state.workbook,
    sheets: state.workbook.sheets.map((s) =>
      s.id === state.workbook.activeSheetId ? updater(s) : s,
    ),
  };
}

function pushUndo(state: SpreadsheetState): { undoStack: WorkbookData[]; redoStack: WorkbookData[] } {
  const stack = [...state.undoStack, state.workbook];
  if (stack.length > 50) stack.shift();
  return { undoStack: stack, redoStack: [] };
}

function getCellDisplayValue(cell: CellData | undefined): string {
  if (!cell) return "";
  if (cell.computedValue !== undefined) return String(cell.computedValue);
  if (cell.value === null) return "";
  return String(cell.value);
}

// ---------------------------------------------------------------------------
// Reducer
// ---------------------------------------------------------------------------

function reducer(state: SpreadsheetState, action: Action): SpreadsheetState {
  switch (action.type) {
    case "SET_CELL_VALUE": {
      const history = pushUndo(state);
      const isFormula = action.value.startsWith("=");
      const cellData: CellData = isFormula
        ? { value: action.value, formula: action.value.slice(1), computedValue: null }
        : { value: isNaN(Number(action.value)) || action.value === "" ? action.value : Number(action.value) };

      // Preserve existing format and meta
      const sheet = getActiveSheet(state);
      const existing = sheet.cells[action.address];
      if (existing?.format) cellData.format = existing.format;
      if (existing?.meta) cellData.meta = existing.meta;
      if (existing?.comment) cellData.comment = existing.comment;

      // Update the cell, then recalculate ALL sheets (cross-sheet refs may depend on this)
      const updatedWorkbook = updateActiveSheet(state, (s) => ({
        ...s, cells: { ...s.cells, [action.address]: cellData },
      }));
      const workbook = recalculateWorkbook(updatedWorkbook);

      return { ...state, workbook, ...history };
    }

    case "SET_CELL_FORMAT": {
      const history = pushUndo(state);
      const workbook = updateActiveSheet(state, (s) => {
        const cells = { ...s.cells };
        for (const addr of action.addresses) {
          const existing = cells[addr] ?? { value: null };
          cells[addr] = { ...existing, format: { ...existing.format, ...action.format } };
        }
        return { ...s, cells };
      });
      return { ...state, workbook, ...history };
    }

    case "SET_SELECTION":
      return {
        ...state,
        selection: {
          activeCell: action.cell,
          ranges: [{ start: action.cell, end: action.cell }],
        },
        editingCell: null,
      };

    case "EXTEND_SELECTION":
      return {
        ...state,
        selection: {
          ...state.selection,
          ranges: [
            { start: state.selection.activeCell, end: action.cell },
            ...state.selection.ranges.slice(1),
          ],
        },
      };

    case "ADD_SELECTION":
      return {
        ...state,
        selection: {
          activeCell: action.cell,
          ranges: [...state.selection.ranges, { start: action.cell, end: action.cell }],
        },
      };

    case "SELECT_RANGE":
      return {
        ...state,
        selection: {
          activeCell: action.start,
          ranges: [{ start: action.start, end: action.end }],
        },
      };

    case "NAVIGATE": {
      const { row, col } = parseAddress(state.selection.activeCell);
      let newRow = row;
      let newCol = col;
      switch (action.direction) {
        case "up": newRow = Math.max(0, row - 1); break;
        case "down": newRow = row + 1; break;
        case "left": newCol = Math.max(0, col - 1); break;
        case "right": newCol = col + 1; break;
      }
      const newAddr = toAddress(newRow, newCol);
      if (action.extend) {
        return {
          ...state,
          selection: {
            ...state.selection,
            ranges: [
              { start: state.selection.activeCell, end: newAddr },
              ...state.selection.ranges.slice(1),
            ],
          },
        };
      }
      return {
        ...state,
        selection: { activeCell: newAddr, ranges: [{ start: newAddr, end: newAddr }] },
        editingCell: null,
      };
    }

    case "START_EDIT": {
      const sheet = getActiveSheet(state);
      const cell = sheet.cells[state.selection.activeCell];
      const initialValue = action.value ?? (cell?.formula ? "=" + cell.formula : getCellDisplayValue(cell));
      return { ...state, editingCell: state.selection.activeCell, editValue: initialValue };
    }

    case "UPDATE_EDIT":
      return { ...state, editValue: action.value };

    case "CONFIRM_EDIT": {
      if (!state.editingCell) return state;
      const newState = reducer(state, { type: "SET_CELL_VALUE", address: state.editingCell, value: state.editValue });
      // Move down after confirm
      const { row, col } = parseAddress(state.editingCell);
      const nextAddr = toAddress(row + 1, col);
      return {
        ...newState,
        editingCell: null,
        editValue: "",
        selection: { activeCell: nextAddr, ranges: [{ start: nextAddr, end: nextAddr }] },
      };
    }

    case "CANCEL_EDIT":
      return { ...state, editingCell: null, editValue: "" };

    case "RESIZE_COLUMN": {
      const workbook = updateActiveSheet(state, (s) => ({
        ...s,
        columnWidths: { ...s.columnWidths, [action.col]: Math.max(30, action.width) },
      }));
      return { ...state, workbook };
    }

    case "ADD_SHEET": {
      const id = `sheet-${Date.now()}`;
      const num = state.workbook.sheets.length + 1;
      const sheet = createEmptySheet(id, `Sheet ${num}`);
      return {
        ...state,
        workbook: {
          sheets: [...state.workbook.sheets, sheet],
          activeSheetId: id,
        },
      };
    }

    case "RENAME_SHEET":
      return {
        ...state,
        workbook: {
          ...state.workbook,
          sheets: state.workbook.sheets.map((s) =>
            s.id === action.sheetId ? { ...s, name: action.name } : s,
          ),
        },
      };

    case "DELETE_SHEET": {
      if (state.workbook.sheets.length <= 1) return state;
      const remaining = state.workbook.sheets.filter((s) => s.id !== action.sheetId);
      const activeId = state.workbook.activeSheetId === action.sheetId
        ? remaining[0].id
        : state.workbook.activeSheetId;
      return {
        ...state,
        workbook: { sheets: remaining, activeSheetId: activeId },
      };
    }

    case "SET_ACTIVE_SHEET":
      return {
        ...state,
        workbook: { ...state.workbook, activeSheetId: action.sheetId },
        selection: { activeCell: "A1", ranges: [{ start: "A1", end: "A1" }] },
        editingCell: null,
      };

    case "SET_FROZEN_ROWS": {
      const workbook = updateActiveSheet(state, (s) => ({
        ...s, frozenRows: Math.max(0, action.count),
      }));
      return { ...state, workbook };
    }

    case "SET_FROZEN_COLS": {
      const workbook = updateActiveSheet(state, (s) => ({
        ...s, frozenCols: Math.max(0, action.count),
      }));
      return { ...state, workbook };
    }

    case "UNDO": {
      if (state.undoStack.length === 0) return state;
      const prev = state.undoStack[state.undoStack.length - 1];
      return {
        ...state,
        workbook: prev,
        undoStack: state.undoStack.slice(0, -1),
        redoStack: [...state.redoStack, state.workbook],
      };
    }

    case "REDO": {
      if (state.redoStack.length === 0) return state;
      const next = state.redoStack[state.redoStack.length - 1];
      return {
        ...state,
        workbook: next,
        undoStack: [...state.undoStack, state.workbook],
        redoStack: state.redoStack.slice(0, -1),
      };
    }

    case "SET_WORKBOOK":
      // Recalculate so externally-synced formula cells (server round-trips,
      // agent-bridge tool updates, prop-driven snapshots) evaluate — same as
      // createInitialState and SET_CELL_VALUE. Without this they render blank.
      return { ...state, workbook: recalculateWorkbook(action.workbook) };

    default:
      return state;
  }
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

export function useSpreadsheetStore(initialData?: WorkbookData) {
  const [state, dispatch] = useReducer(reducer, initialData, (data) => createInitialState(data));

  const actions = useMemo(() => ({
    setCellValue: (address: string, value: string) => dispatch({ type: "SET_CELL_VALUE", address, value }),
    setCellFormat: (addresses: string[], format: Partial<CellFormat>) => dispatch({ type: "SET_CELL_FORMAT", addresses, format }),
    setSelection: (cell: string) => dispatch({ type: "SET_SELECTION", cell }),
    extendSelection: (cell: string) => dispatch({ type: "EXTEND_SELECTION", cell }),
    addSelection: (cell: string) => dispatch({ type: "ADD_SELECTION", cell }),
    selectRange: (start: string, end: string) => dispatch({ type: "SELECT_RANGE", start, end }),
    navigate: (direction: "up" | "down" | "left" | "right", extend?: boolean) => dispatch({ type: "NAVIGATE", direction, extend }),
    startEdit: (value?: string) => dispatch({ type: "START_EDIT", value }),
    updateEdit: (value: string) => dispatch({ type: "UPDATE_EDIT", value }),
    confirmEdit: () => dispatch({ type: "CONFIRM_EDIT" }),
    cancelEdit: () => dispatch({ type: "CANCEL_EDIT" }),
    resizeColumn: (col: number, width: number) => dispatch({ type: "RESIZE_COLUMN", col, width }),
    addSheet: () => dispatch({ type: "ADD_SHEET" }),
    renameSheet: (sheetId: string, name: string) => dispatch({ type: "RENAME_SHEET", sheetId, name }),
    deleteSheet: (sheetId: string) => dispatch({ type: "DELETE_SHEET", sheetId }),
    setFrozenRows: (count: number) => dispatch({ type: "SET_FROZEN_ROWS", count }),
    setFrozenCols: (count: number) => dispatch({ type: "SET_FROZEN_COLS", count }),
    setActiveSheet: (sheetId: string) => dispatch({ type: "SET_ACTIVE_SHEET", sheetId }),
    undo: () => dispatch({ type: "UNDO" }),
    redo: () => dispatch({ type: "REDO" }),
    setWorkbook: (workbook: WorkbookData) => dispatch({ type: "SET_WORKBOOK", workbook }),
  }), []);

  return { state, actions };
}

/** Convert 0-based column index to letter(s): 0="A", 25="Z", 26="AA" */
export function columnToLetter(col: number): string {
  let result = "";
  let c = col;
  while (c >= 0) {
    result = String.fromCharCode((c % 26) + 65) + result;
    c = Math.floor(c / 26) - 1;
  }
  return result;
}

/** Convert column letter(s) to 0-based index: "A"=0, "Z"=25, "AA"=26 */
export function letterToColumn(letters: string): number {
  let result = 0;
  for (let i = 0; i < letters.length; i++) {
    result = result * 26 + (letters.charCodeAt(i) - 64);
  }
  return result - 1;
}

/** Parse address string to 0-based row and col: "B3" -> { row: 2, col: 1 } */
export function parseAddress(addr: string): { row: number; col: number } {
  const match = addr.match(/^([A-Z]+)(\d+)$/);
  if (!match) return { row: 0, col: 0 };
  return {
    col: letterToColumn(match[1]),
    row: parseInt(match[2], 10) - 1,
  };
}

/** Convert 0-based row and col to address string: (2, 1) -> "B3" */
export function toAddress(row: number, col: number): string {
  return columnToLetter(col) + (row + 1);
}

/** Check if a string is a valid cell address */
export function isValidAddress(addr: string): boolean {
  return /^[A-Z]+\d+$/.test(addr);
}

/** Expand a range into an array of addresses */
export function expandRange(startAddr: string, endAddr: string): string[] {
  const s = parseAddress(startAddr);
  const e = parseAddress(endAddr);
  const minRow = Math.min(s.row, e.row);
  const maxRow = Math.max(s.row, e.row);
  const minCol = Math.min(s.col, e.col);
  const maxCol = Math.max(s.col, e.col);
  const addresses: string[] = [];
  for (let r = minRow; r <= maxRow; r++) {
    for (let c = minCol; c <= maxCol; c++) {
      addresses.push(toAddress(r, c));
    }
  }
  return addresses;
}

/** Normalize a range so start is top-left and end is bottom-right */
export function normalizeRange(startAddr: string, endAddr: string): { start: string; end: string } {
  const s = parseAddress(startAddr);
  const e = parseAddress(endAddr);
  return {
    start: toAddress(Math.min(s.row, e.row), Math.min(s.col, e.col)),
    end: toAddress(Math.max(s.row, e.row), Math.max(s.col, e.col)),
  };
}

/** Offset an address by row/col deltas */
export function offsetAddress(addr: string, rowDelta: number, colDelta: number): string {
  const { row, col } = parseAddress(addr);
  return toAddress(row + rowDelta, col + colDelta);
}

import { useCallback, useRef, useState } from "react";
import { cn, ContextMenu } from "@particle-academy/react-fancy";
import type { SpreadsheetContextMenuItem } from "../Spreadsheet/Spreadsheet.types";
import { useSpreadsheet } from "../Spreadsheet/Spreadsheet.context";
import { ColumnHeaders } from "./ColumnHeaders";
import { RowHeader } from "./RowHeaders";
import { Cell } from "./Cell";
import { CellEditor } from "./CellEditor";
import { SelectionOverlay } from "./SelectionOverlay";
import { toAddress, parseAddress } from "../../engine/cell-utils";
import { cellsToTSV, tsvToCells } from "../../engine/clipboard";

function renderMenuItems(items: SpreadsheetContextMenuItem[], activeCell: string): React.ReactNode {
  return items.map((item, i) => {
    if (item.items && item.items.length > 0) {
      return (
        <ContextMenu.Sub key={i}>
          <ContextMenu.SubTrigger>{item.label}</ContextMenu.SubTrigger>
          <ContextMenu.SubContent>
            {renderMenuItems(item.items, activeCell)}
          </ContextMenu.SubContent>
        </ContextMenu.Sub>
      );
    }
    return (
      <ContextMenu.Item
        key={i}
        onClick={() => item.onClick?.(activeCell)}
        disabled={typeof item.disabled === "function" ? item.disabled(activeCell) : item.disabled}
        danger={item.danger}
      >
        {item.label}
      </ContextMenu.Item>
    );
  });
}

interface SpreadsheetGridProps {
  className?: string;
}

export function SpreadsheetGrid({ className }: SpreadsheetGridProps) {
  const {
    columnCount,
    rowCount,
    rowHeight,
    getColumnWidth,
    selection,
    editingCell,
    readOnly,
    activeSheet,
    navigate,
    startEdit,
    confirmEdit,
    cancelEdit,
    setCellValue,
    setFrozenRows,
    setFrozenCols,
    extendSelection,
    undo,
    redo,
    contextMenuItems,
  } = useSpreadsheet();

  const containerRef = useRef<HTMLDivElement>(null);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      // Don't intercept when editing (CellEditor handles its own keys)
      if (editingCell) return;

      // Navigation
      if (e.key === "ArrowUp") { e.preventDefault(); navigate("up", e.shiftKey); return; }
      if (e.key === "ArrowDown") { e.preventDefault(); navigate("down", e.shiftKey); return; }
      if (e.key === "ArrowLeft") { e.preventDefault(); navigate("left", e.shiftKey); return; }
      if (e.key === "ArrowRight") { e.preventDefault(); navigate("right", e.shiftKey); return; }
      if (e.key === "Tab") { e.preventDefault(); navigate(e.shiftKey ? "left" : "right"); return; }
      if (e.key === "Enter") { e.preventDefault(); if (!readOnly) startEdit(); return; }

      // Copy
      if ((e.ctrlKey || e.metaKey) && e.key === "c") {
        e.preventDefault();
        const range = selection.ranges[0];
        if (range) {
          const tsv = cellsToTSV(activeSheet.cells, range);
          navigator.clipboard.writeText(tsv);
        }
        return;
      }

      // Paste
      if ((e.ctrlKey || e.metaKey) && e.key === "v") {
        e.preventDefault();
        navigator.clipboard.readText().then((text) => {
          if (!text) return;
          const { values } = tsvToCells(text);
          const { row: startRow, col: startCol } = parseAddress(selection.activeCell);
          for (let r = 0; r < values.length; r++) {
            for (let c = 0; c < values[r].length; c++) {
              const addr = toAddress(startRow + r, startCol + c);
              setCellValue(addr, values[r][c]);
            }
          }
        });
        return;
      }

      // Undo/Redo
      if ((e.ctrlKey || e.metaKey) && e.key === "z") { e.preventDefault(); undo(); return; }
      if ((e.ctrlKey || e.metaKey) && e.key === "y") { e.preventDefault(); redo(); return; }

      // Start editing by typing
      if (!readOnly && !e.ctrlKey && !e.metaKey && !e.altKey && e.key.length === 1) {
        startEdit(e.key);
      }

      // Delete/Backspace clears cell
      if (!readOnly && (e.key === "Delete" || e.key === "Backspace")) {
        e.preventDefault();
        startEdit("");
        // Immediately confirm with empty value
        setTimeout(() => confirmEdit(), 0);
      }
    },
    [editingCell, readOnly, navigate, startEdit, confirmEdit, undo, redo],
  );

  // Calculate the position of the editing cell for the overlay editor
  const editorPosition = editingCell
    ? (() => {
        const { row, col } = parseAddress(editingCell);
        let left = 48; // row header width
        for (let c = 0; c < col; c++) left += getColumnWidth(c);
        const top = row * rowHeight;
        return { left, top };
      })()
    : null;

  const handleCopy = useCallback(() => {
    const range = selection.ranges[0];
    if (range) {
      const tsv = cellsToTSV(activeSheet.cells, range);
      navigator.clipboard.writeText(tsv);
    }
  }, [selection, activeSheet]);

  const handlePaste = useCallback(() => {
    navigator.clipboard.readText().then((text) => {
      if (!text) return;
      const { values } = tsvToCells(text);
      const { row: startRow, col: startCol } = parseAddress(selection.activeCell);
      for (let r = 0; r < values.length; r++) {
        for (let c = 0; c < values[r].length; c++) {
          setCellValue(toAddress(startRow + r, startCol + c), values[r][c]);
        }
      }
    });
  }, [selection, setCellValue]);

  const handleClearSelection = useCallback(() => {
    const range = selection.ranges[0];
    if (!range) return;
    const { start, end } = range;
    const s = parseAddress(start);
    const e = parseAddress(end);
    const minR = Math.min(s.row, e.row), maxR = Math.max(s.row, e.row);
    const minC = Math.min(s.col, e.col), maxC = Math.max(s.col, e.col);
    for (let r = minR; r <= maxR; r++) {
      for (let c = minC; c <= maxC; c++) {
        setCellValue(toAddress(r, c), "");
      }
    }
  }, [selection, setCellValue]);

  return (
    <ContextMenu>
      <ContextMenu.Trigger className="min-h-0 flex-1">
        <div
          ref={containerRef}
          data-fancy-sheets-grid=""
          className={cn("relative h-full overflow-auto bg-white focus:outline-none dark:bg-zinc-900", className)}
          tabIndex={0}
          onKeyDown={handleKeyDown}
        >
          {/* Column headers */}
          <div className="sticky top-0 z-10">
            <ColumnHeaders />
          </div>

          {/* Rows */}
          <div className="relative">
            {Array.from({ length: rowCount }, (_, rowIdx) => {
              const isFrozenRow = rowIdx < activeSheet.frozenRows;
              return (
                <div
                  key={rowIdx}
                  className={cn(
                    "flex",
                    // Frozen rows need a solid background so scrolling content
                    // doesn't bleed through any cell-level transparency
                    // (highlight overlays, alpha format colors, etc.).
                    isFrozenRow && "bg-white dark:bg-zinc-900",
                  )}
                  style={isFrozenRow ? {
                    position: "sticky",
                    top: rowHeight + rowIdx * rowHeight,
                    zIndex: 8,
                  } : undefined}
                >
                  <div className="sticky left-0 z-[5]">
                    <RowHeader rowIndex={rowIdx} />
                  </div>
                  {Array.from({ length: columnCount }, (_, colIdx) => {
                    const addr = toAddress(rowIdx, colIdx);
                    const isFrozenCol = colIdx < activeSheet.frozenCols;
                    return (
                      <div
                        key={addr}
                        className={cn(
                          // Same solid-background guarantee for frozen
                          // columns — keeps the column opaque while content
                          // scrolls horizontally underneath.
                          isFrozenCol && "bg-white dark:bg-zinc-900",
                        )}
                        style={isFrozenCol ? {
                          position: "sticky",
                          left: 48 + Array.from({ length: colIdx }, (_, c) => getColumnWidth(c)).reduce((a, b) => a + b, 0),
                          zIndex: isFrozenRow ? 9 : 6,
                        } : undefined}
                      >
                        <Cell address={addr} row={rowIdx} col={colIdx} />
                      </div>
                    );
                  })}
                </div>
              );
            })}

            {/* Selection overlay */}
            <SelectionOverlay />

            {/* Cell editor overlay */}
            {editorPosition && (
              <div
                className="absolute z-20"
                style={{ left: editorPosition.left, top: editorPosition.top }}
              >
                <CellEditor />
              </div>
            )}
          </div>
        </div>
      </ContextMenu.Trigger>
      <ContextMenu.Content>
        <ContextMenu.Item onClick={handleCopy}>Copy</ContextMenu.Item>
        <ContextMenu.Item onClick={handlePaste} disabled={readOnly}>Paste</ContextMenu.Item>
        <ContextMenu.Separator />
        <ContextMenu.Item onClick={handleClearSelection} disabled={readOnly}>Clear cells</ContextMenu.Item>
        <ContextMenu.Separator />
        <ContextMenu.Item onClick={() => {
          const row = parseAddress(selection.activeCell).row;
          setFrozenRows(activeSheet.frozenRows > 0 ? 0 : row);
        }} disabled={readOnly}>
          {activeSheet.frozenRows > 0 ? "Unfreeze rows" : "Freeze rows above"}
        </ContextMenu.Item>
        <ContextMenu.Item onClick={() => {
          const col = parseAddress(selection.activeCell).col;
          setFrozenCols(activeSheet.frozenCols > 0 ? 0 : col);
        }} disabled={readOnly}>
          {activeSheet.frozenCols > 0 ? "Unfreeze columns" : "Freeze columns left"}
        </ContextMenu.Item>
        {(() => {
          const items = typeof contextMenuItems === "function"
            ? contextMenuItems(selection.activeCell)
            : contextMenuItems;
          if (!items || items.length === 0) return null;
          return (
            <>
              <ContextMenu.Separator />
              {renderMenuItems(items, selection.activeCell)}
            </>
          );
        })()}
      </ContextMenu.Content>
    </ContextMenu>
  );
}

SpreadsheetGrid.displayName = "SpreadsheetGrid";

import { useState, useCallback } from "react";
import { cn } from "@particle-academy/react-fancy";
