/** A rectangular range of cells */
export interface CellRange {
  start: string;
  end: string;
}

/** Full selection state */
export interface SelectionState {
  /** The anchor cell (where selection started) */
  activeCell: string;
  /** Ranges currently selected (supports multi-select via Ctrl+Click) */
  ranges: CellRange[];
}

import type { CellData, CellFormat, CellValue } from "../types/cell";
import { currencySymbol, formatWithCode } from "./number-format";

/** Decimal places a display format shows when the cell does not set `decimals`. */
export function defaultDecimals(displayFormat: CellFormat["displayFormat"]): number | undefined {
  switch (displayFormat) {
    case "number":
      return 0;
    case "currency":
      return 2;
    case "percentage":
      return 1;
    default:
      return undefined;
  }
}

/**
 * The spreadsheet format code a cell's display format stands for: exactly the
 * code holy-sheet writes into an .xlsx for the same `displayFormat`, `decimals`
 * and `currency` (`NumFmtBuilder` in all three of its runtimes). So a workbook
 * reads the same in this grid as in Excel or LibreOffice after export, and a
 * file holy-sheet read back renders as its author formatted it.
 *
 * `null` means no code: the value shows as it is.
 */
export function displayFormatCode(format: CellFormat | undefined): string | null {
  const fmt = format?.displayFormat;
  const places = (fallback: number) => {
    const d = format?.decimals ?? fallback;
    return d > 0 ? "." + "0".repeat(Math.floor(d)) : "";
  };

  switch (fmt) {
    case "number":
      return "#,##0" + places(0);
    case "percentage":
      return "0" + places(1) + "%";
    case "currency": {
      const symbol = `"${currencySymbol(format?.currency)}"`;
      const body = "#,##0" + places(2);
      return `${symbol}${body};-${symbol}${body}`;
    }
    case "date":
      return "yyyy-mm-dd";
    case "datetime":
      return "yyyy-mm-dd hh:mm:ss";
    case undefined:
    case "auto":
      // Auto shows the value, rounded when the cell asks for decimal places.
      return format?.decimals !== undefined ? "0" + places(0) : null;
    default:
      return null;
  }
}

/**
 * Detects a formula whose OUTERMOST function returns a date serial, so an
 * auto-formatted `=TODAY()` shows a date. `YEAR(DATE(...))` is not one: YEAR
 * returns a plain number.
 */
function isDateFormula(formula: string | undefined): boolean {
  if (!formula) return false;
  return /^(TODAY|NOW|DATE|EDATE)\s*\(/.test(formula.trim().toUpperCase());
}

/** A cell value as the grid displays it. Pure: usable headlessly, in SSR and exports. */
export function formatCellValue(val: CellValue | undefined, cell: CellData | undefined): string {
  if (val === null || val === undefined) return "";
  if (typeof val === "boolean") return val ? "TRUE" : "FALSE";
  if (typeof val !== "number") return String(val);

  const fmt = cell?.format?.displayFormat;
  if ((fmt === undefined || fmt === "auto") && isDateFormula(cell?.formula)) {
    return formatWithCode(val, val % 1 === 0 ? "yyyy-mm-dd" : "yyyy-mm-dd hh:mm:ss") ?? String(val);
  }

  const code = displayFormatCode(cell?.format);
  return code === null ? String(val) : (formatWithCode(val, code) ?? String(val));
}

import type { CellValue } from "../types/cell";
import type { WorkbookData, SheetData } from "../types/sheet";
import { expandRange } from "./cell-utils";
import { lexFormula } from "./formula/lexer";
import { parseFormula } from "./formula/parser";
import { evaluateAST } from "./formula/evaluator";
import { buildDependencyGraph, detectCircularRefs, getRecalculationOrder } from "./formula/dependency-graph";

/**
 * Recalculate every formula cell in a workbook, resolving cross-sheet
 * references. Pure — no React, no DOM — so it runs headless in Node for SSR,
 * snapshots, export pipelines, and tests. Returns a new workbook with each
 * formula cell's `computedValue` populated.
 */
export function recalculateWorkbook(workbook: WorkbookData): WorkbookData {
  // Recalculate sequentially so cross-sheet refs see already-computed values
  const recalculated: SheetData[] = [];
  for (const sheet of workbook.sheets) {
    recalculated.push(recalculateSheet(sheet, recalculated));
  }
  // Second pass: recalculate again with ALL sheets computed
  // (handles reverse-order cross-sheet refs like Sheet1 referencing Sheet3)
  const finalSheets: SheetData[] = [];
  for (const sheet of recalculated) {
    finalSheets.push(recalculateSheet(sheet, recalculated));
  }
  return { ...workbook, sheets: finalSheets };
}

/**
 * Recalculate all formula cells in a single sheet, with optional cross-sheet
 * reference support when `allSheets` is supplied. Pure.
 */
export function recalculateSheet(sheet: SheetData, allSheets?: SheetData[]): SheetData {
  const graph = buildDependencyGraph(sheet.cells);
  if (graph.size === 0) return sheet;

  const circular = detectCircularRefs(graph);
  const order = getRecalculationOrder(graph);
  const cells = { ...sheet.cells };

  const getCellValue = (addr: string): CellValue => {
    const c = cells[addr];
    if (!c) return null;
    if (c.formula && c.computedValue !== undefined) return c.computedValue;
    return c.value;
  };

  const getRangeValues = (startAddr: string, endAddr: string): CellValue[] => {
    const addresses = expandRange(startAddr, endAddr);
    return addresses.map(getCellValue);
  };

  // Cross-sheet getters
  const getSheetCellValue = (sheetName: string, addr: string): CellValue => {
    if (!allSheets) return "#REF!";
    const target = allSheets.find((s) => s.name === sheetName || s.id === sheetName);
    if (!target) return "#REF!";
    const c = target.cells[addr];
    if (!c) return null;
    if (c.formula && c.computedValue !== undefined) return c.computedValue;
    return c.value;
  };

  const getSheetRangeValues = (sheetName: string, startAddr: string, endAddr: string): CellValue[] => {
    if (!allSheets) return [];
    const target = allSheets.find((s) => s.name === sheetName || s.id === sheetName);
    if (!target) return [];
    const addresses = expandRange(startAddr, endAddr);
    return addresses.map((a) => {
      const c = target.cells[a];
      if (!c) return null;
      if (c.formula && c.computedValue !== undefined) return c.computedValue;
      return c.value;
    });
  };

  const ctx = { getSheetCellValue, getSheetRangeValues };

  for (const addr of order) {
    const cell = cells[addr];
    if (!cell?.formula) continue;

    if (circular.has(addr)) {
      cells[addr] = { ...cell, computedValue: "#CIRC!" };
      continue;
    }

    try {
      const tokens = lexFormula(cell.formula);
      const ast = parseFormula(tokens);
      const result = evaluateAST(ast, getCellValue, getRangeValues, ctx);
      cells[addr] = { ...cell, computedValue: result };
    } catch {
      cells[addr] = { ...cell, computedValue: "#ERROR!" };
    }
  }

  return { ...sheet, cells };
}

import { useCallback } from "react";
import { cn } from "@particle-academy/react-fancy";
import { useSpreadsheet } from "../Spreadsheet/Spreadsheet.context";
import { columnToLetter, toAddress, parseAddress } from "../../engine/cell-utils";
import { ColumnResizeHandle } from "./ColumnResizeHandle";

export function ColumnHeaders() {
  const { columnCount, rowCount, rowHeight, getColumnWidth, selection, selectRange, _isDragging } = useSpreadsheet();

  const handleColumnMouseDown = useCallback(
    (colIdx: number, e: React.MouseEvent) => {
      if (e.button !== 0) return;
      if (e.shiftKey) {
        const activeCol = parseAddress(selection.activeCell).col;
        const minCol = Math.min(activeCol, colIdx);
        const maxCol = Math.max(activeCol, colIdx);
        selectRange(toAddress(0, minCol), toAddress(rowCount - 1, maxCol));
      } else {
        selectRange(toAddress(0, colIdx), toAddress(rowCount - 1, colIdx));
      }
      _isDragging.current = true;
    },
    [rowCount, selectRange, selection.activeCell, _isDragging],
  );

  const handleColumnMouseEnter = useCallback(
    (colIdx: number) => {
      if (_isDragging.current) {
        const activeCol = parseAddress(selection.activeCell).col;
        const minCol = Math.min(activeCol, colIdx);
        const maxCol = Math.max(activeCol, colIdx);
        selectRange(toAddress(0, minCol), toAddress(rowCount - 1, maxCol));
      }
    },
    [rowCount, selection.activeCell, selectRange, _isDragging],
  );

  const handleMouseUp = useCallback(() => {
    _isDragging.current = false;
  }, [_isDragging]);

  return (
    <div
      data-fancy-sheets-column-headers=""
      className="flex border-b border-zinc-300 bg-zinc-100 dark:border-zinc-600 dark:bg-zinc-800"
      style={{ height: rowHeight }}
    >
      {/* Corner cell */}
      <div
        className="flex shrink-0 items-center justify-center border-r border-zinc-300 bg-zinc-100 text-[11px] font-medium text-zinc-400 dark:border-zinc-600 dark:bg-zinc-800"
        style={{ width: 48, minWidth: 48 }}
      />
      {/* Column letters */}
      {Array.from({ length: columnCount }, (_, i) => {
        // Only highlight if the ENTIRE column is selected (spans all rows)
        const isColSelected = selection.ranges.some((range) => {
          const s = parseAddress(range.start);
          const e = parseAddress(range.end);
          const minCol = Math.min(s.col, e.col);
          const maxCol = Math.max(s.col, e.col);
          const minRow = Math.min(s.row, e.row);
          const maxRow = Math.max(s.row, e.row);
          return i >= minCol && i <= maxCol && minRow === 0 && maxRow >= rowCount - 1;
        });
        return (
          <div
            key={i}
            className={cn(
              "relative flex shrink-0 cursor-pointer items-center justify-center border-r border-zinc-300 text-[11px] font-medium select-none hover:bg-zinc-200 dark:border-zinc-600 dark:hover:bg-zinc-700",
              isColSelected
                ? "bg-blue-100 text-blue-700 dark:bg-blue-900/50 dark:text-blue-300"
                : "text-zinc-500 dark:text-zinc-400",
            )}
            style={{ width: getColumnWidth(i), minWidth: getColumnWidth(i) }}
            onMouseDown={(e) => handleColumnMouseDown(i, e)}
            onMouseEnter={() => handleColumnMouseEnter(i)}
            onMouseUp={handleMouseUp}
          >
            {columnToLetter(i)}
            <ColumnResizeHandle colIndex={i} />
          </div>
        );
      })}
    </div>
  );
}

