import { useCallback } from "react";
import { cn } from "@particle-academy/react-fancy";
import { useSpreadsheet } from "../Spreadsheet/Spreadsheet.context";
import { toAddress, parseAddress } from "../../engine/cell-utils";

interface RowHeadersProps {
  rowIndex: number;
}

export function RowHeader({ rowIndex }: RowHeadersProps) {
  const { rowHeight, columnCount, selection, selectRange, _isDragging } = useSpreadsheet();

  // Only highlight if the ENTIRE row is selected (selection spans all columns)
  const isRowSelected = selection.ranges.some((range) => {
    const s = parseAddress(range.start);
    const e = parseAddress(range.end);
    const minRow = Math.min(s.row, e.row);
    const maxRow = Math.max(s.row, e.row);
    const minCol = Math.min(s.col, e.col);
    const maxCol = Math.max(s.col, e.col);
    return rowIndex >= minRow && rowIndex <= maxRow && minCol === 0 && maxCol >= columnCount - 1;
  });

  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      if (e.button !== 0) return;
      if (e.shiftKey) {
        const activeRow = parseAddress(selection.activeCell).row;
        const minRow = Math.min(activeRow, rowIndex);
        const maxRow = Math.max(activeRow, rowIndex);
        selectRange(toAddress(minRow, 0), toAddress(maxRow, columnCount - 1));
      } else {
        selectRange(toAddress(rowIndex, 0), toAddress(rowIndex, columnCount - 1));
      }
      _isDragging.current = true;
    },
    [rowIndex, columnCount, selectRange, selection.activeCell, _isDragging],
  );

  const handleMouseEnter = useCallback(() => {
    if (_isDragging.current) {
      const activeRow = parseAddress(selection.activeCell).row;
      const minRow = Math.min(activeRow, rowIndex);
      const maxRow = Math.max(activeRow, rowIndex);
      selectRange(toAddress(minRow, 0), toAddress(maxRow, columnCount - 1));
    }
  }, [rowIndex, columnCount, selection.activeCell, selectRange, _isDragging]);

  const handleMouseUp = useCallback(() => {
    _isDragging.current = false;
  }, [_isDragging]);

  return (
    <div
      data-fancy-sheets-row-header=""
      className={cn(
        "flex shrink-0 cursor-pointer items-center justify-center border-r border-b border-zinc-300 text-[11px] font-medium select-none hover:bg-zinc-200 dark:border-zinc-600 dark:hover:bg-zinc-700",
        isRowSelected
          ? "bg-blue-100 text-blue-700 dark:bg-blue-900/50 dark:text-blue-300"
          : "bg-zinc-100 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-400",
      )}
      style={{ width: 48, minWidth: 48, height: rowHeight }}
      onMouseDown={handleMouseDown}
      onMouseEnter={handleMouseEnter}
      onMouseUp={handleMouseUp}
    >
      {rowIndex + 1}
    </div>
  );
}

RowHeader.displayName = "RowHeader";

import { useCallback, memo, useState } from "react";
import { cn } from "@particle-academy/react-fancy";
import { useSpreadsheet } from "../Spreadsheet/Spreadsheet.context";
import type { CellData } from "../../types/cell";
import { formatCellValue } from "../../engine/cell-display";

const DEFAULT_COMMENT_COLOR = "#f59e0b";

interface CellProps {
  address: string;
  row: number;
  col: number;
}

function getCellDisplayValue(cell: CellData | undefined): string {
  if (!cell) return "";
  const val = cell.formula && cell.computedValue !== undefined ? cell.computedValue : cell.value;
  return formatCellValue(val, cell);
}

export const Cell = memo(function Cell({ address, row, col }: CellProps) {
  const {
    activeSheet,
    selection,
    editingCell,
    readOnly,
    setSelection,
    extendSelection,
    addSelection,
    startEdit,
    rowHeight,
    getColumnWidth,
    isCellSelected,
    isCellActive,
    highlights,
    _isDragging,
  } = useSpreadsheet();

  const cell = activeSheet.cells[address];
  const highlight = highlights[address];
  const isActive = isCellActive(address);
  const isSelected = isCellSelected(address);
  const isEditing = editingCell === address;
  const displayValue = getCellDisplayValue(cell);
  const width = getColumnWidth(col);

  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      if (e.button !== 0) return;
      if (e.shiftKey) {
        extendSelection(address);
      } else if (e.ctrlKey || e.metaKey) {
        addSelection(address);
      } else {
        setSelection(address);
      }
      _isDragging.current = true;
    },
    [address, setSelection, extendSelection, addSelection, _isDragging],
  );

  const handleMouseEnter = useCallback(() => {
    if (_isDragging.current) {
      extendSelection(address);
    }
  }, [address, extendSelection, _isDragging]);

  const handleMouseUp = useCallback(() => {
    _isDragging.current = false;
  }, [_isDragging]);

  const handleDoubleClick = useCallback(() => {
    if (readOnly) return;
    startEdit();
  }, [readOnly, startEdit]);

  const formatStyle: React.CSSProperties = {};
  if (cell?.format?.bold) formatStyle.fontWeight = "bold";
  if (cell?.format?.italic) formatStyle.fontStyle = "italic";
  if (cell?.format?.textAlign) formatStyle.textAlign = cell.format.textAlign;
  if (cell?.format?.backgroundColor) {
    formatStyle.backgroundColor = cell.format.backgroundColor;
    // When a custom background is set but no explicit text color, force dark text
    // so content stays readable against light/pastel backgrounds in both modes.
    if (!cell.format.color) formatStyle.color = "#1f2937";
  }
  if (cell?.format?.color) formatStyle.color = cell.format.color;
  if (cell?.format?.fontSize) formatStyle.fontSize = cell.format.fontSize;
  if (cell?.format?.borderTop) {
    formatStyle.borderTopWidth = 1;
    formatStyle.borderTopStyle = "solid";
    formatStyle.borderTopColor = cell.format.borderTop;
  }
  if (cell?.format?.borderRight) formatStyle.borderRightColor = cell.format.borderRight;
  if (cell?.format?.borderBottom) formatStyle.borderBottomColor = cell.format.borderBottom;
  if (cell?.format?.borderLeft) {
    formatStyle.borderLeftWidth = 1;
    formatStyle.borderLeftStyle = "solid";
    formatStyle.borderLeftColor = cell.format.borderLeft;
  }

  // Comment indicator
  const comment = cell?.comment;
  const commentColor = comment?.color ?? DEFAULT_COMMENT_COLOR;
  if (comment) {
    formatStyle.borderColor = commentColor;
    formatStyle.borderWidth = 1;
    formatStyle.borderStyle = "solid";
  }

  const [showComment, setShowComment] = useState(false);

  return (
    <div
      data-fancy-sheets-cell=""
      data-selected={isSelected || undefined}
      data-active={isActive || undefined}
      data-highlighted={!!highlight || undefined}
      role="gridcell"
      className={cn(
        "relative flex items-center truncate border-r border-b border-zinc-200 bg-white px-1.5 text-[13px] select-none dark:border-zinc-700 dark:bg-zinc-900",
        isActive && "ring-2 ring-inset ring-blue-500",
        isSelected && !isActive && "bg-blue-50 dark:bg-blue-950/40",
        cell?.format?.className,
      )}
      style={{ width, minWidth: width, height: rowHeight, ...formatStyle }}
      onMouseDown={handleMouseDown}
      onMouseEnter={(e) => {
        handleMouseEnter();
        if (comment) setShowComment(true);
      }}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => { if (comment) setShowComment(false); }}
      onDoubleClick={handleDoubleClick}
    >
      {highlight && (
        <div
          className="pointer-events-none absolute inset-0"
          style={{
            outline: `2px solid ${highlight.color}`,
            outlineOffset: '-2px',
            backgroundColor: highlight.backgroundColor
              ?? (highlight.color.startsWith('#') ? `${highlight.color}1A` : undefined),
          }}
          aria-hidden
        />
      )}
      {highlight?.label && (
        <span
          className="pointer-events-none absolute top-0 left-0 z-[1] px-0.5 text-[8px] font-bold leading-none text-white"
          style={{ backgroundColor: highlight.color }}
          aria-hidden
        >
          {highlight.label}
        </span>
      )}
      {!isEditing && <span className="truncate">{displayValue}</span>}
      {comment && (
        <div
          className="absolute top-0 right-0 h-0 w-0"
          style={{
            borderTop: `6px solid ${commentColor}`,
            borderLeft: "6px solid transparent",
          }}
          aria-hidden
        />
      )}
      {comment && showComment && (
        <div
          className="absolute top-full left-0 z-50 mt-0.5 max-w-[200px] rounded border bg-white px-2 py-1.5 text-[11px] leading-tight shadow-lg dark:bg-zinc-800"
          style={{ borderColor: commentColor }}
        >
          {comment.author && (
            <div className="mb-0.5 font-semibold" style={{ color: commentColor }}>{comment.author}</div>
          )}
          <div className="text-zinc-700 dark:text-zinc-200 whitespace-pre-wrap">{comment.text}</div>
        </div>
      )}
    </div>
  );
});

Cell.displayName = "Cell";

import { useEffect, useRef, useCallback } from "react";
import { useSpreadsheet } from "../Spreadsheet/Spreadsheet.context";
import { parseAddress } from "../../engine/cell-utils";

export function CellEditor() {
  const {
    editingCell,
    editValue,
    updateEdit,
    confirmEdit,
    cancelEdit,
    getColumnWidth,
    rowHeight,
  } = useSpreadsheet();

  const inputRef = useRef<HTMLInputElement>(null);
  const mountedAt = useRef(0);

  useEffect(() => {
    if (editingCell && inputRef.current) {
      mountedAt.current = Date.now();
      inputRef.current.focus();
    }
  }, [editingCell]);

  const handleBlur = useCallback(() => {
    // Ignore blur within 100ms of mount to avoid double-click race condition
    if (Date.now() - mountedAt.current < 100) return;
    confirmEdit();
  }, [confirmEdit]);

  if (!editingCell) return null;

  const { col } = parseAddress(editingCell);
  const width = getColumnWidth(col);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault();
      confirmEdit();
    } else if (e.key === "Escape") {
      e.preventDefault();
      cancelEdit();
    } else if (e.key === "Tab") {
      e.preventDefault();
      confirmEdit();
    }
  };

  return (
    <input
      ref={inputRef}
      data-fancy-sheets-cell-editor=""
      className="absolute z-20 border-2 border-blue-500 bg-white px-1 text-[13px] outline-none dark:bg-zinc-800 dark:text-zinc-100"
      style={{ width: Math.max(width, 60), height: rowHeight }}
      value={editValue}
      onChange={(e) => updateEdit(e.target.value)}
      onKeyDown={handleKeyDown}
      onBlur={handleBlur}
    />
  );
}

CellEditor.displayName = "CellEditor";

import { useMemo } from "react";
import { useSpreadsheet } from "../Spreadsheet/Spreadsheet.context";
import { parseAddress, normalizeRange } from "../../engine/cell-utils";

export function SelectionOverlay() {
  const { selection, getColumnWidth, rowHeight } = useSpreadsheet();

  const rects = useMemo(() => {
    return selection.ranges.map((range, i) => {
      const norm = normalizeRange(range.start, range.end);
      const s = parseAddress(norm.start);
      const e = parseAddress(norm.end);

      let left = 48; // row header width
      for (let c = 0; c < s.col; c++) left += getColumnWidth(c);

      let width = 0;
      for (let c = s.col; c <= e.col; c++) width += getColumnWidth(c);

      const top = s.row * rowHeight;
      const height = (e.row - s.row + 1) * rowHeight;

      return { left, top, width, height, isPrimary: i === 0 };
    });
  }, [selection.ranges, getColumnWidth, rowHeight]);

  return (
    <>
      {rects.map((rect, i) => (
        <div
          key={i}
          data-fancy-sheets-selection=""
          className="pointer-events-none absolute border-2 border-blue-500"
          style={{
            left: rect.left,
            top: rect.top,
            width: rect.width,
            height: rect.height,
            backgroundColor: rect.isPrimary ? "rgba(59, 130, 246, 0.08)" : "rgba(59, 130, 246, 0.05)",
          }}
        />
      ))}
    </>
  );
}

SelectionOverlay.displayName = "SelectionOverlay";

import type { CellMap } from "../types/sheet";
import type { CellRange } from "../types/selection";
import { parseAddress, toAddress, normalizeRange } from "./cell-utils";

/** Serialize a cell range to TSV string */
export function cellsToTSV(cells: CellMap, range: CellRange): string {
  const norm = normalizeRange(range.start, range.end);
  const s = parseAddress(norm.start);
  const e = parseAddress(norm.end);
  const rows: string[] = [];

  for (let r = s.row; r <= e.row; r++) {
    const cols: string[] = [];
    for (let c = s.col; c <= e.col; c++) {
      const addr = toAddress(r, c);
      const cell = cells[addr];
      if (!cell) {
        cols.push("");
      } else if (cell.computedValue !== undefined && cell.computedValue !== null) {
        cols.push(String(cell.computedValue));
      } else if (cell.value !== null) {
        cols.push(String(cell.value));
      } else {
        cols.push("");
      }
    }
    rows.push(cols.join("\t"));
  }

  return rows.join("\n");
}

/** Parse TSV string into cell data */
export function tsvToCells(tsv: string): { values: string[][]; rows: number; cols: number } {
  const lines = tsv.split("\n");
  const values = lines.map((line) => line.split("\t"));
  const rows = values.length;
  const cols = Math.max(...values.map((v) => v.length));
  return { values, rows, cols };
}

/**
 * Spreadsheet number format codes (`#,##0.00`, `0.0%`, `"$"#,##0.00;-"$"#,##0.00`,
 * `yyyy-mm-dd`, ...) rendered the way a spreadsheet application displays them.
 *
 * Pure and React-free: `TEXT()` and the grid's cell display both go through it,
 * so a formatted cell and `=TEXT(A1, code)` can never disagree.
 *
 * The behaviour is MEASURED, not recalled. Every expectation in
 * `number-format.test.ts` is what LibreOffice 26.2 displayed for the same value
 * and code, and the rules below are the ones that table forced:
 *
 * - Rounding is half away from zero on the value's 15-significant-digit decimal
 *   form, so 1.005 shows as 1.01 although the double is 1.00499999...
 * - A single-section code signs a negative only when the rounded digits are not
 *   all zero (-0.4 under `0` is `0`); a negative section (`...;-"$"#,##0.00`)
 *   is chosen by the value's sign, so -0.004 is `-$0.00`.
 * - The sign leads everything, literals included (`-$1,234.57`, `-Total: 1,235`).
 * - Optional fraction digits (`#`, `?`) drop trailing zeros, and the decimal
 *   point goes with them when nothing is left (`#.##` shows 5 as `5`).
 * - Times truncate to the second (a serial of 23:59:59.99 is `23:59:59`).
 *
 * Not supported: fractions (`# ?/?`), elapsed time (`[h]`), fractional seconds
 * and conditions or colours in brackets (brackets are skipped).
 */

import { DAY_MS, dateOfSerial } from "./serial-date";

/** 9999-12-31, the last date a spreadsheet can display. */
const MAX_SERIAL = 2_958_465;

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const WEEKDAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

/**
 * ISO 4217 code → the symbol holy-sheet writes into the file's format code.
 * Mirrors holy-sheet's `NumFmtBuilder::currencySymbol()` so a workbook shows the
 * same symbol in the grid and in Excel; an unlisted code is written as itself
 * followed by a space.
 */
const CURRENCY_SYMBOLS: Record<string, string> = {
  USD: "$",
  EUR: "€",
  GBP: "£",
  JPY: "¥",
  CNY: "¥",
  INR: "₹",
  AUD: "A$",
  CAD: "C$",
  CHF: "CHF",
  KRW: "₩",
};

export function currencySymbol(currency: string | undefined): string {
  const iso = (currency ?? "USD").toUpperCase();
  return CURRENCY_SYMBOLS[iso] ?? `${iso} `;
}

type Token =
  | { kind: "literal"; text: string }
  | { kind: "digit"; ch: "0" | "#" | "?" }
  | { kind: "point" }
  | { kind: "comma" }
  | { kind: "percent" }
  | { kind: "exponent"; text: string; sign: "+" | "-" }
  | { kind: "general" }
  | { kind: "date"; text: string }
  | { kind: "ampm"; text: string };

/** Splits a code on `;` outside quotes, escapes and brackets. */
function splitSections(code: string): string[] {
  const sections: string[] = [];
  let current = "";
  for (let i = 0; i < code.length; i++) {
    const ch = code[i];
    if (ch === '"') {
      const end = code.indexOf('"', i + 1);
      const stop = end === -1 ? code.length : end + 1;
      current += code.slice(i, stop);
      i = stop - 1;
    } else if (ch === "\\" || ch === "_" || ch === "*") {
      current += code.slice(i, i + 2);
      i++;
    } else if (ch === "[") {
      const end = code.indexOf("]", i + 1);
      const stop = end === -1 ? code.length : end + 1;
      current += code.slice(i, stop);
      i = stop - 1;
    } else if (ch === ";") {
      sections.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  sections.push(current);
  return sections;
}

function tokenize(section: string): Token[] {
  const tokens: Token[] = [];
  const literal = (text: string) => {
    const last = tokens[tokens.length - 1];
    if (last?.kind === "literal") last.text += text;
    else tokens.push({ kind: "literal", text });
  };

  for (let i = 0; i < section.length; i++) {
    const ch = section[i];
    const rest = section.slice(i);

    if (ch === '"') {
      const end = section.indexOf('"', i + 1);
      const stop = end === -1 ? section.length : end;
      literal(section.slice(i + 1, stop));
      i = stop;
    } else if (ch === "\\") {
      if (i + 1 < section.length) literal(section[i + 1]);
      i++;
    } else if (ch === "_") {
      literal(" ");
      i++;
    } else if (ch === "*") {
      i++;
    } else if (ch === "[") {
      const end = section.indexOf("]", i + 1);
      i = end === -1 ? section.length : end;
    } else if (ch === "0" || ch === "#" || ch === "?") {
      tokens.push({ kind: "digit", ch });
    } else if (ch === ".") {
      tokens.push({ kind: "point" });
    } else if (ch === ",") {
      tokens.push({ kind: "comma" });
    } else if (ch === "%") {
      tokens.push({ kind: "percent" });
    } else if ((ch === "E" || ch === "e") && (section[i + 1] === "+" || section[i + 1] === "-")) {
      tokens.push({ kind: "exponent", text: ch, sign: section[i + 1] as "+" | "-" });
      i++;
    } else if (/^general/i.test(rest)) {
      tokens.push({ kind: "general" });
      i += 6;
    } else if (ch === "@") {
      tokens.push({ kind: "general" });
    } else if (/^am\/pm/i.test(rest)) {
      tokens.push({ kind: "ampm", text: section.slice(i, i + 5) });
      i += 4;
    } else if (/^a\/p/i.test(rest)) {
      tokens.push({ kind: "ampm", text: section.slice(i, i + 3) });
      i += 2;
    } else if (/[ymdhs]/i.test(ch)) {
      let end = i + 1;
      while (end < section.length && section[end].toLowerCase() === ch.toLowerCase()) end++;
      tokens.push({ kind: "date", text: section.slice(i, end).toLowerCase() });
      i = end - 1;
    } else {
      literal(ch);
    }
  }

  return tokens;
}

/**
 * `abs * 10^shift` rounded half away from zero to `decimals` places, working on
 * the 15-significant-digit decimal form rather than on the binary double.
 */
function roundDecimal(abs: number, decimals: number, shift = 0): { int: string; frac: string } {
  let scaled = "0";

  if (abs !== 0) {
    const [mantissa, exponent] = abs.toExponential(14).split("e");
    const digits = mantissa.replace(".", "");
    const keep = Number(exponent) + shift + 1 + decimals;

    if (keep >= digits.length) {
      scaled = digits + "0".repeat(keep - digits.length);
    } else if (keep >= 0) {
      scaled = digits.slice(0, keep) || "0";
      if (digits[keep] >= "5") scaled = incrementDigits(keep === 0 ? "0" : scaled);
    }
  }

  const padded = scaled.padStart(decimals + 1, "0");
  const int = padded.slice(0, padded.length - decimals).replace(/^0+(?=\d)/, "");
  return { int, frac: padded.slice(padded.length - decimals) };
}

function incrementDigits(digits: string): string {
  const chars = digits.split("");
  for (let i = chars.length - 1; i >= 0; i--) {
    if (chars[i] === "9") {
      chars[i] = "0";
    } else {
      chars[i] = String(Number(chars[i]) + 1);
      return chars.join("");
    }
  }
  return "1" + chars.join("");
}

/** The General format: the value at 15 significant digits, nothing more. */
function formatGeneral(value: number): string {
  return String(Number(value.toPrecision(15))).toUpperCase();
}

function renderNumber(tokens: Token[], value: number, autoSign: boolean): string {
  const exponentAt = tokens.findIndex((t) => t.kind === "exponent");
  const numberEnd = exponentAt === -1 ? tokens.length : exponentAt;
  const pointAt = tokens.findIndex((t, i) => t.kind === "point" && i < numberEnd);
  const intEnd = pointAt === -1 ? numberEnd : pointAt;

  const intDigits: number[] = [];
  const fracDigits: number[] = [];
  const expDigits: number[] = [];
  tokens.forEach((t, i) => {
    if (t.kind !== "digit") return;
    if (i < intEnd) intDigits.push(i);
    else if (i < numberEnd) fracDigits.push(i);
    else expDigits.push(i);
  });

  if (intDigits.length + fracDigits.length === 0) {
    // No placeholders: a literal-only section, or General / @ with literals.
    const general = tokens.some((t) => t.kind === "general") ? formatGeneral(Math.abs(value)) : "";
    const sign = autoSign && general !== "" && /[1-9]/.test(general) ? "-" : "";
    return sign + tokens.map((t) => (t.kind === "literal" ? t.text : t.kind === "general" ? general : "")).join("");
  }

  const lastNumberDigit = fracDigits.length > 0 ? fracDigits[fracDigits.length - 1] : intDigits[intDigits.length - 1];
  let shift = 0;
  let grouping = false;
  const hiddenCommas = new Set<number>();
  tokens.forEach((t, i) => {
    if (t.kind === "percent") shift += 2;
    if (t.kind !== "comma" || i >= numberEnd) return;
    hiddenCommas.add(i);
    if (i > lastNumberDigit) shift -= 3;
    else if (i < intEnd && intDigits.some((d) => d < i)) grouping = true;
  });

  const abs = Math.abs(value);
  const decimals = fracDigits.length;
  let exponent = 0;
  let rounded: { int: string; frac: string };

  if (exponentAt !== -1) {
    exponent = abs === 0 ? 0 : Number(abs.toExponential(14).split("e")[1]);
    rounded = roundDecimal(abs, decimals, shift - exponent);
    if (rounded.int.length > 1) {
      exponent += 1;
      rounded = roundDecimal(abs, decimals, shift - exponent);
    }
  } else {
    rounded = roundDecimal(abs, decimals, shift);
  }

  // Fraction: optional placeholders drop trailing zeros.
  let cut = decimals;
  while (cut > 0 && rounded.frac[cut - 1] === "0" && (tokens[fracDigits[cut - 1]] as { ch: string }).ch !== "0") cut--;
  const fracOut = new Map<number, string>();
  fracDigits.forEach((tokenIndex, n) => {
    const ch = (tokens[tokenIndex] as { ch: string }).ch;
    fracOut.set(tokenIndex, n < cut ? rounded.frac[n] : ch === "?" ? " " : "");
  });

  // Integer: filled right to left, the leftmost placeholder taking any overflow.
  const intOut = new Map<number, string>();
  const hasRequiredInt = intDigits.some((i) => (tokens[i] as { ch: string }).ch === "0");
  const intValue = rounded.int === "0" && !hasRequiredInt ? "" : rounded.int;
  if (grouping) {
    const zeros = intDigits.filter((i) => (tokens[i] as { ch: string }).ch === "0").length;
    const filled = intValue.padStart(zeros, "0").replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    intDigits.forEach((tokenIndex, n) => intOut.set(tokenIndex, n === 0 ? filled : ""));
  } else {
    let remaining = intValue;
    for (let n = intDigits.length - 1; n >= 0; n--) {
      const tokenIndex = intDigits[n];
      const ch = (tokens[tokenIndex] as { ch: string }).ch;
      if (n === 0) {
        intOut.set(tokenIndex, remaining !== "" ? remaining : ch === "0" ? "0" : ch === "?" ? " " : "");
      } else if (remaining !== "") {
        intOut.set(tokenIndex, remaining[remaining.length - 1]);
        remaining = remaining.slice(0, -1);
      } else {
        intOut.set(tokenIndex, ch === "0" ? "0" : ch === "?" ? " " : "");
      }
    }
  }

  const expText = String(Math.abs(exponent)).padStart(expDigits.length, "0");
  const nonZero = /[1-9]/.test(intValue + rounded.frac.slice(0, cut));
  let out = autoSign && nonZero ? "-" : "";

  tokens.forEach((t, i) => {
    switch (t.kind) {
      case "literal":
        out += t.text;
        break;
      case "digit":
        if (i < intEnd) out += intOut.get(i) ?? "";
        else if (i < numberEnd) out += fracOut.get(i) ?? "";
        else if (i === expDigits[0]) out += expText;
        break;
      case "point":
        if (i === pointAt && (cut > 0 || decimals === 0)) out += ".";
        break;
      case "comma":
        if (!hiddenCommas.has(i)) out += ",";
        break;
      case "percent":
        out += "%";
        break;
      case "exponent":
        out += t.text + (exponent < 0 ? "-" : t.sign === "+" ? "+" : "");
        break;
      case "general":
        out += formatGeneral(abs);
        break;
      default:
        break;
    }
  });

  return out;
}

function renderDate(tokens: Token[], value: number): string | null {
  let day = Math.floor(value);
  let ms = Math.round((value - day) * DAY_MS);
  if (ms >= DAY_MS) {
    day += 1;
    ms -= DAY_MS;
  }
  // UTC fields throughout; see serial-date.ts.
  const date = dateOfSerial(day);
  const seconds = Math.floor(ms / 1000);
  const hours = Math.floor(seconds / 3600);
  const twelveHour = tokens.some((t) => t.kind === "ampm");
  const pad = (n: number, width: number) => String(n).padStart(width, "0");

  // m / mm are minutes after an hour token or before a seconds token.
  const neighbour = (index: number, step: 1 | -1): string | undefined => {
    for (let i = index + step; i >= 0 && i < tokens.length; i += step) {
      const t = tokens[i];
      if (t.kind === "date") return t.text[0];
      if (t.kind !== "literal") return undefined;
    }
    return undefined;
  };
  const isMinute = (index: number): boolean => neighbour(index, -1) === "h" || neighbour(index, 1) === "s";

  // Only a code that shows a calendar date is limited to 9999-12-31; a time-only
  // code shows the time of any serial.
  const showsDate = tokens.some(
    (t, i) => t.kind === "date" && (t.text[0] === "y" || t.text[0] === "d" || (t.text[0] === "m" && !(t.text.length <= 2 && isMinute(i)))),
  );
  if (showsDate && day > MAX_SERIAL) return null;

  return tokens
    .map((t, i) => {
      if (t.kind === "literal") return t.text;
      // Number-code characters mean nothing in a date code; they are text there.
      if (t.kind === "comma") return ",";
      if (t.kind === "point") return ".";
      if (t.kind === "percent") return "%";
      if (t.kind === "digit") return t.ch;
      if (t.kind === "exponent") return t.text + t.sign;
      if (t.kind === "ampm") {
        const pm = hours >= 12;
        const [am, pmText] = t.text.split("/");
        return pm ? pmText : am;
      }
      if (t.kind !== "date") return "";

      const { text } = t;
      switch (text[0]) {
        case "y":
          return text.length <= 2 ? pad(date.getUTCFullYear() % 100, 2) : pad(date.getUTCFullYear(), 4);
        case "d":
          if (text.length === 1) return String(date.getUTCDate());
          if (text.length === 2) return pad(date.getUTCDate(), 2);
          if (text.length === 3) return WEEKDAYS[date.getUTCDay()].slice(0, 3);
          return WEEKDAYS[date.getUTCDay()];
        case "h": {
          const h = twelveHour ? hours % 12 || 12 : hours;
          return text.length === 1 ? String(h) : pad(h, 2);
        }
        case "s": {
          const s = seconds % 60;
          return text.length === 1 ? String(s) : pad(s, 2);
        }
        case "m": {
          if (text.length <= 2 && isMinute(i)) {
            const m = Math.floor(seconds / 60) % 60;
            return text.length === 1 ? String(m) : pad(m, 2);
          }
          const month = date.getUTCMonth();
          if (text.length === 1) return String(month + 1);
          if (text.length === 2) return pad(month + 1, 2);
          if (text.length === 3) return MONTHS[month].slice(0, 3);
          if (text.length === 4) return MONTHS[month];
          return MONTHS[month][0];
        }
        default:
          return "";
      }
    })
    .join("");
}

/**
 * Renders a number through a spreadsheet format code. Returns `null` when the
 * value cannot be shown in that code (a date past 9999-12-31, or a non-finite
 * number); `TEXT()` turns that into `#VALUE!`, the grid shows the raw value.
 */
export function formatWithCode(value: number, code: string): string | null {
  if (!Number.isFinite(value)) return null;

  const sections = splitSections(code);
  let section = sections[0];
  let autoSign = value < 0;

  if (value < 0 && sections.length >= 2) {
    section = sections[1];
    autoSign = false;
  } else if (value === 0 && sections.length >= 3) {
    section = sections[2];
  }

  if (code.trim() === "") return formatGeneral(value);

  const tokens = tokenize(section);

  if (tokens.some((t) => t.kind === "date" || t.kind === "ampm")) {
    return renderDate(tokens, value);
  }

  return renderNumber(tokens, value, autoSign);
}

import type { FormulaToken, FormulaTokenType } from "../../types/formula";

export function lexFormula(input: string): FormulaToken[] {
  const tokens: FormulaToken[] = [];
  const len = input.length;
  let i = 0;

  while (i < len) {
    const ch = input[i];

    // Whitespace
    if (ch === " " || ch === "\t") { i++; continue; }

    // Number
    if ((ch >= "0" && ch <= "9") || (ch === "." && i + 1 < len && input[i + 1] >= "0" && input[i + 1] <= "9")) {
      const pos = i;
      while (i < len && ((input[i] >= "0" && input[i] <= "9") || input[i] === ".")) i++;
      if (i < len && (input[i] === "e" || input[i] === "E")) {
        i++;
        if (i < len && (input[i] === "+" || input[i] === "-")) i++;
        while (i < len && input[i] >= "0" && input[i] <= "9") i++;
      }
      tokens.push({ type: "number", value: input.slice(pos, i), position: pos });
      continue;
    }

    // String
    if (ch === '"') {
      const pos = i;
      i++;
      while (i < len && input[i] !== '"') {
        if (input[i] === "\\") i++;
        i++;
      }
      i++; // closing quote
      tokens.push({ type: "string", value: input.slice(pos + 1, i - 1), position: pos });
      continue;
    }

    // Identifier (cell ref, range ref, sheet ref, function name, or boolean)
    if ((ch >= "A" && ch <= "Z") || (ch >= "a" && ch <= "z") || ch === "_") {
      const pos = i;
      i++;
      // Allow spaces in sheet names when followed by !
      while (i < len && ((input[i] >= "A" && input[i] <= "Z") || (input[i] >= "a" && input[i] <= "z") || (input[i] >= "0" && input[i] <= "9") || input[i] === "_" || input[i] === " ")) {
        // Only allow spaces if they're part of a sheet name (followed eventually by !)
        if (input[i] === " ") {
          let lookAhead = i + 1;
          while (lookAhead < len && input[lookAhead] === " ") lookAhead++;
          // Check if after the spaces there's more identifier chars followed by !
          if (lookAhead < len && ((input[lookAhead] >= "A" && input[lookAhead] <= "Z") || (input[lookAhead] >= "a" && input[lookAhead] <= "z") || (input[lookAhead] >= "0" && input[lookAhead] <= "9") || input[lookAhead] === "!")) {
            i++;
            continue;
          }
          break;
        }
        i++;
      }
      let word = input.slice(pos, i).trimEnd();
      i = pos + word.length;

      // Boolean
      if (word.toUpperCase() === "TRUE" || word.toUpperCase() === "FALSE") {
        tokens.push({ type: "boolean", value: word.toUpperCase(), position: pos });
        continue;
      }

      // Cross-sheet reference: SheetName!CellRef or SheetName!Range
      if (i < len && input[i] === "!") {
        const sheetName = word;
        i++; // skip !
        const refStart = i;
        while (i < len && ((input[i] >= "A" && input[i] <= "Z") || (input[i] >= "a" && input[i] <= "z") || (input[i] >= "0" && input[i] <= "9"))) i++;
        const ref1 = input.slice(refStart, i);

        if (i < len && input[i] === ":") {
          // Sheet range ref: Sheet1!A1:B5
          i++;
          const ref2Start = i;
          while (i < len && ((input[i] >= "A" && input[i] <= "Z") || (input[i] >= "a" && input[i] <= "z") || (input[i] >= "0" && input[i] <= "9"))) i++;
          const ref2 = input.slice(ref2Start, i);
          tokens.push({ type: "sheetRangeRef", value: sheetName + "!" + ref1 + ":" + ref2, position: pos });
        } else {
          // Sheet cell ref: Sheet1!A1
          tokens.push({ type: "sheetCellRef", value: sheetName + "!" + ref1.toUpperCase(), position: pos });
        }
        continue;
      }

      // Check for range ref: CELLREF:CELLREF
      if (i < len && input[i] === ":") {
        const colonPos = i;
        i++;
        const rangeStart = i;
        while (i < len && ((input[i] >= "A" && input[i] <= "Z") || (input[i] >= "a" && input[i] <= "z") || (input[i] >= "0" && input[i] <= "9"))) i++;
        if (i > rangeStart) {
          tokens.push({ type: "rangeRef", value: word + ":" + input.slice(rangeStart, i), position: pos });
          continue;
        }
        i = colonPos;
      }

      // Check if it's a function call (followed by parenthesis)
      let j = i;
      while (j < len && input[j] === " ") j++;
      if (j < len && input[j] === "(") {
        tokens.push({ type: "function", value: word.toUpperCase(), position: pos });
        continue;
      }

      // Cell reference (letters + digits)
      if (/^[A-Z]+\d+$/i.test(word)) {
        tokens.push({ type: "cellRef", value: word.toUpperCase(), position: pos });
        continue;
      }

      // Unknown identifier — treat as cell ref
      tokens.push({ type: "cellRef", value: word.toUpperCase(), position: pos });
      continue;
    }

    // Operators
    if (ch === "+" || ch === "-" || ch === "*" || ch === "/" || ch === "^" || ch === "&") {
      tokens.push({ type: "operator", value: ch, position: i });
      i++;
      continue;
    }

    // Comparison operators
    if (ch === "=" || ch === "<" || ch === ">") {
      const pos = i;
      i++;
      if (i < len && (input[i] === "=" || input[i] === ">")) i++;
      tokens.push({ type: "operator", value: input.slice(pos, i), position: pos });
      continue;
    }

    // Parentheses
    if (ch === "(" || ch === ")") {
      tokens.push({ type: "paren", value: ch, position: i });
      i++;
      continue;
    }

    // Comma
    if (ch === ",") {
      tokens.push({ type: "comma", value: ",", position: i });
      i++;
      continue;
    }

    // Skip unknown
    i++;
  }

  return tokens;
}

import type { FormulaToken, FormulaASTNode } from "../../types/formula";

/**
 * Hard cap on parser recursion depth. Prevents stack overflow / tab freeze
 * from deeply nested formulas like `=((((((1))))))` x N. 64 is generous —
 * legitimate formulas rarely nest beyond ~20.
 */
const MAX_DEPTH = 64;

/**
 * Recursive descent parser for spreadsheet formulas.
 * Operator precedence (low to high):
 *   1. Comparison: =, <>, <, >, <=, >=
 *   2. String concatenation: &
 *   3. Addition/subtraction: +, -
 *   4. Multiplication/division: *, /
 *   5. Exponentiation: ^
 *   6. Unary: -, +
 *   7. Atoms: number, string, boolean, cellRef, rangeRef, function call, (expr)
 */
export function parseFormula(tokens: FormulaToken[]): FormulaASTNode {
  let pos = 0;

  function peek(): FormulaToken | undefined {
    return tokens[pos];
  }

  function advance(): FormulaToken {
    return tokens[pos++];
  }

  function expect(type: string, value?: string): FormulaToken {
    const t = advance();
    if (!t || t.type !== type || (value !== undefined && t.value !== value)) {
      throw new Error(`Expected ${type}${value ? ` '${value}'` : ""} at position ${t?.position ?? pos}`);
    }
    return t;
  }

  function checkDepth(depth: number): void {
    if (depth > MAX_DEPTH) {
      throw new Error(`Formula nested too deep (max ${MAX_DEPTH} levels)`);
    }
  }

  // Precedence levels — every level threads `depth` so we can cap recursion.
  function parseExpression(depth = 0): FormulaASTNode {
    checkDepth(depth);
    return parseComparison(depth + 1);
  }

  function parseComparison(depth: number): FormulaASTNode {
    let left = parseConcatenation(depth + 1);
    while (peek() && peek()!.type === "operator" && ["=", "<>", "<", ">", "<=", ">="].includes(peek()!.value)) {
      const op = advance().value;
      const right = parseConcatenation(depth + 1);
      left = { type: "binaryOp", operator: op, left, right };
    }
    return left;
  }

  function parseConcatenation(depth: number): FormulaASTNode {
    checkDepth(depth);
    let left = parseAddition(depth + 1);
    while (peek() && peek()!.type === "operator" && peek()!.value === "&") {
      advance();
      const right = parseAddition(depth + 1);
      left = { type: "binaryOp", operator: "&", left, right };
    }
    return left;
  }

  function parseAddition(depth: number): FormulaASTNode {
    checkDepth(depth);
    let left = parseMultiplication(depth + 1);
    while (peek() && peek()!.type === "operator" && (peek()!.value === "+" || peek()!.value === "-")) {
      const op = advance().value;
      const right = parseMultiplication(depth + 1);
      left = { type: "binaryOp", operator: op, left, right };
    }
    return left;
  }

  function parseMultiplication(depth: number): FormulaASTNode {
    checkDepth(depth);
    let left = parseExponentiation(depth + 1);
    while (peek() && peek()!.type === "operator" && (peek()!.value === "*" || peek()!.value === "/")) {
      const op = advance().value;
      const right = parseExponentiation(depth + 1);
      left = { type: "binaryOp", operator: op, left, right };
    }
    return left;
  }

  function parseExponentiation(depth: number): FormulaASTNode {
    checkDepth(depth);
    let left = parseUnary(depth + 1);
    while (peek() && peek()!.type === "operator" && peek()!.value === "^") {
      advance();
      const right = parseUnary(depth + 1);
      left = { type: "binaryOp", operator: "^", left, right };
    }
    return left;
  }

  function parseUnary(depth: number): FormulaASTNode {
    checkDepth(depth);
    if (peek() && peek()!.type === "operator" && (peek()!.value === "-" || peek()!.value === "+")) {
      const op = advance().value;
      const operand = parseUnary(depth + 1);
      return { type: "unaryOp", operator: op, operand };
    }
    return parseAtom(depth + 1);
  }

  function parseAtom(depth: number): FormulaASTNode {
    checkDepth(depth);
    const t = peek();
    if (!t) throw new Error("Unexpected end of formula");

    // Number
    if (t.type === "number") {
      advance();
      return { type: "number", value: parseFloat(t.value) };
    }

    // String
    if (t.type === "string") {
      advance();
      return { type: "string", value: t.value };
    }

    // Boolean
    if (t.type === "boolean") {
      advance();
      return { type: "boolean", value: t.value === "TRUE" };
    }

    // Range reference (A1:B5)
    if (t.type === "rangeRef") {
      advance();
      const parts = t.value.split(":");
      return { type: "rangeRef", start: parts[0], end: parts[1] };
    }

    // Cross-sheet cell reference (Sheet1!A1)
    if (t.type === "sheetCellRef") {
      advance();
      const bangIdx = t.value.indexOf("!");
      return { type: "sheetCellRef", sheet: t.value.slice(0, bangIdx), address: t.value.slice(bangIdx + 1).toUpperCase() };
    }

    // Cross-sheet range reference (Sheet1!A1:B5)
    if (t.type === "sheetRangeRef") {
      advance();
      const bangIdx = t.value.indexOf("!");
      const sheetName = t.value.slice(0, bangIdx);
      const rangePart = t.value.slice(bangIdx + 1);
      const parts = rangePart.split(":");
      return { type: "sheetRangeRef", sheet: sheetName, start: parts[0].toUpperCase(), end: parts[1].toUpperCase() };
    }

    // Function call
    if (t.type === "function") {
      const name = advance().value;
      expect("paren", "(");
      const args: FormulaASTNode[] = [];
      if (peek() && !(peek()!.type === "paren" && peek()!.value === ")")) {
        args.push(parseExpression(depth + 1));
        while (peek() && peek()!.type === "comma") {
          advance();
          args.push(parseExpression(depth + 1));
        }
      }
      expect("paren", ")");
      return { type: "functionCall", name, args };
    }

    // Cell reference
    if (t.type === "cellRef") {
      advance();
      return { type: "cellRef", address: t.value };
    }

    // Parenthesized expression
    if (t.type === "paren" && t.value === "(") {
      advance();
      const expr = parseExpression(depth + 1);
      expect("paren", ")");
      return expr;
    }

    throw new Error(`Unexpected token '${t.value}' at position ${t.position}`);
  }

  const ast = parseExpression(0);
  return ast;
}

import type { FormulaASTNode } from "../../types/formula";
import type { CellValue } from "../../types/cell";
import { getFunction } from "./functions/registry";
import { parseAddress, toAddress } from "../cell-utils";

// Import side-effect function registrations
import "./functions/math";
import "./functions/text";
import "./functions/logic";
import "./functions/conditional";
import "./functions/lookup";
import "./functions/datetime";
import "./functions/info";

export type CellValueGetter = (address: string) => CellValue;
export type RangeValueGetter = (start: string, end: string) => CellValue[];
export type SheetCellValueGetter = (sheetName: string, address: string) => CellValue;
export type SheetRangeValueGetter = (sheetName: string, start: string, end: string) => CellValue[];

export interface EvaluatorContext {
  getCellValue: CellValueGetter;
  getRangeValues: RangeValueGetter;
  getSheetCellValue?: SheetCellValueGetter;
  getSheetRangeValues?: SheetRangeValueGetter;
}

export function evaluateAST(
  node: FormulaASTNode,
  getCellValue: CellValueGetter,
  getRangeValues: RangeValueGetter,
  ctx?: { getSheetCellValue?: SheetCellValueGetter; getSheetRangeValues?: SheetRangeValueGetter },
): CellValue {
  switch (node.type) {
    case "number":
      return node.value;
    case "string":
      return node.value;
    case "boolean":
      return node.value;

    case "cellRef":
      return getCellValue(node.address);

    case "rangeRef": {
      const vals = getRangeValues(node.start, node.end);
      return vals[0] ?? null;
    }

    case "sheetCellRef": {
      if (!ctx?.getSheetCellValue) return "#REF!";
      return ctx.getSheetCellValue(node.sheet, node.address);
    }

    case "sheetRangeRef": {
      if (!ctx?.getSheetRangeValues) return "#REF!";
      const vals = ctx.getSheetRangeValues(node.sheet, node.start, node.end);
      return vals[0] ?? null;
    }

    case "functionCall": {
      const entry = getFunction(node.name);
      if (!entry) return `#NAME?`;

      const argValues: CellValue[][] = node.args.map((arg) => {
        if (arg.type === "rangeRef") {
          return getRangeValues(arg.start, arg.end);
        }
        if (arg.type === "sheetRangeRef") {
          if (!ctx?.getSheetRangeValues) return ["#REF!" as CellValue];
          return ctx.getSheetRangeValues(arg.sheet, arg.start, arg.end);
        }
        const val = evaluateAST(arg, getCellValue, getRangeValues, ctx);
        return [val];
      });

      try {
        return entry.fn(argValues);
      } catch {
        return "#ERROR!";
      }
    }

    case "binaryOp": {
      const left = evaluateAST(node.left, getCellValue, getRangeValues, ctx);
      const right = evaluateAST(node.right, getCellValue, getRangeValues, ctx);

      const lNum = typeof left === "number" ? left : Number(left);
      const rNum = typeof right === "number" ? right : Number(right);

      switch (node.operator) {
        case "+": return (isNaN(lNum) || isNaN(rNum)) ? "#VALUE!" : lNum + rNum;
        case "-": return (isNaN(lNum) || isNaN(rNum)) ? "#VALUE!" : lNum - rNum;
        case "*": return (isNaN(lNum) || isNaN(rNum)) ? "#VALUE!" : lNum * rNum;
        case "/": return rNum === 0 ? "#DIV/0!" : (isNaN(lNum) || isNaN(rNum)) ? "#VALUE!" : lNum / rNum;
        case "^": return (isNaN(lNum) || isNaN(rNum)) ? "#VALUE!" : Math.pow(lNum, rNum);
        case "&": return String(left ?? "") + String(right ?? "");
        case "=": return left === right;
        case "<>": return left !== right;
        case "<": return lNum < rNum;
        case ">": return lNum > rNum;
        case "<=": return lNum <= rNum;
        case ">=": return lNum >= rNum;
        default: return "#ERROR!";
      }
    }

    case "unaryOp": {
      const operand = evaluateAST(node.operand, getCellValue, getRangeValues, ctx);
      const num = typeof operand === "number" ? operand : Number(operand);
      if (isNaN(num)) return "#VALUE!";
      return node.operator === "-" ? -num : num;
    }

    default:
      return "#ERROR!";
  }
}

import type { CellMap } from "../../types/sheet";
import { lexFormula } from "./lexer";
import { parseFormula } from "./parser";
import { extractReferences } from "./references";

/** Build a dependency graph: cell -> cells it depends on */
export function buildDependencyGraph(cells: CellMap): Map<string, Set<string>> {
  const graph = new Map<string, Set<string>>();

  for (const [addr, cell] of Object.entries(cells)) {
    if (!cell.formula) continue;
    try {
      const tokens = lexFormula(cell.formula);
      const ast = parseFormula(tokens);
      const refs = extractReferences(ast);
      graph.set(addr, new Set(refs));
    } catch {
      graph.set(addr, new Set());
    }
  }

  return graph;
}

/** Detect circular references using DFS */
export function detectCircularRefs(graph: Map<string, Set<string>>): Set<string> {
  const circular = new Set<string>();
  const visited = new Set<string>();
  const inStack = new Set<string>();

  function dfs(node: string): boolean {
    if (inStack.has(node)) return true;
    if (visited.has(node)) return false;

    visited.add(node);
    inStack.add(node);

    const deps = graph.get(node);
    if (deps) {
      for (const dep of deps) {
        if (dfs(dep)) {
          circular.add(node);
          return true;
        }
      }
    }

    inStack.delete(node);
    return false;
  }

  for (const node of graph.keys()) {
    dfs(node);
  }

  return circular;
}

/** Get cells that need recalculation in topological order */
export function getRecalculationOrder(graph: Map<string, Set<string>>): string[] {
  const visited = new Set<string>();
  const order: string[] = [];

  function visit(node: string): void {
    if (visited.has(node)) return;
    visited.add(node);

    const deps = graph.get(node);
    if (deps) {
      for (const dep of deps) {
        visit(dep);
      }
    }

    order.push(node);
  }

  for (const node of graph.keys()) {
    visit(node);
  }

  return order;
}

import { useCallback, useRef } from "react";
import { useSpreadsheet } from "../Spreadsheet/Spreadsheet.context";

interface ColumnResizeHandleProps {
  colIndex: number;
}

export function ColumnResizeHandle({ colIndex }: ColumnResizeHandleProps) {
  const { resizeColumn, getColumnWidth } = useSpreadsheet();
  const startX = useRef(0);
  const startWidth = useRef(0);

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      e.stopPropagation();
      startX.current = e.clientX;
      startWidth.current = getColumnWidth(colIndex);
      const target = e.currentTarget as HTMLElement;
      target.setPointerCapture(e.pointerId);

      const handlePointerMove = (ev: PointerEvent) => {
        const delta = ev.clientX - startX.current;
        resizeColumn(colIndex, startWidth.current + delta);
      };

      const handlePointerUp = () => {
        target.removeEventListener("pointermove", handlePointerMove);
        target.removeEventListener("pointerup", handlePointerUp);
      };

      target.addEventListener("pointermove", handlePointerMove);
      target.addEventListener("pointerup", handlePointerUp);
    },
    [colIndex, getColumnWidth, resizeColumn],
  );

  return (
    <div
      data-fancy-sheets-resize-handle=""
      className="absolute right-0 top-0 h-full w-1 cursor-col-resize hover:bg-blue-500/50"
      onPointerDown={handlePointerDown}
    />
  );
}

