import { useCallback, useRef, useState } from "react";

/**
 * One state slot that works controlled or uncontrolled.
 *
 * ---------------------------------------------------------------------------
 * Why the value is tracked in a ref (fixed 5.32.0)
 * ---------------------------------------------------------------------------
 *
 * This resolved a functional update against the RENDER CLOSURE's `value` and then
 * handed React an already-computed value:
 *
 *     const nextValue = typeof next === "function" ? next(value) : next;
 *     setUncontrolledValue(nextValue);
 *
 * So `setValue(fn)` twice in one batch had both calls compute from the same stale
 * `value`, and **the first update was silently lost.** React's own `setState`
 * updater form does not have that problem precisely because React resolves it
 * against the latest state; passing a pre-computed value gives that up.
 *
 * Found by a hook test that paste-held two items inside one `act()` and got one.
 * It is not an exotic case — any caller that loops, or handles two events in a
 * batch, hits it, and the symptom is a dropped update with nothing to indicate one
 * happened.
 *
 * The fix cannot be "pass the updater to React", because `onChange` has to be
 * called with the resulting value and an updater must stay pure — React may invoke
 * it twice (StrictMode), which would fire `onChange` twice. So the previous value
 * comes from a ref that is re-synced from the authoritative `value` on every render
 * and advanced on every set. Within a batch the ref carries intent; after a render
 * the real value wins.
 *
 * A side effect worth having: `setValue` no longer depends on `value`, so it is
 * stable for the life of the component.
 */
export function useControllableState<T>(
  controlledValue: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T | ((prev: T) => T)) => void] {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  // Re-synced every render from whichever side owns the value. A controlled parent
  // that ignores `onChange` therefore wins on the next render rather than being
  // overridden by what this hook optimistically recorded.
  const valueRef = useRef(value);
  valueRef.current = value;

  const isControlledRef = useRef(isControlled);
  isControlledRef.current = isControlled;

  const setValue = useCallback((next: T | ((prev: T) => T)) => {
    const nextValue =
      typeof next === "function"
        ? (next as (prev: T) => T)(valueRef.current)
        : next;

    // Advance the ref BEFORE notifying, so a second call in the same batch builds
    // on this one instead of on what the last render saw.
    valueRef.current = nextValue;

    if (!isControlledRef.current) {
      setUncontrolledValue(nextValue);
    }

    onChangeRef.current?.(nextValue);
  }, []);

  return [value, setValue];
}

import { useEffect, type RefObject } from "react";

export function useOutsideClick(
  ref: RefObject<HTMLElement | null>,
  handler: (event: MouseEvent | TouchEvent) => void,
  enabled: boolean = true,
  ignoreRef?: RefObject<HTMLElement | null>,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: MouseEvent | TouchEvent) => {
      const el = ref.current;
      if (!el || el.contains(event.target as Node)) return;
      // Ignore clicks on the trigger/anchor element — the trigger's
      // own onClick handler manages toggling.
      if (ignoreRef?.current?.contains(event.target as Node)) return;
      handler(event);
    };

    document.addEventListener("mousedown", listener);
    document.addEventListener("touchstart", listener);

    return () => {
      document.removeEventListener("mousedown", listener);
      document.removeEventListener("touchstart", listener);
    };
  }, [ref, handler, enabled, ignoreRef]);
}

import { useEffect } from "react";

export function useEscapeKey(
  handler: () => void,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const listener = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        handler();
      }
    };

    document.addEventListener("keydown", listener);
    return () => document.removeEventListener("keydown", listener);
  }, [handler, enabled]);
}

import { useEffect, type RefObject } from "react";

const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled])",
  "textarea:not([disabled])",
  "select:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(", ");

export function useFocusTrap(
  ref: RefObject<HTMLElement | null>,
  enabled: boolean = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const el = ref.current;
    if (!el) return;

    const previouslyFocused = document.activeElement as HTMLElement | null;

    const focusables = () =>
      Array.from(el.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR));

    // Focus first focusable element
    const first = focusables()[0];
    first?.focus();

    const listener = (event: KeyboardEvent) => {
      if (event.key !== "Tab") return;

      const items = focusables();
      if (items.length === 0) return;

      const firstItem = items[0];
      const lastItem = items[items.length - 1];

      if (event.shiftKey) {
        if (document.activeElement === firstItem) {
          event.preventDefault();
          lastItem.focus();
        }
      } else {
        if (document.activeElement === lastItem) {
          event.preventDefault();
          firstItem.focus();
        }
      }
    };

    el.addEventListener("keydown", listener);

    return () => {
      el.removeEventListener("keydown", listener);
      previouslyFocused?.focus();
    };
  }, [ref, enabled]);
}

import { useCallback, useEffect, useState, type RefObject } from "react";
import type { Placement } from "../utils/types";

interface FloatingPosition {
  x: number;
  y: number;
  placement: Placement;
}

interface UseFloatingPositionOptions {
  placement?: Placement;
  offset?: number;
  enabled?: boolean;
}

function getPosition(
  anchor: DOMRect,
  floating: DOMRect,
  placement: Placement,
  offset: number,
): FloatingPosition {
  let x = 0;
  let y = 0;
  const base = placement.split("-")[0] as "top" | "bottom" | "left" | "right";
  const align = placement.split("-")[1] as "start" | "end" | undefined;

  switch (base) {
    case "top":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.top - floating.height - offset;
      break;
    case "bottom":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.bottom + offset;
      break;
    case "left":
      x = anchor.left - floating.width - offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
    case "right":
      x = anchor.right + offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
  }

  if (base === "top" || base === "bottom") {
    if (align === "start") x = anchor.left;
    else if (align === "end") x = anchor.right - floating.width;
  }

  if (base === "left" || base === "right") {
    if (align === "start") y = anchor.top;
    else if (align === "end") y = anchor.bottom - floating.height;
  }

  // Viewport clamping
  let finalPlacement = placement;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  if (base === "bottom" && y + floating.height > vh) {
    y = anchor.top - floating.height - offset;
    finalPlacement = placement.replace("bottom", "top") as Placement;
  } else if (base === "top" && y < 0) {
    y = anchor.bottom + offset;
    finalPlacement = placement.replace("top", "bottom") as Placement;
  }

  x = Math.max(4, Math.min(x, vw - floating.width - 4));
  y = Math.max(4, Math.min(y, vh - floating.height - 4));

  return { x, y, placement: finalPlacement };
}

export function useFloatingPosition(
  anchorRef: RefObject<HTMLElement | null>,
  floatingRef: RefObject<HTMLElement | null>,
  options: UseFloatingPositionOptions = {},
): FloatingPosition {
  const { placement = "bottom", offset = 8, enabled = true } = options;
  const [position, setPosition] = useState<FloatingPosition>({
    x: -9999,
    y: -9999,
    placement,
  });

  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const floating = floatingRef.current;
    if (!anchor || !floating) return;

    const anchorRect = anchor.getBoundingClientRect();
    const floatingRect = floating.getBoundingClientRect();
    const next = getPosition(anchorRect, floatingRect, placement, offset);
    // Bail out when nothing changed so this can run after every commit
    // (below) without causing an infinite render loop.
    setPosition((prev) =>
      prev.x === next.x && prev.y === next.y && prev.placement === next.placement
        ? prev
        : next,
    );
  }, [anchorRef, floatingRef, placement, offset]);

  // Re-measure after every commit while open.
  //
  // The floating element mounts a frame or two AFTER `enabled` flips — its
  // render is gated behind a state flip (e.g. useAnimation's `mounted`), so at
  // the moment `enabled` turns true the floating ref is still null and a single
  // measurement no-ops, leaving the popover parked at its off-screen sentinel.
  //
  // A passive effect with no deps runs after *every* commit — including the one
  // that finally mounts the floating element — and, crucially, keeps running in
  // hidden/background tabs where `requestAnimationFrame` is paused. The bail-out
  // in `update` makes the steady-state calls free, so this both fixes the
  // late-mount race and survives tab-visibility throttling.
  useEffect(() => {
    if (enabled) update();
  });

  // …but the per-commit effect ISN'T enough when the floating element mounts
  // through a <Portal> whose own mount gate (SSR-safe; renders nothing until its
  // useEffect runs) attaches the node WITHOUT re-rendering this hook's component.
  // Then no commit happens here, the measurement never runs, and the popover
  // stays parked at its off-screen sentinel until an unrelated scroll/resize
  // fires `update()` — the "menu only appears after I scroll" bug. Poll with rAF
  // until the node is actually in the DOM, measure it, then keep it observed for
  // size changes (async content / lazily-loaded icons).
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    let ro: ResizeObserver | null = null;
    const tick = () => {
      const el = floatingRef.current;
      if (el) {
        update();
        if (typeof ResizeObserver !== "undefined") {
          ro = new ResizeObserver(() => update());
          ro.observe(el);
        }
      } else {
        raf = requestAnimationFrame(tick);
      }
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      ro?.disconnect();
    };
  }, [enabled, update, floatingRef]);

  // Park off-screen when closed so the next open re-measures from scratch.
  useEffect(() => {
    if (!enabled) {
      setPosition((prev) =>
        prev.x === -9999 ? prev : { x: -9999, y: -9999, placement },
      );
    }
  }, [enabled, placement]);

  // Reposition on scroll/resize while open.
  useEffect(() => {
    if (!enabled) return;

    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);

    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [update, enabled]);

  return position;
}

import { useCallback, useEffect, useRef, useState } from "react";

interface UseAnimationOptions {
  open: boolean;
  enterClass: string;
  exitClass: string;
}

interface UseAnimationReturn {
  mounted: boolean;
  className: string;
  ref: React.RefObject<HTMLElement | null>;
}

export function useAnimation({
  open,
  enterClass,
  exitClass,
}: UseAnimationOptions): UseAnimationReturn {
  const [mounted, setMounted] = useState(open);
  const [animClass, setAnimClass] = useState(open ? enterClass : "");
  const ref = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (open) {
      setMounted(true);
      setAnimClass(enterClass);
    } else if (mounted) {
      setAnimClass(exitClass);
    }
  }, [open, enterClass, exitClass, mounted]);

  const handleAnimationEnd = useCallback(() => {
    if (!open) {
      setMounted(false);
      setAnimClass("");
    }
  }, [open]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    el.addEventListener("animationend", handleAnimationEnd);
    return () => el.removeEventListener("animationend", handleAnimationEnd);
  }, [handleAnimationEnd, mounted]);

  return { mounted, className: animClass, ref };
}

import { useId as useReactId } from "react";

export function useId(prefix?: string): string {
  const id = useReactId();
  return prefix ? `${prefix}-${id}` : id;
}

import { useCallback, useEffect, useRef } from "react";

export interface ViewportState {
  panX: number;
  panY: number;
  zoom: number;
}

interface UsePanZoomOptions {
  viewport: ViewportState;
  setViewport: (vp: ViewportState | ((prev: ViewportState) => ViewportState)) => void;
  minZoom: number;
  maxZoom: number;
  pannable: boolean;
  zoomable: boolean;
  containerRef: React.RefObject<HTMLElement | null>;
}

interface UsePanZoomReturn {
  containerProps: {
    onPointerDown: (e: React.PointerEvent) => void;
    onPointerMove: (e: React.PointerEvent) => void;
    onPointerUp: (e: React.PointerEvent) => void;
  };
  isPanning: boolean;
}

export function usePanZoom({
  viewport,
  setViewport,
  minZoom,
  maxZoom,
  pannable,
  zoomable,
  containerRef,
}: UsePanZoomOptions): UsePanZoomReturn {
  const isPanningRef = useRef(false);
  const startRef = useRef({ x: 0, y: 0, panX: 0, panY: 0 });

  // Store latest values in refs so the native wheel listener always sees current state
  const viewportRef = useRef(viewport);
  viewportRef.current = viewport;
  const setViewportRef = useRef(setViewport);
  setViewportRef.current = setViewport;
  const zoomableRef = useRef(zoomable);
  zoomableRef.current = zoomable;
  const minZoomRef = useRef(minZoom);
  minZoomRef.current = minZoom;
  const maxZoomRef = useRef(maxZoom);
  maxZoomRef.current = maxZoom;

  // Attach a non-passive wheel listener so preventDefault() actually stops page scroll
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    function handleWheel(e: WheelEvent) {
      if (!zoomableRef.current) return;
      // Require Ctrl+wheel (or pinch gesture) to zoom — don't hijack normal page scroll
      if (!e.ctrlKey && !e.metaKey) return;
      e.preventDefault();

      const rect = container!.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      setViewportRef.current((prev) => {
        const factor = 1 - e.deltaY * 0.001;
        const newZoom = Math.min(maxZoomRef.current, Math.max(minZoomRef.current, prev.zoom * factor));
        const ratio = newZoom / prev.zoom;

        return {
          zoom: newZoom,
          panX: mouseX - (mouseX - prev.panX) * ratio,
          panY: mouseY - (mouseY - prev.panY) * ratio,
        };
      });
    }

    container.addEventListener("wheel", handleWheel, { passive: false });
    return () => {
      container.removeEventListener("wheel", handleWheel);
    };
  }, [containerRef]);

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (!pannable) return;
      // Only pan on primary button and when clicking the background
      if (e.button !== 0) return;
      const target = e.target as HTMLElement;
      if (target !== containerRef.current && !target.hasAttribute("data-canvas-bg")) return;

      isPanningRef.current = true;
      startRef.current = { x: e.clientX, y: e.clientY, panX: viewport.panX, panY: viewport.panY };
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      e.preventDefault();
    },
    [pannable, viewport.panX, viewport.panY, containerRef],
  );

  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isPanningRef.current) return;
      const dx = e.clientX - startRef.current.x;
      const dy = e.clientY - startRef.current.y;
      setViewport((prev) => ({
        ...prev,
        panX: startRef.current.panX + dx,
        panY: startRef.current.panY + dy,
      }));
    },
    [setViewport],
  );

  const onPointerUp = useCallback(() => {
    isPanningRef.current = false;
  }, []);

  return {
    containerProps: { onPointerDown, onPointerMove, onPointerUp },
    isPanning: isPanningRef.current,
  };
}

import { useCallback, useRef, useState } from "react";

export interface NodeRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

interface UseNodeRegistryReturn {
  registerNode: (id: string, rect: NodeRect) => void;
  unregisterNode: (id: string) => void;
  nodeRects: Map<string, NodeRect>;
  version: number;
}

export function useNodeRegistry(): UseNodeRegistryReturn {
  const rectsRef = useRef(new Map<string, NodeRect>());
  const [version, setVersion] = useState(0);

  const registerNode = useCallback((id: string, rect: NodeRect) => {
    rectsRef.current.set(id, rect);
    setVersion((v) => v + 1);
  }, []);

  const unregisterNode = useCallback((id: string) => {
    rectsRef.current.delete(id);
    setVersion((v) => v + 1);
  }, []);

  return { registerNode, unregisterNode, nodeRects: rectsRef.current, version };
}

import { useCallback, useEffect, useState } from "react";
import {
    getThemePreference,
    resolveTheme,
    setThemePreference,
    subscribeTheme,
    type ResolvedTheme,
    type ThemePreference,
} from "../theme";

export type UseThemeResult = {
    /** What the user asked for, including `"system"`. */
    preference: ThemePreference;
    /** What is actually on screen. */
    resolved: ResolvedTheme;
    setPreference: (preference: ThemePreference) => void;
};

/**
 * Read and set the theme from a component, re-rendering when it changes —
 * including when the OS theme changes underneath a `"system"` preference.
 *
 * The initial state is deliberately `system` / `light` rather than the real
 * theme: the server has neither storage nor an OS preference, so reading the
 * truth during render is exactly the hydration mismatch this project has
 * already chased down more than once. The effect syncs immediately on mount.
 */
export function useTheme(): UseThemeResult {
    const [state, setState] = useState<{ preference: ThemePreference; resolved: ResolvedTheme }>({
        preference: "system",
        resolved: "light",
    });

    useEffect(() => {
        const sync = (): void => {
            setState({ preference: getThemePreference(), resolved: resolveTheme() });
        };
        sync();
        return subscribeTheme(sync);
    }, []);

    const setPreference = useCallback((preference: ThemePreference): void => {
        setThemePreference(preference);
    }, []);

    return { ...state, setPreference };
}

/**
 * Light / dark / **system** theming.
 *
 * `styles.css` in this package defines the dark contract — it redefines the
 * whole `--color-secondary-*` scale under `:where(.dark)` so that "900" always
 * means strongest foreground and "50" always means faintest surface. This module
 * is the other half of that contract: the thing that decides when `.dark` is on.
 *
 * It lives here rather than in each app because every consumer was hand-rolling
 * it, and every hand-rolled copy had the same two holes:
 *
 *  - **No live listener.** The OS preference was read once at boot, so changing
 *    the system theme with the page open did nothing. That is a default, not a
 *    "system" mode.
 *  - **No way back.** Choosing light or dark wrote to storage forever, so
 *    "follow my system" was unreachable after a single click.
 *
 * Both are fixed by treating **"system" as the absence of a stored choice**
 * rather than as a third stored value.
 *
 * Every export is safe to call during SSR, where it is a no-op that resolves to
 * `"light"`. Pair it with `useTheme`, which deliberately renders `system/light`
 * on the server and syncs in an effect — this project has paid for hydration
 * mismatches caused by reading the real theme during render.
 */

export type ThemePreference = "light" | "dark" | "system";
export type ResolvedTheme = "light" | "dark";

/**
 * Deliberately the key the showcase already used, so adopting this module keeps
 * a returning visitor's saved choice instead of silently resetting it.
 */
export const THEME_STORAGE_KEY = "fancy-ui.theme";

const DARK_QUERY = "(prefers-color-scheme: dark)";

type ThemeListener = (resolved: ResolvedTheme, preference: ThemePreference) => void;

const listeners = new Set<ThemeListener>();
let storageKey = THEME_STORAGE_KEY;
let stopWatchingSystem: (() => void) | null = null;

function canUseDom(): boolean {
    return typeof window !== "undefined" && typeof document !== "undefined";
}

/** The stored choice, or `"system"` when there isn't one. */
export function getThemePreference(): ThemePreference {
    if (!canUseDom()) return "system";
    try {
        const saved = window.localStorage.getItem(storageKey);
        return saved === "light" || saved === "dark" ? saved : "system";
    } catch {
        // Private browsing and blocked storage both throw here. A theme is not
        // worth taking the page down over.
        return "system";
    }
}

function systemTheme(): ResolvedTheme {
    if (!canUseDom() || typeof window.matchMedia !== "function") return "light";
    return window.matchMedia(DARK_QUERY).matches ? "dark" : "light";
}

/** What is actually on screen, as opposed to what the user asked for. */
export function resolveTheme(preference: ThemePreference = getThemePreference()): ResolvedTheme {
    return preference === "system" ? systemTheme() : preference;
}

function applyToDocument(resolved: ResolvedTheme): void {
    if (!canUseDom()) return;
    const root = document.documentElement;
    // The class is what this package's CSS keys off; the attribute is for
    // consumers whose own styles key off `[data-theme]`.
    root.classList.toggle("dark", resolved === "dark");
    root.setAttribute("data-theme", resolved);
}

function publish(): void {
    const preference = getThemePreference();
    const resolved = resolveTheme(preference);
    applyToDocument(resolved);
    listeners.forEach((listener) => listener(resolved, preference));
}

/**
 * Choose a theme. `"system"` REMOVES the stored value rather than storing the
 * string — an absent choice is what lets the OS keep speaking for the user.
 */
export function setThemePreference(preference: ThemePreference): void {
    if (canUseDom()) {
        try {
            if (preference === "system") {
                window.localStorage.removeItem(storageKey);
            } else {
                window.localStorage.setItem(storageKey, preference);
            }
        } catch {
            // As above: still apply it for this page even if it cannot persist.
        }
    }
    publish();
}

/** Observe theme changes. Returns an unsubscribe. */
export function subscribeTheme(listener: ThemeListener): () => void {
    listeners.add(listener);
    return () => {
        listeners.delete(listener);
    };
}

/**
 * Apply the current theme and start following the OS. Call once, as early as
 * possible — before first paint if you want to avoid a flash of the wrong
 * theme. Returns a disposer; calling it again is harmless.
 */
export function initTheme(options: { storageKey?: string } = {}): () => void {
    if (options.storageKey) storageKey = options.storageKey;
    if (!canUseDom()) return () => {};

    applyToDocument(resolveTheme());

    if (!stopWatchingSystem && typeof window.matchMedia === "function") {
        const media = window.matchMedia(DARK_QUERY);
        const onSystemChange = (): void => {
            // Only "system" follows the OS. An explicit choice has to survive
            // the user switching their OS theme, or it isn't a choice.
            if (getThemePreference() === "system") publish();
        };

        if (typeof media.addEventListener === "function") {
            media.addEventListener("change", onSystemChange);
            stopWatchingSystem = () => media.removeEventListener("change", onSystemChange);
        } else {
            // Safari < 14 and friends.
            media.addListener(onSystemChange);
            stopWatchingSystem = () => media.removeListener(onSystemChange);
        }
    }

    return () => {
        stopWatchingSystem?.();
        stopWatchingSystem = null;
    };
}

import { Button, Input, Select } from "@particle-academy/react-fancy";
import type {
  SitemapChangeFreq,
  SitemapModel,
  SitemapUrl,
} from "../lib/model";
import { validateSitemap } from "../lib/validate";
import { IssueList, Section } from "./internal";

export interface SitemapEditorProps {
  value: SitemapModel;
  onChange: (next: SitemapModel) => void;
  hideIssues?: boolean;
  className?: string;
}

const CHANGE_FREQS: SitemapChangeFreq[] = [
  "always",
  "hourly",
  "daily",
  "weekly",
  "monthly",
  "yearly",
  "never",
];

/** Controlled sitemap.xml editor: a flat list of URL entries. */
export function SitemapEditor({
  value,
  onChange,
  hideIssues,
  className,
}: SitemapEditorProps) {
  const issues = validateSitemap(value);
  const patch = (next: Partial<SitemapModel>) => onChange({ ...value, ...next });

  const updateUrl = (index: number, next: Partial<SitemapUrl>) =>
    patch({
      urls: value.urls.map((u, i) => (i === index ? { ...u, ...next } : u)),
    });

  const addUrl = () => patch({ urls: [...value.urls, { loc: "" }] });

  const removeUrl = (index: number) =>
    patch({ urls: value.urls.filter((_, i) => i !== index) });

  return (
    <div className={className} data-x-editor="sitemap">
      <Section
        title="URLs"
        handle="sitemap-urls"
        action={
          <Button
            type="button"
            variant="ghost"
            onClick={addUrl}
            data-x-add="sitemap-url"
          >
            Add URL
          </Button>
        }
      >
        {value.urls.map((url, i) => (
          <div
            key={i}
            data-x-url={i}
            style={{
              border: "1px solid var(--rf-border, #e5e7eb)",
              borderRadius: "0.5rem",
              padding: "0.6rem",
              display: "flex",
              flexDirection: "column",
              gap: "0.4rem",
            }}
          >
            <div style={{ display: "flex", gap: "0.4rem", alignItems: "end" }}>
              <div style={{ flex: 1 }}>
                <Input
                  label="loc"
                  value={url.loc}
                  onValueChange={(loc) => updateUrl(i, { loc })}
                  placeholder="https://example.com/page"
                  data-x-input={`sitemap-loc:${i}`}
                />
              </div>
              <Button
                type="button"
                variant="ghost"
                color="red"
                onClick={() => removeUrl(i)}
                data-x-remove={`sitemap-url:${i}`}
              >
                ×
              </Button>
            </div>
            <div
              style={{
                display: "flex",
                gap: "0.4rem",
                flexWrap: "wrap",
              }}
            >
              <div style={{ flex: "1 1 9rem" }}>
                <Input
                  label="lastmod"
                  type="text"
                  value={url.lastmod ?? ""}
                  onValueChange={(v) =>
                    updateUrl(i, { lastmod: v || undefined })
                  }
                  placeholder="2026-01-01"
                  data-x-input={`sitemap-lastmod:${i}`}
                />
              </div>
              <div style={{ flex: "1 1 9rem" }}>
                <Select
                  label="changefreq"
                  value={url.changefreq ?? ""}
                  list={["", ...CHANGE_FREQS]}
                  onValueChange={(v) =>
                    updateUrl(i, {
                      changefreq: (v || undefined) as
                        | SitemapChangeFreq
                        | undefined,
                    })
                  }
                  data-x-input={`sitemap-changefreq:${i}`}
                />
              </div>
              <div style={{ flex: "1 1 6rem" }}>
                <Input
                  label="priority"
                  type="number"
                  value={url.priority != null ? String(url.priority) : ""}
                  onValueChange={(v) =>
                    updateUrl(i, {
                      priority: v === "" ? undefined : Number(v),
                    })
                  }
                  placeholder="0.5"
                  data-x-input={`sitemap-priority:${i}`}
                />
              </div>
            </div>
          </div>
        ))}
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="sitemap" />}
    </div>
  );
}

import { useState } from "react";
import { Badge, Button, Callout, Input } from "@particle-academy/react-fancy";

/**
 * Shared internal building blocks for the editors. Not exported from the
 * package root — these are implementation details of the editors.
 */

/** Surface a list of validation issues as a soft warning callout. */
export function IssueList({
  issues,
  testid,
}: {
  issues: string[];
  testid?: string;
}) {
  if (!issues.length) return null;
  return (
    <Callout color="amber" data-x-issues={testid ?? ""}>
      <ul style={{ margin: 0, paddingLeft: "1.1rem" }}>
        {issues.map((issue, i) => (
          <li key={i} data-x-issue>
            {issue}
          </li>
        ))}
      </ul>
    </Callout>
  );
}

/**
 * Controlled add/remove list of plain strings rendered as chips with an
 * inline "add a row" input. `disallowedValues` are rejected on add and, if
 * already present, flagged — used by RobotsEditor to keep protected paths out
 * of an Allow list.
 */
export function StringList({
  label,
  values,
  onChange,
  placeholder,
  handle,
  disallowedValues,
  disallowedReason,
}: {
  label?: string;
  values: string[];
  onChange: (next: string[]) => void;
  placeholder?: string;
  /** data-* handle base, e.g. "robots-allow". */
  handle: string;
  disallowedValues?: string[];
  disallowedReason?: (value: string) => string;
}) {
  const [draft, setDraft] = useState("");
  const blocked = new Set(disallowedValues ?? []);

  const add = () => {
    const v = draft.trim();
    if (!v || values.includes(v)) {
      setDraft("");
      return;
    }
    onChange([...values, v]);
    setDraft("");
  };

  const remove = (value: string) =>
    onChange(values.filter((v) => v !== value));

  return (
    <div data-x-list={handle}>
      {label ? (
        <div
          style={{ fontSize: "0.8rem", fontWeight: 600, marginBottom: "0.25rem" }}
        >
          {label}
        </div>
      ) : null}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "0.35rem",
          marginBottom: values.length ? "0.4rem" : 0,
        }}
      >
        {values.map((value) => {
          const isBlocked = blocked.has(value);
          return (
            <Badge
              key={value}
              color={isBlocked ? "red" : "slate"}
              variant={isBlocked ? "soft" : "outline"}
              data-x-chip={`${handle}:${value}`}
              title={
                isBlocked && disallowedReason
                  ? disallowedReason(value)
                  : undefined
              }
            >
              {value}
              <button
                type="button"
                onClick={() => remove(value)}
                aria-label={`Remove ${value}`}
                data-x-remove={`${handle}:${value}`}
                style={{
                  marginLeft: "0.35rem",
                  border: "none",
                  background: "transparent",
                  cursor: "pointer",
                  fontWeight: 700,
                }}
              >
                ×
              </button>
            </Badge>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: "0.4rem" }}>
        <Input
          value={draft}
          onValueChange={setDraft}
          placeholder={placeholder}
          data-x-input={`${handle}-draft`}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              add();
            }
          }}
        />
        <Button
          type="button"
          variant="ghost"
          onClick={add}
          data-x-add={handle}
        >
          Add
        </Button>
      </div>
    </div>
  );
}

/** A labelled section wrapper used to group fields inside an editor. */
export function Section({
  title,
  action,
  children,
  handle,
}: {
  title: string;
  action?: React.ReactNode;
  children: React.ReactNode;
  handle?: string;
}) {
  return (
    <section
      data-x-section={handle}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "0.5rem",
        marginBottom: "1rem",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <h4 style={{ margin: 0, fontSize: "0.9rem", fontWeight: 700 }}>
          {title}
        </h4>
        {action}
      </div>
      {children}
    </section>
  );
}

/**
 * TS model types for the well-known files modeled by `fancy-x-files`.
 *
 * These are intentionally small, standalone shapes (this package does NOT
 * import the PHP/JS port) so the editor builds + ships independently. They
 * mirror the canonical shapes emitted by the `fancy-x-files` packages.
 *
 * Every model is plain JSON: arrays of objects + primitives. That makes the
 * whole surface agent-emittable — an embedded agent can read the current
 * model, propose a new one, and hand it back through the same `onChange`
 * channel a human uses (Human+ UX contract).
 */

/** The well-known files this suite can edit + preview. */
export type XFileKind =
  | "robots"
  | "securityTxt"
  | "llmsTxt"
  | "humansTxt"
  | "sitemap"
  | "agents";

/** robots.txt — grouped crawl rules, sitemaps, host, protected paths. */
export interface RobotsGroup {
  /** `User-agent` lines for this group. `["*"]` for all. */
  userAgents: string[];
  /** `Allow:` paths. */
  allow: string[];
  /** `Disallow:` paths. */
  disallow: string[];
  /** Optional `Crawl-delay:` seconds. */
  crawlDelay?: number;
}

export interface RobotsModel {
  groups: RobotsGroup[];
  /** Absolute `Sitemap:` URLs. */
  sitemaps: string[];
  /**
   * Paths that must be Disallowed for every user-agent and may NEVER be
   * Allowed — mirrors the PHP `protect()` safety rail. The renderer pins
   * these as Disallow on every group; the editor refuses to Allow them.
   */
  protectedPaths: string[];
  /** Optional `Host:` directive. */
  host?: string;
}

/** security.txt (RFC 9116). */
export interface SecurityTxtModel {
  /** `Contact:` — one or more mailto:/https: URIs. At least one required. */
  contact: string[];
  /** `Expires:` — ISO 8601 timestamp; MUST be in the future. */
  expires: string;
  /** `Encryption:` URI. */
  encryption?: string;
  /** `Acknowledgments:` URI. */
  acknowledgments?: string;
  /** `Preferred-Languages:` comma-separated tags. */
  preferredLanguages?: string;
  /** `Canonical:` URI. */
  canonical?: string;
  /** `Policy:` URI. */
  policy?: string;
  /** `Hiring:` URI. */
  hiring?: string;
}

/** llms.txt — Markdown index of resources for LLMs. */
export interface LlmsLink {
  title: string;
  url: string;
  notes?: string;
}

export interface LlmsSection {
  name: string;
  links: LlmsLink[];
}

export interface LlmsTxtModel {
  title: string;
  /** The blockquote summary directly under the H1. */
  summary?: string;
  /** Free-form Markdown paragraph(s) of detail. */
  details?: string;
  sections: LlmsSection[];
}

/** humans.txt — credits + site colophon. */
export interface HumansTxtEntry {
  /** e.g. "Developer", "Designer". */
  role: string;
  name: string;
  /** Optional contact / handle / site. */
  contact?: string;
}

export interface HumansTxtModel {
  team: HumansTxtEntry[];
  /** "Site" section free-text (Standards, Components, Software, …). */
  site?: string;
  thanks?: string[];
}

/** sitemap.xml — a flat URL set. */
export type SitemapChangeFreq =
  | "always"
  | "hourly"
  | "daily"
  | "weekly"
  | "monthly"
  | "yearly"
  | "never";

export interface SitemapUrl {
  loc: string;
  /** ISO 8601 date. */
  lastmod?: string;
  changefreq?: SitemapChangeFreq;
  /** 0.0 – 1.0. */
  priority?: number;
}

export interface SitemapModel {
  urls: SitemapUrl[];
}

/**
 * /AGENTS — a machine-readable register of the agents allowed (or denied) to
 * act on the site, mirroring the robots-style "agent policy" idea.
 */
export interface AgentEntry {
  /** Stable identifier / handle for the agent. */
  id: string;
  /** Human label. */
  name?: string;
  /** Policy for this agent. */
  policy: "allow" | "deny";
  /** Optional homepage / contact URL. */
  url?: string;
  /** Optional one-line description of permitted scope. */
  scope?: string;
}

export interface AgentsModel {
  agents: AgentEntry[];
  /** Optional contact for policy questions. */
  contact?: string;
}

/** The aggregate value held by `XFilesManager`. */
export interface XFilesModel {
  robots?: RobotsModel;
  securityTxt?: SecurityTxtModel;
  llmsTxt?: LlmsTxtModel;
  humansTxt?: HumansTxtModel;
  sitemap?: SitemapModel;
  agents?: AgentsModel;
}

/** Map a file kind to its model type. */
export interface XFileModelMap {
  robots: RobotsModel;
  securityTxt: SecurityTxtModel;
  llmsTxt: LlmsTxtModel;
  humansTxt: HumansTxtModel;
  sitemap: SitemapModel;
  agents: AgentsModel;
}

/** Empty-but-valid starting models, handy for "add this file" affordances. */
export const emptyRobots = (): RobotsModel => ({
  groups: [{ userAgents: ["*"], allow: [], disallow: [] }],
  sitemaps: [],
  protectedPaths: [],
});

export const emptySecurityTxt = (): SecurityTxtModel => ({
  contact: [],
  expires: "",
});

export const emptyLlmsTxt = (): LlmsTxtModel => ({
  title: "",
  sections: [],
});

export const emptyHumansTxt = (): HumansTxtModel => ({ team: [] });

export const emptySitemap = (): SitemapModel => ({ urls: [] });

export const emptyAgents = (): AgentsModel => ({ agents: [] });

/** Human-readable label + on-disk filename for each kind. */
export const X_FILE_META: Record<
  XFileKind,
  { label: string; filename: string }
> = {
  robots: { label: "robots.txt", filename: "robots.txt" },
  securityTxt: { label: "security.txt", filename: ".well-known/security.txt" },
  llmsTxt: { label: "llms.txt", filename: "llms.txt" },
  humansTxt: { label: "humans.txt", filename: "humans.txt" },
  sitemap: { label: "sitemap.xml", filename: "sitemap.xml" },
  agents: { label: "AGENTS", filename: ".well-known/agents.json" },
};

/**
 * Validation helpers. Each `validate*` returns a flat `string[]` of
 * human-readable issues (empty array == valid). The editors surface these
 * inline, and an embedded agent can call them to check a proposal before
 * handing it back.
 */
import type {
  AgentsModel,
  HumansTxtModel,
  LlmsTxtModel,
  RobotsModel,
  SecurityTxtModel,
  SitemapModel,
  XFileKind,
} from "./model";

const looksLikeUrl = (s: string): boolean =>
  /^https?:\/\/\S+$/i.test(s.trim());

export function validateRobots(model: RobotsModel): string[] {
  const issues: string[] = [];
  if (!model.groups.length) {
    issues.push("At least one user-agent group is required.");
  }
  model.groups.forEach((group, i) => {
    const where = `Group ${i + 1}`;
    if (!group.userAgents.length) {
      issues.push(`${where}: needs at least one User-agent (use "*" for all).`);
    }
    // Protected paths must never be Allowed — mirrors PHP protect() safety.
    for (const path of group.allow) {
      if (model.protectedPaths.includes(path)) {
        issues.push(
          `${where}: "${path}" is a protected path and cannot be Allowed. Remove it from Allow or unprotect it.`,
        );
      }
    }
    if (group.crawlDelay != null && group.crawlDelay < 0) {
      issues.push(`${where}: Crawl-delay must be ≥ 0.`);
    }
  });
  for (const sm of model.sitemaps) {
    if (!looksLikeUrl(sm)) {
      issues.push(`Sitemap "${sm}" should be an absolute http(s) URL.`);
    }
  }
  return issues;
}

export function validateSecurityTxt(model: SecurityTxtModel): string[] {
  const issues: string[] = [];
  if (!model.contact.length || model.contact.every((c) => !c.trim())) {
    issues.push("At least one Contact is required (mailto: or https: URI).");
  }
  if (!model.expires) {
    issues.push("Expires is required.");
  } else {
    const when = new Date(model.expires);
    if (Number.isNaN(when.getTime())) {
      issues.push("Expires must be a valid date/time.");
    } else if (when.getTime() <= Date.now()) {
      issues.push("Expires must be a date in the future.");
    }
  }
  return issues;
}

export function validateLlmsTxt(model: LlmsTxtModel): string[] {
  const issues: string[] = [];
  if (!model.title.trim()) issues.push("Title is required.");
  model.sections.forEach((section, i) => {
    if (!section.name.trim()) {
      issues.push(`Section ${i + 1}: needs a name.`);
    }
    section.links.forEach((link, j) => {
      const where = `Section ${i + 1} · link ${j + 1}`;
      if (!link.title.trim()) issues.push(`${where}: needs a title.`);
      if (!looksLikeUrl(link.url)) {
        issues.push(`${where}: URL should be an absolute http(s) URL.`);
      }
    });
  });
  return issues;
}

export function validateHumansTxt(model: HumansTxtModel): string[] {
  const issues: string[] = [];
  model.team.forEach((m, i) => {
    if (!m.role.trim()) issues.push(`Team member ${i + 1}: needs a role.`);
    if (!m.name.trim()) issues.push(`Team member ${i + 1}: needs a name.`);
  });
  return issues;
}

export function validateSitemap(model: SitemapModel): string[] {
  const issues: string[] = [];
  if (!model.urls.length) issues.push("Add at least one URL.");
  model.urls.forEach((u, i) => {
    if (!looksLikeUrl(u.loc)) {
      issues.push(`URL ${i + 1}: <loc> should be an absolute http(s) URL.`);
    }
    if (u.priority != null && (u.priority < 0 || u.priority > 1)) {
      issues.push(`URL ${i + 1}: priority must be between 0.0 and 1.0.`);
    }
  });
  return issues;
}

export function validateAgents(model: AgentsModel): string[] {
  const issues: string[] = [];
  const seen = new Set<string>();
  model.agents.forEach((a, i) => {
    if (!a.id.trim()) {
      issues.push(`Agent ${i + 1}: needs an id.`);
    } else if (seen.has(a.id)) {
      issues.push(`Agent ${i + 1}: duplicate id "${a.id}".`);
    } else {
      seen.add(a.id);
    }
    if (a.url && !looksLikeUrl(a.url)) {
      issues.push(`Agent ${i + 1}: url should be an absolute http(s) URL.`);
    }
  });
  return issues;
}

/** Dispatch validation by file kind. */
export function validateModel(kind: XFileKind, model: unknown): string[] {
  switch (kind) {
    case "robots":
      return validateRobots(model as RobotsModel);
    case "securityTxt":
      return validateSecurityTxt(model as SecurityTxtModel);
    case "llmsTxt":
      return validateLlmsTxt(model as LlmsTxtModel);
    case "humansTxt":
      return validateHumansTxt(model as HumansTxtModel);
    case "sitemap":
      return validateSitemap(model as SitemapModel);
    case "agents":
      return validateAgents(model as AgentsModel);
  }
}

import { forwardRef } from "react";
import { cn } from "../lib/utils/cn";
import type { SkeletonProps } from "./Skeleton.types";

function toStyleValue(value: string | number | undefined): string | undefined {
  if (value === undefined) return undefined;
  return typeof value === "number" ? `${value}px` : value;
}

export const Skeleton = forwardRef<HTMLDivElement, SkeletonProps>(
  ({ shape = "rect", width, height, className }, ref) => {
    const style: React.CSSProperties = {
      width: toStyleValue(width),
      height: toStyleValue(height),
    };

    return (
      <div
        ref={ref}
        aria-hidden="true"
        data-react-fancy-skeleton=""
        className={cn(
          "animate-pulse bg-zinc-200 dark:bg-zinc-700",
          shape === "rect" && "rounded-lg",
          shape === "circle" && "rounded-full aspect-square",
          shape === "text" && "rounded h-4 w-full",
          className,
        )}
        style={style}
      />
    );
  },
);

Skeleton.displayName = "Skeleton";

export interface SkeletonProps {
  /** Shape of the skeleton placeholder */
  shape?: "rect" | "circle" | "text";
  /** Custom width (CSS value or number in px) */
  width?: string | number;
  /** Custom height (CSS value or number in px) */
  height?: string | number;
  /** Additional CSS classes */
  className?: string;
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useEffect, useMemo, useRef, useState, type CSSProperties, type PointerEvent as ReactPointerEvent, type ReactNode } from "react";
import type { ElementAnimation, Slide as SlideData, SlideElement, Theme } from "../lib/types";
import { resolveTheme } from "../lib/theme/theme-utils";
import { cn } from "../lib/utils/cn";
import { buildSteps, stepDelays, paragraphReveals, type ParaReveal } from "../lib/utils/builds";
import { TextElementRenderer } from "../text-element";
import { ImageElementRenderer } from "../image-element";
import { ShapeElementRenderer } from "../shape-element";
import { SlideContext, isDarkColor, type SlideContextValue } from "./slide-context";
import { BUILD_KEYFRAMES, buildEnterStyle } from "./builds-style";

export interface SlideProps {
    /** The slide to render. */
    slide: SlideData;
    /** Deck theme — controls fonts/colors/aspect-ratio when the slide doesn't override. */
    theme?: Theme;
    /** Pin the slide to this width in px. When omitted, the slide fills its container with auto-resize. */
    width?: number;
    /** Aspect ratio override — falls back to theme.aspectRatio. */
    aspectRatio?: number;
    /** Edit mode flag — passed to element renderers + enables drag/resize affordances. */
    editing?: boolean;
    /**
     * Current build step (0..totalSteps). `0` = nothing built (only non-animated
     * elements visible); each step reveals more animated elements. Omit (or pass
     * a number ≥ total) to show the fully-built slide. Ignored when `editing` —
     * the editor always shows every element so authors can position them.
     */
    buildStep?: number;
    /** Called when a text element's content is edited (only in editing mode). */
    onElementContentChange?: (elementId: string, content: string) => void;
    /** Called when an element is clicked — host-driven selection. */
    onElementSelect?: (elementId: string | null) => void;
    /** Selected element id — adds a focus ring and shows resize handles when editing. */
    selectedElementId?: string | null;
    /** Called when the user drags an element body to a new position (slide-relative 0..1). */
    onElementMove?: (elementId: string, x: number, y: number) => void;
    /** Called when the user resizes via a corner / edge handle (slide-relative 0..1). */
    onElementResize?: (elementId: string, patch: { x: number; y: number; w: number; h: number }) => void;
    /** Optional override renderer for a custom element type (or to replace one of the built-ins). */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    className?: string;
    style?: CSSProperties;
}

/**
 * Slide — the shared renderer. Used by SlideViewer, DeckEditor canvas,
 * SlideThumbnail, and the agent bridge's preview tools. All resolution-
 * independence lives here: child elements get a `slideWidthPx` so they can
 * scale font sizes / stroke widths to the rendered slide size.
 *
 * In `editing` mode this component grows two extra affordances:
 *   - pointer-drag on an element body moves it
 *   - selected elements show 8 resize handles (4 corners, 4 edges)
 *
 * Both fire through `onElementMove` / `onElementResize` so the host owns
 * the state — Slide stays a pure renderer.
 */
export function Slide({
    slide,
    theme,
    width,
    aspectRatio,
    editing = false,
    buildStep,
    onElementContentChange,
    onElementSelect,
    selectedElementId,
    onElementMove,
    onElementResize,
    renderElement,
    className,
    style,
}: SlideProps) {
    const t = resolveTheme(theme);
    const ratio = aspectRatio ?? t.aspectRatio ?? 16 / 9;
    const ref = useRef<HTMLDivElement>(null);
    const [measured, setMeasured] = useState<number>(width ?? 0);

    // Auto-measure when width isn't pinned.
    useEffect(() => {
        if (width !== undefined) {
            setMeasured(width);
            return;
        }
        const el = ref.current;
        if (!el) return;
        const ro = new ResizeObserver((entries) => {
            for (const e of entries) {
                setMeasured(e.contentRect.width);
            }
        });
        ro.observe(el);
        return () => ro.disconnect();
    }, [width]);

    const slideWidthPx = measured || 1;
    const slideHeightPx = slideWidthPx / ratio;

    const bg = slide.background;
    // The effective background colour used both for the slide div's `background`
    // and for the dark-theme heuristic exposed via SlideContext.
    const effectiveBg =
        bg?.color ?? t.colors?.background ?? "#ffffff";
    const backgroundStyle: CSSProperties = {
        background: bg?.gradient
            ? bg.gradient
            : bg?.image
                ? `${bg.color ?? "transparent"} url(${bg.image}) center/${bg.imageFit ?? "cover"} no-repeat`
                : effectiveBg,
    };

    const slideContext = useMemo<SlideContextValue>(
        () => ({
            theme: t,
            isDark: isDarkColor(effectiveBg),
            slideWidthPx,
        }),
        [t, effectiveBg, slideWidthPx],
    );

    // ─── Build (entrance-animation) bookkeeping ─────────────────────────────
    // In editing mode builds never hide anything — authors must see/position
    // every element. Otherwise we resolve each animated element's reveal step
    // and the per-element entrance delay for the step currently firing.
    const buildInfo = useMemo(() => {
        if (editing) return null;
        const steps = buildSteps(slide);
        if (steps.length === 0) return null;
        const revealStep = new Map<string, number>(); // element id → FIRST 1-based step it reveals on
        steps.forEach((step, i) => {
            for (const b of step.builds) {
                // By-paragraph elements appear across multiple steps; the
                // element box becomes visible on its earliest paragraph's step.
                if (!revealStep.has(b.element.id)) revealStep.set(b.element.id, i + 1);
            }
        });
        // When `buildStep` is omitted (thumbnails, exports) the slide renders
        // fully built with NO entrance animation. When provided, the firing
        // step's elements animate in.
        const driven = buildStep !== undefined;
        const currentStep = driven ? buildStep : steps.length;
        const firing = driven ? steps[currentStep - 1] : undefined;
        const delays = firing ? stepDelays(firing.builds) : new Map<string, number>();
        // Per-element paragraph reveal state (by-paragraph text builds). When
        // undriven, every paragraph is revealed (fully-built, no animation).
        const paraReveals = driven
            ? paragraphReveals(slide, currentStep)
            : new Map<string, ParaReveal>();
        return { revealStep, currentStep, delays, paraReveals, driven };
    }, [editing, slide, buildStep]);

    return (
        <SlideContext.Provider value={slideContext}>
            <div
                ref={ref}
                className={cn("fs-slide", className)}
                style={{
                    width: width ? `${width}px` : "100%",
                    height: width ? `${width / ratio}px` : `${slideHeightPx}px`,
                    position: "relative",
                    overflow: "hidden",
                    color: t.colors?.text,
                    ...backgroundStyle,
                    ...style,
                }}
                data-fancy-slides-slide={slide.id}
                onClick={(e) => {
                    if (e.target === e.currentTarget && onElementSelect) onElementSelect(null);
                }}
            >
                {buildInfo && <style>{BUILD_KEYFRAMES}</style>}
                {orderedElements(slide.elements).map((element) => {
                    // Resolve build visibility / entrance animation for this element.
                    let buildHidden = false;
                    let buildAnimation: ElementAnimation | undefined;
                    let buildDelay = 0;
                    // By-paragraph reveal state for this element (text builds only).
                    const paraReveal = buildInfo?.paraReveals.get(element.id);
                    if (buildInfo) {
                        const step = buildInfo.revealStep.get(element.id);
                        if (step !== undefined) {
                            if (buildInfo.currentStep < step) {
                                buildHidden = true; // not yet built
                            } else if (paraReveal) {
                                // By-paragraph element: the box stays mounted from its
                                // first paragraph onward; individual paragraphs hide /
                                // animate inside the text renderer. No whole-box effect.
                            } else if (buildInfo.currentStep === step && element.animation) {
                                // Revealing on the step that just fired → play the effect.
                                buildAnimation = element.animation;
                                buildDelay = buildInfo.delays.get(element.id) ?? 0;
                            }
                        }
                    }
                    if (buildHidden) return null;
                    return (
                        <SlideElementHost
                            key={element.id}
                            element={element}
                            theme={t}
                            slideWidthPx={slideWidthPx}
                            slideHeightPx={slideHeightPx}
                            editing={editing}
                            selected={selectedElementId === element.id}
                            onContentChange={onElementContentChange}
                            onSelect={onElementSelect}
                            onMove={onElementMove}
                            onResize={onElementResize}
                            renderElement={renderElement}
                            buildAnimation={buildAnimation}
                            buildDelay={buildDelay}
                            paraReveal={paraReveal}
                        />
                    );
                })}
            </div>
        </SlideContext.Provider>
    );
}

interface SlideElementHostProps {
    element: SlideElement;
    theme: Theme;
    slideWidthPx: number;
    slideHeightPx: number;
    editing: boolean;
    selected: boolean;
    onContentChange?: (elementId: string, content: string) => void;
    onSelect?: (elementId: string | null) => void;
    onMove?: (elementId: string, x: number, y: number) => void;
    onResize?: (elementId: string, patch: { x: number; y: number; w: number; h: number }) => void;
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** Entrance build animation to play (only set on the step the element reveals on). */
    buildAnimation?: ElementAnimation;
    /** Effective entrance delay (ms) resolved for with-prev / after-prev chaining. */
    buildDelay?: number;
    /** Per-paragraph reveal state for a by-paragraph text build (text elements only). */
    paraReveal?: ParaReveal;
}

/** Smallest allowed element size, as a fraction of the slide. */
const MIN_DIM = 0.02;

/** Drag distance below which we treat the gesture as a click. */
const CLICK_DRAG_THRESHOLD_PX = 3;

type ResizeAnchor = "nw" | "n" | "ne" | "e" | "se" | "s" | "sw" | "w";

interface DragState {
    mode: "move" | ResizeAnchor;
    startClientX: number;
    startClientY: number;
    startX: number;
    startY: number;
    startW: number;
    startH: number;
    didMove: boolean;
}

function SlideElementHost({
    element,
    theme,
    slideWidthPx,
    slideHeightPx,
    editing,
    selected,
    onContentChange,
    onSelect,
    onMove,
    onResize,
    renderElement,
    buildAnimation,
    buildDelay = 0,
    paraReveal,
}: SlideElementHostProps) {
    const dragRef = useRef<DragState | null>(null);

    if (element.hidden) return null;

    const left = element.x * slideWidthPx;
    const top = element.y * slideHeightPx;
    const width = element.w * slideWidthPx;
    const height = element.h * slideHeightPx;

    const interactive = editing && !element.locked;
    const canMove = interactive && !!onMove;
    const canResize = interactive && !!onResize && selected;

    const startDrag = (mode: DragState["mode"]) => (e: ReactPointerEvent<HTMLElement>) => {
        e.stopPropagation();
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        dragRef.current = {
            mode,
            startClientX: e.clientX,
            startClientY: e.clientY,
            startX: element.x,
            startY: element.y,
            startW: element.w,
            startH: element.h,
            didMove: false,
        };
    };

    const onPointerMove = (e: ReactPointerEvent<HTMLElement>) => {
        const drag = dragRef.current;
        if (!drag) return;
        const dxPx = e.clientX - drag.startClientX;
        const dyPx = e.clientY - drag.startClientY;
        if (Math.hypot(dxPx, dyPx) >= CLICK_DRAG_THRESHOLD_PX) drag.didMove = true;
        const dx = dxPx / slideWidthPx;
        const dy = dyPx / slideHeightPx;
        if (drag.mode === "move") {
            if (!onMove) return;
            const maxX = 1 - element.w;
            const maxY = 1 - element.h;
            const nextX = clamp(drag.startX + dx, 0, Math.max(0, maxX));
            const nextY = clamp(drag.startY + dy, 0, Math.max(0, maxY));
            onMove(element.id, nextX, nextY);
            return;
        }
        if (!onResize) return;
        const patch = computeResize(drag, dx, dy);
        onResize(element.id, patch);
    };

    const endDrag = (e: ReactPointerEvent<HTMLElement>) => {
        const drag = dragRef.current;
        if (!drag) return;
        try {
            (e.target as HTMLElement).releasePointerCapture(e.pointerId);
        } catch {
            /* element may have unmounted; ignore */
        }
        const wasMove = drag.didMove;
        dragRef.current = null;
        if (!wasMove && onSelect) onSelect(element.id);
    };

    const box: CSSProperties = {
        position: "absolute",
        left: `${left}px`,
        top: `${top}px`,
        width: `${width}px`,
        height: `${height}px`,
        transform: element.rotation ? `rotate(${element.rotation}deg)` : undefined,
        transformOrigin: "center center",
        zIndex: element.z ?? "auto",
        outline: selected ? "2px solid #8b5cf6" : undefined,
        outlineOffset: selected ? 2 : undefined,
        cursor: canMove ? "move" : interactive ? "pointer" : "default",
        touchAction: canMove ? "none" : undefined,
        ...(buildAnimation ? buildEnterStyle(buildAnimation, buildDelay) : null),
    };

    const rendered =
        renderInner({ element, theme, slideWidthPx, slideHeightPx, editing, selected, onContentChange, paraReveal })
        ?? renderElement?.(element, slideWidthPx)
        ?? elementPlaceholder(element);

    // Whole-element hyperlink — a click target in the viewer (never while
    // editing, so the link doesn't swallow selection). Fills the element box.
    const inner =
        element.href && !editing ? (
            <a
                href={element.href}
                target="_blank"
                rel="noreferrer"
                style={{ display: "block", width: "100%", height: "100%", color: "inherit", textDecoration: "inherit" }}
                data-fancy-slides-href=""
            >
                {rendered}
            </a>
        ) : (
            rendered
        );

    return (
        <div
            className={buildAnimation ? "fs-build-enter" : undefined}
            style={box}
            data-fancy-slides-element={element.id}
            data-fancy-slides-element-type={element.type}
            data-fancy-slides-build={buildAnimation ? "" : undefined}
            onPointerDown={canMove ? startDrag("move") : undefined}
            onPointerMove={canMove ? onPointerMove : undefined}
            onPointerUp={canMove ? endDrag : undefined}
            onPointerCancel={canMove ? endDrag : undefined}
            onClick={(e) => {
                // Click fallback for non-pointer environments / non-movable elements.
                if (!onSelect || canMove) return;
                e.stopPropagation();
                onSelect(element.id);
            }}
        >
            {inner}
            {canResize && (
                <ResizeHandles
                    onStart={(anchor) => startDrag(anchor)}
                    onMove={onPointerMove}
                    onEnd={endDrag}
                />
            )}
        </div>
    );
}

interface ResizeHandlesProps {
    onStart: (anchor: ResizeAnchor) => (e: ReactPointerEvent<HTMLElement>) => void;
    onMove: (e: ReactPointerEvent<HTMLElement>) => void;
    onEnd: (e: ReactPointerEvent<HTMLElement>) => void;
}

function ResizeHandles({ onStart, onMove, onEnd }: ResizeHandlesProps) {
    const anchors: Array<{ anchor: ResizeAnchor; style: CSSProperties; cursor: string }> = [
        { anchor: "nw", style: { left: -5, top: -5 }, cursor: "nwse-resize" },
        { anchor: "n", style: { left: "calc(50% - 5px)", top: -5 }, cursor: "ns-resize" },
        { anchor: "ne", style: { right: -5, top: -5 }, cursor: "nesw-resize" },
        { anchor: "e", style: { right: -5, top: "calc(50% - 5px)" }, cursor: "ew-resize" },
        { anchor: "se", style: { right: -5, bottom: -5 }, cursor: "nwse-resize" },
        { anchor: "s", style: { left: "calc(50% - 5px)", bottom: -5 }, cursor: "ns-resize" },
        { anchor: "sw", style: { left: -5, bottom: -5 }, cursor: "nesw-resize" },
        { anchor: "w", style: { left: -5, top: "calc(50% - 5px)" }, cursor: "ew-resize" },
    ];
    return (
        <>
            {anchors.map(({ anchor, style, cursor }) => (
                <div
                    key={anchor}
                    style={{
                        position: "absolute",
                        width: 10,
                        height: 10,
                        background: "#ffffff",
                        border: "1.5px solid #8b5cf6",
                        borderRadius: 2,
                        cursor,
                        touchAction: "none",
                        boxShadow: "0 1px 2px rgba(0,0,0,0.15)",
                        ...style,
                    }}
                    data-fancy-slides-resize-handle={anchor}
                    onPointerDown={onStart(anchor)}
                    onPointerMove={onMove}
                    onPointerUp={onEnd}
                    onPointerCancel={onEnd}
                />
            ))}
        </>
    );
}

interface RenderInnerArgs {
    element: SlideElement;
    theme: Theme;
    slideWidthPx: number;
    slideHeightPx: number;
    editing: boolean;
    selected: boolean;
    onContentChange?: (elementId: string, content: string) => void;
    paraReveal?: ParaReveal;
}

function renderInner({ element, theme, slideWidthPx, slideHeightPx, editing, selected, onContentChange, paraReveal }: RenderInnerArgs): ReactNode | undefined {
    switch (element.type) {
        case "text":
            return (
                <TextElementRenderer
                    element={element}
                    theme={theme}
                    slideWidthPx={slideWidthPx}
                    editing={editing}
                    selected={selected}
                    onContentChange={onContentChange ? (c) => onContentChange(element.id, c) : undefined}
                    paraReveal={paraReveal}
                />
            );
        case "image":
            return <ImageElementRenderer element={element} />;
        case "shape":
            return <ShapeElementRenderer element={element} theme={theme} slideWidthPx={slideWidthPx} slideHeightPx={slideHeightPx} />;
        case "chart":
        case "code":
        case "table":
        case "embed":
            // These render via consumer-provided `renderElement` so we don't
            // pull fancy-echarts / fancy-code / etc. into the package's static
            // graph. Hosts opt into the default registry from
            // `@particle-academy/fancy-slides/registry`.
            return undefined;
        default:
            return null;
    }
}

/**
 * Built-in fallback for the optional element types (chart / code / table /
 * embed) when the host hasn't wired a `renderElement` (or it returned
 * undefined). Without this the element would render blank, making the
 * toolbar's Insert buttons look broken. The placeholder keeps every insert
 * visible and nudges the dev toward the default registry. Hosts that want the
 * real chart/code/table render pass `renderElement` from
 * `@particle-academy/fancy-slides/registry`.
 */
function elementPlaceholder(element: SlideElement): ReactNode {
    if (element.type !== "chart" && element.type !== "code" && element.type !== "table" && element.type !== "embed") {
        return null;
    }
    const label = element.type.charAt(0).toUpperCase() + element.type.slice(1);
    return (
        <div
            style={{
                width: "100%",
                height: "100%",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                gap: "0.35em",
                textAlign: "center",
                padding: "0.5em",
                boxSizing: "border-box",
                border: "1px dashed currentColor",
                borderRadius: 8,
                opacity: 0.55,
                overflow: "hidden",
            }}
        >
            <span style={{ fontWeight: 600 }}>{label}</span>
            <span style={{ fontSize: "0.7em", opacity: 0.8 }}>Pass renderElement to render</span>
        </div>
    );
}

function orderedElements(elements: SlideElement[]): SlideElement[] {
    // Elements without a `z` keep their array order; explicit z overrides win.
    return [...elements].sort((a, b) => {
        const az = a.z ?? -1;
        const bz = b.z ?? -1;
        if (az === bz) return 0;
        return az < bz ? -1 : 1;
    });
}

function clamp(v: number, min: number, max: number): number {
    return Math.max(min, Math.min(max, v));
}

/**
 * Given a drag delta + which anchor is being dragged, compute the patch
 * `{ x, y, w, h }` to apply. Clamps so dimensions stay >= MIN_DIM and the
 * element stays within the slide. Opposite edges stay fixed (e.g. dragging
 * the W handle moves the left edge but not the right).
 */
function computeResize(drag: DragState, dx: number, dy: number): { x: number; y: number; w: number; h: number } {
    let { startX: x, startY: y, startW: w, startH: h } = drag;
    const right = drag.startX + drag.startW;
    const bottom = drag.startY + drag.startH;
    const anchor = drag.mode as ResizeAnchor;

    if (anchor.includes("w")) {
        const newX = clamp(drag.startX + dx, 0, right - MIN_DIM);
        x = newX;
        w = right - newX;
    } else if (anchor.includes("e")) {
        w = clamp(drag.startW + dx, MIN_DIM, 1 - drag.startX);
    }
    if (anchor.includes("n")) {
        const newY = clamp(drag.startY + dy, 0, bottom - MIN_DIM);
        y = newY;
        h = bottom - newY;
    } else if (anchor.includes("s")) {
        h = clamp(drag.startH + dy, MIN_DIM, 1 - drag.startY);
    }
    return { x, y, w, h };
}

/**
 * Pure-CSS entrance animations for element builds. Mirrors the slide-level
 * transition approach in `SlideViewer`: a set of keyframes wrapped in a
 * `prefers-reduced-motion: no-preference` guard, plus a helper that picks the
 * right `animation-name` + timing for a given element animation.
 *
 * No runtime deps — keyframes are injected via a `<style>` tag by `<Slide>`.
 */

import type { CSSProperties } from "react";
import type { ElementAnimation } from "../lib/types";

const DEFAULT_BUILD_DURATION = 500;
const EASE = "cubic-bezier(0.16, 1, 0.3, 1)"; // ease-out

/**
 * Inline style that plays an element's entrance build. `delay` is the
 * *effective* delay already resolved for with-prev / after-prev chaining.
 * Under reduced-motion the keyframes are disabled in CSS, so the element
 * simply appears at its final frame.
 */
export function buildEnterStyle(animation: ElementAnimation, effectiveDelay: number): CSSProperties {
    const duration = animation.duration ?? DEFAULT_BUILD_DURATION;
    const dir = animation.direction ?? "left";
    let name: string;
    switch (animation.effect) {
        case "fade":
            name = "fs-build-fade";
            break;
        case "zoom":
            name = "fs-build-zoom";
            break;
        case "fly-in":
            name = `fs-build-fly-${dir}`;
            break;
        case "wipe":
            name = `fs-build-wipe-${dir}`;
            break;
        default:
            name = "fs-build-fade";
    }
    return {
        animationName: name,
        animationDuration: `${duration}ms`,
        animationDelay: `${effectiveDelay}ms`,
        animationTimingFunction: EASE,
        animationFillMode: "both",
    };
}

/**
 * Keyframes for every build effect. `fly-in` translates from the named
 * direction; `wipe` reveals via a `clip-path` inset growing from that edge.
 * Reduced-motion users get no animation — `animation-fill-mode: both` would
 * otherwise pin the `from` frame, so we disable the build animations entirely
 * (the elements are still gated on clicks, they just appear instantly).
 */
export const BUILD_KEYFRAMES = `
@media (prefers-reduced-motion: reduce) {
    .fs-build-enter { animation: none !important; }
}
@media (prefers-reduced-motion: no-preference) {
    @keyframes fs-build-fade {
        from { opacity: 0; }
        to { opacity: 1; }
    }
    @keyframes fs-build-zoom {
        from { opacity: 0; transform: scale(0.8); }
        to { opacity: 1; transform: scale(1); }
    }
    @keyframes fs-build-fly-left {
        from { opacity: 0; transform: translateX(-24%); }
        to { opacity: 1; transform: translateX(0); }
    }
    @keyframes fs-build-fly-right {
        from { opacity: 0; transform: translateX(24%); }
        to { opacity: 1; transform: translateX(0); }
    }
    @keyframes fs-build-fly-up {
        from { opacity: 0; transform: translateY(24%); }
        to { opacity: 1; transform: translateY(0); }
    }
    @keyframes fs-build-fly-down {
        from { opacity: 0; transform: translateY(-24%); }
        to { opacity: 1; transform: translateY(0); }
    }
    /* wipe: clip-path inset reveals from the named edge toward the opposite one.
       inset(top right bottom left) — start fully clipped on the far side. */
    @keyframes fs-build-wipe-left {
        from { clip-path: inset(0 100% 0 0); }
        to { clip-path: inset(0 0 0 0); }
    }
    @keyframes fs-build-wipe-right {
        from { clip-path: inset(0 0 0 100%); }
        to { clip-path: inset(0 0 0 0); }
    }
    @keyframes fs-build-wipe-up {
        from { clip-path: inset(100% 0 0 0); }
        to { clip-path: inset(0 0 0 0); }
    }
    @keyframes fs-build-wipe-down {
        from { clip-path: inset(0 0 100% 0); }
        to { clip-path: inset(0 0 0 0); }
    }
}
`;

import { createContext, useContext } from "react";
import type { Theme } from "../lib/types";

/**
 * What the surrounding <Slide> knows about itself. Exposed to children
 * (including `renderElement` callbacks and registry hosts like chart-host)
 * via React context so they can react to the deck's theme without the
 * renderElement signature having to carry it around.
 */
export interface SlideContextValue {
    /** Fully-resolved theme (merged with defaults). */
    theme: Theme;
    /**
     * Heuristic: true when the resolved background is dark enough that
     * native-rendered widgets (charts, code blocks) should use a dark variant.
     * Computed once from `theme.colors.background` luminance.
     */
    isDark: boolean;
    /** Slide width in CSS pixels at the current render size. */
    slideWidthPx: number;
}

export const SlideContext = createContext<SlideContextValue | null>(null);

/**
 * Read the surrounding <Slide>'s context. Returns null when called outside
 * a Slide — chart-host / code-host can use that signal to fall back to
 * a sensible default (light theme, no resize anchor).
 */
export function useSlideContext(): SlideContextValue | null {
    return useContext(SlideContext);
}

/**
 * Convenience: returns the resolved theme, or undefined when the caller
 * isn't inside a Slide.
 */
export function useSlideTheme(): Theme | undefined {
    return useContext(SlideContext)?.theme;
}

/**
 * Convenience: returns true when the surrounding slide's background reads
 * as "dark enough" — useful for charts/code blocks that ship a dark variant.
 */
export function useIsDarkSlide(): boolean {
    return useContext(SlideContext)?.isDark ?? false;
}

/** Compute `isDark` from a hex/rgb colour. Used by Slide when building the context. */
export function isDarkColor(color: string): boolean {
    // Normalise #rgb / #rrggbb / rgb()/rgba() to a triple.
    const m = color.match(/^#([0-9a-f]{3,8})$/i);
    if (m) {
        let hex = m[1];
        if (hex.length === 3) {
            hex = hex.split("").map((c) => c + c).join("");
        }
        if (hex.length >= 6) {
            const r = parseInt(hex.slice(0, 2), 16);
            const g = parseInt(hex.slice(2, 4), 16);
            const b = parseInt(hex.slice(4, 6), 16);
            return relativeLuminance(r, g, b) < 0.5;
        }
    }
    const rgb = color.match(/rgba?\(([^()]+)\)/i);
    if (rgb) {
        const [r, g, b] = rgb[1].split(",").map((s) => parseInt(s.trim(), 10));
        if (!Number.isNaN(r) && !Number.isNaN(g) && !Number.isNaN(b)) {
            return relativeLuminance(r, g, b) < 0.5;
        }
    }
    return false;
}

function relativeLuminance(r: number, g: number, b: number): number {
    // Standard sRGB → relative luminance.
    const toLinear = (c: number) => {
        const v = c / 255;
        return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * toLinear(r) + 0.7152 * toLinear(g) + 0.0722 * toLinear(b);
}

/**
 * The fancy-slides data model.
 *
 * Every shape here is JSON-friendly — pure objects, arrays, primitives, and
 * tagged unions. No React children, no functions, no class instances. This
 * is the contract the deck schema commits to: an LLM can emit a deck, a
 * server can store one, a designer can hand-edit one, and the viewer +
 * editor will render it identically.
 *
 * Coordinate system: elements position themselves in slide-relative units
 * where the slide is a 1.0 × (1 / aspectRatio) rectangle. So `x: 0.5, y: 0.5`
 * is the centre of the slide regardless of how big it's rendered. This
 * keeps decks resolution-independent — a fullscreen 1920×1080 viewer and a
 * thumbnail at 320×180 render the same layout.
 */

// ─── Deck ──────────────────────────────────────────────────────────────────

export interface Deck {
    /** Stable id. Required even when persistence is in-memory. */
    id: string;
    /** Human title — shown in the editor chrome + browser tab. */
    title: string;
    /** Ordered slide list. The viewer steps through in this order. */
    slides: Slide[];
    /** Visual theme for the whole deck. */
    theme: Theme;
    /**
     * Schema version the deck was authored against. Omitted == version 1 (the
     * implicit version for decks created before versioning). Used by the
     * serialize / parse helpers to migrate older shapes forward. Mirrors
     * `dark-slide`'s `Schema::SCHEMA_VERSION`.
     */
    version?: number;
    /** Free-form metadata — `{ author, createdAt, updatedAt, tags, … }`. */
    metadata?: Record<string, unknown>;
}

/**
 * Current deck schema version. Bump when a structural change needs migration on
 * load. Kept in lockstep with the sibling `dark-slide` PHP package.
 */
export const SCHEMA_VERSION = 1;

// ─── Slide ─────────────────────────────────────────────────────────────────

/** Layout presets that pre-populate / constrain element placement. */
export type SlideLayout =
    | "blank"            // empty canvas, free placement
    | "title"            // centered title
    | "title-content"    // title at top, content area below
    | "two-column"       // left + right halves
    | "section-divider"  // section header with subtitle
    | "image-text"       // image left, text right
    | "text-image"       // text left, image right
    | "quote";           // big centered quote

export interface Slide {
    /** Stable id. */
    id: string;
    /** Optional layout preset. Mostly used by agents — humans tend to free-place. */
    layout?: SlideLayout;
    /** Elements rendered on the slide in z-order (last on top). */
    elements: SlideElement[];
    /** Background fill — color, image, or gradient. Inherits from theme when absent. */
    background?: SlideBackground;
    /** Entrance transition for this slide. Inherits from theme.transition when absent. */
    transition?: SlideTransition;
    /** Speaker notes — markdown. */
    notes?: string;
    /**
     * Plain-text narration script for AI-narrated decks: TTS reads from
     * `narration`, presenter view shows `notes`. Opaque to the pptx writer
     * (stored as data, not rendered into the slide).
     */
    narration?: string;
    /** Free-form metadata — `{ title, tags, durationSec, … }`. */
    metadata?: Record<string, unknown>;
}

// ─── Elements ──────────────────────────────────────────────────────────────

/**
 * Every element is positioned in slide-relative coordinates (0..1). x/y are
 * the top-left corner; w/h are width/height as a fraction of the slide.
 */
export interface ElementBase {
    /** Stable id. Agents reference elements by id. */
    id: string;
    /** Element kind — discriminator. */
    type: SlideElement["type"];
    /** Left edge, 0..1 (fraction of slide width). */
    x: number;
    /** Top edge, 0..1 (fraction of slide height). */
    y: number;
    /** Width, 0..1. */
    w: number;
    /** Height, 0..1. */
    h: number;
    /** Rotation in degrees, clockwise. */
    rotation?: number;
    /** Z-order — higher renders on top. Falls back to array order when undefined. */
    z?: number;
    /** Lock from editing. */
    locked?: boolean;
    /** Hide on this slide (still in the data — for animated reveals). */
    hidden?: boolean;
    /**
     * Whole-element hyperlink. When set, the element becomes a click target in
     * the viewer (opens in a new tab) and the pptx writer emits an
     * `<a:hlinkClick>` on the shape / picture. For rich inline links *within*
     * text, use a markdown `[label](url)` in the text content instead.
     */
    href?: string;
    /** Entrance build animation — when present the element participates in the slide's build sequence. */
    animation?: ElementAnimation;
}

// ─── Element entrance animations (builds) ────────────────────────────────────

/** Visual entrance effect played when an element builds onto the slide. */
export type AnimationEffect = "fade" | "fly-in" | "zoom" | "wipe";

/** When an element's build fires relative to the surrounding builds. */
export type AnimationTrigger = "on-click" | "with-prev" | "after-prev";

/**
 * Per-element entrance animation ("build step"). Elements with an `animation`
 * start hidden and reveal as the presenter advances through the slide's build
 * sequence. The shape is shared with the sibling `dark-slide` PHP package, so
 * keep it byte-for-byte aligned.
 */
export interface ElementAnimation {
    /** Visual effect. */
    effect: AnimationEffect;
    /** When the build fires relative to its neighbours. Default `"on-click"`. */
    trigger?: AnimationTrigger;
    /** Direction for `fly-in` / `wipe`. Default `"left"`. */
    direction?: "left" | "right" | "up" | "down";
    /** Effect duration in ms. Default `500`. */
    duration?: number;
    /** Delay before the effect starts, in ms. Default `0`. */
    delay?: number;
    /** Build order within the slide, ascending; ties broken by element array index. */
    order?: number;
    /**
     * Reveal a TEXT element one paragraph/line at a time (PowerPoint/Google
     * Slides "By paragraph"). The element expands into one build per paragraph
     * — the element's `content` split on `"\n"` (a trailing empty line is
     * dropped). The first paragraph uses this animation's `trigger`; every
     * subsequent paragraph reveals on a fresh click. Only meaningful for text
     * elements; ignored for other types and when the element has 0/1 paragraphs
     * (then it behaves like a normal single build).
     */
    byParagraph?: boolean;
}

export interface TextElement extends ElementBase {
    type: "text";
    /** Content — markdown by default; can also be plain text or HTML. */
    content: string;
    /** Content format. Defaults to `"markdown"`. */
    format?: "markdown" | "html" | "plain";
    /** Typography. */
    style?: TextStyle;
}

export interface TextStyle {
    /** Font family — falls back to theme.fonts.body. */
    fontFamily?: string;
    /** Font size in px at the slide's design width (theme.slideWidth). */
    fontSize?: number;
    /** Font weight (`100..900`, or `"normal" | "bold"`). */
    weight?: "normal" | "medium" | "semibold" | "bold" | number;
    /** Horizontal alignment. */
    align?: "left" | "center" | "right" | "justify";
    /** Vertical alignment within the box. */
    verticalAlign?: "top" | "middle" | "bottom";
    /** Color (any CSS color). Falls back to theme.colors.text. */
    color?: string;
    /** Line height (multiplier). */
    lineHeight?: number;
    /** Italic. */
    italic?: boolean;
    /** Underline. */
    underline?: boolean;
}

export interface ImageElement extends ElementBase {
    type: "image";
    /** Image URL or data URI. */
    src: string;
    /** Alt text for accessibility. */
    alt?: string;
    /** How the image is fit inside its box. */
    fit?: "contain" | "cover" | "fill" | "scale-down";
    /** Optional crop window (slide-relative). */
    crop?: { x: number; y: number; w: number; h: number };
}

export interface ChartElement extends ElementBase {
    type: "chart";
    /** Apache ECharts option object. Passed straight to `<EChart>`. */
    option: Record<string, unknown>;
    /** Theme name passed to `<EChart>`. */
    chartTheme?: string;
}

export interface CodeElement extends ElementBase {
    type: "code";
    /** Source code. */
    code: string;
    /** Language alias for the highlighter. */
    language?: string;
    /** Show line numbers. Defaults to `true`. */
    lineNumbers?: boolean;
    /** Theme — `"light"`, `"dark"`, `"auto"`, or a custom registered name. */
    codeTheme?: string;
}

/**
 * One table column. `key` is what every row is keyed BY; `label` is what the
 * header shows, and falls back to `key` when absent, as dark-slide’s writer
 * resolves it.
 */
/**
 * A table cell's look: dark-slide's table cell model, drawn the same way here.
 * Precedence: cell > row > column > band (header | stripe | body) > table >
 * theme > default. `false` stops the chain and means off.
 */
export interface TableCellStyle {
    fill?: string | false;
    color?: string;
    bold?: boolean;
    italic?: boolean;
    underline?: boolean;
    align?: "left" | "center" | "right" | "justify";
    anchor?: "top" | "middle" | "bottom";
    /** Design px, scaled like text. */
    fontSize?: number;
    fontFamily?: string;
    /** `false` for none, or one rule for every side: `{ color, width }` (width in design px). */
    borders?: false | { color?: string; width?: number };
}

export interface TableColumn extends TableCellStyle {
    key: string;
    label?: string;
    /** A fraction of the table (all widths <= 1) or a weight. */
    width?: number;
}

/** A cell given as an object: its text plus its own style. */
export interface TableCell extends TableCellStyle {
    text: string;
}

export interface TableStyle extends TableCellStyle {
    /** The header row's band (default: theme accent, white, bold); `false` for no header row. */
    header?: TableCellStyle | false;
    /** Every second body row's band (default: theme surface); `false` for none. */
    stripe?: TableCellStyle | false;
    /** Every body row's band. */
    body?: TableCellStyle;
}

/**
 * One table row: an object keyed by each column’s `key`, or the values in COLUMN
 * ORDER.
 *
 * The keyed form is canonical — it survives a column reorder, and it is the only
 * one that can also carry row-level style for the pptx writer. The positional
 * form is accepted because it is what an author guesses from a bare column list,
 * and guessing it used to render a full-size grid with every cell blank and
 * nothing logged (#14).
 */
export type TableRow = Record<string, unknown> | unknown[];

export interface TableElement extends ElementBase {
    type: "table";
    /** Column definitions — `{ key, label }`. */
    columns: TableColumn[];
    /** Row data — objects keyed by column `key`, or values in column order. A value is text or a `TableCell`. */
    rows: TableRow[];
    /** The table's look, as dark-slide writes it. */
    style?: TableStyle;
}

export type ShapeKind = "rect" | "rounded-rect" | "ellipse" | "line" | "arrow" | "triangle";

export interface ShapeElement extends ElementBase {
    type: "shape";
    shape: ShapeKind;
    /** Fill color (any CSS color, or `"none"`). */
    fill?: string;
    /** Stroke color. */
    stroke?: string;
    /** Stroke width in px at the slide's design width. */
    strokeWidth?: number;
    /** Dashed stroke. */
    dashed?: boolean;
    /**
     * Corner radius for `rounded-rect`, in px at the slide's design width (default 8),
     * capped at half the shorter side. A plain `rect` has square corners.
     */
    radius?: number;
}

export interface EmbedElement extends ElementBase {
    type: "embed";
    /** Embed URL — typically a video, dashboard, or fancy-screens Screen. */
    src: string;
    /** iframe `title` for accessibility. */
    title?: string;
    /** Sandbox attribute. Defaults to allow-scripts (no allow-same-origin). */
    sandbox?: string;
}

export type SlideElement =
    | TextElement
    | ImageElement
    | ChartElement
    | CodeElement
    | TableElement
    | ShapeElement
    | EmbedElement;

// ─── Background, transitions, theme ────────────────────────────────────────

export interface SlideBackground {
    /** Solid color, or `"transparent"` to inherit theme. */
    color?: string;
    /** Image background URL. Takes precedence over color when present. */
    image?: string;
    /** How the background image is fit. Defaults to `"cover"`. */
    imageFit?: "contain" | "cover" | "fill";
    /** Optional gradient — `"linear-gradient(...)"` or `"radial-gradient(...)"` string. */
    gradient?: string;
}

export type TransitionKind = "none" | "fade" | "slide" | "zoom";

export interface SlideTransition {
    kind: TransitionKind;
    /** Duration in ms. */
    duration?: number;
    /** Direction for `slide` transitions. */
    direction?: "left" | "right" | "up" | "down";
}

export interface Theme {
    /** Theme name — used for serialization + agent routing. */
    name: string;
    /** Aspect ratio — defaults to 16:9. Custom themes can pick anything. */
    aspectRatio?: number;
    /** Design width in px. Slides scale to fit; this just sets the unit base for fontSize/strokeWidth. */
    slideWidth?: number;
    colors?: ThemeColors;
    fonts?: ThemeFonts;
    /** Default transition for slides that don't specify their own. */
    defaultTransition?: SlideTransition;
}

export interface ThemeColors {
    background?: string;
    text?: string;
    muted?: string;
    accent?: string;
    surface?: string;
}

export interface ThemeFonts {
    /** Used for `Heading`-like text elements (the default for large fontSize). */
    heading?: string;
    /** Used for body text. */
    body?: string;
    /** Used by CodeElement. */
    mono?: string;
}

// ─── Agent / Human+ surface ────────────────────────────────────────────────

/**
 * Agent activity broadcast whenever the deck mutates. Hosts subscribe to feed
 * an AgentPanel, presence layer, or audit log.
 */
export interface DeckActivity {
    /** Stable activity id. */
    id: string;
    /** Wall-clock timestamp. */
    at: number;
    /** Who made the change. */
    actor: { kind: "human" | "agent"; id: string; name?: string; color?: string };
    /** What changed. */
    op: DeckOp;
}

/**
 * The canonical, language-neutral deck operation vocabulary (v0.13+).
 *
 * Every op is a flat JSON object discriminated by a dotted `op` string. The
 * shape is deliberately language-neutral so the *same* op contract is shared
 * with the sibling `dark-slide` PHP package: an op emitted by `<DeckEditor>` in
 * the browser can be reduced server-side by `DarkSlide\Reducer::apply()`, and a
 * server-computed `DarkSlide\Agent::diff()` replays in the editor — one
 * vocabulary, one reducer per authoritative host. Published as a JSON Schema via
 * {@link deckOpSchema} so any backend can validate it.
 *
 * Ids are always named `slideId` / `elementId` (never a bare `id`), and `op`
 * names are `subject.verb` in camelCase. Migrating from the pre-0.13
 * `kind`-flavored ops: {@link mapLegacyOp}.
 */
export type DeckOp =
    | { op: "deck.setTitle"; title: string }
    | { op: "deck.setTheme"; theme: Theme }
    /** Replace the entire deck atomically — stream a full presentation IN in one op. */
    | { op: "deck.replace"; deck: Deck }
    | { op: "slide.add"; index: number; slide: Slide }
    | { op: "slide.remove"; slideId: string }
    | { op: "slide.reorder"; slideId: string; toIndex: number }
    | { op: "slide.setLayout"; slideId: string; layout: SlideLayout }
    | { op: "slide.setNotes"; slideId: string; notes: string }
    | { op: "slide.setBackground"; slideId: string; background?: SlideBackground }
    | { op: "slide.setTransition"; slideId: string; transition?: SlideTransition }
    | { op: "element.add"; slideId: string; element: SlideElement }
    | { op: "element.remove"; slideId: string; elementId: string }
    | { op: "element.update"; slideId: string; elementId: string; patch: Partial<SlideElement> }
    | { op: "element.move"; slideId: string; elementId: string; x: number; y: number }
    | { op: "element.resize"; slideId: string; elementId: string; w: number; h: number }
    | { op: "element.setAnimation"; slideId: string; elementId: string; animation?: ElementAnimation };

/** The dotted `op` discriminator of every {@link DeckOp}. */
export type DeckOpType = DeckOp["op"];

/**
 * The pre-0.13 `kind`-flavored op vocabulary. Retained so existing consumers can
 * map their stored/streamed ops forward with {@link mapLegacyOp}. Prefer
 * {@link DeckOp} in new code.
 *
 * @deprecated Use {@link DeckOp}; convert with {@link mapLegacyOp}.
 */
export type LegacyDeckOp =
    | { kind: "deck_set_title"; title: string }
    | { kind: "deck_apply_theme"; theme: Theme }
    | { kind: "deck_set"; deck: Deck }
    | { kind: "slide_add"; index: number; slide: Slide }
    | { kind: "slide_remove"; id: string }
    | { kind: "slide_reorder"; id: string; toIndex: number }
    | { kind: "slide_set_layout"; id: string; layout: SlideLayout }
    | { kind: "slide_set_notes"; id: string; notes: string }
    | { kind: "slide_set_background"; id: string; background?: SlideBackground }
    | { kind: "slide_set_transition"; id: string; transition?: SlideTransition }
    | { kind: "element_add"; slideId: string; element: SlideElement }
    | { kind: "element_remove"; slideId: string; elementId: string }
    | { kind: "element_update"; slideId: string; elementId: string; patch: Partial<SlideElement> }
    | { kind: "element_move"; slideId: string; elementId: string; x: number; y: number }
    | { kind: "element_resize"; slideId: string; elementId: string; w: number; h: number }
    | { kind: "element_set_animation"; slideId: string; elementId: string; animation?: ElementAnimation };

import type { Theme } from "../types";
import { defaultTheme } from "./default-theme";

/**
 * Merge a partial theme with the defaults so consumers can override just the
 * pieces they care about (colors, fonts, aspect ratio) and inherit the rest.
 */
export function defineTheme(overrides: Partial<Theme> & { name: string }): Theme {
    return {
        ...defaultTheme,
        ...overrides,
        colors: { ...defaultTheme.colors, ...overrides.colors },
        fonts: { ...defaultTheme.fonts, ...overrides.fonts },
        defaultTransition: overrides.defaultTransition ?? defaultTheme.defaultTransition,
    };
}

/** Resolve the effective theme for a deck — applies the default for any missing fields. */
export function resolveTheme(theme: Theme | undefined): Theme {
    if (!theme) return defaultTheme;
    return defineTheme(theme);
}

/**
 * Tiny class-name joiner. Avoids pulling clsx as a dep for this small package.
 */
export function cn(...parts: Array<string | false | null | undefined>): string {
    return parts.filter(Boolean).join(" ");
}

/**
 * Build (entrance-animation) sequencing — the shared model used by both
 * `SlideViewer` and `PresenterView` so step-through behaves identically.
 *
 * A slide's *builds* are the elements that carry an `animation`. They are
 * stable-sorted by `(order ?? 0)` then original element array index, then
 * grouped into *click steps*:
 *
 *   - The first build, and every build whose trigger is `"on-click"`, starts
 *     a NEW step.
 *   - `"with-prev"` plays simultaneously with the current step's lead.
 *   - `"after-prev"` plays after a delay equal to the current step's lead
 *     duration (chained onto its `delay`).
 *
 * `buildStep` semantics (used by the viewer/presenter):
 *   - `0`  → nothing built yet; only non-animated elements are visible.
 *   - `n`  → the first `n` steps have fired; their elements are visible.
 *   - `totalSteps` → every build is shown (the fully-built slide).
 */

import type { ElementAnimation, Slide, SlideElement } from "../types";

/** One element participating in a build, paired with its (defaulted) animation. */
export interface Build {
    element: SlideElement;
    animation: ElementAnimation;
    /** Original index of the element in the slide's `elements` array (tie-breaker). */
    index: number;
    /**
     * For a "by paragraph" text build, which paragraph index (0-based) this
     * build reveals. Undefined for whole-element builds. The renderer uses this
     * to show "the first K paragraphs of this element".
     */
    paraIndex?: number;
}

/**
 * Split a text element's `content` into paragraphs for a "by paragraph" build.
 * Splits on `"\n"` and drops a single trailing empty line (so content ending in
 * a newline doesn't manifest a phantom blank build). Empty interior lines are
 * preserved — they still consume a click, matching PowerPoint's behaviour.
 */
export function splitParagraphs(content: string): string[] {
    const lines = content.split("\n");
    if (lines.length > 1 && lines[lines.length - 1] === "") lines.pop();
    return lines;
}

/**
 * The blocks a text element renders as in the static (non-build) path, given its
 * `format`. Markdown/HTML content is split line-by-line (one block per `"\n"`) so
 * a single newline is a hard line/paragraph break — the canonical line-based
 * model (`splitParagraphs`, `normalizeSlideMarkdown`, dark-slide's pptx export).
 * Passing the whole multi-line string to a CommonMark renderer would instead
 * fold a lone `"\n"` into a soft break (a space), collapsing the lines.
 *
 * `plain` content is returned as a single block: it renders with
 * `white-space: pre-wrap`, which already preserves its newlines.
 */
export function textBlocks(content: string, format: "markdown" | "html" | "plain"): string[] {
    return format === "plain" ? [content] : splitParagraphs(content);
}

/**
 * Whether an element expands into per-paragraph builds: a text element whose
 * animation has `byParagraph` and that splits into 2+ paragraphs. With 0/1
 * paragraphs it behaves like a normal single build.
 */
export function isByParagraph(element: SlideElement, animation: ElementAnimation): boolean {
    if (!animation.byParagraph || element.type !== "text") return false;
    return splitParagraphs(element.content).length > 1;
}

/** A click step — the set of builds revealed by a single forward advance. */
export interface BuildStep {
    /** Builds that reveal on this step (lead first, then with-prev / after-prev). */
    builds: Build[];
}

const DEFAULT_BUILD_DURATION = 500;

/**
 * Collect a slide's builds in resolved order: every element with an
 * `animation`, stable-sorted by `(order ?? 0)` then array index.
 */
export function collectBuilds(slide: Slide | undefined): Build[] {
    if (!slide) return [];
    const builds: Build[] = [];
    slide.elements.forEach((element, index) => {
        if (element.animation) {
            builds.push({ element, animation: element.animation, index });
        }
    });
    // Stable sort: Array.prototype.sort is stable in modern engines, but we
    // tie-break on the captured array index explicitly to be safe.
    const ordered = builds.sort((a, b) => {
        const ao = a.animation.order ?? 0;
        const bo = b.animation.order ?? 0;
        if (ao !== bo) return ao - bo;
        return a.index - b.index;
    });

    // Expand "by paragraph" text builds into one build per paragraph. The first
    // paragraph keeps the element's own trigger (so it can be with-prev /
    // after-prev relative to a prior element); every subsequent paragraph is
    // "on-click" — one line per click. They stay contiguous, so the rest of an
    // element's paragraphs fire before the next element's builds.
    const expanded: Build[] = [];
    for (const build of ordered) {
        if (isByParagraph(build.element, build.animation)) {
            const paras = splitParagraphs((build.element as { content: string }).content);
            paras.forEach((_, paraIndex) => {
                const animation: ElementAnimation =
                    paraIndex === 0 ? build.animation : { ...build.animation, trigger: "on-click" };
                expanded.push({ element: build.element, animation, index: build.index, paraIndex });
            });
        } else {
            expanded.push(build);
        }
    }
    return expanded;
}

/**
 * Group a slide's builds into click steps. The first build always opens a
 * step; thereafter an `"on-click"` trigger opens a new step while
 * `"with-prev"` / `"after-prev"` attach to the current one.
 */
export function buildSteps(slide: Slide | undefined): BuildStep[] {
    const builds = collectBuilds(slide);
    const steps: BuildStep[] = [];
    for (const build of builds) {
        const trigger = build.animation.trigger ?? "on-click";
        if (steps.length === 0 || trigger === "on-click") {
            steps.push({ builds: [build] });
        } else {
            steps[steps.length - 1]!.builds.push(build);
        }
    }
    return steps;
}

/** Total number of click steps for a slide (0 when the slide has no builds). */
export function totalBuildSteps(slide: Slide | undefined): number {
    return buildSteps(slide).length;
}

/**
 * Given a slide and a `buildStep` (0..totalSteps), return the set of element
 * ids that should be VISIBLE. Elements with no animation are always visible;
 * animated elements become visible once their owning step has fired.
 */
export function visibleElementIds(slide: Slide | undefined, buildStep: number): Set<string> {
    const visible = new Set<string>();
    if (!slide) return visible;
    const steps = buildSteps(slide);
    const stepOfElement = new Map<string, number>(); // 1-based step at which an element FIRST reveals
    steps.forEach((step, i) => {
        for (const b of step.builds) {
            // For by-paragraph builds many builds share one element id; the
            // element is visible once its earliest (first paragraph) step fires.
            if (!stepOfElement.has(b.element.id)) stepOfElement.set(b.element.id, i + 1);
        }
    });
    for (const element of slide.elements) {
        const revealStep = stepOfElement.get(element.id);
        if (revealStep === undefined) {
            visible.add(element.id); // no animation → always visible
        } else if (buildStep >= revealStep) {
            visible.add(element.id); // step has fired
        }
    }
    return visible;
}

/**
 * Per-element paragraph reveal state for a "by paragraph" text build at a given
 * `buildStep`. Keyed by element id:
 *   - `revealed` — how many paragraphs (0..count) should be shown so far.
 *   - `firingParaIndex` — the paragraph index revealing on the step that just
 *     fired (so the renderer plays its entrance effect), or `undefined` when no
 *     paragraph of this element fires on `buildStep`.
 * Only elements that actually expand by-paragraph appear in the map.
 */
export interface ParaReveal {
    revealed: number;
    firingParaIndex?: number;
}

export function paragraphReveals(slide: Slide | undefined, buildStep: number): Map<string, ParaReveal> {
    const out = new Map<string, ParaReveal>();
    if (!slide) return out;
    const steps = buildSteps(slide);
    steps.forEach((step, i) => {
        const stepNum = i + 1; // 1-based
        for (const b of step.builds) {
            if (b.paraIndex === undefined) continue;
            const fired = buildStep >= stepNum;
            const prev = out.get(b.element.id) ?? { revealed: 0 };
            if (fired) {
                prev.revealed = Math.max(prev.revealed, b.paraIndex + 1);
                if (stepNum === buildStep) prev.firingParaIndex = b.paraIndex;
            }
            out.set(b.element.id, prev);
        }
    });
    return out;
}

/**
 * The builds that fire when advancing INTO `buildStep` (1-based). Returns the
 * lead build first; the viewer uses `with-prev` / `after-prev` to compute each
 * element's effective `delay`. Empty when `buildStep` is out of range.
 */
export function buildsForStep(slide: Slide | undefined, buildStep: number): Build[] {
    const steps = buildSteps(slide);
    const step = steps[buildStep - 1];
    return step ? step.builds : [];
}

/**
 * Compute the effective entrance delay (ms) for each build within a step,
 * honouring `with-prev` (0 extra) and `after-prev` (lead duration). The lead
 * build keeps its own `delay`; followers add to it. Keyed by element id.
 */
export function stepDelays(builds: Build[]): Map<string, number> {
    const delays = new Map<string, number>();
    const lead = builds[0];
    if (!lead) return delays;
    const leadDelay = lead.animation.delay ?? 0;
    const leadDuration = lead.animation.duration ?? DEFAULT_BUILD_DURATION;
    delays.set(lead.element.id, leadDelay);
    for (let i = 1; i < builds.length; i++) {
        const b = builds[i]!;
        const own = b.animation.delay ?? 0;
        const trigger = b.animation.trigger ?? "on-click";
        // with-prev → simultaneous with lead; after-prev → starts after lead finishes.
        const base = trigger === "after-prev" ? leadDelay + leadDuration : leadDelay;
        delays.set(b.element.id, base + own);
    }
    return delays;
}

