    name: "vivid",
    colors: {
        background: "#0f172a",
        text: "#f8fafc",
        muted: "#cbd5e1",
        accent: "#22d3ee",
        surface: "#1e293b",
    },
};

export const builtinThemes: Record<string, Theme> = {
    default: defaultTheme,
    dark: darkTheme,
    vivid: vividTheme,
};

/**
 * A CSS font-family for a theme face, with a generic fallback.
 *
 * A deck names brand faces ("Poppins", "Inter") that the viewing browser often
 * does not have. Without a fallback the browser picks its default, which is a
 * SERIF, so a sans-serif deck drew its titles in Times; PowerPoint and
 * LibreOffice substitute a sans. Names with spaces are quoted; a value that is
 * already a stack (it has a comma) is left as the author wrote it.
 */
const GENERIC = {
    sans: "ui-sans-serif, system-ui, sans-serif",
    mono: "ui-monospace, SFMono-Regular, Menlo, monospace",
} as const;

export function fontStack(face: string | null | undefined, kind: keyof typeof GENERIC = "sans"): string {
    const name = typeof face === "string" ? face.trim() : "";
    if (name === "") return GENERIC[kind];
    if (name.includes(",")) return name;
    const quoted = /\s/.test(name) && !/^["'].*["']$/.test(name) ? `"${name}"` : name;
    return `${quoted}, ${GENERIC[kind]}`;
}

import { fontStack } from "../lib/utils/font-stack";
import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import { FauxClient, type FauxClientProps } from "@particle-academy/react-fancy";
import type { Deck, SlideElement, SlideTransition } from "../lib/types";
import { resolveTheme } from "../lib/theme/theme-utils";
import { Slide } from "../slide";
import { useSlideKeyboard } from "../lib/hooks/use-slide-keyboard";
import { totalBuildSteps } from "../lib/utils/builds";
import { cn } from "../lib/utils/cn";
import { defaultElementRegistry } from "../lib/registry";

export interface SlideViewerProps {
    /** Deck to play. */
    deck: Deck;
    /** Controlled current slide index. Use with `onIndexChange`. */
    index?: number;
    /** Default current slide index (uncontrolled). */
    defaultIndex?: number;
    /** Called when the viewer advances. */
    onIndexChange?: (index: number) => void;
    /** Called when the viewer exits (Esc). */
    onExit?: () => void;
    /** Auto-advance interval in ms — kiosk mode. Omit to disable. */
    autoAdvanceMs?: number;
    /** Hide the bottom progress bar + slide counter. */
    hideChrome?: boolean;
    /**
     * Custom renderer for element types Slide doesn't render natively
     * (chart/code/table/embed). Defaults to the built-in
     * `defaultElementRegistry` so decks play fully out of the box; pass your
     * own to override.
     */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** Extra classes on the viewer wrapper. */
    className?: string;
    /**
     * Show the deck in react-fancy's `FauxClient` frame: a device bezel with a
     * zoom bar and a full-screen button, out of sight until the frame is
     * hovered. Default `true`; `false` for the bare viewer, as before 0.21.
     */
    frame?: boolean;
    /** Passed to the frame: `variant`, `zoom` / `onZoomChange`, `onFullscreenChange`, … */
    frameProps?: Partial<FauxClientProps>;
}

/**
 * Read-only deck viewer. Renders one slide at a time at the maximum size
 * that fits the container while preserving the theme's aspect ratio.
 * Keyboard nav is built in; expand a fullscreen-ready container around
 * `<SlideViewer>` to get the F11-style experience.
 */
export function SlideViewer({
    deck,
    index: controlledIndex,
    defaultIndex,
    onIndexChange,
    onExit,
    autoAdvanceMs,
    hideChrome = false,
    renderElement = defaultElementRegistry,
    className,
    frame = true,
    frameProps,
}: SlideViewerProps) {
    const isControlled = controlledIndex !== undefined;
    const [internalIndex, setInternalIndex] = useState(defaultIndex ?? 0);
    const index = isControlled ? controlledIndex! : internalIndex;

    const goTo = useCallback(
        (i: number) => {
            const clamped = Math.max(0, Math.min(deck.slides.length - 1, i));
            if (!isControlled) setInternalIndex(clamped);
            onIndexChange?.(clamped);
        },
        [deck.slides.length, isControlled, onIndexChange],
    );

    const [blanked, setBlanked] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);
    const frameRef = useRef<HTMLDivElement>(null);
    // The frame shows the zoom controls; the SLIDE does the zooming, because a
    // viewer that fits itself to its box only re-fits under a scaled frame.
    const [ownZoom, setOwnZoom] = useState(frameProps?.defaultZoom ?? 1);
    const zoom = frame ? (frameProps?.zoom ?? ownZoom) : 1;
    const onZoomChange = useCallback(
        (z: number) => {
            setOwnZoom(z);
            frameProps?.onZoomChange?.(z);
        },
        [frameProps],
    );

    // Track nav direction so `slide` transitions default sensibly: advancing
    // forward enters from the right, going back enters from the left.
    const prevIndexRef = useRef(index);
    const forward = index >= prevIndexRef.current;

    // ─── Intra-slide build (entrance-animation) step-through ────────────────
    // 0 = nothing built yet on the current slide. Each forward advance fires
    // the next step until `totalBuildSteps`, after which we move to the next
    // slide. Going backward lands on the previous slide fully built.
    const slide = deck.slides[index];
    const totalSteps = totalBuildSteps(slide);
    const [buildStep, setBuildStep] = useState(0);

    // Reset the build step on slide change. Only a forward advance INTO the next
    // slide replays builds from 0; every other landing (retreat, Home/End,
    // digit jump, external control) shows the slide fully built. `nextFreshRef`
    // flags the one forward-advance case.
    const nextFreshRef = useRef(false);
    useEffect(() => {
        if (index === prevIndexRef.current) return;
        prevIndexRef.current = index;
        const fresh = nextFreshRef.current;
        nextFreshRef.current = false;
        setBuildStep(fresh ? 0 : totalBuildSteps(deck.slides[index]));
    }, [index, deck.slides]);

    const advance = useCallback(() => {
        if (buildStep < totalSteps) {
            setBuildStep((s) => s + 1);
        } else if (index < deck.slides.length - 1) {
            nextFreshRef.current = true; // next slide starts with nothing built
            goTo(index + 1);
        }
    }, [buildStep, totalSteps, index, deck.slides.length, goTo]);

    const retreat = useCallback(() => {
        // v1: reversing individual builds is out of scope — step back a whole
        // slide, showing it fully built (handled by the reset effect).
        if (index > 0) goTo(index - 1);
    }, [index, goTo]);

    useSlideKeyboard({
        total: deck.slides.length,
        index,
        goTo,
        onAdvance: advance,
        onRetreat: retreat,
        onExit,
        onBlank: () => setBlanked((b) => !b),
        onFullscreen: () => {
            // The frame, not the viewer: full screen keeps the zoom bar and the
            // exit button, and the frame's own button stays in step with it.
            const el = frame ? frameRef.current : containerRef.current;
            if (!el) return;
            if (document.fullscreenElement) document.exitFullscreen();
            else el.requestFullscreen?.();
        },
    });

    // Auto-advance loop for kiosk mode — steps through builds then slides.
    useEffect(() => {
        if (!autoAdvanceMs || deck.slides.length <= 1) return;
        const t = setTimeout(() => {
            if (buildStep < totalSteps) {
                setBuildStep((s) => s + 1);
            } else {
                nextFreshRef.current = true;
                goTo(index + 1 < deck.slides.length ? index + 1 : 0);
            }
        }, autoAdvanceMs);
        return () => clearTimeout(t);
    }, [autoAdvanceMs, index, deck.slides.length, goTo, buildStep, totalSteps]);
    const theme = resolveTheme(deck.theme);
    const aspectRatio = theme.aspectRatio ?? 16 / 9;

    // Resolve the incoming slide's entrance transition (slide → theme default → none).
    const transition: SlideTransition | undefined = slide?.transition ?? theme.defaultTransition;
    const enterStyle = transitionEnterStyle(transition, forward);

    const viewer = (
        <div
            ref={containerRef}
            className={cn("fs-viewer", className)}
            style={{
                position: "relative",
                width: "100%",
                height: "100%",
                background: blanked ? "#000000" : theme.colors?.background ?? "#000000",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                overflow: "hidden",
            }}
            tabIndex={0}
            data-fancy-slides-viewer={deck.id}
            data-fancy-slides-build-step={buildStep}
            onClick={(e) => {
                if (blanked) return;
                // Click zones: the left third goes back, the rest goes forward,
                // as in a book. A click anywhere used to go forward only.
                const box = e.currentTarget.getBoundingClientRect();
                if (box.width > 0 && e.clientX - box.left < box.width / 3) retreat();
                else advance();
            }}
        >
            {/* Keyframes for slide entrance transitions. Pure CSS — no runtime deps.
                Gated behind prefers-reduced-motion so animations vanish entirely
                for users who ask for less motion. */}
            <style>{TRANSITION_KEYFRAMES}</style>

            {!blanked && slide && (
                // What scrolls when the slide is zoomed past the frame. The
                // counter and the previous / next buttons sit outside it, so they
                // stay where they are.
                <div
                    data-fancy-slides-scroller=""
                    style={{
                        position: "absolute",
                        inset: 0,
                        display: "flex",
                        overflow: zoom > 1 ? "auto" : "hidden",
                        // A size container, so the slide can fit THIS box's
                        // height (cqh) rather than the window's (vh).
                        containerType: "size",
                    }}
                >
                <div
                    data-fancy-slides-slide-box=""
                    style={{
                        // Box that fits the slide while preserving aspect ratio,
                        // times the frame's zoom. `margin: auto` centres it while
                        // it fits and lets it scroll from its edge once it does not.
                        width: zoom === 1
                            ? "min(100cqw, calc(100cqh * var(--fs-ratio)))"
                            : `calc(min(100cqw, calc(100cqh * var(--fs-ratio))) * ${zoom})`,
                        flexShrink: 0,
                        margin: "auto",
                        aspectRatio: String(aspectRatio),
                        // CSS var lets us inline-style the aspect ratio so it works in any container.
                        ["--fs-ratio" as keyof React.CSSProperties as string]: aspectRatio.toString(),
                        boxShadow: "0 8px 30px rgba(0,0,0,0.35)",
                    } as React.CSSProperties}
                >
                    {/* Keyed by index so React remounts on every slide change and the
                        enter animation replays from its first frame. */}
                    <div key={index} className="fs-slide-enter" style={enterStyle}>
                        <Slide slide={slide} theme={theme} buildStep={buildStep} renderElement={renderElement} />
                    </div>
                </div>
                </div>
            )}

            {!blanked && index > 0 && (
                <button
                    type="button"
                    className="fs-nav"
                    data-fancy-slides-prev=""
                    aria-label="Previous slide"
                    title="Previous slide"
                    onClick={(e) => {
                        e.stopPropagation();
                        retreat();
                    }}
                    style={{ ...NAV_BUTTON, left: 12 }}
                >
                    <Chevron direction="left" />
                </button>
            )}
            {!blanked && (index < deck.slides.length - 1 || buildStep < totalSteps) && (
                <button
                    type="button"
                    className="fs-nav"
                    data-fancy-slides-next=""
                    aria-label="Next slide"
                    title="Next slide"
                    onClick={(e) => {
                        e.stopPropagation();
                        advance();
                    }}
                    style={{ ...NAV_BUTTON, right: 12 }}
                >
                    <Chevron direction="right" />
                </button>
            )}

            {!hideChrome && !blanked && (
                <div
                    style={{
                        position: "absolute",
                        bottom: 16,
                        right: 16,
                        padding: "4px 10px",
                        borderRadius: 999,
                        background: "rgba(15, 23, 42, 0.6)",
                        color: "#f8fafc",
                        fontSize: 12,
                        fontFamily: fontStack(theme.fonts?.mono, "mono"),
                        backdropFilter: "blur(6px)",
                    }}
                    aria-label="Slide counter"
                >
                    {index + 1} / {deck.slides.length}
                </div>
            )}
        </div>
    );

    if (!frame) return viewer;

    return (
        <FauxClient
            ref={frameRef}
            variant="device"
            fill
            controls
            {...frameProps}
            zoom={zoom}
            onZoomChange={onZoomChange}
            applyZoom={false}
            className={cn("fs-viewer-frame", frameProps?.className)}
        >
            {viewer}
        </FauxClient>
    );
}

/** The previous / next buttons: hidden until the viewer is hovered, like the frame's controls. */
const NAV_BUTTON: React.CSSProperties = {
    position: "absolute",
    top: "50%",
    transform: "translateY(-50%)",
    width: 36,
    height: 36,
    borderRadius: 999,
    border: "none",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    background: "rgba(15, 23, 42, 0.55)",
    color: "#f8fafc",
    cursor: "pointer",
    backdropFilter: "blur(6px)",
    zIndex: 2,
};

function Chevron({ direction }: { direction: "left" | "right" }) {
    return (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.25" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d={direction === "left" ? "m15 18-6-6 6-6" : "m9 18 6-6-6-6"} />
        </svg>
    );
}

// ─── Transitions ─────────────────────────────────────────────────────────────

const DEFAULT_DURATION = 400;
const EASE = "cubic-bezier(0.16, 1, 0.3, 1)"; // ease-out

/**
 * Build the inline style that drives a slide's entrance animation. The actual
 * keyframes live in {@link TRANSITION_KEYFRAMES}; here we just pick the right
 * `animation-name` + duration. `prefers-reduced-motion: reduce` is handled in
 * CSS (the keyframe-bearing rules are wrapped in a media query), so a reduced-
 * motion user simply sees the final frame with no movement.
 */
function transitionEnterStyle(transition: SlideTransition | undefined, forward: boolean): React.CSSProperties {
    const kind = transition?.kind ?? "none";
    if (kind === "none") return { width: "100%", height: "100%" };

    const duration = transition?.duration ?? DEFAULT_DURATION;
    let name: string;
    switch (kind) {
        case "fade":
            name = "fs-fade-in";
            break;
        case "zoom":
            name = "fs-zoom-in";
            break;
        case "slide": {
            const dir = transition?.direction ?? (forward ? "right" : "left");
            name = `fs-slide-in-${dir}`;
            break;
        }
        default:
            return { width: "100%", height: "100%" };
    }

    return {
        width: "100%",
        height: "100%",
        animationName: name,
        animationDuration: `${duration}ms`,
        animationTimingFunction: EASE,
        animationFillMode: "both",
    };
}

/**
 * Keyframes for every transition kind. Wrapped in
 * `@media (prefers-reduced-motion: no-preference)` so that reduced-motion users
 * get no animation at all — `animation-fill-mode: both` would otherwise pin the
 * element at its `from` frame, so we disable the animation entirely instead.
 */
const TRANSITION_KEYFRAMES = `
@media (prefers-reduced-motion: reduce) {
    .fs-slide-enter { animation: none !important; }
}
@media (prefers-reduced-motion: no-preference) {
    @keyframes fs-fade-in {
        from { opacity: 0; }
        to { opacity: 1; }
    }
    @keyframes fs-zoom-in {
        from { opacity: 0; transform: scale(0.92); }
        to { opacity: 1; transform: scale(1); }
    }
    @keyframes fs-slide-in-right {
        from { opacity: 0; transform: translateX(8%); }
        to { opacity: 1; transform: translateX(0); }
    }
    @keyframes fs-slide-in-left {
        from { opacity: 0; transform: translateX(-8%); }
        to { opacity: 1; transform: translateX(0); }
    }
    @keyframes fs-slide-in-up {
        from { opacity: 0; transform: translateY(8%); }
        to { opacity: 1; transform: translateY(0); }
    }
    @keyframes fs-slide-in-down {
        from { opacity: 0; transform: translateY(-8%); }
        to { opacity: 1; transform: translateY(0); }
    }
}
.fs-viewer .fs-nav { opacity: 0; transition: opacity 150ms ease; }
.fs-viewer:hover .fs-nav, .fs-viewer .fs-nav:focus-visible { opacity: 1; }
.fs-viewer .fs-nav:hover { background: rgba(15, 23, 42, 0.75) !important; }
@media (hover: none) { .fs-viewer .fs-nav { opacity: 1; } }
`;

/**
 * A CSS font-family for a theme face, with a generic fallback.
 *
 * A deck names brand faces ("Poppins", "Inter") that the viewing browser often
 * does not have. Without a fallback the browser picks its default, which is a
 * SERIF, so a sans-serif deck drew its titles in Times; PowerPoint and
 * LibreOffice substitute a sans. Names with spaces are quoted; a value that is
 * already a stack (it has a comma) is left as the author wrote it.
 */
const GENERIC = {
    sans: "ui-sans-serif, system-ui, sans-serif",
    mono: "ui-monospace, SFMono-Regular, Menlo, monospace",
} as const;

export function fontStack(face: string | null | undefined, kind: keyof typeof GENERIC = "sans"): string {
    const name = typeof face === "string" ? face.trim() : "";
    if (name === "") return GENERIC[kind];
    if (name.includes(",")) return name;
    const quoted = /\s/.test(name) && !/^["'].*["']$/.test(name) ? `"${name}"` : name;
    return `${quoted}, ${GENERIC[kind]}`;
}

/**
 * The fancy-slides data model.
 *
 * Every shape here is JSON-friendly — pure objects, arrays, primitives, and
 * tagged unions. No React children, no functions, no class instances. This
 * is the contract the deck schema commits to: an LLM can emit a deck, a
 * server can store one, a designer can hand-edit one, and the viewer +
 * editor will render it identically.
 *
 * Coordinate system: elements position themselves in slide-relative units
 * where the slide is a 1.0 × (1 / aspectRatio) rectangle. So `x: 0.5, y: 0.5`
 * is the centre of the slide regardless of how big it's rendered. This
 * keeps decks resolution-independent — a fullscreen 1920×1080 viewer and a
 * thumbnail at 320×180 render the same layout.
 */

// ─── Deck ──────────────────────────────────────────────────────────────────

export interface Deck {
    /** Stable id. Required even when persistence is in-memory. */
    id: string;
    /** Human title — shown in the editor chrome + browser tab. */
    title: string;
    /** Ordered slide list. The viewer steps through in this order. */
    slides: Slide[];
    /** Visual theme for the whole deck. */
    theme: Theme;
    /**
     * Schema version the deck was authored against. Omitted == version 1 (the
     * implicit version for decks created before versioning). Used by the
     * serialize / parse helpers to migrate older shapes forward. Mirrors
     * `dark-slide`'s `Schema::SCHEMA_VERSION`.
     */
    version?: number;
    /** Free-form metadata — `{ author, createdAt, updatedAt, tags, … }`. */
    metadata?: Record<string, unknown>;
}

/**
 * Current deck schema version. Bump when a structural change needs migration on
 * load. Kept in lockstep with the sibling `dark-slide` PHP package.
 */
export const SCHEMA_VERSION = 1;

// ─── Slide ─────────────────────────────────────────────────────────────────

/** Layout presets that pre-populate / constrain element placement. */
export type SlideLayout =
    | "blank"            // empty canvas, free placement
    | "title"            // centered title
    | "title-content"    // title at top, content area below
    | "two-column"       // left + right halves
    | "section-divider"  // section header with subtitle
    | "image-text"       // image left, text right
    | "text-image"       // text left, image right
    | "quote";           // big centered quote

export interface Slide {
    /** Stable id. */
    id: string;
    /** Optional layout preset. Mostly used by agents — humans tend to free-place. */
    layout?: SlideLayout;
    /** Elements rendered on the slide in z-order (last on top). */
    elements: SlideElement[];
    /** Background fill — color, image, or gradient. Inherits from theme when absent. */
    background?: SlideBackground;
    /** Entrance transition for this slide. Inherits from theme.transition when absent. */
    transition?: SlideTransition;
    /** Speaker notes — markdown. */
    notes?: string;
    /**
     * Plain-text narration script for AI-narrated decks: TTS reads from
     * `narration`, presenter view shows `notes`. Opaque to the pptx writer
     * (stored as data, not rendered into the slide).
     */
    narration?: string;
    /** Free-form metadata — `{ title, tags, durationSec, … }`. */
    metadata?: Record<string, unknown>;
}

// ─── Elements ──────────────────────────────────────────────────────────────

/**
 * Every element is positioned in slide-relative coordinates (0..1). x/y are
 * the top-left corner; w/h are width/height as a fraction of the slide.
 */
export interface ElementBase {
    /** Stable id. Agents reference elements by id. */
    id: string;
    /** Element kind — discriminator. */
    type: SlideElement["type"];
    /** Left edge, 0..1 (fraction of slide width). */
    x: number;
    /** Top edge, 0..1 (fraction of slide height). */
    y: number;
    /** Width, 0..1. */
    w: number;
    /** Height, 0..1. */
    h: number;
    /** Rotation in degrees, clockwise. */
    rotation?: number;
    /** Z-order — higher renders on top. Falls back to array order when undefined. */
    z?: number;
    /** Lock from editing. */
    locked?: boolean;
    /** Hide on this slide (still in the data — for animated reveals). */
    hidden?: boolean;
    /**
     * Whole-element hyperlink. When set, the element becomes a click target in
     * the viewer (opens in a new tab) and the pptx writer emits an
     * `<a:hlinkClick>` on the shape / picture. For rich inline links *within*
     * text, use a markdown `[label](url)` in the text content instead.
     */
    href?: string;
    /** Entrance build animation — when present the element participates in the slide's build sequence. */
    animation?: ElementAnimation;
}

// ─── Element entrance animations (builds) ────────────────────────────────────

/** Visual entrance effect played when an element builds onto the slide. */
export type AnimationEffect = "fade" | "fly-in" | "zoom" | "wipe";

/** When an element's build fires relative to the surrounding builds. */
export type AnimationTrigger = "on-click" | "with-prev" | "after-prev";

/**
 * Per-element entrance animation ("build step"). Elements with an `animation`
 * start hidden and reveal as the presenter advances through the slide's build
 * sequence. The shape is shared with the sibling `dark-slide` PHP package, so
 * keep it byte-for-byte aligned.
 */
export interface ElementAnimation {
    /** Visual effect. */
    effect: AnimationEffect;
    /** When the build fires relative to its neighbours. Default `"on-click"`. */
    trigger?: AnimationTrigger;
    /** Direction for `fly-in` / `wipe`. Default `"left"`. */
    direction?: "left" | "right" | "up" | "down";
    /** Effect duration in ms. Default `500`. */
    duration?: number;
    /** Delay before the effect starts, in ms. Default `0`. */
    delay?: number;
    /** Build order within the slide, ascending; ties broken by element array index. */
    order?: number;
    /**
     * Reveal a TEXT element one paragraph/line at a time (PowerPoint/Google
     * Slides "By paragraph"). The element expands into one build per paragraph
     * — the element's `content` split on `"\n"` (a trailing empty line is
     * dropped). The first paragraph uses this animation's `trigger`; every
     * subsequent paragraph reveals on a fresh click. Only meaningful for text
     * elements; ignored for other types and when the element has 0/1 paragraphs
     * (then it behaves like a normal single build).
     */
    byParagraph?: boolean;
}

export interface TextElement extends ElementBase {
    type: "text";
    /** Content — markdown by default; can also be plain text or HTML. */
    content: string;
    /** Content format. Defaults to `"markdown"`. */
    format?: "markdown" | "html" | "plain";
    /** Typography. */
    style?: TextStyle;
}

export interface TextStyle {
    /** Font family — falls back to theme.fonts.body. */
    fontFamily?: string;
    /** Font size in px at the slide's design width (theme.slideWidth). */
    fontSize?: number;
    /** Font weight (`100..900`, or `"normal" | "bold"`). */
    weight?: "normal" | "medium" | "semibold" | "bold" | number;
    /** Horizontal alignment. */
    align?: "left" | "center" | "right" | "justify";
    /** Vertical alignment within the box. */
    verticalAlign?: "top" | "middle" | "bottom";
    /** Color (any CSS color). Falls back to theme.colors.text. */
    color?: string;
    /** Line height (multiplier). */
    lineHeight?: number;
    /** Italic. */
    italic?: boolean;
    /** Underline. */
    underline?: boolean;
}

export interface ImageElement extends ElementBase {
    type: "image";
    /** Image URL or data URI. */
    src: string;
    /** Alt text for accessibility. */
    alt?: string;
    /** How the image is fit inside its box. */
    fit?: "contain" | "cover" | "fill" | "scale-down";
    /** Optional crop window (slide-relative). */
    crop?: { x: number; y: number; w: number; h: number };
}

export interface ChartElement extends ElementBase {
    type: "chart";
    /** Apache ECharts option object. Passed straight to `<EChart>`. */
    option: Record<string, unknown>;
    /** Theme name passed to `<EChart>`. */
    chartTheme?: string;
}

export interface CodeElement extends ElementBase {
    type: "code";
    /** Source code. */
    code: string;
    /** Language alias for the highlighter. */
    language?: string;
    /** Show line numbers. Defaults to `true`. */
    lineNumbers?: boolean;
    /** Theme — `"light"`, `"dark"`, `"auto"`, or a custom registered name. */
    codeTheme?: string;
}

/**
 * One table column. `key` is what every row is keyed BY; `label` is what the
 * header shows, and falls back to `key` when absent, as dark-slide’s writer
 * resolves it.
 */
/**
 * A table cell's look: dark-slide's table cell model, drawn the same way here.
 * Precedence: cell > row > column > band (header | stripe | body) > table >
 * theme > default. `false` stops the chain and means off.
 */
export interface TableCellStyle {
    fill?: string | false;
    color?: string;
    bold?: boolean;
    italic?: boolean;
    underline?: boolean;
    align?: "left" | "center" | "right" | "justify";
    anchor?: "top" | "middle" | "bottom";
    /** Design px, scaled like text. */
    fontSize?: number;
    fontFamily?: string;
    /** `false` for none, or one rule for every side: `{ color, width }` (width in design px). */
    borders?: false | { color?: string; width?: number };
}

export interface TableColumn extends TableCellStyle {
    key: string;
    label?: string;
    /** A fraction of the table (all widths <= 1) or a weight. */
    width?: number;
}

/** A cell given as an object: its text plus its own style. */
export interface TableCell extends TableCellStyle {
    text: string;
}

export interface TableStyle extends TableCellStyle {
    /** The header row's band (default: theme accent, white, bold); `false` for no header row. */
    header?: TableCellStyle | false;
    /** Every second body row's band (default: theme surface); `false` for none. */
    stripe?: TableCellStyle | false;
    /** Every body row's band. */
    body?: TableCellStyle;
}

/**
 * One table row: an object keyed by each column’s `key`, or the values in COLUMN
 * ORDER.
 *
 * The keyed form is canonical — it survives a column reorder, and it is the only
 * one that can also carry row-level style for the pptx writer. The positional
 * form is accepted because it is what an author guesses from a bare column list,
 * and guessing it used to render a full-size grid with every cell blank and
 * nothing logged (#14).
 */
export type TableRow = Record<string, unknown> | unknown[];

export interface TableElement extends ElementBase {
    type: "table";
    /** Column definitions — `{ key, label }`. */
    columns: TableColumn[];
    /** Row data — objects keyed by column `key`, or values in column order. A value is text or a `TableCell`. */
    rows: TableRow[];
    /** The table's look, as dark-slide writes it. */
    style?: TableStyle;
}

export type ShapeKind = "rect" | "rounded-rect" | "ellipse" | "line" | "arrow" | "triangle";

export interface ShapeElement extends ElementBase {
    type: "shape";
    shape: ShapeKind;
    /** Fill color (any CSS color, or `"none"`). */
    fill?: string;
    /** Stroke color. */
    stroke?: string;
    /** Stroke width in px at the slide's design width. */
    strokeWidth?: number;
    /** Dashed stroke. */
    dashed?: boolean;
    /**
     * Corner radius for `rounded-rect`, in px at the slide's design width (default 8),
     * capped at half the shorter side. A plain `rect` has square corners.
     */
    radius?: number;
}

export interface EmbedElement extends ElementBase {
    type: "embed";
    /** Embed URL — typically a video, dashboard, or fancy-screens Screen. */
    src: string;
    /** iframe `title` for accessibility. */
    title?: string;
    /** Sandbox attribute. Defaults to allow-scripts (no allow-same-origin). */
    sandbox?: string;
}

export type SlideElement =
    | TextElement
    | ImageElement
    | ChartElement
    | CodeElement
    | TableElement
    | ShapeElement
    | EmbedElement;

// ─── Background, transitions, theme ────────────────────────────────────────

export interface SlideBackground {
    /** Solid color, or `"transparent"` to inherit theme. */
    color?: string;
    /** Image background URL. Takes precedence over color when present. */
    image?: string;
    /** How the background image is fit. Defaults to `"cover"`. */
    imageFit?: "contain" | "cover" | "fill";
    /** Optional gradient — `"linear-gradient(...)"` or `"radial-gradient(...)"` string. */
    gradient?: string;
}

export type TransitionKind = "none" | "fade" | "slide" | "zoom";

export interface SlideTransition {
    kind: TransitionKind;
    /** Duration in ms. */
    duration?: number;
    /** Direction for `slide` transitions. */
    direction?: "left" | "right" | "up" | "down";
}

export interface Theme {
    /** Theme name — used for serialization + agent routing. */
    name: string;
    /** Aspect ratio — defaults to 16:9. Custom themes can pick anything. */
    aspectRatio?: number;
    /** Design width in px. Slides scale to fit; this just sets the unit base for fontSize/strokeWidth. */
    slideWidth?: number;
    colors?: ThemeColors;
    fonts?: ThemeFonts;
    /** Default transition for slides that don't specify their own. */
    defaultTransition?: SlideTransition;
}

export interface ThemeColors {
    background?: string;
    text?: string;
    muted?: string;
    accent?: string;
    surface?: string;
}

export interface ThemeFonts {
    /** Used for `Heading`-like text elements (the default for large fontSize). */
    heading?: string;
    /** Used for body text. */
    body?: string;
    /** Used by CodeElement. */
    mono?: string;
}

// ─── Agent / Human+ surface ────────────────────────────────────────────────

/**
 * Agent activity broadcast whenever the deck mutates. Hosts subscribe to feed
 * an AgentPanel, presence layer, or audit log.
 */
export interface DeckActivity {
    /** Stable activity id. */
    id: string;
    /** Wall-clock timestamp. */
    at: number;
    /** Who made the change. */
    actor: { kind: "human" | "agent"; id: string; name?: string; color?: string };
    /** What changed. */
    op: DeckOp;
}

/**
 * The canonical, language-neutral deck operation vocabulary (v0.13+).
 *
 * Every op is a flat JSON object discriminated by a dotted `op` string. The
 * shape is deliberately language-neutral so the *same* op contract is shared
 * with the sibling `dark-slide` PHP package: an op emitted by `<DeckEditor>` in
 * the browser can be reduced server-side by `DarkSlide\Reducer::apply()`, and a
 * server-computed `DarkSlide\Agent::diff()` replays in the editor — one
 * vocabulary, one reducer per authoritative host. Published as a JSON Schema via
 * {@link deckOpSchema} so any backend can validate it.
 *
 * Ids are always named `slideId` / `elementId` (never a bare `id`), and `op`
 * names are `subject.verb` in camelCase. Migrating from the pre-0.13
 * `kind`-flavored ops: {@link mapLegacyOp}.
 */
export type DeckOp =
    | { op: "deck.setTitle"; title: string }
    | { op: "deck.setTheme"; theme: Theme }
    /** Replace the entire deck atomically — stream a full presentation IN in one op. */
    | { op: "deck.replace"; deck: Deck }
    | { op: "slide.add"; index: number; slide: Slide }
    | { op: "slide.remove"; slideId: string }
    | { op: "slide.reorder"; slideId: string; toIndex: number }
    | { op: "slide.setLayout"; slideId: string; layout: SlideLayout }
    | { op: "slide.setNotes"; slideId: string; notes: string }
    | { op: "slide.setBackground"; slideId: string; background?: SlideBackground }
    | { op: "slide.setTransition"; slideId: string; transition?: SlideTransition }
    | { op: "element.add"; slideId: string; element: SlideElement }
    | { op: "element.remove"; slideId: string; elementId: string }
    | { op: "element.update"; slideId: string; elementId: string; patch: Partial<SlideElement> }
    | { op: "element.move"; slideId: string; elementId: string; x: number; y: number }
    | { op: "element.resize"; slideId: string; elementId: string; w: number; h: number }
    | { op: "element.setAnimation"; slideId: string; elementId: string; animation?: ElementAnimation };

/** The dotted `op` discriminator of every {@link DeckOp}. */
export type DeckOpType = DeckOp["op"];

/**
 * The pre-0.13 `kind`-flavored op vocabulary. Retained so existing consumers can
 * map their stored/streamed ops forward with {@link mapLegacyOp}. Prefer
 * {@link DeckOp} in new code.
 *
 * @deprecated Use {@link DeckOp}; convert with {@link mapLegacyOp}.
 */
export type LegacyDeckOp =
    | { kind: "deck_set_title"; title: string }
    | { kind: "deck_apply_theme"; theme: Theme }
    | { kind: "deck_set"; deck: Deck }
    | { kind: "slide_add"; index: number; slide: Slide }
    | { kind: "slide_remove"; id: string }
    | { kind: "slide_reorder"; id: string; toIndex: number }
    | { kind: "slide_set_layout"; id: string; layout: SlideLayout }
    | { kind: "slide_set_notes"; id: string; notes: string }
    | { kind: "slide_set_background"; id: string; background?: SlideBackground }
    | { kind: "slide_set_transition"; id: string; transition?: SlideTransition }
    | { kind: "element_add"; slideId: string; element: SlideElement }
    | { kind: "element_remove"; slideId: string; elementId: string }
    | { kind: "element_update"; slideId: string; elementId: string; patch: Partial<SlideElement> }
    | { kind: "element_move"; slideId: string; elementId: string; x: number; y: number }
    | { kind: "element_resize"; slideId: string; elementId: string; w: number; h: number }
    | { kind: "element_set_animation"; slideId: string; elementId: string; animation?: ElementAnimation };

import type { Theme } from "../types";
import { defaultTheme } from "./default-theme";

/**
 * Merge a partial theme with the defaults so consumers can override just the
 * pieces they care about (colors, fonts, aspect ratio) and inherit the rest.
 */
export function defineTheme(overrides: Partial<Theme> & { name: string }): Theme {
    return {
        ...defaultTheme,
        ...overrides,
        colors: { ...defaultTheme.colors, ...overrides.colors },
        fonts: { ...defaultTheme.fonts, ...overrides.fonts },
        defaultTransition: overrides.defaultTransition ?? defaultTheme.defaultTransition,
    };
}

/** Resolve the effective theme for a deck — applies the default for any missing fields. */
export function resolveTheme(theme: Theme | undefined): Theme {
    if (!theme) return defaultTheme;
    return defineTheme(theme);
}

import { useCallback, useEffect, useMemo, useRef } from "react";

export interface SlideKeyboardOptions {
    /** Number of slides — clamps next/prev to bounds. */
    total: number;
    /** Current slide index. */
    index: number;
    /** Move to a specific slide. Used by Home/End/1-9 (and by arrows when no `onAdvance`/`onRetreat`). */
    goTo: (index: number) => void;
    /**
     * Forward step (→ / Space / PageDown). When provided it OWNS forward nav —
     * e.g. step through builds, then advance the slide. Falls back to
     * `goTo(index + 1)` when omitted.
     */
    onAdvance?: () => void;
    /**
     * Backward step (← / PageUp). When provided it OWNS backward nav. Falls back
     * to `goTo(index - 1)` when omitted.
     */
    onRetreat?: () => void;
    /** Called on Esc — typically exits fullscreen. */
    onExit?: () => void;
    /** Called on `B` — typically blacks/whites out the screen. */
    onBlank?: () => void;
    /** Called on `F` — typically toggles fullscreen. */
    onFullscreen?: () => void;
    /** Disable when the editor is focused / a modal is open. */
    enabled?: boolean;
}

/**
 * A custom shortcut handler. Return `true` to let the built-in keymap (and any
 * earlier-registered handler for the same combo) also run — by default a match
 * is consumed.
 */
export type ShortcutHandler = (event: KeyboardEvent) => void | boolean;

/** One row of the active keymap — for rendering a cheatsheet. */
export interface KeymapEntry {
    combo: string;
    description: string;
    source: "builtin" | "custom";
}

export interface SlideKeyboardApi {
    /**
     * Register an app-specific shortcut without forking the hook. Combos use a
     * `Mod+S` grammar (`Mod` = ⌘ on macOS, Ctrl elsewhere; also `Cmd`/`Ctrl`/
     * `Alt`/`Shift`), or a bare key (`/`, `Enter`). Most-recently-registered wins
     * for the same combo. Returns an `unregister` function.
     */
    registerShortcut: (combo: string, handler: ShortcutHandler, description?: string) => () => void;
    /** The active keymap (built-ins + registered) — render a cheatsheet without duplicating source. */
    activeKeymap: () => KeymapEntry[];
}

const BUILTIN_KEYMAP: KeymapEntry[] = [
    { combo: "→ / Space / PageDown", description: "Advance (next build / slide)", source: "builtin" },
    { combo: "← / PageUp", description: "Retreat (previous build / slide)", source: "builtin" },
    { combo: "Home", description: "First slide", source: "builtin" },
    { combo: "End", description: "Last slide", source: "builtin" },
    { combo: "1–9", description: "Jump to slide N", source: "builtin" },
    { combo: "Esc", description: "Exit", source: "builtin" },
    { combo: "B / .", description: "Blank screen", source: "builtin" },
    { combo: "F", description: "Toggle fullscreen", source: "builtin" },
];

function isMac(): boolean {
    if (typeof navigator === "undefined") return false;
    return /mac|iphone|ipad/i.test(navigator.platform || navigator.userAgent || "");
}

function canon(meta: boolean, ctrl: boolean, alt: boolean, shift: boolean, key: string): string {
    const mods: string[] = [];
    if (meta) mods.push("meta");
    if (ctrl) mods.push("ctrl");
    if (alt) mods.push("alt");
    if (shift) mods.push("shift");
    mods.sort();
    return [...mods, key.toLowerCase()].join("+");
}

/** Parse a combo string (`"Mod+S"`, `"Cmd+K"`, `"/"`) into the canonical form. */
function parseCombo(combo: string): string {
    const segs = combo.split("+").map((s) => s.trim()).filter(Boolean);
    const key = segs.pop() ?? "";
    let meta = false,
        ctrl = false,
        alt = false,
        shift = false;
    for (const s of segs) {
        const m = s.toLowerCase();
        if (m === "mod") (isMac() ? (meta = true) : (ctrl = true));
        else if (m === "cmd" || m === "meta" || m === "super" || m === "win") meta = true;
        else if (m === "ctrl" || m === "control") ctrl = true;
        else if (m === "alt" || m === "option" || m === "opt") alt = true;
        else if (m === "shift") shift = true;
    }
    return canon(meta, ctrl, alt, shift, key);
}

function eventCombo(e: KeyboardEvent): string {
    return canon(e.metaKey, e.ctrlKey, e.altKey, e.shiftKey, e.key);
}

/**
 * Standard slideshow keyboard plumbing, plus a `registerShortcut` extension
 * point for app-specific combos.
 *
 *   ←   / PageUp     — retreat (onRetreat, else previous slide)
 *   →   / PageDown / Space — advance (onAdvance, else next slide)
 *   Home / End        — first / last slide
 *   Esc               — onExit
 *   B / .             — onBlank (blackout)
 *   F                 — onFullscreen
 *   1..9              — jump to slide N
 *
 * Returns a {@link SlideKeyboardApi} — existing callers that ignore the return
 * value keep working unchanged.
 */
export function useSlideKeyboard({
    total,
    index,
    goTo,
    onAdvance,
    onRetreat,
    onExit,
    onBlank,
    onFullscreen,
    enabled = true,
}: SlideKeyboardOptions): SlideKeyboardApi {
    // Registered shortcuts live in a ref so registering doesn't re-bind the
    // keydown listener; each entry keeps its raw combo + description for the keymap.
    const shortcutsRef = useRef<Map<string, { handler: ShortcutHandler; combo: string; description: string }>>(new Map());

    const registerShortcut = useCallback<SlideKeyboardApi["registerShortcut"]>((combo, handler, description = "") => {
        const key = parseCombo(combo);
        const entry = { handler, combo, description };
        shortcutsRef.current.set(key, entry);
        return () => {
            // Only remove if a newer registration hasn't replaced it.
            if (shortcutsRef.current.get(key) === entry) shortcutsRef.current.delete(key);
        };
    }, []);

    const activeKeymap = useCallback<SlideKeyboardApi["activeKeymap"]>(() => {
        const custom: KeymapEntry[] = [...shortcutsRef.current.values()].map((e) => ({
            combo: e.combo,
            description: e.description,
            source: "custom" as const,
        }));
        return [...BUILTIN_KEYMAP, ...custom];
    }, []);

    useEffect(() => {
        if (!enabled) return;

        const handler = (e: KeyboardEvent) => {
            const target = e.target as HTMLElement | null;
            const editable = !!target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable);
            const hasMod = e.metaKey || e.ctrlKey || e.altKey;

            // Custom shortcuts fire first. A modifier combo (Cmd+S) works even
            // while typing; a bare-key combo (/) is suppressed inside inputs so
            // it doesn't hijack text entry.
            if (hasMod || !editable) {
                const shortcut = shortcutsRef.current.get(eventCombo(e));
                if (shortcut) {
                    const chain = shortcut.handler(e);
                    if (chain !== true) return; // consumed unless it opts into chaining
                }
            }

            // Built-in navigation never runs while editing text.
            if (editable) return;

            switch (e.key) {
                case "ArrowLeft":
                case "PageUp":
                    e.preventDefault();
                    if (onRetreat) onRetreat();
                    else if (index > 0) goTo(index - 1);
                    return;
                case "ArrowRight":
                case "PageDown":
                case " ":
                    e.preventDefault();
                    if (onAdvance) onAdvance();
                    else if (index < total - 1) goTo(index + 1);
                    return;
                case "Home":
                    e.preventDefault();
                    goTo(0);
                    return;
                case "End":
                    e.preventDefault();
                    goTo(total - 1);
                    return;
                case "Escape":
                    if (onExit) {
                        e.preventDefault();
                        onExit();
                    }
                    return;
                case "b":
                case "B":
                case ".":
                    if (onBlank) {
                        e.preventDefault();
                        onBlank();
                    }
                    return;
                case "f":
                case "F":
                    if (onFullscreen) {
                        e.preventDefault();
                        onFullscreen();
                    }
                    return;
                default: {
                    const n = parseInt(e.key, 10);
                    if (Number.isFinite(n) && n >= 1 && n <= 9) {
                        e.preventDefault();
                        goTo(Math.min(total - 1, n - 1));
                    }
                }
            }
        };

        window.addEventListener("keydown", handler);
        return () => window.removeEventListener("keydown", handler);
    }, [enabled, index, total, goTo, onAdvance, onRetreat, onExit, onBlank, onFullscreen]);

    return useMemo<SlideKeyboardApi>(() => ({ registerShortcut, activeKeymap }), [registerShortcut, activeKeymap]);
}

/**
 * Build (entrance-animation) sequencing — the shared model used by both
 * `SlideViewer` and `PresenterView` so step-through behaves identically.
 *
 * A slide's *builds* are the elements that carry an `animation`. They are
 * stable-sorted by `(order ?? 0)` then original element array index, then
 * grouped into *click steps*:
 *
 *   - The first build, and every build whose trigger is `"on-click"`, starts
 *     a NEW step.
 *   - `"with-prev"` plays simultaneously with the current step's lead.
 *   - `"after-prev"` plays after a delay equal to the current step's lead
 *     duration (chained onto its `delay`).
 *
 * `buildStep` semantics (used by the viewer/presenter):
 *   - `0`  → nothing built yet; only non-animated elements are visible.
 *   - `n`  → the first `n` steps have fired; their elements are visible.
 *   - `totalSteps` → every build is shown (the fully-built slide).
 */

import type { ElementAnimation, Slide, SlideElement } from "../types";

/** One element participating in a build, paired with its (defaulted) animation. */
export interface Build {
    element: SlideElement;
    animation: ElementAnimation;
    /** Original index of the element in the slide's `elements` array (tie-breaker). */
    index: number;
    /**
     * For a "by paragraph" text build, which paragraph index (0-based) this
     * build reveals. Undefined for whole-element builds. The renderer uses this
     * to show "the first K paragraphs of this element".
     */
    paraIndex?: number;
}

/**
 * Split a text element's `content` into paragraphs for a "by paragraph" build.
 * Splits on `"\n"` and drops a single trailing empty line (so content ending in
 * a newline doesn't manifest a phantom blank build). Empty interior lines are
 * preserved — they still consume a click, matching PowerPoint's behaviour.
 */
export function splitParagraphs(content: string): string[] {
    const lines = content.split("\n");
    if (lines.length > 1 && lines[lines.length - 1] === "") lines.pop();
    return lines;
}

/**
 * The blocks a text element renders as in the static (non-build) path, given its
 * `format`. Markdown/HTML content is split line-by-line (one block per `"\n"`) so
 * a single newline is a hard line/paragraph break — the canonical line-based
 * model (`splitParagraphs`, `normalizeSlideMarkdown`, dark-slide's pptx export).
 * Passing the whole multi-line string to a CommonMark renderer would instead
 * fold a lone `"\n"` into a soft break (a space), collapsing the lines.
 *
 * `plain` content is returned as a single block: it renders with
 * `white-space: pre-wrap`, which already preserves its newlines.
 */
export function textBlocks(content: string, format: "markdown" | "html" | "plain"): string[] {
    return format === "plain" ? [content] : splitParagraphs(content);
}

/**
 * Whether an element expands into per-paragraph builds: a text element whose
 * animation has `byParagraph` and that splits into 2+ paragraphs. With 0/1
 * paragraphs it behaves like a normal single build.
 */
export function isByParagraph(element: SlideElement, animation: ElementAnimation): boolean {
    if (!animation.byParagraph || element.type !== "text") return false;
    return splitParagraphs(element.content).length > 1;
}

/** A click step — the set of builds revealed by a single forward advance. */
export interface BuildStep {
    /** Builds that reveal on this step (lead first, then with-prev / after-prev). */
    builds: Build[];
}

const DEFAULT_BUILD_DURATION = 500;

/**
 * Collect a slide's builds in resolved order: every element with an
 * `animation`, stable-sorted by `(order ?? 0)` then array index.
 */
export function collectBuilds(slide: Slide | undefined): Build[] {
    if (!slide) return [];
    const builds: Build[] = [];
    slide.elements.forEach((element, index) => {
        if (element.animation) {
            builds.push({ element, animation: element.animation, index });
        }
    });
    // Stable sort: Array.prototype.sort is stable in modern engines, but we
    // tie-break on the captured array index explicitly to be safe.
    const ordered = builds.sort((a, b) => {
        const ao = a.animation.order ?? 0;
        const bo = b.animation.order ?? 0;
        if (ao !== bo) return ao - bo;
        return a.index - b.index;
    });

    // Expand "by paragraph" text builds into one build per paragraph. The first
    // paragraph keeps the element's own trigger (so it can be with-prev /
    // after-prev relative to a prior element); every subsequent paragraph is
    // "on-click" — one line per click. They stay contiguous, so the rest of an
    // element's paragraphs fire before the next element's builds.
    const expanded: Build[] = [];
    for (const build of ordered) {
        if (isByParagraph(build.element, build.animation)) {
            const paras = splitParagraphs((build.element as { content: string }).content);
            paras.forEach((_, paraIndex) => {
                const animation: ElementAnimation =
                    paraIndex === 0 ? build.animation : { ...build.animation, trigger: "on-click" };
                expanded.push({ element: build.element, animation, index: build.index, paraIndex });
            });
        } else {
            expanded.push(build);
        }
    }
    return expanded;
}

/**
 * Group a slide's builds into click steps. The first build always opens a
 * step; thereafter an `"on-click"` trigger opens a new step while
 * `"with-prev"` / `"after-prev"` attach to the current one.
 */
export function buildSteps(slide: Slide | undefined): BuildStep[] {
    const builds = collectBuilds(slide);
    const steps: BuildStep[] = [];
    for (const build of builds) {
        const trigger = build.animation.trigger ?? "on-click";
        if (steps.length === 0 || trigger === "on-click") {
            steps.push({ builds: [build] });
        } else {
            steps[steps.length - 1]!.builds.push(build);
        }
    }
    return steps;
}

/** Total number of click steps for a slide (0 when the slide has no builds). */
export function totalBuildSteps(slide: Slide | undefined): number {
    return buildSteps(slide).length;
}

/**
 * Given a slide and a `buildStep` (0..totalSteps), return the set of element
 * ids that should be VISIBLE. Elements with no animation are always visible;
 * animated elements become visible once their owning step has fired.
 */
export function visibleElementIds(slide: Slide | undefined, buildStep: number): Set<string> {
    const visible = new Set<string>();
    if (!slide) return visible;
    const steps = buildSteps(slide);
    const stepOfElement = new Map<string, number>(); // 1-based step at which an element FIRST reveals
    steps.forEach((step, i) => {
        for (const b of step.builds) {
            // For by-paragraph builds many builds share one element id; the
            // element is visible once its earliest (first paragraph) step fires.
            if (!stepOfElement.has(b.element.id)) stepOfElement.set(b.element.id, i + 1);
        }
    });
    for (const element of slide.elements) {
        const revealStep = stepOfElement.get(element.id);
        if (revealStep === undefined) {
            visible.add(element.id); // no animation → always visible
        } else if (buildStep >= revealStep) {
            visible.add(element.id); // step has fired
        }
    }
    return visible;
}

/**
 * Per-element paragraph reveal state for a "by paragraph" text build at a given
 * `buildStep`. Keyed by element id:
 *   - `revealed` — how many paragraphs (0..count) should be shown so far.
 *   - `firingParaIndex` — the paragraph index revealing on the step that just
 *     fired (so the renderer plays its entrance effect), or `undefined` when no
 *     paragraph of this element fires on `buildStep`.
 * Only elements that actually expand by-paragraph appear in the map.
 */
export interface ParaReveal {
    revealed: number;
    firingParaIndex?: number;
}

export function paragraphReveals(slide: Slide | undefined, buildStep: number): Map<string, ParaReveal> {
    const out = new Map<string, ParaReveal>();
    if (!slide) return out;
    const steps = buildSteps(slide);
    steps.forEach((step, i) => {
        const stepNum = i + 1; // 1-based
        for (const b of step.builds) {
            if (b.paraIndex === undefined) continue;
            const fired = buildStep >= stepNum;
            const prev = out.get(b.element.id) ?? { revealed: 0 };
            if (fired) {
                prev.revealed = Math.max(prev.revealed, b.paraIndex + 1);
                if (stepNum === buildStep) prev.firingParaIndex = b.paraIndex;
            }
            out.set(b.element.id, prev);
        }
    });
    return out;
}

/**
 * The builds that fire when advancing INTO `buildStep` (1-based). Returns the
 * lead build first; the viewer uses `with-prev` / `after-prev` to compute each
 * element's effective `delay`. Empty when `buildStep` is out of range.
 */
export function buildsForStep(slide: Slide | undefined, buildStep: number): Build[] {
    const steps = buildSteps(slide);
    const step = steps[buildStep - 1];
    return step ? step.builds : [];
}

/**
 * Compute the effective entrance delay (ms) for each build within a step,
 * honouring `with-prev` (0 extra) and `after-prev` (lead duration). The lead
 * build keeps its own `delay`; followers add to it. Keyed by element id.
 */
export function stepDelays(builds: Build[]): Map<string, number> {
    const delays = new Map<string, number>();
    const lead = builds[0];
    if (!lead) return delays;
    const leadDelay = lead.animation.delay ?? 0;
    const leadDuration = lead.animation.duration ?? DEFAULT_BUILD_DURATION;
    delays.set(lead.element.id, leadDelay);
    for (let i = 1; i < builds.length; i++) {
        const b = builds[i]!;
        const own = b.animation.delay ?? 0;
        const trigger = b.animation.trigger ?? "on-click";
        // with-prev → simultaneous with lead; after-prev → starts after lead finishes.
        const base = trigger === "after-prev" ? leadDelay + leadDuration : leadDelay;
        delays.set(b.element.id, base + own);
    }
    return delays;
}

/**
 * Tiny class-name joiner. Avoids pulling clsx as a dep for this small package.
 */
export function cn(...parts: Array<string | false | null | undefined>): string {
    return parts.filter(Boolean).join(" ");
}

/**
 * Default element registry. Wires up the element types fancy-slides doesn't
 * render natively (chart / code / table / embed) by composing the other
 * fancy packages as optional peer deps.
 *
 * Hosts opt into this by importing from the `/registry` subpath:
 *
 *     import { defaultElementRegistry } from "@particle-academy/fancy-slides/registry";
 *     <DeckEditor renderElement={defaultElementRegistry} … />
 *
 * Keeping it behind a subpath means consumers who only render decks with
 * built-in element types (text / image / shape) never pull fancy-echarts,
 * fancy-code, or react-fancy Table into their bundle.
 */

import { lazy, Suspense } from "react";
import type { ChartElement, CodeElement, SlideElement, EmbedElement, TableElement } from "../types";

const ChartHost = lazy(() => import("./element-renderers/chart-host"));
const CodeHost = lazy(() => import("./element-renderers/code-host"));
const TableHost = lazy(() => import("./element-renderers/table-host"));
const EmbedHost = lazy(() => import("./element-renderers/embed-host"));

const Loading = ({ label }: { label: string }) => (
    <div
        style={{
            display: "grid",
            placeItems: "center",
            width: "100%",
            height: "100%",
            color: "rgba(0,0,0,0.4)",
            fontSize: 12,
            fontFamily: "ui-sans-serif, system-ui, sans-serif",
        }}
    >
        {label}…
    </div>
);

/**
 * Renderer signature compatible with `Slide`'s `renderElement` prop. Returns
 * `undefined` for element types fancy-slides handles itself, so the call
 * site falls back to the built-in renderer.
 */
export function defaultElementRegistry(element: SlideElement, slideWidthPx: number) {
    switch (element.type) {
        case "chart":
            return (
                <Suspense fallback={<Loading label="Loading chart" />}>
                    <ChartHost element={element as ChartElement} slideWidthPx={slideWidthPx} />
                </Suspense>
            );
        case "code":
            return (
                <Suspense fallback={<Loading label="Loading code" />}>
                    <CodeHost element={element as CodeElement} />
                </Suspense>
            );
        case "table":
            return (
                <Suspense fallback={<Loading label="Loading table" />}>
                    <TableHost element={element as TableElement} />
                </Suspense>
            );
        case "embed":
            return (
                <Suspense fallback={<Loading label="Loading embed" />}>
                    <EmbedHost element={element as EmbedElement} />
                </Suspense>
            );
        default:
            return undefined;
    }
}

