import { lazy, Suspense, type ComponentType } from "react";
import type { ChartElement } from "../../types";
import { useIsDarkSlide } from "../../../slide/slide-context";
import { PeerMissing } from "./peer-missing";

/**
 * fancy-echarts is an OPTIONAL peer. A static `import { EChart } from
 * "@particle-academy/fancy-echarts"` would make Rollup statically resolve the
 * peer when a CONSUMER builds — and blow up with MISSING_EXPORT if they never
 * installed it. So instead we load the peer via a DYNAMIC import and read its
 * members off the resolved module at RUNTIME, guarding for the stub case.
 *
 * The dynamic `import().then(m => …)` resolves to the optional-peer stub when
 * the peer is absent (`m.EChart` is `undefined`), which we detect and swap for
 * a placeholder — no build-time named binding to break.
 */
interface InnerProps {
    option: unknown;
    theme: string | undefined;
}

const ChartInner: ComponentType<InnerProps> = lazy(async () => {
    try {
        const mod: Record<string, unknown> = await import("@particle-academy/fancy-echarts");
        const EChart = mod.EChart as
            | ComponentType<{ option: unknown; theme?: string; style?: Record<string, string> }>
            | undefined;
        if (!EChart) {
            return { default: () => <PeerMissing label="Chart" install="npm i @particle-academy/fancy-echarts" /> };
        }
        // fancy-echarts ships its chart types as opt-in tree-shake-friendly
        // modules, so the consumer normally calls `registerAll()` somewhere
        // global. We wire it here, but only once the peer has actually loaded —
        // both calls are idempotent on echarts' side, so re-imports are safe.
        (mod.registerAll as (() => void) | undefined)?.();
        (mod.registerBuiltinThemes as (() => void) | undefined)?.();
        return {
            default: ({ option, theme }: InnerProps) => (
                <div style={{ width: "100%", height: "100%" }}>
                    {/* Fill the frame: fancy-echarts defaults to 400px tall, which ran
                        every chart out of a smaller frame and cut its axis. */}
                    <EChart option={option} theme={theme} style={{ width: "100%", height: "100%" }} />
                </div>
            ),
        };
    } catch {
        return { default: () => <PeerMissing label="Chart" install="npm i @particle-academy/fancy-echarts" /> };
    }
});

export default function ChartHost({ element }: { element: ChartElement; slideWidthPx: number }) {
    // Hooks stay in the OUTER component (Rules of Hooks); resolved values are
    // passed into the lazily-loaded inner. If the slide background reads as dark
    // and the chart doesn't pin a theme, fall back to echarts' built-in "dark".
    const isDarkSlide = useIsDarkSlide();
    const theme = element.chartTheme ?? (isDarkSlide ? "dark" : undefined);
    warnAboutUnplottableOption(element);
    return (
        <Suspense fallback={null}>
            <ChartInner option={slideChartOption(element.option)} theme={theme} />
        </Suspense>
    );
}

/**
 * The option as a slide chart lays out: ECharts' defaults are for a page, not
 * a frame on a slide. Its default grid keeps ~60px above and below the plot, so
 * a 160px frame was left a 40px plot with its axis labels piled up; and its
 * dark theme paints its own background where PowerPoint shows the slide. Both
 * are DEFAULTS only: an option that sets `grid` or `backgroundColor` keeps it.
 */
export function slideChartOption(option: unknown): unknown {
    if (typeof option !== "object" || option === null || Array.isArray(option)) return option;
    const o = option as Record<string, unknown>;
    const legend = o.legend !== undefined && o.legend !== null && (o.legend as { show?: unknown }).show !== false;
    const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

    // Every category label, as PowerPoint shows them; ECharts hides the ones it
    // guesses will collide, which dropped half the depots from a four-bar chart.
    const xAxis = isObj(o.xAxis) && (o.xAxis.type ?? "category") === "category"
        ? { ...o.xAxis, axisLabel: { interval: 0, ...(isObj(o.xAxis.axisLabel) ? o.xAxis.axisLabel : {}) } }
        : o.xAxis;

    // Values printed ABOVE a bar or point, as the deck writes them (outEnd / t);
    // ECharts' default puts a bar's value inside it.
    const series = Array.isArray(o.series)
        ? o.series.map((s) => {
              if (!isObj(s) || !isObj(s.label) || s.label.show !== true || s.label.position !== undefined) return s;
              return s.type === "bar" || s.type === "line" ? { ...s, label: { ...s.label, position: "top" } } : s;
          })
        : o.series;

    return {
        backgroundColor: "transparent",
        ...o,
        ...(xAxis === undefined ? {} : { xAxis }),
        ...(series === undefined ? {} : { series }),
        grid: o.grid ?? { top: o.title ? 32 : 12, right: 12, bottom: legend ? 28 : 8, left: 8, containLabel: true },
    };
}

const warned = new WeakSet<object>();

/**
 * An `option` that declares nothing to plot.
 *
 * ECharts draws an EMPTY CANVAS for an option it cannot make a chart from, at the
 * full size of the element, raising nothing. Same silent shape as a table row
 * matching no column (#14): the surface renders, the data does not, and nothing
 * says which. `dark-slide`'s published schema now describes the option surface so
 * an author can get this right; this is the other half, for one who did not.
 *
 * A `dataset` with no explicit `series` is a legitimate ECharts shape and is NOT
 * warned about -- a warning people learn to ignore is worse than none.
 *
 * Dev-only, and once per element rather than once per render: React renders the
 * same element repeatedly, twice per commit under StrictMode. Read NODE_ENV off
 * globalThis because this package ships to browsers, where `process` may not
 * exist; where it is absent we warn, because the silent blank canvas is the bug.
 */
function warnAboutUnplottableOption(element: ChartElement): void {
    const env = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env;
    if (env?.NODE_ENV === "production") return;
    if (warned.has(element)) return;

    const option: unknown = element.option;
    const isObject = typeof option === "object" && option !== null && !Array.isArray(option);
    const o = isObject ? (option as Record<string, unknown>) : null;
    const hasSeries = Array.isArray(o?.series) ? o.series.length > 0 : o?.series != null;
    if (hasSeries || o?.dataset != null) return;

    warned.add(element);
    console.warn(
        `[fancy-slides] chart "${element.id}": the option declares no \`series\`, so ECharts renders an ` +
            `empty canvas at the full size of the element with no error. Give \`series\` a list of points ` +
            `(\`[{ type: "bar", data: [1, 2] }]\`), or a \`dataset\`. The option surface a pptx export can ` +
            `also render is published in dark-slide's deck schema.`,
    );
}

import { lazy, Suspense, type ComponentType } from "react";
import type { CodeElement } from "../../types";
import { PeerMissing } from "./peer-missing";

/**
 * fancy-code is an OPTIONAL peer. As with chart-host, a static
 * `import { CodeEditor } from "@particle-academy/fancy-code"` would make
 * Rollup statically resolve the peer at CONSUMER build time and fail with
 * MISSING_EXPORT when it isn't installed. We load it via a DYNAMIC import and
 * read `CodeEditor` off the resolved module at RUNTIME, guarding the stub case.
 */
interface InnerProps {
    code: string;
    language: string;
    codeTheme: string;
    lineNumbers: boolean;
}

const CodeInner: ComponentType<InnerProps> = lazy(async () => {
    try {
        const mod: Record<string, unknown> = await import("@particle-academy/fancy-code");
        // CodeEditor is a component with a static `.Panel` sub-component.
        const CodeEditor = mod.CodeEditor as
            | (ComponentType<{
                  value: string;
                  language: string;
                  theme: string;
                  readOnly?: boolean;
                  lineNumbers?: boolean;
                  children?: React.ReactNode;
              }> & { Panel: ComponentType })
            | undefined;
        if (!CodeEditor) {
            return { default: () => <PeerMissing label="Code" install="npm i @particle-academy/fancy-code" /> };
        }
        return {
            default: ({ code, language, codeTheme, lineNumbers }: InnerProps) => (
                <div style={{ width: "100%", height: "100%", overflow: "hidden", borderRadius: 8 }}>
                    <CodeEditor value={code} language={language} theme={codeTheme} readOnly lineNumbers={lineNumbers}>
                        <CodeEditor.Panel />
                    </CodeEditor>
                </div>
            ),
        };
    } catch {
        return { default: () => <PeerMissing label="Code" install="npm i @particle-academy/fancy-code" /> };
    }
});

export default function CodeHost({ element }: { element: CodeElement }) {
    return (
        <Suspense fallback={null}>
            <CodeInner
                code={element.code}
                language={element.language ?? "javascript"}
                codeTheme={element.codeTheme ?? "dark"}
                lineNumbers={element.lineNumbers ?? true}
            />
        </Suspense>
    );
}

import { fontStack } from "../../utils/font-stack";
import type { CSSProperties } from "react";
import { Table } from "@particle-academy/react-fancy";
import type { TableColumn, TableElement, TableRow } from "../../types";
import { tableCells, unreadableTableRows } from "../../utils/table-rows";
import { resolveCell, type CellLook } from "../../utils/table-style";
import { useSlideContext } from "../../../slide/slide-context";

/**
 * `columns` and `rows` are REQUIRED on `TableElement`, and are still read
 * defensively here.
 *
 * The type only binds TypeScript consumers at compile time. This element also
 * arrives as plain JSON — from a database, an API, a saved deck, and above all
 * from an **agent**, which this package explicitly invites to author slides
 * through the MCP bridge. An agent emitting `{ type: "table" }` with no
 * `columns` is a predictable outcome, not an exotic one.
 *
 * Unguarded, `element.columns.map(...)` threw *during render*, so the failure was
 * not contained by the element: it unmounted whatever the consumer wrapped
 * `SlideViewer` in, and the error ("Cannot read properties of undefined (reading
 * 'map')") named none of this code. A malformed element must degrade to blank,
 * never take down the deck.
 *
 * Reported as #12.
 */
export default function TableHost({ element }: { element: TableElement }) {
    // `?? []` rather than loosening the type: the contract still REQUIRES both,
    // and making them optional would push this same guard onto every consumer.
    const context = useSlideContext();
    const theme = context?.theme;
    const columns: TableColumn[] = Array.isArray(element.columns) ? element.columns : [];
    const rows: TableRow[] = Array.isArray(element.rows) ? element.rows : [];

    // With no columns there is nothing to draw. An empty <Table> renders a stray
    // border, which reads as a styling bug rather than as absent data.
    if (columns.length === 0) return null;

    warnAboutUnreadableRows(element, columns, rows);

    const style = (element as { style?: Record<string, unknown> }).style;
    const hasHeader = style?.header !== false;
    // Sizes are design px on the deck canvas, scaled to the rendered slide the
    // way text is. Outside a Slide there is nothing to scale against.
    const scale = context ? context.slideWidthPx / (context.theme.slideWidth ?? 1920) : 1;
    const widths = columnWidths(columns);

    return (
        // Fits its frame; never a scroll box. A scroll box clipped the last row
        // behind a scrollbar on a slide, which has no way to scroll.
        <div style={{ width: "100%", height: "100%", overflow: "hidden" }}>
            <Table className="w-full">
                {hasHeader && (
                    <Table.Head>
                        <Table.Row>
                            {columns.map((c, i) => (
                                // `label ?? key`, as dark-slide's writer resolves it.
                                <Table.Cell key={c.key} header style={cellCss(resolveCell(element, theme, c, null, { header: true }), scale, widths[i], theme?.fonts?.body)}>
                                    {c.label ?? c.key}
                                </Table.Cell>
                            ))}
                        </Table.Row>
                    </Table.Head>
                )}
                <Table.Body>
                    {rows.map((row, r) => {
                        const cells = tableCells(row, columns);
                        return (
                            <Table.Row key={r}>
                                {columns.map((c, i) => {
                                    const look = resolveCell(element, theme, c, cells[c.key], { header: false, bodyIndex: r, row: Array.isArray(row) ? undefined : row });
                                    return (
                                        <Table.Cell key={c.key} style={cellCss(look, scale, hasHeader ? undefined : widths[i], theme?.fonts?.body)}>
                                            {look.text}
                                        </Table.Cell>
                                    );
                                })}
                            </Table.Row>
                        );
                    })}
                </Table.Body>
            </Table>
        </div>
    );
}

/** Column widths as percentages: fractions (all <= 1) or weights, as dark-slide reads them. */
function columnWidths(columns: TableColumn[]): (string | undefined)[] {
    const raw = columns.map((c) => (typeof (c as { width?: unknown }).width === "number" ? ((c as { width?: number }).width as number) : null));
    if (raw.every((w) => w === null)) return columns.map(() => undefined);
    const fractions = raw.every((w) => w === null || w <= 1);
    const declared = raw.filter((w): w is number => w !== null);
    const filled = fractions
        ? (() => {
              const rest = Math.max(0, 1 - declared.reduce((a, b) => a + b, 0));
              const open = raw.filter((w) => w === null).length;
              return raw.map((w) => w ?? (open > 0 ? rest / open : 0));
          })()
        : raw.map((w) => w ?? 1);
    const total = filled.reduce((a, b) => a + b, 0) || 1;
    return filled.map((w) => `${((w / total) * 100).toFixed(3)}%`);
}

function cellCss(look: CellLook, scale: number, width?: string, bodyFont?: string): CSSProperties {
    const border = look.border === null ? "none" : `${Math.max(1, look.borderWidth * scale)}px solid ${look.border}`;
    return {
        backgroundColor: look.fill ?? "transparent",
        color: look.color,
        fontWeight: look.bold ? 700 : 400,
        fontStyle: look.italic ? "italic" : "normal",
        textDecoration: look.underline ? "underline" : undefined,
        textAlign: look.align,
        verticalAlign: look.anchor,
        fontSize: `${look.fontSize * scale}px`,
        lineHeight: 1.25,
        fontFamily: fontStack(look.fontFamily ?? bodyFont),
        // PowerPoint's default cell insets: 7.2pt / 3.6pt = 19.2 / 9.6 design px.
        padding: `${9.6 * scale}px ${19.2 * scale}px`,
        border,
        width,
    };
}

const warned = new WeakSet<object>();

/**
 * The one unreadable shape left: an OBJECT row that matches no column key.
 *
 * A positional row is now read by order and a partially-filled row is ordinary,
 * so what remains is a row keyed by something no column reads — in practice a
 * mis-cased or renamed key. No rule can rescue it (`{"Plan": …}` is a perfectly
 * good object; nothing says which column it meant), and it fails the same silent
 * way: full-size grid, every cell empty. So the renderer says so.
 *
 * Dev-only, and once per element rather than once per render — React renders the
 * same element repeatedly, twice per commit under StrictMode, and a warning that
 * repeats is a warning people filter out. `dark-slide`'s `Agent.validate()`
 * reports the same row on the writer side, where an agent can act on it.
 */
function warnAboutUnreadableRows(element: TableElement, columns: TableColumn[], rows: TableRow[]): void {
    // Read off globalThis rather than `process.env` directly: this package ships to
    // browsers, where `process` may simply not exist and a bare reference throws.
    // Where NODE_ENV is absent we warn, because a silent blank grid is the defect.
    const env = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env;
    if (env?.NODE_ENV === "production") return;
    if (warned.has(element)) return;

    const keys = columns.map((c) => c.key);
    const unreadable = unreadableTableRows(rows, columns);

    if (unreadable.length === 0) return;
    warned.add(element);

    console.warn(
        `[fancy-slides] table "${element.id}": ${unreadable.length} of ${rows.length} rows match no column, ` +
            `so their cells render empty at full table size. Key each cell by a column key ` +
            `(${keys.join(", ")}), or give the row as a positional array in column order. ` +
            `Got: ${JSON.stringify(unreadable[0])}`,
    );
}

import type { EmbedElement } from "../../types";

export default function EmbedHost({ element }: { element: EmbedElement }) {
    return (
        <iframe
            src={element.src}
            title={element.title ?? "Embedded content"}
            sandbox={element.sandbox ?? "allow-scripts"}
            style={{ width: "100%", height: "100%", border: 0, display: "block" }}
        />
    );
}

import type { TableColumn, TableRow } from "../types";

/**
 * One table row's cells, keyed by column key.
 *
 * A row is canonically an object keyed by each column's `key`. A row given as an
 * ARRAY is POSITIONAL: its values are read in column order.
 *
 * The positional form used to resolve every cell to `undefined`, so the table drew
 * at the correct size with every cell blank — no exception, nothing logged,
 * because the geometry comes from `columns` and `rows.length` rather than from any
 * cell. It is also the shape an author guesses whenever the published schema shows
 * a column list and no row shape, which is what `dark-slide` published until
 * 0.10.4. Reported as #14, after reaching a customer as "the table rows were
 * empty".
 *
 * Surplus values have nowhere to go and are dropped; columns past the last value
 * read as empty, exactly as a missing key does. The matching rule lives in
 * `dark-slide`'s `TableResolver::cellMap` in all three writer engines, and is
 * pinned cross-language by `fancy-conformance` rows 0029–0033.
 *
 * It lives here rather than in the renderer because the EDITOR needs the identical
 * rule — two readings of one row is how a deck renders one way and edits another.
 */
export function tableCells(row: TableRow, columns: TableColumn[]): Record<string, unknown> {
    // A row can itself be null in hand-written JSON.
    if (!row) return {};
    if (!Array.isArray(row)) return row;

    const cells: Record<string, unknown> = {};
    row.forEach((value, i) => {
        const column = columns[i];
        if (column) cells[column.key] = value;
    });

    return cells;
}

/**
 * Every row in the canonical keyed form.
 *
 * Use it before EDITING: an editor that patches a positional row by key would
 * write a cell the renderer then reads from a different place. Converting on the
 * way in means a deck authored positionally is saved back keyed, which is the form
 * that survives a column reorder.
 */
export function tableRowsAsRecords(rows: TableRow[], columns: TableColumn[]): Record<string, unknown>[] {
    return (Array.isArray(rows) ? rows : []).map((row) => tableCells(row, columns));
}

/**
 * The rows no rule can rescue: OBJECT rows that match no column key.
 *
 * A positional row is read by order and a partially-filled row is ordinary, so
 * what remains is a row keyed by something no column reads — in practice a
 * mis-cased or renamed key. Nothing says which column `{"Plan": …}` meant, and it
 * fails the same silent way: full-size grid, every cell empty.
 */
export function unreadableTableRows(rows: TableRow[], columns: TableColumn[]): TableRow[] {
    const keys = columns.map((c) => c.key);

    return (Array.isArray(rows) ? rows : []).filter((row) => {
        if (!row || Array.isArray(row)) return false;
        const rowKeys = Object.keys(row);
        return rowKeys.length > 0 && !rowKeys.some((k) => keys.includes(k));
    });
}

import type { TableColumn, TableElement, Theme } from "../types";

/**
 * A table cell's look, resolved the way dark-slide's `TableResolver` resolves it,
 * so a deck draws here as it prints:
 *
 *     cell > row > column > band (header | stripe | body) > table > theme > default
 *
 * An ABSENT key falls through to the next layer; `false` stops the chain and
 * means off (no fill, no borders). Lengths are design pixels on the deck canvas
 * (`theme.slideWidth`, 1920 by default) and are scaled by the caller.
 *
 * Kept to what a viewer draws: fill, text colour, weight, slant, underline,
 * alignment, vertical anchor, size, face and borders.
 */
export interface CellLook {
    text: string;
    fill: string | null;
    color: string;
    bold: boolean;
    italic: boolean;
    underline: boolean;
    align: "left" | "center" | "right" | "justify";
    anchor: "top" | "middle" | "bottom";
    fontSize: number;
    fontFamily: string | null;
    /** A border colour, or null for none. One rule for all four sides. */
    border: string | null;
    /** The border width, design px (0.75pt default = 2px on the 1920 canvas). */
    borderWidth: number;
}

const STYLE_KEYS = ["fill", "color", "bold", "italic", "underline", "align", "anchor", "fontSize", "fontFamily", "borders"] as const;

export const DEFAULT_FONT_SIZE = 28;
const DEFAULT_BODY_COLOR = "#0F172A";
const DEFAULT_HEADER_COLOR = "#FFFFFF";
const DEFAULT_ACCENT = "#8B5CF6";
const DEFAULT_STRIPE_FILL = "#F8FAFC";
const DEFAULT_BORDER_COLOR = "#D9DEE4";
/** 0.75pt on a 720pt slide, in design px on the 1920 canvas. */
const DEFAULT_BORDER_PX = 2;

type Layer = Record<string, unknown>;

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

function styleKeys(source: unknown): Layer {
    const out: Layer = {};
    if (!isObject(source)) return out;
    for (const k of STYLE_KEYS) {
        if (k in source && source[k] !== null && source[k] !== undefined) out[k] = source[k];
    }
    return out;
}

function themeColor(theme: Theme | undefined, key: "text" | "accent" | "surface" | "background", fallback: string): string {
    const v = theme?.colors?.[key];
    return typeof v === "string" && v !== "" ? v : fallback;
}

function hex6(color: string): string | null {
    const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(color.trim());
    if (!m) return null;
    const h = m[1]!;
    return (h.length === 3 ? h.split("").map((c) => c + c).join("") : h).toUpperCase();
}

/** The stripe band dark-slide draws: theme surface; on a dark theme, background 8% toward text; else light. */
function stripeDefault(theme: Theme | undefined): string {
    const surface = theme?.colors?.surface;
    if (typeof surface === "string" && surface !== "") return surface;
    const bg = hex6(themeColor(theme, "background", "#FFFFFF")) ?? "FFFFFF";
    const lum = (299 * parseInt(bg.slice(0, 2), 16) + 587 * parseInt(bg.slice(2, 4), 16) + 114 * parseInt(bg.slice(4, 6), 16)) / 255000;
    if (lum >= 0.5) return DEFAULT_STRIPE_FILL;
    const text = hex6(themeColor(theme, "text", "#F9FAFB")) ?? "F9FAFB";
    let out = "#";
    for (const i of [0, 2, 4]) {
        const x = parseInt(bg.slice(i, i + 2), 16);
        const y = parseInt(text.slice(i, i + 2), 16);
        out += (x + Math.trunc(((y - x) * 8) / 100)).toString(16).toUpperCase().padStart(2, "0");
    }
    return out;
}

/** A cell value: a string/number, or an object carrying `text` and its own style keys. */
export function cellSpec(value: unknown): Layer & { text: string } {
    if (isObject(value) && ("text" in value || STYLE_KEYS.some((k) => k in value))) {
        return { ...styleKeys(value), text: value.text == null ? "" : String(value.text) };
    }
    if (value == null) return { text: "" };
    if (typeof value === "object") return { text: JSON.stringify(value) };
    return { text: String(value) };
}

/**
 * Resolve one cell. `bodyIndex` counts body rows from 0 (the header is not one);
 * striping applies to odd body rows, as dark-slide stripes them.
 */
export function resolveCell(
    element: TableElement,
    theme: Theme | undefined,
    column: TableColumn,
    value: unknown,
    position: { header: true } | { header: false; bodyIndex: number; row?: unknown },
): CellLook {
    const style: Layer = isObject((element as { style?: unknown }).style) ? ((element as { style?: unknown }).style as Layer) : {};

    const defaults: Layer = { color: themeColor(theme, "text", DEFAULT_BODY_COLOR), align: "left", anchor: "middle", fontSize: DEFAULT_FONT_SIZE };
    let band: Layer = {};
    if (position.header) {
        band = { fill: themeColor(theme, "accent", DEFAULT_ACCENT), color: DEFAULT_HEADER_COLOR, bold: true, ...(isObject(style.header) ? styleKeys(style.header) : {}) };
    } else {
        band = isObject(style.body) ? styleKeys(style.body) : {};
        if (style.stripe !== false && position.bodyIndex % 2 === 1) {
            band = { ...band, fill: stripeDefault(theme), ...(isObject(style.stripe) ? styleKeys(style.stripe) : {}) };
        }
    }
    const spec = position.header ? { text: column.label ?? column.key } : cellSpec(value);
    const rowLayer = position.header ? {} : styleKeys(position.row);
    const layers: Layer[] = [defaults, styleKeys(style), band, styleKeys(column), rowLayer, spec];

    const r: Layer = {};
    let border: string | null = DEFAULT_BORDER_COLOR;
    let borderWidth = DEFAULT_BORDER_PX;
    for (const layer of layers) {
        for (const [k, v] of Object.entries(layer)) {
            if (k === "borders") {
                if (v === false || v === "none") {
                    border = null;
                } else if (isObject(v)) {
                    const all = isObject(v.all) ? v.all : v;
                    if (typeof all.color === "string") border = all.color;
                    if (typeof all.width === "number") borderWidth = all.width;
                }
                continue;
            }
            if (k !== "text") r[k] = v;
        }
    }

    const fill = r.fill;
    const align = r.align === "center" || r.align === "centre" ? "center" : r.align === "right" ? "right" : r.align === "justify" ? "justify" : "left";
    const anchor = r.anchor === "top" ? "top" : r.anchor === "bottom" ? "bottom" : "middle";
    return {
        text: spec.text,
        fill: fill === false || fill === "none" || fill == null ? null : String(fill),
        color: String(r.color),
        bold: r.bold === true,
        italic: r.italic === true,
        underline: r.underline === true,
        align,
        anchor,
        fontSize: typeof r.fontSize === "number" ? r.fontSize : Number(r.fontSize) || DEFAULT_FONT_SIZE,
        fontFamily: typeof r.fontFamily === "string" ? r.fontFamily : null,
        border,
        borderWidth,
    };
}

import { forwardRef, useId } from "react";
import { cn } from "../lib/utils/cn";
import { useControllableState } from "../lib/hooks/use-controllable-state";
import { Field } from "../field";
import { useFieldMode } from "../lib/components/inputs/mode/FieldMode.context";
import { DisplayValue } from "../lib/components/inputs/mode/DisplayValue";
import { useInlineEdit } from "../lib/components/inputs/mode/useInlineEdit";
import { dirtyRingClasses } from "../lib/components/inputs/inputs.utils";
import type { SliderProps } from "./Slider.types";

export const Slider = forwardRef<HTMLInputElement, SliderProps>(
  (props, ref) => {
    const {
      size = "md",
      dirty,
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      name,
      min = 0,
      max = 100,
      step = 1,
      showValue,
      marks,
    } = props;

    const autoId = useId();
    const sliderId = id ?? autoId;

    if (props.range) {
      return (
        <RangeSlider
          {...props}
          id={sliderId}
          ref={ref}
        />
      );
    }

    return (
      <SingleSlider
        {...props}
        range={false}
        id={sliderId}
        ref={ref}
      />
    );
  },
);

Slider.displayName = "Slider";

const SingleSlider = forwardRef<HTMLInputElement, SliderProps & { range?: false }>(
  (
    {
      size = "md",
      dirty,
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      name,
      min = 0,
      max = 100,
      step = 1,
      showValue,
      marks,
      prefix,
      suffix,
      mode,
      ...rest
    },
    ref,
  ) => {
    const singleProps = rest as { value?: number; defaultValue?: number; onValueChange?: (v: number) => void };
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
    const [value, setValue] = useControllableState(
      singleProps.value,
      singleProps.defaultValue ?? min,
      singleProps.onValueChange,
    );

    const slider = !showControl ? (
      <DisplayValue
        size={size}
        className={className}
        interactive={interactive}
        onActivate={enterEdit}
      >
        {`${prefix ?? ""}${value}${suffix ?? ""}`}
      </DisplayValue>
    ) : (
      <div data-react-fancy-slider="" className={cn("flex flex-col gap-1", className)}>
        <div className="flex items-center gap-3">
          <input
            ref={ref}
            id={id}
            type="range"
            name={name}
            min={min}
            max={max}
            step={step}
            value={value}
            disabled={disabled}
            autoFocus={interactive}
            onBlur={() => {
              if (interactive) exitEdit();
            }}
            onChange={(e) => setValue(Number(e.target.value))}
            className={cn(
              "w-full cursor-pointer accent-blue-600 disabled:cursor-not-allowed disabled:opacity-50",
              dirtyRingClasses(dirty),
              {
                xs: "h-1",
                sm: "h-1.5",
                md: "h-2",
                lg: "h-2.5",
                xl: "h-3",
              }[size],
            )}
          />
          {showValue && (
            <span className="min-w-[3ch] shrink-0 whitespace-nowrap text-right text-sm font-medium text-zinc-700 dark:text-zinc-300">
              {prefix}{value}{suffix}
            </span>
          )}
        </div>
        {marks && marks.length > 0 && <SliderMarks marks={marks} min={min} max={max} />}
      </div>
    );

    if (label || error || description) {
      return (
        <Field label={label} labelHidden={labelHidden} description={description} error={error} required={required} htmlFor={id} size={size}>
          {slider}
        </Field>
      );
    }

    return slider;
  },
);

SingleSlider.displayName = "SingleSlider";

const RangeSlider = forwardRef<HTMLInputElement, SliderProps & { range: true }>(
  (
    {
      size = "md",
      dirty,
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      name,
      min = 0,
      max = 100,
      step = 1,
      showValue,
      marks,
      prefix,
      suffix,
      mode,
      ...rest
    },
    ref,
  ) => {
    const rangeProps = rest as { value?: [number, number]; defaultValue?: [number, number]; onValueChange?: (v: [number, number]) => void };
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
    const [value, setValue] = useControllableState(
      rangeProps.value,
      rangeProps.defaultValue ?? [min, max] as [number, number],
      rangeProps.onValueChange,
    );

    const handleMin = (n: number) => {
      setValue([Math.min(n, value[1]), value[1]]);
    };

    const handleMax = (n: number) => {
      setValue([value[0], Math.max(n, value[0])]);
    };

    const leftPercent = ((value[0] - min) / (max - min)) * 100;
    const rightPercent = ((value[1] - min) / (max - min)) * 100;

    const slider = !showControl ? (
      <DisplayValue
        size={size}
        className={className}
        interactive={interactive}
        onActivate={enterEdit}
      >
        {`${prefix ?? ""}${value[0]}${suffix ?? ""}–${prefix ?? ""}${value[1]}${suffix ?? ""}`}
      </DisplayValue>
    ) : (
      <div
        data-react-fancy-slider=""
        className={cn("flex flex-col gap-1", className)}
        onBlur={(e) => {
          if (interactive && !e.currentTarget.contains(e.relatedTarget as Node)) exitEdit();
        }}
      >
        <div className="flex items-center gap-3">
          <div className="relative w-full">
            <div className="pointer-events-none absolute top-1/2 h-1.5 w-full -translate-y-1/2 rounded-full bg-zinc-200 dark:bg-zinc-700" />
            <div
              className="pointer-events-none absolute top-1/2 h-1.5 -translate-y-1/2 rounded-full bg-blue-500"
              style={{ left: `${leftPercent}%`, width: `${rightPercent - leftPercent}%` }}
            />
            <input
              ref={ref}
              type="range"
              min={min}
              max={max}
              step={step}
              value={value[0]}
              disabled={disabled}
              autoFocus={interactive}
              onChange={(e) => handleMin(Number(e.target.value))}
              className={cn(
                "pointer-events-none absolute w-full cursor-pointer appearance-none bg-transparent [&::-webkit-slider-thumb]:pointer-events-auto [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-blue-600 [&::-webkit-slider-thumb]:shadow",
                dirtyRingClasses(dirty),
              )}
            />
            <input
              type="range"
              min={min}
              max={max}
              step={step}
              value={value[1]}
              disabled={disabled}
              onChange={(e) => handleMax(Number(e.target.value))}
              className="pointer-events-none absolute w-full cursor-pointer appearance-none bg-transparent [&::-webkit-slider-thumb]:pointer-events-auto [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-blue-600 [&::-webkit-slider-thumb]:shadow"
            />
            <div className="h-6" />
          </div>
          {showValue && (
            <span className="min-w-[6ch] shrink-0 whitespace-nowrap text-right text-sm font-medium text-zinc-700 dark:text-zinc-300">
              {prefix}{value[0]}{suffix}–{prefix}{value[1]}{suffix}
            </span>
          )}
        </div>
        {marks && marks.length > 0 && <SliderMarks marks={marks} min={min} max={max} />}
      </div>
    );

    if (label || error || description) {
      return (
        <Field label={label} labelHidden={labelHidden} description={description} error={error} required={required} htmlFor={id} size={size}>
          {slider}
        </Field>
      );
    }

    return slider;
  },
);

RangeSlider.displayName = "RangeSlider";

function SliderMarks({
  marks,
  min,
  max,
}: {
  marks: { value: number; label?: string }[];
  min: number;
  max: number;
}) {
  return (
    <div className="relative h-5 w-full">
      {marks.map((mark) => {
        const percent = ((mark.value - min) / (max - min)) * 100;
        return (
          <span
            key={mark.value}
            className="absolute -translate-x-1/2 text-xs text-zinc-500 dark:text-zinc-400"
            style={{ left: `${percent}%` }}
          >
            {mark.label ?? mark.value}
          </span>
        );
      })}
    </div>
  );
}

import type { ReactNode } from "react";
import type { InputBaseProps } from "../lib/components/inputs/inputs.types";

interface SliderBaseProps extends InputBaseProps {
  min?: number;
  max?: number;
  step?: number;
  showValue?: boolean;
  marks?: { value: number; label?: string }[];
  prefix?: ReactNode;
  suffix?: ReactNode;
