export interface ChatTranscriptProps {
    history: ChatEntry[];
    agentName: string;
    /** Renders the working indicator while a turn is in flight. */
    thinking?: boolean;
    /** Replaces the default empty state. */
    emptyState?: React.ReactNode;
}

/**
 * The conversation.
 *
 * Renders `display` in preference to `content`: the latter is what the model
 * was sent, with extracted file text folded in, and showing it would paste a
 * whole handbook back at the teacher.
 */
export function ChatTranscript({ history, agentName, thinking, emptyState }: ChatTranscriptProps) {
    const endRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        endRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }, [history.length, thinking]);

    if (history.length === 0 && !thinking) {
        return (
            <div className="flex flex-1 items-center justify-center px-6 py-12 text-center">
                {emptyState ?? (
                    <div className="max-w-md">
                        <Text className="!text-sm !text-secondary-600">
                            Describe the course you want, or attach the material to build it from —
                            a handbook, a slide deck, a question bank.
                        </Text>
                        <Text className="!text-xs !text-secondary-500 !mt-3">
                            {agentName} drafts changes for you to review. It cannot save anything itself.
                        </Text>
                    </div>
                )}
            </div>
        );
    }

    return (
        <div className="flex-1 overflow-y-auto px-4 py-4 grid gap-4 content-start">
            {history.map((entry, i) => (
                <Bubble key={i} entry={entry} agentName={agentName} />
            ))}

            {thinking && (
                <div className="flex gap-3">
                    <Who label={agentName} />
                    <div className="rounded-lg bg-secondary-100 px-3 py-2">
                        <span className="inline-flex gap-1" aria-label={`${agentName} is working`}>
                            <Dot delay="0ms" />
                            <Dot delay="150ms" />
                            <Dot delay="300ms" />
                        </span>
                    </div>
                </div>
            )}

            <div ref={endRef} />
        </div>
    );
}

function Bubble({ entry, agentName }: { entry: ChatEntry; agentName: string }) {
    const mine = entry.role === 'user';
    const body = entry.display || entry.content || '';

    return (
        <div className={`flex gap-3 ${mine ? 'flex-row-reverse' : ''}`}>
            <Who label={mine ? 'You' : agentName} />
            <div className={`max-w-[46rem] ${mine ? 'text-right' : ''}`}>
                <div
                    className={`inline-block rounded-lg px-3 py-2 text-left break-words text-sm ${
                        mine
                            ? 'bg-brand text-white whitespace-pre-wrap'
                            : 'bg-secondary-100 text-secondary-900'
                    }`}
                >
                    {mine ? (
                        // The teacher's own words, verbatim. Rendering these as
                        // markdown would silently reformat what they typed.
                        body
                    ) : (
                        // Model output is markdown, and it is not trusted input —
                        // it can carry whatever an uploaded file talked it into
                        // writing. ContentRenderer sanitizes by default; never
                        // pass `unsafe` here.
                        <ContentRenderer value={body} format="markdown" className={PROSE} />
                    )}
                </div>
                {entry.files && entry.files.length > 0 && (
                    <div className={`mt-1.5 flex flex-wrap gap-1.5 ${mine ? 'justify-end' : ''}`}>
                        {entry.files.map((name) => (
                            <Badge key={name} color="gray" variant="soft" size="sm">
                                {name}
                            </Badge>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

function Who({ label }: { label: string }) {
    return (
        <div className="shrink-0 pt-1">
            <span className="text-[10px] font-semibold uppercase tracking-wide text-secondary-500">
                {label}
            </span>
        </div>
    );
}

function Dot({ delay }: { delay: string }) {
    return (
        <span
            className="h-1.5 w-1.5 rounded-full bg-secondary-400 animate-bounce"
            style={{ animationDelay: delay }}
        />
    );
}

import { Badge, Button, Text, type Color } from '@particle-academy/react-fancy';
import { useRef, useState } from 'react';

const ACCEPT = '.pdf,.png,.jpg,.jpeg,.gif,.webp,.docx,.xlsx,.csv,.txt,.pptx';

export interface MessageComposerProps {
    onSend: (message: string, files: File[], reset: () => void) => void;
    agentName: string;
    /** Blocks input — in flight, or no model configured. */
    disabled?: boolean;
    /** Spins the send button. Distinct from `disabled` on purpose. */
    busy?: boolean;
    accept?: string;
    maxFiles?: number;
    hint?: React.ReactNode;
    /** react-fancy Button colour for the send action. */
    color?: Color;
}

/**
 * Message box with file drop.
 *
 * Named to avoid colliding with react-fancy's own `Composer`, and hand-rolled
 * rather than using its `PromptInput` because that component maps dropped
 * files to `{id, name, bytes}` and discards the File — so the chip renders but
 * the upload can never happen. Reported upstream; switch to it once the
 * attachment carries the file.
 *
 * Attachments are held here until send, so a mistaken drop can be removed
 * before it costs a model call.
 */
export function MessageComposer({
    onSend,
    agentName,
    disabled,
    busy,
    accept = ACCEPT,
    maxFiles = 10,
    hint,
    color = 'red',
}: MessageComposerProps) {
    const [message, setMessage] = useState('');
    const [files, setFiles] = useState<File[]>([]);
    const [dragging, setDragging] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);

    function addFiles(list: FileList | null) {
        const incoming = Array.from(list ?? []);
        if (incoming.length === 0) return;

        setFiles((current) => {
            // De-dupe by name+size so dropping the same file twice does not
            // send it twice and pay for it twice.
            const seen = new Set(current.map((f) => `${f.name}:${f.size}`));
            return [...current, ...incoming.filter((f) => !seen.has(`${f.name}:${f.size}`))].slice(
                0,
                maxFiles,
            );
        });
    }

    function submit(e: React.FormEvent | React.KeyboardEvent) {
        e.preventDefault();
        if (disabled || message.trim() === '') return;

        onSend(message.trim(), files, () => {
            setMessage('');
            setFiles([]);
            if (inputRef.current) inputRef.current.value = '';
        });
    }

    function onKeyDown(e: React.KeyboardEvent) {
        // Enter sends, Shift+Enter breaks the line — the convention everywhere
        // else, and course descriptions are multi-line often enough to matter.
        if (e.key === 'Enter' && !e.shiftKey) submit(e);
    }

    return (
        <form
            onSubmit={submit}
            onDragOver={(e) => {
                e.preventDefault();
                setDragging(true);
            }}
            onDragLeave={() => setDragging(false)}
            onDrop={(e) => {
                e.preventDefault();
                setDragging(false);
                addFiles(e.dataTransfer.files);
            }}
            className={`border-t px-4 py-3 transition ${
                dragging ? 'border-brand bg-primary-50 dark:bg-primary-950' : 'border-secondary-200 bg-white dark:bg-zinc-900'
            }`}
        >
            {files.length > 0 && (
                <div className="mb-2 flex flex-wrap gap-1.5">
                    {files.map((file, i) => (
                        <span key={`${file.name}:${i}`} className="inline-flex items-center gap-1">
                            <Badge color="blue" variant="soft" size="sm">
                                {file.name} · {Math.max(1, Math.round(file.size / 1024))} KB
                            </Badge>
                            <button
                                type="button"
                                onClick={() => setFiles((c) => c.filter((_, j) => j !== i))}
                                className="text-xs text-secondary-500 hover:text-primary-600"
                                aria-label={`Remove ${file.name}`}
                            >
                                ×
                            </button>
                        </span>
                    ))}
                </div>
            )}

            <div className="flex items-end gap-2">
                <button
                    type="button"
                    onClick={() => inputRef.current?.click()}
                    className="shrink-0 rounded-md border border-secondary-300 px-3 py-2 text-sm text-secondary-700 hover:bg-secondary-50"
                    title="Attach course material"
                >
                    Attach
                </button>
                <input
                    ref={inputRef}
                    type="file"
                    multiple
                    accept={accept}
                    className="hidden"
                    onChange={(e) => addFiles(e.target.files)}
                />

                <textarea
                    rows={2}
                    value={message}
                    disabled={disabled}
                    onChange={(e) => setMessage(e.target.value)}
                    onKeyDown={onKeyDown}
                    placeholder={`Ask ${agentName} to draft or update course material…`}
                    className="flex-1 resize-none rounded-md border border-secondary-300 px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/15 disabled:bg-secondary-50"
                />

                <Button
                    type="submit"
                    // Colour comes from the PROP, not a forced `!bg-brand`
                    // class. That token is defined by some hosts and not
                    // others, so forcing it renders an unstyled grey slab
                    // wherever it is absent — with no error to trace.
                    color={color}
                    // Only `busy`, never `disabled` — the box is also disabled
                    // when no model is configured, and a permanent spinner reads
                    // as "working" when nothing is happening at all.
                    loading={busy}
                    disabled={disabled || message.trim() === ''}
                    className="!font-semibold"
                >
                    Send
                </Button>
            </div>

            <Text className="!text-[11px] !text-secondary-500 !mt-1.5">
                {hint ?? (
                    <>
                        PDF and images are read directly; Word, Excel, PowerPoint and CSV are converted
                        to text first. Drop files anywhere on this box.
                    </>
                )}
            </Text>
        </form>
    );
}

import { Badge, Button, Heading, Text, type Color } from '@particle-academy/react-fancy';
import { useState } from 'react';
import type { ChangeAction, ChangePlan } from '../lib/types';

const ACTION_COLOR: Record<ChangeAction, Color> = {
    create: 'green',
    update: 'blue',
    delete: 'red',
};

export interface PlanReviewProps {
    plan?: ChangePlan | null;
    onApply: () => void;
    onDiscard: () => void;
    busy?: boolean;
    /** Shown in the footer. Set to null to drop the note entirely. */
    draftNote?: React.ReactNode;
    /** react-fancy Button colour for the apply action. */
    color?: Color;
}

/** Scalar values short enough to read inline, which is where they belong. */
function inlineFields(attributes: Record<string, unknown>): [string, string][] {
    return Object.entries(attributes)
        .filter(([, v]) => v !== null && typeof v !== 'object')
        .map(([k, v]) => [k, String(v)] as [string, string])
        .filter(([, v]) => v.length <= 60);
}

/**
 * The approval surface — the only place a proposal becomes rows.
 *
 * Every operation is inspectable before anything is written, raw attributes
 * included. A reviewer who cannot see what they are approving is not really
 * approving it, and "Apply" on an opaque list is just a slower yes.
 *
 * ---------------------------------------------------------------------------
 * That paragraph was true of the intent and false of the behaviour
 * ---------------------------------------------------------------------------
 *
 * Attributes WERE all rendered — behind a click, one operation at a time, with
 * the Apply button available from the start. So a reviewer saw
 * "Radio Discipline Check — a quiz on callsigns · 5 fields" and could approve it
 * without ever seeing `passing_score: 0`, which is the single attribute deciding
 * whether that certification exam means anything.
 *
 * It mattered because these proposals come from a model, and Teachers Aid extracts
 * uploaded course material into the turn. `passing_score` is a legitimate,
 * model-controlled field: nothing is bypassed when an injected instruction proposes
 * zero. The tool is working as designed and **the review IS the control.** A
 * control that requires a click nobody is prompted to make is not one.
 *
 * So scalar attributes now render inline on every row, always. Expansion is for
 * long text and nested objects only, and several rows can be open at once —
 * reviewing a twelve-operation plan through a one-at-a-time accordion is twelve
 * clicks and no way to compare two rows, which is its own pressure to skip.
 *
 * Raised by a consumer who went looking for a mass-assignment hole in the PHP
 * side, did not find one, and asked the better question: what can an admin
 * actually see at the moment they commit?
 */
export function PlanReview({ plan, onApply, onDiscard, busy, draftNote, color = 'red' }: PlanReviewProps) {
    const [expanded, setExpanded] = useState<ReadonlySet<number>>(new Set());

    if (!plan || !plan.operations?.length) return null;

    const summary = Object.entries(plan.summary ?? {})
        .map(([key, count]) => `${count} × ${key.replace('_', ' ')}`)
        .join(' · ');

    return (
        <section className="rounded-lg border border-amber-300 bg-amber-50/60 overflow-hidden">
            <header className="flex flex-wrap items-center justify-between gap-3 border-b border-amber-200 bg-amber-100/60 px-4 py-3">
                <div>
                    <Heading as="h2" size="sm" weight="semibold" className="!text-sm">
                        Proposed changes — nothing has been saved yet
                    </Heading>
                    {summary && <Text className="!text-xs !text-secondary-600 !mt-0.5">{summary}</Text>}
                </div>
                <div className="flex gap-2">
                    <Button
                        onClick={onDiscard}
                        disabled={busy}
                        className="!border !border-secondary-300 !bg-white dark:!bg-zinc-900 !text-secondary-700 !text-sm !px-3 !py-1.5 !rounded-md"
                    >
                        Discard
                    </Button>
                    <Button
                        onClick={onApply}
                        // See MessageComposer: colour is a prop, never a forced
                        // `!bg-brand` class the host may not define.
                        color={color}
                        loading={busy}
                        disabled={busy}
                        className="!font-semibold !text-sm"
                    >
                        Apply {plan.count} change{plan.count === 1 ? '' : 's'}
                    </Button>
                </div>
            </header>

            <ol className="divide-y divide-amber-200">
                {plan.operations.map((op, i) => {
                    const open = expanded.has(i);
                    const attributes = Object.entries(op.attributes ?? {});
                    const inline = inlineFields(op.attributes ?? {});
                    const rest = attributes.length - inline.length;

                    return (
                        <li key={i} className="px-4 py-3">
                            <button
                                type="button"
                                onClick={() =>
                                    setExpanded((prev) => {
                                        const next = new Set(prev);
                                        if (!next.delete(i)) next.add(i);
                                        return next;
                                    })
                                }
                                className="flex w-full items-start gap-3 text-left"
                                aria-expanded={open}
                            >
                                <Badge color={ACTION_COLOR[op.action] ?? 'gray'} variant="soft" size="sm">
                                    {op.action}
                                </Badge>
                                <span className="flex-1">
                                    <Text className="!text-sm !font-medium">{op.description}</Text>

                                    {/*
                                     * Inline, always, and NOT behind the toggle. This is the
                                     * difference between a review and a slower yes -- see the
                                     * component docblock for the `passing_score: 0` case.
                                     */}
                                    {inline.length > 0 && (
                                        <span
                                            className="mt-1 flex flex-wrap gap-x-3 gap-y-1"
                                            data-plan-op-fields={i}
                                        >
                                            {inline.map(([key, value]) => (
                                                <span key={key} className="text-xs text-secondary-600">
                                                    <span className="font-medium uppercase tracking-wide text-secondary-500">
                                                        {key}
                                                    </span>{' '}
                                                    <span className="text-secondary-800">{value}</span>
                                                </span>
                                            ))}
                                        </span>
                                    )}

                                    {op.ref && (
                                        <Text className="!text-xs !text-secondary-500 !mt-0.5">
                                            referenced later as ${op.ref}
                                        </Text>
                                    )}
                                </span>
                                <span className="text-xs text-secondary-500 shrink-0">
                                    {open
                                        ? 'Hide'
                                        : rest > 0
                                          ? `${rest} more field${rest === 1 ? '' : 's'}`
                                          : 'Details'}
                                </span>
                            </button>

                            {open && (
                                <dl className="mt-3 grid gap-2 rounded-md bg-white/70 dark:bg-zinc-900/70 p-3 text-sm">
                                    {attributes.map(([key, value]) => (
                                        <div key={key} className="grid sm:grid-cols-[10rem_1fr] gap-1 sm:gap-3">
                                            <dt className="text-xs font-medium uppercase tracking-wide text-secondary-500">
                                                {key}
                                            </dt>
                                            <dd className="whitespace-pre-wrap break-words text-secondary-800">
                                                {value !== null && typeof value === 'object'
                                                    ? JSON.stringify(value, null, 2)
                                                    : String(value)}
                                            </dd>
                                        </div>
                                    ))}
                                </dl>
                            )}
                        </li>
                    );
                })}
            </ol>

            {draftNote !== null && (
                <footer className="border-t border-amber-200 px-4 py-2">
                    <Text className="!text-xs !text-secondary-600">
                        {draftNote ?? (
                            <>
                                Applied changes are saved as <strong>drafts</strong>. Publishing stays a
                                separate, deliberate step.
                            </>
                        )}
                    </Text>
                </footer>
            )}
        </section>
    );
}

/**
 * The shapes this UX renders. They mirror what particle-academy/teachers-aid
 * serialises, but nothing here imports it — the package is a view over plain
 * JSON, so a host on any backend can feed it.
 */

export type ChangeAction = 'create' | 'update' | 'delete';

/** One proposed change. Inert until a human applies the plan it belongs to. */
export interface ChangeOperation {
    action: ChangeAction;
    entity: string;
    /** Human-readable one-liner for the review list. */
    description: string;
    attributes?: Record<string, unknown>;
    /** Present on updates and deletes. */
    id?: number;
    /**
     * Name this operation's new record is referred to by later in the same
     * plan, e.g. a lesson pointing at `$c1` before the course has an id.
     */
    ref?: string;
}

export interface ChangePlan {
    operations: ChangeOperation[];
    /** Counts keyed by "action entity", e.g. `{"create lesson": 3}`. */
    summary?: Record<string, number>;
    count: number;
}

export interface ChatEntry {
    role: 'user' | 'assistant';
    /**
     * What to show. Distinct from what the model was sent, which has extracted
     * file text folded into it — rendering that would paste a whole handbook
     * back at the teacher.
     */
    display?: string;
    content?: string;
    /** Names of files attached to this turn. */
    files?: string[];
}

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from "react";
import { useTerminal } from "../lib/hooks/use-terminal";
import { ShellSwitcher } from "./ShellSwitcher";
import { TerminalContextMenu } from "./TerminalContextMenu";
import { diffOutput } from "../lib/output-diff";
import { decideShellSelect } from "../lib/shell-select";
import { providerWrite, resolveClipboard } from "../lib/clipboard";
import { resolveMenuItems, type TerminalContextMenuContext, type TerminalContextMenuItem } from "../lib/context-menu";
import { nextSelectionSnapshot } from "../lib/selection-snapshot";
import type { TerminalHandle, TerminalProps } from "../lib/types";

/**
 * Human+ `<Terminal>` — a controlled, themeable xterm.js terminal.
 *
 * - **Authoring surface:** terse, controlled (`output` + `onData`), JSON-friendly
 *   props (rows/cols, theme tokens, initial buffer), a stable `data-fancy-terminal`
 *   handle, and a ref exposing {@link TerminalHandle} (write/clear/fit/getBuffer/…).
 * - **Inhabited surface:** the same handle is what an MCP bridge drives, so an
 *   embedded agent reads the buffer + writes input without DOM-scraping.
 *
 * The parent must have a height — the terminal fits its container (like any xterm
 * surface); a 0-height parent collapses it.
 *
 * ```tsx
 * const [out, setOut] = useState("");
 * <div style={{ height: 360 }}>
 *   <Terminal output={out} onData={(d) => backend.send(d)} />
 * </div>
 * ```
 */
export const Terminal = forwardRef<TerminalHandle, TerminalProps>(function Terminal(
  {
    output,
    theme,
    rows,
    cols,
    fit = true,
    readOnly,
    cursorBlink,
    cursorStyle,
    fontFamily,
    fontSize,
    scrollback,
    initialOutput,
    onData,
    onResize,
    shells,
    activeShell,
    onShellChange,
    showShellBar = false,
    clipboard,
    osc52,
    copyPaste,
    onReady,
    onPaste,
    onLinkActivate,
    links,
    contextMenu,
    className,
    style,
    ...rest
  },
  ref,
) {
  const containerRef = useRef<HTMLDivElement>(null);

  // Selected shell: controlled by `activeShell` when provided, else internal.
  const isShellControlled = activeShell !== undefined;
  const [internalShell, setInternalShell] = useState<string | undefined>(undefined);
  const shellId = isShellControlled ? activeShell : internalShell;

  // Read shell state live so the stable handle's setShell/getShell never go stale.
  const shellStateRef = useRef({ shells, shellId, isShellControlled, onShellChange });
  shellStateRef.current = { shells, shellId, isShellControlled, onShellChange };

  const selectShell = useCallback((id: string) => {
    const s = shellStateRef.current;
    const decision = decideShellSelect(s.shells, s.shellId, id);
    if (!decision) return; // unknown id — no-op
    if (!s.isShellControlled) setInternalShell(id);
    s.onShellChange?.(id, decision.profile);
  }, []);

  const handle = useTerminal(containerRef, {
    theme,
    rows,
    cols,
    fit,
    readOnly,
    cursorBlink,
    cursorStyle,
    fontFamily,
    fontSize,
    scrollback,
    // `initialOutput` is for uncontrolled use; with a controlled `output` the
    // diffing effect below owns the buffer, so don't double-write.
    initialOutput: output === undefined ? initialOutput : undefined,
    onData,
    onResize,
    clipboard,
    osc52,
    copyPaste,
    onReady,
    onPaste,
    onLinkActivate,
    links,
  });

  // Delegate `xterm` / `ready` as live getters rather than spreading `handle`
  // (object spread would snapshot the getters — capturing xterm === null before
  // the container is measured, the exact race consumers hit). Methods are stable.
  useImperativeHandle(
    ref,
    (): TerminalHandle => ({
      get xterm() {
        return handle.xterm;
      },
      get ready() {
        return handle.ready;
      },
      write: handle.write,
      writeln: handle.writeln,
      clear: handle.clear,
      reset: handle.reset,
      fit: handle.fit,
      focus: handle.focus,
      getBuffer: handle.getBuffer,
      getSelection: handle.getSelection,
      copySelection: handle.copySelection,
      paste: handle.paste,
      selectAll: handle.selectAll,
      clearSelection: handle.clearSelection,
      setShell: selectShell,
      getShell: () => shellStateRef.current.shellId,
    }),
    [handle, selectShell],
  );

  // Controlled output: write only the appended delta; reset + rewrite if the
  // value diverges from what we've already written (a wholesale replace).
  const written = useRef("");
  useEffect(() => {
    if (output === undefined) return;
    const change = diffOutput(written.current, output);
    if (!change) return;
    if (change.reset) handle.reset();
    handle.write(change.write);
    written.current = output;
  }, [output, handle]);

  // Right-click selection context menu (Copy / Paste / Select all / Clear by
  // default; customizable via the `contextMenu` prop).
  const [menu, setMenu] = useState<{
    at: { x: number; y: number };
    items: TerminalContextMenuItem[];
    ctx: TerminalContextMenuContext;
  } | null>(null);

  // #2 — over a mouse-reporting TUI (Claude Code, tmux, vim) the app's redraw
  // asynchronously clears xterm's selection right after a right-click, so both
  // late reads lose: at `contextmenu` time the selection may already be gone,
  // and by the time the user clicks Copy it almost always is. Track a snapshot
  // at pointer time (capture phase — before xterm / the app can react) and use
  // it as the menu's source of truth whenever the live selection is empty.
  const selectionSnapshot = useRef("");
  const trackSelection = useCallback(
    (e: React.MouseEvent) => {
      selectionSnapshot.current = nextSelectionSnapshot(
        selectionSnapshot.current,
        { type: e.type as "mousedown" | "mouseup", button: e.button },
        handle.getSelection(),
      );
    },
    [handle],
  );

  const openMenu = useCallback(
    (e: React.MouseEvent) => {
      if (contextMenu === false) return;
      e.preventDefault();
      const selection = handle.getSelection() || selectionSnapshot.current;
      const ctx: TerminalContextMenuContext = {
        hasSelection: selection.length > 0,
        selection,
        readOnly: !!readOnly,
      };
      const items = resolveMenuItems(contextMenu, ctx, {
        // Copy writes the SNAPSHOTTED selection through the active clipboard
        // provider — never a click-time re-read, which copies "" over a TUI
        // (falling back to the live selection only when the snapshot is empty).
        copy: (c) => {
          const text = c.selection || handle.getSelection();
          if (text) void providerWrite(resolveClipboard(clipboard).provider, text);
        },
        paste: () => void handle.paste(),
        selectAll: () => handle.selectAll(),
        clear: () => handle.clear(),
      });
      if (items) setMenu({ at: { x: e.clientX, y: e.clientY }, items, ctx });
    },
    [contextMenu, handle, readOnly, clipboard],
  );

  const menuNode = menu ? (
    <TerminalContextMenu at={menu.at} items={menu.items} ctx={menu.ctx} onClose={() => setMenu(null)} />
  ) : null;

  const surface = (
    <div
      ref={containerRef}
      data-fancy-terminal=""
      onMouseDownCapture={trackSelection}
      onMouseUpCapture={trackSelection}
      onContextMenu={openMenu}
      data-readonly={readOnly ? "" : undefined}
      data-fancy-terminal-shell={shellId ?? undefined}
      // When the shell bar is shown the wrapper owns the box; the surface flexes.
      style={
        showShellBar && shells
          ? { width: "100%", flex: 1, minHeight: 0 }
          : { width: "100%", height: "100%", ...style }
      }
      {...(showShellBar && shells ? {} : rest)}
    />
  );

  if (!showShellBar || !shells) {
    return (
      <>
        {surface}
        {menuNode}
      </>
    );
  }

  return (
    <div
      data-fancy-terminal-shell={shellId ?? undefined}
      className={className}
      style={{ display: "flex", flexDirection: "column", width: "100%", height: "100%", ...style }}
      {...rest}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          padding: "4px 6px",
          background: "#09090b",
          borderBottom: "1px solid #27272a",
        }}
      >
        <ShellSwitcher
          shells={shells}
          value={shellId}
          onChange={(id) => selectShell(id)}
          disabled={readOnly}
        />
      </div>
      {surface}
      {menuNode}
    </div>
  );
});

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
} from "react";
import { resolveShell, type ShellProfile } from "../lib/types";

export interface ShellSwitcherProps {
  /** The available shells / profiles. */
  shells: ShellProfile[];
  /** Controlled selected shell id. */
  value?: string;
  /** Fired when a shell is picked. */
  onChange: (id: string, profile: ShellProfile) => void;
  className?: string;
  style?: CSSProperties;
  /** Disable the control. */
  disabled?: boolean;
}

const PANEL_BG = "#18181b"; // zinc-900
const BORDER = "#3f3f46"; // zinc-700
const FG = "#e4e4e7"; // zinc-200
const MUTED = "#a1a1aa"; // zinc-400
const ACCENT = "#8b5cf6"; // violet-500
const HOVER_BG = "#27272a"; // zinc-800

/**
 * Compact, accessible shell picker styled to the Fancy dark theme. Self-contained
 * (zero third-party deps) — a button that toggles a listbox of `shells`.
 *
 * Stable handles for agents: the root carries `data-fancy-shell-switcher` and each
 * option carries `data-shell-id`, so a bridge can pick a shell without DOM-guessing.
 *
 * Controlled: pass `value` + `onChange`. Keyboard accessible (Arrow / Enter / Esc).
 */
export function ShellSwitcher({
  shells,
  value,
  onChange,
  className,
  style,
  disabled,
}: ShellSwitcherProps) {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);
  const rootRef = useRef<HTMLDivElement>(null);
  const listId = useId();

  const selected = resolveShell(shells, value);
  const selectedIndex = selected ? shells.indexOf(selected) : -1;

  // Close on outside click.
  useEffect(() => {
    if (!open) return;
    const onDocClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [open]);

  const openMenu = useCallback(() => {
    if (disabled) return;
    setActiveIndex(selectedIndex >= 0 ? selectedIndex : 0);
    setOpen(true);
  }, [disabled, selectedIndex]);

  const pick = useCallback(
    (i: number) => {
      const profile = shells[i];
      if (!profile) return;
      onChange(profile.id, profile);
      setOpen(false);
    },
    [shells, onChange],
  );

  const onButtonKeyDown = (e: KeyboardEvent) => {
    if (disabled) return;
    if (e.key === "ArrowDown" || e.key === "ArrowUp" || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      openMenu();
    }
  };

  const onListKeyDown = (e: KeyboardEvent) => {
    if (e.key === "Escape") {
      e.preventDefault();
      setOpen(false);
      return;
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(shells.length - 1, i + 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(0, i - 1));
    } else if (e.key === "Home") {
      e.preventDefault();
      setActiveIndex(0);
    } else if (e.key === "End") {
      e.preventDefault();
      setActiveIndex(shells.length - 1);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      pick(activeIndex);
    }
  };

  const buttonStyle: CSSProperties = {
    display: "inline-flex",
    alignItems: "center",
    gap: 6,
    height: 26,
    padding: "0 8px",
    fontSize: 12,
    lineHeight: 1,
    fontFamily: "inherit",
    color: FG,
    background: PANEL_BG,
    border: `1px solid ${BORDER}`,
    borderRadius: 6,
    cursor: disabled ? "default" : "pointer",
    opacity: disabled ? 0.6 : 1,
    userSelect: "none",
  };

  return (
    <div
      ref={rootRef}
      data-fancy-shell-switcher=""
      data-active-shell={value ?? undefined}
      className={className}
      style={{ position: "relative", display: "inline-block", ...style }}
    >
      <button
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label="Select shell"
        disabled={disabled}
        style={buttonStyle}
        onClick={() => (open ? setOpen(false) : openMenu())}
        onKeyDown={onButtonKeyDown}
      >
        {selected?.icon ? (
          <span aria-hidden="true" style={{ color: ACCENT }}>
            {selected.icon}
          </span>
        ) : null}
        <span>{selected?.label ?? "Select shell"}</span>
        <span aria-hidden="true" style={{ color: MUTED, fontSize: 9 }}>
          ▼
        </span>
      </button>

      {open ? (
        <ul
          role="listbox"
          id={listId}
          aria-label="Shells"
          tabIndex={-1}
          // Autofocus is deliberate: this list only renders once the switcher
          // is opened by an explicit user action, so focus is going where the
          // person just asked to be. (This used to carry an
          // `eslint-disable jsx-a11y/no-autofocus`, but jsx-a11y has never been
          // a dependency here — it silenced a rule that did not exist, and
          // broke linting once ESLint was actually turned on.)
          autoFocus
          onKeyDown={onListKeyDown}
          ref={(el) => el?.focus()}
          style={{
            position: "absolute",
            zIndex: 50,
            top: "calc(100% + 4px)",
            left: 0,
            minWidth: "100%",
            margin: 0,
            padding: 4,
            listStyle: "none",
            background: PANEL_BG,
            border: `1px solid ${BORDER}`,
            borderRadius: 8,
            boxShadow: "0 8px 24px rgba(0,0,0,0.45)",
            outline: "none",
          }}
        >
          {shells.map((s, i) => {
            const isSelected = s.id === value;
            const isActive = i === activeIndex;
            return (
              <li
                key={s.id}
                role="option"
                aria-selected={isSelected}
                data-shell-id={s.id}
                onMouseEnter={() => setActiveIndex(i)}
                onClick={() => pick(i)}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  padding: "6px 8px",
                  fontSize: 12,
                  borderRadius: 5,
                  color: FG,
                  cursor: "pointer",
                  background: isActive ? HOVER_BG : "transparent",
                }}
              >
                <span
                  aria-hidden="true"
                  style={{
                    width: 18,
                    textAlign: "center",
                    color: isSelected ? ACCENT : MUTED,
                  }}
                >
                  {s.icon ?? ""}
                </span>
                <span style={{ flex: 1 }}>{s.label}</span>
                {isSelected ? (
                  <span aria-hidden="true" style={{ color: ACCENT, fontSize: 11 }}>
                    ✓
                  </span>
                ) : null}
              </li>
            );
          })}
        </ul>
      ) : null}
    </div>
  );
}

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { clampMenuPosition } from "../lib/menu-position";
import type {
  TerminalContextMenuContext,
  TerminalContextMenuItem,
} from "../lib/context-menu";

/**
 * The terminal selection context menu. Deliberately plain React + inline styles
 * (fancy-term has no react-fancy dependency) styled to match the shell bar. It
 * closes on click-outside + Escape, and clamps itself inside the viewport on
 * mount so a right-click near an edge never spills off-screen.
 */
export function TerminalContextMenu({
  at,
  items,
  ctx,
  onClose,
}: {
  at: { x: number; y: number };
  items: TerminalContextMenuItem[];
  ctx: TerminalContextMenuContext;
  onClose: () => void;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [pos, setPos] = useState(at);

  // Clamp once we can measure the rendered menu.
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return;
    const r = el.getBoundingClientRect();
    setPos(
      clampMenuPosition(
        at,
        { width: r.width, height: r.height },
        { width: window.innerWidth, height: window.innerHeight },
      ),
    );
  }, [at]);

  // Dismiss on click-outside + Escape (capture so it wins over the surface).
  useEffect(() => {
    const onDown = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) onClose();
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("mousedown", onDown, true);
    document.addEventListener("keydown", onKey, true);
    return () => {
      document.removeEventListener("mousedown", onDown, true);
      document.removeEventListener("keydown", onKey, true);
    };
  }, [onClose]);

  return (
    <div
      ref={ref}
      data-fancy-terminal-menu=""
      role="menu"
      style={{
        position: "fixed",
        left: pos.x,
        top: pos.y,
        zIndex: 2147483000,
        minWidth: 176,
        padding: 4,
        background: "#18181b",
        border: "1px solid #3f3f46",
        borderRadius: 8,
        boxShadow: "0 10px 32px -8px rgba(0,0,0,.6)",
        color: "#e4e4e7",
        font: '13px/1.4 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif',
        userSelect: "none",
      }}
    >
      {items.map((it) =>
        it.separator ? (
          <div
            key={it.id}
            role="separator"
            style={{ height: 1, margin: "4px 6px", background: "#3f3f46" }}
          />
        ) : (
          <button
            key={it.id}
            type="button"
            role="menuitem"
            data-menu-item={it.id}
            disabled={it.disabled}
            onClick={() => {
              if (it.disabled) return;
              it.onSelect?.(ctx);
              onClose();
            }}
            onMouseEnter={(e) => {
              if (!it.disabled) e.currentTarget.style.background = "#27272a";
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = "transparent";
            }}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 9,
              width: "100%",
              textAlign: "left",
              padding: "6px 9px",
              border: "none",
              borderRadius: 5,
              background: "transparent",
              color: it.disabled ? "#52525b" : "inherit",
              cursor: it.disabled ? "default" : "pointer",
              font: "inherit",
            }}
          >
            <span style={{ width: 16, textAlign: "center", opacity: 0.8 }}>
              {it.icon ?? ""}
            </span>
            <span style={{ flex: 1 }}>{it.label}</span>
          </button>
        ),
      )}
    </div>
  );
}

import { useEffect, useRef, type RefObject } from "react";
// `@xterm/xterm` and `@xterm/addon-fit` are CommonJS-ONLY, and their exports are
// not statically detectable by Node's cjs-module-lexer. A named import here
// becomes `import { Terminal } from '@xterm/xterm'` in the ESM bundle, which
// throws `SyntaxError: Named export 'Terminal' not found` the moment anyone
// imports this package WITHOUT a bundler — SSR, a react-dom/server render test,
// a plain Node script. Vite's interop hides it, which is why the component
// works in an app and why this shipped in 0.6.1 unnoticed.
//
// A DEFAULT import is the fix: for a CJS module Node binds `default` to
// `module.exports`, so destructuring off it works under both Node and every
// bundler. Types come from a separate `import type`, which is erased.
//
// Guarded two ways: `src/packaging.test.ts` forbids a bare named import from
// these peers, and `scripts/check-esm-import.mjs` imports the built bundle in a
// real Node process — vitest runs through Vite and CANNOT see this defect.
import xtermPkg from "@xterm/xterm";
import addonFitPkg from "@xterm/addon-fit";
import type { Terminal as XTerm } from "@xterm/xterm";
import type { FitAddon } from "@xterm/addon-fit";

const { Terminal: XTermCtor } = xtermPkg;
const { FitAddon: FitAddonCtor } = addonFitPkg;
import { fancyDarkTheme } from "../theme";
import { useTerminalFit } from "./use-terminal-fit";
import { providerRead, providerWrite, readDataTransfer, resolveClipboard } from "../clipboard";
import { copyPasteBehavior, resolveKeyAction } from "../copy-paste-mode";
import { registerOsc52 } from "../osc52";
import { resolveLinkHandlers, terminalLinkProvider } from "../links";
import type { TerminalHandle, TerminalOptions } from "../types";

const DEFAULT_FONT =
  'ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace';

/** A minimal externally-resolvable promise (Promise.withResolvers isn't universally available). */
function makeDeferred<T>(): { promise: Promise<T>; resolve: (value: T) => void } {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((r) => {
    resolve = r;
  });
  return { promise, resolve };
}

/** Read the whole xterm buffer as plain text — what an agent "sees". */
function readBuffer(term: XTerm | null): string {
  if (!term) return "";
  const buf = term.buffer.active;
  const lines: string[] = [];
  for (let i = 0; i < buf.length; i++) {
    const line = buf.getLine(i);
    if (line) lines.push(line.translateToString(true));
  }
  return lines.join("\n").replace(/\n+$/, "");
}

/**
 * Create + own an xterm.js instance for a container, returning a stable
 * {@link TerminalHandle}. The headless engine layer behind `<Terminal>` — use it
 * directly when you want the terminal without the component shell (custom chrome,
 * an agent bridge host, tests). Options are read live, so changing them re-applies
 * without tearing down the terminal.
 */
export function useTerminal(
  containerRef: RefObject<HTMLElement | null>,
  options: TerminalOptions = {},
): TerminalHandle {
  const xtermRef = useRef<XTerm | null>(null);
  const fitRef = useRef<FitAddon | null>(null);
  const optsRef = useRef(options);
  optsRef.current = options;

  // A re-armable "xterm is open" promise backing handle.ready.
  const readyRef = useRef(makeDeferred<XTerm>());

  // Stable handle — its methods always operate on the live xterm via the ref.
  const handleRef = useRef<TerminalHandle | null>(null);
  if (handleRef.current === null) {
    handleRef.current = {
      get xterm() {
        return xtermRef.current;
      },
      get ready() {
        return readyRef.current.promise;
      },
      write: (d) => xtermRef.current?.write(d),
      writeln: (d) => xtermRef.current?.writeln(d),
      clear: () => xtermRef.current?.clear(),
      reset: () => xtermRef.current?.reset(),
      fit: () => {
        const addon = fitRef.current;
        if (!addon) return;
        try {
          // Guard against an unmeasurable container / not-yet-rendered viewport:
          // proposeDimensions() returns undefined (or NaN) then, and fit() would
          // call xterm's resize(undefined,…), which console-errors "cols must be
          // numeric". Skip — the ResizeObserver fires again once it's measurable.
          // This matters most under `showShellBar`, whose extra layout pass races
          // the first fit.
          const dims = addon.proposeDimensions();
          if (
            !dims ||
            !Number.isFinite(dims.cols) ||
            !Number.isFinite(dims.rows) ||
            dims.cols < 1 ||
            dims.rows < 1
          ) {
            return;
          }
          addon.fit();
        } catch {
          /* container not measurable yet — ignore */
        }
      },
      focus: () => xtermRef.current?.focus(),
      getBuffer: () => readBuffer(xtermRef.current),
      getSelection: () => xtermRef.current?.getSelection() ?? "",
      copySelection: async () => {
        const sel = xtermRef.current?.getSelection() ?? "";
        if (!sel) return false;
        return providerWrite(resolveClipboard(optsRef.current.clipboard).provider, sel);
      },
      paste: async (text) => {
        const data = text ?? (await providerRead(resolveClipboard(optsRef.current.clipboard).provider));
        if (data) xtermRef.current?.paste(data);
      },
      selectAll: () => xtermRef.current?.selectAll(),
      clearSelection: () => xtermRef.current?.clearSelection(),
      // Shell selection is owned by the <Terminal> component layer (it needs the
      // `shells` list + onShellChange). The headless engine is shell-agnostic, so
      // these are no-ops here and get overridden when <Terminal> composes them.
      setShell: () => {},
      getShell: () => undefined,
    };
  }
  const handle = handleRef.current;

  // Create the engine once for the container.
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const o = optsRef.current;

    const term = new XTermCtor({
      theme: o.theme ?? fancyDarkTheme,
      // Only pass rows/cols when explicitly set. xterm validates these and
      // console-errors "rows/cols must be numeric" if handed `undefined`, rather
      // than falling back to its 80×24 default. Omit the keys instead.
      ...(typeof o.rows === "number" ? { rows: o.rows } : {}),
      ...(typeof o.cols === "number" ? { cols: o.cols } : {}),
      disableStdin: o.readOnly ?? false,
      cursorBlink: o.cursorBlink ?? true,
      cursorStyle: o.cursorStyle ?? "block",
      fontFamily: o.fontFamily ?? DEFAULT_FONT,
      fontSize: o.fontSize ?? 13,
      scrollback: o.scrollback ?? 1000,
      allowProposedApi: true,
    });
    const fitAddon = new FitAddonCtor();
    term.loadAddon(fitAddon);
    term.open(el);
    xtermRef.current = term;
    fitRef.current = fitAddon;

    const dataSub = term.onData((d) => optsRef.current.onData?.(d));
    const resizeSub = term.onResize(({ cols, rows }) =>
      optsRef.current.onResize?.({ cols, rows }),
    );

    // Paste the system clipboard into the terminal (honors readOnly + bracketed
    // paste). Shared by the paste key chord and middle-click paste.
    const pasteFromClipboard = async () => {
      const oo = optsRef.current;
      if (oo.readOnly) return;
      const text = await providerRead(resolveClipboard(oo.clipboard).provider);
      if (text) xtermRef.current?.paste(text);
    };

    // ── Clipboard wiring (gated by `clipboard !== false`, read live) ──────────
    // Copy/paste key chords resolved by the active `copyPaste` mode: Ctrl+Shift+C
    // always copies; plain Ctrl+C stays SIGINT unless winmac + selection; winmac
    // also binds Ctrl/Cmd+V paste. Returning false consumes the event.
    term.attachCustomKeyEventHandler((e) => {
      const oo = optsRef.current;
      const clip = resolveClipboard(oo.clipboard);
      if (!clip.enabled) return true;
      const action = resolveKeyAction(e, term.hasSelection(), copyPasteBehavior(oo.copyPaste));
      if (action === "copy") {
        void providerWrite(clip.provider, term.getSelection());
        return false;
      }
      if (action === "paste") {
        void pasteFromClipboard();
        return false;
      }
      return true;
    });

    // OSC 52 — terminal programs (Claude Code, tmux, vim) copy/read the clipboard
    // via `ESC ] 52`. Routed through the live provider; off when clipboard === false.
    const oscDisposable = registerOsc52(
      term,
      () => resolveClipboard(optsRef.current.clipboard).provider,
      () => {
        const oo = optsRef.current;
        return resolveClipboard(oo.clipboard).enabled ? (oo.osc52 ?? "copy") : false;
      },
    );

    // Clickable URLs and file paths, sent wherever the host's `links` config says
    // (`onLinkActivate` is 0.7.0's shorthand for `links.url`). One provider for the
    // terminal's life that resolves the CURRENT config on every hover, so changing
    // it never rebuilds the terminal. With nothing configured there are no links,
    // and no underline promising a click that does nothing.
    const linkDisposable = term.registerLinkProvider({
      provideLinks(bufferLineNumber, callback) {
        const oo = optsRef.current;
        const links = oo.links?.url === undefined && oo.onLinkActivate
          ? { ...oo.links, url: oo.onLinkActivate }
          : oo.links;
        terminalLinkProvider(term, resolveLinkHandlers(links)).provideLinks(bufferLineNumber, callback);
      },
    });

    // linux mode: auto-copy the selection as it changes (X11 primary-selection).
    const selectionSub = term.onSelectionChange(() => {
      const oo = optsRef.current;
      const clip = resolveClipboard(oo.clipboard);
      if (clip.enabled && copyPasteBehavior(oo.copyPaste).selectToCopy && term.hasSelection()) {
        void providerWrite(clip.provider, term.getSelection());
      }
    });

    // linux mode: middle-click pastes.
    const onMouseDown = (ev: MouseEvent) => {
      const oo = optsRef.current;
      if (ev.button !== 1) return;
      if (!resolveClipboard(oo.clipboard).enabled) return;
      if (!copyPasteBehavior(oo.copyPaste).middleClickPaste) return;
      ev.preventDefault();
      void pasteFromClipboard();
    };
    el.addEventListener("mousedown", onMouseDown);

    // Paste: a capture-phase listener on the container runs before xterm's own
    // textarea handler. We do NOT preventDefault for text, so xterm pastes it
    // exactly once natively — we only surface the payload (esp. pasted images)
    // via onPaste. The host returning false (or a read-only terminal) suppresses
    // the native text paste.
    const onPasteEvent = (e: ClipboardEvent) => {
      const o2 = optsRef.current;
      if (resolveClipboard(o2.clipboard).enabled === false) return;
      if (o2.readOnly) {
        e.preventDefault();
        return;
      }
      const payload = readDataTransfer(e.clipboardData);
      if (o2.onPaste?.(payload) === false) e.preventDefault();
    };
    el.addEventListener("paste", onPasteEvent, true);

    if (o.initialOutput) term.write(o.initialOutput);
    // Route through the guarded handle.fit() (proposeDimensions check) so a
    // not-yet-laid-out container never triggers an xterm resize(undefined).
    if (o.fit ?? true) handle.fit();

    // The terminal is open + attached — signal readiness so consumers wiring
    // addons don't have to poll handle.xterm.
    optsRef.current.onReady?.(term);
    readyRef.current.resolve(term);

    return () => {
      el.removeEventListener("paste", onPasteEvent, true);
      el.removeEventListener("mousedown", onMouseDown);
      oscDisposable?.dispose();
      linkDisposable.dispose();
      selectionSub.dispose();
      dataSub.dispose();
      resizeSub.dispose();
      term.dispose();
      xtermRef.current = null;
      fitRef.current = null;
      // Re-arm readiness for a potential remount (container change).
      readyRef.current = makeDeferred<XTerm>();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [containerRef]);

  // Re-apply reactive options without tearing the terminal down.
  useEffect(() => {
    const t = xtermRef.current;
    if (!t) return;
    if (options.theme) t.options.theme = options.theme;
    if (options.readOnly !== undefined) t.options.disableStdin = options.readOnly;
    if (options.cursorBlink !== undefined) t.options.cursorBlink = options.cursorBlink;
    if (options.cursorStyle) t.options.cursorStyle = options.cursorStyle;
    if (options.fontSize) t.options.fontSize = options.fontSize;
    if (options.fontFamily) t.options.fontFamily = options.fontFamily;
  }, [options.theme, options.readOnly, options.cursorBlink, options.cursorStyle, options.fontSize, options.fontFamily]);

  // Auto-fit on container resize (0×0-guarded).
  useTerminalFit(containerRef, () => handle.fit(), options.fit ?? true);

  return handle;
}

/**
 * Decide what to push to the terminal when the controlled `output` changes.
 * Terminals are append-only streams, so the common case (output grew) writes
 * only the delta; a value that no longer extends what we've written means a
 * wholesale replace, so reset + rewrite. Returns null when nothing changed.
 */
export function diffOutput(
  written: string,
  next: string,
): { reset: boolean; write: string } | null {
  if (next === written) return null;
  if (next.startsWith(written)) return { reset: false, write: next.slice(written.length) };
  return { reset: true, write: next };
}

import { resolveShell, type ShellProfile } from "./types";

/**
 * Pure decision for "select shell `id`": resolves the profile and reports whether
 * the selection actually changed. The single source of truth shared by
 * `<Terminal>`'s `setShell`, `<ShellSwitcher>`, and `useTerminalSession`, so the
 * interactive behavior is unit-testable without a DOM.
 *
 * Returns `null` when the id isn't in `shells` (a no-op — unknown shell).
 */
export function decideShellSelect(
  shells: ShellProfile[] | undefined,
  current: string | undefined,
  id: string,
): { profile: ShellProfile; changed: boolean } | null {
  const profile = resolveShell(shells, id);
  if (!profile) return null;
  return { profile, changed: current !== id };
}

/**
 * Pure decision for a session shell switch. The session hook holds the buffer +
 * the transport, so it only needs to know: did the shell change? If so it must
 * reset the buffer (to `initial`) and reconnect the transport. Extracted so the
 * reset-and-reconnect contract is unit-testable without rendering the hook.
 */
export function decideShellSwitch(
  current: string | undefined,
  next: string | undefined,
): { changed: boolean } {
  return { changed: current !== next };
}

// clipboard.ts — small, dependency-free clipboard helpers shared by the headless
// hook (copy/paste primitives + the paste interceptor) and the component. Kept
// pure where possible so the extraction logic is unit-testable without a DOM.

/** What a paste / drop carried: plain text plus any files (e.g. pasted images). */
export interface ClipboardPayload {
  /** Plain text from the clipboard (or pasted selection). May be "". */
  text: string;
  /** Files present on the clipboard / drop — typically pasted/dropped images. */
  files: File[];
  /** Convenience: the subset of `files` whose MIME type is `image/*`. */
  images: File[];
}

/** True when a file looks like an image (by MIME type). */
export function isImageFile(f: { type?: string }): boolean {
  return typeof f.type === "string" && f.type.startsWith("image/");
}

/**
 * Pull text + files out of a ClipboardEvent / DragEvent `dataTransfer`. The
 * DataTransferItemList is checked first (pasted screenshots only appear there in
 * some browsers), then `.files` as a fallback. Pure + null-safe.
 */
export function readDataTransfer(dt: DataTransfer | null | undefined): ClipboardPayload {
  const files: File[] = [];
  let text = "";
  if (dt) {
    try {
      text = dt.getData("text/plain") ?? "";
    } catch {
      /* getData can throw in restricted contexts */
    }
    const items = dt.items;
    if (items) {
      for (let i = 0; i < items.length; i++) {
        const it = items[i];
        if (it && it.kind === "file") {
          const f = it.getAsFile();
          if (f) files.push(f);
        }
      }
    }
    if (files.length === 0 && dt.files) {
      for (let i = 0; i < dt.files.length; i++) files.push(dt.files[i]);
    }
  }
  return { text, files, images: files.filter(isImageFile) };
}

/** Write text to the system clipboard. Resolves false when unavailable/denied. */
export async function writeClipboardText(text: string): Promise<boolean> {
  try {
    const nav = typeof navigator !== "undefined" ? navigator : undefined;
    if (nav?.clipboard?.writeText) {
      await nav.clipboard.writeText(text);
      return true;
    }
  } catch {
    /* fall through to the legacy path */
  }
  // Legacy fallback for insecure contexts / older browsers.
  try {
    if (typeof document === "undefined") return false;
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  } catch {
    return false;
  }
}

/** Read text from the system clipboard. Resolves "" when unavailable/denied. */
export async function readClipboardText(): Promise<string> {
  try {
    const nav = typeof navigator !== "undefined" ? navigator : undefined;
    if (nav?.clipboard?.readText) return await nav.clipboard.readText();
  } catch {
    /* permission denied / unavailable */
  }
  return "";
}

/**
 * A host-supplied clipboard. Every copy/paste path in fancy-term — the copy
 * chord, the context menu, OSC 52, `handle.copySelection` / `handle.paste` —
 * routes through this, so an Electron host (where `navigator.clipboard` silently
 * no-ops in a sandboxed renderer) can bridge to its main-process clipboard over
 * IPC. `writeText` may return anything (a `Promise<void>` from IPC is fine);
 * `readText` returns the clipboard text.
 */
export interface ClipboardProvider {
  writeText: (text: string) => void | Promise<unknown>;
  readText: () => string | Promise<string>;
}

/** The default provider — `navigator.clipboard` with the legacy `execCommand` fallback. */
export const navigatorClipboard: ClipboardProvider = {
  writeText: (text) => writeClipboardText(text),
  readText: () => readClipboardText(),
};

/** The `clipboard` prop: `false` disables clipboard wiring; a provider object injects a host clipboard; `true`/omitted uses {@link navigatorClipboard}. */
export type ClipboardOption = boolean | ClipboardProvider;

/** Normalize the `clipboard` prop into `{ enabled, provider }`, read live per call. */
export function resolveClipboard(clipboard: ClipboardOption | undefined): {
  enabled: boolean;
  provider: ClipboardProvider;
} {
  if (clipboard === false) return { enabled: false, provider: navigatorClipboard };
  if (clipboard && typeof clipboard === "object") return { enabled: true, provider: clipboard };
  return { enabled: true, provider: navigatorClipboard };
}

/** Write via a provider, resolving `true` on success and `false` if it throws/rejects. */
export async function providerWrite(provider: ClipboardProvider, text: string): Promise<boolean> {
  try {
    await provider.writeText(text);
    return true;
  } catch {
    return false;
  }
}

/** Read via a provider, resolving `""` if it throws/rejects. */
export async function providerRead(provider: ClipboardProvider): Promise<string> {
  try {
    return (await provider.readText()) ?? "";
  } catch {
    return "";
  }
}

// context-menu.ts — the model for the customizable terminal selection menu.
// Pure data + a resolver; the rendering lives in TerminalContextMenu.tsx.

/** Context handed to the menu at right-click time + to custom item builders. */
export interface TerminalContextMenuContext {
  /** Whether there is a non-empty text selection. */
  hasSelection: boolean;
  /** The selected text (or ""). */
  selection: string;
  /** Whether the terminal is read-only (paste / clear are dropped by default). */
  readOnly: boolean;
}

/** A single menu entry. `onSelect` runs on click; set `separator` for a divider. */
export interface TerminalContextMenuItem {
  /** Stable id (used as the React key + a `data-menu-item` handle). */
  id: string;
  /** Visible label. Ignored for separators. */
  label?: string;
  /** Optional leading glyph / emoji / short string (JSON-friendly — no ReactNode). */
  icon?: string;
  /** Greyed-out + non-interactive. */
  disabled?: boolean;
  /** Render a divider instead of a clickable item. */
  separator?: boolean;
  /** Invoked on click with the menu context. */
  onSelect?: (ctx: TerminalContextMenuContext) => void;
}

/** The actions the built-in items dispatch to (wired by the component). */
export interface TerminalMenuActions {
  /**
   * Receives the menu's {@link TerminalContextMenuContext} so it can copy the
   * selection **snapshotted when the menu opened** — by click time the live
   * xterm selection is often already cleared (a mouse-reporting TUI's redraw
   * clears it right after the right-click), so re-reading it copies nothing.
   */
  copy: (ctx: TerminalContextMenuContext) => void;
  paste: () => void;
  selectAll: () => void;
  clear: () => void;
}

/**
 * The `contextMenu` prop shape:
 * - `false` — disable the menu entirely.
 * - `true` / omitted — the default Copy / Paste / Select all / Clear menu.
 * - an array — replace the default items wholesale.
 * - a function — receives the context **and the default items** so you can
 *   add/remove/reorder (e.g. append a "Send to agent" item).
 */
export type TerminalContextMenuConfig =
  | boolean
  | TerminalContextMenuItem[]
  | ((
      ctx: TerminalContextMenuContext,
      defaults: TerminalContextMenuItem[],
    ) => TerminalContextMenuItem[]);

/** The built-in Copy / Paste / Select all / Clear items, contextual to selection + readOnly. */
export function defaultMenuItems(
  ctx: TerminalContextMenuContext,
  actions: TerminalMenuActions,
): TerminalContextMenuItem[] {
  const items: TerminalContextMenuItem[] = [
    { id: "copy", label: "Copy", icon: "⧉", disabled: !ctx.hasSelection, onSelect: actions.copy },
  ];
  if (!ctx.readOnly) {
    items.push({ id: "paste", label: "Paste", icon: "⎘", onSelect: actions.paste });
  }
  items.push({ id: "select-all", label: "Select all", onSelect: actions.selectAll });
  if (!ctx.readOnly) {
    items.push({ id: "sep-default", separator: true });
    items.push({ id: "clear", label: "Clear", onSelect: actions.clear });
  }
  return items;
}

/**
 * Resolve the configured menu into the final item list, or `null` when disabled.
 * Empty results (e.g. a function that filtered everything out) also resolve to
 * `null` so the caller can skip opening an empty menu.
 */
export function resolveMenuItems(
  config: TerminalContextMenuConfig | undefined,
  ctx: TerminalContextMenuContext,
  actions: TerminalMenuActions,
): TerminalContextMenuItem[] | null {
  if (config === false) return null;
  const defaults = defaultMenuItems(ctx, actions);
  const items =
    config === undefined || config === true
      ? defaults
      : Array.isArray(config)
        ? config
        : config(ctx, defaults);
  return items.length > 0 ? items : null;
}

// selection-snapshot.ts — pure decision layer for the context-menu selection
// snapshot (#2). Over a mouse-reporting TUI (Claude Code, tmux, vim with mouse
// mode) a right-click is forwarded to the app, whose redraw asynchronously
// clears xterm's selection — often between the selecting drag and the menu
// opening, and almost always before the user clicks Copy. So the component
// keeps a snapshot of the selection, maintained at pointer time (capture
// phase, before xterm or the app can react), and the menu falls back to it
// whenever the live selection has already been cleared.

/** The bits of a pointer event the snapshot decision needs. */
export interface SnapshotPointerEvent {
  type: "mousedown" | "mouseup";
  /** 0 = left, 1 = middle, 2 = right. */
  button: number;
}

/**
 * Compute the next selection snapshot after a pointer event on the terminal
 * surface.
 *
 * - A fresh **left press** starts a new gesture — drop the snapshot (the live
 *   selection still reads the *old* text at capture time, so it must not win).
 * - Otherwise a **non-empty live selection** always refreshes the snapshot
 *   (drag-select completes on left mouseup; a right press re-captures while
 *   the selection is still alive).
 * - An **empty** live selection keeps the previous snapshot — that's exactly
 *   the TUI-cleared-it-under-us case the snapshot exists for.
 */
export function nextSelectionSnapshot(
  prev: string,
  event: SnapshotPointerEvent,
  liveSelection: string,
): string {
  if (event.type === "mousedown" && event.button === 0) return "";
  return liveSelection || prev;
}

import type { HTMLAttributes } from "react";
import type { ITheme, Terminal as XTerm } from "@xterm/xterm";
import type { ClipboardOption, ClipboardPayload } from "./clipboard";
import type { CopyPasteMode } from "./copy-paste-mode";
import type { Osc52Mode } from "./osc52";
import type { TerminalLinks } from "./links";
import type { TerminalContextMenuConfig } from "./context-menu";

/** xterm.js color theme (re-exported for ergonomic typing). */
export type TerminalTheme = ITheme;

export type CursorStyle = "block" | "underline" | "bar";

/**
 * A selectable shell / profile. Fully JSON-friendly (primitives only) so an agent
 * can emit it. fancy-term owns the *selected-shell state + UI + events*; the
 * `command` / `args` / `cwd` fields are **host hints** — fancy-term never spawns a
 * shell, the host reconnects its PTY/command backend to the chosen profile.
 */
export interface ShellProfile {
  /** Stable key, e.g. `"powershell"`. */
  id: string;
  /** Display label, e.g. `"PowerShell"`. */
  label: string;
  /** Optional short glyph / emoji / single char (kept JSON-friendly — no ReactNode). */
  icon?: string;
  /** Host hint — the executable, e.g. `"pwsh"` / `"cmd.exe"`. */
  command?: string;
  /** Host hint — launch args. */
  args?: string[];
  /** Host hint — working directory. */
  cwd?: string;
}

/**
 * Imperative handle exposed via the `<Terminal>` ref and returned by
 * {@link useTerminal}. The same surface an MCP bridge drives so an embedded
 * agent reads the buffer + writes input without DOM-scraping.
 */
export interface TerminalHandle {
  /** The underlying xterm.js instance — escape hatch for addons / advanced use. Null before mount. */
  readonly xterm: XTerm | null;
  /**
   * Resolves with the xterm instance once it's opened + measured. Because
   * `xterm` is null until the container lays out, a consumer that must wire an
   * addon can `await handle.ready` instead of polling. Re-armed if the terminal
   * is torn down + recreated (e.g. a container change).
   */
  readonly ready: Promise<XTerm>;
  /** Write raw data (ANSI escape sequences honored) to the terminal. */
  write: (data: string) => void;
  /** Write data followed by CRLF. */
  writeln: (data: string) => void;
  /** Clear the viewport (keeps scrollback). */
  clear: () => void;
  /** Full reset — clears scrollback + terminal state. */
  reset: () => void;
  /** Re-fit to the container (no-op when the box is 0-size or fit is off). */
  fit: () => void;
  /** Focus the terminal input. */
  focus: () => void;
  /** The full buffer as plain text — what an agent "sees". */
  getBuffer: () => string;
  /** The current text selection, or "" when nothing is selected. */
  getSelection: () => string;
  /** Copy the current selection to the system clipboard. Resolves false when there's nothing selected or the clipboard is unavailable. */
  copySelection: () => Promise<boolean>;
  /** Paste text into the terminal. With no argument, reads the system clipboard. Honors xterm's bracketed-paste mode. */
  paste: (text?: string) => Promise<void>;
  /** Select the entire buffer. */
  selectAll: () => void;
  /** Clear the current selection. */
  clearSelection: () => void;
  /**
   * Switch the active shell by id. Resolves the matching {@link ShellProfile}
   * from `shells` and fires `onShellChange`; in uncontrolled mode it also updates
   * the internal selection. No-op when the id isn't in `shells`.
   */
  setShell: (id: string) => void;
  /** The active shell id, or `undefined` when no shell is selected. */
  getShell: () => string | undefined;
}

/** Engine options shared by `<Terminal>` and {@link useTerminal}. */
export interface TerminalOptions {
  /** xterm color theme. Omit for the built-in Fancy dark theme. */
  theme?: TerminalTheme;
  /** Fixed grid size. Omit + leave `fit` on to size from the container. */
  rows?: number;
  cols?: number;
  /** Auto-fit to the container via the fit addon + ResizeObserver. Default true. */
  fit?: boolean;
  /** Block stdin (display-only terminal). Default false. */
  readOnly?: boolean;
  /** Blink the cursor. Default true. */
  cursorBlink?: boolean;
  /** Cursor shape. Default "block". */
  cursorStyle?: CursorStyle;
  /** Monospace font stack. */
  fontFamily?: string;
  /** Font size in px. Default 13. */
  fontSize?: number;
  /** Scrollback lines. Default 1000. */
  scrollback?: number;
  /** Data written once on mount, before any controlled `output`. */
  initialOutput?: string;
  /** User keystrokes / paste data (xterm `onData`). Wire to your PTY/command backend. */
  onData?: (data: string) => void;
  /** Notified on terminal resize. */
  onResize?: (size: { cols: number; rows: number }) => void;
  /**
   * Clipboard wiring — gates the Ctrl+Shift+C / Cmd+C copy chord, the paste
   * interceptor ({@link onPaste}), the context-menu copy/paste, and OSC 52.
   *
   * - `true` / omitted — enabled, backed by `navigator.clipboard`.
   * - `false` — disabled (no copy chord / OSC 52; native text paste still works).
   * - a `{ writeText, readText }` **provider** — every copy/paste path routes
   *   through it. Supply this in a sandboxed Electron renderer, where
   *   `navigator.clipboard` silently no-ops, to bridge to the main-process
   *   clipboard over IPC.
   */
  clipboard?: ClipboardOption;
  /**
   * OSC 52 clipboard policy — lets terminal programs (Claude Code, tmux, vim)
   * set/read the system clipboard via `ESC ] 52`. `"copy"` (default) allows
   * writes only; `"read"` / `"both"` also answer read requests (an exfiltration
   * risk — opt in deliberately); `false` disables it. Routed through the same
   * clipboard provider as {@link clipboard}; a no-op when clipboard is `false`.
   * Default `"copy"`.
   */
  osc52?: Osc52Mode;
  /**
   * Copy/paste UX convention: `"contextmenu"` (menu + Ctrl+Shift+C),
   * `"linux"` (highlight-to-copy + middle-click paste), or `"winmac"`
   * (Ctrl/Cmd+C copies the selection, Ctrl/Cmd+V pastes). Omit for the historical
   * default (Ctrl+Shift+C + Cmd+C-with-selection). Ctrl+Shift+C always copies.
   */
  copyPaste?: CopyPasteMode;
  /**
   * Called once the xterm instance is opened + attached — the imperative twin of
   * {@link TerminalHandle.ready}. Use it to load an addon without racing the
   * container layout (where `handle.xterm` is still null).
   */
  onReady?: (xterm: XTerm) => void;
  /**
   * Fired on every paste with the clipboard payload — `{ text, files, images }`.
   * Plain text still pastes into the terminal natively; this is where a host
   * receives pasted **images** (a shell can't render them) to upload / hand to an
   * agent / write a path. Return `false` to fully consume the paste (suppress the
   * default text paste — e.g. to transform it, then call `handle.paste(...)`).
   */
  onPaste?: (payload: ClipboardPayload) => void | boolean;
  /**
   * Makes http(s) URLs in the output clickable — underlined on hover, with a
   * pointer cursor — and calls this with the URL on click. A URL that wraps
   * across rows is one link. **fancy-term opens nothing itself**: what a click
   * does (open a browser, a panel, nothing) is the host's decision. Omit it and
   * URLs are plain text, as before.
   */
  onLinkActivate?: (url: string, event: MouseEvent) => void;
  /**
   * Which links are clickable, and where each kind of click goes — the
   * developer's choice, per kind:
   *
   * ```tsx
   * links={{
   *   url: "browser",                 // or "none", or (url, event) => …
   *   file: "vscode",                 // "cursor" | "windsurf" | "vscode-insiders" | "none"
   *                                   // | { template: "https://github.com/o/r/blob/main/{path}#L{line}" }
   *                                   // | (file, event) => openInMyViewer(file.absolutePath, file.line)
   *   root: "/home/me/project",       // the shell's cwd, to resolve relative paths
   * }}
   * ```
   *
   * File links cover compiler, test and stack-trace output — `src/a.ts:42:7`,
   * `C:\x\a.cs(12,5)` — and are linked only with a directory part or a line
   * number, so ordinary words are never underlined. Omit `links` (and
   * `onLinkActivate`) and nothing is linked. `links.url` wins over `onLinkActivate`.
   */
  links?: TerminalLinks;
}

export interface TerminalProps extends TerminalOptions, Omit<HTMLAttributes<HTMLDivElement>, "onInput" | "onResize" | "onPaste" | "contextMenu" | "children"> {
  /**
   * The controlled output buffer. The component diffs against the previous value
   * and writes only the appended delta, so a host can drive the terminal from
   * React state — e.g. streaming command output via fancy-query's
   * `useFancyStream`. Replacing it with a non-extending string resets + rewrites.
   */
  output?: string;

  /**
   * The shells / profiles a host offers. fancy-term renders the selector and
   * tracks the choice; the host reacts (reconnects its PTY to the chosen shell).
   * Spread {@link BUILTIN_SHELLS} for sensible presets, but the host owns the list.
   */
  shells?: ShellProfile[];
  /** Controlled active-shell id. Omit for uncontrolled (internal) selection. */
  activeShell?: string;
  /** Fired when the user (or `setShell`) switches shells. */
  onShellChange?: (id: string, profile: ShellProfile) => void;
  /**
   * Render the built-in `<ShellSwitcher>` toolbar above the xterm surface when
   * `shells` is provided. Default `false` — opt-in so existing layout is unchanged.
   */
  showShellBar?: boolean;

  /**
   * The right-click selection context menu. `false` disables it; `true` / omitted
   * gives the default Copy / Paste / Select all / Clear menu; an array replaces
   * the items; a `(ctx, defaults) => items` function lets you add/remove/reorder
   * (e.g. append a "Send to agent" item). See {@link TerminalContextMenuConfig}.
   */
  contextMenu?: TerminalContextMenuConfig;
}

/**
 * Resolve a shell id to its {@link ShellProfile} within a list. Pure helper —
 * the single place `setShell` / `<ShellSwitcher>` / the session hook agree on
 * what "switch to id X" means.
 */
export function resolveShell(
  shells: ShellProfile[] | undefined,
  id: string | undefined,
): ShellProfile | undefined {
  if (!shells || id === undefined) return undefined;
  return shells.find((s) => s.id === id);
}

/**
 * A small set of sensible built-in shell presets a host can spread / filter.
 * `command` / `args` are host hints only — fancy-term never spawns them.
 */
export const BUILTIN_SHELLS: readonly ShellProfile[] = [
  { id: "cmd", label: "Command Prompt", icon: ">_", command: "cmd.exe" },
  { id: "powershell", label: "Windows PowerShell", icon: "PS", command: "powershell.exe" },
  { id: "pwsh", label: "PowerShell", icon: "PS", command: "pwsh" },
  {
    id: "git-bash",
    label: "Git Bash",
    icon: "",
    command: "C:\\Program Files\\Git\\bin\\bash.exe",
    args: ["--login", "-i"],
  },
  { id: "bash", label: "Bash", icon: "$", command: "bash" },
  { id: "zsh", label: "Zsh", icon: "%", command: "zsh" },
] as const;

// menu-position.ts — clamp a fixed-position menu so it never spills off-screen.
// Pure helper (unit-testable); the component measures its own rect and applies it.

export interface MenuPoint {
  x: number;
  y: number;
}
export interface MenuSize {
  width: number;
  height: number;
}

/**
 * Clamp a menu's top-left so the whole menu stays inside the viewport (minus a
 * margin). Pushes left/up when it would overflow the right/bottom edge, and never
 * goes past the top-left margin. Pure.
 */
export function clampMenuPosition(
  at: MenuPoint,
  menu: MenuSize,
  viewport: MenuSize,
  margin = 8,
): MenuPoint {
  const maxX = Math.max(margin, viewport.width - menu.width - margin);
  const maxY = Math.max(margin, viewport.height - menu.height - margin);
  return {
    x: Math.min(Math.max(margin, at.x), maxX),
    y: Math.min(Math.max(margin, at.y), maxY),
  };
}

import { useEffect, useRef, type RefObject } from "react";

/**
 * Run `fit` whenever the container resizes — and once it first has a real,
 * non-zero box. Guards the hidden-tab / late-mount 0×0 case: fitting a collapsed
 * container yields garbage rows/cols (or throws), so we simply skip until there
 * is layout to measure.
 */
export function useTerminalFit(
  ref: RefObject<HTMLElement | null>,
  fit: () => void,
  enabled = true,
): void {
  const fitRef = useRef(fit);
  fitRef.current = fit;

  useEffect(() => {
    if (!enabled) return;
    const el = ref.current;
    if (!el) return;

    const run = () => {
      if (el.clientWidth > 0 && el.clientHeight > 0) fitRef.current();
    };

    const observer = new ResizeObserver(run);
    observer.observe(el);
    run(); // initial — fires once the box has layout

    return () => observer.disconnect();
  }, [ref, enabled]);
}

// copy-paste-mode.ts — the pure decision layer for the `copyPaste` prop. Kept
// DOM-free (like copy-keybinding.ts / shell-select.ts) so the behavior is
// unit-testable without a live xterm. use-terminal.ts wires the resulting
// behavior to real events.

/**
 * The copy/paste convention the terminal follows:
 * - `contextmenu` — copy/paste via the right-click menu only (plus the always-on
 *   Ctrl+Shift+C copy chord).
 * - `linux` — highlight-to-copy (X11 primary-selection style) + middle-click
 *   paste. Right-click still opens the context menu.
 * - `winmac` — Ctrl/Cmd+C copies the selection (falling back to SIGINT when
 *   nothing is selected), Ctrl/Cmd+V pastes.
 *
 * Omitting the prop keeps the historical default: the Ctrl+Shift+C chord and
 * Cmd+C-with-selection, no auto-copy, no mouse paste.
 */
export type CopyPasteMode = "contextmenu" | "linux" | "winmac";

/** The resolved, event-agnostic behavior flags a {@link CopyPasteMode} implies. */
export interface CopyPasteBehavior {
  /** Auto-copy the selection to the clipboard as soon as it changes (linux). */
  selectToCopy: boolean;
  /** Paste on middle-mouse-button (linux). */
  middleClickPaste: boolean;
  /** (Ctrl|Cmd)+C copies the selection when one exists (winmac). */
  keyCopy: boolean;
  /** (Ctrl|Cmd)+V — and Ctrl+Shift+V — paste (winmac). */
  keyPaste: boolean;
}

export function copyPasteBehavior(mode: CopyPasteMode | undefined): CopyPasteBehavior {
  switch (mode) {
    case "linux":
      return { selectToCopy: true, middleClickPaste: true, keyCopy: false, keyPaste: false };
    case "winmac":
      return { selectToCopy: false, middleClickPaste: false, keyCopy: true, keyPaste: true };
    case "contextmenu":
    default:
      return { selectToCopy: false, middleClickPaste: false, keyCopy: false, keyPaste: false };
  }
}

/** The subset of a KeyboardEvent the copy/paste decision reads. */
export interface KeyEventLike {
  type: string;
  key: string;
  ctrlKey: boolean;
  shiftKey: boolean;
  metaKey: boolean;
}

/**
 * Resolve a key event to a clipboard action, given the current selection state
 * and the active behavior. Returns `"copy"`, `"paste"`, or `null` (do nothing —
 * let the byte reach the shell). Only fires on `keydown`.
 *
 * Copy is honored across every mode for the terminal-safe **Ctrl+Shift+C** chord
 * and macOS **Cmd+C-with-selection**; `keyCopy` adds plain (Ctrl|Cmd)+C. Plain
 * Ctrl+C with no selection is never a copy — it stays SIGINT.
 */
export function resolveKeyAction(
  e: KeyEventLike,
  hasSelection: boolean,
  behavior: CopyPasteBehavior,
): "copy" | "paste" | null {
  if (e.type !== "keydown") return null;
  const key = e.key.toLowerCase();

  if (key === "c") {
    if (e.ctrlKey && e.shiftKey && !e.metaKey) return "copy"; // Ctrl+Shift+C — always
    if (e.metaKey && !e.ctrlKey && hasSelection) return "copy"; // Cmd+C w/ selection — always (macOS)
    if (behavior.keyCopy && (e.ctrlKey || e.metaKey) && !e.shiftKey && hasSelection) return "copy";
    return null;
  }

  if (key === "v" && behavior.keyPaste) {
    if ((e.ctrlKey || e.metaKey) && !e.shiftKey) return "paste"; // Ctrl/Cmd+V
    if (e.ctrlKey && e.shiftKey) return "paste"; // Ctrl+Shift+V (terminal-safe paste)
    return null;
  }

  return null;
}

// osc52.ts — OSC 52 clipboard handling. Modern TUIs (Claude Code, tmux, vim /
// neovim) copy their own selection with `ESC ] 52 ; <Pc> ; <Pd> BEL`. xterm.js
// drops OSC 52 by default, so a program shows "copied" but nothing reaches the
// system clipboard — a silent, confusing failure. We parse the sequence and
// route it through the injectable clipboard provider.
//
// The parse + base64 codec are pure so they're unit-testable without a live
// xterm; registerOsc52 wires them to an xterm instance.

import type { Terminal as XTerm } from "@xterm/xterm";
import type { IDisposable } from "@xterm/xterm";
import type { ClipboardProvider } from "./clipboard";
import { providerRead } from "./clipboard";

/**
 * OSC 52 policy: `copy` allows programs to WRITE the clipboard (the common TUI
 * case), `read` allows a program to READ it back (a `?` request), `both` allows
 * either, `false` disables OSC 52 entirely. Read is the real exfiltration risk
 * (arbitrary terminal output could siphon your clipboard), so it must be opted
 * into explicitly.
 */
export type Osc52Mode = "copy" | "read" | "both" | false;

/** A parsed OSC 52 request: which selection buffer, and write-a-payload vs read-request. */
export interface Osc52Request {
  /** The `Pc` field — clipboard selection(s), e.g. `"c"` (clipboard), `"p"` (primary). */
  selection: string;
  kind: "write" | "read";
  /** Decoded text for a write; `""` for a read request. */
  data: string;
}

/** UTF-8-safe base64 encode (browser `btoa` operates on binary strings). */
export function encodeBase64(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binary = "";
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return typeof btoa === "function" ? btoa(binary) : binary;
}

/** UTF-8-safe base64 decode; returns `""` on malformed input. */
export function decodeBase64(b64: string): string {
  try {
    const binary = typeof atob === "function" ? atob(b64) : b64;
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return new TextDecoder().decode(bytes);
  } catch {
    return "";
  }
}

/**
 * Parse an OSC 52 payload (the part after `ESC ] 52 ;`, i.e. `<Pc> ; <Pd>`).
 * `Pd === "?"` is a read request; otherwise `Pd` is base64 to write. Returns
 * `null` for a malformed payload (no `;`).
 */
export function parseOsc52(payload: string): Osc52Request | null {
  const semi = payload.indexOf(";");
  if (semi < 0) return null;
  const selection = payload.slice(0, semi);
  const pd = payload.slice(semi + 1);
  if (pd === "?") return { selection, kind: "read", data: "" };
  return { selection, kind: "write", data: decodeBase64(pd) };
}

/** Build the OSC 52 response a `read` request expects: `ESC ] 52 ; <Pc> ; <base64> BEL`. */
export function osc52Response(selection: string, text: string): string {
  return `\x1b]52;${selection};${encodeBase64(text)}\x07`;
}

/**
 * Register an OSC 52 handler on an xterm instance, routing writes/reads through
 * `provider` per `mode`. Returns the {@link IDisposable} (or `null` when
 * `mode === false`). The handler always returns `true` (consumed) so a
 * disallowed direction is swallowed rather than echoed as garbage.
 */
export function registerOsc52(
  term: XTerm,
  provider: () => ClipboardProvider,
  mode: () => Osc52Mode,
): IDisposable | null {
  if (mode() === false) return null;

  return term.parser.registerOscHandler(52, (payload) => {
    const m = mode();
    if (m === false) return true;
    const req = parseOsc52(payload);
    if (!req) return false; // not ours / malformed — let xterm handle it

    if (req.kind === "write") {
      if (m === "copy" || m === "both") {
        void Promise.resolve(provider().writeText(req.data)).catch(() => {});
      }
      return true;
    }

    // read request (`?`)
    if (m === "read" || m === "both") {
      void providerRead(provider()).then((text) => {
        term.write(osc52Response(req.selection, text));
      });
    }
    return true;
  });
}

// links.ts — clickable URLs in terminal output.
//
// xterm.js has a link-provider API in its core but detects nothing on its own;
// the official web-links addon is a separate third-party package. Detection is
// small, so it lives here: `findUrls` is pure (testable without a terminal) and
// `urlLinkProvider` maps its matches onto buffer cells, joining a line that
// wrapped across rows so a long URL is one link, not two halves.
//
// fancy-term never opens anything itself. Activation is the host's: Genie opens
// http(s) with its shell; another host may open a panel, or refuse.

import type { IBufferCell, IDisposable, ILink, ILinkProvider, Terminal as XTerm } from "@xterm/xterm";

/** A URL found in a string: `start` inclusive, `end` exclusive (string indices). */
export interface UrlMatch {
  url: string;
  start: number;
  end: number;
}

// http(s), then everything up to whitespace or a character that cannot end a URL
// in running text. Trailing punctuation is trimmed afterwards, not here, so a
// closing bracket can be kept when the URL itself opened one.
const URL_PATTERN = /https?:\/\/[^\s<>"'`]+/g;

/** Characters that end a sentence, not a URL: "see https://example.com." */
const TRAILING = ".,;:!?";

/** Drop trailing punctuation, and a closing bracket the URL did not open. */
function trimUrl(raw: string): string {
  let url = raw;
  for (;;) {
    const last = url[url.length - 1];
    if (last === undefined) return url;
    if (TRAILING.includes(last)) {
      url = url.slice(0, -1);
      continue;
    }
    const pairs: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
    const open = pairs[last];
    if (open) {
      const opened = url.split(open).length - 1;
      const closed = url.split(last).length - 1;
      if (closed > opened) {
        url = url.slice(0, -1);
        continue;
      }
    }
    return url;
  }
}

/** Every http(s) URL in `text`, in order. */
export function findUrls(text: string): UrlMatch[] {
  const out: UrlMatch[] = [];
  for (const match of text.matchAll(URL_PATTERN)) {
    const start = match.index ?? 0;
    const url = trimUrl(match[0]);
    // "https://" alone is not a link.
    if (url.length <= url.indexOf("//") + 2) continue;
    out.push({ url, start, end: start + url.length });
  }
  return out;
}

/** A file reference found in a string: where it is, and what to open. */
export interface FileMatch {
  /** The path as printed (relative paths are the host's to resolve: it knows the cwd). */
  path: string;
  /** 1-based line, when the output gave one (`:42`, `(42,7)`). */
  line?: number;
  /** 1-based column, when the output gave one. */
  column?: number;
  /** What was matched, suffix included — `src/app.ts:42:7`. */
  text: string;
  start: number;
  end: number;
}

/** What a file link hands the host on click. */
export interface FileLink {
  path: string;
  line?: number;
  column?: number;
}

// An optional root (drive, ./, ../, ~/, /), directory segments, and a file name
// ending in an extension that starts with a letter (so `1.2.3` is not a file).
// Then an optional `:line[:col]` or `(line,col)` suffix. The lookbehind stops a
// match starting in the middle of a token — inside a URL, an email, a word.
const FILE_PATTERN =
  /(?<![\w.@~/\\:-])((?:[A-Za-z]:[\\/]|\.{1,2}[\\/]|~[\\/]|[\\/])?(?:[\w@+-][\w.@+-]*[\\/])*[\w@+-][\w.@+-]*\.[A-Za-z][A-Za-z0-9]{0,9})(?::(\d+)(?::(\d+))?|\((\d+),(\d+)\))?/g;

/**
 * File references in `text` — compiler errors, stack frames, test output.
 *
 * Linked only with a directory part (`src/a.ts`, `./a.ts`, `C:\x\a.ts`) or a line
 * number (`app.ts:3`). A bare `package.json` or `e.g.` in prose stays plain text:
 * an underline that opens nothing useful is worse than no underline. A path that
 * is part of a URL is never a second link.
 */
export function findFilePaths(text: string): FileMatch[] {
  const urls = findUrls(text);
  const out: FileMatch[] = [];

  for (const match of text.matchAll(FILE_PATTERN)) {
    const start = match.index ?? 0;
    const end = start + match[0].length;
    const path = match[1];
    const lineText = match[2] ?? match[4];
    const columnText = match[3] ?? match[5];

    const hasDirectory = path.includes("/") || path.includes(String.fromCharCode(92));
    if (!hasDirectory && lineText === undefined) continue;
    if (urls.some((u) => start < u.end && end > u.start)) continue;

    out.push({
      path,
      line: lineText === undefined ? undefined : Number(lineText),
      column: columnText === undefined ? undefined : Number(columnText),
      text: match[0],
      start,
      end,
    });
  }
  return out;
}

/** A cell position, 1-based as xterm's link ranges are. */
interface CellPos {
  x: number;
  y: number;
}

/**
 * The logical line containing buffer row `row` (0-based): its first row, and its
 * text with, for every character, the 1-based cell it starts in.
 *
 * Built from cells rather than `translateToString` because a wide character
 * (CJK, many emoji) takes two cells and one string index; mapping by string
 * index would put every link after one in the wrong place.
 */
function logicalLine(xterm: XTerm, row: number): { text: string; cells: CellPos[] } | null {
  const buffer = xterm.buffer.active;
  let first = row;
  while (first > 0 && buffer.getLine(first)?.isWrapped) first--;

  let text = "";
  const cells: CellPos[] = [];
  let reusable: IBufferCell | undefined;

  for (let y = first; ; y++) {
    const line = buffer.getLine(y);
    if (!line) break;
    if (y > first && !line.isWrapped) break;

    for (let x = 0; x < line.length; x++) {
      const cell = line.getCell(x, reusable);
      if (!cell) break;
      reusable = cell;
      // The trailing half of a wide character has width 0 and no chars. Counted
      // as a space it would split a URL that contains one (an IDN host) in two.
      if (cell.getWidth() === 0) continue;
      const chars = cell.getChars() || " ";
      for (let i = 0; i < chars.length; i++) {
        text += chars[i];
        cells.push({ x: x + 1, y: y + 1 });
      }
    }
  }

  return cells.length > 0 ? { text, cells } : null;
}

export interface TerminalLinkOptions {
  /** Called when an http(s) link is clicked. Omit and URLs are not linked. */
  onUrl?: (url: string, event: MouseEvent) => void;
  /** Called when a file link is clicked. Omit and file paths are not linked. */
  onFile?: (file: FileLink, event: MouseEvent) => void;
  /** Underline on hover and a pointer cursor. Default `true`. */
  decorate?: boolean;
}

/**
 * An xterm link provider for http(s) URLs and file references. Each kind is
 * linked only when its handler is given. fancy-term opens nothing itself.
 */
export function terminalLinkProvider(xterm: XTerm, options: TerminalLinkOptions): ILinkProvider {
  const decorations = options.decorate === false ? undefined : { underline: true, pointerCursor: true };
  return {
    provideLinks(bufferLineNumber, callback) {
      if (!options.onUrl && !options.onFile) return callback(undefined);
      const line = logicalLine(xterm, bufferLineNumber - 1);
      if (!line) return callback(undefined);

      const found: Array<{ start: number; end: number; text: string; activate: (e: MouseEvent) => void }> = [];
      if (options.onUrl) {
        const onUrl = options.onUrl;
        for (const m of findUrls(line.text)) {
          found.push({ start: m.start, end: m.end, text: m.url, activate: (e) => onUrl(m.url, e) });
        }
      }
      if (options.onFile) {
        const onFile = options.onFile;
        for (const m of findFilePaths(line.text)) {
          const file: FileLink = { path: m.path };
          if (m.line !== undefined) file.line = m.line;
          if (m.column !== undefined) file.column = m.column;
          found.push({ start: m.start, end: m.end, text: m.text, activate: (e) => onFile(file, e) });
        }
      }
      found.sort((a, b) => a.start - b.start);

      const links: ILink[] = [];
      for (const f of found) {
        const start = line.cells[f.start];
        const end = line.cells[f.end - 1];
        if (!start || !end) continue;
        // Asked per row; report only links that touch this one, or a wrapped link
        // would be reported once for every row it spans.
        if (end.y < bufferLineNumber || start.y > bufferLineNumber) continue;
        links.push({ range: { start, end }, text: f.text, decorations, activate: (event) => f.activate(event) });
      }
      callback(links.length > 0 ? links : undefined);
    },
  };
}

export interface UrlLinkOptions {
  /** Called when a link is clicked. fancy-term opens nothing itself. */
  onActivate: (url: string, event: MouseEvent) => void;
  /** Underline on hover and a pointer cursor. Default `true`. */
  decorate?: boolean;
}

/** An xterm link provider for http(s) URLs only (0.7.0's API). */
export function urlLinkProvider(xterm: XTerm, options: UrlLinkOptions): ILinkProvider {
  return terminalLinkProvider(xterm, { onUrl: options.onActivate, decorate: options.decorate });
}

/** Make http(s) URLs in this terminal clickable. Dispose to remove. */
export function registerUrlLinks(xterm: XTerm, options: UrlLinkOptions): IDisposable {
  return xterm.registerLinkProvider(urlLinkProvider(xterm, options));
}

// ---------------------------------------------------------------------------
// Where a click goes — the developer's choice
// ---------------------------------------------------------------------------

/** Where an http(s) link goes: a new browser tab, nowhere, or your own handler. */
export type UrlLinkTarget = "browser" | "none" | ((url: string, event: MouseEvent) => void);

/**
 * Where a file link goes:
 * - an installed editor, through its URL scheme (`"vscode"`, `"vscode-insiders"`,
 *   `"cursor"`, `"windsurf"`) — these need an absolute path, so set `root`;
 * - `{ template }` — any URL, with `{path}`, `{line}` and `{column}` filled in:
 *   another editor's scheme, or a code host in the browser
 *   (`"https://github.com/org/repo/blob/main/{path}#L{line}"`);
 * - your own handler — open it in your UI, run an action, anything;
 * - `"none"`.
 */
export type FileLinkTarget =
  | "vscode"
  | "vscode-insiders"
  | "cursor"
  | "windsurf"
  | "none"
  | { template: string }
  | ((file: FileLink & { absolutePath?: string }, event: MouseEvent) => void);

export interface TerminalLinks {
  /** http(s) links. Omit for no URL links. */
  url?: UrlLinkTarget;
  /** File references. Omit for no file links. */
  file?: FileLinkTarget;
  /**
   * The directory relative paths are relative to — the shell's working
   * directory. Editors need absolute paths; without `root` a relative path is
   * handed over as printed.
   */
  root?: string;
}

const EDITOR_TEMPLATES: Record<string, string> = {
  // VS Code's documented form: vscode://file/c:/project/a.ts:5:4 — one slash
  // before the path, drive or not. Its forks take the same.
  vscode: "vscode://file{slashPath}:{line}:{column}",
  "vscode-insiders": "vscode-insiders://file{slashPath}:{line}:{column}",
  cursor: "cursor://file{slashPath}:{line}:{column}",
  windsurf: "windsurf://file{slashPath}:{line}:{column}",
};

const BACKSLASH = String.fromCharCode(92);

function isAbsolute(path: string): boolean {
  return path.startsWith("/") || path.startsWith(BACKSLASH) || /^[A-Za-z]:[/]/.test(path.split(BACKSLASH).join("/"));
}

/**
 * `path` resolved against `root`, with forward slashes and `.` / `..` collapsed.
 * Absolute paths are kept (only their slashes change); `~` is left for the host,
 * which knows the home directory.
 */
export function resolveFilePath(path: string, root?: string): string {
  const slashed = path.split(BACKSLASH).join("/");
  if (slashed.startsWith("~")) return slashed;
  const joined = isAbsolute(slashed) || !root ? slashed : `${root.split(BACKSLASH).join("/").replace(/[/]+$/, "")}/${slashed}`;

  const leadingSlash = joined.startsWith("/");
  const out: string[] = [];
  for (const part of joined.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === ".." && out.length > 0 && out[out.length - 1] !== ".." && !/^[A-Za-z]:$/.test(out[out.length - 1])) {
      out.pop();
      continue;
    }
    out.push(part);
  }
  return (leadingSlash ? "/" : "") + out.join("/");
}

/**
 * The URL a template-style target opens for `file`. Tokens, URI-encoded:
 *
 * - `{path}` — the resolved path exactly: `/home/me/a.ts`, `C:/w/a.ts`, `src/a.ts`.
 * - `{slashPath}` — the same with exactly ONE leading slash: `/home/me/a.ts`,
 *   `/C:/w/a.ts`. The editor presets use it, matching VS Code's documented form
 *   `vscode://file/c:/project/a.ts:5:4` — `{path}` there would give a Windows
 *   path no slash and a POSIX one two.
 * - `{line}`, `{column}` — default 1.
 */
export function fileLinkUrl(file: FileLink, template: string, root?: string): string {
  const path = resolveFilePath(file.path, root);
  const slashPath = "/" + path.replace(/^[/]+/, "");
  return template
    .split("{slashPath}")
    .join(encodeURI(slashPath))
    .split("{path}")
    .join(encodeURI(path))
    .split("{line}")
    .join(String(file.line ?? 1))
    .split("{column}")
    .join(String(file.column ?? 1));
}

/** Opens a URL outside the page: a new tab for http(s), the OS handler for any other scheme. */
export function openExternal(url: string): void {
  if (typeof document === "undefined") return;
  if (/^https?:/i.test(url)) {
    window.open(url, "_blank", "noopener,noreferrer");
    return;
  }
  // A custom scheme (vscode://…) is handed to the OS; an anchor click does that
  // without leaving a blank tab behind, which window.open would.
  const a = document.createElement("a");
  a.href = url;
  a.rel = "noopener noreferrer";
  a.style.display = "none";
  document.body.appendChild(a);
  a.click();
  a.remove();
}

/**
 * The link handlers a {@link TerminalLinks} config means. `open` is injectable
 * so a host (or a test) can intercept where things go.
 */
export function resolveLinkHandlers(
  links: TerminalLinks | undefined,
  open: (url: string) => void = openExternal,
): Pick<TerminalLinkOptions, "onUrl" | "onFile"> {
  const out: Pick<TerminalLinkOptions, "onUrl" | "onFile"> = {};
  const url = links?.url;
  if (typeof url === "function") out.onUrl = url;
  else if (url === "browser") out.onUrl = (u) => open(u);

  const file = links?.file;
  const root = links?.root;
  if (typeof file === "function") {
    out.onFile = (f, e) => file(root ? { ...f, absolutePath: resolveFilePath(f.path, root) } : f, e);
  } else if (typeof file === "string" && file !== "none") {
    const template = EDITOR_TEMPLATES[file];
    if (template) out.onFile = (f) => open(fileLinkUrl(f, template, root));
  } else if (file && typeof file === "object") {
    const template = file.template;
    out.onFile = (f) => open(fileLinkUrl(f, template, root));
  }
  return out;
}

import { useMemo, useState } from 'react';
import {
    Badge,
    Button,
    Callout,
    Card,
    cn,
    Heading,
    Modal,
    Progress,
    Text,
} from '@particle-academy/react-fancy';
import {
    QuestionRenderer,
    type AnswerValue,
    answerValueToPayload,
} from './QuestionRenderer';
import type { AnswerInput, Test, TestAttempt } from '../lib/types';

export interface TestRunnerProps {
    test: Test;
    onSubmit: (answers: AnswerInput[]) => Promise<TestAttempt>;
    onFinished?: (attempt: TestAttempt) => void;
}

export function TestRunner({ test, onSubmit, onFinished }: TestRunnerProps) {
    const questions = useMemo(() => test.questions ?? [], [test.questions]);
    const [answers, setAnswers] = useState<Record<number, AnswerValue>>({});
    const [submitting, setSubmitting] = useState(false);
    const [result, setResult] = useState<TestAttempt | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [confirmOpen, setConfirmOpen] = useState(false);

    const answeredCount = Object.values(answers).filter(
        (a) => a !== null && a !== undefined,
    ).length;
    const percent = questions.length
        ? Math.round((answeredCount / questions.length) * 100)
        : 0;
    const allAnswered = answeredCount === questions.length && questions.length > 0;

    async function handleSubmit(): Promise<void> {
        setConfirmOpen(false);
        setSubmitting(true);
        setError(null);
        try {
            const payload: AnswerInput[] = questions.map(
                (q) => answerValueToPayload(q.id, answers[q.id] ?? null) as AnswerInput,
            );
            const attempt = await onSubmit(payload);
            setResult(attempt);
            onFinished?.(attempt);
        } catch (e) {
            const message = e instanceof Error ? e.message : String(e);
            setError(message);
        } finally {
            setSubmitting(false);
        }
    }

    if (result) {
        return <TestResult attempt={result} />;
    }

    return (
        <>
            <Card
                variant="outlined"
                padding="none"
                className="!rounded-xl !shadow-sm overflow-hidden"
            >
                <div className="px-6 py-5 border-b border-secondary-200">
                    <div className="flex items-start justify-between gap-4">
                        <div>
                            <Heading as="h1" size="xl" weight="bold">
                                {test.title}
                            </Heading>
                            {test.description && (
                                <Text className="!mt-1" color="muted">
                                    {test.description}
                                </Text>
                            )}
                        </div>
                        <div className="flex flex-col items-end gap-2">
                            {test.is_final && (
                                <Badge color="amber" variant="soft" size="md">
                                    Final exam
                                </Badge>
                            )}
                            <Text size="xs" color="muted">
                                Pass at {test.passing_score}%
                            </Text>
                        </div>
                    </div>

                    <div className="mt-4 grid gap-1.5">
                        <Progress
                            value={percent}
                            max={100}
                            color="red"
                            size="sm"
                        />
                        <div className="flex items-center justify-between">
                            <Text size="xs" color="muted">
                                {answeredCount} of {questions.length} answered
                            </Text>
                            <Text size="xs" weight="semibold" className="!text-brand">
                                {percent}%
                            </Text>
                        </div>
                    </div>
                </div>

                <div className="px-6 py-6 grid gap-5">
                    {questions.map((q, i) => (
                        <Card
                            key={q.id}
                            variant="outlined"
                            padding="md"
                            className="!rounded-lg"
                        >
                            <div className="flex items-center justify-between mb-3">
                                <Text size="xs" weight="semibold" className="uppercase tracking-wide" color="muted">
                                    Question {i + 1} of {questions.length}
                                </Text>
                                <Badge color="zinc" variant="soft" size="sm">
                                    {q.points} pt{q.points === 1 ? '' : 's'}
                                </Badge>
                            </div>
                            <QuestionRenderer
                                question={q}
                                value={answers[q.id] ?? null}
                                onChange={(next) =>
                                    setAnswers((prev) => ({ ...prev, [q.id]: next }))
                                }
                            />
                        </Card>
                    ))}
                </div>

                {error && (
                    <div className="px-6 pb-4">
                        <Callout color="red">{error}</Callout>
                    </div>
                )}

                <div className="px-6 py-4 border-t border-secondary-200 bg-secondary-50/50 flex items-center justify-between gap-3">
                    <Text size="sm" color="muted">
                        {allAnswered
                            ? "You've answered every question."
                            : `${questions.length - answeredCount} question${questions.length - answeredCount === 1 ? '' : 's'} remaining`}
                    </Text>
                    <Button
                        loading={submitting}
                        disabled={submitting || answeredCount === 0}
                        onClick={() => setConfirmOpen(true)}
                        className="!bg-brand hover:!bg-primary-600 disabled: !text-white !font-semibold !px-6 !py-2.5 !rounded-md !shadow-sm"
                    >
                        {submitting ? 'Submitting…' : 'Submit test'}
                    </Button>
                </div>
            </Card>

            <Modal open={confirmOpen} onClose={() => setConfirmOpen(false)} size="sm">
                <Card variant="flat" padding="lg">
                    <Heading as="h2" size="lg" weight="bold">
                        Submit your answers?
                    </Heading>
                    <Text color="muted" className="!mt-2">
                        {allAnswered
                            ? `You've answered all ${questions.length} questions. You can't change your answers after submitting.`
                            : `You have ${questions.length - answeredCount} unanswered question${questions.length - answeredCount === 1 ? '' : 's'}. Unanswered questions count as zero.`}
                    </Text>
                    <div className="mt-6 flex justify-end gap-3">
                        <Button
                            variant="ghost"
                            onClick={() => setConfirmOpen(false)}
                            className="hover:!text-brand !px-4 !py-2"
                        >
                            Keep working
                        </Button>
                        <Button
                            onClick={handleSubmit}
                            className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-5 !py-2 !rounded-md"
                        >
                            Submit
                        </Button>
                    </div>
                </Card>
            </Modal>
        </>
    );
}

function TestResult({ attempt }: { attempt: TestAttempt }) {
    const passed = attempt.passed === true;
    const pending = attempt.passed === null;
    const score = attempt.score !== null ? Number(attempt.score) : null;

    return (
        <Card
            variant="outlined"
            padding="none"
            className="!rounded-xl !shadow-sm overflow-hidden"
        >
            <div
                className={cn(
                    'px-6 py-5',
                    pending
                            ? 'bg-blue-50 dark:bg-blue-950/40'
                            : passed
                              ? 'bg-emerald-50 dark:bg-emerald-950/40'
                              : 'bg-red-50 dark:bg-red-950/40',
                )}
            >
                <div className="flex items-center gap-3">
                    <div
                        className={cn(
                            'flex h-12 w-12 items-center justify-center rounded-full text-xl font-bold',
                            pending
                                ? 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200'
                                : passed
                                ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-200'
                                : 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200',
                        )}
                    >
                        {pending ? '…' : passed ? '✓' : '✕'}
                    </div>
                    <div>
                        <Heading as="h2" size="xl" weight="bold">
                            {pending ? 'Awaiting grading' : passed ? 'You passed!' : 'Did not pass'}
                        </Heading>
                        <Text className="!mt-0.5" color="muted">
                            {pending
                                ? 'Some answers require manual review.'
                                : passed
                                ? 'Nice work. Your certificate is being issued.'
                                : 'Review the material and try again.'}
                        </Text>
                    </div>
                </div>
            </div>

            <div className="px-6 py-5 grid sm:grid-cols-3 gap-4">
                <Stat label="Score" value={score !== null ? `${score}%` : '—'} highlight />
                <Stat
                    label="Points awarded"
                    value={
                        attempt.points_awarded !== null && attempt.max_score !== null
                            ? `${attempt.points_awarded} / ${attempt.max_score}`
                            : '—'
                    }
                />
                <Stat label="Attempt" value={`#${attempt.attempt_number}`} />
            </div>
        </Card>
    );
}

function Stat({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
    return (
        <div className="rounded-lg border border-secondary-200 bg-secondary-50/50 px-4 py-3">
            <Text size="xs" weight="semibold" className="uppercase tracking-wide" color="muted">
                {label}
            </Text>
            <div
                className={cn(
                    'mt-1 text-2xl font-bold',
                    highlight ? 'text-brand' : 'text-secondary-900',
                )}
            >
                {value}
            </div>
        </div>
    );
}

import {
    CheckboxGroup,
    RadioGroup,
    Text,
    Textarea,
} from '@particle-academy/react-fancy';
import type { Question } from '../lib/types';

export type AnswerValue =
    | { kind: 'option_id'; value: number }
    | { kind: 'option_ids'; value: number[] }
    | { kind: 'text'; value: string }
    | null;

export interface QuestionRendererProps {
    question: Question;
    value: AnswerValue;
    onChange: (next: AnswerValue) => void;
    disabled?: boolean;
}

export function QuestionRenderer({
    question,
    value,
    onChange,
    disabled,
}: QuestionRendererProps) {
    const options = question.options ?? [];

    if (question.type === 'multiple_choice' || question.type === 'true_false') {
        const selected =
            value?.kind === 'option_id' ? String(value.value) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <RadioGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_id', value: Number(next) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    if (question.type === 'multiple_select') {
        const selected =
            value?.kind === 'option_ids' ? value.value.map(String) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <Text size="sm" color="muted">
                    Select all that apply.
                </Text>
                <CheckboxGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_ids', value: next.map(Number) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    // short_answer
    const text = value?.kind === 'text' ? value.value : '';
    return (
        <div className="grid gap-3">
            <Text weight="semibold" className="!text-base">
                {question.prompt}
            </Text>
            <Textarea
                value={text}
                onChange={(e) =>
                    onChange({
                        kind: 'text',
                        value: (e.target as HTMLTextAreaElement).value,
                    })
                }
                disabled={disabled}
                rows={4}
                placeholder="Type your answer here…"
            />
        </div>
    );
}

export function answerValueToPayload(
    questionId: number,
    value: AnswerValue,
): { question_id: number; answer: unknown } {
    if (!value) return { question_id: questionId, answer: null };
    switch (value.kind) {
        case 'option_id':
            return { question_id: questionId, answer: { option_id: value.value } };
        case 'option_ids':
            return { question_id: questionId, answer: { option_ids: value.value } };
        case 'text':
            return { question_id: questionId, answer: { text: value.value } };
    }
}

