export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(
  (
    {
      size = "md",
      dirty,
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      autoResize,
      minRows = 3,
      maxRows,
      prefix,
      suffix,
      prefixPosition: _prefixPosition,
      suffixPosition: _suffixPosition,
      mode,
      onValueChange,
      onChange,
      value,
      defaultValue,
      ...props
    },
    ref,
  ) => {
    const autoId = useId();
    const textareaId = id ?? autoId;
    const internalRef = useRef<HTMLTextAreaElement | null>(null);
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);

    useEffect(() => {
      const el = internalRef.current;
      if (!autoResize || !el) return;
      el.style.height = "auto";
      const lineHeight = parseInt(getComputedStyle(el).lineHeight) || 20;
      const minHeight = minRows * lineHeight;
      const maxHeight = maxRows ? maxRows * lineHeight : Infinity;
      el.style.height = `${Math.min(Math.max(el.scrollHeight, minHeight), maxHeight)}px`;
    }, [autoResize, minRows, maxRows, value, defaultValue]);

    const textarea = !showControl ? (
      <DisplayValue
        size={size}
        className="whitespace-pre-wrap"
        interactive={interactive}
        onActivate={enterEdit}
      >
        {(value ?? defaultValue) as string | undefined}
      </DisplayValue>
    ) : (
      <InputWrapper
        prefix={prefix}
        suffix={suffix}
        prefixPosition="outside"
        suffixPosition="outside"
        size={size}
      >
        <textarea
          data-react-fancy-textarea=""
          ref={(node) => {
            internalRef.current = node;
            if (typeof ref === "function") {
              ref(node);
            } else if (ref) {
              ref.current = node;
            }
          }}
          id={textareaId}
          disabled={disabled}
          required={required}
          rows={autoResize ? minRows : minRows}
          value={value}
          defaultValue={defaultValue}
          className={cn(
            inputBaseClasses,
            inputSizeClasses[size],
            dirtyClasses(dirty),
            errorClasses(error),
            "w-full resize-y",
            autoResize && "resize-none overflow-hidden",
            className,
          )}
          onChange={(e) => {
            onChange?.(e);
            onValueChange?.(e.target.value);
          }}
          {...props}
          autoFocus={interactive || props.autoFocus}
          onBlur={(e) => {
            props.onBlur?.(e);
            if (interactive) exitEdit();
          }}
        />
      </InputWrapper>
    );

    if (label || error || description) {
      return (
        <Field
          label={label}
          labelHidden={labelHidden}
          description={description}
          error={error}
          required={required}
          htmlFor={textareaId}
          size={size}
        >
          {textarea}
        </Field>
      );
    }

    return textarea;
  },
);

