import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import { useCallback, useEffect, useState, type RefObject } from "react";
import type { Placement } from "../utils/types";

interface FloatingPosition {
  x: number;
  y: number;
  placement: Placement;
}

interface UseFloatingPositionOptions {
  placement?: Placement;
  offset?: number;
  enabled?: boolean;
}

function getPosition(
  anchor: DOMRect,
  floating: DOMRect,
  placement: Placement,
  offset: number,
): FloatingPosition {
  let x = 0;
  let y = 0;
  const base = placement.split("-")[0] as "top" | "bottom" | "left" | "right";
  const align = placement.split("-")[1] as "start" | "end" | undefined;

  switch (base) {
    case "top":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.top - floating.height - offset;
      break;
    case "bottom":
      x = anchor.left + anchor.width / 2 - floating.width / 2;
      y = anchor.bottom + offset;
      break;
    case "left":
      x = anchor.left - floating.width - offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
    case "right":
      x = anchor.right + offset;
      y = anchor.top + anchor.height / 2 - floating.height / 2;
      break;
  }

  if (base === "top" || base === "bottom") {
    if (align === "start") x = anchor.left;
    else if (align === "end") x = anchor.right - floating.width;
  }

  if (base === "left" || base === "right") {
    if (align === "start") y = anchor.top;
    else if (align === "end") y = anchor.bottom - floating.height;
  }

  // Viewport clamping
  let finalPlacement = placement;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  if (base === "bottom" && y + floating.height > vh) {
    y = anchor.top - floating.height - offset;
    finalPlacement = placement.replace("bottom", "top") as Placement;
  } else if (base === "top" && y < 0) {
    y = anchor.bottom + offset;
    finalPlacement = placement.replace("top", "bottom") as Placement;
  }

  x = Math.max(4, Math.min(x, vw - floating.width - 4));
  y = Math.max(4, Math.min(y, vh - floating.height - 4));

  return { x, y, placement: finalPlacement };
}

export function useFloatingPosition(
  anchorRef: RefObject<HTMLElement | null>,
  floatingRef: RefObject<HTMLElement | null>,
  options: UseFloatingPositionOptions = {},
): FloatingPosition {
  const { placement = "bottom", offset = 8, enabled = true } = options;
  const [position, setPosition] = useState<FloatingPosition>({
    x: -9999,
    y: -9999,
    placement,
  });

  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const floating = floatingRef.current;
    if (!anchor || !floating) return;

    const anchorRect = anchor.getBoundingClientRect();
    const floatingRect = floating.getBoundingClientRect();
    const next = getPosition(anchorRect, floatingRect, placement, offset);
    // Bail out when nothing changed so this can run after every commit
    // (below) without causing an infinite render loop.
    setPosition((prev) =>
      prev.x === next.x && prev.y === next.y && prev.placement === next.placement
        ? prev
        : next,
    );
  }, [anchorRef, floatingRef, placement, offset]);

  // Re-measure after every commit while open.
  //
  // The floating element mounts a frame or two AFTER `enabled` flips — its
  // render is gated behind a state flip (e.g. useAnimation's `mounted`), so at
  // the moment `enabled` turns true the floating ref is still null and a single
  // measurement no-ops, leaving the popover parked at its off-screen sentinel.
  //
  // A passive effect with no deps runs after *every* commit — including the one
  // that finally mounts the floating element — and, crucially, keeps running in
  // hidden/background tabs where `requestAnimationFrame` is paused. The bail-out
  // in `update` makes the steady-state calls free, so this both fixes the
  // late-mount race and survives tab-visibility throttling.
  useEffect(() => {
    if (enabled) update();
  });

  // …but the per-commit effect ISN'T enough when the floating element mounts
  // through a <Portal> whose own mount gate (SSR-safe; renders nothing until its
  // useEffect runs) attaches the node WITHOUT re-rendering this hook's component.
  // Then no commit happens here, the measurement never runs, and the popover
  // stays parked at its off-screen sentinel until an unrelated scroll/resize
  // fires `update()` — the "menu only appears after I scroll" bug. Poll with rAF
  // until the node is actually in the DOM, measure it, then keep it observed for
  // size changes (async content / lazily-loaded icons).
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    let ro: ResizeObserver | null = null;
    const tick = () => {
      const el = floatingRef.current;
      if (el) {
        update();
        if (typeof ResizeObserver !== "undefined") {
          ro = new ResizeObserver(() => update());
          ro.observe(el);
        }
      } else {
        raf = requestAnimationFrame(tick);
      }
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      ro?.disconnect();
    };
  }, [enabled, update, floatingRef]);

  // Park off-screen when closed so the next open re-measures from scratch.
  useEffect(() => {
    if (!enabled) {
      setPosition((prev) =>
        prev.x === -9999 ? prev : { x: -9999, y: -9999, placement },
      );
    }
  }, [enabled, placement]);

  // Reposition on scroll/resize while open.
  useEffect(() => {
    if (!enabled) return;

    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);

    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [update, enabled]);

  return position;
}

import { createContext, useContext } from "react";
import type { TreeNavContextValue } from "./TreeNav.types";

export const TreeNavContext = createContext<TreeNavContextValue | null>(null);

export function useTreeNav(): TreeNavContextValue {
  const ctx = useContext(TreeNavContext);
  if (!ctx) {
    throw new Error("useTreeNav must be used within a <TreeNav> component");
  }
  return ctx;
}

import { useMemo, useCallback, useLayoutEffect, useRef, useState } from "react";
import { cn } from "../lib/utils/cn";
import { VirtualList } from "../virtual-list";
import { TreeNavContext } from "./TreeNav.context";
import { TreeNode } from "./TreeNode";
import { createTreeStore, TreeInternalsContext, type TreeInternals } from "./tree-store";
import type { TreeNavProps, TreeNodeData, DragState } from "./TreeNav.types";

function collectFolderIds(nodes: TreeNodeData[]): string[] {
  const ids: string[] = [];
  for (const node of nodes) {
    if (node.children && node.children.length > 0) {
      ids.push(node.id);
      ids.push(...collectFolderIds(node.children));
    }
  }
  return ids;
}

const EMPTY_DRAG_STATE: DragState = {
  draggedNodeId: null,
  dropTargetId: null,
  dropPosition: null,
};

interface FlatRow {
  id: string;
  node: TreeNodeData;
  depth: number;
}

/** The rows currently visible — every node, descending only into expanded folders. */
function flattenVisible(nodes: TreeNodeData[], expanded: ReadonlySet<string>): FlatRow[] {
  const rows: FlatRow[] = [];
  const walk = (list: TreeNodeData[], depth: number) => {
    for (const node of list) {
      rows.push({ id: node.id, node, depth });
      const isFolder = node.type === "folder" || (node.children && node.children.length > 0);
      if (isFolder && node.children && expanded.has(node.id)) walk(node.children, depth + 1);
    }
  };
  walk(nodes, 0);
  return rows;
}

function TreeNavRoot({
  nodes,
  selectedId,
  onSelect,
  onNodeContextMenu,
  draggable = false,
  onNodeMove,
  acceptExternalDrops = false,
  onExternalDrop,
  expandedIds: controlledExpanded,
  defaultExpandedIds,
  onExpandedChange,
  defaultExpandAll = false,
  indentSize = 16,
  showIcons = true,
  dragCursor = "none",
  virtualize = false,
  height = 400,
  rowHeight = 26,
  className,
}: TreeNavProps) {
  const [internalExpanded, setInternalExpanded] = useState<string[]>(() => {
    if (defaultExpandedIds) return defaultExpandedIds;
    if (defaultExpandAll) return collectFolderIds(nodes);
    return [];
  });

  const isControlled = controlledExpanded !== undefined;
  const expandedIds = isControlled ? controlledExpanded : internalExpanded;
  // One Set per change, so a row's "am I expanded?" is a lookup, not a scan.
  const expanded = useMemo(() => new Set(expandedIds), [expandedIds]);

  const [dragState, setDragState] = useState<DragState>(EMPTY_DRAG_STATE);

  /*
   * The latest props and state, for handlers that must stay STABLE. A handler
   * whose identity changes on every click would change the context rows read,
   * and re-render every row — the exact cost this component is avoiding.
   */
  const latest = useRef({ expandedIds, isControlled, onExpandedChange, onSelect, onNodeContextMenu, onNodeMove, onExternalDrop });
  latest.current = { expandedIds, isControlled, onExpandedChange, onSelect, onNodeContextMenu, onNodeMove, onExternalDrop };

  const setExpanded = useCallback((next: string[]) => {
    if (!latest.current.isControlled) setInternalExpanded(next);
    latest.current.onExpandedChange?.(next);
  }, []);

  const toggle = useCallback(
    (id: string) => {
      const current = latest.current.expandedIds;
      setExpanded(current.includes(id) ? current.filter((v) => v !== id) : [...current, id]);
    },
    [setExpanded],
  );

  const expandNode = useCallback(
    (id: string) => {
      const current = latest.current.expandedIds;
      if (!current.includes(id)) setExpanded([...current, id]);
    },
    [setExpanded],
  );

  const select = useCallback((node: TreeNodeData) => latest.current.onSelect?.(node.id, node), []);
  const contextMenu = useCallback(
    (e: React.MouseEvent, node: TreeNodeData) => latest.current.onNodeContextMenu?.(e, node),
    [],
  );
  const moveNode = useCallback(
    (sourceId: string, targetId: string, position: Parameters<NonNullable<TreeNavProps["onNodeMove"]>>[2]) =>
      latest.current.onNodeMove?.(sourceId, targetId, position),
    [],
  );
  const externalDrop = useCallback(
    (event: React.DragEvent, target: TreeNodeData, position: Parameters<NonNullable<TreeNavProps["onExternalDrop"]>>[2]) =>
      latest.current.onExternalDrop?.(event, target, position),
    [],
  );

  // What rows subscribe to. Seeded with this render's values so the first paint
  // is right; kept current after each render that changes them.
  const [store] = useState(() => createTreeStore({ selectedId, expanded, dragState }));
  useLayoutEffect(() => {
    const current = store.get();
    if (current.selectedId !== selectedId || current.expanded !== expanded || current.dragState !== dragState) {
      store.set({ selectedId, expanded, dragState });
    }
  }, [store, selectedId, expanded, dragState]);

  const hasContextMenu = onNodeContextMenu !== undefined;
  const internals = useMemo<TreeInternals>(
    () => ({
      store,
      nodes,
      select,
      toggle,
      expandNode,
      setDragState,
      // Present only when the host gave one: a row then claims the right-click.
      contextMenu: hasContextMenu ? contextMenu : undefined,
      moveNode,
      externalDrop,
      indentSize,
      showIcons,
      draggable,
      dragCursor,
      acceptExternalDrops,
      flat: virtualize,
    }),
    [store, nodes, select, toggle, expandNode, hasContextMenu, contextMenu, moveNode, externalDrop,
     indentSize, showIcons, draggable, dragCursor, acceptExternalDrops, virtualize],
  );

  // Unchanged public context, still live for `useTreeNav()` callers. Rows no
  // longer read it, so its changing on a click re-renders only those callers.
  const ctx = useMemo(
    () => ({
      selectedId, onSelect, onNodeContextMenu, expandedIds, toggle, indentSize, showIcons,
      draggable, dragCursor, dragState, setDragState, onNodeMove, acceptExternalDrops, onExternalDrop, nodes, expandNode,
    }),
    [selectedId, onSelect, onNodeContextMenu, expandedIds, toggle, indentSize, showIcons,
     draggable, dragCursor, dragState, onNodeMove, acceptExternalDrops, onExternalDrop, nodes, expandNode],
  );

  const rows = useMemo(
    () => (virtualize ? flattenVisible(nodes, expanded) : []),
    [virtualize, nodes, expanded],
  );

  const handleDragEnd = useCallback(() => {
    setDragState(EMPTY_DRAG_STATE);
  }, []);

  const dropEnabled = draggable || acceptExternalDrops;

  return (
    <TreeNavContext.Provider value={ctx}>
      <TreeInternalsContext.Provider value={internals}>
        <nav
          data-react-fancy-tree-nav=""
          data-react-fancy-tree-nav-virtual={virtualize ? "" : undefined}
          className={cn("flex flex-col gap-0.5 py-1 text-sm", className)}
          onDragEnd={dropEnabled ? handleDragEnd : undefined}
        >
          {virtualize ? (
            <VirtualList
              items={rows}
              height={height}
              estimateRowHeight={rowHeight}
              renderRow={(row) => <TreeNode node={row.node} depth={row.depth} />}
            />
          ) : (
            nodes.map((node) => <TreeNode key={node.id} node={node} depth={0} />)
          )}
        </nav>
      </TreeInternalsContext.Provider>
    </TreeNavContext.Provider>
  );
}

TreeNavRoot.displayName = "TreeNav";

export const TreeNav = Object.assign(TreeNavRoot, {
  Node: TreeNode,
});

import type { ReactNode } from "react";

export interface TreeNodeData {
  /** Unique identifier */
  id: string;
  /** Display label */
  label: string;
  /** Node type for icon rendering */
  type?: "file" | "folder";
  /** File extension hint (e.g., "ts", "php", "html") for icon coloring */
  ext?: string;
  /** Nested children */
  children?: TreeNodeData[];
  /** Custom icon override */
  icon?: ReactNode;
  /** Whether the node is disabled */
  disabled?: boolean;
}

/** Where the dragged node will land relative to the drop target */
export type DropPosition = "before" | "after" | "inside";

export interface DragState {
  draggedNodeId: string | null;
  dropTargetId: string | null;
  dropPosition: DropPosition | null;
}

export interface TreeNavProps {
  /** Tree data */
  nodes: TreeNodeData[];
  /** Currently selected node ID */
  selectedId?: string;
  /** Callback when a node is selected */
  onSelect?: (id: string, node: TreeNodeData) => void;
  /** Callback when a node is right-clicked */
  onNodeContextMenu?: (e: React.MouseEvent, node: TreeNodeData) => void;
  /** Enable drag-and-drop reordering (default: false) */
  draggable?: boolean;
  /** Callback when a node is moved via drag and drop */
  onNodeMove?: (sourceId: string, targetId: string, position: DropPosition) => void;
  /** Accept drops from outside the tree — OS files, items from other
   *  components, etc. When true, drag-over is allowed for any data source
   *  and `onExternalDrop` fires on drop. (default: false) */
  acceptExternalDrops?: boolean;
  /** Called when an external drag (file or cross-component) is dropped on
   *  a node. The raw event lets you read `event.dataTransfer.files` for OS
   *  file drops or `event.dataTransfer.getData(type)` for custom MIME
   *  payloads from other components. */
  onExternalDrop?: (event: React.DragEvent, target: TreeNodeData, position: DropPosition) => void;
  /** Controlled expanded node IDs */
  expandedIds?: string[];
  /** Default expanded node IDs (uncontrolled) */
  defaultExpandedIds?: string[];
  /** Callback when expanded state changes */
  onExpandedChange?: (ids: string[]) => void;
  /** Expand all folders by default */
  defaultExpandAll?: boolean;
  /** Indent size per nesting level in px (default: 16) */
  indentSize?: number;
  /** Show file/folder icons (default: true) */
  showIcons?: boolean;
  /**
   * Cursor shown on hover over a draggable node.
   * - `"none"` (default): the normal clickable cursor — no move affordance on
   *   mere hover. A closed-hand `grabbing` cursor still appears while a drag is
   *   actually happening. This suits click-to-select/open trees (file/nav
   *   trees), where an always-on grab cursor wrongly implies move-first intent.
   * - `"grab"`: show the open-hand `grab` cursor on hover. Opt in when the whole
   *   row is genuinely a drag handle and reordering is the primary interaction.
   * @default "none"
   */
  dragCursor?: "grab" | "none";
  /**
   * Render only the rows in view. For big trees — thousands of expanded nodes —
   * where mounting every visible row is itself the cost. The visible rows are
   * flattened (expanded folders only) and windowed by `VirtualList`; selection,
   * expansion, context menus and drag-and-drop behave as in the nested tree.
   * Needs a `height`. Default `false`.
   */
  virtualize?: boolean;
  /** Height of the scroll viewport when `virtualize` is on. Default 400. */
  height?: number | string;
  /** Estimated row height in px when `virtualize` is on; real heights replace it as rows render. Default 26. */
  rowHeight?: number;
  /** Custom className */
  className?: string;
}

export interface TreeNavContextValue {
  selectedId?: string;
  onSelect?: (id: string, node: TreeNodeData) => void;
  onNodeContextMenu?: (e: React.MouseEvent, node: TreeNodeData) => void;
  expandedIds: string[];
  toggle: (id: string) => void;
  indentSize: number;
  showIcons: boolean;
  draggable: boolean;
  dragCursor: "grab" | "none";
  dragState: DragState;
  setDragState: (state: DragState) => void;
  onNodeMove?: (sourceId: string, targetId: string, position: DropPosition) => void;
  acceptExternalDrops: boolean;
  onExternalDrop?: (event: React.DragEvent, target: TreeNodeData, position: DropPosition) => void;
  nodes: TreeNodeData[];
  expandNode: (id: string) => void;
}

export interface TreeNodeProps {
  node: TreeNodeData;
  depth: number;
  className?: string;
}

import { memo, useRef, useEffect, useCallback } from "react";
import { cn } from "../lib/utils/cn";
import { useTreeInternals, useTreeSlice } from "./tree-store";
