// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------

function isDescendantOf(
  nodes: TreeNodeData[],
  ancestorId: string,
  targetId: string,
): boolean {
  function findNode(haystack: TreeNodeData[], id: string): TreeNodeData | undefined {
    for (const n of haystack) {
      if (n.id === id) return n;
      if (n.children) {
        const found = findNode(n.children, id);
        if (found) return found;
      }
    }
    return undefined;
  }

  function hasDescendant(node: TreeNodeData, id: string): boolean {
    if (!node.children) return false;
    for (const child of node.children) {
      if (child.id === id) return true;
      if (hasDescendant(child, id)) return true;
    }
    return false;
  }

  const ancestor = findNode(nodes, ancestorId);
  return ancestor ? hasDescendant(ancestor, targetId) : false;
}

function computeDropPosition(
  e: React.DragEvent,
  isFolder: boolean,
): DropPosition {
  const rect = e.currentTarget.getBoundingClientRect();
  const offsetY = e.clientY - rect.top;
  const third = rect.height / 3;

  if (offsetY < third) return "before";
  if (offsetY > third * 2) return "after";
  return isFolder ? "inside" : "after";
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------


/**
 * One row (and, when nested, its expanded children).
 *
 * Reads what changes on a click — selection, expansion, drag — as per-row slices
 * of a store, so a click re-renders only the rows whose slice changed. It used to
 * read one context holding all of it, so every click re-rendered every row:
 * 175-267 ms per click on a 5,000-node tree. `memo` keeps a parent's re-render
 * from reaching rows whose `node` and `depth` did not change.
 */
function TreeNodeImpl({ node, depth }: TreeNodeProps) {
  const {
    store, nodes, select, toggle, expandNode, setDragState, contextMenu, moveNode, externalDrop,
    indentSize, showIcons, draggable, dragCursor, acceptExternalDrops, flat,
  } = useTreeInternals();

  const isFolder = node.type === "folder" || (node.children && node.children.length > 0);
  const isExpanded = useTreeSlice((s) => s.expanded.has(node.id));
  const isSelected = useTreeSlice((s) => s.selectedId === node.id);
  const isDragging = useTreeSlice((s) => s.dragState.draggedNodeId === node.id);
  const dropPosition = useTreeSlice((s) =>
    s.dragState.dropTargetId === node.id ? s.dragState.dropPosition : null,
  );
  const isDropTarget = dropPosition !== null;
  const paddingLeft = depth * indentSize + 4;

  // Auto-expand timer for folders during drag
  const autoExpandTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearAutoExpand = useCallback(() => {
    if (autoExpandTimer.current) {
      clearTimeout(autoExpandTimer.current);
      autoExpandTimer.current = null;
    }
  }, []);

  useEffect(() => clearAutoExpand, [clearAutoExpand]);

  // ---------------------------------------------------------------------------
  // Click handlers
  // ---------------------------------------------------------------------------

  const handleClick = () => {
    if (node.disabled) return;
    if (isFolder) {
      toggle(node.id);
    }
    select(node);
  };

  const handleContextMenu = (e: React.MouseEvent) => {
    if (contextMenu) {
      e.preventDefault();
      contextMenu(e, node);
    }
  };

  // ---------------------------------------------------------------------------
  // Drag source handlers
  // ---------------------------------------------------------------------------

  const handleDragStart = useCallback((e: React.DragEvent) => {
    e.dataTransfer.setData("text/plain", node.id);
    e.dataTransfer.effectAllowed = "move";
    // Set state async so the browser captures the element for the drag ghost first
    requestAnimationFrame(() => {
      setDragState({ draggedNodeId: node.id, dropTargetId: null, dropPosition: null });
    });
  }, [node.id, setDragState]);

  const handleDragEnd = useCallback(() => {
    clearAutoExpand();
    setDragState({ draggedNodeId: null, dropTargetId: null, dropPosition: null });
  }, [clearAutoExpand, setDragState]);

  // ---------------------------------------------------------------------------
  // Drop target handlers (on outer div). Drag state is read from the store when
  // the event fires, so a row does not re-render as a drag moves elsewhere.
  // ---------------------------------------------------------------------------

  const handleDragOver = useCallback((e: React.DragEvent) => {
    const { dragState } = store.get();
    const isExternalDrag = !dragState.draggedNodeId;
    if (isExternalDrag) {
      // External drop accepted only when host opted in.
      if (!acceptExternalDrops) return;
    } else {
      const sourceId = dragState.draggedNodeId!;
      if (sourceId === node.id) return;
      if (isDescendantOf(nodes, sourceId, node.id)) return;
    }

    e.preventDefault();
    e.stopPropagation();
    e.dataTransfer.dropEffect = isExternalDrag ? "copy" : "move";

    const position = computeDropPosition(e, !!isFolder);

    // Auto-expand collapsed folders when hovering "inside"
    if (isFolder && !store.get().expanded.has(node.id) && position === "inside") {
      if (!autoExpandTimer.current) {
        autoExpandTimer.current = setTimeout(() => {
          expandNode(node.id);
          autoExpandTimer.current = null;
        }, 500);
      }
    } else {
      clearAutoExpand();
    }

    if (dragState.dropTargetId !== node.id || dragState.dropPosition !== position) {
      setDragState({ draggedNodeId: dragState.draggedNodeId, dropTargetId: node.id, dropPosition: position });
    }
  }, [store, acceptExternalDrops, node.id, isFolder, nodes, setDragState, expandNode, clearAutoExpand]);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    if (!e.currentTarget.contains(e.relatedTarget as Node)) {
      clearAutoExpand();
      const { dragState } = store.get();
      if (dragState.dropTargetId === node.id) {
        setDragState({ ...dragState, dropTargetId: null, dropPosition: null });
      }
    }
  }, [store, node.id, setDragState, clearAutoExpand]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    clearAutoExpand();

    const { dragState } = store.get();
    const sourceId = dragState.draggedNodeId;
    const position = dragState.dropPosition ?? computeDropPosition(e, !!isFolder);

    if (sourceId) {
      // Internal node move.
      if (sourceId === node.id) return;
      if (isDescendantOf(nodes, sourceId, node.id)) return;
      moveNode?.(sourceId, node.id, position);
    } else if (acceptExternalDrops) {
      // External drop — files, items from other components, etc.
      externalDrop?.(e, node, position);
    }

    setDragState({ draggedNodeId: null, dropTargetId: null, dropPosition: null });
  }, [store, node, isFolder, nodes, moveNode, acceptExternalDrops, externalDrop, setDragState, clearAutoExpand]);

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  const canDrag = draggable && !node.disabled;
  const dropEnabled = draggable || acceptExternalDrops;

  return (
    <div
      data-react-fancy-tree-node=""
      onDragOver={dropEnabled ? handleDragOver : undefined}
      onDragLeave={dropEnabled ? handleDragLeave : undefined}
      onDrop={dropEnabled ? handleDrop : undefined}
    >
      {/* Before drop indicator */}
      {isDropTarget && dropPosition === "before" && (
        <div
          data-react-fancy-tree-drop-indicator="before"
          className="pointer-events-none h-0.5 rounded-full bg-blue-500"
          style={{ marginLeft: paddingLeft }}
        />
      )}

      <button
        type="button"
        draggable={canDrag}
        onDragStart={canDrag ? handleDragStart : undefined}
        onDragEnd={canDrag ? handleDragEnd : undefined}
        onClick={handleClick}
        onContextMenu={handleContextMenu}
        disabled={node.disabled}
        className={cn(
          "flex w-full items-center gap-1 rounded-md py-0.5 text-left text-[13px] transition-colors",
          isSelected
            ? "bg-blue-500/15 text-blue-600 dark:text-blue-400"
            : "text-zinc-700 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800",
          node.disabled && "pointer-events-none opacity-40",
          isDragging && "opacity-50",
          // Grab affordance. By default (`dragCursor="none"`) the row keeps its
          // normal click cursor on hover — no open-hand "move me" cursor before
          // any drag — and only shows the closed-hand `grabbing` cursor while a
          // drag is actually underway (mousedown/drag). `dragCursor="grab"` opts
          // back into the always-on grab cursor for whole-row drag handles (#14).
          canDrag &&
            (dragCursor === "grab" ? "cursor-grab active:cursor-grabbing" : "active:cursor-grabbing"),
          isDropTarget && dropPosition === "inside" && "bg-blue-500/10 ring-1 ring-blue-500/30 ring-inset",
        )}
        style={{ paddingLeft }}
      >
        {isFolder && <ChevronIcon open={isExpanded} />}
        {!isFolder && <span className="w-3.5 shrink-0" />}
        {showIcons && (
          node.icon ?? (isFolder
            ? <FolderIcon open={isExpanded} />
            : <FileIcon ext={node.ext ?? node.label.split(".").pop()} />)
        )}
        <span className="truncate">{node.label}</span>
      </button>

      {/* After drop indicator */}
      {isDropTarget && dropPosition === "after" && (
        <div
          data-react-fancy-tree-drop-indicator="after"
          className="pointer-events-none h-0.5 rounded-full bg-blue-500"
          style={{ marginLeft: paddingLeft }}
        />
      )}

      {/* A virtual list renders rows flat, so a row never renders its own children there. */}
      {!flat && isFolder && isExpanded && node.children && (
        <div data-react-fancy-tree-node-children="">
          {node.children.map((child) => (
            <TreeNode key={child.id} node={child} depth={depth + 1} />
          ))}
        </div>
      )}
    </div>
  );
}

export const TreeNode = memo(TreeNodeImpl);

TreeNode.displayName = "TreeNode";

export { TreeNav } from "./TreeNav";
export { useTreeNav } from "./TreeNav.context";
export type {
  TreeNavProps,
  TreeNodeData,
  TreeNodeProps,
  TreeNavContextValue,
  DropPosition,
} from "./TreeNav.types";

import { createContext, useContext, useSyncExternalStore } from "react";
import type { DragState, DropPosition, TreeNodeData } from "./TreeNav.types";

/** What changes as someone clicks, toggles and drags — the state rows subscribe to. */
export interface TreeState {
  selectedId?: string;
  expanded: ReadonlySet<string>;
  dragState: DragState;
}

export interface TreeStore {
  get(): TreeState;
  set(next: TreeState): void;
  subscribe(listener: () => void): () => void;
}

export function createTreeStore(initial: TreeState): TreeStore {
  let state = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => state,
    set(next) {
      state = next;
      for (const listener of listeners) listener();
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/**
 * Everything a row needs that does NOT change on a click. Handlers are stable
 * (they read the latest props and state when called), so this value only changes
 * when the tree's data or configuration does.
 *
 * Kept apart from the public `TreeNavContext` on purpose: that one still carries
 * live `selectedId` / `expandedIds` for `useTreeNav()` callers, and any component
 * reading it re-renders on every click. Rows no longer read it — which is the
 * whole fix: a click used to re-render every row in the tree.
 */
export interface TreeInternals {
  store: TreeStore;
  nodes: TreeNodeData[];
  select: (node: TreeNodeData) => void;
  toggle: (id: string) => void;
  expandNode: (id: string) => void;
  setDragState: (state: DragState) => void;
  contextMenu?: (e: React.MouseEvent, node: TreeNodeData) => void;
  moveNode?: (sourceId: string, targetId: string, position: DropPosition) => void;
  externalDrop?: (event: React.DragEvent, target: TreeNodeData, position: DropPosition) => void;
  indentSize: number;
  showIcons: boolean;
  draggable: boolean;
  dragCursor: "grab" | "none";
  acceptExternalDrops: boolean;
  /** Rows are rendered flat by a virtual list, so a row never renders its children. */
  flat: boolean;
}

export const TreeInternalsContext = createContext<TreeInternals | null>(null);

export function useTreeInternals(): TreeInternals {
  const internals = useContext(TreeInternalsContext);
  if (!internals) throw new Error("TreeNav.Node must be used within a <TreeNav> component");
  return internals;
}

/** Subscribe to ONE derived value; the row re-renders only when that value changes. */
export function useTreeSlice<T>(select: (state: TreeState) => T): T {
  const { store } = useTreeInternals();
  return useSyncExternalStore(
    store.subscribe,
    () => select(store.get()),
    () => select(store.get()),
  );
}

import { twMerge } from "tailwind-merge";

/**
 * A class value: a string, a number, a conditional map, an array of any of
 * those, or nothing. Mirrors what `clsx` accepted, because every component in
 * this package already passes these shapes.
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassDictionary
  | ClassValue[];

type ClassDictionary = Record<string, unknown>;

/**
 * Flatten class values into a space-separated string.
 *
 * This was `clsx` until 2026-08-19. It is roughly twenty lines of logic, it
 * shipped as a RUNTIME dependency to every consumer of this package, and its
 * last commit was 801 days old — so it fell to the rule that third-party code
 * must be both approved and actively maintained. Owning it costs less than
 * carrying it.
 *
 * `tailwind-merge` deliberately stays: deciding which of two conflicting
 * Tailwind utilities wins requires modelling the entire utility space, which is
 * emphatically not twenty lines, and it is actively maintained.
 *
 * Falsy values are dropped — including `0` and `""`, which is what `clsx` did
 * and what `tests/cn.test.ts` pins. A truthy number is kept, because digits are
 * legal class names. `bigint` is admitted because clsx's signature did and
 * the compiler proved it reachable from two call sites here.
 */
function flatten(value: ClassValue): string {
  if (!value) return "";

  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  if (Array.isArray(value)) {
    let out = "";
    for (const item of value) {
      const part = flatten(item);
      if (part) out = out ? `${out} ${part}` : part;
    }
    return out;
  }

  let out = "";
  for (const key in value) {
    if (value[key]) out = out ? `${out} ${key}` : key;
  }
  return out;
}

export function cn(...inputs: ClassValue[]): string {
  return twMerge(flatten(inputs));
}

import type { Span, StyleName } from "./spans";

/**
 * First-party syntax highlighting for fenced code blocks.
 *
 * A small scanner, not a grammar engine. It classifies the token kinds that carry
 * most of the reading value — comments, strings, numbers, keywords, literals and
 * built-ins, plus function/class signatures, JSX tags and decorators — and colours
 * them with the palette highlight.js used through marked-terminal, so a block
 * that used to be highlighted still reads the same way.
 *
 * Coverage is deliberately the languages the Fancy suite is written in and the
 * formats agents emit most: TypeScript/JavaScript (+ JSX), JSON, shell, Python,
 * PHP, SQL, YAML and diffs. Any other language — or none — renders uncoloured.
 * Guessing is not attempted: highlight.js' auto-detection painted ordinary prose
 * in an unlabelled fence as keywords.
 *
 * Tokens partition the input exactly — no character is added or removed — so
 * highlighting can never change a line's width.
 */

const words = (list: string): Set<string> => new Set(list.trim().split(/\s+/));

const JS_KEYWORDS = words(`
  as in of if for while finally var new function do return void else break catch
  instanceof with throw case default try switch continue typeof delete let yield
  const class debugger async await static import from export extends`);
const JS_LITERALS = words("true false null undefined NaN Infinity");
const JS_BUILT_INS = words(`
  setInterval setTimeout clearInterval clearTimeout require exports eval isFinite
  isNaN parseFloat parseInt decodeURI decodeURIComponent encodeURI
  encodeURIComponent escape unescape arguments this super console window document
  localStorage module global Intl DataView Number Math Date String RegExp Object
  Function Boolean Error Symbol Set Map WeakSet WeakMap Proxy Reflect JSON Promise
  Float64Array Int16Array Int32Array Int8Array Uint16Array Uint32Array
  Float32Array Array Uint8Array Uint8ClampedArray ArrayBuffer BigInt64Array
  BigUint64Array BigInt EvalError InternalError RangeError ReferenceError
  SyntaxError TypeError URIError`);
const TS_KEYWORDS = words(`${[...JS_KEYWORDS].join(" ")}
  type namespace typedef interface public private protected implements declare
  abstract readonly`);
const TS_BUILT_INS = words(`${[...JS_BUILT_INS].join(" ")} any void number boolean string object never enum unknown`);

const PY_KEYWORDS = words(`
  and as assert async await break class continue def del elif else except finally
  for from global if import in is lambda nonlocal not or pass raise return try
  while with yield match case`);
const PY_LITERALS = words("__debug__ Ellipsis False None NotImplemented True");
const PY_BUILT_INS = words(`
  __import__ abs all any ascii bin bool breakpoint bytearray bytes callable chr
  classmethod compile complex delattr dict dir divmod enumerate eval exec filter
  float format frozenset getattr globals hasattr hash help hex id input int
  isinstance issubclass iter len list locals map max memoryview min next object
  oct open ord pow print property range repr reversed round set setattr slice
  sorted staticmethod str sum super tuple type vars zip self`);

const PHP_KEYWORDS = words(`
  __CLASS__ __DIR__ __FILE__ __FUNCTION__ __LINE__ __METHOD__ __NAMESPACE__
  __TRAIT__ die echo exit include include_once print require require_once array
  abstract and as binary bool boolean break callable case catch class clone const
