const SQL_LITERALS = words("true false null");
const SQL_TYPES = words(`
  int integer bigint smallint tinyint decimal numeric float real double varchar
  char text date time timestamp datetime boolean bool blob json jsonb uuid serial`);
const SQL_BUILT_INS = words("count sum avg min max coalesce now lower upper length substring cast concat round");

interface Signature {
  /** Keyword that opens the signature. */
  keyword: string;
  style: StyleName;
  /** Characters that end it, at bracket depth 0. */
  end: string;
  /** Whether the end character belongs to the signature (Python's `:`). */
  inclusive: boolean;
}

interface CLike {
  keywords: Set<string>;
  literals: Set<string>;
  builtIns: Set<string>;
  types?: Set<string>;
  caseInsensitive?: boolean;
  lineComments: string[];
  /** Line comments that only start at a word boundary (shell `#`). */
  boundaryLineComment?: string;
  blockComment?: [string, string];
  quotes: string[];
  /** Quotes whose strings may span lines. Others stop at a newline. */
  multilineQuotes?: string;
  template?: boolean;
  tripleQuotes?: boolean;
  stringPrefix?: RegExp;
  identifier: RegExp;
  variable?: RegExp;
  signatures?: Signature[];
  jsx?: boolean;
  regex?: boolean;
  decorators?: boolean;
  phpTags?: boolean;
  /** Do not treat `obj.default` / `$obj->class` as keywords. */
  memberAccess?: string[];
}

type Push = (text: string, ...styles: StyleName[]) => void;

const NUMBER = /(?:0[xX][\da-fA-F_]+|0[bB][01_]+|0[oO][0-7_]+|(?:\d[\d_]*\.?[\d_]*|\.\d[\d_]*)(?:[eE][+-]?\d+)?)n?/y;
const IDENT_CHAR = /[\w$\u0080-\uffff]/;

function matchAt(re: RegExp, text: string, index: number): string | null {
  re.lastIndex = index;
  const m = re.exec(text);
  return m && m.index === index && m[0] !== "" ? m[0] : null;
}

const MAX_TEMPLATE_NESTING = 4;

function scanClike(code: string, spec: CLike, outer: readonly StyleName[], out: Span[], nesting = 0): void {
  let i = 0;
  // What the last significant token was, for regex/JSX disambiguation.
  let prev: "start" | "operator" | "value" = "start";
  let lastMember = false;
  let signature: { style: StyleName; end: string; inclusive: boolean; depth: number } | null = null;

  const push: Push = (text, ...styles) => {
    if (text === "") return;
    const all: StyleName[] = [...outer];
    if (signature) all.push(signature.style);
    all.push(...styles);
    out.push({ text, styles: all });
  };

  const readQuoted = (start: number, quote: string, multiline: boolean): number => {
    let j = start + quote.length;
    while (j < code.length) {
      if (code[j] === "\\") {
        j += 2;
        continue;
      }
      if (code.startsWith(quote, j)) return j + quote.length;
      if (!multiline && code[j] === "\n") return j;
      j++;
    }
    return code.length;
  };

  while (i < code.length) {
    const ch = code[i]!;

    if (spec.phpTags) {
      const tag = matchAt(/<\?(?:php|=)?|\?>/y, code, i);
      if (tag) {
        push(tag, "meta");
        i += tag.length;
        prev = "start";
        continue;
      }
    }

    const lineComment = spec.lineComments.find((c) => code.startsWith(c, i));
    const boundaryComment =
      spec.boundaryLineComment && code.startsWith(spec.boundaryLineComment, i) && (i === 0 || /[\s;]/.test(code[i - 1]!));
    if (lineComment || boundaryComment) {
      const end = code.indexOf("\n", i);
      const stop = end === -1 ? code.length : end;
      push(code.slice(i, stop), "comment");
      i = stop;
      continue;
    }

    if (spec.blockComment && code.startsWith(spec.blockComment[0], i)) {
      const end = code.indexOf(spec.blockComment[1], i + spec.blockComment[0].length);
      const stop = end === -1 ? code.length : end + spec.blockComment[1].length;
      push(code.slice(i, stop), "comment");
      i = stop;
      continue;
    }

    // Strings, with an optional prefix (Python f"", r'', b"").
    const prefix = spec.stringPrefix ? matchAt(spec.stringPrefix, code, i) : null;
    const quoteStart = i + (prefix?.length ?? 0);
    const triple = spec.tripleQuotes ? ['"""', "'''"].find((q) => code.startsWith(q, quoteStart)) : undefined;
    const quote = triple ?? spec.quotes.find((q) => code.startsWith(q, quoteStart));
    if (quote && (prefix === null || !IDENT_CHAR.test(code[i - 1] ?? ""))) {
      if (quote === "`" && spec.template) {
        i = scanTemplate(code, i, spec, outer, signature?.style, out, nesting);
      } else {
        const multiline = triple !== undefined || (spec.multilineQuotes ?? "").includes(quote);
        const end = readQuoted(quoteStart, quote, multiline);
        push(code.slice(i, end), "string");
        i = end;
      }
      prev = "value";
      continue;
    }

    if (spec.regex && ch === "/" && prev !== "value") {
      const end = readRegex(code, i);
      if (end !== -1) {
        push(code.slice(i, end), "regexp");
        i = end;
        prev = "value";
        continue;
      }
    }

    if (spec.decorators && ch === "@") {
      const name = matchAt(/@[A-Za-z_][\w.]*/y, code, i);
      if (name && (i === 0 || !IDENT_CHAR.test(code[i - 1]!))) {
        push(name, "meta");
        i += name.length;
        prev = "operator";
        continue;
      }
    }

    // `</Name` is a closing tag wherever it appears; an opening `<Name` only where
    // an expression can start (so `a < b` and `Array<string>` stay operators).
    const closingTag = code[i + 1] === "/" && /[A-Za-z]/.test(code[i + 2] ?? "");
    if (spec.jsx && ch === "<" && (closingTag || (prev !== "value" && /[A-Za-z>]/.test(code[i + 1] ?? "")))) {
      const end = scanJsxTag(code, i, push);
      if (end !== -1) {
        i = end;
        prev = "operator";
        continue;
      }
    }

    if (spec.variable) {
      const variable = matchAt(spec.variable, code, i);
      if (variable) {
        push(variable);
        i += variable.length;
        prev = "value";
        continue;
      }
    }

    if (/[\d.]/.test(ch) && !IDENT_CHAR.test(code[i - 1] ?? "")) {
      const num = matchAt(NUMBER, code, i);
      if (num && /\d/.test(num) && !IDENT_CHAR.test(code[i + num.length] ?? "")) {
        push(num, "number");
        i += num.length;
        prev = "value";
        continue;
      }
    }

    const ident = matchAt(spec.identifier, code, i);
    if (ident) {
      const key = spec.caseInsensitive ? ident.toLowerCase() : ident;
      const isMember = lastMember;
      let style: StyleName | undefined;
      if (!isMember) {
        if (spec.keywords.has(key)) style = "keyword";
        else if (spec.literals.has(key)) style = "literal";
        else if (spec.builtIns.has(key)) style = "built_in";
        else if (spec.types?.has(key)) style = "type";
      }
      const opens: Signature | undefined = !isMember && !signature ? spec.signatures?.find((s) => s.keyword === key) : undefined;
      if (opens) signature = { style: opens.style, end: opens.end, inclusive: opens.inclusive, depth: 0 };
      if (style) push(ident, style);
      else push(ident);
      i += ident.length;
      prev = style === "keyword" ? "operator" : "value";
      lastMember = false;
      continue;
    }

    // Punctuation, operators and whitespace.
    if (signature) {
      if ("([{".includes(ch) && !(signature.depth === 0 && signature.end.includes(ch))) signature.depth++;
      else if (")]}".includes(ch) && signature.depth > 0) signature.depth--;
      else if (signature.depth === 0 && signature.end.includes(ch)) {
        if (signature.inclusive) {
          push(ch);
          signature = null;
          i++;
          prev = "operator";
          continue;
        }
        signature = null;
      }
    }
    const member = spec.memberAccess?.find((m) => code.startsWith(m, i));
    if (member) {
      push(member);
      i += member.length;
      lastMember = true;
      prev = "operator";
      continue;
    }
    push(ch);
    i++;
    if (!/\s/.test(ch)) {
      prev = ")]}".includes(ch) ? "value" : "operator";
      lastMember = false;
    }
  }
}

const MAX_REGEX_SCAN = 500;

function readRegex(code: string, start: number): number {
  let j = start + 1;
  let inClass = false;
  if (code[j] === "/" || code[j] === "*") return -1;
  // Bounded: every `/` that fails to close would otherwise rescan the rest of
  // its line, which is quadratic on one long hostile line.
  const limit = Math.min(code.length, start + MAX_REGEX_SCAN);
  while (j < limit) {
    const c = code[j]!;
    if (c === "\n") return -1;
    if (c === "\\") {
      j += 2;
      continue;
    }
    if (c === "[") inClass = true;
    else if (c === "]") inClass = false;
    else if (c === "/" && !inClass) {
      j++;
      while (j < code.length && /[a-z]/.test(code[j]!)) j++;
      return j;
    }
    j++;
  }
  return -1;
}

function scanTemplate(
  code: string,
  start: number,
  spec: CLike,
  outer: readonly StyleName[],
  signatureStyle: StyleName | undefined,
  out: Span[],
  nesting: number,
): number {
  const base: StyleName[] = [...outer];
  if (signatureStyle) base.push(signatureStyle);
  const stringStyles: StyleName[] = [...base, "string"];
  let j = start + 1;
  let literalStart = start;
  while (j < code.length) {
    const c = code[j]!;
    if (c === "\\") {
      j += 2;
      continue;
    }
    if (c === "`") {
      j++;
      out.push({ text: code.slice(literalStart, j), styles: stringStyles });
      return j;
    }
    if (c === "$" && code[j + 1] === "{") {
      out.push({ text: code.slice(literalStart, j + 2), styles: stringStyles });
      let depth = 1;
      let k = j + 2;
      while (k < code.length && depth > 0) {
        if (code[k] === "{") depth++;
        else if (code[k] === "}") depth--;
        if (depth > 0) k++;
      }
      // Substitutions are highlighted as code, to a fixed depth: untrusted input
      // of nested `${` would otherwise recurse until the stack overflows.
      if (nesting < MAX_TEMPLATE_NESTING) scanClike(code.slice(j + 2, k), spec, stringStyles, out, nesting + 1);
      else out.push({ text: code.slice(j + 2, k), styles: stringStyles });
      literalStart = k;
      j = k + 1;
      continue;
    }
    j++;
  }
  out.push({ text: code.slice(literalStart), styles: stringStyles });
  return code.length;
}

/** `<Name attr="x">` / `</Name>` / `<>`. Returns the index after the tag, or -1. */
const MAX_TAG_SCAN = 1000;

function scanJsxTag(code: string, start: number, push: Push): number {
  const m = /<\/?([A-Za-z][\w.:-]*)?/y;
  m.lastIndex = start;
  const open = m.exec(code);
  if (!open) return -1;
  let j = start + open[0].length;
  const pieces: Array<[string, StyleName[]]> = [];
  const opener = open[0].slice(0, open[0].length - (open[1]?.length ?? 0));
  pieces.push([opener, ["tag"]]);
  if (open[1]) pieces.push([open[1], ["tag", "name"]]);
  while (j < code.length) {
    const c = code[j]!;
    if (c === ">") {
      pieces.push([">", ["tag"]]);
      j++;
      for (const [text, styles] of pieces) push(text, ...styles);
      return j;
    }
    // Bounded, so a long run of stray `<` in untrusted code cannot go quadratic.
    if (j - start > MAX_TAG_SCAN) return -1;
    if (c === '"' || c === "'") {
      const end = code.indexOf(c, j + 1);
      if (end === -1 || end - start > MAX_TAG_SCAN) return -1;
      pieces.push([code.slice(j, end + 1), ["tag", "string"]]);
      j = end + 1;
      continue;
    }
    const attr = /[A-Za-z_][\w:-]*/y;
    attr.lastIndex = j;
    const name = attr.exec(code);
    if (name) {
      pieces.push([name[0], ["tag", "attr"]]);
      j += name[0].length;
      continue;
    }
    if (c === "{") {
      let depth = 1;
      let k = j + 1;
      while (k < code.length && depth > 0) {
        if (code[k] === "{") depth++;
        else if (code[k] === "}") depth--;
        k++;
      }
      pieces.push([code.slice(j, k), ["tag"]]);
      j = k;
      continue;
    }
    if (!/[\s=/]/.test(c)) return -1;
    pieces.push([c, ["tag"]]);
    j++;
  }
  return -1;
}

const JS: CLike = {
  keywords: JS_KEYWORDS,
  literals: JS_LITERALS,
  builtIns: JS_BUILT_INS,
  lineComments: ["//"],
  blockComment: ["/*", "*/"],
  quotes: ["'", '"', "`"],
  template: true,
  identifier: /[A-Za-z_$][\w$]*/y,
  signatures: [
    { keyword: "function", style: "function", end: "{;", inclusive: false },
    { keyword: "class", style: "class", end: "{=", inclusive: false },
  ],
  jsx: true,
  regex: true,
  decorators: true,
  memberAccess: ["?.", "."],
};

const TS: CLike = {
  ...JS,
  keywords: TS_KEYWORDS,
  builtIns: TS_BUILT_INS,
  signatures: [...(JS.signatures ?? []), { keyword: "interface", style: "class", end: "{", inclusive: false }],
};

const PYTHON: CLike = {
  keywords: PY_KEYWORDS,
  literals: PY_LITERALS,
  builtIns: PY_BUILT_INS,
  lineComments: ["#"],
  quotes: ["'", '"'],
  tripleQuotes: true,
  stringPrefix: /[rRbBuUfF]{1,2}(?=['"])/y,
  identifier: /[A-Za-z_][\w]*/y,
  signatures: [
    { keyword: "def", style: "function", end: ":", inclusive: true },
    { keyword: "class", style: "class", end: ":", inclusive: true },
  ],
  decorators: true,
  memberAccess: ["."],
};

const PHP: CLike = {
  keywords: PHP_KEYWORDS,
  literals: PHP_LITERALS,
  builtIns: PHP_BUILT_INS,
  caseInsensitive: true,
  lineComments: ["//", "#"],
  blockComment: ["/*", "*/"],
  quotes: ["'", '"'],
  multilineQuotes: `'"`,
  identifier: /[A-Za-z_\u0080-\uffff][\w\u0080-\uffff]*/y,
  variable: /\$+[A-Za-z_\u0080-\uffff][\w\u0080-\uffff]*/y,
  signatures: [
    { keyword: "function", style: "function", end: "{;", inclusive: false },
    { keyword: "class", style: "class", end: "{", inclusive: false },
  ],
  phpTags: true,
  memberAccess: ["?->", "->", "::"],
};

const SHELL: CLike = {
  keywords: SH_KEYWORDS,
  literals: SH_LITERALS,
  builtIns: SH_BUILT_INS,
  lineComments: [],
  boundaryLineComment: "#",
  quotes: ["'", '"'],
  multilineQuotes: `'"`,
  identifier: /[A-Za-z_][\w.-]*/y,
  variable: /\$(?:\{[^}\n]*\}|[\w#@?$!*-]+)/y,
};

const SQL: CLike = {
  keywords: SQL_KEYWORDS,
  literals: SQL_LITERALS,
  builtIns: SQL_BUILT_INS,
  types: SQL_TYPES,
  caseInsensitive: true,
  lineComments: ["--"],
  blockComment: ["/*", "*/"],
  quotes: ["'"],
  identifier: /[A-Za-z_][\w$]*/y,
  memberAccess: ["."],
};

function clike(spec: CLike): (code: string) => Span[] {
  return (code) => {
    const out: Span[] = [];
    scanClike(code, spec, [], out);
    return out;
  };
}

function json(code: string): Span[] {
  const out: Span[] = [];
  let i = 0;
  while (i < code.length) {
    const ch = code[i]!;
    if (code.startsWith("//", i) || code.startsWith("/*", i)) {
      const block = code.startsWith("/*", i);
      const end = block ? code.indexOf("*/", i + 2) : code.indexOf("\n", i);
      const stop = end === -1 ? code.length : block ? end + 2 : end;
      out.push({ text: code.slice(i, stop), styles: ["comment"] });
      i = stop;
      continue;
    }
    if (ch === '"') {
      let j = i + 1;
      while (j < code.length && code[j] !== '"' && code[j] !== "\n") j += code[j] === "\\" ? 2 : 1;
      j = Math.min(code.length, j + 1);
      let k = j;
      while (k < code.length && /\s/.test(code[k]!)) k++;
      const isKey = code[k] === ":";
      out.push({ text: code.slice(i, j), styles: [isKey ? "attr" : "string"] });
      i = j;
      continue;
    }
    const num = /-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/y;
    num.lastIndex = i;
    const n = num.exec(code);
    if (n && (i === 0 || !/[\w.]/.test(code[i - 1]!))) {
      out.push({ text: n[0], styles: ["number"] });
      i += n[0].length;
      continue;
    }
    const lit = /true|false|null/y;
    lit.lastIndex = i;
    const l = lit.exec(code);
    if (l && !/\w/.test(code[i + l[0].length] ?? "")) {
      out.push({ text: l[0], styles: ["literal"] });
      i += l[0].length;
      continue;
    }
    out.push({ text: ch, styles: [] });
    i++;
  }
  return out;
}

function yamlScalar(text: string, out: Span[]): void {
  // Split off leading/trailing whitespace so only the value itself is coloured.
  // Plain trims, not a regex: `(.*?)(\s*)$` backtracks quadratically on whitespace.
  const lead = text.length - text.trimStart().length;
  const value = text.trim();
  const trail = text.slice(lead + value.length);
  out.push({ text: text.slice(0, lead), styles: [] });
  if (value !== "") {
    let style: StyleName = "string";
    if (/^(?:true|false|yes|no|null|~)$/i.test(value)) style = "literal";
    else if (/^[-+]?(?:\d[\d_]*(?:\.\d+)?(?:[eE][+-]?\d+)?|0x[\da-fA-F]+)$/.test(value)) style = "number";
    else if (/^[|>][-+]?$/.test(value)) style = "meta";
    out.push({ text: value, styles: [style] });
  }
  out.push({ text: trail, styles: [] });
}

function yaml(code: string): Span[] {
  const out: Span[] = [];
  code.split("\n").forEach((line, index) => {
    if (index > 0) out.push({ text: "\n", styles: [] });
    let rest = line;
    // Comment: a `#` at the start or after whitespace, outside quotes.
    let comment = "";
    let quote: string | null = null;
    for (let i = 0; i < rest.length; i++) {
      const c = rest[i]!;
      if (quote) {
        if (c === quote) quote = null;
      } else if (c === '"' || c === "'") quote = c;
      else if (c === "#" && (i === 0 || /\s/.test(rest[i - 1]!))) {
        comment = rest.slice(i);
        rest = rest.slice(0, i);
        break;
      }
    }
    if (/^(?:---|\.\.\.)\s*$/.test(rest)) {
      out.push({ text: rest, styles: ["meta"] });
    } else {
      const key = /^(\s*(?:-\s+)?)((?:"[^"]*"|'[^']*'|[^\s:#"'][^:#]*):)(?=\s|$)/.exec(rest);
      let value = rest;
      if (key) {
        out.push({ text: key[1]!, styles: [] });
        out.push({ text: key[2]!, styles: ["attr"] });
        value = rest.slice(key[0].length);
      } else {
        const bullet = /^(\s*-\s+)/.exec(rest);
        if (bullet) {
          out.push({ text: bullet[1]!, styles: [] });
          value = rest.slice(bullet[1]!.length);
        }
      }
      // Flow collections: colour each element, keep the punctuation plain.
      for (const part of value.split(/([[\]{},])/)) {
        if (part === "") continue;
        if (/^[[\]{},]$/.test(part)) out.push({ text: part, styles: [] });
        else yamlScalar(part, out);
      }
    }
    if (comment) out.push({ text: comment, styles: ["comment"] });
  });
  return out;
}

function diff(code: string): Span[] {
  const out: Span[] = [];
  code.split("\n").forEach((line, index) => {
    if (index > 0) out.push({ text: "\n", styles: [] });
    let style: StyleName | undefined;
    if (/^(?:---|\+\+\+|Index: |index |diff --git|={3,}|\*{3} )/.test(line)) style = "comment";
    else if (/^@@/.test(line)) style = "meta";
    else if (/^[-<]/.test(line)) style = "deletion";
    else if (/^[+>!]/.test(line)) style = "addition";
    out.push({ text: line, styles: style ? [style] : [] });
  });
  return out;
}

const LEXERS: Record<string, (code: string) => Span[]> = {};
const register = (names: string, lexer: (code: string) => Span[]) => {
  for (const name of names.split(" ")) LEXERS[name] = lexer;
};
register("js javascript jsx mjs cjs node", clike(JS));
register("ts typescript tsx mts cts", clike(TS));
register("py python python3 py3", clike(PYTHON));
register("php php8", clike(PHP));
register("sh bash zsh shell console shellscript", clike(SHELL));
register("sql mysql pgsql postgres postgresql sqlite", clike(SQL));
register("json jsonc json5", json);
register("yaml yml", yaml);
register("diff patch", diff);

/** Languages with a first-party lexer, by every accepted fence name. */
export const HIGHLIGHT_LANGUAGES: readonly string[] = Object.keys(LEXERS);

/**
 * Tokenise `code` for display. Unsupported or absent languages come back as one
 * unstyled span, so callers never need a second code path.
 */
export function highlightCode(code: string, language: string | undefined): Span[] {
  const name = (language ?? "").trim().split(/\s+/)[0]!.toLowerCase();
  const lexer = LEXERS[name];
  if (!lexer || code === "") return code === "" ? [] : [{ text: code, styles: [] }];
  return lexer(code);
}

import { renderTerminalMarkdown } from "./terminal";

// C0 control codes we keep: TAB (9), LF (10), CR (13). Everything else in
// 0x00-0x1F, plus DEL (0x7F), is stripped from untrusted markdown before it
// reaches the terminal. Critically this includes ESC (27) — ESC begins every
// ANSI / OSC / CSI escape sequence, so leaving it in would let agent replies or
// tool output carry OSC52 clipboard writes, OSC8 hyperlink spoofs, and CSI
// buffer overwrites straight to the user's terminal. Expressed as a codepoint
// filter (not a regex character class) so the pattern carries no invisible
// control characters itself — the split-range class that predated this let ESC
// slip through exactly because the gap was easy to miss.
const KEEP_CONTROL = new Set([9, 10, 13]);

function stripControlChars(source: string): string {
  let out = "";
  for (const ch of source) {
    const cp = ch.codePointAt(0) ?? 0;
    const isControl = cp <= 0x1f || cp === 0x7f;
    if (!isControl || KEEP_CONTROL.has(cp)) {
      out += ch;
    }
  }
  return out;
}

/**
 * Render markdown as ANSI text for a terminal, wrapped at 80 columns.
 *
 * Colour follows chalk's detection of the environment (`FORCE_COLOR`, a TTY);
 * with colour off the output is plain text in the same layout.
 */
export function renderMarkdown(source: string): string {
  return renderTerminalMarkdown(stripControlChars(source));
}

import stringWidth from "string-width";

/**
 * The intermediate form every markdown construct renders to: lines of styled
 * spans. Styles are named, never raw ANSI, and are listed outermost first — a
 * bold word inside a blockquote is `["blockquote", "strong"]`.
 *
 * Keeping ANSI out until the very last step is what makes wrapping and width
 * measurement trustworthy. marked-terminal styled first and wrapped the escaped
 * string afterwards, so it measured bytes it had coloured, counted UTF-16 code
 * units as columns, and split lines in the middle of an open style.
 */
export type StyleName =
  | "h1"
  | "heading"
  | "strong"
  | "em"
  | "codespan"
  | "del"
  | "link"
  | "href"
  | "html"
  | "blockquote"
  | "tableHead"
  | "tableBorder"
  | "keyword"
  | "built_in"
  | "type"
  | "literal"
  | "number"
  | "string"
  | "regexp"
  | "comment"
  | "function"
  | "class"
  | "meta"
  | "tag"
  | "name"
  | "attr"
  | "addition"
  | "deletion";

export interface Span {
  text: string;
  styles: readonly StyleName[];
  /** A hard line break (`br`). Its `text` is ignored. */
  br?: true;
}

export type Line = Span[];

const segmenter = new Intl.Segmenter(undefined, { granularity: "grapheme" });

/** Split into user-perceived characters, so a wrap never lands inside one. */
export function graphemes(text: string): string[] {
  return Array.from(segmenter.segment(text), (s) => s.segment);
}

/** Terminal columns — East Asian wide characters and emoji count as 2. */
export function columns(text: string): number {
  return /^[\x20-\x7e]*$/.test(text) ? text.length : stringWidth(text);
}

const clusterWidths = new Map<string, number>();

/** Width of one grapheme, cached: cutting a long CJK run measures thousands. */
function clusterColumns(cluster: string): number {
  let width = clusterWidths.get(cluster);
  if (width === undefined) {
    width = columns(cluster);
    if (clusterWidths.size < 4096) clusterWidths.set(cluster, width);
  }
  return width;
}

export function lineText(line: Line): string {
  return line.map((span) => span.text).join("");
}

export function lineColumns(line: Line): number {
  return columns(lineText(line));
}

function sameStyles(a: readonly StyleName[], b: readonly StyleName[]): boolean {
  return a.length === b.length && a.every((style, i) => style === b[i]);
}

/** Join neighbouring spans that carry identical styles, and drop empty ones. */
export function mergeSpans(line: Line): Line {
  const out: Line = [];
  for (const span of line) {
    if (span.text === "") continue;
    const last = out[out.length - 1];
    if (last && sameStyles(last.styles, span.styles)) last.text += span.text;
    else out.push({ text: span.text, styles: span.styles });
  }
  return out;
}

/** Add a style OUTSIDE every span of every line (a blockquote around its body). */
export function wrapStyle(lines: Line[], style: StyleName): Line[] {
  return lines.map((line) => line.map((span) => ({ ...span, styles: [style, ...span.styles] })));
}

/** Split spans at `\n` into lines, keeping each piece's styles. */
export function splitLines(spans: readonly Span[]): Line[] {
  const lines: Line[] = [[]];
  for (const span of spans) {
    const parts = span.text.split("\n");
    parts.forEach((part, i) => {
      if (i > 0) lines.push([]);
      if (part !== "") lines[lines.length - 1]!.push({ text: part, styles: span.styles });
    });
  }
  return lines;
}

interface Piece {
  text: string;
  styles: readonly StyleName[];
}

interface Word {
  pieces: Piece[];
  width: number;
  /** Styles of the whitespace that preceded this word, used for the joining space. */
  gapStyles: readonly StyleName[] | null;
}

function toWords(section: readonly Span[]): Word[] {
  const words: Word[] = [];
  let current: Word | null = null;
  let pendingGap: readonly StyleName[] | null = null;
  for (const span of section) {
    for (const part of span.text.split(/([ \t\n]+)/)) {
      if (part === "") continue;
      if (/^[ \t\n]+$/.test(part)) {
        if (current) {
          words.push(current);
          current = null;
        }
        pendingGap ??= span.styles;
        continue;
      }
      if (!current) {
        current = { pieces: [], width: 0, gapStyles: words.length === 0 ? null : pendingGap };
        pendingGap = null;
      }
      current.pieces.push({ text: part, styles: span.styles });
      current.width += columns(part);
    }
  }
  if (current) words.push(current);
  return words;
}

/**
 * Greedy word wrap at `width` terminal columns.
 *
 * The same algorithm marked-terminal used — runs of whitespace collapse to one
 * space, a word that does not fit starts the next line, and a word wider than the
 * whole line is cut into line-sized pieces — but measured in columns rather than
 * UTF-16 code units, cut only between graphemes, and applied to spans so a style
 * never crosses a line break.
 *
 * Hard breaks (`br` spans) always end a line.
 */
export function wrapSpans(spans: readonly Span[], width: number): Line[] {
  const limit = Math.max(1, Math.floor(width));
  const sections: Span[][] = [[]];
  for (const span of spans) {
    if (span.br) sections.push([]);
    else sections[sections.length - 1]!.push(span);
  }

  const lines: Line[] = [];
  for (const section of sections) {
    let line: Line = [];
    let used = 0;
    const flush = () => {
      lines.push(mergeSpans(line));
      line = [];
      used = 0;
    };

    for (const word of toWords(section)) {
      const gap = used > 0 ? 1 : 0;
      if (used + gap + word.width <= limit) {
        if (gap) line.push({ text: " ", styles: word.gapStyles ?? [] });
        line.push(...word.pieces);
        used += gap + word.width;
        continue;
      }
      if (word.width <= limit) {
        flush();
        line.push(...word.pieces);
        used = word.width;
        continue;
      }

      // Wider than a whole line: fill what is left of this one, then cut.
      let started = false;
      for (const piece of word.pieces) {
        for (const cluster of graphemes(piece.text)) {
          const w = clusterColumns(cluster);
          const needsGap = !started && used > 0;
          const cost = (needsGap ? 1 : 0) + w;
          if (used + cost > limit && used > 0) flush();
          if (!started && used > 0) {
            line.push({ text: " ", styles: word.gapStyles ?? [] });
            used += 1;
          }
          started = true;
          line.push({ text: cluster, styles: piece.styles });
          used += w;
        }
      }
    }
    if (line.length > 0) flush();
  }
  return lines;
}

import chalk, { Chalk, type ChalkInstance } from "chalk";
import { Marked, type Token, type Tokens } from "marked";
import { highlightCode } from "./highlight";
import {
  columns,
  lineText,
  mergeSpans,
  splitLines,
  wrapSpans,
  wrapStyle,
  type Line,
  type Span,
  type StyleName,
} from "./spans";

/**
 * Markdown to ANSI, walking marked's tokens.
 *
 * This replaced marked-terminal (unmaintained since 2025). It keeps that
 * renderer's visual vocabulary — `#` heading prefixes, `*` bullets, two-space
 * indents, `text (url)` links, box-drawn tables and its colour palette — and
 * fixes what it got wrong: list numbering, inline formatting in list items,
 * width measured in code units instead of columns, styles cut in half by line
 * breaks, full resets that erased enclosing styles, and OSC 8 hyperlinks whose
 * visible text could name a different URL from the one they opened.
 *
 * Internal. The public surface is `renderMarkdown(source)`.
 */

export interface TerminalMarkdownOptions {
  /** Wrap width in terminal columns. Default 80. */
  width?: number;
  /** Chalk colour level (0-3). Default: detected from the environment, like chalk itself. */
  level?: 0 | 1 | 2 | 3;
}

const DEFAULT_WIDTH = 80;
const INDENT = "  ";

type Styler = (text: string) => string;

function stylers(c: ChalkInstance): Record<StyleName, Styler> {
  return {
    h1: c.magenta.underline.bold,
    heading: c.green.bold,
    strong: c.bold,
    em: c.italic,
    codespan: c.yellow,
    del: c.dim.gray.strikethrough,
    link: c.blue,
    href: c.blue.underline,
    html: c.gray,
    blockquote: c.gray.italic,
    tableHead: c.red,
    tableBorder: c.gray,
    keyword: c.blue,
    built_in: c.cyan,
    type: c.cyan.dim,
    literal: c.blue,
    number: c.green,
    string: c.red,
    regexp: c.red,
    comment: c.green,
    function: c.yellow,
    class: c.blue,
    meta: c.gray,
    tag: c.gray,
    name: c.blue,
    attr: c.cyan,
    addition: c.green,
    deletion: c.red,
  };
}

const parser = new Marked();

// marked hands text through raw; these five are what an author types to mean a
// literal character. Code spans and code blocks are literal and never decoded.
const ENTITIES: Record<string, string> = { "&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": '"', "&#39;": "'" };
function decodeEntities(text: string): string {
  return text.replace(/&(?:amp|lt|gt|quot|#39);/g, (m) => ENTITIES[m] ?? m);
}

// ---------------------------------------------------------------------------
// Inline
// ---------------------------------------------------------------------------

function inline(tokens: readonly Token[] | undefined, outer: readonly StyleName[]): Span[] {
  const out: Span[] = [];
  for (const token of tokens ?? []) out.push(...inlineToken(token, outer));
  return out;
}

function span(text: string, outer: readonly StyleName[], style?: StyleName): Span {
  return { text, styles: style ? [...outer, style] : outer };
}

function inlineToken(token: Token, outer: readonly StyleName[]): Span[] {
  switch (token.type) {
    case "text": {
      const t = token as Tokens.Text;
      return t.tokens?.length ? inline(t.tokens, outer) : [span(decodeEntities(t.text), outer)];
    }
    case "escape":
      return [span((token as Tokens.Escape).text, outer)];
    case "strong":
      return inline((token as Tokens.Strong).tokens, [...outer, "strong"]);
    case "em":
      return inline((token as Tokens.Em).tokens, [...outer, "em"]);
    case "del":
      return inline((token as Tokens.Del).tokens, [...outer, "del"]);
    case "codespan":
      return [span((token as Tokens.Codespan).text, outer, "codespan")];
    case "br":
      return [{ text: "\n", styles: outer, br: true }];
    case "html":
      return [span((token as Tokens.HTML).text, outer, "html")];
    case "link": {
      const link = token as Tokens.Link;
      const within: StyleName[] = [...outer, "link"];
      const text = inline(link.tokens, within);
      const href = decodeEntities(link.href);
      const plain = text.map((s) => s.text).join("");
      // Always print the destination. An OSC 8 hyperlink shows only its label,
      // and in agent output the label is untrusted: `[https://bank](https://evil)`.
      if (plain === "" || plain === href) return [span(href, within, "href")];
      return [...text, span(" (", within), span(href, within, "href"), span(")", within)];
    }
    case "image": {
      const image = token as Tokens.Image;
      const title = image.title ? ` – ${image.title}` : "";
      return [span(`![${decodeEntities(image.text)}${title}](${decodeEntities(image.href)})`, outer)];
    }
    default: {
      const generic = token as { tokens?: Token[]; text?: string };
      if (generic.tokens?.length) return inline(generic.tokens, outer);
      return typeof generic.text === "string" ? [span(generic.text, outer)] : [];
    }
  }
}

// ---------------------------------------------------------------------------
// Blocks
// ---------------------------------------------------------------------------

/** Indent every line, blank ones included (a code block's or a quote's). */
function indent(lines: Line[]): Line[] {
  return lines.map((line) => [span(INDENT, []), ...line]);
}

/** Join rendered blocks, separated by `gap` blank lines. Empty blocks vanish. */
function joinBlocks(blocks: Line[][], gap: number): Line[] {
  const out: Line[] = [];
  for (const block of blocks) {
    if (block.length === 0) continue;
    if (out.length > 0) for (let i = 0; i < gap; i++) out.push([]);
    out.push(...block);
  }
  return out;
}

function blocks(tokens: readonly Token[], width: number, gap: number): Line[] {
  return joinBlocks(
    tokens.map((token) => block(token, width)),
    gap,
  );
}

function block(token: Token, width: number): Line[] {
  switch (token.type) {
    case "space":
    case "def":
      return [];
    case "heading": {
      const heading = token as Tokens.Heading;
      const style: StyleName = heading.depth === 1 ? "h1" : "heading";
      const spans = [span(`${"#".repeat(heading.depth)} `, [style]), ...inline(heading.tokens, [style])];
      return wrapSpans(spans, width);
    }
    case "paragraph":
      return wrapSpans(inline((token as Tokens.Paragraph).tokens, []), width);
    case "text": {
      const text = token as Tokens.Text;
      const spans = text.tokens?.length ? inline(text.tokens, []) : [span(decodeEntities(text.text), [])];
      return wrapSpans(spans, width);
    }
    case "code": {
      const code = token as Tokens.Code;
      const text = code.text.replace(/\n+$/, "");
      if (text === "") return [];
      return indent(splitLines(highlightCode(text, code.lang)));
    }
    case "blockquote": {
      const quote = token as Tokens.Blockquote;
      const body = trimBlankLines(blocks(quote.tokens, width - INDENT.length, 1));
      return wrapStyle(indent(body), "blockquote");
    }
    case "list":
      return list(token as Tokens.List, width);
    case "table":
      return table(token as Tokens.Table);
    case "hr":
      return [[span("-".repeat(Math.max(1, width - 1)), [])]];
    case "html": {
      const html = (token as Tokens.HTML).text.replace(/\n+$/, "");
      return html.split("\n").map((line) => (line === "" ? [] : [span(line, [], "html")]));
    }
    default: {
      const generic = token as { tokens?: Token[]; text?: string };
      if (generic.tokens?.length) return wrapSpans(inline(generic.tokens, []), width);
      return typeof generic.text === "string" ? wrapSpans([span(generic.text, [])], width) : [];
    }
  }
}

function trimBlankLines(lines: Line[]): Line[] {
  let start = 0;
  let end = lines.length;
  while (start < end && lineText(lines[start]!).trim() === "") start++;
  while (end > start && lineText(lines[end - 1]!).trim() === "") end--;
  return lines.slice(start, end);
}

function list(token: Tokens.List, width: number): Line[] {
  const start = typeof token.start === "number" ? token.start : 1;
  const out: Line[] = [];
  token.items.forEach((item, index) => {
    const marker = token.ordered ? `${start + index}. ` : "* ";
    const hanging = " ".repeat(marker.length);
    const textWidth = width - INDENT.length - marker.length;

    const entries: Array<{ line: Line; nested: boolean }> = [];
    item.tokens.forEach((child, childIndex) => {
      if (child.type === "list") {
        // A nested list indents from THIS list, not from the item's text — the
        // layout marked-terminal produced, kept so nested lists do not move.
        for (const line of list(child as Tokens.List, width - INDENT.length)) entries.push({ line, nested: true });
        return;
      }
      let lines = block(child, textWidth);
      if (childIndex === 0 && item.task) {
        const box = span(item.checked ? "[X] " : "[ ] ", []);
        lines = lines.length === 0 ? [[box]] : [[box, ...lines[0]!], ...lines.slice(1)];
      }
      for (const line of lines) entries.push({ line, nested: false });
    });

    // Blank lines never appear inside an item, which keeps loose lists compact —
    // also marked-terminal's behaviour.
    const content = entries.filter((entry) => entry.line.length > 0);
    if (content.length === 0) {
      out.push([span(INDENT + marker.trimEnd(), [])]);
      return;
    }
    content.forEach(({ line, nested }, i) => {
      const lead = i === 0 ? INDENT + marker : nested ? INDENT : INDENT + hanging;
      out.push([span(lead, []), ...line]);
    });
  });
  return out;
}

function table(token: Tokens.Table): Line[] {
  const header = token.header.map((cell) => flatten(inline(cell.tokens, [])));
  const rows = token.rows.map((row) => row.map((cell) => flatten(inline(cell.tokens, []))));
  const count = Math.max(header.length, ...rows.map((r) => r.length));
  const widths: number[] = [];
  for (let col = 0; col < count; col++) {
    const cells = [header[col], ...rows.map((r) => r[col])];
    widths.push(Math.max(0, ...cells.map((c) => (c ? columns(lineText(c)) : 0))));
  }

  const border = (left: string, mid: string, right: string): Line => [
    span(left + widths.map((w) => "─".repeat(w + 2)).join(mid) + right, ["tableBorder"]),
  ];
  const row = (cells: Line[], head: boolean): Line => {
    const line: Line = [span("│", ["tableBorder"])];
    for (let col = 0; col < count; col++) {
      const content = cells[col] ?? [];
      const free = widths[col]! - columns(lineText(content));
      const align = token.align[col];
      const left = align === "right" ? free : align === "center" ? Math.floor(free / 2) : 0;
      const cellSpans: Line = [span(" ".repeat(left + 1), []), ...content, span(" ".repeat(free - left + 1), [])];
      line.push(...(head ? cellSpans.map((s) => ({ ...s, styles: ["tableHead", ...s.styles] as StyleName[] })) : cellSpans));
      line.push(span("│", ["tableBorder"]));
    }
    return line;
  };

  const out: Line[] = [border("┌", "┬", "┐"), row(header, true)];
  rows.forEach((cells) => {
    out.push(border("├", "┼", "┤"), row(cells, false));
  });
  out.push(border("└", "┴", "┘"));
  return out;
}

/** Table cells are one line: hard breaks and newlines become spaces. */
function flatten(spans: Span[]): Line {
  return mergeSpans(spans.map((s) => ({ text: s.br ? " " : s.text.replace(/\n/g, " "), styles: s.styles })));
}

// ---------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------

const stylerCache = new WeakMap<ChalkInstance, Record<StyleName, Styler>>();

function toAnsi(lines: Line[], c: ChalkInstance): string {
  let table = stylerCache.get(c);
  if (!table) {
    table = stylers(c);
    stylerCache.set(c, table);
  }
  const styleFor = table;
  return lines
    .map((line) =>
      mergeSpans(line)
        .map((s) => s.styles.reduceRight((text, name) => styleFor[name](text), s.text))
        .join(""),
    )
    .join("\n");
}

const chalkByLevel = new Map<number, ChalkInstance>();

export function renderTerminalMarkdown(source: string, options: TerminalMarkdownOptions = {}): string {
  const width = options.width ?? DEFAULT_WIDTH;
  let c: ChalkInstance = chalk;
  if (options.level !== undefined) {
    c = chalkByLevel.get(options.level) ?? new Chalk({ level: options.level });
    chalkByLevel.set(options.level, c);
  }
  const tokens = parser.lexer(source);
  return toAnsi(trimEnd(blocks(tokens, width, 1)), c);
}

/**
 * Drop trailing whitespace from the document, before styling. Trimming the
 * ANSI string instead would stop at the first closing escape, so coloured
 * output would keep whitespace that plain output loses.
 */
function trimEnd(lines: Line[]): Line[] {
  const out = [...lines];
  while (out.length > 0 && lineText(out[out.length - 1]!).trim() === "") out.pop();
  const last = out[out.length - 1];
  if (!last) return out;
  const trimmed = mergeSpans(last).map((s) => ({ ...s }));
  while (trimmed.length > 0) {
    const tail = trimmed[trimmed.length - 1]!;
    tail.text = tail.text.replace(/\s+$/, "");
    if (tail.text !== "") break;
    trimmed.pop();
  }
  out[out.length - 1] = trimmed;
  return out;
}

import { useCallback } from "react";
import { useForm as inertiaUseForm } from "@inertiajs/react";

/**
 * Per-field bridge returned by `useFancyForm().field(name)`. Shaped to
 * drop directly into react-fancy form components without further
 * wiring.
 */
export interface FancyFieldBridge<T = unknown> {
  /** Pass to `<Input value={...} />` — current field value (string). */
  value: T;
  /** Pass to `<Input onChange={...} />`. Accepts the React event *or* a raw value (Select, Switch). */
  onChange: (e: React.ChangeEvent<HTMLInputElement> | T) => void;
  /** Pass to `<Input error={...} />` — last server validation error for this field. */
  error?: string;
  /** True while a submit is in flight. */
  loading?: boolean;
  /** Stable name attribute. */
  name: string;
}

/**
 * Bridge type returned by useFancyForm. Wraps Inertia's `useForm()` and
 * adds a `field(name)` helper that returns props ready to spread into
 * react-fancy's `<Input>`, `<Select>`, `<Switch>`, `<Textarea>`, etc.
 */
export interface FancyFormBridge<TData extends Record<string, unknown>> {
  data: TData;
  setData: <K extends keyof TData>(key: K, value: TData[K]) => void;
  errors: Partial<Record<keyof TData, string>>;
  processing: boolean;

  /**
   * Returns `{ value, onChange, error, loading, name }` for a field.
   * `onChange` accepts both a React change event (native input/textarea)
   * and a raw value (Select/Switch/MultiSwitch which pass the new value
   * directly).
   */
  field<K extends keyof TData & string>(name: K): FancyFieldBridge<TData[K]>;

  /** Forwarded from Inertia's useForm. */
  submit: (method: string, url: string, options?: object) => void;
  post: (url: string, options?: object) => void;
  put: (url: string, options?: object) => void;
  patch: (url: string, options?: object) => void;
  delete: (url: string, options?: object) => void;
  reset: (...fields: Array<keyof TData>) => void;
  clearErrors: (...fields: Array<keyof TData>) => void;
}

/**
 * Inertia's `useForm()` shape (loose typing — we don't import @inertiajs
 * statically since it's an optional peer when fancy-inertia is used
 * outside of Inertia for code-sharing reasons).
 */
type InertiaForm<T> = {
  data: T;
  setData: (key: keyof T, value: unknown) => void;
  errors: Partial<Record<keyof T, string>>;
  processing: boolean;
  submit: (method: string, url: string, options?: object) => void;
  post: (url: string, options?: object) => void;
  put: (url: string, options?: object) => void;
  patch: (url: string, options?: object) => void;
  delete: (url: string, options?: object) => void;
  reset: (...fields: Array<keyof T>) => void;
  clearErrors: (...fields: Array<keyof T>) => void;
};

/**
 * Wraps Inertia's `useForm()` so each field can be wired into react-fancy
 * inputs in one line:
 *
 *   const form = useFancyForm({ name: "", email: "" });
 *   <Input {...form.field("name")} placeholder="Name" />
 *   <Input {...form.field("email")} placeholder="Email" />
 *   <Button onClick={() => form.post("/users")}>Save</Button>
 *
 * Call signature mirrors `useForm()` from @inertiajs/react. Pass either
 * the initial values, or the result of `useForm(...)` if you've already
 * called it (lets you compose with library-supplied form objects):
 *
 *   const inertiaForm = useForm({ name: "" });
 *   const form = useFancyForm(inertiaForm);
 */
export function useFancyForm<TData extends Record<string, unknown>>(
  initialOrForm: TData | InertiaForm<TData>,
): FancyFormBridge<TData> {
  // If the consumer already called useForm() and passed the result in, re-use
  // it; otherwise instantiate one here.
  //
  // The shim is called UNCONDITIONALLY and at the top level. It used to live
  // inside a useMemo keyed on `initialOrForm`, which meant Inertia's useForm ran
  // only when that memo recomputed. Pass a stable reference — a module-level
  // constant, or anything memoised — and the memo is cached from the second
  // render on, the inner hooks are skipped, React's hook order desyncs, and the
  // next render dies with "Cannot read properties of undefined (reading
  // 'length')" from deep inside React.
  //
  // It hid well: every call site that passes an inline object literal gets a new
  // reference each render, so the memo always recomputed and the hooks always
  // ran. Only callers doing the tidier thing were affected.
  const provided = isInertiaForm<TData>(initialOrForm) ? initialOrForm : null;

  // EMPTY_INITIAL is module-level and therefore stable, so this costs one idle
  // Inertia form when a caller supplied their own. Rules of Hooks over
  // micro-optimisation: the alternative is a conditional hook.
  const shim = useInertiaFormShim<TData>(
    (provided ? EMPTY_INITIAL : initialOrForm) as TData,
  );

  const form: InertiaForm<TData> = provided ?? shim;

  const field = useCallback(
    <K extends keyof TData & string>(name: K): FancyFieldBridge<TData[K]> => ({
      name,
      value: form.data[name],
      onChange: (e) => {
        const next =
          e !== null && typeof e === "object" && "target" in (e as object)
            ? ((e as React.ChangeEvent<HTMLInputElement>).target as HTMLInputElement & {
                checked?: boolean;
                type?: string;
              })
            : null;
        if (next) {
          const value = next.type === "checkbox" ? next.checked : next.value;
          form.setData(name, value as unknown as TData[K]);
        } else {
          form.setData(name, e as unknown as TData[K]);
        }
      },
      error: form.errors[name],
      loading: form.processing,
    }),
    [form],
  );

  return {
    data: form.data,
    setData: form.setData as FancyFormBridge<TData>["setData"],
    errors: form.errors,
    processing: form.processing,
    field,
    submit: form.submit,
    post: form.post,
    put: form.put,
    patch: form.patch,
    delete: form.delete,
    reset: form.reset,
    clearErrors: form.clearErrors,
  };
}

function isInertiaForm<T>(x: unknown): x is InertiaForm<T> {
  return (
    typeof x === "object" &&
    x !== null &&
    "data" in (x as object) &&
    "setData" in (x as object) &&
    "errors" in (x as object) &&
    "processing" in (x as object)
  );
}

/**
 * Stable placeholder for the case where the caller supplied their own form.
 * Module-level so the reference never changes between renders.
 */
const EMPTY_INITIAL = Object.freeze({}) as Record<string, unknown>;

function useInertiaFormShim<TData extends Record<string, unknown>>(initial: TData): InertiaForm<TData> {
  return inertiaUseForm(initial as any) as unknown as InertiaForm<TData>;
}

import { useCallback, useRef, useState } from "react";
import { runFlow, type RunOptions, type RunResult } from "./run-flow";
import { getNodeKind } from "../lib/registry/registry";
import type {
  ExecutorRegistry,
  FlowGraph,
  NodeRunStatus,
  RunEvent,
} from "../lib/types";

export type FlowRunFeedEntry = {
  id: string;
  at: number;
  /**
   * `message` is a node's own human-facing announcement (`startingMsg` /
   * `stoppingMsg`), kept distinct from `status` and `info` so a progress UI can
   * show ONLY the narration. Folded in with diagnostics it would be unfindable,
   * which is the same as not having it.
   */
  level: "info" | "warn" | "error" | "status" | "message";
  text: string;
  nodeId?: string;
  detail?: unknown;
};

export type UseFlowRunReturn = {
  /** Status keyed by nodeId — drive the UI overlay from this. */
  statuses: Record<string, NodeRunStatus>;
  /** Per-node status text (e.g. error message). */
  statusText: Record<string, string | undefined>;
  /** Latest computed output value per node (for reactive kinds). */
  outputs: Record<string, unknown>;
  /**
   * Latest status message per nodeId, from the node's own `startingMsg` /
   * `stoppingMsg`. Undefined for the nodes that declared none, which is most
   * of them by design.
   */
  nodeMessages: Record<string, string | undefined>;
  /** Live event log (capped to last N). */
  feed: FlowRunFeedEntry[];
  /** Whether a run is currently in progress. */
  running: boolean;
  /** Last run result, or null. */
  lastResult: RunResult | null;
  /** Kick off a run with the provided graph + executors. */
  run: (graph: FlowGraph, executors: ExecutorRegistry, options?: RunOptions) => Promise<RunResult>;
  /** Cancel the current run (if any). */
  cancel: () => void;
  /** Reset all runtime state (statuses, feed, lastResult). */
  reset: () => void;
};

export type UseFlowRunOptions = {
  /** Cap the in-memory feed to this many entries. Default 200. */
  maxFeed?: number;
};

/**
 * useFlowRun — drives `runFlow` + maintains observability state. Pair with
 * `applyStatusesToNodes` (below) before passing nodes to `<FlowCanvas>` so
 * the per-node status badge renders.
 */
export function useFlowRun({ maxFeed = 200 }: UseFlowRunOptions = {}): UseFlowRunReturn {
  const [statuses, setStatuses] = useState<Record<string, NodeRunStatus>>({});
  const [statusText, setStatusText] = useState<Record<string, string | undefined>>({});
  const [nodeMessages, setNodeMessages] = useState<Record<string, string | undefined>>({});
  const [outputs, setOutputs] = useState<Record<string, unknown>>({});
  const [feed, setFeed] = useState<FlowRunFeedEntry[]>([]);
  const [running, setRunning] = useState(false);
  const [lastResult, setLastResult] = useState<RunResult | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const handleEvent = useCallback(
    (e: RunEvent) => {
      switch (e.type) {
        case "node-status":
          setStatuses((s) => ({ ...s, [e.nodeId]: e.status }));
          setStatusText((t) => ({ ...t, [e.nodeId]: e.text }));
          appendFeed({ level: "status", text: `${e.nodeId} → ${e.status}${e.text ? ` (${e.text})` : ""}`, nodeId: e.nodeId });
          break;
        case "node-message":
          setNodeMessages((m) => ({ ...m, [e.nodeId]: e.message }));
          appendFeed({ level: "message", text: e.message, nodeId: e.nodeId });
          break;
        case "node-output":
          setOutputs((o) => ({ ...o, [e.nodeId]: e.value }));
          appendFeed({ level: "info", text: `${e.nodeId}.${e.portId} = ${preview(e.value)}`, nodeId: e.nodeId, detail: e.value });
          break;
        case "log":
          appendFeed({ level: e.level, text: e.message, nodeId: e.nodeId, detail: e.detail });
          break;
        case "run-start":
          appendFeed({ level: "info", text: "▶ run started" });
          break;
        case "run-end":
          appendFeed({ level: e.ok ? "info" : "error", text: e.ok ? "✓ run complete" : "✗ run failed" });
          break;
        case "run-error":
          appendFeed({ level: "error", text: e.error });
          break;
      }
      function appendFeed(partial: Omit<FlowRunFeedEntry, "id" | "at">) {
        setFeed((f) => {
          const entry: FlowRunFeedEntry = { id: `${Date.now()}_${f.length}`, at: Date.now(), ...partial };
          const next = [...f, entry];
          return next.length > maxFeed ? next.slice(next.length - maxFeed) : next;
        });
      }
    },
    [maxFeed],
  );

  const run = useCallback(
    async (graph: FlowGraph, executors: ExecutorRegistry, options: RunOptions = {}) => {
      if (running) {
        return { ok: false, outputs: {}, error: "another run is already in progress" } satisfies RunResult;
      }
      const controller = new AbortController();
      abortRef.current = controller;
      // Reset previous statuses for the nodes we're about to run.
      const idleStatuses: Record<string, NodeRunStatus> = {};
      for (const n of graph.nodes) idleStatuses[n.id] = "idle";
      setStatuses(idleStatuses);
      setStatusText({});
      setOutputs({});
      setRunning(true);
      try {
        const result = await runFlow(graph, executors, handleEvent, { ...options, signal: controller.signal });
        setLastResult(result);
        return result;
      } finally {
        setRunning(false);
        abortRef.current = null;
      }
    },
    [handleEvent, running],
  );

  const cancel = useCallback(() => abortRef.current?.abort(), []);

  const reset = useCallback(() => {
    setStatuses({});
    setStatusText({});
    setOutputs({});
    setFeed([]);
    setLastResult(null);
  }, []);

  return { statuses, statusText, nodeMessages, outputs, feed, running, lastResult, run, cancel, reset };
}

/**
 * Write each reactive kind's latest run output into its `data.output`, so its
 * card can render the computed value live. Non-reactive kinds are returned
 * untouched. Pair with `applyStatusesToNodes` before rendering.
 */
export function applyOutputsToNodes<TNode extends { id: string; type?: string; data: any }>(
  nodes: TNode[],
  outputs: Record<string, unknown>,
): TNode[] {
  return nodes.map((n) => {
    const kind = getNodeKind((n.data as any)?.kind ?? n.type ?? "");
    if (!kind?.reactive || !(n.id in outputs)) return n;
    return { ...n, data: { ...n.data, output: outputs[n.id] } };
  });
}

/** Merge runtime statuses into nodes for rendering. */
export function applyStatusesToNodes<TNode extends { id: string; data: any }>(
  nodes: TNode[],
  statuses: Record<string, NodeRunStatus>,
  statusText: Record<string, string | undefined>,
): TNode[] {
  return nodes.map((n) => ({
    ...n,
    data: {
      ...n.data,
      status: statuses[n.id] ?? n.data?.status ?? "idle",
      statusText: statusText[n.id] ?? n.data?.statusText,
    },
  }));
}

function preview(v: unknown): string {
  try {
    const s = JSON.stringify(v);
    return s && s.length > 60 ? s.slice(0, 57) + "…" : (s ?? String(v));
  } catch {
    return String(v);
  }
}

import type {
  ExecutorRegistry,
  FlowEdge,
  FlowGraph,
  FlowNode,
  NodeExecutor,
  RunEvent,
} from "../lib/types";
// Both modules are React-free by design — the `/engine` entry must not pull in
// React. Import them directly rather than via the `registry` barrel, which
// re-exports the RegistryNode component.
import { getNodeKind, kindIds } from "../lib/registry/registry";
import { resolveNodePorts } from "../lib/registry/ports";
import { RunIdentity, type RunIdentityJson } from "./run-identity";
import { TerminalSessions, specForLane } from "./terminal-sessions";
import { undeliveredEdgeWarnings } from "./undelivered-edges";
import { resolveWorkflowProps } from "./workflow-props";

export type RunOptions = {
  /** Stop the run after this many ms. Default: no timeout. */
  timeoutMs?: number;
  /** Abort signal — host can cancel the run. */
  signal?: AbortSignal;
  /** Initial inputs supplied to entry-point nodes (no incoming edges). */
  initialInputs?: Record<string, Record<string, unknown>>;
  /**
   * Values for the inputs the graph DECLARES, passed by name.
   *
   * The flat, node-id-free way to configure a run. `initialInputs` is keyed by
   * node id, so a caller had to know the trigger was called `t` and a rename
   * broke every caller while the graph stayed valid. Props are checked against
   * `graph.inputs`, so a misspelling fails the run instead of sitting unread.
   */
  props?: Record<string, unknown>;
  /**
   * Which ENTRY POINTS are live — the ids of nodes with NO incoming edges this
   * run should start from. Omit it and every entry point runs, exactly as
   * before the option existed.
   *
   * A graph may hold more than one trigger — a `manual_trigger` for
   * hand-testing beside the event trigger that runs it for real — and a trigger
   * has no inbound edges, which IS the readiness rule. So without this, every
   * trigger's branch runs on every run, whichever one fired. The triggers
   * themselves are harmless; everything DOWNSTREAM of the ones that did not
   * fire is not. A `user_input` stranded on the manual branch parks an
   * event-driven run to ask a person for data the event already supplied,
   * which from outside looks like the event trigger being ignored.
   *
   * Naming the live entry points makes the others INACTIVE, and the existing
   * "at least one active inbound edge" rule then skips everything reachable
   * only from them. No new routing logic.
   *
   * Three edges, each pinned by `flow/entry-points` in
   * `@particle-academy/fancy-conformance`:
   *  - `undefined` is NOT `[]`. Unset runs every entry point; an empty array
   *    says none is live and runs nothing.
   *  - A node reachable from SEVERAL entry points still runs when any one of
   *    them fires — one active inbound edge is enough, as always.
   *  - Naming a node that HAS inbound edges names no entry point, so every real
   *    entry is inactive and nothing runs. That falls out of the rule rather
   *    than being special-cased; validate your ids if you want a typo to be
   *    loud, because the runtime cannot tell one from a deliberate empty
   *    selection.
   */
  entryNodes?: string[];
  /** Nesting depth — set by `subflow` when it runs a child graph. */
  depth?: number;
  /**
   * Who is running, so a writing node can derive a stable idempotency key.
   *
   * A bare string is taken as the run key. **Deliberately not defaulted:** a
   * minted-per-call key would change on every whole-run retry, which is exactly
   * the failure an idempotency key exists to prevent — so a host that has not
   * supplied one gets `ctx.run === undefined` and a connector that declines to
   * write blind, rather than a plausible-looking key that double-charges.
   */
  run?: RunIdentity | RunIdentityJson | string;
  /**
   * Outputs already checkpointed for this run, keyed by node id.
   *
   * A node present here is **republished, not re-executed** — its stored value
   * goes back onto the same ports, so downstream routing reproduces exactly
   * what it did the first time. This is what makes a per-node durable driver
   * possible without a second copy of the routing rules, and it is how the PHP
   * and Python runtimes have always resumed.
   */
  resumeOutputs?: Record<string, unknown>;
  /**
   * Executors bound to ONE node id each, matched against `node.id` and nothing
   * else. They outrank every entry of the executor registry.
   *
   * The registry cannot say this. It is one flat object, and `executorLookupIds`
   * tries a key as the node's id AND as its kind, so a key that is both is both:
   * binding `host_kind` to pin the node CALLED `host_kind` also rebinds every
   * node whose kind is `host_kind`. That is the registry's contract (pinned by
   * `flow/executor-resolution`) and it stays. This is the separate channel for a
   * binding that must not leak into the kind namespace -- the PHP twin's
   * `bindNode`, which has always been kept apart from `bind`.
   *
   * The durable replay fences every node but its target through this. Through
   * the registry, a node whose id matched a kind fenced every node of that kind,
   * and the durable run reported success having run nothing.
   *
   * NOT handed down to a nested run. Node ids belong to one graph: a `subflow`
   * child's `t` is not its parent's `t`, so `ctx.executors` stays the registry
   * alone.
   */
  nodeExecutors?: Record<string, NodeExecutor>;
};

export type RunResult = {
  ok: boolean;
  /** Outputs collected per node, keyed by node id. */
  outputs: Record<string, unknown>;
  /** Error captured if any node threw. */
  error?: string;
};

/**
 * runFlow — topological execution of a FlowGraph against an ExecutorRegistry.
 *
 * Each node runs once, when all upstream nodes have produced outputs on the
 * connected ports. Decision nodes (or any executor that returns `{ branch:
 * 'true' }`) can short-circuit specific output ports — only edges leaving
 * an "active" port propagate to downstream nodes.
 *
 * Cycles are detected and abort the run with an error.
 *
 * The `onEvent` callback receives a stream of `RunEvent`s — wire it to a
 * status feed, log panel, or store.
 */
export async function runFlow(
  graph: FlowGraph,
  executors: ExecutorRegistry,
  onEvent: (event: RunEvent) => void = () => {},
  options: RunOptions = {},
): Promise<RunResult> {
  const { signal, initialInputs = {}, timeoutMs, depth = 0, resumeOutputs = {}, entryNodes, nodeExecutors } = options;
  const run = options.run === undefined ? undefined : RunIdentity.from(options.run);
  const outputs: Record<string, unknown> = {};
  const portValues = new Map<string, unknown>(); // key: `${nodeId}:${portId}`
  const completed = new Set<string>();
  const errors: string[] = [];

  // Topological order via Kahn's algorithm. We allow nodes to run as soon
  // as their incoming edges' source ports have produced values, so the
  // order here is just a deterministic baseline used for cycle detection.
  const order = topoSort(graph);
  if (order === null) {
    const msg = "Cycle detected in flow graph — aborting.";
    onEvent({ type: "run-error", error: msg });
    return { ok: false, outputs, error: msg };
  }

  // Props are checked BEFORE anything runs, and a failure aborts the run.
  //
  // Before a node executes, not after: a workflow whose third node needed a
  // value the caller misspelled would otherwise do two nodes' worth of real
  // work — sending, writing, charging — and only then discover the call was
  // malformed. Validation that happens after a side effect is not validation.
  const propsCheck = resolveWorkflowProps(graph.inputs, options.props);
  if (!propsCheck.ok) {
    onEvent({ type: "run-error", error: propsCheck.error });
    return { ok: false, outputs, error: propsCheck.error };
  }
  const props = propsCheck.props;
  const declaresProps = (graph.inputs?.length ?? 0) > 0;

  const incomingByNode = indexIncoming(graph.edges);
  // Built ONCE. Used only to explain an undelivered edge, but building it per
  // node would make a diagnostic quietly O(n^2) on the hot path.
  const nodesById = new Map(graph.nodes.map((n) => [n.id, n]));

  // Terminal lanes. Constructed unconditionally and costing nothing until a
  // node inside one actually runs — a graph with no terminal lane never asks
  // for a host, so nothing spawns and nothing needs one registered.
  const sessions = new TerminalSessions(graph);
  const isTerminalLane = (candidate: FlowNode): boolean =>
    getNodeKind(candidate.type ?? "")?.name === "@particle-academy/terminal_lane";

  const terminalAccessorFor = (node: FlowNode) => {
    const laneId = sessions.laneFor(node.id, isTerminalLane);
    if (laneId === null) return undefined;

    const lane = graph.nodes.find((n) => n.id === laneId);
    if (!lane) return undefined;

    // Returned as a FUNCTION rather than an open session, so the terminal opens
    // on first USE rather than when a node in the lane starts. A node that
    // never touches its terminal never spawns one, which is what makes the
    // lane safe to draw around nodes that mostly do other things.
    return {
      session: () => sessions.session(laneId, specForLane(lane)),
      // Awaits the session first on purpose. A transcript handed out before
      // anything is feeding it would look perfectly healthy and match nothing,
      // and "waited and nothing came" is the hardest failure here to tell apart
      // from a process that is simply slow.
      transcript: async () => {
        await sessions.session(laneId, specForLane(lane));
        return sessions.transcriptFor(laneId);
      },
    };
  };

  const timer = timeoutMs ? setTimeout(() => errors.push(`Run timed out after ${timeoutMs}ms`), timeoutMs) : null;

  onEvent({ type: "run-start" });

  try {
    for (const node of order) {
      if (signal?.aborted) throw new Error("aborted");
      if (errors.length) break;

      // A checkpointed node is republished, never re-executed. Publishing the
      // stored value back onto its own ports is what makes the resume exact:
      // the branch it took, the ports it lit and the inputs its successors
      // collect are all reproduced by the engine's own rules rather than by a
      // driver's recollection of them.
      if (Object.prototype.hasOwnProperty.call(resumeOutputs, node.id)) {
        const stored = resumeOutputs[node.id];
        outputs[node.id] = stored;
        const activated = activatedPorts(node, stored);
        for (const portId of activated.ports) {
          const value = portValueOf(activated, portId);
          portValues.set(`${node.id}:${portId}`, value);
          onEvent({ type: "node-output", nodeId: node.id, portId, value });
        }
        completed.add(node.id);
        onEvent({ type: "node-status", nodeId: node.id, status: "done", text: "resumed" });
        continue;
      }

      const incoming = incomingByNode.get(node.id) ?? [];

      // An ENTRY POINT this run did not start from is inactive.
      //
      // A node with no inbound edges is unconditionally ready -- that IS the
      // readiness rule -- so a graph with two triggers ran both branches on
      // every run, whichever trigger actually fired. Marking the unnamed ones
      // inactive here lets the "at least one active inbound edge" test below
      // skip everything reachable only from them, with no new routing logic.
      //
      // Gates only nodes with NO incoming edges: a node further down the graph
      // is not an entry point, and its readiness is still decided by its edges.
      if (incoming.length === 0 && entryNodes !== undefined && !entryNodes.includes(node.id)) {
        onEvent({ type: "node-status", nodeId: node.id, status: "idle", text: "skipped" });
        continue;
      }

      // AN EDGE THAT DELIVERS NOTHING MUST SAY SO.
      //
      // Checked HERE, before the activity gate, because the two outcomes are
      // both silent and only one reaches `collectInputs`: a node whose only
      // inbound edge is bad is SKIPPED, and one with another live edge RUNS with
      // that port missing. The rule itself lives in `undeliveredEdgeWarnings`,
      // which the durable coordinator also asks at its skip decision -- one
      // implementation, so the two paths cannot disagree about a handle.
      for (const warning of undeliveredEdgeWarnings(node, incoming, portValues, completed, nodesById)) {
        onEvent(warning);
      }

      // Run a node once any upstream branch reaches it. We iterate in
      // topological order, so by the time we reach this node every upstream
      // node has been processed — each incoming edge is therefore *settled*
      // (active or dead, never still-pending). Requiring ALL incoming edges to
      // be active wrongly skipped MERGE POINTS: when a Decision routes down one
      // branch, the other branch's edge stays dead forever, so an `every` check
      // skipped the shared continuation node and halted the run after the first
      // branch (#1). Run when AT LEAST ONE incoming edge is active —
      // collectInputs() only reads from the active ones. A genuine parallel
      // join still works: in topo order both of its inputs are already active.
      if (incoming.length > 0) {
        const anyActive = incoming.some((e) => portValues.has(`${e.source}:${e.sourceHandle ?? "out"}`));
        if (!anyActive) {
          onEvent({ type: "node-status", nodeId: node.id, status: "idle", text: "skipped" });
          continue;
        }
      }

      // Notes/annotations + layout (lane/pool) nodes are visual only — never
      // executed and never fed to runners. Their config (a note's text, a lane's
      // title) stays in the document for editors + MCP tools, but the engine
      // walks straight past them. Edges cross lanes freely, so grouping never
      // affects topology.
      const visualKind = getNodeKind(node.type ?? "");
      const isLayout = visualKind?.category === "layout";
      const isAnnotation = node.type === "note" || visualKind?.category === "annotation";
      if (isLayout || isAnnotation) {
        onEvent({
          type: "node-status",
          nodeId: node.id,
          status: "idle",
          text: isLayout ? "lane" : "annotation",
        });
        continue;
      }

      onEvent({ type: "node-status", nodeId: node.id, status: "running" });
      announce(onEvent, node, "start");

      const inputs = collectInputs(node, incoming, portValues, initialInputs, props, declaresProps);
      const exec = pickExecutor(executors, node, nodeExecutors);
      if (!exec) {
        // Name what was LOOKED FOR, not just what the node calls itself.
        //
        // This said `kind=${node.type}` — so a registry keyed under one of the
        // kind's other ids produced "kind=manual_trigger is missing" about a
        // kind that exists AND is registered, just under a different key. The
        // consumer who reported it reasonably read that as the kind being
        // absent and went looking for a missing package.
        // The wildcard is part of `executorLookupIds` now, so it is already in
        // the list — appending "and the wildcard" as well made the message name
        // it twice, and the test that reads the ids back out of the message
        // parsed the prose between the two quoted stars as an id.
        const tried = executorLookupIds(node);
        const msg = `No executor registered for kind=${node.type}`
          + ` — tried ${tried.map((id) => `"${id}"`).join(", ")}`
          + `. Key your registry by one of those.`;
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }

      try {
        const result = await Promise.resolve(
          exec({
            node,
            inputs,
            abort: (reason) => { throw new Error(reason ?? "aborted"); },
            emit: onEvent,
            executors,
            depth,
            run,
            // Structural executors derive a nested lane from the graph they are
            // in; `for_each`'s `item` port cannot be implemented without it.
            graph,
            terminal: terminalAccessorFor(node),
          }),
        );
        outputs[node.id] = result;

        // Decide which output ports were activated. Three conventions:
        //  1) If result is `{ __port: "out", value: x }`, only that port emits.
        //  2) If result has `branch: <portId>`, only that port emits (decision sugar).
        //  3) If result has `__ports`, exactly those emit — a list shares one
        //     payload, a map gives each its own.
        //  4) Otherwise, the value is published on every declared output port.
        const activated = activatedPorts(node, result);
        for (const portId of activated.ports) {
          const value = portValueOf(activated, portId);
          portValues.set(`${node.id}:${portId}`, value);
          onEvent({ type: "node-output", nodeId: node.id, portId, value });
        }
        completed.add(node.id);
        onEvent({ type: "node-status", nodeId: node.id, status: "done" });
        // Only on the success path, and deliberately so: a `stoppingMsg` of
        // "Analysis complete" emitted after a throw tells a human the opposite
        // of what happened, in the part of the UI they trust most. A failure
        // reports through node-status/log, which is what those exist for.
        announce(onEvent, node, "end");
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }
    }
  } finally {
    if (timer) clearTimeout(timer);

    // Terminals close HERE, in the same `finally` that clears the timer, so
    // they go away on the error and abort paths too — not only when a run ends
    // tidily. A PTY that outlives its run is a process nobody is watching and
    // nothing will close.
    //
    // Failures are reported and swallowed rather than thrown: this is the
    // teardown path, and throwing would replace the run's real error with a
    // cleanup error, hiding what actually went wrong behind the consequence.
    for (const error of await sessions.closeAll()) {
      onEvent({ type: "log", level: "warn", message: `terminal close failed: ${error.message}` });
    }
  }

  const ok = errors.length === 0;
  onEvent({ type: "run-end", ok });
  return ok ? { ok, outputs } : { ok, outputs, error: errors[0] };
}

function indexIncoming(edges: FlowEdge[]): Map<string, FlowEdge[]> {
  const map = new Map<string, FlowEdge[]>();
  for (const e of edges) {
    const list = map.get(e.target) ?? [];
    list.push(e);
    map.set(e.target, list);
  }
  return map;
}

function topoSort(graph: FlowGraph): FlowNode[] | null {
  const inDegree = new Map<string, number>();
  for (const n of graph.nodes) inDegree.set(n.id, 0);
  for (const e of graph.edges) inDegree.set(e.target, (inDegree.get(e.target) ?? 0) + 1);
  const queue: string[] = [];
  for (const [id, d] of inDegree) if (d === 0) queue.push(id);
  const ordered: string[] = [];
  while (queue.length) {
    const id = queue.shift()!;
    ordered.push(id);
    for (const e of graph.edges) {
      if (e.source !== id) continue;
      const next = (inDegree.get(e.target) ?? 0) - 1;
      inDegree.set(e.target, next);
      if (next === 0) queue.push(e.target);
    }
  }
  if (ordered.length !== graph.nodes.length) return null;
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  return ordered.map((id) => byId.get(id)!).filter(Boolean);
}

function collectInputs(
  node: FlowNode,
  incoming: FlowEdge[],
  portValues: Map<string, unknown>,
  initial: Record<string, Record<string, unknown>>,
  props: Record<string, unknown>,
  declaresProps: boolean,
): Record<string, unknown> {
  const inputs: Record<string, unknown> = { ...(initial[node.id] ?? {}) };

  // ENTRY POINTS are seeded with the props by their bare names.
  //
  // This is what lets an existing graph keep working unchanged. A trigger that
  // reads `{{ topic }}` was fed by `initialInputs[triggerId].topic`; a caller
  // moving to props passes `{ topic }` and the node sees exactly what it saw
  // before. Only entry points, because a node in the middle of a graph reading
  // a bare `topic` would be shadowing whatever its upstream edge is called.
  //
  // Never clobbers: a value already seeded by the host is the host's.
  if (incoming.length === 0) {
    for (const [name, value] of Object.entries(props)) {
      if (!(name in inputs)) inputs[name] = value;
    }
  }
  for (const e of incoming) {
    const portId = e.targetHandle ?? "in";
    const key = `${e.source}:${e.sourceHandle ?? "out"}`;
    // A branch that never fired has no entry in portValues. Assigning its
    // `undefined` would CLOBBER the value the branch that DID fire already
    // contributed on this same handle — emptying every merge point downstream
    // of a decision, silently, with the run still reporting success.
    //
    // This is the other half of the merge-point bug above: that fix stopped the
    // shared continuation node being skipped, but it still arrived with nothing
    // whenever a later inactive edge happened to be last in `incoming`.
    if (!portValues.has(key)) continue;
    inputs[portId] = portValues.get(key);

    // ALSO address it by the SOURCE NODE'S ID, when the edge named no handle.
    //
    // Authors reach for node ids -- every graph tool addresses nodes that way,
    // so `{{ n2.text }}` is the first thing written, by people and far more
    // often by assistants generating graphs. That resolved to nothing, and
    // NOTHING FAILED: an unresolvable path yields "", so the node ran, the run
    // reported success, and the damage was output that was quietly wrong. A
    // consumer shipped a file named `document.md` containing the literal text
    // of its own template, on a green run (fancy-flow-php#8).
    //
    // `targetHandle` already covers this and stays the right mechanism for
    // reading something other than the immediate predecessor -- but it is set
    // on the EDGE, which is not where an author is looking while writing a
    // node's config. The model was not wrong; the obvious spelling meant
    // nothing.
    //
    // Only for edges that declared NO handle: an edge that named one said what
    // it meant, and a second key under the source id would quietly widen a
    // deliberate contract. `??=` so nothing already seeded -- by the host's
    // initialInputs or an earlier edge -- is ever clobbered.
    if (e.targetHandle == null && !(e.source in inputs)) {
      inputs[e.source] = portValues.get(key);
    }
  }

  // EVERY node gets `$props` — but ONLY when the workflow declares inputs.
  //
  // The first half is what makes props usable at depth. Seeding entry points
  // alone would mean a node six hops downstream had the value threaded through
  // every edge in between, and every hop is somewhere it can be dropped. It
  // costs nothing to resolve because `$props` is an ORDINARY KEY in the inputs
  // object: `resolvePath` already walks dot-paths against it, so
  // `{{ $props.topic }}` works with no change to any expression resolver in any
  // of the three runtimes.
  //
  // The second half is a CORRECTION, and the golden parity fixtures caught it.
  // An earlier draft wrote `$props` unconditionally, justified as "so
  // `{{ $props.x }}` resolves to null rather than throwing" — which is not
  // true. `resolvePath` returns null for any unresolvable path, so on a graph
  // declaring nothing the key changes no behaviour at all. What it DOES do is
  // add a key to every executor's inputs, on every graph, forever — which
  // showed up instantly as a diff in every stored golden.
  //
  // `ConnectorFacet::from` states the same rule for the same reason: a payload
  // gaining a key on every entry is a wire change for no gain, and the ABSENCE
  // of a key is already the honest way to say "this one takes no props".
  //
  // Keyed on the DECLARATION rather than on whether a value arrived: a workflow
  // whose inputs are all optional and all omitted still declared a contract, so
  // `$props` is present and empty.
  if (declaresProps) inputs.$props = props;

  return inputs;
}

/**
 * Every key a node's executor may legitimately be registered under, in
 * precedence order. **This is the resolution rule** — `pickExecutor` walks this
 * list and takes the first hit, and the failure message lists the same ids.
 *
 * That sharing is the point, and it used to be a claim rather than a fact: this
 * docblock already said "shared by the lookup and by its failure message" while
 * `pickExecutor` re-implemented the walk beside it. The two agreed until the
 * precedence changed, and then the message listed an id the lookup no longer
 * tried — sending a reader to check something that never happened, which the
 * comment correctly named as worse than listing nothing. **Prose next to a check
 * is not the check.** One list now, walked by both, so they cannot drift.
 *
 * The order, and why:
 *
 * 1. `node.id` — the per-node override. First so a graph can pin ONE node to a
 *    stub without unbinding that kind for every other node using it.
 * 2. `node.type`, then every id its kind answers to — **if `node.type` names a
 *    registered kind, it is authoritative and `data.kind` is not consulted at
 *    all.** A node that says it is an `llm_call` must never quietly run another
 *    kind's code; it fails closed instead.
 * 3. Otherwise `data.kind` and its kind's ids. A `node.type` naming no
 *    registered kind is not a claim about behaviour — usually it is an xyflow
 *    RENDERER type (`"fancyNode"`), which is ordinary practice, and then
 *    `data.kind` is the only real answer. This branch also covers `type` absent.
 * 4. `"*"` — the wildcard, last, and a sentinel rather than a kind: it is never
 *    expanded through the alias machinery, or every unmatched node would bind to
 *    whatever a kind literally named `*` aliased to.
 *
 * Pinned as `flow/executor-resolution` in `@particle-academy/fancy-conformance`.
 */
function executorLookupIds(node: FlowNode): string[] {
  const ids: string[] = [node.id];
  if (node.type) ids.push(node.type);

  const typeKind = node.type ? getNodeKind(node.type) : null;

  if (typeKind) {
    for (const id of kindIds(typeKind)) ids.push(id);
  } else {
    const declared = (node.data as { kind?: unknown } | undefined)?.kind;
    const kindName = typeof declared === "string" && declared !== "" ? declared : null;

    if (kindName) {
      ids.push(kindName);
      const dataKind = getNodeKind(kindName);
      if (dataKind) {
        for (const id of kindIds(dataKind)) ids.push(id);
      }
    }
  }

  ids.push("*");

  return [...new Set(ids)];
}

function pickExecutor(
  executors: ExecutorRegistry,
  node: FlowNode,
  nodeExecutors?: Record<string, NodeExecutor>,
): NodeExecutor | undefined {
  // A node-only binding is looked up by the node's id and NO other key, which
  // is the whole reason it is not an entry in `executors` (see
  // `RunOptions.nodeExecutors`). Own properties only: a node called
  // `constructor` must not find `Object`.
  const pinned = nodeExecutors && Object.prototype.hasOwnProperty.call(nodeExecutors, node.id)
    ? nodeExecutors[node.id]
    : undefined;
  if (pinned) return pinned;

  // The whole rule lives in `executorLookupIds` -- see its docblock. Walking
  // that one list is what keeps the resolution and the failure message from
  // ever disagreeing about which keys were tried.
  //
  // The HOST registry is consulted first, and that order is the contract: a
  // kind ships an executor as a default, and a host that registers its own
  // takes over. Reversing it would make a builtin unoverridable.
  for (const id of executorLookupIds(node)) {
    if (executors[id]) return executors[id];
  }

  // Then the kind's own, for the kinds that ship one.
  //
  // This fallback did not exist, and `NodeKindDefinition.executor` was
  // therefore a field nothing read. `subflow` and `llm_router` have both
  // declared one since they were written, and both were unreachable through
  // `runFlow`: a consumer who called `registerBuiltinKinds()` and ran a graph
  // containing a subflow node got "No executor registered for kind=subflow"
  // about a kind that ships its executor in the same object as its schema.
  //
  // It survived because the two are unit-tested by calling the executor
  // directly — which proves the executor works and says nothing about whether
  // anything can reach it. A declared capability with no reader is the shape
  // this estate keeps finding, and the only reliable way to catch it is a test
  // that goes through the front door.
  return getNodeKind(node.type ?? "")?.executor;
}

function activatedPorts(node: FlowNode, result: unknown): { ports: string[]; value: unknown; values?: Record<string, unknown> } {
  if (result && typeof result === "object") {
    const r = result as Record<string, unknown>;
    if (typeof r.__port === "string") {
      return { ports: [r.__port], value: r.value };
    }
    // A CHOSEN SUBSET (fancy-flow-php#18): a list lights those ports with one
    // payload, a map gives each lit port its own. Before this a node could light
    // one port or all of them, so a router that matched two of five had to drop
    // work or wake lanes nobody asked for.
    //
    // An empty list lights NOTHING, deliberately — the same rule an explicitly
    // empty `outputs` array follows below. `values` is read per port, so a
    // payload that is present and null stays null rather than falling back to
    // the whole result, which is the trap `branch` already had to learn.
    if (Array.isArray(r.__ports)) {
      return { ports: r.__ports.filter((p): p is string => typeof p === "string"), value: r.value };
    }
    if (r.__ports && typeof r.__ports === "object") {
      const values = r.__ports as Record<string, unknown>;
      return { ports: Object.keys(values), value: r.value, values };
    }
    if (typeof r.branch === "string") {
      // `Object.hasOwn`, NOT `??`. The two are different questions:
      //   no `value` key at all -> the whole result IS the payload (the case
      //                            this fallback exists for)
      //   `value` present, null -> the payload is null; pass null on
      // `r.value ?? r` cannot tell them apart, so a branch whose payload was
      // null leaked the WRAPPER downstream -- every following node received
      // `{ branch, value }`, two fields no kind declares, while the fields it
      // does declare were absent. The reachable path is an upstream `transform`
      // whose dot-path did not resolve, which is exactly the silent-null case.
      // `Port.only`'s `?? null` never had it. All four runtimes shared this,
      // identically -- so no parity table could catch it; they agreed on being
      // wrong.
      return { ports: [r.branch], value: Object.prototype.hasOwnProperty.call(r, "value") ? r.value : r };
    }
  }
  // Resolve through the shared helper so the ports the runtime activates are
  // the same ones the canvas drew — including config-driven ports, which the
  // node's `data` does not carry. Falls back to a lone `out` when a node
  // declares nothing.
  const kind = getNodeKind((node.data as any)?.kind ?? node.type ?? "") ?? undefined;
  const declared = resolveNodePorts(node, kind).outputs?.map((p) => p.id);

  // THREE states, and the middle one is the point. `undefined` means nothing —
  // neither the node nor its kind — declared any ports, which falls back to a
  // lone `out` so a hand-written document can omit them entirely and still
  // chain. An empty ARRAY means a node (or a terminal kind) declaring that it
  // publishes NOTHING, and it is honoured literally.
  //
  // This line read `declared?.length ? declared : ["out"]` until 0.76.0, and
  // `[]` is falsy, so the two collapsed into one: a node that had explicitly
  // said it publishes nothing published `out` instead. That made this engine
  // disagree with the PHP, Python and Rust twins on the identical document —
  // and this editor WRITES `outputs: []` on export for a terminal node, so the
  // disagreement was reachable by round-tripping a graph rather than by
  // hand-authoring anything unusual.
  //
  // It was a silent truncation the other way round that justified the old
  // behaviour: publishing nothing cuts every chain through such a node. That
  // cut is no longer silent — an edge leaving a node that published nothing
  // raises the undelivered-edge warning, whose port lookup honours the same
  // three states. Strict AND loud; either alone would have been worse than
  // neither.
  return { ports: declared ?? ["out"], value: result };
}

/**
 * What one lit port carries: its own entry when the result named ports
 * individually, otherwise the single payload every lit port shares.
 *
 * `hasOwnProperty`, not `??`: a per-port payload that is present and null is a
 * payload. `values[portId] ?? value` would quietly hand that port the shared
 * value instead — the same confusion `branch` had between "no key" and "null".
 */
function portValueOf(activated: { value: unknown; values?: Record<string, unknown> }, portId: string): unknown {
  return activated.values && Object.prototype.hasOwnProperty.call(activated.values, portId)
    ? activated.values[portId]
    : activated.value;
}

/**
 * Emit a node's own status message for one phase of its execution, if it
 * declared one.
 *
 * Opt-in by absence: a node with no `startingMsg` / `stoppingMsg` says nothing,
 * because most nodes in a real graph are plumbing and narrating all of them
 * buries the two or three steps a person actually wants to follow.
 *
 * A message must be a non-empty string after trimming. An empty string is the
 * shape a cleared editor field takes, and a blank line in a progress feed is
 * indistinguishable from a real message that happens to render as nothing —
 * so it is treated as "not set" rather than as "announce nothing visible".
 */
function announce(
  onEvent: (event: RunEvent) => void,
  node: FlowNode,
  phase: "start" | "end",
): void {
  const data = node.data as { startingMsg?: unknown; stoppingMsg?: unknown } | undefined;
  const raw = phase === "start" ? data?.startingMsg : data?.stoppingMsg;
  if (typeof raw !== "string") return;

  const message = raw.trim();
  if (message === "") return;

  onEvent({ type: "node-message", nodeId: node.id, phase, message });
}

/**
 * Who is running, which step this is, and how many times it has been tried.
 *
 * ## Why an engine needs this at all
 *
 * A node that WRITES to somebody else's system — charge a card, send a message,
 * open a pull request — can only survive a retry if the retry carries the same
 * idempotency key the first attempt did. Otherwise the provider treats the
 * second call as a new request and the customer is charged twice.
 *
 * Until this existed the executor context was `{ node, inputs, emit, abort }`,
 * which is not enough to derive one. Both obvious fallbacks are worse than
 * sending no key at all:
 *
 * - **the node id alone** is stable across retries, and also across RUNS — two
 *   legitimate payments share a key and the provider silently collapses the
 *   second into the first. A payment that never happened, reported as success;
 * - **a fresh random value** is unique per run, and also per ATTEMPT — a retry
 *   creates a second charge, which is the thing being avoided.
 *
 * ## What actually identifies a step
 *
 * Not `(run, node)`. A node legitimately executes more than once inside one
 * run: once per subflow invocation, once per iteration of a loop an executor
 * drives itself. `(run, node)` would give every one of those the same key, and
 * a provider would honour exactly one of them.
 *
 * So a step is identified by the **path of invocations that led to it**, plus
 * an optional **occurrence** for repetition at the same level:
 *
 * ```text
 * runKey ":" segment ("/" segment)*        segment := escape(id) ["#" occurrence]
 * ```
 *
 * And the part that is easy to get backwards: **`attempt` is NOT in the key.**
 * It is carried here for logging and for {@link RunIdentity.isReplaySafe}, and
 * putting it in the key would restore the exact bug the key exists to prevent.
 *
 * Pinned cross-runtime by `shared/flow-run-identity` in
 * `@particle-academy/fancy-conformance`.
 */

/** The wire shape — what a queue job payload carries. */
export type RunIdentityJson = {
  runKey: string;
  path?: string[];
  attempt?: number;
  firstAttemptAt?: string;
};

/**
 * Escape one segment so the composition is injective.
 *
 * `%` FIRST, or the escaping is not reversible: escaping `/` before `%` turns a
 * literal `a%2Fb` into the same text as the escaped form of `a/b`, which is the
 * collision this exists to prevent, reintroduced by its own fix.
 */
export function escapeSegment(value: string): string {
  // Not `replaceAll` — the package targets ES2020, and this must produce the
  // identical string on every runtime that reads the conformance table.
  return value.replace(/%/g, "%25").replace(/\//g, "%2F").replace(/#/g, "%23");
}

function renderSegment(value: string, occurrence?: number | null): string {
  const escaped = escapeSegment(value);
  // `occurrence === 0` is a real occurrence. A truthiness check here silently
  // collapses iteration 0 into the un-iterated key.
  return occurrence === undefined || occurrence === null ? escaped : `${escaped}#${occurrence}`;
}

function instant(value: string): number {
  const ms = Date.parse(value);
  if (Number.isNaN(ms)) {
    throw new Error(
      `RunIdentity: firstAttemptAt is not a parseable timestamp: ${JSON.stringify(value)}`,
    );
  }
  return ms;
}

/**
 * A run, a position inside it, and how many times this position has been tried.
 *
 * Immutable. {@link descend} returns a new identity rather than mutating, so an
 * executor cannot change what its siblings see.
 */
export class RunIdentity {
  /** Stable for the whole run: same across retries, resumes, workers and hosts. */
  readonly runKey: string;

  /**
   * Enclosing invocation segments, outermost first, ALREADY RENDERED.
   *
   * Empty at the top level. A subflow pushes the invoking node's id; an
   * executor that loops pushes `id#i`.
   */
  readonly path: readonly string[];

  /**
   * 1-based attempt of THIS logical step. Never part of the key.
   *
   * The durable driver sets it from the node's claim row, which is exact. A
   * plain in-process `runFlow` gets whatever the host passed, which is
   * run-scoped and therefore conservative — see `isReplaySafe`.
   */
  readonly attempt: number;

  /** ISO-8601 UTC instant of attempt 1 of this step. */
  readonly firstAttemptAt: string;

  constructor(
    runKey: string,
    path: readonly string[] = [],
    attempt = 1,
    firstAttemptAt: string = new Date().toISOString(),
  ) {
    if (!runKey || runKey.trim() === "") {
      throw new Error("RunIdentity: runKey must be a non-empty string.");
    }
    this.runKey = runKey;
    this.path = Object.freeze([...path]);
    this.attempt = Math.max(1, Math.trunc(attempt));
    this.firstAttemptAt = firstAttemptAt;
    Object.freeze(this);
  }

  /**
   * The identity of one execution of one node — stable across retries of that
   * execution, distinct from every other execution of the same node.
   *
   * Pass `occurrence` when an executor runs the same node more than once at the
   * same level (a loop body, one item of a fan-out it drives itself).
   */
  stepKey(nodeId: string, occurrence?: number | null): string {
    return `${this.runKey}:${[...this.path, renderSegment(nodeId, occurrence)].join("/")}`;
  }

  /**
   * A child identity for work nested inside this step.
   *
   * `subflow` pushes the invoking node's id, so a node inside the child graph
   * cannot collide with a same-named node in the parent. Attempt and
   * `firstAttemptAt` are carried down unchanged: the nested work happens inside
   * this step's attempt, and shares its clock.
   */
  descend(segment: string, occurrence?: number | null): RunIdentity {
    return new RunIdentity(
      this.runKey,
      [...this.path, renderSegment(segment, occurrence)],
      this.attempt,
      this.firstAttemptAt,
    );
  }

  /** A copy on a different attempt, first-attempt clock preserved. */
  withAttempt(attempt: number, firstAttemptAt?: string): RunIdentity {
    return new RunIdentity(
      this.runKey,
      this.path,
      attempt,
      firstAttemptAt ?? this.firstAttemptAt,
    );
  }

  /**
   * May this attempt reuse the step key and still be deduplicated?
   *
   * Providers forget idempotency keys — Stripe after 24 hours. Past that
   * window, resending the key creates a second charge and sending a fresh one
   * creates a second charge, so **the caller must refuse rather than pick
   * between them**: a loud stuck run beats a silent double write.
   *
   * `true` on attempt 1 whatever the elapsed time — nothing was sent on an
   * earlier attempt, so there is nothing for the provider to have forgotten.
   * That is what lets a run park on a human gate for a week and then write.
   *
   * `windowSeconds: null` means the provider does not expire keys. `0` means
   * it does not dedupe at all, so no retry may reuse a key — it is a real
   * window, not an absent one, and the two must not be conflated: reading `0`
   * as `null` turns "this provider does not dedupe" into "this provider
   * dedupes forever", which is the more dangerous of the two by a distance.
   */
  isReplaySafe(windowSeconds: number | null | undefined, now: Date | string = new Date()): boolean {
    if (this.attempt <= 1) return true;
    if (windowSeconds === null || windowSeconds === undefined) return true;
    if (windowSeconds <= 0) return false;

    const nowMs = typeof now === "string" ? instant(now) : now.getTime();
    // Clock skew between two workers must not turn a legitimate retry into a
    // refusal, so a negative elapsed clamps to zero.
    const elapsedSeconds = Math.max(0, (nowMs - instant(this.firstAttemptAt)) / 1000);

    // Inclusive: a key written at T is remembered THROUGH T + window.
    return elapsedSeconds <= windowSeconds;
  }

  toJSON(): Required<RunIdentityJson> {
    return {
      runKey: this.runKey,
      path: [...this.path],
      attempt: this.attempt,
      firstAttemptAt: this.firstAttemptAt,
    };
  }

  /** Rebuild from a queue payload. */
  static from(value: RunIdentity | RunIdentityJson | string): RunIdentity {
    if (value instanceof RunIdentity) return value;
    if (typeof value === "string") return new RunIdentity(value);
    return new RunIdentity(
      value.runKey,
      value.path ?? [],
      value.attempt ?? 1,
      value.firstAttemptAt ?? new Date().toISOString(),
    );
  }
}

import { getTerminalHost, type TerminalSession, type TerminalSessionSpec } from "../lib/registry/capabilities";
import { TerminalTranscript } from "./terminal-transcript";
import type { FlowGraph, FlowNode } from "../lib/types";

/**
 * One terminal per terminal lane, for the length of a run.
 *
 * ## The lifetime, and why it is not per-node
 *
 * A terminal node is only useful if the process it talks to is the SAME one the
 * last node talked to. `cd` has to persist; an agent TUI has to still be
 * running with its conversation intact. A session opened per node would give
 * every node a fresh shell and quietly turn a sequence of steps into a series
 * of unrelated ones — each individually correct, the whole thing meaningless.
 *
 * So the session is keyed on the LANE, opened lazily by the first node inside
 * it, and closed once when the run ends. A graph that never reaches a terminal
 * node spawns no process at all, which is what makes it safe for the lane to
 * exist on a canvas that mostly does other things.
 *
 * ## Why membership is `parentId`
 *
 * It is what the canvas already means by "inside", and it already persists into
 * the WorkflowSchema — so a headless runtime resolves exactly the grouping a
 * person drew, with no second association to keep in step. The alternative, a
 * lane id typed into each node's config, is the same fact in two places and
 * would drift the first time somebody dragged a node out of a lane.
 *
 * Nesting is followed to the nearest terminal lane, so an ordinary lane inside
 * a terminal lane still resolves — grouping for looks should not change which
 * terminal a node talks to.
 */
export class TerminalSessions {
  private readonly open = new Map<string, Promise<TerminalSession>>();

  private readonly laneOf = new Map<string, string | null>();

  private readonly transcripts = new Map<string, TerminalTranscript>();

  private readonly listening = new Map<string, () => void>();

  constructor(private readonly graph: FlowGraph) {}

  /**
   * The terminal lane a node belongs to, or null.
   *
   * Walks up `parentId` rather than checking only the immediate parent, and
   * caches per node id — a graph is walked once per run, and the answer cannot
   * change while it runs.
   */
  laneFor(nodeId: string, isTerminalLane: (node: FlowNode) => boolean): string | null {
    const cached = this.laneOf.get(nodeId);
    if (cached !== undefined) return cached;

    const byId = new Map(this.graph.nodes.map((n) => [n.id, n]));
    const seen = new Set<string>();

    let current = byId.get(nodeId);
    let answer: string | null = null;

    while (current) {
      // A cycle in `parentId` is malformed rather than impossible — a dragged
      // node with a stale parent can produce one — and walking it forever would
      // hang the run rather than fail it.
      if (seen.has(current.id)) break;
      seen.add(current.id);

      if (current.id !== nodeId && isTerminalLane(current)) {
        answer = current.id;
        break;
      }

      const parentId = (current as unknown as { parentId?: string }).parentId;
      current = parentId ? byId.get(parentId) : undefined;
    }

    this.laneOf.set(nodeId, answer);
    return answer;
  }

  /**
   * The session for a lane, opening it on first use.
   *
   * The PROMISE is cached, not the resolved session. Two nodes cannot run
   * concurrently in the current engine, but a caller that awaits a
   * half-finished open would otherwise start a second process — and two shells
   * where a graph says one is the failure this class exists to prevent, arriving
   * only under concurrency and therefore only sometimes.
   */
  session(laneId: string, spec: TerminalSessionSpec): Promise<TerminalSession> {
    const existing = this.open.get(laneId);
    if (existing) return existing;

    const host = getTerminalHost();

    if (!host) {
      // Named as a MISSING HOST rather than a failed open. A node in a terminal
      // lane with no host registered is a configuration problem — the desktop
      // app did not install one — and reporting it as "the terminal failed"
      // sends someone to debug a process that was never started.
      const failed = Promise.reject(
        new Error(
          "No terminal host is registered. A terminal lane needs one — call registerTerminalHost() "
            + "from the desktop app, or install @particle-academy/fancy-flow/terminal/fancy-term-host.",
        ),
      );
      // Cached so every node in the lane fails the same way rather than the
      // first one failing and the rest re-asking a question already answered.
      this.open.set(laneId, failed);
      // Nothing awaits this until a node does; keep node from warning meanwhile.
      failed.catch(() => {});
      return failed;
    }

    // Subscribed the moment the session resolves, not when a node first waits.
    //
    // A process answers on its own schedule, and the node that types at it and
    // the node that reads the reply are two separate steps. Anything printed in
    // between is unrecoverable if the buffer starts when the WAIT does — so a
    // fast process would be missed and a slow one caught, which is the same bug
    // presenting as flakiness rather than as a bug.
    const opening = Promise.resolve(host.open(spec)).then((session) => {
      const transcript = this.transcriptFor(laneId);
      this.listening.set(laneId, session.onData((chunk) => transcript.append(chunk)));
      return session;
    });

    this.open.set(laneId, opening);
    opening.catch(() => {});
    return opening;
  }

  /**
   * The accumulated output for a lane.
   *
   * Created on demand and kept for the run, so it exists before the session
   * resolves and survives every node that reads it. Consuming is the reader's
   * job — see `TerminalTranscript.waitFor`.
   */
  transcriptFor(laneId: string): TerminalTranscript {
    const existing = this.transcripts.get(laneId);
    if (existing) return existing;

    const created = new TerminalTranscript();
    this.transcripts.set(laneId, created);
    return created;
  }

  /** True once a lane has a session — used to avoid opening one during teardown. */
  isOpen(laneId: string): boolean {
    return this.open.has(laneId);
  }

  /**
   * Close every session this run opened.
   *
   * Every close is attempted even if one throws: a host that fails to close one
   * PTY must not strand the others, which would leave processes alive after the
   * run reported that it had finished. Errors are returned rather than thrown,
   * because teardown runs in a `finally` and throwing there would replace the
   * run's real error with a cleanup error.
   */
  async closeAll(): Promise<Error[]> {
    const errors: Error[] = [];

    for (const [laneId, pending] of this.open) {
      try {
        // Unsubscribe BEFORE closing. A host that emits a final chunk while
        // shutting down would otherwise append to a transcript nobody will read
        // again, and a listener outliving its session is how a closed terminal
        // keeps a run's objects alive.
        this.listening.get(laneId)?.();
        this.listening.delete(laneId);

        const session = await pending;
        await session.close();
      } catch (e) {
        errors.push(e instanceof Error ? e : new Error(`${laneId}: ${String(e)}`));
      }
    }

    this.open.clear();
    this.listening.clear();
    this.transcripts.clear();
    return errors;
  }
}

/** The spec a terminal lane node declares. */
export function specForLane(lane: FlowNode): TerminalSessionSpec {
  const config = ((lane.data as { config?: Record<string, unknown> } | undefined)?.config ?? {}) as Record<
    string,
    unknown
  >;

  const text = (key: string): string | undefined => {
    const value = config[key];
    return typeof value === "string" && value !== "" ? value : undefined;
  };

  const env = config.env;

  return {
    command: text("command"),
    cwd: text("cwd"),
    env:
      env && typeof env === "object" && !Array.isArray(env)
        ? Object.fromEntries(
            Object.entries(env as Record<string, unknown>).map(([k, v]) => [k, String(v)]),
          )
        : undefined,
  };
}

/**
 * AN EDGE THAT DELIVERS NOTHING MUST SAY SO — the one implementation of that
 * check, shared by every path that can reach it.
 *
 * `runFlow` asks it of each node it reaches. The durable `Coordinator` asks it
 * of each node its frontier SKIPS, because a skipped node never gets a job and
 * so never replays to ask it for itself. Two copies of this check would agree
 * for a while and then disagree on one handle — which is exactly the kind of
 * divergence the warning exists to report — so there is one, and it EMITS
 * nothing. It returns the events and each caller decides where they go.
 *
 * Kept React-free on purpose: `run-flow.ts` imports it, and the `/engine` entry
 * must not reach React.
 */
import type { FlowEdge, FlowNode, RunEvent } from "../lib/types";
// React-free modules, imported directly rather than via the `registry` barrel,
// which re-exports the RegistryNode component.
import { defaultConfigFor, getNodeKind } from "../lib/registry/registry";
import { nodeConfig, resolvePortSpec } from "../lib/registry/ports";
import { outputFieldsFor } from "../lib/expressions/variables";

/**
 * The `log` / `warn` events for every inbound edge of `target` that delivers
 * nothing and never could.
 *
 * Asked BEFORE the activity gate, because the two outcomes are both silent and
 * only one reaches `collectInputs`. If the bad edge is the node's only inbound
 * one the node is SKIPPED; if it has another live edge it RUNS with that port
 * simply missing -- and then a downstream template that is entirely correct
 * renders empty, because the payload never arrived to have a field in it.
 *
 * Keyed on the source having COMPLETED and on the handle being a port the source
 * could NEVER publish. A branch that was not taken is ordinary and must never
 * warn; a source that finished and cannot publish this port is a
 * misconfiguration that delivers nothing on any run. A warning that fires on
 * ordinary branching is noise, and noise is how a real warning stops being read.
 * PHP has always said this; this runtime ran the same graph and said nothing
 * (fancy-flow#17). Pinned by `flow/run-diagnostics`.
 *
 * - `incoming` — the target's inbound edges, in graph order.
 * - `portValues` — keyed `"<nodeId>:<portId>"`, one key per port a node
 *   published, in publication order. Only the KEYS are read: which ports
 *   published, never what they carried.
 * - `completed` — the ids of nodes that ran to an output. A source that did not
 *   complete is never judged (row 0014).
 * - `nodesById` — every node of the graph, to resolve a source's ports and
 *   output fields.
 */
export function undeliveredEdgeWarnings(
  target: FlowNode,
  incoming: readonly FlowEdge[],
  portValues: ReadonlyMap<string, unknown>,
  completed: ReadonlySet<string>,
  nodesById: ReadonlyMap<string, FlowNode>,
): RunEvent[] {
  const events: RunEvent[] = [];

  for (const e of incoming) {
    const handle = e.sourceHandle ?? "out";
    if (portValues.has(`${e.source}:${handle}`) || !completed.has(e.source)) continue;
    if (possiblePortIds(nodesById.get(e.source)).includes(handle)) continue;

    events.push({
      type: "log",
      nodeId: target.id,
      level: "warn",
      message: undeliveredEdgeMessage(e, target, portValues, nodesById),
      detail: { edge: e.id, source: e.source, sourceHandle: handle },
    });
  }

  return events;
}

/**
 * Every port this node COULD publish — not the ones it did.
 *
 * The distinction that keeps the undelivered-edge warning honest. A `branch`
 * that took `true` publishes no `false`, and the edge leaving `false` binds
 * nothing: that is ORDINARY BRANCHING. A handle that is not a port of the node
 * at all can never bind on any run. "Did it publish?" cannot tell those apart —
 * both are absent — so this asks what is POSSIBLE.
 *
 * The rule is the PHP twin's `PortResolution::possible`, precedence and all,
 * because a warning one runtime raises and another does not is a parity failure:
 *
 *   1. the node's own declared `outputs`;
 *   2. the kind's CONFIG-DERIVED ports, when the config declares any;
 *   3. the kind's declared ports;
 *   4. `out`.
 *
 * It differs from `resolveNodePorts` in exactly one place, on purpose. A kind
 * whose ports come from config — `switch_case`, `llm_router` — and whose config
 * declares none yet answers with its DEFAULT-config shape (`case_a`, `case_b`,
 * `default`), which is what PHP's static declaration for that kind is.
 * `resolveNodePorts` answers with what that empty config yields (`default`
 * alone), which is right for the canvas and for `activatedPorts`, so it is left
 * alone: this only decides whether to warn, never what routes.
 */
function possiblePortIds(node: FlowNode | undefined): string[] {
  if (!node) return ["out"];

  const own = (node.data as { outputs?: unknown } | undefined)?.outputs;
  if (Array.isArray(own)) return own.map((p: { id: string }) => p.id);

  // An unregistered kind is not ambiguous: `activatedPorts` falls back to
  // exactly `out` for a kind it cannot resolve, so that is all it publishes.
  const kind = getNodeKind((node.data as any)?.kind ?? node.type ?? "");
  if (!kind) return ["out"];

  const config = nodeConfig(node);
  const representative = typeof kind.outputs === "function" && !configDeclaresPorts(kind.name, config);
  const resolved = resolvePortSpec(kind.outputs, representative ? defaultConfigFor(kind) : config);

  // THREE states, not two. `undefined` is "this kind declares nothing", which
  // falls back to `out` exactly as `activatedPorts` does. An empty ARRAY is a
  // kind declaring it has no output ports, and it is returned as such.
  //
  // This line read `ids.length > 0 ? ids : ["out"]` until 0.76.0, collapsing
  // both into `out` — the same empty-to-`out` collapse `activatedPorts` made,
  // in the other of the two gates that shape a port set. Fixing only the
  // activation side would have been half a fix, and the dangerous half: the
  // node would publish nothing while this lookup still reported `out` as
  // deliverable, so the undelivered-edge warning would stay SILENT for exactly
  // the edge that had just stopped delivering.
  if (resolved === undefined) return ["out"];

  return resolved.map((p) => p.id);
}

/**
 * Whether a config-driven kind's config declares any ports of its own — PHP's
 * `configDerived` returning non-empty. Matched on the BARE kind name, as there:
 * graphs carry both `switch_case` and `@particle-academy/switch_case`.
 */
function configDeclaresPorts(kindName: string, config: Record<string, unknown>): boolean {
  const bare = kindName.startsWith("@") ? kindName.slice(kindName.lastIndexOf("/") + 1) : kindName;

  if (bare === "switch_case") {
    // `cases` maps VALUE => PORT, so the ports are its values.
    const cases = config.cases;
    return !!cases && typeof cases === "object"
      && Object.values(cases).some((port) => typeof port === "string" && port !== "");
  }

  if (bare === "llm_router") {
    const routes = config.routes;
    return Array.isArray(routes)
      && routes.some((route) => (route as { port?: unknown } | null)?.port != null && (route as { port: unknown }).port !== "");
  }

  return true;
}

/**
 * The message for an edge whose source port publishes nothing.
 *
 * The PHP twin's wording, byte for byte, and each part earns its place:
 *
 *   1. THE EDGE ID FIRST — the thing the author, looking at a graph, can act on.
 *   2. THE CONSEQUENCE, IN RUNTIME TERMS. Without "nothing would reach X" this
 *      reads as a schema nit, and a handle string feels cosmetic.
 *   3. THE AVAILABLE PORTS — what the source ACTUALLY published on this run, in
 *      publication order, so a config-driven kind reports its real ports.
 *   4. THE REMEDY FOR THE COMMON CASE. Nearly every occurrence is an agent
 *      ADDING a handle that should not be there, so "leave sourceHandle off" —
 *      offered only when there is a handle to leave off.
 *
 * Plus the part only the engine can supply: when the handle names a FIELD of
 * the source kind's output shape, say so. That is the actual confusion — a field
 * name where a port belongs — and naming it turns a correction into an
 * explanation.
 */
function undeliveredEdgeMessage(
  edge: FlowEdge,
  target: FlowNode,
  portValues: ReadonlyMap<string, unknown>,
  nodesById: ReadonlyMap<string, FlowNode>,
): string {
  const handle = edge.sourceHandle ?? "out";

  const prefix = `${edge.source}:`;
  const available: string[] = [];
  for (const key of portValues.keys()) {
    if (key.startsWith(prefix)) available.push(key.slice(prefix.length));
  }

  let message =
    `Edge ${edge.id} reads port "${handle}" from node ${edge.source}, which never publishes it — ` +
    `nothing would reach ${target.id} at run time.`;

  if (available.length > 0) message += ` Available: ${available.join(", ")}.`;

  // The near-miss: a FIELD of that name, where a PORT was expected.
  const source = nodesById.get(edge.source);
  if (source && outputFieldsFor(source).some((field) => field?.path === handle)) {
    message +=
      ` Note: "${handle}" is a FIELD this node emits, not a port — read it downstream as ` +
      `{{ in.${handle} }} rather than naming it as a source handle.`;
  }

  if (edge.sourceHandle != null) message += " Leave sourceHandle off to read the node's output.";

  return message;
}

import type { WorkflowInput } from "../lib/types";

/**
 * Resolving what a caller passed against what a workflow declared.
 *
 * Kept in its own module, and deliberately a pure function over two plain
 * objects, because the PHP and Python runtimes implement the same rules and
 * `suites/flow/workflow-props` in `@particle-academy/fancy-conformance` is the
 * table all three run. A rule that lives inside a runner is a rule each runtime
 * re-derives; a rule that is a function over maps is one they can share a
 * fixture for.
 *
 * ## Every branch here exists to make a mistake LOUD
 *
 * The failure this replaces was silence. `initialInputs` was keyed by node id,
 * so a caller passed `{ t: { topic: "otters" } }` and had to know the trigger
 * was named `t`; and nothing declared what a workflow accepted, so a
 * misspelled key was not an error — the value sat unread, the node saw
 * nothing, and the run reported success with output that was quietly wrong.
 *
 * So: an unknown key fails, a missing required value fails, and a wrong type
 * fails. None of those is a warning. A warning on a queue worker is a line in a
 * log nobody opens.
 */

/**
 * Why a resolution failed, in a vocabulary that is the same in every runtime.
 *
 * The MESSAGE is English prose and each runtime words it slightly differently,
 * which is fine for a human and useless for a shared fixture table. The CODE is
 * what `suites/flow/workflow-props` asserts, so parity is pinned on the
 * decision rather than on the phrasing — otherwise the three implementations
 * would be held to a translation instead of a behaviour.
 */
export type PropsErrorCode = "unknown_input" | "missing_required" | "type_mismatch";

/** The outcome of checking a caller's props against a declaration. */
export type PropsResolution =
  | { ok: true; props: Record<string, unknown> }
  | { ok: false; code: PropsErrorCode; error: string };

/**
 * The runtime type of a value, in the vocabulary a declaration uses.
 *
 * Arrays are checked before objects because `typeof []` is `"object"` and a
 * declaration that says `array` means a list — accepting `{}` there would be
 * the check passing while meaning nothing.
 */
function typeOf(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

/**
 * Check and fill a caller's props.
 *
 * Returns the resolved map — declared defaults filled in, nothing else added —
 * or the first error. One error rather than a list, because a run stops at the
 * first one anyway and a caller fixing a call wants the thing to fix, not a
 * report.
 */
export function resolveWorkflowProps(
  declared: WorkflowInput[] | undefined,
  passed: Record<string, unknown> | undefined,
): PropsResolution {
  const inputs = declared ?? [];
  const given = passed ?? {};
  const byName = new Map(inputs.map((input) => [input.name, input]));

  // UNKNOWN KEYS FIRST, and this is the check the whole feature is for.
  //
  // A caller who misspells `topic` as `topik` has configured nothing, and
  // before this the run went ahead and looked fine. Checking it before
  // anything else means the error names what they typed rather than
  // complaining that the thing they thought they passed is missing.
  for (const name of Object.keys(given)) {
    if (!byName.has(name)) {
      const known = inputs.map((input) => input.name);
      const suffix = known.length === 0
        ? "this workflow declares no inputs"
        : `known inputs: ${known.join(", ")}`;

      return {
        ok: false,
        code: "unknown_input",
        error: `Unknown workflow input "${name}" — ${suffix}.`,
      };
    }
  }

  const resolved: Record<string, unknown> = {};

  for (const input of inputs) {
    // `hasOwnProperty`, not a truthiness or `??` check. `0`, `false` and `""`
    // are real values a caller meant to pass, and a default applied over them
    // is a silent override — a limit of 0 quietly becoming 10 is not an error
    // anybody sees.
    const supplied = Object.prototype.hasOwnProperty.call(given, input.name);
    const hasDefault = Object.prototype.hasOwnProperty.call(input, "default");

    if (!supplied) {
      if (hasDefault) {
        resolved[input.name] = input.default;
        continue;
      }

      if (input.required) {
        return {
          ok: false,
          code: "missing_required",
          error: `Missing required workflow input "${input.name}"${
            input.type ? ` (${input.type})` : ""
          }.`,
        };
      }

      // Not supplied, no default, not required — absent rather than
      // `undefined`, so `{{ $props.x }}` resolves to null on both runtimes
      // instead of one of them inventing a key.
      continue;
    }

    const value = given[input.name];

    // An undeclared type accepts anything. "I am not asserting a shape" must
    // not degrade into "nothing is allowed".
    if (input.type !== undefined) {
      const actual = typeOf(value);
      if (actual !== input.type) {
        return {
          ok: false,
          code: "type_mismatch",
          error: `Workflow input "${input.name}" expects ${input.type}, got ${actual}.`,
        };
      }
    }

    resolved[input.name] = value;
  }

  return { ok: true, props: resolved };
}

/**
 * What a terminal has said, in a form a node can wait on.
 *
 * A raw `onData` stream is not something a workflow can match against, for
 * three reasons that all fail the same way — intermittently, and usually only
 * once there is real output moving:
 *
 *  1. **Chunks are arbitrary.** A PTY splits wherever it splits, so `Ready >`
 *     can arrive as `Rea` + `dy >`. Testing each chunk on its own finds the
 *     pattern when output is small enough to land in one write and misses it
 *     when it is not. So matching runs against an ACCUMULATED buffer, never a
 *     chunk.
 *
 *  2. **Output arrives before anyone is listening.** A node that types at a
 *     process and a node that waits for its reply are two steps, and anything
 *     printed between them is gone if the buffer starts when the wait does.
 *     So the transcript is attached when the SESSION opens, and a wait reads
 *     what has already accumulated before it subscribes to anything new.
 *
 *  3. **Escape sequences are everywhere and they also straddle.** An agent TUI
 *     writes `Ready` as `ESC[32m Ready ESC[0m`, so matching raw bytes fails on
 *     text a person can plainly read. Stripping per chunk reintroduces problem
 *     1 in a second guise — `ESC[3` + `2mReady` strips to `ESC[32mReady` with
 *     the escape now INSIDE the text. So an incomplete trailing sequence is
 *     held back until the rest of it arrives.
 *
 * Text is consumed through a match, so two waits for the same pattern do not
 * both resolve on the first occurrence — which would let a loop appear to make
 * progress while reading one old line forever.
 */

/**
 * The control characters, by code point rather than as literals.
 *
 * A raw ESC byte sitting in a `.ts` file survives most tools and not all of
 * them, and the failure is the quiet kind: strip one out and the pattern below
 * still parses, still looks right in review, and matches nothing — so every
 * wait fails on coloured output while the code reads as correct. It happened
 * twice while this file was being written, which is the argument.
 */
const ESC = String.fromCharCode(0x1b);
const CSI = String.fromCharCode(0x9b);
const BEL = String.fromCharCode(0x07);

/**
 * CSI (`ESC [ ... final`), OSC (`ESC ] ... BEL|ST`), and the two-character
 * escapes. Written out rather than taken from a dependency: it is a regex, and
 * the suite's rule is that third-party code is a liability carried for years.
 */
const ANSI = new RegExp(
  `[${ESC}${CSI}](?:\\[[0-?]*[ -/]*[@-~]|\\][^${BEL}${ESC}]*(?:${BEL}|${ESC}\\\\)|[@-Z\\\\-_])`,
  "g",
);

/**
 * How much unterminated escape to hold back before giving up on it.
 *
 * An OSC sequence carrying a window title is legitimately long, but a lone
 * `ESC` that never terminates is just a byte — holding the rest of the stream
 * hostage behind it would stall a wait forever, which is a worse failure than
 * one stray character in the output.
 */
const MAX_PENDING_ESCAPE = 1024;

/**
 * Cap on retained text. A chatty process across a long run would otherwise grow
 * this without limit. Dropping from the FRONT keeps the recent output — which
 * is what a wait is about to match — and a pattern spanning a megabyte of
 * output is not a pattern anybody wrote.
 */
const MAX_BUFFER = 1_000_000;

export type TranscriptWaitResult =
  | { status: "matched"; text: string; match: RegExpMatchArray }
  | { status: "timeout"; text: string }
  | { status: "exited"; text: string; exitCode: number; signal?: string };

export class TerminalTranscript {
  /** Stripped, complete text not yet consumed by a wait. */
  private text = "";

  /** Raw bytes held back because they may be the start of an escape sequence. */
  private tail = "";

  private readonly waiters = new Set<() => void>();

  /** Feed raw terminal output in. Safe to call with any chunking. */
  append(chunk: string): void {
    this.tail += chunk;

    const safe = this.safeLength();
    if (safe > 0) {
      this.text += this.tail.slice(0, safe).replace(ANSI, "");
      this.tail = this.tail.slice(safe);
    }

    if (this.text.length > MAX_BUFFER) {
      this.text = this.text.slice(this.text.length - MAX_BUFFER);
    }

    for (const wake of [...this.waiters]) wake();
  }

  /**
   * How much of `tail` can be stripped now.
   *
   * Everything, unless the final `ESC` has not yet been terminated — in which
   * case processing stops there and resumes when the rest arrives.
   */
  private safeLength(): number {
    const lastEsc = Math.max(this.tail.lastIndexOf(ESC), this.tail.lastIndexOf(CSI));
    if (lastEsc === -1) return this.tail.length;

    // A complete sequence starting there means nothing is pending.
    ANSI.lastIndex = lastEsc;
    const match = ANSI.exec(this.tail);
    ANSI.lastIndex = 0;
    if (match && match.index === lastEsc) return this.tail.length;

    // Unterminated, but long enough that it is not really an escape.
    if (this.tail.length - lastEsc > MAX_PENDING_ESCAPE) return this.tail.length;

    return lastEsc;
  }

  /** Unconsumed output, escape sequences removed. */
  peek(): string {
    return this.text;
  }

  /** Drop everything currently buffered — used before typing a new command. */
  clear(): void {
    this.text = "";
    this.tail = "";
  }

  /**
   * Wait until `pattern` matches the unconsumed text.
   *
   * Checks what has ALREADY arrived before subscribing, because the common case
   * is that the process answered while the previous node was still finishing.
   *
   * `exited` is raced deliberately. Without it, a shell that dies reports as
   * "timed out waiting for X" — sending whoever reads it to lengthen a timeout
   * for a process that is not running. Naming the exit is the difference
   * between a diagnosis and a wrong lead.
   */
  waitFor(
    pattern: RegExp,
    options: { timeoutMs: number; exited?: Promise<{ exitCode: number; signal?: string }> },
  ): Promise<TranscriptWaitResult> {
    return new Promise<TranscriptWaitResult>((resolve) => {
      let settled = false;
      let timer: ReturnType<typeof setTimeout> | undefined;

      const finish = (result: TranscriptWaitResult) => {
        if (settled) return;
        settled = true;
        this.waiters.delete(check);
        if (timer) clearTimeout(timer);
        resolve(result);
      };

      const check = () => {
        // A global or sticky pattern carries `lastIndex` between calls, so it
        // would start each attempt part-way through a buffer it has not read.
        pattern.lastIndex = 0;
        const match = pattern.exec(this.text);
        if (!match) return;

        // `|| 1` so a pattern that can match empty still makes progress rather
        // than consuming nothing and matching the same position forever.
        const through = match.index + (match[0].length || 1);
        const text = this.text.slice(0, through);
        this.text = this.text.slice(through);
        finish({ status: "matched", text, match });
      };

      this.waiters.add(check);
      check();
      if (settled) return;

      if (options.timeoutMs > 0) {
        timer = setTimeout(() => {
          const text = this.text;
          this.text = "";
          finish({ status: "timeout", text });
        }, options.timeoutMs);
        // Never hold a Node process open just to time out a wait nobody wants.
        (timer as unknown as { unref?: () => void }).unref?.();
      }

      options.exited?.then(
        (exit) => {
          // No re-check here, deliberately. `append` wakes every waiter the
          // instant data lands, so a process that prints its answer and then
          // exits has already matched by the time this runs — `settled` is
          // true and this returns. A re-check looked like it was guarding that
          // race and was in fact unreachable, which is worse than absent: it
          // read as a guarantee while the actual guarantee lived elsewhere.
          if (settled) return;
          const text = this.text;
          this.text = "";
          finish({ status: "exited", text, exitCode: exit.exitCode, signal: exit.signal });
        },
        () => {},
      );
    });
  }
}

import type { ConfigField, NodeCategory, NodeKindDefinition } from "./types";
// The DATA module, deliberately -- importing `./builtin` here is what put
// React into `/engine` (#11). See that file for the whole story.
import { registerBuiltinKindData } from "./builtin-kinds";

const kinds = new Map<string, NodeKindDefinition<any, any, any>>();
/** alias → canonical name. See `resolveKindId`. */
const aliases = new Map<string, string>();
const listeners = new Set<() => void>();
/**
 * canonical name → presentation patch. See `overrideNodeKind`.
 *
 * Kept SEPARATE from `kinds` on purpose: an override has to survive its base
 * kind being re-registered (HMR, a later `registerBuiltinKinds()`, a package
 * upgrade). Merging into the definition would mean the next registration
 * silently reverts the consumer's naming.
 */
const overrides = new Map<string, NodeKindPresentation>();

/**
 * Names a HOST registered, as opposed to names the builtin kit registered.
 *
 * Builtin registration is not a one-shot event: `registerBuiltinKinds()` is
 * exported, the four kinds with renderers are deliberately registered twice
 * (React-free table, then decorated), and since 0.66.1 the root barrel calls it
 * as an import side effect. So "the builtins register again" happens routinely
 * and at times no consumer can predict.
 *
 * Without this set, every one of those occasions silently reverted a host's
 * replacement of a builtin — the only mechanism we offer for extending one.
 * A consumer's field would vanish from the editor while their server kept
 * validating it, and whether it happened at all depended on which module their
 * bundler evaluated second.
 *
 * This is the same protection `overrides` already had, and for the same stated
 * reason. Presentation patches were kept safe from re-registration; behavioural
 * replacement was not, and nothing marked the asymmetry.
 */
const hostOwned = new Set<string>();

/**
 * canonical name -> schema patch from a SERVER. See `applyKindSchemaOverlay`.
 *
 * Kept in its own map for the reason `overrides` is: a patch stored ON the kind
 * is reverted the next time that kind is registered, and builtin registration
 * is not a one-shot event. 0.66.2 was exactly that bug for behavioural
 * replacement; this is the same shape and gets the same protection rather than
 * waiting to learn it twice.
 */
const schemaOverlays = new Map<string, KindSchemaOverlay>();

/**
 * The builtin definition for a name, kept even while a host owns the name.
 *
 * Without it, releasing a claim could only DELETE the entry — which is a worse
 * state than before the override, not a return to it: the palette loses the
 * node and the canvas renders raw kind ids where a label belongs.
 */
const builtinDefs = new Map<string, NodeKindDefinition<any, any, any>>();

let builtinsEnsured = false;

/**
 * Put the builtin kit in the registry before anyone reads or writes it.
 *
 * Registration used to be a bare `registerBuiltinKinds()` in `src/index.ts`, so
 * it fired ONLY as an import side effect of that one entry. Every other route in
 * — the `/engine` and `/registry` subpaths, or a root import that TypeScript
 * erases because it only took types — got an empty registry, and an empty
 * registry is silent: `getNodeKind()` returns null, `FlowViewer` falls through
 * its title chain, and the canvas shows `@particle-academy/llm_call` where a
 * name belongs.
 *
 * Doing it here instead means correctness no longer depends on which entry a
 * consumer imported, or on a bundler agreeing to keep a top-level statement.
 *
 * The flag is set BEFORE the call so a listener that reads the registry from
 * inside `notify()` cannot recurse. `registerNodeKind` ensures too, so builtins
 * are always in place before a host registers over one of them.
 */
export function ensureBuiltinKinds(): void {
  if (builtinsEnsured) return;
  builtinsEnsured = true;
  registerBuiltinKindData();
}

/**
 * The presentation fields a consumer may override on someone else's node kind.
 *
 * Deliberately excludes everything behavioural — `executor`, `inputs`,
 * `outputs`, `configSchema`, `sideEffects`. An "override" that could change
 * those is not an override, it is a fork wearing a friendly name, and it would
 * desync the graph from the runtime that executes it.
 *
 * `category` IS included: which drawer a node appears in is presentation, and a
 * consumer regrouping their palette is the same kind of act as renaming.
 */
export type NodeKindPresentation = Partial<
  Pick<NodeKindDefinition, "label" | "description" | "icon" | "accent" | "category">
>;

/**
 * registerNodeKind — install a node kind in the global registry. Returns
 * an `unregister` function. Calling with the same name replaces the prior
 * registration (handy for HMR).
 *
 * A kind's `name` is its CANONICAL id and is what gets written into saved
 * documents. Publish namespaced (`@fancy/llm_branch`, `@acme/salesforce_upsert`)
 * and list any previous bare names in `aliases`, so graphs saved before the
 * rename keep resolving.
 */
export function registerNodeKind<TC = any, TI = any, TO = any>(
  definition: NodeKindDefinition<TC, TI, TO>,
): () => void {
  ensureBuiltinKinds();
  // Claiming the name is what protects it: from here on the builtin kit will
  // not overwrite this entry, however many times it re-registers.
  hostOwned.add(definition.name);
  kinds.set(definition.name, definition as NodeKindDefinition<any, any, any>);
  for (const alias of definition.aliases ?? []) aliases.set(alias, definition.name);
  notify();
  return () => {
    if (kinds.get(definition.name) === (definition as any)) {
      kinds.delete(definition.name);
      hostOwned.delete(definition.name);
      for (const alias of definition.aliases ?? []) {
        if (aliases.get(alias) === definition.name) aliases.delete(alias);
      }
      notify();
    }
  };
}

/**
 * Register a kind AS PART OF THE BUILTIN KIT — never overwriting a host.
 *
 * The builtin modules use this instead of `registerNodeKind` so that repeated
 * builtin registration is safe. It still replaces builtins (the four kinds with
 * renderers are registered twice on purpose, plain table then decorated), but
 * it steps aside for any name a host has claimed.
 *
 * Internal: not re-exported from the package. A consumer wanting to install a
 * kind uses `registerNodeKind`, and gets ownership of the name by doing so.
 */
export function registerBuiltinKindInternal(
  definition: NodeKindDefinition<any, any, any>,
): void {
  // Recorded BEFORE the ownership check: a host owning the name now is exactly
  // when we will later need the builtin to hand back.
  builtinDefs.set(definition.name, definition);

  if (hostOwned.has(definition.name)) return;

  kinds.set(definition.name, definition);
  for (const alias of definition.aliases ?? []) {
    if (!hostOwned.has(aliases.get(alias) ?? "")) aliases.set(alias, definition.name);
  }
}

/**
 * Release a host's claim on a name and restore the builtin behind it.
 *
 * The counterpart to `registerNodeKind` replacing a builtin. `registerNodeKind`
 * does return an unregister closure, but a consumer reading the export list
 * cannot find it, and one correctly concluded no such operation existed — so
 * this is the named form.
 *
 * **Test isolation is the reason it matters.** Before 0.66.2, calling
 * `registerBuiltinKinds()` restored the builtins over any override, and people
 * reasonably used that to reset between tests. Since 0.66.2 it correctly
 * refuses to overwrite a host's registration, so that reset silently stopped
 * resetting — and it does not fail where it broke, it fails as a wrong
 * assertion in a later, unrelated test. Use this instead.
 *
 * Returns whether anything was actually released, so a typo'd name is visible
 * rather than a silent no-op — a reset helper that quietly stops resetting is
 * the failure this exists to prevent.
 */
export function unregisterNodeKind(name: string): boolean {
  const canonical = resolveKindId(name) ?? name;

  const released = hostOwned.delete(canonical);
  if (!released && !kinds.has(canonical)) return false;

  const builtin = builtinDefs.get(canonical);
  if (builtin) {
    kinds.set(canonical, builtin);
    for (const alias of builtin.aliases ?? []) aliases.set(alias, canonical);
  } else {
    const previous = kinds.get(canonical);
    kinds.delete(canonical);
    for (const alias of previous?.aliases ?? []) {
      if (aliases.get(alias) === canonical) aliases.delete(alias);
    }
  }

  notify();

  return released;
}

/**
 * Empty the registry completely, builtins included.
 *
 * For tests that need a clean slate — in particular any test asserting how host
 * and builtin registration interact, which cannot be written against a registry
 * still holding the previous test's kinds. Production code has no reason to
 * call it: a registry that can be emptied at runtime is a registry that can be
 * emptied at the wrong moment.
 */
export function resetNodeKindsForTests(): void {
  kinds.clear();
  aliases.clear();
  overrides.clear();
  schemaOverlays.clear();
  hostOwned.clear();
  builtinDefs.clear();
  builtinsEnsured = false;
  notify();
}

/**
 * A schema patch for a kind, sourced from a host's SERVER-side registry.
 *
 * fancy-flow has two kind registries. The PHP one lets a host decorate a
 * builtin and that decoration reaches the runtime and validation; the editor,
 * built from the JS registry, never learned any of it. A consumer hit this as a
 * field that existed, ran, and had no control in the panel.
 *
 * **The server owns what a node is CONFIGURED with. The client keeps what a
 * node DOES.** Only the serialisable half is here on purpose: `executor`,
 * `component`, `renderBody` and `icon` cannot cross a wire, and neither can
 * ports — `PortSpec` may be a FUNCTION of config, and three builtins use that
 * form (`switch_case` groups match keys onto one port and joins their labels;
 * `subflow` branches on a derived mode and cares about order). Expressing those
 * as data needs a mini-language with grouping, conditionals and ordering, which
 * is a second implementation of logic that already exists.
 */
export type KindSchemaOverlay = {
  /** Canonical id or alias — resolved either way. */
  kind: string;
  /**
   * REPLACES the kind's schema. Never merges.
   *
   * The motivating case is *drop seven fields and add one*, and a merge cannot
   * express a removal. A `remove: string[]` beside a merge would be two
   * mechanisms for one job, and their interaction would be the next bug. The
   * server sends the schema it wants; that is the point of it owning one.
   */
  configSchema?: ConfigField[];
  label?: string;
  description?: string;
  category?: NodeCategory;
};

export type KindSchemaOverlayResult = {
  /** Canonical ids that matched a registered kind. */
  applied: string[];
  /**
   * Ids that matched NOTHING, reported rather than dropped.
   *
   * A server lists many kinds and a client will not have registered all of
   * them. Applying what matches and staying quiet about the rest is how a
   * field goes missing with no error anywhere — which is the defect this whole
   * mechanism exists to end, so it must not be reintroduced by the fix.
   */
  unknown: string[];
  unapply: () => void;
};

/**
 * Apply server-sourced schema patches to kinds this client already has.
 *
 * It does NOT register kinds. A kind must exist locally for its executor,
 * ports and renderer; the overlay corrects its schema, it does not conjure one.
 */
export function applyKindSchemaOverlay(
  overlays: readonly KindSchemaOverlay[],
): KindSchemaOverlayResult {
  ensureBuiltinKinds();

  const applied: string[] = [];
  const unknown: string[] = [];
  const previous = new Map<string, KindSchemaOverlay | undefined>();

  for (const overlay of overlays) {
    const canonical = resolveKindId(overlay.kind);
    if (!canonical) {
      unknown.push(overlay.kind);
      continue;
    }

    if (!previous.has(canonical)) previous.set(canonical, schemaOverlays.get(canonical));
    schemaOverlays.set(canonical, { ...overlay, kind: canonical });
    applied.push(canonical);
  }

  if (applied.length > 0) notify();

  return {
    applied,
    unknown,
    unapply: () => {
      for (const [canonical, before] of previous) {
        if (before) {
          schemaOverlays.set(canonical, before);
        } else {
          schemaOverlays.delete(canonical);
        }
      }
      notify();
    },
  };
}

/** Drop every server-sourced schema patch. Mostly for tests. */
export function clearKindSchemaOverlays(): void {
  if (schemaOverlays.size === 0) return;
  schemaOverlays.clear();
  notify();
}

/**
 * Resolve any id — canonical or alias — to the canonical one, or null.
 *
 * `kind` is persisted inside every saved graph, so a bare name that two
 * packages could both claim is unfixable after the fact: the ambiguous string
 * is already in the document. Canonical ids are namespaced; aliases exist so
 * documents written before namespacing keep opening.
 */
export function resolveKindId(id: string): string | null {
  ensureBuiltinKinds();
  if (kinds.has(id)) return id;
  const canonical = aliases.get(id);
  return canonical && kinds.has(canonical) ? canonical : null;
}

/**
 * Rename or re-describe a kind you did not author.
 *
 * Before this existed the only way to relabel a builtin was `registerNodeKind`
 * with a full definition — which REPLACES the kind, so a consumer wanting
 * "Call an API" instead of "HTTP Request" had to re-declare that node's
 * configSchema, ports, executor and renderer, and silently forfeited whatever
 * the builtin gained in the next release. In practice nobody renamed a node,
 * and the palette could not be localised at all.
 *
 * ```ts
 * const undo = overrideNodeKind("@particle-academy/api_request", {
 *   label: "Call an API",
 *   description: "Fetch or post JSON to a URL",
 * });
 * ```
 *
 * Applies at `getNodeKind()` and `listNodeKinds()`, so one call reaches the
 * palette, the node cards on the canvas, `FlowViewer`, and anything else that
 * reads the registry. Returns an unsubscribe, matching `registerNodeKind`.
 *
 * Patching an unregistered id is allowed and takes effect if that kind is
 * registered later — order of module side effects is not something a consumer
 * should have to reason about.
 */
export function overrideNodeKind(name: string, patch: NodeKindPresentation): () => void {
  const canonical = resolveKindId(name) ?? name;
  const previous = overrides.get(canonical);

  overrides.set(canonical, { ...previous, ...patch });
  notify();

  return () => {
    if (previous) {
      overrides.set(canonical, previous);
    } else {
      overrides.delete(canonical);
    }
    notify();
  };
}

/** Remove every presentation override. Mostly for tests. */
export function clearNodeKindOverrides(): void {
  if (overrides.size === 0) return;
  overrides.clear();
  notify();
}

function withOverride(kind: NodeKindDefinition | undefined): NodeKindDefinition | null {
  if (!kind) return null;

  // base -> SERVER schema -> LOCAL presentation override.
  //
  // The local override wins, and the order is pinned by a test because it is
  // invisible until the two disagree: `overrideNodeKind` is the app author's
  // explicit choice about naming, which is more specific than a server default.
  const overlay = schemaOverlays.get(kind.name);
  const patch = overrides.get(kind.name);
  if (!overlay && !patch) return kind;

  const withSchema = overlay
    ? ({
        ...kind,
        ...(overlay.configSchema !== undefined ? { configSchema: overlay.configSchema } : {}),
        ...(overlay.label !== undefined ? { label: overlay.label } : {}),
        ...(overlay.description !== undefined ? { description: overlay.description } : {}),
        ...(overlay.category !== undefined ? { category: overlay.category } : {}),
      } as NodeKindDefinition)
    : kind;

  return patch ? ({ ...withSchema, ...patch } as NodeKindDefinition) : withSchema;
}

/** Get a single kind by canonical id or alias, or null. */
export function getNodeKind(name: string): NodeKindDefinition | null {
  const canonical = resolveKindId(name);
  return canonical ? withOverride(kinds.get(canonical) as NodeKindDefinition) : null;
}

/** Every id a kind answers to — canonical first. Used to key node-type maps. */
export function kindIds(kind: NodeKindDefinition): string[] {
  return [kind.name, ...(kind.aliases ?? [])];
}

/** List every registered kind, optionally filtered by category. */
export function listNodeKinds(category?: string): NodeKindDefinition[] {
  ensureBuiltinKinds();
  const all = Array.from(kinds.values()).map((k) =>
    withOverride(k as NodeKindDefinition),
  ) as NodeKindDefinition[];
  // Filter AFTER applying overrides, so an override that moves a node to a
  // different category actually moves it in the palette rather than leaving it
  // filed under the old one with a new name.
  return category ? all.filter((k) => k.category === category) : all;
}

/** Subscribe to registry changes. Returns an unsubscribe function. */
export function onNodeKindsChanged(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function notify(): void {
  for (const l of listeners) l();
}

/** Fill in defaults from a kind's configSchema for newly-created nodes. */
export function defaultConfigFor(kind: NodeKindDefinition): Record<string, unknown> {
  const fromKind = kind.defaultConfig ? { ...(kind.defaultConfig as Record<string, unknown>) } : {};
  for (const field of kind.configSchema ?? []) {
    if (fromKind[field.key] !== undefined) continue;
    if ("default" in field && (field as any).default !== undefined) {
      fromKind[field.key] = (field as any).default;
    }
  }
  return fromKind;
}

/**
 * Validate a config object against a kind's schema. Returns an array of
 * issues (empty = valid). Validation is intentionally light — type
 * coercion + required-field checks. Hosts can layer Zod / Ajv on top.
 */
export function validateConfig(
  kind: NodeKindDefinition,
  config: Record<string, unknown>,
): Array<{ key: string; message: string }> {
  const issues: Array<{ key: string; message: string }> = [];
  for (const field of kind.configSchema ?? []) {
    const value = config[field.key];
    if (field.required && (value === undefined || value === null || value === "")) {
      issues.push({ key: field.key, message: `${field.label} is required` });
      continue;
    }
    if (value === undefined || value === null) continue;
    const issue = validateField(field, value);
    if (issue) issues.push({ key: field.key, message: issue });
  }
  return issues;
}

function validateField(field: ConfigField, value: unknown): string | null {
  switch (field.type) {
    case "text":
    case "textarea":
    case "expression":
    case "credential":
      return typeof value === "string" ? null : `${field.label} must be a string`;
    case "number": {
      if (typeof value !== "number" || !Number.isFinite(value)) return `${field.label} must be a number`;
      if (field.min !== undefined && value < field.min) return `${field.label} must be >= ${field.min}`;
      if (field.max !== undefined && value > field.max) return `${field.label} must be <= ${field.max}`;
      return null;
    }
    case "switch":
      return typeof value === "boolean" ? null : `${field.label} must be a boolean`;
    case "select": {
      const allowed = field.options.map((o) => o.value);
      return allowed.includes(String(value)) ? null : `${field.label} must be one of ${allowed.join(", ")}`;
    }
    case "json":
      return null; // permissive — just JSON-shaped
    case "repeater": {
      if (!Array.isArray(value)) return `${field.label} must be a list`;
      if (field.minItems !== undefined && value.length < field.minItems) {
        return `${field.label} needs at least ${field.minItems}`;
      }
      if (field.maxItems !== undefined && value.length > field.maxItems) {
        return `${field.label} allows at most ${field.maxItems}`;
      }
      // Surface the first offending row so the author knows WHICH one.
      for (let i = 0; i < value.length; i++) {
        const row = value[i];
        if (!row || typeof row !== "object" || Array.isArray(row)) {
          return `${field.label} item ${i + 1} must be an object`;
        }
        for (const sub of field.fields) {
          const cell = (row as Record<string, unknown>)[sub.key];
          if (sub.required && (cell === undefined || cell === null || cell === "")) {
            return `${field.label} item ${i + 1}: ${sub.label} is required`;
          }
          if (cell === undefined || cell === null) continue;
          const issue = validateField(sub, cell);
          if (issue) return `${field.label} item ${i + 1}: ${issue}`;
        }
      }
      return null;
    }
    case "keyvalue": {
      if (typeof value !== "object" || value === null || Array.isArray(value)) {
        return `${field.label} must be a key/value map`;
      }
      const allowed = field.valueOptions?.map((o) => o.value);
      for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
        if (typeof v !== "string") return `${field.label}: "${k}" must be a string`;
        if (allowed && !allowed.includes(v)) {
          return `${field.label}: "${k}" must be one of ${allowed.join(", ")}`;
        }
      }
      return null;
    }
    case "document":
      return null; // opaque to fancy-flow — the host's editor owns its shape
    default:
      return null;
  }
}

/** Default accents per category. */
export function categoryAccent(category: string): string {
  switch (category) {
    case "trigger": return "#10b981";
    case "logic":   return "#f59e0b";
    case "data":    return "#0ea5e9";
    case "ai":      return "#8b5cf6";
    case "io":      return "#3b82f6";
    case "human":   return "#ec4899";
    case "output":  return "#a855f7";
    case "layout":  return "#64748b";
    case "annotation": return "#eab308";
    default:        return "#71717a";
  }
}

import type { TerminalSession } from "./registry/capabilities";
import type { TerminalTranscript } from "../use-flow-run/terminal-transcript";

/**
 * Public domain types for fancy-flow. Built-in nodes are layered on top of
 * @xyflow/react's `Node` so consumers can mix custom xyflow nodes alongside
 * the kit. Edges remain xyflow's standard `Edge`.
 */

import type { Edge, Node } from "@xyflow/react";
// Type-only, so this stays erased — `types.ts` must not pull a runtime module
// into every consumer that only wanted a type.
import type { RunIdentity } from "../use-flow-run/run-identity";

export type FlowNodeKind =
  | "trigger"
  | "action"
  | "decision"
  | "output"
  | "note"
  | "subgraph";

/** Status surfaced on the node while a run is in progress. */
export type NodeRunStatus = "idle" | "queued" | "running" | "done" | "error";

/** Port description on a node. Ports are visual handles xyflow can connect. */
export type PortDescriptor = {
  id: string;
  label?: string;
  /** Optional logical type for hosts that want to validate connections. */
  type?: string;
};

/** Common shape every kit node carries in its `data` slot. */
export type BaseNodeData = {
  label: string;
  description?: string;
  /** Free-form configuration the host owns (form values, code, parameters). */
  config?: Record<string, unknown>;
  /** Set by the runner; hosts shouldn't edit this directly. */
  status?: NodeRunStatus;
  /** Optional human-readable status detail (e.g. error message, current step). */
  statusText?: string;
  /**
   * Announced to a person just BEFORE this node runs — "Starting the deep
   * analysis". Authored on the node, so a graph narrates itself without the
   * host writing any per-node reporting code.
   *
   * Optional on purpose. Most nodes in a real graph are plumbing, and a run
   * that narrates all of them buries the two or three steps anyone follows.
   */
  startingMsg?: string;
  /**
   * Announced AFTER this node finishes — "Analysis complete".
   *
   * Emitted only when the node SUCCEEDS. A completion message printed after a
   * failure tells a human the opposite of what happened, in the part of the UI
   * they trust most; failures report through `node-status` and `log`.
   */
  stoppingMsg?: string;
  /** Per-node accent override, e.g. for theming a custom subclass. */
  color?: string;
  /** Input ports rendered on the node. Defaults vary by kind. */
  inputs?: PortDescriptor[];
  /** Output ports rendered on the node. Defaults vary by kind. */
  outputs?: PortDescriptor[];
};

export type TriggerNodeData = BaseNodeData & { kind: "trigger" };
export type ActionNodeData = BaseNodeData & { kind: "action" };
export type DecisionNodeData = BaseNodeData & { kind: "decision" };
export type OutputNodeData = BaseNodeData & { kind: "output" };
export type NoteNodeData = BaseNodeData & { kind: "note"; body?: string };
export type SubgraphNodeData = BaseNodeData & {
  kind: "subgraph";
  /** Ids of the nodes contained in this subgraph. */
  childIds?: string[];
  /** Whether the subgraph is shown collapsed (default true — children hidden). */
  collapsed?: boolean;
};

export type FlowNodeData =
  | TriggerNodeData
  | ActionNodeData
  | DecisionNodeData
  | OutputNodeData
  | NoteNodeData
  | SubgraphNodeData;

export type FlowNode = Node<FlowNodeData>;
export type FlowEdge = Edge;

/**
 * One value a workflow DECLARES that it accepts at run start.
 *
 * The declaration is the point. Before this existed, a caller passed
 * `initialInputs` keyed BY NODE ID — so they had to know the trigger happened
 * to be called `t`, and renaming that node broke every caller while the graph
 * itself stayed valid. Nothing reported it.
 *
 * And nothing said what a workflow accepted at all: no names, no types, no
 * defaults. An agent composing a call had nothing to read, and a misspelled key
 * did not fail — the value simply sat unused while the run reported success.
 */
export type WorkflowInput = {
  /** What a caller passes it as. */
  name: string;
  /**
   * Optional. Omitting it means "I am not asserting a shape", which must not
   * degrade into "nothing is allowed" — an undeclared type accepts anything.
   */
  type?: "string" | "number" | "boolean" | "object" | "array";
  /**
   * The run needs a value. Satisfied by a `default`, so `required` means
   * "this must resolve to something" rather than "the caller must type it".
   */
  required?: boolean;
  /** Used when the caller omits the key. An explicit value always wins. */
  default?: unknown;
  description?: string;
};

/** A serializable graph — what hosts persist, what agents read/write. */
export type FlowGraph = {
  nodes: FlowNode[];
  edges: FlowEdge[];
  /**
   * What this workflow accepts. Callers pass a flat object BY NAME.
   *
   * Omitted entirely when a graph takes none, so existing saved graphs are
   * unchanged byte for byte and every diff stays readable.
   */
  inputs?: WorkflowInput[];
};

/** Per-node executor signature. Inputs are keyed by input-port id. */
export type NodeExecutor<TIn = Record<string, unknown>, TOut = unknown> = (
  ctx: {
    node: FlowNode;
    inputs: TIn;
    /** Stops the run if called. */
    abort: (reason?: string) => never;
    /** Lets the executor stream status updates and partial outputs. */
    emit: (event: RunEvent) => void;
    /**
     * The registry THIS run is executing against.
     *
     * Handed down so an executor that starts a NESTED run gives the child the
     * same executors as the parent. `subflow` previously ran its child against
     * `config.executors ?? {}` — an empty registry unless the graph happened to
     * carry one — so a host kind resolved at top level and vanished one level
     * down, and a host that had REPLACED a builtin got the package's version in
     * the child. Same graph, different behaviour by nesting depth, reported
     * against the PHP twin as fancy-flow-php#7.
     *
     * Inheriting from the context rather than from a parameter is what makes it
     * unforgettable: any future nesting executor gets it without opting in.
     */
    executors?: ExecutorRegistry;
    /**
     * How deep this run is nested. 0 for a top-level run; `subflow` passes
     * depth + 1 to its child, so runaway recursion can be reported by name
     * rather than as a stack overflow.
     */
    depth?: number;
    /**
     * Who is running, and which attempt of which step this is.
     *
     * `ctx.run.stepKey(ctx.node.id)` is the idempotency key for a node that
     * writes to somebody else's system — stable across retries of this step,
     * distinct for every other execution of the same node.
     *
     * `undefined` when the host supplied no identity, and that is a real
     * answer: a write with no key must decline or accept one attempt, never
     * invent a key. See `RunIdentity`.
     */
    run?: RunIdentity;
    /**
     * The graph this node belongs to.
     *
     * A STRUCTURAL executor needs it: `for_each`'s `item` port fans out over a
     * lane derived from the graph — the nodes reachable from `item`, stopping
     * at anything also reachable from `done` — and that lane cannot be computed
     * from `node` and `inputs` alone.
     *
     * Without it the `item` port was accepted by the schema, drawn by the
     * editor, and silently ignored at run time on this runtime: downstream
     * nodes ran ONCE against the whole collection instead of once per item,
     * with no error. The PHP twin derives the same lane from `$ctx->graph` and
     * has since 0.6; parity was measured against a reference graph where the
     * two disagreed.
     *
     * Optional, because a host may construct a context by hand. An executor
     * that needs it must degrade rather than throw — `for_each` falls back to
     * publishing the collection, which is what it did everywhere before.
     */
    graph?: FlowGraph;
    /**
     * The terminal this node's lane owns, if it is inside a terminal lane.
     *
     * `session()` is a FUNCTION, not an open session, and that is the whole
     * lifetime rule in one shape: the terminal opens on first USE. A node that
     * sits inside a terminal lane and never calls this never spawns a process,
     * so drawing a lane around nodes that mostly do other things costs nothing.
     * Every node in the lane gets the SAME session, which is what makes `cd`
     * persist and an agent TUI still be running with its conversation intact.
     *
     * `undefined` when the node is not inside a terminal lane, and that is a
     * real answer rather than a missing one — a terminal node outside a lane
     * must say so rather than quietly opening a shell of its own, because one
     * unmanaged process per node is exactly what the lane exists to prevent.
     */
    terminal?: {
      session: () => Promise<TerminalSession>;
      /**
       * What the terminal has said, accumulated and matchable.
       *
       * Separate from `session()` because reading and writing are genuinely
       * different jobs with different hazards. `session()` hands over the raw
       * process; this hands over a buffer that already survived arbitrary
       * chunking, escape sequences that straddle chunks, and output that
       * arrived before any node was listening — none of which a node should be
       * asked to get right on its own, and all of which fail intermittently
       * when it doesn't.
       *
       * Opening the session is implied: a transcript with nothing feeding it
       * would silently never match.
       */
      transcript: () => Promise<TerminalTranscript>;
    };
  },
) => Promise<TOut> | TOut;

export type ExecutorRegistry = Partial<Record<FlowNodeKind | string, NodeExecutor>>;

export type RunEvent =
  | { type: "node-status"; nodeId: string; status: NodeRunStatus; text?: string }
  /**
   * A human-facing announcement a node makes around its own execution, from
   * `data.startingMsg` / `data.stoppingMsg`. Opt-in per node: most nodes in a
   * real graph are plumbing, and narrating all of them buries the few steps a
   * person cares about.
   *
   * Deliberately NOT folded into `node-status.text`, which already carries
   * "skipped", "resumed", "lane", "annotation" and raw error strings. Those are
   * diagnostics; these are addressed to a person. A consumer rendering a
   * progress feed cannot be asked to guess which is which — that is how an
   * error string ends up shown to a user as a status update.
   */
  | { type: "node-message"; nodeId: string; phase: "start" | "end"; message: string }
  | { type: "node-output"; nodeId: string; portId: string; value: unknown }
  | { type: "log"; nodeId?: string; level: "info" | "warn" | "error"; message: string; detail?: unknown }
  | { type: "run-start" }
  | { type: "run-end"; ok: boolean }
  | { type: "run-error"; error: string };

import type { FlowNode, PortDescriptor } from "../types";
import type { NodeKindDefinition, PortSpec } from "./types";

/**
 * Port resolution — the single place a node's ports are derived, shared by
 * the canvas renderer and the headless runtime.
 *
 * This module is deliberately React-free: `runFlow` (the `/engine` entry)
 * imports it, and the engine bundle must stay free of React.
 *
 * ## Why this is centralized
 *
 * Ports used to be read in two places that disagreed — the canvas consulted
 * `data.outputs ?? kind.outputs`, while the runtime consulted `data.outputs`
 * ONLY and fell back to a single `out` port. A kind that declared branch ports
 * therefore drew correctly and then routed as if it had one output, unless the
 * host remembered to mirror the ports onto every node's `data`. Both callers
 * now go through `resolveNodePorts`, so declared ports and executed ports
 * cannot drift apart.
 */

/**
 * Resolve a `PortSpec` against a config object.
 *
 * A config-driven spec is author-supplied and runs on every render, so a throw
 * is contained: it degrades to "undeclared" (letting the caller fall back)
 * rather than taking out the canvas or aborting a run mid-flight.
 */
export function resolvePortSpec<TConfig>(
  spec: PortSpec<TConfig> | undefined,
  config: TConfig,
): PortDescriptor[] | undefined {
  if (spec === undefined) return undefined;
  if (typeof spec !== "function") return spec;
  try {
    const resolved = (spec as (c: TConfig) => PortDescriptor[])(config);
    return Array.isArray(resolved) ? resolved : undefined;
  } catch {
    return undefined;
  }
}

/** Read the config bag off a node, tolerating the FlowNodeData union. */
export function nodeConfig(node: Pick<FlowNode, "data">): Record<string, unknown> {
  return ((node.data as any)?.config ?? {}) as Record<string, unknown>;
}

/**
 * Resolve a node's effective ports.
 *
 * Precedence: explicit `data.inputs`/`data.outputs` (a per-node host override)
 * beats the kind's declaration. `undefined` means "nothing declared" — the
 * caller applies its own category default.
 */
export function resolveNodePorts(
  node: Pick<FlowNode, "data">,
  kind?: Pick<NodeKindDefinition<any>, "inputs" | "outputs">,
): { inputs?: PortDescriptor[]; outputs?: PortDescriptor[] } {
  const config = nodeConfig(node);
  const data = node.data as any;
  return {
    inputs: data?.inputs ?? resolvePortSpec(kind?.inputs, config),
    outputs: data?.outputs ?? resolvePortSpec(kind?.outputs, config),
  };
}

import type { FlowGraph } from "../types";

/**
 * Host capabilities — the services core nodes need but must never depend on.
 *
 * A node that imports a provider SDK forces every consumer to install it: a
 * workflow app that never calls a model should not inherit an LLM dependency.
 * So core declares the CONTRACT and the host supplies the implementation, the
 * same arrangement `renderDocumentField` already uses for documents.
 *
 * That keeps opinionated nodes in core without their opinions: `llm_branch`
 * ships the routing semantics, port derivation and config UI, while whichever
 * client the host registers — Prism, an OpenAI SDK, a local model, a fake in a
 * test — decides how the question actually gets asked.
 *
 * Registration is deliberately explicit and typed per capability rather than a
 * stringly-keyed bag, so a missing one is a clear error at the seam instead of
 * an undefined somewhere downstream.
 */

// ── LLM ─────────────────────────────────────────────────────────────────────

export type LlmRoute = { port: string; description?: string };

export type LlmRouteRequest = {
  /** Optional framing for the decision. */
  system?: string;
  /** What the model is deciding about. */
  prompt: string;
  /** The ports it must choose between. */
  routes: LlmRoute[];
  provider?: string;
  model?: string;
  /** Host-resolved credential reference, never a raw key. */
  credential?: string;
};

export type LlmRouteChoice = {
  /** Must be one of the requested route ports. */
  port: string;
  /** Why — carried down the chosen port so a run is explainable afterwards. */
  reason?: string;
};

/**
 * The only thing core asks of an LLM: given routes, pick one.
 *
 * Deliberately not a general chat interface. A narrow contract is one a host
 * can satisfy in a few lines over any SDK, and it keeps the choice
 * machine-checkable — an implementation should constrain the model to the
 * declared ports (structured output / enum) rather than parsing prose.
 */
export type LlmClient = {
  chooseRoute: (request: LlmRouteRequest) => Promise<LlmRouteChoice> | LlmRouteChoice;
};

let llmClient: LlmClient | null = null;

/** Install the host's LLM client. Returns an unregister function. */
export function registerLlmClient(client: LlmClient): () => void {
  llmClient = client;
  return () => {
    if (llmClient === client) llmClient = null;
  };
}

export function getLlmClient(): LlmClient | null {
  return llmClient;
}

// ── Terminal ────────────────────────────────────────────────────────────────

/** What to launch. Omit `command` for the host's default shell. */
export type TerminalSessionSpec = {
  command?: string;
  args?: string[];
  cwd?: string;
  env?: Record<string, string>;
  cols?: number;
  rows?: number;
};

export type TerminalExit = { exitCode: number; signal?: string };

/**
 * One live terminal, owned by the host for as long as the run needs it.
 *
 * Output arrives by SUBSCRIPTION rather than a `read()` the engine calls. A TUI
 * emits continuously and on its own schedule — repainting, streaming a reply,
 * redrawing a spinner — so a polled read either misses bytes between calls or
 * has to buffer them anyway, and every host would invent that buffer
 * differently.
 */
export type TerminalSession = {
  id: string;
  write: (data: string) => void | Promise<void>;
  /** Subscribe to output. Returns an unsubscribe. */
  onData: (listener: (chunk: string) => void) => () => void;
  /**
   * Resolves when the process exits.
   *
   * A promise rather than an `exited` flag the engine polls, so "the agent
   * quit" and "the agent has not answered yet" are distinguishable while
   * waiting. Without it a node awaiting output cannot tell a slow reply from a
   * dead process, and waits out its timeout either way.
   */
  exited: Promise<TerminalExit>;
  close: () => void | Promise<void>;
};

/**
 * The only thing core asks of a terminal: open one.
 *
 * ## Why the contract stops at the PTY
 *
 * There is deliberately no `waitForOutput(pattern)` here, though every terminal
 * node needs one. Matching is derivable from `onData`, so putting it in the
 * contract would mean every host implements it — and two implementations of one
 * agreed rule is precisely how a week of registry defects happened: both sides
 * agreed output matching should work, and would have disagreed on whether a
 * pattern spans chunk boundaries, whether ANSI escapes are stripped first, and
 * what a timeout returns.
 *
 * So core owns the matching and the host owns the process. A host satisfies
 * this in a few lines over `node-pty`; nothing about how a run interprets the
 * bytes is up to it.
 *
 * ## Why this exists at all
 *
 * A terminal cannot live in the engine. `node-pty` is a native addon, so
 * importing it would break every browser build of this package and force the
 * dependency on consumers who never run a terminal node — the same reason the
 * LLM client is a contract rather than an SDK import. The desktop app that CAN
 * spawn a PTY registers one; everyone else never notices the capability exists.
 */
export type TerminalHost = {
  open: (spec: TerminalSessionSpec) => Promise<TerminalSession> | TerminalSession;
};

let terminalHost: TerminalHost | null = null;

/** Install the host's terminal. Returns an unregister function. */
export function registerTerminalHost(host: TerminalHost): () => void {
  terminalHost = host;
  return () => {
    if (terminalHost === host) terminalHost = null;
  };
}

export function getTerminalHost(): TerminalHost | null {
  return terminalHost;
}

// ── Workflow resolution ─────────────────────────────────────────────────────

/**
 * Why a workflow reference could not be resolved.
 *
 * `missing` and `version-mismatch` are deliberately distinct. Collapsing them
 * into a bare null makes "no such workflow" indistinguishable from "that
 * workflow exists, but it is not the one you pinned" — and the second wants an
 * error naming both versions, because it is the interesting failure.
 */
export type WorkflowResolutionFailure = {
  reason: "missing" | "version-mismatch";
  /** The version the host actually holds, when it holds one. */
  available?: number;
  message?: string;
};

export type WorkflowResolution = FlowGraph | WorkflowResolutionFailure | null;

/**
 * Resolve a workflow reference to a runnable graph.
 *
 * `subflow` names another workflow rather than embedding it, so the host owns
 * where workflows live — a database, a file, an API.
 *
 * ## Why `version` is here
 *
 * A workflow another workflow depends on is an INTERFACE, and interfaces need
 * pins. Without a version, a parent goes on calling `invoice-triage`, someone
 * edits that child, and the parent now runs different logic having reported
 * success the whole time — correct-looking, no error, wrong behaviour. The same
 * failure family as the 0.9.0 routing divergence.
 *
 * The parameter lives on the resolver rather than being encoded into the ref
 * string (`invoice-triage@3`) because a stringly-typed protocol is one every
 * host invents differently — the "three vocabularies for one node" problem.
 *
 * Raised by the MOIC Suite consumer, whose `workflow_ref` pins versions and
 * fails loudly on mismatch. Their point: a host COULD NOT implement pinning
 * before this, because the node had no way to ask and the resolver no way to
 * receive.
 *
 * Returning `null` still means "no such workflow". Return a
 * {@link WorkflowResolutionFailure} to distinguish a version mismatch.
 */
export type WorkflowResolver = (
  ref: string,
  version?: number,
) => Promise<WorkflowResolution> | WorkflowResolution;

/** Narrow a resolver's return value to an explicit failure. */
export function isResolutionFailure(value: WorkflowResolution): value is WorkflowResolutionFailure {
  return (
    typeof value === "object" &&
    value !== null &&
    "reason" in value &&
    (value as WorkflowResolutionFailure).reason !== undefined
  );
}

let workflowResolver: WorkflowResolver | null = null;

/** Install the host's workflow resolver. Returns an unregister function. */
export function registerWorkflowResolver(resolver: WorkflowResolver): () => void {
  workflowResolver = resolver;
  return () => {
    if (workflowResolver === resolver) workflowResolver = null;
  };
}

export function getWorkflowResolver(): WorkflowResolver | null {
  return workflowResolver;
}

// ── Introspection ───────────────────────────────────────────────────────────

export type CapabilityId = "llm" | "workflow_resolver" | "document" | "terminal";

/**
 * Which capabilities are currently satisfied.
 *
 * Exists so a host (or the CLI, or an agent over MCP) can answer "what does
 * this graph need that I haven't wired?" BEFORE a run fails halfway through.
 */
export function capabilityStatus(): Record<CapabilityId, boolean> {
  // Imported lazily to avoid dragging the React-dependent rich-input module
  // into the headless engine.
  let documentReady = false;
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
    documentReady = Boolean((globalThis as any).__fancyFlowDocumentAdapter);
  } catch {
    documentReady = false;
  }
  return {
    llm: llmClient !== null,
    workflow_resolver: workflowResolver !== null,
    document: documentReady,
    // Listed here for the reason this function exists at all. A graph with a
    // terminal lane and no host registered fails PART WAY THROUGH — after the
    // nodes before it have already run and possibly written somewhere — and the
    // whole point of asking up front is to learn that before starting. Leaving
    // it out would have made the one check designed to catch this report
    // all-clear for exactly the case it was built for.
    terminal: terminalHost !== null,
  };
}

import { getNodeKind } from "../registry/registry";
import type { FlowGraph, FlowNode } from "../types";

/**
 * What a node emits, described well enough for an author to reference it.
 *
 * This is deliberately NOT `outputs` — that is a `PortSpec`, which describes
 * WIRES (port ids and labels). Nothing in the registry described the DATA on
 * those wires, so "what can I write in this field" had no answer to derive
 * from. Hence a second, small declaration.
 */
export type OutputField = {
  /** Dot-path relative to the emitted value: `text`, `user.email`. */
  path: string;
  type?: "string" | "number" | "boolean" | "object" | "array" | "unknown";
  description?: string;
};

/**
 * A kind's output shape — static, or computed from the node's config.
 *
 * The function form is the important one. A `user_input` step emits exactly the
 * field keys its author defined, and a `transform` emits the keys it was told
 * to build; no static list can know either. A static list would have forced
 * every dynamic kind to declare nothing, which is the case an author most needs
 * help with.
 */
export type OutputShape<TConfig = Record<string, unknown>> =
  | OutputField[]
  | ((config: TConfig) => OutputField[]);

/** One entry in the variable picker. */
export type AvailableVariable = {
  /** Exactly what gets inserted, including the braces. */
  expression: string;
  /** The bare path, for display: `$json.text`. */
  path: string;
  type?: OutputField["type"];
  description?: string;
  /** Label of the upstream node this came from, for disambiguation. */
  source?: string;
};

/**
 * `$json` and `$input` both alias the `in` port value in the PHP resolver
 * (`Expr::resolvePath`). We suggest ONE of them so the picker does not present
 * the same variable twice under two names; `$json` is the spelling every
 * builtin kind's `example` already uses.
 */
const ROOT = "$json";

function expr(path: string): string {
  return `{{ ${path} }}`;
}

/** Resolve a kind's output shape for a specific node. */
export function outputFieldsFor(node: FlowNode): OutputField[] {
  const kindName = (node.data as { kind?: string } | undefined)?.kind ?? node.type;
  if (!kindName) return [];

  const kind = getNodeKind(kindName) as { outputShape?: OutputShape } | undefined;
  const shape = kind?.outputShape;
  if (!shape) return [];

  if (typeof shape === "function") {
    // A kind computes this from author-supplied config, which is exactly where
    // a throw would be easiest to write and worst to ship — a malformed config
    // would take the whole panel down rather than showing one short list.
    try {
      const config = (node.data as { config?: Record<string, unknown> } | undefined)?.config ?? {};
      return shape(config) ?? [];
    } catch {
      return [];
    }
  }
  return shape;
}

/**
 * The variables an author can reference from `nodeId`, in this graph.
 *
 * Only the DIRECT predecessors are consulted, because `in` is the value on the
 * incoming wire. Walking further would offer a grandparent's fields, which
 * resolve to `null` at runtime — a suggestion that silently produces nothing is
 * worse than no suggestion, since the author has no reason to doubt it.
 *
 * Always includes the whole input. That one exists no matter what upstream
 * declared, and it is the escape hatch when a kind has no `outputShape` yet.
 */
export function baseVariables(): AvailableVariable[] {
  return [
    { expression: expr(ROOT), path: ROOT, type: "unknown", description: "The whole incoming value." },
  ];
}

export function availableVariables(graph: FlowGraph, nodeId: string): AvailableVariable[] {
  const out: AvailableVariable[] = baseVariables();
  const seen = new Set<string>([ROOT]);

  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  const upstreamIds = graph.edges.filter((e) => e.target === nodeId).map((e) => e.source);

  for (const id of upstreamIds) {
    if (id === nodeId) continue; // a self-edge is not an input shape
    const upstream = byId.get(id);
    if (!upstream) continue;

    const kindName = (upstream.data as { kind?: string } | undefined)?.kind ?? upstream.type;
    const label =
      (upstream.data as { label?: string } | undefined)?.label ??
      (kindName ? getNodeKind(kindName)?.label : undefined);

    for (const field of outputFieldsFor(upstream)) {
      const path = `${ROOT}.${field.path}`;
      if (seen.has(path)) continue;
      seen.add(path);
      out.push({
        expression: expr(path),
        path,
        type: field.type,
        description: field.description,
        source: label,
      });
    }
  }

  return out;
}

/** One documented form of the expression grammar. */
export type ExpressionForm = { syntax: string; meaning: string };

export type ExpressionGrammarHelp = {
  forms: ExpressionForm[];
  note: string;
};

/**
 * The reference help shown beside an expression field.
 *
 * Every form here is one `Expr::resolvePath` implements — a dot-path and
 * nothing else. It is tempting to document `{{ a && b }}` or `{{ a + b }}`
 * because they look like expressions; the resolver would return `null` for
 * both, and an author following the help would have no way to tell why.
 */
export function describeExpressionGrammar(): ExpressionGrammarHelp {
  return {
    forms: [
      { syntax: "{{ $json }}", meaning: "The whole value arriving on this node's input." },
      { syntax: "{{ $json.field }}", meaning: "One key of that value. Dot-paths nest: $json.user.email." },
      { syntax: "{{ $input.field }}", meaning: "An alias for $json — the same value, either spelling." },
      { syntax: "{{ in }}", meaning: "The input by its context key, rather than through the alias." },
    ],
    note:
      "Dot-paths only — no arithmetic, comparisons or function calls; anything else resolves to nothing. " +
      "A field that is exactly one expression keeps the resolved value's type; mixed text interpolates as a string. " +
      "fancy-flow's own runFlow does not interpolate: it hands config to your executor verbatim, and the " +
      "fancy-flow-php runtime is what resolves these.",
  };
}

import type { ComponentType, ReactNode } from "react";
import type { OutputShape } from "../expressions/variables";
import type { NodeProps } from "@xyflow/react";
import type { FlowNode, NodeExecutor, PortDescriptor } from "../types";
import type { PauseAwaiting } from "./pause";
import type { SideEffects } from "../marketplace/manifest";

/** Categories used by the palette for grouping. */
export type NodeCategory =
  | "trigger"
  | "logic"
  | "data"
  | "ai"
  | "io"
  | "human"
  | "output"
  | "layout"
  | "annotation"
  | "custom";

/**
 * Tagged-union of config-field shapes the auto-form knows how to render.
 * Each variant has a `key` (the config object property it writes to) and
 * a `label`. Hosts can render fully custom panels via the kind's
 * `renderPanel` instead.
 */
export type ConfigField =
  | TextConfigField
  | TextareaConfigField
  | NumberConfigField
  | SelectConfigField
  | SwitchConfigField
  | JsonConfigField
  | ExpressionConfigField
  | CredentialConfigField
  | RepeaterConfigField
  | KeyValueConfigField
  | DocumentConfigField;

/**
 * Field types that may appear inside a `repeater` row. Excludes `repeater`
 * itself — a row of rows has no sane form rendering, and the nesting would
 * make the config shape hard for an agent to emit.
 */
export type RepeaterRowField = Exclude<ConfigField, RepeaterConfigField>;

type ConfigFieldBase = {
  key: string;
  label: string;
  description?: string;
  required?: boolean;
};

export type TextConfigField = ConfigFieldBase & {
  type: "text";
  placeholder?: string;
  default?: string;
  /**
   * Optional fixed choices. When present the field renders as a select
   * instead of a free-text input — the same field declaration serves both a
   * free-form value and a constrained one, so a kind can gain choices later
   * without changing its `type` or migrating stored config.
   *
   * Bare strings are shorthand for `{ value, label: value }`.
   *
   * Unlike `type: "select"`, a stored value outside the list is preserved and
   * shown rather than rejected — choices can change after configs are saved,
   * and silently dropping an author's value is worse than showing a stale one.
   */
  choices?: Array<string | { value: string; label?: string }>;
};
export type TextareaConfigField = ConfigFieldBase & {
  type: "textarea";
  placeholder?: string;
  rows?: number;
  default?: string;
};
export type NumberConfigField = ConfigFieldBase & {
  type: "number";
  min?: number;
  max?: number;
  step?: number;
  default?: number;
};
export type SelectConfigField = ConfigFieldBase & {
  type: "select";
  options: Array<{ value: string; label: string }>;
  default?: string;
};
export type SwitchConfigField = ConfigFieldBase & {
  type: "switch";
  default?: boolean;
};
export type JsonConfigField = ConfigFieldBase & {
  type: "json";
  language?: "json" | "yaml" | "javascript";
  rows?: number;
  default?: unknown;
  /**
   * Declared types per path, as a JSON **string** — `{"retries":"integer"}`.
   *
   * Consumed by richer editors (see `/fields/react-fancy`) to pick a control
   * per value and report contradictions; ignored by the built-in textarea,
   * which has nowhere to put it. Optional, because plenty of JSON config —
   * an arbitrary request body, a JSON Schema — has no fixed shape to declare.
   *
   * A string rather than an object so it survives an MCP round-trip: a kind
   * definition travels as JSON to agents, and a nested object here would be
   * indistinguishable from the value it describes.
   */
  keyMap?: string;
};
export type ExpressionConfigField = ConfigFieldBase & {
  type: "expression";
  /** A short example string shown as placeholder, e.g. "{{ $json.name }}". */
  example?: string;
  default?: string;
};
export type CredentialConfigField = ConfigFieldBase & {
  type: "credential";
  /** Logical credential type. The host implements lookup / picker. */
  credentialType: string;
};

/**
 * Repeater — an editable list of objects, each row authored with its own
 * sub-schema of ConfigFields. This is what a node kind should reach for
 * instead of `type: "json"` whenever its config is list-shaped (form field
 * lists, router routes, tool bindings). Keeping it declarative is what lets
 * `NodeConfigPanel` stay the single authoring surface for humans AND keeps
 * the shape introspectable for agents.
 *
 * Value shape: `Array<Record<string, unknown>>`.
 */
export type RepeaterConfigField = ConfigFieldBase & {
  type: "repeater";
  /** Schema applied to every row. */
  fields: RepeaterRowField[];
  /**
   * Row field whose value titles the row in the editor. Falls back to the
   * first field's value, then to "Item N".
   */
  titleKey?: string;
  /** Label for the add button. Default: "Add". */
  addLabel?: string;
  /** Bounds enforced by validation + the add/remove controls. */
  minItems?: number;
  maxItems?: number;
  default?: Array<Record<string, unknown>>;
};

/**
 * Key/value map — an editable `Record<string, string>`. Use for filter maps,
 * input bindings, header maps, and case→port tables.
 *
 * Value shape: `Record<string, string>`.
 */
export type KeyValueConfigField = ConfigFieldBase & {
  type: "keyvalue";
  keyLabel?: string;
  valueLabel?: string;
  keyPlaceholder?: string;
  valuePlaceholder?: string;
  /** Constrain values to a fixed set (e.g. the node's own port ids). */
  valueOptions?: Array<{ value: string; label: string }>;
  addLabel?: string;
  default?: Record<string, string>;
};

/**
 * Document — an opaque rich/structured document stored in node config and
 * edited by a HOST-SUPPLIED editor, wired through
 * `NodeConfigPanel`'s `renderDocumentField`.
 *
 * fancy-flow deliberately does not know what a document *is* — same
 * arrangement as `credential`. That keeps rich human-input surfaces (authored
 * pages, required-reading steps, multi-section forms) possible without the
 * editor taking a dependency on any particular document model or CMS.
 */
export type DocumentConfigField = ConfigFieldBase & {
  type: "document";
  /**
   * Logical document format, passed through to the host renderer so one host
   * can serve several (e.g. "stages", "markdown", "portable-text").
   */
  documentType?: string;
  default?: unknown;
};

/**
 * Port declaration — either a fixed list, or a function of the node's config
 * for kinds whose branches ARE their config (switch cases, router routes).
 *
 * Declaring the function form keeps the canvas ports, the config, and the
 * ports the runtime activates in lockstep automatically; a static list forces
 * every consumer to hand-sync `data.outputs` from config in a custom renderer,
 * and forgetting to breaks routing silently at execution time.
 */
export type PortSpec<TConfig = unknown> =
  | PortDescriptor[]
  | ((config: TConfig) => PortDescriptor[]);

/**
 * Context passed to a kind's optional `renderBody`. Hosts can read the
 * resolved config + node id to render whatever fancy-* component they
 * want inside the node card.
 */
export type RenderBodyContext<TConfig = unknown> = {
  nodeId: string;
  config: TConfig;
  selected: boolean;
};

/**
 * How a kind's output relates to its input. See `NodeKindDefinition.emits`.
 *
 * Every value is TOP-LEVEL by construction — a relation cannot describe a value
 * nested under a key, which is why `wait` declares a field list instead.
 */
export type EmitsRelation =
  | "input"
  | "inputs-merged"
  | "input-map-merged"
  | `expression:${string}`;

/**
 * NodeKindDefinition — declares an authorable node type. Register one
 * via `registerNodeKind()`. Hosts (and the agent bridge) introspect the
 * registry to know what's authorable.
 */
export type NodeKindDefinition<TConfig = Record<string, unknown>, TIn = any, TOut = any> = {
  /**
   * Canonical identifier — the xyflow node `type` and the value persisted as
   * `kind` in every saved document.
   *
   * Namespace it when publishing (`@fancy/llm_branch`,
   * `@acme/salesforce_upsert`). A bare name that two packages could both claim
   * makes stored graphs ambiguous, and that is unfixable afterwards because the
   * ambiguous string is already written into the document.
   */
  name: string;
  /**
   * Other ids this kind answers to — previous bare names, or a short alias.
   * Resolution accepts them, but export always writes `name`, so documents
   * converge on the canonical id as they are re-saved.
   */
  aliases?: string[];
  /** Palette grouping. */
  category: NodeCategory;
  /** Display label. */
  label: string;
  /** One-line summary surfaced in the palette + agent bridge. */
  description?: string;
  /**
   * Icon rendered in the node header and the palette row. A glyph string is
   * fine; any ReactNode works, so a brand SVG can be dropped in directly.
   */
  icon?: ReactNode;
  /** Hex / CSS color for the header bar. Falls back to a category default. */
  accent?: string;

  /** Declarative form schema for the config panel. */
  configSchema?: ConfigField[];
  /** Default config values used when a node of this kind is created. */
  defaultConfig?: TConfig;

  /** Input ports. Defaults vary by category. See `PortSpec`. */
  inputs?: PortSpec<TConfig>;
  /** Output ports. Defaults vary by category. See `PortSpec`. */
  outputs?: PortSpec<TConfig>;
  /**
   * What this kind EMITS, described well enough for an author to reference it
   * in a `{{ }}` field. Distinct from `outputs`, which describes wires (port
   * ids), not the data on them — nothing in the registry described the latter,
   * so a variable picker had nothing to read.
   *
   * A function when the honest answer depends on config: a `user_input` step
   * emits the field keys its author defined, which no static list can know.
   */
  outputShape?: OutputShape<TConfig>;

  /**
   * How this kind's output RELATES to its input, when the relation is what is
   * knowable rather than a field list.
   *
   * `outputShape` answers *which fields*; this answers *where they come from*.
   * Separate because they are separate questions, and one field carrying
   * sometimes-a-list-sometimes-a-keyword is one a reader handles only in the
   * form it met first.
   *
   * - `"input"` — emits its input unchanged
   * - `"inputs-merged"` — the union of every input PAYLOAD's fields
   * - `"input-map-merged"` — the raw input MAP merged in, whose shape
   *   DEPENDS ON POSITION: `collectInputs` seeds an entry node flat and
   *   keys every other node by handle, so a `schedule_trigger` with an
   *   inbound edge emits `{ cron, timezone, in: {...} }`. Two names because
   *   they are two operations, not one plus a positional rule.
   * - `` `expression:${string}` `` — the shape the expression in THAT CONFIG KEY
   *   names. The key is part of the value because a consumer hardcoding "the
   *   field called expression" has copied our knowledge one level down, which is
   *   the thing this removes: `transform` reads `expression`, `variable` reads
   *   `value`.
   * - a function of config, for a kind whose relation depends on how it was
   *   configured.
   *
   * **A relation with no destination can only express a TOP-LEVEL merge.**
   * `wait` returns `{ waited, duration, input }` — it NESTS its input under a
   * key. `emits: "input"` there would make a reader accept
   * `{{ in.<any inbound field> }}` at top level, which resolves to nothing at
   * run time. It keeps a static `outputShape` with an opaque `input` field
   * instead. Read the executor and ask *merge or nest* before assigning one;
   * under-claiming is free.
   *
   * An `expression` relation is knowable only when the whole config string is a
   * SINGLE reference. Interpolating several yields a string with no addressable
   * fields, and a reader that expands it anyway over-permits.
   */
  emits?: EmitsRelation | ((config: TConfig) => EmitsRelation | null);

  /** Optional custom body rendered inside the node card. */
  renderBody?: (ctx: RenderBodyContext<TConfig>) => ReactNode;

  /**
   * Optional override for the config panel. Receives the current config and
   * an onChange to update it. Defaults to the auto-generated form.
   */
  renderPanel?: (props: {
    config: TConfig;
    onChange: (next: TConfig) => void;
    nodeId: string;
  }) => ReactNode;

  /**
   * Executor — host-implemented function that runs at flow execution.
   * Optional: built-in agentic kinds ship without one so the host wires
   * the actual work (memory store backend, LLM client, HTTP fetcher, etc.).
   */
  executor?: NodeExecutor<TIn, TOut>;

  /**
   * Declares that this kind halts the run to wait for a person, and what for.
   *
   * Only a declaration — the executor still emits the pause (via
   * `pauseForHuman`). Its value is that it is readable WITHOUT running the
   * graph: a host can be told "this workflow needs a resume path you haven't
   * built" before the first run parks itself forever, and the marketplace can
   * refuse to list a pausing node whose package never says so.
   */
  pausesForHuman?: PauseAwaiting;

  /**
   * Whether a node of this kind is safe to run twice.
   *
   * The same three values a marketplace manifest declares (see `SideEffects`),
   * lifted onto the KIND so it is readable at run time. A manifest is install-
   * time data; a durable runner needs this while deciding whether to retry, and
   * cannot go and read a manifest to find out.
   *
   * `fancy-flow-php`'s per-node queue driver keys its retry policy on exactly
   * this: an `unsafe-to-replay` node gets one attempt whatever `tries` says,
   * because a retried `git_pr_open` opens a second pull request. This field is
   * the TypeScript half of that contract — the twins declare the same kind
   * metadata or they are not twins.
   *
   * Declaration only. Nothing here enforces it; a host's runner decides what to
   * do with it, and the TS in-process runner currently does not retry at all.
   */
  sideEffects?: SideEffects;

  /**
   * Make nodes of this kind resizable via drag handles (xyflow NodeResizer).
   * `true` enables it with defaults; pass options to bound it. The resulting
   * width/height are written onto the node and persisted by the schema (0.21+).
   */
  resizable?:
    | boolean
    | { minWidth?: number; minHeight?: number; maxWidth?: number; maxHeight?: number; keepAspectRatio?: boolean };

  /**
   * Contextual per-node toolbar (xyflow NodeToolbar), shown while the node is
   * selected — a discoverable, agent-legible alternative to the right-click
   * menu. Call `useFlowEditor()` inside it to reach the editor api.
   */
  toolbar?: (ctx: { nodeId: string; config: TConfig; selected: boolean }) => ReactNode;

  /**
   * Full custom node renderer. When set, `buildNodeTypes` uses this component
   * for the kind INSTEAD of the default `RegistryNode` card — the escape hatch
   * for nodes that aren't cards (lanes / containers / groups). Receives
   * xyflow's `NodeProps`.
   */
  component?: ComponentType<NodeProps<FlowNode>>;

  /**
   * Opt this kind into reactive data flow: during a run, a node's computed
   * output is written back into its `data.output`, so its card reflects the
   * value live ("computing flows"). Default off — non-reactive kinds are
   * untouched, so this is purely additive.
   */
  reactive?: boolean;
};

