/**
 * TS model types for the well-known files modeled by `fancy-x-files`.
 *
 * These are intentionally small, standalone shapes (this package does NOT
 * import the PHP/JS port) so the editor builds + ships independently. They
 * mirror the canonical shapes emitted by the `fancy-x-files` packages.
 *
 * Every model is plain JSON: arrays of objects + primitives. That makes the
 * whole surface agent-emittable — an embedded agent can read the current
 * model, propose a new one, and hand it back through the same `onChange`
 * channel a human uses (Human+ UX contract).
 */

/** The well-known files this suite can edit + preview. */
export type XFileKind =
  | "robots"
  | "securityTxt"
  | "llmsTxt"
  | "humansTxt"
  | "sitemap"
  | "agents";

/** robots.txt — grouped crawl rules, sitemaps, host, protected paths. */
export interface RobotsGroup {
  /** `User-agent` lines for this group. `["*"]` for all. */
  userAgents: string[];
  /** `Allow:` paths. */
  allow: string[];
  /** `Disallow:` paths. */
  disallow: string[];
  /** Optional `Crawl-delay:` seconds. */
  crawlDelay?: number;
}

export interface RobotsModel {
  groups: RobotsGroup[];
  /** Absolute `Sitemap:` URLs. */
  sitemaps: string[];
  /**
   * Paths that must be Disallowed for every user-agent and may NEVER be
   * Allowed — mirrors the PHP `protect()` safety rail. The renderer pins
   * these as Disallow on every group; the editor refuses to Allow them.
   */
  protectedPaths: string[];
  /** Optional `Host:` directive. */
  host?: string;
}

/** security.txt (RFC 9116). */
export interface SecurityTxtModel {
  /** `Contact:` — one or more mailto:/https: URIs. At least one required. */
  contact: string[];
  /** `Expires:` — ISO 8601 timestamp; MUST be in the future. */
  expires: string;
  /** `Encryption:` URI. */
  encryption?: string;
  /** `Acknowledgments:` URI. */
  acknowledgments?: string;
  /** `Preferred-Languages:` comma-separated tags. */
  preferredLanguages?: string;
  /** `Canonical:` URI. */
  canonical?: string;
  /** `Policy:` URI. */
  policy?: string;
  /** `Hiring:` URI. */
  hiring?: string;
}

/** llms.txt — Markdown index of resources for LLMs. */
export interface LlmsLink {
  title: string;
  url: string;
  notes?: string;
}

export interface LlmsSection {
  name: string;
  links: LlmsLink[];
}

export interface LlmsTxtModel {
  title: string;
  /** The blockquote summary directly under the H1. */
  summary?: string;
  /** Free-form Markdown paragraph(s) of detail. */
  details?: string;
  sections: LlmsSection[];
}

/** humans.txt — credits + site colophon. */
export interface HumansTxtEntry {
  /** e.g. "Developer", "Designer". */
  role: string;
  name: string;
  /** Optional contact / handle / site. */
  contact?: string;
}

export interface HumansTxtModel {
  team: HumansTxtEntry[];
  /** "Site" section free-text (Standards, Components, Software, …). */
  site?: string;
  thanks?: string[];
}

/** sitemap.xml — a flat URL set. */
export type SitemapChangeFreq =
  | "always"
  | "hourly"
  | "daily"
  | "weekly"
  | "monthly"
  | "yearly"
  | "never";

export interface SitemapUrl {
  loc: string;
  /** ISO 8601 date. */
  lastmod?: string;
  changefreq?: SitemapChangeFreq;
  /** 0.0 – 1.0. */
  priority?: number;
}

export interface SitemapModel {
  urls: SitemapUrl[];
}

/**
 * /AGENTS — a machine-readable register of the agents allowed (or denied) to
 * act on the site, mirroring the robots-style "agent policy" idea.
 */
export interface AgentEntry {
  /** Stable identifier / handle for the agent. */
  id: string;
  /** Human label. */
  name?: string;
  /** Policy for this agent. */
  policy: "allow" | "deny";
  /** Optional homepage / contact URL. */
  url?: string;
  /** Optional one-line description of permitted scope. */
  scope?: string;
}

export interface AgentsModel {
  agents: AgentEntry[];
  /** Optional contact for policy questions. */
  contact?: string;
}

/** The aggregate value held by `XFilesManager`. */
export interface XFilesModel {
  robots?: RobotsModel;
  securityTxt?: SecurityTxtModel;
  llmsTxt?: LlmsTxtModel;
  humansTxt?: HumansTxtModel;
  sitemap?: SitemapModel;
  agents?: AgentsModel;
}

/** Map a file kind to its model type. */
export interface XFileModelMap {
  robots: RobotsModel;
  securityTxt: SecurityTxtModel;
  llmsTxt: LlmsTxtModel;
  humansTxt: HumansTxtModel;
  sitemap: SitemapModel;
  agents: AgentsModel;
}

/** Empty-but-valid starting models, handy for "add this file" affordances. */
export const emptyRobots = (): RobotsModel => ({
  groups: [{ userAgents: ["*"], allow: [], disallow: [] }],
  sitemaps: [],
  protectedPaths: [],
});

export const emptySecurityTxt = (): SecurityTxtModel => ({
  contact: [],
  expires: "",
});

export const emptyLlmsTxt = (): LlmsTxtModel => ({
  title: "",
  sections: [],
});

export const emptyHumansTxt = (): HumansTxtModel => ({ team: [] });

export const emptySitemap = (): SitemapModel => ({ urls: [] });

export const emptyAgents = (): AgentsModel => ({ agents: [] });

/** Human-readable label + on-disk filename for each kind. */
export const X_FILE_META: Record<
  XFileKind,
  { label: string; filename: string }
> = {
  robots: { label: "robots.txt", filename: "robots.txt" },
  securityTxt: { label: "security.txt", filename: ".well-known/security.txt" },
  llmsTxt: { label: "llms.txt", filename: "llms.txt" },
  humansTxt: { label: "humans.txt", filename: "humans.txt" },
  sitemap: { label: "sitemap.xml", filename: "sitemap.xml" },
  agents: { label: "AGENTS", filename: ".well-known/agents.json" },
};

/**
 * Local render logic — produces the real text/XML each well-known file will
 * become on disk, mirroring the output format of the `fancy-x-files` PHP / JS
 * packages. Kept here (rather than imported) so the preview is real + the
 * package builds standalone.
 */
import type {
  AgentsModel,
  HumansTxtModel,
  LlmsTxtModel,
  RobotsModel,
  SecurityTxtModel,
  SitemapModel,
  XFileKind,
  XFilesModel,
} from "./model";

/** Render a robots.txt body. Protected paths are pinned Disallow everywhere. */
export function renderRobots(model: RobotsModel): string {
  const lines: string[] = [];
  const groups = model.groups.length
    ? model.groups
    : [{ userAgents: ["*"], allow: [], disallow: [] }];

  groups.forEach((group, i) => {
    if (i > 0) lines.push("");
    const agents = group.userAgents.length ? group.userAgents : ["*"];
    for (const ua of agents) lines.push(`User-agent: ${ua}`);

    // Protected paths are forced Disallow on every group and can never appear
    // in Allow (the editor guards that; we belt-and-braces it here too).
    const protectedSet = new Set(model.protectedPaths);
    for (const path of model.protectedPaths) lines.push(`Disallow: ${path}`);
    for (const path of group.disallow) {
      if (!protectedSet.has(path)) lines.push(`Disallow: ${path}`);
    }
    for (const path of group.allow) {
      if (!protectedSet.has(path)) lines.push(`Allow: ${path}`);
    }
    if (group.crawlDelay != null && group.crawlDelay > 0) {
      lines.push(`Crawl-delay: ${group.crawlDelay}`);
    }
  });

  if (model.host) {
    lines.push("");
    lines.push(`Host: ${model.host}`);
  }
  if (model.sitemaps.length) {
    lines.push("");
    for (const sm of model.sitemaps) lines.push(`Sitemap: ${sm}`);
  }
  return lines.join("\n") + "\n";
}

/** Render an RFC 9116 security.txt body. */
export function renderSecurityTxt(model: SecurityTxtModel): string {
  const lines: string[] = [];
  for (const c of model.contact) lines.push(`Contact: ${c}`);
  if (model.expires) lines.push(`Expires: ${model.expires}`);
  if (model.encryption) lines.push(`Encryption: ${model.encryption}`);
  if (model.acknowledgments)
    lines.push(`Acknowledgments: ${model.acknowledgments}`);
  if (model.preferredLanguages)
    lines.push(`Preferred-Languages: ${model.preferredLanguages}`);
  if (model.canonical) lines.push(`Canonical: ${model.canonical}`);
  if (model.policy) lines.push(`Policy: ${model.policy}`);
  if (model.hiring) lines.push(`Hiring: ${model.hiring}`);
  return lines.join("\n") + "\n";
}

/** Render an llms.txt Markdown document. */
export function renderLlmsTxt(model: LlmsTxtModel): string {
  const lines: string[] = [];
  lines.push(`# ${model.title || "Untitled"}`);
  if (model.summary) {
    lines.push("");
    lines.push(`> ${model.summary}`);
  }
  if (model.details) {
    lines.push("");
    lines.push(model.details);
  }
  for (const section of model.sections) {
    lines.push("");
    lines.push(`## ${section.name}`);
    lines.push("");
    for (const link of section.links) {
      const notes = link.notes ? `: ${link.notes}` : "";
      lines.push(`- [${link.title}](${link.url})${notes}`);
    }
  }
  return lines.join("\n") + "\n";
}

/** Render a humans.txt body. */
export function renderHumansTxt(model: HumansTxtModel): string {
  const lines: string[] = [];
  if (model.team.length) {
    lines.push("/* TEAM */");
    for (const m of model.team) {
      lines.push(`${m.role}: ${m.name}`);
      if (m.contact) lines.push(`Contact: ${m.contact}`);
    }
  }
  if (model.thanks && model.thanks.length) {
    if (lines.length) lines.push("");
    lines.push("/* THANKS */");
    for (const t of model.thanks) lines.push(t);
  }
  if (model.site) {
    if (lines.length) lines.push("");
    lines.push("/* SITE */");
    lines.push(model.site);
  }
  return lines.join("\n") + "\n";
}

const xmlEscape = (s: string): string =>
  s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

/** Render a sitemap.xml document. */
export function renderSitemap(model: SitemapModel): string {
  const lines: string[] = [];
  lines.push('<?xml version="1.0" encoding="UTF-8"?>');
  lines.push('<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">');
  for (const u of model.urls) {
    lines.push("  <url>");
    lines.push(`    <loc>${xmlEscape(u.loc)}</loc>`);
    if (u.lastmod) lines.push(`    <lastmod>${u.lastmod}</lastmod>`);
    if (u.changefreq) lines.push(`    <changefreq>${u.changefreq}</changefreq>`);
    if (u.priority != null)
      lines.push(`    <priority>${u.priority.toFixed(1)}</priority>`);
    lines.push("  </url>");
  }
  lines.push("</urlset>");
  return lines.join("\n") + "\n";
}

/** Render the /AGENTS register as JSON. */
export function renderAgents(model: AgentsModel): string {
  const doc: Record<string, unknown> = {
    agents: model.agents.map((a) => {
      const out: Record<string, unknown> = { id: a.id, policy: a.policy };
      if (a.name) out.name = a.name;
      if (a.url) out.url = a.url;
      if (a.scope) out.scope = a.scope;
      return out;
    }),
  };
  if (model.contact) doc.contact = model.contact;
  return JSON.stringify(doc, null, 2) + "\n";
}

/** Render any well-known file from its model. */
export function renderXFile(kind: XFileKind, model: unknown): string {
  switch (kind) {
    case "robots":
      return renderRobots(model as RobotsModel);
    case "securityTxt":
      return renderSecurityTxt(model as SecurityTxtModel);
    case "llmsTxt":
      return renderLlmsTxt(model as LlmsTxtModel);
    case "humansTxt":
      return renderHumansTxt(model as HumansTxtModel);
    case "sitemap":
      return renderSitemap(model as SitemapModel);
    case "agents":
      return renderAgents(model as AgentsModel);
  }
}

/** Pull a single model out of the aggregate by kind. */
export function pickModel(value: XFilesModel, kind: XFileKind): unknown {
  return value[kind];
}

import { useState } from "react";
import { Badge, Tabs } from "@particle-academy/react-fancy";
import {
  X_FILE_META,
  emptyAgents,
  emptyHumansTxt,
  emptyLlmsTxt,
  emptyRobots,
  emptySecurityTxt,
  emptySitemap,
  type XFileKind,
  type XFilesModel,
} from "../lib/model";
import { validateModel } from "../lib/validate";
import { AgentsEditor } from "./AgentsEditor";
import { HumansTxtEditor } from "./HumansTxtEditor";
import { LlmsTxtEditor } from "./LlmsTxtEditor";
import { RobotsEditor } from "./RobotsEditor";
import { SecurityTxtEditor } from "./SecurityTxtEditor";
import { SitemapEditor } from "./SitemapEditor";
import { XFilePreview } from "./XFilePreview";

export interface XFilesManagerProps {
  /** The aggregate model — each key optional; absent keys offer an "Add" CTA. */
  value: XFilesModel;
  /** Fires with the next aggregate model on every edit. */
  onChange: (next: XFilesModel) => void;
  /** Restrict + order the tabs. Default: all six kinds. */
  kinds?: XFileKind[];
  /** Controlled active tab (a file kind). */
  activeKind?: XFileKind;
  /** Default active tab when uncontrolled. */
  defaultKind?: XFileKind;
  onActiveKindChange?: (kind: XFileKind) => void;
  className?: string;
}

const ALL_KINDS: XFileKind[] = [
  "robots",
  "securityTxt",
  "llmsTxt",
  "sitemap",
  "humansTxt",
  "agents",
];

const EMPTY: Record<XFileKind, () => XFilesModel[XFileKind]> = {
  robots: emptyRobots,
  securityTxt: emptySecurityTxt,
  llmsTxt: emptyLlmsTxt,
  humansTxt: emptyHumansTxt,
  sitemap: emptySitemap,
  agents: emptyAgents,
};

/**
 * The headline compound component. Tabs (one per file kind) hold the aggregate
 * `value` + `onChange`, wiring each editor next to its live preview. Fully
 * controlled and JSON-friendly so an embedded agent can read the whole set of
 * well-known files and propose edits through the same channel (Human+ UX).
 */
export function XFilesManager({
  value,
  onChange,
  kinds = ALL_KINDS,
  activeKind,
  defaultKind,
  onActiveKindChange,
  className,
}: XFilesManagerProps) {
  const [internalActive, setInternalActive] = useState<XFileKind>(
    defaultKind ?? kinds[0],
  );
  const active = activeKind ?? internalActive;

  const setActive = (kind: string) => {
    const k = kind as XFileKind;
    if (activeKind == null) setInternalActive(k);
    onActiveKindChange?.(k);
  };

  const patch = (kind: XFileKind, model: XFilesModel[XFileKind]) =>
    onChange({ ...value, [kind]: model });

  const ensure = (kind: XFileKind) => {
    if (value[kind] == null) patch(kind, EMPTY[kind]());
  };

  const issueCount = (kind: XFileKind): number =>
    value[kind] != null ? validateModel(kind, value[kind]).length : 0;

  const renderEditor = (kind: XFileKind) => {
    const model = value[kind];
    if (model == null) {
      return (
        <div
          data-x-empty={kind}
          style={{
            padding: "1.5rem",
            textAlign: "center",
            display: "flex",
            flexDirection: "column",
            gap: "0.6rem",
            alignItems: "center",
          }}
        >
          <p style={{ margin: 0, opacity: 0.7 }}>
            No {X_FILE_META[kind].label} yet.
          </p>
          <button
            type="button"
            onClick={() => ensure(kind)}
            data-x-create={kind}
            style={{
              padding: "0.4rem 0.8rem",
              borderRadius: "0.4rem",
              border: "1px solid var(--rf-border, #e5e7eb)",
              cursor: "pointer",
              background: "transparent",
            }}
          >
            Add {X_FILE_META[kind].label}
          </button>
        </div>
      );
    }

    switch (kind) {
      case "robots":
        return (
          <RobotsEditor
            value={model as never}
            onChange={(m) => patch("robots", m)}
          />
        );
      case "securityTxt":
        return (
          <SecurityTxtEditor
            value={model as never}
            onChange={(m) => patch("securityTxt", m)}
          />
        );
      case "llmsTxt":
        return (
          <LlmsTxtEditor
            value={model as never}
            onChange={(m) => patch("llmsTxt", m)}
          />
        );
      case "sitemap":
        return (
          <SitemapEditor
            value={model as never}
            onChange={(m) => patch("sitemap", m)}
          />
        );
      case "humansTxt":
        return (
          <HumansTxtEditor
            value={model as never}
            onChange={(m) => patch("humansTxt", m)}
          />
        );
      case "agents":
        return (
          <AgentsEditor
            value={model as never}
            onChange={(m) => patch("agents", m)}
          />
        );
    }
  };

  return (
    <div className={className} data-x-manager>
      <Tabs activeTab={active} onTabChange={setActive}>
        <Tabs.List>
          {kinds.map((kind) => {
            const count = issueCount(kind);
            return (
              <Tabs.Tab key={kind} value={kind} data-x-tab={kind}>
                {X_FILE_META[kind].label}
                {count > 0 ? (
                  <Badge
                    color="amber"
                    variant="soft"
                    size="sm"
                    style={{ marginLeft: "0.4rem" }}
                  >
                    {count}
                  </Badge>
                ) : null}
              </Tabs.Tab>
            );
          })}
        </Tabs.List>
        <Tabs.Panels>
          {kinds.map((kind) => (
            <Tabs.Panel key={kind} value={kind}>
              <div
                data-x-pane={kind}
                style={{
                  display: "grid",
                  gridTemplateColumns: "minmax(0, 1fr) minmax(0, 1fr)",
                  gap: "1rem",
                  alignItems: "start",
                }}
              >
                <div>{renderEditor(kind)}</div>
                <div style={{ position: "sticky", top: "1rem" }}>
                  <XFilePreview kind={kind} model={value[kind]} />
                </div>
              </div>
            </Tabs.Panel>
          ))}
        </Tabs.Panels>
      </Tabs>
    </div>
  );
}

import { Button, Input, Select } from "@particle-academy/react-fancy";
import type { AgentEntry, AgentsModel } from "../lib/model";
import { validateAgents } from "../lib/validate";
import { IssueList, Section } from "./internal";

export interface AgentsEditorProps {
  value: AgentsModel;
  onChange: (next: AgentsModel) => void;
  hideIssues?: boolean;
  className?: string;
}

/** Controlled /AGENTS register editor: per-agent allow/deny policy. */
export function AgentsEditor({
  value,
  onChange,
  hideIssues,
  className,
}: AgentsEditorProps) {
  const issues = validateAgents(value);
  const patch = (next: Partial<AgentsModel>) => onChange({ ...value, ...next });

  const updateAgent = (index: number, next: Partial<AgentEntry>) =>
    patch({
      agents: value.agents.map((a, i) =>
        i === index ? { ...a, ...next } : a,
      ),
